    private static function get_cv_match_job_posts_item_cache_key($jobs_post_id)
    {
        return 'sffc_cv_match_job_posts_item_' . (int) $jobs_post_id;
    }

    public static function invalidate_cv_match_job_posts_cache($jobs_post_id)
    {
        $jobs_post_id = (int) $jobs_post_id;
        if ($jobs_post_id <= 0) {
            return;
        }

        delete_transient(self::get_cv_match_job_posts_item_cache_key($jobs_post_id));
    }

    private function get_cached_cv_match_job_posts_item($jobs_post_id)
    {
        $jobs_post_id = (int) $jobs_post_id;
        if ($jobs_post_id <= 0) {
            return null;
        }

        $cache_key = self::get_cv_match_job_posts_item_cache_key($jobs_post_id);
        $cached = get_transient($cache_key);
        if (is_array($cached) && !empty($cached['post_id'])) {
            return $cached;
        }

        $item = $this->get_crm_reddit_jobs_item($jobs_post_id);
        if (!empty($item) && is_array($item)) {
            set_transient($cache_key, $item, 12 * HOUR_IN_SECONDS);
        }

        return $item;
    }

    private function mask_recruiter_email_for_display($email)
    {
        $email = sanitize_email((string) $email);
        if ($email === '' || strpos($email, '@') === false) {
            return __('Send Intro', 'senna-finance');
        }

        $parts = explode('@', $email, 2);
        $local = (string) ($parts[0] ?? '');
        $domain = (string) ($parts[1] ?? '');

        if ($local === '' || $domain === '') {
            return __('Send Intro', 'senna-finance');
        }

        $local_length = function_exists('mb_strlen') ? mb_strlen($local) : strlen($local);
        $first_local = function_exists('mb_substr') ? mb_substr($local, 0, 1) : substr($local, 0, 1);
        $last_local = $local_length > 1
            ? (function_exists('mb_substr') ? mb_substr($local, -1, 1) : substr($local, -1))
            : '';
        $masked_local = $first_local . '****' . $last_local;

        return $masked_local . '@' . $domain;
    }

    private function mask_recruiter_phone_for_display($phone)
    {
        $raw_phone = trim((string) $phone);
        $digits = preg_replace('/\D+/', '', $raw_phone);

        if ($digits === '') {
            return __('Call', 'senna-finance');
        }

        $length = strlen($digits);
        if ($length <= 3) {
            return substr($digits, 0, 1) . '****';
        }

        return substr($digits, 0, 2) . '*******' . substr($digits, -1);
    }

    private function get_recruiter_first_name_for_display($name)
    {
        $name = trim((string) $name);
        if ($name === '') {
            return __('Recruiter', 'senna-finance');
        }

        $parts = preg_split('/\s+/', $name);
        $first = trim((string) ($parts[0] ?? ''));

        return $first !== '' ? $first : __('Recruiter', 'senna-finance');
    }

    private function get_recruiter_short_name_for_display($name)
    {
        $name = trim((string) $name);
        if ($name === '') {
            return __('Recruiter', 'senna-finance');
        }

        $parts = preg_split('/\s+/', $name);
        $first = trim((string) ($parts[0] ?? ''));
        if ($first === '') {
            return __('Recruiter', 'senna-finance');
        }

        if (count((array) $parts) < 2) {
            return $first;
        }

        $last = trim((string) end($parts));
        $last_initial = $last !== ''
            ? (function_exists('mb_strtoupper') && function_exists('mb_substr')
                ? mb_strtoupper(mb_substr($last, 0, 1))
                : strtoupper(substr($last, 0, 1)))
            : '';

        return $last_initial !== '' ? $first . ' ' . $last_initial . '.' : $first;
    }

    private function get_crm_reddit_current_user_first_name($user_id = 0)
    {
        $user_id = $user_id > 0 ? (int) $user_id : get_current_user_id();
        if ($user_id <= 0) {
            return '';
        }

        $first_name = trim((string) get_user_meta($user_id, 'first_name', true));
        if ($first_name !== '') {
            return $first_name;
        }

        $user = get_user_by('id', $user_id);
        if (!$user instanceof WP_User) {
            return '';
        }

        $display_name = trim((string) $user->display_name);
        if ($display_name === '') {
            return '';
        }

        $parts = preg_split('/\s+/', $display_name);
        return trim((string) ($parts[0] ?? ''));
    }

    private function get_crm_reddit_current_user_full_name($user_id = 0)
    {
        $user_id = $user_id > 0 ? (int) $user_id : get_current_user_id();
        if ($user_id <= 0) {
            return '';
        }

        $user = get_user_by('id', $user_id);
        if (!$user instanceof WP_User) {
            return '';
        }

        $first_name = trim((string) get_user_meta($user_id, 'first_name', true));
        $last_name = trim((string) get_user_meta($user_id, 'last_name', true));
        $full_name = trim($first_name . ' ' . $last_name);

        if ($full_name !== '') {
            return $full_name;
        }

        return trim((string) $user->display_name);
    }

    private function is_arabic_locale($locale = '')
    {
        $locale = $locale !== '' ? (string) $locale : (string) get_locale();
        $locale = strtolower(str_replace('-', '_', $locale));

        return strpos($locale, 'ar') === 0;
    }

    private function localize_interface_copy($english, $arabic, $locale = '')
    {
        return $this->is_arabic_locale($locale) ? $arabic : $english;
    }

    private function get_email_recipient_locale($recipient = null)
    {
        if ($recipient instanceof WP_User) {
            return function_exists('get_user_locale') ? (string) get_user_locale($recipient) : (string) get_locale();
        }

        if (is_numeric($recipient) && (int) $recipient > 0) {
            return function_exists('get_user_locale') ? (string) get_user_locale((int) $recipient) : (string) get_locale();
        }

        $email = sanitize_email((string) $recipient);
        if ($email !== '') {
            $user = get_user_by('email', $email);
            if ($user instanceof WP_User) {
                return function_exists('get_user_locale') ? (string) get_user_locale($user) : (string) get_locale();
            }
        }

        return (string) get_locale();
    }

    private function should_show_cv_match_studio_welcome_modal($user_id)
    {
        $user_id = (int) $user_id;
        if ($user_id <= 0) {
            return false;
        }

        return get_user_meta($user_id, 'sffc_cv_match_studio_welcome_seen', true) !== '1';
    }

    private function parse_cv_match_context_job_id($raw_value)
    {
        if (is_numeric($raw_value)) {
            return absint($raw_value);
        }

        $raw_value = trim((string) $raw_value);
        if ($raw_value === '') {
            return 0;
        }

        if (preg_match('/(?:^|[?&])sffc_recruiter_contact_job_id=(\d+)/', $raw_value, $matches)) {
            return absint($matches[1]);
        }

        if (preg_match('/\b(\d+)\b/', $raw_value, $matches)) {
            return absint($matches[1]);
        }

        return 0;
    }

    private function get_cv_match_welcome_context_job_id($user_id = 0)
    {
        $user_id = (int) $user_id;
        $candidate_ids = [];

        if ($user_id > 0) {
            $candidate_ids[] = $this->parse_cv_match_context_job_id(get_user_meta($user_id, 'mepr_job_id', true));
            $candidate_ids[] = $this->parse_cv_match_context_job_id(get_user_meta($user_id, 'sffc_signup_source_job_id', true));
        }

        $candidate_ids[] = $this->parse_cv_match_context_job_id($this->get_valid_signup_cookie_value('sffc_signup_mepr_job_id'));
        $candidate_ids[] = $this->parse_cv_match_context_job_id($_GET['sffc_recruiter_contact_job_id'] ?? 0);

        foreach ($candidate_ids as $candidate_id) {
            $resolved_id = $this->resolve_crm_reddit_jobs_post_id($candidate_id);
            if ($resolved_id > 0) {
                return $resolved_id;
            }
        }

        return 0;
    }

    private function get_cv_match_studio_landing_preview_data()
    {
        $roles = [];
        $recruiters = [];

        if (!class_exists('SFFC_CRM_Post')) {
            return [
                'roles' => $roles,
                'recruiters' => $recruiters,
            ];
        }

        $post_model = new SFFC_CRM_Post();
        $feed_items = $post_model->get_feed([
            'per_page' => 6,
            'page' => 1,
            'approved_only' => true,
            'orderby' => 'posted_at',
            'order' => 'DESC',
        ]);

        if (empty($feed_items) || !is_array($feed_items)) {
            return [
                'roles' => $roles,
                'recruiters' => $recruiters,
            ];
        }

        $match_scores = [84, 81, 77, 75, 73, 70];
        $used_recruiters = [];

        foreach ($feed_items as $index => $item) {
            if (!is_array($item)) {
                continue;
            }

            $role_title = trim((string) ($item['role_title'] ?? ''));
            if ($role_title === '') {
                continue;
            }

            $location_bits = array_filter([
                trim((string) ($item['location'] ?? '')),
                trim((string) ($item['location_country'] ?? '')),
            ]);
            $location_label = implode(', ', array_slice(array_unique($location_bits), 0, 2));

            $roles[] = [
                'title' => $role_title,
                'company' => trim((string) ($item['company'] ?? '')),
                'logo' => trim((string) ($item['company_logo'] ?? '')),
                'location' => $location_label,
                'score' => (int) ($match_scores[$index] ?? max(68, 82 - ($index * 3))),
                'relative_time' => $this->get_cv_match_relative_time_label($item['posted_at'] ?? ''),
                'url' => $this->build_cv_match_recruiter_role_permalink($item),
            ];

            $recruiter_id = (int) ($item['recruiter_id'] ?? 0);
            if ($recruiter_id <= 0 || isset($used_recruiters[$recruiter_id])) {
                continue;
            }

            $used_recruiters[$recruiter_id] = true;

            $recruiters[] = [
                'id' => $recruiter_id,
                'name' => trim((string) ($item['recruiter_name'] ?? '')),
                'title' => trim((string) ($item['recruiter_title'] ?? 'Recruiter')),
                'firm' => trim((string) ($item['recruiter_firm'] ?? ($item['company'] ?? ''))),
                'photo' => trim((string) ($item['recruiter_photo'] ?? '')),
                'open_roles' => max(1, (int) ($item['recruiter_open_roles_count'] ?? 1)),
                'location' => $location_label,
            ];

            if (count($roles) >= 3 && count($recruiters) >= 3) {
                break;
            }
        }

        return [
            'roles' => array_slice($roles, 0, 3),
            'recruiters' => array_slice($recruiters, 0, 3),
        ];
    }

    private function get_signup_cookie_scope_value()
    {
        if ($this->signup_cookie_scope !== null) {
            return $this->signup_cookie_scope;
        }

        if (is_user_logged_in()) {
            $user_id = (int) get_current_user_id();
            $this->signup_cookie_scope = 'user:' . $user_id . ':' . substr(wp_hash((string) $user_id, 'logged_in'), 0, 16);
            return $this->signup_cookie_scope;
        }

        $cookie_scope = isset($_COOKIE['sffc_signup_scope'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['sffc_signup_scope']))
            : '';

        if ($cookie_scope !== '' && strpos($cookie_scope, 'anon:') === 0) {
            $this->signup_cookie_scope = $cookie_scope;
            return $this->signup_cookie_scope;
        }

        $this->signup_cookie_scope = 'anon:' . wp_generate_uuid4();
        return $this->signup_cookie_scope;
    }

    public function ensure_signup_cookie_scope()
    {
        $scope = $this->get_signup_cookie_scope_value();
        $current_scope = isset($_COOKIE['sffc_signup_scope'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['sffc_signup_scope']))
            : '';

        if ($current_scope === $scope || headers_sent()) {
            $_COOKIE['sffc_signup_scope'] = $scope;
            return;
        }

        setcookie('sffc_signup_scope', $scope, 0, '/', COOKIE_DOMAIN, is_ssl(), false);
        $_COOKIE['sffc_signup_scope'] = $scope;
    }

    public function ensure_signup_prefill_token()
    {
        $token = $this->get_signup_prefill_token_value();
        $current_token = isset($_COOKIE['sffc_signup_prefill_token'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['sffc_signup_prefill_token']))
            : '';

        if ($current_token === $token || headers_sent()) {
            $_COOKIE['sffc_signup_prefill_token'] = $token;
            return;
        }

        setcookie('sffc_signup_prefill_token', $token, time() + (30 * DAY_IN_SECONDS), '/', COOKIE_DOMAIN, is_ssl(), true);
        $_COOKIE['sffc_signup_prefill_token'] = $token;
    }

    private function get_signup_prefill_token_value()
    {
        $token = isset($_COOKIE['sffc_signup_prefill_token'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['sffc_signup_prefill_token']))
            : '';

        if ($token !== '' && preg_match('/^[A-Za-z0-9]{20,}$/', $token)) {
            return $token;
        }

        $token = wp_generate_password(40, false, false);
        $_COOKIE['sffc_signup_prefill_token'] = $token;

        return $token;
    }

    private function get_signup_prefill_transient_key()
    {
        return 'sffc_signup_prefill_' . md5($this->get_signup_cookie_scope_value() . '|' . $this->get_signup_prefill_token_value());
    }

    private function get_signup_prefill_state()
    {
        $state = get_transient($this->get_signup_prefill_transient_key());
        return is_array($state) ? $state : [];
    }

    private function persist_signup_prefill_state(array $data, $expiration = null)
    {
        $expiration = is_int($expiration) && $expiration > 0 ? $expiration : (30 * DAY_IN_SECONDS);
        $state = $this->get_signup_prefill_state();

        foreach (['email', 'first_name', 'last_name', 'study_level', 'account_type', 'mepr_job_id'] as $key) {
            if (!array_key_exists($key, $data)) {
                continue;
            }

            if ($key === 'email') {
                $state[$key] = sanitize_email((string) $data[$key]);
            } elseif ($key === 'mepr_job_id') {
                $state[$key] = absint($this->parse_cv_match_context_job_id($data[$key]));
            } elseif (in_array($key, ['study_level', 'account_type'], true)) {
                $state[$key] = sanitize_key((string) $data[$key]);
            } else {
                $state[$key] = sanitize_text_field((string) $data[$key]);
            }
        }

        foreach (['finance_interest', 'seniority_level', 'support_need'] as $key) {
            if (!array_key_exists($key, $data)) {
                continue;
            }

            $state[$key] = array_values(array_filter(array_map('sanitize_text_field', (array) $data[$key])));
        }

        set_transient($this->get_signup_prefill_transient_key(), $state, $expiration);
    }

    private function get_signup_prefill_state_value($key)
    {
        $state = $this->get_signup_prefill_state();
        return $state[$key] ?? '';
    }

    private function set_signup_scoped_cookie($name, $value, $expires = 0)
    {
        $scope = $this->get_signup_cookie_scope_value();
        if (!headers_sent()) {
            setcookie($name, (string) $value, $expires, '/', COOKIE_DOMAIN, is_ssl(), false);
            setcookie('sffc_signup_owner', $scope, $expires, '/', COOKIE_DOMAIN, is_ssl(), false);
            setcookie('sffc_signup_scope', $scope, 0, '/', COOKIE_DOMAIN, is_ssl(), false);
        }

        $_COOKIE[$name] = (string) $value;
        $_COOKIE['sffc_signup_owner'] = $scope;
        $_COOKIE['sffc_signup_scope'] = $scope;

        $ttl = $expires > 0 ? max(1, $expires - time()) : null;

        if ($name === 'sffc_signup_email') {
            $this->persist_signup_prefill_state(['email' => $value], $ttl);
        } elseif ($name === 'sffc_signup_first_name') {
            $this->persist_signup_prefill_state(['first_name' => $value], $ttl);
        } elseif ($name === 'sffc_signup_last_name') {
            $this->persist_signup_prefill_state(['last_name' => $value], $ttl);
        } elseif ($name === 'sffc_signup_study_level') {
            $this->persist_signup_prefill_state(['study_level' => $value], $ttl);
        } elseif ($name === 'sffc_signup_account_type') {
            $this->persist_signup_prefill_state(['account_type' => $value], $ttl);
        } elseif ($name === 'sffc_signup_mepr_job_id') {
            $this->persist_signup_prefill_state(['mepr_job_id' => $value], $ttl);
        } elseif (in_array($name, ['sffc_contact_data', 'sffc_recruiter_intro_onboarding', 'sffc_dubai_career_flow'], true)) {
            $decoded = json_decode((string) $value, true);
            if (is_array($decoded)) {
                $this->persist_signup_prefill_state([
                    'email' => $decoded['email'] ?? '',
                    'first_name' => $decoded['first_name'] ?? '',
                    'last_name' => $decoded['last_name'] ?? '',
                ], $ttl);
            }
        }
    }

    private function get_valid_signup_cookie_value($name)
    {
        $state_key_map = [
            'sffc_signup_email' => 'email',
            'sffc_signup_first_name' => 'first_name',
            'sffc_signup_last_name' => 'last_name',
            'sffc_signup_study_level' => 'study_level',
            'sffc_signup_account_type' => 'account_type',
            'sffc_signup_mepr_job_id' => 'mepr_job_id',
        ];

        if (isset($state_key_map[$name])) {
            $state_value = $this->get_signup_prefill_state_value($state_key_map[$name]);
            if ($state_value !== '' && $state_value !== []) {
                return is_array($state_value) ? wp_json_encode($state_value) : (string) $state_value;
            }
        }

        $scope = $this->get_signup_cookie_scope_value();
        $owner = isset($_COOKIE['sffc_signup_owner'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['sffc_signup_owner']))
            : '';

        if ($owner === '' || !hash_equals($scope, $owner)) {
            return '';
        }

        return isset($_COOKIE[$name]) ? wp_unslash((string) $_COOKIE[$name]) : '';
    }

    private function get_valid_signup_json_cookie($name)
    {
        $raw = $this->get_valid_signup_cookie_value($name);
        if ($raw === '') {
            return [];
        }

        $data = json_decode(stripslashes($raw), true);
        return is_array($data) ? $data : [];
    }

    public static function get_instance()
    {
        if (null === self::$instance) {
            self::$instance = new self();
        }
        return self::$instance;
    }

