    public function ajax_load_cv_match_job_view()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
        $wp_post_id = isset($_POST['wp_post_id']) ? absint($_POST['wp_post_id']) : 0;
        $crm_post_id = isset($_POST['crm_post_id']) ? absint($_POST['crm_post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $role_title = sanitize_text_field((string) ($_POST['role_title'] ?? ''));
        $match_score = isset($_POST['match_score']) ? max(0, min(100, (int) $_POST['match_score'])) : 0;
        $match_reasons = $this->parse_cv_match_job_context_list($_POST['match_reasons'] ?? [], 4);
        $match_warnings = $this->parse_cv_match_job_context_list($_POST['match_warnings'] ?? [], 4);
        $match_gaps = $this->parse_cv_match_job_context_list($_POST['match_gaps'] ?? [], 4);
        $match_skills = $this->parse_cv_match_job_context_list($_POST['match_skills'] ?? [], 6);
        $recruiter_open_roles_count = isset($_POST['recruiter_open_roles_count']) ? max(0, (int) $_POST['recruiter_open_roles_count']) : 0;
        $cv_text = isset($_POST['cv_text']) ? trim(wp_unslash((string) $_POST['cv_text'])) : '';

        $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id($jobs_post_id, $wp_post_id, $crm_post_id);
        if (!$jobs_post_id && !$wp_post_id && !$crm_post_id) {
            wp_send_json_error([
                'message' => __('Missing role identifiers.', 'senna-finance'),
            ], 400);
        }

        $item = $jobs_post_id > 0 ? $this->get_crm_reddit_jobs_item($jobs_post_id) : null;
        $resolved_title = '';
        if (!empty($item)) {
            $resolved_title = sanitize_text_field((string) ($item['role_title'] ?? ''));
        }
        if ($resolved_title === '' && $role_title !== '') {
            $resolved_title = $role_title;
        }
        if ($resolved_title === '' && $wp_post_id > 0) {
            $resolved_title = sanitize_text_field((string) get_the_title($wp_post_id));
        }
        if ($resolved_title === '') {
            $resolved_title = __('Role workspace', 'senna-finance');
        }

        if (empty($item)) {
            wp_send_json_error([
                'message' => __('We could not load this role workspace yet.', 'senna-finance'),
            ], 404);
        }

        $analysis = $this->build_crm_reddit_single_job_analysis_data($item);
        $html = $this->render_cv_match_job_dashboard($item, $analysis, [
            'match_score' => $match_score,
            'reasons' => $match_reasons,
            'warnings' => $match_warnings,
            'gaps' => $match_gaps,
            'skills' => $match_skills,
            'recruiter_id' => $recruiter_id,
            'recruiter_open_roles_count' => $recruiter_open_roles_count,
            'cv_text' => $cv_text,
            'fast_intel' => true,
        ]);

        wp_send_json_success([
            'html' => $html,
            'jobs_post_id' => $jobs_post_id,
            'role_title' => $resolved_title,
        ]);
    }

    public function ajax_cv_match_dismiss_recruiter_discovery()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please sign in to save dismissed recruiters.', 'senna-finance'),
            ], 401);
        }

        $user_id = get_current_user_id();
        $dismiss_key = sanitize_text_field((string) wp_unslash($_POST['dismiss_key'] ?? ''));
        $dismiss_key = preg_replace('/[^a-zA-Z0-9:_-]/', '', $dismiss_key);

        if ($dismiss_key === '') {
            wp_send_json_error([
                'message' => __('Missing recruiter reference.', 'senna-finance'),
            ], 400);
        }

        $dismissed = $this->get_cv_match_dismissed_recruiter_discovery_keys($user_id);
        if (!in_array($dismiss_key, $dismissed, true)) {
            $dismissed[] = $dismiss_key;
            $dismissed = array_values(array_slice(array_unique($dismissed), -250));
            update_user_meta($user_id, 'sffc_cv_match_dismissed_recruiters', $dismissed);
        }

        wp_send_json_success([
            'dismiss_key' => $dismiss_key,
        ]);
    }

    private function get_cv_match_dismissed_recruiter_discovery_keys($user_id)
    {
        $dismissed = get_user_meta((int) $user_id, 'sffc_cv_match_dismissed_recruiters', true);
        if (!is_array($dismissed)) {
            return [];
        }

        return array_values(array_filter(array_map(static function ($key) {
            $key = sanitize_text_field((string) $key);
            return preg_replace('/[^a-zA-Z0-9:_-]/', '', $key);
        }, $dismissed)));
    }

    private function get_cv_match_recruiter_discovery_dismiss_key(array $row)
    {
        $primary = sanitize_email((string) ($row['contact_email'] ?? ''));
        if ($primary === '') {
            $primary = esc_url_raw((string) ($row['contact_linkedin'] ?? ''));
        }
        if ($primary === '') {
            $primary = implode('|', array_filter([
                (string) ($row['recruiter_name'] ?? ''),
                (string) ($row['recruiter_title'] ?? ''),
                (string) ($row['company_name'] ?? ''),
                (string) ($row['company_url'] ?? ''),
            ]));
        }

        return 'recruiter:' . md5($primary);
    }

    public function ajax_load_cv_match_discovery_view()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        $current_url = isset($_POST['current_url']) ? esc_url_raw((string) wp_unslash($_POST['current_url'])) : '';
        $search_term = isset($_POST['search_term']) ? sanitize_text_field((string) wp_unslash($_POST['search_term'])) : '';
