            'discovery_filter' => isset($_POST['discovery_filter']) ? sanitize_key((string) wp_unslash($_POST['discovery_filter'])) : '',
            'recruiter_region' => isset($_POST['recruiter_region']) ? sanitize_text_field((string) wp_unslash($_POST['recruiter_region'])) : '',
            'recruiter_industry' => isset($_POST['recruiter_industry']) ? sanitize_text_field((string) wp_unslash($_POST['recruiter_industry'])) : '',
            'recruiter_skill' => isset($_POST['recruiter_skill']) ? sanitize_text_field((string) wp_unslash($_POST['recruiter_skill'])) : '',
