        ]);
    }

    public function ajax_cv_match_support_message()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        $subject = sanitize_text_field((string) wp_unslash($_POST['subject'] ?? ''));
        $message = sanitize_textarea_field((string) wp_unslash($_POST['message'] ?? ''));

        if ($subject === '') {
            wp_send_json_error([
                'message' => __('Please add a subject.', 'senna-finance'),
            ], 422);
        }

        if (trim($message) === '') {
            wp_send_json_error([
                'message' => __('Please tell us how we can help.', 'senna-finance'),
            ], 422);
        }

        $admin_email = sanitize_email((string) get_option('admin_email'));
        if ($admin_email === '') {
            wp_send_json_error([
                'message' => __('Support email is not configured yet.', 'senna-finance'),
            ], 500);
        }

        $current_user = wp_get_current_user();
        $user_name = ($current_user instanceof WP_User && $current_user->exists())
            ? trim((string) $current_user->display_name)
            : __('Guest user', 'senna-finance');
        $user_email = ($current_user instanceof WP_User && $current_user->exists())
            ? sanitize_email((string) $current_user->user_email)
            : '';

        $headers = ['Content-Type: text/plain; charset=UTF-8'];
        if ($user_email !== '') {
            $headers[] = 'Reply-To: ' . $user_name . ' <' . $user_email . '>';
        }

        $body_lines = [
            'CV Match Studio support request',
            '',
            'Name: ' . ($user_name !== '' ? $user_name : __('Unknown user', 'senna-finance')),
            'Email: ' . ($user_email !== '' ? $user_email : __('Not available', 'senna-finance')),
            'Sent from: ' . home_url('/'),
            '',
            'Message:',
            $message,
        ];

        $sent = wp_mail(
            $admin_email,
            '[CV Match Studio] ' . $subject,
            implode("\n", $body_lines),
            $headers
        );

        if (!$sent) {
            wp_send_json_error([
                'message' => __('We could not send your message right now. Please try again.', 'senna-finance'),
            ], 500);
        }

        wp_send_json_success([
            'message' => __('Your message has been sent to support.', 'senna-finance'),
        ]);
    }

    public function ajax_cv_match_mark_welcome_seen()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('You must be logged in to save onboarding progress.', 'senna-finance'),
            ], 403);
        }

        $user_id = get_current_user_id();
        if ($user_id <= 0) {
            wp_send_json_error([
                'message' => __('Unable to identify your account right now.', 'senna-finance'),
            ], 500);
        }

        update_user_meta($user_id, 'sffc_cv_match_studio_welcome_seen', '1');

        $preferred_industry = $this->normalize_cv_match_studio_preferred_industry((string) wp_unslash($_POST['preferred_industry'] ?? ''));
        if ($preferred_industry !== '') {
            update_user_meta($user_id, $this->get_cv_match_studio_preferred_industry_meta_key(), $preferred_industry);
        }

        $preferred_location = $this->normalize_cv_match_studio_preferred_location((string) wp_unslash($_POST['preferred_location'] ?? ''));
        if ($preferred_location !== '') {
            update_user_meta($user_id, $this->get_cv_match_studio_preferred_location_meta_key(), $preferred_location);
        }

        $newsletter_ids = isset($_POST['newsletter_ids']) ? (array) wp_unslash($_POST['newsletter_ids']) : [];
        $newsletter_ids = array_values(array_unique(array_filter(array_map('absint', $newsletter_ids))));
        $subscribed_newsletter_ids = [];
        foreach ($newsletter_ids as $newsletter_id) {
            if ($this->subscribe_cv_match_user_to_newsletter($user_id, $newsletter_id)) {
                $subscribed_newsletter_ids[] = $newsletter_id;
            }
        }

        wp_send_json_success([
            'message' => __('Welcome tour preference saved.', 'senna-finance'),
            'preferred_industry' => $preferred_industry,
            'preferred_location' => $preferred_location,
            'subscribed_newsletters' => $subscribed_newsletter_ids,
        ]);
    }

