    private function map_cv_match_studio_preferred_location_to_salary_market($preferred_location)
    {
            $preferred_location = $this->normalize_cv_match_studio_preferred_location((string) $preferred_location);
            $map = [
                'dubai' => 'Dubai, United Arab Emirates',
                'abu_dhabi' => 'Abu Dhabi, United Arab Emirates',
                'riyadh' => 'Riyadh, Saudi Arabia',
                'doha' => 'Doha, Qatar',
                'other' => 'Dubai, United Arab Emirates',
            ];

            return (string) ($map[$preferred_location] ?? 'Dubai, United Arab Emirates');
        }

    private function infer_cv_match_studio_salary_checker_role(array $resume_payload = [])
    {
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            if ($cv_text === '') {
                return __('Investment Associate', 'senna-finance');
            }

        if (!class_exists('SFFC_Planner_CV_Parser')) {
            $parser_file = SFFC_PLUGIN_DIR . 'includes/application-planner/class-cv-parser.php';
            if (file_exists($parser_file)) {
                require_once $parser_file;
            }
        }

        if (class_exists('SFFC_Planner_CV_Parser')) {
            $parser = new SFFC_Planner_CV_Parser();
            $parsed = (array) $parser->parse($cv_text);
            $current_role = $parsed['current_role'] ?? '';
            if (is_array($current_role)) {
                $current_role = (string) ($current_role['role'] ?? $current_role['label'] ?? '');
            }
            $current_role = sanitize_text_field((string) $current_role);
            if ($current_role !== '' && strtolower($current_role) !== 'array') {
                return $current_role;
            }
        }

        $role_patterns = [
            'Chief Financial Officer' => '/\b(chief financial officer|cfo)\b/i',
            'Finance Director' => '/\bfinance director\b/i',
            'Head of Finance' => '/\bhead of finance\b/i',
            'Financial Controller' => '/\bfinancial controller\b/i',
            'FP&A Director' => '/\b(fp&a director|financial planning)\b/i',
            'Treasury Director' => '/\btreasury director|head of treasury\b/i',
            'Investment Director' => '/\binvestment director\b/i',
            'Finance Manager' => '/\bfinance manager\b/i',
        ];

        foreach ($role_patterns as $label => $pattern) {
            if (preg_match($pattern, $cv_text)) {
                return $label;
            }
        }

            return __('Investment Associate', 'senna-finance');
        }

    private function infer_cv_match_studio_salary_checker_seniority($role_title, array $resume_payload = [])
    {
        $role_lc = strtolower((string) $role_title);
        if (strpos($role_lc, 'chief') !== false || strpos($role_lc, 'cfo') !== false || strpos($role_lc, 'leader') !== false) {
            return 'CFO / Finance Leader';
        }
        if (strpos($role_lc, 'director') !== false || strpos($role_lc, 'head') !== false || strpos($role_lc, 'vp') !== false || strpos($role_lc, 'vice president') !== false) {
            return 'Director';
        }
        if (strpos($role_lc, 'manager') !== false || strpos($role_lc, 'controller') !== false) {
            return 'Manager';
        }

        $cv_text = strtolower(trim((string) ($resume_payload['cv_text'] ?? '')));
        if ($cv_text !== '') {
            if (preg_match('/\b(cfo|chief financial officer|finance leader)\b/', $cv_text)) {
                return 'CFO / Finance Leader';
            }
            if (preg_match('/\b(director|head of|vice president|vp)\b/', $cv_text)) {
                return 'Director';
            }
        }

        return 'Senior Manager';
    }

    private function build_cv_match_studio_salary_checker_context($user_id, array $resume_payload = [], $role_title = '', $location = '', $seniority = '')
    {
        $user_id = (int) $user_id;
        $role_title = trim(sanitize_text_field((string) $role_title));
        $location = trim(sanitize_text_field((string) $location));
        $seniority = trim(sanitize_text_field((string) $seniority));

        if ($role_title === '') {
            $role_title = __('Investment Associate', 'senna-finance');
        }

        if ($location === '') {
            $location = 'Dubai, United Arab Emirates';
        }

        if ($seniority === '') {
            $seniority = $this->infer_cv_match_studio_salary_checker_seniority($role_title, $resume_payload);
        }

        return [
            'role_title' => $role_title,
            'location' => $location,
            'seniority' => $seniority,
            'company' => '',
            'salary_text' => '',
            'employment_type' => 'Full-time',
        ];
    }

        private function get_cv_match_studio_salary_checker_payload(array $context)
        {
            $payload = $this->generate_crm_reddit_single_job_salary_trajectory([
                'role_title' => sanitize_text_field((string) ($context['role_title'] ?? __('Investment Associate', 'senna-finance'))),
                'location' => sanitize_text_field((string) ($context['location'] ?? 'Dubai, United Arab Emirates')),
                'seniority' => sanitize_text_field((string) ($context['seniority'] ?? '')),
                'company' => '',
                'salary_text' => '',
                'employment_type' => 'Full-time',
            ]);
            $payload['comparison_currency'] = 'USD';

            return $payload;
        }

