    private function normalize_cv_match_studio_salary_comp_mix(array $comp_mix)
    {
        $fallback = [
            ['label' => __('Base salary', 'senna-finance'), 'percent' => 68, 'color' => '#0a66c2'],
            ['label' => __('Bonus', 'senna-finance'), 'percent' => 14, 'color' => '#16a34a'],
            ['label' => __('Housing / transport', 'senna-finance'), 'percent' => 12, 'color' => '#f59e0b'],
            ['label' => __('Benefits', 'senna-finance'), 'percent' => 6, 'color' => '#64748b'],
        ];

        $colors = ['#0a66c2', '#16a34a', '#f59e0b', '#64748b', '#7c3aed'];
        $items = [];
        foreach ($comp_mix as $index => $item) {
            if (!is_array($item)) {
                continue;
            }
            $label = trim(sanitize_text_field((string) ($item['label'] ?? '')));
            $percent = isset($item['percent']) && is_numeric($item['percent']) ? (int) round((float) $item['percent']) : 0;
            if ($label === '' || $percent <= 0) {
                continue;
            }
            $items[] = [
                'label' => $label,
                'percent' => min(100, max(1, $percent)),
                'color' => sanitize_hex_color((string) ($item['color'] ?? '')) ?: $colors[$index % count($colors)],
            ];
        }

        return !empty($items) ? array_slice($items, 0, 5) : $fallback;
    }

    private function get_cv_match_studio_salary_comp_mix_style(array $comp_mix)
    {
        $segments = [];
        $offset = 0;
        foreach ($comp_mix as $item) {
            $percent = min(100, max(0, (int) ($item['percent'] ?? 0)));
            if ($percent <= 0) {
                continue;
            }
            $start = $offset;
            $offset += $percent;
            $segments[] = sprintf('%s %d%% %d%%', (string) ($item['color'] ?? '#0a66c2'), $start, min(100, $offset));
            if ($offset >= 100) {
                break;
            }
        }
        if ($offset < 100) {
            $segments[] = sprintf('#e5eaf0 %d%% 100%%', $offset);
        }

        return '--salary-comp-mix: conic-gradient(' . implode(', ', $segments) . ');';
    }

    private function normalize_cv_match_studio_salary_market_comparison(array $market_comparison, array $salary)
    {
        $fallback = [
            ['market' => __('Dubai', 'senna-finance'), 'score' => 96, 'label' => __('Regional finance hub', 'senna-finance')],
            ['market' => __('Abu Dhabi', 'senna-finance'), 'score' => 92, 'label' => __('Institutional capital market', 'senna-finance')],
            ['market' => __('Riyadh', 'senna-finance'), 'score' => 88, 'label' => __('Growth mandate depth', 'senna-finance')],
            ['market' => __('Doha', 'senna-finance'), 'score' => 84, 'label' => __('GCC capital gateway', 'senna-finance')],
        ];

        $items = [];
        foreach ($market_comparison as $item) {
            if (!is_array($item)) {
                continue;
            }
            $market = trim(sanitize_text_field((string) ($item['market'] ?? '')));
            $score = isset($item['score']) && is_numeric($item['score']) ? (int) round((float) $item['score']) : 0;
            $label = trim(sanitize_text_field((string) ($item['label'] ?? '')));
            if ($market === '' || $score <= 0) {
                continue;
            }
            $items[] = [
                'market' => $market,
                'score' => min(100, max(1, $score)),
                'label' => $label !== '' ? $label : __('Comparable', 'senna-finance'),
            ];
        }

        return !empty($items) ? array_slice($items, 0, 5) : $fallback;
    }

    private function normalize_cv_match_studio_salary_offer_score(array $offer_score)
    {
        $score = isset($offer_score['score']) && is_numeric($offer_score['score']) ? (int) round((float) $offer_score['score']) : 78;
        $label = trim(sanitize_text_field((string) ($offer_score['label'] ?? '')));
        $summary = trim(sanitize_text_field((string) ($offer_score['summary'] ?? '')));

        return [
            'score' => min(100, max(0, $score)),
            'label' => $label !== '' ? $label : __('Strong finance package', 'senna-finance'),
            'summary' => $summary !== '' ? $summary : __('Score weighs salary, tax, allowance clarity, bonus visibility, relocation support and role scope.', 'senna-finance'),
        ];
    }

