    public function ajax_cv_match_request_market_report()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('You must be logged in to request a market report.', 'senna-finance'),
            ], 403);
        }

        $user_id = get_current_user_id();
        if ($user_id <= 0) {
            wp_send_json_error([
                'message' => __('Unable to identify your account right now.', 'senna-finance'),
            ], 500);
        }

        $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
        $payload = $this->get_cv_match_studio_career_report_payload($user_id, $resume_payload);
        $report = !empty($payload['report']) && is_array($payload['report']) ? $payload['report'] : [];

        $user = wp_get_current_user();
        $admin_email = get_option('admin_email');
        if (!is_email($admin_email)) {
            wp_send_json_error([
                'message' => __('Admin email is not configured right now.', 'senna-finance'),
            ], 500);
        }

        $target_jobs = [];
        foreach (array_slice((array) ($report['jobs'] ?? []), 0, 4) as $job) {
            if (!is_array($job) || empty($job['label'])) {
                continue;
            }
            $target_jobs[] = sprintf(
                '%s (%s%%)',
                sanitize_text_field((string) $job['label']),
                max(0, min(100, (int) ($job['fit_score'] ?? 0)))
            );
        }

        $skills = [];
        foreach (array_slice((array) ($report['skills'] ?? []), 0, 5) as $skill) {
            if (!is_array($skill) || empty($skill['label'])) {
                continue;
            }
            $skills[] = sanitize_text_field((string) $skill['label']);
        }

        $subject = sprintf(
            __('Career Report Market Request: %s', 'senna-finance'),
            $this->get_crm_reddit_current_user_full_name($user_id) ?: $user->display_name
        );

        $market_report_current_role = $this->normalize_cv_match_studio_career_report_text_value(
            $report['current_role'] ?? '',
            __('Candidate profile', 'senna-finance')
        );
        $market_report_primary_market = $this->normalize_cv_match_studio_career_report_text_value(
            $report['primary_market'] ?? '',
            __('Target market', 'senna-finance')
        );

        $message = implode("\n", array_filter([
            'A user requested a manual market report from CV Match Studio.',
            '',
            'User ID: ' . $user_id,
            'Name: ' . ($this->get_crm_reddit_current_user_full_name($user_id) ?: $user->display_name),
            'Email: ' . (string) $user->user_email,
            'Current role: ' . $market_report_current_role,
            'Experience years: ' . (string) ($report['experience_years'] ?? ''),
            'Primary market: ' . $market_report_primary_market,
            'Top target jobs: ' . (!empty($target_jobs) ? implode(', ', $target_jobs) : 'None surfaced'),
            'Skills to consider: ' . (!empty($skills) ? implode(', ', $skills) : 'None surfaced'),
            'Analysis mode: ' . (!empty($payload['generated_with_claude']) ? 'MENA Careers intelligence blend' : 'MENA Careers core analysis'),
            'Generated at: ' . (string) ($payload['generated_at'] ?? current_time('mysql')),
            '',
            'Page: ' . home_url('/'),
        ]));

        $headers = [];
        if (!empty($user->user_email) && is_email($user->user_email)) {
            $headers[] = 'Reply-To: ' . $user->display_name . ' <' . $user->user_email . '>';
        }

        $sent = wp_mail($admin_email, $subject, $message, $headers);
        if (!$sent) {
            wp_send_json_error([
                'message' => __('We could not send your market report request right now.', 'senna-finance'),
            ], 500);
        }

        wp_send_json_success([
            'message' => __('Market report request sent. MENA Careers will review your profile and follow up.', 'senna-finance'),
        ]);
    }

    public function ajax_cv_match_jobs_mailbox_search()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        $user_id = get_current_user_id();
        $search_term = isset($_POST['search']) ? sanitize_text_field(wp_unslash((string) $_POST['search'])) : '';
        $preferred_active_key = isset($_POST['active_key']) ? sanitize_key((string) wp_unslash($_POST['active_key'])) : '';
        $inline_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) wp_unslash($_POST['cv_text'] ?? ''));
        $preferred_industry = $this->normalize_cv_match_studio_preferred_industry((string) wp_unslash($_POST['preferred_industry'] ?? ''));

        $resume_payload = $user_id > 0
            ? $this->get_crm_reddit_active_resume_text($user_id)
            : ['cv_text' => '', 'has_cv' => false];

        if ($preferred_industry === '' && $user_id > 0) {
            $preferred_industry = $this->get_cv_match_studio_user_preferred_industry($user_id);
        }

        if ($inline_cv_text !== '') {
            $resume_payload['cv_text'] = $inline_cv_text;
            $resume_payload['has_cv'] = true;
            $resume_payload['source'] = 'inline';
        }
        $resume_payload['preferred_industry'] = $preferred_industry;

        $first_name = $user_id > 0 ? $this->get_crm_reddit_current_user_first_name($user_id) : '';

        wp_send_json_success([
            'html' => $this->render_cv_match_studio_jobs_mailbox_view($user_id, $resume_payload, $first_name, [], $search_term, $preferred_active_key),
        ]);
    }

