    public function ajax_reddit_check_account_email()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        $email = sanitize_email((string) wp_unslash($_POST['email'] ?? ''));
        $redirect_to = esc_url_raw((string) wp_unslash($_POST['redirect_to'] ?? $this->get_canonical_membership_url()));

        if ($email === '' || !is_email($email)) {
            wp_send_json_success([
                'exists' => false,
                'valid' => false,
            ]);
        }

        $existing_user = get_user_by('email', $email);
        if (!$existing_user instanceof WP_User) {
            wp_send_json_success([
                'exists' => false,
                'valid' => true,
            ]);
        }

        $display_name = trim((string) $existing_user->display_name);
        if ($display_name === '') {
            $display_name = trim((string) get_user_meta($existing_user->ID, 'first_name', true));
        }
        if ($display_name === '') {
            $display_name = (string) $existing_user->user_login;
        }

        wp_send_json_success([
            'exists' => true,
            'valid' => true,
            'displayName' => $display_name,
            'loginUrl' => wp_login_url($redirect_to),
        ]);
    }

    public function ajax_load_cv_match_recruiter_profile()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce');

        if (!is_user_logged_in() || !$this->current_user_has_crm_reddit_premium_access()) {
            wp_send_json_error([
                'message' => __('Upgrade your membership to view recruiter profiles.', 'senna-finance'),
                'membership_url' => $this->get_crm_reddit_membership_url(),
            ], 403);
        }

        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $crm_post_id = isset($_POST['crm_post_id']) ? absint($_POST['crm_post_id']) : 0;
        $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
        $recruiter_name = sanitize_text_field((string) ($_POST['recruiter_name'] ?? ''));

        $profile = $this->get_cv_match_recruiter_profile_data($recruiter_id, $crm_post_id, $jobs_post_id);
        if (empty($profile['recruiter'])) {
            wp_send_json_error([
                'message' => __('We could not load this recruiter profile yet.', 'senna-finance'),
            ], 404);
        }

        $html = $this->render_cv_match_recruiter_profile_modal_content(
            $profile['recruiter'],
            $profile['roles'],
            [
                'current_crm_post_id' => $crm_post_id,
                'current_jobs_post_id' => $jobs_post_id,
                'requested_name' => $recruiter_name,
            ]
        );

        wp_send_json_success([
            'html' => $html,
            'recruiter_id' => (int) ($profile['recruiter']['id'] ?? 0),
            'name' => (string) ($profile['recruiter']['name'] ?? $recruiter_name),
        ]);
    }

    private function get_cv_match_recruiter_profile_data($recruiter_id, $crm_post_id = 0, $jobs_post_id = 0)
    {
        $recruiter_id = absint($recruiter_id);
        $crm_post_id = absint($crm_post_id);
        $jobs_post_id = absint($jobs_post_id);

        if ($recruiter_id <= 0 && $crm_post_id > 0 && class_exists('SFFC_CRM_Post')) {
            $post_model = new SFFC_CRM_Post();
            $crm_post = $post_model->get($crm_post_id);
            $recruiter_id = (int) ($crm_post['recruiter_id'] ?? 0);
        }

        if ($recruiter_id <= 0 && $jobs_post_id > 0) {
            $job_item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            $crm_post_id = (int) ($job_item['crm_post_id'] ?? 0);
            if ($crm_post_id > 0 && class_exists('SFFC_CRM_Post')) {
                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get($crm_post_id);
                $recruiter_id = (int) ($crm_post['recruiter_id'] ?? 0);
            }
        }

        if ($recruiter_id <= 0 || !class_exists('SFFC_CRM_Recruiter') || !class_exists('SFFC_CRM_Post')) {
            return [
                'recruiter' => null,
                'roles' => [],
            ];
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $post_model = new SFFC_CRM_Post();

        $recruiter = $recruiter_model->get($recruiter_id);
        if (empty($recruiter) || !is_array($recruiter)) {
            return [
                'recruiter' => null,
                'roles' => [],
            ];
        }

        $roles = $post_model->get_feed([
            'recruiter_id' => $recruiter_id,
            'page' => 1,
            'per_page' => 18,
            'approved_only' => true,
            'user_id' => get_current_user_id() ?: null,
        ]);

        $recruiter['sectors'] = $this->normalize_cv_match_recruiter_terms($recruiter['sectors'] ?? []);
        $recruiter['regions'] = $this->normalize_cv_match_recruiter_terms($recruiter['regions'] ?? []);
        $recruiter['seniority_levels'] = $this->normalize_cv_match_recruiter_terms($recruiter['seniority_levels'] ?? []);

        return [
            'recruiter' => $recruiter,
            'roles' => is_array($roles) ? $roles : [],
        ];
    }

    private function normalize_cv_match_recruiter_terms($raw)
    {
        if (is_array($raw)) {
            return array_values(array_filter(array_map('sanitize_text_field', $raw)));
        }

        if (is_string($raw) && trim($raw) !== '') {
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                return array_values(array_filter(array_map('sanitize_text_field', $decoded)));
            }

            return array_values(array_filter(array_map('sanitize_text_field', preg_split('/[\r\n,|]+/', $raw) ?: [])));
        }

        return [];
    }

    private function build_cv_match_recruiter_role_permalink(array $role)
    {
        if (!empty($role['wp_post_id'])) {
            $permalink = get_permalink((int) $role['wp_post_id']);
            if (is_string($permalink) && $permalink !== '') {
                return $permalink;
            }
        }

        if (!empty($role['source_url'])) {
            return esc_url_raw((string) $role['source_url']);
        }

        if (!empty($role['application_url'])) {
            return esc_url_raw((string) $role['application_url']);
        }

        return '#';
    }

    private function get_cv_match_relative_time_label($value)
    {
        $timestamp = $value ? strtotime((string) $value) : false;
        if (!$timestamp) {
            return __('Recently', 'senna-finance');
        }

        return sprintf(
            __('%s ago', 'senna-finance'),
            human_time_diff($timestamp, current_time('timestamp'))
        );
    }

    private function render_cv_match_recruiter_profile_modal_content(array $recruiter, array $roles, array $context = [])
    {
        $name = trim((string) ($recruiter['name'] ?? ($context['requested_name'] ?? __('Recruiter profile', 'senna-finance'))));
        $title = trim((string) ($recruiter['title'] ?? __('Recruiter', 'senna-finance')));
        $firm = trim((string) ($recruiter['firm'] ?? __('Search firm', 'senna-finance')));
        $location = trim((string) ($recruiter['location'] ?? ''));
        $email = sanitize_email((string) ($recruiter['email'] ?? ''));
        $phone = trim((string) ($recruiter['phone'] ?? ''));
        $linkedin = esc_url_raw((string) ($recruiter['linkedin_url'] ?? ''));
        $photo = esc_url_raw((string) ($recruiter['photo_url'] ?? ''));
        $bio = trim((string) ($recruiter['bio'] ?? ''));
        $firm_type = trim((string) ($recruiter['firm_type'] ?? ''));
        $response_rate = isset($recruiter['response_rate']) && $recruiter['response_rate'] !== null ? (float) $recruiter['response_rate'] : null;
        $avg_response_days = isset($recruiter['avg_response_days']) ? (int) $recruiter['avg_response_days'] : 0;
        $is_verified = !empty($recruiter['is_verified']);
        $sectors = array_values(array_slice($this->normalize_cv_match_recruiter_terms($recruiter['sectors'] ?? []), 0, 4));
        $regions = array_values(array_slice($this->normalize_cv_match_recruiter_terms($recruiter['regions'] ?? []), 0, 3));
        $seniority_levels = array_values(array_slice($this->normalize_cv_match_recruiter_terms($recruiter['seniority_levels'] ?? []), 0, 3));
