    private function resolve_cv_match_job_view_jobs_post_id($jobs_post_id, $wp_post_id = 0, $crm_post_id = 0)
    {
        $jobs_post_id = absint($jobs_post_id);
        if ($jobs_post_id > 0 && get_post_type($jobs_post_id) === 'jobs') {
            return $jobs_post_id;
        }

        $wp_post_id = absint($wp_post_id);
        if ($wp_post_id > 0) {
            $wp_post = get_post($wp_post_id);
            if ($wp_post instanceof WP_Post) {
                if ($wp_post->post_type === 'jobs') {
                    return (int) $wp_post->ID;
                }

                if ($wp_post->post_type === 'sffc_recruiter_post') {
                    $linked_crm_post_id = (int) get_post_meta($wp_post->ID, '_crm_post_id', true);
                    if ($linked_crm_post_id > 0) {
                        $resolved_jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($linked_crm_post_id);
                        if ($resolved_jobs_post_id > 0) {
                            return $resolved_jobs_post_id;
                        }
                    }
                }
            }
        }

        $crm_post_id = absint($crm_post_id);
        if ($crm_post_id > 0) {
            $resolved_jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($crm_post_id);
            if ($resolved_jobs_post_id > 0) {
                return $resolved_jobs_post_id;
            }
        }

        return 0;
    }

    private function parse_cv_match_job_context_list($raw, $limit = 4)
    {
        $limit = max(1, (int) $limit);
        $values = [];

        if (is_array($raw)) {
            $values = $raw;
        } elseif (is_string($raw) && trim($raw) !== '') {
            $decoded = json_decode(wp_unslash($raw), true);
            if (is_array($decoded)) {
                $values = $decoded;
            } else {
                $values = preg_split('/\s*\|\s*/', trim($raw)) ?: [];
            }
        }

        $values = array_values(array_filter(array_map(static function ($value) {
            return sanitize_text_field((string) $value);
        }, $values), static function ($value) {
            return $value !== '';
        }));

        return array_slice(array_values(array_unique($values)), 0, $limit);
    }

    private function get_cv_match_job_dashboard_tone($score)
    {
        $score = max(0, min(100, (int) $score));
        if ($score >= 75) {
            return 'strong';
        }
        if ($score >= 55) {
            return 'good';
        }
        if ($score >= 35) {
            return 'moderate';
        }

        return 'weak';
    }

    private function get_cv_match_job_dashboard_recommendation($score)
    {
        $score = max(0, min(100, (int) $score));
        if ($score >= 78) {
            return __('High-conviction role', 'senna-finance');
        }
        if ($score >= 60) {
            return __('Worth pursuing', 'senna-finance');
        }
        if ($score >= 42) {
            return __('Borderline route', 'senna-finance');
        }

        return __('Selective fit', 'senna-finance');
    }

    private function get_cv_match_job_dashboard_risk_tone($score, $inverse = false)
    {
        $score = max(0, min(100, (int) $score));
        if ($inverse) {
            if ($score >= 74) {
                return 'low';
            }
            if ($score >= 52) {
                return 'medium';
            }

            return 'high';
        }

        if ($score >= 74) {
            return 'high';
        }
        if ($score >= 52) {
            return 'medium';
        }

        return 'low';
    }

