            </div>
        <?php
        endif;

        return (string) ob_get_clean();
    }

    private function estimate_cv_match_job_applications_needed(array $analysis, $match_score)
    {
        $difficulty = (int) ($analysis['interview_difficulty'] ?? 0);
        $specificity = (int) ($analysis['role_specificity'] ?? 0);
        $access = (int) ($analysis['recruiter_access'] ?? 0);
        $estimate = (int) round(
            12
            + ($difficulty / 18)
            + ($specificity / 24)
            - (((int) $match_score) / 20)
            - ($access / 28)
        );

        return max(3, min(18, $estimate));
    }

    private function format_cv_match_job_applications_needed_range($applications_needed)
    {
        $applications_needed = max(1, (int) $applications_needed);
        $low = max(1, $applications_needed - 1);
        $high = min(24, $applications_needed + 2);

        if ($low === $high) {
            return (string) $low;
        }

        return $low . '-' . $high;
    }

    private function get_cv_match_job_apply_method_label($recruiter_title)
    {
        $recruiter_title = trim((string) $recruiter_title);
        if ($recruiter_title !== '' && preg_match('/\brecruiter\b/i', $recruiter_title)) {
            return __('Through recruiter', 'senna-finance');
        }

        return __('Through company', 'senna-finance');
    }

    private function get_cv_match_job_timing_recommendation(array $item)
    {
        $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
        if ($posted_timestamp <= 0 && !empty($item['posted_at'])) {
            $posted_timestamp = (int) strtotime((string) $item['posted_at']);
        }

        $is_fresh = $posted_timestamp > 0
            && $posted_timestamp >= (current_time('timestamp') - WEEK_IN_SECONDS);

        if ($is_fresh) {
            return [
                'score' => 86,
                'label' => __('Next 24 hours', 'senna-finance'),
                'copy' => __('This role is less than a week old, so applying in the next 24 hours can improve your chances before the shortlist fills.', 'senna-finance'),
                'badge' => __('Fresh role', 'senna-finance'),
                'status' => 'low',
            ];
        }

        return [
            'score' => 64,
            'label' => __('Apply + reach out', 'senna-finance'),
            'copy' => __('This role is older, so apply now and follow up with the recruiter to stand out as the applicant pool may already be crowded.', 'senna-finance'),
            'badge' => __('Needs follow-up', 'senna-finance'),
            'status' => 'high',
        ];
    }

        private function build_cv_match_job_dashboard_jd_text(array $item)
        {
        $jobs_post_id = (int) ($item['post_id'] ?? 0);
        $jobs_post = $jobs_post_id > 0 ? get_post($jobs_post_id) : null;
        $jd_text = '';

        if (!empty($item['crm_post_id'])) {
            $post_model = new SFFC_CRM_Post();
            $crm_post = $post_model->get_full_detail((int) $item['crm_post_id'], get_current_user_id());

            if (!empty($crm_post)) {
                if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                }

                if (function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    $jd_text = (string) sffc_build_crm_jd_text_for_analysis($crm_post);
                }
            }
        }

        if ($jd_text === '' && $jobs_post instanceof WP_Post && $jobs_post->post_type === 'jobs') {
            $jd_text = $this->build_reddit_jobs_jd_text($jobs_post, $item);
        }

            return trim($jd_text);
        }

        private function build_cv_match_studio_jobs_mailbox_body_paragraphs($content, array $fallback = [])
        {
            $text = trim(wp_strip_all_tags((string) $content));
            $paragraphs = [];

            if ($text !== '') {
                $text = preg_replace("/\r\n?/", "\n", $text);
                $chunks = preg_split("/\n\s*\n+/", $text) ?: [];
                if (count($chunks) <= 1 && strpos($text, "\n") !== false) {
                    $chunks = preg_split("/\n+/", $text) ?: [];
                }

                foreach ($chunks as $chunk) {
                    $chunk = sanitize_text_field(trim((string) $chunk));
                    if ($chunk !== '') {
                        $paragraphs[] = $chunk;
                    }
                }
            }

            if (empty($paragraphs)) {
                foreach ($fallback as $chunk) {
                    $chunk = sanitize_text_field(trim((string) $chunk));
                    if ($chunk !== '') {
                        $paragraphs[] = $chunk;
                    }
                }
            }

            return $paragraphs;
        }

        private function normalize_cv_match_studio_jobs_mailbox_body_heading($line)
        {
            $line = strtolower(trim((string) $line));
            $line = preg_replace('/\s+/', ' ', (string) $line);
            $line = preg_replace('/(?:\s*\\\\+)+$/', '', (string) $line);
            $line = trim((string) preg_replace('/[:\-–]+$/', '', (string) $line));

            if ($line === '') {
                return '';
            }

            if (
                $line === 'overview'
                || $line === 'job description'
                || $line === 'job description overview'
                || $line === 'job description: overview'
            ) {
                return 'summary';
            }

            if (
                $line === 'key responsibilities'
                || $line === 'responsibilities'
                || $line === 'what you will do'
                || $line === 'what you’ll do'
            ) {
                return 'responsibilities';
            }

            if (
                $line === 'skills & experience'
                || $line === 'skills and experience'
                || $line === 'skills experience'
                || $line === 'requirements'
                || $line === 'candidate profile'
            ) {
                return 'skills';
            }

            if (
                $line === 'why this role stands out'
                || $line === 'why this role'
                || $line === 'why join'
                || $line === 'why this opportunity stands out'
                || $line === 'why apply'
            ) {
                return 'standout';
            }

            if (
                $line === 'compensation'
                || $line === 'salary'
                || $line === 'benefits'
                || $line === 'compensation & benefits'
            ) {
                return 'compensation';
            }

            return '';
        }

        private function extract_cv_match_studio_jobs_mailbox_body_metadata($line)
        {
            $line = trim((string) $line);
            if ($line === '') {
                return [];
            }

            preg_match_all(
                '/\b(Job Title|Company|Location|Industry|Experience Required|Compensation)\s*:\s*(.+?)(?=\s+\b(?:Job Title|Company|Location|Industry|Experience Required|Compensation)\s*:|$)/i',
                $line,
                $matches,
                PREG_SET_ORDER
            );

            if (empty($matches)) {
                return [];
            }

            $metadata = [];
            foreach ($matches as $match) {
                $label = sanitize_key(str_replace(' ', '_', strtolower((string) ($match[1] ?? ''))));
                $value = sanitize_text_field(trim((string) ($match[2] ?? '')));
                if ($label !== '' && $value !== '') {
                    $metadata[$label] = $value;
                }
            }

            return $metadata;
        }

        private function clean_cv_match_studio_jobs_mailbox_body_line($line)
        {
            $line = html_entity_decode((string) $line, ENT_QUOTES | ENT_HTML5, 'UTF-8');
            $line = str_replace(['\\r\\n', '\\n', '\\r', '\\t'], [' ', ' ', ' ', ' '], $line);
            $line = str_replace('\\', '', $line);
            $line = preg_replace('/[ \t]+/', ' ', (string) $line);
            $line = preg_replace('/(?:\s*[-–—]+)+$/', '', (string) $line);
            $line = trim((string) $line);

            return sanitize_text_field($line);
        }

        private function build_cv_match_studio_jobs_mailbox_body_sections($content, array $fallback = [], array $context = [])
        {
            $text = trim((string) $content);
            $text = html_entity_decode((string) $text, ENT_QUOTES, 'UTF-8');
            $text = wp_strip_all_tags((string) $text);
            $text = str_replace(['\\r\\n', '\\n', '\\r'], "\n", (string) $text);
            $text = preg_replace('/(?:[ \t]*\\\\+)+(?=\n|$)/', '', (string) $text);
            $text = preg_replace("/\r\n?/", "\n", (string) $text);
            $text = str_replace(["\u{2022}", "\u{25CF}", "\u{25E6}"], '•', (string) $text);
            $text = preg_replace('/[ \t]+/', ' ', (string) $text);
            $text = preg_replace("/\n{3,}/", "\n\n", (string) $text);

            $metadata = [];
            $lines = array_values(array_filter(array_map('trim', explode("\n", (string) $text)), static function ($line) {
                return trim((string) $line) !== '';
            }));

            $consumed_indexes = [];
            foreach ($lines as $line_index => $line) {
                $heading_key = $this->normalize_cv_match_studio_jobs_mailbox_body_heading($line);
                if ($heading_key !== '') {
                    break;
                }

                $line_metadata = $this->extract_cv_match_studio_jobs_mailbox_body_metadata($line);
                if (!empty($line_metadata)) {
                    $metadata = array_merge($metadata, $line_metadata);
                    $consumed_indexes[$line_index] = true;
                    continue;
                }

                if (!empty($metadata)) {
                    break;
                }
            }

            $working_lines = [];
            foreach ($lines as $line_index => $line) {
                if (!isset($consumed_indexes[$line_index])) {
                    $working_lines[] = $line;
                }
            }

            $section_labels = [
                'summary' => __('Role summary', 'senna-finance'),
                'responsibilities' => __('Key responsibilities', 'senna-finance'),
                'skills' => __('Skills & experience', 'senna-finance'),
                'standout' => __('Why this role stands out', 'senna-finance'),
                'compensation' => __('Compensation', 'senna-finance'),
            ];

            $sections_map = [];
            $current_key = 'summary';

            $ensure_section = static function (&$sections_map, $section_key, $section_labels) {
                if (!isset($sections_map[$section_key])) {
                    $sections_map[$section_key] = [
                        'key' => $section_key,
                        'label' => $section_labels[$section_key] ?? ucwords(str_replace('_', ' ', $section_key)),
                        'paragraphs' => [],
                        'bullets' => [],
                    ];
                }
            };

            $ensure_section($sections_map, $current_key, $section_labels);

            foreach ($working_lines as $line) {
                $heading_key = $this->normalize_cv_match_studio_jobs_mailbox_body_heading($line);
                if ($heading_key !== '') {
                    $current_key = $heading_key;
                    $ensure_section($sections_map, $current_key, $section_labels);
                    continue;
                }

                if (stripos($line, 'Compensation:') === 0) {
                    $current_key = 'compensation';
                    $ensure_section($sections_map, $current_key, $section_labels);
                    $value = $this->clean_cv_match_studio_jobs_mailbox_body_line(substr($line, strlen('Compensation:')));
                    if ($value !== '') {
                        $sections_map[$current_key]['paragraphs'][] = $value;
                    }
                    continue;
                }

                $line = $this->clean_cv_match_studio_jobs_mailbox_body_line($line);
                if ($line === '') {
                    continue;
                }

                if (preg_match('/^(?:•|-|\*)\s*(.+)$/u', $line, $bullet_match)) {
                    $ensure_section($sections_map, $current_key, $section_labels);
                    $bullet = $this->clean_cv_match_studio_jobs_mailbox_body_line($bullet_match[1] ?? '');
                    if ($bullet !== '') {
                        $sections_map[$current_key]['bullets'][] = $bullet;
                    }
                    continue;
                }

                $ensure_section($sections_map, $current_key, $section_labels);
                $sections_map[$current_key]['paragraphs'][] = $line;
            }

            $sections = array_values(array_filter($sections_map, static function ($section) {
                return !empty($section['paragraphs']) || !empty($section['bullets']);
            }));

            if (empty($sections)) {
                $fallback_paragraphs = $this->build_cv_match_studio_jobs_mailbox_body_paragraphs('', $fallback);
                if (!empty($fallback_paragraphs)) {
                    $sections[] = [
                        'key' => 'summary',
                        'label' => __('Role summary', 'senna-finance'),
                        'paragraphs' => $fallback_paragraphs,
                        'bullets' => [],
                    ];
                }
            }

            $tag_map = [
                'location' => !empty($metadata['location']) ? sprintf(__('Location: %s', 'senna-finance'), $metadata['location']) : (!empty($context['location']) ? sprintf(__('Location: %s', 'senna-finance'), $context['location']) : ''),
                'experience_required' => !empty($metadata['experience_required']) ? sprintf(__('Experience: %s', 'senna-finance'), $metadata['experience_required']) : (!empty($context['seniority']) ? sprintf(__('Level: %s', 'senna-finance'), $context['seniority']) : ''),
                'industry' => !empty($metadata['industry']) ? sprintf(__('Focus: %s', 'senna-finance'), str_replace('_', ' ', $metadata['industry'])) : (!empty($context['sector']) ? sprintf(__('Focus: %s', 'senna-finance'), $context['sector']) : ''),
                'compensation' => !empty($metadata['compensation']) ? sprintf(__('Comp: %s', 'senna-finance'), $metadata['compensation']) : (!empty($context['salary_text']) ? sprintf(__('Comp: %s', 'senna-finance'), $context['salary_text']) : ''),
            ];

            return [
                'sections' => $sections,
                'tags' => array_values(array_filter(array_map('sanitize_text_field', $tag_map))),
            ];
        }

        private function render_cv_match_studio_jobs_mailbox_body_sections(array $body, $class_name = '', $show_tags = true)
        {
            $sections = (array) ($body['sections'] ?? []);
            if (empty($sections)) {
                return '';
            }

            $class_names = trim('sffc-cv-match-studio__jobs-mailbox-messagebody' . ($class_name !== '' ? ' ' . $class_name : ''));

            ob_start();
            ?>
            <div class="<?php echo esc_attr($class_names); ?>">
                <?php if ($show_tags && !empty($body['tags'])) : ?>
                    <div class="sffc-cv-match-studio__jobs-mailbox-bodytags">
                        <?php foreach ((array) $body['tags'] as $tag_index => $tag) : ?>
                            <span class="sffc-cv-match-studio__jobs-mailbox-bodytag is-tone-<?php echo esc_attr((string) (($tag_index % 3) + 1)); ?>">
                                <?php echo esc_html((string) $tag); ?>
                            </span>
                        <?php endforeach; ?>
                    </div>
                <?php endif; ?>
                <?php foreach ($sections as $section) : ?>
                    <section class="sffc-cv-match-studio__jobs-mailbox-bodysection is-<?php echo esc_attr((string) ($section['key'] ?? 'summary')); ?>">
                        <span class="sffc-cv-match-studio__jobs-mailbox-bodylabel"><?php echo esc_html((string) ($section['label'] ?? '')); ?></span>
                        <?php foreach ((array) ($section['paragraphs'] ?? []) as $paragraph) : ?>
                            <?php $paragraph = $this->clean_cv_match_studio_jobs_mailbox_body_line($paragraph); ?>
                            <?php if ($paragraph !== '') : ?>
                                <p><?php echo esc_html($paragraph); ?></p>
                            <?php endif; ?>
                        <?php endforeach; ?>
                        <?php if (!empty($section['bullets'])) : ?>
                            <ul class="sffc-cv-match-studio__jobs-mailbox-bodylist">
                                <?php foreach ((array) $section['bullets'] as $bullet) : ?>
                                    <?php $bullet = $this->clean_cv_match_studio_jobs_mailbox_body_line($bullet); ?>
                                    <?php if ($bullet !== '') : ?>
                                        <li><?php echo esc_html($bullet); ?></li>
                                    <?php endif; ?>
                                <?php endforeach; ?>
                            </ul>
                        <?php endif; ?>
                    </section>
                <?php endforeach; ?>
            </div>
            <?php

            return (string) ob_get_clean();
        }

        private function normalize_cv_match_studio_jobs_mailbox_detector_text($text)
        {
            $text = html_entity_decode((string) $text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
            $text = wp_strip_all_tags((string) $text);
            $text = preg_replace("/\r\n?/", "\n", (string) $text);
            $text = str_replace(["\u{2022}", "\u{25CF}", "\u{25E6}"], ' ', (string) $text);
            $text = preg_replace('/[^\p{L}\p{N}\s\+\&\-\.\,\/]/u', ' ', (string) $text);
            $text = preg_replace('/\s+/', ' ', (string) $text);
            $text = trim((string) $text);

            return function_exists('mb_strtolower') ? mb_strtolower($text) : strtolower($text);
        }

        private function format_cv_match_studio_jobs_mailbox_signal_list(array $signals, $limit = 3, $fallback = '')
        {
            $signals = array_values(array_filter(array_map('sanitize_text_field', $signals)));
            $signals = array_values(array_unique($signals));
            $signals = array_slice($signals, 0, max(1, (int) $limit));

            if (empty($signals)) {
                return (string) $fallback;
            }

            if (count($signals) === 1) {
                return (string) $signals[0];
            }

            if (count($signals) === 2) {
                return $signals[0] . ' ' . __('and', 'senna-finance') . ' ' . $signals[1];
            }

            $last = array_pop($signals);

            return implode(', ', $signals) . ', ' . __('and', 'senna-finance') . ' ' . $last;
        }

        private function pick_cv_match_studio_jobs_mailbox_signal_list(array $preferred, array $used = [], $limit = 3, array $fallback = [])
        {
            $limit = max(1, (int) $limit);
            $seen = [];
            foreach ($used as $value) {
                $key = $this->normalize_cv_match_studio_jobs_mailbox_detector_text((string) $value);
                if ($key !== '') {
                    $seen[$key] = true;
                }
            }

            $selected = [];
            $append = function (array $candidates) use (&$selected, &$seen, $limit) {
                foreach ($candidates as $candidate) {
                    $candidate = sanitize_text_field((string) $candidate);
                    $key = $this->normalize_cv_match_studio_jobs_mailbox_detector_text($candidate);
                    if ($candidate === '' || $key === '' || isset($seen[$key])) {
                        continue;
                    }
                    $selected[] = $candidate;
                    $seen[$key] = true;
                    if (count($selected) >= $limit) {
                        break;
                    }
                }
            };

            $append($preferred);
            if (count($selected) < $limit) {
                $append($fallback);
            }

            return array_slice($selected, 0, $limit);
        }

