                $group_scores['product'] += 2;
            }
            if (strpos($title_haystack, 'product associate') !== false || strpos($title_haystack, 'product management') !== false || strpos($title_haystack, 'client & product solutions') !== false) {
                $group_scores['product'] += 2;
                $group_scores['communication'] += 1;
            }
            if (strpos($title_haystack, 'client solution') !== false || strpos($title_haystack, 'solution') !== false || strpos($title_haystack, 'customer success') !== false || strpos($title_haystack, 'pre sales') !== false || strpos($title_haystack, 'presales') !== false || strpos($title_haystack, 'saas') !== false) {
                $group_scores['product'] += 2;
                $group_scores['communication'] += 1;
            }
            if (strpos($title_haystack, 'operations') !== false || strpos($title_haystack, 'event') !== false) {
                $group_scores['operations'] += 2;
            }
            if (strpos($title_haystack, 'summer analyst') !== false || strpos($title_haystack, 'trading desk') !== false) {
                $group_scores['operations'] += 2;
                $group_scores['markets'] += 1;
            }
            if (strpos($title_haystack, 'servicing') !== false || strpos($title_haystack, 'collateral') !== false || strpos($title_haystack, 'corporate action') !== false) {
                $group_scores['operations'] += 2;
            }
            if (strpos($title_haystack, 'business development') !== false || strpos($title_haystack, 'growth') !== false || strpos($title_haystack, 'partnership') !== false) {
                $group_scores['origination'] += 2;
                $group_scores['communication'] += 1;
            }
            if (strpos($title_haystack, 'investor relations') !== false || strpos($title_haystack, 'client') !== false || strpos($title_haystack, 'advisory') !== false || strpos($title_haystack, 'wealth') !== false) {
                $group_scores['communication'] += 2;
                $group_scores['product'] += 1;
            }
            if (strpos($title_haystack, 'product management') !== false || strpos($title_haystack, 'product manager') !== false) {
                $group_scores['product'] += 2;
                $group_scores['communication'] += 1;
            }
            if (strpos($title_haystack, 'research') !== false || strpos($title_haystack, 'strategist') !== false || strpos($title_haystack, 'economist') !== false || strpos($title_haystack, 'macro') !== false) {
                $group_scores['markets'] += 2;
                $group_scores['communication'] += 1;
            }
            if (strpos($title_haystack, 'research associate') !== false || strpos($title_haystack, 'thematic') !== false || strpos($title_haystack, 'strategy') !== false) {
                $group_scores['markets'] += 2;
                $group_scores['communication'] += 2;
            }
            if (strpos($title_haystack, 'principal') !== false || strpos($title_haystack, 'coo') !== false || strpos($title_haystack, 'operating model') !== false || strpos($title_haystack, 'credit platform') !== false) {
                $group_scores['operations'] += 2;
                $group_scores['investing'] += 1;
            }
            if (strpos($title_haystack, 'specialist') !== false || strpos($title_haystack, 'coverage') !== false || strpos($title_haystack, 'relations') !== false || strpos($title_haystack, 'fundraising') !== false) {
                $group_scores['communication'] += 2;
            }
            if (strpos($title_haystack, 'family office') !== false || strpos($title_haystack, 'principal') !== false || strpos($title_haystack, 'portfolio manager') !== false) {
                $group_scores['markets'] += 2;
                $group_scores['investing'] += 1;
            }
            if (strpos($title_haystack, 'accountant') !== false || strpos($title_haystack, 'investment accounting') !== false || strpos($title_haystack, 'junior accountant') !== false) {
                $group_scores['reporting'] += 2;
                $group_scores['operations'] += 1;
            }
            if (strpos($title_haystack, 'insurance') !== false || strpos($title_haystack, 'solvency') !== false || strpos($title_haystack, 'pension') !== false) {
                $group_scores['reporting'] += 1;
                $group_scores['investing'] += 1;
            }

            arsort($group_scores);
            $primary_group = (string) array_key_first($group_scores);
            $primary_signals = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($signals_by_group[$primary_group] ?? [])))));
            $all_signals = [];
            foreach ($signals_by_group as $group_labels) {
                $all_signals = array_merge($all_signals, (array) $group_labels);
            }

            return [
                'primary_group' => $primary_group,
                'group_scores' => $group_scores,
                'primary_signals' => array_slice($primary_signals, 0, 4),
                'secondary_signals' => array_slice(array_values(array_unique(array_filter(array_map('sanitize_text_field', $all_signals)))), 0, 8),
                'tools' => array_values(array_unique(array_filter(array_map('sanitize_text_field', $tools)))),
                'credentials' => array_values(array_unique(array_filter(array_map('sanitize_text_field', $credentials)))),
                'differentiators' => array_values(array_unique(array_filter(array_map('sanitize_text_field', $differentiators)))),
            ];
        }

        private function build_cv_match_studio_jobs_mailbox_positioning_metrics_from_role($content, array $context = [], $match_score = 0)
        {
            $signals = $this->extract_cv_match_studio_jobs_mailbox_role_signals($content, $context);
            $primary_group = (string) ($signals['primary_group'] ?? 'investing');
            $primary_signals = (array) ($signals['primary_signals'] ?? []);
            $secondary_signals = (array) ($signals['secondary_signals'] ?? []);
            $tools = (array) ($signals['tools'] ?? []);
            $credentials = (array) ($signals['credentials'] ?? []);
            $differentiators = (array) ($signals['differentiators'] ?? []);
            $experience_required = trim((string) ($context['experience_required'] ?? ''));
            $seniority = trim((string) ($context['seniority'] ?? ''));

            $keyword_fallback = array_values(array_filter(array_map('sanitize_text_field', (array) ($context['keywords'] ?? []))));
            $screen_signal_list = $this->pick_cv_match_studio_jobs_mailbox_signal_list(
                $primary_signals,
                [],
                3,
                $keyword_fallback
            );
            $evidence_signal_list = $this->pick_cv_match_studio_jobs_mailbox_signal_list(
                array_merge(array_slice($secondary_signals, 0, 6), $tools, $credentials),
                $screen_signal_list,
                3,
                array_merge(array_slice($primary_signals, 0, 2), $keyword_fallback)
            );
            $credibility_signal_list = $this->pick_cv_match_studio_jobs_mailbox_signal_list(
                array_merge($tools, $credentials, array_slice($secondary_signals, 2, 6)),
                array_merge($screen_signal_list, $evidence_signal_list),
                3,
                array_slice($primary_signals, 1, 3)
            );
            $standout_signal_list = $this->pick_cv_match_studio_jobs_mailbox_signal_list(
                array_merge($differentiators, $credentials, $tools, array_slice($secondary_signals, 4, 6)),
                array_merge($screen_signal_list, $evidence_signal_list, $credibility_signal_list),
                2,
                array_slice($secondary_signals, 0, 3)
            );

            $screen_signal = $this->format_cv_match_studio_jobs_mailbox_signal_list(
                $screen_signal_list,
                3,
                __('the strongest signals in the brief', 'senna-finance')
            );
            $evidence_signal = $this->format_cv_match_studio_jobs_mailbox_signal_list(
                $evidence_signal_list,
                3,
                $screen_signal
            );
            $credibility_signal = $this->format_cv_match_studio_jobs_mailbox_signal_list(
                $credibility_signal_list,
                3,
                $evidence_signal
            );
            $standout_signal = $this->format_cv_match_studio_jobs_mailbox_signal_list(
                $standout_signal_list,
                2,
                $this->format_cv_match_studio_jobs_mailbox_signal_list(array_slice($secondary_signals, 0, 2), 2, __('one quantified example from closely related work', 'senna-finance'))
            );

            $group_copy = [
                'origination' => [
                    'screen' => __('They will first look for early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show this through work experience, deal exposure, projects, certifications, or a small research piece linked to %s.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining what you learned about %s and why it interests you.', 'senna-finance'),
                    'standout' => __('Stand out by adding one simple example: a pitch, outreach project, research note, or commercial idea connected to %s.', 'senna-finance'),
                ],
                'investing' => [
                    'screen' => __('They will first look for genuine interest and basic exposure to %s.', 'senna-finance'),
                    'evidence' => __('Evidence %s through transaction exposure, portfolio work, a stock pitch, a simple model, a finance role, or a relevant project.', 'senna-finance'),
                    'credibility' => __('Sound credible by saying what you understand about %s in plain language, not by over-claiming deal experience.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one concrete leadership example, such as a valuation memo, investment recommendation, or strategic market view.', 'senna-finance'),
                ],
                'markets' => [
                    'screen' => __('They will first look for curiosity and basic market awareness around %s.', 'senna-finance'),
                    'evidence' => __('Show %s through coursework, a market note, Bloomberg or Excel exposure, or a short research project.', 'senna-finance'),
                    'credibility' => __('Sound credible by describing one market idea or learning point linked to %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one concise market view, chart, or research output you can discuss clearly.', 'senna-finance'),
                ],
                'risk' => [
                    'screen' => __('They will first look for analytical discipline and early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show %s through Excel work, data handling, reporting ownership, risk projects, or operational responsibility.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining how you approached accuracy, process, or judgement around %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one clear example of careful analysis, checking work, or improving a process.', 'senna-finance'),
                ],
                'reporting' => [
                    'screen' => __('They will first look for reliability, accuracy, and early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show %s through Excel work, accounting coursework, reporting tasks, reconciliations, or a detail-heavy project.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining how you kept work accurate and organised around %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one deadline-driven task where accuracy mattered.', 'senna-finance'),
                ],
                'operations' => [
                    'screen' => __('They will first look for organisation, follow-through, and early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show %s through operations work, team leadership, project coordination, process ownership, or administrative responsibility.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining how you stayed organised and dependable around %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one example where you coordinated people, deadlines, or data cleanly.', 'senna-finance'),
                ],
                'product' => [
                    'screen' => __('They will first look for analytical curiosity and early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show %s through a project, presentation, Excel analysis, product research, or client-facing finance work.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining the user, client, or investment problem behind %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one small improvement you made to a tool, deck, process, or analysis.', 'senna-finance'),
                ],
                'communication' => [
                    'screen' => __('They will first look for clear communication and early exposure to %s.', 'senna-finance'),
                    'evidence' => __('Show %s through presentations, society work, client-service tasks, written research, or interview examples.', 'senna-finance'),
                    'credibility' => __('Sound credible by explaining what you communicated, to whom, and what changed around %s.', 'senna-finance'),
                    'standout' => __('Stand out by pairing %s with one concise example of clear writing, presenting, or stakeholder communication.', 'senna-finance'),
                ],
            ];

            $copy = $group_copy[$primary_group] ?? $group_copy['investing'];
            $score_floor = max(54, min(90, (int) $match_score));
            $clarity_bonus = min(8, count($primary_signals) * 2 + count($tools) + count($credentials));

            $metrics = [
                [
                    'label' => __('What they check first', 'senna-finance'),
                    'score' => max(58, min(96, $score_floor + $clarity_bonus + 4)),
                    'detail' => sprintf($copy['screen'], $screen_signal),
                    'tone' => 'blue',
                ],
                [
                    'label' => __('What to show on your CV', 'senna-finance'),
                    'score' => max(56, min(94, $score_floor + $clarity_bonus + 1)),
                    'detail' => sprintf($copy['evidence'], $evidence_signal),
                    'tone' => 'green',
                ],
                [
                    'label' => __('How to talk about it', 'senna-finance'),
                    'score' => max(52, min(92, $score_floor + max(1, count($tools) + count($credentials)))),
                    'detail' => sprintf($copy['credibility'], $credibility_signal),
                    'tone' => 'gold',
                ],
                [
                    'label' => __('How to stand out', 'senna-finance'),
                    'score' => max(55, min(94, $score_floor + count($differentiators) + count($credentials) + 3)),
                    'detail' => sprintf($copy['standout'], $standout_signal),
                    'tone' => 'purple',
                ],
            ];

            if ($experience_required !== '' || $seniority !== '') {
                $experience_signal = $experience_required !== '' ? $experience_required : $seniority;
                $metrics[1]['detail'] = rtrim($metrics[1]['detail'], '.') . ' ' . sprintf(__('The role appears to sit around %s, so keep the evidence specific, senior, and credible.', 'senna-finance'), sanitize_text_field($experience_signal));
            }

            foreach ($metrics as &$metric) {
                $metric['bars'] = $this->build_crm_reddit_single_job_bars((int) $metric['score']);
            }
            unset($metric);

            return $metrics;
        }

        private function get_cv_match_job_tracking_context(array $item)
        {
        $default = [
            'pipeline_id' => 0,
            'pipeline_stage' => '',
            'pipeline_stage_label' => __('Not tracked yet', 'senna-finance'),
            'pipeline_stage_color' => '#cbd5e1',
        ];

        if (!is_user_logged_in() || !class_exists('SFFC_CRM_Pipeline')) {
            return $default;
        }

        global $wpdb;

        $user_id = get_current_user_id();
        if ($user_id <= 0) {
            return $default;
        }

        $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
        $stage_meta = SFFC_CRM_Pipeline::get_stages();
        $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
        $role_title = (string) ($item['role_title'] ?? '');
        $company = (string) ($item['company'] ?? '');
        $location = (string) ($item['location'] ?? '');
        $external_url = '';
        if (!empty($item['_jobs_mailbox_view_url'])) {
            $external_url = (string) $item['_jobs_mailbox_view_url'];
        } elseif (!empty($item['view_url'])) {
            $external_url = (string) $item['view_url'];
        } elseif (!empty($item['apply_url'])) {
            $external_url = (string) $item['apply_url'];
        }
        $pipeline_item = null;

        if ($crm_post_id > 0) {
            $pipeline_item = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT id, stage
                     FROM {$pipeline_table}
                     WHERE user_id = %d AND post_id = %d
                     ORDER BY updated_at DESC, stage_entered_at DESC, id DESC
                     LIMIT 1",
                    $user_id,
                    $crm_post_id
                ),
                ARRAY_A
            );
        }

        if (!$pipeline_item && $external_url !== '') {
            $pipeline_item = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT id, stage
                     FROM {$pipeline_table}
                     WHERE user_id = %d AND external_url = %s
                     ORDER BY updated_at DESC, stage_entered_at DESC, id DESC
                     LIMIT 1",
                    $user_id,
                    $external_url
                ),
                ARRAY_A
            );
        }

        if (!$pipeline_item && $role_title !== '' && $company !== '') {
            $pipeline_item = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT id, stage
                     FROM {$pipeline_table}
                     WHERE user_id = %d AND role_title = %s AND company = %s AND location = %s
                     ORDER BY updated_at DESC, stage_entered_at DESC, id DESC
                     LIMIT 1",
                    $user_id,
                    $role_title,
                    $company,
                    $location
                ),
                ARRAY_A
            );
        }

        if (empty($pipeline_item)) {
            return $default;
        }

        $pipeline_stage = (string) ($pipeline_item['stage'] ?? '');
        $pipeline_stage_meta = $pipeline_stage !== '' && isset($stage_meta[$pipeline_stage])
            ? (array) $stage_meta[$pipeline_stage]
            : [];
        $pipeline_stage_label = (string) ($pipeline_stage_meta['label'] ?? '');
        if ($pipeline_stage_label === '' && $pipeline_stage !== '') {
            $pipeline_stage_label = $this->get_cv_match_readable_pipeline_stage_label($pipeline_stage);
        }

        return [
            'pipeline_id' => (int) ($pipeline_item['id'] ?? 0),
            'pipeline_stage' => $pipeline_stage,
            'pipeline_stage_label' => $pipeline_stage_label !== '' ? $pipeline_stage_label : __('Tracked', 'senna-finance'),
            'pipeline_stage_color' => (string) ($pipeline_stage_meta['color'] ?? '#cbd5e1'),
        ];
    }

        private function get_cv_match_readable_pipeline_stage_label($stage)
        {
            $stage = trim((string) $stage);
            if ($stage === '') {
                return '';
            }

            $legacy_labels = [
                'applied' => __('Applied', 'senna-finance'),
                'submitted' => __('Application Submitted', 'senna-finance'),
                'application' => __('Application Submitted', 'senna-finance'),
                'message_sent' => __('Messaged', 'senna-finance'),
                'messaged_recruiter' => __('Messaged', 'senna-finance'),
                'followup' => __('Follow Up', 'senna-finance'),
                'followed_up' => __('Follow Up', 'senna-finance'),
                'interview' => __('Interview', 'senna-finance'),
                'oa' => __('Online Assessment', 'senna-finance'),
                'assessment' => __('Assessment Centre', 'senna-finance'),
                'offer' => __('Offer Received', 'senna-finance'),
            ];

            if (isset($legacy_labels[$stage])) {
                return (string) $legacy_labels[$stage];
            }

            return ucwords(str_replace(['_', '-'], ' ', $stage));
        }

    private function render_cv_match_job_dashboard(array $item, array $analysis, array $context = [])
    {
        $match_score = max(0, min(100, (int) ($context['match_score'] ?? 0)));
        if ($match_score <= 0) {
            $match_score = $this->clamp_crm_reddit_single_job_metric(
                (int) round(((int) ($analysis['recruiter_access'] ?? 0) + (int) ($analysis['role_specificity'] ?? 0) + (100 - (int) ($analysis['cv_change_intensity'] ?? 0))) / 3),
                28,
                94
            );
        }

        $tone = $this->get_cv_match_job_dashboard_tone($match_score);
        $recommendation = $this->get_cv_match_job_dashboard_recommendation($match_score);
        $role_title = trim((string) ($item['role_title'] ?? __('Role workspace', 'senna-finance')));
        $company = trim((string) ($item['company'] ?? __('MENA Careers', 'senna-finance')));
        $location = trim((string) ($item['location'] ?? ''));
        $salary_text = trim((string) ($item['salary_text'] ?? ''));
        $sector = trim((string) ($item['sector'] ?? ''));
        $employment_type = trim((string) ($item['employment_type'] ?? ''));
        $seniority = trim((string) ($item['seniority'] ?? ''));
        $posted_label = trim((string) ($item['posted_label'] ?? ''));
        $apply_url = trim((string) ($item['apply_url'] ?? ''));
        $view_url = trim((string) ($item['view_url'] ?? ''));
        $tracking_external_url = $apply_url !== '' ? $apply_url : $view_url;
        $company_logo = trim((string) ($item['company_logo'] ?? ''));
        $has_recruiter_name_access = $this->current_user_has_crm_reddit_premium_access();
        $recruiter_name = trim((string) ($item['recruiter_name'] ?? __('Recruiter', 'senna-finance')));
        $recruiter_display_name = $this->get_crm_reddit_public_recruiter_name($recruiter_name, $has_recruiter_name_access);
        $recruiter_title = trim((string) ($item['recruiter_title'] ?? __('Hiring team', 'senna-finance')));
        $recruiter_firm = trim((string) ($item['recruiter_firm'] ?? ''));
        $recruiter_photo = trim((string) ($item['recruiter_photo'] ?? ''));
        $recruiter_email = trim((string) ($item['recruiter_email'] ?? ''));
        $recruiter_linkedin = trim((string) ($item['recruiter_linkedin'] ?? ''));
        $recruiter_phone = trim((string) ($item['recruiter_phone'] ?? ''));
        $membership_url = $this->get_crm_reddit_membership_url();
        $recruiter_id = (int) ($context['recruiter_id'] ?? ($item['recruiter_id'] ?? 0));
        $recruiter_open_roles_count = max(
            0,
            (int) ($context['recruiter_open_roles_count'] ?? ($item['recruiter_open_roles_count'] ?? 0))
        );
        $recruiter_open_roles_label = sprintf(
            _n('%d role open', '%d roles open', $recruiter_open_roles_count, 'senna-finance'),
            $recruiter_open_roles_count
        );
        $recruiter_phone_digits = preg_replace('/[^0-9\+]/', '', $recruiter_phone);
        $masked_email_label = $recruiter_email !== '' && strpos($recruiter_email, '@') !== false
            ? preg_replace('/^(.).+(@.+)$/', '$1****$2', sanitize_email($recruiter_email))
            : __('Email', 'senna-finance');
        $masked_phone_label = $recruiter_phone_digits !== ''
            ? substr($recruiter_phone_digits, 0, 2) . '******' . substr($recruiter_phone_digits, -1)
            : __('Call', 'senna-finance');
        $linkedin_label = $has_recruiter_name_access
            ? $recruiter_name
            : $this->get_crm_reddit_public_recruiter_name($recruiter_name, false);
        $cv_text = trim((string) ($context['cv_text'] ?? ''));
        $has_cv = !empty($context['has_cv']) || $cv_text !== '';
        $description_text = wp_trim_words($this->get_crm_reddit_single_job_description_text($item), 30, '…');
        $match_reasons = !empty($context['reasons']) ? (array) $context['reasons'] : array_slice((array) ($analysis['best_odds'] ?? []), 0, 3);
        $match_gaps = !empty($context['gaps']) ? (array) $context['gaps'] : array_slice((array) ($analysis['cv_changes'] ?? []), 0, 3);
        $match_warnings = !empty($context['warnings']) ? (array) $context['warnings'] : array_slice((array) ($analysis['rejection_profiles'] ?? []), 0, 3);
        $signal_skills = !empty($context['skills']) ? (array) $context['skills'] : (array) ($analysis['top_skills'] ?? []);
        $top_skills = array_values(array_slice(array_filter(array_map('strval', (array) ($analysis['top_skills'] ?? []))), 0, 4));
        $backgrounds = array_values(array_slice(array_filter(array_map('strval', (array) ($analysis['backgrounds'] ?? []))), 0, 4));
        $qualifications = array_values(array_slice(array_filter(array_map('strval', (array) ($analysis['qualifications'] ?? []))), 0, 3));
        $reach_out_targets = array_values(array_slice(array_filter((array) ($analysis['reach_out_targets'] ?? []), 'is_array'), 0, 3));
        $role_context = $this->build_crm_reddit_networking_context((int) ($item['post_id'] ?? 0));
        $application_steps = !empty($role_context['application_process']) && is_array($role_context['application_process'])
            ? array_values(array_slice(array_filter(array_map('strval', $role_context['application_process'])), 0, 4))
            : [];
        $team_contacts = !empty($role_context['team_contacts']) && is_array($role_context['team_contacts'])
            ? array_values(array_slice(array_filter(array_map('strval', $role_context['team_contacts'])), 0, 3))
            : [];
        if (!$has_recruiter_name_access) {
            foreach ($reach_out_targets as &$reach_out_target) {
                $target_role = trim((string) ($reach_out_target['role'] ?? ''));
                if (!empty($reach_out_target['name']) && stripos($target_role, 'recruiter') !== false) {
                    $reach_out_target['name'] = $this->get_crm_reddit_public_recruiter_name((string) $reach_out_target['name'], false);
                }
            }
            unset($reach_out_target);
        }
        $keyword_target = max(1, (int) ($analysis['keyword_target'] ?? 1));
        $keyword_covered = max(0, min($keyword_target, (int) ($analysis['keyword_covered'] ?? 0)));
        $keyword_percent = max(0, min(100, (int) round(($keyword_covered / $keyword_target) * 100)));
        $required_years = trim((string) ($analysis['required_years'] ?? ''));
        $role_badge = trim((string) ($analysis['badge'] ?? ''));
        $fit_copy = trim((string) ($analysis['fit_copy'] ?? ''));
        $outreach_line = trim((string) ($analysis['outreach_line'] ?? ''));
        $preference = trim((string) ($analysis['preference'] ?? ''));
        $job_description_text = $this->build_cv_match_job_dashboard_jd_text($item);
        $salary_trajectory = !empty($context['fast_intel'])
            ? $this->get_crm_reddit_single_job_salary_trajectory_fast($item)
            : $this->get_crm_reddit_single_job_salary_trajectory($item);
        $salary_panel_html = $this->render_crm_reddit_single_job_salary_section(
            is_array($salary_trajectory) ? $salary_trajectory : [],
            $has_recruiter_name_access,
            $membership_url
        );
        $tracking_context = $this->get_cv_match_job_tracking_context($item);
        $tracker_stage_options = class_exists('SFFC_CRM_Pipeline') ? array_intersect_key(
            SFFC_CRM_Pipeline::get_stages(),
            array_flip(['interested', 'application_submitted', 'messaged', 'follow_up'])
        ) : [];
        $primary_background = $backgrounds[0] ?? __('Relevant Finance Background', 'senna-finance');
        $secondary_backgrounds = array_values(array_slice($backgrounds, 1, 3));
        $filtered_qualifications = array_values(array_filter($qualifications, static function ($qualification) {
            $qualification = trim((string) $qualification);
            return $qualification !== '' && $qualification !== __('Relevant Degree', 'senna-finance');
        }));
        $profile_signals = array_values(array_filter([
            $required_years,
            $seniority !== '' ? ucfirst(str_replace('_', ' ', $seniority)) : '',
            $sector,
        ]));
        $work_style = '';
        if (!empty($item['is_remote'])) {
            $work_style = __('Remote', 'senna-finance');
        } elseif (!empty($item['is_hybrid'])) {
            $work_style = __('Hybrid', 'senna-finance');
        } elseif ($location !== '') {
            $work_style = __('On-site', 'senna-finance');
        }
        $experience_target = $required_years !== '' ? $required_years : ($seniority !== '' ? ucfirst(str_replace('_', ' ', $seniority)) : '');
        $setup_stats = array_values(array_filter([
            [
                'label' => __('Work style', 'senna-finance'),
                'value' => $work_style,
            ],
            [
                'label' => __('Experience target', 'senna-finance'),
                'value' => $experience_target,
            ],
            [
                'label' => __('Location', 'senna-finance'),
                'value' => $location,
            ],
            [
                'label' => __('Mandate focus', 'senna-finance'),
                'value' => $sector !== '' ? $sector : $employment_type,
            ],
        ], static function ($stat) {
            return is_array($stat) && trim((string) ($stat['value'] ?? '')) !== '';
        }));
        $process_steps = [];
        foreach ($application_steps as $index => $step) {
            $step = trim((string) $step);
            if ($step === '') {
                continue;
            }

            $title = sprintf(__('Stage %d', 'senna-finance'), $index + 1);
            $detail = $step;
            if (strpos($step, ':') !== false) {
                [$raw_title, $raw_detail] = array_map('trim', explode(':', $step, 2));
                if ($raw_title !== '') {
                    $title = $raw_title;
                }
                if ($raw_detail !== '') {
                    $detail = $raw_detail;
                }
            }

            $process_steps[] = [
                'title' => $title,
                'detail' => $detail,
            ];
        }
        if (empty($process_steps)) {
            $process_steps = [
                [
                    'title' => __('Screening', 'senna-finance'),
                    'detail' => __('Expect the first pass to center on title fit, sector relevance, and visible signal quality in the CV.', 'senna-finance'),
                ],
                [
                    'title' => __('Interviews', 'senna-finance'),
                    'detail' => __('Prepare for deeper testing on the skills, experience depth, and mandate specifics highlighted in this dashboard.', 'senna-finance'),
                ],
            ];
        }
        $materials = $this->get_crm_reddit_application_pack_resources($item);

        $applications_needed = $this->estimate_cv_match_job_applications_needed($analysis, $match_score);
        $applications_needed_range = $this->format_cv_match_job_applications_needed_range($applications_needed);
        $apply_method = $this->get_cv_match_job_apply_method_label($recruiter_title);
        $apply_method_via_recruiter = stripos($apply_method, 'recruiter') !== false;
        $cv_review_score = max(0, 100 - (int) ($analysis['cv_change_intensity'] ?? 0));
        $timing_recommendation = $this->get_cv_match_job_timing_recommendation($item);

        $metric_cards = [
            [
                'slug' => 'access',
                'label' => __('Average applications needed', 'senna-finance'),
                'score' => max(0, min(100, 100 - (($applications_needed - 3) * 7))),
                'bars' => (array) (($analysis['bars']['access'] ?? [])),
                'copy' => __('Estimated tailored applications to land a similar role in this lane.', 'senna-finance'),
                'status' => $applications_needed <= 5 ? 'low' : ($applications_needed <= 9 ? 'medium' : 'high'),
                'display_value' => $applications_needed_range,
                'badge' => sprintf(__('%s avg', 'senna-finance'), $applications_needed_range),
                'badge_tone' => $applications_needed <= 5 ? 'low' : ($applications_needed <= 9 ? 'medium' : 'high'),
                'mode' => 'applications',
            ],
            [
                'slug' => 'pressure',
                'label' => __('Best method to apply', 'senna-finance'),
                'score' => $apply_method_via_recruiter ? 82 : 58,
                'bars' => (array) (($analysis['bars']['difficulty'] ?? [])),
                'copy' => $apply_method_via_recruiter
                    ? __('The public contact reads like a recruiter route, so lead through the recruiter first.', 'senna-finance')
                    : __('The named contact reads like an internal hiring lead, so apply through the company first.', 'senna-finance'),
                'status' => $apply_method_via_recruiter ? 'low' : 'medium',
                'display_value' => $apply_method,
                'badge' => $apply_method_via_recruiter ? __('Recruiter route', 'senna-finance') : __('Company route', 'senna-finance'),
                'badge_tone' => $apply_method_via_recruiter ? 'low' : 'medium',
                'mode' => 'apply_method',
            ],
            [
                'slug' => 'cv',
                'label' => __('Positioning review status', 'senna-finance'),
                'score' => $has_cv ? $cv_review_score : 0,
                'bars' => (array) (($analysis['bars']['cv'] ?? [])),
                'copy' => $has_cv
                    ? __('Your active CV is loaded for live review, tailored materials, and recruiter outreach.', 'senna-finance')
                    : __('Upload your CV to unlock live review, tailored materials, and recruiter outreach.', 'senna-finance'),
                'status' => $has_cv ? $this->get_cv_match_job_dashboard_risk_tone((int) ($analysis['cv_change_intensity'] ?? 0), true) : 'medium',
                'display_value' => $has_cv ? __('Ready', 'senna-finance') : __('Locked', 'senna-finance'),
                'badge' => $has_cv ? __('CV loaded', 'senna-finance') : __('CV required', 'senna-finance'),
                'badge_tone' => $has_cv ? 'low' : 'medium',
                'center_value' => $has_cv ? ((string) $cv_review_score . '%') : __('Locked', 'senna-finance'),
                'center_label' => $has_cv ? __('review', 'senna-finance') : __('CV first', 'senna-finance'),
                'locked' => !$has_cv,
            ],
            [
                'slug' => 'precision',
                'label' => __('Best time to apply', 'senna-finance'),
                'score' => (int) ($timing_recommendation['score'] ?? 0),
                'bars' => (array) (($analysis['bars']['specificity'] ?? [])),
                'copy' => (string) ($timing_recommendation['copy'] ?? ''),
                'status' => (string) ($timing_recommendation['status'] ?? 'medium'),
                'display_value' => (string) ($timing_recommendation['label'] ?? ''),
                'badge' => (string) ($timing_recommendation['badge'] ?? ''),
                'badge_tone' => (string) ($timing_recommendation['status'] ?? 'medium'),
                'mode' => 'timing',
            ],
        ];

        $snapshot_pills = array_values(array_filter([
            $location,
            $salary_text,
            $sector,
            $employment_type,
            $seniority,
            $posted_label,
        ]));

