    /**
     * Get the supported market post types.
     *
     * @return array<string>
     */
    private function get_market_post_types()
    {
        return ['sffc_pe_news', 'sffc_pe_deal', 'sffc_pe_signal', 'sffc_market_intel'];
    }

    /**
     * Get market post type labels.
     *
     * @return array<string, string>
     */
    private function get_market_type_labels()
    {
        return [
            'sffc_pe_news' => 'News',
            'sffc_pe_deal' => 'Deal',
            'sffc_pe_signal' => 'Signal',
            'sffc_market_intel' => 'Intel',
        ];
    }

    /**
     * Determine whether a post belongs to the Markets tab.
     *
     * @param WP_Post|int|null $post Post object or ID.
     * @return bool
     */
    private function is_market_post($post)
    {
        $post = get_post($post);
        if (!$post instanceof WP_Post) {
            return false;
        }

        return in_array($post->post_type, $this->get_market_post_types(), true);
    }

    /**
     * Build a normalized market card payload.
     *
     * @param WP_Post|int $post Post object or ID.
     * @return array<string, mixed>|null
     */
    private function build_market_article_data($post)
    {
        $post = get_post($post);
        if (!$post instanceof WP_Post || 'publish' !== $post->post_status || !$this->is_market_post($post)) {
            return null;
        }

        $type_labels = $this->get_market_type_labels();
        $post_id = (int) $post->ID;
        $content = (string) $post->post_content;
        $excerpt = has_excerpt($post) ? $post->post_excerpt : wp_trim_words(wp_strip_all_tags($content), 20, '...');
        $title = $this->get_market_article_display_title($post);

        return [
            'id' => $post_id,
            'title' => $title,
            'excerpt' => wp_trim_words($excerpt, 20, '...'),
            'url' => get_permalink($post),
            'date' => get_the_date('M j, Y', $post),
            'date_relative' => human_time_diff(get_post_time('U', true, $post), current_time('timestamp')) . ' ago',
            'featured_image' => get_the_post_thumbnail_url($post_id, 'medium'),
            'post_type' => $post->post_type,
            'type_label' => $type_labels[$post->post_type] ?? 'Article',
            'company' => get_post_meta($post_id, '_company_name', true),
            'deal_value' => get_post_meta($post_id, '_deal_value', true),
            'region' => get_post_meta($post_id, '_region', true),
            'signal_type' => get_post_meta($post_id, '_signal_type', true),
            'reading_time' => max(1, ceil(str_word_count(wp_strip_all_tags($content)) / 200)) . ' min',
        ];
    }

    private function get_market_article_display_title(WP_Post $post)
    {
        $title = trim((string) get_the_title($post));
        $original_title = trim((string) get_post_meta((int) $post->ID, '_original_title', true));

        if ($this->is_generic_market_article_title($title) && $original_title !== '') {
            return $original_title;
        }

        return $title !== '' ? $title : ($original_title !== '' ? $original_title : __('Market update', 'senna-finance'));
    }

    private function is_generic_market_article_title($title)
    {
        $title = trim((string) $title);
        if ($title === '') {
            return false;
        }

        return (bool) preg_match('/^[A-Za-z&\-\s]+ Dealmaking Shifts as Markets Evolve$/', $title);
    }

    /**
     * Query market articles with consistent pagination/filter behavior.
     *
     * @param string $filter Active filter.
     * @param int    $page   1-indexed page.
     * @param int    $per_page Page size.
     * @return array<string, mixed>
     */
    private function get_market_articles_feed($filter = 'all', $page = 1, $per_page = 12)
    {
        $page = max(1, absint($page));
        $per_page = max(1, absint($per_page));
        $allowed_post_types = $this->get_market_post_types();
        $post_types = $allowed_post_types;

        if ('all' !== $filter && in_array($filter, $allowed_post_types, true)) {
            $post_types = [$filter];
        }

        $query = new WP_Query([
            'post_type' => $post_types,
            'posts_per_page' => $per_page,
            'paged' => $page,
            'post_status' => 'publish',
            'orderby' => 'date',
            'order' => 'DESC',
            'no_found_rows' => false,
            'update_post_meta_cache' => true,
            'update_post_term_cache' => false,
        ]);

        $articles = [];

        if ($query->have_posts()) {
            while ($query->have_posts()) {
                $query->the_post();
                $article = $this->build_market_article_data(get_post());
                if ($article) {
                    $articles[] = $article;
                }
            }
            wp_reset_postdata();
        }

        return [
            'articles' => $articles,
            'has_more' => $query->max_num_pages > $page,
            'current_page' => $page,
            'total_posts' => (int) $query->found_posts,
        ];
    }

    /**
     * Query the market article types used inside CV Match Studio.
     *
     * @param int $limit Number of articles to fetch.
     * @return array<int, array<string, mixed>>
     */
    private function get_cv_match_studio_market_items($limit = 24)
    {
        $query = new WP_Query([
            'post_type' => ['sffc_pe_news', 'sffc_pe_deal', 'sffc_pe_signal'],
            'posts_per_page' => max(1, absint($limit)),
            'post_status' => 'publish',
            'orderby' => 'date',
            'order' => 'DESC',
            'no_found_rows' => true,
            'update_post_meta_cache' => true,
            'update_post_term_cache' => false,
        ]);

        $items = [];

        if ($query->have_posts()) {
            while ($query->have_posts()) {
                $query->the_post();
                $item = $this->build_market_article_data(get_post());
                if ($item && in_array((string) ($item['post_type'] ?? ''), ['sffc_pe_news', 'sffc_pe_deal', 'sffc_pe_signal'], true)) {
                    $items[] = $item;
                }
            }
            wp_reset_postdata();
        }

        return $items;
    }

    /**
     * Render the CV Match Studio markets feed.
     *
     * @return string
     */
    private function render_cv_match_studio_markets_view()
    {
        $items = $this->get_cv_match_studio_market_items(30);
        $type_counts = [
            'all' => count($items),
            'sffc_pe_news' => 0,
            'sffc_pe_deal' => 0,
            'sffc_pe_signal' => 0,
        ];

        foreach ($items as $item) {
            $post_type = (string) ($item['post_type'] ?? '');
            if (isset($type_counts[$post_type])) {
                $type_counts[$post_type]++;
            }
        }

        $filters = [
            'all' => __('All Latest News', 'senna-finance'),
            'sffc_pe_news' => __('News', 'senna-finance'),
            'sffc_pe_deal' => __('Deals', 'senna-finance'),
            'sffc_pe_signal' => __('Signals', 'senna-finance'),
        ];

        ob_start();
        ?>
        <div class="sffc-cv-match-studio__markets-shell">
            <div class="sffc-cv-match-studio__markets-layout">
                <section class="sffc-cv-match-studio__markets-feed" aria-label="<?php esc_attr_e('Market updates', 'senna-finance'); ?>">
                    <div class="sffc-cv-match-studio__markets-filterbar" role="tablist" aria-label="<?php esc_attr_e('Market filters', 'senna-finance'); ?>">
                        <?php foreach ($filters as $filter_key => $filter_label) : ?>
                            <button
                                type="button"
                                class="sffc-cv-match-studio__markets-filter<?php echo $filter_key === 'all' ? ' is-active' : ''; ?>"
                                data-cv-match-markets-filter="<?php echo esc_attr($filter_key); ?>"
                                aria-pressed="<?php echo $filter_key === 'all' ? 'true' : 'false'; ?>">
