    /**
     * Render market article cards HTML.
     *
     * @param array<int, array<string, mixed>> $articles Normalized market articles.
     * @param bool                             $feature_first Whether the first article should render as the lead story.
     * @return string
     */
    private function render_market_cards_html($articles, $feature_first = false)
    {
        if (empty($articles)) {
            return '';
        }

        ob_start();
        foreach ($articles as $index => $article) :
            $is_lead = $feature_first && 0 === (int) $index;
        ?>
            <article class="sffc-markets-card<?php echo $is_lead ? ' sffc-markets-card--lead' : ''; ?>" data-article-type="<?php echo esc_attr($article['post_type']); ?>" data-article-id="<?php echo esc_attr($article['id']); ?>">
                <div class="sffc-markets-card-content">
                    <div class="sffc-markets-card-kicker">
                        <?php if ($is_lead) : ?>
                            <span class="sffc-markets-card-lead-label"><?php esc_html_e('Latest Story', 'senna-finance'); ?></span>
                        <?php endif; ?>
                        <span class="sffc-markets-card-type sffc-markets-card-type--<?php echo esc_attr($article['post_type']); ?>"><?php echo esc_html($article['type_label']); ?></span>
                    </div>

                    <?php if ($is_lead) : ?>
                        <p class="sffc-markets-card-date-stamp"><?php echo esc_html($article['date']); ?></p>
                    <?php endif; ?>

                    <h3 class="sffc-markets-card-title">
                        <a href="<?php echo esc_url($article['url']); ?>"><?php echo esc_html($article['title']); ?></a>
                    </h3>

                    <div class="sffc-markets-card-meta">
                        <?php if (!empty($article['company'])) : ?>
                            <span class="sffc-markets-card-company"><?php echo esc_html($article['company']); ?></span>
                            <span class="sffc-markets-card-meta-dot"></span>
                        <?php endif; ?>
                        <span class="sffc-markets-card-date"><?php echo esc_html($article['date_relative']); ?></span>
                        <?php if (!empty($article['reading_time'])) : ?>
                            <span class="sffc-markets-card-meta-dot"></span>
                            <span class="sffc-markets-card-reading-time"><?php echo esc_html($article['reading_time']); ?></span>
                        <?php endif; ?>
                    </div>

                    <?php if (!empty($article['excerpt'])) : ?>
                        <p class="sffc-markets-card-excerpt"><?php echo esc_html($article['excerpt']); ?></p>
                    <?php endif; ?>

                    <?php if (!empty($article['deal_value']) || !empty($article['region']) || !empty($article['signal_type'])) : ?>
                        <div class="sffc-markets-card-tags">
                            <?php if (!empty($article['deal_value'])) : ?>
                                <span class="sffc-markets-card-tag sffc-markets-card-tag--value"><?php echo esc_html($article['deal_value']); ?></span>
                            <?php endif; ?>
                            <?php if (!empty($article['region'])) : ?>
                                <span class="sffc-markets-card-tag sffc-markets-card-tag--region"><?php echo esc_html($article['region']); ?></span>
                            <?php endif; ?>
                            <?php if (!empty($article['signal_type'])) : ?>
                                <span class="sffc-markets-card-tag sffc-markets-card-tag--signal"><?php echo esc_html($article['signal_type']); ?></span>
                            <?php endif; ?>
                        </div>
                    <?php endif; ?>
                </div>

                <footer class="sffc-markets-card-actions">
                    <button type="button" class="sffc-markets-action-btn" data-action="generate-report" data-article-id="<?php echo esc_attr($article['id']); ?>" title="<?php esc_attr_e('Generate Report', 'senna-finance'); ?>">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                            <polyline points="14 2 14 8 20 8" />
                            <line x1="16" y1="13" x2="8" y2="13" />
                            <line x1="16" y1="17" x2="8" y2="17" />
                            <polyline points="10 9 9 9 8 9" />
                        </svg>
                        <span><?php esc_html_e('Report', 'senna-finance'); ?></span>
                    </button>
                    <button type="button" class="sffc-markets-action-btn" data-action="export-data" data-article-id="<?php echo esc_attr($article['id']); ?>" title="<?php esc_attr_e('Export Data', 'senna-finance'); ?>">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                            <polyline points="7 10 12 15 17 10" />
                            <line x1="12" y1="15" x2="12" y2="3" />
                        </svg>
                        <span><?php esc_html_e('Export', 'senna-finance'); ?></span>
                    </button>
                    <button type="button" class="sffc-markets-action-btn" data-action="analyze" data-article-id="<?php echo esc_attr($article['id']); ?>" title="<?php esc_attr_e('Analyze with AI', 'senna-finance'); ?>">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
                        </svg>
                        <span><?php esc_html_e('Analyze', 'senna-finance'); ?></span>
                    </button>
                    <a href="<?php echo esc_url($article['url']); ?>" class="sffc-markets-action-btn sffc-markets-action-btn--primary">
                        <span><?php esc_html_e('Read', 'senna-finance'); ?></span>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <line x1="5" y1="12" x2="19" y2="12" />
                            <polyline points="12 5 19 12 12 19" />
                        </svg>
                    </a>
                </footer>
            </article>
        <?php
        endforeach;

        return (string) ob_get_clean();
    }

    /**
     * Main CRM shortcode with tabs
     * Usage: [sffc_crm]
     */
    public function render_crm($atts)
    {
        $atts = shortcode_atts([
            'default_tab' => 'all-roles',
        ], $atts);

        $valid_tabs = ['all-roles', 'matches', 'recruiter-intros', 'contacts', 'outreach-lists', 'pipeline', 'saved', 'dashboard', 'resume', 'inbox', 'analytics'];
        if (!empty($_GET['tab'])) {
            $requested_tab = sanitize_key(wp_unslash($_GET['tab']));
            if (in_array($requested_tab, $valid_tabs, true)) {
                $atts['default_tab'] = $requested_tab;
            }
        }

        // Get header settings
        $header_settings = get_option('sffc_crm_header_settings', []);
        $header_defaults = [
            'logo_url' => '',
            'title' => 'MENA Careers Recruiter Match CRM',
            'show_user_dropdown' => true,
            'menu_items' => [
                ['label' => 'Profile', 'url' => '/profile/', 'icon' => 'user'],
                ['label' => 'MENA Careers AI', 'url' => '/senna-ai/', 'icon' => 'cpu'],
            ],
        ];
        $header_settings = wp_parse_args($header_settings, $header_defaults);

        // Get current user info
        $current_user = wp_get_current_user();
        $user_name = $current_user->display_name;
        $default_guest_avatar = 'https://media.joinsenna.com/2026/01/sennaLogoOfficial.png?1767629924';
        $custom_avatar_key = class_exists('SFFC_User_Preferences') ? SFFC_User_Preferences::META_PROFILE_AVATAR : 'sffc_profile_avatar';

        $custom_profile_avatar = ($current_user->ID) ? get_user_meta($current_user->ID, $custom_avatar_key, true) : '';
        $gravatar_data = $current_user->ID ? get_avatar_data($current_user->ID, ['size' => 256, 'default' => '404']) : [];
        $gravatar_url = (!empty($gravatar_data['found_avatar']) && !empty($gravatar_data['url'])) ? $gravatar_data['url'] : '';
        $profile_avatar_url = $custom_profile_avatar ? $custom_profile_avatar : ($gravatar_url ? $gravatar_url : $default_guest_avatar);
        $has_profile_photo = !empty($profile_avatar_url);

        $initial_source = $current_user->first_name ?: ($user_name ?: $current_user->user_login);
        $initial_source = $initial_source ?: get_bloginfo('name');
        $avatar_initial = strtoupper(function_exists('mb_substr') ? mb_substr($initial_source, 0, 1) : substr($initial_source, 0, 1));
        if (!$avatar_initial) {
            $avatar_initial = 'G';
        }

        $user_avatar = $profile_avatar_url ?: $default_guest_avatar;
        $is_premium_member = false;
        $active_subscriptions = [];
        $subscription_urls = [];
        $memberpress = null;
        if ($current_user->ID && class_exists('SFFC_MemberPress_Integration')) {
            $memberpress = SFFC_MemberPress_Integration::get_instance();
            $is_premium_member = $memberpress->has_premium_access($current_user->ID);
            $active_subscriptions = $memberpress->get_user_subscriptions($current_user->ID);
            $subscription_urls = $memberpress->get_subscription_urls($current_user->ID);
        }
        $email_mode = get_option('sffc_crm_email_mode', 'oauth');
        if (!in_array($email_mode, ['oauth', 'mailto'], true)) {
            $email_mode = 'oauth';
        }
        $support_mailto = 'mailto:support.team@joinsenna.com';
        $plan_entries = $this->get_subscription_plans();

        $crm_membership_url = $this->get_canonical_membership_url();
        $crm_account_url = home_url('/terminal/?tab=dashboard');
        $account_password_url = $crm_account_url;
        $fallback_password_url = wp_lostpassword_url();
        $account_login_url = wp_login_url($crm_account_url);
        $account_manage_url = !empty($subscription_urls['billing_url']) ? $subscription_urls['billing_url'] : $crm_membership_url;
        $account_locale = $this->get_member_pricing_signup_locale();

        $password_reset_state = [
            'has_request' => false,
            'valid' => false,
            'error' => '',
            'login' => '',
            'key' => '',
            'display' => '',
        ];

        $reset_login_param = isset($_GET['login']) ? sanitize_user(wp_unslash($_GET['login']), true) : '';
        $reset_key_param = isset($_GET['key']) ? sanitize_text_field(wp_unslash($_GET['key'])) : '';

        if ($reset_login_param && $reset_key_param) {
            $password_reset_state['has_request'] = true;
            if (!function_exists('check_password_reset_key')) {
                require_once ABSPATH . 'wp-includes/pluggable.php';
            }
            $user_for_reset = check_password_reset_key($reset_key_param, $reset_login_param);
            if (is_wp_error($user_for_reset)) {
                $password_reset_state['error'] = $user_for_reset->get_error_message();
            } else {
                $password_reset_state['valid'] = true;
                $password_reset_state['login'] = $user_for_reset->user_login;
                $password_reset_state['key'] = $reset_key_param;
                $display_name = trim($user_for_reset->first_name . ' ' . $user_for_reset->last_name);
                if (!$display_name) {
                    $display_name = $user_for_reset->display_name ?: $user_for_reset->user_login;
                }
                $password_reset_state['display'] = $display_name;
            }
        }

        $password_reset_form_markup = '';
        if ($password_reset_state['valid']) {
            ob_start();
        ?>
            <section class="sffc-crm-account-card sffc-crm-account-password sffc-crm-account-password--inline">
                <h3><?php esc_html_e('Create your password', 'senna-finance'); ?></h3>
                <p>
                    <?php
                    printf(
                        esc_html__('You are setting a password for %s. Choose a strong password (minimum 8 characters).', 'senna-finance'),
                        esc_html($password_reset_state['display'])
                    );
                    ?>
                </p>
                <?php if (is_user_logged_in()): ?>
                    <p class="sffc-crm-account-note"><?php esc_html_e('Heads up: finishing this reset will sign you out so you can sign back in with the new password.', 'senna-finance'); ?></p>
                <?php endif; ?>
                <form id="sffc-crm-password-form" class="sffc-crm-password-form" data-login="<?php echo esc_attr($password_reset_state['login']); ?>" data-key="<?php echo esc_attr($password_reset_state['key']); ?>">
                    <div class="sffc-crm-form-group">
                        <label for="sffc-crm-password-new"><?php esc_html_e('New password', 'senna-finance'); ?></label>
                        <input type="password" id="sffc-crm-password-new" name="new_password" class="sffc-crm-input" minlength="8" required>
                    </div>
                    <div class="sffc-crm-form-group">
                        <label for="sffc-crm-password-confirm"><?php esc_html_e('Confirm new password', 'senna-finance'); ?></label>
                        <input type="password" id="sffc-crm-password-confirm" name="confirm_password" class="sffc-crm-input" minlength="8" required>
                    </div>
                    <button type="submit" class="sffc-crm-btn sffc-crm-btn-primary">
                        <?php esc_html_e('Set Password', 'senna-finance'); ?>
                    </button>
                    <div class="sffc-crm-password-feedback" style="display:none;"></div>
                </form>
            </section>
        <?php
            $password_reset_form_markup = ob_get_clean();
        }

        ob_start();
        ?>
        <div class="sffc-crm-container" data-default-tab="<?php echo esc_attr($atts['default_tab']); ?>" data-email-mode="<?php echo esc_attr($email_mode); ?>">
            <!-- Header -->
            <div class="sffc-crm-header">
                <!-- Left: Logo & Title -->
                <div class="sffc-crm-header-left">
                    <?php if (!empty($header_settings['logo_url'])): ?>
                        <a href="<?php echo esc_url(home_url('/')); ?>" class="sffc-crm-logo">
                            <img src="<?php echo esc_url($header_settings['logo_url']); ?>" alt="<?php echo esc_attr(get_bloginfo('name')); ?>">
                        </a>
                    <?php endif; ?>
                    <h1 class="sffc-crm-title">
                        <?php echo esc_html($header_settings['title']); ?>
                        <span><?php echo esc_html($this->localize_interface_copy('Private recruiter intelligence + structured outreach', 'استخبارات خاصة لجهات التوظيف + تواصل منظم', $account_locale)); ?></span>
                    </h1>
                </div>

                <!-- Right: Actions & User Dropdown -->
                <div class="sffc-crm-header-right">
                    <!-- Mobile Menu Toggle -->
                    <button class="sffc-crm-btn sffc-crm-btn-icon sffc-crm-mobile-menu-toggle" id="sffc-crm-mobile-menu-toggle" aria-label="<?php echo esc_attr($this->localize_interface_copy('Menu', 'القائمة', $account_locale)); ?>">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <line x1="3" y1="12" x2="21" y2="12"></line>
                            <line x1="3" y1="6" x2="21" y2="6"></line>
                            <line x1="3" y1="18" x2="21" y2="18"></line>
                        </svg>
                    </button>

                    <div class="sffc-crm-header-actions">
                        <button class="sffc-crm-btn sffc-crm-btn-secondary" id="sffc-crm-filter-toggle">
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
                            </svg>
                            <span class="sffc-crm-btn-text"><?php echo esc_html($this->localize_interface_copy('Filters', 'الفلاتر', $account_locale)); ?></span>
                        </button>
                        <?php if (is_user_logged_in() && $email_mode === 'oauth'): ?>
                            <button class="sffc-crm-btn sffc-crm-btn-primary sffc-crm-btn-small sffc-crm-connect-email" id="sffc-crm-connect-email">
                                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"></path>
                                    <polyline points="22,6 12,13 2,6"></polyline>
                                </svg>
                                <span><?php echo esc_html($this->localize_interface_copy('Connect Email', 'ربط البريد الإلكتروني', $account_locale)); ?></span>
                            </button>
                            <div class="sffc-crm-email-pill" id="sffc-crm-email-pill" style="display:none;"></div>
                        <?php elseif (is_user_logged_in()): ?>
                            <div class="sffc-crm-email-pill sffc-crm-email-pill--manual">
                                <?php echo esc_html($this->localize_interface_copy('Manual email mode active', 'وضع البريد اليدوي مفعل', $account_locale)); ?>
                            </div>
                        <?php endif; ?>
                    </div>

                    <?php if ($header_settings['show_user_dropdown']): ?>
                        <!-- User Dropdown -->
                        <div class="sffc-crm-user-dropdown" id="sffc-crm-user-dropdown">
                            <button class="sffc-crm-dropdown-toggle" id="sffc-crm-user-toggle" aria-expanded="false" aria-haspopup="true">
                                <img src="<?php echo esc_url($user_avatar); ?>" alt="" class="sffc-crm-user-avatar">
                                <span class="sffc-crm-user-name"><?php echo esc_html($user_name); ?></span>
                                <svg class="sffc-crm-dropdown-arrow" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
