    private function transform_cv_match_job_namespace($markup)
    {
        $markup = (string) $markup;
        if ($markup === '') {
            return '';
        }

        return strtr($markup, [
            'sffc-cv-match-studio__' => 'sffc-cv-match-job__',
            'sffc-cv-match-studio--' => 'sffc-cv-match-job--',
            'sffc-cv-match-studio' => 'sffc-cv-match-job',
        ]);
    }

    private function render_cv_match_single_job_dashboard(array $item, array $analysis, array $context = [])
    {
        $markup = $this->render_cv_match_job_dashboard($item, $analysis, $context);
        $extra_sections = $this->render_cv_match_single_job_extra_sections($item, $analysis, $context);

        if ($extra_sections !== '') {
            $closing_tag = '</section>';
            $position = strrpos($markup, $closing_tag);
            if ($position !== false) {
                $markup = substr_replace($markup, $extra_sections . $closing_tag, $position, strlen($closing_tag));
            } else {
                $markup .= $extra_sections;
            }
        }

        return $this->transform_cv_match_job_namespace($markup);
    }

    private function render_cv_match_single_job_extra_sections(array $item, array $analysis, array $context = [])
    {
        $cv_text = trim((string) ($context['cv_text'] ?? ''));
        $has_cv = !empty($context['has_cv']) || $cv_text !== '';
        $ai_overview = $this->get_crm_reddit_single_job_ai_overview($item, $analysis);
        $profile_comparison = $this->get_crm_reddit_single_job_profile_comparison($item, $analysis, $cv_text);
        $salary_trajectory = $this->get_crm_reddit_single_job_salary_trajectory($item);

        $overview_sections = array_values(array_filter((array) ($ai_overview['sections'] ?? []), 'is_array'));
        $overview_skills = array_values(array_filter(array_map('strval', (array) ($ai_overview['key_skills'] ?? []))));
        $overview_backgrounds = array_values(array_filter(array_map('strval', (array) ($ai_overview['backgrounds'] ?? []))));
        $overview_qualifications = array_values(array_filter(array_map('strval', (array) ($ai_overview['qualifications'] ?? []))));
        $overview_required_years = trim((string) ($ai_overview['required_years'] ?? ''));

        $comparison_paragraphs = array_values(array_filter(array_map('strval', (array) ($profile_comparison['paragraphs'] ?? []))));
        $comparison_highlights = array_values(array_filter(array_map('strval', (array) ($profile_comparison['highlights'] ?? []))));
        $matched_signals = array_values(array_filter(array_map('strval', (array) ($profile_comparison['matched_signals'] ?? []))));
        $missing_signals = array_values(array_filter(array_map('strval', (array) ($profile_comparison['missing_signals'] ?? []))));
        $cv_fix_points = array_values(array_filter(array_map('strval', (array) ($profile_comparison['cv_fix_points'] ?? []))));
        $keyword_swaps = array_values(array_filter((array) ($profile_comparison['keyword_swaps'] ?? []), 'is_array'));

        $salary_stages = array_values(array_filter((array) ($salary_trajectory['stages'] ?? []), 'is_array'));
        $salary_insights = array_values(array_filter(array_map('strval', (array) ($salary_trajectory['insights'] ?? []))));
        $salary_currency = (string) ($salary_trajectory['currency_code'] ?? 'AED');
        $salary_average = $this->format_crm_reddit_single_job_compact_salary((int) ($salary_trajectory['average_salary'] ?? 0), $salary_currency);
        $salary_median = $this->format_crm_reddit_single_job_compact_salary((int) ($salary_trajectory['median_salary'] ?? 0), $salary_currency);
        $salary_tax = trim((string) ($salary_trajectory['tax_rate'] ?? '0%'));
        $salary_max = 0;
        foreach ($salary_stages as $stage) {
            $salary_max = max($salary_max, (int) ($stage['annual_salary'] ?? 0));
        }

        $comparison_terms = [
            'is-match' => $matched_signals,
            'is-gap' => $missing_signals,
            'is-highlight' => $comparison_highlights,
            'is-skill' => $overview_skills,
        ];

        $description_html = trim((string) ($item['description_html'] ?? ''));
        if ($description_html === '' && !empty($item['excerpt'])) {
            $description_html = wpautop(esc_html((string) $item['excerpt']));
        }

        ob_start();
        ?>
        <div class="sffc-cv-match-studio__job-dashboard-grid sffc-cv-match-studio__job-dashboard-grid--overview">
            <article class="sffc-cv-match-studio__job-card sffc-cv-match-studio__job-card--wide">
                <div class="sffc-cv-match-studio__job-card-head">
                    <span><?php esc_html_e('AI overview', 'senna-finance'); ?></span>
                    <strong><?php esc_html_e('Role summary & candidate preference', 'senna-finance'); ?></strong>
                </div>
                <div class="sffc-cv-match-studio__job-overview-copy">
                    <?php if (!empty($ai_overview['job_summary'])) : ?>
                        <p><?php echo esc_html((string) $ai_overview['job_summary']); ?></p>
                    <?php endif; ?>
                    <?php if (!empty($ai_overview['candidate_preference'])) : ?>
                        <p class="is-muted"><?php echo esc_html((string) $ai_overview['candidate_preference']); ?></p>
                    <?php endif; ?>
                </div>
                <div class="sffc-cv-match-studio__job-fact-grid">
                    <?php if (!empty($overview_skills)) : ?>
                        <div class="sffc-cv-match-studio__job-fact">
                            <span><?php esc_html_e('Key skills', 'senna-finance'); ?></span>
                            <strong><?php echo esc_html(implode(', ', array_slice($overview_skills, 0, 3))); ?></strong>
                        </div>
                    <?php endif; ?>
                    <?php if (!empty($overview_backgrounds)) : ?>
                        <div class="sffc-cv-match-studio__job-fact">
                            <span><?php esc_html_e('Preferred backgrounds', 'senna-finance'); ?></span>
                            <strong><?php echo esc_html(implode(', ', array_slice($overview_backgrounds, 0, 2))); ?></strong>
                        </div>
                    <?php endif; ?>
                    <?php if (!empty($overview_qualifications)) : ?>
                        <div class="sffc-cv-match-studio__job-fact">
                            <span><?php esc_html_e('Qualification signals', 'senna-finance'); ?></span>
                            <strong><?php echo esc_html(implode(', ', array_slice($overview_qualifications, 0, 2))); ?></strong>
                        </div>
                    <?php endif; ?>
                    <?php if ($overview_required_years !== '') : ?>
                        <div class="sffc-cv-match-studio__job-fact">
                            <span><?php esc_html_e('Experience target', 'senna-finance'); ?></span>
                            <strong><?php echo esc_html($overview_required_years); ?></strong>
                        </div>
                    <?php endif; ?>
                </div>
                <?php if (!empty($overview_sections)) : ?>
                    <div class="sffc-cv-match-studio__job-insight-list">
                        <?php foreach (array_slice($overview_sections, 0, 3) as $section) : ?>
                            <?php if (empty($section['answer'])) { continue; } ?>
                            <p><?php echo esc_html((string) $section['answer']); ?></p>
                        <?php endforeach; ?>
                    </div>
