    private function get_cv_match_job_namespace_css()
    {
        static $css = null;

        if ($css !== null) {
            return $css;
        }

        $css_path = SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css';
        if (!file_exists($css_path) || !is_readable($css_path)) {
            $css = '';
            return $css;
        }

        $source = (string) file_get_contents($css_path);
        if ($source === '') {
            $css = '';
            return $css;
        }

        $css = strtr($source, [
            'sffc-cv-match-studio__' => 'sffc-cv-match-job__',
            'sffc-cv-match-studio--' => 'sffc-cv-match-job--',
            'sffc-cv-match-studio' => 'sffc-cv-match-job',
        ]);

        $css .= <<<'CSS'

.sffc-cv-match-job--single-job .sffc-cv-match-job__main {
  padding-bottom: 176px;
}

.sffc-cv-match-job__job-dock {
  position: fixed;
  left: var(--cv-match-job-dock-left, 50vw);
  transform: translateX(-50%);
  bottom: 20px;
  z-index: 28;
  width: var(--cv-match-job-dock-width, min(1120px, calc(100vw - 72px)));
  pointer-events: none;
}

.sffc-cv-match-job__job-dock-shell,
.sffc-cv-match-job__job-dock-field {
  pointer-events: none;
}

.sffc-cv-match-job__job-dock-shell {
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}

.sffc-cv-match-job__job-dock-field {
  position: static;
  width: 100%;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}

.sffc-cv-match-job__job-dock-input {
 
    position: relative;
    display: block;
    width: 100%;
    min-height: 108px;
    max-height: none;
    padding: 18px 20px 54px;
    border-radius: 8px;
    background: #0d353e00;
    border: 1px solid rgba(23, 59, 93, 0.1);
    box-shadow: 0 18px 42px rgba(19, 33, 57, 0.12);
    backdrop-filter: blur(16px);
    pointer-events: auto;
}

.sffc-cv-match-job__job-dock-textarea {
  display: block;
  width: 100%;
  min-height: 34px;
  max-height: 72px;
  border: 0;
  background: transparent;
  color: var(--cv-match-ink);
  font-size: 14px;
  line-height: 1.5;
  padding: 0;
  resize: none;
  outline: none;
  box-shadow: none;
  font-family: Tahoma, Arial, sans-serif;
}

.sffc-cv-match-job__job-dock-textarea::placeholder {
  color: rgba(23, 59, 93, 0.56);
}

.sffc-cv-match-job__job-dock-bar {
  position: absolute;
  left: 20px;
  right: 20px;
  bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 34px;
  pointer-events: auto;
  padding-top: 10px;
  border-top: 1px solid rgba(23, 59, 93, 0.08);
}

.sffc-cv-match-job__job-dock-tools {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.sffc-cv-match-job__tool-button {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(23, 59, 93, 0.08);
  box-shadow: 0 8px 18px rgba(19, 33, 57, 0.07);
}

.sffc-cv-match-job__tool-hint {
  color: rgba(23, 59, 93, 0.58);
  font-size: 12px;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sffc-cv-match-job__job-dock-submit {
  min-width: 118px;
  min-height: 38px;
  border-radius: 14px;
}

@media (max-width: 780px) {
  .sffc-cv-match-job--single-job .sffc-cv-match-job__main {
    padding-bottom: calc(env(safe-area-inset-bottom) + 150px);
  }

  .sffc-cv-match-job__job-dock {
    left: 50vw;
    bottom: calc(env(safe-area-inset-bottom) + 10px);
    width: calc(100vw - 24px);
  }

  .sffc-cv-match-job__job-dock-input {
    min-height: 104px;
    padding: 14px 14px 50px;
    border-radius: 18px;
  }

  .sffc-cv-match-job__job-dock-textarea {
    min-height: 32px;
    max-height: 62px;
    font-size: 13px;
  }

  .sffc-cv-match-job__job-dock-bar {
    left: 14px;
    right: 14px;
    bottom: 10px;
    gap: 10px;
    padding-top: 8px;
  }

  .sffc-cv-match-job__tool-hint {
    font-size: 11px;
  }

  .sffc-cv-match-job__job-dock-submit {
    min-width: 102px;
    min-height: 36px;
  }
}
CSS;

        return $css;
    }

