        /**
         * Render feed content
         */
        private function render_feed_content()
        {
            $post_model = new SFFC_CRM_Post();
            $user_id = get_current_user_id();

            if ($user_id > 0 && function_exists('sffc_crm_user_is_excluded') && sffc_crm_user_is_excluded($user_id)) {
                ob_start();
            ?>
                <div class="sffc-crm-empty">
                    <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                        <circle cx="12" cy="12" r="10"></circle>
                        <line x1="12" y1="8" x2="12" y2="12"></line>
                        <line x1="12" y1="16" x2="12.01" y2="16"></line>
                    </svg>
                    <h3><?php esc_html_e('Feed unavailable', 'senna-finance'); ?></h3>
                    <p><?php esc_html_e('This account has been excluded from CRM feeds and alerts.', 'senna-finance'); ?></p>
                </div>
            <?php
                return ob_get_clean();
            }

            // Check if user has premium membership
            $is_premium = false;
            if (class_exists('SFFC_MemberPress_Integration')) {
                $mepr = SFFC_MemberPress_Integration::get_instance();
                $is_premium = $mepr->has_premium_access($user_id);
            }

            $posts = $post_model->get_feed([
                'page' => 1,
                'per_page' => 20,
                'user_id' => $user_id,
            ]);

            $preview_limit = 2;
            ob_start();
            ?>
            <div class="sffc-crm-feed-list" id="crm-feed-grid" data-is-premium="<?php echo $is_premium ? 'true' : 'false'; ?>">
                <?php if (empty($posts)): ?>
                    <div class="sffc-crm-empty">
                        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                            <circle cx="12" cy="12" r="10"></circle>
                            <line x1="12" y1="8" x2="12" y2="12"></line>
                            <line x1="12" y1="16" x2="12.01" y2="16"></line>
                        </svg>
                        <h3>No posts yet</h3>
                        <p>Check back soon for recruiter opportunities.</p>
                    </div>
                <?php else: ?>
                    <?php foreach ($posts as $post): ?>
                        <?php echo $this->render_post_row($post, $is_premium); ?>
                    <?php endforeach; ?>
                <?php endif; ?>
            </div>

            <div class="sffc-crm-load-more" id="crm-load-more" style="<?php echo count($posts) < 20 ? 'display:none;' : ''; ?>">
                <button class="sffc-crm-btn sffc-crm-btn-secondary" data-page="1">Load More</button>
            </div>
        <?php
            return ob_get_clean();
        }

        /**
         * Render single post row (list format)
         */
        private function render_post_row($post, $is_premium = false)
        {
            $is_saved = !empty($post['is_saved']);
            $posted_ago = human_time_diff(strtotime($post['posted_at'])) . ' ago';
            $can_reach_out = $is_premium && is_user_logged_in();

            $public_name = $post['recruiter_name'] ?? 'Unknown Recruiter';
            $public_firm = $post['recruiter_firm'] ?? '';
            if (!$is_premium) {
                if (!empty($post['recruiter_display_name'])) {
                    $public_name = $post['recruiter_display_name'];
                }
                if (!empty($post['recruiter_display_company'])) {
                    $public_firm = $post['recruiter_display_company'];
                }
            }

            $reach_out_classes = 'sffc-crm-btn sffc-crm-btn-primary sffc-crm-btn-small sffc-crm-reach-out-btn';
            $reach_out_attrs = ' data-action="reach-out" data-post-id="' . esc_attr($post['id']) . '" data-recruiter-id="' . esc_attr($post['recruiter_id']) . '"';
            $reach_out_title = 'Reach out to this recruiter';

            if (!$can_reach_out) {
                $reach_out_classes .= ' is-locked';
                $reach_out_attrs .= ' data-requires-membership="true"';
                $reach_out_title = 'Join MENA Careers to unlock Reach Out';
            }

            ob_start();
        ?>
            <?php $inline_recruiter_data = [
                'id' => (int) $post['recruiter_id'],
                'name' => $public_name,
                'email' => $post['recruiter_email'] ?? '',
                'company' => $public_firm,
            ]; ?>
            <div class="sffc-crm-post-row" data-post-id="<?php echo esc_attr($post['id']); ?>" data-recruiter='<?php echo esc_attr(json_encode($inline_recruiter_data)); ?>'>
                <div class="sffc-crm-row-select">
                    <input type="checkbox"
                        class="sffc-crm-bulk-select-checkbox"
                        data-recruiter-id="<?php echo esc_attr($post['recruiter_id']); ?>"
                        data-name="<?php echo esc_attr($public_name); ?>"
                        data-email="<?php echo esc_attr($post['recruiter_email']); ?>"
                        data-company="<?php echo esc_attr($public_firm); ?>"
                        title="Select recruiter">
                </div>
                <!-- Recruiter Avatar -->
                <div class="sffc-crm-row-avatar<?php echo $is_premium ? '' : ' is-blurred'; ?>">
                    <?php if (!empty($post['recruiter_photo'])): ?>
                        <img src="<?php echo esc_url($post['recruiter_photo']); ?>" alt="" class="sffc-crm-avatar">
                    <?php else: ?>
                        <div class="sffc-crm-avatar sffc-crm-avatar-placeholder">
                            <?php echo esc_html(substr($public_name ?: 'R', 0, 1)); ?>
                        </div>
                    <?php endif; ?>
                </div>

                <!-- Main Content -->
                <div class="sffc-crm-row-content">
                    <?php $post_url = SFFC_CRM_Post_Type::get_post_url($post['id']); ?>
                    <div class="sffc-crm-row-header">
                        <h3 class="sffc-crm-row-title">
                            <a href="<?php echo esc_url($post_url); ?>" class="sffc-crm-post-link"><?php echo esc_html($post['role_title']); ?></a>
                        </h3>
                        <span class="sffc-crm-row-time"><?php echo esc_html($posted_ago); ?></span>
                    </div>
                    <div class="sffc-crm-row-meta">
                        <span class="sffc-crm-row-recruiter">
                            <?php echo esc_html($public_name); ?>
                            <?php if (!empty($public_firm)): ?>
                                <span class="sffc-crm-row-firm">at <?php echo esc_html($public_firm); ?></span>
                            <?php endif; ?>
                        </span>
                        <?php if (!empty($post['company'])): ?>
                            <span class="sffc-crm-row-sep">•</span>
                            <span class="sffc-crm-row-company"><?php echo esc_html($post['company']); ?></span>
                        <?php endif; ?>
                    </div>
                    <div class="sffc-crm-row-tags">
                        <?php if (!empty($post['location'])): ?>
                            <span class="sffc-crm-tag sffc-crm-tag-location">
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path>
                                    <circle cx="12" cy="10" r="3"></circle>
                                </svg>
                                <?php echo esc_html($post['location']); ?>
                            </span>
                        <?php endif; ?>
                        <?php if (!empty($post['salary_text'])): ?>
                            <span class="sffc-crm-tag"><?php echo esc_html($post['salary_text']); ?></span>
                        <?php endif; ?>
                        <?php if (!empty($post['seniority'])): ?>
                            <span class="sffc-crm-tag sffc-crm-tag-seniority"><?php echo esc_html(strtoupper($post['seniority'])); ?></span>
                        <?php endif; ?>
                        <?php if (!empty($post['is_remote'])): ?>
                            <span class="sffc-crm-tag sffc-crm-tag-remote">Remote</span>
                        <?php endif; ?>
                    </div>
                </div>

                <!-- Actions -->
                <div class="sffc-crm-row-actions">
                    <button class="sffc-crm-btn sffc-crm-btn-icon sffc-crm-save-btn <?php echo $is_saved ? 'is-saved' : ''; ?>"
                        data-action="save"
                        data-post-id="<?php echo esc_attr($post['id']); ?>"
