        <?php
            return ob_get_clean();
        }

        /**
         * Render single post card (legacy - kept for backwards compatibility)
         */
        private function render_post_card($post, $is_premium = false)
        {
            $is_saved = !empty($post['is_saved']);
            $posted_ago = human_time_diff(strtotime($post['posted_at'])) . ' ago';
            $post_url = SFFC_CRM_Post_Type::get_post_url($post['id']);
            $can_reach_out = $is_premium && is_user_logged_in();

            $reach_out_classes = 'sffc-crm-btn sffc-crm-btn-primary sffc-crm-reach-out-btn';
            $reach_out_attrs = ' data-action="reach-out" data-post-id="' . esc_attr($post['id']) . '" data-recruiter-id="' . esc_attr($post['recruiter_id']) . '"';
            $reach_out_title = 'Reach out to this recruiter';

            if (!$can_reach_out) {
                $reach_out_classes .= ' is-locked';
                $reach_out_attrs .= ' data-requires-membership="true"';
                $reach_out_title = 'Join MENA Careers to unlock Reach Out';
            }

            ob_start();
        ?>
            <div class="sffc-crm-post-card" data-post-id="<?php echo esc_attr($post['id']); ?>">
                <!-- Recruiter Header -->
                <div class="sffc-crm-post-recruiter">
                    <?php if (!empty($post['recruiter_photo'])): ?>
                        <img src="<?php echo esc_url($post['recruiter_photo']); ?>" alt="" class="sffc-crm-avatar">
                    <?php else: ?>
                        <div class="sffc-crm-avatar sffc-crm-avatar-placeholder">
                            <?php echo esc_html(substr($post['recruiter_name'] ?? 'R', 0, 1)); ?>
                        </div>
                    <?php endif; ?>
                    <div class="sffc-crm-recruiter-info">
                        <span class="sffc-crm-recruiter-name"><?php echo esc_html($post['recruiter_name'] ?? 'Unknown Recruiter'); ?></span>
                        <span class="sffc-crm-recruiter-firm"><?php echo esc_html($post['recruiter_firm'] ?? ''); ?></span>
                    </div>
                    <span class="sffc-crm-post-time"><?php echo esc_html($posted_ago); ?></span>
                </div>

                <!-- Role Info -->
                <div class="sffc-crm-post-role">
                    <h3 class="sffc-crm-post-title">
                        <a href="<?php echo esc_url($post_url); ?>" class="sffc-crm-post-link"><?php echo esc_html($post['role_title']); ?></a>
                    </h3>
                    <?php if (!empty($post['company'])): ?>
                        <span class="sffc-crm-post-company"><?php echo esc_html($post['company']); ?></span>
                    <?php endif; ?>
                </div>

                <!-- Meta Tags -->
                <div class="sffc-crm-post-meta">
                    <?php if (!empty($post['location'])): ?>
                        <span class="sffc-crm-tag">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path>
                                <circle cx="12" cy="10" r="3"></circle>
                            </svg>
                            <?php echo esc_html($post['location']); ?>
                        </span>
                    <?php endif; ?>

                    <?php if (!empty($post['salary_text'])): ?>
                        <span class="sffc-crm-tag">
                            <?php echo esc_html($post['salary_text']); ?>
                        </span>
                    <?php endif; ?>

                    <?php if (!empty($post['seniority'])): ?>
                        <span class="sffc-crm-tag sffc-crm-tag-seniority">
                            <?php echo esc_html(strtoupper($post['seniority'])); ?>
                        </span>
                    <?php endif; ?>

                    <?php if (!empty($post['is_remote'])): ?>
                        <span class="sffc-crm-tag sffc-crm-tag-remote">Remote</span>
                    <?php endif; ?>
                </div>

                <!-- Snippet -->
                <?php if (!empty($post['content_snippet'])): ?>
                    <p class="sffc-crm-post-snippet"><?php echo esc_html($post['content_snippet']); ?></p>
                <?php endif; ?>

                <!-- Actions -->
                <div class="sffc-crm-post-actions">
                    <button class="sffc-crm-btn sffc-crm-btn-icon sffc-crm-save-btn <?php echo $is_saved ? 'is-saved' : ''; ?>"
                        data-action="save"
                        data-post-id="<?php echo esc_attr($post['id']); ?>"
                        title="<?php echo $is_saved ? 'Saved' : 'Save'; ?>">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="<?php echo $is_saved ? 'currentColor' : 'none'; ?>" stroke="currentColor" stroke-width="2">
                            <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"></path>
                        </svg>
                    </button>
                    <a href="<?php echo esc_url($post_url); ?>" class="sffc-crm-btn sffc-crm-btn-outline">
                        View Details
                    </a>
                    <button type="button"
                        class="<?php echo esc_attr($reach_out_classes); ?>"
                        title="<?php echo esc_attr($reach_out_title); ?>" <?php echo $reach_out_attrs; ?>>
                        Reach Out
                    </button>
                </div>
            </div>
        <?php
            return ob_get_clean();
        }

        /**
         * Render feed shortcode (standalone)
         */
        public function render_feed($atts)
        {
            $atts = shortcode_atts([
                'per_page' => 20,
                'sector' => '',
                'seniority' => '',
            ], $atts);

            if (!is_user_logged_in()) {
                return $this->render_login_prompt();
            }

            ob_start();
        ?>
            <div class="sffc-crm-container sffc-crm-feed-only">
                <?php echo $this->render_feed_content(); ?>
            </div>
        <?php
            return ob_get_clean();
        }

        public function render_crm_reddit_feed($atts)
        {
            $atts = shortcode_atts([
                'jobs_post_id' => 0,
                'per_page' => 8,
                'title' => 'r/MENA Careers',
                'subtitle' => 'Roles from the jobs post type first, then recruiter-led opportunities from MENA Careers CRM.',
                'active_tab' => 'careers',
            ], $atts, 'sffc_crm_reddit_feed');

            wp_enqueue_style(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                SFFC_VERSION,
                true
            );
            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                SFFC_VERSION,
                true
            );
            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                SFFC_VERSION,
                true
            );

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            $per_page = max(1, min(18, absint($atts['per_page'])));
            $post_model = new SFFC_CRM_Post();
            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $search_term = sanitize_text_field((string) wp_unslash($_GET['sffc_reddit_search'] ?? ''));
            $selected_group = sanitize_title((string) wp_unslash($_GET['reddit_group'] ?? ''));

            wp_localize_script('sffc-crm-reddit-feed', 'sffcCrmRedditFeed', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_reddit_group_nav'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'uploadNonce' => wp_create_nonce('sffc_cv_upload'),
                'applyNonce' => wp_create_nonce('sffc_crm_reddit_apply'),
                'gapPayloadNonce' => wp_create_nonce('sffc_crm_reddit_gap_payload'),
                'networkingNonce' => wp_create_nonce('sffc_crm_reddit_networking_strategy'),
                'materialNonce' => wp_create_nonce('sffc_crm_reddit_material_generate'),
                'loadMoreNonce' => wp_create_nonce('sffc_crm_reddit_load_more'),
                'isLoggedIn' => $is_logged_in,
                'storageKey' => 'sffc_crm_reddit_group_nav_prefs',
                'membershipUrl' => $this->get_crm_reddit_membership_url(),
                'pipelineStages' => class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [],
                'currentUser' => [
                    'email' => $is_logged_in ? (string) wp_get_current_user()->user_email : '',
                ],
            ]);

            $feed_page_data = $this->get_crm_reddit_feed_page_data($jobs_post_id, $per_page, $user_id, $selected_group, $search_term);
            $pinned_item = !empty($feed_page_data['pinned_item']) ? $feed_page_data['pinned_item'] : [];
            $feed_items = (array) ($feed_page_data['items'] ?? []);
            $has_more_feed_items = !empty($feed_page_data['has_more']);

            $search_suggestions = $this->build_crm_reddit_search_suggestions($feed_items, $search_term);

            $stories = $this->build_crm_reddit_company_stories($feed_items);

            $current_url = get_permalink(get_queried_object_id());
            if (!$current_url) {
                $current_url = '#';
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $group_preferences = $this->get_crm_reddit_group_nav_preferences($user_id);
            $nav_groups = $this->build_crm_reddit_nav_groups(
                $group_model->get_all([
                    'is_active' => 1,
                    'order_by' => 'display_order',
                    'order' => 'ASC',
                    'include_post_count' => true,
                ]),
                $group_preferences,
                $selected_group,
                $current_url,
                $search_term
            );

            $active_group_context = $this->get_crm_reddit_active_group_context($selected_group, $nav_groups, (string) $atts['subtitle']);
            $recruiter_role_count = (int) ($feed_page_data['total_crm_count'] ?? 0);
            $sidebar_recruiters = $this->build_crm_reddit_recruiter_sidebar($feed_items);
            $is_senna_community_view = $selected_group === '';
            $community_resume_context = ['cv_text' => '', 'has_cv' => false, 'source' => ''];
            if ($is_senna_community_view && $is_logged_in) {
                $community_resume_context = $this->get_crm_reddit_active_resume_text($user_id);
            }
            $community_requires_cv = $is_senna_community_view && $is_logged_in && empty($community_resume_context['has_cv']);
            $community_dashboard = $is_senna_community_view
                ? $this->build_crm_reddit_community_dashboard_data($feed_items, $sidebar_recruiters)
                : [];
            $loaded_crm_ids = array_values(array_filter(array_map(static function ($feed_item) {
                return ($feed_item['source'] ?? '') === 'crm' ? (int) ($feed_item['crm_post_id'] ?? 0) : 0;
            }, $feed_items)));
            $account_user = [];
            $account_shell_markup = '';

            if ($is_logged_in) {
                try {
                    $account_user = $this->get_crm_reddit_account_user($user_id);
                    if (!empty($account_user)) {
                        $account_shell_markup = $this->render_crm_reddit_account_shell($user_id, $account_user, $nav_groups);
                    }
                } catch (\Throwable $throwable) {
                    error_log('SFFC Reddit Feed account shell error: ' . $throwable->getMessage());
                    $account_user = [];
                    $account_shell_markup = '';
                }
            }

            ob_start();
        ?>
            <section class="sffc-crm-reddit-shell<?php echo $is_senna_community_view ? ' sffc-crm-reddit-shell--community-mailbox' : ''; ?>">
                <header class="sffc-crm-reddit-topbar">
                    <a class="sffc-crm-reddit-brand" href="<?php echo esc_url(home_url('/')); ?>">senna</a>
                    <form class="sffc-crm-reddit-search" action="<?php echo esc_url($current_url); ?>" method="get" role="search" aria-label="<?php esc_attr_e('Search feed', 'senna-finance'); ?>">
                        <label class="screen-reader-text" for="sffc-crm-reddit-search-input"><?php esc_html_e('Search careers, firms, mentors', 'senna-finance'); ?></label>
                        <span class="sffc-crm-reddit-search-badge"><?php echo esc_html($atts['title']); ?></span>
                        <div class="sffc-crm-reddit-search-field" data-reddit-search-field>
                            <input
                                id="sffc-crm-reddit-search-input"
                                class="sffc-crm-reddit-search-input"
                                type="search"
                                name="sffc_reddit_search"
                                value="<?php echo esc_attr($search_term); ?>"
                                placeholder="<?php esc_attr_e('Search careers, firms, mentors', 'senna-finance'); ?>"
                                autocomplete="off"
                                data-reddit-search-input
                                aria-autocomplete="list"
                                aria-expanded="false"
                                aria-controls="sffc-crm-reddit-search-dropdown">
                            <?php if (!empty($search_suggestions)) : ?>
                                <div class="sffc-crm-reddit-search-dropdown" id="sffc-crm-reddit-search-dropdown" data-reddit-search-dropdown hidden>
                                    <?php foreach ($search_suggestions as $suggestion) : ?>
                                        <button
                                            class="sffc-crm-reddit-search-option"
                                            type="button"
                                            data-suggestion-value="<?php echo esc_attr((string) $suggestion['value']); ?>"
                                            data-suggestion-type="<?php echo esc_attr((string) $suggestion['type']); ?>">
                                            <?php if (!empty($suggestion['image'])) : ?>
                                                <span class="sffc-crm-reddit-search-option-media">
                                                    <img
                                                        src="<?php echo esc_url((string) $suggestion['image']); ?>"
                                                        alt="<?php echo esc_attr((string) ($suggestion['image_label'] ?? $suggestion['value'] ?? '')); ?>"
