        public function render_crm_reddit_dashboard($atts)
        {
            $atts = shortcode_atts([
                'jobs_post_id' => 0,
                'per_page' => 18,
                'fallback_role' => 'Investment Associate',
                'title' => __('Recommended leads tailored just for you', 'senna-finance'),
                'current_url' => '',
            ], $atts, 'sffc_crm_reddit_dashboard');

            wp_enqueue_style(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css',
                [],
                SFFC_VERSION
            );
            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                SFFC_VERSION,
                true
            );

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            $per_page = max(12, min(36, absint($atts['per_page'])));
            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $public_profile_slug = sanitize_title((string) ($_GET['profile'] ?? ''));
            $public_profile_user_id = $public_profile_slug !== '' ? $this->get_crm_reddit_user_id_by_public_profile_slug($public_profile_slug) : 0;
            $has_dashboard_membership_access = $is_logged_in && $this->current_user_has_crm_reddit_premium_access();
            $dashboard_upgrade_url = $this->get_canonical_membership_url();
            $dashboard_tab = sanitize_key((string) ($_GET['dashboard_tab'] ?? 'recruiter-matches'));
            if (!in_array($dashboard_tab, ['my-profile', 'expert-support', 'home', 'recruiter-matches', 'tracking', 'review-cv', 'recruiter-outreach'], true)) {
                $dashboard_tab = 'recruiter-matches';
            }
            if ($public_profile_slug !== '') {
                $dashboard_tab = 'my-profile';
            }
            $matches_filter = sanitize_key((string) ($_GET['matches_filter'] ?? 'highest-match'));
            if (!in_array($matches_filter, ['live-feed', 'recently-posted', 'highest-match'], true)) {
                $matches_filter = 'highest-match';
            }
            $metrics_window = sanitize_key((string) ($_GET['metrics_window'] ?? 'month'));
            if (!in_array($metrics_window, ['week', 'two-weeks', 'month'], true)) {
                $metrics_window = 'month';
            }
            $matches_page = max(1, absint($_GET['matches_page'] ?? 1));
            $search_term = sanitize_text_field((string) ($_GET['sffc_reddit_search'] ?? ''));
            $fallback_role = sanitize_text_field((string) $atts['fallback_role']);
            if ($fallback_role === '') {
                $fallback_role = 'Investment Associate';
            }
            $needs_resume_payload = $is_logged_in && in_array($dashboard_tab, ['home', 'recruiter-matches', 'tracking', 'review-cv', 'recruiter-outreach'], true);
            $resume_payload = $needs_resume_payload
                ? $this->get_crm_reddit_active_resume_text($user_id)
                : ['cv_text' => '', 'has_cv' => false];
            wp_localize_script('sffc-crm-reddit-feed', 'sffcCrmRedditFeed', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_reddit_group_nav'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'uploadNonce' => wp_create_nonce('sffc_cv_upload'),
                'applyNonce' => wp_create_nonce('sffc_crm_reddit_apply'),
                'gapPayloadNonce' => wp_create_nonce('sffc_crm_reddit_gap_payload'),
                'networkingNonce' => wp_create_nonce('sffc_crm_reddit_networking_strategy'),
                'outreachNonce' => wp_create_nonce('sffc_crm_reddit_generate_outreach'),
                'materialNonce' => wp_create_nonce('sffc_crm_reddit_material_generate'),
                'loadMoreNonce' => wp_create_nonce('sffc_crm_reddit_load_more'),
                'dashboardTabNonce' => wp_create_nonce('sffc_crm_reddit_dashboard_tab'),
                'avatarNonce' => wp_create_nonce('sffc_crm_avatar_nonce'),
                'isLoggedIn' => $is_logged_in,
                'membershipUrl' => $this->get_crm_reddit_membership_url(),
                'pipelineStages' => class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [],
                'currentUser' => [
                    'email' => $is_logged_in ? (string) wp_get_current_user()->user_email : '',
                ],
            ]);

            $feed_items = [];
            $dashboard_metrics_items = [];
            $dashboard_data = [
                'insights' => [],
                'cards' => [],
                'total_roles' => 0,
            ];

            if ($dashboard_tab === 'recruiter-matches') {
                $feed_page_data = null;
                $feed_cache_key = '';
                if ($search_term === '') {
                    $feed_cache_key = 'sffc_crm_dash_feed_' . md5((int) $jobs_post_id . '|' . (int) $per_page . '|' . (int) $user_id . '|' . (string) $dashboard_tab);
                    $feed_page_data = get_transient($feed_cache_key);
                }
                if (!is_array($feed_page_data)) {
                    $feed_page_data = $this->get_crm_reddit_dashboard_feed_page_data($jobs_post_id, $per_page, $user_id, $search_term);
                    if ($feed_cache_key !== '') {
                        set_transient($feed_cache_key, $feed_page_data, 5 * MINUTE_IN_SECONDS);
                    }
                }
                $feed_items = (array) ($feed_page_data['items'] ?? []);
                $dashboard_metrics_items = $this->get_crm_reddit_dashboard_metrics_source_items($jobs_post_id, $user_id, $search_term);
            }

            $current_url = esc_url_raw((string) $atts['current_url']);
            if ($current_url === '') {
                $current_url = get_permalink(get_queried_object_id());
            }
            if (!$current_url) {
                $current_url = home_url('/community/');
            }
            $home_tab_url = add_query_arg('dashboard_tab', 'home', $current_url);
            $my_profile_tab_url = add_query_arg('dashboard_tab', 'my-profile', $current_url);
            $expert_support_tab_url = add_query_arg('dashboard_tab', 'expert-support', $current_url);
            $matches_tab_url = add_query_arg('dashboard_tab', 'recruiter-matches', $current_url);
            $tracking_tab_url = add_query_arg('dashboard_tab', 'tracking', $current_url);
            $review_cv_tab_url = add_query_arg('dashboard_tab', 'review-cv', $current_url);
            $recruiter_outreach_tab_url = add_query_arg('dashboard_tab', 'recruiter-outreach', $current_url);

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $nav_groups = $this->build_crm_reddit_nav_groups(
                $group_model->get_all([
                    'is_active' => 1,
                    'order_by' => 'display_order',
                    'order' => 'ASC',
                    'include_post_count' => true,
                ]),
                $this->get_crm_reddit_group_nav_preferences($user_id),
                '',
                $current_url,
                ''
            );

            $account_user = [];
            if ($is_logged_in) {
                try {
                    $account_user = $this->get_crm_reddit_account_user($user_id);
                } catch (\Throwable $throwable) {
                    error_log('SFFC Reddit Dashboard user error: ' . $throwable->getMessage());
                    $account_user = [];
                }
            }
            $public_profile_account_user = [];
            if ($public_profile_user_id > 0) {
                try {
                    $public_profile_account_user = $this->get_crm_reddit_account_user($public_profile_user_id);
                } catch (\Throwable $throwable) {
                    error_log('SFFC Reddit Dashboard public profile user error: ' . $throwable->getMessage());
                    $public_profile_account_user = [];
                }
            }
            $sidebar_avatar_url = $is_logged_in ? $this->get_crm_reddit_profile_avatar_url($user_id, $account_user) : '';
            $dashboard_role_options = $this->get_crm_reddit_dashboard_search_role_options();
            $dashboard_role_list_id = function_exists('wp_unique_id') ? wp_unique_id('sffc-crm-dashboard-role-list-') : 'sffc-crm-dashboard-role-list-' . wp_rand();
            $dashboard_topbar_counts = $is_logged_in ? $this->get_crm_reddit_dashboard_topbar_counts($user_id) : ['notifications' => 0, 'messages' => 0];
            $dashboard_topbar_ats = $this->get_crm_reddit_dashboard_topbar_ats_state($dashboard_data, $resume_payload, $user_id);

            ob_start();
        ?>
            <section class="sffc-crm-reddit-shell sffc-crm-reddit-shell--dashboard-app" data-dashboard-shell data-dashboard-active-tab="<?php echo esc_attr($dashboard_tab); ?>" data-dashboard-jobs-post-id="<?php echo esc_attr((string) $jobs_post_id); ?>" data-dashboard-per-page="<?php echo esc_attr((string) $per_page); ?>" data-dashboard-fallback-role="<?php echo esc_attr($fallback_role); ?>" data-dashboard-current-url="<?php echo esc_url($current_url); ?>">
                <div class="sffc-crm-dashboard-app-shell">
                    <aside class="sffc-crm-dashboard-app-sidebar">
                        <div class="sffc-crm-dashboard-app-sidebar-top">
                            <div class="sffc-crm-dashboard-app-logo">
                                <a href="<?php echo esc_url(home_url('/')); ?>">MENA Careers</a>
                            </div>
                            <button class="sffc-crm-dashboard-app-collapse" type="button" aria-label="<?php esc_attr_e('Collapse navigation', 'senna-finance'); ?>">⌃</button>
                        </div>



                        <nav class="sffc-crm-dashboard-app-primary" aria-label="<?php esc_attr_e('Primary navigation', 'senna-finance'); ?>">
                            <a class="sffc-crm-dashboard-app-nav-link<?php echo $dashboard_tab === 'expert-support' ? ' is-active' : ''; ?>" href="<?php echo esc_url($expert_support_tab_url); ?>" data-dashboard-nav>
                                <span class="sffc-crm-dashboard-app-nav-icon">◎</span>
                                <span><?php esc_html_e('Expert Support', 'senna-finance'); ?></span>
                            </a>
                            <a class="sffc-crm-dashboard-app-nav-link<?php echo $dashboard_tab === 'my-profile' ? ' is-active is-current' : ''; ?>" href="<?php echo esc_url($my_profile_tab_url); ?>" data-dashboard-nav>
                                <span class="sffc-crm-dashboard-app-nav-icon">✦</span>
                                <span><?php esc_html_e('My Profile', 'senna-finance'); ?></span>
                            </a>
                            <a class="sffc-crm-dashboard-app-nav-link<?php echo $dashboard_tab === 'home' ? ' is-active' : ''; ?>" href="<?php echo esc_url($home_tab_url); ?>" data-dashboard-nav>
                                <span class="sffc-crm-dashboard-app-nav-icon">⌂</span>
                                <span><?php esc_html_e('Hiring Contacts', 'senna-finance'); ?></span>
                            </a>
                            <a class="sffc-crm-dashboard-app-nav-link<?php echo $dashboard_tab === 'recruiter-matches' ? ' is-active' : ''; ?>" href="<?php echo esc_url($matches_tab_url); ?>" data-dashboard-nav>
                                <span class="sffc-crm-dashboard-app-nav-icon">↗</span>
                                <span><?php esc_html_e('Career Leads', 'senna-finance'); ?></span>
                            </a>
                            <a class="sffc-crm-dashboard-app-nav-link<?php echo $dashboard_tab === 'tracking' ? ' is-active' : ''; ?>" href="<?php echo esc_url($tracking_tab_url); ?>" data-dashboard-nav>
