        private function get_crm_reddit_dashboard_partial_state(array $args = [])
        {
            $args = wp_parse_args($args, [
                'jobs_post_id' => 0,
                'per_page' => 18,
                'fallback_role' => 'Investment Associate',
                'current_url' => '',
                'dashboard_tab' => 'recruiter-matches',
                'matches_filter' => 'highest-match',
                'metrics_window' => 'month',
                'matches_page' => 1,
                'search_term' => '',
            ]);

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($args['jobs_post_id']);
            $per_page = max(12, min(36, absint($args['per_page'])));
            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $has_dashboard_membership_access = $is_logged_in && $this->current_user_has_crm_reddit_premium_access();
            $dashboard_tab = sanitize_key((string) $args['dashboard_tab']);
            if (!in_array($dashboard_tab, ['my-profile', 'expert-support', 'home', 'recruiter-matches', 'tracking', 'review-cv', 'recruiter-outreach'], true)) {
                $dashboard_tab = 'recruiter-matches';
            }
            $matches_filter = sanitize_key((string) $args['matches_filter']);
            if (!in_array($matches_filter, ['live-feed', 'recently-posted', 'highest-match'], true)) {
                $matches_filter = 'highest-match';
            }
            $metrics_window = sanitize_key((string) $args['metrics_window']);
            if (!in_array($metrics_window, ['week', 'two-weeks', 'month'], true)) {
                $metrics_window = 'month';
            }
            $matches_page = max(1, absint($args['matches_page']));
            $search_term = sanitize_text_field((string) $args['search_term']);
            $fallback_role = sanitize_text_field((string) $args['fallback_role']);
            if ($fallback_role === '') {
                $fallback_role = 'Investment Associate';
            }

            $needs_resume_payload = $is_logged_in && in_array($dashboard_tab, ['home', 'recruiter-matches', 'tracking', 'review-cv', 'recruiter-outreach'], true);
            $resume_payload = $needs_resume_payload
                ? $this->get_crm_reddit_active_resume_text($user_id)
                : ['cv_text' => '', 'has_cv' => false];

            $feed_items = [];
            $dashboard_metrics_items = [];
            $dashboard_data = [
                'insights' => [],
                'cards' => [],
                'total_roles' => 0,
            ];

            if ($dashboard_tab === 'recruiter-matches') {
                $feed_page_data = null;
                $feed_cache_key = '';
                if ($search_term === '') {
                    $feed_cache_key = 'sffc_crm_dash_feed_' . md5((int) $jobs_post_id . '|' . (int) $per_page . '|' . (int) $user_id . '|' . (string) $dashboard_tab);
                    $feed_page_data = get_transient($feed_cache_key);
                }
                if (!is_array($feed_page_data)) {
                    $feed_page_data = $this->get_crm_reddit_feed_page_data($jobs_post_id, $per_page, $user_id, '', $search_term);
                    if ($feed_cache_key !== '') {
                        set_transient($feed_cache_key, $feed_page_data, 5 * MINUTE_IN_SECONDS);
                    }
                }
                $feed_items = (array) ($feed_page_data['items'] ?? []);
                $dashboard_metrics_items = $this->get_crm_reddit_dashboard_metrics_source_items($jobs_post_id, $user_id, $search_term);
            }

            $current_url = esc_url_raw((string) $args['current_url']);
            if ($current_url === '') {
                $current_url = get_permalink(get_queried_object_id());
            }
            if (!$current_url) {
                $current_url = home_url('/community/');
            }
            $my_profile_tab_url = add_query_arg('dashboard_tab', 'my-profile', $current_url);

            $account_user = [];
            if ($is_logged_in) {
                try {
                    $account_user = $this->get_crm_reddit_account_user($user_id);
                } catch (\Throwable $throwable) {
                    error_log('SFFC Reddit Dashboard user error: ' . $throwable->getMessage());
                    $account_user = [];
                }
            }

            $render_topbar = $dashboard_tab !== 'recruiter-outreach';
            $sidebar_avatar_url = $is_logged_in ? $this->get_crm_reddit_profile_avatar_url($user_id, $account_user) : '';
            $dashboard_role_options = $render_topbar ? $this->get_crm_reddit_dashboard_search_role_options() : [];
            $dashboard_role_list_id = function_exists('wp_unique_id') ? wp_unique_id('sffc-crm-dashboard-role-list-') : 'sffc-crm-dashboard-role-list-' . wp_rand();
            $dashboard_topbar_counts = ($is_logged_in && $render_topbar) ? $this->get_crm_reddit_dashboard_topbar_counts($user_id) : ['notifications' => 0, 'messages' => 0];
            $dashboard_topbar_ats = $this->get_crm_reddit_dashboard_topbar_ats_state($dashboard_data, $resume_payload, $user_id);

            return [
                'jobs_post_id' => $jobs_post_id,
                'per_page' => $per_page,
                'user_id' => $user_id,
                'is_logged_in' => $is_logged_in,
                'dashboard_tab' => $dashboard_tab,
                'matches_filter' => $matches_filter,
                'metrics_window' => $metrics_window,
                'matches_page' => $matches_page,
                'search_term' => $search_term,
                'fallback_role' => $fallback_role,
                'resume_payload' => $resume_payload,
                'feed_items' => $feed_items,
                'dashboard_metrics_items' => $dashboard_metrics_items,
                'dashboard_data' => $dashboard_data,
                'current_url' => $current_url,
                'my_profile_tab_url' => $my_profile_tab_url,
                'account_user' => $account_user,
                'sidebar_avatar_url' => $sidebar_avatar_url,
                'dashboard_role_options' => $dashboard_role_options,
                'dashboard_role_list_id' => $dashboard_role_list_id,
                'dashboard_topbar_counts' => $dashboard_topbar_counts,
                'dashboard_topbar_ats' => $dashboard_topbar_ats,
                'has_dashboard_membership_access' => $has_dashboard_membership_access,
                'dashboard_upgrade_url' => $this->get_canonical_membership_url(),
                'render_topbar' => $render_topbar,
                'main_class' => 'sffc-crm-dashboard-app-main' . ($dashboard_tab === 'review-cv' ? ' sffc-crm-dashboard-app-main--review-cv' : '') . ($dashboard_tab === 'recruiter-outreach' ? ' sffc-crm-dashboard-app-main--recruiter-outreach' : '') . ($dashboard_tab === 'expert-support' ? ' sffc-crm-dashboard-app-main--expert-support' : ''),
                'board_class' => 'sffc-crm-dashboard-app-board' . ($dashboard_tab === 'review-cv' ? ' sffc-crm-dashboard-app-board--review-cv' : '') . ($dashboard_tab === 'recruiter-outreach' ? ' sffc-crm-dashboard-app-board--recruiter-outreach' : '') . ($dashboard_tab === 'expert-support' ? ' sffc-crm-dashboard-app-board--expert-support' : ''),
            ];
        }

        private function get_crm_reddit_dashboard_topbar_ats_state(array $dashboard_data = [], array $resume_payload = [], $user_id = 0)
        {
            $user_id = (int) $user_id;
            $score = 0;
            $value = '';

            if ($user_id > 0) {
                $cv_ats_payload = $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, false);
                if (!empty($cv_ats_payload['score'])) {
                    $score = max(0, min(100, (int) $cv_ats_payload['score']));
                }
            }

            if ($score > 0 && $value === '') {
                $value = $score . '%';
            }

            if ($value === '') {
                $value = $score > 0 ? ($score . '%') : __('ATS', 'senna-finance');
            }

            return [
                'score' => $score,
                'value' => $value,
                'state' => $score > 0 ? 'ready' : 'empty',
            ];
        }

