        public function render_crm_cv_match_job($atts)
        {
            $atts = shortcode_atts([
                'jobs_post_id' => 0,
            ], $atts, 'sffc_crm_cv_match_job');

            $reddit_feed_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/reddit-feed.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/reddit-feed.css') : SFFC_VERSION;
            $cv_match_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') : SFFC_VERSION;
            $reddit_feed_js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/reddit-feed.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/reddit-feed.js') : SFFC_VERSION;
            $cv_match_js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/cv-match-studio.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/cv-match-studio.js') : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css',
                [],
                $reddit_feed_css_version
            );

            wp_enqueue_style(
                'sffc-crm-cv-match-studio',
                SFFC_PLUGIN_URL . 'assets/css/crm/cv-match-studio.css',
                ['sffc-crm-reddit-feed'],
                $cv_match_css_version
            );

            $standalone_cv_match_css = $this->get_cv_match_job_namespace_css();
            if ($standalone_cv_match_css !== '') {
                wp_add_inline_style('sffc-crm-cv-match-studio', $standalone_cv_match_css);
            }

            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                $reddit_feed_js_version,
                true
            );

            wp_enqueue_script(
                'sffc-crm-cv-match-studio',
                SFFC_PLUGIN_URL . 'assets/js/crm/cv-match-studio.js',
                ['sffc-crm-reddit-feed'],
                $cv_match_js_version,
                true
            );

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            $job_item = $this->get_crm_reddit_jobs_item($jobs_post_id);

            if (empty($job_item)) {
                return '<section class="sffc-crm-reddit-shell sffc-crm-reddit-shell--single-job"><article class="sffc-crm-reddit-card sffc-crm-reddit-card--empty"><h3>' .
                    esc_html__('Job post not available', 'senna-finance') .
                    '</h3><p>' .
                    esc_html__('This layout needs a valid jobs post to render the full role details.', 'senna-finance') .
                    '</p></article></section>';
            }

            $cv_match_user_id = get_current_user_id();
            $cv_match_is_logged_in = is_user_logged_in();
            $cv_match_has_premium_access = $cv_match_is_logged_in && $this->current_user_has_crm_reddit_premium_access();
            $cv_match_resume_payload = $cv_match_is_logged_in
                ? $this->get_crm_reddit_active_resume_text($cv_match_user_id)
                : ['cv_text' => '', 'has_cv' => false];
            $cv_match_preferred_industry = $cv_match_user_id > 0
                ? $this->get_cv_match_studio_user_preferred_industry($cv_match_user_id)
                : '';
            if ($cv_match_preferred_industry === '') {
                $cv_match_preferred_industry = 'private_equity';
            }
            $cv_match_resume_payload['preferred_industry'] = $cv_match_preferred_industry;
            $show_cv_onboarding_modal = $cv_match_is_logged_in
                && $show_welcome_modal
                && empty(trim((string) ($cv_match_resume_payload['cv_text'] ?? '')));
            $cv_match_ats_state = $this->get_crm_reddit_dashboard_topbar_ats_state([], $cv_match_resume_payload, $cv_match_user_id);
            $cv_match_current_url = get_permalink(get_queried_object_id());
            if (!$cv_match_current_url) {
                $cv_match_current_url = home_url('/');
            }
            $cv_match_account_user = $cv_match_user_id > 0 ? $this->get_crm_reddit_account_user($cv_match_user_id) : [];
            $cv_match_avatar_url = $cv_match_user_id > 0 ? $this->get_crm_reddit_profile_avatar_url($cv_match_user_id, $cv_match_account_user) : '';
            $cv_match_display_name = trim((string) ($cv_match_account_user['display_name'] ?? ''));
            if ($cv_match_display_name === '') {
                $cv_match_display_name = __('MENA Careers', 'senna-finance');
            }
            $cv_match_first_name = '';
            if ($cv_match_is_logged_in) {
                $current_user = wp_get_current_user();
                if ($current_user instanceof WP_User && $current_user->exists()) {
                    $cv_match_first_name = trim((string) $current_user->first_name);
                    if ($cv_match_first_name === '') {
                        $name_parts = preg_split('/\s+/', trim((string) $current_user->display_name));
                        $cv_match_first_name = trim((string) ($name_parts[0] ?? ''));
                    }
                }
            }
            $cv_match_plan_label = $cv_match_has_premium_access
                ? __('Premium plan', 'senna-finance')
                : ($cv_match_is_logged_in ? __('Free plan', 'senna-finance') : __('Guest workspace', 'senna-finance'));
            $cv_match_sidebar_card_kicker = $cv_match_has_premium_access
                ? __('Premium access', 'senna-finance')
                : __('Upgrade', 'senna-finance');
            $cv_match_sidebar_card_title = $cv_match_has_premium_access
                ? __('Manage your plan and recruiter access.', 'senna-finance')
                : __('Unlock deeper recruiter context and tailored material routes.', 'senna-finance');
            $cv_match_sidebar_card_copy = $cv_match_has_premium_access
                ? __('Adjust your current plan, billing, and access level without leaving the workspace.', 'senna-finance')
                : ($cv_match_is_logged_in ? __('Move beyond the free workspace with stronger fit analysis and better recruiter routes.', 'senna-finance') : __('Best for candidates who want stronger fit analysis and a better route than direct apply.', 'senna-finance'));
            $cv_match_sidebar_card_cta = $cv_match_has_premium_access
                ? __('Manage Plan', 'senna-finance')
                : __('Upgrade', 'senna-finance');
            $cv_match_top_pill_label = $cv_match_has_premium_access
                ? __('Manage Plan', 'senna-finance')
                : ($cv_match_is_logged_in ? __('Upgrade', 'senna-finance') : __('Apply Smart - Join MENA Careers', 'senna-finance'));
            $cv_match_plan_action_url = $cv_match_is_logged_in
                ? home_url('/account/')
                : $this->get_crm_reddit_membership_url();
            $cv_match_cv_source_options = $cv_match_user_id > 0 ? array_values(array_filter(
                $this->get_crm_reddit_dashboard_outreach_cv_options($cv_match_user_id, $cv_match_resume_payload),
                static function ($option) {
                    return !empty($option['value']);
                }
            )) : [];
            $cv_match_studio_url = $this->get_crm_cv_match_studio_url();
            $community_dashboard_url = home_url('/community/');
            $review_cv_url = add_query_arg('dashboard_tab', 'review-cv', $community_dashboard_url);
            $recruiter_discovery_url = add_query_arg('dashboard_tab', 'recruiter-matches', $community_dashboard_url);
            $recruiter_outreach_url = add_query_arg('dashboard_tab', 'recruiter-outreach', $community_dashboard_url);
            $profile_url = add_query_arg('dashboard_tab', 'my-profile', $community_dashboard_url);

            wp_localize_script('sffc-crm-reddit-feed', 'sffcCrmRedditFeed', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_reddit_group_nav'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'uploadNonce' => wp_create_nonce('sffc_cv_upload'),
                'applyNonce' => wp_create_nonce('sffc_crm_reddit_apply'),
                'gapPayloadNonce' => wp_create_nonce('sffc_crm_reddit_gap_payload'),
                'networkingNonce' => wp_create_nonce('sffc_crm_reddit_networking_strategy'),
                'outreachNonce' => wp_create_nonce('sffc_crm_reddit_generate_outreach'),
                'materialNonce' => wp_create_nonce('sffc_crm_reddit_material_generate'),
                'isLoggedIn' => $cv_match_is_logged_in,
                'membershipUrl' => $this->get_crm_reddit_membership_url(),
                'pipelineStages' => class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [],
                'currentUser' => [
                    'email' => $cv_match_is_logged_in ? (string) wp_get_current_user()->user_email : '',
                ],
            ]);

            wp_localize_script('sffc-crm-cv-match-studio', 'sffcCrmCvMatchStudio', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_nonce'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'outreachNonce' => wp_create_nonce('sffc_crm_reddit_generate_outreach'),
                'materialNonce' => wp_create_nonce('sffc_crm_reddit_material_generate'),
                'cvGapUrl' => home_url('/cv-gap-analyser/'),
                'pdfWorker' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
                'membershipUrl' => $this->get_crm_reddit_membership_url(),
                'accountUrl' => home_url('/account/'),
                'loggedIn' => $cv_match_is_logged_in,
                'hasPremiumAccess' => $cv_match_has_premium_access,
