        public function render_crm_apply_button($atts)
        {
            $atts = shortcode_atts([
                'jobs_post_id' => 0,
                'label' => __('Apply', 'senna-finance'),
                'class' => '',
            ], $atts, 'sffc_crm_apply_button');

            wp_enqueue_style(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css',
                [],
                SFFC_VERSION
            );

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            if ($jobs_post_id <= 0) {
                $jobs_post_id = $this->get_crm_reddit_dashboard_default_jobs_post_id(0);
            }

            $job_item = $jobs_post_id > 0 ? $this->get_crm_reddit_jobs_item($jobs_post_id) : null;
            if (empty($job_item)) {
                return sprintf(
                    '<a class="%1$s" href="%2$s">%3$s</a>',
                    esc_attr(trim('sffc-crm-apply-shortcode__trigger ' . (string) $atts['class'])),
                    esc_url(home_url('/')),
                    esc_html((string) $atts['label'])
                );
            }

            $role_title = trim((string) ($job_item['role_title'] ?? __('Live role', 'senna-finance')));
            $company_name = trim((string) ($job_item['company'] ?? ''));
            $location = trim((string) ($job_item['location'] ?? ''));
            $primary_apply_url = trim((string) ($job_item['apply_url'] ?? ''));
            $role_page_url = trim((string) ($job_item['view_url'] ?? ''));
            if ($primary_apply_url === '') {
                $primary_apply_url = $role_page_url;
            }
            if ($role_page_url === '') {
                $role_page_url = $primary_apply_url;
            }

            $role_meta = implode(' • ', array_values(array_filter([$company_name, $location])));
            $instance_id = wp_unique_id('sffc-crm-apply-shortcode-');
            $trigger_classes = trim('sffc-crm-apply-shortcode__trigger ' . (string) $atts['class']);
            $membership_url = $this->get_canonical_membership_url();
            if ($membership_url === '') {
                $membership_url = home_url('/');
            }
            $recruiter_name = trim((string) ($job_item['recruiter_name'] ?? __('Hiring Team', 'senna-finance')));
            $recruiter_name_parts = preg_split('/\s+/', $recruiter_name) ?: [];
            $recruiter_first_name = !empty($recruiter_name_parts[0]) ? trim((string) $recruiter_name_parts[0]) : '';
            $recruiter_last_name = count($recruiter_name_parts) > 1 ? trim((string) $recruiter_name_parts[count($recruiter_name_parts) - 1]) : '';
            $recruiter_last_initial = $recruiter_last_name !== ''
                ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_last_name, 0, 1) : substr($recruiter_last_name, 0, 1))
                : '';
            $recruiter_display_name = $recruiter_first_name !== ''
                ? trim($recruiter_first_name . ($recruiter_last_initial !== '' ? ' ' . $recruiter_last_initial . '.' : ''))
                : __('Hiring Team', 'senna-finance');
            $recruiter_photo = trim((string) ($job_item['recruiter_photo'] ?? ''));
            $recruiter_initial = $recruiter_name !== ''
                ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1))
                : 'R';

            ob_start();
        ?>
            <div id="<?php echo esc_attr($instance_id); ?>" class="sffc-crm-apply-shortcode" data-crm-apply-shortcode>
                <button type="button" class="<?php echo esc_attr($trigger_classes); ?>" data-crm-apply-shortcode-open>
                    <?php echo esc_html((string) $atts['label']); ?>
                </button>

                <div class="sffc-match-modal sffc-crm-reddit-single-apply-modal sffc-crm-apply-shortcode-modal" data-crm-apply-shortcode-modal hidden>
                    <div class="sffc-match-modal-overlay" data-crm-apply-shortcode-close></div>
                    <div class="sffc-match-modal-content sffc-match-modal--skyscanner sffc-crm-reddit-single-apply-dialog" role="dialog" aria-modal="true" aria-labelledby="<?php echo esc_attr($instance_id); ?>-title" tabindex="-1">
                        <div class="sffc-match-modal-topbar sffc-crm-reddit-single-apply-topbar">
                            <div class="sffc-match-modal-topbar-main">
                                <div class="sffc-match-modal-hero-content">
                                    <div class="sffc-match-modal-hero-badge">
                                        <button type="button" class="sffc-match-hero-score" data-crm-apply-shortcode-close>
                                            <span class="sffc-match-hero-score-icon" aria-hidden="true">
                                                <svg viewBox="0 0 20 20">
                                                    <path d="M11.8 4.5 6.2 10l5.6 5.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
                                                </svg>
                                            </span>
                                            <span><?php esc_html_e('Back to Job Post', 'senna-finance'); ?></span>
                                        </button>
                                    </div>
                                    <h1 id="<?php echo esc_attr($instance_id); ?>-title" class="sffc-match-modal-hero-title"><?php echo esc_html($role_title); ?></h1>
                                    <div class="sffc-match-modal-hero-meta">
                                        <?php if ($company_name !== '') : ?>
                                            <span><?php echo esc_html($company_name); ?></span>
                                        <?php endif; ?>
                                        <?php if ($location !== '') : ?>
                                            <span><?php echo esc_html($location); ?></span>
                                        <?php endif; ?>
                                    </div>
                                </div>
                                <button type="button" class="sffc-match-modal-logo" data-crm-apply-shortcode-close aria-label="<?php esc_attr_e('Close modal', 'senna-finance'); ?>">
                                    <svg viewBox="0 0 24 24" aria-hidden="true">
                                        <path d="M7 7 17 17M17 7 7 17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" />
                                    </svg>
                                </button>
                            </div>
