                    if (!root) {
                        return;
                    }

                    var openButton = root.querySelector('[data-crm-apply-shortcode-open]');
                    var modal = root.querySelector('[data-crm-apply-shortcode-modal]');
                    var dialog = root.querySelector('.sffc-crm-reddit-single-apply-dialog');
                    var closeButtons = root.querySelectorAll('[data-crm-apply-shortcode-close]');

                    if (!openButton || !modal || !dialog) {
                        return;
                    }

                    function openModal() {
                        modal.hidden = false;
                        document.body.classList.add('sffc-match-modal-open');
                        window.requestAnimationFrame(function() {
                            dialog.focus();
                        });
                    }

                    function closeModal() {
                        modal.hidden = true;
                        document.body.classList.remove('sffc-match-modal-open');
                    }

                    openButton.addEventListener('click', openModal);
                    closeButtons.forEach(function(button) {
                        button.addEventListener('click', closeModal);
                    });

                    document.addEventListener('keydown', function(event) {
                        if (event.key === 'Escape' && !modal.hidden) {
                            closeModal();
                        }
                    });
                })();
            </script>
        <?php

            return (string) ob_get_clean();
        }

        private function render_crm_apply_chat_activity_panel($user_id, $mode = 'intros')
        {
            $mode = $mode === 'sent' ? 'sent' : 'intros';
            $items = $mode === 'intros'
                ? $this->get_community_send_intro_applications_for_user($user_id)
                : $this->get_community_managed_applications_for_user($user_id);
            $title = $mode === 'intros'
                ? __('Recruiter intros', 'senna-finance')
                : __('Tailored applications sent', 'senna-finance');
