                <div class="sffc-crm-apply-chat__activity-head">
                    <strong><?php echo esc_html($title); ?></strong>
                    <p><?php echo esc_html($description); ?></p>
                </div>
                <?php if (!empty($items)) : ?>
                    <div class="sffc-crm-apply-chat__activity-list">
                        <?php foreach ($items as $item) : ?>
                            <?php
                            $item = is_array($item) ? $item : [];
                            $primary = trim((string) ($item['name'] ?? ''));
                            $secondary = trim((string) ($item['company'] ?? ''));
                            $meta = trim((string) ($item['title'] ?? ''));
                            $status = trim((string) ($item['campaign_status'] ?? ''));
                            $sent_at = trim((string) ($item['sent_at'] ?? ''));
                            $supporting = trim((string) ($item['company_info'] ?? ''));
                            $documents = trim((string) ($item['attachment_urls'] ?? ''));
                            $detail_link = $mode === 'intros'
                                ? trim((string) ($item['linkedin'] ?? ''))
                                : trim((string) ($item['linkedin'] ?? ''));
                            ?>
                            <article class="sffc-crm-apply-chat__activity-card">
                                <div class="sffc-crm-apply-chat__activity-card-main">
                                    <div class="sffc-crm-apply-chat__activity-card-copy">
                                        <strong><?php echo esc_html($primary !== '' ? $primary : __('Update', 'senna-finance')); ?></strong>
                                        <?php if ($secondary !== '') : ?><span><?php echo esc_html($secondary); ?></span><?php endif; ?>
                                        <?php if ($meta !== '') : ?><small><?php echo esc_html($meta); ?></small><?php endif; ?>
                                    </div>
                                    <div class="sffc-crm-apply-chat__activity-card-status">
                                        <?php if ($status !== '') : ?><span class="sffc-crm-apply-chat__activity-chip"><?php echo esc_html($status); ?></span><?php endif; ?>
                                        <?php if ($sent_at !== '') : ?><time><?php echo esc_html($sent_at); ?></time><?php endif; ?>
                                    </div>
                                </div>
                                <?php if ($supporting !== '' || $documents !== '') : ?>
                                    <div class="sffc-crm-apply-chat__activity-card-meta">
                                        <?php if ($supporting !== '') : ?><p><?php echo esc_html($supporting); ?></p><?php endif; ?>
                                        <?php if ($documents !== '') : ?><p class="is-muted"><?php echo esc_html($documents); ?></p><?php endif; ?>
                                    </div>
                                <?php endif; ?>
                                <?php if ($detail_link !== '') : ?>
                                    <div class="sffc-crm-apply-chat__activity-card-actions">
                                        <a href="<?php echo esc_url($detail_link); ?>" target="_blank" rel="noopener noreferrer" class="sffc-crm-apply-chat__activity-link">
                                            <?php echo esc_html($mode === 'intros' ? __('Open recruiter route', 'senna-finance') : __('Open application route', 'senna-finance')); ?>
                                        </a>
                                    </div>
                                <?php endif; ?>
                            </article>
                        <?php endforeach; ?>
                    </div>
                <?php else : ?>
                    <article class="sffc-crm-apply-chat__activity-empty">
                        <strong><?php echo esc_html($empty_title); ?></strong>
                        <p><?php echo esc_html($empty_copy); ?></p>
                    </article>
                <?php endif; ?>
            </section>
            <?php

            return (string) ob_get_clean();
        }

