        private function resolve_crm_reddit_jobs_post_id($raw_jobs_post_id)
        {
            $jobs_post_id = absint($raw_jobs_post_id);
            if ($jobs_post_id > 0) {
                return $jobs_post_id;
            }

            $queried_object = get_queried_object();
            if ($queried_object instanceof WP_Post) {
                if ($queried_object->post_type === 'jobs') {
                    return (int) $queried_object->ID;
                }

                if ($queried_object->post_type === 'sffc_recruiter_post') {
                    $crm_post_id = (int) get_post_meta($queried_object->ID, '_crm_post_id', true);
                    if ($crm_post_id > 0) {
                        $linked_jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($crm_post_id);
                        if ($linked_jobs_post_id > 0) {
                            return $linked_jobs_post_id;
                        }
                    }
                }
            }

            $current_post_id = get_the_ID();
            if ($current_post_id > 0 && get_post_type($current_post_id) === 'jobs') {
                return (int) $current_post_id;
            }

            return 0;
        }

        private function find_jobs_post_id_by_crm_post_id($crm_post_id)
        {
            $crm_post_id = (int) $crm_post_id;
            if ($crm_post_id <= 0) {
                return 0;
            }

            global $wpdb;

            return (int) $wpdb->get_var($wpdb->prepare(
                "SELECT p.ID
                 FROM {$wpdb->posts} p
                 INNER JOIN {$wpdb->postmeta} pm ON pm.post_id = p.ID
                 WHERE p.post_type = %s
                   AND p.post_status IN ('publish', 'draft', 'pending', 'future', 'private')
                   AND pm.meta_key = %s
                   AND pm.meta_value = %s
                 ORDER BY p.ID DESC
                 LIMIT 1",
                'jobs',
                '_crm_post_id',
                (string) $crm_post_id
            ));
        }

        private function get_crm_reddit_jobs_item($jobs_post_id)
        {
            $jobs_post_id = (int) $jobs_post_id;
            if ($jobs_post_id <= 0) {
                return null;
            }

            $jobs_post = get_post($jobs_post_id);
            if (!$jobs_post instanceof WP_Post || $jobs_post->post_type !== 'jobs') {
                return null;
            }

            $crm_post_id = (int) get_post_meta($jobs_post_id, '_crm_post_id', true);
            $crm_post = null;
            if ($crm_post_id > 0) {
                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get($crm_post_id);
            }

            $title = get_post_meta($jobs_post_id, '_job_title', true);
            if ($title === '') {
                $title = $jobs_post->post_title;
            }

            $company = get_post_meta($jobs_post_id, '_company_name', true);
            if ($company === '') {
                $company = get_post_meta($jobs_post_id, 'sffc_company_name', true);
            }
            if ($company === '') {
                $company = get_post_meta($jobs_post_id, 'sffc_actual_company', true);
            }
            if ($company === '' && !empty($crm_post['company'])) {
                $company = $crm_post['company'];
            }

            $application_url = '';
            foreach (['_application_url', 'newapplicationLink', 'applicationLink', 'sffc_application_url', '_sffc_job_application_url'] as $application_meta_key) {
                $application_url = trim((string) get_post_meta($jobs_post_id, $application_meta_key, true));
                if ($application_url !== '') {
                    break;
                }
            }

            $excerpt = $jobs_post->post_excerpt;
            if ($excerpt === '') {
                $excerpt = wp_trim_words(wp_strip_all_tags((string) $jobs_post->post_content), 42, '...');
            }
            if ($excerpt === '' && !empty($crm_post['content_snippet'])) {
                $excerpt = (string) $crm_post['content_snippet'];
            }

            $city = sanitize_text_field((string) get_post_meta($jobs_post_id, 'addressLocality', true));
            $country = sanitize_text_field((string) get_post_meta($jobs_post_id, 'addressCountry', true));
            $location = implode(', ', array_filter([$city, $country]));
            if ($location === '' && !empty($crm_post['location'])) {
                $location = sanitize_text_field((string) $crm_post['location']);
            }

            $salary = sanitize_text_field((string) get_post_meta($jobs_post_id, 'sffc_salary_display', true));
            if ($salary === '' && !empty($crm_post['salary_text'])) {
                $salary = sanitize_text_field((string) $crm_post['salary_text']);
            }
            $sector = sanitize_text_field((string) get_post_meta($jobs_post_id, '_sector', true));
            if ($sector === '') {
                $sector = sanitize_text_field((string) get_post_meta($jobs_post_id, 'sector', true));
            }
            if ($sector === '' && !empty($crm_post['sector'])) {
                $sector = sanitize_text_field((string) $crm_post['sector']);
            }

            $employment_type = get_post_meta($jobs_post_id, 'employmentType', true);
            if (is_array($employment_type)) {
                $employment_type = implode(', ', array_map('sanitize_text_field', $employment_type));
            }
            $employment_type = sanitize_text_field((string) $employment_type);

            $company_logo = '';
            if (!empty($crm_post['company_logo'])) {
                $company_logo = $this->normalize_company_logo_url($crm_post['company_logo']);
            }
            $keywords = !empty($crm_post['keywords'])
                ? $this->normalize_recruiter_intro_keywords($crm_post['keywords'])
                : [];

            $description_source = trim((string) get_post_meta($jobs_post_id, 'jobDescription', true));
            if ($description_source === '') {
                $description_source = trim((string) get_post_meta($jobs_post_id, 'sffc_job_description', true));
            }
            if ($description_source === '' && !empty($jobs_post->post_content)) {
                $description_source = (string) $jobs_post->post_content;
            } elseif (!empty($crm_post['content'])) {
                $description_source = (string) $crm_post['content'];
            } elseif (!empty($excerpt)) {
                $description_source = (string) $excerpt;
            }

            $posted_timestamp = $this->normalize_crm_linkedin_jobs_posted_timestamp($crm_post['posted_at'] ?? '');
            if ($posted_timestamp <= 0) {
                $posted_timestamp = (int) get_post_time('U', true, $jobs_post);
            }

            $primary_group = $this->get_crm_reddit_primary_group($crm_post_id);
            $duration = sanitize_text_field((string) get_post_meta($jobs_post_id, 'duration', true));
            if ($duration === '') {
                $duration = sanitize_text_field((string) get_post_meta($jobs_post_id, 'internship_duration', true));
            }
            if ($duration === '' && !empty($crm_post['duration'])) {
                $duration = sanitize_text_field((string) $crm_post['duration']);
            }
            $auto_submit_payload = $this->get_crm_apply_chat_auto_submit_payload($jobs_post_id);

            return [
                'source' => 'jobs',
                'source_platform' => sanitize_text_field((string) ($crm_post['source_platform'] ?? '')),
                'post_id' => $jobs_post_id,
                'wp_post_id' => $jobs_post_id,
                'crm_post_id' => $crm_post_id,
                'modal_key' => 'jobs-' . $jobs_post_id,
                'role_title' => sanitize_text_field((string) $title),
                'company' => sanitize_text_field((string) $company),
                'recruiter_name' => sanitize_text_field((string) ($crm_post['recruiter_name'] ?? __('Editorial Desk', 'senna-finance'))),
                'recruiter_firm' => sanitize_text_field((string) ($crm_post['recruiter_firm'] ?? __('MENA Careers', 'senna-finance'))),
                'recruiter_public_firm_label' => sanitize_text_field((string) ($crm_post['recruiter_display_company'] ?? '')),
                'recruiter_title' => sanitize_text_field((string) ($crm_post['recruiter_title'] ?? '')),
                'recruiter_photo' => esc_url_raw((string) ($crm_post['recruiter_photo'] ?? '')),
                'recruiter_email' => sanitize_email((string) ($crm_post['recruiter_email'] ?? '')),
                'recruiter_linkedin' => esc_url_raw((string) ($crm_post['recruiter_linkedin'] ?? '')),
                'recruiter_phone' => sanitize_text_field((string) ($crm_post['recruiter_phone'] ?? ($crm_post['phone'] ?? ($crm_post['contact_phone'] ?? '')))),
                'company_logo' => $company_logo,
                'location' => $location,
                'salary_text' => $salary,
                'sector' => $sector,
                'recruiter_specializations' => sanitize_text_field((string) ($crm_post['recruiter_specializations'] ?? '')),
                'seniority' => sanitize_text_field((string) ($crm_post['seniority'] ?? '')),
                'employment_type' => $employment_type,
                'duration' => $duration,
                'excerpt' => sanitize_text_field((string) $excerpt),
                'description_preview' => $this->get_crm_reddit_dashboard_description_preview($description_source, $excerpt),
                'description_html' => $this->format_crm_reddit_job_content($description_source),
                'view_url' => get_permalink($jobs_post_id) ?: '',
                'apply_url' => esc_url_raw((string) $application_url),
                'application_workspace_url' => esc_url_raw((string) ($auto_submit_payload['application_embed_url'] ?? '')),
                'auto_submit_supported' => $auto_submit_payload['supported'],
                'auto_submit_provider' => $auto_submit_payload['provider'],
                'auto_submit_schema_status' => $auto_submit_payload['schema_status'],
                'auto_submit_field_count' => $auto_submit_payload['field_count'],
                'auto_submit_required_question_count' => $auto_submit_payload['required_question_count'],
                'greenhouse_board_token' => $auto_submit_payload['greenhouse_board_token'],
                'greenhouse_job_id' => $auto_submit_payload['greenhouse_job_id'],
                'message_url' => $this->get_crm_reddit_message_url($crm_post ?: []),
                'posted_timestamp' => $posted_timestamp,
                'posted_label' => sprintf(
                    /* translators: %s: relative time */
                    __('%s ago', 'senna-finance'),
                    human_time_diff($posted_timestamp, current_time('timestamp'))
                ),
                'badge' => __('Pinned role', 'senna-finance'),
                'group_name' => (string) ($primary_group['name'] ?? __('MENA Careers Community', 'senna-finance')),
                'group_slug' => (string) ($primary_group['slug'] ?? ''),
                'keywords' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) $keywords)), 0, 8)),
            ];
        }

        private function get_crm_apply_chat_auto_submit_payload($jobs_post_id)
        {
            $jobs_post_id = absint($jobs_post_id);
            $payload = [
                'supported' => false,
                'provider' => '',
                'schema_status' => '',
                'field_count' => 0,
                'required_question_count' => 0,
                'application_embed_url' => '',
                'greenhouse_board_token' => '',
                'greenhouse_job_id' => '',
            ];

            if ($jobs_post_id <= 0) {
                return $payload;
            }

            $provider = sanitize_key((string) get_post_meta($jobs_post_id, '_sffc_auto_submit_provider', true));
            $supported = (string) get_post_meta($jobs_post_id, '_sffc_auto_submit_supported', true) === '1';
            $schema_status = sanitize_key((string) get_post_meta($jobs_post_id, '_sffc_auto_submit_schema_status', true));
            $schema_raw = get_post_meta($jobs_post_id, '_sffc_auto_submit_schema', true);
            $schema = [];
            $url_board_token = '';
            $url_job_id = '';

            if (is_string($schema_raw) && trim($schema_raw) !== '') {
                $decoded = json_decode($schema_raw, true);
                $schema = is_array($decoded) ? $decoded : [];
            } elseif (is_array($schema_raw)) {
                $schema = $schema_raw;
            }

            if (!empty($schema)) {
                $supported = true;
                if ($provider === '') {
                    $provider = sanitize_key((string) ($schema['provider'] ?? ''));
                }
                if ($schema_status === '') {
                    $schema_status = 'discovered';
                }
            }
            if (!$supported) {
                $application_url = $this->get_crm_apply_chat_jobs_application_url($jobs_post_id);
                if ($application_url !== '' && preg_match('~(?:job-boards|boards)(?:\.eu)?\.greenhouse\.io/([^/?#]+)/jobs/(\d+)~i', $application_url, $matches)) {
                    $supported = true;
                    $provider = 'greenhouse';
                    $url_board_token = sanitize_key(rawurldecode($matches[1]));
                    $url_job_id = sanitize_text_field($matches[2]);
                }
            }
            if (!$supported) {
                $application_url = $this->get_crm_apply_chat_jobs_application_url($jobs_post_id);
                $source_platform = strtolower((string) get_post_meta($jobs_post_id, '_source_platform', true));
                if ($application_url !== '' && ($provider === 'successfactors' || strpos($source_platform, 'successfactors') !== false || preg_match('~successfactors|sapsf|/talentcommunity/apply/~i', $application_url))) {
                    $schema = $this->fetch_crm_apply_chat_successfactors_schema_from_job_url($jobs_post_id);
                    if (!empty($schema)) {
                        $supported = true;
                        $provider = 'successfactors';
                        $schema_status = 'discovered';
                    }
                }
            }

            $payload['supported'] = $supported;
            $payload['provider'] = $provider;
            $payload['schema_status'] = $schema_status;
            $payload['field_count'] = absint($schema['field_count'] ?? 0);
            $payload['required_question_count'] = absint($schema['required_question_count'] ?? 0);
            $payload['application_embed_url'] = esc_url_raw((string) ($schema['application_embed_url'] ?? ($schema['hosted_url'] ?? '')));
            $payload['greenhouse_board_token'] = sanitize_text_field((string) get_post_meta($jobs_post_id, '_sffc_greenhouse_board_token', true));
            $payload['greenhouse_job_id'] = sanitize_text_field((string) get_post_meta($jobs_post_id, '_sffc_greenhouse_job_id', true));

            if ($payload['greenhouse_board_token'] === '' && !empty($schema['board_token'])) {
                $payload['greenhouse_board_token'] = sanitize_text_field((string) $schema['board_token']);
            }
            if ($payload['greenhouse_job_id'] === '' && !empty($schema['job_id'])) {
                $payload['greenhouse_job_id'] = sanitize_text_field((string) $schema['job_id']);
            }
            if ($payload['greenhouse_board_token'] === '' && $url_board_token !== '') {
                $payload['greenhouse_board_token'] = $url_board_token;
            }
            if ($payload['greenhouse_job_id'] === '' && $url_job_id !== '') {
                $payload['greenhouse_job_id'] = $url_job_id;
            }

            return $payload;
        }

        private function get_crm_apply_chat_jobs_application_url($jobs_post_id)
        {
            $jobs_post_id = absint($jobs_post_id);
            if ($jobs_post_id <= 0) {
                return '';
            }

            foreach (['_application_url', 'newapplicationLink', 'applicationLink', 'sffc_application_url', '_sffc_job_application_url'] as $application_meta_key) {
                $application_url = esc_url_raw((string) get_post_meta($jobs_post_id, $application_meta_key, true));
                if ($application_url !== '') {
                    return $application_url;
                }
            }

            return '';
        }

        private function fetch_crm_apply_chat_successfactors_schema_from_job_url($jobs_post_id)
        {
            $jobs_post_id = absint($jobs_post_id);
            $job_url = $this->get_crm_apply_chat_jobs_application_url($jobs_post_id);
            if ($jobs_post_id <= 0 || $job_url === '') {
                return [];
            }

            $response = wp_remote_get($job_url, [
                'timeout' => 25,
                'redirection' => 4,
                'headers' => [
                    'Accept' => 'text/html,application/xhtml+xml',
                    'User-Agent' => 'Mozilla/5.0 (compatible; WordPress/' . get_bloginfo('version') . '; ' . home_url('/') . ')',
                ],
            ]);

            if (is_wp_error($response) || (int) wp_remote_retrieve_response_code($response) !== 200) {
                return [];
            }

            $html = (string) wp_remote_retrieve_body($response);
            $schema = $this->build_crm_apply_chat_successfactors_schema_from_html($html, $jobs_post_id, $job_url);
            if (empty($schema)) {
                return [];
            }

            update_post_meta($jobs_post_id, '_sffc_auto_submit_supported', '1');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_provider', 'successfactors');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_schema_status', 'discovered');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_schema', wp_json_encode($schema));
            self::invalidate_cv_match_job_posts_cache((int) $jobs_post_id);

            return $schema;
        }

        private function build_crm_apply_chat_successfactors_schema_from_html($html, $jobs_post_id, $job_url)
        {
            $html = (string) $html;
            $sso_url = '';
            $source_id = '';
            $locale = '';
            $internal_id = '';

            if (preg_match('/ssoUrl\s*:\s*[\'"]([^\'"]+)[\'"]/i', $html, $matches)) {
                $sso_url = esc_url_raw((string) $matches[1]);
            } elseif (preg_match('~https://career\d+\.successfactors\.(?:com|eu)~i', $html, $matches)) {
                $sso_url = esc_url_raw((string) $matches[0]);
            } elseif (preg_match('~https://performancemanager(\d+)\.successfactors\.eu~i', $html, $matches)) {
                $sso_url = esc_url_raw('https://career' . $matches[1] . '.successfactors.eu');
            }

            if (preg_match('/sourceId\s*:\s*[\'"]([^\'"]+)[\'"]/i', $html, $matches)) {
                $source_id = sanitize_text_field((string) $matches[1]);
            }

            if (preg_match('/locale\s*:\s*[\'"]([A-Za-z_-]+)[\'"]/i', $html, $matches)) {
                $locale = sanitize_text_field((string) $matches[1]);
            } elseif (preg_match('/[?&]locale=([A-Za-z_-]+)/i', $job_url, $matches)) {
                $locale = sanitize_text_field((string) $matches[1]);
            } else {
                $locale = 'en_US';
            }

            if (preg_match('/internalId\s*:\s*"([^"-]+)(?:-[^"]*)?"/i', $html, $matches)) {
                $internal_id = sanitize_text_field((string) $matches[1]);
            } elseif (preg_match('/"internalId"\s*:\s*"([^"-]+)(?:-[^"]*)?"/i', $html, $matches)) {
                $internal_id = sanitize_text_field((string) $matches[1]);
            } elseif (preg_match('~/job/[^/]+/(\d+)(?:-[A-Za-z_]+)?/?~i', $job_url, $matches)) {
                $internal_id = sanitize_text_field((string) $matches[1]);
            }

            $company_code = '';
            if (stripos($source_id, 'JATS-') === 0) {
                $company_code = substr($source_id, 5);
            }
            if ($company_code === '' && preg_match('/[?&](?:company|career_company)=([^&"\']+)/i', $html, $matches)) {
                $company_code = rawurldecode((string) $matches[1]);
            }
            $company_code = sanitize_text_field($company_code);

            if ($sso_url === '' || $company_code === '' || $internal_id === '') {
                return [];
            }

            $embed_url = esc_url_raw(rtrim($sso_url, '/') . '/career?company=' . rawurlencode($company_code) . '&site=&lang=' . rawurlencode($locale) . '&login_ns=register&career_ns=job_application&career_job_req_id=' . rawurlencode($internal_id) . '&jobPipeline=Direct&clientId=jobs2web');
            $questions = $this->fetch_crm_apply_chat_successfactors_questions($embed_url);
            if (empty($questions)) {
                $questions = [
                    [
                        'label' => __('Resume/CV upload', 'senna-finance'),
                        'required' => true,
                        'description' => '',
                        'fields' => [['name' => 'resume', 'type' => 'file', 'values' => []]],
                    ],
                    [
                        'label' => __('Email address', 'senna-finance'),
                        'required' => true,
                        'description' => '',
                        'fields' => [['name' => 'email', 'type' => 'email', 'values' => []]],
                    ],
                    [
                        'label' => __('First name', 'senna-finance'),
                        'required' => true,
                        'description' => '',
                        'fields' => [['name' => 'first_name', 'type' => 'text', 'values' => []]],
                    ],
                    [
                        'label' => __('Last name', 'senna-finance'),
                        'required' => true,
                        'description' => '',
                        'fields' => [['name' => 'last_name', 'type' => 'text', 'values' => []]],
                    ],
                ];
            }

            return [
                'provider' => 'successfactors',
                'source_platform' => 'SAP SuccessFactors',
                'job_id' => sanitize_text_field((string) get_post_meta($jobs_post_id, '_job_id', true)),
                'internal_job_id' => $internal_id,
                'source_id' => $source_id,
                'company_code' => $company_code,
                'sso_url' => $sso_url,
                'title' => sanitize_text_field((string) get_the_title($jobs_post_id)),
                'company_name' => sanitize_text_field((string) get_post_meta($jobs_post_id, '_company_name', true)),
                'location' => sanitize_text_field((string) get_post_meta($jobs_post_id, '_job_location', true)),
                'schema_url' => esc_url_raw($job_url),
                'hosted_url' => $embed_url,
                'application_embed_url' => $embed_url,
                'absolute_url' => esc_url_raw($job_url),
                'questions' => $questions,
                'location_questions' => [],
                'required_question_count' => count(array_filter($questions, static function ($question) {
                    return is_array($question) && !empty($question['required']);
                })),
                'field_count' => array_sum(array_map(static function ($question) {
                    return is_array($question) ? max(1, count((array) ($question['fields'] ?? []))) : 0;
                }, $questions)),
                'discovered_at' => current_time('mysql'),
            ];
        }

        private function fetch_crm_apply_chat_successfactors_questions($embed_url)
        {
            $embed_url = esc_url_raw((string) $embed_url);
            if ($embed_url === '' || !class_exists('DOMDocument')) {
                return [];
            }

            $response = wp_remote_get($embed_url, [
                'timeout' => 25,
                'redirection' => 4,
                'headers' => [
                    'Accept' => 'text/html,application/xhtml+xml',
                    'User-Agent' => 'Mozilla/5.0 (compatible; WordPress/' . get_bloginfo('version') . '; ' . home_url('/') . ')',
                ],
            ]);
            if (is_wp_error($response) || (int) wp_remote_retrieve_response_code($response) >= 400) {
                return [];
            }

            return $this->extract_crm_apply_chat_form_questions_from_html((string) wp_remote_retrieve_body($response));
        }

        private function extract_crm_apply_chat_form_questions_from_html($html)
        {
            if (trim((string) $html) === '' || !class_exists('DOMDocument')) {
                return [];
            }

            $previous = libxml_use_internal_errors(true);
            $dom = new DOMDocument();
            $dom->loadHTML('<?xml encoding="utf-8" ?>' . (string) $html);
            libxml_clear_errors();
            libxml_use_internal_errors($previous);

            $xpath = new DOMXPath($dom);
            $questions = [];
            foreach ($xpath->query('//input|//textarea|//select') as $field) {
                if (!$field instanceof DOMElement) {
                    continue;
                }
                $type = strtolower((string) $field->getAttribute('type'));
                $name = sanitize_text_field((string) $field->getAttribute('name'));
                if ($name === '' || in_array($type, ['hidden', 'submit', 'button', 'reset'], true)) {
                    continue;
                }

                $label = '';
                $id = (string) $field->getAttribute('id');
                if ($id !== '') {
                    $label_node = $xpath->query('//label[@for=' . $this->xpath_literal($id) . ']')->item(0);
                    if ($label_node) {
                        $label = trim(preg_replace('/\s+/', ' ', html_entity_decode(wp_strip_all_tags((string) $label_node->textContent), ENT_QUOTES, 'UTF-8')));
                    }
                }
                if ($label === '') {
                    $label = trim(str_replace(['_', '-'], ' ', $name));
                }

                $values = [];
                if (strtolower($field->tagName) === 'select') {
                    foreach ($xpath->query('.//option', $field) as $option) {
                        if ($option instanceof DOMElement) {
                            $option_label = trim(preg_replace('/\s+/', ' ', html_entity_decode(wp_strip_all_tags((string) $option->textContent), ENT_QUOTES, 'UTF-8')));
                            if ($option_label !== '') {
                                $values[] = [
                                    'label' => sanitize_text_field($option_label),
                                    'value' => sanitize_text_field((string) $option->getAttribute('value')),
                                ];
                            }
                        }
                    }
                }

                $questions[] = [
                    'label' => sanitize_text_field($label),
                    'required' => $field->hasAttribute('required') || (string) $field->getAttribute('aria-required') === 'true',
                    'description' => '',
                    'fields' => [[
                        'name' => $name,
                        'type' => sanitize_key(strtolower($field->tagName) === 'textarea' ? 'textarea' : ($type ?: strtolower($field->tagName))),
                        'values' => $values,
                    ]],
                ];
            }

            $seen = [];
            return array_values(array_filter($questions, static function ($question) use (&$seen) {
                $label = strtolower(trim((string) ($question['label'] ?? '')));
                if ($label === '' || isset($seen[$label])) {
                    return false;
                }
                $seen[$label] = true;
                return true;
            }));
        }

        private function fetch_crm_apply_chat_greenhouse_schema_from_hosted_url($jobs_post_id)
        {
            $jobs_post_id = absint($jobs_post_id);
            $hosted_url = $this->get_crm_apply_chat_jobs_application_url($jobs_post_id);
            if ($jobs_post_id <= 0 || $hosted_url === '' || !preg_match('~job-boards(?:\.eu)?\.greenhouse\.io/([^/?#]+)/jobs/(\d+)~i', $hosted_url, $matches)) {
                return [];
            }

            $board_token = sanitize_key(rawurldecode($matches[1]));
            $job_id = sanitize_text_field($matches[2]);
            $response = wp_remote_get($hosted_url, [
                'timeout' => 30,
                'redirection' => 3,
                'headers' => [
                    'Accept' => 'text/html',
                    'User-Agent' => 'Mozilla/5.0 (compatible; WordPress/' . get_bloginfo('version') . '; ' . home_url('/') . ')',
                ],
            ]);

            if (is_wp_error($response) || (int) wp_remote_retrieve_response_code($response) !== 200) {
                return [];
            }

            $html = (string) wp_remote_retrieve_body($response);
            if (!preg_match('~window\.__remixContext\s*=\s*(\{.*?\});\s*</script>~s', $html, $context_matches)) {
                return [];
            }

            $context = json_decode($context_matches[1], true);
            if (!is_array($context)) {
                return [];
            }

            $route_payload = $this->find_crm_apply_chat_greenhouse_remix_job_payload($context);
            $job_post = is_array($route_payload['jobPost'] ?? null) ? $route_payload['jobPost'] : [];
            $questions = is_array($job_post['questions'] ?? null) ? $job_post['questions'] : [];
            if (empty($questions)) {
                return [];
            }

            $submit_url = esc_url_raw((string) ($route_payload['submitPath'] ?? ''));
            if ($submit_url === '') {
                $submit_host = stripos((string) wp_parse_url($hosted_url, PHP_URL_HOST), 'job-boards.eu.greenhouse.io') !== false
                    ? 'boards.eu.greenhouse.io'
                    : 'boards.greenhouse.io';
                $submit_url = esc_url_raw('https://' . $submit_host . '/' . rawurlencode($board_token) . '/jobs/' . rawurlencode($job_id));
            }

            $location_questions = is_array($job_post['location_questions'] ?? null) ? $job_post['location_questions'] : [];
            $all_questions = array_merge($questions, $location_questions);
            $schema = [
                'provider' => 'greenhouse',
                'source_key' => '',
                'source_platform' => 'Greenhouse',
                'board_token' => $board_token,
                'job_id' => $job_id,
                'internal_job_id' => sanitize_text_field((string) ($route_payload['jobPostId'] ?? $job_id)),
                'title' => sanitize_text_field((string) ($job_post['title'] ?? get_the_title($jobs_post_id))),
                'company_name' => sanitize_text_field((string) ($job_post['company_name'] ?? get_post_meta($jobs_post_id, '_company_name', true))),
                'location' => sanitize_text_field((string) ($job_post['job_post_location'] ?? get_post_meta($jobs_post_id, '_job_location', true))),
                'schema_url' => esc_url_raw($hosted_url),
                'hosted_url' => esc_url_raw($hosted_url),
                'submit_url' => $submit_url,
                'absolute_url' => esc_url_raw($hosted_url),
                'data_compliance' => is_array($job_post['data_compliance'] ?? null) ? $job_post['data_compliance'] : [],
                'questions' => $questions,
                'location_questions' => $location_questions,
                'required_question_count' => count(array_filter($all_questions, static function ($question) {
                    return is_array($question) && !empty($question['required']);
                })),
                'field_count' => array_sum(array_map(static function ($question) {
                    return is_array($question) ? count((array) ($question['fields'] ?? [])) : 0;
                }, $all_questions)),
                'discovered_at' => current_time('mysql'),
            ];

            update_post_meta($jobs_post_id, '_sffc_auto_submit_supported', '1');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_provider', 'greenhouse');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_schema_status', 'discovered');
            update_post_meta($jobs_post_id, '_sffc_auto_submit_schema', wp_json_encode($schema));
            update_post_meta($jobs_post_id, '_sffc_greenhouse_board_token', $board_token);
            update_post_meta($jobs_post_id, '_sffc_greenhouse_job_id', $job_id);

            if (class_exists('SFFC_CRM_Shortcodes')) {
                self::invalidate_cv_match_job_posts_cache((int) $jobs_post_id);
            }

            return $schema;
        }

        private function find_crm_apply_chat_greenhouse_remix_job_payload(array $node)
        {
            if (!empty($node['jobPost']) && is_array($node['jobPost']) && !empty($node['jobPost']['questions'])) {
                return $node;
            }

            foreach ($node as $value) {
                if (is_array($value)) {
                    $found = $this->find_crm_apply_chat_greenhouse_remix_job_payload($value);
                    if (!empty($found)) {
                        return $found;
                    }
                }
            }

            return [];
        }

        private function build_crm_reddit_crm_item(array $post)
        {
            $role_title = sanitize_text_field((string) ($post['role_title'] ?? __('Opportunity', 'senna-finance')));
            $slug_seed = sanitize_title($role_title . '-' . ($post['company'] ?? ''));
            $linked_wp_post_id = (int) ($post['wp_post_id'] ?? 0);
            $view_url = $linked_wp_post_id > 0 ? (get_permalink($linked_wp_post_id) ?: '') : '';
            if ($view_url === '') {
                $view_url = SFFC_CRM_Post_Type::get_post_url((int) ($post['id'] ?? 0), $slug_seed);
            }
            $excerpt = !empty($post['content_snippet'])
                ? sanitize_text_field((string) $post['content_snippet'])
                : sanitize_text_field(wp_trim_words(wp_strip_all_tags((string) ($post['content'] ?? '')), 42, '...'));

            $company_logo = !empty($post['company_logo']) ? $this->normalize_company_logo_url($post['company_logo']) : '';
            $description_source = !empty($post['content']) ? (string) $post['content'] : (string) $excerpt;
            $primary_group = $this->get_crm_reddit_primary_group((int) ($post['id'] ?? 0));
            $keywords = !empty($post['keywords'])
