        private function get_crm_reddit_dashboard_description_preview($content = '', $fallback = '')
        {
            $source = trim(wp_strip_all_tags((string) $content));
            if ($source === '') {
                $source = trim(wp_strip_all_tags((string) $fallback));
            }

            if ($source === '') {
                return '';
            }

            $source = preg_replace('/\s+/', ' ', $source);

            return function_exists('mb_strimwidth')
                ? trim((string) mb_strimwidth($source, 0, 220, '...'))
                : trim((string) substr($source, 0, 217) . (strlen($source) > 217 ? '...' : ''));
        }

        private function get_crm_reddit_primary_group($crm_post_id)
        {
            static $group_cache = [];

            $crm_post_id = (int) $crm_post_id;
            if ($crm_post_id <= 0) {
                $application_url = '';
                foreach (['_application_url', 'newapplicationLink', 'applicationLink', 'sffc_application_url', '_sffc_job_application_url'] as $application_meta_key) {
                    $application_url = trim((string) get_post_meta($post_id, $application_meta_key, true));
                    if ($application_url !== '') {
                        break;
                    }
                }

                return [
                    'name' => __('MENA Careers Community', 'senna-finance'),
                    'slug' => '',
                ];
            }

            if (isset($group_cache[$crm_post_id])) {
                return $group_cache[$crm_post_id];
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $groups = $group_model->get_groups_for_post($crm_post_id);
            $group = !empty($groups[0]) ? $groups[0] : [];

            $group_cache[$crm_post_id] = [
                'name' => !empty($group['name']) ? sanitize_text_field((string) $group['name']) : __('MENA Careers Community', 'senna-finance'),
                'slug' => !empty($group['slug']) ? sanitize_title((string) $group['slug']) : '',
            ];

            return $group_cache[$crm_post_id];
        }

        private function get_crm_reddit_group_slugs_for_post($crm_post_id)
        {
            static $group_slug_cache = [];

            $crm_post_id = (int) $crm_post_id;
            if ($crm_post_id <= 0) {
                return [];
            }

            if (isset($group_slug_cache[$crm_post_id])) {
                return $group_slug_cache[$crm_post_id];
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $groups = $group_model->get_groups_for_post($crm_post_id);
            $group_slug_cache[$crm_post_id] = array_values(array_filter(array_map(
                static function ($group) {
                    return sanitize_title((string) ($group['slug'] ?? ''));
                },
                (array) $groups
            )));

            return $group_slug_cache[$crm_post_id];
        }

        private function get_cv_match_studio_mailbox_group_slugs(array $item)
        {
            $slugs = [];
            $primary_slug = sanitize_title((string) ($item['group_slug'] ?? ''));
            if ($primary_slug !== '') {
                $slugs[] = $primary_slug;
            }

            $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
            if ($crm_post_id <= 0 && (string) ($item['source'] ?? '') !== 'jobs') {
                $crm_post_id = (int) ($item['post_id'] ?? 0);
            }
            if ($crm_post_id <= 0 && !empty($item['id'])) {
                $crm_post_id = (int) $item['id'];
            }

            if ($crm_post_id > 0) {
                $slugs = array_merge($slugs, $this->get_crm_reddit_group_slugs_for_post($crm_post_id));
            }

            return array_values(array_unique(array_filter($slugs)));
        }

        private function get_crm_reddit_message_url(array $post)
        {
            if (!empty($post['recruiter_linkedin'])) {
                return esc_url_raw((string) $post['recruiter_linkedin']);
            }

            if (!empty($post['recruiter_email'])) {
                return 'mailto:' . sanitize_email((string) $post['recruiter_email']);
            }

            return '';
        }

        private function is_email_application_url($url)
        {
            $url = trim((string) $url);
            if ($url === '') {
                return false;
            }

            $decoded = html_entity_decode(rawurldecode($url), ENT_QUOTES, 'UTF-8');
            if (stripos($decoded, 'mailto:') === 0) {
                return true;
            }

            return (bool) preg_match('/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i', $decoded);
        }

        private function get_crm_reddit_opportunity_notice(array $item)
        {
            $role_title = trim((string) ($item['role_title'] ?? ''));
            $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
            $normalized_title = function_exists('mb_strtolower')
                ? mb_strtolower($role_title)
                : strtolower($role_title);

            $high_competition_titles = $this->get_crm_reddit_hidden_role_titles();

            if ($normalized_title !== '') {
                foreach ($high_competition_titles as $high_competition_title) {
                    if ($high_competition_title !== '' && strpos($normalized_title, $high_competition_title) !== false) {
                        return [
                            'tone' => 'rare',
                            'headline' => __('Rare Opportunity! This role is usually hidden', 'senna-finance'),
                            'meta' => __('Strong candidate demand is expected for this title, so speed and application quality matter more here.', 'senna-finance'),
                        ];
                    }
                }
            }

            return null;
        }

        private function get_crm_reddit_hidden_role_titles()
        {
            return [
                'investment analyst',
                'finance analyst',
                'equity analyst',
                'finance intern',
                'private credit analyst',
                'family office investment analyst',
                'secondaries pe analyst',
                'energy pe analyst',
                'investment associate',
                'finance associate',
            ];
        }

        private function get_crm_reddit_opportunity_membership_counts()
        {
            static $counts = null;

            if ($counts !== null) {
                return $counts;
            }

            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_posts';
            $base_where = "p.is_active = 1 AND p.admin_approved = 1 AND (p.post_status IS NULL OR p.post_status = 'open')";
            $hidden_titles = $this->get_crm_reddit_hidden_role_titles();
            $rows = $wpdb->get_results(
                "SELECT p.role_title
                 FROM {$table} p
                 WHERE {$base_where}",
                ARRAY_A
            );

            $hidden_count = 0;

            foreach ((array) $rows as $row) {
                $normalized_title = trim((string) ($row['role_title'] ?? ''));
                if ($normalized_title === '') {
                    continue;
                }

                $normalized_title = function_exists('mb_strtolower')
                    ? mb_strtolower($normalized_title)
                    : strtolower($normalized_title);

                foreach ($hidden_titles as $hidden_title) {
                    if ($hidden_title !== '' && strpos($normalized_title, $hidden_title) !== false) {
                        $hidden_count++;
                        break;
                    }
                }
            }

            $counts = [
                'early_bird' => 0,
                'hidden' => max(0, $hidden_count),
            ];

            return $counts;
        }

        private function get_crm_reddit_opportunity_action_label($tone, array $counts)
        {
            $count_key = $tone === 'rare' ? 'hidden' : 'early_bird';
            $count = (int) ($counts[$count_key] ?? 0);

            if ($tone === 'rare') {
                if ($count >= 10) {
                    return sprintf(
                        /* translators: %d: rare roles count */
                        __('Access Rare Roles (%d)', 'senna-finance'),
                        $count
                    );
                }

                return __('Access Rare Roles', 'senna-finance');
            }

            return __('Access Roles', 'senna-finance');
        }

        private function get_crm_reddit_opportunity_group_label($tone, array $counts)
        {
            $count_key = $tone === 'rare' ? 'hidden' : 'early_bird';
            $count = (int) ($counts[$count_key] ?? 0);

            if ($tone === 'rare') {
                if ($count >= 10) {
                    return sprintf(
                        /* translators: %d: rare roles count */
                        __('Rare Roles (%d)', 'senna-finance'),
                        $count
                    );
                }

                return __('Rare Roles', 'senna-finance');
            }

            return __('Roles', 'senna-finance');
        }

