                        <path d="M12 2.8 14.9 8l5.7 1.1-4 4.1.7 5.8-5.3-2.5-5.3 2.5.7-5.8-4-4.1L9.1 8Z" fill="currentColor" />
                    </svg>
                </span>
                <span class="sffc-crm-reddit-opportunity-copy">
                    <strong><?php echo esc_html((string) $notice['headline']); ?></strong>
                    <?php if (!empty($notice['meta'])) : ?>
