                    <?php endif; ?>
                </span>
            </div>
        <?php
            return ob_get_clean();
        }

        private function render_crm_recommended_guest_signal_bootstrap(array $job_item, $view_url = '')
        {
            if (is_user_logged_in()) {
                return '';
            }

            $role_title = trim((string) ($job_item['role_title'] ?? ''));
            if ($role_title === '') {
                return '';
            }

            $keywords = !empty($job_item['keywords'])
                ? array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) $this->normalize_recruiter_intro_keywords($job_item['keywords']))), 0, 6))
                : [];
            $resolved_view_url = trim((string) $view_url);
            if ($resolved_view_url === '' && !empty($job_item['view_url'])) {
                $resolved_view_url = (string) $job_item['view_url'];
            }
            if ($resolved_view_url === '' && !empty($job_item['wp_post_id'])) {
                $resolved_view_url = (string) (get_permalink((int) $job_item['wp_post_id']) ?: '');
            }

            $payload = [
                'id' => (int) ($job_item['crm_post_id'] ?? ($job_item['id'] ?? 0)),
                'jobsPostId' => (int) ($job_item['post_id'] ?? ($job_item['jobs_post_id'] ?? 0)),
                'wpPostId' => (int) ($job_item['wp_post_id'] ?? 0),
                'title' => sanitize_text_field($role_title),
                'href' => esc_url_raw($resolved_view_url),
                'location' => sanitize_text_field((string) ($job_item['location'] ?? '')),
                'sector' => sanitize_text_field((string) ($job_item['sector'] ?? '')),
                'seniority' => sanitize_text_field((string) ($job_item['seniority'] ?? '')),
                'keywords' => $keywords,
                'pinned' => true,
                'eventType' => 'landing',
            ];

            ob_start();
        ?>
            <script>
                (function () {
                    try {
                        if (typeof window === "undefined" || !window.localStorage) {
                            return;
                        }

                        var recentKey = "sffcCvMatchRecentRoles";
                        var guestKey = "sffcCvMatchGuestSignals";
                        var recentLimit = 10;
                        var interactionLimit = 12;
                        var now = Date.now();
                        var role = <?php echo wp_json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>;
                        var referrer = document.referrer || "";

                        function parseReferrer(value) {
                            var empty = {
                                referrerDomain: "",
                                referrerPath: "",
                                sourceChannel: "",
                            };

                            if (!value) {
                                return empty;
                            }

                            try {
                                var parsed = new URL(value, window.location.origin);
                                var hostname = String(parsed.hostname || "").toLowerCase();
                                var sourceChannel = "external";

                                if (hostname === String(window.location.hostname || "").toLowerCase() || hostname === "") {
                                    sourceChannel = "internal";
                                } else if (hostname.indexOf("linkedin.com") !== -1 || hostname.indexOf("lnkd.in") !== -1) {
                                    sourceChannel = "linkedin";
                                } else if (hostname.indexOf("google.") !== -1) {
                                    sourceChannel = "google";
                                } else if (
                                    hostname.indexOf("instagram.com") !== -1 ||
                                    hostname.indexOf("facebook.com") !== -1 ||
                                    hostname.indexOf("twitter.com") !== -1 ||
                                    hostname.indexOf("x.com") !== -1 ||
                                    hostname.indexOf("t.co") !== -1
                                ) {
                                    sourceChannel = "social";
                                }

                                return {
                                    referrerDomain: hostname,
                                    referrerPath: String(parsed.pathname || ""),
                                    sourceChannel: sourceChannel,
                                };
                            } catch (error) {
                                return empty;
                            }
                        }

                        function load(key, fallback) {
                            try {
                                var raw = window.localStorage.getItem(key);
                                return raw ? JSON.parse(raw) : fallback;
                            } catch (error) {
                                return fallback;
                            }
                        }

                        function normalizeKeywords(value) {
                            if (typeof value === "string") {
                                value = value.split(/[\r\n,|]+/);
                            }

                            return Array.isArray(value)
                                ? value.map(function (keyword) {
                                      return String(keyword || "").trim();
                                  }).filter(Boolean).slice(0, 6)
                                : [];
                        }

                        function normalizeRole(input, eventType, meta) {
                            if (!input || typeof input !== "object") {
                                return null;
                            }

                            var normalized = {
                                title: String(input.title || "").trim(),
                                href: String(input.href || "").trim(),
                                pinned: true,
                                touchedAt: now,
                                id: Number(input.id || 0),
                                jobsPostId: Number(input.jobsPostId || input.jobs_post_id || 0),
                                wpPostId: Number(input.wpPostId || input.wp_post_id || 0),
                                location: String(input.location || "").trim(),
                                sector: String(input.sector || "").trim(),
                                seniority: String(input.seniority || "").trim(),
                                keywords: normalizeKeywords(input.keywords),
                                eventType: String(eventType || input.eventType || "landing").trim(),
                                referrerDomain: String((meta && meta.referrerDomain) || "").trim().toLowerCase(),
                                referrerPath: String((meta && meta.referrerPath) || "").trim(),
                                sourceChannel: String((meta && meta.sourceChannel) || "").trim().toLowerCase(),
                            };

                            if (!normalized.title && !normalized.href && !normalized.id) {
                                return null;
                            }

                            return normalized;
                        }

                        function compare(left, right) {
                            if (!!left.pinned !== !!right.pinned) {
                                return left.pinned ? -1 : 1;
                            }

                            return Number(right.touchedAt || 0) - Number(left.touchedAt || 0);
                        }

                        function saveRecent(normalizedRole) {
                            var recent = load(recentKey, []);
                            recent = Array.isArray(recent) ? recent : [];
                            recent = recent.filter(function (item) {
                                return item && item.href !== normalizedRole.href;
                            });
                            recent.unshift({
                                title: normalizedRole.title,
                                href: normalizedRole.href,
                                pinned: true,
                                touchedAt: normalizedRole.touchedAt,
                                id: normalizedRole.id,
                                jobsPostId: normalizedRole.jobsPostId,
                                wpPostId: normalizedRole.wpPostId,
                                location: normalizedRole.location,
                                sector: normalizedRole.sector,
                                seniority: normalizedRole.seniority,
                                keywords: normalizedRole.keywords,
                            });
                            window.localStorage.setItem(recentKey, JSON.stringify(recent.sort(compare).slice(0, recentLimit)));
                        }

                        function saveGuest(normalizedRole, meta) {
                            var guest = load(guestKey, {});
                            var interactions = Array.isArray(guest.interactions) ? guest.interactions : [];
                            var roleKey = normalizedRole.href || String(normalizedRole.id || normalizedRole.jobsPostId || normalizedRole.wpPostId || "");

                            interactions = interactions.filter(function (item) {
                                var itemKey = (item && item.href) || String((item && (item.id || item.jobsPostId || item.wpPostId)) || "");
                                return itemKey !== roleKey;
                            });
                            interactions.unshift(normalizedRole);

                            guest.sessionStartedAt = Number(guest.sessionStartedAt || now) || now;
                            guest.updatedAt = now;
                            guest.referrerDomain = guest.referrerDomain || meta.referrerDomain || "";
                            guest.referrerPath = guest.referrerPath || meta.referrerPath || "";
                            guest.sourceChannel = guest.sourceChannel || meta.sourceChannel || "";
                            guest.landingRole = normalizedRole;
                            guest.interactions = interactions.sort(compare).slice(0, interactionLimit);

                            window.localStorage.setItem(guestKey, JSON.stringify(guest));
                        }

                        var referrerMeta = parseReferrer(referrer);
                        var normalizedRole = normalizeRole(role, "landing", referrerMeta);
                        if (!normalizedRole) {
                            return;
                        }

                        saveRecent(normalizedRole);
                        saveGuest(normalizedRole, referrerMeta);
                    } catch (error) {
                        return;
                    }
                })();
            </script>
        <?php
            return ob_get_clean();
        }

        private function build_crm_reddit_company_stories(array $feed_items)
        {
            $stories = [];

            foreach ($feed_items as $index => $item) {
                $company = trim((string) ($item['company'] ?? ''));
                if ($company === '') {
                    $company = __('Featured Company', 'senna-finance');
                }

                $story_key = sanitize_title($company);
                if ($story_key === '') {
                    $story_key = 'company-' . ($index + 1);
                }

                if (!isset($stories[$story_key])) {
                    $company_initial = strtoupper(function_exists('mb_substr') ? mb_substr($company, 0, 1) : substr($company, 0, 1));
                    $stories[$story_key] = [
                        'key' => $story_key,
                        'company' => $company,
                        'company_initial' => $company_initial !== '' ? $company_initial : 'C',
                        'company_logo' => !empty($item['company_logo']) ? esc_url_raw((string) $item['company_logo']) : '',
                        'lead_recruiter_name' => sanitize_text_field((string) ($item['recruiter_name'] ?? '')),
                        'lead_recruiter_photo' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'lead_recruiter_firm' => sanitize_text_field((string) ($item['recruiter_firm'] ?? '')),
                        'role_count' => 0,
                        'items' => [],
                    ];
                }

                if ($stories[$story_key]['company_logo'] === '' && !empty($item['company_logo'])) {
                    $stories[$story_key]['company_logo'] = esc_url_raw((string) $item['company_logo']);
                }

                if ($stories[$story_key]['lead_recruiter_name'] === '' && !empty($item['recruiter_name'])) {
                    $stories[$story_key]['lead_recruiter_name'] = sanitize_text_field((string) $item['recruiter_name']);
                    $stories[$story_key]['lead_recruiter_photo'] = esc_url_raw((string) ($item['recruiter_photo'] ?? ''));
                    $stories[$story_key]['lead_recruiter_firm'] = sanitize_text_field((string) ($item['recruiter_firm'] ?? ''));
                }

                $stories[$story_key]['role_count']++;
                $stories[$story_key]['items'][] = $item;
            }

            return array_values($stories);
        }

        private function get_crm_reddit_group_nav_preferences($user_id)
        {
            $defaults = [
                'order' => [],
                'pinned' => [],
            ];

            if ($user_id <= 0) {
                return $defaults;
            }

            $stored = get_user_meta($user_id, 'sffc_crm_reddit_group_nav_prefs', true);
            if (!is_array($stored)) {
                return $defaults;
            }

            return [
                'order' => array_values(array_filter(array_map('sanitize_title', (array) ($stored['order'] ?? [])))),
                'pinned' => array_values(array_filter(array_map('sanitize_title', (array) ($stored['pinned'] ?? [])))),
            ];
        }

        private function build_crm_reddit_nav_groups(array $groups, array $preferences, $selected_group, $current_url, $search_term)
        {
            $order_lookup = [];
            foreach ((array) ($preferences['order'] ?? []) as $position => $slug) {
                $order_lookup[$slug] = $position;
            }

            $pinned_lookup = array_fill_keys((array) ($preferences['pinned'] ?? []), true);

            $items = [];
            foreach ($groups as $group) {
                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                if ($slug === '') {
                    continue;
                }

                $name = sanitize_text_field((string) ($group['name'] ?? $slug));
                $initial = strtoupper(function_exists('mb_substr') ? mb_substr($name, 0, 1) : substr($name, 0, 1));
                $url = add_query_arg('reddit_group', $slug, $current_url);
                if ($search_term !== '') {
                    $url = add_query_arg('sffc_reddit_search', $search_term, $url);
                }

                $items[] = [
                    'slug' => $slug,
                    'name' => $name,
                    'initial' => $initial !== '' ? $initial : 'G',
                    'icon' => esc_url_raw((string) ($group['icon'] ?? '')),
                    'meta' => sprintf(_n('%d role', '%d roles', (int) ($group['post_count'] ?? 0), 'senna-finance'), (int) ($group['post_count'] ?? 0)),
                    'url' => $url,
                    'is_active' => $selected_group === $slug,
                    'is_pinned' => !empty($pinned_lookup[$slug]),
                    'preference_order' => $order_lookup[$slug] ?? PHP_INT_MAX,
                    'display_order' => (int) ($group['display_order'] ?? 0),
                ];
            }

            usort($items, static function ($left, $right) {
                $left_pinned = !empty($left['is_pinned']) ? 1 : 0;
                $right_pinned = !empty($right['is_pinned']) ? 1 : 0;
                if ($left_pinned !== $right_pinned) {
                    return $right_pinned <=> $left_pinned;
                }

                $left_order = (int) ($left['preference_order'] ?? PHP_INT_MAX);
                $right_order = (int) ($right['preference_order'] ?? PHP_INT_MAX);
                if ($left_order !== $right_order) {
                    return $left_order <=> $right_order;
                }

                $left_display = (int) ($left['display_order'] ?? 0);
                $right_display = (int) ($right['display_order'] ?? 0);
                if ($left_display !== $right_display) {
                    return $left_display <=> $right_display;
                }

                return strcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
            });

            $all_url = remove_query_arg('reddit_group', $current_url);
            if ($search_term !== '') {
                $all_url = add_query_arg('sffc_reddit_search', $search_term, $all_url);
            }

            array_unshift($items, [
                'slug' => '',
                'name' => __('MENA Careers Community', 'senna-finance'),
                'initial' => 'S',
                'icon' => '',
                'meta' => __('Default role stream across the community', 'senna-finance'),
                'url' => $all_url,
                'is_active' => $selected_group === '',
                'is_pinned' => false,
                'preference_order' => -1,
                'display_order' => -1,
            ]);

            return $items;
        }

        private function get_crm_reddit_active_group_context($selected_group, array $nav_groups, $fallback_subtitle = '')
        {
            foreach ($nav_groups as $nav_group) {
                if ((string) ($nav_group['slug'] ?? '') === (string) $selected_group) {
                    return [
                        'title' => (string) ($nav_group['name'] ?? __('MENA Careers Community', 'senna-finance')),
                        'subtitle' => $selected_group === ''
                            ? (string) $fallback_subtitle
                            : (string) ($nav_group['meta'] ?? $fallback_subtitle),
                    ];
                }
            }

            return [
                'title' => __('MENA Careers Community', 'senna-finance'),
                'subtitle' => (string) $fallback_subtitle,
            ];
        }

        private function filter_crm_reddit_feed_items(array $feed_items, $search_term)
        {
            $needle = function_exists('mb_strtolower')
                ? mb_strtolower(trim((string) $search_term))
                : strtolower(trim((string) $search_term));

            if ($needle === '') {
                return $feed_items;
            }

            return array_values(array_filter($feed_items, static function ($item) use ($needle) {
                $haystack = implode(' ', array_filter([
                    (string) ($item['role_title'] ?? ''),
                    (string) ($item['company'] ?? ''),
                    (string) ($item['recruiter_name'] ?? ''),
                    (string) ($item['recruiter_firm'] ?? ''),
                    (string) ($item['location'] ?? ''),
                    (string) ($item['salary_text'] ?? ''),
                    (string) ($item['seniority'] ?? ''),
                    (string) ($item['employment_type'] ?? ''),
                    (string) ($item['excerpt'] ?? ''),
                ]));

                $haystack = function_exists('mb_strtolower') ? mb_strtolower($haystack) : strtolower($haystack);

                return $haystack !== '' && strpos($haystack, $needle) !== false;
            }));
        }

        private function build_crm_reddit_search_suggestions(array $feed_items, $search_term = '', $limit = 14)
        {
            $suggestions = [];
            $seen = [];
            $limit = max(1, (int) $limit);
            $needle = function_exists('mb_strtolower')
                ? mb_strtolower(trim((string) $search_term))
                : strtolower(trim((string) $search_term));

            foreach ($feed_items as $item) {
                $candidates = [
                    [
                        'value' => trim((string) ($item['role_title'] ?? '')),
                        'type' => 'role',
                        'label' => __('Role', 'senna-finance'),
                        'meta' => implode(' • ', array_filter([
                            trim((string) ($item['company'] ?? '')),
                            trim((string) ($item['location'] ?? '')),
                        ])),
                        'image' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'image_label' => trim((string) ($item['recruiter_name'] ?? '')),
                    ],
                    [
                        'value' => trim((string) ($item['company'] ?? '')),
                        'type' => 'company',
                        'label' => __('Company', 'senna-finance'),
                        'meta' => trim((string) ($item['role_title'] ?? '')),
                        'image' => esc_url_raw((string) ($item['company_logo'] ?? ($item['recruiter_photo'] ?? ''))),
                        'image_label' => trim((string) ($item['company'] ?? '')),
                    ],
                    [
                        'value' => trim((string) ($item['recruiter_name'] ?? '')),
                        'type' => 'recruiter',
                        'label' => __('Recruiter', 'senna-finance'),
                        'meta' => implode(' • ', array_filter([
                            trim((string) ($item['role_title'] ?? '')),
                            trim((string) ($item['company'] ?? '')),
                        ])),
                        'image' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'image_label' => trim((string) ($item['recruiter_name'] ?? '')),
                    ],
                ];

                foreach ($candidates as $candidate) {
                    if ($candidate['value'] === '') {
                        continue;
                    }

                    $normalized = function_exists('mb_strtolower')
                        ? mb_strtolower($candidate['value'])
                        : strtolower($candidate['value']);

                    if ($needle !== '' && strpos($normalized, $needle) === false) {
                        continue;
                    }

                    $key = $candidate['type'] . '|' . $normalized;
                    if (isset($seen[$key])) {
                        continue;
                    }

                    if (empty($candidate['meta'])) {
                        $candidate['meta'] = (string) $candidate['label'];
                    }

                    $seen[$key] = true;
                    $suggestions[] = $candidate;

                    if (count($suggestions) >= $limit) {
                        break 2;
                    }
                }
            }

            return $suggestions;
        }

        private function get_crm_reddit_single_job_search_items($limit = 60)
        {
            $limit = max(8, min(120, (int) $limit));
            $items = [];
            $seen = [];
            $query = new WP_Query([
                'post_type' => ['jobs', 'sffc_job'],
                'post_status' => 'publish',
                'posts_per_page' => $limit,
                'orderby' => 'date',
                'order' => 'DESC',
                'ignore_sticky_posts' => true,
                'no_found_rows' => true,
            ]);

            if (!$query->have_posts()) {
                return [];
            }

            foreach ($query->posts as $post) {
                if (!$post instanceof WP_Post) {
                    continue;
                }

                $item = null;

                if ($post->post_type === 'jobs') {
                    $item = $this->get_crm_reddit_jobs_item((int) $post->ID);
                } elseif ($post->post_type === 'sffc_job') {
                    $item = $this->build_crm_reddit_single_job_search_item_from_sffc_job($post);
                }

                if (empty($item) || !is_array($item)) {
                    continue;
                }

                $dedupe_key = strtolower(trim((string) ($item['role_title'] ?? '')) . '|' . trim((string) ($item['company'] ?? '')));
                if ($dedupe_key === '|' || isset($seen[$dedupe_key])) {
                    continue;
                }

                $seen[$dedupe_key] = true;
                $items[] = $item;

                if (count($items) >= $limit) {
                    break;
                }
            }

            wp_reset_postdata();

            return $items;
        }

        private function build_crm_reddit_single_job_search_item_from_sffc_job(WP_Post $post)
        {
            $post_id = (int) $post->ID;
            if ($post_id <= 0 || $post->post_type !== 'sffc_job') {
                return null;
            }

            $company = '';
            foreach (['_company_name', 'sffc_company_name', 'company_name', 'company'] as $meta_key) {
                $company = trim((string) get_post_meta($post_id, $meta_key, true));
                if ($company !== '') {
                    break;
                }
            }

            $location = '';
            foreach (['sffc_job_location', 'location', 'sffc_location'] as $meta_key) {
                $location = trim((string) get_post_meta($post_id, $meta_key, true));
                if ($location !== '') {
                    break;
                }
            }

            $excerpt = trim((string) $post->post_excerpt);
            if ($excerpt === '') {
                $excerpt = wp_trim_words(wp_strip_all_tags((string) $post->post_content), 32, '...');
            }

            return [
                'source' => 'sffc_job',
                'post_id' => $post_id,
                'role_title' => sanitize_text_field((string) get_the_title($post)),
                'company' => sanitize_text_field($company),
                'recruiter_name' => '',
                'recruiter_firm' => '',
                'location' => sanitize_text_field($location),
                'salary_text' => '',
                'seniority' => sanitize_text_field((string) get_post_meta($post_id, 'sffc_job_level', true)),
                'employment_type' => sanitize_text_field((string) get_post_meta($post_id, 'sffc_job_type', true)),
                'excerpt' => sanitize_text_field($excerpt),
            ];
        }

        private function build_crm_reddit_recruiter_sidebar(array $feed_items)
        {
            $recruiters = [];

            foreach ($feed_items as $index => $item) {
                $name = trim((string) ($item['recruiter_name'] ?? ''));
                if ($name === '') {
                    $name = __('Hiring Team', 'senna-finance');
                }

                $company = trim((string) ($item['company'] ?? ''));
                if ($company === '') {
                    $company = trim((string) ($item['recruiter_firm'] ?? ''));
                }
                if ($company === '') {
                    $company = __('MENA Careers', 'senna-finance');
                }

                $key = sanitize_title($name . '-' . $company);
                if ($key === '') {
                    $key = 'recruiter-' . ($index + 1);
                }

                if (!isset($recruiters[$key])) {
                    $initial = strtoupper(function_exists('mb_substr') ? mb_substr($name, 0, 1) : substr($name, 0, 1));
                    $recruiters[$key] = [
                        'name' => sanitize_text_field($name),
                        'company' => sanitize_text_field($company),
                        'photo' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'initial' => $initial !== '' ? $initial : 'R',
                        'message_url' => '',
                        'role_count' => 0,
                    ];
                }

                if ($recruiters[$key]['photo'] === '' && !empty($item['recruiter_photo'])) {
                    $recruiters[$key]['photo'] = esc_url_raw((string) $item['recruiter_photo']);
                }

                if ($recruiters[$key]['message_url'] === '' && !empty($item['recruiter_email'])) {
                    $recruiters[$key]['message_url'] = 'mailto:' . sanitize_email((string) $item['recruiter_email']);
                }

                $recruiters[$key]['role_count']++;
            }

            uasort($recruiters, static function ($left, $right) {
                $left_count = (int) ($left['role_count'] ?? 0);
                $right_count = (int) ($right['role_count'] ?? 0);

                if ($left_count === $right_count) {
                    return strcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
                }

                return $right_count <=> $left_count;
            });

            return array_slice(array_values($recruiters), 0, 8);
        }

        public function ajax_save_reddit_group_nav_prefs()
        {
            check_ajax_referer('sffc_crm_reddit_group_nav', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $order = isset($_POST['order']) && is_array($_POST['order']) ? wp_unslash($_POST['order']) : [];
            $pinned = isset($_POST['pinned']) && is_array($_POST['pinned']) ? wp_unslash($_POST['pinned']) : [];

            $payload = [
                'order' => array_values(array_filter(array_map('sanitize_title', $order))),
                'pinned' => array_values(array_filter(array_map('sanitize_title', $pinned))),
            ];

            update_user_meta(get_current_user_id(), 'sffc_crm_reddit_group_nav_prefs', $payload);

            wp_send_json_success(['preferences' => $payload]);
        }

        public function ajax_reddit_prepare_apply()
        {
            check_ajax_referer('sffc_crm_reddit_apply', 'nonce');

            $full_name = sanitize_text_field((string) ($_POST['full_name'] ?? ''));
            $email = sanitize_email((string) ($_POST['email'] ?? ''));
            $apply_url = esc_url_raw((string) ($_POST['apply_url'] ?? ''));
            $role_context = [
                'role_title' => sanitize_text_field((string) ($_POST['role_title'] ?? '')),
                'company_name' => sanitize_text_field((string) ($_POST['company_name'] ?? '')),
                'location' => sanitize_text_field((string) ($_POST['location'] ?? '')),
                'apply_url' => $apply_url,
                'senna_url' => esc_url_raw((string) ($_POST['senna_url'] ?? '')),
                'similar_roles_url' => esc_url_raw((string) ($_POST['similar_roles_url'] ?? '')),
            ];

            if ($full_name === '') {
                wp_send_json_error(['message' => __('Full name is required.', 'senna-finance')], 422);
            }

            if ($email === '' || !is_email($email)) {
                wp_send_json_error(['message' => __('Enter a valid email address.', 'senna-finance')], 422);
            }

            if ($apply_url === '' || !wp_http_validate_url($apply_url)) {
                wp_send_json_error(['message' => __('Application link unavailable.', 'senna-finance')], 422);
            }

            if (is_user_logged_in()) {
                $current_user = wp_get_current_user();
                if ($current_user instanceof \WP_User && !empty($current_user->user_email) && is_email($current_user->user_email)) {
                    $this->send_reddit_role_applied_email($current_user, $role_context);
                }

                wp_send_json_success([
                    'status' => 'logged_in',
                    'redirect' => $apply_url,
                    'message' => __('Opening application.', 'senna-finance'),
                ]);
            }

            $existing_user = get_user_by('email', $email);
            if ($existing_user) {
                $this->send_reddit_role_applied_email($existing_user, $role_context);

                wp_send_json_success([
                    'status' => 'exists',
                    'redirect' => $apply_url,
                    'message' => __('We found your MENA Careers account. Opening the application now.', 'senna-finance'),
                ]);
            }

            $parsed_name = $this->parse_full_name($full_name);
            $first_name = sanitize_text_field((string) ($parsed_name['first_name'] ?? ''));
            $last_name = sanitize_text_field((string) ($parsed_name['last_name'] ?? ''));

            $this->capture_membership_signup_lead([
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'application_url' => $apply_url,
                'role_title' => (string) ($role_context['role_title'] ?? ''),
                'company_name' => (string) ($role_context['company_name'] ?? ''),
                'source' => 'reddit_prepare_apply',
            ]);

            wp_send_json_success([
                'status' => 'lead_captured',
                'redirect' => home_url('/memberships/'),
                'message' => __('Continue to memberships to choose the plan that fits your search.', 'senna-finance'),
            ]);
        }

