        public function ajax_reddit_set_active_resume()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $upload_id = isset($_POST['upload_id']) ? absint($_POST['upload_id']) : 0;

            if ($upload_id <= 0) {
                wp_send_json_error(['message' => __('A valid resume is required.', 'senna-finance')], 422);
            }

            $resume = $this->get_crm_reddit_resume_upload($user_id, $upload_id);
            if (empty($resume)) {
                wp_send_json_error(['message' => __('That resume could not be found.', 'senna-finance')], 404);
            }

            update_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), $upload_id);
            update_user_meta($user_id, $this->get_crm_reddit_resume_source_preference_meta_key(), 'upload');

            $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            $this->maybe_queue_crm_reddit_cv_ats_scan($user_id, $resume_payload);
            $ats_state = $this->get_crm_reddit_dashboard_topbar_ats_state([], $resume_payload, $user_id);

            wp_send_json_success([
                'upload_id' => $upload_id,
                'markup' => $this->render_crm_reddit_profile_panel($user_id),
                'active_cv_text' => (string) ($resume_payload['cv_text'] ?? ''),
                'ats_state' => $ats_state,
                'review_markup' => $this->render_crm_reddit_dashboard_review_cv_view($user_id, $resume_payload, $this->get_crm_reddit_dashboard_default_jobs_post_id()),
            ]);
