        public function ajax_reddit_save_pasted_cv()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) wp_unslash($_POST['cv_text'] ?? ''));

            if ($cv_text === '') {
                wp_send_json_error(['message' => __('Paste your CV text to continue.', 'senna-finance')], 422);
            }

            $text_length = function_exists('mb_strlen') ? mb_strlen($cv_text) : strlen($cv_text);
            if ($text_length < 180) {
                wp_send_json_error(['message' => __('Paste a fuller version of your CV so MENA Careers has enough detail to score it properly.', 'senna-finance')], 422);
            }

            update_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), $cv_text);
            update_user_meta($user_id, $this->get_crm_reddit_resume_source_preference_meta_key(), 'pasted');

            $file_name = sanitize_file_name((string) wp_unslash($_POST['file_name'] ?? ''));
            $stored_upload_id = $this->maybe_store_crm_reddit_text_resume_upload($user_id, $cv_text, $file_name);
            if ($stored_upload_id > 0) {
                update_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), $stored_upload_id);
                update_user_meta($user_id, $this->get_crm_reddit_resume_source_preference_meta_key(), 'upload');
                $this->maybe_sync_crm_reddit_resume_upload_document($user_id, $stored_upload_id);
            }

            $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            $this->maybe_queue_crm_reddit_cv_ats_scan($user_id, $resume_payload);
            $ats_state = $this->get_crm_reddit_dashboard_topbar_ats_state([], $resume_payload, $user_id);

            wp_send_json_success([
                'message' => __('CV Saved! All good to go', 'senna-finance'),
                'upload_id' => $stored_upload_id,
                'markup' => $this->render_crm_reddit_profile_panel($user_id),
                'active_cv_text' => (string) ($resume_payload['cv_text'] ?? ''),
                'ats_state' => $ats_state,
                'review_markup' => $this->render_crm_reddit_dashboard_review_cv_view($user_id, $resume_payload, $this->get_crm_reddit_dashboard_default_jobs_post_id()),
            ]);
        }

