        public function ajax_reddit_generate_outreach()
        {
            check_ajax_referer('sffc_crm_reddit_generate_outreach', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $request = [
                'cv_source' => sanitize_text_field((string) wp_unslash($_POST['cv_source'] ?? 'active')),
                'cv_text' => sanitize_textarea_field((string) wp_unslash($_POST['cv_text'] ?? '')),
                'jobs_post_id' => absint($_POST['jobs_post_id'] ?? 0),
                'custom_role_title' => sanitize_text_field((string) wp_unslash($_POST['custom_role_title'] ?? '')),
                'outreach_context' => sanitize_key((string) wp_unslash($_POST['outreach_context'] ?? 'enquiring_about_role')),
                'target_channel' => sanitize_key((string) wp_unslash($_POST['target_channel'] ?? 'linkedin_inmail')),
                'recipient_name' => sanitize_text_field((string) wp_unslash($_POST['recipient_name'] ?? '')),
                'recipient_role' => sanitize_text_field((string) wp_unslash($_POST['recipient_role'] ?? '')),
                'user_context' => sanitize_textarea_field((string) wp_unslash($_POST['user_context'] ?? '')),
            ];

            if ($request['cv_source'] === '') {
                wp_send_json_error(['message' => __('Choose a CV source first.', 'senna-finance')], 422);
            }

            if ($request['target_channel'] === '') {
                wp_send_json_error(['message' => __('Choose a target channel first.', 'senna-finance')], 422);
            }

            if ($request['recipient_name'] === '') {
                wp_send_json_error(['message' => __('Enter the recipient name before generating the outreach.', 'senna-finance')], 422);
            }

            if (
                $request['outreach_context'] === 'enquiring_about_role'
                && $request['jobs_post_id'] <= 0
                && $request['custom_role_title'] === ''
            ) {
                wp_send_json_error(['message' => __('Choose a live role or enter a role title for this outreach.', 'senna-finance')], 422);
            }

            $context = $this->build_crm_reddit_outreach_context($user_id, $request);
            if (empty($context)) {
                wp_send_json_error(['message' => __('We could not build the outreach context right now.', 'senna-finance')], 422);
            }

            if (empty($context['cv_text'])) {
                wp_send_json_error(['message' => __('Choose a saved CV source first so MENA Careers can shape the outreach around your profile.', 'senna-finance')], 422);
            }

            $cache_key = 'sffc_reddit_outreach_v2_' . md5(wp_json_encode([
                'jobs_post_id' => (int) ($context['jobs_post_id'] ?? 0),
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'cv_hash' => md5((string) ($context['cv_text'] ?? '')),
                'context' => (string) ($context['outreach_context'] ?? ''),
                'target' => (string) ($context['target_channel'] ?? ''),
                'recipient_name' => (string) ($context['recipient_name'] ?? ''),
                'recipient_role' => (string) ($context['recipient_role'] ?? ''),
                'user_context' => (string) ($context['user_context'] ?? ''),
            ]));

            $cached_result = get_transient($cache_key);
            $result = [];
            $generated_with_claude = false;

            if (is_array($cached_result) && isset($cached_result['result'])) {
                $result = (array) ($cached_result['result'] ?? []);
                $generated_with_claude = !empty($cached_result['generated_with_claude']);
            } elseif (is_array($cached_result)) {
                $result = $cached_result;
            }

            if (!is_array($result) || empty($result['message']['body'])) {
                $result = $this->call_crm_reddit_outreach_claude($context);
                if (is_array($result) && !empty($result['message']['body'])) {
                    $generated_with_claude = true;
                } else {
                    $result = $this->build_crm_reddit_outreach_fallback($context);
                    $generated_with_claude = false;
                }
                set_transient($cache_key, [
                    'result' => $result,
                    'generated_with_claude' => $generated_with_claude,
                ], 12 * HOUR_IN_SECONDS);
            }

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_dashboard_outreach_results_markup($result, $context),
                'result' => $result,
                'generated_with_claude' => $generated_with_claude,
            ]);
        }

        public function ajax_reddit_dashboard_tab()
        {
            check_ajax_referer('sffc_crm_reddit_dashboard_tab', 'nonce');

            $href = esc_url_raw((string) wp_unslash($_POST['href'] ?? ''));
            $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
            $per_page = max(12, min(36, absint($_POST['per_page'] ?? 18)));
            $fallback_role = sanitize_text_field((string) wp_unslash($_POST['fallback_role'] ?? 'Investment Associate'));
            $current_url = esc_url_raw((string) wp_unslash($_POST['current_url'] ?? ''));

            $query_args = [];
            if ($href !== '') {
                $query = (string) wp_parse_url($href, PHP_URL_QUERY);
                if ($query !== '') {
                    parse_str($query, $query_args);
                }
            }

            $allowed_query_keys = [
                'dashboard_tab',
                'matches_filter',
                'metrics_window',
                'matches_page',
                'sffc_reddit_search',
                'discovery_filter',
                'recruiter_region',
                'recruiter_industry',
                'recruiter_skill',
            ];

            $original_get = $_GET;
            foreach ($allowed_query_keys as $query_key) {
                if (array_key_exists($query_key, $query_args)) {
                    $_GET[$query_key] = is_array($query_args[$query_key]) ? '' : (string) $query_args[$query_key];
                } else {
                    unset($_GET[$query_key]);
                }
            }

            try {
                $markup = $this->render_crm_reddit_dashboard_partial_markup([
                    'jobs_post_id' => $jobs_post_id,
                    'per_page' => $per_page,
                    'fallback_role' => $fallback_role,
                    'current_url' => $current_url,
                    'dashboard_tab' => sanitize_key((string) ($query_args['dashboard_tab'] ?? 'recruiter-matches')),
                    'matches_filter' => sanitize_key((string) ($query_args['matches_filter'] ?? 'highest-match')),
                    'metrics_window' => sanitize_key((string) ($query_args['metrics_window'] ?? 'month')),
                    'matches_page' => max(1, absint($query_args['matches_page'] ?? 1)),
                    'search_term' => sanitize_text_field((string) ($query_args['sffc_reddit_search'] ?? '')),
                ]);
            } finally {
                $_GET = $original_get;
            }

            wp_send_json_success([
                'markup' => $markup,
            ]);
        }

