        public function ajax_reddit_cancel_subscription_request()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user = wp_get_current_user();
            if (!$user instanceof \WP_User || (int) $user->ID <= 0) {
                wp_send_json_error(['message' => __('We could not identify your account.', 'senna-finance')], 400);
            }

            $reason = trim((string) wp_unslash($_POST['reason'] ?? ''));
            $delete_account = !empty($_POST['delete_account']);

            if ($reason === '') {
                wp_send_json_error(['message' => __('Please explain why you want to cancel your subscription.', 'senna-finance')], 422);
            }

            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            if ($admin_email === '') {
                wp_send_json_error(['message' => __('Admin email is not configured.', 'senna-finance')], 500);
            }

            $subject = __('Subscription cancellation request', 'senna-finance');
            $message_lines = [
                'Subscription cancellation request',
                '',
                'User ID: ' . (int) $user->ID,
                'Name: ' . sanitize_text_field((string) $user->display_name),
                'Email: ' . sanitize_email((string) $user->user_email),
                'Delete account and all data: ' . ($delete_account ? 'Yes' : 'No'),
                '',
                'Reason:',
                $reason,
            ];

            $headers = [];
            if (!empty($user->user_email) && is_email($user->user_email)) {
                $headers[] = 'Reply-To: ' . sanitize_email((string) $user->user_email);
            }

            $sent = wp_mail($admin_email, $subject, implode("\n", $message_lines), $headers);
            if (!$sent) {
                wp_send_json_error(['message' => __('We could not send your request right now. Please try again.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => $delete_account
                    ? __('Your cancellation and data deletion request has been sent to the admin team.', 'senna-finance')
                    : __('Your cancellation request has been sent to the admin team.', 'senna-finance'),
            ]);
        }

        public function ajax_reddit_expert_support_request()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Please sign in to request expert support.', 'senna-finance')], 403);
            }

            $user = wp_get_current_user();
            if (!$user instanceof \WP_User || (int) $user->ID <= 0) {
                wp_send_json_error(['message' => __('We could not identify your account.', 'senna-finance')], 400);
            }

            $support_types = array_values(array_filter(array_map('sanitize_key', (array) ($_POST['support_types'] ?? []))));
            $request_call = !empty($_POST['request_call']);
            $call_reason = sanitize_key((string) wp_unslash($_POST['call_reason'] ?? ''));
            $preferred_timing = sanitize_text_field((string) wp_unslash($_POST['preferred_timing'] ?? ''));
            $details = trim((string) wp_unslash($_POST['details'] ?? ''));

            if (empty($support_types)) {
                wp_send_json_error(['message' => __('Choose at least one type of expert support.', 'senna-finance')], 422);
            }

            if ($details === '') {
                wp_send_json_error(['message' => __('Please explain what you want help with.', 'senna-finance')], 422);
            }

            if ($request_call && $call_reason === '') {
                wp_send_json_error(['message' => __('Choose why you want a call so we can route it properly.', 'senna-finance')], 422);
            }

            $support_labels = $this->get_crm_reddit_dashboard_expert_support_type_labels();
            $call_reason_labels = $this->get_crm_reddit_dashboard_expert_support_call_reason_labels();
            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            if ($admin_email === '') {
                wp_send_json_error(['message' => __('Admin email is not configured.', 'senna-finance')], 500);
            }

            $selected_support = array_map(static function ($type) use ($support_labels) {
                return $support_labels[$type] ?? $type;
            }, $support_types);

            $admin_subject = sprintf(
                __('Expert support request from %s', 'senna-finance'),
                sanitize_text_field((string) $user->display_name)
            );
            $admin_message = $this->build_reddit_service_request_email([
                'eyebrow' => __('Support Request', 'senna-finance'),
                'headline' => __('New expert support request', 'senna-finance'),
                'intro' => __('A MENA Careers member has asked for hands-on support inside the community workspace. Review the request details below and reply directly if you need clarification.', 'senna-finance'),
                'rows' => array_filter([
                    [
                        'label' => __('Member', 'senna-finance'),
                        'value' => esc_html(sanitize_text_field((string) $user->display_name)),
                    ],
                    [
                        'label' => __('Email', 'senna-finance'),
                        'value' => esc_html(sanitize_email((string) $user->user_email)),
                    ],
                    [
                        'label' => __('Support Requested', 'senna-finance'),
                        'value' => esc_html(implode(', ', $selected_support)),
                    ],
                    [
                        'label' => __('Requested Call', 'senna-finance'),
                        'value' => $request_call ? esc_html__('Yes', 'senna-finance') : esc_html__('No', 'senna-finance'),
                    ],
                    $request_call ? [
                        'label' => __('Call Reason', 'senna-finance'),
                        'value' => esc_html((string) ($call_reason_labels[$call_reason] ?? $call_reason)),
                    ] : null,
                    $request_call ? [
                        'label' => __('Preferred Timing', 'senna-finance'),
                        'value' => esc_html($preferred_timing !== '' ? $preferred_timing : __('Not provided', 'senna-finance')),
                    ] : null,
                    [
                        'label' => __('Profile', 'senna-finance'),
                        'value' => '<a href="' . esc_url(admin_url('user-edit.php?user_id=' . (int) $user->ID)) . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html__('Open user profile', 'senna-finance') . '</a>',
                    ],
                ]),
                'body_label' => __('Request Details', 'senna-finance'),
                'body_copy' => $details,
                'footer_note' => esc_html__('This support request was submitted from the community Profile workspace.', 'senna-finance'),
            ]);

            $user_subject = __('We received your MENA Careers support request', 'senna-finance');
            $user_message = $this->build_reddit_service_request_email([
                'eyebrow' => __('Support Confirmed', 'senna-finance'),
                'headline' => __('Your support request is with the MENA Careers team', 'senna-finance'),
                'intro' => sprintf(__('Hi %s, we have received your support request. A member of the MENA Careers team will review it and come back to you shortly by email.', 'senna-finance'), trim((string) ($user->first_name ?: $user->display_name ?: $user->user_login))),
                'rows' => array_filter([
                    [
                        'label' => __('Support Requested', 'senna-finance'),
                        'value' => esc_html(implode(', ', $selected_support)),
                    ],
                    [
                        'label' => __('Requested Call', 'senna-finance'),
                        'value' => $request_call ? esc_html__('Yes', 'senna-finance') : esc_html__('No', 'senna-finance'),
                    ],
                    $request_call ? [
                        'label' => __('Preferred Timing', 'senna-finance'),
                        'value' => esc_html($preferred_timing !== '' ? $preferred_timing : __('Not provided', 'senna-finance')),
                    ] : null,
                ]),
                'body_label' => __('Your Brief', 'senna-finance'),
                'body_copy' => $details,
                'note_html' => esc_html__('MENA Careers will use the context in your request to route you to the most relevant review or support path.', 'senna-finance'),
                'footer_note' => esc_html__('You are receiving this because you asked the MENA Careers team for expert support from your community profile.', 'senna-finance'),
            ]);

            $sent = wp_mail($admin_email, $admin_subject, $admin_message, $this->get_reddit_email_headers_with_reply_to((string) $user->display_name, (string) $user->user_email));
            if (!$sent) {
                wp_send_json_error(['message' => __('We could not send your support request right now. Please try again.', 'senna-finance')], 500);
            }

            if (!wp_mail((string) $user->user_email, $user_subject, $user_message, $this->get_reddit_email_headers())) {
                wp_send_json_error(['message' => __('We received your request, but could not send the confirmation email right now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => __('Your expert support request has been sent. The team will review it and get back to you.', 'senna-finance'),
            ]);
        }

        public function ajax_cv_match_expert_cv_review_request()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

