            if (!$user instanceof \WP_User || (int) $user->ID <= 0) {
                wp_send_json_error(['message' => __('We could not identify your account.', 'senna-finance')], 400);
            }

            $cv_source = sanitize_text_field((string) wp_unslash($_POST['cv_source'] ?? ''));
            $target_roles = trim((string) wp_unslash($_POST['target_roles'] ?? ''));
            $review_notes = trim((string) wp_unslash($_POST['review_notes'] ?? ''));

            if ($cv_source === '') {
                wp_send_json_error(['message' => __('Choose which CV you want reviewed.', 'senna-finance')], 422);
            }

            if ($target_roles === '') {
                wp_send_json_error(['message' => __('Tell us which roles you are targeting.', 'senna-finance')], 422);
            }

            $resume_payload = $this->get_crm_reddit_active_resume_text((int) $user->ID);
            $cv_options = $this->get_crm_reddit_dashboard_outreach_cv_options((int) $user->ID, $resume_payload);
            $cv_label = $cv_source;
            foreach ($cv_options as $option) {
                if ((string) ($option['value'] ?? '') === $cv_source) {
                    $cv_label = (string) ($option['label'] ?? $cv_source);
                    break;
                }
            }

            $selected_cv_payload = $this->resolve_crm_reddit_dashboard_outreach_cv_text((int) $user->ID, $cv_source);
            $selected_cv_text = trim((string) ($selected_cv_payload['cv_text'] ?? ''));
