                wp_send_json_error(['message' => __('That CV could not be found or is empty. Choose another CV and try again.', 'senna-finance')], 422);
            }

            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            if ($admin_email === '') {
                wp_send_json_error(['message' => __('Admin email is not configured.', 'senna-finance')], 500);
            }

            $subject = sprintf(
                /* translators: %s: user display name */
                __('Expert Career Assessment request from %s', 'senna-finance'),
                sanitize_text_field((string) $user->display_name)
            );
            $admin_message = $this->build_reddit_service_request_email([
                'eyebrow' => __('Career Assessment Request', 'senna-finance'),
                'headline' => __('New expert Career Assessment request', 'senna-finance'),
                'intro' => __('A MENA Careers member has requested an expert Career Assessment from their profile workspace. Review the target roles and selected CV below.', 'senna-finance'),
                'rows' => [
                    [
                        'label' => __('Member', 'senna-finance'),
                        'value' => esc_html(sanitize_text_field((string) $user->display_name)),
                    ],
                    [
                        'label' => __('Email', 'senna-finance'),
                        'value' => esc_html(sanitize_email((string) $user->user_email)),
                    ],
                    [
                        'label' => __('Selected CV', 'senna-finance'),
                        'value' => esc_html($cv_label),
                    ],
                    [
                        'label' => __('CV Source', 'senna-finance'),
                        'value' => esc_html($cv_source),
                    ],
                    [
                        'label' => __('CV Word Count', 'senna-finance'),
                        'value' => esc_html((string) str_word_count(wp_strip_all_tags($selected_cv_text))),
                    ],
                    [
                        'label' => __('Target Roles', 'senna-finance'),
                        'value' => esc_html($target_roles),
                    ],
                    [
                        'label' => __('Profile', 'senna-finance'),
                        'value' => '<a href="' . esc_url(admin_url('user-edit.php?user_id=' . (int) $user->ID)) . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html__('Open user profile', 'senna-finance') . '</a>',
                    ],
                ],
                'body_label' => __('Selected CV Text', 'senna-finance'),
                'body_copy' => $selected_cv_text,
                'note_html' => $review_notes !== '' ? '<strong>' . esc_html__('Additional notes:', 'senna-finance') . '</strong><br>' . nl2br(esc_html($review_notes)) : '',
