        public function ajax_linkedin_jobs_profile_review_request()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $current_user = is_user_logged_in() ? wp_get_current_user() : null;
            $user_id = $current_user instanceof \WP_User ? (int) $current_user->ID : 0;
            if ($user_id <= 0 || !$this->current_user_has_crm_editorial_paid_membership_access()) {
                wp_send_json_error([
                    'message' => __('Join MENA Careers to request an expert Career Assessment.', 'senna-finance'),
                    'redirect' => home_url('/memberships/'),
                ], 403);
            }

            $posted_name = sanitize_text_field((string) wp_unslash($_POST['candidate_name'] ?? ''));
            $posted_email = sanitize_email((string) wp_unslash($_POST['candidate_email'] ?? ''));
            $candidate_name = $user_id > 0
                ? sanitize_text_field((string) ($current_user->display_name ?: $current_user->user_login))
                : $posted_name;
            $candidate_email = $user_id > 0
                ? sanitize_email((string) $current_user->user_email)
                : $posted_email;
            $linkedin_profile_url = esc_url_raw((string) wp_unslash($_POST['linkedin_profile_url'] ?? ''));
            $review_notes = trim((string) wp_unslash($_POST['review_notes'] ?? ''));
            $role_title = sanitize_text_field((string) wp_unslash($_POST['role_title'] ?? ''));
            $company = sanitize_text_field((string) wp_unslash($_POST['company'] ?? ''));
            $location = sanitize_text_field((string) wp_unslash($_POST['location'] ?? ''));
            $post_id = absint($_POST['crm_post_id'] ?? 0);
            $selected_package = sanitize_key((string) wp_unslash($_POST['review_package'] ?? ''));
            $package = $this->get_linkedin_jobs_profile_review_package($selected_package);

            if ($candidate_name === '') {
                wp_send_json_error(['message' => __('Add your name so the assessor knows whose profile to assess.', 'senna-finance')], 422);
            }

            if ($candidate_email === '' || !is_email($candidate_email)) {
                wp_send_json_error(['message' => __('Add a valid email so we can send the expert review.', 'senna-finance')], 422);
            }

            if ($linkedin_profile_url === '' || stripos($linkedin_profile_url, 'linkedin.com/') === false) {
                wp_send_json_error(['message' => __('Paste a valid LinkedIn profile URL to continue.', 'senna-finance')], 422);
            }

            if (empty($_FILES['cv_file'])) {
                wp_send_json_error(['message' => __('Upload your CV so the recruiter can review the full profile evidence.', 'senna-finance')], 422);
            }

            if (empty($package)) {
                wp_send_json_error(['message' => __('Choose the Career Assessment package you want to continue with.', 'senna-finance')], 422);
            }

            $upload_result = $this->extract_crm_apply_chat_cv_text_from_upload($_FILES['cv_file'], 'full');
            if (empty($upload_result['success'])) {
                wp_send_json_error([
                    'message' => (string) ($upload_result['message'] ?? __('Unable to read that CV file.', 'senna-finance')),
                ], 422);
            }

            $cv_text = trim((string) ($upload_result['text'] ?? ''));
            $cv_file_name = sanitize_file_name((string) ($upload_result['file_name'] ?? 'CV upload'));
            if ($cv_text === '') {
                wp_send_json_error(['message' => __('We could not read text from that CV. Upload a selectable PDF/DOCX or paste key details in the notes.', 'senna-finance')], 422);
            }

            $cv_preview = trim(wp_strip_all_tags(substr($cv_text, 0, 4500)));
            $word_count = str_word_count(wp_strip_all_tags($cv_text));
            $role_context = implode(' · ', array_filter([$role_title, $company, $location]));
            $pending_payload = [
                'candidate_name' => $candidate_name,
                'candidate_email' => $candidate_email,
                'linkedin_profile_url' => $linkedin_profile_url,
                'review_notes' => $review_notes,
                'role_title' => $role_title,
                'company' => $company,
                'location' => $location,
                'role_context' => $role_context,
                'post_id' => $post_id,
                'user_id' => $user_id,
                'cv_text' => $cv_text,
                'cv_preview' => $cv_preview,
                'word_count' => $word_count,
                'cv_file_name' => $cv_file_name,
                'package_key' => (string) $package['key'],
                'package_label' => (string) $package['label'],
                'package_membership_id' => (int) $package['membership_id'],
                'package_price' => '',
                'created_at' => current_time('mysql'),
            ];

            if (!$this->send_linkedin_jobs_profile_review_admin_email($pending_payload)) {
                wp_send_json_error(['message' => __('We could not send your assessment request right now. Please try again.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => __('Your Career Assessment request has been sent to the MENA Careers team.', 'senna-finance'),
                'cv_preview' => $cv_preview,
                'word_count' => $word_count,
                'file_name' => $cv_file_name,
                'selected_package' => (string) $package['key'],
            ]);
        }

        private function get_linkedin_jobs_profile_review_packages()
        {
            $currency = $this->get_user_currency_preference();
            $packages = [
                [
                    'key' => 'full',
                    'label' => __('Full Career Assessment', 'senna-finance'),
                    'subtitle' => __('CV, LinkedIn, and role-fit report reviewed together.', 'senna-finance'),
