        private function get_linkedin_jobs_profile_review_package($key)
        {
            $key = sanitize_key((string) $key);
            foreach ($this->get_linkedin_jobs_profile_review_packages() as $package) {
                if ((string) $package['key'] === $key) {
                    return $package;
                }
            }

            return null;
        }

        private function get_linkedin_jobs_profile_review_pending_key($email)
        {
            return 'sffc_profile_review_pending_' . md5(strtolower(trim((string) $email)));
        }

        private function store_linkedin_jobs_profile_review_pending_request($email, $payload)
        {
            set_transient($this->get_linkedin_jobs_profile_review_pending_key($email), $payload, 90 * DAY_IN_SECONDS);
        }

        public function handle_linkedin_jobs_profile_review_memberpress_event($event)
        {
            $transaction = is_object($event) && method_exists($event, 'get_data') ? $event->get_data() : $event;
            $this->handle_linkedin_jobs_profile_review_memberpress_transaction($transaction);
        }

        public function handle_linkedin_jobs_profile_review_memberpress_transaction($transaction)
        {
            $user_id = 0;
            $product_id = 0;
            $email = '';

            if (is_object($transaction)) {
                $user_id = absint($transaction->user_id ?? 0);
                $product_id = absint($transaction->product_id ?? ($transaction->membership_id ?? 0));
                $email = sanitize_email((string) ($transaction->user_email ?? ''));
            }

            if ($user_id > 0) {
                $user = get_user_by('id', $user_id);
                if ($user instanceof \WP_User) {
                    $email = sanitize_email((string) $user->user_email);
                }
            }

            if ($email === '') {
                return;
            }

            $pending_key = $this->get_linkedin_jobs_profile_review_pending_key($email);
            $pending = get_transient($pending_key);
            if (empty($pending) || !is_array($pending)) {
                return;
            }

            $expected_product_id = absint($pending['package_membership_id'] ?? 0);
            if ($product_id > 0 && $expected_product_id > 0 && $product_id !== $expected_product_id) {
                return;
            }

            if ($this->send_linkedin_jobs_profile_review_admin_email($pending)) {
                delete_transient($pending_key);
            }
        }

        private function send_linkedin_jobs_profile_review_admin_email($pending)
        {
            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            if ($admin_email === '') {
                return false;
            }

            $candidate_name = sanitize_text_field((string) ($pending['candidate_name'] ?? 'Candidate'));
            $candidate_email = sanitize_email((string) ($pending['candidate_email'] ?? ''));
            $linkedin_profile_url = esc_url_raw((string) ($pending['linkedin_profile_url'] ?? ''));
            $cv_file_name = sanitize_file_name((string) ($pending['cv_file_name'] ?? 'CV upload'));
            $word_count = absint($pending['word_count'] ?? 0);
            $role_context = sanitize_text_field((string) ($pending['role_context'] ?? ''));
            $post_id = absint($pending['post_id'] ?? 0);
            $package_label = sanitize_text_field((string) ($pending['package_label'] ?? 'Career Assessment'));
            $package_price = sanitize_text_field((string) ($pending['package_price'] ?? ''));
            $review_notes = trim((string) ($pending['review_notes'] ?? ''));
            $cv_text = trim((string) ($pending['cv_text'] ?? ''));

            $admin_rows = [
                [
                    'label' => __('Package', 'senna-finance'),
                    'value' => esc_html(trim($package_label . ($package_price !== '' ? ' · ' . $package_price : ''))),
                ],
                [
                    'label' => __('Candidate', 'senna-finance'),
                    'value' => esc_html($candidate_name),
                ],
                [
                    'label' => __('Email', 'senna-finance'),
                    'value' => '<a href="mailto:' . esc_attr($candidate_email) . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html($candidate_email) . '</a>',
                ],
                [
                    'label' => __('LinkedIn URL', 'senna-finance'),
                    'value' => '<a href="' . esc_url($linkedin_profile_url) . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html($linkedin_profile_url) . '</a>',
                ],
                [
                    'label' => __('CV File', 'senna-finance'),
                    'value' => esc_html($cv_file_name),
                ],
                [
                    'label' => __('CV Word Count', 'senna-finance'),
                    'value' => esc_html((string) $word_count),
                ],
            ];

            if ($role_context !== '') {
                $admin_rows[] = [
                    'label' => __('Role Context', 'senna-finance'),
                    'value' => esc_html($role_context),
                ];
            }

            if ($post_id > 0) {
                $admin_rows[] = [
                    'label' => __('CRM Post', 'senna-finance'),
                    'value' => '<a href="' . esc_url(admin_url('post.php?post=' . $post_id . '&action=edit')) . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html__('Open role in admin', 'senna-finance') . '</a>',
                ];
            }

            $admin_message = $this->build_reddit_service_request_email([
                'eyebrow' => __('Expert Career Assessment', 'senna-finance'),
                'headline' => __('New Career Assessment request', 'senna-finance'),
                'intro' => __('A paying member requested an expert Career Assessment. Review the CV, LinkedIn profile, role context, evidence gaps, and positioning for recruiter readability.', 'senna-finance'),
                'rows' => $admin_rows,
                'body_label' => __('Extracted CV Text', 'senna-finance'),
                'body_copy' => $cv_text,
                'note_html' => $review_notes !== '' ? '<strong>' . esc_html__('Candidate notes:', 'senna-finance') . '</strong><br>' . nl2br(esc_html($review_notes)) : esc_html__('No additional notes were provided.', 'senna-finance'),
                'footer_note' => esc_html__('This request was submitted by a logged-in paying MENA Careers member.', 'senna-finance'),
            ]);

            $admin_subject = sprintf(
                __('Career Assessment request from %s', 'senna-finance'),
                $candidate_name
            );

            return (bool) wp_mail($admin_email, $admin_subject, $admin_message, $this->get_reddit_email_headers_with_reply_to($candidate_name, $candidate_email));
        }

