        public function ajax_reddit_dashboard_send_message()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $body = wp_kses_post((string) wp_unslash($_POST['body'] ?? ''));

            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Conversation required.', 'senna-finance')], 400);
            }

            if (trim(wp_strip_all_tags($body)) === '') {
                wp_send_json_error(['message' => __('Message content required.', 'senna-finance')], 400);
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-message.php';

            $conversation_model = new SFFC_CRM_Conversation();
            $message_model = new SFFC_CRM_Message();
            $conversation = $conversation_model->get($conversation_id);

            if (empty($conversation) || (int) ($conversation['user_id'] ?? 0) !== $user_id) {
                wp_send_json_error(['message' => __('Conversation not found.', 'senna-finance')], 404);
            }

            $member_recipient_id = $this->get_crm_reddit_dashboard_member_conversation_target_id((array) $conversation);

            $user = wp_get_current_user();
            $message_id = $message_model->create_outbound($conversation_id, [
                'channel' => 'manual',
                'subject' => sanitize_text_field((string) ($conversation['subject'] ?? __('MENA Careers message', 'senna-finance'))),
                'body_html' => $body,
                'body_text' => wp_strip_all_tags($body),
                'from_email' => (string) $user->user_email,
                'from_name' => (string) ($user->display_name ?: $user->user_login),
            ]);

            if (is_wp_error($message_id)) {
                wp_send_json_error(['message' => $message_id->get_error_message()], 400);
            }

            if ($member_recipient_id > 0) {
                $recipient_conversation_id = $this->find_or_create_crm_reddit_dashboard_member_conversation((int) $member_recipient_id, $user_id);
                if ($recipient_conversation_id > 0) {
                    $message_model->create_inbound($recipient_conversation_id, [
                        'channel' => 'manual',
                        'subject' => sanitize_text_field((string) ($conversation['subject'] ?? __('MENA Careers message', 'senna-finance'))),
                        'body_html' => $body,
                        'body_text' => wp_strip_all_tags($body),
                        'from_email' => (string) $user->user_email,
                        'from_name' => (string) ($user->display_name ?: $user->user_login),
                        'to_email' => (string) (get_userdata($member_recipient_id)->user_email ?? ''),
                        'to_name' => (string) (get_userdata($member_recipient_id)->display_name ?? ''),
                    ]);
                    $this->clear_crm_reddit_dashboard_runtime_caches((int) $member_recipient_id);
                }
            }

            $this->maybe_notify_admin_of_crm_reddit_dashboard_message($user_id, $conversation_id, $body);
            $this->clear_crm_reddit_dashboard_runtime_caches($user_id);

            wp_send_json_success(array_merge(
                [
                    'message' => __('Message sent.', 'senna-finance'),
                ],
                $this->get_crm_reddit_dashboard_inbox_payload($user_id, $conversation_id)
            ));
        }

        public function ajax_reddit_dashboard_message_users()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $search = sanitize_text_field((string) wp_unslash($_POST['search'] ?? ''));
            $users = $this->get_crm_reddit_dashboard_messageable_users($user_id, $search, 8);

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_dashboard_message_user_options($users),
            ]);
        }

        public function ajax_reddit_dashboard_start_message()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $recipient_user_id = absint($_POST['recipient_user_id'] ?? 0);
            if ($recipient_user_id <= 0 || $recipient_user_id === $user_id) {
                wp_send_json_error(['message' => __('Select a valid member.', 'senna-finance')], 422);
            }

            if (!$this->is_crm_reddit_dashboard_messageable_user($recipient_user_id)) {
                wp_send_json_error(['message' => __('That member cannot be messaged right now.', 'senna-finance')], 404);
            }

            $conversation_id = $this->find_or_create_crm_reddit_dashboard_member_conversation($user_id, $recipient_user_id);
            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Could not start that conversation.', 'senna-finance')], 500);
            }

            $this->clear_crm_reddit_dashboard_runtime_caches($user_id);

            wp_send_json_success(array_merge(
                [
                    'message' => __('Conversation ready.', 'senna-finance'),
                    'conversation_id' => $conversation_id,
                ],
                $this->get_crm_reddit_dashboard_inbox_payload($user_id, $conversation_id)
            ));
        }

        public function ajax_reddit_match_explainer()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $wp_post_id = absint($_POST['wp_post_id'] ?? 0);
            $crm_post_id = absint($_POST['crm_post_id'] ?? 0);

            if ($wp_post_id <= 0 && $crm_post_id <= 0) {
                wp_send_json_error(['message' => __('A valid role is required.', 'senna-finance')], 422);
            }

            $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            if (empty($resume_payload['has_cv']) || empty($resume_payload['cv_text'])) {
                wp_send_json_error(['message' => __('Add a CV first to explain the match.', 'senna-finance')], 422);
            }

            $context = $this->build_crm_reddit_dashboard_match_explainer_context($user_id, $wp_post_id, $crm_post_id, $resume_payload);
            if (empty($context)) {
                wp_send_json_error(['message' => __('We could not build the match context for this role.', 'senna-finance')], 404);
            }

            $cv_profile = $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true);
            $explanation = $this->get_or_generate_crm_reddit_dashboard_match_explanation($context, $cv_profile);

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_dashboard_match_explainer_markup($explanation, $context),
            ]);
        }

        public function ajax_reddit_ats_explainer()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            if (empty($resume_payload['has_cv']) || empty($resume_payload['cv_text'])) {
                wp_send_json_error(['message' => __('Add a CV first to generate an ATS explanation.', 'senna-finance')], 422);
            }

            $cv_profile = $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true);
            if (empty($cv_profile)) {
                $cv_profile = $this->build_crm_reddit_cv_ats_fallback((string) ($resume_payload['cv_text'] ?? ''));
            }

            $explanation = $this->sanitize_crm_reddit_dashboard_ats_explanation((array) ($cv_profile['ats_explainer'] ?? []));
            if (empty($explanation['summary'])) {
                $explanation = $this->sanitize_crm_reddit_dashboard_ats_explanation(
                    $this->build_crm_reddit_dashboard_ats_explainer_fallback($resume_payload, $cv_profile)
                );
            }

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_dashboard_ats_explainer_markup($explanation, $cv_profile),
            ]);
        }

        private function build_crm_reddit_dashboard_match_explainer_context($user_id, $wp_post_id, $crm_post_id, array $resume_payload = [])
        {
            $user_id = (int) $user_id;
            $wp_post_id = (int) $wp_post_id;
            $crm_post_id = (int) $crm_post_id;
            $item = [];
            $job_description = '';
            $requirements = [];
            $skills = [];
            $keywords = [];

            if ($wp_post_id > 0) {
                $item = (array) $this->get_crm_reddit_jobs_item($wp_post_id);
                $networking_context = $this->build_crm_reddit_networking_context($wp_post_id);
                if (is_array($networking_context)) {
                    $job_description = trim((string) ($networking_context['job_description'] ?? ''));
                    $requirements = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($networking_context['requirements'] ?? [])))));
                    $skills = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($networking_context['skills'] ?? [])))));
                    $keywords = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($networking_context['keywords'] ?? [])))));
                    if ($crm_post_id <= 0) {
                        $crm_post_id = (int) ($networking_context['crm_post_id'] ?? 0);
                    }
                }
            }

            if (empty($item) && $crm_post_id > 0) {
                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get((int) $crm_post_id);
                if (!empty($crm_post) && is_array($crm_post)) {
                    $item = (array) $this->build_crm_reddit_dashboard_crm_item($crm_post);
                    $requirements_context = $post_model->get_full_detail((int) $crm_post_id, $user_id);
                    if (!empty($requirements_context) && is_array($requirements_context)) {
                        if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                            require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                        }
                        if (function_exists('sffc_build_crm_jd_text_for_analysis')) {
                            $job_description = trim((string) sffc_build_crm_jd_text_for_analysis($requirements_context));
                        }
                        foreach ((array) ($requirements_context['requirements'] ?? []) as $requirement) {
                            $value = is_array($requirement)
                                ? (string) ($requirement['label'] ?? $requirement['text'] ?? $requirement['requirement'] ?? '')
                                : (string) $requirement;
                            $value = sanitize_text_field(trim($value));
                            if ($value !== '') {
                                $requirements[] = $value;
                            }
                        }
                        foreach ((array) ($requirements_context['skills_mentioned'] ?? []) as $skill) {
                            $value = is_array($skill)
                                ? (string) ($skill['skill'] ?? $skill['name'] ?? $skill['label'] ?? '')
                                : (string) $skill;
                            $value = sanitize_text_field(trim($value));
                            if ($value !== '') {
                                $skills[] = $value;
                            }
                        }
                    }
                    $keywords = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) $post_model->get_keywords((int) $crm_post_id)))));
                }
            }

            if (empty($item)) {
                return [];
            }

            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $match_score = $cv_text !== ''
                ? $this->build_crm_reddit_dashboard_match_score($item, $cv_text, $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true))
                : 0;

            return [
                'user_id' => $user_id,
                'wp_post_id' => (int) ($item['wp_post_id'] ?? $wp_post_id),
                'crm_post_id' => (int) ($item['crm_post_id'] ?? $crm_post_id),
                'role_title' => (string) ($item['role_title'] ?? ''),
                'company' => (string) ($item['company'] ?? ''),
                'location' => (string) ($item['location'] ?? ''),
                'seniority' => (string) ($item['seniority'] ?? ''),
                'industry' => $this->get_crm_reddit_dashboard_match_industry_label($item),
                'keywords' => array_values(array_slice(array_unique(array_merge($keywords, (array) ($item['keywords'] ?? []))), 0, 12)),
                'skills' => array_values(array_slice(array_unique($skills), 0, 10)),
                'requirements' => array_values(array_slice(array_unique($requirements), 0, 10)),
                'job_description' => $job_description !== '' ? $job_description : wp_strip_all_tags((string) ($item['description_html'] ?? '')),
                'cv_text' => $cv_text,
                'cv_source_hash' => md5($cv_text),
                'match_score' => $match_score,
            ];
        }

        private function get_or_generate_crm_reddit_dashboard_match_explanation(array $context, array $cv_profile = [])
        {
            $cache_key = 'sffc_crm_match_explainer_v1_' . md5(wp_json_encode([
                'user_id' => (int) ($context['user_id'] ?? 0),
                'wp_post_id' => (int) ($context['wp_post_id'] ?? 0),
                'crm_post_id' => (int) ($context['crm_post_id'] ?? 0),
                'cv_hash' => (string) ($context['cv_source_hash'] ?? ''),
                'plugin_version' => $this->get_crm_reddit_cv_ats_scan_plugin_version(),
                'scan_version' => $this->get_crm_reddit_cv_ats_scan_version(),
            ]));
            $cached = get_transient($cache_key);
            if (is_array($cached) && !empty($cached['summary'])) {
                return $cached;
            }

            $explanation = $this->call_crm_reddit_dashboard_match_explainer_claude($context, $cv_profile);
            if (empty($explanation['summary'])) {
                $explanation = $this->build_crm_reddit_dashboard_match_explainer_fallback($context, $cv_profile);
            }

            set_transient($cache_key, $explanation, 12 * HOUR_IN_SECONDS);

            return $explanation;
        }

        private function build_crm_reddit_dashboard_ats_explainer_fallback(array $resume_payload = [], array $cv_profile = [])
        {
            $score = max(0, min(100, (int) ($cv_profile['score'] ?? 0)));
            $summary = trim((string) ($cv_profile['summary'] ?? ''));
            $strength = trim((string) ($cv_profile['top_strength'] ?? ''));
            $gap = trim((string) ($cv_profile['top_gap'] ?? ''));

            return [
                'summary' => $summary !== ''
                    ? $summary
                    : sprintf(__('This ATS score reflects structure, finance-language visibility, quantified impact, and how clearly the CV signals the roles it is targeting. The current score is %d%%.', 'senna-finance'), $score),
                'strengths' => array_values(array_filter([
                    $strength !== '' ? $strength : __('Finance experience and role fit are already visible.', 'senna-finance'),
                    !empty($cv_profile['keywords']) ? __('Relevant finance keywords are already present in the CV.', 'senna-finance') : '',
                ])),
                'gaps' => array_values(array_filter([
                    $gap !== '' ? $gap : __('The top of the CV could be sharper and more recruiter-readable.', 'senna-finance'),
                ])),
                'next_steps' => [
                    __('Tighten the opening profile so the role target is obvious in the first lines.', 'senna-finance'),
                    __('Add one or two clearer quantified outcomes near the most relevant experience.', 'senna-finance'),
                    __('Mirror the exact finance language you want recruiters to search for.', 'senna-finance'),
                ],
            ];
        }

        private function sanitize_crm_reddit_dashboard_ats_explanation(array $explanation = [])
        {
            $summary = $this->dedupe_crm_reddit_dashboard_sentences((string) ($explanation['summary'] ?? ''));

            return [
                'summary' => $summary,
                'strengths' => $this->dedupe_crm_reddit_dashboard_string_list((array) ($explanation['strengths'] ?? [])),
                'gaps' => $this->dedupe_crm_reddit_dashboard_string_list((array) ($explanation['gaps'] ?? [])),
                'next_steps' => $this->dedupe_crm_reddit_dashboard_string_list((array) ($explanation['next_steps'] ?? [])),
            ];
        }

        private function dedupe_crm_reddit_dashboard_sentences($text)
        {
            $text = trim((string) $text);
            if ($text === '') {
                return '';
            }

            $parts = preg_split('/(?<=[.!?])\s+/', $text) ?: [$text];
            $seen = [];
            $unique = [];
            foreach ($parts as $part) {
                $part = trim((string) $part);
                if ($part === '') {
                    continue;
                }
                $key = strtolower(preg_replace('/\s+/', ' ', preg_replace('/[^a-z0-9 ]/i', '', $part)));
                if ($key === '' || isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $unique[] = $part;
            }

            return trim(implode(' ', array_slice($unique, 0, 3)));
        }

        private function dedupe_crm_reddit_dashboard_string_list(array $items)
        {
            $seen = [];
            $unique = [];
            foreach ($items as $item) {
                $item = trim(sanitize_text_field((string) $item));
                if ($item === '') {
                    continue;
                }
                $key = strtolower(preg_replace('/\s+/', ' ', preg_replace('/[^a-z0-9 ]/i', '', $item)));
                if ($key === '' || isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $unique[] = $item;
            }

            return array_values(array_slice($unique, 0, 4));
        }

        private function call_crm_reddit_dashboard_match_explainer_claude(array $context, array $cv_profile = [])
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return [];
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 900,
                'temperature' => 0.2,
                'system' => "You explain why a CV matches a private equity role. Be concrete, natural, and specific. Return strict JSON only with keys: summary, strengths, missing, next_steps. strengths and missing must be arrays of short strings. Never address the candidate directly by name. Focus on role fit, seniority, keywords, sector, market, and what is absent. Default to a private equity hiring lens, while still recognizing adjacent investing, portfolio operations, private credit, investor relations, and relevant strategy pathways when the brief supports them.",
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => wp_json_encode([
                            'role' => [
                                'title' => (string) ($context['role_title'] ?? ''),
                                'company' => (string) ($context['company'] ?? ''),
                                'location' => (string) ($context['location'] ?? ''),
                                'seniority' => (string) ($context['seniority'] ?? ''),
                                'industry' => (string) ($context['industry'] ?? ''),
                                'keywords' => array_values(array_slice((array) ($context['keywords'] ?? []), 0, 10)),
                                'skills' => array_values(array_slice((array) ($context['skills'] ?? []), 0, 8)),
                                'requirements' => array_values(array_slice((array) ($context['requirements'] ?? []), 0, 8)),
                                'job_description_excerpt' => function_exists('mb_substr')
                                    ? mb_substr((string) ($context['job_description'] ?? ''), 0, 3200)
                                    : substr((string) ($context['job_description'] ?? ''), 0, 3200),
                            ],
                            'cv' => [
                                'analysis' => [
                                    'score' => (int) ($context['match_score'] ?? 0),
                                    'keywords' => (array) ($cv_profile['keywords'] ?? []),
                                    'locations' => (array) ($cv_profile['locations'] ?? []),
                                    'target_roles' => (array) ($cv_profile['target_roles'] ?? []),
                                    'sectors' => (array) ($cv_profile['sectors'] ?? []),
                                    'seniority' => (array) ($cv_profile['seniority'] ?? []),
                                    'summary' => (string) ($cv_profile['summary'] ?? ''),
                                    'top_strength' => (string) ($cv_profile['top_strength'] ?? ''),
                                    'top_gap' => (string) ($cv_profile['top_gap'] ?? ''),
                                ],
                                'excerpt' => function_exists('mb_substr')
                                    ? mb_substr((string) ($context['cv_text'] ?? ''), 0, 3200)
                                    : substr((string) ($context['cv_text'] ?? ''), 0, 3200),
                            ],
                        ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 60,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response) || 200 !== (int) wp_remote_retrieve_response_code($response)) {
                return [];
            }

            $body = json_decode((string) wp_remote_retrieve_body($response), true);
            $text = '';
            foreach ((array) ($body['content'] ?? []) as $part) {
                if (($part['type'] ?? '') === 'text') {
                    $text .= (string) ($part['text'] ?? '');
                }
            }
            if ($text === '') {
                return [];
            }

            $decoded = json_decode(trim($text), true);
            if (!is_array($decoded)) {
                if (preg_match('/\{.*\}/s', $text, $matches)) {
                    $decoded = json_decode((string) $matches[0], true);
                }
            }
            if (!is_array($decoded)) {
                return [];
            }

            return [
                'summary' => sanitize_text_field((string) ($decoded['summary'] ?? '')),
                'strengths' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($decoded['strengths'] ?? []))), 0, 4)),
                'missing' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($decoded['missing'] ?? []))), 0, 4)),
                'next_steps' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($decoded['next_steps'] ?? []))), 0, 4)),
            ];
        }

        private function build_crm_reddit_dashboard_match_explainer_fallback(array $context, array $cv_profile = [])
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text((string) ($context['cv_text'] ?? ''));
            $strengths = [];
            $missing = [];
            $next_steps = [];

            $role_title = $this->normalize_crm_reddit_dashboard_cv_text((string) ($context['role_title'] ?? ''));
            if ($role_title !== '' && strpos($cv_text, $role_title) !== false) {
                $strengths[] = __('The exact role title or a very close variant appears in the CV.', 'senna-finance');
            }

            $matched_keywords = [];
            foreach ((array) ($context['keywords'] ?? []) as $keyword) {
                $keyword = sanitize_text_field((string) $keyword);
                $keyword_lc = $this->normalize_crm_reddit_dashboard_cv_text($keyword);
                if ($keyword_lc === '') {
                    continue;
                }
                if (strpos($cv_text, $keyword_lc) !== false) {
                    $matched_keywords[] = $keyword;
                } else {
                    $missing[] = sprintf(__('The brief still asks for clearer evidence of %s.', 'senna-finance'), $keyword);
                }
            }

            if (!empty($matched_keywords)) {
                $strengths[] = sprintf(
                    __('The CV already overlaps with role keywords such as %s.', 'senna-finance'),
                    implode(', ', array_slice($matched_keywords, 0, 3))
                );
            }

            $location = $this->normalize_crm_reddit_dashboard_cv_text((string) ($context['location'] ?? ''));
            if ($location !== '' && strpos($cv_text, $location) !== false) {
                $strengths[] = __('The target location is already visible in the CV/profile signal.', 'senna-finance');
            } elseif ($location !== '') {
                $missing[] = __('Location alignment is weak or not explicit in the current CV.', 'senna-finance');
            }

            $seniority_adjustment = $this->get_crm_reddit_dashboard_seniority_score_adjustment($context, $cv_text, $cv_profile);
            if ($seniority_adjustment >= 8) {
                $strengths[] = __('The experience level reads as well aligned with the seniority of the brief.', 'senna-finance');
            } elseif ($seniority_adjustment <= -20) {
                $missing[] = __('The role seniority looks materially below or above the current profile level.', 'senna-finance');
            }

            $requirements = array_values(array_slice(array_unique(array_merge((array) ($context['skills'] ?? []), (array) ($context['requirements'] ?? []))), 0, 5));
            foreach ($requirements as $requirement) {
                $requirement_lc = $this->normalize_crm_reddit_dashboard_cv_text((string) $requirement);
                if ($requirement_lc !== '' && strpos($cv_text, $requirement_lc) === false) {
                    $missing[] = sprintf(__('This role would benefit from clearer mention of %s.', 'senna-finance'), sanitize_text_field((string) $requirement));
                }
            }

            if (empty($strengths)) {
                $strengths[] = __('The score is mostly being driven by broad finance-role overlap rather than exact brief alignment.', 'senna-finance');
            }

            if (empty($missing)) {
                $missing[] = __('The current CV is not showing an obvious hard gap against the visible role requirements.', 'senna-finance');
            }

            $next_steps[] = __('Move the strongest matched keyword or transaction signal higher in the experience section.', 'senna-finance');
            if (!empty($missing[0])) {
                $next_steps[] = __('Add one proof point that closes the clearest missing signal before applying.', 'senna-finance');
            }
            $next_steps[] = __('Keep the role title, sector language, and location phrasing close to the brief.', 'senna-finance');

            return [
                'summary' => sprintf(
                    __('This score is being driven by role overlap, seniority fit, and how much of the brief language already shows up in the CV for %s.', 'senna-finance'),
                    (string) ($context['role_title'] ?? __('this role', 'senna-finance'))
                ),
                'strengths' => array_values(array_slice(array_unique($strengths), 0, 4)),
                'missing' => array_values(array_slice(array_unique($missing), 0, 4)),
                'next_steps' => array_values(array_slice(array_unique($next_steps), 0, 4)),
            ];
        }

        private function render_crm_reddit_dashboard_match_explainer_markup(array $explanation, array $context = [])
        {
            $score = max(0, min(100, (int) ($context['match_score'] ?? 0)));
            ob_start();
        ?>
