        public function save_crm_reddit_dashboard_profile($user_id, array $request_data = [])
        {
            $profile_state = $this->get_crm_reddit_dashboard_profile_state($user_id);
            $alert_frequency_options = $this->get_crm_reddit_dashboard_alert_frequency_options();

            $headline = sanitize_text_field((string) wp_unslash($request_data['headline'] ?? ($profile_state['headline'] ?? '')));
            $about = sanitize_textarea_field((string) wp_unslash($request_data['about'] ?? ($profile_state['about'] ?? '')));
            $alert_frequency = sanitize_key((string) wp_unslash($request_data['alert_frequency'] ?? ($profile_state['alert_frequency'] ?? 'daily')));
            if (!isset($alert_frequency_options[$alert_frequency])) {
                $alert_frequency = 'daily';
            }

            $target_roles = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['target_roles'] ?? []));
            $target_locations = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['target_locations'] ?? []));
            $target_sectors = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['target_sectors'] ?? []), 18);
            $technical_skills = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['technical_skills'] ?? []), 18);
            $qualifications = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['qualifications'] ?? []), 18);
            $languages = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['languages'] ?? []), 12);
            $excluded_roles = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['excluded_roles'] ?? []), 18);
            $excluded_locations = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['excluded_locations'] ?? []), 18);
            $excluded_sectors = $this->normalize_crm_reddit_profile_tag_values(wp_unslash($request_data['excluded_sectors'] ?? []), 18);

            if (function_exists('sffc_crm_save_job_preferences')) {
                sffc_crm_save_job_preferences($user_id, [
                    'target_roles' => $target_roles,
                    'target_locations' => $target_locations,
                    'target_sectors' => $target_sectors,
                ]);
            }

            if (class_exists('SFFC_User_Preferences')) {
                SFFC_User_Preferences::get_instance()->set_profile_headline($user_id, $headline);
            } else {
                update_user_meta($user_id, 'sffc_profile_headline', $headline);
            }

            wp_update_user([
                'ID' => $user_id,
                'description' => $about,
            ]);

            update_user_meta($user_id, 'sffc_crm_technical_skills', $technical_skills);
            update_user_meta($user_id, 'sffc_crm_certifications', $qualifications);
            update_user_meta($user_id, 'sffc_crm_languages', $languages);
            update_user_meta($user_id, 'sffc_crm_excluded_roles', $excluded_roles);
            update_user_meta($user_id, 'sffc_crm_excluded_locations', $excluded_locations);
            update_user_meta($user_id, 'sffc_crm_excluded_sectors', $excluded_sectors);
            update_user_meta($user_id, 'sffc_crm_alert_frequency', $alert_frequency);
            update_user_meta($user_id, 'sffc_crm_digest_daily', $alert_frequency === 'daily' ? 1 : 0);
            update_user_meta($user_id, 'sffc_crm_digest_weekly', $alert_frequency === 'weekly' ? 1 : 0);

            $account_user = $this->get_crm_reddit_account_user($user_id);

            return [
                'message' => __('Profile updated successfully.', 'senna-finance'),
                'markup' => $this->render_crm_reddit_dashboard_profile_view($user_id, $account_user),
            ];
        }

        private function get_crm_reddit_dashboard_topbar_counts($user_id)
        {
            $counts = [
                'notifications' => 0,
                'messages' => 0,
            ];

            if ($user_id <= 0) {
                return $counts;
            }

            $cache_key = 'sffc_crm_dash_topbar_counts_job_matches_' . (int) $user_id;
            $cached = get_transient($cache_key);
            if (is_array($cached) && isset($cached['notifications'], $cached['messages'])) {
                return $cached;
            }

            // Seed welcome/messages and daily notifications only on a cold count read,
            // so the initial unread state is correct without paying this cost on every render.
            $this->ensure_crm_reddit_dashboard_paula_thread($user_id);
            $this->seed_crm_reddit_dashboard_notifications($user_id, '');

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-alert.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';

            $alert_model = new SFFC_CRM_Alert();
            $counts['notifications'] = count(array_filter(
                (array) $alert_model->get_notifications($user_id, ['limit' => 50, 'offset' => 0]),
                function ($notification) {
                    return empty($notification['is_read']) && $this->is_cv_match_studio_job_match_notification((array) $notification);
                }
            ));

            $conversation_model = new SFFC_CRM_Conversation();
            $conversation_counts = (array) $conversation_model->get_counts($user_id);
            $counts['messages'] = (int) ($conversation_counts['unread'] ?? 0);

            set_transient($cache_key, $counts, MINUTE_IN_SECONDS);
            return $counts;
        }

        private function get_crm_reddit_dashboard_notifications_payload($user_id, $current_url = '')
        {
            $cache_key = 'sffc_crm_dash_notifications_job_matches_' . md5((string) $user_id . '|' . (string) $current_url);
            $cached = get_transient($cache_key);
            if (is_array($cached) && isset($cached['markup'], $cached['unread_count'], $cached['notifications'])) {
                $cached['notifications'] = $this->normalize_cv_match_studio_private_equity_notification_items((array) $cached['notifications']);
                return $cached;
            }

            $notifications = $this->get_cv_match_studio_notification_preview_items($user_id, $current_url);
            $unread_count = count(array_filter($notifications, static function ($notification) {
                return empty($notification['is_read']);
            }));

            $payload = [
                'markup' => $this->render_crm_reddit_dashboard_notifications_markup($notifications, $unread_count),
                'unread_count' => $unread_count,
                'notifications' => $notifications,
            ];
            set_transient($cache_key, $payload, 5 * MINUTE_IN_SECONDS);

            return $payload;
        }

        private function normalize_cv_match_studio_private_equity_notification_items(array $notifications)
        {
            return array_map(function ($notification) {
                $notification = is_array($notification) ? $notification : [];
                $notification['title'] = $this->normalize_cv_match_studio_private_equity_notification_text((string) ($notification['title'] ?? ''), 'title');
                $notification['message'] = $this->normalize_cv_match_studio_private_equity_notification_text((string) ($notification['message'] ?? ''), 'message');
                return $notification;
            }, $notifications);
        }

        private function get_crm_reddit_dashboard_inbox_payload($user_id, $active_conversation_id = 0)
        {
            $cache_key = '';
            if ((int) $active_conversation_id <= 0) {
                $cache_key = 'sffc_crm_dash_inbox_' . (int) $user_id . '_default';
                $cached = get_transient($cache_key);
                if (is_array($cached) && isset($cached['markup'], $cached['unread_count'])) {
                    return $cached;
                }
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-message.php';

            $this->ensure_crm_reddit_dashboard_paula_thread($user_id);

            $conversation_model = new SFFC_CRM_Conversation();
            $message_model = new SFFC_CRM_Message();
            $conversations = (array) $conversation_model->get_user_conversations($user_id, [
                'status' => 'active',
                'limit' => 8,
                'offset' => 0,
                'orderby' => 'last_message_at',
                'order' => 'DESC',
            ]);
            $conversations = $this->decorate_crm_reddit_dashboard_inbox_conversations($conversations);
            $compose_users = $this->get_crm_reddit_dashboard_messageable_users($user_id, '', 8);

            if (empty($conversations)) {
                $payload = [
                    'markup' => $this->render_crm_reddit_dashboard_inbox_markup([], [], 0, 0, $compose_users),
                    'unread_count' => 0,
                ];
                if ($cache_key !== '') {
                    set_transient($cache_key, $payload, MINUTE_IN_SECONDS);
                }
                return $payload;
            }

            $active_conversation_id = $active_conversation_id > 0
                ? $active_conversation_id
                : (int) ($conversations[0]['id'] ?? 0);

            $active_conversation = null;
            foreach ($conversations as $conversation) {
                if ((int) ($conversation['id'] ?? 0) === $active_conversation_id) {
                    $active_conversation = $conversation;
                    break;
                }
            }
            if (empty($active_conversation)) {
                $active_conversation = $conversations[0];
                $active_conversation_id = (int) ($active_conversation['id'] ?? 0);
            }

            if ($active_conversation_id > 0) {
                $conversation_model->mark_read($active_conversation_id, $user_id);
            }

            $messages = $active_conversation_id > 0
                ? (array) $message_model->get_conversation_messages($active_conversation_id, ['limit' => 100, 'order' => 'ASC'])
                : [];

            $conversation_counts = (array) $conversation_model->get_counts($user_id);
            $unread_count = (int) ($conversation_counts['unread'] ?? 0);

            $payload = [
                'markup' => $this->render_crm_reddit_dashboard_inbox_markup($conversations, $messages, $active_conversation_id, $unread_count, $compose_users),
                'unread_count' => $unread_count,
            ];
            if ($cache_key !== '') {
                set_transient($cache_key, $payload, MINUTE_IN_SECONDS);
            }

            return $payload;
        }

        private function clear_crm_reddit_dashboard_runtime_caches($user_id, array $options = [])
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return;
            }

            delete_transient('sffc_crm_dash_topbar_counts_' . $user_id);
            delete_transient('sffc_crm_dash_inbox_' . $user_id . '_default');

            if (!empty($options['current_url'])) {
                delete_transient('sffc_crm_dash_notifications_' . md5($user_id . '|' . (string) $options['current_url']));
                delete_transient('sffc_crm_dash_notifications_pe_' . md5($user_id . '|' . (string) $options['current_url']));
            }

            if (!empty($options['clear_notification_seed'])) {
                delete_transient('sffc_crm_dash_notifications_seed_' . $user_id);
            }
        }

        private function get_crm_reddit_dashboard_member_thread_id($user_a_id, $user_b_id)
        {
            $user_ids = [(int) $user_a_id, (int) $user_b_id];
            sort($user_ids, SORT_NUMERIC);
            return 'member_dm_' . $user_ids[0] . '_' . $user_ids[1];
        }

        private function get_crm_reddit_dashboard_member_conversation_label($counterpart_user_id)
        {
            return 'member_dm:' . (int) $counterpart_user_id;
        }

        private function get_crm_reddit_dashboard_member_conversation_target_id(array $conversation)
        {
            $labels = trim((string) ($conversation['labels'] ?? ''));
            if ($labels === '' || strpos($labels, 'member_dm:') !== 0) {
                return 0;
            }

            return absint(substr($labels, strlen('member_dm:')));
        }

        private function is_crm_reddit_dashboard_messageable_user($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return false;
            }

            $user = get_userdata($user_id);
            return $user instanceof WP_User && (int) $user->ID > 0;
        }

        private function get_crm_reddit_dashboard_user_role_label($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return __('MENA Careers member', 'senna-finance');
            }

            $preferences = function_exists('sffc_crm_get_job_preferences')
                ? (array) sffc_crm_get_job_preferences($user_id)
                : [];

            if (!empty($preferences['target_roles'][0])) {
                return sanitize_text_field((string) $preferences['target_roles'][0]);
            }

            $headline = trim((string) get_user_meta($user_id, 'sffc_profile_headline', true));
            if ($headline !== '') {
                $headline = preg_replace('/\s+/', ' ', $headline);
                return function_exists('mb_strimwidth')
                    ? mb_strimwidth($headline, 0, 72, '...')
                    : substr($headline, 0, 69) . (strlen($headline) > 69 ? '...' : '');
            }

            $skills = (array) get_user_meta($user_id, 'sffc_crm_technical_skills', true);
            if (!empty($skills[0])) {
                return sanitize_text_field((string) $skills[0]);
            }

            return __('MENA Careers member', 'senna-finance');
        }

        private function get_crm_reddit_dashboard_messageable_users($current_user_id, $search = '', $limit = 8)
        {
            $current_user_id = (int) $current_user_id;
            $limit = max(4, min(12, (int) $limit));

            $query_args = [
                'number' => $limit,
                'orderby' => 'display_name',
                'order' => 'ASC',
                'exclude' => [$current_user_id],
                'fields' => 'all_with_meta',
            ];

            $search = trim((string) $search);
            if ($search !== '') {
                $query_args['search'] = '*' . esc_attr($search) . '*';
                $query_args['search_columns'] = ['display_name', 'user_email', 'user_login'];
            }

            $query = new WP_User_Query($query_args);
            $users = [];

            foreach ((array) $query->get_results() as $user) {
                if (!$user instanceof WP_User) {
                    continue;
                }

                $users[] = [
                    'id' => (int) $user->ID,
                    'name' => (string) ($user->display_name ?: $user->user_login),
                    'email' => (string) $user->user_email,
                    'role' => $this->get_crm_reddit_dashboard_user_role_label((int) $user->ID),
                    'avatar_url' => (string) get_avatar_url($user->ID, ['size' => 72]),
                ];
            }

            return $users;
        }

        private function render_crm_reddit_dashboard_message_user_options(array $users)
        {
            ob_start();
            if (empty($users)) :
            ?>
                <div class="sffc-cv-match-studio__inbox-user-empty"><?php esc_html_e('No members found right now.', 'senna-finance'); ?></div>
                <?php
            else :
                foreach ($users as $user_option) :
                ?>
                    <button
                        type="button"
                        class="sffc-cv-match-studio__inbox-user-option"
                        data-dashboard-compose-user="<?php echo esc_attr((string) ($user_option['id'] ?? 0)); ?>">
                        <span class="sffc-cv-match-studio__inbox-user-avatar">
                            <?php if (!empty($user_option['avatar_url'])) : ?>
                                <img src="<?php echo esc_url((string) $user_option['avatar_url']); ?>" alt="<?php echo esc_attr((string) ($user_option['name'] ?? '')); ?>">
                            <?php else : ?>
                                <?php echo esc_html(strtoupper(substr((string) ($user_option['name'] ?? 'S'), 0, 1))); ?>
                            <?php endif; ?>
                        </span>
                        <span class="sffc-cv-match-studio__inbox-user-copy">
                            <strong><?php echo esc_html((string) ($user_option['name'] ?? '')); ?></strong>
                            <span><?php echo esc_html((string) ($user_option['role'] ?? __('MENA Careers member', 'senna-finance'))); ?></span>
                        </span>
                    </button>
            <?php
                endforeach;
            endif;
            return (string) ob_get_clean();
        }

        private function create_crm_reddit_dashboard_member_conversation($owner_user_id, $counterpart_user_id)
        {
            global $wpdb;

            $owner_user_id = (int) $owner_user_id;
            $counterpart_user_id = (int) $counterpart_user_id;
            if ($owner_user_id <= 0 || $counterpart_user_id <= 0) {
                return 0;
            }

            $counterpart = get_userdata($counterpart_user_id);
            if (!$counterpart instanceof WP_User) {
                return 0;
            }

            $thread_id = $this->get_crm_reddit_dashboard_member_thread_id($owner_user_id, $counterpart_user_id);
            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $wpdb->insert(
                $table,
                [
                    'user_id' => $owner_user_id,
                    'recruiter_id' => null,
                    'post_id' => null,
                    'subject' => sanitize_text_field((string) ($counterpart->display_name ?: $counterpart->user_login)),
                    'channel' => 'manual',
                    'status' => 'active',
                    'is_read' => 1,
                    'is_starred' => 0,
                    'last_message_at' => current_time('mysql'),
                    'last_message_preview' => '',
                    'last_message_direction' => 'outbound',
                    'message_count' => 0,
                    'unread_count' => 0,
                    'thread_id' => sanitize_text_field($thread_id),
                    'labels' => $this->get_crm_reddit_dashboard_member_conversation_label($counterpart_user_id),
                    'created_at' => current_time('mysql'),
                    'updated_at' => current_time('mysql'),
                ],
                ['%d', '%d', '%d', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%s', '%s']
            );

            if ($wpdb->last_error) {
                return 0;
            }

            return (int) $wpdb->insert_id;
        }

        private function find_or_create_crm_reddit_dashboard_member_conversation($owner_user_id, $counterpart_user_id)
        {
            global $wpdb;

            $owner_user_id = (int) $owner_user_id;
            $counterpart_user_id = (int) $counterpart_user_id;
            if ($owner_user_id <= 0 || $counterpart_user_id <= 0) {
                return 0;
            }

            $thread_id = $this->get_crm_reddit_dashboard_member_thread_id($owner_user_id, $counterpart_user_id);
            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table}
                 WHERE user_id = %d
                   AND thread_id = %s
                   AND labels = %s
                 ORDER BY id DESC
                 LIMIT 1",
                $owner_user_id,
                $thread_id,
                $this->get_crm_reddit_dashboard_member_conversation_label($counterpart_user_id)
            ));

            if ($existing_id > 0) {
                return $existing_id;
            }

            return $this->create_crm_reddit_dashboard_member_conversation($owner_user_id, $counterpart_user_id);
        }

        private function decorate_crm_reddit_dashboard_inbox_conversations(array $conversations)
        {
            foreach ($conversations as $index => $conversation) {
                $counterpart_user_id = $this->get_crm_reddit_dashboard_member_conversation_target_id((array) $conversation);
                if ($counterpart_user_id <= 0) {
                    continue;
                }

                $counterpart = get_userdata($counterpart_user_id);
                if (!$counterpart instanceof WP_User) {
                    continue;
                }

                $conversations[$index]['recruiter_name'] = (string) ($counterpart->display_name ?: $counterpart->user_login);
                $conversations[$index]['recruiter_email'] = (string) $counterpart->user_email;
                $conversations[$index]['recruiter_firm'] = $this->get_crm_reddit_dashboard_user_role_label($counterpart_user_id);
                $conversations[$index]['recruiter_photo'] = (string) get_avatar_url($counterpart_user_id, ['size' => 72]);
                $conversations[$index]['is_member_thread'] = 1;
                $conversations[$index]['member_target_user_id'] = $counterpart_user_id;
            }

            return $conversations;
        }

        private function ensure_crm_reddit_dashboard_paula_thread($user_id)
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-message.php';
            $conversation_model = new SFFC_CRM_Conversation();
            $message_model = new SFFC_CRM_Message();

            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            $paula_recruiter_id = (int) get_option('sffc_crm_dashboard_paula_recruiter_id', 0);
            $paula = null;

            if ($paula_recruiter_id > 0) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';
                $recruiter_model = new SFFC_CRM_Recruiter();
                $paula = $recruiter_model->get($paula_recruiter_id);
            }

            if (empty($paula) && $admin_email !== '') {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';
                $recruiter_model = new SFFC_CRM_Recruiter();
                $paula = $recruiter_model->find_by_email($admin_email);
            }

            if (empty($paula)) {
                if (!isset($recruiter_model)) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';
                    $recruiter_model = new SFFC_CRM_Recruiter();
                }
                $recruiter_id = $recruiter_model->create([
                    'name' => 'Paula',
                    'first_name' => 'Paula',
                    'last_name' => '',
                    'firm' => 'MENA Careers',
                    'title' => 'Member Success',
                    'email' => $admin_email,
                    'photo_url' => 'https://joinsenna.com/wp-content/uploads/2024/04/237358380-shes-positively-professional-p.jpeg',
                    'linkedin_url' => '',
                    'data_source' => 'manual',
                    'is_active' => 1,
                ]);
                if ($recruiter_id) {
                    $paula = $recruiter_model->get((int) $recruiter_id);
                }
            }

            if (empty($paula['id'])) {
                return 0;
            }

            update_option('sffc_crm_dashboard_paula_recruiter_id', (int) $paula['id'], false);

            $stored_conversation_id = (int) get_user_meta($user_id, 'sffc_crm_dashboard_paula_conversation_id', true);
            if ($stored_conversation_id > 0) {
                $stored_conversation = $conversation_model->get($stored_conversation_id);
                if (!empty($stored_conversation) && (int) ($stored_conversation['user_id'] ?? 0) === (int) $user_id) {
                    return $stored_conversation_id;
                }
            }

            $conversation_id = (int) $conversation_model->find_or_create($user_id, (int) $paula['id'], __('Welcome to MENA Careers', 'senna-finance'));
            if ($conversation_id <= 0) {
                return 0;
            }
            update_user_meta($user_id, 'sffc_crm_dashboard_paula_conversation_id', $conversation_id);

            $existing_messages = (int) $message_model->get_conversation_message_count($conversation_id);
            if ($existing_messages === 0) {
                $user = get_user_by('id', $user_id);
                $first_name = '';
                if ($user instanceof WP_User) {
                    $first_name = trim((string) get_user_meta($user_id, 'first_name', true));
                    if ($first_name === '') {
                        $first_name = trim((string) ($user->first_name ?? ''));
                    }
                }
                $display_name = $first_name !== ''
                    ? $first_name
                    : ($user instanceof WP_User ? ($user->display_name ?: $user->user_login) : __('there', 'senna-finance'));
                $welcome = sprintf(
                    __("Hi %s,\n\nWelcome to MENA Careers. Use your dashboard to browse curated finance role lists and recruiter contact lists, save the lists that matter, export roles, and request daily scans when new opportunities are added.\n\nIf you need help finding the right finance lists, building a recruiter contact list, tracking applications, or choosing the right next step, just reply here and our team will get back to you.\n\nPaula", 'senna-finance'),
                    $display_name
                );

                $message_model->create_inbound($conversation_id, [
                    'channel' => 'manual',
                    'subject' => __('Welcome to MENA Careers', 'senna-finance'),
                    'body_text' => $welcome,
                    'body_html' => nl2br(esc_html($welcome)),
                    'from_email' => $admin_email,
                    'from_name' => 'Paula',
                    'to_email' => $user instanceof WP_User ? (string) $user->user_email : '',
                    'to_name' => $display_name,
                ]);
            }

            return $conversation_id;
        }

        private function seed_crm_reddit_dashboard_notifications($user_id, $current_url = '')
        {
            $seed_key = 'sffc_crm_dash_notifications_seed_' . (int) $user_id;
            if (get_transient($seed_key)) {
                return;
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-alert.php';

            $alert_model = new SFFC_CRM_Alert();
            $profile = $this->get_crm_reddit_dashboard_profile_state($user_id);

            $this->maybe_seed_crm_reddit_dashboard_role_notification($alert_model, $user_id, $profile);
            set_transient($seed_key, 1, 10 * MINUTE_IN_SECONDS);
        }

        private function maybe_seed_crm_reddit_dashboard_role_notification(SFFC_CRM_Alert $alert_model, $user_id, array $profile)
        {
            $items = $this->get_crm_reddit_dashboard_metrics_source_items(0, $user_id, '');
            foreach ((array) $items as $item) {
                if (!$this->is_crm_reddit_dashboard_recent_match_candidate($item, $profile)) {
                    continue;
                }

                $post_id = (int) ($item['wp_post_id'] ?? 0);
                if ($post_id <= 0) {
                    continue;
                }

                if ($this->has_crm_reddit_notification_for_key($user_id, 'dashboard_role_match', 'post_id', $post_id, DAY_IN_SECONDS * 7)) {
                    return;
                }

                $role_title = (string) ($item['role_title'] ?? __('New role', 'senna-finance'));
                $company = (string) ($item['company'] ?? __('MENA Careers network', 'senna-finance'));
                $location = (string) ($item['location'] ?? '');
                $message = $location !== ''
                    ? sprintf(__('A finance role match, %1$s at %2$s, was just added in %3$s.', 'senna-finance'), $role_title, $company, $location)
                    : sprintf(__('A finance role match, %1$s at %2$s, was just added to your MENA Careers workspace.', 'senna-finance'), $role_title, $company);

                $alert_model->create_notification($user_id, [
                    'type' => 'dashboard_role_match',
                    'title' => __('New finance role match', 'senna-finance'),
                    'message' => $message,
                    'data' => [
                        'post_id' => $post_id,
                        'role_title' => $role_title,
                    ],
                    'action_url' => (string) ($item['view_url'] ?? ''),
                ]);
                return;
            }
        }

        private function maybe_seed_crm_reddit_dashboard_market_notification(SFFC_CRM_Alert $alert_model, $user_id)
        {
            $article = null;
            $feed = $this->get_market_articles_feed('all', 1, 1);
            if (!empty($feed['items'][0])) {
                $article = $feed['items'][0];
            }

            if (empty($article['id'])) {
                return;
            }

            $article_id = (int) $article['id'];
            if ($this->has_crm_reddit_notification_for_key($user_id, 'dashboard_market_news', 'article_id', $article_id, DAY_IN_SECONDS)) {
                return;
            }

            $alert_model->create_notification($user_id, [
                'type' => 'dashboard_market_news',
                'title' => __('Finance market update', 'senna-finance'),
                'message' => (string) ($article['title'] ?? __('Fresh finance market update available.', 'senna-finance')),
                'data' => [
                    'article_id' => $article_id,
                    'type_label' => (string) ($article['type_label'] ?? __('News', 'senna-finance')),
                ],
                'action_url' => (string) ($article['url'] ?? ''),
            ]);
        }

        private function maybe_seed_crm_reddit_dashboard_tip_notification(SFFC_CRM_Alert $alert_model, $user_id, array $profile, $current_url = '')
        {
            $day_key = gmdate('Y-m-d', current_time('timestamp'));
            if ($this->has_crm_reddit_notification_for_key($user_id, 'dashboard_daily_tip', 'day_key', $day_key, DAY_IN_SECONDS * 2)) {
                return;
            }

            $tip = $this->get_crm_reddit_dashboard_daily_tip_for_user($user_id, $profile);
            if ($tip === '') {
                return;
            }

            if ($this->has_crm_reddit_notification_message($user_id, 'dashboard_daily_tip', $tip, DAY_IN_SECONDS * 7)) {
                return;
            }

            $alert_model->create_notification($user_id, [
                'type' => 'dashboard_daily_tip',
                'title' => __('Finance positioning tip', 'senna-finance'),
                'message' => $tip,
                'data' => [
                    'day_key' => $day_key,
                ],
                'action_url' => $current_url,
            ]);
        }

        private function has_crm_reddit_notification_for_key($user_id, $type, $data_key, $data_value, $age_window)
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_notifications';
            $age_window = max(HOUR_IN_SECONDS, (int) $age_window);
            $since = gmdate('Y-m-d H:i:s', current_time('timestamp') - $age_window);

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT id, data FROM {$table} WHERE user_id = %d AND type = %s AND created_at >= %s ORDER BY id DESC LIMIT 20",
                $user_id,
                $type,
                $since
            ), ARRAY_A);

            foreach ((array) $rows as $row) {
                $data = !empty($row['data']) ? json_decode((string) $row['data'], true) : [];
                if ((string) ($data[$data_key] ?? '') === (string) $data_value) {
                    return true;
                }
            }

            return false;
        }

        private function has_crm_reddit_notification_message($user_id, $type, $message, $age_window)
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_notifications';
            $age_window = max(HOUR_IN_SECONDS, (int) $age_window);
            $since = gmdate('Y-m-d H:i:s', current_time('timestamp') - $age_window);
            $normalized_message = $this->normalize_crm_reddit_notification_message($message);

            if ($normalized_message === '') {
                return false;
            }

            $rows = $wpdb->get_col($wpdb->prepare(
                "SELECT message FROM {$table} WHERE user_id = %d AND type = %s AND created_at >= %s ORDER BY id DESC LIMIT 20",
                $user_id,
                $type,
                $since
            ));

            foreach ((array) $rows as $row_message) {
                if ($this->normalize_crm_reddit_notification_message((string) $row_message) === $normalized_message) {
                    return true;
                }
            }

            return false;
        }

        private function normalize_crm_reddit_notification_message($message)
        {
            $message = strtolower(wp_strip_all_tags((string) $message));
            $message = preg_replace('/\s+/', ' ', $message);
            return trim((string) $message);
        }

        private function is_crm_reddit_dashboard_recent_match_candidate(array $item, array $profile)
        {
            $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
            if ($posted_timestamp <= 0 && !empty($item['posted_at'])) {
                $posted_timestamp = strtotime((string) $item['posted_at']);
            }
            if ($posted_timestamp > 0 && $posted_timestamp < (current_time('timestamp') - (DAY_IN_SECONDS * 7))) {
                return false;
            }

            $role_title = function_exists('mb_strtolower') ? mb_strtolower((string) ($item['role_title'] ?? '')) : strtolower((string) ($item['role_title'] ?? ''));
            $location = function_exists('mb_strtolower') ? mb_strtolower((string) ($item['location'] ?? '')) : strtolower((string) ($item['location'] ?? ''));
            $sector = function_exists('mb_strtolower') ? mb_strtolower((string) ($item['sector'] ?? $item['industry'] ?? '')) : strtolower((string) ($item['sector'] ?? $item['industry'] ?? ''));

            foreach ((array) ($profile['excluded_roles'] ?? []) as $excluded_role) {
                $excluded_role = function_exists('mb_strtolower') ? mb_strtolower((string) $excluded_role) : strtolower((string) $excluded_role);
                if ($excluded_role !== '' && strpos($role_title, $excluded_role) !== false) {
                    return false;
                }
            }
            foreach ((array) ($profile['excluded_locations'] ?? []) as $excluded_location) {
                $excluded_location = function_exists('mb_strtolower') ? mb_strtolower((string) $excluded_location) : strtolower((string) $excluded_location);
                if ($excluded_location !== '' && strpos($location, $excluded_location) !== false) {
                    return false;
                }
            }
            foreach ((array) ($profile['excluded_sectors'] ?? []) as $excluded_sector) {
                $excluded_sector = function_exists('mb_strtolower') ? mb_strtolower((string) $excluded_sector) : strtolower((string) $excluded_sector);
                if ($excluded_sector !== '' && strpos($sector, $excluded_sector) !== false) {
                    return false;
                }
            }

            $score = 0;
            foreach ((array) ($profile['target_roles'] ?? []) as $target_role) {
                $target_role = function_exists('mb_strtolower') ? mb_strtolower((string) $target_role) : strtolower((string) $target_role);
                if ($target_role !== '' && (strpos($role_title, $target_role) !== false || strpos($target_role, $role_title) !== false)) {
                    $score += 2;
                    break;
                }
            }
            foreach ((array) ($profile['target_locations'] ?? []) as $target_location) {
                $target_location = function_exists('mb_strtolower') ? mb_strtolower((string) $target_location) : strtolower((string) $target_location);
                if ($target_location !== '' && strpos($location, $target_location) !== false) {
                    $score += 1;
                    break;
                }
            }

            if (empty($profile['target_roles']) && empty($profile['target_locations'])) {
                return true;
            }

            return $score >= 2;
        }

        private function get_crm_reddit_dashboard_daily_tip(array $profile)
        {
            return $this->get_crm_reddit_dashboard_daily_tip_for_user(get_current_user_id(), $profile);
        }

        private function get_crm_reddit_dashboard_daily_tip_for_user($user_id, array $profile)
        {
            $user_id = (int) $user_id;
            $day_key = gmdate('Y-m-d', current_time('timestamp'));
            $cache_key = $this->get_crm_reddit_dashboard_daily_tip_cache_key($user_id, $day_key);
            $cached = get_transient($cache_key);
            if (is_string($cached) && $cached !== '') {
                return $cached;
            }

            if ($user_id > 0) {
                $this->maybe_queue_crm_reddit_dashboard_daily_tip($user_id, $day_key);
            }

            return $this->get_crm_reddit_dashboard_daily_tip_fallback($profile);
        }

        private function get_crm_reddit_dashboard_daily_tip_cache_key($user_id, $day_key)
        {
            return 'sffc_crm_dash_daily_tip_v2_' . md5((int) $user_id . '|' . (string) $day_key);
        }

        private function maybe_queue_crm_reddit_dashboard_daily_tip($user_id, $day_key)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0 || !function_exists('wp_schedule_single_event')) {
                return;
            }

            $queue_key = 'sffc_crm_dash_daily_tip_queue_' . md5($user_id . '|' . (string) $day_key);
            if (get_transient($queue_key)) {
                return;
            }

            $scheduled = wp_next_scheduled('sffc_crm_reddit_generate_daily_tip', [$user_id, (string) $day_key]);
            if (!$scheduled) {
                wp_schedule_single_event(time() + 15, 'sffc_crm_reddit_generate_daily_tip', [$user_id, (string) $day_key]);
            }

            set_transient($queue_key, 1, HOUR_IN_SECONDS);
        }

        public function generate_crm_reddit_dashboard_daily_tip($user_id, $day_key = '')
        {
            $user_id = (int) $user_id;
            $day_key = (string) $day_key;
            if ($user_id <= 0) {
                return;
            }

            if ($day_key === '') {
                $day_key = gmdate('Y-m-d', current_time('timestamp'));
            }

            $cache_key = $this->get_crm_reddit_dashboard_daily_tip_cache_key($user_id, $day_key);
            $existing = get_transient($cache_key);
            if (is_string($existing) && $existing !== '') {
                return;
            }

            $profile = $this->get_crm_reddit_dashboard_profile_state($user_id);
            $tip = '';
            $api_key = $this->get_crm_reddit_claude_api_key();
            $theme = $this->get_crm_reddit_dashboard_daily_tip_theme($user_id, $profile, $day_key);

            if ($api_key !== '') {
                $role_hint = implode(', ', array_slice((array) ($profile['target_roles'] ?? []), 0, 3));
                $location_hint = implode(', ', array_slice((array) ($profile['target_locations'] ?? []), 0, 3));
                $prompt = "You are writing one concise premium daily private equity market tip for a private equity candidate.\n"
                    . "Target roles: " . ($role_hint !== '' ? $role_hint : 'private equity roles') . "\n"
                    . "Preferred locations: " . ($location_hint !== '' ? $location_hint : 'Dubai, Abu Dhabi, Riyadh, Doha, London, Singapore') . "\n"
                    . "Today's topic: " . (string) ($theme['label'] ?? 'candidate positioning') . "\n"
                    . "Topic instruction: " . (string) ($theme['prompt'] ?? 'Give one practical candidate tip.') . "\n"
                    . "Write one natural-sounding tip under 220 characters. No emojis. No bullet points. Avoid generic market commentary unless the topic explicitly requires it. Focus on practical candidate advantage in private equity hiring today.";
                $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                    'timeout' => 25,
                    'headers' => [
                        'Content-Type' => 'application/json',
                        'x-api-key' => $api_key,
                        'anthropic-version' => '2023-06-01',
                    ],
                    'body' => wp_json_encode([
                        'model' => 'claude-sonnet-4-6',
                        'max_tokens' => 180,
                        'messages' => [
                            [
                                'role' => 'user',
                                'content' => $prompt,
                            ],
                        ],
                    ]),
                ]);

                if (!is_wp_error($response)) {
                    $body = json_decode((string) wp_remote_retrieve_body($response), true);
                    if (!empty($body['content'][0]['text'])) {
                        $tip = sanitize_text_field(trim((string) $body['content'][0]['text']));
                    }
                }
            }

            if ($tip === '') {
                $tip = $this->get_crm_reddit_dashboard_daily_tip_fallback($profile);
            }

            set_transient($cache_key, $tip, DAY_IN_SECONDS);
        }

