            $day_key = gmdate('Y-m-d', current_time('timestamp'));
            $theme = $this->get_crm_reddit_dashboard_daily_tip_theme(get_current_user_id(), $profile, $day_key);
            $role = (string) (($profile['target_roles'][0] ?? __('your target role', 'senna-finance')));
