        private function normalize_cv_match_studio_private_equity_notification_text($text, $context = 'message')
        {
            $text = trim((string) $text);

            if ($text === '') {
                return $context === 'title'
                    ? __('Finance role match', 'senna-finance')
                        : __('A finance role match is ready in your MENA Careers workspace.', 'senna-finance');
            }

            $lower = strtolower($text);
            if ($context === 'title') {
                $title_map = [
                    'new matching role added' => __('New finance role match', 'senna-finance'),
                    'new finance match added' => __('New finance role match', 'senna-finance'),
                    'new finance match added' => __('New finance role match', 'senna-finance'),
                    'new role added' => __('New finance role added', 'senna-finance'),
                    'role alert' => __('Finance role alert', 'senna-finance'),
                    'job alert' => __('Finance job alert', 'senna-finance'),
                    'application update' => __('Application update', 'senna-finance'),
                    'recruiter update' => __('Recruiter update', 'senna-finance'),
                ];

                foreach ($title_map as $needle => $replacement) {
                    if (strpos($lower, $needle) !== false) {
                        return $replacement;
                    }
                }

                if (strpos($lower, 'role') === false && strpos($lower, 'job') === false && strpos($lower, 'recruiter') === false && strpos($lower, 'application') === false) {
                    return sprintf(__('Finance role match: %s', 'senna-finance'), $text);
                }

                return $text;
            }

            $replacements = [
                'finance role' => __('finance role', 'senna-finance'),
                'finance match' => __('finance role match', 'senna-finance'),
                'was just added to the platform' => __('was just added to your finance workspace', 'senna-finance'),
                'role alerts' => __('private equity role alerts', 'senna-finance'),
                'career alerts' => __('finance career alerts', 'senna-finance'),
                'saved roles' => __('saved private equity roles', 'senna-finance'),
                'application updates' => __('private equity application updates', 'senna-finance'),
            ];

            return str_ireplace(array_keys($replacements), array_values($replacements), $text);
        }

        private function is_cv_match_studio_job_match_notification(array $notification)
        {
            $type = sanitize_key((string) ($notification['type'] ?? ''));
            $allowed_types = [
                'dashboard_role_match',
                'role_match',
                'job_match',
                'job_alert',
                'role_alert',
                'application_update',
                'recruiter_post',
                'recruiter_update',
                'saved_list_update',
            ];
            if (in_array($type, $allowed_types, true)) {
                return true;
            }

            if (in_array($type, ['dashboard_daily_tip', 'dashboard_market_news', 'market_news', 'daily_tip'], true)) {
                return false;
            }

            $text = strtolower(wp_strip_all_tags((string) ($notification['title'] ?? '') . ' ' . (string) ($notification['message'] ?? '')));
            if (preg_match('/\b(tip|market update|news|article|insight)\b/', $text)) {
                return false;
            }

            return (bool) preg_match('/\b(role|job|match|recruiter|hiring|application|apply|saved list|daily scan)\b/', $text);
        }

        private function format_cv_match_studio_notification_preview_item(array $notification)
        {
            return [
                'id' => (int) ($notification['id'] ?? 0),
                'title' => $this->normalize_cv_match_studio_private_equity_notification_text((string) ($notification['title'] ?? ''), 'title'),
                'message' => $this->normalize_cv_match_studio_private_equity_notification_text((string) ($notification['message'] ?? ''), 'message'),
                'created_at' => (string) ($notification['created_at'] ?? current_time('mysql')),
                'is_read' => !empty($notification['is_read']),
                'action_url' => (string) ($notification['action_url'] ?? ''),
            ];
        }

        private function get_cv_match_studio_job_match_notification_fallbacks($user_id, $limit = 4)
        {
            $profile = $this->get_crm_reddit_dashboard_profile_state($user_id);
            $items = $this->get_crm_reddit_dashboard_metrics_source_items(0, $user_id, '');
            $fallbacks = [];

            foreach ((array) $items as $item) {
                if (!$this->is_crm_reddit_dashboard_recent_match_candidate((array) $item, $profile)) {
                    continue;
                }

                $role_title = trim((string) ($item['role_title'] ?? __('Finance role', 'senna-finance')));
                $company = trim((string) ($item['company'] ?? __('MENA Careers network', 'senna-finance')));
                $location = trim((string) ($item['location'] ?? ''));
                $created_at = (string) ($item['posted_at'] ?? '');
                if ($created_at === '' && !empty($item['posted_timestamp'])) {
                    $created_at = gmdate('Y-m-d H:i:s', (int) $item['posted_timestamp']);
                }
                if ($created_at === '') {
                    $created_at = current_time('mysql');
                }

                $fallbacks[] = [
                    'id' => 0,
                    'title' => __('New finance role match', 'senna-finance'),
                    'message' => $location !== ''
                        ? sprintf(__('%1$s at %2$s is available in %3$s.', 'senna-finance'), $role_title, $company, $location)
                        : sprintf(__('%1$s at %2$s is available in your finance role list.', 'senna-finance'), $role_title, $company),
                    'created_at' => $created_at,
                    'is_read' => true,
                    'action_url' => (string) ($item['view_url'] ?? ''),
                ];

                if (count($fallbacks) >= $limit) {
                    break;
                }
            }

            return $fallbacks;
        }

        private function get_cv_match_studio_notification_preview_items($user_id, $current_url = '')
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $this->seed_crm_reddit_dashboard_notifications($user_id, $current_url);

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-alert.php';
            $alert_model = new SFFC_CRM_Alert();
            $notifications = array_values(array_filter(
                (array) $alert_model->get_notifications($user_id, ['limit' => 12, 'offset' => 0]),
                function ($notification) {
                    return $this->is_cv_match_studio_job_match_notification((array) $notification);
                }
            ));
            $items = array_map(function ($notification) {
                return $this->format_cv_match_studio_notification_preview_item((array) $notification);
            }, array_slice($notifications, 0, 4));

            if (count($items) < 4) {
                $seen = [];
                foreach ($items as $item) {
                    $seen[strtolower((string) ($item['title'] ?? '') . '|' . (string) ($item['message'] ?? '') . '|' . (string) ($item['action_url'] ?? ''))] = true;
                }
                foreach ($this->get_cv_match_studio_job_match_notification_fallbacks($user_id, 4) as $fallback) {
                    $key = strtolower((string) ($fallback['title'] ?? '') . '|' . (string) ($fallback['message'] ?? '') . '|' . (string) ($fallback['action_url'] ?? ''));
                    if (!isset($seen[$key])) {
                        $items[] = $fallback;
                        $seen[$key] = true;
                    }
                    if (count($items) >= 4) {
                        break;
                    }
                }
            }

            return array_slice($items, 0, 4);
        }

        private function get_cv_match_studio_message_preview_items($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            $this->ensure_crm_reddit_dashboard_paula_thread($user_id);

            $conversation_model = new SFFC_CRM_Conversation();
            $conversations = (array) $conversation_model->get_user_conversations($user_id, [
                'limit' => 4,
                'offset' => 0,
                'orderby' => 'last_message_at',
                'order' => 'DESC',
            ]);
            $conversations = $this->decorate_crm_reddit_dashboard_inbox_conversations($conversations);

            return array_map(function ($conversation) {
                return [
                    'conversation_id' => (int) ($conversation['id'] ?? 0),
                    'name' => (string) ($conversation['recruiter_name'] ?? __('MENA Careers', 'senna-finance')),
                    'meta' => (string) ($conversation['recruiter_firm'] ?? ''),
                    'photo' => (string) ($conversation['recruiter_photo'] ?? ''),
                    'preview' => (string) ($conversation['last_message_preview'] ?? ''),
                    'timestamp' => (string) ($conversation['last_message_at'] ?? current_time('mysql')),
                    'unread_count' => (int) ($conversation['unread_count'] ?? 0),
                ];
            }, $conversations);
        }

