        private function maybe_notify_admin_of_crm_reddit_dashboard_message($user_id, $conversation_id, $body)
        {
            $admin_email = sanitize_email((string) get_option('admin_email', ''));
            if ($admin_email === '') {
                return;
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';

            $conversation_model = new SFFC_CRM_Conversation();
            $recruiter_model = new SFFC_CRM_Recruiter();
            $conversation = $conversation_model->get($conversation_id);
            if (empty($conversation['recruiter_id'])) {
                return;
            }

            $recruiter = $recruiter_model->get((int) $conversation['recruiter_id']);
            if (empty($recruiter) || strcasecmp((string) ($recruiter['email'] ?? ''), $admin_email) !== 0) {
                return;
            }

            $user = get_user_by('id', $user_id);
            $subject = sprintf(__('New dashboard message from %s', 'senna-finance'), $user instanceof WP_User ? ($user->display_name ?: $user->user_login) : __('a MENA Careers member', 'senna-finance'));
            $message = sprintf(
                "%s\n\n%s",
                sprintf(__('A member replied to Paula in the dashboard inbox.' . "\n\n" . 'From: %s', 'senna-finance'), $user instanceof WP_User ? ($user->user_email ?: $user->user_login) : __('Unknown', 'senna-finance')),
                wp_strip_all_tags($body)
            );
            $headers = ['Reply-To: ' . ($user instanceof WP_User ? $user->user_email : $admin_email)];
            wp_mail($admin_email, $subject, $message, $headers);
        }

        public function ajax_reddit_load_more()
        {
            check_ajax_referer('sffc_crm_reddit_load_more', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $per_page = isset($_POST['per_page']) ? max(1, min(18, absint($_POST['per_page']))) : 8;
            $selected_group = sanitize_title((string) wp_unslash($_POST['reddit_group'] ?? ''));
            $search_term = sanitize_text_field((string) wp_unslash($_POST['search_term'] ?? ''));
            $loaded_ids = isset($_POST['loaded_ids']) ? array_map('absint', (array) wp_unslash($_POST['loaded_ids'])) : [];
            $loaded_ids = array_values(array_filter($loaded_ids));
            $user_id = get_current_user_id();

            $page_data = $this->get_crm_reddit_feed_page_data($jobs_post_id, $per_page, $user_id, $selected_group, $search_term, $loaded_ids, false);
            $items = (array) ($page_data['items'] ?? []);

            if (empty($items)) {
                wp_send_json_success([
                    'markup' => '',
                    'has_more' => false,
                    'loaded_ids' => $loaded_ids,
                    'loaded_count' => count($loaded_ids),
                ]);
            }

            $returned_ids = array_values(array_filter(array_map(static function ($item) {
                return ($item['source'] ?? '') === 'crm' ? (int) ($item['crm_post_id'] ?? 0) : 0;
            }, $items)));
            $all_loaded_ids = array_values(array_unique(array_merge($loaded_ids, $returned_ids)));

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_feed_cards_markup($items, is_user_logged_in(), $selected_group),
                'has_more' => !empty($page_data['has_more']),
                'loaded_ids' => $all_loaded_ids,
                'loaded_count' => count($all_loaded_ids),
            ]);
        }

        private function build_crm_reddit_outreach_context($user_id, array $request)
        {
            $jobs_post_id = (int) ($request['jobs_post_id'] ?? 0);
            $role_context = $jobs_post_id > 0 ? $this->build_crm_reddit_networking_context($jobs_post_id) : null;
            $resume_payload = $this->resolve_crm_reddit_dashboard_outreach_cv_text($user_id, (string) ($request['cv_source'] ?? 'active'));
            $inline_cv_text = sanitize_textarea_field((string) ($request['cv_text'] ?? ''));

            $target_channel = sanitize_key((string) ($request['target_channel'] ?? 'linkedin_inmail'));
            $outreach_context = sanitize_key((string) ($request['outreach_context'] ?? 'enquiring_about_role'));
            $custom_role_title = sanitize_text_field((string) ($request['custom_role_title'] ?? ''));
            $recipient_name = sanitize_text_field((string) ($request['recipient_name'] ?? ''));
            $recipient_role = sanitize_text_field((string) ($request['recipient_role'] ?? ''));

            if ($recipient_name === '' && !empty($role_context['recruiter_name'])) {
                $recipient_name = sanitize_text_field((string) $role_context['recruiter_name']);
            }

            if ($recipient_role === '' && !empty($role_context['recruiter_title'])) {
                $recipient_role = sanitize_text_field((string) $role_context['recruiter_title']);
            }

            return [
                'jobs_post_id' => $jobs_post_id,
                'role_title' => $custom_role_title !== '' ? $custom_role_title : (string) ($role_context['role_title'] ?? ''),
                'company' => (string) ($role_context['company'] ?? ''),
                'location' => (string) ($role_context['location'] ?? ''),
                'industry' => (string) ($role_context['industry'] ?? ''),
                'job_description' => (string) ($role_context['job_description'] ?? ''),
                'keywords' => (array) ($role_context['keywords'] ?? []),
                'skills' => (array) ($role_context['skills'] ?? []),
                'requirements' => (array) ($role_context['requirements'] ?? []),
                'recruiter_name' => (string) ($role_context['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($role_context['recruiter_title'] ?? ''),
                'recruiter_firm' => (string) ($role_context['recruiter_firm'] ?? ''),
                'recruiter_email' => (string) ($role_context['recruiter_email'] ?? ''),
                'recruiter_linkedin' => (string) ($role_context['recruiter_linkedin'] ?? ''),
                'cv_source' => (string) ($request['cv_source'] ?? ''),
                'cv_text' => $inline_cv_text !== '' ? $inline_cv_text : (string) ($resume_payload['cv_text'] ?? ''),
                'outreach_context' => $outreach_context,
                'custom_role_title' => $custom_role_title,
                'target_channel' => $target_channel,
                'recipient_name' => $recipient_name,
                'recipient_role' => $recipient_role,
                'user_context' => sanitize_textarea_field((string) ($request['user_context'] ?? '')),
            ];
        }

        private function resolve_crm_reddit_dashboard_outreach_cv_text($user_id, $source)
        {
            $source = trim((string) $source);
            if ($source === '' || $source === 'active') {
                return $this->get_crm_reddit_active_resume_text($user_id);
            }

            if ($source === 'pasted') {
                $text = $this->sanitize_crm_reddit_pasted_cv_text((string) get_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), true));
                return [
                    'cv_text' => $text,
                    'has_cv' => $text !== '',
                    'source' => $text !== '' ? 'pasted' : '',
                ];
            }

            if (strpos($source, 'upload:') === 0) {
                $upload_id = absint(substr($source, 7));
                if ($upload_id > 0) {
                    return $this->build_crm_reddit_active_upload_resume_payload($this->get_crm_reddit_resume_upload($user_id, $upload_id));
                }
            }

            return [
                'cv_text' => '',
                'has_cv' => false,
                'source' => '',
            ];
        }

        private function get_crm_reddit_feed_page_data($jobs_post_id, $per_page, $user_id, $selected_group, $search_term, array $loaded_crm_ids = [], $include_pinned = true)
        {
            $per_page = max(1, min(18, absint($per_page)));
            $linked_jobs_item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            $pinned_item = $include_pinned ? $linked_jobs_item : [];
            $exclude_crm_id = !empty($linked_jobs_item['crm_post_id']) ? (int) $linked_jobs_item['crm_post_id'] : 0;
            $exclude_ids = $loaded_crm_ids;
            if ($exclude_crm_id > 0) {
                $exclude_ids[] = $exclude_crm_id;
            }
            $exclude_ids = array_values(array_unique(array_filter(array_map('absint', $exclude_ids))));
            $crm_total_count = $this->get_crm_reddit_feed_total_count($selected_group, $search_term, $exclude_crm_id);
            $feed_posts = $this->get_crm_reddit_feed_posts_batch($per_page + 1, $user_id, $selected_group, $search_term, $exclude_ids);
            $items = [];
            if (!empty($pinned_item)) {
                $items[] = $pinned_item;
            }

            foreach ((array) $feed_posts as $feed_post) {
                $crm_id = (int) ($feed_post['id'] ?? 0);
                if ($exclude_crm_id > 0 && $crm_id === $exclude_crm_id) {
                    continue;
                }

                $items[] = $this->build_crm_reddit_crm_item($feed_post);
            }

            if ($search_term !== '') {
                $exclude_jobs_ids = [];
                if (!empty($pinned_item['wp_post_id'])) {
                    $exclude_jobs_ids[] = (int) $pinned_item['wp_post_id'];
                }
                foreach ($items as $item) {
                    $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                    if ($wp_post_id > 0) {
                        $exclude_jobs_ids[] = $wp_post_id;
                    }
                }
                $jobs_matches = $this->get_crm_reddit_jobs_search_items($per_page + 1, $search_term, $exclude_jobs_ids);
                foreach ($jobs_matches as $jobs_item) {
                    $items[] = $jobs_item;
                }
            }

            $crm_items_count = count($items) - (!empty($pinned_item) ? 1 : 0);
            $has_more = $crm_items_count > $per_page;
            if ($has_more) {
                $items = array_slice($items, 0, $per_page + (!empty($pinned_item) ? 1 : 0));
                $crm_items_count = $per_page;
            }

            return [
                'pinned_item' => $pinned_item,
                'items' => $items,
                'has_more' => $has_more,
                'total_crm_count' => $crm_total_count,
            ];
        }

