        private function get_crm_reddit_dashboard_metrics_source_items($jobs_post_id, $user_id, $search_term = '')
        {
            $search_term = trim((string) $search_term);
            $cache_key = '';
            if ($search_term === '') {
                $cache_key = 'sffc_crm_dash_metrics_items_' . md5((int) $jobs_post_id . '|' . (int) $user_id);
                $cached = get_transient($cache_key);
                if (is_array($cached)) {
                    return $cached;
                }
            }

            $items = [];
            $linked_jobs_item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            $exclude_ids = [];
            $exclude_jobs_ids = [];

            if (!empty($linked_jobs_item)) {
                $items[] = $linked_jobs_item;
                if (!empty($linked_jobs_item['crm_post_id'])) {
                    $exclude_ids[] = (int) $linked_jobs_item['crm_post_id'];
                }
                if (!empty($linked_jobs_item['wp_post_id'])) {
                    $exclude_jobs_ids[] = (int) $linked_jobs_item['wp_post_id'];
                }
            }

            $feed_posts = $this->get_crm_reddit_feed_posts_batch(40, $user_id, '', $search_term, $exclude_ids);
            foreach ((array) $feed_posts as $feed_post) {
                $built_item = $this->build_crm_reddit_dashboard_crm_item((array) $feed_post);
                $items[] = $built_item;
                if (!empty($built_item['wp_post_id'])) {
                    $exclude_jobs_ids[] = (int) $built_item['wp_post_id'];
                }
            }

            if ($search_term !== '') {
                foreach ($this->get_crm_reddit_jobs_search_items(20, $search_term, $exclude_jobs_ids) as $jobs_item) {
                    $items[] = $jobs_item;
                }
            }

            $items = $this->filter_cv_match_studio_frontend_region_items($items);

            if ($cache_key !== '') {
                set_transient($cache_key, $items, 10 * MINUTE_IN_SECONDS);
            }

            return $items;
        }

        private function filter_cv_match_studio_frontend_region_items(array $items)
        {
            return array_values($items);
        }

        private function is_cv_match_studio_frontend_region_item(array $item)
        {
            return true;
        }

        private function filter_cv_match_studio_frontend_private_equity_items(array $items)
        {
            $filtered = array_values(array_filter($items, function ($item) {
                return $this->is_cv_match_studio_frontend_private_equity_item((array) $item);
            }));

            return $filtered;
        }

        private function is_cv_match_studio_frontend_private_equity_item(array $item)
        {
            $signals = array_filter([
                (string) ($item['location'] ?? ''),
                (string) ($item['location_city'] ?? ''),
                (string) ($item['location_country'] ?? ''),
                (string) ($item['role_title'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
                (string) ($item['company'] ?? ''),
            ]);

            foreach ($signals as $signal) {
                if ($this->is_cv_match_studio_frontend_private_equity_text((string) $signal)) {
                    return true;
                }
            }

            foreach ((array) ($item['keywords'] ?? []) as $keyword) {
                if ($this->is_cv_match_studio_frontend_private_equity_text((string) $keyword)) {
                    return true;
                }
            }

            return false;
        }

