        private function get_crm_reddit_jobs_search_items($limit, $search_term = '', array $exclude_jobs_post_ids = [])
        {
            global $wpdb;

            $limit = max(1, min(5000, (int) $limit));
            $search_term = trim((string) $search_term);
            if ($search_term === '') {
                return [];
            }

            $posts_table = $wpdb->posts;
            $postmeta_table = $wpdb->postmeta;
            $where = [
                "p.post_type = 'jobs'",
                "p.post_status = 'publish'",
            ];
            $params = [];
            $search_like = '%' . $wpdb->esc_like($search_term) . '%';
            $where[] = "(
                p.post_title LIKE %s
                OR p.post_content LIKE %s
                OR EXISTS (
                    SELECT 1
                    FROM {$postmeta_table} pm
                    WHERE pm.post_id = p.ID
                      AND pm.meta_key IN ('jobDescription', '_job_title', '_company_name', 'hiringOrganization', 'addressLocality', 'addressCountry', 'sector', '_sector')
                      AND pm.meta_value LIKE %s
                )
            )";
            array_push($params, $search_like, $search_like, $search_like);

            $exclude_jobs_post_ids = array_values(array_unique(array_filter(array_map('absint', $exclude_jobs_post_ids))));
            if (!empty($exclude_jobs_post_ids)) {
                $placeholders = implode(',', array_fill(0, count($exclude_jobs_post_ids), '%d'));
                $where[] = "p.ID NOT IN ({$placeholders})";
                $params = array_merge($params, $exclude_jobs_post_ids);
            }

            $sql = "SELECT p.ID
                    FROM {$posts_table} p
                    WHERE " . implode(' AND ', $where) . "
                    ORDER BY p.post_date DESC
                    LIMIT %d";
            $params[] = $limit;

            $job_ids = $wpdb->get_col($wpdb->prepare($sql, $params));
            $items = [];
            foreach ((array) $job_ids as $job_id) {
                $item = $this->get_crm_reddit_jobs_item((int) $job_id);
                if (!empty($item)) {
                    $items[] = $item;
                }
            }

            return $items;
        }

        private function get_crm_reddit_feed_posts_batch($limit, $user_id, $selected_group, $search_term, array $exclude_crm_ids = [])
        {
            global $wpdb;

            if ($user_id && function_exists('sffc_crm_user_is_excluded') && sffc_crm_user_is_excluded((int) $user_id)) {
                return [];
            }

            $limit = max(1, min(5000, (int) $limit));
            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $relationships_table = $wpdb->prefix . 'sffc_crm_post_group_relationships';
            $groups_table = $wpdb->prefix . 'sffc_crm_post_groups';
            $early_bird_exclusion_select = $this->get_crm_posts_early_bird_exclusion_select('p');

            $joins = [
                "LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id",
            ];
            $where = [
                "p.is_active = 1",
                "p.admin_approved = 1",
                "(p.post_status IS NULL OR p.post_status = 'open')",
            ];
            $params = [];

            if ($selected_group !== '') {
                $joins[] = "INNER JOIN {$relationships_table} pgr ON p.id = pgr.post_id";
                $joins[] = "INNER JOIN {$groups_table} g ON g.id = pgr.group_id";
                $where[] = "g.slug = %s";
                $params[] = $selected_group;
            }

            if ($search_term !== '') {
                $search_like = '%' . $wpdb->esc_like($search_term) . '%';
                $where[] = "(p.role_title LIKE %s OR p.content LIKE %s OR p.company LIKE %s OR p.keywords LIKE %s OR r.name LIKE %s OR r.firm LIKE %s)";
                array_push($params, $search_like, $search_like, $search_like, $search_like, $search_like, $search_like);
            }

            if (!empty($exclude_crm_ids)) {
                $placeholders = implode(',', array_fill(0, count($exclude_crm_ids), '%d'));
                $where[] = "p.id NOT IN ({$placeholders})";
                $params = array_merge($params, $exclude_crm_ids);
            }

            $sql = "SELECT DISTINCT p.id, p.role_title, p.company, p.location, p.location_country,
                           p.salary_text, p.seniority, p.sector, p.content, p.content_snippet, p.posted_at,
                           p.is_remote, p.is_hybrid, p.application_url, p.wp_post_id, p.company_logo, p.keywords,
                           p.experience_years, p.is_featured, {$early_bird_exclusion_select},
                           COALESCE(NULLIF(p.company_logo, ''), r.default_company_logo) AS company_logo,
                           r.name as recruiter_name, r.firm as recruiter_firm,
                           r.photo_url as recruiter_photo, r.title as recruiter_title,
                           r.email as recruiter_email, r.linkedin_url as recruiter_linkedin,
                           r.sectors as recruiter_specializations
                    FROM {$posts_table} p
                    " . implode("\n", $joins) . "
                    WHERE " . implode(' AND ', $where) . "
                    ORDER BY p.is_featured DESC, p.posted_at DESC
                    LIMIT %d";

            $params[] = $limit;

            return $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);
        }

        private function get_crm_reddit_feed_total_count($selected_group, $search_term, $exclude_crm_id = 0)
        {
            global $wpdb;

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $relationships_table = $wpdb->prefix . 'sffc_crm_post_group_relationships';
            $groups_table = $wpdb->prefix . 'sffc_crm_post_groups';

            $joins = [
                "LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id",
            ];
            $where = [
                "p.is_active = 1",
                "p.admin_approved = 1",
                "(p.post_status IS NULL OR p.post_status = 'open')",
            ];
            $params = [];

            if ($selected_group !== '') {
                $joins[] = "INNER JOIN {$relationships_table} pgr ON p.id = pgr.post_id";
                $joins[] = "INNER JOIN {$groups_table} g ON g.id = pgr.group_id";
                $where[] = "g.slug = %s";
                $params[] = $selected_group;
            }

            if ($search_term !== '') {
                $search_like = '%' . $wpdb->esc_like($search_term) . '%';
                $where[] = "(p.role_title LIKE %s OR p.content LIKE %s OR p.company LIKE %s OR p.keywords LIKE %s OR r.name LIKE %s OR r.firm LIKE %s)";
                array_push($params, $search_like, $search_like, $search_like, $search_like, $search_like, $search_like);
            }

            if ($exclude_crm_id > 0) {
                $where[] = "p.id != %d";
                $params[] = $exclude_crm_id;
            }

            $sql = "SELECT COUNT(DISTINCT p.id)
                    FROM {$posts_table} p
                    " . implode("\n", $joins) . "
                    WHERE " . implode(' AND ', $where);

            if (!empty($params)) {
                $sql = $wpdb->prepare($sql, $params);
            }

            return (int) $wpdb->get_var($sql);
        }

        private function render_crm_reddit_feed_cards_markup(array $feed_items, $is_logged_in, $selected_group = '')
        {
            ob_start();
            foreach ($feed_items as $feed_item) {
                echo $this->render_crm_reddit_feed_card($feed_item, $is_logged_in, $selected_group);
            }

            return ob_get_clean();
