        private function get_crm_reddit_membership_url()
        {
            $default_url = home_url('/memberships/');

            try {
                if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                    $integration = SFFC_CRM_MemberPress_Integration::get_instance();
                    if ($integration && method_exists($integration, 'get_upgrade_url')) {
                        return (string) $integration->get_upgrade_url('pro');
                    }
                }
            } catch (\Throwable $throwable) {
                error_log('SFFC Reddit Feed membership URL error: ' . $throwable->getMessage());
            }

            return (string) apply_filters('sffc_gap_analyzer_membership_url', $default_url);
        }

        private function get_crm_reddit_upgrade_capture_material_preview_items(array $context)
        {
            $preview_items = [];
            $pack_labels = array_values(array_filter(array_map('sanitize_text_field', (array) ($context['pack_labels'] ?? []))));
            if (empty($pack_labels)) {
                $pack_labels = [
                    __('Tailored CV Draft', 'senna-finance'),
                    __('Cover Letter', 'senna-finance'),
                    __('Interview Questions', 'senna-finance'),
                    __('Hiring Guide', 'senna-finance'),
                ];
            }

            foreach (array_slice($pack_labels, 0, 4) as $label) {
                $preview_items[] = [
                    'label' => $label,
                    'meta' => __('Built for this role', 'senna-finance'),
                ];
            }

            return $preview_items;
        }

        private function get_crm_reddit_upgrade_capture_keyword_preview_items(array $context)
        {
            $keyword_labels = array_values(array_filter(array_map('sanitize_text_field', (array) ($context['keywords'] ?? []))));
            if (empty($keyword_labels)) {
                $keyword_labels = [
                    __('Valuation', 'senna-finance'),
                    __('Due Diligence', 'senna-finance'),
                    __('Portfolio Construction', 'senna-finance'),
                ];
            }

            $defaults = [
                __('Usually missing from generic finance CVs', 'senna-finance'),
                __('Common shortlist filter in finance searches', 'senna-finance'),
                __('Signals clearer role fit to recruiters', 'senna-finance'),
            ];
            $preview_items = [];
            foreach (array_slice($keyword_labels, 0, 3) as $index => $label) {
                $preview_items[] = [
                    'label' => $label,
                    'value' => max(52, 84 - ($index * 12)),
                    'note' => $defaults[$index] ?? __('High-value keyword signal', 'senna-finance'),
                ];
            }

            return $preview_items;
        }

