        public function maybe_schedule_crm_reddit_cv_scan_refresh()
        {
            $current_version = $this->get_crm_reddit_cv_ats_scan_plugin_version();
            $stored_version = (string) get_option($this->get_crm_reddit_cv_scan_refresh_version_option_key(), '');

            if ($stored_version === $current_version) {
                return;
            }

            update_option($this->get_crm_reddit_cv_scan_refresh_version_option_key(), $current_version, false);
            update_option($this->get_crm_reddit_cv_scan_refresh_state_option_key(), [
                'plugin_version' => $current_version,
                'offset' => 0,
                'batch_size' => 20,
                'started_at' => current_time('mysql'),
            ], false);

            if (!wp_next_scheduled('sffc_crm_reddit_refresh_cv_scans_batch')) {
                wp_schedule_single_event(time() + 10, 'sffc_crm_reddit_refresh_cv_scans_batch');
            }
        }

        public function process_crm_reddit_cv_scan_refresh_batch()
        {
            global $wpdb;

            $state = get_option($this->get_crm_reddit_cv_scan_refresh_state_option_key(), []);
            if (!is_array($state) || empty($state['plugin_version'])) {
                return;
            }

            if ((string) $state['plugin_version'] !== $this->get_crm_reddit_cv_ats_scan_plugin_version()) {
                return;
            }

            $offset = max(0, absint($state['offset'] ?? 0));
            $batch_size = max(1, min(50, absint($state['batch_size'] ?? 20)));
            $meta_keys = [
                $this->get_crm_reddit_pasted_cv_meta_key(),
                $this->get_crm_reddit_active_resume_meta_key(),
            ];
            $placeholders = implode(', ', array_fill(0, count($meta_keys), '%s'));
            $sql = $wpdb->prepare(
                "SELECT DISTINCT user_id
                 FROM {$wpdb->usermeta}
                 WHERE meta_key IN ({$placeholders})
                 ORDER BY user_id ASC
                 LIMIT %d OFFSET %d",
                array_merge($meta_keys, [$batch_size, $offset])
            );
            $user_ids = array_map('intval', (array) $wpdb->get_col($sql));

            if (empty($user_ids)) {
                delete_option($this->get_crm_reddit_cv_scan_refresh_state_option_key());
                return;
            }

            foreach ($user_ids as $user_id) {
                $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
                if (!empty($resume_payload['has_cv']) && !empty($resume_payload['cv_text'])) {
                    $this->maybe_queue_crm_reddit_cv_ats_scan($user_id, $resume_payload);
                }
            }

            if (count($user_ids) < $batch_size) {
                delete_option($this->get_crm_reddit_cv_scan_refresh_state_option_key());
                return;
            }

            $state['offset'] = $offset + count($user_ids);
            update_option($this->get_crm_reddit_cv_scan_refresh_state_option_key(), $state, false);
            wp_schedule_single_event(time() + 20, 'sffc_crm_reddit_refresh_cv_scans_batch');
        }

