        private function get_crm_reddit_account_user($user_id)
        {
            $cache_key = 'sffc_crm_dash_account_user_' . (int) $user_id;
            $cached = get_transient($cache_key);
            if (is_array($cached) && !empty($cached['user_id'])) {
                if (is_user_logged_in() && get_current_user_id() === (int) $user_id) {
                    $membership = $this->get_crm_reddit_membership_summary($user_id);
                    $cached['membership_label'] = (string) ($membership['product_name'] ?: $membership['tier_label']);
                    $cached['membership_tier'] = (string) ($membership['tier'] ?? 'free');
                    $cached['membership_url'] = (string) ($membership['upgrade_url'] ?? $this->get_crm_reddit_membership_url());
                }
                return $cached;
            }

            $user = get_user_by('id', $user_id);
            if (!$user instanceof WP_User) {
                return [];
            }

            $membership = $this->get_crm_reddit_membership_summary($user_id);
            $display_name = $user->display_name ?: $user->user_login;
            $avatar_url = $this->get_crm_reddit_profile_avatar_url($user_id);

            $payload = [
                'user_id' => $user_id,
                'display_name' => $display_name,
                'email' => (string) $user->user_email,
                'avatar_url' => $avatar_url !== '' ? $avatar_url : (string) get_avatar_url($user_id, ['size' => 96]),
                'avatar_initial' => strtoupper(substr(trim($display_name), 0, 1)),
                'membership_label' => (string) ($membership['product_name'] ?: $membership['tier_label']),
                'membership_tier' => (string) ($membership['tier'] ?? 'free'),
                'membership_url' => (string) ($membership['upgrade_url'] ?? $this->get_crm_reddit_membership_url()),
                'logout_url' => wp_logout_url(get_permalink(get_queried_object_id()) ?: home_url('/')),
            ];

            set_transient($cache_key, $payload, 10 * MINUTE_IN_SECONDS);

            return $payload;
        }

        private function get_crm_reddit_configured_memberpress_plan_map()
        {
            static $plan_map = null;

            if (is_array($plan_map)) {
                return $plan_map;
            }

            $plan_map = [];
            foreach ((array) $this->get_subscription_plans() as $plan) {
                $product_id = !empty($plan['memberpress_product_id'])
                    ? absint($plan['memberpress_product_id'])
                    : $this->extract_memberpress_product_id_from_shortcode((string) ($plan['shortcode'] ?? ''));

                if ($product_id <= 0 || isset($plan_map[$product_id])) {
                    continue;
                }

                $plan_map[$product_id] = [
                    'name' => trim((string) ($plan['name'] ?? '')),
                    'slug' => sanitize_title((string) ($plan['slug'] ?? ($plan['name'] ?? ''))),
                ];
            }

            return $plan_map;
        }

        private function get_crm_reddit_primary_memberpress_subscription(array $subscriptions)
        {
            if (empty($subscriptions)) {
                return [];
            }

            $normalized = array_values(array_filter(array_map(static function ($subscription) {
                return is_array($subscription) ? $subscription : [];
            }, $subscriptions)));

            if (empty($normalized)) {
                return [];
            }

            usort($normalized, static function ($left, $right) {
                $status_rank = static function ($status) {
                    $status = strtolower((string) $status);
                    if (in_array($status, ['active', 'confirmed', 'complete'], true)) {
                        return 3;
                    }
                    if (in_array($status, ['trial', 'pending'], true)) {
                        return 2;
                    }
                    return 1;
                };

                $left_rank = $status_rank($left['status'] ?? '');
                $right_rank = $status_rank($right['status'] ?? '');
                if ($left_rank !== $right_rank) {
                    return $right_rank <=> $left_rank;
                }

                $left_total = (float) ($left['total'] ?? $left['price'] ?? 0);
                $right_total = (float) ($right['total'] ?? $right['price'] ?? 0);
                if ($left_total !== $right_total) {
                    return $right_total <=> $left_total;
                }

                $left_created = !empty($left['created_at']) ? strtotime((string) $left['created_at']) : 0;
                $right_created = !empty($right['created_at']) ? strtotime((string) $right['created_at']) : 0;
                if ($left_created !== $right_created) {
                    return $right_created <=> $left_created;
                }

                return ((int) ($right['id'] ?? 0)) <=> ((int) ($left['id'] ?? 0));
            });

            return $normalized[0] ?? [];
        }

        private function get_crm_reddit_memberpress_plan_name(array $subscription, $fallback_name = '')
        {
            $product_id = absint($subscription['product_id'] ?? 0);
            $plan_map = $this->get_crm_reddit_configured_memberpress_plan_map();

            if ($product_id > 0 && !empty($plan_map[$product_id]['name'])) {
                return (string) $plan_map[$product_id]['name'];
            }

            $product_name = trim((string) ($subscription['product_name'] ?? ''));
            if ($product_name !== '') {
                return $product_name;
            }

            return (string) $fallback_name;
        }

        private function infer_crm_reddit_membership_tier_from_subscription(array $subscription, $fallback_tier = 'free')
        {
            $product_id = absint($subscription['product_id'] ?? 0);
            $plan_map = $this->get_crm_reddit_configured_memberpress_plan_map();

            $candidates = [];
            if ($product_id > 0 && !empty($plan_map[$product_id])) {
                $candidates[] = (string) ($plan_map[$product_id]['slug'] ?? '');
                $candidates[] = (string) ($plan_map[$product_id]['name'] ?? '');
            }
            $candidates[] = (string) ($subscription['product_name'] ?? '');

            foreach ($candidates as $candidate) {
                $candidate = strtolower(trim($candidate));
                if ($candidate === '') {
                    continue;
                }
                if (str_contains($candidate, 'insider')) {
                    return 'insider';
                }
                if (str_contains($candidate, 'pro')) {
                    return 'pro';
                }
                if (str_contains($candidate, 'basic')) {
                    return 'basic';
                }
            }

            return (string) $fallback_tier;
        }

        private function get_crm_reddit_membership_summary($user_id)
        {
            $tier = 'free';
            $tier_label = __('Free access', 'senna-finance');
            $product_name = '';
            $status_label = __('Not subscribed', 'senna-finance');
            $expires_label = '';
            $manage_url = $this->get_crm_reddit_membership_url();
            $billing_url = $this->get_crm_reddit_membership_url();
            $upgrade_url = $this->get_crm_reddit_membership_url();
            $features = [
                __('Role-matched recruiter-led opportunities', 'senna-finance'),
                __('Application review and outreach support', 'senna-finance'),
                __('Premium documents and hiring insights', 'senna-finance'),
            ];

            try {
                if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                    $crm_integration = SFFC_CRM_MemberPress_Integration::get_instance();
                    if ($crm_integration && method_exists($crm_integration, 'get_crm_tier')) {
                        $tier = (string) $crm_integration->get_crm_tier($user_id);
                    }
                    if ($crm_integration && method_exists($crm_integration, 'get_upgrade_url')) {
                        $upgrade_url = (string) $crm_integration->get_upgrade_url($tier === 'free' ? 'basic' : 'pro');
                    }
                }
            } catch (\Throwable $throwable) {
                error_log('SFFC Reddit Feed CRM tier error: ' . $throwable->getMessage());
            }

            try {
                if (class_exists('SFFC_MemberPress_Integration')) {
                    $mepr_integration = SFFC_MemberPress_Integration::get_instance();

                    if ($mepr_integration && method_exists($mepr_integration, 'get_user_subscriptions')) {
                        $subscriptions = (array) $mepr_integration->get_user_subscriptions($user_id);
                        $subscription = $this->get_crm_reddit_primary_memberpress_subscription($subscriptions);
                        if (!empty($subscription)) {
                            $tier = $this->infer_crm_reddit_membership_tier_from_subscription($subscription, $tier);
                            $product_name = $this->get_crm_reddit_memberpress_plan_name($subscription, $product_name);
                            $status_value = strtolower((string) ($subscription['status'] ?? ''));
                            $status_label = $status_value !== '' ? ucfirst($status_value) : __('Active', 'senna-finance');

                            if (!empty($subscription['expires_at']) && $subscription['expires_at'] !== '0000-00-00 00:00:00') {
                                $expires_label = mysql2date('j M Y', (string) $subscription['expires_at']);
                            }
                        }
                    }

                    if ($mepr_integration && method_exists($mepr_integration, 'get_subscription_urls')) {
                        $subscription_urls = (array) $mepr_integration->get_subscription_urls($user_id);
                        $manage_url = !empty($subscription_urls['subscriptions_url']) ? (string) $subscription_urls['subscriptions_url'] : $manage_url;
                        $billing_url = !empty($subscription_urls['billing_url']) ? (string) $subscription_urls['billing_url'] : $billing_url;
                    }
                }
            } catch (\Throwable $throwable) {
                error_log('SFFC Reddit Feed MemberPress summary error: ' . $throwable->getMessage());
            }

            $tier_labels = [
                'free' => __('Free access', 'senna-finance'),
                'basic' => __('Basic membership', 'senna-finance'),
                'pro' => __('Pro membership', 'senna-finance'),
                'insider' => __('MENA Careers Member', 'senna-finance'),
            ];
            $tier_label = $tier_labels[$tier] ?? ucfirst($tier);

            if ($product_name === '') {
                $product_name = $tier_label;
                if ($tier !== 'free') {
                    $status_label = __('Active', 'senna-finance');
                }
            }

            if ($tier === 'insider') {
                $features = [
                    __('Direct recruiter introductions and outreach priority', 'senna-finance'),
                    __('Full AI review tools and premium application materials', 'senna-finance'),
                    __('Highest visibility across roles, groups, and private opportunities', 'senna-finance'),
                ];
            } elseif ($tier === 'pro') {
                $features = [
                    __('Full recruiter-led feed access and hidden-role unlocks', 'senna-finance'),
                    __('Positioning review, documents, and premium insights', 'senna-finance'),
                    __('Broader messaging and outreach support', 'senna-finance'),
                ];
            } elseif ($tier === 'basic') {
                $features = [
                    __('Early-bird roles and premium application materials', 'senna-finance'),
                    __('Structured recruiter discovery and saved groups', 'senna-finance'),
                    __('Sharper application support across the platform', 'senna-finance'),
                ];
            }

            return [
                'tier' => $tier,
                'tier_label' => $tier_label,
                'product_name' => $product_name,
                'status_label' => $status_label,
                'expires_label' => $expires_label,
                'manage_url' => $manage_url,
                'billing_url' => $billing_url,
                'upgrade_url' => $upgrade_url,
                'features' => $features,
            ];
        }

        private function get_crm_reddit_profile_avatar_url($user_id, array $account_user = [])
        {
            $default_guest_avatar = 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp';
            if ((int) $user_id <= 0) {
                $guest_avatar = (string) ($account_user['avatar_url'] ?? '');
                return $guest_avatar !== '' ? $guest_avatar : $default_guest_avatar;
            }

            $meta_key = class_exists('SFFC_User_Preferences')
                ? SFFC_User_Preferences::META_PROFILE_AVATAR
                : 'sffc_profile_avatar';
            $custom_avatar = esc_url_raw((string) get_user_meta($user_id, $meta_key, true));

            if ($custom_avatar !== '') {
                return $custom_avatar;
            }

            if (!empty($account_user['avatar_url'])) {
                return (string) $account_user['avatar_url'];
            }

            $gravatar_data = get_avatar_data($user_id, ['size' => 160, 'default' => '404']);
            if (!empty($gravatar_data['found_avatar']) && !empty($gravatar_data['url'])) {
                return (string) $gravatar_data['url'];
            }

            return $default_guest_avatar;
        }

        private function get_crm_reddit_profile_cover_url($user_id)
        {
            $default_cover = 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1800&q=80';
            $custom_cover = (int) $user_id > 0 ? esc_url_raw((string) get_user_meta((int) $user_id, 'sffc_profile_cover', true)) : '';

            return $custom_cover !== '' ? $custom_cover : $default_cover;
        }

        private function get_crm_reddit_public_profile_slug($user_id)
        {
            $user = get_user_by('id', (int) $user_id);
            if (!$user instanceof WP_User) {
                return '';
            }

            $stored_slug = sanitize_title((string) get_user_meta((int) $user_id, 'sffc_public_profile_slug', true));
            if ($stored_slug !== '') {
                return $stored_slug;
            }

            $base_slug = sanitize_title((string) ($user->user_nicename ?: $user->user_login ?: ('member-' . (int) $user_id)));
            if ($base_slug === '') {
                $base_slug = 'member-' . (int) $user_id;
            }

            $slug = $base_slug;
            $suffix = 2;
            while (($existing_user = get_user_by('slug', $slug)) instanceof WP_User && (int) $existing_user->ID !== (int) $user_id) {
                $slug = $base_slug . '-' . $suffix;
                $suffix++;
            }

            update_user_meta((int) $user_id, 'sffc_public_profile_slug', $slug);
            return $slug;
        }

        private function get_crm_reddit_public_profile_url($user_id)
        {
            $slug = $this->get_crm_reddit_public_profile_slug($user_id);
            return $slug !== '' ? add_query_arg('profile', $slug, home_url('/terminal/')) : home_url('/terminal/?tab=profile');
        }

        private function get_crm_reddit_user_id_by_public_profile_slug($slug)
        {
            $slug = sanitize_title((string) $slug);
            if ($slug === '') {
                return 0;
            }

            $user = get_user_by('slug', $slug);
            if ($user instanceof WP_User && (int) $user->ID > 0) {
                return (int) $user->ID;
            }

            $users = get_users([
                'number' => 1,
                'fields' => 'ID',
                'meta_key' => 'sffc_public_profile_slug',
                'meta_value' => $slug,
            ]);

            return !empty($users[0]) ? (int) $users[0] : 0;
        }

        private function get_crm_reddit_dashboard_alert_frequency_options()
        {
            return [
                'twice_daily' => __('Twice a day', 'senna-finance'),
                'daily' => __('Daily', 'senna-finance'),
                'every_3_days' => __('Every 3 days', 'senna-finance'),
                'weekly' => __('Weekly', 'senna-finance'),
            ];
        }

        private function normalize_crm_reddit_profile_tag_values($value, $limit = 12)
        {
            if (is_string($value)) {
                $value = preg_split('/[\r\n,]+/', $value);
            }

            if (!is_array($value)) {
                return [];
            }

            $normalized = [];
            foreach ($value as $entry) {
                $entry = sanitize_text_field((string) $entry);
                if ($entry === '') {
                    continue;
                }

                $lookup = function_exists('mb_strtolower') ? mb_strtolower($entry) : strtolower($entry);
                if (isset($normalized[$lookup])) {
                    continue;
                }

                $normalized[$lookup] = $entry;
                if (count($normalized) >= $limit) {
                    break;
                }
            }

            return array_values($normalized);
        }

        private function get_crm_reddit_dashboard_profile_state($user_id, array $account_user = [])
        {
            $user = get_user_by('id', $user_id);
            if (!$user instanceof WP_User) {
                return [];
            }

            $preferences = function_exists('sffc_crm_get_job_preferences')
                ? sffc_crm_get_job_preferences($user_id)
                : [];
            $headline_meta = class_exists('SFFC_User_Preferences')
                ? (string) get_user_meta($user_id, SFFC_User_Preferences::META_PROFILE_HEADLINE, true)
                : '';
            $headline = $headline_meta !== ''
                ? $headline_meta
                : (!empty($preferences['target_roles'][0])
                    ? sprintf(__('%s candidate building stronger recruiter visibility through MENA Careers.', 'senna-finance'), $preferences['target_roles'][0])
                    : __('Finance candidate building sharper recruiter visibility through MENA Careers.', 'senna-finance'));
            $about = trim((string) $user->description);
            $alert_frequency_options = $this->get_crm_reddit_dashboard_alert_frequency_options();
            $alert_frequency = sanitize_key((string) get_user_meta($user_id, 'sffc_crm_alert_frequency', true));
            if (!isset($alert_frequency_options[$alert_frequency])) {
                $alert_frequency = !empty(get_user_meta($user_id, 'sffc_crm_digest_weekly', true)) ? 'weekly' : 'daily';
            }

            $target_roles = $this->normalize_crm_reddit_profile_tag_values($preferences['target_roles'] ?? []);
            $target_locations = $this->normalize_crm_reddit_profile_tag_values($preferences['target_locations'] ?? []);
            $target_sectors = $this->normalize_crm_reddit_profile_tag_values($preferences['target_sectors'] ?? []);
            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [
                'investment_banking' => __('Investment Banking', 'senna-finance'),
                'private_equity' => __('Finance', 'senna-finance'),
                'asset_management' => __('Asset Management', 'senna-finance'),
                'hedge_fund' => __('Hedge Fund', 'senna-finance'),
                'finance' => __('Finance', 'senna-finance'),
                'consulting' => __('Consulting', 'senna-finance'),
            ];
            $skills = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_technical_skills', true) ?: []);
            $qualifications = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_certifications', true) ?: []);
            $languages = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_languages', true) ?: []);
            $excluded_roles = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_roles', true) ?: []);
            $excluded_locations = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_locations', true) ?: []);
            $excluded_sectors = $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_sectors', true) ?: []);
            $avatar_url = $this->get_crm_reddit_profile_avatar_url($user_id, $account_user);
            $cover_url = $this->get_crm_reddit_profile_cover_url($user_id);

            return [
                'display_name' => (string) ($account_user['display_name'] ?? $user->display_name ?: $user->user_login),
                'email' => (string) ($account_user['email'] ?? $user->user_email),
                'membership_label' => (string) ($account_user['membership_label'] ?? __('Free access', 'senna-finance')),
                'headline' => $headline,
                'about' => $about,
                'avatar_url' => $avatar_url,
                'cover_url' => $cover_url,
                'avatar_initial' => strtoupper(substr(trim((string) ($account_user['display_name'] ?? $user->display_name ?: $user->user_login)), 0, 1)),
                'target_roles' => $target_roles,
                'target_locations' => $target_locations,
                'target_sectors' => $target_sectors,
                'sector_options' => $sector_options,
                'technical_skills' => $skills,
                'qualifications' => $qualifications,
                'languages' => $languages,
                'excluded_roles' => $excluded_roles,
                'excluded_locations' => $excluded_locations,
                'excluded_sectors' => $excluded_sectors,
                'alert_frequency' => $alert_frequency,
                'alert_frequency_options' => $alert_frequency_options,
                'role_count' => count($target_roles),
                'location_count' => count($target_locations),
                'skill_count' => count($skills),
                'qualification_count' => count($qualifications),
            ];
        }

        private function get_crm_reddit_dashboard_profile_recommended_jobs(array $profile, $limit = 5)
        {
            $limit = max(2, min(6, (int) $limit));

            if (!class_exists('SFFC_CRM_Post')) {
                $post_model_file = SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
                if (file_exists($post_model_file)) {
                    require_once $post_model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return [];
            }

            $post_model = new SFFC_CRM_Post();
            $posts = (array) $post_model->get_feed([
                'page' => 1,
                'per_page' => 64,
                'approved_only' => true,
                'post_status' => 'open',
                'orderby' => 'posted_at',
                'order' => 'DESC',
            ]);

            if (empty($posts)) {
                return [];
            }

            $positive_terms = [
                'roles' => (array) ($profile['target_roles'] ?? []),
                'locations' => (array) ($profile['target_locations'] ?? []),
                'sectors' => (array) ($profile['target_sectors'] ?? []),
                'skills' => array_merge((array) ($profile['technical_skills'] ?? []), (array) ($profile['qualifications'] ?? [])),
            ];
            $negative_terms = array_merge(
                (array) ($profile['excluded_roles'] ?? []),
                (array) ($profile['excluded_locations'] ?? []),
                (array) ($profile['excluded_sectors'] ?? [])
            );

            $items = [];
            foreach ($posts as $post) {
                $post = (array) $post;
                $role_title = trim((string) ($post['role_title'] ?? ''));
                if ($role_title === '') {
                    continue;
                }

                $haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                    $role_title,
                    (string) ($post['company'] ?? ''),
                    (string) ($post['location'] ?? ''),
                    (string) ($post['location_country'] ?? ''),
                    (string) ($post['sector'] ?? ''),
                    (string) ($post['seniority'] ?? ''),
                    (string) ($post['keywords'] ?? ''),
                    wp_strip_all_tags((string) ($post['content_snippet'] ?? ($post['content'] ?? ''))),
                ])));

                $excluded = false;
                foreach ($negative_terms as $term) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                    if ($needle !== '' && strpos($haystack, $needle) !== false) {
                        $excluded = true;
                        break;
                    }
                }
                if ($excluded) {
                    continue;
                }

                $score = 0;
                foreach ($positive_terms['roles'] as $term) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                    if ($needle !== '' && strpos($haystack, $needle) !== false) {
                        $score += 6;
                    }
                }
                foreach ($positive_terms['locations'] as $term) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                    if ($needle !== '' && strpos($haystack, $needle) !== false) {
                        $score += 5;
                    }
                }
                foreach ($positive_terms['sectors'] as $term) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                    if ($needle !== '' && strpos($haystack, $needle) !== false) {
                        $score += 4;
                    }
                }
                foreach ($positive_terms['skills'] as $term) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                    if ($needle !== '' && strpos($haystack, $needle) !== false) {
                        $score += 2;
                    }
                }

                $posted_ts = !empty($post['posted_at']) ? strtotime((string) $post['posted_at']) : 0;
                $items[] = [
                    'id' => (int) ($post['id'] ?? 0),
                    'title' => $role_title,
                    'company' => trim((string) ($post['company'] ?? '')),
                    'location' => trim((string) ($post['location'] ?? '')),
                    'sector' => trim((string) ($post['sector'] ?? '')),
                    'seniority' => trim((string) ($post['seniority'] ?? '')),
                    'posted_at' => trim((string) ($post['posted_at'] ?? '')),
                    'posted_ts' => $posted_ts,
                    'score' => $score,
                    'logo' => !empty($post['company_logo']) ? $this->normalize_company_logo_url((string) $post['company_logo']) : '',
                    'wp_post_id' => (int) ($post['wp_post_id'] ?? 0),
                    'jobs_post_id' => (int) ($post['jobs_post_id'] ?? 0),
                ];
            }

            usort($items, static function ($left, $right) {
                $score_compare = (int) ($right['score'] ?? 0) <=> (int) ($left['score'] ?? 0);
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return (int) ($right['posted_ts'] ?? 0) <=> (int) ($left['posted_ts'] ?? 0);
            });

            return array_slice($items, 0, $limit);
        }

        private function get_crm_reddit_dashboard_profile_job_url(array $job)
        {
            $wp_post_id = (int) ($job['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                $permalink = get_permalink($wp_post_id);
                if ($permalink) {
                    return (string) $permalink;
                }
            }

            $post_id = (int) ($job['id'] ?? 0);
            if ($post_id > 0 && !class_exists('SFFC_CRM_Post_Type')) {
                $post_type_file = SFFC_PLUGIN_DIR . 'includes/crm/class-crm-post-type.php';
                if (file_exists($post_type_file)) {
                    require_once $post_type_file;
                }
            }
            if ($post_id > 0 && class_exists('SFFC_CRM_Post_Type')) {
                return SFFC_CRM_Post_Type::get_post_url($post_id, sanitize_title((string) ($job['title'] ?? '')));
            }

            $jobs_post_id = (int) ($job['jobs_post_id'] ?? 0);
            if ($jobs_post_id > 0) {
                return add_query_arg(['post_type' => 'jobs', 'p' => $jobs_post_id], home_url('/'));
            }

            return home_url('/terminal/');
        }

        private function get_crm_reddit_dashboard_profile_posted_label($posted_at)
        {
            $posted_ts = !empty($posted_at) ? strtotime((string) $posted_at) : 0;
            if ($posted_ts <= 0) {
                return __('Recently posted', 'senna-finance');
            }

            return sprintf(__('%s ago', 'senna-finance'), human_time_diff($posted_ts, current_time('timestamp')));
        }

        private function render_crm_reddit_dashboard_profile_recommended_jobs_card(array $jobs)
        {
            if (empty($jobs)) {
                return '';
            }

            ob_start();
            ?>
            <article class="sffc-crm-dashboard-app-profile-side-card sffc-crm-dashboard-app-profile-side-card--recommended-jobs">
                <header class="sffc-crm-dashboard-app-profile-recommendations-head">
                    <span class="sffc-crm-dashboard-app-profile-recommendations-premium" aria-hidden="true"></span>
                    <div>
                        <strong><?php esc_html_e('Recommended jobs', 'senna-finance'); ?></strong>
                        <span><?php esc_html_e('Based on your profile preferences', 'senna-finance'); ?></span>
                    </div>
                </header>
                <div class="sffc-crm-dashboard-app-profile-job-recommendations">
