        private function render_crm_reddit_dashboard_profile_chip_dropdown($field_name, $label, array $options, array $selected_values = [], $mode = 'tag')
        {
            $selected_lookup = [];
            foreach ($selected_values as $selected_value) {
                $selected_lookup[strtolower((string) $selected_value)] = true;
            }

            $active_label = '';
            foreach ($options as $value => $option_label) {
                $value = (string) $value;
                if (isset($selected_lookup[strtolower($value)])) {
                    $active_label = (string) $option_label;
                    break;
                }
            }
            if ($active_label === '' && !empty($selected_values)) {
                $active_label = (string) reset($selected_values);
            }

            $button_label = $active_label !== '' ? $active_label : $label;
            $button_label = function_exists('mb_strlen') && mb_strlen($button_label) > 28
                ? mb_substr($button_label, 0, 25) . '...'
                : $button_label;

            ob_start();
            ?>
            <div class="sffc-crm-dashboard-app-profile-filter" data-dashboard-profile-filter>
                <button
                    type="button"
                    class="sffc-crm-dashboard-app-profile-filter-button<?php echo $active_label !== '' ? ' is-active' : ''; ?>"
                    data-dashboard-profile-filter-toggle
                    data-field="<?php echo esc_attr($field_name); ?>"
                    data-mode="<?php echo esc_attr($mode); ?>"
                    aria-haspopup="listbox"
                    aria-expanded="false">
                    <span><?php echo esc_html($button_label); ?></span>
                    <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
                        <path d="M4 6 8 10l4-4" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </button>
                <div class="sffc-crm-dashboard-app-profile-filter-menu" data-dashboard-profile-filter-menu hidden>
                    <?php foreach ($options as $value => $option_label):
                        $value = (string) $value;
                        $option_label = (string) $option_label;
                        $is_selected = isset($selected_lookup[strtolower($value)]);
                    ?>
                        <button
                            type="button"
                            class="sffc-crm-dashboard-app-profile-filter-option<?php echo $is_selected ? ' is-selected' : ''; ?>"
                            data-dashboard-profile-filter-option
                            data-field="<?php echo esc_attr($field_name); ?>"
                            data-mode="<?php echo esc_attr($mode); ?>"
                            data-value="<?php echo esc_attr($value); ?>"
                            data-label="<?php echo esc_attr($option_label); ?>"
                            role="option"
                            aria-selected="<?php echo $is_selected ? 'true' : 'false'; ?>">
                            <span><?php echo esc_html($option_label); ?></span>
                            <svg viewBox="0 0 18 18" aria-hidden="true" focusable="false">
                                <path d="M4 9.3 7.4 12.6 14 5.8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                            </svg>
                        </button>
                    <?php endforeach; ?>
                </div>
            </div>
            <?php
            return (string) ob_get_clean();
        }

        private function get_crm_reddit_resume_upload($user_id, $upload_id)
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_cv_uploads';

            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return null;
            }

            return $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT id, file_name, file_path, file_type, file_size, upload_date, parse_status, error_message
                     FROM {$table}
                     WHERE id = %d AND user_id = %s
                     LIMIT 1",
                    $upload_id,
                    (string) $user_id
                ),
                ARRAY_A
            );
        }

        private function get_crm_reddit_resume_uploads($user_id, $limit = 8)
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_cv_uploads';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return [];
            }

            $rows = $wpdb->get_results(
                $wpdb->prepare(
                    "SELECT id, file_name, file_path, file_type, file_size, upload_date, parse_status, error_message
                     FROM {$table}
                     WHERE user_id = %s
                     ORDER BY upload_date DESC
                     LIMIT %d",
                    (string) $user_id,
                    max(1, absint($limit))
                ),
                ARRAY_A
            );

            if (empty($rows)) {
                return [];
            }

            $stored_active_id = absint((string) get_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), true));
            $fallback_active_id = !empty($rows[0]['id']) ? (int) $rows[0]['id'] : 0;
            $row_ids = array_map(static function ($row) {
                return (int) ($row['id'] ?? 0);
            }, $rows);
            $active_id = ($stored_active_id > 0 && in_array($stored_active_id, $row_ids, true)) ? $stored_active_id : $fallback_active_id;
            $now = current_time('timestamp');
            $documents = [];

            foreach ($rows as $row) {
                $upload_time = !empty($row['upload_date']) ? strtotime((string) $row['upload_date']) : false;
                $file_type = strtolower((string) ($row['file_type'] ?? ''));
                $documents[] = [
                    'id' => (int) ($row['id'] ?? 0),
                    'name' => (string) ($row['file_name'] ?? ''),
                    'path' => (string) ($row['file_path'] ?? ''),
                    'file_type' => $file_type,
                    'file_type_label' => strtoupper($file_type),
                    'file_size' => size_format((int) ($row['file_size'] ?? 0)),
                    'uploaded' => (string) ($row['upload_date'] ?? ''),
                    'uploaded_label' => $upload_time ? human_time_diff($upload_time, $now) . ' ago' : __('Recently added', 'senna-finance'),
                    'parse_status' => (string) ($row['parse_status'] ?? 'pending'),
                    'parse_status_label' => $this->get_crm_reddit_resume_status_label((string) ($row['parse_status'] ?? 'pending')),
                    'error_message' => (string) ($row['error_message'] ?? ''),
                    'is_resume' => ((int) ($row['id'] ?? 0) === $active_id),
                    'is_word' => in_array($file_type, ['doc', 'docx'], true),
                    'is_cv_document' => in_array($file_type, ['doc', 'docx', 'pdf', 'txt'], true),
                ];
            }

            return $documents;
        }

        private function maybe_store_crm_reddit_text_resume_upload($user_id, $cv_text, $file_name)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $cv_text = $this->sanitize_crm_reddit_pasted_cv_text($cv_text);
            $file_name = sanitize_file_name((string) $file_name);

            if ($user_id <= 0 || $cv_text === '') {
                return 0;
            }

            if ($file_name === '') {
                $file_name = 'senna-primary-cv.txt';
            }

            $table = $wpdb->prefix . 'sffc_cv_uploads';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return 0;
            }

            $upload_dir = wp_upload_dir();
            if (!empty($upload_dir['error']) || empty($upload_dir['basedir'])) {
                return 0;
            }

            $base_name = sanitize_file_name((string) pathinfo($file_name, PATHINFO_FILENAME));
            if ($base_name === '') {
                $base_name = 'senna-cv';
            }

            $target_dir = trailingslashit((string) $upload_dir['basedir']) . 'sffc-cv-text-resumes/' . $user_id;
            if (!wp_mkdir_p($target_dir)) {
                return 0;
            }

            $text_hash = substr(md5($cv_text), 0, 12);
            $target_path = trailingslashit($target_dir) . $base_name . '-' . $text_hash . '.txt';
            if (file_put_contents($target_path, $cv_text, LOCK_EX) === false) {
                return 0;
            }

            $existing_id = (int) $wpdb->get_var(
                $wpdb->prepare(
                    "SELECT id FROM {$table} WHERE user_id = %s AND file_path = %s LIMIT 1",
                    (string) $user_id,
                    $target_path
                )
            );

            if ($existing_id > 0) {
                $wpdb->update(
                    $table,
                    [
                        'file_name' => $file_name,
                        'file_size' => strlen($cv_text),
                        'upload_date' => current_time('mysql'),
                        'parse_status' => 'completed',
                        'error_message' => '',
                    ],
                    [
                        'id' => $existing_id,
                        'user_id' => (string) $user_id,
                    ],
                    ['%s', '%d', '%s', '%s', '%s'],
                    ['%d', '%s']
                );

                return $existing_id;
            }

            $inserted = $wpdb->insert(
                $table,
                [
                    'user_id' => (string) $user_id,
                    'file_name' => $file_name,
                    'file_path' => $target_path,
                    'file_type' => 'txt',
                    'file_size' => strlen($cv_text),
                    'upload_date' => current_time('mysql'),
                    'parse_status' => 'completed',
                    'error_message' => '',
                ],
                ['%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s']
            );

            if (!$inserted) {
                return 0;
            }

            return (int) $wpdb->insert_id;
        }

        private function get_crm_reddit_resume_status_label($status)
