            $labels = [
                'completed' => __('Ready', 'senna-finance'),
                'processing' => __('Processing', 'senna-finance'),
                'failed' => __('Needs attention', 'senna-finance'),
                'pending' => __('Pending', 'senna-finance'),
            ];

            return $labels[$status] ?? __('Pending', 'senna-finance');
        }

