        private function normalize_cv_match_studio_preferred_industry($value)
        {
            $value = strtolower(trim((string) $value));
            $value = str_replace(['-', '/', '&'], [' ', ' ', ' and '], $value);
            $value = preg_replace('/\s+/', ' ', str_replace('_', ' ', (string) $value));
            $value = trim((string) $value);

            $map = [
                'ib' => 'investment_banking',
                'investment bank' => 'investment_banking',
                'investment banking' => 'investment_banking',
                'investment_banking' => 'investment_banking',
                'pe' => 'private_equity',
                'finance' => 'private_equity',
                'private_equity' => 'private_equity',
                'am' => 'asset_management',
                'asset management' => 'asset_management',
                'asset mgmt' => 'asset_management',
                'asset mgt' => 'asset_management',
                'asset_management' => 'asset_management',
                'venture capital' => 'private_equity',
                'venture_capital' => 'private_equity',
                'hedge fund' => 'hedge_fund',
                'hedge funds' => 'hedge_fund',
                'hedge_fund' => 'hedge_fund',
                'accounting finance' => 'finance',
                'accounting and finance' => 'finance',
                'accounting_finance' => 'finance',
                'risk compliance' => 'finance',
                'risk and compliance' => 'finance',
                'risk_compliance' => 'finance',
                'finance' => 'finance',
                'consulting' => 'consulting',
                'strategy consulting' => 'consulting',
                'other' => 'other',
            ];

            return (string) ($map[$value] ?? '');
        }

        private function get_cv_match_studio_user_preferred_industry($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return '';
            }

            $preferred_industry = $this->normalize_cv_match_studio_preferred_industry((string) get_user_meta($user_id, $this->get_cv_match_studio_preferred_industry_meta_key(), true));
            $saved_finance_interest = array_values(array_filter(array_map('sanitize_key', (array) get_user_meta($user_id, 'sffc_signup_finance_interest', true))));

            if (!empty($saved_finance_interest)) {
                $signup_industry = $this->normalize_cv_match_studio_preferred_industry((string) $saved_finance_interest[0]);
                if ($signup_industry !== '' && ($preferred_industry === '' || $preferred_industry === 'finance')) {
                    return $signup_industry;
                }
            }

            return $preferred_industry;
        }

