        private function detect_cv_match_studio_preferred_location_from_job_item(array $job_item)
        {
            $location = strtolower(trim((string) ($job_item['location'] ?? '')));
            if ($location === '') {
                return '';
            }

            $matches = [];
            $checks = [
                'london' => ['london'],
                'paris' => ['paris'],
                'milan' => ['milan'],
                'amsterdam' => ['amsterdam'],
                'dubai' => ['dubai'],
            ];

            foreach ($checks as $preferred_location => $terms) {
                foreach ($terms as $term) {
                    if (strpos($location, $term) !== false) {
                        $matches[] = $preferred_location;
                        break;
                    }
                }
            }

            $matches = array_values(array_unique($matches));

            if (count($matches) === 1) {
                return (string) $matches[0];
            }

            return '';
        }

