                'asset_management' => __('Asset Management', 'senna-finance'),
                'hedge_fund' => __('Hedge Fund', 'senna-finance'),
                'finance' => __('Finance', 'senna-finance'),
                'consulting' => __('Consulting', 'senna-finance'),
                'other' => __('Other', 'senna-finance'),
            ];

            return (string) ($labels[$this->normalize_cv_match_studio_preferred_industry($value)] ?? '');
        }

        private function sanitize_crm_reddit_pasted_cv_text($text)
        {
            $text = (string) $text;
            $text = wp_strip_all_tags($text);
            $text = preg_replace("/\r\n|\r/", "\n", $text);
            $text = preg_replace("/[ \t]+/", ' ', (string) $text);
            $text = preg_replace("/\n{3,}/", "\n\n", (string) $text);

            return trim((string) $text);
        }

        private function get_crm_reddit_active_resume_text($user_id)
        {
            $pasted_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) get_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), true));
            $source_preference = sanitize_key((string) get_user_meta($user_id, $this->get_crm_reddit_resume_source_preference_meta_key(), true));
            $preferred_industry = $this->get_cv_match_studio_user_preferred_industry($user_id);

            $active_id = absint((string) get_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), true));
            $active_upload = $active_id > 0 ? $this->get_crm_reddit_resume_upload($user_id, $active_id) : null;

            if (empty($active_upload) || empty($active_upload['id'])) {
                $uploads = $this->get_crm_reddit_resume_uploads($user_id, 1);
                if (!empty($uploads[0]['id'])) {
                    $active_upload = $this->get_crm_reddit_resume_upload($user_id, (int) $uploads[0]['id']);
                }
            }

            $cache_key = 'sffc_crm_resume_active_' . md5(wp_json_encode([
                'user_id' => (int) $user_id,
                'source_preference' => $source_preference,
                'pasted_hash' => md5($pasted_cv_text),
                'active_id' => (int) ($active_upload['id'] ?? 0),
                'active_upload_date' => (string) ($active_upload['upload_date'] ?? ''),
                'active_file_size' => (int) ($active_upload['file_size'] ?? 0),
                'active_file_type' => (string) ($active_upload['file_type'] ?? ''),
                'preferred_industry' => $preferred_industry,
            ]));
            $cached_payload = get_transient($cache_key);
            if (is_array($cached_payload) && array_key_exists('cv_text', $cached_payload)) {
                return $cached_payload;
            }

            $pasted_payload = [
                'cv_text' => $pasted_cv_text,
                'has_cv' => $pasted_cv_text !== '',
                'source' => $pasted_cv_text !== '' ? 'pasted' : '',
                'preferred_industry' => $preferred_industry,
            ];
            $upload_payload = $this->build_crm_reddit_active_upload_resume_payload($active_upload);
            $upload_payload['preferred_industry'] = $preferred_industry;

            if ($source_preference === 'upload' && !empty($upload_payload['has_cv'])) {
                set_transient($cache_key, $upload_payload, 30 * MINUTE_IN_SECONDS);
                return $upload_payload;
            }

            if ($source_preference === 'pasted' && !empty($pasted_payload['has_cv'])) {
                set_transient($cache_key, $pasted_payload, 30 * MINUTE_IN_SECONDS);
                return $pasted_payload;
            }

            if (!empty($pasted_payload['has_cv'])) {
                set_transient($cache_key, $pasted_payload, 30 * MINUTE_IN_SECONDS);
                return $pasted_payload;
            }

            if (!empty($upload_payload['has_cv'])) {
                set_transient($cache_key, $upload_payload, 30 * MINUTE_IN_SECONDS);
                return $upload_payload;
            }

            $editorial_document = $this->get_crm_editorial_latest_resume_document($user_id);
            $editorial_payload = $this->build_crm_editorial_resume_payload($editorial_document);
            $editorial_payload['preferred_industry'] = $preferred_industry;

            if (!empty($editorial_payload['has_cv'])) {
                set_transient($cache_key, $editorial_payload, 30 * MINUTE_IN_SECONDS);
                return $editorial_payload;
            }

            $empty_payload = [
                'cv_text' => '',
                'has_cv' => false,
                'source' => '',
                'preferred_industry' => $preferred_industry,
            ];
            set_transient($cache_key, $empty_payload, 30 * MINUTE_IN_SECONDS);

            return $empty_payload;
        }

        private function build_crm_reddit_active_upload_resume_payload($active_upload)
        {
            if (empty($active_upload) || empty($active_upload['file_type'])) {
                return [
                    'cv_text' => '',
                    'has_cv' => false,
                    'source' => '',
                ];
            }

            $file_type = strtolower((string) $active_upload['file_type']);
            if (!in_array($file_type, ['doc', 'docx', 'pdf', 'txt'], true) || empty($active_upload['file_path']) || !file_exists((string) $active_upload['file_path'])) {
                return [
                    'cv_text' => '',
                    'has_cv' => false,
                    'source' => '',
                ];
            }

            if ($file_type === 'txt') {
                $text = (string) file_get_contents((string) $active_upload['file_path']);
                $text = $this->sanitize_crm_reddit_pasted_cv_text($text);

                return [
                    'cv_text' => $text,
                    'has_cv' => trim($text) !== '',
                    'source' => trim($text) !== '' ? 'upload' : '',
                ];
            }

            if (!class_exists('SFFC_Document_Parser')) {
                require_once SFFC_PLUGIN_DIR . 'includes/class-document-parser.php';
            }

            $parser = SFFC_Document_Parser::get_instance();
            if ($file_type === 'pdf') {
                $text = (string) $parser->extract_pdf_text((string) $active_upload['file_path']);
            } elseif ($file_type === 'docx') {
                $text = (string) $parser->extract_docx_text((string) $active_upload['file_path']);
            } else {
                $text = (string) $parser->extract_doc_text((string) $active_upload['file_path']);
            }

            if ($text !== '') {
                $text = (string) $parser->clean_text($text);
            }

            return [
                'cv_text' => $text,
                'has_cv' => trim($text) !== '',
                'source' => trim($text) !== '' ? 'upload' : '',
            ];
        }

        private function build_crm_editorial_resume_payload(array $document)
        {
            $file_path = $this->get_crm_editorial_resume_document_file_path($document);
            if ($file_path === '' || !file_exists($file_path)) {
                return [
                    'cv_text' => '',
                    'has_cv' => false,
                    'source' => '',
                ];
            }

            $extension = strtolower((string) pathinfo($file_path, PATHINFO_EXTENSION));
            if (!in_array($extension, ['pdf', 'doc', 'docx', 'txt'], true)) {
                return [
                    'cv_text' => '',
                    'has_cv' => false,
                    'source' => '',
                ];
            }

            if ($extension === 'txt') {
                $text = (string) file_get_contents($file_path);
                $text = $this->sanitize_crm_reddit_pasted_cv_text($text);

                return [
                    'cv_text' => $text,
                    'has_cv' => trim($text) !== '',
                    'source' => trim($text) !== '' ? 'community_onboarding' : '',
                ];
            }

            if (!class_exists('SFFC_Document_Parser')) {
                require_once SFFC_PLUGIN_DIR . 'includes/class-document-parser.php';
            }

            $parser = SFFC_Document_Parser::get_instance();
            if ($extension === 'pdf') {
                $text = (string) $parser->extract_pdf_text($file_path);
            } elseif ($extension === 'docx') {
                $text = (string) $parser->extract_docx_text($file_path);
            } else {
                $text = (string) $parser->extract_doc_text($file_path);
            }

            if ($text !== '') {
                $text = (string) $parser->clean_text($text);
            }

            return [
                'cv_text' => $text,
                'has_cv' => trim($text) !== '',
                'source' => trim($text) !== '' ? 'community_onboarding' : '',
            ];
        }

        private function get_crm_reddit_cv_ats_scan_payload($user_id, array $resume_payload = [], $queue_if_missing = true)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $has_cv = !empty($resume_payload['has_cv']) && $cv_text !== '';
            if (!$has_cv) {
                return [];
            }

            $source_hash = md5($cv_text);
            $stored = get_user_meta($user_id, $this->get_crm_reddit_cv_ats_scan_meta_key(), true);
            if (
                $this->is_crm_reddit_cv_ats_scan_current($stored, $source_hash)
            ) {
                if ($queue_if_missing && !$this->has_crm_reddit_cv_ats_explainer($stored)) {
                    $this->maybe_queue_crm_reddit_cv_ats_scan($user_id, $resume_payload);
                }
                return $stored;
            }

            if ($queue_if_missing) {
                $this->maybe_queue_crm_reddit_cv_ats_scan($user_id, $resume_payload);
            }

            return [];
        }

        private function maybe_queue_crm_reddit_cv_ats_scan($user_id, array $resume_payload = [])
        {
            $user_id = (int) $user_id;
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $has_cv = !empty($resume_payload['has_cv']) && $cv_text !== '';
            if ($user_id <= 0 || !$has_cv) {
                return;
            }

            $source_hash = md5($cv_text);
            $stored = get_user_meta($user_id, $this->get_crm_reddit_cv_ats_scan_meta_key(), true);
            if (
                $this->is_crm_reddit_cv_ats_scan_current($stored, $source_hash)
                && $this->has_crm_reddit_cv_ats_explainer($stored)
            ) {
                return;
            }

            $lock_key = 'sffc_crm_cv_ats_scan_lock_' . md5($user_id . '|' . $source_hash);
            if (get_transient($lock_key)) {
                return;
            }

            set_transient($lock_key, 1, 10 * MINUTE_IN_SECONDS);
            set_transient('sffc_crm_cv_ats_scan_context_' . md5($user_id . '|' . $source_hash), [
                'cv_text' => $cv_text,
                'source' => sanitize_key((string) ($resume_payload['source'] ?? '')),
            ], 15 * MINUTE_IN_SECONDS);

            if (!wp_next_scheduled('sffc_crm_reddit_generate_cv_ats_scan', [$user_id, $source_hash])) {
                wp_schedule_single_event(time() + 15, 'sffc_crm_reddit_generate_cv_ats_scan', [$user_id, $source_hash]);
            }
        }

        public function generate_crm_reddit_cv_ats_scan($user_id, $source_hash)
        {
            $user_id = (int) $user_id;
            $source_hash = sanitize_text_field((string) $source_hash);
            if ($user_id <= 0 || $source_hash === '') {
                return;
            }

            $context_key = 'sffc_crm_cv_ats_scan_context_' . md5($user_id . '|' . $source_hash);
            $lock_key = 'sffc_crm_cv_ats_scan_lock_' . md5($user_id . '|' . $source_hash);
            $context = get_transient($context_key);

            if (!is_array($context) || empty($context['cv_text'])) {
                delete_transient($lock_key);
                return;
            }

            $current_resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            $current_cv_text = trim((string) ($current_resume_payload['cv_text'] ?? ''));
            if ($current_cv_text === '' || md5($current_cv_text) !== $source_hash) {
                delete_transient($context_key);
                delete_transient($lock_key);
                return;
            }

            $scan = $this->call_crm_reddit_cv_ats_claude([
                'cv_text' => (string) $context['cv_text'],
                'source' => sanitize_key((string) ($context['source'] ?? '')),
            ]);

            if (empty($scan['score'])) {
                $scan = $this->build_crm_reddit_cv_ats_fallback((string) $context['cv_text']);
            }

            $ats_explainer = $this->sanitize_crm_reddit_dashboard_ats_explanation((array) ($scan['ats_explainer'] ?? []));
            if (empty($ats_explainer['summary'])) {
                $ats_explainer = $this->sanitize_crm_reddit_dashboard_ats_explanation(
                    $this->build_crm_reddit_dashboard_ats_explainer_fallback(
                        ['cv_text' => (string) $context['cv_text']],
                        $scan
                    )
                );
            }

            update_user_meta($user_id, $this->get_crm_reddit_cv_ats_scan_meta_key(), [
                'version' => $this->get_crm_reddit_cv_ats_scan_version(),
                'plugin_version' => $this->get_crm_reddit_cv_ats_scan_plugin_version(),
                'score' => (int) ($scan['score'] ?? 0),
                'label' => sanitize_text_field((string) ($scan['label'] ?? '')),
                'summary' => sanitize_text_field((string) ($scan['summary'] ?? '')),
                'top_strength' => sanitize_text_field((string) ($scan['top_strength'] ?? '')),
                'top_gap' => sanitize_text_field((string) ($scan['top_gap'] ?? '')),
                'keywords' => $this->normalize_crm_reddit_cv_signal_terms($scan['keywords'] ?? [], 'term'),
                'locations' => $this->normalize_crm_reddit_cv_signal_terms($scan['locations'] ?? [], 'name'),
                'target_roles' => $this->normalize_crm_reddit_cv_signal_terms($scan['target_roles'] ?? [], 'name'),
                'sectors' => $this->normalize_crm_reddit_cv_signal_terms($scan['sectors'] ?? [], 'name'),
                'seniority' => $this->normalize_crm_reddit_cv_signal_terms($scan['seniority'] ?? [], 'name'),
                'ats_explainer' => $ats_explainer,
                'source' => sanitize_key((string) ($context['source'] ?? '')),
                'source_hash' => $source_hash,
                'generated_at' => current_time('mysql'),
            ]);

            delete_transient($context_key);
            delete_transient($lock_key);
        }

        private function call_crm_reddit_cv_ats_claude(array $context)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            $cv_text = trim((string) ($context['cv_text'] ?? ''));
            if ($api_key === '' || $cv_text === '') {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 1400,
                'temperature' => 0.1,
                'system' => 'You assess CV quality for private equity recruiting and ATS readiness, with strong awareness of hiring patterns across private equity, growth equity, private credit, portfolio operations, investor relations, asset management, strategy, and adjacent investing roles. You also extract the strongest reusable signals for matching a candidate to private equity roles, plus a concise ATS explanation to show inside a dashboard modal. Respond with only valid JSON. No markdown. Return exactly this shape: {"score":78,"label":"Recruiter-ready","summary":"...","top_strength":"...","top_gap":"...","keywords":[{"term":"lbo modeling","weight":0.94}],"locations":[{"name":"Global","weight":0.92}],"target_roles":[{"name":"Investment Manager","weight":0.95}],"sectors":[{"name":"Private Equity","weight":0.91}],"seniority":[{"name":"Director","weight":0.88}],"ats_explainer":{"summary":"2-3 sentences, no repetition","strengths":["..."],"gaps":["..."],"next_steps":["..."]}}. Weights must be decimals from 0.10 to 1.00. Ignore generic CV filler such as months, graduation, dates, university years, and section headings. Do not repeat the same sentence or idea inside ats_explainer.',
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => wp_json_encode([
                            'source' => (string) ($context['source'] ?? ''),
                            'instruction' => 'Assess this CV for private equity ATS readiness and recruiter readability, with awareness of hiring patterns across private equity, investing, private credit, portfolio operations, investor relations, asset management, and adjacent strategy roles. Then extract the most reusable matching signals for recruiting: strongest role titles implied by repeated evidence, strongest sector focus, strongest locations, strongest seniority hints, and high-signal skills/keywords. Also return a concise ATS explanation with distinct strengths, gaps, and next steps. Do not tailor to a single job description. Ignore expected resume filler such as dates, months, graduation language, and generic headings.',
                            'cv_text' => $cv_text,
                        ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit CV ATS Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);
            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit CV ATS Claude Error: status ' . $status);
                return null;
            }

            $decoded = json_decode((string) $body['content'][0]['text'], true);
            if (!is_array($decoded)) {
                error_log('Reddit CV ATS Claude Parse Error: ' . json_last_error_msg());
                return null;
            }

            return [
                'score' => max(35, min(95, (int) ($decoded['score'] ?? 0))),
                'label' => sanitize_text_field((string) ($decoded['label'] ?? '')),
                'summary' => sanitize_text_field((string) ($decoded['summary'] ?? '')),
                'top_strength' => sanitize_text_field((string) ($decoded['top_strength'] ?? '')),
                'top_gap' => sanitize_text_field((string) ($decoded['top_gap'] ?? '')),
                'keywords' => $this->normalize_crm_reddit_cv_signal_terms($decoded['keywords'] ?? [], 'term'),
                'locations' => $this->normalize_crm_reddit_cv_signal_terms($decoded['locations'] ?? [], 'name'),
                'target_roles' => $this->normalize_crm_reddit_cv_signal_terms($decoded['target_roles'] ?? [], 'name'),
                'sectors' => $this->normalize_crm_reddit_cv_signal_terms($decoded['sectors'] ?? [], 'name'),
                'seniority' => $this->normalize_crm_reddit_cv_signal_terms($decoded['seniority'] ?? [], 'name'),
                'ats_explainer' => $this->sanitize_crm_reddit_dashboard_ats_explanation((array) ($decoded['ats_explainer'] ?? [])),
            ];
        }

        private function build_crm_reddit_cv_ats_fallback($cv_text)
        {
            $cv_text = trim((string) $cv_text);
            $word_count = str_word_count($cv_text);
            $has_metrics = preg_match('/\b\d+(?:[%kKmM]|\+)?\b/', $cv_text) ? 1 : 0;
            $has_sections = preg_match('/\b(experience|education|skills|summary|employment|certification)\b/i', $cv_text) ? 1 : 0;
            $has_tools = preg_match('/\b(excel|powerpoint|python|sql|valuation|modelling|modeling|deal|analysis)\b/i', $cv_text) ? 1 : 0;
            $score = 46 + min(18, (int) floor($word_count / 55)) + ($has_metrics * 10) + ($has_sections * 8) + ($has_tools * 8);
            $score = max(35, min(88, $score));

            return [
                'score' => $score,
                'label' => $score >= 75 ? __('Recruiter-ready', 'senna-finance') : __('Needs tightening', 'senna-finance'),
                'summary' => __('Stored CV scored from structure, quantified impact, and finance keyword visibility.', 'senna-finance'),
                'top_strength' => $has_metrics ? __('Quantified evidence is visible', 'senna-finance') : __('Experience sections are present', 'senna-finance'),
                'top_gap' => !$has_metrics ? __('Add more quantified outcomes', 'senna-finance') : __('Tighten skill wording near the top', 'senna-finance'),
                'keywords' => $this->extract_crm_reddit_cv_keyword_signals($cv_text, 10),
                'locations' => $this->extract_crm_reddit_cv_location_signals($cv_text, 6),
                'target_roles' => $this->extract_crm_reddit_cv_role_signals($cv_text, 6),
                'sectors' => $this->extract_crm_reddit_cv_sector_signals($cv_text, 6),
                'seniority' => $this->extract_crm_reddit_cv_seniority_signals($cv_text, 4),
                'ats_explainer' => [
                    'summary' => __('This ATS score reflects structure, finance-language visibility, quantified impact, and how clearly the CV signals the roles it is targeting.', 'senna-finance'),
                    'strengths' => [
                        $has_metrics ? __('Quantified finance evidence is visible.', 'senna-finance') : __('Core finance experience is present.', 'senna-finance'),
                    ],
                    'gaps' => [
                        !$has_metrics ? __('Add more quantified outcomes and transaction detail.', 'senna-finance') : __('Tighten the opening positioning so the role target is clearer.', 'senna-finance'),
                    ],
                    'next_steps' => [
                        __('Sharpen the opening summary around the target role.', 'senna-finance'),
                        __('Bring the strongest quantified impact closer to the top of the CV.', 'senna-finance'),
                        __('Mirror the exact finance keywords recruiters are likely to search for.', 'senna-finance'),
                    ],
                ],
            ];
        }

        private function is_crm_reddit_cv_ats_scan_current($stored, $source_hash)
        {
            return is_array($stored)
                && (string) ($stored['source_hash'] ?? '') === (string) $source_hash
                && !empty($stored['score'])
                && (int) ($stored['version'] ?? 0) >= $this->get_crm_reddit_cv_ats_scan_version()
                && (string) ($stored['plugin_version'] ?? '') === $this->get_crm_reddit_cv_ats_scan_plugin_version();
        }

        private function has_crm_reddit_cv_ats_explainer($stored)
        {
            return is_array($stored)
                && !empty($stored['ats_explainer'])
                && is_array($stored['ats_explainer'])
                && !empty($stored['ats_explainer']['summary']);
        }

        private function normalize_crm_reddit_cv_signal_terms($items, $label_key = 'name')
        {
            $normalized = [];

            foreach ((array) $items as $item) {
                if (is_string($item)) {
                    $label = sanitize_text_field($item);
                    $weight = 0.5;
                } elseif (is_array($item)) {
                    $label = sanitize_text_field((string) ($item[$label_key] ?? $item['label'] ?? $item['term'] ?? $item['name'] ?? ''));
                    $weight = (float) ($item['weight'] ?? 0.5);
                } else {
                    continue;
                }

                if ($label === '') {
                    continue;
                }

                $normalized[] = [
                    'label' => $label,
                    'weight' => max(0.1, min(1.0, $weight)),
                ];
            }

            return array_slice($normalized, 0, 12);
        }

