        private function extract_crm_reddit_cv_seniority_signals($cv_text, $limit = 4)
        {
            $phrases = [
                'intern',
                'summer',
                'off-cycle',
                'graduate',
                'analyst',
                'senior analyst',
                'associate',
                'senior associate',
                'manager',
                'portfolio manager',
                'vice president',
                'vp',
                'director',
                'head of'
            ];

            return $this->extract_crm_reddit_cv_phrase_weights($cv_text, $phrases, $limit, 'name');
        }

        private function extract_crm_reddit_cv_phrase_weights($cv_text, array $phrases, $limit = 6, $label_key = 'name', array $ignore_phrases = [])
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text === '') {
                return [];
            }

            $counts = [];
            foreach ($phrases as $phrase) {
                $phrase = trim((string) $phrase);
                if ($phrase === '' || in_array($phrase, $ignore_phrases, true)) {
                    continue;
                }
                $count = $this->count_crm_reddit_dashboard_phrase_mentions($cv_text, $phrase);
                if ($count <= 0) {
                    continue;
                }
                $counts[$phrase] = $count;
            }

            if (empty($counts)) {
                return [];
            }

            arsort($counts);
            $top_count = max(1, (int) reset($counts));
            $results = [];
            foreach (array_slice($counts, 0, max(1, (int) $limit), true) as $phrase => $count) {
                $results[] = [
                    $label_key => $this->format_crm_reddit_dashboard_signal_phrase($phrase),
                    'weight' => max(0.2, min(1.0, round($count / $top_count, 2))),
                ];
            }

            return $results;
        }

        private function apply_crm_reddit_dashboard_cv_ats_overlay(array $insights, array $cv_ats_payload = [])
        {
            if (empty($insights[0]) || empty($cv_ats_payload['score'])) {
                return $insights;
            }

            $score = max(35, min(95, (int) $cv_ats_payload['score']));
            $label = trim((string) ($cv_ats_payload['label'] ?? ''));
            $summary = trim((string) ($cv_ats_payload['summary'] ?? ''));
            $top_gap = trim((string) ($cv_ats_payload['top_gap'] ?? ''));

            $insights[0]['primary']['value'] = sprintf(__('%d%%', 'senna-finance'), $score);
            $insights[0]['primary']['delta_label'] = $label !== '' ? $label : ($score >= 75 ? __('Recruiter-ready', 'senna-finance') : __('Needs tightening', 'senna-finance'));
            $insights[0]['primary']['delta_tone'] = $score >= 75 ? 'positive' : 'caution';
            $insights[0]['secondary']['label'] = __('Priority fix', 'senna-finance');
            $insights[0]['secondary']['value'] = $top_gap !== '' ? $top_gap : __('Tighten profile wording', 'senna-finance');
            $insights[0]['secondary']['note'] = $summary !== '' ? $summary : (string) ($insights[0]['secondary']['note'] ?? '');
            if ($summary !== '') {
                $insights[0]['note'] = $summary;
            }

            return $insights;
        }

        private function render_crm_reddit_account_shell($user_id, array $account_user, array $nav_groups)
        {
            ob_start();
        ?>
            <section class="sffc-crm-reddit-account-shell" data-reddit-account-shell hidden>
                <div class="sffc-crm-reddit-account-head">
                    <div class="sffc-crm-reddit-account-heading">
                        <span><?php esc_html_e('Member workspace', 'senna-finance'); ?></span>
