        private function render_crm_reddit_dashboard_profile_view($user_id, array $account_user = [], array $args = [])
        {
            $is_public_profile = !empty($args['public_profile']);

            if ((!$is_public_profile && !is_user_logged_in()) || (int) $user_id <= 0) {
                if ($is_public_profile) {
                    return '<section class="sffc-crm-dashboard-app-profile-page sffc-crm-dashboard-app-profile-page--public" data-dashboard-profile-shell><div class="sffc-crm-dashboard-app-profile-guest"><div class="sffc-crm-dashboard-app-profile-guest-copy"><span>' . esc_html__('Profile unavailable', 'senna-finance') . '</span><h2>' . esc_html__('We could not find that public profile.', 'senna-finance') . '</h2></div></div></section>';
                }

                $join_url = $this->get_crm_reddit_membership_url();
                ob_start();
            ?>
                <section class="sffc-crm-dashboard-app-profile-page sffc-crm-dashboard-app-profile-page--guest" data-dashboard-profile-shell>
                    <div class="sffc-crm-dashboard-app-profile-guest">
                        <div class="sffc-crm-dashboard-app-profile-guest-copy">
                            <span><?php esc_html_e('Build a recruiter-ready MENA Careers profile', 'senna-finance'); ?></span>
                            <h2><?php esc_html_e('Save your roles, locations, skills, and alerts in one private profile.', 'senna-finance'); ?></h2>
                            <p><?php esc_html_e('Shape what you want to see, what you want to avoid, and how often MENA Careers should surface matching opportunities.', 'senna-finance'); ?></p>
                        </div>
                        <a class="sffc-crm-dashboard-app-profile-save" href="<?php echo esc_url($join_url); ?>">
                            <?php esc_html_e('Join MENA Careers', 'senna-finance'); ?>
                        </a>
                    </div>
                </section>
            <?php
                return ob_get_clean();
            }

            if (empty($account_user)) {
                $account_user = $this->get_crm_reddit_account_user($user_id);
            }

            $profile = $this->get_crm_reddit_dashboard_profile_state($user_id, $account_user);
            $profile_membership_summary = $this->get_crm_reddit_membership_summary($user_id);
            $profile_membership_tier = sanitize_key((string) ($profile_membership_summary['tier'] ?? 'free'));
            $show_premium_profile_badge = in_array($profile_membership_tier, ['pro', 'insider'], true);
            $alert_label = (string) ($profile['alert_frequency_options'][$profile['alert_frequency']] ?? __('Daily', 'senna-finance'));
            $profile_location_options = [
                'Dubai, United Arab Emirates' => __('Dubai, United Arab Emirates', 'senna-finance'),
                'Abu Dhabi, United Arab Emirates' => __('Abu Dhabi, United Arab Emirates', 'senna-finance'),
                'Riyadh, Saudi Arabia' => __('Riyadh, Saudi Arabia', 'senna-finance'),
                'Doha, Qatar' => __('Doha, Qatar', 'senna-finance'),
                'Kuwait City, Kuwait' => __('Kuwait City, Kuwait', 'senna-finance'),
                'Manama, Bahrain' => __('Manama, Bahrain', 'senna-finance'),
                'London, United Kingdom' => __('London, United Kingdom', 'senna-finance'),
                'Singapore' => __('Singapore', 'senna-finance'),
                'Remote' => __('Remote', 'senna-finance'),
            ];
            foreach ((array) ($profile['target_locations'] ?? []) as $selected_location) {
                $selected_location = trim((string) $selected_location);
                if ($selected_location !== '' && !isset($profile_location_options[$selected_location])) {
                    $profile_location_options[$selected_location] = $selected_location;
                }
            }
            $profile_seniority_options = [
                'Intern' => __('Intern', 'senna-finance'),
                'Analyst' => __('Analyst', 'senna-finance'),
                'Associate' => __('Associate', 'senna-finance'),
                'Senior Associate' => __('Senior Associate', 'senna-finance'),
                'Vice President' => __('Vice President', 'senna-finance'),
                'Director' => __('Director', 'senna-finance'),
                'Managing Director' => __('Managing Director', 'senna-finance'),
            ];
            $profile_qualification_options = [
                'CFA' => __('CFA', 'senna-finance'),
                'ACA' => __('ACA', 'senna-finance'),
                'ACCA' => __('ACCA', 'senna-finance'),
                'CPA' => __('CPA', 'senna-finance'),
                'MBA' => __('MBA', 'senna-finance'),
                'Masters' => __('Masters', 'senna-finance'),
                'Bachelors' => __('Bachelors', 'senna-finance'),
            ];
            foreach ((array) ($profile['qualifications'] ?? []) as $selected_qualification) {
                $selected_qualification = trim((string) $selected_qualification);
                if ($selected_qualification !== '' && !isset($profile_qualification_options[$selected_qualification])) {
                    $profile_qualification_options[$selected_qualification] = $selected_qualification;
                }
            }
            $profile_cover_url = (string) ($profile['cover_url'] ?? $this->get_crm_reddit_profile_cover_url($user_id));
            $profile_headline = trim((string) ($profile['headline'] ?? ''));
            $profile_location_label = !empty($profile['target_locations'][0])
                ? (string) $profile['target_locations'][0]
                : __('Dubai, United Arab Emirates', 'senna-finance');
            $profile_followers_label = sprintf(
                _n('%s role tracked', '%s roles tracked', (int) ($profile['role_count'] ?? 0), 'senna-finance'),
                number_format_i18n((int) ($profile['role_count'] ?? 0))
            );
            $profile_connection_label = sprintf(
                _n('%s qualification', '%s qualifications', (int) ($profile['qualification_count'] ?? 0), 'senna-finance'),
                number_format_i18n((int) ($profile['qualification_count'] ?? 0))
            );
            $profile_public_url = $this->get_crm_reddit_public_profile_url($user_id);
            $profile_public_label = preg_replace('#^https?://#', '', $profile_public_url);
            $profile_public_label = $profile_public_label !== null ? trim((string) $profile_public_label, '/') : '';
            $profile_primary_language = !empty($profile['languages'][0])
                ? (string) $profile['languages'][0]
                : __('English', 'senna-finance');
            $recommended_jobs = $this->get_crm_reddit_dashboard_profile_recommended_jobs($profile, 5);

            ob_start();
            ?>
            <section class="sffc-crm-dashboard-app-profile-page<?php echo $is_public_profile ? ' sffc-crm-dashboard-app-profile-page--public' : ''; ?>" data-dashboard-profile-shell data-active-profile-tab="overview">
                <form class="sffc-crm-dashboard-app-profile-form" data-dashboard-profile-form>
                    <div class="sffc-crm-dashboard-app-profile-summary sffc-crm-dashboard-app-profile-summary--linkedin">
                        <article class="sffc-crm-dashboard-app-profile-summary-main">
                            <div class="sffc-crm-dashboard-app-profile-cover" data-dashboard-profile-cover style="background-image: linear-gradient(180deg, rgba(0,0,0,0.08), rgba(0,0,0,0.18)), url('<?php echo esc_url($profile_cover_url); ?>');">
                                <?php if (!$is_public_profile) : ?>
                                    <input type="file" name="cover_file" accept=".jpg,.jpeg,.png,.webp" data-dashboard-profile-cover-input hidden>
                                    <button type="button" class="sffc-crm-dashboard-app-profile-cover-edit" aria-label="<?php esc_attr_e('Edit cover image', 'senna-finance'); ?>">
                                        <svg viewBox="0 0 20 20" aria-hidden="true" focusable="false">
                                            <path d="m4 13.7-.7 3 3-.7 8.7-8.7-2.3-2.3L4 13.7Z" fill="currentColor" />
                                            <path d="m13.6 4 2.4 2.4.7-.7a1.7 1.7 0 0 0-2.4-2.4l-.7.7Z" fill="currentColor" />
                                        </svg>
                                    </button>
                                <?php endif; ?>
                            </div>
                            <div class="sffc-crm-dashboard-app-profile-summary-head">
                                <label class="sffc-crm-dashboard-app-profile-avatar-field">
                                    <?php if (!$is_public_profile) : ?>
                                        <input type="file" name="avatar_file" accept=".jpg,.jpeg,.png,.webp" data-dashboard-profile-avatar-input>
                                    <?php endif; ?>
                                    <span class="sffc-crm-dashboard-app-profile-avatar-media<?php echo !empty($profile['avatar_url']) ? ' has-image' : ''; ?>" data-dashboard-profile-avatar-media>
                                        <?php if (!empty($profile['avatar_url'])) : ?>
                                            <img src="<?php echo esc_url((string) $profile['avatar_url']); ?>" alt="<?php echo esc_attr((string) ($profile['display_name'] ?? '')); ?>">
                                        <?php else : ?>
                                            <strong><?php echo esc_html((string) ($profile['avatar_initial'] ?? 'S')); ?></strong>
                                        <?php endif; ?>
                                    </span>
