        private function render_crm_reddit_dashboard_review_cv_view($user_id, array $resume_payload = [], $jobs_post_id = 0)
        {
            if (!is_user_logged_in() || (int) $user_id <= 0) {
                $join_url = $this->get_crm_reddit_membership_url();
                $guest_cards = [
                    [
                        'image' => 'https://media.joinsenna.com/2025/05/vecteezy_examiner-reading-a-resume-during-job-interview-at-office_27087428-scaled.jpg?1747417164',
                        'title' => __('Get a recruiter-style positioning review before you apply', 'senna-finance'),
                        'description' => __('See what weakens your positioning and what to tighten before you submit.', 'senna-finance'),
                        'cta' => __('Review my CV', 'senna-finance'),
                    ],
                    [
                        'image' => 'https://joinsenna.com/wp-content/uploads/2024/02/vecteezy_happy-millennial-caucasian-lady-in-suit-typing-on-tablet-at_39011035-scaled.jpg',
                        'title' => __('Compare your CV directly against the live job description', 'senna-finance'),
                        'description' => __('Map your experience against the brief and spot the gaps recruiters will notice first.', 'senna-finance'),
                        'cta' => __('Compare to role', 'senna-finance'),
                    ],
                    [
                        'image' => 'https://joinsenna.com/wp-content/uploads/2023/12/151470567-two-business-women-work-office-2048x1366-1.jpeg',
                        'title' => __('See which recruiters are most likely to respond to your profile', 'senna-finance'),
                        'description' => __('Understand where your background looks strongest and who is most worth approaching.', 'senna-finance'),
                        'cta' => __('Match with recruiters', 'senna-finance'),
                    ],
                    [
                        'image' => 'https://joinsenna.com/wp-content/uploads/2023/11/vecteezy_business-partnership-handshake-concept-photo-two-coworkers_26312344_877-scaled.jpg',
                        'title' => __('Fix your positioning and move faster toward interviews', 'senna-finance'),
                        'description' => __('Turn vague experience into a sharper story that improves your chances of getting hired.', 'senna-finance'),
                        'cta' => __('Join and get hired', 'senna-finance'),
                    ],
                ];
                ob_start();
            ?>
                <section class="sffc-crm-dashboard-app-review" data-dashboard-review-shell>
                    <div class="sffc-crm-dashboard-app-review-guest">
                        <header class="sffc-crm-dashboard-app-review-guest-head">
                            <h2><?php esc_html_e('Join, sharpen your positioning, and match with recruiters', 'senna-finance'); ?></h2>
                            <a class="sffc-crm-dashboard-app-review-guest-head-cta" href="<?php echo esc_url($join_url); ?>">
                                <?php esc_html_e('Review My CV', 'senna-finance'); ?>
                            </a>
                        </header>
                        <div class="sffc-crm-dashboard-app-review-guest-carousel">
                            <?php foreach ($guest_cards as $guest_card) : ?>
                                <article class="sffc-crm-dashboard-app-review-guest-card">
                                    <div class="sffc-crm-dashboard-app-review-guest-media">
                                        <img src="<?php echo esc_url((string) $guest_card['image']); ?>" alt="<?php echo esc_attr((string) $guest_card['title']); ?>">
                                    </div>
                                    <div class="sffc-crm-dashboard-app-review-guest-copy">
                                        <h3><?php echo esc_html((string) $guest_card['title']); ?></h3>
                                        <p><?php echo esc_html((string) ($guest_card['description'] ?? '')); ?></p>
                                    </div>
                                    <a class="sffc-crm-dashboard-app-review-guest-cta" href="<?php echo esc_url($join_url); ?>">
                                        <span><?php echo esc_html((string) $guest_card['cta']); ?></span>
                                        <span aria-hidden="true">›</span>
                                    </a>
                                </article>
                            <?php endforeach; ?>
                        </div>
                    </div>
                </section>
            <?php
                return ob_get_clean();
            }

            $documents = $this->get_crm_reddit_resume_uploads($user_id, 24);
            $pasted_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) get_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), true));
            $has_pasted_cv = $pasted_cv_text !== '';
            $review_jobs_post_id = $this->get_crm_reddit_dashboard_default_jobs_post_id((int) $jobs_post_id);
            $stored_count = count($documents);
            $active_source = (string) ($resume_payload['source'] ?? '');
            $active_cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $editor_cv_text = $active_source === 'upload' && $active_cv_text !== '' ? $active_cv_text : $pasted_cv_text;
            $has_editor_cv = $editor_cv_text !== '';
            $primary_label = $active_source === 'pasted'
                ? __('Pasted CV is active', 'senna-finance')
                : ($active_source === 'upload'
                    ? __('Uploaded resume is active', 'senna-finance')
                    : (!empty($resume_payload['has_cv']) ? __('Stored resume is active', 'senna-finance') : __('No active CV yet', 'senna-finance')));
            $pasted_saved_label = $active_source === 'upload' && $active_cv_text !== ''
                ? __('Text extracted from your active uploaded resume. You can edit it here and save it as a live profile.', 'senna-finance')
                : ($has_pasted_cv ? __('Saved in your dashboard profile', 'senna-finance') : __('Paste your CV text to create your primary review profile', 'senna-finance'));
