        public function ajax_reddit_generate_interview_questions_custom()
        {
            check_ajax_referer('sffc_crm_reddit_account', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Join MENA Careers to connect your saved CV and generate interview questions.', 'senna-finance')], 403);
            }

            if (!$this->current_user_has_crm_reddit_premium_access()) {
                wp_send_json_error(['message' => __('Upgrade your membership to unlock tailored interview questions.', 'senna-finance')], 402);
            }

            $user_id = get_current_user_id();
            $role_title = sanitize_text_field((string) wp_unslash($_POST['role_title'] ?? ''));
            $company = sanitize_text_field((string) wp_unslash($_POST['company'] ?? ''));
            $job_description = sanitize_textarea_field((string) wp_unslash($_POST['job_description'] ?? ''));
            $cv_source = sanitize_text_field((string) wp_unslash($_POST['cv_source'] ?? 'active'));

            if ($job_description === '') {
                wp_send_json_error(['message' => __('Paste the job description first.', 'senna-finance')], 422);
            }

            $job_description_length = function_exists('mb_strlen') ? mb_strlen($job_description) : strlen($job_description);
            if ($job_description_length < 180) {
                wp_send_json_error(['message' => __('Paste a fuller job description so MENA Careers has enough detail to work with.', 'senna-finance')], 422);
            }

            $resume_payload = $this->resolve_crm_reddit_dashboard_outreach_cv_text($user_id, $cv_source);
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            if ($cv_text === '') {
                wp_send_json_error(['message' => __('Save a CV in Profile > Career Assessment first, then choose it here.', 'senna-finance')], 422);
            }

            $prepared = $this->prepare_cv_match_interview_questions_payload([
                'role_title' => $role_title,
                'company' => $company,
                'job_description' => $job_description,
                'cv_text' => $cv_text,
            ]);

            if (is_wp_error($prepared)) {
                wp_send_json_error(['message' => $prepared->get_error_message()], (int) ($prepared->get_error_data('status') ?: 500));
            }

            wp_send_json_success([
                'title' => (string) ($prepared['title'] ?? ''),
                'markup' => (string) ($prepared['markup'] ?? ''),
            ]);
        }

        private function prepare_cv_match_interview_questions_payload(array $args)
        {
            $role_title = trim((string) ($args['role_title'] ?? ''));
            $company = trim((string) ($args['company'] ?? ''));
            $job_description = trim((string) ($args['job_description'] ?? ''));
            $cv_text = trim((string) ($args['cv_text'] ?? ''));

            if ($job_description === '') {
                return new WP_Error('interview_questions_missing_description', __('A job description is required.', 'senna-finance'), ['status' => 422]);
            }

            $context = [
                'role_title' => $role_title !== '' ? $role_title : __('Target role', 'senna-finance'),
                'company' => $company !== '' ? $company : __('Target firm', 'senna-finance'),
                'location' => '',
                'industry' => 'Finance',
                'seniority' => '',
                'recruiter_name' => '',
                'recruiter_title' => '',
                'recruiter_firm' => '',
                'posted_label' => __('Pasted role brief', 'senna-finance'),
                'keywords' => [],
                'skills' => [],
                'requirements' => $this->extract_cv_match_interview_requirements($job_description),
                'application_process' => [],
                'has_cv' => $cv_text !== '',
                'cv_text' => $cv_text,
                'job_description' => $job_description,
            ];

            $config = $this->get_crm_reddit_material_type_config('interview_questions', $context);
            if (empty($config)) {
                return new WP_Error('interview_questions_config_missing', __('Interview questions are not configured right now.', 'senna-finance'), ['status' => 500]);
            }

            $context['material_type'] = 'interview_questions';
            $context['material_label'] = (string) ($config['label'] ?? '');
            $context['material_headline'] = (string) ($config['headline'] ?? '');
            $context['download_extension'] = (string) ($config['download_extension'] ?? 'docx');
            $context['download_name'] = (string) ($config['download_name'] ?? 'interview-questions');
            $context['loading_label'] = (string) ($config['loading_label'] ?? '');

            $material = $this->get_or_generate_crm_reddit_material($context, 'interview_questions', 0);
            if (empty($material)) {
                return new WP_Error('interview_questions_generation_failed', __('We could not generate interview questions right now.', 'senna-finance'), ['status' => 500]);
            }

            return [
                'title' => (string) ($material['title'] ?? ''),
                'markup' => $this->render_crm_reddit_material_markup($material, $context, 'interview_questions'),
                'material' => $material,
                'context' => $context,
            ];
        }

        private function extract_cv_match_interview_requirements($job_description)
        {
            $lines = preg_split('/[\r\n]+/', (string) $job_description);
            $requirements = [];

            foreach ((array) $lines as $line) {
                $clean_line = trim(wp_strip_all_tags((string) $line));
                $clean_line = preg_replace('/^[\-\*\•\d\.\)\s]+/', '', (string) $clean_line);
                if ($clean_line === '') {
                    continue;
                }
                if (function_exists('mb_strlen') ? mb_strlen($clean_line) < 26 : strlen($clean_line) < 26) {
                    continue;
                }
                $requirements[] = sanitize_text_field($clean_line);
                if (count($requirements) >= 8) {
                    break;
                }
            }

            return $requirements;
        }

        private function get_crm_reddit_dashboard_outreach_cv_options($user_id, array $resume_payload = [])
        {
            $options = [];
            $active_source = (string) ($resume_payload['source'] ?? '');
            $active_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            if ($active_text !== '') {
                $active_label = $active_source === 'upload'
                    ? __('Active uploaded resume', 'senna-finance')
                    : __('Active CV profile', 'senna-finance');
                $options[] = [
                    'value' => 'active',
                    'label' => $active_label,
                    'description' => $active_source === 'upload'
                        ? __('Use the resume currently marked active in your dashboard.', 'senna-finance')
                        : __('Use the profile text currently saved as your active CV.', 'senna-finance'),
                ];
            }

            $pasted_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) get_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), true));
            if ($pasted_cv_text !== '') {
                $options[] = [
                    'value' => 'pasted',
                    'label' => __('Pasted CV profile', 'senna-finance'),
                    'description' => __('Reach for the CV text you pasted and edited directly in MENA Careers.', 'senna-finance'),
                ];
            }

            $documents = $this->get_crm_reddit_resume_uploads($user_id, 12);
            foreach ($documents as $document) {
                $upload_id = (int) ($document['id'] ?? 0);
                if ($upload_id <= 0) {
                    continue;
                }

                $options[] = [
                    'value' => 'upload:' . $upload_id,
                    'label' => sprintf(
                        __('Upload: %1$s', 'senna-finance'),
                        (string) ($document['name'] ?? __('Stored resume', 'senna-finance'))
                    ),
                    'description' => __('Use a saved uploaded resume file as the message source.', 'senna-finance'),
                ];
            }

            if (empty($options)) {
                $options[] = [
                    'value' => '',
                    'label' => __('No saved CV source yet', 'senna-finance'),
                    'description' => __('Save a CV in Profile > Career Assessment first to personalise the outreach.', 'senna-finance'),
                ];
            }

            return array_values(array_unique($options, SORT_REGULAR));
        }

        private function get_crm_reddit_dashboard_outreach_role_options($preferred_jobs_post_id = 0)
        {
            $options = [];
            $jobs_ids = get_posts([
                'post_type' => 'jobs',
                'post_status' => 'publish',
                'posts_per_page' => 18,
                'orderby' => 'date',
                'order' => 'DESC',
                'fields' => 'ids',
                'no_found_rows' => true,
            ]);

            $preferred_jobs_post_id = (int) $preferred_jobs_post_id;
            if ($preferred_jobs_post_id > 0 && !in_array($preferred_jobs_post_id, $jobs_ids, true)) {
                array_unshift($jobs_ids, $preferred_jobs_post_id);
            }

            foreach (array_values(array_unique(array_map('intval', $jobs_ids))) as $jobs_id) {
                if ($jobs_id <= 0) {
                    continue;
                }

                $item = $this->get_crm_reddit_jobs_item($jobs_id);
                if (empty($item)) {
                    continue;
                }

                $label_bits = array_filter([
                    (string) ($item['role_title'] ?? ''),
                    (string) ($item['company'] ?? ''),
                ]);
                $role_meta_bits = array_filter([
                    (string) ($item['location'] ?? ''),
                    (string) ($item['workplace_type'] ?? ''),
                ]);

                $options[] = [
                    'value' => $jobs_id,
                    'label' => implode(' · ', $label_bits),
                    'description' => !empty($role_meta_bits)
                        ? implode(' · ', $role_meta_bits)
                        : __('Live role context', 'senna-finance'),
                    'recipient_name' => (string) ($item['recruiter_name'] ?? ''),
                    'recipient_role' => (string) ($item['recruiter_title'] ?? ''),
                ];
            }

            if (empty($options)) {
                $options[] = [
                    'value' => 0,
                    'label' => __('No live role selected', 'senna-finance'),
                    'description' => __('Select a role to let MENA Careers tailor the recruiter angle.', 'senna-finance'),
                    'recipient_name' => '',
                    'recipient_role' => '',
                ];
            }

            return $options;
        }

        private function get_crm_reddit_dashboard_search_role_options()
        {
            $cache_key = 'sffc_crm_dash_role_options_v1';
            $cached = get_transient($cache_key);
            if (is_array($cached) && !empty($cached)) {
                return $cached;
            }

            global $wpdb;

            $role_options = [
                __('Investment Associate', 'senna-finance'),
                __('Senior Associate', 'senna-finance'),
                __('Vice President', 'senna-finance'),
                __('Principal', 'senna-finance'),
                __('Investment Director', 'senna-finance'),
                __('Portfolio Operations Manager', 'senna-finance'),
                __('Investor Relations Associate', 'senna-finance'),
                __('Fund Finance Manager', 'senna-finance'),
                __('Private Credit Associate', 'senna-finance'),
                __('Venture Capital Associate', 'senna-finance'),
                __('Asset Management Associate', 'senna-finance'),
                __('Growth Equity Associate', 'senna-finance'),
                __('Infrastructure Associate', 'senna-finance'),
                __('Portfolio Value Creation Manager', 'senna-finance'),
                __('Hedge Fund Associate', 'senna-finance'),
                __('Investor Relations Manager', 'senna-finance'),
                __('Risk Manager', 'senna-finance'),
                __('Investment Director', 'senna-finance'),
                __('Investment Associate', 'senna-finance'),
                __('Portfolio Manager', 'senna-finance'),
            ];

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $posts_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($posts_table))) === $posts_table;
            if ($posts_table_exists) {
                $post_role_options = $wpdb->get_col(
                    "SELECT role_title
                     FROM {$posts_table}
                     WHERE role_title IS NOT NULL AND role_title != '' AND is_active = 1 AND admin_approved = 1
                     GROUP BY role_title
                     ORDER BY COUNT(*) DESC, role_title ASC
                     LIMIT 80"
                );
                if (!empty($post_role_options)) {
                    $role_options = array_merge($role_options, array_map('sanitize_text_field', $post_role_options));
                }
            }

            $jobs_query = new WP_Query([
                'post_type' => 'jobs',
                'post_status' => 'publish',
                'posts_per_page' => 60,
                'orderby' => 'date',
                'order' => 'DESC',
                'fields' => 'ids',
                'no_found_rows' => true,
            ]);
            if (!empty($jobs_query->posts)) {
                foreach ((array) $jobs_query->posts as $job_id) {
                    $title = get_the_title((int) $job_id);
                    if ($title !== '') {
                        $role_options[] = sanitize_text_field($title);
                    }
                }
            }

            $role_options = array_values(array_unique(array_filter(array_map('trim', $role_options))));
            natcasesort($role_options);
            $role_options = array_values($role_options);
            set_transient($cache_key, $role_options, DAY_IN_SECONDS);

            return $role_options;
        }

