        private function render_crm_reddit_outreach_message_html($body, array $context_state = [])
        {
            $body = trim((string) $body);
            if ($body === '') {
                return '';
            }

            $phrases = array_values(array_filter([
                (string) ($context_state['role_title'] ?? ''),
                (string) ($context_state['company'] ?? ''),
                (string) ($context_state['location'] ?? ''),
                (string) (($context_state['keywords'][0] ?? '')),
                (string) (($context_state['keywords'][1] ?? '')),
                (string) (($context_state['skills'][0] ?? '')),
                (string) (($context_state['skills'][1] ?? '')),
            ]));

            $highlight_classes = [
                'is-green',
                'is-orange',
                'is-purple',
            ];

            $paragraphs = preg_split("/\n{2,}/", $body) ?: [$body];
            $html_parts = [];

            foreach ($paragraphs as $paragraph) {
                $paragraph = trim((string) $paragraph);
                if ($paragraph === '') {
                    continue;
                }

                $sentences = preg_split('/(?<=[\.\?\!])\s+/', $paragraph) ?: [$paragraph];
                $sentence_parts = [];

                foreach ($sentences as $sentence) {
                    $sentence = trim((string) $sentence);
                    if ($sentence === '') {
                        continue;
                    }

                    $sentence_html = esc_html($sentence);
                    $class_index = 0;

                    foreach ($phrases as $phrase) {
                        $phrase = trim((string) $phrase);
                        if ($phrase === '') {
                            continue;
                        }

                        $escaped_phrase = preg_quote(esc_html($phrase), '/');
                        $highlight_class = $highlight_classes[$class_index % count($highlight_classes)];
                        $sentence_html = preg_replace(
                            '/(' . $escaped_phrase . ')/iu',
                            '<mark class="sffc-crm-dashboard-app-outreach-inline ' . $highlight_class . '">$1</mark>',
                            $sentence_html
                        );
                        $class_index++;
                    }

                    if (strpos($sentence, '?') !== false) {
                        $sentence_html = '<span class="sffc-crm-dashboard-app-outreach-inline is-underlined">' . $sentence_html . '</span>';
                    }

                    $sentence_parts[] = $sentence_html;
                }

                if (!empty($sentence_parts)) {
                    $html_parts[] = '<p>' . implode(' ', $sentence_parts) . '</p>';
                }
            }

            return implode('', $html_parts);
        }

        private function call_crm_reddit_outreach_claude(array $context)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 2600,
                'temperature' => 0.15,
                'system' => $this->get_crm_reddit_outreach_system_prompt(),
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => $this->build_crm_reddit_outreach_user_prompt($context),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit Outreach Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);

            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit Outreach Claude Error: status ' . $status);
                return null;
            }

            return $this->parse_crm_reddit_networking_json((string) $body['content'][0]['text']);
        }

        private function get_crm_reddit_outreach_system_prompt()
        {
            return 'You are MENA Careers’s recruiter outreach strategist. Your job is to generate recruiter messages that feel specific, credible, and worth replying to.

CRITICAL INSTRUCTIONS:
1. Return only valid JSON with no markdown.
2. Adapt the output to both the outreach context and the target channel.
3. LinkedIn / InMail should use a sharp hook and low-pressure close.
4. Email should emphasise value, clarity, and usually end with an easy question.
5. Text and WhatsApp should be much shorter and easier to answer quickly.
6. If the role context exists, use it concretely. If it does not, use the CV and relationship context to shape the message.
7. Do not invent credentials, experience, or access that are not visible in the CV or role context.
8. Do not sound desperate, generic, or overly formal.
9. Suggest smart extra tactics such as voice notes, lower-pressure closes, or focused follow-up only when appropriate.
10. The message is FROM the candidate TO the recipient. Never address the candidate as if they are the recipient.
11. If a recipient name is supplied, address the message to that person. If not, use the recruiter/contact from the role context.
12. Keep the output sharply useful, not verbose.
13. Never use lazy openings such as "I noticed you...", "I came across...", "I’m curious about your perspective", or "Hope you do not mind the message".
14. The opener must contain one concrete role-, company-, team-, or market-specific angle drawn from the brief or context.
15. The message should feel like a thoughtful human note, not a networking template.
16. Make the ask easy to answer and engineered to get a reply, not admiration.
17. Avoid flattery, vague enthusiasm, or generic statements about being passionate / interested.
18. If the supplied context is thin, stay concise and clean rather than filling space with generic recruiter language.';
        }

        private function build_crm_reddit_outreach_user_prompt(array $context)
        {
            $job_description = (string) ($context['job_description'] ?? '');
            if (strlen($job_description) > 9000) {
                $job_description = substr($job_description, 0, 9000) . "\n[TRUNCATED]";
            }

            $cv_text = trim((string) ($context['cv_text'] ?? ''));
            if (strlen($cv_text) > 6500) {
                $cv_text = substr($cv_text, 0, 6500) . "\n[TRUNCATED]";
            }

            $prompt_context = [
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'location' => (string) ($context['location'] ?? ''),
                'industry' => (string) ($context['industry'] ?? ''),
                'recruiter_name' => (string) ($context['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($context['recruiter_title'] ?? ''),
                'recruiter_firm' => (string) ($context['recruiter_firm'] ?? ''),
                'keywords' => array_values(array_slice((array) ($context['keywords'] ?? []), 0, 8)),
                'skills' => array_values(array_slice((array) ($context['skills'] ?? []), 0, 8)),
                'requirements' => array_values(array_slice((array) ($context['requirements'] ?? []), 0, 8)),
                'outreach_context' => (string) ($context['outreach_context'] ?? ''),
                'target_channel' => (string) ($context['target_channel'] ?? ''),
                'recipient_name' => (string) ($context['recipient_name'] ?? ''),
                'recipient_role' => (string) ($context['recipient_role'] ?? ''),
                'user_context' => (string) ($context['user_context'] ?? ''),
            ];

            return 'Create a recruiter outreach message using the CV and role context below.

ROLE / CHANNEL CONTEXT:
' . wp_json_encode($prompt_context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '

CV EXCERPT:
' . $cv_text . '

JOB DESCRIPTION:
' . $job_description . '

RECIPIENT RULE:
The outreach message must be addressed TO the recipient named in recipient_name (or the recruiter/contact in role context if recipient_name is blank). The sender is the candidate whose CV is provided above.

QUALITY BAR:
- The message must sound like it was written for this exact scenario, not a reusable recruiter template.
- Use one concrete role/company/team/market hook early.
- The ask should be light, specific, and easy to answer.
- No generic recruiter flattery.
- No "I noticed..." opener.
- No "curious about your perspective on something."
- No broad networking copy if the user selected a specific role context.

Return ONLY this JSON structure:
{
  "headline": "1 sentence on the smartest outreach angle",
  "why_this_works": "2-3 sentences explaining why this approach fits the context and channel",
  "positioning_signals": ["3-4 specific things from the CV/role to lead with"],
  "watchouts": ["2-4 mistakes to avoid in this exact outreach"],
  "message": {
    "channel_label": "LinkedIn InMail|LinkedIn message|Email|Text|WhatsApp",
    "context_label": "human-readable outreach context",
    "subject": "subject line or empty string if not needed",
    "opening_hook": "best opening angle",
    "body": "ready-to-send message",
    "follow_up": "how and when to follow up",
    "bonus_tactic": "optional smart tactic like voice note, lower-pressure close, or question ending"
  },
  "variants": [
    {"label": "Shorter version", "body": "shorter alternative"},
    {"label": "Warmer version", "body": "warmer alternative"}
  ]
}';
        }

        private function build_crm_reddit_outreach_fallback(array $context)
        {
            $role_title = (string) ($context['role_title'] ?? __('the role', 'senna-finance'));
            $company = (string) ($context['company'] ?? __('the team', 'senna-finance'));
            $industry = (string) ($context['industry'] ?? __('finance', 'senna-finance'));
            $target_channel = (string) ($context['target_channel'] ?? 'linkedin_inmail');
            $outreach_context = (string) ($context['outreach_context'] ?? 'enquiring_about_role');
            $recipient_name = trim((string) ($context['recipient_name'] ?? ''));
            $recipient_role = trim((string) ($context['recipient_role'] ?? ''));
            $user_context = trim((string) ($context['user_context'] ?? ''));
            $keywords = array_values(array_filter(array_map('strval', (array) ($context['keywords'] ?? []))));
            $skills = array_values(array_filter(array_map('strval', (array) ($context['skills'] ?? []))));
            $lead_signal = $keywords[0] ?? ($skills[0] ?? __('the role brief', 'senna-finance'));
            $second_signal = $skills[0] ?? ($keywords[1] ?? __('relevant experience', 'senna-finance'));
            $name_or_there = $recipient_name !== '' ? $recipient_name : __('there', 'senna-finance');
            $role_or_contact = $recipient_role !== '' ? $recipient_role : __('recruiter', 'senna-finance');
            $relationship_line = $user_context !== '' ? sanitize_text_field(wp_trim_words($user_context, 12, '')) : '';

            $channel_label_map = [
                'linkedin_inmail' => __('LinkedIn InMail', 'senna-finance'),
                'linkedin_message' => __('LinkedIn message', 'senna-finance'),
                'email' => __('Email', 'senna-finance'),
                'text' => __('Text', 'senna-finance'),
                'whatsapp' => __('WhatsApp', 'senna-finance'),
            ];
            $context_label_map = [
                'general_linkedin_connection' => __('General connection', 'senna-finance'),
                'enquiring_about_role' => __('Enquiring about a role', 'senna-finance'),
                'asking_for_referral' => __('Asking for a referral', 'senna-finance'),
                'looking_to_network' => __('Looking to network', 'senna-finance'),
                'asking_about_their_role' => __('Asking about their role', 'senna-finance'),
                'general_catch_up' => __('General catch up', 'senna-finance'),
                'passed_on_contact' => __('Passed on contact', 'senna-finance'),
            ];

            $subject = $target_channel === 'email'
                ? sprintf(__('%1$s at %2$s', 'senna-finance'), $role_title, $company)
                : '';
            $context_openers = [
                'general_linkedin_connection' => sprintf(__('I’m reaching out because the combination of %1$s and %2$s in %3$s at %4$s is unusually close to the work I’ve been doing.', 'senna-finance'), $lead_signal, $second_signal, $role_title, $company),
                'enquiring_about_role' => sprintf(__('The way %1$s at %2$s leans on %3$s feels especially relevant to my background.', 'senna-finance'), $role_title, $company, $lead_signal),
                'asking_for_referral' => sprintf(__('I’m looking closely at %1$s at %2$s, and the brief’s emphasis on %3$s is one of the reasons I’m taking it seriously.', 'senna-finance'), $role_title, $company, $lead_signal),
                'looking_to_network' => sprintf(__('I’m reaching out because %1$s at %2$s sits right at the intersection of %3$s and %4$s.', 'senna-finance'), $role_title, $company, $lead_signal, $second_signal),
                'asking_about_their_role' => sprintf(__('Your seat around %1$s at %2$s is exactly the sort of path I’ve been trying to understand more clearly.', 'senna-finance'), $role_title, $company),
                'general_catch_up' => sprintf(__('I thought I’d get back in touch because I’ve been looking closely at %1$s at %2$s and it lines up well with the work I’ve been doing.', 'senna-finance'), $role_title, $company),
                'passed_on_contact' => sprintf(__('I was pointed your way about %1$s at %2$s, and the brief’s emphasis on %3$s feels especially relevant to my background.', 'senna-finance'), $role_title, $company, $lead_signal),
            ];
            $context_asks = [
                'general_linkedin_connection' => __('Would you be open to connecting here? I’d value one quick steer on where candidates usually under- or over-index when they first reach out.', 'senna-finance'),
                'enquiring_about_role' => __('When you speak with strong candidates early, what tends to separate the ones you move forward beyond the obvious technical fit?', 'senna-finance'),
                'asking_for_referral' => __('If after a quick look you think the fit is real, would you be open to pointing me toward the best route in?', 'senna-finance'),
                'looking_to_network' => __('If you’re open to it, I’d value one or two lines on how you’d position someone with my background against this kind of seat.', 'senna-finance'),
                'asking_about_their_role' => __('If you’re open to it, I’d love to hear what people often misunderstand about this kind of seat when they approach it from the outside.', 'senna-finance'),
                'general_catch_up' => __('If you’re open to it, would be good to catch up properly and hear what you’re seeing in the market right now.', 'senna-finance'),
                'passed_on_contact' => __('If useful, I’d value a quick steer on whether this is a role where my background is worth pushing forward more directly.', 'senna-finance'),
            ];

            $opening_line = (string) ($context_openers[$outreach_context] ?? $context_openers['enquiring_about_role']);
            $ask_line = (string) ($context_asks[$outreach_context] ?? $context_asks['enquiring_about_role']);
            $context_bridge = $relationship_line !== ''
                ? sprintf(__(' %s.', 'senna-finance'), rtrim($relationship_line, '.'))
                : '';
            $candidate_first_name = $this->get_crm_reddit_current_user_first_name();
            if ($candidate_first_name === '') {
                $candidate_first_name = __('Candidate', 'senna-finance');
            }

            $body = sprintf(
                __('Hi %1$s,%2$s %3$s It lines up closely with my background in %4$s. %5$s Best, %6$s', 'senna-finance'),
                $name_or_there,
                $context_bridge,
                $opening_line,
                $second_signal,
                $ask_line,
                $candidate_first_name
            );

            if (strpos($target_channel, 'linkedin') === 0) {
                $body = sprintf(
                    __('Hi %1$s - %2$s It lines up closely with my background in %3$s. %4$s', 'senna-finance'),
                    $name_or_there,
                    $opening_line,
                    $second_signal,
                    $ask_line
                );
            } elseif (in_array($target_channel, ['text', 'whatsapp'], true)) {
                $body = sprintf(
                    __('Hi %1$s - %2$s My background is closest to %3$s. %4$s', 'senna-finance'),
                    $name_or_there,
                    $opening_line,
                    $second_signal,
                    $ask_line
                );
            }

            return [
                'headline' => sprintf(__('Anchor the message to %1$s at %2$s, then ask one focused question a %3$s can actually answer.', 'senna-finance'), $role_title, $company, strtolower($role_or_contact)),
                'why_this_works' => sprintf(__('This draft opens on a role-specific angle rather than recruiter flattery, ties your fit back to %1$s and %2$s, and ends with a question that is easy to answer over %3$s.', 'senna-finance'), $lead_signal, $second_signal, strtolower((string) ($channel_label_map[$target_channel] ?? __('the channel', 'senna-finance')))),
                'positioning_signals' => [
                    sprintf(__('Lead with why %s matters for this exact role.', 'senna-finance'), $lead_signal),
                    sprintf(__('Use one proof point that makes %s credible, not just claimed.', 'senna-finance'), $second_signal),
                    sprintf(__('Keep the %s angle purposeful rather than broad.', 'senna-finance'), $industry),
                ],
                'watchouts' => [
                    __('Do not open with vague recruiter flattery or "I noticed..." language.', 'senna-finance'),
                    __('Do not make the first message about wanting to "pick your brain".', 'senna-finance'),
                    __('Do not front-load too much biography before earning engagement.', 'senna-finance'),
                ],
                'message' => [
                    'channel_label' => (string) ($channel_label_map[$target_channel] ?? __('LinkedIn InMail', 'senna-finance')),
                    'context_label' => (string) ($context_label_map[$outreach_context] ?? __('Outreach', 'senna-finance')),
                    'subject' => $subject,
                    'opening_hook' => sprintf(__('Open on the %1$s / %2$s angle in %3$s at %4$s rather than on the recruiter themselves.', 'senna-finance'), $lead_signal, $second_signal, $role_title, $company),
                    'body' => $body,
                    'follow_up' => $target_channel === 'email'
                        ? __('Follow up once after 3 to 4 days with one sharper proof point or a tighter role-specific question. Do not resend the same paragraph.', 'senna-finance')
                        : __('Follow up lightly after 3 to 4 days with one fresh role-specific angle instead of repeating the first message.', 'senna-finance'),
                    'bonus_tactic' => strpos($target_channel, 'linkedin') === 0
                        ? __('If they engage but do not fully reply, a short voice note that sharpens the fit can feel more natural than another paragraph.', 'senna-finance')
                        : __('End on one easy-to-answer question so the reply feels lighter than a meeting request.', 'senna-finance'),
                ],
                'variants' => [
                    [
                        'label' => __('Shorter version', 'senna-finance'),
                        'body' => sprintf(__('Hi %1$s - I’m reaching out about %2$s at %3$s because the brief’s focus on %4$s is unusually close to my background. If useful, I’d value one quick steer on what strong candidates usually make clear early.', 'senna-finance'), $name_or_there, $role_title, $company, $lead_signal),
                    ],
                    [
                        'label' => __('Warmer version', 'senna-finance'),
                        'body' => sprintf(__('Hi %1$s - I’ve been looking closely at %2$s at %3$s and the way the brief leans on %4$s stood out because it maps closely to my background. I wanted to send a short, role-specific note and ask one focused question rather than a generic networking message.', 'senna-finance'), $name_or_there, $role_title, $company, $lead_signal),
                    ],
                ],
            ];
        }

        private function get_crm_reddit_dashboard_default_jobs_post_id($preferred_jobs_post_id = 0)
        {
            $preferred_jobs_post_id = (int) $preferred_jobs_post_id;
            if ($preferred_jobs_post_id > 0 && get_post_type($preferred_jobs_post_id) === 'jobs') {
                return $preferred_jobs_post_id;
            }

            $latest_jobs = get_posts([
                'post_type' => 'jobs',
                'post_status' => 'publish',
                'posts_per_page' => 1,
                'orderby' => 'date',
                'order' => 'DESC',
                'fields' => 'ids',
                'no_found_rows' => true,
            ]);

            return !empty($latest_jobs[0]) ? (int) $latest_jobs[0] : 0;
        }

