        public function ajax_reddit_gap_payload()
        {
            check_ajax_referer('sffc_crm_reddit_gap_payload', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $crm_post_id = isset($_POST['crm_post_id']) ? absint($_POST['crm_post_id']) : 0;
            if ($jobs_post_id <= 0) {
                if ($crm_post_id <= 0) {
                    wp_send_json_error(['message' => __('A valid role is required.', 'senna-finance')], 422);
                }

                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get_full_detail($crm_post_id, get_current_user_id());

                if (empty($crm_post)) {
                    wp_send_json_error(['message' => __('Unable to find that role.', 'senna-finance')], 404);
                }

                if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                }

                $jd_text = function_exists('sffc_build_crm_jd_text_for_analysis')
                    ? (string) sffc_build_crm_jd_text_for_analysis($crm_post)
                    : wp_strip_all_tags((string) ($crm_post['content'] ?? $crm_post['content_snippet'] ?? ''));

                $resume_payload = is_user_logged_in()
                    ? $this->get_crm_reddit_active_resume_text(get_current_user_id())
                    : ['cv_text' => '', 'has_cv' => false];

                wp_send_json_success([
                    'job_title' => (string) ($crm_post['role_title'] ?? ''),
                    'company' => (string) ($crm_post['company'] ?? ''),
                    'location' => (string) ($crm_post['location'] ?? ''),
                    'recruiter_name' => (string) ($crm_post['recruiter_name'] ?? ''),
                    'recruiter_title' => (string) ($crm_post['recruiter_title'] ?? ''),
                    'recruiter_firm' => (string) ($crm_post['recruiter_firm'] ?? ''),
                    'recruiter_photo' => (string) ($crm_post['recruiter_photo'] ?? ''),
                    'jd_text' => $jd_text,
                    'cv_text' => (string) ($resume_payload['cv_text'] ?? ''),
                    'has_cv' => !empty($resume_payload['has_cv']),
                    'materials_markup' => '',
                    'match_context' => [
                        'jobs_post_id' => 0,
                        'crm_post_id' => $crm_post_id,
                        'role_title' => (string) ($crm_post['role_title'] ?? ''),
                        'company' => (string) ($crm_post['company'] ?? ''),
                    ],
                ]);
            }

            $item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            if (empty($item)) {
                wp_send_json_error(['message' => __('Unable to find that job post.', 'senna-finance')], 404);
            }

            $jobs_post = get_post($jobs_post_id);
            if (!$jobs_post instanceof WP_Post || $jobs_post->post_type !== 'jobs') {
                wp_send_json_error(['message' => __('That job post is unavailable.', 'senna-finance')], 404);
            }

            $jd_text = '';

            if (!empty($item['crm_post_id'])) {
                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get_full_detail((int) $item['crm_post_id'], get_current_user_id());

                if (!empty($crm_post)) {
                    if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                        require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                    }

                    if (function_exists('sffc_build_crm_jd_text_for_analysis')) {
                        $jd_text = (string) sffc_build_crm_jd_text_for_analysis($crm_post);
                    }
                }
            }

            if ($jd_text === '') {
                $jd_text = $this->build_reddit_jobs_jd_text($jobs_post, $item);
            }

            $resume_payload = is_user_logged_in()
                ? $this->get_crm_reddit_active_resume_text(get_current_user_id())
                : ['cv_text' => '', 'has_cv' => false];

            wp_send_json_success([
                'job_title' => (string) ($item['role_title'] ?? ''),
                'company' => (string) ($item['company'] ?? ''),
                'location' => (string) ($item['location'] ?? ''),
                'recruiter_name' => (string) ($item['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($item['recruiter_title'] ?? ''),
                'recruiter_firm' => (string) ($item['recruiter_firm'] ?? ''),
                'recruiter_photo' => (string) ($item['recruiter_photo'] ?? ''),
                'jd_text' => $jd_text,
                'cv_text' => (string) ($resume_payload['cv_text'] ?? ''),
                'has_cv' => !empty($resume_payload['has_cv']),
                'materials_markup' => $this->render_crm_reddit_gap_materials_markup($item),
                'match_context' => [
                    'jobs_post_id' => $jobs_post_id,
                    'crm_post_id' => (int) ($item['crm_post_id'] ?? 0),
                    'role_title' => (string) ($item['role_title'] ?? ''),
                    'company' => (string) ($item['company'] ?? ''),
                ],
            ]);
        }

        public function ajax_reddit_networking_strategy()
        {
            check_ajax_referer('sffc_crm_reddit_networking_strategy', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            if ($jobs_post_id <= 0) {
                wp_send_json_error(['message' => __('A valid jobs post is required.', 'senna-finance')], 422);
            }

            $user_context = sanitize_text_field((string) ($_POST['user_context'] ?? ''));
            $context = $this->build_crm_reddit_networking_context($jobs_post_id);

            if (empty($context)) {
                wp_send_json_error(['message' => __('Unable to build networking context for this role.', 'senna-finance')], 404);
            }

            $has_networking_access = $this->current_user_has_crm_reddit_premium_access();
            $access_mode = $has_networking_access ? 'premium' : 'preview';

            $cache_key = 'sffc_reddit_networking_v3_' . md5(wp_json_encode([
                'jobs_post_id' => $jobs_post_id,
                'crm_post_id' => (int) ($context['crm_post_id'] ?? 0),
                'user_context' => $user_context,
                'access_mode' => $access_mode,
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'location' => (string) ($context['location'] ?? ''),
                'job_description' => (string) ($context['job_description'] ?? ''),
            ]));

            $strategy = get_transient($cache_key);
            if (!is_array($strategy) || empty($strategy['hero'])) {
                if ($has_networking_access) {
                    $strategy = $this->call_crm_reddit_networking_claude($context, $user_context);
                    if (empty($strategy)) {
                        $strategy = $this->build_crm_reddit_networking_preview($context, $user_context);
                    }
                } else {
                    $strategy = $this->build_crm_reddit_networking_preview($context, $user_context);
                }

                set_transient($cache_key, $strategy, 30 * MINUTE_IN_SECONDS);
            }

            wp_send_json_success([
                'markup' => $this->render_crm_reddit_networking_results_markup($strategy, $context),
                'context' => [
                    'role_title' => (string) ($context['role_title'] ?? ''),
                    'company' => (string) ($context['company'] ?? ''),
                ],
            ]);
        }

        public function ajax_reddit_material_generate()
        {
            check_ajax_referer('sffc_crm_reddit_material_generate', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $material_type = sanitize_key((string) ($_POST['material_type'] ?? ''));
            $cv_text = sanitize_textarea_field((string) ($_POST['cv_text'] ?? ''));
            $custom_context = [
                'role_title' => sanitize_text_field((string) ($_POST['role_title'] ?? '')),
                'company' => sanitize_text_field((string) ($_POST['company'] ?? '')),
                'job_description' => sanitize_textarea_field((string) ($_POST['jd_text'] ?? '')),
            ];

            if (($jobs_post_id <= 0 && $custom_context['job_description'] === '') || $material_type === '') {
                wp_send_json_error(['message' => __('A valid role and material type are required.', 'senna-finance')], 422);
            }

            $prepared = $this->prepare_crm_reddit_material_payload($jobs_post_id, $material_type, $cv_text, $custom_context);
            if (is_wp_error($prepared)) {
                wp_send_json_error(['message' => $prepared->get_error_message()], (int) ($prepared->get_error_data('status') ?: 500));
            }

            $item = $jobs_post_id > 0 ? $this->get_crm_reddit_jobs_item($jobs_post_id) : [];
            $resource_meta = [];
            if (!empty($item)) {
                $resources = $this->get_crm_reddit_application_pack_resources($item);
                if (!empty($resources)) {
                    foreach ($resources as $resource) {
                        if (sanitize_key((string) ($resource['material_type'] ?? '')) === $material_type) {
                            $resource_meta = $resource;
                            break;
                        }
                    }
                }
            }
            if (empty($resource_meta)) {
                $resource_meta = $this->get_crm_reddit_material_type_config($material_type, [
                    'company' => (string) ($custom_context['company'] ?? ''),
                ]);
            }

            $material = is_array($prepared['material'] ?? null) ? $prepared['material'] : [];
            $context = is_array($prepared['context'] ?? null) ? $prepared['context'] : [];
            $resource_payload = [
                'material_type' => $material_type,
                'label' => (string) ($resource_meta['label'] ?? ($prepared['title'] ?? __('Material', 'senna-finance'))),
                'file_type' => strtoupper((string) ($resource_meta['type'] ?? ($resource_meta['download_extension'] ?? 'DOCX'))),
                'kind' => (string) ($resource_meta['kind'] ?? (($material_type === 'interview_questions' || $material_type === 'hiring_guide') ? 'pdf' : 'word')),
                'company' => (string) ($item['company'] ?? ($context['company'] ?? '')),
                'jobs_post_id' => $jobs_post_id,
                'crm_post_id' => (int) ($item['crm_post_id'] ?? ($context['crm_post_id'] ?? 0)),
                'title' => (string) ($prepared['title'] ?? ''),
                'markup' => (string) ($prepared['markup'] ?? ''),
                'copy_text' => (string) (($material['copy_text'] ?? '') ?: ''),
                'download_url' => (string) (($material['download_url'] ?? '') ?: ''),
                'download_filename' => (string) (($material['download_filename'] ?? '') ?: ''),
                'source' => (string) (($material['generation_source'] ?? '') ?: 'unknown'),
            ];

            wp_send_json_success([
                'title' => (string) ($prepared['title'] ?? ''),
                'markup' => (string) ($prepared['markup'] ?? ''),
                'resource' => $resource_payload,
            ]);
        }

        public function ajax_reddit_material_pack_generate()
        {
            check_ajax_referer('sffc_crm_reddit_material_generate', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $cv_text = sanitize_textarea_field((string) ($_POST['cv_text'] ?? ''));
            $custom_context = [
                'role_title' => sanitize_text_field((string) ($_POST['role_title'] ?? '')),
                'company' => sanitize_text_field((string) ($_POST['company'] ?? '')),
                'job_description' => sanitize_textarea_field((string) ($_POST['jd_text'] ?? '')),
            ];
            $requested_material_types = $this->get_crm_reddit_requested_material_types($_POST['material_types'] ?? []);

            if ($jobs_post_id <= 0 && $custom_context['job_description'] === '') {
                wp_send_json_error(['message' => __('A valid role is required.', 'senna-finance')], 422);
            }

            $item = $jobs_post_id > 0 ? $this->get_crm_reddit_jobs_item($jobs_post_id) : [];
            if ($jobs_post_id > 0 && empty($item)) {
                wp_send_json_error(['message' => __('Unable to locate this role.', 'senna-finance')], 404);
            }

            $resources = !empty($item)
                ? $this->get_crm_reddit_application_pack_resources($item)
                : $this->get_crm_reddit_custom_application_pack_resources($custom_context);
            if (!empty($requested_material_types)) {
                $resources = array_values(array_filter($resources, static function ($resource) use ($requested_material_types) {
                    return in_array(sanitize_key((string) ($resource['material_type'] ?? '')), $requested_material_types, true);
                }));
            }
            if (empty($resources)) {
                wp_send_json_error(['message' => __('No application materials are configured for this role.', 'senna-finance')], 404);
            }

            $pack_payload = [];
            $generated_with_claude = false;
            $used_fallback = false;

            foreach ($resources as $resource) {
                $material_type = sanitize_key((string) ($resource['material_type'] ?? ''));
                if ($material_type === '') {
                    continue;
                }

                $prepared = $this->prepare_crm_reddit_material_payload($jobs_post_id, $material_type, $cv_text, $custom_context);
                if (is_wp_error($prepared)) {
                    wp_send_json_error([
                        'message' => $prepared->get_error_message(),
                        'material_type' => $material_type,
                    ], (int) ($prepared->get_error_data('status') ?: 500));
                }

                $pack_payload[] = [
                    'material_type' => $material_type,
                    'label' => (string) ($resource['label'] ?? ''),
                    'file_type' => strtoupper((string) ($resource['type'] ?? ($resource['download_extension'] ?? 'DOCX'))),
                    'kind' => (string) ($resource['kind'] ?? (($material_type === 'interview_questions' || $material_type === 'hiring_guide') ? 'pdf' : 'word')),
                    'company' => (string) ($item['company'] ?? ($custom_context['company'] ?? '')),
                    'jobs_post_id' => (int) ($item['post_id'] ?? 0),
                    'crm_post_id' => (int) ($item['crm_post_id'] ?? 0),
                    'title' => (string) ($prepared['title'] ?? ''),
                    'markup' => (string) ($prepared['markup'] ?? ''),
                    'copy_text' => (string) (($prepared['material']['copy_text'] ?? '') ?: ''),
                    'download_url' => (string) (($prepared['material']['download_url'] ?? '') ?: ''),
                    'download_filename' => (string) (($prepared['material']['download_filename'] ?? '') ?: ''),
                    'source' => (string) (($prepared['material']['generation_source'] ?? '') ?: 'unknown'),
                ];

                if (($prepared['material']['generation_source'] ?? '') === 'claude') {
                    $generated_with_claude = true;
                } elseif (($prepared['material']['generation_source'] ?? '') === 'fallback') {
                    $used_fallback = true;
                }
            }

            if (empty($pack_payload)) {
                wp_send_json_error(['message' => __('We could not prepare this application pack right now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'resources' => $pack_payload,
                'generated_with_claude' => $generated_with_claude,
                'used_fallback' => $used_fallback,
                'message' => !$generated_with_claude && $used_fallback
                    ? __('MENA Careers generation is unavailable right now. No tailored materials were produced.', 'senna-finance')
                    : '',
            ]);
        }

        private function prepare_crm_reddit_material_payload($jobs_post_id, $material_type, $cv_text = '', array $custom_context = [])
        {
            $context = $this->build_crm_reddit_material_context((int) $jobs_post_id, (string) $material_type, (string) $cv_text, $custom_context);
            if (empty($context)) {
                return new WP_Error('material_context_unavailable', __('Unable to build the material context for this role.', 'senna-finance'), ['status' => 404]);
            }

            $material = $this->get_or_generate_crm_reddit_material($context, (string) $material_type, (int) $jobs_post_id);
            if (empty($material)) {
                return new WP_Error('material_generation_failed', __('We could not prepare this material right now.', 'senna-finance'), ['status' => 500]);
            }

            return [
                'title' => (string) ($material['title'] ?? ''),
                'markup' => $this->render_crm_reddit_material_markup($material, $context, (string) $material_type),
                'material' => $material,
                'context' => $context,
            ];
        }

        private function get_or_generate_crm_reddit_material(array $context, $material_type, $jobs_post_id = 0)
        {
            $cache_key = 'sffc_reddit_material_v3_' . md5(wp_json_encode([
                'jobs_post_id' => (int) $jobs_post_id,
                'crm_post_id' => (int) ($context['crm_post_id'] ?? 0),
                'material_type' => (string) $material_type,
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'job_description' => (string) ($context['job_description'] ?? ''),
                'cv_hash' => md5((string) ($context['cv_text'] ?? '')),
            ]));

            $material = get_transient($cache_key);
            $material_is_valid = is_array($material) && (
                ($material_type === 'cover_letter' && !empty($material['document_text']))
                || ($material_type !== 'cover_letter' && !empty($material['sections']))
            );

            if ($material_is_valid) {
                return $material;
            }

            $material = $this->call_crm_reddit_material_claude($context, $material_type);
            if (empty($material)) {
                $material = $this->build_crm_reddit_material_fallback($context, $material_type);
                if (!empty($material)) {
                    $material['generation_source'] = 'fallback';
                }
            } else {
                $material['generation_source'] = 'claude';
            }

            if (empty($material)) {
                return null;
            }

            $download = $this->build_crm_reddit_material_download_file($material, $context, $material_type);
            if (!empty($download['url'])) {
                $material['download_url'] = (string) $download['url'];
                $material['download_filename'] = (string) ($download['filename'] ?? '');
            }

            set_transient($cache_key, $material, 45 * MINUTE_IN_SECONDS);

            return $material;
        }

        private function build_crm_reddit_material_context($jobs_post_id, $material_type, $cv_text_override = '', array $custom_context = [])
        {
            if ((int) $jobs_post_id <= 0) {
                return $this->build_crm_reddit_custom_material_context($material_type, $custom_context, $cv_text_override);
            }

            $context = $this->build_crm_reddit_networking_context((int) $jobs_post_id);
            if (empty($context)) {
                return null;
            }

            $config = $this->get_crm_reddit_material_type_config($material_type, $context);
            if (empty($config)) {
                return null;
            }

            $resume_payload = is_user_logged_in()
                ? $this->get_crm_reddit_active_resume_text(get_current_user_id())
                : ['cv_text' => '', 'has_cv' => false];
            $override_text = trim((string) $cv_text_override);
            if ($override_text !== '') {
                $resume_payload['cv_text'] = $override_text;
                $resume_payload['has_cv'] = true;
            }

            $context['material_type'] = $material_type;
            $context['material_label'] = (string) ($config['label'] ?? '');
            $context['material_headline'] = (string) ($config['headline'] ?? '');
            $context['download_extension'] = (string) ($config['download_extension'] ?? 'txt');
            $context['download_name'] = (string) ($config['download_name'] ?? 'senna-material');
            $context['loading_label'] = (string) ($config['loading_label'] ?? '');
            $context['cv_text'] = trim((string) ($resume_payload['cv_text'] ?? ''));
            $context['has_cv'] = !empty($resume_payload['has_cv']);
            $context['candidate_name'] = $this->get_crm_reddit_current_user_full_name();

            return $context;
        }

        private function build_crm_reddit_custom_material_context($material_type, array $custom_context = [], $cv_text_override = '')
        {
            $job_description = trim((string) ($custom_context['job_description'] ?? ''));
            if ($job_description === '') {
                return null;
            }

            $company = trim((string) ($custom_context['company'] ?? ''));
            $role_title = trim((string) ($custom_context['role_title'] ?? ''));
            $config = $this->get_crm_reddit_material_type_config($material_type, [
                'company' => $company,
            ]);
            if (empty($config)) {
                return null;
            }

            $resume_payload = is_user_logged_in()
                ? $this->get_crm_reddit_active_resume_text(get_current_user_id())
                : ['cv_text' => '', 'has_cv' => false];
            $override_text = trim((string) $cv_text_override);
            if ($override_text !== '') {
                $resume_payload['cv_text'] = $override_text;
                $resume_payload['has_cv'] = true;
            }

            $role_signals = $this->extract_cv_match_studio_jobs_mailbox_role_signals($job_description, [
                'title' => $role_title,
                'company' => $company,
            ]);

            return [
                'crm_post_id' => 0,
                'role_title' => $role_title,
                'company' => $company,
                'location' => '',
                'industry' => '',
                'seniority' => '',
                'recruiter_name' => '',
                'recruiter_title' => '',
                'recruiter_firm' => '',
                'posted_label' => '',
                'job_description' => $job_description,
                'keywords' => array_values(array_slice((array) ($role_signals['primary_signals'] ?? []), 0, 10)),
                'skills' => array_values(array_slice((array) ($role_signals['primary_signals'] ?? []), 0, 8)),
                'requirements' => array_values(array_slice(array_merge(
                    (array) ($role_signals['primary_signals'] ?? []),
                    (array) ($role_signals['tools'] ?? []),
                    (array) ($role_signals['credentials'] ?? [])
                ), 0, 10)),
                'application_process' => [],
                'material_type' => $material_type,
                'material_label' => (string) ($config['label'] ?? ''),
                'material_headline' => (string) ($config['headline'] ?? ''),
                'download_extension' => (string) ($config['download_extension'] ?? 'txt'),
                'download_name' => (string) ($config['download_name'] ?? 'senna-material'),
                'loading_label' => (string) ($config['loading_label'] ?? ''),
                'cv_text' => trim((string) ($resume_payload['cv_text'] ?? '')),
                'has_cv' => !empty($resume_payload['has_cv']),
                'candidate_name' => $this->get_crm_reddit_current_user_full_name(),
            ];
        }

        private function call_crm_reddit_material_claude(array $context, $material_type)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return null;
            }

            $request_body = [
                'model' => $this->get_crm_reddit_material_model(),
                'max_tokens' => 3800,
                'temperature' => 0.15,
                'system' => $this->get_crm_reddit_material_system_prompt(),
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => $this->build_crm_reddit_material_user_prompt($context, $material_type),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit Materials Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);

            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit Materials Claude Error: status ' . $status);
                return null;
            }

            return $this->parse_crm_reddit_material_json((string) $body['content'][0]['text'], $context, $material_type);
        }

        private function get_crm_reddit_material_model()
        {
            // Keep materials generation aligned with the same Claude model used by inst-terminal / gap analysis.
            return 'claude-sonnet-4-6';
        }

        private function get_crm_reddit_material_system_prompt()
        {
            return 'You are MENA Careers’s private equity application materials strategist.

You produce company-specific, role-specific application materials for a single live opportunity with the goal of helping the candidate land a private equity role, or a credible adjacent role into investing, portfolio operations, private credit, investor relations, or broader buyside pathways.

CRITICAL RULES:
1. Respond with ONLY valid JSON
2. No markdown code fences
3. No generic career-advice filler
4. Every point must tie back to the supplied role, company, location, recruiter context, industry, or job description
5. If no CV text is provided, never invent candidate experience - write adaptation-ready copy that the user can quickly personalise
6. If CV text is provided, use it carefully to shape stronger, more relevant wording
7. Keep the tone polished, editorial, concise, and commercially useful
8. Avoid obvious AI phrases such as "I would recommend" or "based on the information provided"
9. The output must feel like a tailored document draft, not a generic checklist
10. Default to a private equity hiring lens: strong documents should sound credible to recruiters, hiring managers, investment teams, portfolio operations leaders, private credit teams, investor relations teams, and adjacent buyside hiring processes
11. Prioritise private-equity-relevant signals when supported by the role or CV, including modelling, research depth, diligence, transaction exposure, market judgement, stakeholder credibility, operating leverage, and commercial ownership
12. If the role is adjacent to the target market, position the candidate toward private-equity-relevant transferability without falsely calling the role something it is not
13. Never invent transactions, returns, modelling exposure, live deals, or firm-specific motivations that are not supported by the supplied context';
        }

        private function build_crm_reddit_material_user_prompt(array $context, $material_type)
        {
            $config = $this->get_crm_reddit_material_type_config($material_type, $context);
            $job_description = (string) ($context['job_description'] ?? '');
            if (strlen($job_description) > 12000) {
                $job_description = substr($job_description, 0, 12000) . "\n[TRUNCATED]";
            }

            $cv_text = (string) ($context['cv_text'] ?? '');
            if (strlen($cv_text) > 7000) {
                $cv_text = substr($cv_text, 0, 7000) . "\n[TRUNCATED]";
            }

            $prompt_context = [
                'material_type' => $material_type,
                'material_label' => (string) ($config['label'] ?? ''),
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'location' => (string) ($context['location'] ?? ''),
                'industry' => (string) ($context['industry'] ?? ''),
                'seniority' => (string) ($context['seniority'] ?? ''),
                'recruiter_name' => (string) ($context['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($context['recruiter_title'] ?? ''),
                'recruiter_firm' => (string) ($context['recruiter_firm'] ?? ''),
                'posted_label' => (string) ($context['posted_label'] ?? ''),
                'candidate_name' => (string) ($context['candidate_name'] ?? ''),
                'keywords' => array_values(array_slice((array) ($context['keywords'] ?? []), 0, 8)),
                'skills' => array_values(array_slice((array) ($context['skills'] ?? []), 0, 8)),
                'requirements' => array_values(array_slice((array) ($context['requirements'] ?? []), 0, 8)),
                'application_process' => array_values(array_slice((array) ($context['application_process'] ?? []), 0, 6)),
                'has_cv' => !empty($context['has_cv']),
            ];

            $json_shape = '{
  "title": "specific material title",
  "eyebrow": "short label",
  "intro": "2-3 sentence opening that explains how this material fits the role and company",
  "sections": [
    {
      "heading": "section heading",
      "body": "1-3 sentence section body",
      "bullets": ["up to 5 bullets"]
    }
  ],
  "copy_text": "a clean plain-text version of the material that can be copied directly",
  "download_name": "short-slug-file-name"
}';

            if ($material_type === 'cv_template') {
                $json_shape = '{
  "title": "specific material title",
  "eyebrow": "short label",
  "intro": "1-2 sentence framing note",
  "sections": [
    {
      "heading": "Professional Summary|Selected Experience Bullet Examples|Technical Skills|Education Positioning",
      "body": "optional short setup line",
      "bullets": ["actual CV-ready lines, not advice"]
    }
  ],
  "copy_text": "a clean plain-text CV draft that can be copied directly",
  "download_name": "short-slug-file-name"
}';
            }

            if ($material_type === 'cover_letter') {
                $json_shape = '{
  "title": "specific material title",
  "eyebrow": "short label",
  "document_text": "the actual finished cover letter text, written as a real letter with greeting, body paragraphs, and close",
  "copy_text": "the same full cover letter text, ready to copy directly",
  "download_name": "short-slug-file-name"
}';
            }

            return 'Create a company-specific application material for this live role.

PRIMARY OBJECTIVE:
Help this candidate land a private equity role, or if the role is adjacent to that path, position them as credibly as possible for the next step.

ROLE POSITIONING RULES:
- use the language of private equity recruiting that best fits the brief
- emphasize the strongest evidenced signals from the CV and job brief, including modelling, research quality, diligence, transaction or market relevance, commercial judgement, and stakeholder credibility where applicable
- if the role is not a perfect fit, frame the strongest transferable signals that still make the profile more credible for private equity, private markets, or adjacent senior recruiting
- never invent experience, closed deals, portfolio responsibility, or technical depth that the CV does not support

MATERIAL BRIEF:
' . (string) ($config['prompt_brief'] ?? '') . '

ROLE CONTEXT:
' . wp_json_encode($prompt_context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '

JOB DESCRIPTION:
' . $job_description . '

' . ($cv_text !== '' ? "ACTIVE RESUME TEXT:\n" . $cv_text . "\n\n" : "ACTIVE RESUME TEXT:\n[none provided]\n\n") . '
Return ONLY this JSON structure:
' . $json_shape . '

' . ($material_type === 'cv_template'
                ? '
For this CV template:
- write actual CV-ready content, not advice about how to write a CV
- do not use headings like "Lead with" or "What to emphasise"
- the bullets must read like real achievement bullets, not coaching notes
- where the resume includes numbers, transaction values, time savings, or outcomes, use them
- if no precise metrics are available, still write outcome-led bullets without inventing false numbers
- show contribution, ownership, and business impact clearly
- wherever justified, make the bullet sound more credible for private equity recruiting than for broad generic recruiting'
                : '') . '

' . ($material_type === 'cover_letter'
                ? '
For this cover letter:
- write the actual letter, not advice about how to write it
- do not return headings like "Opening Angle" or "Proof Points"
- do not explain the strategy
- produce a polished draft that sounds credible for this exact firm and role
- if CV text is limited, stay truthful and use careful, adaptable wording rather than invented achievements
- the final letter should feel credible to a private equity recruiter, hiring manager, or investing team, not like a generic application
- if candidate_name is provided in the role context, sign off the final letter with that exact name after the close'
                : '');
        }

        private function ensure_crm_reddit_cover_letter_signoff($document_text, array $context)
        {
            $document_text = trim((string) $document_text);
            if ($document_text === '') {
                return $document_text;
            }

            $candidate_name = trim((string) ($context['candidate_name'] ?? ''));
            if ($candidate_name === '') {
                return $document_text;
            }

            if (preg_match('/\b' . preg_quote($candidate_name, '/') . '\b/i', $document_text)) {
                return $document_text;
            }

            if (preg_match('/Kind regards,?\s*$/i', $document_text)) {
                return rtrim($document_text) . "\n" . $candidate_name;
            }

            if (preg_match('/(Best regards,?|Regards,?|Sincerely,?)\s*$/i', $document_text)) {
                return rtrim($document_text) . "\n" . $candidate_name;
            }

            return rtrim($document_text) . "\n\nKind regards,\n" . $candidate_name;
        }

        private function parse_crm_reddit_material_json($content, array $context, $material_type)
        {
            if ($content === '') {
                return null;
            }

            $result = json_decode($content, true);
            if (json_last_error() !== JSON_ERROR_NONE || !is_array($result)) {
                $cleaned = preg_replace('/^```json\s*/i', '', $content);
                $cleaned = preg_replace('/^```\s*/i', '', (string) $cleaned);
                $cleaned = preg_replace('/\s*```\s*$/i', '', (string) $cleaned);
                $cleaned = trim((string) $cleaned);

                $result = json_decode($cleaned, true);
            }

            if ((json_last_error() !== JSON_ERROR_NONE || !is_array($result)) && preg_match('/\{[\s\S]+\}/s', $content, $matches)) {
                $result = json_decode((string) $matches[0], true);
            }

            if (json_last_error() !== JSON_ERROR_NONE || !is_array($result)) {
                error_log('Reddit Materials Claude Parse Error: ' . json_last_error_msg());
                return null;
            }

            $config = $this->get_crm_reddit_material_type_config($material_type, $context);
            $download_name = sanitize_title((string) ($result['download_name'] ?? ($config['download_name'] ?? 'senna-material')));
            if ($download_name === '') {
                $download_name = 'senna-material';
            }

            $sections = [];
            foreach ((array) ($result['sections'] ?? []) as $section) {
                if (!is_array($section)) {
                    continue;
                }

                $heading = trim((string) ($section['heading'] ?? ''));
                $body = trim((string) ($section['body'] ?? ''));
                $bullets = [];

                foreach ((array) ($section['bullets'] ?? []) as $bullet) {
                    $bullet = trim((string) $bullet);
                    if ($bullet !== '') {
                        $bullets[] = $bullet;
                    }
                }

                if ($heading === '' && $body === '' && empty($bullets)) {
                    continue;
                }

                $sections[] = [
                    'heading' => $heading,
                    'body' => $body,
                    'bullets' => $bullets,
                ];
            }

            $document_text = trim((string) ($result['document_text'] ?? ''));

            if ($material_type !== 'cover_letter' && empty($sections)) {
                return null;
            }

            if ($material_type === 'cover_letter' && $document_text === '') {
                return null;
            }

            if ($material_type === 'cover_letter') {
                $document_text = $this->ensure_crm_reddit_cover_letter_signoff($document_text, $context);
            }

            return [
                'title' => trim((string) ($result['title'] ?? ($config['label'] ?? ''))),
                'eyebrow' => trim((string) ($result['eyebrow'] ?? ($config['headline'] ?? ''))),
                'intro' => trim((string) ($result['intro'] ?? '')),
                'sections' => $sections,
                'document_text' => $document_text,
                'copy_text' => trim((string) ($result['copy_text'] ?? ($document_text !== '' ? $document_text : $this->build_crm_reddit_material_copy_text_from_sections($sections, $result, $context, $material_type)))),
                'download_name' => $download_name,
            ];
        }

        private function build_crm_reddit_material_fallback(array $context, $material_type)
        {
            $config = $this->get_crm_reddit_material_type_config($material_type, $context);
            if (empty($config)) {
                return null;
            }

            $role_title = (string) ($context['role_title'] ?? __('the role', 'senna-finance'));
            $company = (string) ($context['company'] ?? __('the company', 'senna-finance'));
            $location = (string) ($context['location'] ?? '');
            $skills = array_values(array_slice((array) ($context['skills'] ?? []), 0, 4));
            $requirements = array_values(array_slice((array) ($context['requirements'] ?? []), 0, 4));
            $keywords = array_values(array_slice((array) ($context['keywords'] ?? []), 0, 4));
            $signals = array_values(array_filter(array_unique(array_merge($skills, $requirements, $keywords))));
            $signal_text = !empty($signals) ? implode(', ', array_slice($signals, 0, 4)) : __('analytical judgement, role fit, and clear finance positioning', 'senna-finance');
            $location_text = $location !== '' ? sprintf(__(' for %s', 'senna-finance'), $location) : '';

            $sections = [];
            $intro = '';
            $copy_text = '';

            switch ($material_type) {
                case 'cv_template':
                    $intro = sprintf(__('This CV draft is aligned to %1$s at %2$s%3$s and is written to sound sharper, more commercial, and more outcome-led against the live brief.', 'senna-finance'), $role_title, $company, $location_text);
                    $sections = [
                        [
                            'heading' => __('Professional Summary', 'senna-finance'),
                            'body' => '',
                            'bullets' => [
                                sprintf(__('[Degree / current role] candidate targeting %1$s at %2$s, bringing analytical rigour, strong commercial judgement, and clear interest in %3$s.', 'senna-finance'), $role_title, $company, $signal_text),
                                __('Experience spanning financial analysis, investment judgement, and high-pressure execution environments, with a track record of producing work that is both accurate and decision-useful.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('Selected Experience Bullet Examples', 'senna-finance'),
                            'body' => '',
                            'bullets' => [
                                __('Built integrated financial models and diligence packs that helped senior stakeholders assess transaction upside, downside, and key execution risks across priority targets.', 'senna-finance'),
                                __('Automated recurring reporting and analysis workflows, reducing manual preparation time and improving the speed and consistency of internal decision support.', 'senna-finance'),
                                __('Synthesised market, company, and performance data into concise materials used in investment discussions, management presentations, or live deal workstreams.', 'senna-finance'),
                                __('Worked across multiple deadlines while maintaining analytical quality, clear communication, and commercially relevant output for senior team members or clients.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('Technical Skills', 'senna-finance'),
                            'body' => '',
                            'bullets' => [
                                sprintf(__('Advanced Excel and modelling capability shaped around %s.', 'senna-finance'), $signal_text),
                                __('PowerPoint / presentation drafting for investment, client, or senior stakeholder use.', 'senna-finance'),
                                __('Strong written and verbal communication in commercial settings, with the ability to distil complex analysis into clear conclusions.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('Education Positioning', 'senna-finance'),
                            'body' => '',
                            'bullets' => [
                                __('Position quantitative, finance, economics, or analytical coursework prominently if it supports the hiring brief.', 'senna-finance'),
                                __('Show academic distinction, relevant societies, or investment-related projects where available.', 'senna-finance'),
                            ],
                        ],
                    ];
                    break;

                case 'cover_letter':
                    $intro = '';
                    $document_text = "Dear Hiring Team,\n\n"
                        . sprintf(__('I am applying for the %1$s opportunity at %2$s. The role stands out because it calls for sharper commercial judgement, disciplined analysis, and a clear understanding of what strong finance work looks like in practice.', 'senna-finance'), $role_title, $company)
                        . "\n\n"
                        . sprintf(__('What draws me most to this opportunity is the chance to contribute in an environment where %1$s appear to matter in a real way. I would position my background around analytical rigour, reliable execution, and the ability to communicate clearly in situations where accuracy and judgement both matter.', 'senna-finance'), $signal_text)
                        . "\n\n"
                        . sprintf(__('I would welcome the opportunity to bring that level of preparation and intent to %1$s at %2$s. Thank you for your time and consideration, and I would value the chance to discuss my application further.', 'senna-finance'), $role_title, $company)
                        . "\n\n"
                        . __('Kind regards,', 'senna-finance');
                    $document_text = $this->ensure_crm_reddit_cover_letter_signoff($document_text, $context);
                    break;

                case 'interview_questions':
                    $intro = sprintf(__('This interview pack is focused on the themes most likely to surface for %1$s at %2$s. It is designed to help you prepare around the role signals already visible in the live brief.', 'senna-finance'), $role_title, $company);
                    $sections = [
                        [
                            'heading' => __('Likely Questions', 'senna-finance'),
                            'body' => __('Expect questions that test technical readiness, judgement, motivation, and whether your background maps cleanly to the team’s work.', 'senna-finance'),
                            'bullets' => [
                                sprintf(__('Questions tied to %s.', 'senna-finance'), $signal_text),
                                __('Questions about how you think, not only what you have done.', 'senna-finance'),
                                __('Questions that test whether you understand the role and firm properly.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('What Interviewers Are Testing', 'senna-finance'),
                            'body' => __('The strongest answers usually balance technical clarity with calm commercial judgement.', 'senna-finance'),
                            'bullets' => [
                                __('Depth over volume.', 'senna-finance'),
                                __('Structured thinking under pressure.', 'senna-finance'),
                                __('Clear evidence of role-specific preparation.', 'senna-finance'),
                            ],
