                    ];
                    break;

                case 'hiring_guide':
                default:
                    $intro = sprintf(__('This hiring guide is built around %1$s at %2$s and focuses on what the process is likely rewarding before and during application review.', 'senna-finance'), $role_title, $company);
                    $sections = [
                        [
                            'heading' => __('What This Team Is Likely Screening For', 'senna-finance'),
                            'body' => __('The brief suggests a premium on candidates who can sound credible quickly and show they understand how the role fits the business.', 'senna-finance'),
                            'bullets' => [
                                sprintf(__('Evidence of %s.', 'senna-finance'), $signal_text),
                                __('Clear fit with the level and environment.', 'senna-finance'),
                                __('Commercial awareness rather than generic interest.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('Where Candidates Usually Misfire', 'senna-finance'),
                            'body' => __('Most weak applications look underprepared, overly generic, or disconnected from the actual role signals.', 'senna-finance'),
                            'bullets' => [
                                __('Generic motivation with no firm-specific context.', 'senna-finance'),
                                __('Experience bullets that describe tasks instead of outcomes.', 'senna-finance'),
                                __('No visible link between background and the live brief.', 'senna-finance'),
                            ],
                        ],
                        [
                            'heading' => __('What to Prepare Before You Apply', 'senna-finance'),
                            'body' => __('Tighten the application around clarity, signal, and evidence before submitting anything externally.', 'senna-finance'),
                            'bullets' => [
                                __('Refine your opening CV summary.', 'senna-finance'),
                                __('Align your strongest examples with the role language.', 'senna-finance'),
                                __('Prepare a short reason this role makes sense now.', 'senna-finance'),
                            ],
                        ],
                    ];
                    break;
            }

            $copy_text = $this->build_crm_reddit_material_copy_text_from_sections($sections, [
                'title' => (string) ($config['label'] ?? ''),
                'intro' => $intro,
            ], $context, $material_type);

            return [
                'title' => (string) ($config['label'] ?? ''),
                'eyebrow' => (string) ($config['headline'] ?? ''),
                'intro' => $intro,
                'sections' => $sections,
                'document_text' => isset($document_text) ? $document_text : '',
                'copy_text' => isset($document_text) ? $document_text : $copy_text,
                'download_name' => (string) ($config['download_name'] ?? 'senna-material'),
            ];
        }

        private function build_crm_reddit_material_copy_text_from_sections(array $sections, array $result, array $context, $material_type)
        {
            $lines = [];
            $title = trim((string) ($result['title'] ?? ''));
            $intro = trim((string) ($result['intro'] ?? ''));

            if ($title !== '') {
                $lines[] = $title;
                $lines[] = str_repeat('=', min(strlen($title), 72));
                $lines[] = '';
            }

            if ($intro !== '') {
                $lines[] = $intro;
                $lines[] = '';
            }

            foreach ($sections as $section) {
                $heading = trim((string) ($section['heading'] ?? ''));
                $body = trim((string) ($section['body'] ?? ''));
                $bullets = (array) ($section['bullets'] ?? []);

                if ($heading !== '') {
                    $lines[] = $heading;
                }
                if ($body !== '') {
                    $lines[] = $body;
                }
                foreach ($bullets as $bullet) {
                    $bullet = trim((string) $bullet);
                    if ($bullet !== '') {
                        $lines[] = '- ' . $bullet;
                    }
                }
                $lines[] = '';
            }

            return trim(implode("\n", $lines));
        }

        private function build_crm_reddit_material_download_file(array $material, array $context, $material_type)
        {
            $content = trim((string) ($material['copy_text'] ?? ''));
            if ($content === '') {
                return null;
            }

            $upload_dir = wp_upload_dir();
            if (!empty($upload_dir['error']) || empty($upload_dir['path']) || empty($upload_dir['url'])) {
                return null;
            }

            if (!wp_mkdir_p($upload_dir['path'])) {
                return null;
            }

            $base_name = sanitize_file_name((string) ($material['download_name'] ?? ($context['download_name'] ?? 'senna-material')));
            if ($base_name === '') {
                $base_name = 'senna-material';
            }

            $filename = $base_name . '-' . time() . '.docx';
            $filepath = trailingslashit($upload_dir['path']) . $filename;
            $fileurl = trailingslashit($upload_dir['url']) . $filename;

            if (!$this->write_crm_reddit_docx_file($filepath, $material, $context, $material_type)) {
                return null;
            }

            wp_schedule_single_event(time() + 3600, 'sffc_delete_temp_export', [$filepath]);

            return [
                'filename' => $filename,
                'url' => $fileurl,
            ];
        }

        private function write_crm_reddit_docx_file($filepath, array $material, array $context, $material_type)
        {
            if (!class_exists('ZipArchive')) {
                return false;
            }

            $zip = new ZipArchive();
            if (true !== $zip->open($filepath, ZipArchive::CREATE | ZipArchive::OVERWRITE)) {
                return false;
            }

            $title = (string) ($material['title'] ?? ($context['material_label'] ?? 'MENA Careers Material'));
            $document_xml = $this->build_crm_reddit_docx_document_xml($material, $context, $material_type);

            $zip->addFromString('[Content_Types].xml', $this->get_crm_reddit_docx_content_types_xml());
            $zip->addEmptyDir('_rels');
            $zip->addFromString('_rels/.rels', $this->get_crm_reddit_docx_rels_xml());
            $zip->addEmptyDir('docProps');
            $zip->addFromString('docProps/core.xml', $this->get_crm_reddit_docx_core_xml($title));
            $zip->addFromString('docProps/app.xml', $this->get_crm_reddit_docx_app_xml());
            $zip->addEmptyDir('word');
            $zip->addFromString('word/document.xml', $document_xml);
            $zip->addFromString('word/styles.xml', $this->get_crm_reddit_docx_styles_xml());
            $zip->addEmptyDir('word/_rels');
            $zip->addFromString('word/_rels/document.xml.rels', $this->get_crm_reddit_docx_document_rels_xml());

            $zip->close();

            return file_exists($filepath);
        }

        private function build_crm_reddit_docx_document_xml(array $material, array $context, $material_type)
        {
            $parts = [];
            $title = (string) ($material['title'] ?? '');
            $eyebrow = (string) ($material['eyebrow'] ?? '');
            $meta = array_values(array_filter([
                (string) ($context['role_title'] ?? ''),
                (string) ($context['company'] ?? ''),
                (string) ($context['location'] ?? ''),
            ]));
            $document_text = trim((string) ($material['document_text'] ?? ''));

            if ($eyebrow !== '') {
                $parts[] = $this->build_crm_reddit_docx_paragraph($eyebrow, 'Kicker');
            }
            if ($title !== '') {
                $parts[] = $this->build_crm_reddit_docx_paragraph($title, 'Title');
            }
            if (!empty($meta)) {
                $parts[] = $this->build_crm_reddit_docx_paragraph(implode(' | ', $meta), 'Meta');
            }

            if ($material_type === 'cover_letter' && $document_text !== '') {
                foreach (preg_split("/\n\s*\n/", $document_text) as $paragraph) {
                    $paragraph = trim((string) $paragraph);
                    if ($paragraph !== '') {
                        $parts[] = $this->build_crm_reddit_docx_paragraph($paragraph, 'Body');
                    }
                }
            } else {
                $intro = trim((string) ($material['intro'] ?? ''));
                if ($intro !== '') {
                    $parts[] = $this->build_crm_reddit_docx_paragraph($intro, 'Body');
                }

                foreach ((array) ($material['sections'] ?? []) as $section) {
                    $heading = trim((string) ($section['heading'] ?? ''));
                    $body = trim((string) ($section['body'] ?? ''));
                    $bullets = (array) ($section['bullets'] ?? []);

                    if ($heading !== '') {
                        $parts[] = $this->build_crm_reddit_docx_paragraph($heading, 'Heading');
                    }
                    if ($body !== '') {
                        $parts[] = $this->build_crm_reddit_docx_paragraph($body, 'Body');
                    }
                    foreach ($bullets as $bullet) {
                        $bullet = trim((string) $bullet);
                        if ($bullet !== '') {
                            $parts[] = $this->build_crm_reddit_docx_paragraph('• ' . $bullet, 'Body');
                        }
                    }
                }
            }

            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<w:document xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:wp14="http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:w10="urn:schemas-microsoft-com:office:word" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" mc:Ignorable="w14 wp14">'
                . '<w:body>'
                . implode('', $parts)
                . '<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080" w:header="708" w:footer="708" w:gutter="0"/></w:sectPr>'
                . '</w:body></w:document>';
        }

        private function build_crm_reddit_docx_paragraph($text, $style = 'Body')
        {
            $text = $this->escape_crm_reddit_docx_text($text);
            return '<w:p><w:pPr><w:pStyle w:val="' . esc_attr($style) . '"/></w:pPr><w:r><w:t xml:space="preserve">' . $text . '</w:t></w:r></w:p>';
        }

        private function escape_crm_reddit_docx_text($text)
        {
            return htmlspecialchars((string) $text, ENT_XML1 | ENT_QUOTES, 'UTF-8');
        }

        private function get_crm_reddit_docx_content_types_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                . '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                . '<Default Extension="xml" ContentType="application/xml"/>'
                . '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
                . '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
                . '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
                . '<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>'
                . '</Types>';
        }

        private function get_crm_reddit_docx_rels_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                . '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
                . '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
                . '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>'
                . '</Relationships>';
        }

        private function get_crm_reddit_docx_document_rels_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                . '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
                . '</Relationships>';
        }

        private function get_crm_reddit_docx_core_xml($title)
        {
            $escaped_title = $this->escape_crm_reddit_docx_text($title);
            $timestamp = gmdate('Y-m-d\TH:i:s\Z');
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
                . '<dc:title>' . $escaped_title . '</dc:title>'
                . '<dc:creator>MENA Careers</dc:creator>'
                . '<cp:lastModifiedBy>MENA Careers</cp:lastModifiedBy>'
                . '<dcterms:created xsi:type="dcterms:W3CDTF">' . $timestamp . '</dcterms:created>'
                . '<dcterms:modified xsi:type="dcterms:W3CDTF">' . $timestamp . '</dcterms:modified>'
                . '</cp:coreProperties>';
        }

        private function get_crm_reddit_docx_app_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">'
                . '<Application>MENA Careers</Application>'
                . '</Properties>';
        }

        private function get_crm_reddit_docx_styles_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                . '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
                . '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="20"/><w:color w:val="17323B"/></w:rPr></w:style>'
                . '<w:style w:type="paragraph" w:styleId="Kicker"><w:name w:val="Kicker"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:b/><w:caps/><w:sz w:val="16"/><w:color w:val="6C7A86"/></w:rPr></w:style>'
                . '<w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/><w:b/><w:sz w:val="34"/><w:color w:val="0D353E"/></w:rPr></w:style>'
                . '<w:style w:type="paragraph" w:styleId="Meta"><w:name w:val="Meta"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="6C7A86"/></w:rPr></w:style>'
                . '<w:style w:type="paragraph" w:styleId="Heading"><w:name w:val="Heading"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:b/><w:sz w:val="24"/><w:color w:val="17323B"/></w:rPr></w:style>'
                . '<w:style w:type="paragraph" w:styleId="Body"><w:name w:val="Body"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="20"/><w:color w:val="17323B"/></w:rPr></w:style>'
                . '</w:styles>';
        }

        private function get_crm_reddit_material_type_config($material_type, array $item = [])
        {
            $company = trim((string) ($item['company'] ?? ''));
            $company_prefix = $company !== '' ? $company . ' ' : '';
            $slug_company = sanitize_title($company);

            $configs = [
                'cv_template' => [
                    'label' => $company_prefix . __('CV Template', 'senna-finance'),
                    'headline' => __('Role-specific CV draft', 'senna-finance'),
                    'loading_label' => __('CV template', 'senna-finance'),
                    'prompt_brief' => 'Create a sharp CV template for this exact role and company. Focus on positioning, role fit, achievement framing, and which keywords or proof points deserve emphasis.',
                    'download_extension' => 'docx',
                    'download_name' => trim(($slug_company !== '' ? $slug_company . '-' : '') . 'cv-template'),
                ],
                'cover_letter' => [
                    'label' => $company_prefix . __('Cover Letter', 'senna-finance'),
                    'headline' => __('Company-specific cover letter', 'senna-finance'),
                    'loading_label' => __('cover letter template', 'senna-finance'),
                    'prompt_brief' => 'Create a cover letter draft specifically for this role and company. It should sound informed, commercially aware, and clearly tied to the live brief instead of generic motivation.',
                    'download_extension' => 'docx',
                    'download_name' => trim(($slug_company !== '' ? $slug_company . '-' : '') . 'cover-letter'),
                ],
                'interview_questions' => [
                    'label' => $company_prefix . __('Interview Questions', 'senna-finance'),
                    'headline' => __('Likely interview themes', 'senna-finance'),
                    'loading_label' => __('interview questions template', 'senna-finance'),
                    'prompt_brief' => 'Create an interview-prep sheet for this exact role. Include likely questions, what interviewers are really testing, and the answer angles the candidate should prepare.',
                    'download_extension' => 'docx',
                    'download_name' => trim(($slug_company !== '' ? $slug_company . '-' : '') . 'interview-questions'),
                ],
                'hiring_guide' => [
                    'label' => $company_prefix . __('Hiring Guide', 'senna-finance'),
                    'headline' => __('What to expect from this process', 'senna-finance'),
                    'loading_label' => __('hiring guide template', 'senna-finance'),
                    'prompt_brief' => 'Create a hiring guide for this role and company. Explain what the team is likely screening for, where candidates usually miss, and how to prepare more intelligently before applying or interviewing.',
                    'download_extension' => 'docx',
                    'download_name' => trim(($slug_company !== '' ? $slug_company . '-' : '') . 'hiring-guide'),
                ],
            ];

            return $configs[$material_type] ?? [];
        }

        private function render_crm_reddit_material_markup(array $material, array $context, $material_type)
        {
            $config = $this->get_crm_reddit_material_type_config($material_type, $context);
            $copy_text = (string) ($material['copy_text'] ?? '');
            $download_name = sanitize_file_name((string) ($material['download_name'] ?? ($config['download_name'] ?? 'senna-material')));
            $download_extension = sanitize_key((string) ($context['download_extension'] ?? ($config['download_extension'] ?? 'txt')));
            $role_title = trim((string) ($context['role_title'] ?? ''));
            $company = trim((string) ($context['company'] ?? ''));
            $document_text = trim((string) ($material['document_text'] ?? ''));

            ob_start();
        ?>
            <article
                class="sffc-crm-reddit-material-article"
                data-material-article
                data-download-name="<?php echo esc_attr($download_name !== '' ? $download_name : 'senna-material'); ?>"
                data-download-extension="<?php echo esc_attr($download_extension !== '' ? $download_extension : 'txt'); ?>"
                data-download-url="<?php echo esc_url((string) ($material['download_url'] ?? '')); ?>">
                <div class="sffc-crm-reddit-material-head">
                    <div class="sffc-crm-reddit-material-head-copy">
                        <p class="sffc-crm-reddit-material-head-kicker"><?php echo esc_html((string) ($material['eyebrow'] ?? '')); ?></p>
                        <h2><?php echo esc_html((string) ($material['title'] ?? ($config['label'] ?? ''))); ?></h2>
                        <div class="sffc-crm-reddit-material-head-meta">
                            <?php if ($role_title !== '') : ?>
                                <span><?php echo esc_html($role_title); ?></span>
                            <?php endif; ?>
                            <?php if ($company !== '') : ?>
                                <span><?php echo esc_html($company); ?></span>
                            <?php endif; ?>
                        </div>
                    </div>
                    <div class="sffc-crm-reddit-material-actions">
                        <button type="button" class="sffc-crm-reddit-material-action" data-material-copy>
                            <?php esc_html_e('Copy', 'senna-finance'); ?>
                        </button>
                        <button type="button" class="sffc-crm-reddit-material-action is-primary" data-material-download>
                            <?php esc_html_e('Download', 'senna-finance'); ?>
                        </button>
                    </div>
                </div>

                <?php if ($material_type === 'cover_letter' && $document_text !== '') : ?>
                    <div class="sffc-crm-reddit-material-letter">
                        <?php foreach (preg_split("/\n\s*\n/", $document_text) as $paragraph) : ?>
                            <?php $paragraph = trim((string) $paragraph); ?>
                            <?php if ($paragraph !== '') : ?>
                                <p><?php echo nl2br(esc_html($paragraph)); ?></p>
                            <?php endif; ?>
                        <?php endforeach; ?>
                    </div>
                <?php elseif (!empty($material['intro'])) : ?>
                    <section class="sffc-crm-reddit-material-intro">
                        <p><?php echo esc_html((string) $material['intro']); ?></p>
                    </section>
                <?php endif; ?>

                <?php if ($material_type !== 'cover_letter') : ?>
                    <div class="sffc-crm-reddit-material-sections">
                        <?php foreach ((array) ($material['sections'] ?? []) as $section) : ?>
                            <section class="sffc-crm-reddit-material-section">
                                <?php if (!empty($section['heading'])) : ?>
                                    <h3><?php echo esc_html((string) $section['heading']); ?></h3>
                                <?php endif; ?>
                                <?php if (!empty($section['body'])) : ?>
                                    <p><?php echo esc_html((string) $section['body']); ?></p>
                                <?php endif; ?>
                                <?php if (!empty($section['bullets']) && is_array($section['bullets'])) : ?>
                                    <ul>
                                        <?php foreach ($section['bullets'] as $bullet) : ?>
                                            <?php if (trim((string) $bullet) !== '') : ?>
                                                <li><?php echo esc_html((string) $bullet); ?></li>
                                            <?php endif; ?>
                                        <?php endforeach; ?>
                                    </ul>
                                <?php endif; ?>
                            </section>
                        <?php endforeach; ?>
                    </div>
                <?php endif; ?>

                <textarea class="sffc-crm-reddit-material-copy-source" data-material-copy-source hidden><?php echo esc_textarea($copy_text); ?></textarea>
            </article>
        <?php
            return ob_get_clean();
        }

        private function build_crm_reddit_networking_context($jobs_post_id)
        {
            $item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            if (empty($item)) {
                return null;
            }

            $jobs_post = get_post($jobs_post_id);
            if (!$jobs_post instanceof WP_Post || $jobs_post->post_type !== 'jobs') {
                return null;
            }

            $crm_post = null;
            $keywords = [];
            if (!empty($item['crm_post_id'])) {
                $post_model = new SFFC_CRM_Post();
                $crm_post = $post_model->get_full_detail((int) $item['crm_post_id'], get_current_user_id());
                $keywords = $post_model->get_keywords((int) $item['crm_post_id']);
            }

            $job_description = '';
            if (!empty($crm_post)) {
                if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                }

                if (function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    $job_description = (string) sffc_build_crm_jd_text_for_analysis($crm_post);
                }
            }

            if ($job_description === '') {
                $job_description = $this->build_reddit_jobs_jd_text($jobs_post, $item);
            }

            $industry = '';
            if (!empty($crm_post['sector'])) {
                $industry = sanitize_text_field((string) $crm_post['sector']);
            } elseif (!empty($crm_post['recruiter_specializations'])) {
                $industry = sanitize_text_field((string) $crm_post['recruiter_specializations']);
            }

            $team_contacts = [];
            foreach ((array) ($crm_post['team_contacts'] ?? []) as $contact) {
                if (is_array($contact)) {
                    $label = trim(implode(' - ', array_filter([
                        sanitize_text_field((string) ($contact['name'] ?? '')),
                        sanitize_text_field((string) ($contact['title'] ?? '')),
                    ])));
                    if ($label !== '') {
                        $team_contacts[] = $label;
                    }
                } else {
                    $label = sanitize_text_field((string) $contact);
                    if ($label !== '') {
                        $team_contacts[] = $label;
                    }
                }
            }

            $application_process = [];
            foreach ((array) ($crm_post['application_process'] ?? []) as $step) {
                if (is_array($step)) {
                    $label = trim(implode(': ', array_filter([
                        sanitize_text_field((string) ($step['stage'] ?? '')),
                        sanitize_text_field((string) ($step['description'] ?? '')),
                    ])));
                    if ($label !== '') {
                        $application_process[] = $label;
                    }
                } else {
                    $label = sanitize_text_field((string) $step);
                    if ($label !== '') {
                        $application_process[] = $label;
                    }
                }
            }

            $normalized_keywords = [];
            foreach ((array) $keywords as $keyword) {
                if (is_array($keyword)) {
                    $value = trim((string) ($keyword['keyword'] ?? $keyword['name'] ?? $keyword['value'] ?? ''));
                } else {
                    $value = trim((string) $keyword);
                }

                if ($value !== '') {
                    $normalized_keywords[] = sanitize_text_field($value);
                }
            }

            $skills = [];
            foreach ((array) ($crm_post['skills_mentioned'] ?? []) as $skill) {
                if (is_array($skill)) {
                    $value = trim((string) ($skill['skill'] ?? $skill['name'] ?? $skill['label'] ?? ''));
                } else {
                    $value = trim((string) $skill);
                }
                if ($value !== '') {
                    $skills[] = sanitize_text_field($value);
                }
            }

            $requirements = [];
            foreach ((array) ($crm_post['requirements'] ?? []) as $requirement) {
                if (is_array($requirement)) {
                    $value = trim((string) ($requirement['label'] ?? $requirement['text'] ?? $requirement['requirement'] ?? ''));
                } else {
                    $value = trim((string) $requirement);
                }
                if ($value !== '') {
                    $requirements[] = sanitize_text_field($value);
                }
            }

            return [
                'jobs_post_id' => $jobs_post_id,
                'crm_post_id' => (int) ($item['crm_post_id'] ?? 0),
                'role_title' => sanitize_text_field((string) ($item['role_title'] ?? '')),
                'company' => sanitize_text_field((string) ($item['company'] ?? '')),
                'location' => sanitize_text_field((string) ($item['location'] ?? '')),
                'industry' => $industry,
                'seniority' => sanitize_text_field((string) ($crm_post['seniority'] ?? ($item['seniority'] ?? ''))),
                'experience_years' => sanitize_text_field((string) ($crm_post['experience_years'] ?? '')),
                'posted_label' => sanitize_text_field((string) ($item['posted_label'] ?? '')),
                'apply_url' => esc_url_raw((string) ($item['apply_url'] ?? '')),
                'view_url' => esc_url_raw((string) ($item['view_url'] ?? '')),
                'recruiter_name' => sanitize_text_field((string) ($crm_post['recruiter_name'] ?? ($item['recruiter_name'] ?? ''))),
                'recruiter_title' => sanitize_text_field((string) ($crm_post['recruiter_title'] ?? ($item['recruiter_title'] ?? ''))),
                'recruiter_firm' => sanitize_text_field((string) ($crm_post['recruiter_firm'] ?? ($item['recruiter_firm'] ?? ''))),
                'recruiter_email' => sanitize_email((string) ($crm_post['recruiter_email'] ?? ($item['recruiter_email'] ?? ''))),
                'recruiter_linkedin' => esc_url_raw((string) ($crm_post['recruiter_linkedin'] ?? ($item['recruiter_linkedin'] ?? ''))),
                'recruiter_specializations' => sanitize_text_field((string) ($crm_post['recruiter_specializations'] ?? '')),
                'team_contacts' => array_values(array_unique($team_contacts)),
                'application_process' => array_values(array_unique($application_process)),
                'keywords' => array_values(array_unique($normalized_keywords)),
                'skills' => array_values(array_unique($skills)),
                'requirements' => array_values(array_unique($requirements)),
                'job_description' => trim((string) $job_description),
            ];
        }

        private function call_crm_reddit_networking_claude(array $context, $user_context = '')
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 4000,
                'temperature' => 0.1,
                'system' => $this->get_crm_reddit_networking_system_prompt(),
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => $this->build_crm_reddit_networking_user_prompt($context, $user_context),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit Networking Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);

            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit Networking Claude Error: status ' . $status);
                return null;
            }

            return $this->parse_crm_reddit_networking_json((string) $body['content'][0]['text']);
        }

        private function get_crm_reddit_claude_api_key()
        {
            $api_key = get_option('sffc_api_key', '');

            if ($api_key === '') {
                $api_key = get_option('sffc_anthropic_key', '');
            }

            if ($api_key === '') {
                $api_key = get_option('sffc_claude_api_key', '');
            }

            if ($api_key === '' && defined('ANTHROPIC_API_KEY')) {
                $api_key = ANTHROPIC_API_KEY;
            }

            if ($api_key === '' && class_exists('SFFC_API_Key_Manager')) {
                $key_manager = SFFC_API_Key_Manager::get_instance();
                $api_key = $key_manager->get_api_key();
            }

            if ($api_key === '' && class_exists('SFFC_Claude_API_Manager')) {
                $manager = SFFC_Claude_API_Manager::get_instance();
                if (method_exists($manager, 'get_api_key')) {
                    $api_key = (string) $manager->get_api_key();
                }
            }

            return is_string($api_key) ? trim($api_key) : '';
        }

        private function get_crm_reddit_networking_system_prompt()
        {
            return 'You are MENA Careers’s recruiter networking strategist for competitive private equity roles. Your job is to build specific, role-aware networking guidance based on the job description, company, industry, location, recruiter context, and application timing.

CRITICAL INSTRUCTIONS:
1. You MUST respond with ONLY valid JSON - no markdown, no code blocks, no text before or after
2. Start your response with { and end with }
3. Every recommendation must tie back to the supplied role context
4. Do NOT give generic advice such as "be authentic" or "network more"
5. If recruiter data is limited, say that clearly and shift toward team/company outreach logic
6. Keep lists concise and practical
7. Do not invent credentials, contacts, or referral access that were not provided
8. Outreach is often ignored when it lacks context, so every contact recommendation must include what signal to lead with
9. Meeting or call templates must be specific to the role, contact type, and timing instead of sounding generic
10. The template outputs must feel distinct and useful:
   - "most_likely_to_respond_template" should be the strongest first-touch message for the person most likely to reply
   - "linkedin_networking_inmail_strategy" should include a short strategy note plus a ready-to-use LinkedIn/InMail message
   - "quick_networking_call_strategy" should explain when to ask for a short call and include the exact wording
   - "email_referral_templates" should include both an email version and a referral-ask version';
        }

        private function build_crm_reddit_networking_user_prompt(array $context, $user_context = '')
        {
            $job_description = (string) ($context['job_description'] ?? '');
            if (strlen($job_description) > 12000) {
                $job_description = substr($job_description, 0, 12000) . "\n[TRUNCATED]";
            }

            $prompt_context = [
                'role_title' => (string) ($context['role_title'] ?? ''),
                'company' => (string) ($context['company'] ?? ''),
                'location' => (string) ($context['location'] ?? ''),
                'industry' => (string) ($context['industry'] ?? ''),
                'seniority' => (string) ($context['seniority'] ?? ''),
                'experience_years' => (string) ($context['experience_years'] ?? ''),
                'posted_label' => (string) ($context['posted_label'] ?? ''),
                'recruiter_name' => (string) ($context['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($context['recruiter_title'] ?? ''),
                'recruiter_firm' => (string) ($context['recruiter_firm'] ?? ''),
                'recruiter_specializations' => (string) ($context['recruiter_specializations'] ?? ''),
                'keywords' => array_values(array_slice((array) ($context['keywords'] ?? []), 0, 8)),
                'skills' => array_values(array_slice((array) ($context['skills'] ?? []), 0, 8)),
                'requirements' => array_values(array_slice((array) ($context['requirements'] ?? []), 0, 8)),
                'application_process' => array_values(array_slice((array) ($context['application_process'] ?? []), 0, 6)),
                'team_contacts' => array_values(array_slice((array) ($context['team_contacts'] ?? []), 0, 6)),
                'user_context' => $user_context,
            ];

            return 'Build a networking strategy for this role. The output must be specific to the role, company, industry, location, recruiter context, and timing.

The final output should feel like a sharp recruiter playbook, not a generic networking guide. The templates must be clearly differentiated so the user gets:
- a "Most Likely to Respond" first-touch template
- a "LinkedIn Networking InMail + Strategy" asset
- a "Quick Networking Call Strategy" asset
- an "Email + Referral Templates" asset

ROLE CONTEXT:
' . wp_json_encode($prompt_context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . '

JOB DESCRIPTION:
' . $job_description . '

Return ONLY this JSON structure:
{
  "hero": {
    "headline": "1 sentence on the smartest networking angle",
    "summary": "2-3 sentences explaining why this route fits this exact role",
    "job_signal": "specific signal pulled from the role, company, location, or recruiter context",
    "timing_signal": "specific note on timing or urgency"
  },
  "recruiter_strategy": {
    "best_angle": "how to approach this recruiter or hiring contact",
    "why_it_works": "why that angle fits this role",
    "best_channel": "LinkedIn DM|Email|Warm intro|Application then outreach",
    "lead_with": ["3-5 concrete proof points or signals to lead with"],
    "avoid": ["3-5 things to avoid saying or doing"]
  },
  "referral_strategy": {
    "best_path": "the strongest referral route here",
    "when_to_ask": "when the user should ask for a referral",
    "proof_points": ["3-5 points the user should establish before asking"],
    "avoid": ["2-4 referral mistakes to avoid"]
  },
  "who_to_network_with": {
    "primary_targets": [
      {"name": "person or contact type", "role": "role", "why": "why this person matters first"}
    ],
    "secondary_targets": [
      {"name": "person or contact type", "role": "role", "why": "why this is useful later"}
    ],
    "contact_order": "1-2 sentences on the ideal sequence"
  },
  "outreach_sequence": [
    {"step": "Step title", "timing": "when", "action": "what to do", "goal": "why it matters"}
  ],
  "message_drafts": {
    "most_likely_to_respond_template": "a ready-to-send first-touch template for the contact most likely to respond first",
    "linkedin_networking_inmail_strategy": "a short strategy note plus a ready-to-use LinkedIn networking InMail",
    "email_referral_templates": "email wording plus referral wording packaged together"
  },
  "contact_playbook": {
    "best_first_move": "1-2 sentence recommendation on the smartest initial outreach move",
    "context_to_use": ["3-5 specific role/company/recruiter signals the user can reference"],
    "bad_outreach_risks": ["3-5 reasons people get ignored for this role if they reach out badly"],
    "follow_up_logic": "1-2 sentences on when and how to follow up",
    "contact_cards": [
      {
        "name": "person or contact type",
        "role": "role",
        "why_this_person": "why they matter in the outreach sequence",
        "best_channel": "LinkedIn DM|LinkedIn InMail|Email|Warm intro",
        "best_ask": "Insight request|Coffee meeting|Zoom call|5 min telephone call|In-person catch up|Soft referral ask",
        "lead_with": "what to reference first for context",
        "avoid": "what to avoid in the first outreach",
        "best_timing": "when this is best used"
      }
    ]
  },
  "conversation_templates": {
    "quick_networking_call_strategy": "quick networking call strategy with a short role-aware ask and example wording"
  }
}';
        }

        private function parse_crm_reddit_networking_json($content)
        {
            if ($content === '') {
                return null;
            }

            $result = json_decode($content, true);
            if (json_last_error() === JSON_ERROR_NONE && is_array($result)) {
                return $result;
            }

            $cleaned = preg_replace('/^```json\s*/i', '', $content);
            $cleaned = preg_replace('/^```\s*/i', '', (string) $cleaned);
            $cleaned = preg_replace('/\s*```\s*$/i', '', (string) $cleaned);
            $cleaned = trim((string) $cleaned);

            $result = json_decode($cleaned, true);
            if (json_last_error() === JSON_ERROR_NONE && is_array($result)) {
                return $result;
            }

            if (preg_match('/\{[\s\S]+\}/s', $content, $matches)) {
                $result = json_decode((string) $matches[0], true);
                if (json_last_error() === JSON_ERROR_NONE && is_array($result)) {
                    return $result;
                }
            }

            $fixed = $this->fix_crm_reddit_networking_json($content);
            if ($fixed !== null) {
                $result = json_decode($fixed, true);
                if (json_last_error() === JSON_ERROR_NONE && is_array($result)) {
                    return $result;
                }
            }

            error_log('Reddit Networking Claude Parse Error: ' . json_last_error_msg());
            return null;
        }

        private function fix_crm_reddit_networking_json($content)
        {
            $start = strpos($content, '{');
            $end = strrpos($content, '}');

            if ($start === false || $end === false || $end <= $start) {
                return null;
            }

            $json = substr($content, $start, $end - $start + 1);
            $json = preg_replace("/[\x00-\x1F\x7F]/u", ' ', (string) $json);
            $json = preg_replace('/,\s*([}\]])/', '$1', (string) $json);

            return is_string($json) ? trim($json) : null;
        }

        private function build_crm_reddit_networking_fallback(array $context, $user_context = '')
        {
            $role_title = (string) ($context['role_title'] ?? __('the role', 'senna-finance'));
            $company = (string) ($context['company'] ?? __('the firm', 'senna-finance'));
            $location = (string) ($context['location'] ?? __('the market', 'senna-finance'));
            $industry = (string) ($context['industry'] ?? __('finance', 'senna-finance'));
            $recruiter_name = (string) ($context['recruiter_name'] ?? '');
            $recruiter_title = (string) ($context['recruiter_title'] ?? __('recruiter', 'senna-finance'));
            $best_channel = !empty($context['recruiter_linkedin'])
                ? 'LinkedIn DM'
                : (!empty($context['recruiter_email']) ? 'Email' : 'Application then outreach');
            $keyword_signal = !empty($context['keywords'][0]) ? (string) $context['keywords'][0] : $industry;
            $second_signal = !empty($context['skills'][0]) ? (string) $context['skills'][0] : (string) ($context['seniority'] ?? __('relevant experience', 'senna-finance'));
            $timing_signal = !empty($context['posted_label'])
                ? sprintf(__('The role was posted %s, so fast follow-up matters.', 'senna-finance'), (string) $context['posted_label'])
                : __('Treat the role as live and move quickly after applying.', 'senna-finance');
            $user_context_sentence = $user_context !== ''
                ? sprintf(__('Use the extra context you shared (%s) to sharpen the proof points you lead with.', 'senna-finance'), $user_context)
                : __('Lead with the most relevant proof of fit before asking for more of the recruiter’s time.', 'senna-finance');
            $candidate_first_name = $this->get_crm_reddit_current_user_first_name();
            if ($candidate_first_name === '') {
                $candidate_first_name = __('Candidate', 'senna-finance');
            }

            return [
                'hero' => [
                    'headline' => sprintf(__('Lead with role fit, not a cold request, for %s at %s.', 'senna-finance'), $role_title, $company),
                    'summary' => sprintf(__('This role sits in %s and is tied to %s, so the strongest outreach is short, specific, and anchored to one or two signals from the brief rather than a broad networking ask. %s', 'senna-finance'), $industry, $keyword_signal, $user_context_sentence),
                    'job_signal' => sprintf(__('The brief appears to prioritise %s and %s, so your first message should sound informed rather than exploratory.', 'senna-finance'), $keyword_signal, $second_signal),
                    'timing_signal' => $timing_signal,
                ],
                'recruiter_strategy' => [
                    'best_angle' => $recruiter_name !== ''
                        ? sprintf(__('Approach %s as the route into the process, not as someone you need to impress with a long story.', 'senna-finance'), $recruiter_name)
                        : __('Treat the recruiter touchpoint as a way to signal fit and timing, then move quickly into a role-specific conversation.', 'senna-finance'),
                    'why_it_works' => sprintf(__('For a %s role in %s, recruiters usually respond better to concise evidence of fit, location alignment, and timing than to generic enthusiasm.', 'senna-finance'), $role_title, $location),
                    'best_channel' => $best_channel,
                    'lead_with' => [
                        sprintf(__('One direct line on your fit for %s.', 'senna-finance'), $role_title),
                        sprintf(__('Evidence that you already understand the %s angle of the mandate.', 'senna-finance'), $industry),
                        sprintf(__('A short proof point linked to %s.', 'senna-finance'), $keyword_signal),
                        sprintf(__('A reason your background fits %s or the wider %s market.', 'senna-finance'), $location, $location),
                    ],
                    'avoid' => [
                        __('Do not open by asking for a referral in the first line.', 'senna-finance'),
                        __('Do not send a generic “would love to connect” note with no role context.', 'senna-finance'),
                        __('Do not describe your whole CV when one sharp proof point will do.', 'senna-finance'),
                    ],
