        private function build_crm_reddit_networking_preview(array $context, $user_context = '')
        {
            $role_title = (string) ($context['role_title'] ?? __('the role', 'senna-finance'));
            $company = (string) ($context['company'] ?? __('the firm', 'senna-finance'));
            $location = (string) ($context['location'] ?? __('the market', 'senna-finance'));
            $industry = (string) ($context['industry'] ?? __('finance', 'senna-finance'));
            $seniority = strtolower(trim((string) ($context['seniority'] ?? '')));
            $posted_label = (string) ($context['posted_label'] ?? '');
            $recruiter_name = (string) ($context['recruiter_name'] ?? '');
            $recruiter_title = (string) ($context['recruiter_title'] ?? __('Recruiter', 'senna-finance'));
            $team_contacts = array_values(array_filter((array) ($context['team_contacts'] ?? [])));
            $application_process = array_values(array_filter((array) ($context['application_process'] ?? [])));
            $signals = $this->get_crm_reddit_networking_preview_signals($context);
            $primary_signal = $signals[0] ?? $industry;
            $secondary_signal = $signals[1] ?? ($signals[0] ?? __('relevant experience', 'senna-finance'));
            $third_signal = $signals[2] ?? $location;
            $best_channel = $this->get_crm_reddit_networking_preview_channel($context);
            $timing_bucket = $this->get_crm_reddit_networking_preview_timing_bucket($posted_label);
            $variant = $this->get_crm_reddit_networking_preview_variant($context);
            $is_early_career = strpos($seniority, 'intern') !== false || strpos($seniority, 'analyst') !== false || strpos($seniority, 'graduate') !== false;
            $has_team_route = !empty($team_contacts);
            $candidate_first_name = $this->get_crm_reddit_current_user_first_name();
            if ($candidate_first_name === '') {
                $candidate_first_name = __('Candidate', 'senna-finance');
            }
            $user_context_sentence = $user_context !== ''
                ? sprintf(__('Use the extra context you added (%s) as supporting proof, not as the opening line.', 'senna-finance'), $user_context)
                : __('Lead with one sharp proof point rather than a long background summary.', 'senna-finance');

            $headline_options = [
                sprintf(__('For %1$s at %2$s, the best first move is to lead with %3$s before you ask for access.', 'senna-finance'), $role_title, $company, $primary_signal),
                sprintf(__('The sharper route into %1$s at %2$s is to prove %3$s, then ask a focused question.', 'senna-finance'), $role_title, $company, $primary_signal),
                sprintf(__('A stronger opening for %1$s is to show you already understand %2$s, not just that you want the role.', 'senna-finance'), $role_title, $primary_signal),
                sprintf(__('This %1$s role rewards context-first outreach: show %2$s, then move toward conversation.', 'senna-finance'), $role_title, $primary_signal),
            ];

            $summary_options = [
                sprintf(__('This role sits in %1$s and appears to care about %2$s and %3$s. That means the best networking move is not a generic request for time, but a short note that sounds like you already understand the brief, the team shape, and the hiring signal in %4$s. %5$s', 'senna-finance'), $industry, $primary_signal, $secondary_signal, $location, $user_context_sentence),
                sprintf(__('MENA Careers would not open this with a broad “would love to connect” note. For %1$s at %2$s, a better path is to anchor your outreach to %3$s, connect it to %4$s, and make the first ask small enough to earn a reply. %5$s', 'senna-finance'), $role_title, $company, $primary_signal, $secondary_signal, $user_context_sentence),
                sprintf(__('The live brief points toward %1$s rather than generic enthusiasm. In practice that means your outreach should sound like someone already tracking %2$s in %3$s, not someone asking strangers to explain the whole process. %4$s', 'senna-finance'), $primary_signal, $company, $location, $user_context_sentence),
                sprintf(__('The networking angle here is narrower and more tactical than most job seekers assume. For %1$s, your message needs to carry proof around %2$s, timing discipline, and a credible reason to be speaking to this team in %3$s right now. %4$s', 'senna-finance'), $role_title, $primary_signal, $location, $user_context_sentence),
            ];

            $job_signal_options = [
                sprintf(__('The brief leans toward %1$s and %2$s, so outreach should reference those signals before anything personal.', 'senna-finance'), $primary_signal, $secondary_signal),
                sprintf(__('What stands out most is the combination of %1$s with %2$s. That is a better opening signal than generic interest in %3$s.', 'senna-finance'), $primary_signal, $secondary_signal, $industry),
                sprintf(__('The role appears to reward candidates who can speak to %1$s in a %2$s context.', 'senna-finance'), $primary_signal, $location),
                sprintf(__('A smarter first note would sound informed about %1$s and %2$s rather than broad ambitions.', 'senna-finance'), $primary_signal, $secondary_signal),
            ];

            $timing_signal_options = [
                'fresh' => [
                    sprintf(__('Because the role appears newly live (%s), speed matters. A concise, role-aware message is better than a polished but delayed one.', 'senna-finance'), $posted_label !== '' ? $posted_label : __('recently posted', 'senna-finance')),
                    __('This looks like a fresh opportunity, so a fast, context-rich first touch is more valuable than waiting to craft a perfect note.', 'senna-finance'),
                ],
                'active' => [
                    sprintf(__('The role is still active (%s), so the best move is to reach out while the mandate feels current and the recruiter can still place your name quickly.', 'senna-finance'), $posted_label !== '' ? $posted_label : __('currently live', 'senna-finance')),
                    __('The timing window is still open, which makes a short role-specific message more useful than a long networking build-up.', 'senna-finance'),
                ],
                'mature' => [
                    sprintf(__('The posting timing (%s) suggests you need more context in the first note to avoid sounding late or generic.', 'senna-finance'), $posted_label !== '' ? $posted_label : __('live for a while', 'senna-finance')),
                    __('This does not look like a brand-new posting, so the first message should carry more context and a clearer reason to respond now.', 'senna-finance'),
                ],
            ];

            $best_angle_options = [
                sprintf(__('Open on %1$s, then make a small ask around %2$s rather than asking immediately for a meeting or referral.', 'senna-finance'), $primary_signal, $secondary_signal),
                sprintf(__('Treat the first note as a calibration message: prove %1$s, show awareness of %2$s, and only then ask for a short steer.', 'senna-finance'), $primary_signal, $location),
                sprintf(__('Use %1$s as the anchor and frame your message around why this specific %2$s role at %3$s is the right fit.', 'senna-finance'), $primary_signal, $role_title, $company),
                sprintf(__('Lead with one crisp fit point tied to %1$s. The best outcome of the first touch is not a long conversation, but a credible reply.', 'senna-finance'), $primary_signal),
            ];

            $why_it_works_options = [
                sprintf(__('For a %1$s role in %2$s, the recruiter is more likely to respond to clear signals of fit than to broad networking intent.', 'senna-finance'), $role_title, $location),
                sprintf(__('This works because %1$s is easier to validate quickly than a long story about motivation, especially when the brief already signals %2$s.', 'senna-finance'), $primary_signal, $secondary_signal),
                sprintf(__('A short, informed opening reduces the risk of being grouped with low-context outreach, which is common for %1$s roles.', 'senna-finance'), $role_title),
                sprintf(__('The first message needs to sound like it belongs in the process already. Referencing %1$s helps do that quickly.', 'senna-finance'), $primary_signal),
            ];

            $lead_with = [
                sprintf(__('A direct proof point showing exposure to %s.', 'senna-finance'), $primary_signal),
                sprintf(__('One credible sentence linking your background to %s.', 'senna-finance'), $secondary_signal),
                sprintf(__('A role-specific reason %s at %s is relevant for you now.', 'senna-finance'), $role_title, $company),
                sprintf(__('If true, a location or language signal that supports working in %s.', 'senna-finance'), $location),
            ];

            $avoid = [
                __('Do not ask for a referral in the first line.', 'senna-finance'),
                __('Do not send a generic “would love to connect” request with no role context.', 'senna-finance'),
                __('Do not paste your whole background when one strong proof point will do.', 'senna-finance'),
                __('Do not make the first ask bigger than the context you have earned.', 'senna-finance'),
            ];

            $best_path_options = $has_team_route ? [
                __('Start with the recruiter route for timing and process clarity, then move toward the most relevant team-side contact once you can sound informed.', 'senna-finance'),
                __('Use the recruiter touchpoint to get into the process, then use a team-side contact to sharpen context rather than to force a referral.', 'senna-finance'),
                __('The strongest path is a two-step route: signal fit through the recruiter, then deepen credibility with the most relevant team-side voice.', 'senna-finance'),
            ] : [
                __('Without a clear team-side route, earn a short exchange first and only then ask whether there is someone closer to the mandate you should learn from.', 'senna-finance'),
                __('Treat the recruiter route as primary until you have enough context to justify being redirected closer to the team.', 'senna-finance'),
                __('The cleanest route here is to sound process-aware first, then ask whether there is a better person to speak with about the mandate.', 'senna-finance'),
            ];

            $when_to_ask_options = $is_early_career ? [
                __('Ask only after you have shown role-specific interest and earned at least one useful exchange; junior private equity candidates are penalized quickly for asking too early.', 'senna-finance'),
                __('Do not ask in the first interaction. Ask after you have demonstrated fit and have something concrete to be referred for.', 'senna-finance'),
            ] : [
                __('Ask once your fit is clear, your application state is ready, and the person you are messaging has enough context to attach your name to the role.', 'senna-finance'),
                __('Ask after you have created some context and can point to a specific reason you would be credible in process, not before.', 'senna-finance'),
            ];

            $proof_points = [
                sprintf(__('You can explain why %s is the right next step for you.', 'senna-finance'), $role_title),
                sprintf(__('You can point to a specific fit signal around %s.', 'senna-finance'), $primary_signal),
                __('Your application timing feels real rather than speculative.', 'senna-finance'),
                __('Your ask is small enough to be reasonable for a first exchange.', 'senna-finance'),
            ];

            $referral_avoid = [
                __('Do not turn an insight conversation into a referral request too quickly.', 'senna-finance'),
                __('Do not ask multiple people at the same firm for the same favour at once.', 'senna-finance'),
                __('Do not request access if you cannot yet explain your fit clearly.', 'senna-finance'),
            ];

            $primary_contact_name = $recruiter_name !== '' ? $recruiter_name : __('Recruiter contact', 'senna-finance');
            $team_contact_name = !empty($team_contacts[0]) ? (string) $team_contacts[0] : __('Relevant team-side contact', 'senna-finance');
            $contact_order_options = [
                sprintf(__('Start with %1$s or the process-facing route, then move to %2$s once you can ask sharper questions.', 'senna-finance'), $primary_contact_name, $team_contact_name),
                sprintf(__('The best sequence is process first, context second: use %1$s for timing, then %2$s for insight.', 'senna-finance'), $primary_contact_name, $team_contact_name),
                __('Use your first touch to get into the right lane, then speak to someone closer to the work once you can sound informed rather than curious from scratch.', 'senna-finance'),
            ];

            $first_step_action = $best_channel === 'Application then outreach'
                ? __('Get your application ready first so your first message can say you have already applied or are about to submit.', 'senna-finance')
                : __('Prepare one short outreach message tied to the brief before asking for time.', 'senna-finance');
            $second_step_action = $has_team_route
                ? __('After the first touch, move to a team-side contact with one focused question that proves you read the role properly.', 'senna-finance')
                : __('Follow up with one sharper signal or update instead of repeating the original outreach.', 'senna-finance');
            $third_step_action = !empty($application_process)
                ? sprintf(__('Align your follow-up with the likely process signal: %s.', 'senna-finance'), (string) $application_process[0])
                : __('Only escalate the ask once you have either a reply, a warm hint, or clear proof of fit to reference.', 'senna-finance');

            $best_first_move_options = [
                sprintf(__('Lead with one tight line on %1$s, then ask a small question that makes sense for a %2$s role at %3$s.', 'senna-finance'), $primary_signal, $role_title, $company),
                sprintf(__('The best opening move is not a meeting request. It is a short role-aware note that proves you understand %1$s and why it matters here.', 'senna-finance'), $primary_signal),
                sprintf(__('Open with context, not ambition. Show %1$s first, then ask for the smallest useful steer.', 'senna-finance'), $primary_signal),
                sprintf(__('Make the first note easy to answer: one proof point, one specific signal about %1$s, and one small ask.', 'senna-finance'), $primary_signal),
            ];

            $context_to_use = [
                sprintf(__('Reference one visible signal from the brief such as %s.', 'senna-finance'), $primary_signal),
                sprintf(__('Connect your background to %s rather than to “finance” broadly.', 'senna-finance'), $secondary_signal),
                sprintf(__('Explain why %s in %s is relevant for you now.', 'senna-finance'), $company, $location),
            ];
            if ($third_signal !== '' && $third_signal !== $location) {
                $context_to_use[] = sprintf(__('If true, mention your exposure to %s as supporting context.', 'senna-finance'), $third_signal);
            }

            $bad_outreach_risks = [
                __('Messages that ask for time before showing any role-specific context.', 'senna-finance'),
                __('Opening with broad interest in finance or investing without a private equity, market-specific, or role-specific angle.', 'senna-finance'),
                __('Reaching out in the wrong tone for the role’s seniority or timing.', 'senna-finance'),
            ];
            if ($best_channel === 'LinkedIn DM') {
                $bad_outreach_risks[] = __('Writing a long LinkedIn message when a tighter note would be easier to answer.', 'senna-finance');
            } elseif ($best_channel === 'Email') {
                $bad_outreach_risks[] = __('Sending a polished but generic email that could have been sent to any firm.', 'senna-finance');
            } else {
                $bad_outreach_risks[] = __('Applying silently and only networking later, after the context window has faded.', 'senna-finance');
            }

            $follow_up_logic_options = [
                __('Follow up once after a few days with one sharper signal, update, or question. Do not resend the same message.', 'senna-finance'),
                __('One follow-up is enough. If there is still no reply, improve the angle or move to a better-matched contact.', 'senna-finance'),
                __('Use the follow-up to add context, not pressure. A better signal is stronger than a second generic request.', 'senna-finance'),
            ];

            $contact_cards = [
                [
                    'name' => $primary_contact_name,
                    'role' => $recruiter_title !== '' ? $recruiter_title : __('Recruiter', 'senna-finance'),
                    'why_this_person' => $variant % 2 === 0
                        ? __('Best for timing clarity, recruiter process signals, and getting your name onto the right lane quickly.', 'senna-finance')
                        : __('Best for knowing whether the role is moving now, what matters first, and how to position your first touch.', 'senna-finance'),
                    'best_channel' => $best_channel,
                    'best_ask' => $is_early_career ? __('Insight request', 'senna-finance') : __('5 min telephone call', 'senna-finance'),
                    'lead_with' => sprintf(__('Lead with %1$s and one direct reason this %2$s role is relevant for you now.', 'senna-finance'), $primary_signal, $role_title),
                    'avoid' => __('Avoid treating the first note like a favour request or a coffee ask.', 'senna-finance'),
                    'best_timing' => $timing_bucket === 'fresh' ? __('Best used immediately while the role still feels newly live.', 'senna-finance') : __('Best used once you can point to a ready application or clear fit signal.', 'senna-finance'),
                ],
                [
                    'name' => $team_contact_name,
                    'role' => __('Team-side perspective', 'senna-finance'),
                    'why_this_person' => $has_team_route
                        ? __('Best for understanding what the mandate actually sounds like internally and how candidates usually stand out.', 'senna-finance')
                        : __('Best used as the type of person you should look for next, once the process-facing route has given you enough context.', 'senna-finance'),
                    'best_channel' => __('LinkedIn DM', 'senna-finance'),
                    'best_ask' => $is_early_career ? __('Coffee meeting', 'senna-finance') : __('Zoom call', 'senna-finance'),
                    'lead_with' => sprintf(__('Lead with one focused question on how %s shows up in the actual work.', 'senna-finance'), $primary_signal),
                    'avoid' => __('Avoid turning the first exchange into an obvious referral ask.', 'senna-finance'),
                    'best_timing' => __('Best used after you have a better sense of the mandate and can ask more intelligent questions.', 'senna-finance'),
                ],
            ];

            $conversation_templates = [
                'coffee_meeting' => sprintf(__('Hi [Name], I’m looking closely at the %1$s role at %2$s and wanted to avoid sending a generic message. The brief’s focus on %3$s is especially relevant to my background, and I wondered if you might be open to a short coffee so I can ask one or two more informed questions about the team and the role.', 'senna-finance'), $role_title, $company, $primary_signal),
