        private function get_crm_reddit_networking_preview_variant(array $context)
        {
            $seed = strtolower(implode('|', array_filter([
                (string) ($context['role_title'] ?? ''),
                (string) ($context['company'] ?? ''),
                (string) ($context['location'] ?? ''),
                (string) ($context['industry'] ?? ''),
                (string) ($context['seniority'] ?? ''),
                (string) ($context['posted_label'] ?? ''),
            ])));

            if ($seed === '') {
                return 0;
            }

            return (int) (abs(crc32($seed)) % 4);
        }

        private function get_crm_reddit_networking_preview_signals(array $context)
        {
            $signals = [];
            foreach (['keywords', 'skills', 'requirements'] as $key) {
                foreach ((array) ($context[$key] ?? []) as $value) {
                    $value = trim((string) $value);
                    if ($value !== '') {
                        $signals[] = sanitize_text_field($value);
                    }
                }
            }

            if (!empty($context['industry'])) {
                $signals[] = sanitize_text_field((string) $context['industry']);
            }

            if (!empty($context['location'])) {
                $signals[] = sanitize_text_field((string) $context['location']);
            }

            return array_values(array_slice(array_unique(array_filter($signals)), 0, 6));
        }

        private function get_crm_reddit_networking_preview_channel(array $context)
        {
            if (!empty($context['recruiter_linkedin'])) {
                return 'LinkedIn DM';
            }

            if (!empty($context['recruiter_email'])) {
                return 'Email';
            }

            if (!empty($context['team_contacts'])) {
                return 'Warm intro';
            }

            return 'Application then outreach';
        }

        private function get_crm_reddit_networking_preview_timing_bucket($posted_label)
        {
            $posted_label = strtolower(trim((string) $posted_label));
            if ($posted_label === '') {
                return 'active';
            }

            foreach (['hour', 'today', 'yesterday', 'day'] as $needle) {
                if (strpos($posted_label, $needle) !== false) {
                    return 'fresh';
                }
            }

            if (strpos($posted_label, 'week') !== false) {
                return 'active';
            }

            return 'mature';
        }

        private function render_crm_reddit_networking_results_markup(array $strategy, array $context)
        {
            $hero = is_array($strategy['hero'] ?? null) ? $strategy['hero'] : [];
            $recruiter_strategy = is_array($strategy['recruiter_strategy'] ?? null) ? $strategy['recruiter_strategy'] : [];
            $referral_strategy = is_array($strategy['referral_strategy'] ?? null) ? $strategy['referral_strategy'] : [];
            $who_to_network_with = is_array($strategy['who_to_network_with'] ?? null) ? $strategy['who_to_network_with'] : [];
            $outreach_sequence = is_array($strategy['outreach_sequence'] ?? null) ? $strategy['outreach_sequence'] : [];
            $message_drafts = is_array($strategy['message_drafts'] ?? null) ? $strategy['message_drafts'] : [];
            $contact_playbook = is_array($strategy['contact_playbook'] ?? null) ? $strategy['contact_playbook'] : [];
            $conversation_templates = is_array($strategy['conversation_templates'] ?? null) ? $strategy['conversation_templates'] : [];
            $template_drafts = [
                'most_likely_to_respond' => trim((string) ($message_drafts['most_likely_to_respond_template'] ?? ($message_drafts['linkedin_connect'] ?? ''))),
                'linkedin_strategy' => trim((string) ($message_drafts['linkedin_networking_inmail_strategy'] ?? ($message_drafts['linkedin_inmail'] ?? ($message_drafts['recruiter_message'] ?? '')))),
                'quick_call_strategy' => trim((string) ($conversation_templates['quick_networking_call_strategy'] ?? ($conversation_templates['five_min_telephone_call'] ?? ''))),
                'email_referral_templates' => trim((string) ($message_drafts['email_referral_templates'] ?? '')),
            ];
            $contacts = [];

            if (!empty($context['recruiter_name']) || !empty($context['recruiter_title'])) {
                $contacts[] = [
                    'name' => (string) ($context['recruiter_name'] ?? __('Recruiter contact', 'senna-finance')),
                    'role' => (string) ($context['recruiter_title'] ?? __('Recruiter', 'senna-finance')),
                    'meta' => (string) ($context['recruiter_firm'] ?? ''),
                ];
            }

            foreach ((array) ($context['team_contacts'] ?? []) as $team_contact) {
                if (!is_string($team_contact) || trim($team_contact) === '') {
                    continue;
                }

                $contacts[] = [
                    'name' => trim($team_contact),
                    'role' => __('Team contact', 'senna-finance'),
                    'meta' => (string) ($context['company'] ?? ''),
                ];
            }

            $contact_cards = [];
            foreach ((array) ($contact_playbook['contact_cards'] ?? []) as $card) {
                if (!is_array($card)) {
                    continue;
                }

                $contact_cards[] = [
                    'name' => trim((string) ($card['name'] ?? '')),
                    'role' => trim((string) ($card['role'] ?? '')),
                    'why_this_person' => trim((string) ($card['why_this_person'] ?? '')),
                    'best_channel' => trim((string) ($card['best_channel'] ?? '')),
                    'best_ask' => trim((string) ($card['best_ask'] ?? '')),
                    'lead_with' => trim((string) ($card['lead_with'] ?? '')),
                    'avoid' => trim((string) ($card['avoid'] ?? '')),
                    'best_timing' => trim((string) ($card['best_timing'] ?? '')),
                ];
            }

            $has_networking_access = $this->current_user_has_crm_reddit_premium_access();
            $membership_url = $this->get_canonical_membership_url();
            $current_user = wp_get_current_user();
            $membership_email = ($current_user instanceof \WP_User && !empty($current_user->user_email) && is_email($current_user->user_email))
                ? (string) $current_user->user_email
                : '';
            $target_groups = [
                'primary_targets' => [
                    'label' => __('Primary targets', 'senna-finance'),
                    'items' => is_array($who_to_network_with['primary_targets'] ?? null) ? $who_to_network_with['primary_targets'] : [],
                ],
                'secondary_targets' => [
                    'label' => __('Secondary targets', 'senna-finance'),
                    'items' => is_array($who_to_network_with['secondary_targets'] ?? null) ? $who_to_network_with['secondary_targets'] : [],
                ],
            ];
            $placeholder_for_role = static function ($role = '', $is_recruiter = false) {
                $role = strtolower(trim((string) $role));
                if ($is_recruiter || strpos($role, 'recruit') !== false || strpos($role, 'hiring') !== false) {
                    return __('Recruiter contact', 'senna-finance');
                }

                if (strpos($role, 'analyst') !== false || strpos($role, 'associate') !== false || strpos($role, 'team') !== false || strpos($role, 'intern') !== false) {
                    return __('Team contact', 'senna-finance');
                }

                return __('Relevant contact', 'senna-finance');
            };

            $redaction_map = [];
            $recruiter_name = trim((string) ($context['recruiter_name'] ?? ''));
            if ($recruiter_name !== '') {
                $redaction_map[$recruiter_name] = $placeholder_for_role((string) ($context['recruiter_title'] ?? ''), true);
            }
            foreach ((array) ($context['team_contacts'] ?? []) as $team_contact) {
                $team_contact = is_string($team_contact) ? trim($team_contact) : '';
                if ($team_contact !== '') {
                    $redaction_map[$team_contact] = __('Team contact', 'senna-finance');
                }
            }
            foreach ((array) ($who_to_network_with['primary_targets'] ?? []) as $target) {
                if (is_array($target) && !empty($target['name'])) {
                    $redaction_map[trim((string) $target['name'])] = $placeholder_for_role((string) ($target['role'] ?? ''));
                }
            }
            foreach ((array) ($who_to_network_with['secondary_targets'] ?? []) as $target) {
                if (is_array($target) && !empty($target['name'])) {
                    $redaction_map[trim((string) $target['name'])] = $placeholder_for_role((string) ($target['role'] ?? ''));
                }
            }
            foreach ($contact_cards as $card) {
                if (!empty($card['name'])) {
                    $redaction_map[trim((string) $card['name'])] = $placeholder_for_role((string) ($card['role'] ?? ''));
                }
            }
            uksort($redaction_map, static function ($left, $right) {
                return strlen((string) $right) <=> strlen((string) $left);
            });

            $mask_name = static function ($value, $role = '', $is_recruiter = false) use ($placeholder_for_role) {
                $value = trim((string) $value);
                if ($value === '') {
                    return __('Hidden contact', 'senna-finance');
                }

                return $placeholder_for_role($role, $is_recruiter);
            };

            $redact_text = function ($text) use ($redaction_map) {
                $text = trim((string) $text);
                if ($text === '') {
                    return '';
                }

                foreach ($redaction_map as $token => $replacement) {
                    $safe_token = trim((string) $token);
                    if ($safe_token === '') {
                        continue;
                    }

                    $text = str_ireplace($safe_token, (string) $replacement, $text);
                }

                return $text;
            };

            $teaser_text = function ($text, $word_limit = 42) use ($redact_text) {
                $text = $redact_text($text);
                if ($text === '') {
                    return '';
                }

                $words = preg_split('/\s+/', $text) ?: [];
                if (count($words) <= $word_limit) {
                    return $text;
                }

                $slice = array_slice($words, 0, $word_limit);
                return trim(implode(' ', $slice)) . '…';
            };

            $teaser_items = function (array $items, $limit = 2, $word_limit = 20) use ($teaser_text) {
                $items = array_values(array_filter(array_map(static function ($item) {
                    return is_string($item) ? trim($item) : '';
                }, $items)));

                if (empty($items)) {
                    return [];
                }

                $items = array_slice($items, 0, $limit);
                return array_values(array_filter(array_map(static function ($item) use ($teaser_text, $word_limit) {
                    return $teaser_text($item, $word_limit);
                }, $items)));
            };

            ob_start();
        ?>
