        private function render_crm_reddit_networking_list_markup(array $items)
        {
            $items = array_values(array_filter(array_map(static function ($item) {
                return is_string($item) ? trim($item) : '';
            }, $items)));

            if (empty($items)) {
                return '<p class="sffc-crm-reddit-networking-list-empty">' . esc_html__('No additional detail available yet.', 'senna-finance') . '</p>';
            }

            ob_start();
        ?>
            <ul class="sffc-crm-reddit-networking-list">
                <?php foreach ($items as $item) : ?>
                    <li><?php echo esc_html($item); ?></li>
                <?php endforeach; ?>
            </ul>
        <?php
            return ob_get_clean();
        }

        private function render_crm_reddit_blurred_text_image($text, $variant = 'body', $class_name = '')
        {
            $text = trim((string) $text);
            if ($text === '') {
                return '';
            }

            $variants = [
                'headline' => ['width' => 720, 'font' => 26, 'line_height' => 34, 'max_chars' => 34, 'max_lines' => 2],
                'title' => ['width' => 420, 'font' => 18, 'line_height' => 24, 'max_chars' => 24, 'max_lines' => 2],
                'meta' => ['width' => 340, 'font' => 15, 'line_height' => 21, 'max_chars' => 26, 'max_lines' => 2],
                'body' => ['width' => 640, 'font' => 16, 'line_height' => 24, 'max_chars' => 46, 'max_lines' => 3],
                'body_short' => ['width' => 480, 'font' => 16, 'line_height' => 24, 'max_chars' => 34, 'max_lines' => 2],
            ];
            $config = $variants[$variant] ?? $variants['body'];

            $words = preg_split('/\s+/', $text) ?: [];
            $lines = [];
            $current_line = '';

            foreach ($words as $word) {
                $candidate = trim($current_line === '' ? $word : $current_line . ' ' . $word);
                $candidate_length = function_exists('mb_strlen') ? mb_strlen($candidate) : strlen($candidate);
                if ($candidate_length > $config['max_chars'] && $current_line !== '') {
                    $lines[] = $current_line;
                    $current_line = $word;
                    if (count($lines) >= $config['max_lines']) {
                        break;
                    }
                } else {
                    $current_line = $candidate;
                }
            }

            if ($current_line !== '' && count($lines) < $config['max_lines']) {
                $lines[] = $current_line;
            }

            if (empty($lines)) {
                $lines[] = $text;
            }

            $line_count = count($lines);
            $height = max(34, ($line_count * (int) $config['line_height']) + 8);
            $text_nodes = [];

            foreach ($lines as $index => $line) {
                $y = 6 + ((int) $config['font']) + ($index * (int) $config['line_height']);
                $escaped_line = htmlspecialchars($line, ENT_QUOTES | ENT_XML1, 'UTF-8');
                $text_nodes[] = '<text x="0" y="' . $y . '">' . $escaped_line . '</text>';
            }

            $svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' . (int) $config['width'] . '" height="' . $height . '" viewBox="0 0 ' . (int) $config['width'] . ' ' . $height . '">'
                . '<defs><filter id="b"><feGaussianBlur stdDeviation="3.8"/></filter></defs>'
                . '<g filter="url(#b)" fill="#14262d" font-family="Georgia, serif" font-size="' . (int) $config['font'] . '" font-weight="600">'
                . implode('', $text_nodes)
                . '</g></svg>';

            $data_uri = 'data:image/svg+xml;base64,' . base64_encode($svg);
            $classes = trim('sffc-crm-reddit-locked-blur sffc-crm-reddit-locked-blur--' . sanitize_html_class($variant) . ' ' . $class_name);

            return '<span class="' . esc_attr($classes) . '" aria-hidden="true"><img src="' . esc_url($data_uri) . '" alt="" loading="lazy" decoding="async"></span>';
        }

        private function get_crm_reddit_blurred_avatar_data_uri($image_url, $fallback_letter = 'R')
        {
            $fallback_letter = strtoupper(substr(trim((string) $fallback_letter), 0, 1));
            if ($fallback_letter === '') {
                $fallback_letter = 'R';
            }

            if ($image_url !== '') {
                $escaped_url = htmlspecialchars(esc_url_raw($image_url), ENT_QUOTES | ENT_XML1, 'UTF-8');
                $svg = '<svg xmlns="http://www.w3.org/2000/svg" width="56" height="56" viewBox="0 0 56 56">'
                    . '<defs><clipPath id="c"><circle cx="28" cy="28" r="28"/></clipPath><filter id="b"><feGaussianBlur stdDeviation="3.8"/></filter></defs>'
                    . '<g clip-path="url(#c)" filter="url(#b)"><image href="' . $escaped_url . '" width="56" height="56" preserveAspectRatio="xMidYMid slice"/></g>'
                    . '</svg>';
            } else {
                $escaped_letter = htmlspecialchars($fallback_letter, ENT_QUOTES | ENT_XML1, 'UTF-8');
                $svg = '<svg xmlns="http://www.w3.org/2000/svg" width="56" height="56" viewBox="0 0 56 56">'
                    . '<defs><filter id="b"><feGaussianBlur stdDeviation="3.2"/></filter></defs>'
                    . '<g filter="url(#b)"><circle cx="28" cy="28" r="28" fill="#d9dee2"/><text x="28" y="35" text-anchor="middle" fill="#63727a" font-family="Arial, sans-serif" font-size="22" font-weight="700">' . $escaped_letter . '</text></g>'
                    . '</svg>';
            }

            return 'data:image/svg+xml;base64,' . base64_encode($svg);
        }

        private function current_user_has_crm_reddit_premium_access()
        {
            if (!is_user_logged_in()) {
                return false;
            }

            $user_id = get_current_user_id();
            if ($user_id <= 0) {
                return false;
            }

            $has_membership_access = false;

            try {
                if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                    $crm_memberpress = SFFC_CRM_MemberPress_Integration::get_instance();
                    if ($crm_memberpress && method_exists($crm_memberpress, 'get_crm_tier')) {
                        $member_tier = (string) $crm_memberpress->get_crm_tier($user_id);
                        $has_membership_access = in_array($member_tier, ['insider', 'pro', 'career', 'elite', 'premium'], true);
                    }
                }

                if (!$has_membership_access && class_exists('SFFC_MemberPress_Integration')) {
                    $mepr = SFFC_MemberPress_Integration::get_instance();
                    if ($mepr && method_exists($mepr, 'has_premium_access')) {
                        $has_membership_access = (bool) $mepr->has_premium_access($user_id);
                    }
                }

                if (!$has_membership_access && method_exists($this, 'get_active_memberpress_product_ids') && method_exists($this, 'has_active_paid_memberpress_plan')) {
                    $active_product_ids = $this->get_active_memberpress_product_ids($user_id);
                    $has_membership_access = $this->has_active_paid_memberpress_plan($active_product_ids);
                }

                if (!$has_membership_access && class_exists('MeprUser')) {
                    $mepr_user = new MeprUser($user_id);
                    if (method_exists($mepr_user, 'is_active')) {
                        $has_membership_access = (bool) $mepr_user->is_active();
                    }
                }
            } catch (\Throwable $throwable) {
                $has_membership_access = false;
            }

            return $has_membership_access;
        }

        private function current_user_has_crm_editorial_paid_membership_access($user_id = null)
        {
            if (!is_user_logged_in()) {
                return false;
            }

            $user_id = $user_id !== null ? absint($user_id) : get_current_user_id();
            if ($user_id <= 0) {
                return false;
            }

            if (user_can($user_id, 'manage_options')) {
                return true;
            }

            try {
                if (method_exists($this, 'get_active_memberpress_product_ids') && method_exists($this, 'has_active_paid_memberpress_plan')) {
                    if ($this->has_active_paid_memberpress_plan($this->get_active_memberpress_product_ids($user_id))) {
                        return true;
                    }
                }
            } catch (\Throwable $throwable) {
                // Fall through to the checkout redirect verification below.
            }

            if ($this->user_has_verified_memberpress_checkout_redirect($user_id)) {
                return true;
            }

            return false;
        }

        private function get_crm_apply_chat_membership_snapshot($user_id)
        {
            $user_id = absint($user_id);
            $snapshot = [
                'has_paid_membership' => false,
                'tier' => 'free',
                'plan_name' => '',
                'status' => '',
                'amount' => 0,
            ];

            if ($user_id <= 0) {
                return $snapshot;
            }

            $snapshot['has_paid_membership'] = $this->current_user_has_crm_editorial_paid_membership_access($user_id);

            try {
                if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                    $crm_integration = SFFC_CRM_MemberPress_Integration::get_instance();
                    if ($crm_integration && method_exists($crm_integration, 'get_crm_tier')) {
                        $snapshot['tier'] = (string) $crm_integration->get_crm_tier($user_id);
                    }
                }
            } catch (\Throwable $throwable) {
                $snapshot['tier'] = 'free';
            }

            try {
                if (class_exists('SFFC_MemberPress_Integration')) {
                    $mepr_integration = SFFC_MemberPress_Integration::get_instance();
                    if ($mepr_integration && method_exists($mepr_integration, 'get_user_subscriptions')) {
                        $subscriptions = (array) $mepr_integration->get_user_subscriptions($user_id);
                        $subscription = $this->get_crm_reddit_primary_memberpress_subscription($subscriptions);
                        if (!empty($subscription)) {
                            $snapshot['plan_name'] = $this->get_crm_reddit_memberpress_plan_name($subscription, '');
                            $snapshot['status'] = sanitize_key((string) ($subscription['status'] ?? ''));
                            $snapshot['amount'] = (float) ($subscription['total'] ?? $subscription['price'] ?? 0);
                            if ($snapshot['amount'] > 0 && in_array($snapshot['status'], ['active', 'confirmed', 'complete', 'trial', 'pending'], true)) {
                                $snapshot['has_paid_membership'] = true;
                            }
                            if ($snapshot['tier'] === 'free') {
                                $snapshot['tier'] = $this->infer_crm_reddit_membership_tier_from_subscription($subscription, 'free');
                            }
                        }
                    }
                }
            } catch (\Throwable $throwable) {
                // Keep the snapshot lightweight and non-fatal.
            }

            return $snapshot;
        }

