        private function get_crm_editorial_paid_memberpress_product_ids()
        {
            $product_ids = [234380, 190564];

            foreach ((array) $this->get_subscription_plans() as $plan) {
                $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                $product_id = $this->extract_memberpress_product_id_from_shortcode($shortcode);
                if ($product_id > 0) {
                    $product_ids[] = $product_id;
                }
            }

            /**
             * Allows additional paid MemberPress products to unlock the editorial community.
             *
             * @param int[] $product_ids
             */
            $product_ids = apply_filters('sffc_crm_editorial_paid_memberpress_product_ids', $product_ids);

            return array_values(array_unique(array_filter(array_map('absint', (array) $product_ids))));
        }

        private function is_crm_editorial_paid_memberpress_product_id($product_id)
        {
            $product_id = absint($product_id);
            if ($product_id <= 0) {
                return false;
            }

            if (in_array($product_id, $this->get_crm_editorial_paid_memberpress_product_ids(), true)) {
                return true;
            }

            return $this->get_memberpress_product_price_amount($product_id) > 0;
        }

        private function user_has_verified_memberpress_checkout_redirect($user_id)
        {
            $user_id = absint($user_id);
            if ($user_id <= 0) {
                return false;
            }

            $membership_id = isset($_GET['membership_id']) ? absint(wp_unslash($_GET['membership_id'])) : 0;
            $transaction_id = isset($_GET['transaction_id']) ? absint(wp_unslash($_GET['transaction_id'])) : 0;
            $subscription_id = isset($_GET['subscription_id']) ? absint(wp_unslash($_GET['subscription_id'])) : 0;

            if ($membership_id <= 0 && $transaction_id <= 0 && $subscription_id <= 0) {
                return false;
            }

            $verified_product_id = 0;
            if ($transaction_id > 0) {
                $verified_product_id = $this->get_verified_memberpress_transaction_product_id($transaction_id, $user_id);
            }

            if ($verified_product_id <= 0 && $subscription_id > 0) {
                $verified_product_id = $this->get_verified_memberpress_subscription_product_id($subscription_id, $user_id);
            }

            if (
                $verified_product_id <= 0
                && $membership_id > 0
                && $this->is_crm_editorial_paid_memberpress_product_id($membership_id)
                && in_array($membership_id, $this->get_active_memberpress_product_ids($user_id), true)
            ) {
                $verified_product_id = $membership_id;
            }

            if ($verified_product_id <= 0 || !$this->is_crm_editorial_paid_memberpress_product_id($verified_product_id)) {
                return false;
            }

            update_user_meta($user_id, 'sffc_crm_editorial_community_onboarding_seen', '1');
            update_user_meta($user_id, 'sffc_crm_editorial_paid_checkout_verified_at', current_time('mysql'));
            update_user_meta($user_id, 'sffc_crm_editorial_paid_checkout_product_id', $verified_product_id);

            return true;
        }

        private function get_verified_memberpress_transaction_product_id($transaction_id, $user_id)
        {
            $transaction_id = absint($transaction_id);
            $user_id = absint($user_id);
            if ($transaction_id <= 0 || $user_id <= 0) {
                return 0;
            }

            try {
                if (class_exists('MeprTransaction')) {
                    $transaction = new MeprTransaction($transaction_id);
                    $transaction_user_id = isset($transaction->user_id) ? absint($transaction->user_id) : 0;
                    $product_id = isset($transaction->product_id) ? absint($transaction->product_id) : 0;
                    if ($transaction_user_id === $user_id && $product_id > 0) {
                        return $product_id;
                    }
                }
            } catch (\Throwable $throwable) {
                // Fall through to direct table lookup.
            }

            global $wpdb;
            $table = $wpdb->prefix . 'mepr_transactions';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
            if ($table_exists !== $table) {
                return 0;
            }

            $row = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT user_id, product_id FROM {$table} WHERE id = %d LIMIT 1",
                    $transaction_id
                ),
                ARRAY_A
            );

            if (!is_array($row) || absint($row['user_id'] ?? 0) !== $user_id) {
                return 0;
            }

            return absint($row['product_id'] ?? 0);
        }

        private function get_verified_memberpress_subscription_product_id($subscription_id, $user_id)
        {
            $subscription_id = absint($subscription_id);
            $user_id = absint($user_id);
            if ($subscription_id <= 0 || $user_id <= 0) {
                return 0;
            }

            try {
                if (class_exists('MeprSubscription')) {
                    $subscription = new MeprSubscription($subscription_id);
                    $subscription_user_id = isset($subscription->user_id) ? absint($subscription->user_id) : 0;
                    $product_id = isset($subscription->product_id) ? absint($subscription->product_id) : 0;
                    if ($subscription_user_id === $user_id && $product_id > 0) {
                        return $product_id;
                    }
                }
            } catch (\Throwable $throwable) {
                // Fall through to direct table lookup.
            }

            global $wpdb;
            $table = $wpdb->prefix . 'mepr_subscriptions';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
            if ($table_exists !== $table) {
                return 0;
            }

            $row = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT user_id, product_id FROM {$table} WHERE id = %d LIMIT 1",
                    $subscription_id
                ),
                ARRAY_A
            );

            if (!is_array($row) || absint($row['user_id'] ?? 0) !== $user_id) {
                return 0;
            }

            return absint($row['product_id'] ?? 0);
        }

        private function build_reddit_jobs_jd_text(WP_Post $jobs_post, array $item)
        {
            if (!function_exists('sffc_format_crm_jd_content_for_text')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
            }

            $lines = [];
            $role_title = trim((string) ($item['role_title'] ?? $jobs_post->post_title));
            $company = trim((string) ($item['company'] ?? ''));
            $location = trim((string) ($item['location'] ?? ''));
            $salary_text = trim((string) ($item['salary_text'] ?? ''));
            $employment_type = trim((string) ($item['employment_type'] ?? ''));
            $seniority = trim((string) ($item['seniority'] ?? ''));

            if ($role_title !== '') {
                $lines[] = 'Job Title: ' . $role_title;
            }
            if ($company !== '') {
                $lines[] = 'Company: ' . $company;
            }
            if ($location !== '') {
                $lines[] = 'Location: ' . $location;
            }
            if ($salary_text !== '') {
                $lines[] = 'Compensation: ' . $salary_text;
            }
            if ($employment_type !== '') {
                $lines[] = 'Employment Type: ' . $employment_type;
            }
            if ($seniority !== '') {
                $lines[] = 'Seniority: ' . $seniority;
            }

            $content = (string) $jobs_post->post_content;
            if ($content === '' && !empty($item['description_html'])) {
                $content = (string) $item['description_html'];
            }
            if ($content === '' && !empty($item['excerpt'])) {
                $content = (string) $item['excerpt'];
            }

            $formatted_content = function_exists('sffc_format_crm_jd_content_for_text')
                ? sffc_format_crm_jd_content_for_text($content)
                : trim(wp_strip_all_tags($content));

            if ($formatted_content !== '') {
                $lines[] = '';
                $lines[] = 'Job Description:';
                $lines[] = $formatted_content;
            }

            return trim(implode("\n", $lines));
        }

