        private function get_reddit_email_headers_with_reply_to($name = '', $email = '')
        {
            $headers = $this->get_reddit_email_headers();
            $email = sanitize_email((string) $email);
            $name = trim((string) $name);

            if ($email === '' || !is_email($email)) {
                return $headers;
            }

            $reply_to = $name !== ''
                ? sprintf('Reply-To: %s <%s>', sanitize_text_field($name), $email)
                : 'Reply-To: ' . $email;

            $headers[] = $reply_to;

            return array_values(array_unique($headers));
        }

