                        continue;
                    }

                    $is_secondary = !empty($button['secondary']);
                    $bg = $is_secondary ? $styles['card_bg'] : $styles['accent'];
                    $border = $is_secondary ? '1px solid ' . $styles['accent'] : '1px solid ' . $styles['accent'];
                    $color = $is_secondary ? $styles['accent'] : '#ffffff';
