    <td align="center">
      <table role="presentation" cellpadding="0" cellspacing="0" width="640" dir="' . esc_attr($dir) . '" style="max-width:640px !important;width:100% !important;background:' . $styles['card_bg'] . ' !important;border:1px solid ' . $styles['border'] . ' !important;border-radius:18px !important;overflow:hidden !important;border-collapse:separate !important;direction:' . esc_attr($dir) . ';text-align:' . esc_attr($align) . ';">
        <tr>
