            <img src="' . $logo_url . '" alt="MENA Careers" style="display:block !important;width:148px !important;max-width:148px !important;height:auto !important;margin:0 0 22px !important;">
            <div style="' . $styles['sans'] . 'font-size:11px !important;font-weight:700 !important;letter-spacing:0.14em !important;text-transform:uppercase !important;color:' . $styles['accent'] . ' !important;margin:0 0 12px !important;">' . esc_html($eyebrow) . '</div>
            <div style="' . $styles['serif'] . 'font-size:34px !important;line-height:1.08 !important;letter-spacing:-0.03em !important;color:' . $styles['text'] . ' !important;margin:0 0 12px !important;">' . esc_html($headline) . '</div>
            <div style="' . $styles['sans'] . 'font-size:15px !important;line-height:1.7 !important;color:' . $styles['muted'] . ' !important;margin:0 !important;">' . $intro_html . '</div>
