        <tr>
          <td style="padding:0 34px 30px !important;">
            <div style="height:1px !important;background:' . $styles['border'] . ' !important;margin:0 0 18px !important;"></div>
            <div style="' . $styles['sans'] . 'font-size:12px !important;line-height:1.7 !important;color:' . $styles['muted'] . ' !important;">' . ($footer_note !== '' ? wp_kses_post($footer_note) : esc_html__('MENA Careers · Finance roles, application support, and recruiter-led opportunities.', 'senna-finance')) . '</div>
