        private function build_reddit_email_detail_rows(array $rows)
        {
            $styles = $this->get_reddit_email_styles();
            $html = '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse !important;background:' . $styles['card_bg'] . ' !important;border:1px solid ' . $styles['border'] . ' !important;border-radius:14px !important;overflow:hidden !important;margin:0 0 24px !important;">';

            $count = count($rows);
            foreach ($rows as $index => $row) {
                $label = esc_html((string) ($row['label'] ?? ''));
                $value = (string) ($row['value'] ?? '');
                if ($label === '' || $value === '') {
                    continue;
                }

                $divider = $index < ($count - 1) ? 'border-bottom:1px solid ' . $styles['border'] . ' !important;' : '';
                $html .= '<tr>
                    <td style="' . $styles['sans'] . 'padding:16px 18px !important;width:180px !important;font-size:11px !important;font-weight:700 !important;letter-spacing:0.1em !important;text-transform:uppercase !important;color:' . $styles['accent'] . ' !important;' . $divider . '">' . $label . '</td>
                    <td style="' . $styles['sans'] . 'padding:16px 18px !important;font-size:15px !important;line-height:1.6 !important;color:' . $styles['text'] . ' !important;' . $divider . '">' . wp_kses_post($value) . '</td>
                </tr>';
            }

            $html .= '</table>';

            return $html;
        }

