                <div style="' . $styles['sans'] . 'font-size:11px !important;font-weight:700 !important;letter-spacing:0.1em !important;text-transform:uppercase !important;color:' . $styles['accent'] . ' !important;margin:0 0 10px !important;">' . esc_html($label) . '</div>
                <div style="' . $styles['sans'] . 'font-size:15px !important;line-height:1.75 !important;color:' . $styles['text'] . ' !important;margin:0 !important;">' . nl2br(esc_html($copy)) . '</div>
