        private function build_reddit_service_request_email(array $args = [])
        {
            $eyebrow = (string) ($args['eyebrow'] ?? __('MENA Careers Request', 'senna-finance'));
            $headline = (string) ($args['headline'] ?? __('Request update', 'senna-finance'));
            $intro = (string) ($args['intro'] ?? '');
            $rows = is_array($args['rows'] ?? null) ? (array) $args['rows'] : [];
            $body_label = (string) ($args['body_label'] ?? '');
            $body_copy = (string) ($args['body_copy'] ?? '');
            $note_html = (string) ($args['note_html'] ?? '');
            $cta_buttons = is_array($args['cta_buttons'] ?? null) ? (array) $args['cta_buttons'] : [];
            $footer_note = (string) ($args['footer_note'] ?? '');

            $content_html = '';

            if (!empty($rows)) {
                $content_html .= $this->build_reddit_email_detail_rows($rows);
            }

            if ($body_label !== '' && $body_copy !== '') {
                $content_html .= $this->build_reddit_email_copy_block($body_label, $body_copy);
            }

            if ($note_html !== '') {
                $content_html .= '<div style="margin:0 0 26px !important;padding:18px 20px !important;background:#fffdf8 !important;border:1px solid #ded7ca !important;border-radius:14px !important;">
                    <div style="' . $this->get_reddit_email_styles()['sans'] . 'font-size:15px !important;line-height:1.75 !important;color:#5e6b71 !important;margin:0 !important;">' . wp_kses_post($note_html) . '</div>
                </div>';
            }

            return $this->build_reddit_email_frame(
                $eyebrow,
                $headline,
                esc_html($intro),
                $content_html,
                $cta_buttons,
                $footer_note
            );
        }

        private function send_reddit_role_applied_email($user, array $role_context)
        {
            if (!$user instanceof \WP_User || empty($user->user_email) || !is_email($user->user_email)) {
                return false;
            }

            $locale = $this->get_email_recipient_locale($user);

            $role_title = trim((string) ($role_context['role_title'] ?? '')) ?: $this->localize_interface_copy('Role', 'الفرصة', $locale);
            $company_name = trim((string) ($role_context['company_name'] ?? '')) ?: $this->localize_interface_copy('MENA Careers', 'سنّا', $locale);
            $location = trim((string) ($role_context['location'] ?? ''));
            $senna_url = esc_url((string) ($role_context['senna_url'] ?? ''));
            $similar_roles_url = esc_url((string) ($role_context['similar_roles_url'] ?? home_url('/terminal/?tab=console')));
            $apply_url = esc_url((string) ($role_context['apply_url'] ?? ''));
            $recipient_name = trim((string) ($user->first_name ?: $user->display_name ?: $user->user_login));
            $applied_time = wp_date('j M Y, g:i a');

            $intro_html = esc_html($this->is_arabic_locale($locale)
                ? sprintf('مرحباً %s، حفظنا لك الفرصة التي قدّمت عليها عبر سنّا. احتفظ بهذه الرسالة كمرجع سريع وكطريق مباشر للعودة إلى صفحة الفرصة.', $recipient_name)
                : sprintf(__('Hi %s, we have saved the role you just applied to through MENA Careers. Keep this email as your clean application record and quick route back to the role page.', 'senna-finance'), $recipient_name));

            $content_html = '<div style="margin:0 0 20px !important;padding:22px 22px 18px !important;background:#f4eee3 !important;border:1px solid #ded7ca !important;border-radius:16px !important;">
                <div style="font-family:Signifier,Georgia,\'Times New Roman\',serif !important;font-size:27px !important;line-height:1.12 !important;letter-spacing:-0.03em !important;color:#14262d !important;margin:0 0 8px !important;">' . esc_html($role_title) . '</div>
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:15px !important;line-height:1.6 !important;color:#0D353E !important;font-weight:700 !important;margin:0 0 4px !important;">' . esc_html($company_name) . '</div>
                ' . ($location !== '' ? '<div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:14px !important;line-height:1.6 !important;color:#5e6b71 !important;margin:0 !important;">' . esc_html($location) . '</div>' : '') . '
            </div>';

            $rows = [
                [
                    'label' => $this->localize_interface_copy('Status', 'الحالة', $locale),
                    'value' => esc_html($this->localize_interface_copy('Applied via MENA Careers', 'تم التقديم عبر سنّا', $locale)),
                ],
                [
                    'label' => $this->localize_interface_copy('Applied', 'تاريخ التقديم', $locale),
                    'value' => esc_html($applied_time),
                ],
            ];

            if ($senna_url !== '') {
                $rows[] = [
                    'label' => $this->localize_interface_copy('Role Page', 'صفحة الفرصة', $locale),
                    'value' => '<a href="' . $senna_url . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html($this->localize_interface_copy('View this role on MENA Careers', 'اعرض هذه الفرصة على سنّا', $locale)) . '</a>',
                ];
            }

            if ($apply_url !== '') {
                $rows[] = [
                    'label' => $this->localize_interface_copy('Application Link', 'رابط التقديم', $locale),
                    'value' => '<a href="' . $apply_url . '" style="color:#0D353E !important;text-decoration:none !important;font-weight:700 !important;">' . esc_html($this->localize_interface_copy('Reopen the external application', 'افتح صفحة التقديم الخارجية', $locale)) . '</a>',
                ];
            }

            $content_html .= $this->build_reddit_email_detail_rows($rows);

            $content_html .= '<div style="margin:0 0 26px !important;padding:18px 20px !important;background:#fffdf8 !important;border:1px solid #ded7ca !important;border-radius:14px !important;">
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:11px !important;font-weight:700 !important;letter-spacing:0.1em !important;text-transform:uppercase !important;color:#0D353E !important;margin:0 0 8px !important;">' . esc_html($this->localize_interface_copy('Next on MENA Careers', 'الخطوة التالية على سنّا', $locale)) . '</div>
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:15px !important;line-height:1.7 !important;color:#5e6b71 !important;margin:0 !important;">' . esc_html($this->localize_interface_copy('Use MENA Careers to track this opportunity, review the role page again, and unlock more similar roles aligned to the same firm, strategy, and level.', 'استخدم سنّا لمتابعة هذه الفرصة والعودة إلى صفحة الدور وفتح فرص مشابهة أكثر قرباً من نفس الشركة والاستراتيجية والمستوى.', $locale)) . '</div>
            </div>';

            $message = $this->build_reddit_email_frame(
                $this->localize_interface_copy('Application Recorded', 'تم تسجيل التقديم', $locale),
                $this->is_arabic_locale($locale) ? sprintf('تم التقديم على %s لدى %s', $role_title, $company_name) : sprintf(__('[Applied] %s at %s', 'senna-finance'), $role_title, $company_name),
                $intro_html,
                $content_html,
                [
                    ['label' => $this->localize_interface_copy('View Role on MENA Careers', 'اعرض الفرصة على سنّا', $locale), 'url' => $senna_url !== '' ? $senna_url : home_url('/')],
                    ['label' => $this->localize_interface_copy('Explore Similar Roles', 'استعرض فرصاً مشابهة', $locale), 'url' => $similar_roles_url !== '' ? $similar_roles_url : home_url('/terminal/?tab=console'), 'secondary' => true],
                ],
                esc_html($this->localize_interface_copy('You are receiving this because you opened an application through MENA Careers. Keep this message for reference as you continue your search.', 'وصلك هذا البريد لأنك فتحت طلب تقديم عبر سنّا. احتفظ به كمرجع وأنت تواصل بحثك.', $locale)),
                $locale
            );

            $subject = $this->is_arabic_locale($locale)
                ? sprintf('تم التقديم: %s لدى %s', $role_title, $company_name)
                : sprintf('[Applied] %s at %s', $role_title, $company_name);

            return (bool) wp_mail($user->user_email, $subject, $message, $this->get_reddit_email_headers());
        }

        private function send_reddit_welcome_credentials_email($user, $temporary_password, array $role_context)
        {
