            $content_html = '<div style="margin:0 0 20px !important;padding:22px 22px 18px !important;background:#f4eee3 !important;border:1px solid #ded7ca !important;border-radius:16px !important;">
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:11px !important;font-weight:700 !important;letter-spacing:0.1em !important;text-transform:uppercase !important;color:#0D353E !important;margin:0 0 10px !important;">' . esc_html($this->localize_interface_copy('MENA Careers Account Ready', 'حساب سنّا جاهز', $locale)) . '</div>
                <div style="font-family:Signifier,Georgia,\'Times New Roman\',serif !important;font-size:27px !important;line-height:1.12 !important;letter-spacing:-0.03em !important;color:#14262d !important;margin:0 !important;">' . esc_html($this->localize_interface_copy('Temporary credentials for your account', 'بيانات الدخول المؤقتة لحسابك', $locale)) . '</div>
            </div>';

            $content_html .= $this->build_reddit_email_detail_rows($credential_rows);

            $content_html .= '<div style="margin:0 0 26px !important;padding:18px 20px !important;background:#fffdf8 !important;border:1px solid #ded7ca !important;border-radius:14px !important;">
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:11px !important;font-weight:700 !important;letter-spacing:0.1em !important;text-transform:uppercase !important;color:#0D353E !important;margin:0 0 8px !important;">' . esc_html($this->localize_interface_copy('Role in Progress', 'الفرصة المرتبطة بحسابك', $locale)) . '</div>
                <div style="font-family:Signifier,Georgia,\'Times New Roman\',serif !important;font-size:22px !important;line-height:1.16 !important;letter-spacing:-0.02em !important;color:#14262d !important;margin:0 0 6px !important;">' . esc_html($role_title) . '</div>
                <div style="font-family:\'Helvetica Neue\',Arial,sans-serif !important;font-size:14px !important;line-height:1.6 !important;color:#5e6b71 !important;margin:0 !important;">' . esc_html($this->is_arabic_locale($locale) ? sprintf('تم حفظ %s الآن داخل حسابك الجديد في سنّا، مع صفحة الفرصة وفرص مشابهة لها.', $company_name) : sprintf(__('%s is now saved against your new MENA Careers account, together with the role page and similar opportunities.', 'senna-finance'), $company_name)) . '</div>
            </div>';

            $message = $this->build_reddit_email_frame(
                $this->localize_interface_copy('Welcome to MENA Careers', 'أهلاً بك في سنّا', $locale),
                $this->localize_interface_copy('Your MENA Careers account is ready', 'حسابك في سنّا جاهز', $locale),
                $intro_html,
                $content_html,
                [
                    ['label' => $this->localize_interface_copy('Log in to MENA Careers', 'سجّل الدخول إلى سنّا', $locale), 'url' => $login_url],
                    ['label' => $this->localize_interface_copy('View Role on MENA Careers', 'اعرض الفرصة على سنّا', $locale), 'url' => $senna_url !== '' ? $senna_url : home_url('/'), 'secondary' => true],
                ],
                esc_html($this->localize_interface_copy('This is your temporary password email from MENA Careers. For security, update your password after your first login.', 'هذه رسالة كلمة المرور المؤقتة من سنّا. ولأمان حسابك، حدّث كلمة المرور بعد أول تسجيل دخول.', $locale)),
