            $subject = $this->localize_interface_copy('Your MENA Careers temporary credentials', 'بيانات الدخول المؤقتة إلى حسابك في سنّا', $locale);

            return (bool) wp_mail($user->user_email, $subject, $message, $this->get_reddit_email_headers());
        }

        private function render_crm_reddit_feed_card(array $item, $is_logged_in, $selected_group = '')
        {
            $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
            $avatar_letter = $recruiter_name !== ''
                ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1))
                : 'S';
            $company_letter = !empty($item['company'])
                ? strtoupper(function_exists('mb_substr') ? mb_substr((string) $item['company'], 0, 1) : substr((string) $item['company'], 0, 1))
                : 'C';
            $apply_url = !empty($item['apply_url']) ? $item['apply_url'] : $item['view_url'];
            $message_url = $item['message_url'] ?? '';
            $opportunity_notice = $this->get_crm_reddit_opportunity_notice($item);

            $chips = [];
            foreach (['company', 'location', 'salary_text', 'seniority', 'employment_type'] as $chip_key) {
                $chip_value = trim((string) ($item[$chip_key] ?? ''));
                if ($chip_value !== '') {
                    $chips[] = $chip_value;
                }
            }
            $chips = array_slice(array_values(array_unique($chips)), 0, 4);
            $group_name = trim((string) ($item['group_name'] ?? ''));
            $group_slug = sanitize_title((string) ($item['group_slug'] ?? ''));
            $group_url = $group_slug !== ''
                ? add_query_arg('reddit_group', $group_slug, get_permalink(get_queried_object_id()) ?: home_url('/'))
                : '';
            $has_premium_access = $this->current_user_has_crm_reddit_premium_access();
            $membership_url = $this->get_canonical_membership_url();
            $is_senna_community_view = $selected_group === '';
            $card_classes = ['sffc-crm-reddit-card'];
            if ($item['source'] === 'jobs') {
                $card_classes[] = 'is-pinned';
            }
            if ($is_senna_community_view) {
                $card_classes[] = 'is-senna-community';
            }
            $match_reason = $this->build_crm_reddit_feed_match_reason($item);
            $mail_meta = array_values(array_filter([
                trim((string) ($item['company'] ?? '')),
                trim((string) ($item['location'] ?? '')),
                trim((string) ($item['employment_type'] ?? '')),
                trim((string) ($item['seniority'] ?? '')),
            ]));
            $route_badge = !empty($item['apply_url'])
                ? __('Direct apply live', 'senna-finance')
                : __('Open job page', 'senna-finance');
            $route_badge_tone = !empty($item['apply_url']) ? 'apply' : 'page';
            $primary_cta_label = !empty($item['apply_url']) ? __('Apply now', 'senna-finance') : __('Open role', 'senna-finance');
            $recruiter_display_name = $recruiter_name !== '' ? $recruiter_name : __('MENA Careers', 'senna-finance');
            $recruiter_company = trim((string) ($item['recruiter_firm'] ?? ($item['company'] ?? '')));
            $posted_label = trim((string) ($item['posted_label'] ?? ''));

            ob_start();
        ?>
            <?php if ($is_senna_community_view) : ?>
                <article
                    class="<?php echo esc_attr(implode(' ', $card_classes)); ?>"
                    data-source="<?php echo esc_attr($item['source']); ?>"
                    <?php echo !empty($item['view_url']) ? ' data-reddit-card-url="' . esc_url((string) $item['view_url']) . '"' : ''; ?>>
                    <div class="sffc-crm-reddit-community-row">
                        <div class="sffc-crm-reddit-community-cell sffc-crm-reddit-community-cell--role">
                            <div class="sffc-crm-reddit-avatar-stack">
                                <div class="sffc-crm-reddit-avatar">
                                    <?php if (!empty($item['recruiter_photo'])) : ?>
                                        <img src="<?php echo esc_url($item['recruiter_photo']); ?>" alt="<?php echo esc_attr($recruiter_name); ?>">
                                    <?php else : ?>
                                        <span><?php echo esc_html($avatar_letter); ?></span>
                                    <?php endif; ?>
                                </div>
                                <div class="sffc-crm-reddit-company-badge">
                                    <?php if (!empty($item['company_logo'])) : ?>
                                        <img src="<?php echo esc_url($item['company_logo']); ?>" alt="<?php echo esc_attr((string) ($item['company'] ?? __('Company', 'senna-finance'))); ?>">
                                    <?php else : ?>
                                        <span><?php echo esc_html($company_letter); ?></span>
                                    <?php endif; ?>
                                </div>
                            </div>
                            <div class="sffc-crm-reddit-community-role-copy">
                                <h3 class="sffc-crm-reddit-community-role-title">
                                    <a href="<?php echo esc_url((string) $item['view_url']); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html((string) ($item['role_title'] ?? '')); ?></a>
                                </h3>
                                <div class="sffc-crm-reddit-community-role-meta">
