                                <?php if (!empty($mail_meta)) : ?>
                                    <div class="sffc-crm-reddit-community-role-tags">
                                        <?php foreach (array_slice($mail_meta, 0, 3) as $meta_item) : ?>
                                            <span><?php echo esc_html($meta_item); ?></span>
                                        <?php endforeach; ?>
