                                        <img src="<?php echo esc_url($item['recruiter_photo']); ?>" alt="<?php echo esc_attr($recruiter_name); ?>">
                                    <?php else : ?>
                                        <span><?php echo esc_html($avatar_letter); ?></span>
                                    <?php endif; ?>
                                </div>
                                <div class="sffc-crm-reddit-community-recruiter-copy">
                                    <strong><?php echo esc_html($recruiter_display_name); ?></strong>
                                    <?php if ($recruiter_company !== '') : ?>
                                        <span><?php echo esc_html($recruiter_company); ?></span>
                                    <?php endif; ?>
                                </div>
                            </div>
                        </div>

                        <div class="sffc-crm-reddit-community-cell sffc-crm-reddit-community-cell--status">
                            <span class="sffc-crm-reddit-community-cell-label"><?php esc_html_e('Status', 'senna-finance'); ?></span>
                            <div class="sffc-crm-reddit-community-status">
                                <span class="sffc-crm-reddit-card-mailbox-route sffc-crm-reddit-card-mailbox-route--<?php echo esc_attr($route_badge_tone); ?>"><?php echo esc_html($route_badge); ?></span>
                                <?php if ($posted_label !== '') : ?>
