        private function build_crm_reddit_community_dashboard_data(array $feed_items, array $sidebar_recruiters)
        {
            $total_roles = count($feed_items);
            $jobs_source_count = 0;
            $crm_source_count = 0;
            $direct_apply_count = 0;
            $job_page_count = 0;
            $location_counts = [];

            foreach ($feed_items as $feed_item) {
                if (($feed_item['source'] ?? '') === 'jobs') {
                    $jobs_source_count++;
                } else {
                    $crm_source_count++;
                }

                if (!empty($feed_item['view_url'])) {
                    $job_page_count++;
                }

                if (!empty($feed_item['apply_url'])) {
                    $direct_apply_count++;
                }

                $location = trim((string) ($feed_item['location'] ?? ''));
                if ($location !== '') {
                    $first_location = trim((string) strtok($location, ','));
                    $first_location = $first_location !== '' ? $first_location : $location;
                    $location_counts[$first_location] = (int) ($location_counts[$first_location] ?? 0) + 1;
                }
            }

            arsort($location_counts);
            $top_locations = [];
            $location_peak = !empty($location_counts) ? max($location_counts) : 1;
            foreach (array_slice($location_counts, 0, 4, true) as $label => $count) {
                $top_locations[] = [
                    'label' => $label,
                    'count' => sprintf(__('%d roles', 'senna-finance'), $count),
                    'percent' => $location_peak > 0 ? max(18, (int) round(($count / $location_peak) * 100)) : 18,
                ];
            }

            $apply_rate = $job_page_count > 0 ? (int) round(($direct_apply_count / $job_page_count) * 100) : 0;
            $source_total = max(1, $jobs_source_count + $crm_source_count);

            return [
                'apply_rate' => $apply_rate,
                'apply_angle' => max(18, min(360, (int) round(($apply_rate / 100) * 360))),
                'direct_apply_count' => $direct_apply_count,
                'coverage_note' => sprintf(
                    __('%d role pages are ready to open.', 'senna-finance'),
                    $job_page_count
                ),
                'source_note' => sprintf(
                    __('%d recruiters are currently active.', 'senna-finance'),
                    count($sidebar_recruiters)
                ),
                'market_note' => $top_locations ? sprintf(__('Top market: %s', 'senna-finance'), (string) $top_locations[0]['label']) : __('Markets updating live', 'senna-finance'),
                'source_bars' => [
                    [
                        'label' => __('Direct from jobs', 'senna-finance'),
                        'value' => sprintf(__('%d roles', 'senna-finance'), $jobs_source_count),
                        'percent' => $source_total > 0 ? (int) round(($jobs_source_count / $source_total) * 100) : 0,
                        'tone' => 'slate',
                    ],
                    [
                        'label' => __('Recruiter-led', 'senna-finance'),
                        'value' => sprintf(__('%d roles', 'senna-finance'), $crm_source_count),
                        'percent' => $source_total > 0 ? (int) round(($crm_source_count / $source_total) * 100) : 0,
                        'tone' => 'gold',
                    ],
                    [
                        'label' => __('Direct apply live', 'senna-finance'),
                        'value' => sprintf(__('%d roles', 'senna-finance'), $direct_apply_count),
                        'percent' => $total_roles > 0 ? (int) round(($direct_apply_count / $total_roles) * 100) : 0,
                        'tone' => 'green',
                    ],
                ],
                'top_locations' => $top_locations,
            ];
        }

        private function build_crm_reddit_dashboard_app_data(array $feed_items, $fallback_role = 'Investment Associate', array $metrics_source_items = [], $user_id = 0, array $resume_payload = [])
        {
            $user_id = (int) $user_id;
            $profile_hints = $user_id > 0 ? $this->get_crm_reddit_dashboard_profile_hints($user_id) : [
                'target_roles' => [],
                'target_locations' => [],
                'technical_skills' => [],
            ];
            $analysis_items = !empty($metrics_source_items) ? $metrics_source_items : $feed_items;
            $resume_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $has_resume = !empty($resume_payload['has_cv']) && $resume_text !== '';
            $cv_ats_payload = ($user_id > 0 && $has_resume)
                ? $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true)
                : [];
            $cv_role_signal = $has_resume ? $this->detect_crm_reddit_dashboard_cv_role_signal($resume_text, $analysis_items) : [];

            $role_label = trim((string) $fallback_role);
            $cv_profile_role_label = $this->get_crm_reddit_dashboard_primary_cv_role_label($cv_ats_payload);
            if ($cv_profile_role_label !== '') {
                $role_label = $cv_profile_role_label;
            } elseif (!empty($cv_role_signal['label'])) {
                $role_label = (string) $cv_role_signal['label'];
            } elseif (!empty($profile_hints['target_roles'][0])) {
                $role_label = (string) $profile_hints['target_roles'][0];
            } elseif ($role_label === '') {
                $role_label = 'Investment Associate';
            }

            $matched_items = $this->get_crm_reddit_dashboard_ranked_home_items(
                $analysis_items,
                $resume_text,
                $cv_ats_payload,
                $role_label
            );
            if (empty($matched_items)) {
                $matched_items = $this->get_crm_reddit_dashboard_app_role_matches($analysis_items, $role_label);
            }
            if (empty($matched_items)) {
                $matched_items = array_slice($analysis_items, 0, 18);
            }

            $role_keywords = [];
            $recruiters = [];
            $locations = [];
            $direct_companies = [];
            $recent_growth = [];
            $recent_roles = [];
            $salary_anchors = [];
            $now = current_time('timestamp');
            $recent_cutoff = $now - (45 * DAY_IN_SECONDS);
            $monthly_counts = [];
            $monthly_salary = [];
            $timeline_labels = [];

            for ($offset = 5; $offset >= 0; $offset--) {
                $bucket_time = strtotime("-{$offset} month", strtotime(date('Y-m-01 00:00:00', $now)));
                $bucket_key = date('Y-m', $bucket_time);
                $timeline_labels[] = date('M', $bucket_time);
                $monthly_counts[$bucket_key] = 0;
                $monthly_salary[$bucket_key] = [];
            }

            foreach ($matched_items as $item) {
                $company = trim((string) ($item['company'] ?? ''));
                $location = $this->get_crm_reddit_dashboard_app_location_label((string) ($item['location'] ?? ''));
                $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
                $is_recent = $posted_timestamp > 0 && $posted_timestamp >= $recent_cutoff;
                $keywords = array_values(array_filter(array_map('sanitize_text_field', (array) ($item['keywords'] ?? []))));

                foreach (array_slice($keywords, 0, 6) as $keyword) {
                    $keyword_key = trim((string) $keyword);
                    if ($keyword_key === '') {
                        continue;
                    }
                    $role_keywords[$keyword_key] = (int) ($role_keywords[$keyword_key] ?? 0) + 1;
                }

                $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
                if ($recruiter_name !== '') {
                    if (!isset($recruiters[$recruiter_name])) {
                        $recruiters[$recruiter_name] = [
                            'primary' => $recruiter_name,
                            'secondary' => trim((string) ($item['recruiter_title'] ?? '')),
                            'image' => (string) ($item['recruiter_photo'] ?? ''),
                            'initial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1)),
                            'count' => 0,
                        ];
                    }
                    $recruiters[$recruiter_name]['count']++;
                    if ($recruiters[$recruiter_name]['secondary'] === '' && !empty($item['recruiter_title'])) {
                        $recruiters[$recruiter_name]['secondary'] = trim((string) $item['recruiter_title']);
                    }
                }

                if ($location !== '') {
                    if (!isset($locations[$location])) {
                        $locations[$location] = ['count' => 0, 'recent' => 0, 'direct' => 0];
                    }
                    $locations[$location]['count']++;
                    if ($is_recent) {
                        $locations[$location]['recent']++;
                    }
                    if (!empty($item['apply_url'])) {
                        $locations[$location]['direct']++;
                    }
                }

                if ($company !== '' && !empty($item['apply_url'])) {
                    if (!isset($direct_companies[$company])) {
                        $direct_companies[$company] = [
                            'primary' => $company,
                            'secondary' => $location,
                            'count' => 0,
                        ];
                    }
                    $direct_companies[$company]['count']++;
                }

                if ($company !== '' && $is_recent) {
                    if (!isset($recent_growth[$company])) {
                        $recent_growth[$company] = [
                            'primary' => $company,
                            'secondary' => $location,
                            'count' => 0,
                        ];
                    }
                    $recent_growth[$company]['count']++;
                }

                $recent_roles[] = [
                    'primary' => (string) ($item['role_title'] ?? ''),
                    'secondary' => trim($company . ($location !== '' ? ' · ' . $location : '')),
                    'posted' => (string) ($item['posted_label'] ?? ''),
                ];

                $anchor = $this->extract_crm_reddit_single_job_salary_anchor((string) ($item['salary_text'] ?? ''));
                if ($anchor > 0) {
                    $salary_anchors[] = $anchor;
                }

                if ($posted_timestamp > 0) {
                    $bucket_key = date('Y-m', strtotime(date('Y-m-01 00:00:00', $posted_timestamp)));
                    if (array_key_exists($bucket_key, $monthly_counts)) {
                        $monthly_counts[$bucket_key]++;
                        if ($anchor > 0) {
                            $monthly_salary[$bucket_key][] = $anchor;
                        }
                    }
                }
            }

            uasort($recruiters, static function ($left, $right) {
                return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
            });
            uasort($locations, static function ($left, $right) {
                return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
            });
            uasort($direct_companies, static function ($left, $right) {
                return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
            });
            uasort($recent_growth, static function ($left, $right) {
                return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
            });
            arsort($role_keywords);

            $location_hints = $this->build_crm_reddit_dashboard_location_hints($resume_text, array_keys($locations), $cv_ats_payload);
            $skill_signal = $this->build_crm_reddit_dashboard_skills_in_demand_rows(
                $role_keywords,
                $resume_text,
                (array) ($profile_hints['technical_skills'] ?? [])
            );

            $primary_location = !empty($locations) ? (string) array_key_first($locations) : __('Global', 'senna-finance');
            $primary_location_data = (array) ($locations[$primary_location] ?? ['count' => 0, 'recent' => 0, 'direct' => 0]);
            $keyword_count = count($role_keywords);
            $matched_total = max(1, count($matched_items));
            $direct_total = count(array_filter($matched_items, static function ($item) {
                return !empty($item['apply_url']);
            }));
            $heuristic_ats_score = $this->clamp_crm_reddit_single_job_metric(
                44 + min(16, $keyword_count * 3) + min(18, $direct_total * 4) + min(14, (int) ($primary_location_data['recent'] ?? 0) * 5),
                41,
                89
            );
            $ats_score = !empty($cv_ats_payload['score'])
                ? max(35, min(95, (int) $cv_ats_payload['score']))
                : $heuristic_ats_score;

            $salary_average = !empty($salary_anchors) ? (int) round(array_sum($salary_anchors) / count($salary_anchors)) : 0;
            $salary_display = $salary_average > 0
                ? $this->format_crm_reddit_single_job_compact_salary($salary_average, 'USD')
                : __('Signals updating', 'senna-finance');

            $top_skill = !empty($role_keywords) ? (string) array_key_first($role_keywords) : __('Financial modelling', 'senna-finance');
            $recent_total = count(array_filter($matched_items, static function ($item) use ($recent_cutoff) {
                return (int) ($item['posted_timestamp'] ?? 0) >= $recent_cutoff;
            }));

            $count_series = array_values($monthly_counts);
            $salary_series = [];
            foreach ($monthly_salary as $values) {
                $salary_series[] = !empty($values) ? (int) round(array_sum($values) / count($values)) : 0;
            }
            if (count(array_filter($salary_series)) < 2 && count($salary_anchors) >= 2) {
                sort($salary_anchors);
                $chunks = array_chunk($salary_anchors, max(1, (int) ceil(count($salary_anchors) / 6)));
                $salary_series = [];
                foreach ($chunks as $chunk) {
                    $salary_series[] = (int) round(array_sum($chunk) / max(1, count($chunk)));
                }
                while (count($salary_series) < 6) {
                    array_unshift($salary_series, (int) ($salary_series[0] ?? 0));
                }
                $salary_series = array_slice($salary_series, -6);
            }

            $salary_trend = $this->get_crm_reddit_dashboard_app_series_status($salary_series, [
                'up' => __('Increasing', 'senna-finance'),
                'down' => __('Declining', 'senna-finance'),
                'flat' => __('Stable', 'senna-finance'),
            ]);
            $industry_trend = $this->get_crm_reddit_dashboard_app_series_status($count_series, [
                'up' => __('Positive outlook', 'senna-finance'),
                'down' => __('Negative', 'senna-finance'),
                'flat' => __('Stable', 'senna-finance'),
                'mixed' => __('Evolving', 'senna-finance'),
            ], true);
            $market_status = $this->get_crm_reddit_dashboard_app_market_status($matched_total, $recent_total, $direct_total);
            $location_trend_source = $locations;
            uasort($location_trend_source, static function ($left, $right) {
                $recent_compare = ((int) ($right['recent'] ?? 0)) <=> ((int) ($left['recent'] ?? 0));
                if ($recent_compare !== 0) {
                    return $recent_compare;
                }
                return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
            });
            $location_trend_rows = [];
            foreach (array_slice($location_trend_source, 0, 4, true) as $location_name => $location_data) {
                $location_trend_rows[] = [
                    'primary' => (string) $location_name,
                    'secondary' => sprintf(
                        __('%d recent openings · %d total roles', 'senna-finance'),
                        (int) ($location_data['recent'] ?? 0),
                        (int) ($location_data['count'] ?? 0)
                    ),
                    'initial' => strtoupper(function_exists('mb_substr') ? mb_substr((string) $location_name, 0, 1) : substr((string) $location_name, 0, 1)),
                ];
            }

            $cards = [
                [
                    'title' => __('Recruiters looking for your skills', 'senna-finance'),
                    'eyebrow' => __('Contacts', 'senna-finance'),
                    'status' => __('Live', 'senna-finance'),
                    'rows' => array_map(static function ($row) {
                        $secondary = trim((string) ($row['secondary'] ?? ''));
                        return [
                            'primary' => (string) ($row['primary'] ?? ''),
                            'secondary' => $secondary !== '' ? $secondary : __('Recruiter', 'senna-finance'),
                            'image' => (string) ($row['image'] ?? ''),
                            'initial' => (string) ($row['initial'] ?? '•'),
                        ];
                    }, array_slice(array_values($recruiters), 0, 3)),
                    'action' => __('View all', 'senna-finance'),
                    'url' => home_url('/community/'),
                ],
                [
                    'title' => __('Locations to consider', 'senna-finance'),
                    'eyebrow' => __('Markets', 'senna-finance'),
                    'status' => !empty($location_hints) ? __('CV-aware', 'senna-finance') : (!empty($profile_hints['target_locations']) ? __('Profile-aware', 'senna-finance') : __('Live', 'senna-finance')),
                    'rows' => $this->build_crm_reddit_dashboard_app_location_rows($locations, $location_hints),
                    'action' => __('View all', 'senna-finance'),
                    'url' => home_url('/community/'),
                ],
                [
                    'title' => __('Direct apply routes', 'senna-finance'),
                    'eyebrow' => __('Companies', 'senna-finance'),
                    'status' => __('Low friction', 'senna-finance'),
                    'rows' => $this->build_crm_reddit_dashboard_app_company_rows($direct_companies, __('Direct apply live', 'senna-finance')),
                    'action' => __('View all', 'senna-finance'),
                    'url' => home_url('/community/'),
                ],
                [
                    'title' => __('Hiring trends by location', 'senna-finance'),
                    'eyebrow' => __('Markets', 'senna-finance'),
                    'status' => __('Recent', 'senna-finance'),
                    'rows' => $location_trend_rows,
                    'action' => __('View all', 'senna-finance'),
                    'url' => home_url('/community/'),
                ],
                [
                    'title' => __('Hiring trends for your role', 'senna-finance'),
                    'eyebrow' => __('Roles', 'senna-finance'),
                    'status' => __('Updated', 'senna-finance'),
                    'rows' => array_map(static function ($row) {
                        return [
                            'primary' => (string) ($row['primary'] ?? ''),
                            'secondary' => trim((string) ($row['secondary'] ?? '') . ((string) ($row['posted'] ?? '') !== '' ? ' · ' . (string) $row['posted'] : '')),
                            'initial' => strtoupper(function_exists('mb_substr') ? mb_substr((string) ($row['primary'] ?? 'R'), 0, 1) : substr((string) ($row['primary'] ?? 'R'), 0, 1)),
                        ];
                    }, array_slice($recent_roles, 0, 3)),
