                'total_roles' => $matched_total,
            ];
        }

        private function build_crm_reddit_dashboard_app_insights(array $context)
        {
            return [];
        }

        private function maybe_queue_crm_reddit_dashboard_app_insights(array $context)
        {
            $user_id = (int) ($context['user_id'] ?? 0);
            $day_key = (string) ($context['_insights_day_key'] ?? $this->get_crm_reddit_dashboard_insights_day_key());
            $context_hash = (string) ($context['_insights_context_hash'] ?? $this->get_crm_reddit_dashboard_app_insights_context_hash($context));
            $queue_key = $this->get_crm_reddit_dashboard_insights_queue_key($user_id, $day_key, $context_hash);

            if ($user_id <= 0 || $day_key === '' || $context_hash === '' || $queue_key === '' || !$this->is_crm_reddit_dashboard_insights_table_ready()) {
                return;
            }

            if ($this->is_crm_reddit_dashboard_app_insights_payload($this->get_crm_reddit_dashboard_insights_payload($user_id, $day_key, $context_hash))) {
                return;
            }

            $lock_key = $queue_key . '_lock';
            if (get_transient($lock_key)) {
                return;
            }

            set_transient($lock_key, 1, 10 * MINUTE_IN_SECONDS);
            set_transient($queue_key . '_context', $context, 15 * MINUTE_IN_SECONDS);

            $scheduled = wp_next_scheduled('sffc_crm_reddit_generate_dashboard_insights', [$queue_key]);
            if (!$scheduled) {
                wp_schedule_single_event(time() + 15, 'sffc_crm_reddit_generate_dashboard_insights', [$queue_key]);
            }
        }

        public function generate_crm_reddit_dashboard_app_insights_cache($queue_key)
        {
            $queue_key = sanitize_key((string) $queue_key);
            if ($queue_key === '') {
                return;
            }

            $context = get_transient($queue_key . '_context');
            if (!is_array($context) || empty($context)) {
                delete_transient($queue_key . '_lock');
                return;
            }

            $user_id = (int) ($context['user_id'] ?? 0);
            $day_key = (string) ($context['_insights_day_key'] ?? $this->get_crm_reddit_dashboard_insights_day_key());
            $context_hash = (string) ($context['_insights_context_hash'] ?? $this->get_crm_reddit_dashboard_app_insights_context_hash($context));

            if ($user_id <= 0 || $day_key === '' || $context_hash === '' || !$this->is_crm_reddit_dashboard_insights_table_ready()) {
                delete_transient($queue_key . '_context');
                delete_transient($queue_key . '_lock');
                return;
            }

            if ($this->is_crm_reddit_dashboard_app_insights_payload($this->get_crm_reddit_dashboard_insights_payload($user_id, $day_key, $context_hash))) {
                delete_transient($queue_key . '_context');
                delete_transient($queue_key . '_lock');
                return;
            }

            $fallback = $this->build_crm_reddit_dashboard_app_insights_fallback($context);
            $claude = $this->call_crm_reddit_dashboard_app_insights_claude($context);
            $insights = $this->merge_crm_reddit_dashboard_app_insights($fallback, is_array($claude) ? $claude : []);
            $this->save_crm_reddit_dashboard_insights_payload(
                $user_id,
                $day_key,
                $context_hash,
                $insights,
                $context,
                !empty($claude['cards']) ? 'claude' : 'fallback',
                !empty($claude['cards']) ? 'generated' : 'fallback'
            );
            delete_transient($queue_key . '_context');
            delete_transient($queue_key . '_lock');
        }

        private function is_crm_reddit_dashboard_insights_table_ready($refresh = false)
        {
            static $ready = null;

            if (!$refresh && $ready !== null) {
                return $ready;
            }

            if (!$refresh) {
                $cached = get_transient('sffc_crm_dash_insights_table_ready');
                if ($cached !== false) {
                    $ready = (bool) $cached;
                    return $ready;
                }
            }

            global $wpdb;

            $table = $this->get_crm_reddit_dashboard_insights_table_name();
            $ready = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;
            set_transient('sffc_crm_dash_insights_table_ready', $ready ? 1 : 0, 15 * MINUTE_IN_SECONDS);

            return $ready;
        }

        private function get_crm_reddit_dashboard_insights_table_name()
        {
            global $wpdb;

            return $wpdb->prefix . 'sffc_crm_dashboard_insights';
        }

        private function get_crm_reddit_dashboard_insights_day_key()
        {
            return wp_date('Y-m-d', current_time('timestamp'));
        }

        private function get_crm_reddit_dashboard_app_insights_context_hash(array $context)
        {
            return md5(wp_json_encode([
                'role' => (string) ($context['role_label'] ?? ''),
                'items' => array_map(static function ($item) {
                    return [
                        'post_id' => (int) ($item['post_id'] ?? 0),
                        'crm_post_id' => (int) ($item['crm_post_id'] ?? 0),
                        'posted' => (int) ($item['posted_timestamp'] ?? 0),
                        'sector' => (string) ($item['sector'] ?? ''),
                        'location' => (string) ($item['location'] ?? ''),
                        'salary' => (string) ($item['salary_text'] ?? ''),
                    ];
                }, (array) ($context['items'] ?? [])),
            ]));
        }

        private function get_crm_reddit_dashboard_insights_queue_key($user_id, $day_key, $context_hash)
        {
            $user_id = (int) $user_id;
            $day_key = trim((string) $day_key);
            $context_hash = trim((string) $context_hash);

            if ($user_id <= 0 || $day_key === '' || $context_hash === '') {
                return '';
            }

            return 'sffc_crm_dash_insights_job_' . md5($user_id . '|' . $day_key . '|' . $context_hash);
        }

        private function get_crm_reddit_dashboard_insights_payload($user_id, $day_key, $context_hash)
        {
            $user_id = (int) $user_id;
            $day_key = trim((string) $day_key);
            $context_hash = trim((string) $context_hash);
            if ($user_id <= 0 || $day_key === '' || $context_hash === '' || !$this->is_crm_reddit_dashboard_insights_table_ready()) {
                return null;
            }

            global $wpdb;

            $table = $this->get_crm_reddit_dashboard_insights_table_name();
            $payload_json = $wpdb->get_var($wpdb->prepare(
                "SELECT payload
                 FROM {$table}
                 WHERE user_id = %d
                   AND day_key = %s
                   AND context_hash = %s
                 ORDER BY id DESC
                 LIMIT 1",
                $user_id,
                $day_key,
                $context_hash
            ));

            if (!is_string($payload_json) || $payload_json === '') {
                return null;
            }

            $payload = json_decode($payload_json, true);
            $payload = $this->sanitize_crm_reddit_dashboard_app_insights_payload($payload);

            return $this->is_crm_reddit_dashboard_app_insights_payload($payload) ? $payload : null;
        }

        private function save_crm_reddit_dashboard_insights_payload($user_id, $day_key, $context_hash, array $payload, array $context = [], $source = 'claude', $status = 'generated')
        {
            $user_id = (int) $user_id;
            $day_key = trim((string) $day_key);
            $context_hash = trim((string) $context_hash);
            $payload = $this->sanitize_crm_reddit_dashboard_app_insights_payload($payload);
            if ($user_id <= 0 || $day_key === '' || $context_hash === '' || !$this->is_crm_reddit_dashboard_app_insights_payload($payload) || !$this->is_crm_reddit_dashboard_insights_table_ready()) {
                return false;
            }

            global $wpdb;

            $result = $wpdb->replace(
                $this->get_crm_reddit_dashboard_insights_table_name(),
                [
                    'user_id' => $user_id,
                    'day_key' => $day_key,
                    'context_hash' => $context_hash,
                    'role_label' => sanitize_text_field((string) ($context['role_label'] ?? '')),
                    'payload' => wp_json_encode($payload),
                    'source' => sanitize_key((string) $source),
                    'status' => sanitize_key((string) $status),
                    'generated_at' => current_time('mysql'),
                ],
                ['%d', '%s', '%s', '%s', '%s', '%s', '%s', '%s']
            );

            return $result !== false;
        }

        private function build_crm_reddit_dashboard_app_insights_fallback(array $context)
        {
            $role_label = (string) ($context['role_label'] ?? __('Investment Associate', 'senna-finance'));
            $top_skill = (string) ($context['top_skill'] ?? __('Financial modelling', 'senna-finance'));
            $keyword_count = (int) ($context['keyword_count'] ?? 0);
            $ats_score = (int) ($context['ats_score'] ?? 0);
            $ats_series = $this->normalize_crm_reddit_dashboard_app_chart_series((array) ($context['ats_series'] ?? []));
            $matched_total = max(1, (int) ($context['matched_total'] ?? 0));

            return [
                [
                    'title' => __('CV ATS Score', 'senna-finance'),
                    'subtitle' => __('Readiness against active openings', 'senna-finance'),
                    'icon' => '◉',
                    'tone' => 'ats',
                    'primary' => [
                        'label' => __('Current score', 'senna-finance'),
                        'value' => sprintf(__('%d%%', 'senna-finance'), $ats_score),
                        'delta_label' => $ats_score >= 75 ? __('Recruiter-ready', 'senna-finance') : __('Needs tightening', 'senna-finance'),
                        'delta_tone' => $ats_score >= 75 ? 'positive' : 'caution',
                        'points' => $this->build_crm_reddit_dashboard_app_sparkline_points($ats_series, 180, 54, 4),
                        'area' => $this->build_crm_reddit_dashboard_app_sparkline_area($ats_series, 180, 54, 4),
                    ],
                    'secondary' => [
                        'label' => __('Top recruiter ask', 'senna-finance'),
                        'value' => $top_skill,
                        'note' => sprintf(__('%d skill signals across %d live openings', 'senna-finance'), max(1, $keyword_count), $matched_total),
                    ],
                    'note' => sprintf(__('Role-fit language is strongest when %s is visible early and the CV mirrors the language used across active %s openings.', 'senna-finance'), $top_skill, $role_label),
                    'action_label' => __('Re-scan', 'senna-finance'),
                    'action_url' => home_url('/terminal/?tab=console'),
                ],
            ];
        }

        private function call_crm_reddit_dashboard_app_insights_claude(array $context)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 2400,
                'temperature' => 0.1,
                'system' => $this->get_crm_reddit_dashboard_app_insights_system_prompt(),
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => $this->build_crm_reddit_dashboard_app_insights_user_prompt($context),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit Dashboard Insights Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);

            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit Dashboard Insights Claude Error: status ' . $status);
                return null;
            }

            $decoded = json_decode((string) $body['content'][0]['text'], true);
            if (!is_array($decoded)) {
                error_log('Reddit Dashboard Insights Claude Parse Error: ' . json_last_error_msg());
                return null;
            }

            return $decoded;
        }

        private function get_crm_reddit_dashboard_app_insights_system_prompt()
        {
            return 'You are MENA Careers’s dashboard intelligence analyst for private equity hiring data.

CRITICAL INSTRUCTIONS:
1. Respond with ONLY valid JSON. No markdown, no commentary, no code fences.
2. Start with { and end with }.
3. Use the supplied platform metrics and role context as the primary source.
4. Do not invent counts, sectors, or market signals not implied by the data.
5. Keep chart_series arrays at exactly 6 integers between 8 and 100, derived from the supplied series data.
6. Keep copy concise, operational, and commercially useful.
7. Return this exact shape:
{
  "cards": {
    "ats_score": {
      "title": "string",
      "subtitle": "string",
      "primary_label": "string",
      "primary_value": "string",
      "delta_label": "string",
      "delta_tone": "positive|negative|caution|neutral",
      "chart_series": [0,0,0,0,0,0],
      "secondary_label": "string",
      "secondary_value": "string",
      "secondary_note": "string",
      "note": "string",
      "action_label": "string"
    }
  }
}';
        }

        private function build_crm_reddit_dashboard_app_insights_user_prompt(array $context)
        {
            return wp_json_encode([
                'role_label' => (string) ($context['role_label'] ?? ''),
                'top_skill' => (string) ($context['top_skill'] ?? ''),
                'platform_summary' => [
                    'matched_total' => (int) ($context['matched_total'] ?? 0),
                    'keyword_count' => (int) ($context['keyword_count'] ?? 0),
                    'ats_score' => (int) ($context['ats_score'] ?? 0),
                ],
                'series' => [
                    'timeline_labels' => array_values((array) ($context['timeline_labels'] ?? [])),
                    'ats_series' => array_values((array) ($context['ats_series'] ?? [])),
                ],
                'instruction' => 'Use the supplied platform metrics as the main source and return only the ats_score card.',
            ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }

        private function merge_crm_reddit_dashboard_app_insights(array $fallback, array $claude)
        {
            if (empty($claude['cards']) || !is_array($claude['cards'])) {
                return $fallback;
            }

            $card_map = [0 => 'ats_score'];

            foreach ($card_map as $index => $card_key) {
                if (empty($fallback[$index]) || empty($claude['cards'][$card_key]) || !is_array($claude['cards'][$card_key])) {
                    continue;
                }

                $card = $claude['cards'][$card_key];
                foreach (['title', 'subtitle', 'note'] as $field) {
                    if (!empty($card[$field])) {
                        $fallback[$index][$field] = trim((string) $card[$field]);
                    }
                }
                if (!empty($card['action_label'])) {
                    $fallback[$index]['action_label'] = trim((string) $card['action_label']);
                }

                $series = $this->normalize_crm_reddit_dashboard_app_chart_series((array) ($card['chart_series'] ?? []));
                if (!empty($series)) {
                    $fallback[$index]['primary']['points'] = $this->build_crm_reddit_dashboard_app_sparkline_points($series, 180, 54, 4);
                    $fallback[$index]['primary']['area'] = $this->build_crm_reddit_dashboard_app_sparkline_area($series, 180, 54, 4);
                    unset($fallback[$index]['primary']['bars']);
                }

                $fallback[$index]['primary']['label'] = !empty($card['primary_label']) ? trim((string) $card['primary_label']) : $fallback[$index]['primary']['label'];
                $fallback[$index]['primary']['value'] = !empty($card['primary_value']) ? trim((string) $card['primary_value']) : $fallback[$index]['primary']['value'];
                $fallback[$index]['primary']['delta_label'] = !empty($card['delta_label']) ? trim((string) $card['delta_label']) : $fallback[$index]['primary']['delta_label'];
                $fallback[$index]['primary']['delta_tone'] = !empty($card['delta_tone']) ? trim((string) $card['delta_tone']) : $fallback[$index]['primary']['delta_tone'];

                $fallback[$index]['secondary']['label'] = !empty($card['secondary_label']) ? trim((string) $card['secondary_label']) : $fallback[$index]['secondary']['label'];
                $fallback[$index]['secondary']['value'] = !empty($card['secondary_value']) ? trim((string) $card['secondary_value']) : $fallback[$index]['secondary']['value'];
                $fallback[$index]['secondary']['note'] = !empty($card['secondary_note']) ? trim((string) $card['secondary_note']) : $fallback[$index]['secondary']['note'];
            }

            return $fallback;
        }

        private function is_crm_reddit_dashboard_app_insights_payload($payload)
        {
            return is_array($payload) && count($payload) >= 1 && !empty($payload[0]['primary']['value']);
        }

        private function sanitize_crm_reddit_dashboard_app_insights_payload($payload)
        {
            if (!is_array($payload) || empty($payload)) {
                return null;
            }

            $filtered = array_values(array_filter($payload, static function ($card) {
                return is_array($card) && ((string) ($card['tone'] ?? '') === 'ats' || (string) ($card['title'] ?? '') === __('CV ATS Score', 'senna-finance'));
            }));

            if (empty($filtered) && !empty($payload[0]) && is_array($payload[0])) {
                $filtered = [$payload[0]];
            }

            return !empty($filtered) ? array_slice($filtered, 0, 1) : null;
        }

        private function normalize_crm_reddit_dashboard_app_chart_series(array $series)
        {
            $series = array_values(array_filter(array_map('intval', $series), static function ($value) {
                return $value >= 0;
            }));

            if (empty($series)) {
                return [];
            }

            while (count($series) < 6) {
                $series[] = (int) end($series);
            }

            $series = array_slice($series, -6);

            return array_map(static function ($value) {
                return max(8, min(100, (int) $value));
            }, $series);
        }

        private function build_crm_reddit_dashboard_app_ats_series(array $count_series, $direct_total, $matched_total, $ats_score)
        {
            $matched_total = max(1, (int) $matched_total);
            $direct_ratio = (int) round(((int) $direct_total / $matched_total) * 100);
            $series = [];
            foreach ((array) $count_series as $index => $count) {
                $count = (int) $count;
                $volume_factor = max(28, min(100, $count * 9));
                $step_penalty = max(0, (count($count_series) - $index - 1) * 3);
                $series[] = max(18, min(100, (int) round(($volume_factor * 0.7) + ($direct_ratio * 0.3) - $step_penalty)));
            }
            if (!empty($series)) {
                $series[count($series) - 1] = max(8, min(100, (int) $ats_score));
            }
            return $this->normalize_crm_reddit_dashboard_app_chart_series($series);
        }

        private function build_crm_reddit_dashboard_app_market_series(array $count_series, $matched_total, $recent_total, $direct_total)
        {
            $matched_total = max(1, (int) $matched_total);
            $recent_ratio = (int) round(((int) $recent_total / $matched_total) * 100);
            $direct_ratio = (int) round(((int) $direct_total / $matched_total) * 100);
            $series = [];
            foreach ((array) $count_series as $count) {
                $count = (int) $count;
                $volume_factor = max(22, min(100, $count * 10));
                $series[] = max(18, min(100, (int) round(($volume_factor * 0.45) + ($recent_ratio * 0.3) + ($direct_ratio * 0.25))));
            }
            return $this->normalize_crm_reddit_dashboard_app_chart_series($series);
        }

        private function get_crm_reddit_dashboard_app_top_industry(array $items)
        {
            $industry_counts = [];
            foreach ($items as $item) {
                $industry = $this->format_crm_reddit_dashboard_industry_label((string) ($item['sector'] ?? ''));
                if ($industry === '') {
                    continue;
                }
                $industry_counts[$industry] = (int) ($industry_counts[$industry] ?? 0) + 1;
            }
            if (empty($industry_counts)) {
                return '';
            }
            arsort($industry_counts);
            return (string) array_key_first($industry_counts);
        }

        private function build_crm_reddit_dashboard_app_industry_series(array $items, $target_industry)
        {
            $target_industry = trim((string) $target_industry);
            if ($target_industry === '') {
                return [];
            }

            $series = array_fill(0, 6, 0);
            $now = current_time('timestamp');
            $bucket_map = [];
            for ($offset = 5; $offset >= 0; $offset--) {
                $bucket_time = strtotime("-{$offset} month", strtotime(date('Y-m-01 00:00:00', $now)));
                $bucket_map[date('Y-m', $bucket_time)] = 5 - $offset;
            }

            foreach ($items as $item) {
                $industry = $this->format_crm_reddit_dashboard_industry_label((string) ($item['sector'] ?? ''));
                if ($industry !== $target_industry) {
                    continue;
                }
                $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
                if ($posted_timestamp <= 0) {
                    continue;
                }
                $bucket_key = date('Y-m', strtotime(date('Y-m-01 00:00:00', $posted_timestamp)));
                if (isset($bucket_map[$bucket_key])) {
                    $series[(int) $bucket_map[$bucket_key]]++;
                }
            }

            return $series;
        }

        private function format_crm_reddit_dashboard_industry_label($sector)
        {
            $sector = sanitize_key((string) $sector);
            if ($sector === '') {
                return '';
            }

            $map = [
                'pe' => __('Finance', 'senna-finance'),
                'ib' => __('Investment Banking', 'senna-finance'),
                'vc' => __('Venture Capital', 'senna-finance'),
                'asset_management' => __('Asset Management', 'senna-finance'),
                'private_credit' => __('Private Credit', 'senna-finance'),
                'family_office' => __('Family Office', 'senna-finance'),
                'consulting' => __('Consulting', 'senna-finance'),
                'corporate' => __('Portfolio Operations', 'senna-finance'),
                'fintech' => __('FinTech', 'senna-finance'),
                'real_estate' => __('Real Estate', 'senna-finance'),
                'hedge_fund' => __('Hedge Fund', 'senna-finance'),
                'investment_management' => __('Investment Management', 'senna-finance'),
            ];

            if (isset($map[$sector])) {
                return (string) $map[$sector];
            }

            return ucwords(str_replace(['_', '-'], ' ', $sector));
        }

        private function get_crm_reddit_dashboard_stage_tag_color($stage)
        {
            $stage = sanitize_key((string) $stage);
            $green_stages = ['interested', 'telephone_interview', 'video_interview', 'face_to_face_interview', 'offer_received'];
            $purple_stages = ['application_submitted', 'messaged', 'follow_up', 'assessment_centre'];
            $yellow_stages = ['not_applied', 'online_assessment', 'case_study', 'hirevue', 'not_interested', 'rejected'];

            if ($stage === '') {
                return '#7c3aed';
            }

            if (in_array($stage, $green_stages, true)) {
                return '#16a34a';
            }

            if (in_array($stage, $purple_stages, true)) {
                return '#7c3aed';
            }

            if (in_array($stage, $yellow_stages, true)) {
                return '#b45309';
            }

            return '#16a34a';
        }

        private function build_crm_reddit_dashboard_matches_view(array $feed_items, $search_term = '', $cv_text = '', $has_cv = false, $matches_filter = 'highest-match', $current_url = '', $matches_page = 1, array $metric_items = [], $metrics_window = 'month')
        {
            global $wpdb;

            $rows = [];
            $seen = [];
            $raw_cv_text = (string) $cv_text;
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $has_cv = (bool) $has_cv && $cv_text !== '';
            $cv_profile = ($has_cv && is_user_logged_in())
                ? $this->get_crm_reddit_cv_ats_scan_payload(get_current_user_id(), ['cv_text' => $raw_cv_text, 'has_cv' => true], true)
                : [];
            $matches_filter = sanitize_key((string) $matches_filter);
            $matches_page = max(1, (int) $matches_page);
            $metrics_window = sanitize_key((string) $metrics_window);
            if (!in_array($metrics_window, ['week', 'two-weeks', 'month'], true)) {
                $metrics_window = 'month';
            }
            $batch_size = 12;
            $stage_meta = class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [];
            $pipeline_lookup = [];
            $pipeline_lookup_by_identity = [];

            if (is_user_logged_in()) {
                $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
                $pipeline_rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT id, post_id, stage, role_title, company, external_url, recruiter_id, updated_at, stage_entered_at
                     FROM {$pipeline_table}
                     WHERE user_id = %d
                     ORDER BY updated_at DESC, stage_entered_at DESC, id DESC",
                    get_current_user_id()
                ), ARRAY_A);

                foreach ((array) $pipeline_rows as $pipeline_row) {
                    $post_id = (int) ($pipeline_row['post_id'] ?? 0);
                    if ($post_id > 0 && !isset($pipeline_lookup[$post_id])) {
                        $pipeline_lookup[$post_id] = $pipeline_row;
                    }

                    $identity_key = $this->get_crm_reddit_dashboard_pipeline_identity_key(
                        (string) ($pipeline_row['role_title'] ?? ''),
                        (string) ($pipeline_row['company'] ?? ''),
                        (string) ($pipeline_row['location'] ?? ''),
                        (string) ($pipeline_row['external_url'] ?? '')
                    );
                    if ($identity_key !== '' && !isset($pipeline_lookup_by_identity[$identity_key])) {
                        $pipeline_lookup_by_identity[$identity_key] = $pipeline_row;
                    }
                }
            }

            foreach ($feed_items as $index => $item) {
                $dedupe_key = $this->get_crm_reddit_dashboard_match_dedupe_key((array) $item);
                if ($dedupe_key === '' || isset($seen[$dedupe_key])) {
                    continue;
                }
                $seen[$dedupe_key] = true;

                $view_url = $this->resolve_crm_reddit_dashboard_item_view_url((array) $item);
                if ($view_url === '') {
                    continue;
                }

                $company = trim((string) ($item['company'] ?? ''));
                $location = $this->get_crm_reddit_dashboard_app_location_label((string) ($item['location'] ?? ''));
                $match_score = $has_cv ? $this->build_crm_reddit_dashboard_match_score((array) $item, $cv_text, $cv_profile) : 0;
                $match_label = $has_cv ? sprintf(__('%d%%', 'senna-finance'), $match_score) : __('Upload CV', 'senna-finance');
                $match_tone = !$has_cv ? 'caution' : ($match_score >= 75 ? 'positive' : ($match_score >= 60 ? 'neutral' : 'caution'));
                $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
                $pipeline_item = $crm_post_id > 0 && isset($pipeline_lookup[$crm_post_id]) ? $pipeline_lookup[$crm_post_id] : null;
                if (!$pipeline_item) {
                    $pipeline_identity_key = $this->get_crm_reddit_dashboard_pipeline_identity_key(
                        (string) ($item['role_title'] ?? ''),
                        $company,
                        (string) ($item['location'] ?? ''),
                        (string) ($item['apply_url'] ?? '')
                    );
                    if ($pipeline_identity_key !== '' && isset($pipeline_lookup_by_identity[$pipeline_identity_key])) {
                        $pipeline_item = $pipeline_lookup_by_identity[$pipeline_identity_key];
                    }
                }
                $pipeline_stage = (string) ($pipeline_item['stage'] ?? '');
                $pipeline_stage_label = $pipeline_stage !== '' && isset($stage_meta[$pipeline_stage]['label'])
                    ? (string) $stage_meta[$pipeline_stage]['label']
                    : __('Not tracked yet', 'senna-finance');
                $pipeline_stage_color = $pipeline_stage !== '' && isset($stage_meta[$pipeline_stage]['color'])
                    ? (string) $stage_meta[$pipeline_stage]['color']
                    : '#cbd5e1';
                $pipeline_stage_color = $this->get_crm_reddit_dashboard_stage_tag_color($pipeline_stage);

                $rows[] = [
                    'feed_order' => $index,
                    'role_title' => (string) ($item['role_title'] ?? ''),
                    'company' => $company !== '' ? $company : __('Stealth employer', 'senna-finance'),
                    'company_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($company !== '' ? $company : 'S', 0, 1) : substr($company !== '' ? $company : 'S', 0, 1)),
                    'logo' => (string) ($item['company_logo'] ?? ''),
                    'recruiter_name' => (string) ($item['recruiter_name'] ?? __('Hiring Team', 'senna-finance')),
                    'recruiter_title' => (string) ($item['recruiter_title'] ?? __('Recruiter', 'senna-finance')),
                    'recruiter_photo' => (string) ($item['recruiter_photo'] ?? ''),
                    'recruiter_initial' => strtoupper(function_exists('mb_substr') ? mb_substr((string) ($item['recruiter_name'] ?? 'R'), 0, 1) : substr((string) ($item['recruiter_name'] ?? 'R'), 0, 1)),
                    'recruiter_email' => sanitize_email((string) ($item['recruiter_email'] ?? '')),
                    'recruiter_linkedin' => esc_url_raw((string) ($item['recruiter_linkedin'] ?? '')),
                    'location' => $location !== '' ? $location : __('Global', 'senna-finance'),
                    'match_label' => $match_label,
                    'match_tone' => $match_tone,
                    'match_score' => $match_score,
                    'posted_label' => (string) ($item['posted_label'] ?? __('Recently added', 'senna-finance')),
                    'posted_timestamp' => (int) ($item['posted_timestamp'] ?? 0),
                    'industry' => $this->get_crm_reddit_dashboard_match_industry_label((array) $item),
                    'is_direct' => !empty($item['apply_url']),
                    'has_jobs_post' => !empty($item['wp_post_id']) || (string) ($item['source'] ?? '') === 'jobs',
                    'view_url' => $view_url,
                    'crm_post_id' => $crm_post_id,
                    'wp_post_id' => (int) ($item['wp_post_id'] ?? 0),
                    'recruiter_id' => (int) ($item['recruiter_id'] ?? 0),
                    'pipeline_id' => (int) ($pipeline_item['id'] ?? 0),
                    'pipeline_stage' => $pipeline_stage,
                    'pipeline_stage_label' => $pipeline_stage_label,
                    'pipeline_stage_color' => $pipeline_stage_color,
                    'external_url' => (string) ($item['apply_url'] ?? ''),
                ];
            }

            if ($search_term !== '') {
                $needle = function_exists('mb_strtolower') ? mb_strtolower($search_term) : strtolower($search_term);
                $rows = array_values(array_filter($rows, static function ($row) use ($needle) {
                    $haystack = implode(' ', [
                        (string) ($row['role_title'] ?? ''),
                        (string) ($row['company'] ?? ''),
                        (string) ($row['recruiter_name'] ?? ''),
                        (string) ($row['location'] ?? ''),
                    ]);
                    $haystack = function_exists('mb_strtolower') ? mb_strtolower($haystack) : strtolower($haystack);
                    return strpos($haystack, $needle) !== false;
                }));
            }

            $recent_sort = static function ($left, $right) {
                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
            };

            if ($matches_filter === 'recently-posted') {
                usort($rows, $recent_sort);
            } elseif ($matches_filter === 'highest-match' && $has_cv) {
                usort($rows, static function ($left, $right) {
                    $score_compare = ((int) ($right['match_score'] ?? 0)) <=> ((int) ($left['match_score'] ?? 0));
                    if ($score_compare !== 0) {
                        return $score_compare;
                    }
                    return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
                });
            } else {
                usort($rows, $recent_sort);

                if ($has_cv) {
                    $strong_rows = array_values(array_filter($rows, static function ($row) {
                        return ((int) ($row['match_score'] ?? 0)) >= 58;
                    }));
                    $other_rows = array_values(array_filter($rows, static function ($row) {
                        return ((int) ($row['match_score'] ?? 0)) < 58;
                    }));
                    $rows = array_merge($strong_rows, $other_rows);

                    $seed_parts = [
                        (string) get_current_user_id(),
                        (string) current_time('Y-m-d'),
                        (string) $matches_filter,
                        (string) $search_term,
                    ];
                    $seed = md5(implode('|', $seed_parts));
                    $chunked_rows = [];
                    foreach (array_chunk($rows, $batch_size) as $batch) {
                        usort($batch, static function ($left, $right) use ($seed) {
                            $left_key = (string) ($left['view_url'] ?? '') . '|' . (string) ($left['role_title'] ?? '');
                            $right_key = (string) ($right['view_url'] ?? '') . '|' . (string) ($right['role_title'] ?? '');
                            $left_rank = sprintf('%u', crc32($seed . '|' . $left_key));
                            $right_rank = sprintf('%u', crc32($seed . '|' . $right_key));
                            if ($left_rank === $right_rank) {
                                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
                            }
                            return $left_rank <=> $right_rank;
                        });
                        $chunked_rows = array_merge($chunked_rows, $batch);
                    }
                    $rows = $chunked_rows;
                }
            }

            $total_rows = count($rows);
            $offset = ($matches_page - 1) * $batch_size;
            $display_rows = array_slice($rows, $offset, $batch_size);
            $has_more = ($offset + $batch_size) < $total_rows;

            $query_base = [
                'dashboard_tab' => 'recruiter-matches',
                'matches_filter' => $matches_filter,
                'sffc_reddit_search' => $search_term,
            ];

            $filters = [
                [
                    'label' => __('Live Feed', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'recruiter-matches', 'matches_filter' => 'live-feed', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'live-feed',
                ],
                [
                    'label' => __('Recently Posted', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'recruiter-matches', 'matches_filter' => 'recently-posted', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'recently-posted',
                ],
                [
                    'label' => __('Best Contact Fit', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'recruiter-matches', 'matches_filter' => 'highest-match', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'highest-match',
                ],
            ];
            $window_options = [
                'week' => __('Past week', 'senna-finance'),
                'two-weeks' => __('Past two weeks', 'senna-finance'),
                'month' => __('Past month', 'senna-finance'),
            ];
            $windows = [];
            foreach ($window_options as $window_key => $window_label) {
                $windows[] = [
                    'label' => $window_label,
                    'url' => add_query_arg(['dashboard_tab' => 'recruiter-matches', 'matches_filter' => $matches_filter, 'metrics_window' => $window_key, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $metrics_window === $window_key,
                ];
            }

            $summary_cards = $this->build_crm_reddit_dashboard_matches_summary_cards(!empty($metric_items) ? $metric_items : $rows, $metrics_window, $search_term);

            return [
                'rows' => $display_rows,
                'total' => $total_rows,
                'page' => $matches_page,
                'has_more' => $has_more,
                'next_url' => $has_more ? add_query_arg(array_merge($query_base, ['metrics_window' => $metrics_window, 'matches_page' => $matches_page + 1]), $current_url !== '' ? $current_url : home_url('/community/')) : '',
                'filters' => $filters,
                'windows' => $windows,
                'summary' => $summary_cards,
            ];
        }

        private function build_crm_reddit_dashboard_matches_summary_cards(array $rows, $metrics_window = 'month', $search_term = '')
        {
            $metrics_window = sanitize_key((string) $metrics_window);
            $window_days = 30;
            if ($metrics_window === 'week') {
                $window_days = 7;
            } elseif ($metrics_window === 'two-weeks') {
                $window_days = 14;
            }

            $today = strtotime(date('Y-m-d 00:00:00', current_time('timestamp')));
            $day_buckets = [];
            for ($offset = ($window_days * 2) - 1; $offset >= 0; $offset--) {
                $bucket_time = strtotime("-{$offset} days", $today);
                $bucket_key = date('Y-m-d', $bucket_time);
                $day_buckets[$bucket_key] = [
                    'posts' => 0,
                    'locations' => [],
                    'industries' => [],
                ];
            }

            $top_location = '';
            $top_location_count = 0;
            $second_location = '';
            $second_location_count = 0;
            $top_industry = '';
            $top_industry_count = 0;
            $second_industry = '';
            $second_industry_count = 0;
            $location_totals = [];
            $industry_totals = [];
            $today_posts = 0;
            $week_posts = 0;

            foreach ($rows as $row) {
                $row = (array) $row;
                $posted_timestamp = (int) ($row['posted_timestamp'] ?? 0);
                if ($posted_timestamp <= 0 && !empty($row['posted_at'])) {
                    $posted_timestamp = strtotime((string) $row['posted_at']);
                }
                if ($posted_timestamp <= 0) {
                    continue;
                }

                $bucket_key = date('Y-m-d', strtotime(date('Y-m-d 00:00:00', $posted_timestamp)));
                if (!isset($day_buckets[$bucket_key])) {
                    continue;
                }

                $day_buckets[$bucket_key]['posts']++;
                $week_posts++;
                if ($bucket_key === date('Y-m-d', $today)) {
                    $today_posts++;
                }

                $location = $this->get_crm_reddit_dashboard_app_location_label((string) ($row['location'] ?? ''));
                if ($location !== '') {
                    $day_buckets[$bucket_key]['locations'][$location] = (int) ($day_buckets[$bucket_key]['locations'][$location] ?? 0) + 1;
                    $location_totals[$location] = (int) ($location_totals[$location] ?? 0) + 1;
                }

                $industry = trim((string) ($row['industry'] ?? ''));
                if ($industry === '') {
                    foreach (['sector', 'specialisation', 'specialization', 'recruiter_specializations'] as $industry_field) {
                        if (!empty($row[$industry_field])) {
                            $industry = $this->format_crm_reddit_dashboard_match_industry_name((string) $row[$industry_field]);
                            if ($industry !== '') {
                                break;
                            }
                        }
                    }
                }
                if ($industry !== '') {
                    $day_buckets[$bucket_key]['industries'][$industry] = (int) ($day_buckets[$bucket_key]['industries'][$industry] ?? 0) + 1;
                    $industry_totals[$industry] = (int) ($industry_totals[$industry] ?? 0) + 1;
                }
            }

            arsort($location_totals);
            $location_names = array_keys($location_totals);
            $top_location = (string) ($location_names[0] ?? __('No signal', 'senna-finance'));
            $top_location_count = (int) ($location_totals[$top_location] ?? 0);
            $second_location = (string) ($location_names[1] ?? __('No runner-up', 'senna-finance'));
            $second_location_count = (int) ($location_totals[$second_location] ?? 0);

            arsort($industry_totals);
            $industry_names = array_keys($industry_totals);
            $top_industry = (string) ($industry_names[0] ?? __('Financial Services', 'senna-finance'));
            $top_industry_count = (int) ($industry_totals[$top_industry] ?? 0);
            $second_industry = (string) ($industry_names[1] ?? __('No runner-up', 'senna-finance'));
            $second_industry_count = (int) ($industry_totals[$second_industry] ?? 0);

            $post_series = [];
            $top_location_series = [];
            $top_industry_series = [];
            $ordered_bucket_keys = array_keys($day_buckets);
            foreach ($ordered_bucket_keys as $bucket_key) {
                $post_series[] = (int) ($day_buckets[$bucket_key]['posts'] ?? 0);
                $top_location_series[] = $top_location !== '' ? (int) ($day_buckets[$bucket_key]['locations'][$top_location] ?? 0) : 0;
                $top_industry_series[] = $top_industry !== '' ? (int) ($day_buckets[$bucket_key]['industries'][$top_industry] ?? 0) : 0;
            }

            $recent_post_total = array_sum(array_slice($post_series, -$window_days));
            $previous_post_total = array_sum(array_slice($post_series, 0, $window_days));
            $post_delta = $this->format_crm_reddit_dashboard_metric_delta($recent_post_total, $previous_post_total);
            $location_delta = $this->format_crm_reddit_dashboard_metric_delta(
                array_sum(array_slice($top_location_series, -$window_days)),
                array_sum(array_slice($top_location_series, 0, $window_days))
            );
            $industry_delta = $this->format_crm_reddit_dashboard_metric_delta(
                array_sum(array_slice($top_industry_series, -$window_days)),
                array_sum(array_slice($top_industry_series, 0, $window_days))
            );

            $news_card = $this->build_crm_reddit_dashboard_market_news_metric($window_days, (string) $search_term);

            return [
                $news_card,
                [
                    'title' => __('Trending Area', 'senna-finance'),
                    'primary' => [
                        'label' => __('Top market', 'senna-finance'),
                        'value' => $top_location,
                        'delta_label' => $location_delta['label'],
                        'delta_tone' => $location_delta['tone'],
                        'points' => $this->build_crm_reddit_dashboard_app_sparkline_points($top_location_series, 180, 54, 4),
                        'area' => $this->build_crm_reddit_dashboard_app_sparkline_area($top_location_series, 180, 54, 4),
                    ],
                    'secondary' => [
                        'label' => __('Runner-up', 'senna-finance'),
                        'value' => $second_location,
                        'note' => sprintf(
                            _n('%d live role', '%d live roles', max(0, $top_location_count + $second_location_count), 'senna-finance'),
                            max(0, $top_location_count + $second_location_count)
                        ),
                    ],
                ],
                [
                    'title' => __('Trending Sector', 'senna-finance'),
                    'primary' => [
                        'label' => __('Leading sector', 'senna-finance'),
                        'value' => $top_industry,
                        'delta_label' => $industry_delta['label'],
                        'delta_tone' => $industry_delta['tone'],
                        'points' => $this->build_crm_reddit_dashboard_app_sparkline_points($top_industry_series, 180, 54, 4),
                        'area' => $this->build_crm_reddit_dashboard_app_sparkline_area($top_industry_series, 180, 54, 4),
                    ],
                    'secondary' => [
                        'label' => __('Runner-up', 'senna-finance'),
                        'value' => $second_industry,
                        'note' => sprintf(
                            _n('%d live role', '%d live roles', max(0, $top_industry_count + $second_industry_count), 'senna-finance'),
                            max(0, $top_industry_count + $second_industry_count)
                        ),
                    ],
                ],
            ];
        }

        private function build_crm_reddit_dashboard_market_news_metric($window_days = 30, $search_term = '')
        {
            $window_days = max(7, (int) $window_days);
            $search_term = sanitize_text_field((string) $search_term);
            $post_types = ['sffc_pe_news', 'sffc_pe_deal'];
            $date_after = gmdate('Y-m-d', current_time('timestamp') - ($window_days * DAY_IN_SECONDS));

            $query_args = [
                'post_type' => $post_types,
                'post_status' => 'publish',
                'posts_per_page' => 12,
                'orderby' => 'date',
                'order' => 'DESC',
                'date_query' => [
                    [
                        'after' => $date_after,
                        'inclusive' => true,
                    ],
                ],
            ];
            if ($search_term !== '') {
                $query_args['s'] = $search_term;
            }

            $feature_query = new WP_Query($query_args);
            $articles = [];
            if ($feature_query->have_posts()) {
                while ($feature_query->have_posts()) {
                    $feature_query->the_post();
                    $article = $this->build_market_article_data(get_post());
                    if ($article) {
                        $articles[] = [
                            'type_label' => (string) ($article['type_label'] ?? __('News', 'senna-finance')),
                            'title' => (string) ($article['title'] ?? ''),
                            'excerpt' => (string) ($article['excerpt'] ?? ''),
                            'url' => (string) ($article['url'] ?? home_url('/terminal/?tab=markets')),
                            'date_relative' => (string) ($article['date_relative'] ?? ''),
                            'company' => (string) ($article['company'] ?? ''),
                        ];
                    }
                }
                wp_reset_postdata();
            }

            if (empty($articles)) {
                return [
                    'kind' => 'news',
                    'title' => __('Markets Desk', 'senna-finance'),
                    'articles' => [[
                        'type_label' => __('News', 'senna-finance'),
                        'title' => __('No recent market article found', 'senna-finance'),
                        'excerpt' => __('Fresh PE news and deal coverage will appear here as soon as new articles are published.', 'senna-finance'),
                        'url' => home_url('/terminal/?tab=markets'),
                        'date_relative' => __('Updated live', 'senna-finance'),
                    ]],
                ];
            }

            if (count($articles) > 1) {
                shuffle($articles);
            }

            return [
                'kind' => 'news',
                'title' => __('Markets Desk', 'senna-finance'),
                'articles' => array_slice($articles, 0, 12),
            ];
        }

        private function build_crm_reddit_dashboard_tracking_view($user_id, $search_term = '', $cv_text = '', $has_cv = false, $matches_filter = 'highest-match', $current_url = '', $matches_page = 1, $metrics_window = 'month')
        {
            $user_id = (int) $user_id;
            $raw_cv_text = (string) $cv_text;
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $has_cv = (bool) $has_cv && $cv_text !== '';
            $cv_profile = ($has_cv && $user_id > 0)
                ? $this->get_crm_reddit_cv_ats_scan_payload($user_id, ['cv_text' => $raw_cv_text, 'has_cv' => true], true)
                : [];
            $matches_filter = sanitize_key((string) $matches_filter);
            if (!in_array($matches_filter, ['live-feed', 'recently-posted', 'highest-match'], true)) {
                $matches_filter = 'highest-match';
            }
            $metrics_window = sanitize_key((string) $metrics_window);
            if (!in_array($metrics_window, ['week', 'two-weeks', 'month'], true)) {
                $metrics_window = 'month';
            }
            $matches_page = max(1, (int) $matches_page);
            $batch_size = 12;
            $stage_meta = class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [];
            $pipeline_model = class_exists('SFFC_CRM_Pipeline') ? new SFFC_CRM_Pipeline() : null;
            $pipeline_items = $user_id > 0 && $pipeline_model ? (array) $pipeline_model->get_user_pipeline($user_id) : [];
            $post_model = class_exists('SFFC_CRM_Post') ? new SFFC_CRM_Post() : null;
            $rows = [];
            $search_term = sanitize_text_field((string) $search_term);

            foreach ($pipeline_items as $pipeline_item) {
                $crm_post = null;
                $item = [];
                $crm_post_id = (int) ($pipeline_item['post_id'] ?? 0);

                if ($crm_post_id > 0 && $post_model) {
                    $crm_post = $post_model->get($crm_post_id);
                    if (!empty($crm_post) && is_array($crm_post)) {
                        $item = $this->build_crm_reddit_crm_item($crm_post);
                    }
                }

                $view_url = (string) ($item['view_url'] ?? '');
                if ($view_url === '') {
                    $view_url = esc_url_raw((string) ($pipeline_item['external_url'] ?? ''));
                }

                $role_title = (string) ($pipeline_item['role_title'] ?? ($item['role_title'] ?? ''));
                $company = (string) ($pipeline_item['company'] ?? ($item['company'] ?? ''));
                $location = (string) ($pipeline_item['location'] ?? ($item['location'] ?? ''));
                $recruiter_name = (string) ($pipeline_item['recruiter_name'] ?? ($item['recruiter_name'] ?? __('Hiring Team', 'senna-finance')));
                $recruiter_photo = (string) ($pipeline_item['recruiter_photo'] ?? ($item['recruiter_photo'] ?? ''));
                $recruiter_title = (string) ($item['recruiter_title'] ?? '');
                $recruiter_email = (string) ($item['recruiter_email'] ?? ($pipeline_item['contact_email'] ?? ''));
                $recruiter_linkedin = (string) ($item['recruiter_linkedin'] ?? ($pipeline_item['contact_linkedin'] ?? ''));
                $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
                $updated_timestamp = !empty($pipeline_item['updated_at']) ? (int) strtotime((string) $pipeline_item['updated_at']) : 0;
                $stage_entered_timestamp = !empty($pipeline_item['stage_entered_at']) ? (int) strtotime((string) $pipeline_item['stage_entered_at']) : 0;
                $sort_timestamp = max($updated_timestamp, $stage_entered_timestamp, $posted_timestamp);
                $match_score = $has_cv && !empty($item) ? $this->build_crm_reddit_dashboard_match_score($item, $cv_text, $cv_profile) : 0;
                $pipeline_stage = (string) ($pipeline_item['stage'] ?? '');
                $pipeline_stage_label = (string) ($stage_meta[$pipeline_stage]['label'] ?? '');
                if ($pipeline_stage_label === '' && $pipeline_stage !== '') {
                    $pipeline_stage_label = $this->get_cv_match_readable_pipeline_stage_label($pipeline_stage);
                }

                $rows[] = [
                    'role_title' => $role_title !== '' ? $role_title : __('Tracked role', 'senna-finance'),
                    'company' => $company !== '' ? $company : __('MENA Careers opportunity', 'senna-finance'),
                    'company_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($company !== '' ? $company : 'S', 0, 1) : substr($company !== '' ? $company : 'S', 0, 1)),
                    'logo' => (string) ($item['company_logo'] ?? ''),
                    'recruiter_name' => $recruiter_name,
                    'recruiter_title' => $recruiter_title,
                    'recruiter_photo' => $recruiter_photo,
                    'recruiter_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 1) : substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 1)),
                    'recruiter_email' => sanitize_email($recruiter_email),
                    'recruiter_linkedin' => esc_url_raw($recruiter_linkedin),
                    'location' => $this->get_crm_reddit_dashboard_app_location_label($location),
                    'match_label' => $has_cv ? sprintf(__('%d%%', 'senna-finance'), $match_score) : __('Upload CV', 'senna-finance'),
                    'match_tone' => !$has_cv ? 'caution' : ($match_score >= 75 ? 'positive' : ($match_score >= 60 ? 'neutral' : 'caution')),
                    'match_score' => $match_score,
                    'posted_label' => $sort_timestamp > 0 ? sprintf(
                        /* translators: %s: relative time */
                        __('%s ago', 'senna-finance'),
                        human_time_diff($sort_timestamp, current_time('timestamp'))
                    ) : __('Tracked recently', 'senna-finance'),
                    'posted_timestamp' => $sort_timestamp,
                    'is_direct' => !empty($item['apply_url']) || !empty($pipeline_item['external_url']),
                    'has_jobs_post' => !empty($item['wp_post_id']) || (string) ($item['source'] ?? '') === 'jobs',
                    'view_url' => $view_url,
                    'crm_post_id' => $crm_post_id,
                    'wp_post_id' => (int) ($item['wp_post_id'] ?? 0),
                    'recruiter_id' => (int) ($pipeline_item['recruiter_id'] ?? 0),
                    'pipeline_id' => (int) ($pipeline_item['id'] ?? 0),
                    'pipeline_stage' => $pipeline_stage,
                    'pipeline_stage_label' => $pipeline_stage_label !== '' ? $pipeline_stage_label : __('Tracked', 'senna-finance'),
                    'pipeline_stage_color' => $this->get_crm_reddit_dashboard_stage_tag_color($pipeline_stage),
                    'external_url' => (string) ($pipeline_item['external_url'] ?? ''),
                ];
            }

            if ($search_term !== '') {
                $needle = function_exists('mb_strtolower') ? mb_strtolower($search_term) : strtolower($search_term);
                $rows = array_values(array_filter($rows, static function ($row) use ($needle) {
                    $haystack = implode(' ', [
                        (string) ($row['role_title'] ?? ''),
                        (string) ($row['company'] ?? ''),
                        (string) ($row['recruiter_name'] ?? ''),
                        (string) ($row['location'] ?? ''),
                    ]);
                    $haystack = function_exists('mb_strtolower') ? mb_strtolower($haystack) : strtolower($haystack);
                    return strpos($haystack, $needle) !== false;
                }));
            }

            if ($matches_filter === 'highest-match' && $has_cv) {
                usort($rows, static function ($left, $right) {
                    $score_compare = ((int) ($right['match_score'] ?? 0)) <=> ((int) ($left['match_score'] ?? 0));
                    if ($score_compare !== 0) {
                        return $score_compare;
                    }
                    return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
                });
            } else {
                usort($rows, static function ($left, $right) {
                    return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
                });
            }

            $total_rows = count($rows);
            $offset = ($matches_page - 1) * $batch_size;
            $display_rows = array_slice($rows, $offset, $batch_size);
            $has_more = ($offset + $batch_size) < $total_rows;

            $filters = [
                [
                    'label' => __('All Tracked', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'tracking', 'matches_filter' => 'live-feed', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'live-feed',
                ],
                [
                    'label' => __('Recently Updated', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'tracking', 'matches_filter' => 'recently-posted', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'recently-posted',
                ],
                [
                    'label' => __('Highest Match', 'senna-finance'),
                    'url' => add_query_arg(['dashboard_tab' => 'tracking', 'matches_filter' => 'highest-match', 'metrics_window' => $metrics_window, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $matches_filter === 'highest-match',
                ],
            ];

            $window_options = [
                'week' => __('Past week', 'senna-finance'),
                'two-weeks' => __('Past two weeks', 'senna-finance'),
                'month' => __('Past month', 'senna-finance'),
            ];
            $windows = [];
            foreach ($window_options as $window_key => $window_label) {
                $windows[] = [
                    'label' => $window_label,
                    'url' => add_query_arg(['dashboard_tab' => 'tracking', 'matches_filter' => $matches_filter, 'metrics_window' => $window_key, 'sffc_reddit_search' => $search_term, 'matches_page' => 1], $current_url !== '' ? $current_url : home_url('/community/')),
                    'active' => $metrics_window === $window_key,
                ];
            }

            return [
                'rows' => $display_rows,
                'total' => $total_rows,
                'page' => $matches_page,
                'has_more' => $has_more,
                'next_url' => $has_more ? add_query_arg([
                    'dashboard_tab' => 'tracking',
                    'matches_filter' => $matches_filter,
                    'metrics_window' => $metrics_window,
                    'sffc_reddit_search' => $search_term,
                    'matches_page' => $matches_page + 1,
                ], $current_url !== '' ? $current_url : home_url('/community/')) : '',
                'filters' => $filters,
                'windows' => $windows,
                'summary' => $this->build_crm_reddit_dashboard_tracking_summary_cards($user_id, $metrics_window),
            ];
        }

        private function build_crm_reddit_dashboard_tracking_summary_cards($user_id, $metrics_window = 'month')
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $metrics_window = sanitize_key((string) $metrics_window);
            $window_days = 30;
            if ($metrics_window === 'week') {
                $window_days = 7;
            } elseif ($metrics_window === 'two-weeks') {
                $window_days = 14;
            }

            $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
            $history_table = $wpdb->prefix . 'sffc_crm_pipeline_history';
            $today = strtotime(date('Y-m-d 00:00:00', current_time('timestamp')));
            $bucket_count = $window_days * 2;
            $bucket_keys = [];
            for ($offset = $bucket_count - 1; $offset >= 0; $offset--) {
                $bucket_time = strtotime("-{$offset} days", $today);
                $bucket_keys[] = date('Y-m-d', $bucket_time);
            }

            $stage_map = [
                'application_submitted' => __('Applied', 'senna-finance'),
                'messaged' => __('Messaged', 'senna-finance'),
                'follow_up' => __('Follow Up', 'senna-finance'),
            ];
            $series_map = [];
            $current_counts = [];
            foreach ($stage_map as $stage_key => $stage_label) {
                $series_map[$stage_key] = array_fill_keys($bucket_keys, 0);
                $current_counts[$stage_key] = 0;
            }

            if ($user_id > 0) {
                $current_stage_rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT stage, COUNT(*) AS count
                     FROM {$pipeline_table}
                     WHERE user_id = %d
                       AND stage IN ('application_submitted','messaged','follow_up')
                     GROUP BY stage",
                    $user_id
                ), ARRAY_A);

                foreach ((array) $current_stage_rows as $stage_row) {
                    $stage_key = (string) ($stage_row['stage'] ?? '');
                    if (isset($current_counts[$stage_key])) {
                        $current_counts[$stage_key] = (int) ($stage_row['count'] ?? 0);
                    }
                }

                $history_rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT h.to_stage, DATE(h.transitioned_at) AS bucket_date, COUNT(*) AS stage_count
                     FROM {$history_table} h
                     INNER JOIN {$pipeline_table} p ON p.id = h.pipeline_id
                     WHERE p.user_id = %d
                       AND h.to_stage IN ('application_submitted','messaged','follow_up')
                       AND h.transitioned_at >= %s
                     GROUP BY h.to_stage, DATE(h.transitioned_at)",
                    $user_id,
                    date('Y-m-d H:i:s', strtotime('-' . ($bucket_count - 1) . ' days', $today))
                ), ARRAY_A);

                foreach ((array) $history_rows as $history_row) {
                    $stage_key = (string) ($history_row['to_stage'] ?? '');
                    $bucket_key = (string) ($history_row['bucket_date'] ?? '');
                    if (isset($series_map[$stage_key][$bucket_key])) {
                        $series_map[$stage_key][$bucket_key] = (int) ($history_row['stage_count'] ?? 0);
                    }
                }
            }

            $cards = [];
            foreach ($stage_map as $stage_key => $stage_title) {
                $series = array_values($series_map[$stage_key]);
                $recent_total = array_sum(array_slice($series, -$window_days));
                $previous_total = array_sum(array_slice($series, 0, $window_days));
                $delta = $this->format_crm_reddit_dashboard_metric_delta($recent_total, $previous_total);
                $cards[] = [
                    'title' => $stage_title,
                    'primary' => [
                        'label' => __('Current stage', 'senna-finance'),
                        'value' => (string) ($current_counts[$stage_key] ?? 0),
                        'delta_label' => $delta['label'],
                        'delta_tone' => $delta['tone'],
                        'points' => $this->build_crm_reddit_dashboard_app_sparkline_points($series, 180, 54, 4),
                        'area' => $this->build_crm_reddit_dashboard_app_sparkline_area($series, 180, 54, 4),
                    ],
                    'secondary' => [
                        'label' => __('Stage updates', 'senna-finance'),
                        'value' => (string) $recent_total,
                        'note' => sprintf(
                            /* translators: %d: number of days */
                            __('Tracked over the last %d days', 'senna-finance'),
                            $window_days
                        ),
                    ],
                ];
            }

            return $cards;
        }

        private function format_crm_reddit_dashboard_metric_delta($current_total, $previous_total)
        {
            $current_total = (int) $current_total;
            $previous_total = (int) $previous_total;

            if ($current_total === 0 && $previous_total === 0) {
                return [
                    'label' => __('0%', 'senna-finance'),
                    'tone' => 'neutral',
                ];
            }

            if ($previous_total <= 0) {
                return [
                    'label' => __('New', 'senna-finance'),
                    'tone' => 'positive',
                ];
            }

            $delta = (int) round((($current_total - $previous_total) / max(1, $previous_total)) * 100);
            if ($delta > 0) {
                return [
                    'label' => sprintf(__('+%d%%', 'senna-finance'), $delta),
                    'tone' => 'positive',
                ];
            }
            if ($delta < 0) {
                return [
                    'label' => sprintf(__('%d%%', 'senna-finance'), $delta),
                    'tone' => 'negative',
                ];
            }

            return [
                'label' => __('0%', 'senna-finance'),
                'tone' => 'neutral',
            ];
        }

        private function get_crm_reddit_dashboard_match_industry_label(array $item)
        {
            $candidates = [];

            foreach (['industry', 'sector', 'specialisation', 'specialization', 'recruiter_specializations'] as $field_key) {
                if (!empty($item[$field_key])) {
                    $candidates[] = (string) $item[$field_key];
                }
            }

            if (!empty($item['industries']) && is_array($item['industries'])) {
                foreach ((array) $item['industries'] as $industry_name) {
                    $candidates[] = (string) $industry_name;
                }
            }

            foreach ($candidates as $candidate) {
                $label = $this->format_crm_reddit_dashboard_match_industry_name($candidate);
                if ($label !== '') {
                    return $label;
                }
            }

            return __('Financial Services', 'senna-finance');
        }

        private function format_crm_reddit_dashboard_match_industry_name($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return '';
            }

            $normalized = strtolower(str_replace(['-', '/', '&'], [' ', ' ', ' and '], $value));
            $normalized = preg_replace('/\s+/', ' ', str_replace('_', ' ', $normalized));
            $normalized = trim((string) $normalized);

            $map = [
                'pe' => __('Finance', 'senna-finance'),
                'finance' => __('Finance', 'senna-finance'),
                'vc' => __('Venture Capital', 'senna-finance'),
                'venture capital' => __('Venture Capital', 'senna-finance'),
                'asset management' => __('Asset Management', 'senna-finance'),
                'asset mgmt' => __('Asset Management', 'senna-finance'),
                'asset mgt' => __('Asset Management', 'senna-finance'),
                'asset_mgmt' => __('Asset Management', 'senna-finance'),
                'investment banking' => __('Investment Banking', 'senna-finance'),
                'ib' => __('Investment Banking', 'senna-finance'),
                'hedge fund' => __('Hedge Fund', 'senna-finance'),
                'corporate finance' => __('Portfolio Operations', 'senna-finance'),
                'family office' => __('Family Office', 'senna-finance'),
                'real estate' => __('Real Estate', 'senna-finance'),
                'credit' => __('Credit', 'senna-finance'),
                'consulting' => __('Consulting', 'senna-finance'),
                'financial services' => __('Financial Services', 'senna-finance'),
            ];

            if (isset($map[$normalized])) {
                return (string) $map[$normalized];
            }

            return ucwords($normalized);
        }

        private function get_cv_match_studio_industry_signal_terms($industry = '')
        {
            $groups = [
                'investment_banking' => [
                    'investment banking', 'investment bank', 'm&a', 'mergers', 'acquisitions', 'corporate finance',
                    'capital markets', 'advisory', 'coverage', 'valuation', 'dcf', 'pitchbook', 'pitch book',
                    'leveraged finance', 'debt capital', 'equity capital', 'transaction', 'deal execution',
                    'structured finance', 'delta one', 'trading', 'trader', 'traders', 'trades', 'swap', 'swaps',
                    'p&l', 'profit and loss',
                ],
                'private_equity' => [
                    'finance', 'buyout', 'lbo', 'portfolio company', 'portfolio management',
                    'investment memo', 'deal sourcing', 'due diligence', 'fund', 'valuation', 'investor intern',
                    'growth equity',
                ],
                'asset_management' => [
                    'asset management', 'investment management', 'portfolio', 'public markets', 'equity research',
                    'fixed income', 'fund management', 'wealth management', 'private banking', 'investment analyst',
                    'asset allocation',
                ],
                'hedge_fund' => [
                    'hedge fund', 'long short', 'long/short', 'alpha', 'quant', 'trading', 'trader', 'traders',
                    'trades', 'market risk', 'risk reporting', 'p&l', 'profit and loss', 'derivatives',
                    'structured products', 'swap', 'swaps', 'delta one',
                ],
                'finance' => [
                    'finance', 'financial analysis', 'financial modelling', 'financial modeling', 'accounting',
                    'treasury', 'fp&a', 'excel', 'vba', 'automation', 'reporting', 'p&l', 'profit and loss',
                    'risk', 'market risk', 'valuation', 'model', 'models', 'analysis', 'trading', 'traders',
                    'trades', 'structured finance',
                ],
                'consulting' => [
                    'consulting', 'strategy consulting', 'strategy consultant', 'strategy', 'management consulting',
                    'commercial due diligence', 'market research', 'operations', 'case interview', 'client',
                    'business analyst',
                ],
            ];

            $industry = $this->normalize_cv_match_studio_preferred_industry($industry);
            if ($industry !== '') {
                return (array) ($groups[$industry] ?? []);
            }

            return $groups;
        }

        private function build_cv_match_studio_item_signal_haystack(array $item)
        {
            $parts = [
                (string) ($item['role_title'] ?? ''),
                (string) ($item['company'] ?? ''),
                (string) ($item['industry'] ?? ''),
                (string) ($item['industry_label'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['specialisation'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
                (string) ($item['description'] ?? ''),
                (string) ($item['body'] ?? ''),
                implode(' ', array_map('strval', (array) ($item['keywords'] ?? []))),
                implode(' ', array_map('strval', (array) ($item['skills'] ?? []))),
                $this->get_crm_reddit_dashboard_match_industry_label($item),
            ];

            return $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter($parts)));
        }

        private function count_cv_match_studio_term_matches($haystack, array $terms)
        {
            $haystack = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
            if ($haystack === '') {
                return 0;
            }

            $matches = 0;
            foreach ($terms as $term) {
                $term = $this->normalize_crm_reddit_dashboard_cv_text((string) $term);
                if ($term !== '' && strpos($haystack, $term) !== false) {
                    $matches++;
                }
            }

            return $matches;
        }

        private function score_cv_match_studio_preferred_industry_match(array $item, $preferred_industry, $cv_text = '')
        {
            $preferred_industry = $this->normalize_cv_match_studio_preferred_industry($preferred_industry);
            if ($preferred_industry === '' || $preferred_industry === 'other') {
                return 0;
            }

            $item_haystack = $this->build_cv_match_studio_item_signal_haystack($item);
            $terms = $this->get_cv_match_studio_industry_signal_terms($preferred_industry);
            $matches = $this->count_cv_match_studio_term_matches($item_haystack, $terms);
            if ($matches <= 0) {
                return 0;
            }

            $score = min(30, 12 + ($matches * 5));
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text !== '' && $this->count_cv_match_studio_term_matches($cv_text, $terms) > 0) {
                $score += 5;
            }

            return min(35, $score);
        }

        private function score_cv_match_studio_cv_industry_keyword_match(array $item, $cv_text)
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text === '') {
                return 0;
            }

            $item_haystack = $this->build_cv_match_studio_item_signal_haystack($item);
            $score = 0;
            foreach ($this->get_cv_match_studio_industry_signal_terms() as $terms) {
                $cv_matches = $this->count_cv_match_studio_term_matches($cv_text, (array) $terms);
                if ($cv_matches <= 0) {
                    continue;
                }

                $item_matches = $this->count_cv_match_studio_term_matches($item_haystack, (array) $terms);
                if ($item_matches <= 0) {
                    continue;
                }

                $score += min(14, 4 + min($cv_matches, $item_matches) * 3);
            }

            return min(28, $score);
        }

        private function build_crm_reddit_dashboard_match_score(array $item, $cv_text, array $cv_profile = [])
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text === '') {
                return 0;
            }

            $score = 42;
            $role_title = strtolower(trim((string) ($item['role_title'] ?? '')));
            if ($role_title !== '' && strpos($cv_text, $role_title) !== false) {
                $score += 18;
            }

            $role_word_matches = 0;
            foreach (preg_split('/\s+/', $role_title) ?: [] as $role_word) {
                $role_word = trim((string) $role_word);
                if (strlen($role_word) >= 4 && strpos($cv_text, $role_word) !== false) {
                    $role_word_matches++;
                }
            }
            if ($role_word_matches > 0) {
                $score += min(14, $role_word_matches * 3);
            }

            $industry_label = $this->normalize_crm_reddit_dashboard_cv_text($this->get_crm_reddit_dashboard_match_industry_label($item));
            if ($industry_label !== '' && strpos($cv_text, $industry_label) !== false) {
                $score += 12;
            }

            $industry_synonyms = [
                'pe' => ['finance', 'buyout', 'investment management'],
                'vc' => ['venture capital', 'startups', 'growth equity'],
                'ib' => ['investment banking', 'm&a', 'corporate finance'],
                'asset management' => ['asset management', 'portfolio', 'investment management'],
                'corporate finance' => ['corporate finance', 'fp&a', 'financial analysis'],
            ];
            if ($industry_label !== '') {
                foreach ((array) ($industry_synonyms[$industry_label] ?? []) as $synonym) {
                    if (strpos($cv_text, $this->normalize_crm_reddit_dashboard_cv_text((string) $synonym)) !== false) {
                        $score += 7;
                        break;
                    }
                }
            }

            $keywords = array_values(array_filter(array_map('strtolower', (array) ($item['keywords'] ?? []))));
            if (!empty($keywords)) {
                $matches = 0;
                foreach ($keywords as $keyword) {
                    $keyword = trim((string) $keyword);
                    if ($keyword !== '' && strpos($cv_text, $keyword) !== false) {
                        $matches++;
                    }
                }
                $score += min(26, $matches * 5);
            }

            $score += $this->score_cv_match_studio_cv_industry_keyword_match($item, $cv_text);

            $seniority = strtolower(trim((string) ($item['seniority'] ?? '')));
            if ($seniority !== '' && strpos($cv_text, $seniority) !== false) {
                $score += 6;
            }

            $location = strtolower(trim((string) ($item['location'] ?? '')));
            if ($location !== '' && strpos($cv_text, $location) !== false) {
                $score += 4;
            }

            if (!empty($cv_profile)) {
                $score += $this->get_crm_reddit_dashboard_match_score_from_cv_profile($item, $cv_profile);
            }

            $score += $this->get_crm_reddit_dashboard_seniority_score_adjustment($item, $cv_text, $cv_profile);

            if (!empty($item['apply_url'])) {
                $score += 4;
            }

            $score += ((int) ($item['post_id'] ?? $item['wp_post_id'] ?? $item['crm_post_id'] ?? 0)) % 5;

            return $this->clamp_crm_reddit_single_job_metric($score, 24, 96);
        }

        private function get_crm_reddit_dashboard_seniority_score_adjustment(array $item, $cv_text, array $cv_profile = [])
        {
            $candidate_rank = $this->infer_crm_reddit_dashboard_candidate_seniority_rank($cv_text, $cv_profile);
            $role_rank = $this->infer_crm_reddit_dashboard_role_seniority_rank($item);

            if ($candidate_rank === null || $role_rank === null) {
                return 0;
            }

            $gap = $candidate_rank - $role_rank;

            if ($gap >= 4) {
                return -18;
            }

            if ($gap === 3) {
                return -14;
            }

            if ($gap === 2) {
                return -8;
            }

            if ($gap === 1) {
                return -3;
            }

            if ($gap === 0) {
                return 10;
            }

            if ($gap === -1) {
                return 4;
            }

            return 0;
        }

        private function find_recruiter_post_id_by_crm_post_id($crm_post_id)
        {
            $crm_post_id = (int) $crm_post_id;
            if ($crm_post_id <= 0) {
                return 0;
            }

            static $cache = [];
            if (isset($cache[$crm_post_id])) {
                return (int) $cache[$crm_post_id];
            }

            $post_ids = get_posts([
                'post_type' => 'sffc_recruiter_post',
                'post_status' => 'publish',
                'posts_per_page' => 1,
                'fields' => 'ids',
                'no_found_rows' => true,
                'meta_query' => [
                    [
                        'key' => '_crm_post_id',
                        'value' => (string) $crm_post_id,
                    ],
                ],
            ]);

            $cache[$crm_post_id] = !empty($post_ids[0]) ? (int) $post_ids[0] : 0;

            return (int) $cache[$crm_post_id];
        }

        private function resolve_crm_reddit_recruiter_post_permalink(array $item)
        {
            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                $wp_post = get_post($wp_post_id);
                if ($wp_post && $wp_post->post_type === 'sffc_recruiter_post') {
                    $permalink = get_permalink($wp_post_id);
                    if (is_string($permalink) && $permalink !== '') {
                        return $permalink;
                    }
                }
            }

            $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
            if ($crm_post_id > 0) {
                $recruiter_post_id = $this->find_recruiter_post_id_by_crm_post_id($crm_post_id);
                if ($recruiter_post_id > 0) {
                    $permalink = get_permalink($recruiter_post_id);
                    if (is_string($permalink) && $permalink !== '') {
                        return $permalink;
                    }
                }
            }

            return '';
        }

        private function infer_crm_reddit_dashboard_candidate_seniority_rank($cv_text, array $cv_profile = [])
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text === '') {
                return null;
            }

            $highest_rank = null;
            foreach ((array) ($cv_profile['seniority'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $rank = $this->map_crm_reddit_dashboard_seniority_label_to_rank($label);
                if ($rank !== null) {
                    $highest_rank = $highest_rank === null ? $rank : max($highest_rank, $rank);
                }
            }

            $years = 0;
            if (preg_match('/\b(\d{1,2})\s*\+?\s*years?\b/', $cv_text, $matches)) {
                $years = (int) ($matches[1] ?? 0);
            }

            if ($years >= 7) {
                $highest_rank = $highest_rank === null ? 3 : max($highest_rank, 3);
            } elseif ($years >= 4) {
                $highest_rank = $highest_rank === null ? 2 : max($highest_rank, 2);
            }

            foreach (
                [
                    'portfolio manager' => 3,
                    'head of' => 4,
                    'director' => 4,
                    'vice president' => 4,
                    'vp' => 4,
                    'manager' => 3,
                    'senior associate' => 2,
                    'associate' => 2,
                    'senior analyst' => 2,
                    'analyst' => 1,
                    'graduate' => 0,
                    'intern' => 0,
                    'off-cycle' => 0,
                ] as $needle => $rank
            ) {
                if (strpos($cv_text, $needle) !== false) {
                    $highest_rank = $highest_rank === null ? $rank : max($highest_rank, $rank);
                }
            }

            return $highest_rank;
        }

        private function infer_crm_reddit_dashboard_role_seniority_rank(array $item)
        {
            $role_haystack = $this->normalize_crm_reddit_dashboard_cv_text(trim(implode(' ', array_filter([
                (string) ($item['role_title'] ?? ''),
                (string) ($item['seniority'] ?? ''),
            ]))));

            if ($role_haystack === '') {
                return null;
            }

            return $this->map_crm_reddit_dashboard_seniority_label_to_rank($role_haystack);
        }

        private function map_crm_reddit_dashboard_seniority_label_to_rank($label)
        {
            $label = $this->normalize_crm_reddit_dashboard_cv_text($label);
            if ($label === '') {
                return null;
            }

            if (
                strpos($label, 'intern') !== false
                || strpos($label, 'summer') !== false
                || strpos($label, 'off-cycle') !== false
                || strpos($label, 'graduate') !== false
                || strpos($label, 'entry level') !== false
                || strpos($label, 'placement') !== false
            ) {
                return 0;
            }

            if (strpos($label, 'analyst') !== false) {
                return 1;
            }

            if (strpos($label, 'associate') !== false) {
                return 2;
            }

            if (
                strpos($label, 'manager') !== false
                || strpos($label, 'portfolio manager') !== false
                || strpos($label, 'senior manager') !== false
            ) {
                return 3;
            }

            if (
                strpos($label, 'director') !== false
                || strpos($label, 'vice president') !== false
                || preg_match('/\bvp\b/', $label)
                || strpos($label, 'head of') !== false
                || strpos($label, 'partner') !== false
            ) {
                return 4;
            }

            return null;
        }

        private function get_crm_reddit_dashboard_match_score_from_cv_profile(array $item, array $cv_profile = [])
        {
            $score = 0;
            $role_title = $this->normalize_crm_reddit_dashboard_cv_text((string) ($item['role_title'] ?? ''));
            $location = $this->normalize_crm_reddit_dashboard_cv_text((string) ($item['location'] ?? ''));
            $industry = $this->normalize_crm_reddit_dashboard_cv_text($this->get_crm_reddit_dashboard_match_industry_label($item));
            $seniority = $this->normalize_crm_reddit_dashboard_cv_text((string) ($item['seniority'] ?? ''));
            $keyword_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter(array_merge(
                [(string) ($item['role_title'] ?? ''), (string) ($item['location'] ?? ''), (string) ($item['industry'] ?? ''), (string) ($item['sector'] ?? '')],
                array_map('strval', (array) ($item['keywords'] ?? [])),
                array_map('strval', (array) ($item['skills'] ?? [])),
                array_map('strval', (array) ($item['requirements'] ?? []))
            ))));

            foreach ((array) ($cv_profile['target_roles'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $weight = (float) ($signal['weight'] ?? 0);
                if ($label !== '' && $role_title !== '' && strpos($role_title, $label) !== false) {
                    $score += (int) round(18 * $weight);
                }
            }

            foreach ((array) ($cv_profile['keywords'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $weight = (float) ($signal['weight'] ?? 0);
                if ($label !== '' && $keyword_haystack !== '' && strpos($keyword_haystack, $label) !== false) {
                    $score += (int) round(8 * $weight);
                }
            }

            foreach ((array) ($cv_profile['locations'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $weight = (float) ($signal['weight'] ?? 0);
                if ($label !== '' && $location !== '' && strpos($location, $label) !== false) {
                    $score += (int) round(6 * $weight);
                }
            }

            foreach ((array) ($cv_profile['sectors'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $weight = (float) ($signal['weight'] ?? 0);
                if ($label !== '' && $industry !== '' && strpos($industry, $label) !== false) {
                    $score += (int) round(7 * $weight);
                }
            }

            foreach ((array) ($cv_profile['seniority'] ?? []) as $signal) {
                $label = $this->normalize_crm_reddit_dashboard_cv_text((string) ($signal['label'] ?? ''));
                $weight = (float) ($signal['weight'] ?? 0);
                if ($label !== '' && $seniority !== '' && strpos($seniority, $label) !== false) {
                    $score += (int) round(4 * $weight);
                }
            }

            return max(0, $score);
        }

        private function get_crm_reddit_dashboard_primary_cv_role_label(array $cv_profile = [])
        {
            $best_label = '';
            $best_weight = -1;

            foreach ((array) ($cv_profile['target_roles'] ?? []) as $signal) {
                $label = trim((string) ($signal['label'] ?? ''));
                if ($label === '') {
                    continue;
                }

                $weight = (float) ($signal['weight'] ?? 0);
                if ($weight > $best_weight) {
                    $best_label = $label;
                    $best_weight = $weight;
                }
            }

            return $best_label;
        }

        private function get_crm_reddit_dashboard_ranked_home_items(array $items, $cv_text, array $cv_profile = [], $role_label = '')
        {
            if (empty($items)) {
                return [];
            }

            $cv_text = trim((string) $cv_text);
            if ($cv_text === '' && empty($cv_profile)) {
                return [];
            }

            $role_label_normalized = $this->normalize_crm_reddit_dashboard_cv_text((string) $role_label);
            $ranked = [];

            foreach ($items as $item) {
                $score = $this->build_crm_reddit_dashboard_match_score($item, $cv_text, $cv_profile);
                $title_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                    (string) ($item['role_title'] ?? ''),
                    (string) ($item['seniority'] ?? ''),
                    implode(' ', array_map('strval', (array) ($item['keywords'] ?? []))),
                ])));

                if ($role_label_normalized !== '' && $title_haystack !== '') {
                    if (strpos($title_haystack, $role_label_normalized) !== false) {
                        $score += 14;
                    } else {
                        $role_tokens = array_values(array_filter(array_map('trim', preg_split('/\s+/', $role_label_normalized)), static function ($token) {
                            return strlen((string) $token) >= 4;
                        }));
                        $token_matches = 0;
                        foreach ($role_tokens as $token) {
                            if (strpos($title_haystack, $token) !== false) {
                                $token_matches++;
                            }
                        }
                        if ($token_matches > 0) {
                            $score += min(10, $token_matches * 3);
                        }
                    }
                }

                $item['_dashboard_match_score'] = $score;
                if ($score >= 42) {
                    $ranked[] = $item;
                }
            }

            usort($ranked, static function ($left, $right) {
                $score_compare = ((int) ($right['_dashboard_match_score'] ?? 0)) <=> ((int) ($left['_dashboard_match_score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
            });

            return array_values(array_slice($ranked, 0, 24));
        }

        private function normalize_crm_reddit_dashboard_cv_text($cv_text)
        {
            $cv_text = trim((string) $cv_text);
            return function_exists('mb_strtolower') ? mb_strtolower($cv_text) : strtolower($cv_text);
        }

        private function get_crm_reddit_dashboard_match_dedupe_key(array $item)
        {
            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                return 'wp:' . $wp_post_id;
            }

            $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
            if ($crm_post_id > 0) {
                return 'crm:' . $crm_post_id;
            }

            $role = sanitize_title((string) ($item['role_title'] ?? ''));
            $company = sanitize_title((string) ($item['company'] ?? ''));
            $location = sanitize_title((string) ($item['location'] ?? ''));

            return trim('fallback:' . $role . ':' . $company . ':' . $location, ':');
        }

        private function get_crm_reddit_dashboard_pipeline_identity_key($role_title = '', $company = '', $location = '', $external_url = '')
        {
            $role = sanitize_title((string) $role_title);
            $company_slug = sanitize_title((string) $company);
            $location_slug = sanitize_title((string) $location);
            $url = trim((string) $external_url);

            if ($url !== '') {
                return 'url:' . md5($url);
            }

            if ($role === '' || $company_slug === '') {
                return '';
            }

            return trim('role-company-location:' . $role . ':' . $company_slug . ':' . $location_slug, ':');
        }

        private function resolve_crm_reddit_dashboard_item_view_url(array $item)
        {
            $source = (string) ($item['source'] ?? '');
            if ($source === 'jobs') {
                $jobs_post_id = (int) ($item['post_id'] ?? 0);
                if ($jobs_post_id > 0) {
                    $permalink = get_permalink($jobs_post_id);
                    if ($permalink) {
                        return (string) $permalink;
                    }
                }
            }

            $recruiter_post_permalink = $this->resolve_crm_reddit_recruiter_post_permalink($item);
            if ($recruiter_post_permalink !== '') {
                return $recruiter_post_permalink;
            }

            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                $wp_post = get_post($wp_post_id);
                if ($wp_post && $wp_post->post_type !== SFFC_CRM_Post_Type::POST_TYPE) {
                    $permalink = get_permalink($wp_post_id);
                    if ($permalink) {
                        return (string) $permalink;
                    }
                }
            }

            return (string) ($item['view_url'] ?? '');
        }

        private function build_crm_reddit_dashboard_app_sparkline_points(array $series, $width = 180, $height = 62, $padding = 6)
        {
            $series = array_values(array_map('floatval', $series));
            if (empty($series)) {
                return '';
            }

            $count = count($series);
            $max = max($series);
            $min = min($series);
            $range = max(1, $max - $min);
            $step_x = $count > 1 ? (($width - ($padding * 2)) / ($count - 1)) : 0;
            $points = [];

            foreach ($series as $index => $value) {
                $x = $padding + ($index * $step_x);
                $normalized = ($value - $min) / $range;
                $y = ($height - $padding) - ($normalized * ($height - ($padding * 2)));
                $points[] = round($x, 2) . ',' . round($y, 2);
            }

            return implode(' ', $points);
        }

        private function build_crm_reddit_dashboard_app_sparkline_area(array $series, $width = 180, $height = 62, $padding = 6)
        {
            $points = $this->build_crm_reddit_dashboard_app_sparkline_points($series, $width, $height, $padding);
            if ($points === '') {
                return '';
            }

            $point_list = array_map('trim', explode(' ', $points));
            $first = $point_list[0] ?? '';
            $last = $point_list[count($point_list) - 1] ?? '';
            if ($first === '' || $last === '') {
                return '';
            }

            [$first_x] = array_pad(explode(',', $first), 2, '0');
            [$last_x] = array_pad(explode(',', $last), 2, '0');

            return 'M ' . $first_x . ' ' . ($height - $padding) . ' L ' . implode(' L ', $point_list) . ' L ' . $last_x . ' ' . ($height - $padding) . ' Z';
        }

        private function get_crm_reddit_dashboard_app_series_status(array $series, array $labels, $allow_mixed = false)
        {
            $series = array_values(array_filter(array_map('floatval', $series), static function ($value) {
                return $value >= 0;
            }));

            $first = (float) ($series[0] ?? 0);
            $last = (float) ($series[count($series) - 1] ?? $first);
            $delta = $last - $first;
            $avg = !empty($series) ? array_sum($series) / count($series) : 0;
            $threshold = max(1, $avg * 0.1);

            if ($allow_mixed && count(array_unique($series)) > 3 && abs($delta) < $threshold) {
                return ['label' => (string) ($labels['mixed'] ?? $labels['flat'] ?? 'Stable'), 'tone' => 'neutral'];
            }

            if ($delta > $threshold) {
                return ['label' => (string) ($labels['up'] ?? 'Increasing'), 'tone' => 'positive'];
            }
            if ($delta < -$threshold) {
                return ['label' => (string) ($labels['down'] ?? 'Declining'), 'tone' => 'negative'];
            }

            return ['label' => (string) ($labels['flat'] ?? 'Stable'), 'tone' => 'neutral'];
        }

        private function get_crm_reddit_dashboard_app_market_status($matched_total, $recent_total, $direct_total)
        {
            $matched_total = max(1, (int) $matched_total);
            $recent_ratio = (int) round(($recent_total / $matched_total) * 100);
            $direct_ratio = (int) round(($direct_total / $matched_total) * 100);
            $score = (int) round(($recent_ratio * 0.55) + ($direct_ratio * 0.45));

            if ($score >= 70) {
                return ['label' => __('Healthy', 'senna-finance'), 'tone' => 'positive'];
            }
            if ($score >= 52) {
                return ['label' => __('Improving', 'senna-finance'), 'tone' => 'positive'];
            }
            if ($score >= 34) {
                return ['label' => __('Caution', 'senna-finance'), 'tone' => 'caution'];
            }

            return ['label' => __('Unstable', 'senna-finance'), 'tone' => 'negative'];
        }

        private function get_crm_reddit_dashboard_app_role_matches(array $feed_items, $role_label)
        {
            $role_label = trim((string) $role_label);
            if ($role_label === '') {
                return $feed_items;
            }

            $needle = function_exists('mb_strtolower') ? mb_strtolower($role_label) : strtolower($role_label);
            $tokens = array_values(array_filter(array_map('trim', preg_split('/\s+/', $needle)), static function ($token) {
                return strlen((string) $token) >= 4;
            }));

            $matches = [];
            foreach ($feed_items as $item) {
                $haystack = implode(' ', array_filter([
                    (string) ($item['role_title'] ?? ''),
                    (string) ($item['seniority'] ?? ''),
                    implode(' ', (array) ($item['keywords'] ?? [])),
                    (string) ($item['company'] ?? ''),
                ]));
                $haystack = function_exists('mb_strtolower') ? mb_strtolower($haystack) : strtolower($haystack);
                $score = 0;

                if ($needle !== '' && strpos($haystack, $needle) !== false) {
                    $score += 4;
                }

                foreach ($tokens as $token) {
                    if ($token !== '' && strpos($haystack, $token) !== false) {
                        $score++;
                    }
                }

                if ($score > 0) {
                    $item['_dashboard_score'] = $score;
                    $matches[] = $item;
                }
            }

            usort($matches, static function ($left, $right) {
                $score_compare = ((int) ($right['_dashboard_score'] ?? 0)) <=> ((int) ($left['_dashboard_score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
            });

            return array_values($matches);
        }

        private function get_crm_reddit_dashboard_app_location_label($location)
        {
            $location = trim((string) $location);
            if ($location === '') {
                return '';
            }

            $parts = array_values(array_filter(array_map('trim', explode(',', $location))));
            return (string) ($parts[0] ?? $location);
        }

        private function get_crm_reddit_dashboard_profile_hints($user_id)
        {
            $preferences = function_exists('sffc_crm_get_job_preferences')
                ? sffc_crm_get_job_preferences((int) $user_id)
                : [];

            return [
                'target_roles' => $this->normalize_crm_reddit_profile_tag_values($preferences['target_roles'] ?? []),
                'target_locations' => $this->normalize_crm_reddit_profile_tag_values($preferences['target_locations'] ?? []),
                'target_sectors' => $this->normalize_crm_reddit_profile_tag_values($preferences['target_sectors'] ?? []),
                'technical_skills' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta((int) $user_id, 'sffc_crm_technical_skills', true) ?: [], 24),
            ];
        }

