        private function build_crm_reddit_dashboard_recruiter_discovery_view($user_id, $search_term = '', array $resume_payload = [], $current_url = '', $page = 1, array $filter_state = [])
        {
            $user_id = (int) $user_id;
            $page = max(1, (int) $page);
            $batch_size = 10;
            $search_term = sanitize_text_field((string) $search_term);
            $current_url = $current_url !== '' ? $current_url : home_url('/community/');

            $discovery_filter = sanitize_key((string) ($filter_state['discovery_filter'] ?? ($_GET['discovery_filter'] ?? 'highest-match')));
            if (!in_array($discovery_filter, ['highest-match', 'region-fit', 'industry-fit', 'skills-fit'], true)) {
                $discovery_filter = 'highest-match';
            }

            $selected_region = sanitize_text_field((string) ($filter_state['recruiter_region'] ?? ($_GET['recruiter_region'] ?? '')));
            $selected_industry = sanitize_text_field((string) ($filter_state['recruiter_industry'] ?? ($_GET['recruiter_industry'] ?? '')));
            $selected_skill = sanitize_text_field((string) ($filter_state['recruiter_skill'] ?? ($_GET['recruiter_skill'] ?? '')));

            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text((string) ($resume_payload['cv_text'] ?? ''));
            $has_cv = !empty($resume_payload['has_cv']) && $cv_text !== '';
            $cv_profile = ($has_cv && $user_id > 0)
                ? $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true)
                : [];
            $profile_hints = $user_id > 0 ? $this->get_crm_reddit_dashboard_profile_hints($user_id) : [];

            $records = $this->get_crm_reddit_dashboard_hr_outreach_records($search_term);
            $rows = [];
            $region_counts = [];
            $industry_counts = [];
            $skill_counts = [];

            foreach ($records as $record) {
                $row = $this->score_crm_reddit_dashboard_recruiter_record((array) $record, $cv_profile, $profile_hints, $cv_text, $has_cv);
                if (empty($row)) {
                    continue;
                }

                foreach ((array) ($row['region_terms'] ?? []) as $term) {
                    $region_counts[$term] = (int) ($region_counts[$term] ?? 0) + 1;
                }
                foreach ((array) ($row['industry_labels'] ?? []) as $term) {
                    $industry_counts[$term] = (int) ($industry_counts[$term] ?? 0) + 1;
                }
                foreach ((array) ($row['skill_labels'] ?? []) as $term) {
                    $skill_counts[$term] = (int) ($skill_counts[$term] ?? 0) + 1;
                }

                $rows[] = $row;
            }

            if ($user_id > 0 && !empty($rows)) {
                $dismissed_recruiters = $this->get_cv_match_dismissed_recruiter_discovery_keys($user_id);
                if (!empty($dismissed_recruiters)) {
                    $rows = array_values(array_filter($rows, static function ($row) use ($dismissed_recruiters) {
                        $key = (string) ($row['dismiss_key'] ?? '');
                        return $key === '' || !in_array($key, $dismissed_recruiters, true);
                    }));
                }
            }

            if ($selected_region !== '') {
                $selected_region_normalized = $this->normalize_crm_reddit_dashboard_cv_text($selected_region);
                $rows = array_values(array_filter($rows, static function ($row) use ($selected_region_normalized) {
                    foreach ((array) ($row['region_terms_normalized'] ?? []) as $term) {
                        if ($term === $selected_region_normalized) {
                            return true;
                        }
                    }
                    return false;
                }));
            }

            if ($selected_industry !== '') {
                $selected_industry_normalized = $this->normalize_crm_reddit_dashboard_cv_text($selected_industry);
                $rows = array_values(array_filter($rows, static function ($row) use ($selected_industry_normalized) {
                    foreach ((array) ($row['industry_labels_normalized'] ?? []) as $term) {
                        if ($term === $selected_industry_normalized) {
                            return true;
                        }
                    }
                    return false;
                }));
            }

            if ($selected_skill !== '') {
                $selected_skill_normalized = $this->normalize_crm_reddit_dashboard_cv_text($selected_skill);
                $rows = array_values(array_filter($rows, static function ($row) use ($selected_skill_normalized) {
                    foreach ((array) ($row['skill_labels_normalized'] ?? []) as $term) {
                        if ($term === $selected_skill_normalized) {
                            return true;
                        }
                    }
                    return false;
                }));
            }

            usort($rows, static function ($left, $right) use ($discovery_filter) {
                $field = 'score';
                if ($discovery_filter === 'region-fit') {
                    $field = 'region_score';
                } elseif ($discovery_filter === 'industry-fit') {
                    $field = 'industry_score';
                } elseif ($discovery_filter === 'skills-fit') {
                    $field = 'skills_score';
                }

                $primary_compare = ((int) ($right[$field] ?? 0)) <=> ((int) ($left[$field] ?? 0));
                if ($primary_compare !== 0) {
                    return $primary_compare;
                }

                return ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
            });

            if (count($rows) > 1) {
                $now = current_time('timestamp');
                $recent_buckets = [
                    'fresh' => [],
                    'active' => [],
                    'older' => [],
                    'undated' => [],
                ];

                foreach ($rows as $row) {
                    $recent_timestamp = (int) ($row['recent_timestamp'] ?? 0);
                    if ($recent_timestamp <= 0) {
                        $recent_buckets['undated'][] = $row;
                        continue;
                    }

                    $age_seconds = max(0, $now - $recent_timestamp);
                    if ($age_seconds <= (14 * DAY_IN_SECONDS)) {
                        $recent_buckets['fresh'][] = $row;
                    } elseif ($age_seconds <= (45 * DAY_IN_SECONDS)) {
                        $recent_buckets['active'][] = $row;
                    } else {
                        $recent_buckets['older'][] = $row;
                    }
                }

                foreach ($recent_buckets as $bucket_key => $bucket_rows) {
                    if (count($bucket_rows) > 1) {
                        shuffle($bucket_rows);
                    }
                    $recent_buckets[$bucket_key] = $bucket_rows;
                }

                $rows = array_merge(
                    $recent_buckets['fresh'],
                    $recent_buckets['active'],
                    $recent_buckets['older'],
                    $recent_buckets['undated']
                );
            }

            $total_rows = count($rows);
            $offset = ($page - 1) * $batch_size;
            $display_rows = array_slice($rows, $offset, $batch_size);
            $has_more = ($offset + $batch_size) < $total_rows;

            arsort($region_counts);
            arsort($industry_counts);
            arsort($skill_counts);

            $base_args = [
                'dashboard_tab' => 'home',
                'sffc_reddit_search' => $search_term,
                'discovery_filter' => $discovery_filter,
                'recruiter_region' => $selected_region,
                'recruiter_industry' => $selected_industry,
                'recruiter_skill' => $selected_skill,
            ];

            $filters = [
                [
                    'label' => __('Highest Match', 'senna-finance'),
                    'url' => add_query_arg(array_merge($base_args, ['discovery_filter' => 'highest-match', 'matches_page' => 1]), $current_url),
                    'active' => $discovery_filter === 'highest-match',
                ],
                [
                    'label' => __('Location Fit', 'senna-finance'),
                    'url' => add_query_arg(array_merge($base_args, ['discovery_filter' => 'region-fit', 'matches_page' => 1]), $current_url),
                    'active' => $discovery_filter === 'region-fit',
                ],
                [
                    'label' => __('Industry Contacts', 'senna-finance'),
                    'url' => add_query_arg(array_merge($base_args, ['discovery_filter' => 'industry-fit', 'matches_page' => 1]), $current_url),
                    'active' => $discovery_filter === 'industry-fit',
                ],
                [
                    'label' => __('Skills Fit', 'senna-finance'),
                    'url' => add_query_arg(array_merge($base_args, ['discovery_filter' => 'skills-fit', 'matches_page' => 1]), $current_url),
                    'active' => $discovery_filter === 'skills-fit',
                ],
            ];

            $build_group_options = function ($query_key, $selected_value, array $values) use ($base_args, $current_url) {
                $options = [[
                    'label' => __('All', 'senna-finance'),
                    'url' => add_query_arg(array_merge($base_args, [$query_key => '', 'matches_page' => 1]), $current_url),
                    'active' => $selected_value === '',
                ]];

                foreach (array_slice(array_keys($values), 0, 6) as $value) {
                    if ((string) $value === '') {
                        continue;
                    }
                    $options[] = [
                        'label' => (string) $value,
                        'url' => add_query_arg(array_merge($base_args, [$query_key => (string) $value, 'matches_page' => 1]), $current_url),
                        'active' => $selected_value === (string) $value,
                    ];
                }

                return $options;
            };

            return [
                'rows' => $display_rows,
                'has_more' => $has_more,
                'next_url' => $has_more ? add_query_arg(array_merge($base_args, ['matches_page' => $page + 1]), $current_url) : '',
                'filters' => $filters,
                'filter_groups' => [
                    [
                        'label' => __('Location / Region', 'senna-finance'),
                        'options' => $build_group_options('recruiter_region', $selected_region, $region_counts),
                    ],
                    [
                        'label' => __('Industries Covered', 'senna-finance'),
                        'options' => $build_group_options('recruiter_industry', $selected_industry, $industry_counts),
                    ],
                    [
                        'label' => __('Skills', 'senna-finance'),
                        'options' => $build_group_options('recruiter_skill', $selected_skill, $skill_counts),
                    ],
                ],
            ];
        }

        private function get_crm_reddit_dashboard_hr_outreach_records($search_term = '')
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-outreach.php';

            $search_term = sanitize_text_field((string) $search_term);
            $cache_key = 'sffc_crm_dash_hr_' . md5($search_term);
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            $model = new SFFC_CRM_HR_Outreach();
            $records = $model->get_all([
                'limit' => 1000,
                'offset' => 0,
                'search' => $search_term,
            ]);

            if ($search_term !== '') {
                $needle = $this->normalize_crm_reddit_dashboard_cv_text($search_term);
                $records = array_values(array_filter((array) $records, function ($record) use ($needle) {
                    $haystack = implode(' ', array_filter([
                        (string) ($record['company_name'] ?? ''),
                        (string) ($record['contact_name'] ?? ''),
                        (string) ($record['contact_title'] ?? ''),
                        (string) ($record['location'] ?? ''),
                        (string) ($record['regions'] ?? ''),
                        implode(' ', (array) ($record['industry'] ?? [])),
                        implode(' ', (array) ($record['skills'] ?? [])),
                        (string) ($record['role_focus'] ?? ''),
                    ]));
                    $haystack = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
                    return $haystack !== '' && strpos($haystack, $needle) !== false;
                }));
            }

            set_transient($cache_key, $records, 10 * MINUTE_IN_SECONDS);
            return $records;
        }

        private function score_crm_reddit_dashboard_recruiter_record(array $record, array $cv_profile = [], array $profile_hints = [], $cv_text = '', $has_cv = false)
        {
            $company_name = trim((string) ($record['company_name'] ?? ''));
            $recruiter_name = trim((string) ($record['contact_name'] ?? ''));
            if ($company_name === '' && $recruiter_name === '') {
                return [];
            }
            if ($has_cv && empty($cv_profile)) {
                $cv_profile = $this->build_crm_reddit_dashboard_discovery_cv_profile_fallback($cv_text);
            }
            $recruiter_title = trim((string) ($record['contact_title'] ?? ''));
            if ($recruiter_title === '') {
                $recruiter_title = __('Recruiter', 'senna-finance');
            }

            $location_label = $this->get_crm_reddit_dashboard_app_location_label((string) ($record['location'] ?? ''));
            $region_terms = $this->extract_crm_reddit_dashboard_discovery_terms((string) ($record['regions'] ?? ''));
            if ($location_label !== '' && !in_array($location_label, $region_terms, true)) {
                array_unshift($region_terms, $location_label);
            }

            $industry_labels = array_values(array_filter(array_map([$this, 'format_crm_reddit_dashboard_match_industry_name'], (array) ($record['industry'] ?? []))));
            $skill_labels = array_values(array_filter(array_map([$this, 'format_crm_reddit_dashboard_discovery_term_label'], (array) ($record['skills'] ?? []))));
            $program_labels = array_values(array_filter(array_map([$this, 'format_crm_reddit_dashboard_discovery_term_label'], (array) ($record['program_types'] ?? []))));
            $process_labels = array_values(array_filter(array_map([$this, 'format_crm_reddit_dashboard_discovery_term_label'], (array) ($record['process'] ?? []))));
            $role_focus_excerpt = wp_trim_words(wp_strip_all_tags((string) ($record['role_focus'] ?? '')), 18, '...');
            $team_contact_haystack = $this->normalize_crm_reddit_dashboard_cv_text($this->build_crm_reddit_dashboard_discovery_team_contact_text((array) ($record['team_contacts'] ?? [])));
            $notes_text = $this->normalize_crm_reddit_dashboard_cv_text((string) ($record['notes'] ?? ''));
            $last_hire_proof = $this->normalize_crm_reddit_dashboard_cv_text((string) ($record['last_hire_proof'] ?? ''));
            $role_focus_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                (string) ($record['role_focus'] ?? ''),
                (string) ($record['contact_title'] ?? ''),
                implode(' ', $industry_labels),
                implode(' ', $skill_labels),
                implode(' ', $program_labels),
                implode(' ', $process_labels),
                $notes_text,
                $last_hire_proof,
                $team_contact_haystack,
            ])));
            $region_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', $region_terms));
            $industry_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                implode(' ', $industry_labels),
                implode(' ', $program_labels),
                (string) ($record['role_focus'] ?? ''),
                $notes_text,
                $last_hire_proof,
                $team_contact_haystack,
            ])));
            $skills_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                implode(' ', $skill_labels),
                implode(' ', $process_labels),
                (string) ($record['role_focus'] ?? ''),
                $notes_text,
                $last_hire_proof,
                $team_contact_haystack,
            ])));

            $location_signals = $this->build_crm_reddit_dashboard_discovery_signal_map(
                (array) ($cv_profile['locations'] ?? []),
                (array) ($profile_hints['target_locations'] ?? []),
                0.72
            );
            $industry_signals = $this->build_crm_reddit_dashboard_discovery_signal_map(
                (array) ($cv_profile['sectors'] ?? []),
                (array) ($profile_hints['target_sectors'] ?? []),
                0.7
            );
            $skill_signals = $this->build_crm_reddit_dashboard_discovery_signal_map(
                (array) ($cv_profile['keywords'] ?? []),
                (array) ($profile_hints['technical_skills'] ?? []),
                0.68
            );
            $role_signals = $this->build_crm_reddit_dashboard_discovery_signal_map(
                (array) ($cv_profile['target_roles'] ?? []),
                (array) ($profile_hints['target_roles'] ?? []),
                0.75
            );

            $region_match = $this->score_crm_reddit_dashboard_weighted_signal_match($location_signals, $region_haystack);
            $industry_match = $this->score_crm_reddit_dashboard_weighted_signal_match($industry_signals, $industry_haystack);
            $skill_match = $this->score_crm_reddit_dashboard_weighted_signal_match($skill_signals, $skills_haystack);
            $role_match = $this->score_crm_reddit_dashboard_weighted_signal_match($role_signals, $role_focus_haystack);

            $region_matches = (array) ($region_match['labels'] ?? []);
            $industry_matches = (array) ($industry_match['labels'] ?? []);
            $skill_matches = (array) ($skill_match['labels'] ?? []);
            $role_matches = (array) ($role_match['labels'] ?? []);

            $region_score = min(32, (int) round(((float) ($region_match['score'] ?? 0)) * 18));
            $industry_score = min(28, (int) round(((float) ($industry_match['score'] ?? 0)) * 15));
            $skills_score = min(26, (int) round(((float) ($skill_match['score'] ?? 0)) * 10));
            $role_score = min(22, (int) round(((float) ($role_match['score'] ?? 0)) * 13));

            $seniority_rank = $this->get_crm_reddit_dashboard_cv_seniority_rank($cv_profile, $cv_text);
            $cv_text_normalized = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $has_cfa = strpos($cv_text_normalized, 'cfa') !== false;
            $has_mba = strpos($cv_text_normalized, 'mba') !== false;
            $has_arabic = strpos($cv_text_normalized, 'arabic') !== false;

            $fit_bonus = $this->get_crm_reddit_dashboard_recruiter_seniority_bonus($record, $seniority_rank);
            if ($has_cfa && !empty($record['hire_cfa_holders'])) {
                $fit_bonus += 8;
            }
            if ($has_mba && !empty($record['hire_mba'])) {
                $fit_bonus += 8;
            }
            if ($has_arabic && (!empty($record['hire_arabic_speakers']) || !empty($record['hire_bilingual']))) {
                $fit_bonus += 5;
            }
            if (!empty($record['hire_visa_sponsorship'])) {
                $fit_bonus += 3;
            }
            if (!empty($record['hire_expats'])) {
                $fit_bonus += 3;
            }
            if (!empty($record['hire_non_target']) && $seniority_rank <= 2) {
                $fit_bonus += 2;
            }
            if (!empty($record['hire_oxbridge']) || !empty($record['hire_russell_group'])) {
                $fit_bonus += $has_mba ? 2 : 0;
            }

            $score = $has_cv ? max(4, min(98, $region_score + $industry_score + $skills_score + $role_score + $fit_bonus)) : 0;
            $match_tone = !$has_cv ? 'caution' : ($score >= 75 ? 'positive' : ($score >= 55 ? 'neutral' : 'caution'));

            $fit_flags = [];
            foreach (
                [
                    'hire_seniors' => __('Senior-friendly', 'senna-finance'),
                    'hire_associates' => __('Associate-friendly', 'senna-finance'),
                    'hire_analysts' => __('Execution-to-manager hiring', 'senna-finance'),
                    'hire_mba' => __('MBA-friendly', 'senna-finance'),
                    'hire_cfa_holders' => __('CFA-friendly', 'senna-finance'),
                    'hire_visa_sponsorship' => __('Visa sponsorship', 'senna-finance'),
                    'hire_expats' => __('Expat hiring', 'senna-finance'),
                ] as $flag_key => $flag_label
            ) {
                if (!empty($record[$flag_key])) {
                    $fit_flags[] = $flag_label;
                }
            }

            $match_reasons = [];
            if (!empty($region_matches)) {
                $match_reasons[] = __('Location fit', 'senna-finance');
            }
            if (!empty($industry_matches)) {
                $match_reasons[] = __('Industry contact', 'senna-finance');
            }
            if (!empty($skill_matches)) {
                $match_reasons[] = __('Relevant skills', 'senna-finance');
            }
            if (!empty($role_matches)) {
                $match_reasons[] = __('Career fit focus', 'senna-finance');
            }
            if ($fit_bonus >= 10) {
                $match_reasons[] = __('Candidate level fit', 'senna-finance');
            }

            return [
                'score' => $score,
                'region_score' => $region_score,
                'industry_score' => $industry_score,
                'skills_score' => $skills_score,
                'recent_timestamp' => !empty($record['updated_at'])
                    ? (int) strtotime((string) $record['updated_at'])
                    : (!empty($record['created_at']) ? (int) strtotime((string) $record['created_at']) : 0),
                'match_label' => $has_cv ? sprintf(__('%d%%', 'senna-finance'), $score) : __('Add CV', 'senna-finance'),
                'match_tone' => $match_tone,
                'match_reason' => !empty($match_reasons) ? implode(' · ', array_slice($match_reasons, 0, 2)) : __('Contact relevance', 'senna-finance'),
                'recruiter_name' => $recruiter_name !== '' ? $recruiter_name : __('Talent Team', 'senna-finance'),
                'recruiter_title' => $recruiter_title,
                'recruiter_photo' => (string) ($record['contact_photo'] ?? ''),
                'recruiter_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 1) : substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 1)),
                'team_contacts_label' => !empty($record['team_contacts']) && is_array($record['team_contacts'])
                    ? sprintf(_n('%d extra contact', '%d extra contacts', count($record['team_contacts']), 'senna-finance'), count($record['team_contacts']))
                    : '',
                'company_name' => $company_name !== '' ? $company_name : __('Recruiting Firm', 'senna-finance'),
                'company_logo' => (string) ($record['company_logo'] ?? ''),
                'company_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($company_name !== '' ? $company_name : 'C', 0, 1) : substr($company_name !== '' ? $company_name : 'C', 0, 1)),
                'company_url' => (string) ($record['company_url'] ?? ''),
                'location_label' => $location_label,
                'regions_label' => implode(', ', array_slice($region_terms, 0, 3)),
                'region_terms' => $region_terms,
                'region_terms_normalized' => array_map([$this, 'normalize_crm_reddit_dashboard_cv_text'], $region_terms),
                'industry_labels' => array_slice($industry_labels, 0, 4),
                'industry_labels_normalized' => array_map([$this, 'normalize_crm_reddit_dashboard_cv_text'], $industry_labels),
                'skill_labels' => array_slice($skill_labels, 0, 4),
                'skill_labels_normalized' => array_map([$this, 'normalize_crm_reddit_dashboard_cv_text'], $skill_labels),
                'role_focus_excerpt' => $role_focus_excerpt !== '' ? $role_focus_excerpt : __('Active private equity hiring contact.', 'senna-finance'),
                'fit_flags' => array_slice($fit_flags, 0, 3),
                'contact_email' => sanitize_email((string) ($record['contact_email'] ?? '')),
                'contact_linkedin' => esc_url_raw((string) ($record['contact_linkedin'] ?? '')),
                'dismiss_key' => $this->get_cv_match_recruiter_discovery_dismiss_key([
                    'recruiter_name' => $recruiter_name !== '' ? $recruiter_name : __('Talent Team', 'senna-finance'),
                    'recruiter_title' => $recruiter_title,
                    'company_name' => $company_name !== '' ? $company_name : __('Recruiting Firm', 'senna-finance'),
                    'contact_email' => sanitize_email((string) ($record['contact_email'] ?? '')),
                    'contact_linkedin' => esc_url_raw((string) ($record['contact_linkedin'] ?? '')),
                    'company_url' => esc_url_raw((string) ($record['company_url'] ?? '')),
                ]),
            ];
        }

        private function build_crm_reddit_dashboard_discovery_cv_profile_fallback($cv_text)
        {
            $cv_text = trim((string) $cv_text);
            if ($cv_text === '') {
                return [];
            }

            return [
                'locations' => $this->extract_crm_reddit_cv_location_signals($cv_text, 6),
                'target_roles' => $this->extract_crm_reddit_cv_role_signals($cv_text, 6),
                'sectors' => $this->extract_crm_reddit_cv_sector_signals($cv_text, 6),
                'keywords' => $this->extract_crm_reddit_cv_keyword_signals($cv_text, 12),
                'seniority' => $this->extract_crm_reddit_cv_seniority_signals($cv_text, 4),
            ];
        }

        private function build_crm_reddit_dashboard_discovery_signal_map(array $weighted_signals = [], array $hint_signals = [], $hint_weight = 0.7)
        {
            $map = [];

            foreach ($weighted_signals as $signal) {
                $label = is_array($signal)
                    ? (string) ($signal['label'] ?? $signal['name'] ?? $signal['term'] ?? '')
                    : (string) $signal;
                $weight = is_array($signal) ? (float) ($signal['weight'] ?? 0.5) : 0.5;
                $normalized = $this->normalize_crm_reddit_dashboard_cv_text($label);
                if ($normalized === '') {
                    continue;
                }

                $map[$normalized] = [
                    'label' => trim($label),
                    'weight' => max(0.1, min(1.0, $weight)),
                ];
            }

            foreach ($hint_signals as $signal) {
                $label = trim((string) $signal);
                $normalized = $this->normalize_crm_reddit_dashboard_cv_text($label);
                if ($normalized === '') {
                    continue;
                }

                if (empty($map[$normalized])) {
                    $map[$normalized] = [
                        'label' => $label,
                        'weight' => max(0.1, min(1.0, (float) $hint_weight)),
                    ];
                } else {
                    $map[$normalized]['weight'] = max((float) $map[$normalized]['weight'], (float) $hint_weight);
                }
            }

            uasort($map, static function ($left, $right) {
                return ((float) ($right['weight'] ?? 0)) <=> ((float) ($left['weight'] ?? 0));
            });

            return $map;
        }

        private function score_crm_reddit_dashboard_weighted_signal_match(array $signal_map, $haystack)
        {
            $haystack = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
            if ($haystack === '' || empty($signal_map)) {
                return ['score' => 0.0, 'labels' => []];
            }

            $score = 0.0;
            $labels = [];
            foreach ($signal_map as $normalized => $signal) {
                $normalized = $this->normalize_crm_reddit_dashboard_cv_text((string) $normalized);
                if ($normalized === '') {
                    continue;
                }

                $match_strength = 0.0;
                if (strpos($haystack, $normalized) !== false) {
                    $match_strength = 1.0;
                } else {
                    $tokens = array_values(array_filter(preg_split('/\s+/', $normalized), static function ($token) {
                        return strlen((string) $token) >= 4;
                    }));
                    if (count($tokens) >= 2) {
                        $token_matches = 0;
                        foreach ($tokens as $token) {
                            if (strpos($haystack, (string) $token) !== false) {
                                $token_matches++;
                            }
                        }
                        if ($token_matches >= max(2, count($tokens) - 1)) {
                            $match_strength = 0.68;
                        }
                    }
                }

                if ($match_strength <= 0) {
                    continue;
                }

                $score += ((float) ($signal['weight'] ?? 0.5)) * $match_strength;
                $labels[] = (string) ($signal['label'] ?? $normalized);
            }

            return [
                'score' => $score,
                'labels' => array_values(array_unique($labels)),
            ];
        }

        private function build_crm_reddit_dashboard_discovery_team_contact_text(array $team_contacts = [])
        {
            $parts = [];
            foreach ($team_contacts as $contact) {
                if (!is_array($contact)) {
                    continue;
                }
                foreach (['name', 'title', 'email', 'phone', 'linkedin'] as $field) {
                    if (!empty($contact[$field])) {
                        $parts[] = (string) $contact[$field];
                    }
                }
            }

            return implode(' ', $parts);
        }

        private function get_crm_reddit_dashboard_recruiter_seniority_bonus(array $record, $seniority_rank)
        {
            $seniority_rank = max(0, (int) $seniority_rank);
            $junior_only = empty($record['hire_seniors'])
                && empty($record['hire_associates'])
                && empty($record['hire_analysts'])
                && empty($record['hire_mba'])
                && (
                    !empty($record['hire_interns'])
                    || !empty($record['hire_graduates'])
                    || !empty($record['hire_placement'])
                    || !empty($record['hire_trainee'])
                );

            if ($seniority_rank >= 4) {
                if (!empty($record['hire_seniors'])) {
                    return 16;
                }
                if (!empty($record['hire_associates'])) {
                    return 8;
                }
                if ($junior_only) {
                    return -34;
                }
                return -14;
            }

            if ($seniority_rank === 3) {
                if (!empty($record['hire_seniors'])) {
                    return 14;
                }
                if (!empty($record['hire_associates'])) {
                    return 10;
                }
                if (!empty($record['hire_analysts'])) {
                    return 4;
                }
                if ($junior_only) {
                    return -28;
                }
                return -10;
            }

            if ($seniority_rank === 2) {
                if (!empty($record['hire_associates'])) {
                    return 12;
                }
                if (!empty($record['hire_analysts'])) {
                    return 8;
                }
                if (!empty($record['hire_interns']) || !empty($record['hire_graduates'])) {
                    return -8;
                }
                return 0;
            }

            if ($seniority_rank === 1) {
                if (!empty($record['hire_analysts'])) {
                    return 10;
                }
                if (!empty($record['hire_associates'])) {
                    return 4;
                }
                if (!empty($record['hire_interns']) || !empty($record['hire_graduates'])) {
                    return -4;
                }
                return 0;
            }

            if (!empty($record['hire_interns']) || !empty($record['hire_graduates']) || !empty($record['hire_placement']) || !empty($record['hire_trainee'])) {
                return 10;
            }

            if (!empty($record['hire_seniors'])) {
                return -10;
            }

            return 0;
        }

        private function extract_crm_reddit_dashboard_signal_labels(array $signals)
        {
            $labels = [];
            foreach ($signals as $signal) {
                if (is_array($signal)) {
                    $raw = $signal['label'] ?? $signal['name'] ?? $signal['term'] ?? '';
                } else {
                    $raw = (string) $signal;
                }
                $label = $this->normalize_crm_reddit_dashboard_cv_text($raw);
                if ($label !== '') {
                    $labels[] = $label;
                }
            }

            return array_values(array_unique($labels));
        }

        private function extract_crm_reddit_dashboard_discovery_terms($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return [];
            }

            $parts = preg_split('/[,|\/]+/', $value);
            $parts = array_values(array_filter(array_map('trim', (array) $parts)));

            return array_values(array_unique($parts));
        }

        private function format_crm_reddit_dashboard_discovery_term_label($value)
        {
            $value = trim(str_replace(['_', '-'], ' ', (string) $value));
            if ($value === '') {
                return '';
            }

            return ucwords($value);
        }

        private function match_crm_reddit_dashboard_signals_to_haystack(array $signals, $haystack)
        {
            $haystack = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
            if ($haystack === '' || empty($signals)) {
                return [];
            }

            $matches = [];
            foreach ($signals as $signal) {
                $signal = $this->normalize_crm_reddit_dashboard_cv_text($signal);
                if ($signal === '') {
                    continue;
                }
                if (strpos($haystack, $signal) !== false) {
                    $matches[] = $signal;
                }
            }

            return array_values(array_unique($matches));
        }

        private function get_crm_reddit_dashboard_cv_seniority_rank(array $cv_profile = [], $cv_text = '')
        {
            $best_rank = null;

            foreach ((array) ($cv_profile['seniority'] ?? []) as $signal) {
                $label = is_array($signal)
                    ? (string) ($signal['label'] ?? $signal['name'] ?? '')
                    : (string) $signal;
                $rank = $this->map_crm_reddit_dashboard_seniority_label_to_rank($label);
                if ($rank !== null) {
                    $best_rank = max($best_rank ?? $rank, $rank);
                }
            }

            if ($best_rank !== null) {
                return (int) $best_rank;
            }

            return (int) max(0, (int) ($this->infer_crm_reddit_dashboard_seniority_rank_from_cv_text($cv_text) ?? 0));
        }

        private function infer_crm_reddit_dashboard_seniority_rank_from_cv_text($cv_text)
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            if ($cv_text === '') {
                return null;
            }

            foreach (
                [
                    'managing director',
                    'director',
                    'vice president',
                    'head of',
                    'portfolio manager',
                    'senior manager',
                    'manager',
                    'associate',
                    'analyst',
                    'intern',
                    'graduate',
                ] as $phrase
            ) {
                $rank = $this->map_crm_reddit_dashboard_seniority_label_to_rank($phrase);
                if ($rank !== null && strpos($cv_text, $phrase) !== false) {
                    return $rank;
                }
            }

            return null;
        }

        private function detect_crm_reddit_dashboard_cv_role_signal($cv_text, array $items)
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_signal_text($cv_text);
            if ($cv_text === '' || empty($items)) {
                return [];
            }

            $role_counts = [];
            foreach ($items as $item) {
                foreach ($this->build_crm_reddit_dashboard_role_phrases_from_title((string) ($item['role_title'] ?? '')) as $phrase) {
                    if ($this->is_crm_reddit_dashboard_noise_phrase($phrase)) {
                        continue;
                    }
                    $mentions = $this->count_crm_reddit_dashboard_phrase_mentions($cv_text, $phrase);
                    if ($mentions <= 0) {
                        continue;
                    }
                    $role_counts[$phrase] = max((int) ($role_counts[$phrase] ?? 0), $mentions);
                }
            }

            if (empty($role_counts)) {
                return [];
            }

            uksort($role_counts, static function ($left, $right) use ($role_counts) {
                $count_compare = ((int) ($role_counts[$right] ?? 0)) <=> ((int) ($role_counts[$left] ?? 0));
                if ($count_compare !== 0) {
                    return $count_compare;
                }

                return strlen((string) $right) <=> strlen((string) $left);
            });

            $top_label = (string) array_key_first($role_counts);
            $top_count = (int) ($role_counts[$top_label] ?? 0);

            if ($top_label === '' || $top_count < 2) {
                return [];
            }

            return [
                'label' => $this->format_crm_reddit_dashboard_signal_phrase($top_label),
                'mentions' => $top_count,
                'counts' => $role_counts,
            ];
        }

        private function build_crm_reddit_dashboard_role_phrases_from_title($title)
        {
            $title = strtolower(trim((string) $title));
            if ($title === '') {
                return [];
            }

            $title = preg_replace('/\s+/', ' ', (string) $title);
            $segments = preg_split('/\s*[\|\-\/,\(\)]\s*/', $title);
            $phrases = [];

            foreach ((array) $segments as $segment) {
                $segment = trim((string) $segment);
                if ($segment === '' || $this->is_crm_reddit_dashboard_noise_phrase($segment)) {
                    continue;
                }

                $phrases[$segment] = true;
                $tokens = array_values(array_filter(preg_split('/\s+/', $segment), static function ($token) {
                    return strlen((string) $token) >= 3;
                }));

                $token_count = count($tokens);
                for ($start = 0; $start < $token_count; $start++) {
                    for ($length = 2; $length <= 3; $length++) {
                        $slice = array_slice($tokens, $start, $length);
                        if (count($slice) !== $length) {
                            continue;
                        }
                        $phrase = trim(implode(' ', $slice));
                        if ($phrase !== '' && !$this->is_crm_reddit_dashboard_noise_phrase($phrase)) {
                            $phrases[$phrase] = true;
                        }
                    }
                }
            }

            return array_keys($phrases);
        }

        private function normalize_crm_reddit_dashboard_signal_text($text)
        {
            $text = strtolower(wp_strip_all_tags((string) $text));
            $text = preg_replace('/[\r\n\t]+/', ' ', (string) $text);
            $text = preg_replace('/[^a-z0-9\+\#\.\-&\/ ]+/i', ' ', (string) $text);
            $text = preg_replace('/\s+/', ' ', (string) $text);

            return trim((string) $text);
        }

        private function count_crm_reddit_dashboard_phrase_mentions($haystack, $phrase)
        {
            $haystack = trim((string) $haystack);
            $phrase = trim((string) $phrase);
            if ($haystack === '' || $phrase === '') {
                return 0;
            }

            $pattern = '/(?<![a-z0-9])' . preg_quote($phrase, '/') . '(?![a-z0-9])/i';
            preg_match_all($pattern, $haystack, $matches);

            return (int) count((array) ($matches[0] ?? []));
        }

        private function is_crm_reddit_dashboard_noise_phrase($phrase)
        {
            $phrase = trim(strtolower((string) $phrase));
            if ($phrase === '') {
                return true;
            }

            static $noise = [
                'date',
                'dates',
                'graduation',
                'graduate',
                'graduated',
                'month',
                'months',
                'january',
                'february',
                'march',
                'april',
                'may',
                'june',
                'july',
                'august',
                'september',
                'october',
                'november',
                'december',
                'jan',
                'feb',
                'mar',
                'apr',
                'jun',
                'jul',
                'aug',
                'sep',
                'sept',
                'oct',
                'nov',
                'dec',
                'present',
                'curriculum vitae',
                'resume',
                'education',
                'experience',
                'skills',
                'email',
                'phone',
                'linkedin',
                'university',
                'bachelor',
                'masters',
                'master',
                'degree',
                'analyst',
                'associate',
                'director',
                'manager',
                'consultant',
                'intern',
                'vice president',
                'president',
                'partner',
                'officer',
            ];

            if (in_array($phrase, $noise, true)) {
                return true;
            }

            if (strlen($phrase) < 4) {
                return true;
            }

            return false;
        }

        private function format_crm_reddit_dashboard_signal_phrase($phrase)
        {
            $phrase = trim((string) $phrase);
            if ($phrase === '') {
                return '';
            }

            $map = [
                'pe' => 'Finance',
                'ib' => 'Investment Banking',
                'm&a' => 'M&A',
                'fp&a' => 'FP&A',
            ];

            $lower = strtolower($phrase);
            if (isset($map[$lower])) {
                return $map[$lower];
            }

            return ucwords($phrase);
        }

        private function build_crm_reddit_dashboard_location_hints($cv_text, array $available_locations, array $cv_profile = [])
        {
            $cv_text = $this->normalize_crm_reddit_dashboard_signal_text($cv_text);
            $hints = [];
            $cv_location_signals = [];
            foreach ((array) ($cv_profile['locations'] ?? []) as $signal) {
                $label = $this->get_crm_reddit_dashboard_app_location_label((string) ($signal['label'] ?? ''));
                if ($label === '') {
                    continue;
                }
                $cv_location_signals[strtolower($label)] = max(
                    (int) ($cv_location_signals[strtolower($label)] ?? 0),
                    max(1, (int) round(((float) ($signal['weight'] ?? 0)) * 3))
                );
            }

            foreach ($available_locations as $location_name) {
                $label = $this->get_crm_reddit_dashboard_app_location_label((string) $location_name);
                if ($label === '') {
                    continue;
                }

                $location_key = strtolower($label);
                $mentions = $cv_text !== '' ? $this->count_crm_reddit_dashboard_phrase_mentions($cv_text, $location_key) : 0;
                $mentions = max($mentions, (int) ($cv_location_signals[$location_key] ?? 0));
                if ($mentions > 0) {
                    $hints[$location_key] = [
                        'label' => $label,
                        'mentions' => $mentions,
                        'source' => 'cv',
                    ];
                }
            }

            uasort($hints, static function ($left, $right) {
                $mention_compare = ((int) ($right['mentions'] ?? 0)) <=> ((int) ($left['mentions'] ?? 0));
                if ($mention_compare !== 0) {
                    return $mention_compare;
                }

                return strcmp((string) ($left['label'] ?? ''), (string) ($right['label'] ?? ''));
            });

            return array_values($hints);
        }

        private function does_crm_reddit_dashboard_keyword_match_profile($keyword, $cv_text = '', array $profile_skills = [])
        {
            $keyword = strtolower(trim((string) $keyword));
            if ($keyword === '') {
                return false;
            }

            $cv_text = strtolower(trim((string) $cv_text));
            if ($cv_text !== '' && strpos($cv_text, $keyword) !== false) {
                return true;
            }

            $keyword_tokens = array_values(array_filter(preg_split('/[^a-z0-9\+#\.]+/i', $keyword)));

            foreach ($profile_skills as $profile_skill) {
                $profile_skill = strtolower(trim((string) $profile_skill));
                if ($profile_skill === '') {
                    continue;
                }

                if ($profile_skill === $keyword || strpos($profile_skill, $keyword) !== false || strpos($keyword, $profile_skill) !== false) {
                    return true;
                }
            }

            if ($cv_text !== '' && count($keyword_tokens) > 1) {
                $matched_tokens = 0;
                foreach ($keyword_tokens as $token) {
                    if (strlen($token) < 3) {
                        continue;
                    }
                    if (strpos($cv_text, $token) !== false) {
                        $matched_tokens++;
                    }
                }
                if ($matched_tokens >= max(2, count($keyword_tokens) - 1)) {
                    return true;
                }
            }

            return false;
        }

        private function build_crm_reddit_dashboard_skills_in_demand_rows(array $role_keywords, $cv_text = '', array $profile_skills = [])
        {
            if (empty($role_keywords)) {
                return [
                    'rows' => [],
                    'matched_count' => 0,
                ];
            }

            $matched = [];
            $unmatched = [];
            $matched_count = 0;

            foreach ($role_keywords as $keyword => $count) {
                $keyword = trim((string) $keyword);
                if ($keyword === '') {
                    continue;
                }

                $is_match = $this->does_crm_reddit_dashboard_keyword_match_profile($keyword, $cv_text, $profile_skills);
                $mentions = $cv_text !== '' ? $this->count_crm_reddit_dashboard_phrase_mentions($this->normalize_crm_reddit_dashboard_signal_text($cv_text), strtolower($keyword)) : 0;
                if ($is_match) {
                    $matched_count++;
                }

                $row = [
                    'primary' => $keyword,
                    'secondary' => $is_match
                        ? sprintf(
                            _n('%1$d live role · mentioned %2$dx in your CV', '%1$d live roles · mentioned %2$dx in your CV', (int) $count, 'senna-finance'),
                            (int) $count,
                            max(1, (int) $mentions)
                        )
                        : sprintf(__('%d live roles · worth surfacing more clearly', 'senna-finance'), (int) $count),
                    'initial' => strtoupper(function_exists('mb_substr') ? mb_substr($keyword, 0, 1) : substr($keyword, 0, 1)),
                    '_mentions' => (int) $mentions,
                    '_count' => (int) $count,
                ];

                if ($is_match) {
                    $matched[] = $row;
                } else {
                    $unmatched[] = $row;
                }
            }

            usort($matched, static function ($left, $right) {
                $mention_compare = ((int) ($right['_mentions'] ?? 0)) <=> ((int) ($left['_mentions'] ?? 0));
                if ($mention_compare !== 0) {
                    return $mention_compare;
                }

                return ((int) ($right['_count'] ?? 0)) <=> ((int) ($left['_count'] ?? 0));
            });

            usort($unmatched, static function ($left, $right) {
                return ((int) ($right['_count'] ?? 0)) <=> ((int) ($left['_count'] ?? 0));
            });

            $rows = array_slice(array_merge($matched, $unmatched), 0, 4);
            $rows = array_map(static function ($row) {
                unset($row['_mentions'], $row['_count']);
                return $row;
            }, $rows);

            return [
                'rows' => $rows,
                'matched_count' => $matched_count,
            ];
        }

        private function build_crm_reddit_dashboard_app_location_rows(array $locations, array $priority_locations = [])
        {
            $ordered_locations = [];
            $priority_lookup = [];
            foreach ($priority_locations as $priority_location) {
                $key = strtolower((string) ($priority_location['label'] ?? ''));
                if ($key === '') {
                    continue;
                }
                $priority_lookup[$key] = (array) $priority_location;
            }

            foreach ($locations as $location => $meta) {
                if (isset($priority_lookup[strtolower((string) $location)])) {
                    $ordered_locations[$location] = $meta;
                }
            }

            foreach ($locations as $location => $meta) {
                if (!isset($ordered_locations[$location])) {
                    $ordered_locations[$location] = $meta;
                }
            }

            $rows = [];
            foreach (array_slice($ordered_locations, 0, 3, true) as $location => $meta) {
                $priority_meta = (array) ($priority_lookup[strtolower((string) $location)] ?? []);
                $is_priority = !empty($priority_meta);
                $rows[] = [
                    'primary' => (string) $location,
                    'secondary' => $is_priority
                        ? sprintf(
                            __('Seen %3$dx in your CV/profile · %1$d live roles · %2$d recent', 'senna-finance'),
                            (int) ($meta['count'] ?? 0),
                            (int) ($meta['recent'] ?? 0),
                            max(1, (int) ($priority_meta['mentions'] ?? 1))
                        )
                        : sprintf(
                            __('%1$d live roles · %2$d recent', 'senna-finance'),
                            (int) ($meta['count'] ?? 0),
                            (int) ($meta['recent'] ?? 0)
                        ),
                    'initial' => strtoupper(function_exists('mb_substr') ? mb_substr((string) $location, 0, 1) : substr((string) $location, 0, 1)),
                ];
            }

            return $rows;
        }

        private function build_crm_reddit_dashboard_app_company_rows(array $companies, $suffix)
        {
            $rows = [];
            foreach (array_slice($companies, 0, 3, true) as $company => $meta) {
                $rows[] = [
                    'primary' => (string) $company,
                    'secondary' => trim((string) ($meta['secondary'] ?? '') . ' · ' . sprintf(__('%d %s', 'senna-finance'), (int) ($meta['count'] ?? 0), $suffix)),
                    'initial' => strtoupper(function_exists('mb_substr') ? mb_substr((string) $company, 0, 1) : substr((string) $company, 0, 1)),
                ];
            }

            return $rows;
        }

        private function build_crm_reddit_feed_match_reason(array $item)
        {
            $role_title = trim((string) ($item['role_title'] ?? __('this role', 'senna-finance')));
            $company = trim((string) ($item['company'] ?? __('the firm', 'senna-finance')));
            $location = trim((string) ($item['location'] ?? ''));
            $seniority = trim((string) ($item['seniority'] ?? ''));
            $employment_type = trim((string) ($item['employment_type'] ?? ''));
            $opportunity_notice = $this->get_crm_reddit_opportunity_notice($item);

            if (!empty($opportunity_notice['meta'])) {
                return (string) $opportunity_notice['meta'];
            }

            $role_bits = array_values(array_filter([$seniority, $employment_type]));
            $role_shape = !empty($role_bits) ? implode(' ', $role_bits) : __('recruiter-led', 'senna-finance');

            if ($location !== '') {
                return sprintf(
                    __('Matched because this %1$s opportunity at %2$s in %3$s is live now and lines up with the kind of role candidates usually want surfaced quickly.', 'senna-finance'),
                    $role_shape,
                    $company,
                    $location
                );
            }

            return sprintf(
                __('Matched because %1$s at %2$s is a live recruiter-led opportunity and the role title is close to the roles candidates usually want prioritised first.', 'senna-finance'),
                $role_title,
                $company
            );
        }

        private function format_crm_reddit_job_content($content)
        {
            $content = trim((string) $content);
            if ($content === '') {
                return '';
            }

            $content = wp_kses_post($content);

            // Respect existing block/HTML content, otherwise turn plain text into paragraphs.
            if (strpos($content, '<') !== false) {
                return $content;
            }

            return wpautop($content);
        }

