        private function get_crm_reddit_single_job_ai_overview(array $item, array $analysis)
        {
            $post_id = (int) ($item['post_id'] ?? 0);
            $intel_hash = $this->get_crm_reddit_single_job_intel_hash($item);
            if ($post_id > 0) {
                $stored = $this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'overview', $intel_hash);
                if ($this->is_crm_reddit_single_job_ai_overview_payload($stored)) {
                    return $stored;
                }
            }

            $overview = $this->generate_crm_reddit_single_job_ai_overview($item, $analysis);
            if ($post_id > 0 && $this->is_crm_reddit_single_job_ai_overview_payload($overview)) {
                $this->store_crm_reddit_single_job_intel_payload($post_id, 'overview', $overview, $intel_hash);
            }

            return $overview;
        }

        private function get_crm_reddit_single_job_ai_overview_fast(array $item, array $analysis)
        {
            $post_id = (int) ($item['post_id'] ?? 0);
            $intel_hash = $this->get_crm_reddit_single_job_intel_hash($item);
            if ($post_id > 0) {
                $stored = $this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'overview', $intel_hash);
                if ($this->is_crm_reddit_single_job_ai_overview_payload($stored)) {
                    return $stored;
                }
            }

            return $this->build_crm_reddit_single_job_ai_overview_fallback($item, $analysis);
        }

        private function generate_crm_reddit_single_job_ai_overview(array $item, array $analysis)
        {
            $description_text = $this->get_crm_reddit_single_job_description_text($item);
            $fallback = $this->build_crm_reddit_single_job_ai_overview_fallback($item, $analysis);

            if ($description_text === '') {
                return $fallback;
            }

            $post_id = (int) ($item['post_id'] ?? 0);
            $cache_seed = $post_id > 0
                ? $post_id . '|' . (string) get_post_modified_time('U', true, $post_id)
                : md5(wp_json_encode([$item['role_title'] ?? '', $item['company'] ?? '', $description_text]));
            $cache_seed .= '|role-overview-v2';
            $cache_key = 'sffc_crm_job_ai_' . md5($cache_seed);
            $cached = get_transient($cache_key);

            if ($this->is_crm_reddit_single_job_ai_overview_payload($cached)) {
                return $cached;
            }

            $claude = $this->call_crm_reddit_single_job_overview_claude([
                'role_title' => (string) ($item['role_title'] ?? ''),
                'company' => (string) ($item['company'] ?? ''),
                'location' => (string) ($item['location'] ?? ''),
                'seniority' => (string) ($item['seniority'] ?? ''),
                'employment_type' => (string) ($item['employment_type'] ?? ''),
                'recruiter_name' => (string) ($item['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($item['recruiter_title'] ?? ''),
                'recruiter_email' => (string) ($item['recruiter_email'] ?? ''),
                'recruiter_linkedin' => (string) ($item['recruiter_linkedin'] ?? ''),
                'description_text' => $description_text,
                'analysis' => $analysis,
            ]);

            $overview = $this->merge_crm_reddit_single_job_ai_overview($fallback, is_array($claude) ? $claude : []);
            set_transient($cache_key, $overview, $this->get_crm_reddit_single_job_role_cache_ttl());

            return $overview;
        }

