        private function build_crm_reddit_single_job_ai_overview_fallback(array $item, array $analysis)
        {
            $role_title = trim((string) ($item['role_title'] ?? __('This role', 'senna-finance')));
            $company = trim((string) ($item['company'] ?? __('the firm', 'senna-finance')));
            $top_skills = array_values(array_filter((array) ($analysis['top_skills'] ?? [])));
            $backgrounds = array_values(array_filter((array) ($analysis['backgrounds'] ?? [])));
