        private function build_crm_reddit_single_job_profile_comparison_fallback(array $item, array $analysis, $cv_text)
        {
            $terminal_profile = $this->build_crm_reddit_single_job_terminal_profile_comparison($item, $cv_text, $analysis);
            if (!empty($terminal_profile)) {
                return $terminal_profile;
            }

            $role_title = trim((string) ($item['role_title'] ?? __('this role', 'senna-finance')));
            $company = trim((string) ($item['company'] ?? __('the firm', 'senna-finance')));
            $skills = array_values(array_filter((array) ($analysis['top_skills'] ?? [])));
            $backgrounds = array_values(array_filter((array) ($analysis['backgrounds'] ?? [])));
            $qualifications = array_values(array_filter((array) ($analysis['qualifications'] ?? [])));
            $required_years = trim((string) ($analysis['required_years'] ?? ''));
            $matches = array_values(array_unique(array_filter(array_slice($skills, 0, 4))));
            $gaps = array_values(array_unique(array_filter(array_slice(array_merge($qualifications, $backgrounds), 0, 4))));

            $paragraphs = [];
            $paragraphs[] = sprintf(
                __('This %1$s brief at %2$s is most obviously rewarding candidates who make %3$s visible early and keep the experience story close to the role language from the first screening pass.', 'senna-finance'),
                $role_title,
                $company,
                !empty($matches) ? implode(', ', array_slice($matches, 0, 3)) : __('the strongest role signals', 'senna-finance')
            );

            $missing_summary = implode(', ', array_slice($gaps, 0, 3));
            $paragraphs[] = sprintf(
                __('The biggest improvement is to make %1$s more obvious%2$s so the CV reads closer to what this team is screening for, even before any recruiter follow-up.', 'senna-finance'),
                $missing_summary !== '' ? $missing_summary : __('your most relevant finance evidence', 'senna-finance'),
                $required_years !== '' ? ' and show ' . $required_years . ' more clearly' : ''
            );

            return [
                'paragraphs' => $paragraphs,
                'highlights' => array_slice(array_values(array_unique(array_merge(array_slice($matches, 0, 2), array_slice($gaps, 0, 2)))), 0, 4),
                'metrics' => $this->build_crm_reddit_single_job_profile_preview_metrics($analysis),
                'preview_metrics' => $this->build_crm_reddit_single_job_profile_preview_metrics($analysis),
                'matched_signals' => array_slice($matches, 0, 4),
                'missing_signals' => array_slice($gaps, 0, 4),
                'cv_fix_points' => $this->build_crm_reddit_single_job_cv_fix_points($analysis, $matches, $gaps),
                'keyword_swaps' => $this->build_crm_reddit_single_job_keyword_swaps('', $analysis, $gaps),
            ];
        }

        private function build_crm_reddit_single_job_terminal_profile_comparison(array $item, $cv_text, array $analysis = [])
        {
            $cv_text = trim((string) $cv_text);
            if ($cv_text === '') {
                return [];
            }

            $description_text = $this->get_crm_reddit_single_job_description_text($item);
            if ($description_text === '') {
                return [];
            }

            static $runtime_cache = [];

            $post_id = (int) ($item['post_id'] ?? 0);
            $cache_seed = ($post_id > 0 ? (string) $post_id : md5($description_text))
                . '|'
                . md5($cv_text)
                . '|single-job-profile-fallback-v1';

            if (isset($runtime_cache[$cache_seed]) && is_array($runtime_cache[$cache_seed])) {
                return $runtime_cache[$cache_seed];
            }

            $transient_key = 'sffc_crm_job_profile_fb_' . md5($cache_seed);
            $cached = get_transient($transient_key);
            if ($this->is_crm_reddit_single_job_profile_payload($cached)) {
                $runtime_cache[$cache_seed] = $cached;
                return $cached;
            }

            if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
            }

            $base_path = SFFC_PLUGIN_DIR . 'includes/application-planner/';
            $required_files = [
                'class-knowledge-base.php',
                'class-jd-parser.php',
                'class-cv-parser.php',
                'class-ai-analyzer.php',
                'class-fallback-analyzer.php',
                'class-ats-analyzer.php',
                'class-gap-analyzer.php',
            ];

            foreach ($required_files as $file) {
                $path = $base_path . $file;
                if (file_exists($path)) {
                    require_once $path;
                }
            }

            if (!class_exists('SFFC_Gap_Analyzer') || !function_exists('sffc_build_crm_jd_text_for_analysis')) {
                return [];
            }

            $jd_text = trim((string) sffc_build_crm_jd_text_for_analysis($item));
            if ($jd_text === '') {
                return [];
            }

            $gap_analyzer = new SFFC_Gap_Analyzer();
            $gap_analyzer->set_mode('fallback_only');
            $result = $gap_analyzer->analyze_for_terminal($jd_text, $cv_text);

            $scores = is_array($result['scores'] ?? null) ? $result['scores'] : [];
            $match_score = max(
                0,
                min(
                    100,
                    (int) ($result['executive_summary']['match_score'] ?? $result['overall_assessment']['fit_percentage'] ?? $scores['overall'] ?? 0)
                )
            );

            if ($match_score <= 0) {
                return [];
            }

            $matched_signals = array_values(array_filter(array_map('strval', (array) ($result['skills_breakdown']['matched_skills'] ?? []))));
            $missing_signals = array_values(array_filter(array_map('strval', (array) ($result['skills_breakdown']['missing_skills'] ?? []))));
            $cv_fix_points = array_values(array_filter(array_map('strval', (array) ($result['cv_improvements'] ?? []))));
            $strength_highlights = array_values(array_filter(array_map(static function ($item) {
                if (!is_array($item)) {
                    return '';
                }

                return trim((string) ($item['strength'] ?? ''));
            }, (array) ($result['strengths_to_highlight'] ?? []))));

            $summary_verdict = trim((string) ($result['executive_summary']['verdict'] ?? ''));
            $summary_insight = trim((string) ($result['executive_summary']['key_insight'] ?? ''));
            $final_recommendation = trim((string) ($result['overall_assessment']['final_recommendation'] ?? ''));

            $payload = [
                'paragraphs' => array_slice(array_values(array_filter([$summary_verdict, $summary_insight, $final_recommendation])), 0, 3),
                'highlights' => array_slice(array_values(array_unique(array_merge(
                    array_slice($matched_signals, 0, 2),
                    array_slice($missing_signals, 0, 2),
                    array_slice($strength_highlights, 0, 2)
                ))), 0, 4),
                'match_score' => $match_score,
                'analysis_source' => 'fallback_engine',
                'metrics' => $this->build_crm_reddit_single_job_terminal_profile_metrics($result),
                'preview_metrics' => $this->build_crm_reddit_single_job_terminal_profile_metrics($result),
                'matched_signals' => array_slice($matched_signals, 0, 6),
                'missing_signals' => array_slice($missing_signals, 0, 6),
                'cv_fix_points' => array_slice($cv_fix_points, 0, 5),
                'keyword_swaps' => $this->build_crm_reddit_single_job_keyword_swaps(
                    $cv_text,
                    $analysis,
                    array_slice($missing_signals, 0, 4)
                ),
            ];

            if ($this->is_crm_reddit_single_job_profile_payload($payload)) {
                set_transient($transient_key, $payload, 12 * HOUR_IN_SECONDS);
                $runtime_cache[$cache_seed] = $payload;
                return $payload;
            }

            return [];
        }

        private function build_crm_reddit_single_job_terminal_profile_metrics(array $result)
        {
            $scores = is_array($result['scores'] ?? null) ? $result['scores'] : [];
            $keyword_analysis = is_array($result['keyword_analysis'] ?? null) ? $result['keyword_analysis'] : [];
            $ats_analysis = is_array($result['ats_analysis'] ?? null) ? $result['ats_analysis'] : [];
            $overall_assessment = is_array($result['overall_assessment'] ?? null) ? $result['overall_assessment'] : [];

            $skills_score = max(0, min(100, (int) ($scores['skills_match'] ?? 0)));
            $experience_score = max(0, min(100, (int) ($scores['experience_match'] ?? 0)));
            $education_score = max(0, min(100, (int) ($scores['education_match'] ?? 0)));
            $keywords_score = max(0, min(100, (int) ($scores['keywords_match'] ?? 0)));
            $ats_score = max(0, min(100, (int) round($ats_analysis['percentage'] ?? 0)));

            return [
                [
                    'label' => __('Skills match', 'senna-finance'),
                    'score' => $skills_score,
                    'detail' => sprintf(
                        __('%1$d matched signals · %2$d missing to surface', 'senna-finance'),
                        count((array) ($result['skills_breakdown']['matched_skills'] ?? [])),
                        count((array) ($result['skills_breakdown']['missing_skills'] ?? []))
                    ),
                    'bars' => $this->build_crm_reddit_single_job_bars($skills_score),
                    'tone' => 'blue',
                ],
                [
                    'label' => __('Experience alignment', 'senna-finance'),
                    'score' => $experience_score,
                    'detail' => (string) ($result['experience_analysis']['experience_gap'] ?? __('Experience alignment assessed from your current CV.', 'senna-finance')),
                    'bars' => $this->build_crm_reddit_single_job_bars($experience_score),
                    'tone' => 'green',
                ],
                [
                    'label' => __('Keyword coverage', 'senna-finance'),
                    'score' => $keywords_score,
                    'detail' => sprintf(
                        __('%1$d%% coverage · %2$d critical terms still missing', 'senna-finance'),
                        (int) ($keyword_analysis['match_percentage'] ?? $keywords_score),
                        count((array) ($keyword_analysis['critical_missing'] ?? []))
                    ),
                    'bars' => $this->build_crm_reddit_single_job_bars($keywords_score),
                    'tone' => 'gold',
                ],
                [
                    'label' => __('ATS readiness', 'senna-finance'),
                    'score' => $ats_score,
                    'detail' => (string) ($overall_assessment['competitive_position'] ?? __('ATS and recruiter readability assessed from your current CV.', 'senna-finance')),
                    'bars' => $this->build_crm_reddit_single_job_bars($ats_score),
                    'tone' => 'purple',
                ],
                [
                    'label' => __('Education fit', 'senna-finance'),
                    'score' => $education_score,
                    'detail' => sprintf(
                        __('Education and credential alignment scored at %d%%', 'senna-finance'),
                        $education_score
                    ),
                    'bars' => $this->build_crm_reddit_single_job_bars($education_score),
                    'tone' => 'slate',
                ],
            ];
        }

        private function build_crm_reddit_single_job_cv_fix_points(array $analysis, array $matches, array $gaps)
        {
            $fixes = [];

            foreach ((array) ($analysis['cv_changes'] ?? []) as $change) {
                $change = trim((string) $change);
                if ($change !== '') {
                    $fixes[] = $change;
                }
            }

            if (!empty($gaps[0])) {
                $fixes[] = sprintf(__('Add one quantified bullet that makes %s explicit in the first half of the CV.', 'senna-finance'), (string) $gaps[0]);
            }
            if (!empty($gaps[1])) {
                $fixes[] = sprintf(__('Rework your summary so %s appears in the first two lines, not later in the experience section.', 'senna-finance'), (string) $gaps[1]);
            }
            if (!empty($matches[0])) {
                $fixes[] = sprintf(__('Keep %s, but give it stronger evidence by attaching numbers, scope, or transaction context.', 'senna-finance'), (string) $matches[0]);
            }

            return array_slice(array_values(array_unique(array_filter($fixes))), 0, 5);
        }

        private function build_crm_reddit_single_job_keyword_swaps($cv_text, array $analysis, array $gaps)
        {
            $cv_text = strtolower(trim((string) $cv_text));
            $swaps = [];
            $role_signals = array_values(array_filter(array_unique(array_merge(
                array_values(array_filter((array) ($analysis['top_skills'] ?? []))),
                array_values(array_filter((array) ($analysis['qualifications'] ?? []))),
                array_values(array_filter((array) ($analysis['backgrounds'] ?? [])))
            ))));

            $generic_patterns = [
                __('analysis', 'senna-finance') => ['analysis', 'analysed', 'analyzed'],
                __('research', 'senna-finance') => ['research', 'researched'],
                __('support', 'senna-finance') => ['support', 'supported', 'assisted', 'helped'],
                __('reporting', 'senna-finance') => ['reporting', 'reports'],
                __('excel', 'senna-finance') => ['excel', 'spreadsheet'],
            ];

            $targets = array_values(array_unique(array_filter(array_merge($gaps, $role_signals))));
            foreach ($generic_patterns as $label => $patterns) {
                foreach ($patterns as $pattern) {
                    if ($cv_text !== '' && strpos($cv_text, strtolower((string) $pattern)) !== false) {
                        $target = array_shift($targets);
                        if ($target === null || $target === '') {
                            break 2;
                        }

                        $swaps[] = [
                            'from' => (string) $label,
                            'to' => (string) $target,
                            'why' => __('This is closer to the screening language the brief is already rewarding.', 'senna-finance'),
                        ];
                        continue 2;
                    }
                }
            }

            while (count($swaps) < 3 && !empty($targets)) {
                $target = array_shift($targets);
                if ($target === null || $target === '') {
                    continue;
                }

                $swaps[] = [
                    'from' => __('generic finance wording', 'senna-finance'),
                    'to' => (string) $target,
                    'why' => __('This makes the role-specific signal easier to see in the first screening pass.', 'senna-finance'),
                ];
            }

            return array_slice($swaps, 0, 3);
        }

        private function build_crm_reddit_single_job_profile_preview_metrics(array $analysis)
        {
            $skills = array_values(array_filter((array) ($analysis['top_skills'] ?? [])));
            $qualifications = array_values(array_filter((array) ($analysis['qualifications'] ?? [])));
            $backgrounds = array_values(array_filter((array) ($analysis['backgrounds'] ?? [])));

            $skill_demand = $this->clamp_crm_reddit_single_job_metric(42 + count($skills) * 11, 34, 94);
            $brief_tightness = (int) ($analysis['role_specificity'] ?? 62);
            $qualification_weight = $this->clamp_crm_reddit_single_job_metric(38 + count($qualifications) * 16, 28, 92);
            $recruiter_visibility = (int) ($analysis['recruiter_access'] ?? 48);

            return [
                [
                    'label' => __('Skill demand', 'senna-finance'),
                    'score' => $skill_demand,
                    'detail' => sprintf(__('%d core skill signals', 'senna-finance'), max(1, count($skills))),
                    'bars' => $this->build_crm_reddit_single_job_bars($skill_demand),
                    'tone' => 'blue',
                ],
                [
                    'label' => __('Brief tightness', 'senna-finance'),
                    'score' => $brief_tightness,
                    'detail' => sprintf(__('%d background routes rewarded', 'senna-finance'), max(1, count($backgrounds))),
                    'bars' => $this->build_crm_reddit_single_job_bars($brief_tightness),
                    'tone' => 'slate',
                ],
                [
                    'label' => __('Qualification weight', 'senna-finance'),
                    'score' => $qualification_weight,
                    'detail' => sprintf(__('%d credentials visible in the brief', 'senna-finance'), max(1, count($qualifications))),
                    'bars' => $this->build_crm_reddit_single_job_bars($qualification_weight),
                    'tone' => 'gold',
                ],
                [
                    'label' => __('Recruiter visibility', 'senna-finance'),
                    'score' => $recruiter_visibility,
                    'detail' => __('How open the contact route looks', 'senna-finance'),
                    'bars' => $this->build_crm_reddit_single_job_bars($recruiter_visibility),
                    'tone' => 'green',
                ],
            ];
        }

