        private function build_crm_reddit_single_job_profile_comparison_metrics(array $analysis, $cv_text)
        {
            $cv_text = strtolower(trim((string) $cv_text));
            $skills = array_values(array_filter((array) ($analysis['top_skills'] ?? [])));
            $backgrounds = array_values(array_filter((array) ($analysis['backgrounds'] ?? [])));
            $qualifications = array_values(array_filter((array) ($analysis['qualifications'] ?? [])));
            $required_years = trim((string) ($analysis['required_years'] ?? ''));

            $skill_matches = $this->count_crm_reddit_single_job_signal_matches($cv_text, $skills);
            $background_matches = $this->count_crm_reddit_single_job_signal_matches($cv_text, $backgrounds);
            $qualification_matches = $this->count_crm_reddit_single_job_signal_matches($cv_text, $qualifications);

            $skill_total = max(1, count($skills));
            $background_total = max(1, count($backgrounds));
            $qualification_total = max(1, count($qualifications));

            $skill_score = $this->clamp_crm_reddit_single_job_metric((int) round(($skill_matches / $skill_total) * 100), 12, 98);
            $background_score = $this->clamp_crm_reddit_single_job_metric((int) round(($background_matches / $background_total) * 100), 12, 98);
            $qualification_score = $this->clamp_crm_reddit_single_job_metric((int) round(($qualification_matches / $qualification_total) * 100), 12, 98);

            $required_range = $this->parse_crm_reddit_single_job_years_range($required_years);
            $cv_years = $this->extract_crm_reddit_single_job_cv_years($cv_text);
            $experience_score = $this->score_crm_reddit_single_job_experience_alignment($required_range, $cv_years);

            return [
                [
                    'label' => __('Skill match', 'senna-finance'),
                    'score' => $skill_score,
                    'detail' => sprintf(__('%1$d of %2$d core signals visible', 'senna-finance'), $skill_matches, $skill_total),
                    'bars' => $this->build_crm_reddit_single_job_bars($skill_score),
                    'tone' => 'blue',
                ],
                [
                    'label' => __('Background fit', 'senna-finance'),
                    'score' => $background_score,
                    'detail' => sprintf(__('%1$d of %2$d target backgrounds surfaced', 'senna-finance'), $background_matches, $background_total),
                    'bars' => $this->build_crm_reddit_single_job_bars($background_score),
                    'tone' => 'green',
                ],
                [
                    'label' => __('Qualification coverage', 'senna-finance'),
                    'score' => $qualification_score,
                    'detail' => sprintf(__('%1$d of %2$d expected credentials found', 'senna-finance'), $qualification_matches, $qualification_total),
                    'bars' => $this->build_crm_reddit_single_job_bars($qualification_score),
                    'tone' => 'gold',
                ],
                [
                    'label' => __('Experience alignment', 'senna-finance'),
                    'score' => $experience_score,
                    'detail' => $this->describe_crm_reddit_single_job_experience_alignment($required_years, $cv_years),
                    'bars' => $this->build_crm_reddit_single_job_bars($experience_score),
                    'tone' => 'purple',
                ],
            ];
        }

        private function count_crm_reddit_single_job_signal_matches($cv_text, array $signals)
        {
            $matches = 0;
            foreach ($signals as $signal) {
                if ($this->does_crm_reddit_single_job_signal_match($cv_text, (string) $signal)) {
                    $matches++;
                }
            }

            return $matches;
        }

        private function does_crm_reddit_single_job_signal_match($cv_text, $signal)
        {
            $cv_text = strtolower(trim((string) $cv_text));
            $signal = strtolower(trim((string) $signal));
            if ($cv_text === '' || $signal === '') {
                return false;
            }

            if (strpos($cv_text, $signal) !== false) {
                return true;
            }

            $tokens = preg_split('/[^a-z0-9]+/i', $signal) ?: [];
            $tokens = array_values(array_filter(array_map('trim', $tokens), static function ($token) {
                return strlen((string) $token) >= 4;
            }));

            if (count($tokens) >= 2) {
                $matched_tokens = 0;
                foreach ($tokens as $token) {
                    if (strpos($cv_text, strtolower((string) $token)) !== false) {
                        $matched_tokens++;
                    }
                }

                return $matched_tokens >= max(2, count($tokens) - 1);
            }

            return false;
        }

        private function parse_crm_reddit_single_job_years_range($required_years)
        {
            $required_years = trim((string) $required_years);
            $range = ['min' => null, 'max' => null];

            if ($required_years === '') {
                return $range;
            }

            if (preg_match('/(\d{1,2})\s*-\s*(\d{1,2})\s*years?/i', $required_years, $matches)) {
                return ['min' => (int) $matches[1], 'max' => (int) $matches[2]];
            }

            if (preg_match('/(\d{1,2})\s*\+\s*years?/i', $required_years, $matches)) {
                return ['min' => (int) $matches[1], 'max' => null];
            }

            if (preg_match('/(\d{1,2})\s*years?/i', $required_years, $matches)) {
                return ['min' => (int) $matches[1], 'max' => (int) $matches[1]];
            }

            return $range;
        }

        private function extract_crm_reddit_single_job_cv_years($cv_text)
        {
            $cv_text = trim((string) $cv_text);
            if ($cv_text === '') {
                return 0;
            }

            if (!preg_match_all('/(\d{1,2})(?:\s*\+)?\s+years?/i', $cv_text, $matches) || empty($matches[1])) {
                return 0;
            }

            $years = array_map('intval', (array) $matches[1]);
            return (int) max($years);
        }

        private function score_crm_reddit_single_job_experience_alignment(array $required_range, $cv_years)
        {
            $cv_years = (int) $cv_years;
            $min = isset($required_range['min']) ? (int) $required_range['min'] : 0;
            $max = isset($required_range['max']) && $required_range['max'] !== null ? (int) $required_range['max'] : null;

            if ($min <= 0) {
                return $cv_years > 0 ? 72 : 48;
            }

            if ($cv_years <= 0) {
                return 34;
            }

            if ($max !== null && $cv_years >= $min && $cv_years <= ($max + 1)) {
                return 90;
            }

            if ($cv_years >= $min) {
                return 82;
            }

            return $this->clamp_crm_reddit_single_job_metric((int) round(($cv_years / $min) * 100), 26, 78);
        }

        private function describe_crm_reddit_single_job_experience_alignment($required_years, $cv_years)
        {
            $required_years = trim((string) $required_years);
            $cv_years = (int) $cv_years;

            if ($required_years === '') {
                return $cv_years > 0
                    ? sprintf(__('CV shows %d years of visible experience', 'senna-finance'), $cv_years)
                    : __('No clear years signal found in the uploaded CV', 'senna-finance');
            }

            if ($cv_years > 0) {
                return sprintf(__('Role asks for %1$s · CV shows %2$d years', 'senna-finance'), $required_years, $cv_years);
            }

            return sprintf(__('Role asks for %s · CV years signal not clearly surfaced', 'senna-finance'), $required_years);
        }

        private function merge_crm_reddit_single_job_ai_overview(array $fallback, array $claude)
        {
            $overview = $fallback;

            if (!empty($claude['job_summary'])) {
                $overview['job_summary'] = trim((string) $claude['job_summary']);
            }
            if (!empty($claude['candidate_preference'])) {
                $overview['candidate_preference'] = trim((string) $claude['candidate_preference']);
            }

            foreach (['key_skills', 'qualifications', 'backgrounds'] as $list_key) {
                if (!empty($claude[$list_key]) && is_array($claude[$list_key])) {
                    $overview[$list_key] = array_values(array_slice(array_filter(array_map('strval', $claude[$list_key])), 0, 4));
                }
            }

            if (!empty($claude['required_years'])) {
                $overview['required_years'] = trim((string) $claude['required_years']);
            }

            if (!empty($claude['sections']) && is_array($claude['sections'])) {
                foreach ($claude['sections'] as $section_key => $section_value) {
                    $resolved_key = is_string($section_key) ? $section_key : (string) ($section_value['id'] ?? '');
                    if ($resolved_key === '' || empty($overview['sections'][$resolved_key]) || !is_array($section_value)) {
                        continue;
                    }

                    if (!empty($section_value['answer'])) {
                        $overview['sections'][$resolved_key]['answer'] = trim((string) $section_value['answer']);
                    }

                    if (!empty($section_value['highlights']) && is_array($section_value['highlights'])) {
                        $overview['sections'][$resolved_key]['highlights'] = array_values(array_slice(array_filter(array_map('strval', $section_value['highlights'])), 0, 4));
                    }
                }
            }

            return $overview;
        }

        private function merge_crm_reddit_single_job_profile_comparison(array $fallback, array $claude)
        {
            $comparison = $fallback;

            if (!empty($claude['paragraphs']) && is_array($claude['paragraphs'])) {
                $paragraphs = array_values(array_filter(array_map(static function ($value) {
                    return trim((string) $value);
                }, $claude['paragraphs'])));
                if (!empty($paragraphs)) {
                    $comparison['paragraphs'] = array_slice($paragraphs, 0, 3);
                }
            }

            if (!empty($claude['highlights']) && is_array($claude['highlights'])) {
                $highlights = array_values(array_filter(array_map(static function ($value) {
                    return trim((string) $value);
                }, $claude['highlights'])));
                if (!empty($highlights)) {
                    $comparison['highlights'] = array_slice($highlights, 0, 4);
                }
            }

            if (!empty($claude['cv_fixes']) && is_array($claude['cv_fixes'])) {
                $fixes = array_values(array_filter(array_map(static function ($value) {
                    return trim((string) $value);
                }, $claude['cv_fixes'])));
                if (!empty($fixes)) {
                    $comparison['cv_fix_points'] = array_slice($fixes, 0, 5);
                }
            }

            if (!empty($claude['keyword_swaps']) && is_array($claude['keyword_swaps'])) {
                $swaps = [];
                foreach ($claude['keyword_swaps'] as $swap) {
                    if (!is_array($swap)) {
                        continue;
                    }

                    $from = trim((string) ($swap['from'] ?? ''));
                    $to = trim((string) ($swap['to'] ?? ''));
                    $why = trim((string) ($swap['why'] ?? ''));
                    if ($from === '' || $to === '') {
                        continue;
                    }

                    $swaps[] = [
                        'from' => $from,
                        'to' => $to,
                        'why' => $why,
                    ];
                }

                if (!empty($swaps)) {
                    $comparison['keyword_swaps'] = array_slice($swaps, 0, 4);
                }
            }

            return $comparison;
        }

        private function get_crm_reddit_single_job_salary_trajectory(array $item)
        {
            $post_id = (int) ($item['post_id'] ?? 0);
            $intel_hash = $this->get_crm_reddit_single_job_intel_hash($item);
            $researched = $this->build_cv_match_studio_researched_salary_trajectory($item);
            if ($this->is_crm_reddit_single_job_salary_payload($researched)) {
                if ($post_id > 0) {
                    $this->store_crm_reddit_single_job_intel_payload($post_id, 'salary', $researched, $intel_hash);
                }
                return $researched;
            }

            if ($post_id > 0) {
                $stored = $this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'salary', $intel_hash);
                if ($this->is_crm_reddit_single_job_salary_payload($stored)) {
                    return $stored;
                }
            }

            $trajectory = $this->generate_crm_reddit_single_job_salary_trajectory($item);
            if ($post_id > 0 && $this->is_crm_reddit_single_job_salary_payload($trajectory)) {
                $this->store_crm_reddit_single_job_intel_payload($post_id, 'salary', $trajectory, $intel_hash);
            }

            return $trajectory;
        }

        private function get_crm_reddit_single_job_salary_trajectory_fast(array $item)
        {
            $post_id = (int) ($item['post_id'] ?? 0);
            $intel_hash = $this->get_crm_reddit_single_job_intel_hash($item);
            $researched = $this->build_cv_match_studio_researched_salary_trajectory($item);
            if ($this->is_crm_reddit_single_job_salary_payload($researched)) {
                return $researched;
            }

            if ($post_id > 0) {
                $stored = $this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'salary', $intel_hash);
                if ($this->is_crm_reddit_single_job_salary_payload($stored)) {
                    return $stored;
                }
            }

            return $this->build_crm_reddit_single_job_salary_trajectory_fallback($item);
        }

        private function generate_crm_reddit_single_job_salary_trajectory(array $item)
        {
            $role_title = trim((string) ($item['role_title'] ?? ''));
            $location = trim((string) ($item['location'] ?? ''));

            $researched = $this->build_cv_match_studio_researched_salary_trajectory($item);
            if ($this->is_crm_reddit_single_job_salary_payload($researched)) {
                return $researched;
            }

            $fallback = $this->build_crm_reddit_single_job_salary_trajectory_fallback($item);
            if ($role_title === '' || $location === '') {
                return $fallback;
            }

            $post_id = (int) ($item['post_id'] ?? 0);
            $cache_seed = ($post_id > 0 ? $post_id . '|' . (string) get_post_modified_time('U', true, $post_id) : md5(wp_json_encode([$role_title, $location])))
                . '|'
                . md5((string) ($item['salary_text'] ?? ''))
                . '|salary-v11-senna-qatar-research-source';
            $cache_key = 'sffc_crm_job_salary_' . md5($cache_seed);
            $cached = get_transient($cache_key);

            if ($this->is_crm_reddit_single_job_salary_payload($cached)) {
                return $cached;
            }

            $fallback['salary_source'] = 'fallback';
            set_transient($cache_key, $fallback, $this->get_crm_reddit_single_job_role_cache_ttl());

            return $fallback;
        }

        public function pregenerate_reddit_job_intel($jobs_post_id, $force = false)
        {
            $jobs_post_id = (int) $jobs_post_id;
            if ($jobs_post_id <= 0) {
                return false;
            }

            $item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            if (!is_array($item)) {
                update_post_meta($jobs_post_id, '_sffc_role_intel_status', 'missing-job');
                return false;
            }

            $analysis = $this->build_crm_reddit_single_job_analysis_data($item);
            $intel_hash = $this->get_crm_reddit_single_job_intel_hash($item);

            if (
                !$force
                && $this->has_crm_reddit_single_job_stored_intel_payloads($jobs_post_id, $intel_hash)
            ) {
                update_post_meta($jobs_post_id, '_sffc_role_intel_status', 'generated');
                return true;
            }

            update_post_meta($jobs_post_id, '_sffc_role_intel_status', 'generating');

            $overview = $this->generate_crm_reddit_single_job_ai_overview($item, $analysis);
            $profile = $this->generate_crm_reddit_single_job_profile_comparison($item, $analysis, '');
            $salary = $this->generate_crm_reddit_single_job_salary_trajectory($item);

            $this->store_crm_reddit_single_job_intel_payload($jobs_post_id, 'overview', $overview, $intel_hash);
            $this->store_crm_reddit_single_job_intel_payload($jobs_post_id, 'profile', $profile, $intel_hash);
            $this->store_crm_reddit_single_job_intel_payload($jobs_post_id, 'salary', $salary, $intel_hash);

            update_post_meta($jobs_post_id, '_sffc_role_intel_status', 'generated');
            update_post_meta($jobs_post_id, '_sffc_role_intel_generated_at', current_time('mysql'));

            return true;
        }

        private function has_crm_reddit_single_job_stored_intel_payloads($post_id, $expected_hash)
        {
            $post_id = (int) $post_id;
            if ($post_id <= 0 || $expected_hash === '') {
                return false;
            }

            return $this->is_crm_reddit_single_job_ai_overview_payload($this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'overview', $expected_hash))
                && $this->is_crm_reddit_single_job_profile_payload($this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'profile', $expected_hash))
                && $this->is_crm_reddit_single_job_salary_payload($this->get_crm_reddit_single_job_stored_intel_payload($post_id, 'salary', $expected_hash));
        }

        private function get_crm_reddit_single_job_stored_intel_payload($post_id, $type, $expected_hash = '')
        {
            $post_id = (int) $post_id;
            if ($post_id <= 0) {
                return null;
            }

            $meta_keys = $this->get_crm_reddit_single_job_intel_meta_keys();
            if (empty($meta_keys[$type])) {
                return null;
            }

            $stored_hash = (string) get_post_meta($post_id, '_sffc_role_intel_hash', true);
            if ($expected_hash !== '' && $stored_hash !== $expected_hash) {
                return null;
            }

            $payload = get_post_meta($post_id, $meta_keys[$type], true);
            return is_array($payload) ? $payload : null;
        }

        private function store_crm_reddit_single_job_intel_payload($post_id, $type, array $payload, $intel_hash)
        {
            $post_id = (int) $post_id;
            if ($post_id <= 0) {
                return;
            }

            $meta_keys = $this->get_crm_reddit_single_job_intel_meta_keys();
            if (empty($meta_keys[$type])) {
                return;
            }

            update_post_meta($post_id, $meta_keys[$type], $payload);
            update_post_meta($post_id, '_sffc_role_intel_hash', (string) $intel_hash);
            update_post_meta($post_id, '_sffc_role_intel_generated_at', current_time('mysql'));
        }

        private function get_crm_reddit_single_job_intel_meta_keys()
        {
            return [
                'overview' => '_sffc_role_overview_v1',
                'profile' => '_sffc_role_profile_v1',
                'salary' => '_sffc_role_salary_v2',
            ];
        }

        private function get_crm_reddit_single_job_intel_hash(array $item)
        {
            return md5(wp_json_encode([
                'role_title' => (string) ($item['role_title'] ?? ''),
                'company' => (string) ($item['company'] ?? ''),
                'location' => (string) ($item['location'] ?? ''),
                'seniority' => (string) ($item['seniority'] ?? ''),
                'employment_type' => (string) ($item['employment_type'] ?? ''),
                'salary_text' => (string) ($item['salary_text'] ?? ''),
                'sector' => (string) ($item['sector'] ?? ''),
                'recruiter_name' => (string) ($item['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($item['recruiter_title'] ?? ''),
                'description_text' => $this->get_crm_reddit_single_job_description_text($item),
            ]));
        }

        private function is_crm_reddit_single_job_ai_overview_payload($payload)
        {
            return is_array($payload) && !empty($payload['sections']) && is_array($payload['sections']);
        }

        private function is_crm_reddit_single_job_profile_payload($payload)
        {
            return is_array($payload) && !empty($payload['paragraphs']) && !empty($payload['metrics']) && isset($payload['keyword_swaps']);
        }

        private function is_crm_reddit_single_job_salary_payload($payload)
        {
            return is_array($payload) && !empty($payload['stages']) && is_array($payload['stages']);
        }

        private function get_crm_reddit_single_job_role_cache_ttl()
        {
            return 7 * DAY_IN_SECONDS;
        }

        private function get_crm_reddit_logged_out_page_cache_ttl()
        {
            return 7 * DAY_IN_SECONDS;
        }

        private function build_cv_match_studio_researched_salary_trajectory(array $item)
        {
            $location = strtolower(trim((string) ($item['location'] ?? '')));
            $is_saudi_market = $location !== '' && (
                strpos($location, 'saudi') !== false
                || strpos($location, 'riyadh') !== false
                || strpos($location, 'jeddah') !== false
                || strpos($location, 'ksa') !== false
            );
            $is_uae_market = $location !== '' && (
                strpos($location, 'uae') !== false
                || strpos($location, 'dubai') !== false
                || strpos($location, 'abu dhabi') !== false
                || strpos($location, 'united arab emirates') !== false
            );
            $is_qatar_market = $location !== '' && (
                strpos($location, 'qatar') !== false
                || strpos($location, 'doha') !== false
                || strpos($location, 'lusail') !== false
                || strpos($location, 'al khor') !== false
                || strpos($location, 'mesaieed') !== false
                || strpos($location, 'ras laffan') !== false
            );

            if (!$is_saudi_market && !$is_uae_market && !$is_qatar_market) {
                return null;
            }

            if ($is_uae_market) {
                $market_rows = $this->get_cv_match_studio_uae_salary_research_rows_2025();
                $market_label = __('UAE', 'senna-finance');
                $country_label = __('United Arab Emirates', 'senna-finance');
                $currency_code = 'AED';
                $usd_rate = 0.272;
                $selected_market_key = 'uae';
            } elseif ($is_qatar_market) {
                $market_rows = $this->get_cv_match_studio_qatar_salary_research_rows_2026();
                $market_label = __('Qatar', 'senna-finance');
                $country_label = __('Qatar', 'senna-finance');
                $currency_code = 'QAR';
                $usd_rate = 0.275;
                $selected_market_key = 'qatar';
            } else {
                $market_rows = $this->get_cv_match_studio_saudi_salary_research_rows();
                $market_label = __('Saudi', 'senna-finance');
                $country_label = __('Saudi Arabia', 'senna-finance');
                $currency_code = 'SAR';
                $usd_rate = 0.267;
                $selected_market_key = 'saudi';
            }

            $match = $this->match_cv_match_studio_salary_research_row($item, $market_rows);
            if (empty($match['row']) || !is_array($match['row'])) {
                return null;
            }

            $row = $match['row'];
            $from_monthly = (int) round(max(0, (float) ($row['from'] ?? 0)) * 1000);
            $avg_monthly = (int) round(max(0, (float) ($row['avg'] ?? 0)) * 1000);
            $to_monthly = (int) round(max(0, (float) ($row['to'] ?? 0)) * 1000);
            if ($from_monthly <= 0 || $avg_monthly <= 0 || $to_monthly <= 0) {
                return null;
            }

            $range_points = [
                ['label' => __('Lower range', 'senna-finance'), 'monthly_salary' => $from_monthly],
                ['label' => __('Market average', 'senna-finance'), 'monthly_salary' => $avg_monthly],
                ['label' => __('Upper range', 'senna-finance'), 'monthly_salary' => $to_monthly],
            ];
            $stages = [];
            foreach ($range_points as $point) {
                $annual_salary = (int) round(((int) $point['monthly_salary']) * 12, -3);
                $usd_equivalent = (int) round($annual_salary * $usd_rate, -3);
                $stages[] = [
                    'label' => (string) $point['label'],
                    'monthly_salary' => (int) $point['monthly_salary'],
                    'annual_salary' => $annual_salary,
                    'gbp_equivalent' => $usd_equivalent,
                    'usd_equivalent' => $usd_equivalent,
                ];
            }

            $category = sanitize_text_field((string) ($row['category'] ?? 'Finance'));
            $role = sanitize_text_field((string) ($row['role'] ?? 'Finance role'));
            $score = $this->score_cv_match_studio_salary_offer_quality($avg_monthly);
            $note_seed = implode('|', [$category, $role, $location, (string) ($match['score'] ?? 0)]);
