        private function build_cv_match_studio_salary_country_comparison(array $item, $selected_market)
        {
            $selected_market = sanitize_key((string) $selected_market);
            $market_configs = [
                'saudi' => [
                    'label' => __('Saudi Arabia', 'senna-finance'),
                    'currency' => 'SAR',
                    'usd_rate' => 0.267,
                    'rows' => $this->get_cv_match_studio_saudi_salary_research_rows(),
                ],
                'uae' => [
                    'label' => __('United Arab Emirates', 'senna-finance'),
                    'currency' => 'AED',
                    'usd_rate' => 0.272,
                    'rows' => $this->get_cv_match_studio_uae_salary_research_rows_2025(),
                ],
                'qatar' => [
                    'label' => __('Qatar', 'senna-finance'),
                    'currency' => 'QAR',
                    'usd_rate' => 0.275,
                    'rows' => $this->get_cv_match_studio_qatar_salary_research_rows_2026(),
                ],
            ];

            $items = [];
            foreach ($market_configs as $market_key => $config) {
                $match = $this->match_cv_match_studio_salary_research_row($item, (array) ($config['rows'] ?? []));
                if (empty($match['row']) || !is_array($match['row'])) {
                    continue;
                }

                $row = $match['row'];
                $monthly = (int) round(max(0, (float) ($row['avg'] ?? 0)) * 1000);
                if ($monthly <= 0) {
                    continue;
                }

                $annual = (int) round($monthly * 12, -3);
                $items[] = [
                    'market_key' => $market_key,
                    'label' => (string) ($config['label'] ?? ''),
                    'currency' => (string) ($config['currency'] ?? ''),
                    'monthly_salary' => $monthly,
                    'annual_salary' => $annual,
                    'usd_equivalent' => (int) round($annual * (float) ($config['usd_rate'] ?? 1), -3),
                    'match_role' => sanitize_text_field((string) ($row['role'] ?? '')),
                    'is_selected' => $market_key === $selected_market,
                ];
            }

            if (empty($items)) {
                return [];
            }

            $selected_usd = 0;
            foreach ($items as $item_row) {
                if (!empty($item_row['is_selected'])) {
                    $selected_usd = (int) ($item_row['usd_equivalent'] ?? 0);
                    break;
                }
            }
            if ($selected_usd <= 0) {
                $selected_usd = (int) ($items[0]['usd_equivalent'] ?? 0);
            }

            foreach ($items as $index => $item_row) {
                $delta = (int) ($item_row['usd_equivalent'] ?? 0) - $selected_usd;
                $items[$index]['direction'] = $delta > 2000 ? 'up' : ($delta < -2000 ? 'down' : 'flat');
                $items[$index]['delta_percent'] = $selected_usd > 0 ? (int) round(($delta / $selected_usd) * 100) : 0;
            }

            return $items;
        }

