        private function rotate_cv_match_studio_salary_notes(array $notes, $seed, $limit = 4)
        {
            $notes = array_values(array_unique(array_filter(array_map(static function ($note) {
                return trim((string) $note);
            }, $notes))));
            $limit = max(1, (int) $limit);

            if (count($notes) <= $limit) {
                return $notes;
            }

            $rotation_seed = (string) $seed . '|' . wp_rand(1, 1000000);
            $offset = abs((int) crc32($rotation_seed)) % count($notes);
            $rotated = array_merge(array_slice($notes, $offset), array_slice($notes, 0, $offset));

            return array_slice($rotated, 0, $limit);
        }

        private function score_cv_match_studio_salary_offer_quality($avg_monthly)
        {
            $avg_monthly = max(0, (int) $avg_monthly);
            if ($avg_monthly >= 120000) {
                return ['score' => 93, 'label' => __('Executive market band', 'senna-finance')];
            }
            if ($avg_monthly >= 75000) {
                return ['score' => 87, 'label' => __('Senior leadership band', 'senna-finance')];
            }
            if ($avg_monthly >= 45000) {
                return ['score' => 80, 'label' => __('Senior professional band', 'senna-finance')];
            }
            if ($avg_monthly >= 30000) {
                return ['score' => 73, 'label' => __('Professional market band', 'senna-finance')];
            }

            return ['score' => 66, 'label' => __('Developing market band', 'senna-finance')];
        }

