        private function match_cv_match_studio_salary_research_row(array $item, array $rows)
        {
            $role_title = (string) ($item['role_title'] ?? '');
            $seniority = (string) ($item['seniority'] ?? '');
            $sector = (string) ($item['sector'] ?? '');
            $employment_type = (string) ($item['employment_type'] ?? '');
            $query = $this->normalize_cv_match_studio_salary_research_text(trim($role_title . ' ' . $seniority . ' ' . $sector . ' ' . $employment_type));
            if ($query === '') {
                return null;
            }

            $best = null;
            $best_score = 0;
            foreach ($rows as $row) {
                $score = $this->score_cv_match_studio_saudi_salary_research_row($row, $query);
                if ($score > $best_score) {
                    $best_score = $score;
                    $best = $row;
                }
            }

            if (empty($best) || $best_score < 45) {
                return null;
            }

            return [
                'row' => $best,
                'score' => $best_score,
            ];
        }

        private function score_cv_match_studio_saudi_salary_research_row(array $row, $query)
        {
            $role = $this->normalize_cv_match_studio_salary_research_text((string) ($row['role'] ?? ''));
            $category = $this->normalize_cv_match_studio_salary_research_text((string) ($row['category'] ?? ''));
            $aliases = array_values(array_filter(array_map([$this, 'normalize_cv_match_studio_salary_research_text'], (array) ($row['aliases'] ?? []))));
            $score = 0;

            if ($role !== '' && $query === $role) {
                $score += 240;
            } elseif ($role !== '' && (strpos($query, $role) !== false || strpos($role, $query) !== false)) {
                $score += 130;
            }

            foreach ($aliases as $alias) {
                if ($alias !== '' && strpos($query, $alias) !== false) {
                    $score += strlen($alias) > 14 ? 85 : 48;
                }
            }

            foreach ($this->tokenize_cv_match_studio_salary_research_text($role) as $token) {
                if (strlen($token) < 3) {
                    continue;
                }
                if (preg_match('/\b' . preg_quote($token, '/') . '\b/', $query)) {
                    $score += 18;
                }
            }

            foreach ($this->tokenize_cv_match_studio_salary_research_text($category) as $token) {
                if (strlen($token) < 4) {
                    continue;
                }
                if (preg_match('/\b' . preg_quote($token, '/') . '\b/', $query)) {
                    $score += 14;
                }
            }

            $role_has = static function ($needle) use ($role) {
                return strpos($role, $needle) !== false;
            };
            if (strpos($query, 'cfo') !== false || strpos($query, 'chief financial officer') !== false) {
                $score += $role_has('cfo') ? 190 : 0;
            }
            if (strpos($query, 'finance manager') !== false) {
                $score += $role_has('finance manager') ? 190 : 0;
            }
            if (strpos($query, 'finance director') !== false) {
                $score += $role_has('finance director') ? 190 : 0;
            }
            if (strpos($query, 'financial controller') !== false) {
                $score += $role_has('financial controller') ? 190 : 0;
            }
            if (strpos($query, 'fund accountant') !== false) {
                $score += $role_has('fund accountant') ? 190 : 0;
            }
            if (strpos($query, 'compliance') !== false) {
                $score += strpos($category, 'compliance') !== false ? 95 : -20;
            }
            if (preg_match('/\brisk\b/', $query)) {
                $score += strpos($category, 'risk') !== false ? 95 : -20;
            }
            if (strpos($query, 'operations') !== false || strpos($query, 'middle office') !== false || strpos($query, 'back office') !== false || preg_match('/\bcoo\b/', $query)) {
                $score += strpos($category, 'operations') !== false ? 95 : -20;
            }
            if (strpos($query, 'investment banking') !== false || strpos($query, ' m a ') !== false || strpos($query, ' dcm ') !== false || strpos($query, ' ecm ') !== false || strpos($query, ' lev fin ') !== false) {
                $score += strpos($category, 'investment banking') !== false ? 105 : -20;
            }
            if (strpos($query, 'finance') !== false || strpos($query, ' pe ') !== false) {
                $score += strpos($category, 'finance') !== false ? 105 : -20;
            }
            if (strpos($query, 'venture capital') !== false || strpos($query, ' vc ') !== false) {
                $score += strpos($category, 'venture capital') !== false ? 105 : -20;
            }
            if (strpos($query, 'relationship manager') !== false || strpos($query, 'corporate banking') !== false || strpos($query, 'wholesale banking') !== false) {
                $score += (strpos($category, 'wholesale banking') !== false || strpos($category, 'corporate banking') !== false) ? 105 : -20;
            }
            if (strpos($query, 'retail banking') !== false || strpos($query, 'consumer banking') !== false) {
                $score += strpos($category, 'retail banking') !== false ? 105 : -20;
            }
            if (strpos($query, 'private banking') !== false || strpos($query, 'wealth') !== false || strpos($query, 'private banker') !== false) {
                $score += (strpos($category, 'private banking') !== false || strpos($category, 'wealth') !== false) ? 105 : -20;
            }
            if (strpos($query, 'institutional sales') !== false || strpos($query, 'distribution') !== false || strpos($query, 'client services') !== false) {
                $score += strpos($category, 'institutional sales') !== false ? 105 : -20;
            }
            if (strpos($query, 'insurance') !== false) {
                $score += strpos($category, 'insurance') !== false ? 95 : -20;
            }
            if (strpos($query, 'asset management') !== false || strpos($query, 'portfolio manager') !== false || strpos($query, 'fund manager') !== false || strpos($query, 'equities') !== false || strpos($query, 'fixed income') !== false) {
                $score += strpos($category, 'asset management') !== false ? 110 : -18;
            }
            if (strpos($query, 'investment management') !== false || strpos($query, 'chief investment officer') !== false || strpos($query, ' cio ') !== false || strpos($query, 'head of investments') !== false || strpos($query, 'investment director') !== false || strpos($query, 'investment manager') !== false) {
                $score += strpos($category, 'investment management') !== false ? 110 : -18;
            }
            if (strpos($query, 'fp a') !== false || strpos($query, 'financial planning') !== false || strpos($query, 'planning analysis') !== false || strpos($query, 'budgeting') !== false || strpos($query, 'reporting manager') !== false || strpos($query, 'treasury') !== false) {
                $score += strpos($category, 'senior finance') !== false ? 115 : -18;
            }
            if (strpos($query, 'audit') !== false || strpos($query, 'internal auditor') !== false || strpos($query, 'internal audit') !== false) {
                $score += (strpos($category, 'audit') !== false || strpos($category, 'senior finance') !== false) ? 105 : -18;
            }
            if (strpos($query, 'tax') !== false) {
                $score += strpos($category, 'tax') !== false ? 105 : -18;
            }
            if (strpos($query, 'deal advisory') !== false || strpos($query, 'transaction services') !== false || strpos($query, 'transaction') !== false) {
                $score += strpos($category, 'deal advisory') !== false ? 105 : -18;
            }
            if (strpos($query, 'real estate') !== false || strpos($query, 'development manager') !== false || strpos($query, 'asset manager') !== false) {
                $score += strpos($category, 'real estate') !== false ? 110 : -18;
            }
            if (strpos($query, 'strategy') !== false || strpos($query, 'engagement manager') !== false || strpos($query, 'management consulting') !== false) {
                $score += strpos($category, 'strategy') !== false ? 105 : -18;
            }

            return max(0, $score);
        }

        private function normalize_cv_match_studio_salary_research_text($text)
        {
            $text = strtolower((string) $text);
            $text = str_replace(['&', '/', '-', '–', '—'], ' ', $text);
            $text = preg_replace('/[^a-z0-9]+/', ' ', $text);
            $text = preg_replace('/\s+/', ' ', (string) $text);
            return trim((string) $text);
        }

        private function tokenize_cv_match_studio_salary_research_text($text)
        {
            $text = $this->normalize_cv_match_studio_salary_research_text($text);
            if ($text === '') {
                return [];
            }

            $stop_words = ['and', 'the', 'for', 'with', 'officer', 'assistant', 'senior'];
            return array_values(array_diff(array_unique(explode(' ', $text)), $stop_words));
        }

