        private function build_crm_reddit_single_job_salary_trajectory_fallback(array $item)
        {
            $role_title = strtolower(trim((string) ($item['role_title'] ?? '')));
            $seniority = strtolower(trim((string) ($item['seniority'] ?? '')));
            $salary_text = trim((string) ($item['salary_text'] ?? ''));
            $market = $this->get_crm_reddit_single_job_salary_market_context($item);

            $labels = [
                __('Entry (0-2 yrs)', 'senna-finance'),
                __('2-5 yrs', 'senna-finance'),
                __('5-10 yrs', 'senna-finance'),
                __('10-15 yrs', 'senna-finance'),
                __('15-20 yrs', 'senna-finance'),
                __('20+ yrs', 'senna-finance'),
            ];

            $level = 'mid';
            if (strpos($role_title, 'intern') !== false || strpos($seniority, 'intern') !== false) {
                $level = 'intern';
            } elseif (strpos($role_title, 'analyst') !== false || strpos($seniority, 'analyst') !== false) {
                $level = 'analyst';
            } elseif (strpos($role_title, 'associate') !== false || strpos($seniority, 'associate') !== false) {
                $level = 'associate';
            } elseif (strpos($role_title, 'manager') !== false || strpos($seniority, 'manager') !== false || strpos($role_title, 'vp') !== false || strpos($role_title, 'vice president') !== false) {
                $level = 'manager';
            } elseif (strpos($role_title, 'director') !== false || strpos($seniority, 'director') !== false || strpos($role_title, 'partner') !== false) {
                $level = 'director';
            }

            $base_map = [
                'AED' => ['intern' => 72000, 'analyst' => 220000, 'associate' => 330000, 'manager' => 520000, 'director' => 860000, 'mid' => 300000],
                'QAR' => ['intern' => 76000, 'analyst' => 235000, 'associate' => 345000, 'manager' => 535000, 'director' => 875000, 'mid' => 315000],
                'SAR' => ['intern' => 68000, 'analyst' => 205000, 'associate' => 315000, 'manager' => 495000, 'director' => 790000, 'mid' => 285000],
                'BHD' => ['intern' => 9200, 'analyst' => 28500, 'associate' => 41000, 'manager' => 65000, 'director' => 103000, 'mid' => 36000],
                'KWD' => ['intern' => 8500, 'analyst' => 26500, 'associate' => 39000, 'manager' => 61000, 'director' => 98000, 'mid' => 34500],
                'JOD' => ['intern' => 11000, 'analyst' => 31500, 'associate' => 45500, 'manager' => 69000, 'director' => 105000, 'mid' => 38000],
                'GBP' => ['intern' => 34000, 'analyst' => 76000, 'associate' => 118000, 'manager' => 175000, 'director' => 290000, 'mid' => 96000],
                'USD' => ['intern' => 48000, 'analyst' => 108000, 'associate' => 165000, 'manager' => 245000, 'director' => 395000, 'mid' => 136000],
                'EUR' => ['intern' => 36000, 'analyst' => 82000, 'associate' => 126000, 'manager' => 188000, 'director' => 305000, 'mid' => 102000],
            ];

            $base_currency = (string) ($market['currency_code'] ?? 'AED');
            $base_table = $base_map[$base_currency] ?? $base_map['AED'];
            $median_salary = (int) round(($base_table[$level] ?? $base_table['mid']) * (float) ($market['region_factor'] ?? 1));

            $anchored_salary = $this->extract_crm_reddit_single_job_salary_anchor($salary_text);
            if ($anchored_salary > 0) {
                $median_salary = (int) round($anchored_salary);
            }

            $multipliers = [0.62, 0.8, 1.0, 1.18, 1.33, 1.47];
            if ($level === 'intern') {
                $multipliers = [0.84, 1.0, 1.45, 2.05, 2.6, 3.15];
            } elseif ($level === 'director') {
                $multipliers = [0.54, 0.72, 1.0, 1.16, 1.3, 1.45];
            }

            $stages = [];
            $usd_rate = (float) ($market['usd_rate'] ?? ($market['gbp_rate'] ?? 1));
            foreach ($labels as $index => $label) {
                $annual_salary = (int) round($median_salary * ($multipliers[$index] ?? 1), -3);
                $usd_equivalent = (int) round(max(0, $annual_salary * $usd_rate), -3);
                $stages[] = [
                    'label' => $label,
                    'annual_salary' => max(0, $annual_salary),
                    'gbp_equivalent' => $usd_equivalent,
                    'usd_equivalent' => $usd_equivalent,
                ];
            }

            $annual_values = array_map(static function ($stage) {
                return (int) ($stage['annual_salary'] ?? 0);
            }, $stages);

            return [
                'currency_code' => $base_currency,
                'salary_source' => 'fallback',
                'average_salary' => (int) round(array_sum($annual_values) / max(1, count($annual_values)), -3),
                'median_salary' => (int) round($median_salary, -3),
                'tax_rate' => (string) ($market['tax_rate'] ?? '0%'),
                'stages' => $stages,
                'insights' => [
                    $anchored_salary > 0
                        ? __('Visible compensation on the brief was used as the anchor, then extended into a typical market progression by experience.', 'senna-finance')
                        : __('The trajectory reflects typical market progression for comparable senior private equity roles, with local market weighting applied where available.', 'senna-finance'),
                    ((string) ($market['tax_rate'] ?? '0%') === '0%')
                        ? __('Low-tax markets can make the local package materially stronger than the USD gross equivalent alone suggests.', 'senna-finance')
                        : __('Take-home value is more sensitive to local tax friction, so headline comp should be read alongside net earnings.', 'senna-finance'),
                ],
                'market_drivers' => [
                    __('Compensation moves up fastest when the role owns cash visibility, reporting quality, board packs, audit readiness, transformation, or multi-entity control.', 'senna-finance'),
                    __('Finance roles can price above wider benchmarks when the mandate supports major growth plans, fund build-out, rapid hiring, or clear operating value creation.', 'senna-finance'),
                ],
                'package_notes' => [
                    __('Read offers as total package: base salary, bonus, carry, relocation support, healthcare, pension, and any location-specific benefits.', 'senna-finance'),
                    __('A lower local base can still be attractive when allowances are explicit, tax friction is low, and bonus mechanics are credible.', 'senna-finance'),
                ],
                'negotiation_points' => [
                    __('Negotiate using proof of finance ownership: month-end close, controls, cash management, investor reporting, audit outcomes, ERP work, and stakeholder influence.', 'senna-finance'),
                    __('Ask whether allowances are included in base or separate, how bonus is calculated, and whether relocation or family support is available.', 'senna-finance'),
                ],
                'comp_mix' => [
                    ['label' => __('Base salary', 'senna-finance'), 'percent' => 68],
                    ['label' => __('Bonus', 'senna-finance'), 'percent' => 14],
                    ['label' => __('Housing / transport', 'senna-finance'), 'percent' => 12],
                    ['label' => __('Benefits', 'senna-finance'), 'percent' => 6],
                ],
                'market_comparison' => [
                    ['market' => __('Dubai', 'senna-finance'), 'score' => 96, 'label' => __('Regional finance hub', 'senna-finance')],
                    ['market' => __('Abu Dhabi', 'senna-finance'), 'score' => 92, 'label' => __('Institutional capital market', 'senna-finance')],
                    ['market' => __('Riyadh', 'senna-finance'), 'score' => 88, 'label' => __('Growth mandate depth', 'senna-finance')],
                    ['market' => __('Doha', 'senna-finance'), 'score' => 84, 'label' => __('GCC capital gateway', 'senna-finance')],
                ],
                'offer_score' => [
