            ];
        }

        private function get_crm_reddit_single_job_salary_market_context(array $item)
        {
            $location = strtolower(trim((string) ($item['location'] ?? '')));
            $contexts = [
                'dubai' => ['currency_code' => 'AED', 'tax_rate' => '0%', 'gbp_rate' => 0.215, 'usd_rate' => 0.272, 'region_factor' => 1.0],
                'abu dhabi' => ['currency_code' => 'AED', 'tax_rate' => '0%', 'gbp_rate' => 0.215, 'usd_rate' => 0.272, 'region_factor' => 1.04],
                'doha' => ['currency_code' => 'QAR', 'tax_rate' => '0%', 'gbp_rate' => 0.217, 'usd_rate' => 0.275, 'region_factor' => 1.02],
                'riyadh' => ['currency_code' => 'SAR', 'tax_rate' => '0%', 'gbp_rate' => 0.213, 'usd_rate' => 0.267, 'region_factor' => 1.0],
                'jeddah' => ['currency_code' => 'SAR', 'tax_rate' => '0%', 'gbp_rate' => 0.213, 'usd_rate' => 0.267, 'region_factor' => 0.94],
                'manama' => ['currency_code' => 'BHD', 'tax_rate' => '0%', 'gbp_rate' => 2.1, 'usd_rate' => 2.65, 'region_factor' => 1.08],
                'kuwait' => ['currency_code' => 'KWD', 'tax_rate' => '0%', 'gbp_rate' => 2.56, 'usd_rate' => 3.25, 'region_factor' => 1.0],
                'amman' => ['currency_code' => 'JOD', 'tax_rate' => '5%', 'gbp_rate' => 1.12, 'usd_rate' => 1.41, 'region_factor' => 0.94],
                'london' => ['currency_code' => 'GBP', 'tax_rate' => '45%', 'gbp_rate' => 1.0, 'usd_rate' => 1.27, 'region_factor' => 1.0],
                'new york' => ['currency_code' => 'USD', 'tax_rate' => '37%', 'gbp_rate' => 0.79, 'usd_rate' => 1.0, 'region_factor' => 1.12],
                'hong kong' => ['currency_code' => 'USD', 'tax_rate' => '17%', 'gbp_rate' => 0.79, 'usd_rate' => 1.0, 'region_factor' => 1.08],
                'singapore' => ['currency_code' => 'USD', 'tax_rate' => '22%', 'gbp_rate' => 0.79, 'usd_rate' => 1.0, 'region_factor' => 1.05],
            ];

            foreach ($contexts as $needle => $context) {
                if ($location !== '' && strpos($location, $needle) !== false) {
                    return $context;
                }
            }

            return ['currency_code' => 'GBP', 'tax_rate' => '45%', 'gbp_rate' => 1.0, 'usd_rate' => 1.27, 'region_factor' => 1.0];
        }

        private function extract_crm_reddit_single_job_salary_anchor($salary_text)
        {
            $salary_text = trim((string) $salary_text);
            if ($salary_text === '') {
                return 0;
            }

            if (!preg_match_all('/(\d+(?:[\.,]\d+)?)\s*([kKmM]?)/', $salary_text, $matches, PREG_SET_ORDER)) {
                return 0;
            }

            $values = [];
            foreach ($matches as $match) {
                $value = (float) str_replace(',', '', (string) ($match[1] ?? '0'));
                $suffix = strtolower((string) ($match[2] ?? ''));
                if ($suffix === 'm') {
                    $value *= 1000000;
                } elseif ($suffix === 'k') {
                    $value *= 1000;
                }
                if ($value > 0) {
                    $values[] = $value;
                }
            }

            if (empty($values)) {
                return 0;
            }

            return (int) round(array_sum($values) / count($values));
        }

        private function mask_crm_reddit_single_job_compact_salary($amount, $currency_code = 'AED', $use_currency_symbol = false)
        {
            $amount = max(0, (int) round((float) $amount));
            if ($amount === 0) {
                $masked = '•••';
            } else {
                $masked = $amount >= 1000000 ? '•••M' : '•••K';
            }
            $prefix = $use_currency_symbol ? trim((string) $this->get_currency_symbol($currency_code)) : trim((string) $currency_code);
            if ($prefix === '') {
                $prefix = trim((string) $currency_code);
            }

            return $prefix . ' ' . $masked;
        }

        private function mask_crm_reddit_single_job_percentage_text($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return '••';
            }

            return strpos($value, '%') !== false ? '••%' : '••';
        }

