        private function build_crm_reddit_single_job_locked_preview_metrics(array $overview = [], array $profile_comparison = [])
        {
            $matched_signals = array_values(array_filter((array) ($profile_comparison['matched_signals'] ?? [])));
            $missing_signals = array_values(array_filter((array) ($profile_comparison['missing_signals'] ?? [])));
            $backgrounds = array_values(array_filter((array) ($overview['backgrounds'] ?? [])));
            $skills = array_values(array_filter((array) ($overview['key_skills'] ?? [])));
            $qualifications = array_values(array_filter((array) ($overview['qualifications'] ?? [])));
            $required_years = trim((string) ($overview['required_years'] ?? ''));
            $metric_source = array_values(array_filter((array) ($profile_comparison['preview_metrics'] ?? $profile_comparison['metrics'] ?? []), 'is_array'));

            $scores = [
                (int) ($metric_source[0]['score'] ?? 72),
                (int) ($metric_source[1]['score'] ?? 76),
                (int) ($metric_source[2]['score'] ?? 63),
                (int) ($metric_source[3]['score'] ?? 79),
            ];
            $secondary_fit_signal = $skills[1] ?? ($required_years !== '' ? $required_years : __('clear role proof', 'senna-finance'));
            $background_anchor = $backgrounds[0] ?? ($required_years !== '' ? $required_years : __('the seat they are actually rewarding', 'senna-finance'));

            $metrics = [
                [
                    'label' => __('Lead with fit', 'senna-finance'),
                    'score' => $scores[0],
                    'detail' => sprintf(
                        __('Open with %1$s and %2$s in the first third of your CV.', 'senna-finance'),
                        (string) ($matched_signals[0] ?? $skills[0] ?? __('your strongest role signal', 'senna-finance')),
                        (string) $secondary_fit_signal
                    ),
                    'tone' => 'blue',
                ],
                [
                    'label' => __('Bridge your story', 'senna-finance'),
                    'score' => $scores[1],
                    'detail' => sprintf(
                        __('Frame your background around %s instead of generic finance interest.', 'senna-finance'),
                        (string) $background_anchor
                    ),
                    'tone' => 'green',
                ],
                [
                    'label' => __('Mirror the brief', 'senna-finance'),
                    'score' => $scores[2],
                    'detail' => sprintf(
                        __('Repeat the brief’s language around %s before your achievements.', 'senna-finance'),
                        (string) ($missing_signals[0] ?? $skills[0] ?? __('the strongest requirement', 'senna-finance'))
                    ),
                    'tone' => 'gold',
                ],
                [
                    'label' => __('Prove it fast', 'senna-finance'),
                    'score' => $scores[3],
                    'detail' => sprintf(
                        __('Add one quantified example that makes %s easy to screen.', 'senna-finance'),
                        (string) ($qualifications[0] ?? $skills[0] ?? __('your best fit signal', 'senna-finance'))
                    ),
                    'tone' => 'purple',
                ],
            ];

            foreach ($metrics as &$metric) {
                $metric['bars'] = $this->build_crm_reddit_single_job_bars((int) $metric['score']);
            }
            unset($metric);

            return $metrics;
        }

