        private function render_cv_match_studio_career_report_sunburst(array $rows)
        {
            if (empty($rows)) {
                return '';
            }

            $segments = [];
            $total = 0;
            foreach ($rows as $row) {
                $score = max(1, min(100, (int) ($row['score'] ?? 0)));
                $total += $score;
                $palette = $this->get_cv_match_studio_career_report_chart_palette((string) ($row['tone'] ?? 'blue'));
                $segments[] = [
                    'label' => sanitize_text_field((string) ($row['label'] ?? '')),
                    'detail' => sanitize_text_field((string) ($row['detail'] ?? '')),
                    'score' => $score,
                    'fill' => $palette['fill'],
                    'soft' => $palette['soft'],
                ];
            }

            if ($total <= 0) {
                return '';
            }

            $start = 0.0;
            $gradient_parts = [];
            foreach ($segments as $segment) {
                $share = ($segment['score'] / $total) * 100;
                $end = min(100, $start + $share);
                $gradient_parts[] = sprintf('%1$s %2$.3f%% %3$.3f%%', $segment['fill'], $start, $end);
                $start = $end;
            }

            ob_start();
        ?>
            <div class="sffc-cv-match-studio__career-report-sunburst-wrap">
                <div class="sffc-cv-match-studio__career-report-sunburst" style="--career-sunburst: conic-gradient(<?php echo esc_attr(implode(', ', $gradient_parts)); ?>);" role="img" aria-label="<?php esc_attr_e('Standout signal sunburst chart', 'senna-finance'); ?>">
                    <div class="sffc-cv-match-studio__career-report-sunburst-core">
                        <span><?php esc_html_e('Standout', 'senna-finance'); ?></span>
                        <strong><?php echo esc_html((string) count($segments)); ?></strong>
                    </div>
                </div>
                <div class="sffc-cv-match-studio__career-report-sunburst-legend">
                    <?php foreach ($segments as $segment) : ?>
                        <article class="sffc-cv-match-studio__career-report-sunburst-key">
                            <span style="background: <?php echo esc_attr($segment['fill']); ?>;"></span>
                            <div>
                                <strong><?php echo esc_html($segment['label']); ?></strong>
                                <?php if ($segment['detail'] !== '') : ?>
                                    <small><?php echo esc_html($segment['detail']); ?></small>
                                <?php endif; ?>
                            </div>
                        </article>
                    <?php endforeach; ?>
                </div>
            </div>
        <?php
            return ob_get_clean();
        }

        private function render_cv_match_studio_career_report_salary_spline(array $salary)
        {
            $stages = array_values(array_filter((array) ($salary['stages'] ?? []), 'is_array'));
            if (empty($stages)) {
                return '';
            }

            $values = array_map(static function ($stage) {
                return max(0, (int) ($stage['annual_salary'] ?? 0));
            }, $stages);
            $max_value = max($values);
            if ($max_value <= 0) {
                $max_value = 1;
            }

            $width = 520;
            $height = 180;
            $left = 18;
            $bottom = 148;
            $usable_width = $width - ($left * 2);
            $usable_height = 116;
            $count = max(1, count($stages));
            $step_x = $count > 1 ? $usable_width / ($count - 1) : 0;
            $points = [];
            foreach ($values as $index => $value) {
                $x = $left + ($step_x * $index);
                $y = $bottom - (($value / $max_value) * $usable_height);
                $points[] = round($x, 2) . ',' . round($y, 2);
            }
            $point_string = implode(' ', $points);
            $area_points = $point_string . ' ' . ($left + $usable_width) . ',' . $bottom . ' ' . $left . ',' . $bottom;

            ob_start();
        ?>
            <div class="sffc-cv-match-studio__career-report-salary-chart">
                <div class="sffc-cv-match-studio__career-report-salary-meta">
                    <div>
                        <span><?php esc_html_e('Average salary', 'senna-finance'); ?></span>
                        <strong><?php echo esc_html($this->format_crm_reddit_single_job_compact_salary((int) ($salary['average_salary'] ?? 0), (string) ($salary['currency_code'] ?? 'GBP'), true)); ?></strong>
                    </div>
                    <div>
                        <span><?php esc_html_e('Median salary', 'senna-finance'); ?></span>
                        <strong><?php echo esc_html($this->format_crm_reddit_single_job_compact_salary((int) ($salary['median_salary'] ?? 0), (string) ($salary['currency_code'] ?? 'GBP'), true)); ?></strong>
                    </div>
                    <div>
                        <span><?php esc_html_e('Tax rate', 'senna-finance'); ?></span>
                        <strong><?php echo esc_html((string) ($salary['tax_rate'] ?? '')); ?></strong>
                    </div>
                </div>
                <div class="sffc-cv-match-studio__career-report-salary-svgwrap">
                    <svg viewBox="0 0 <?php echo esc_attr((string) $width); ?> <?php echo esc_attr((string) $height); ?>" role="img" aria-label="<?php esc_attr_e('Salary trend spline chart', 'senna-finance'); ?>">
                        <line x1="<?php echo esc_attr((string) $left); ?>" y1="32" x2="<?php echo esc_attr((string) ($left + $usable_width)); ?>" y2="32" class="salary-grid-line" />
                        <line x1="<?php echo esc_attr((string) $left); ?>" y1="70" x2="<?php echo esc_attr((string) ($left + $usable_width)); ?>" y2="70" class="salary-grid-line" />
                        <line x1="<?php echo esc_attr((string) $left); ?>" y1="108" x2="<?php echo esc_attr((string) ($left + $usable_width)); ?>" y2="108" class="salary-grid-line" />
                        <line x1="<?php echo esc_attr((string) $left); ?>" y1="<?php echo esc_attr((string) $bottom); ?>" x2="<?php echo esc_attr((string) ($left + $usable_width)); ?>" y2="<?php echo esc_attr((string) $bottom); ?>" class="salary-axis-line" />
                        <polygon points="<?php echo esc_attr($area_points); ?>" class="salary-area-fill"></polygon>
                        <polyline points="<?php echo esc_attr($point_string); ?>" class="salary-line-stroke"></polyline>
                        <?php foreach ($values as $index => $value) : ?>
                            <?php
                            $x = $left + ($step_x * $index);
                            $y = $bottom - (($value / $max_value) * $usable_height);
                            ?>
                            <circle cx="<?php echo esc_attr((string) round($x, 2)); ?>" cy="<?php echo esc_attr((string) round($y, 2)); ?>" r="4.5" class="salary-point"></circle>
                        <?php endforeach; ?>
                    </svg>
                </div>
                <div class="sffc-cv-match-studio__career-report-salary-labels">
                    <?php foreach ($stages as $stage) : ?>
                        <div>
                            <strong><?php echo esc_html((string) ($stage['label'] ?? '')); ?></strong>
                            <span><?php echo esc_html($this->format_crm_reddit_single_job_compact_salary((int) ($stage['annual_salary'] ?? 0), (string) ($salary['currency_code'] ?? 'GBP'), true)); ?></span>
                        </div>
                    <?php endforeach; ?>
                </div>
                <?php if (!empty($salary['insights']) && is_array($salary['insights'])) : ?>
                    <ul class="sffc-cv-match-studio__career-report-salary-notes">
                        <?php foreach (array_slice($salary['insights'], 0, 2) as $insight) : ?>
                            <li><?php echo esc_html((string) $insight); ?></li>
                        <?php endforeach; ?>
                    </ul>
                <?php endif; ?>
            </div>
        <?php
            return ob_get_clean();
        }

