        private function get_cv_match_studio_jobs_mailbox_keyword_chips(array $item, $cv_text = '', $limit = 6)
        {
            $limit = max(1, (int) $limit);
            if (!empty($item['_jobs_mailbox_keyword_chips']) && is_array($item['_jobs_mailbox_keyword_chips'])) {
                return array_slice(array_values(array_filter((array) $item['_jobs_mailbox_keyword_chips'], static function ($chip) {
                    return is_array($chip) && !empty($chip['label']);
                })), 0, $limit);
            }

            $raw_keywords = array_values(array_filter(array_map('sanitize_text_field', (array) ($item['keywords'] ?? []))));
            $job_description_text = trim(implode(' ', array_filter([
                (string) ($item['content'] ?? ''),
                (string) ($item['description_html'] ?? ''),
                (string) ($item['description'] ?? ''),
            ])));
            $derived_keywords = $this->collect_cv_match_studio_jobs_mailbox_apply_keywords($item, $job_description_text);
            $role_signal_source = trim(implode(' ', array_filter([
                $job_description_text,
                (string) ($item['role_title'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['company'] ?? ''),
                (string) ($item['location'] ?? ''),
            ])));
            $role_signals = $this->extract_cv_match_studio_jobs_mailbox_role_signals(
                $role_signal_source,
                [
                    'role_title' => (string) ($item['role_title'] ?? ''),
                    'company' => (string) ($item['company'] ?? ''),
                    'location' => (string) ($item['location'] ?? ''),
                    'seniority' => (string) ($item['seniority'] ?? ''),
                    'sector' => (string) ($item['sector'] ?? ''),
                    'keywords' => (array) ($item['keywords'] ?? []),
                ]
            );
            $signal_keywords = array_merge(
                (array) ($role_signals['primary_signals'] ?? []),
                (array) ($role_signals['tools'] ?? []),
                (array) ($role_signals['credentials'] ?? [])
            );
            $raw_keywords = array_values(array_unique(array_filter(array_merge($raw_keywords, $derived_keywords, $signal_keywords))));
            $company_labels = array_values(array_filter([
                sanitize_text_field((string) ($item['company'] ?? '')),
            ]));
            $raw_keywords = array_values(array_filter(array_map(function ($term) use ($company_labels) {
                $term = str_replace('_', ' ', sanitize_text_field((string) $term));
                $term = trim(preg_replace('/\s+/', ' ', $term));
                return $this->is_cv_match_studio_career_report_useful_term($term, $company_labels) ? $term : '';
            }, $raw_keywords)));
            if (empty($raw_keywords)) {
                return [];
            }

            $normalized_cv_text = $this->normalize_crm_reddit_dashboard_cv_text((string) $cv_text);
            $seen = [];
            $matched = [];
            $missing = [];

            foreach ($raw_keywords as $keyword) {
                $keyword = trim((string) $keyword);
                if ($keyword === '') {
                    continue;
                }

                $dedupe_key = strtolower($keyword);
                if (isset($seen[$dedupe_key])) {
                    continue;
                }
                $seen[$dedupe_key] = true;

                $state = $normalized_cv_text !== '' && $this->cv_match_studio_jobs_mailbox_keyword_matches_cv($keyword, $normalized_cv_text)
                    ? 'match'
                    : ($normalized_cv_text !== '' ? 'missing' : 'neutral');

                $row = [
                    'label' => $keyword,
                    'state' => $state,
                ];

                if ('match' === $state) {
                    $matched[] = $row;
                } elseif ('missing' === $state) {
                    $missing[] = $row;
                } else {
                    $missing[] = $row;
                }
            }

            return array_slice(array_merge($matched, $missing), 0, $limit);
        }

        private function cv_match_studio_jobs_mailbox_keyword_matches_cv($keyword, $normalized_cv_text)
        {
            $normalized_keyword = $this->normalize_crm_reddit_dashboard_cv_text((string) $keyword);
            $normalized_cv_text = $this->normalize_crm_reddit_dashboard_cv_text((string) $normalized_cv_text);

            if ($normalized_keyword === '' || $normalized_cv_text === '') {
                return false;
            }

            if (strpos($normalized_cv_text, $normalized_keyword) !== false) {
                return true;
            }

            $keyword_tokens = array_values(array_filter(explode(' ', $normalized_keyword)));
            if (count($keyword_tokens) <= 1) {
                return strpos(' ' . $normalized_cv_text . ' ', ' ' . $normalized_keyword . ' ') !== false;
            }

            foreach ($keyword_tokens as $token) {
                if (strpos(' ' . $normalized_cv_text . ' ', ' ' . $token . ' ') === false) {
                    return false;
                }
            }

            return true;
        }

        private function render_cv_match_studio_jobs_mailbox_row_keywords(array $item, $cv_text = '', $limit = 6)
        {
            $chips = $this->get_cv_match_studio_jobs_mailbox_keyword_chips($item, $cv_text, $limit);
            if (empty($chips)) {
                return '';
            }

            ob_start();
            ?>
            <span class="sffc-cv-match-studio__jobs-mailbox-keywords">
                <?php foreach ($chips as $chip) : ?>
                    <?php
                    $chip_label = sanitize_text_field((string) ($chip['label'] ?? ''));
                    $chip_state = sanitize_key((string) ($chip['state'] ?? 'neutral'));
                    $chip_tone = 'match' === $chip_state ? 'is-perfect' : ('missing' === $chip_state ? 'is-weak' : 'is-ok');
                    if ($chip_label === '') {
                        continue;
                    }
                    ?>
                    <span class="sffc-cv-match-studio__jobs-mailbox-keywordchip <?php echo esc_attr($chip_tone); ?>">
                        <?php echo esc_html($chip_label); ?>
                    </span>
                <?php endforeach; ?>
            </span>
            <?php
            return ob_get_clean();
        }

        private function get_cv_match_studio_jobs_mailbox_badge_keywords(array $item, $limit = 2)
        {
            $limit = max(1, (int) $limit);
            $source = $item['keywords'] ?? [];

            if (is_string($source)) {
                $decoded = json_decode($source, true);
                $source = is_array($decoded) ? $decoded : (preg_split('/[\r\n,|;]+/', $source) ?: []);
            }

            $keywords = [];
            foreach ((array) $source as $keyword) {
                if (is_array($keyword)) {
                    $label = '';
                    foreach (['keyword', 'label', 'term', 'name', 'value'] as $key) {
                        if (!empty($keyword[$key]) && is_scalar($keyword[$key])) {
                            $label = (string) $keyword[$key];
                            break;
                        }
                    }
                } else {
                    $label = (string) $keyword;
                }

                $label = trim(preg_replace('/\s+/', ' ', sanitize_text_field(str_replace('_', ' ', (string) $label))));
                if ($label === '') {
                    continue;
                }

                $dedupe_key = strtolower($label);
                if (isset($keywords[$dedupe_key])) {
                    continue;
                }

                $keywords[$dedupe_key] = $label;
                if (count($keywords) >= $limit) {
                    break;
                }
            }

            return array_values($keywords);
        }

        private function render_cv_match_studio_jobs_mailbox_badge_keywords(array $item, $limit = 2)
        {
