        private function build_crm_reddit_single_analysis_flow_rows_from_text($text, array $labels = [], $limit = 3)
        {
            $text = trim(wp_strip_all_tags((string) $text));
            if ($text === '') {
                return [];
            }

            $limit = max(1, (int) $limit);
            $parts = preg_split('/(?<=[.!?])\s+/u', $text) ?: [];
            $parts = array_values(array_filter(array_map(static function ($part) {
                return trim((string) $part);
            }, $parts)));

            if (empty($parts)) {
                $parts = [$text];
            }

            $parts = array_slice($parts, 0, $limit);
            $labels = array_values(array_filter(array_map('sanitize_text_field', $labels)));
            $rows = [];

            foreach ($parts as $index => $part) {
                $rows[] = [
                    'label' => $labels[$index] ?? sprintf(__('Step %d', 'senna-finance'), $index + 1),
                    'detail' => $part,
                ];
            }

            return $rows;
        }

        private function render_crm_reddit_single_analysis_text_panels(array $rows, $modifier = '')
        {
            $rows = array_values(array_filter(array_map(static function ($row) {
                if (!is_array($row)) {
                    return null;
                }

                $label = sanitize_text_field((string) ($row['label'] ?? ''));
                $detail = trim((string) ($row['detail'] ?? ''));
                if ($detail === '') {
                    return null;
                }

                return [
                    'label' => $label,
                    'detail' => $detail,
                ];
            }, $rows)));

            if (empty($rows)) {
                return '';
            }

            $classes = 'sffc-crm-reddit-single-analysis-text-panels';
            if ($modifier !== '') {
                $classes .= ' ' . sanitize_html_class($modifier);
            }

            ob_start();
        ?>
            <div class="<?php echo esc_attr($classes); ?>">
                <?php foreach ($rows as $row) : ?>
                    <article class="sffc-crm-reddit-single-analysis-text-panel">
                        <?php if ($row['label'] !== '') : ?>
                            <span class="sffc-crm-reddit-single-analysis-text-panel-label"><?php echo esc_html($row['label']); ?></span>
                        <?php endif; ?>
                        <p><?php echo esc_html($row['detail']); ?></p>
                    </article>
                <?php endforeach; ?>
            </div>
        <?php
            return ob_get_clean();
        }

