        private function render_crm_reddit_single_analysis_flow_chart(array $rows)
        {
            $rows = array_values(array_filter(array_map(static function ($row) {
                if (!is_array($row)) {
                    return null;
                }

                $label = sanitize_text_field((string) ($row['label'] ?? ''));
                $detail = trim((string) ($row['detail'] ?? ''));
                if ($label === '' && $detail === '') {
                    return null;
                }

                return [
                    'label' => $label !== '' ? $label : __('Signal', 'senna-finance'),
                    'detail' => $detail,
                ];
            }, $rows)));

            if (empty($rows)) {
                return '';
            }

            $count = count($rows);
            $step = $count > 1 ? (int) floor(28 / ($count - 1)) : 0;
            $priority_labels = [
                __('Lead with', 'senna-finance'),
                __('Prove quickly', 'senna-finance'),
                __('Support with', 'senna-finance'),
                __('Tighten next', 'senna-finance'),
                __('Keep in reserve', 'senna-finance'),
            ];
            $table_lenses = [
                __('CV headline', 'senna-finance'),
                __('First bullet', 'senna-finance'),
                __('Interview proof', 'senna-finance'),
                __('Application wording', 'senna-finance'),
                __('Cover note', 'senna-finance'),
            ];
            $visual_rows = [];

            foreach ($rows as $index => $row) {
                $score = max(56, 92 - ($index * $step));
                $detail = trim((string) ($row['detail'] ?? ''));
                $sentences = preg_split('/(?<=[.!?])\s+/', $detail) ?: [];
                $first_sentence = trim((string) ($sentences[0] ?? $detail));
                if ($first_sentence === '') {
                    $first_sentence = $detail;
                }

                $visual_rows[] = [
                    'label' => (string) $row['label'],
                    'detail' => $detail,
                    'score' => (int) $score,
                    'priority' => $priority_labels[min($index, count($priority_labels) - 1)],
                    'lens' => $table_lenses[min($index, count($table_lenses) - 1)],
                    'note' => wp_trim_words($first_sentence, 16, ''),
                ];
            }

            $lead_count = min(1, $count);
            $support_count = $count > 2 ? $count - 2 : max(0, $count - 1);
            $tighten_count = $count - $lead_count - $support_count;
            $lead_percent = (int) round(($lead_count / $count) * 100);
            $support_percent = (int) round(($support_count / $count) * 100);
            $tighten_percent = max(0, 100 - $lead_percent - $support_percent);
            $average_score = (int) round(array_sum(array_column($visual_rows, 'score')) / $count);
            $pictogram_fill = max(1, min(5, (int) round($average_score / 20)));
            $table_rows = array_slice($visual_rows, 0, 4);

            ob_start();
        ?>
            <div class="sffc-crm-reddit-single-analysis-flow-chart">
                <article class="sffc-crm-reddit-single-analysis-flow-card sffc-crm-reddit-single-analysis-flow-card--comparison">
                    <div class="sffc-crm-reddit-single-analysis-flow-card-head">
                        <span><?php esc_html_e('Comparison chart', 'senna-finance'); ?></span>
                        <strong><?php esc_html_e('What to surface first', 'senna-finance'); ?></strong>
                    </div>
                    <div class="sffc-crm-reddit-single-analysis-compare-chart">
                        <?php foreach ($visual_rows as $row) : ?>
                            <div class="sffc-crm-reddit-single-analysis-compare-row">
                                <div class="sffc-crm-reddit-single-analysis-compare-copy">
                                    <strong><?php echo esc_html($row['label']); ?></strong>
                                    <span><?php echo esc_html($row['priority']); ?></span>
                                </div>
                                <div class="sffc-crm-reddit-single-analysis-compare-bar">
                                    <span style="width: <?php echo esc_attr((string) $row['score']); ?>%;"></span>
                                </div>
                                <b><?php echo esc_html((string) $row['score']); ?></b>
                            </div>
                        <?php endforeach; ?>
                    </div>
                </article>
                <article class="sffc-crm-reddit-single-analysis-flow-card sffc-crm-reddit-single-analysis-flow-card--pie">
                    <div class="sffc-crm-reddit-single-analysis-flow-card-head">
                        <span><?php esc_html_e('Signal split', 'senna-finance'); ?></span>
                        <strong><?php esc_html_e('Where the emphasis should sit', 'senna-finance'); ?></strong>
                    </div>
                    <div class="sffc-crm-reddit-single-analysis-pie-chart-wrap">
                        <div
                            class="sffc-crm-reddit-single-analysis-pie-chart"
                            style="--lead: <?php echo esc_attr((string) $lead_percent); ?>%; --support: <?php echo esc_attr((string) $support_percent); ?>%; --tighten: <?php echo esc_attr((string) $tighten_percent); ?>%;">
                            <div class="sffc-crm-reddit-single-analysis-pie-chart-core">
                                <strong><?php echo esc_html((string) $average_score); ?></strong>
                                <span><?php esc_html_e('focus', 'senna-finance'); ?></span>
                            </div>
                        </div>
                        <div class="sffc-crm-reddit-single-analysis-pie-legend">
                            <div>
                                <span class="is-lead"></span>
                                <strong><?php esc_html_e('Lead', 'senna-finance'); ?></strong>
                                <b><?php echo esc_html((string) $lead_percent); ?>%</b>
                            </div>
                            <div>
                                <span class="is-support"></span>
                                <strong><?php esc_html_e('Support', 'senna-finance'); ?></strong>
                                <b><?php echo esc_html((string) $support_percent); ?>%</b>
                            </div>
                            <div>
                                <span class="is-tighten"></span>
                                <strong><?php esc_html_e('Tighten', 'senna-finance'); ?></strong>
                                <b><?php echo esc_html((string) $tighten_percent); ?>%</b>
                            </div>
                        </div>
                    </div>
                </article>
                <article class="sffc-crm-reddit-single-analysis-flow-card sffc-crm-reddit-single-analysis-flow-card--table">
                    <div class="sffc-crm-reddit-single-analysis-flow-card-head">
                        <span><?php esc_html_e('Table view', 'senna-finance'); ?></span>
                        <strong><?php esc_html_e('How recruiters will read it', 'senna-finance'); ?></strong>
                    </div>
                    <div class="sffc-crm-reddit-single-analysis-table-chart" role="table" aria-label="<?php esc_attr_e('Recruiter reading order', 'senna-finance'); ?>">
                        <div class="sffc-crm-reddit-single-analysis-table-chart-head" role="row">
                            <span role="columnheader"><?php esc_html_e('Signal', 'senna-finance'); ?></span>
                            <span role="columnheader"><?php esc_html_e('Lens', 'senna-finance'); ?></span>
                            <span role="columnheader"><?php esc_html_e('What to say', 'senna-finance'); ?></span>
                        </div>
                        <?php foreach ($table_rows as $row) : ?>
                            <div class="sffc-crm-reddit-single-analysis-table-chart-row" role="row">
                                <strong role="cell"><?php echo esc_html($row['label']); ?></strong>
                                <span role="cell"><?php echo esc_html($row['lens']); ?></span>
                                <span role="cell"><?php echo esc_html($row['note']); ?></span>
                            </div>
                        <?php endforeach; ?>
                    </div>
                </article>
                <article class="sffc-crm-reddit-single-analysis-flow-card sffc-crm-reddit-single-analysis-flow-card--pictogram">
                    <div class="sffc-crm-reddit-single-analysis-flow-card-head">
                        <span><?php esc_html_e('Pictogram', 'senna-finance'); ?></span>
                        <strong><?php esc_html_e('How ready the section looks on first scan', 'senna-finance'); ?></strong>
                    </div>
                    <div class="sffc-crm-reddit-single-analysis-pictogram">
                        <div class="sffc-crm-reddit-single-analysis-pictogram-icons" aria-hidden="true">
                            <?php for ($i = 0; $i < 5; $i++) : ?>
                                <span class="<?php echo $i < $pictogram_fill ? 'is-filled' : ''; ?>"></span>
                            <?php endfor; ?>
                        </div>
                        <div class="sffc-crm-reddit-single-analysis-pictogram-copy">
                            <strong><?php echo esc_html(sprintf(__('%d out of 5 signals are already strong', 'senna-finance'), $pictogram_fill)); ?></strong>
                            <p><?php echo esc_html($visual_rows[0]['note'] ?? ''); ?></p>
