        private function call_crm_reddit_single_job_overview_claude(array $context)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '') {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 2600,
                'temperature' => 0.1,
                'system' => $this->get_crm_reddit_single_job_overview_system_prompt(),
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => $this->build_crm_reddit_single_job_overview_user_prompt($context),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('Reddit Single Job Overview Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);

            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('Reddit Single Job Overview Claude Error: status ' . $status);
                return null;
            }

            $decoded = json_decode((string) $body['content'][0]['text'], true);
            if (!is_array($decoded)) {
                error_log('Reddit Single Job Overview Claude Parse Error: ' . json_last_error_msg());
                return null;
            }

            return $decoded;
        }

