        private function highlight_crm_reddit_single_job_summary_text($text, array $terms)
        {
            $text = trim((string) $text);
            if ($text === '') {
                return '';
            }

            $terms = array_values(array_unique(array_filter(array_map('trim', $terms))));
            if (empty($terms)) {
                return esc_html($text);
            }

            usort($terms, static function ($a, $b) {
                return strlen((string) $b) <=> strlen((string) $a);
            });

            $placeholders = [];

            foreach ($terms as $index => $term) {
                if ($term === '') {
                    continue;
                }

                $pattern = '/' . preg_quote($term, '/') . '/i';
                $text = preg_replace_callback($pattern, static function ($matches) use (&$placeholders, $index) {
                    $token = '@@SFFC_HL_' . $index . '_' . count($placeholders) . '@@';
                    $placeholders[$token] = '<span class="inst-cv-highlight inst-cv-highlight--add">' . esc_html((string) $matches[0]) . '</span>';
                    return $token;
                }, $text);
            }

            $escaped = esc_html($text);

            if (!empty($placeholders)) {
                $escaped = strtr($escaped, $placeholders);
            }

            $escaped = preg_replace('/(?:%%|@@)SFFC_[A-Z_0-9]+(?:%%|@@)/', '', (string) $escaped);

            return $escaped;
        }

        private function highlight_crm_reddit_single_job_outreach_preview_text($text, array $terms_by_tone)
        {
            $text = trim((string) $text);
            if ($text === '') {
                return '';
            }

            $ordered_terms = [];

            foreach ((array) $terms_by_tone as $tone => $terms) {
                foreach ((array) $terms as $term) {
                    $term = trim((string) $term);
                    if ($term === '') {
                        continue;
                    }

                    $key = function_exists('mb_strtolower')
                        ? mb_strtolower($term)
                        : strtolower($term);
                    if (!isset($ordered_terms[$key])) {
                        $ordered_terms[$key] = [
                            'term' => $term,
                            'tone' => sanitize_html_class((string) $tone),
                        ];
                    }
                }
            }

            if (empty($ordered_terms)) {
                return esc_html($text);
            }

            $ordered_terms = array_values($ordered_terms);
            usort($ordered_terms, static function ($left, $right) {
                return strlen((string) ($right['term'] ?? '')) <=> strlen((string) ($left['term'] ?? ''));
            });

            $placeholders = [];

            foreach ($ordered_terms as $index => $item) {
                $term = (string) ($item['term'] ?? '');
                $tone = (string) ($item['tone'] ?? 'is-highlight');
                if ($term === '') {
                    continue;
                }

                $pattern = '/(?<![\p{L}\p{N}])' . preg_quote($term, '/') . '(?![\p{L}\p{N}])/iu';
                $text = preg_replace_callback($pattern, static function ($matches) use (&$placeholders, $index, $tone) {
                    $token = '@@SFFC_REDDIT_OUTREACH_HL_' . $index . '_' . count($placeholders) . '@@';
                    $placeholders[$token] = '<mark class="sffc-crm-reddit-single-analysis-inline-mark ' . esc_attr($tone) . '">' . esc_html((string) $matches[0]) . '</mark>';
                    return $token;
                }, $text);
            }

            $escaped = esc_html($text);

            if (!empty($placeholders)) {
                $escaped = strtr($escaped, $placeholders);
            }

            $escaped = preg_replace('/(?:%%|@@)SFFC_[A-Z_0-9]+(?:%%|@@)/', '', (string) $escaped);

            return $escaped;
        }

