        private function format_crm_reddit_single_job_compact_salary($amount, $currency_code = 'AED', $use_currency_symbol = false)
        {
            $amount = max(0, (int) round((float) $amount));
            if ($amount === 0) {
                $label = '0K';
            } else {
                $thousands = max(1, (int) round($amount / 1000));
                $label = $thousands >= 1000
                    ? number_format_i18n($thousands / 1000, 1) . 'M'
                    : number_format_i18n($thousands) . 'K';
            }
            $prefix = $use_currency_symbol ? trim((string) $this->get_currency_symbol($currency_code)) : trim((string) $currency_code);
            if ($prefix === '') {
                $prefix = trim((string) $currency_code);
            }

            return $prefix . ' ' . $label;
        }

        private function get_crm_reddit_single_job_salary_comparison_context(array $salary_data)
        {
            $stages = array_values(array_filter((array) ($salary_data['stages'] ?? []), 'is_array'));
            $base_currency = strtoupper(trim((string) ($salary_data['currency_code'] ?? 'AED')));
            $preferred_currency = strtoupper(trim((string) ($salary_data['comparison_currency'] ?? '')));
            if ($preferred_currency === '') {
                $preferred_currency = strtoupper(trim((string) $this->get_user_currency_preference()));
            }

            if ($preferred_currency === '') {
                $preferred_currency = 'USD';
            }

            // Keep the comparison series distinct from the local-currency bars.
            if ($preferred_currency === $base_currency) {
                $preferred_currency = 'USD';
            }

            $fallback_values = array_map(static function ($stage) {
                return max(0, (int) ($stage['usd_equivalent'] ?? ($stage['gbp_equivalent'] ?? 0)));
            }, $stages);

            if ($preferred_currency === 'USD') {
                return [
                    'currency_code' => 'USD',
                    'values' => $fallback_values,
                ];
            }

            $exchange = $this->get_currency_exchange_service();
            if (!$exchange || !method_exists($exchange, 'convert_amount')) {
                return [
                    'currency_code' => 'USD',
                    'values' => $fallback_values,
                ];
            }

            $converted_values = [];
            foreach ($stages as $stage) {
                $local_amount = max(0, (float) ($stage['annual_salary'] ?? 0));
                if ($local_amount <= 0) {
                    $converted_values[] = 0;
                    continue;
                }

                $converted_amount = $exchange->convert_amount($local_amount, $base_currency, $preferred_currency);
                if (!is_numeric($converted_amount) || (float) $converted_amount <= 0) {
                    return [
                        'currency_code' => 'USD',
                        'values' => $fallback_values,
                    ];
                }

                $converted_values[] = max(0, (int) round((float) $converted_amount));
            }

            return [
                'currency_code' => $preferred_currency,
                'values' => $converted_values,
            ];
        }

        private function render_crm_reddit_single_job_salary_chart_svg(array $salary_data, $masked = false, array $comparison_context = [])
        {
            $stages = array_values(array_filter((array) ($salary_data['stages'] ?? []), 'is_array'));
            if (count($stages) < 3) {
                return '';
            }

            $currency_code = (string) ($salary_data['currency_code'] ?? 'AED');
            $local_values = array_map(static function ($stage) {
                return max(0, (int) ($stage['annual_salary'] ?? 0));
            }, $stages);
            if (empty($comparison_context['values']) || !is_array($comparison_context['values'])) {
                $comparison_context = $this->get_crm_reddit_single_job_salary_comparison_context($salary_data);
            }
            $comparison_values = array_map(static function ($value) {
                return max(0, (int) $value);
            }, (array) ($comparison_context['values'] ?? []));
            $comparison_currency = (string) ($comparison_context['currency_code'] ?? 'GBP');
            $local_max = max($local_values);
            $comparison_max = max($comparison_values);

            if ($local_max <= 0 || $comparison_max <= 0) {
                return '';
            }

            $local_axis_max = (int) ceil($local_max / 100000) * 100000;
            if ($local_axis_max <= 0) {
                $local_axis_max = max(100000, $local_max);
            }
            $comparison_axis_max = (int) ceil($comparison_max / 10000) * 10000;
            if ($comparison_axis_max <= 0) {
                $comparison_axis_max = max(10000, $comparison_max);
            }

            $width = 760;
            $height = 390;
            $plot_x = 76;
            $plot_y = 42;
            $plot_width = 590;
            $plot_height = 248;
            $bar_width = 62;
            $point_radius = 7;
            $count = count($stages);
            $gap = (int) floor(($plot_width - ($bar_width * $count)) / max(1, $count - 1));
            $grid_lines = 6;
            $line_points = [];
            $chart_id = 'sffcSalaryChart' . substr(md5((string) wp_json_encode([$local_values, $comparison_values, $currency_code, $comparison_currency, (bool) $masked])), 0, 10);
            $bar_gradient_id = $chart_id . 'BarGradient';
            $line_gradient_id = $chart_id . 'LineGradient';
            $line_area_gradient_id = $chart_id . 'LineAreaGradient';
            $bar_shadow_id = $chart_id . 'BarShadow';
            $line_glow_id = $chart_id . 'LineGlow';

            ob_start();
        ?>
            <svg class="sffc-crm-reddit-single-analysis-salary-chart-svg" viewBox="0 0 <?php echo esc_attr((string) $width); ?> <?php echo esc_attr((string) $height); ?>" role="img" aria-label="<?php esc_attr_e('Salary progression by experience', 'senna-finance'); ?>">
                <defs>
                    <linearGradient id="<?php echo esc_attr($bar_gradient_id); ?>" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stop-color="#9fd0ba" />
                        <stop offset="55%" stop-color="#5fa385" />
                        <stop offset="100%" stop-color="#2f6f5a" />
                    </linearGradient>
                    <linearGradient id="<?php echo esc_attr($line_gradient_id); ?>" x1="0" x2="1" y1="0" y2="0">
                        <stop offset="0%" stop-color="#047857" />
                        <stop offset="55%" stop-color="#16a34a" />
                        <stop offset="100%" stop-color="#22c55e" />
                    </linearGradient>
                    <linearGradient id="<?php echo esc_attr($line_area_gradient_id); ?>" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stop-color="#16a34a" stop-opacity="0.18" />
                        <stop offset="100%" stop-color="#16a34a" stop-opacity="0" />
                    </linearGradient>
                    <filter id="<?php echo esc_attr($bar_shadow_id); ?>" x="-18%" y="-18%" width="136%" height="144%">
                        <feDropShadow dx="0" dy="9" stdDeviation="7" flood-color="#0f5132" flood-opacity="0.16" />
                    </filter>
                    <filter id="<?php echo esc_attr($line_glow_id); ?>" x="-8%" y="-28%" width="116%" height="156%">
                        <feDropShadow dx="0" dy="5" stdDeviation="5" flood-color="#16a34a" flood-opacity="0.28" />
                    </filter>
                </defs>
                <rect x="0" y="0" width="<?php echo esc_attr((string) $width); ?>" height="<?php echo esc_attr((string) $height); ?>" rx="22" fill="#fbfcfe" />
                <rect x="1" y="1" width="<?php echo esc_attr((string) ($width - 2)); ?>" height="<?php echo esc_attr((string) ($height - 2)); ?>" rx="21" fill="none" stroke="#e4ece7" />
                <?php for ($i = 0; $i < $grid_lines; $i++) : ?>
                    <?php
                    $ratio = $grid_lines > 1 ? ($i / ($grid_lines - 1)) : 0;
                    $y = $plot_y + ($plot_height * $ratio);
                    $local_label_value = (int) round($local_axis_max - ($local_axis_max * $ratio));
                    $comparison_label_value = (int) round($comparison_axis_max - ($comparison_axis_max * $ratio));
                    ?>
                    <line x1="<?php echo esc_attr((string) $plot_x); ?>" y1="<?php echo esc_attr((string) $y); ?>" x2="<?php echo esc_attr((string) ($plot_x + $plot_width)); ?>" y2="<?php echo esc_attr((string) $y); ?>" stroke="#d9e4de" stroke-width="1"<?php echo $i === ($grid_lines - 1) ? '' : ' stroke-dasharray="4 8"'; ?> />
                    <text class="sffc-crm-reddit-single-analysis-salary-axis-label<?php echo $masked ? ' is-masked' : ''; ?>" x="14" y="<?php echo esc_attr((string) ($y + 5)); ?>" fill="#64748b" font-size="12" font-family="Arial, sans-serif"><?php echo esc_html($masked ? $this->mask_crm_reddit_single_job_compact_salary($local_label_value, $currency_code) : $this->format_crm_reddit_single_job_compact_salary($local_label_value, $currency_code)); ?></text>
                    <text class="sffc-crm-reddit-single-analysis-salary-axis-label<?php echo $masked ? ' is-masked' : ''; ?>" x="<?php echo esc_attr((string) ($plot_x + $plot_width + 14)); ?>" y="<?php echo esc_attr((string) ($y + 5)); ?>" fill="#047857" font-size="12" font-family="Arial, sans-serif"><?php echo esc_html($masked ? $this->mask_crm_reddit_single_job_compact_salary($comparison_label_value, $comparison_currency, true) : $this->format_crm_reddit_single_job_compact_salary($comparison_label_value, $comparison_currency, true)); ?></text>
                <?php endfor; ?>
                <line x1="<?php echo esc_attr((string) $plot_x); ?>" y1="<?php echo esc_attr((string) ($plot_y + $plot_height)); ?>" x2="<?php echo esc_attr((string) ($plot_x + $plot_width)); ?>" y2="<?php echo esc_attr((string) ($plot_y + $plot_height)); ?>" stroke="#b9c9c0" stroke-width="1.4" />
                <?php foreach ($stages as $index => $stage) : ?>
                    <?php
                    $local_value = max(0, (int) ($stage['annual_salary'] ?? 0));
                    $comparison_value = max(0, (int) ($comparison_values[$index] ?? 0));
                    $x = $plot_x + ($index * ($bar_width + $gap));
                    $bar_height = $local_axis_max > 0 ? ($local_value / $local_axis_max) * $plot_height : 0;
                    $bar_y = $plot_y + $plot_height - $bar_height;
                    $point_x = $x + ($bar_width / 2);
                    $point_y = $plot_y + $plot_height - (($comparison_value / $comparison_axis_max) * $plot_height);
                    $line_points[] = [
                        'x' => round($point_x, 2),
                        'y' => round($point_y, 2),
                    ];
                    ?>
