                    <rect x="<?php echo esc_attr((string) $x); ?>" y="<?php echo esc_attr((string) $bar_y); ?>" width="<?php echo esc_attr((string) $bar_width); ?>" height="<?php echo esc_attr((string) max(2, $bar_height)); ?>" rx="12" fill="url(#<?php echo esc_attr($bar_gradient_id); ?>)" filter="url(#<?php echo esc_attr($bar_shadow_id); ?>)" />
                    <rect x="<?php echo esc_attr((string) ($x + 10)); ?>" y="<?php echo esc_attr((string) ($bar_y + 9)); ?>" width="<?php echo esc_attr((string) max(0, $bar_width - 20)); ?>" height="2" rx="1" fill="#ffffff" opacity="0.28" />
                    <text x="<?php echo esc_attr((string) ($x + ($bar_width / 2))); ?>" y="<?php echo esc_attr((string) ($plot_y + $plot_height + 28)); ?>" fill="#64748b" font-size="13" font-family="Arial, sans-serif" text-anchor="middle"><?php echo esc_html((string) ($stage['label'] ?? '')); ?></text>
                <?php endforeach; ?>
                <?php
                $line_area_path = '';
                $line_path = '';
                if (!empty($line_points)) {
                    $line_area_path = 'M ' . $line_points[0]['x'] . ' ' . ($plot_y + $plot_height);
                    foreach ($line_points as $line_point) {
                        $line_area_path .= ' L ' . $line_point['x'] . ' ' . $line_point['y'];
                    }
                    $last_point = end($line_points);
                    $line_area_path .= ' L ' . $last_point['x'] . ' ' . ($plot_y + $plot_height) . ' Z';

                    if (count($line_points) > 1) {
                        $line_path = 'M ' . $line_points[0]['x'] . ' ' . $line_points[0]['y'];
                        $line_count = count($line_points);
                        for ($line_index = 0; $line_index < ($line_count - 1); $line_index++) {
                            $previous_point = $line_points[max(0, $line_index - 1)];
                            $current_point = $line_points[$line_index];
                            $next_point = $line_points[$line_index + 1];
                            $future_point = $line_points[min($line_count - 1, $line_index + 2)];
                            $control_one_x = $current_point['x'] + (($next_point['x'] - $previous_point['x']) / 6);
                            $control_one_y = $current_point['y'] + (($next_point['y'] - $previous_point['y']) / 6);
                            $control_two_x = $next_point['x'] - (($future_point['x'] - $current_point['x']) / 6);
                            $control_two_y = $next_point['y'] - (($future_point['y'] - $current_point['y']) / 6);
                            $line_path .= ' C ' . round($control_one_x, 2) . ' ' . round($control_one_y, 2) . ', ' . round($control_two_x, 2) . ' ' . round($control_two_y, 2) . ', ' . $next_point['x'] . ' ' . $next_point['y'];
                        }
                    }
                }
                ?>
                <?php if ($line_area_path !== '') : ?>
                    <path d="<?php echo esc_attr($line_area_path); ?>" fill="url(#<?php echo esc_attr($line_area_gradient_id); ?>)" />
                <?php endif; ?>
                <?php if ($line_path !== '') : ?>
                    <path d="<?php echo esc_attr($line_path); ?>" fill="none" stroke="#dcfce7" stroke-width="10" stroke-linecap="round" stroke-linejoin="round" opacity="0.72" />
                    <path d="<?php echo esc_attr($line_path); ?>" fill="none" stroke="url(#<?php echo esc_attr($line_gradient_id); ?>)" stroke-width="4.8" stroke-linecap="round" stroke-linejoin="round" filter="url(#<?php echo esc_attr($line_glow_id); ?>)" />
                <?php endif; ?>
                <?php foreach ($stages as $index => $stage) : ?>
                    <?php
                    $x = $plot_x + ($index * ($bar_width + $gap));
                    $point_x = $x + ($bar_width / 2);
                    $comparison_value = max(0, (int) ($comparison_values[$index] ?? 0));
                    $point_y = $plot_y + $plot_height - (($comparison_value / $comparison_axis_max) * $plot_height);
                    ?>
                    <circle cx="<?php echo esc_attr((string) $point_x); ?>" cy="<?php echo esc_attr((string) $point_y); ?>" r="<?php echo esc_attr((string) ($point_radius + 4)); ?>" fill="#bbf7d0" opacity="0.68" />
                    <circle cx="<?php echo esc_attr((string) $point_x); ?>" cy="<?php echo esc_attr((string) $point_y); ?>" r="<?php echo esc_attr((string) $point_radius); ?>" fill="#047857" stroke="#fff" stroke-width="3" />
                    <circle cx="<?php echo esc_attr((string) $point_x); ?>" cy="<?php echo esc_attr((string) $point_y); ?>" r="2.2" fill="#dcfce7" />
                <?php endforeach; ?>
            </svg>
        <?php
            return ob_get_clean();
        }

