        private function build_crm_reddit_single_job_location_market_context($location_identifier = '')
        {
            $location_identifier = trim((string) $location_identifier);
            $location_key = strtolower($location_identifier);

            $defaults = [
                'cost_of_living' => __('Medium to high for private equity candidates relocating into the market', 'senna-finance'),
                'economy' => __('Employer demand is concentrated around firms with visible hiring needs and specialist mandates', 'senna-finance'),
                'outlook' => __('More attractive when your profile is already well-positioned for the role brief', 'senna-finance'),
            ];

            $profiles = [
                'dubai' => [
                    'cost_of_living' => __('High living costs, with housing usually the biggest trade-off', 'senna-finance'),
                    'economy' => __('A fast-moving financial hub with regional capital flows and cross-border deal activity', 'senna-finance'),
                    'outlook' => __('Strong when firms want internationally credible candidates who can move quickly', 'senna-finance'),
                ],
                'doha' => [
                    'cost_of_living' => __('Moderate to high, with housing quality often shaping the move economics', 'senna-finance'),
                    'economy' => __('State-backed investment activity and institutional capital remain major drivers', 'senna-finance'),
                    'outlook' => __('Best when you can show polished fundamentals and patience for a smaller market', 'senna-finance'),
                ],
                'riyadh' => [
                    'cost_of_living' => __('Rising but still manageable relative to the compensation upside in senior private equity roles', 'senna-finance'),
                    'economy' => __('Large-scale transformation spending and local capital formation keep hiring interest elevated', 'senna-finance'),
                    'outlook' => __('Strong for candidates who can align with growth mandates and local market ambition', 'senna-finance'),
                ],
                'manama' => [
                    'cost_of_living' => __('Moderate by regional finance market standards, usually easier to balance against compensation', 'senna-finance'),
                    'economy' => __('Smaller banking-focused market with concentration around specific employers and mandates', 'senna-finance'),
                    'outlook' => __('Most compelling when you can target the right firms rather than applying broadly', 'senna-finance'),
                ],
                'amman' => [
                    'cost_of_living' => __('Moderate, with lifestyle costs generally lower than the largest finance hubs in the region', 'senna-finance'),
                    'economy' => __('Selective market where employer quality and role specificity matter heavily', 'senna-finance'),
                    'outlook' => __('Best when your profile is already tightly aligned and your expectations are realistic', 'senna-finance'),
                ],
                'new york' => [
                    'cost_of_living' => __('Very high, with rent and daily living costs materially affecting take-home value', 'senna-finance'),
                    'economy' => __('Large and highly competitive market with deep demand for elite execution profiles', 'senna-finance'),
                    'outlook' => __('Excellent for strong profiles, but unforgiving if the fit is only partial', 'senna-finance'),
                ],
                'singapore' => [
                    'cost_of_living' => __('High but usually supported by strong compensation and stable infrastructure', 'senna-finance'),
                    'economy' => __('Regional hub with resilient institutional demand and cross-border finance activity', 'senna-finance'),
                    'outlook' => __('Attractive when you can show precision, stability, and strong regional relevance', 'senna-finance'),
                ],
                'hong kong' => [
                    'cost_of_living' => __('Very high, especially on housing, but still balanced by senior finance upside', 'senna-finance'),
                    'economy' => __('International capital markets hub with cyclical hiring tied to deal and market activity', 'senna-finance'),
                    'outlook' => __('Most compelling when your background is already sharp, technical, and market-aware', 'senna-finance'),
                ],
            ];

            $resolved = $defaults;
            foreach ($profiles as $needle => $profile) {
                if ($location_key !== '' && strpos($location_key, $needle) !== false) {
                    $resolved = array_merge($resolved, $profile);
                    break;
                }
            }

            return $resolved;
        }

