        private function normalize_crm_reddit_single_job_keyword_terms($raw_keywords)
        {
            $terms = [];

            if (is_string($raw_keywords)) {
                $decoded = json_decode($raw_keywords, true);
                if (is_array($decoded)) {
                    $raw_keywords = $decoded;
                } else {
                    $raw_keywords = preg_split('/[\r\n,|]+/', $raw_keywords) ?: [];
                }
            }

            foreach ((array) $raw_keywords as $keyword) {
                $label = '';
                if (is_array($keyword)) {
                    $label = (string) ($keyword['label'] ?? $keyword['keyword'] ?? $keyword['name'] ?? '');
                } else {
                    $label = (string) $keyword;
                }

                $label = sanitize_text_field(trim($label));
                if ($label !== '') {
                    $terms[] = $label;
                }
            }

            return $terms;
        }

        private function collect_crm_reddit_single_job_apply_keywords(array $item, array $overview = [])
        {
            $terms = [];
            $seen = [];
            $stop_terms = array_filter(array_map('sanitize_title', [
                (string) ($item['company'] ?? ''),
                (string) ($item['role_title'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                'job description',
                'overview',
                'requirements',
                'skills',
                'experience',
                'responsibilities',
                'compensation',
            ]));

            $push_term = static function ($value) use (&$terms, &$seen, $stop_terms) {
                $value = sanitize_text_field(trim((string) $value));
                if ($value === '' || (function_exists('mb_strlen') ? mb_strlen($value) : strlen($value)) < 3) {
                    return;
                }

                $slug = sanitize_title($value);
                if ($slug === '' || in_array($slug, $stop_terms, true) || isset($seen[$slug])) {
                    return;
                }

                $seen[$slug] = true;
                $terms[] = $value;
            };

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($item['keywords'] ?? []) as $term) {
                $push_term($term);
            }

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($item['skills_mentioned'] ?? []) as $term) {
                $push_term($term);
            }

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($item['requirements'] ?? []) as $term) {
                $push_term($term);
            }

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($overview['key_skills'] ?? []) as $term) {
                $push_term($term);
            }

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($overview['qualifications'] ?? []) as $term) {
                $push_term($term);
            }

            foreach ($this->normalize_crm_reddit_single_job_keyword_terms($overview['backgrounds'] ?? []) as $term) {
                $push_term($term);
            }

            if (count($terms) < 8 && !empty($item['content']) && class_exists('SFFC_CRM_Keyword_Extractor')) {
                $extractor = new SFFC_CRM_Keyword_Extractor();
                $extracted = $extractor->extract_keywords((string) $item['content'], [
                    'location' => (string) ($item['location'] ?? ''),
                    'role_title' => (string) ($item['role_title'] ?? ''),
                    'company' => (string) ($item['company'] ?? ''),
                ]);
                foreach ($this->normalize_crm_reddit_single_job_keyword_terms($extracted) as $term) {
                    $push_term($term);
                }
            }

            if (count($terms) < 8) {
                $role_signal_source = (string) ($item['content'] ?? '');
                if ($role_signal_source === '') {
                    $role_signal_source = implode(' ', array_filter([
                        (string) ($overview['job_summary'] ?? ''),
                        (string) ($overview['candidate_preference'] ?? ''),
                        implode(' ', (array) ($overview['paragraphs'] ?? [])),
                    ]));
                }

                if ($role_signal_source !== '') {
                    $role_signals = $this->extract_cv_match_studio_jobs_mailbox_role_signals(
                        $role_signal_source,
                        [
                            'role_title' => (string) ($item['role_title'] ?? ''),
                            'company' => (string) ($item['company'] ?? ''),
                            'location' => (string) ($item['location'] ?? ''),
                            'seniority' => (string) ($item['seniority'] ?? ''),
                            'sector' => (string) ($item['sector'] ?? ''),
                            'keywords' => (array) ($item['keywords'] ?? []),
                        ]
                    );

                    foreach (array_merge(
                        (array) ($role_signals['primary_signals'] ?? []),
                        (array) ($role_signals['tools'] ?? []),
                        (array) ($role_signals['credentials'] ?? [])
                    ) as $term) {
                        $push_term($term);
                        if (count($terms) >= 8) {
                            break;
                        }
                    }
                }
            }

            return array_slice($terms, 0, 8);
        }

        private function filter_cv_match_studio_jobs_mailbox_junior_keywords(array $terms)
        {
            $terms = array_values(array_filter(array_map('sanitize_text_field', $terms)));
            $blocked_exact = array_map('sanitize_title', [
                'English',
                'Optimizing Investment',
                'Investment Models and Processes',
                'Investing Data and Technology',
            ]);
            $blocked_fragments = [
                'further improve',
                'our investment',
                'optimizing investment',
                'investment models and processes',
                'data and technology',
                'affinity for',
            ];

            $filtered = [];
            $seen = [];
            foreach ($terms as $term) {
                $term = trim((string) preg_replace('/\s+/', ' ', $term));
                $term_lc = strtolower($term);
                $slug = sanitize_title($term);
                $word_count = count(preg_split('/\s+/', $term) ?: []);

                if ($term === '' || $slug === '' || isset($seen[$slug]) || in_array($slug, $blocked_exact, true)) {
                    continue;
                }
                if ($word_count > 4) {
                    continue;
                }

                $blocked = false;
                foreach ($blocked_fragments as $fragment) {
                    if (strpos($term_lc, $fragment) !== false) {
                        $blocked = true;
                        break;
                    }
                }
                if ($blocked) {
                    continue;
                }

                $seen[$slug] = true;
                $filtered[] = $term;
                if (count($filtered) >= 8) {
                    break;
                }
            }

            return $filtered;
        }

        private function collect_cv_match_studio_jobs_mailbox_apply_keywords(array $item, $job_description_text = '')
        {
            $keyword_item = $item;
            if ($job_description_text !== '') {
                $keyword_item['content'] = (string) $job_description_text;
            }

            $terms = $this->collect_crm_reddit_single_job_apply_keywords($keyword_item, []);

            if (count($terms) < 8) {
                $role_signals = $this->extract_cv_match_studio_jobs_mailbox_role_signals(
                    $job_description_text !== '' ? $job_description_text : (string) ($keyword_item['content'] ?? ''),
                    [
                        'role_title' => (string) ($item['role_title'] ?? ''),
                        'company' => (string) ($item['company'] ?? ''),
                        'location' => (string) ($item['location'] ?? ''),
                        'seniority' => (string) ($item['seniority'] ?? ''),
                        'sector' => (string) ($item['sector'] ?? ''),
                        'keywords' => (array) ($item['keywords'] ?? []),
                    ]
                );

                $seen = [];
                foreach ($terms as $term) {
                    $key = sanitize_title((string) $term);
                    if ($key !== '') {
                        $seen[$key] = true;
                    }
                }

                foreach (array_merge((array) ($role_signals['primary_signals'] ?? []), (array) ($role_signals['tools'] ?? []), (array) ($role_signals['credentials'] ?? [])) as $term) {
                    $term = sanitize_text_field((string) $term);
                    $slug = sanitize_title($term);
                    if ($term === '' || $slug === '' || isset($seen[$slug])) {
                        continue;
                    }
                    $terms[] = $term;
                    $seen[$slug] = true;
                    if (count($terms) >= 10) {
                        break;
                    }
                }
            }

            $terms = $this->filter_cv_match_studio_jobs_mailbox_junior_keywords($terms);

            return array_slice($terms, 0, 8);
        }

        private function get_crm_reddit_single_job_locked_keyword_masks(array $keywords)
        {
            $masks = [];

            foreach ($keywords as $keyword) {
                $keyword = trim((string) $keyword);
                if ($keyword === '') {
                    continue;
                }

                $segments = preg_split('/\s+/', $keyword);
                if (!is_array($segments) || empty($segments)) {
                    continue;
                }

                $masked_segments = [];
                foreach ($segments as $segment) {
                    $segment_length = max(4, min(10, strlen($segment)));
                    $masked_segments[] = str_repeat('•', $segment_length);
                }

                $masks[] = implode(' ', $masked_segments);
            }

            return $masks;
        }

