        private function render_crm_reddit_single_job_recruiter_outreach_preview(array $context)
        {
            $recruiter_first_name = $this->get_recruiter_first_name_for_display((string) ($context['recruiter_display_name'] ?? ''));
            $role_title = trim((string) ($context['role_title'] ?? __('this role', 'senna-finance')));
            $company_name = trim((string) ($context['company_name'] ?? __('the firm', 'senna-finance')));
            $top_skill = trim((string) ($context['top_skill'] ?? __('relevant deal experience', 'senna-finance')));
            $background = trim((string) ($context['background_signal'] ?? __('the hiring brief', 'senna-finance')));
            $subject = sprintf(__('Finance Mandate | %s fit', 'senna-finance'), $company_name);
            $highlight_terms = [
                'is-skill' => array_filter([$top_skill, $background]),
                'is-role' => array_filter([$role_title, $company_name]),
                'is-angle' => array_filter([$role_title, $top_skill]),
            ];
            $paragraphs = [
                sprintf(
                    __('The %1$s brief at %2$s looks especially focused on %3$s and clear early evidence that the candidate can speak to %4$s credibly.', 'senna-finance'),
                    $role_title,
                    $company_name,
                    $top_skill,
                    $background
                ),
                sprintf(
                    __('That is the part of the seat I would lean into first, and I would be happy to send a concise CV version tailored around %1$s if useful.', 'senna-finance'),
                    $top_skill
                ),
                sprintf(
                    __('If you are the right person to ask, I would value a quick steer on whether that is the kind of signal your team looks for early on in %s hires.', 'senna-finance'),
                    $role_title
                ),
            ];
            $candidate_first_name = $this->get_crm_reddit_current_user_first_name();
            if ($candidate_first_name === '') {
                $candidate_first_name = __('Candidate', 'senna-finance');
            }

            ob_start();
        ?>
            <div class="sffc-crm-reddit-single-analysis-outreach-preview-card">
                <h5 class="sffc-crm-reddit-single-analysis-overview-subhead sffc-crm-reddit-single-analysis-outreach-preview-title">
                    <?php
                    echo esc_html(sprintf(
                        __('What to message %s', 'senna-finance'),
                        $recruiter_first_name
                    ));
                    ?>
                </h5>
                <div class="inst-cover-letter-preview sffc-crm-reddit-single-analysis-outreach-preview">
                    <div class="sffc-crm-reddit-single-analysis-outreach-preview-meta">
                        <span class="sffc-crm-reddit-single-analysis-outreach-preview-channel"><?php esc_html_e('Email example', 'senna-finance'); ?></span>
                        <span class="sffc-crm-reddit-single-analysis-outreach-preview-subject"><?php echo esc_html($subject); ?></span>
                    </div>
                    <div class="sffc-crm-reddit-single-analysis-outreach-preview-body">
                        <p class="sffc-crm-reddit-single-analysis-outreach-preview-paragraph"><?php echo esc_html(sprintf(__('Hi %s,', 'senna-finance'), $recruiter_first_name)); ?></p>
                        <?php foreach ($paragraphs as $paragraph) : ?>
                            <p class="sffc-crm-reddit-single-analysis-outreach-preview-paragraph"><?php echo wp_kses_post($this->highlight_crm_reddit_single_job_outreach_preview_text($paragraph, $highlight_terms)); ?></p>
                        <?php endforeach; ?>
                        <p class="sffc-crm-reddit-single-analysis-outreach-preview-paragraph"><?php esc_html_e('Best,', 'senna-finance'); ?><br><?php echo esc_html($candidate_first_name); ?></p>
                    </div>
                </div>
            </div>
        <?php
            return ob_get_clean();
        }

