        private function get_crm_reddit_single_job_cv_score_data(array $profile_comparison, $has_profile_compare_access, $has_uploaded_cv)
        {
            if (!$has_profile_compare_access) {
                return [
                    'score' => 64,
                    'state' => 'locked',
                    'label' => __('Unlock ATS score', 'senna-finance'),
                ];
            }

            if (!$has_uploaded_cv) {
                return [
                    'score' => 0,
                    'state' => 'upload',
                    'label' => __('Upload your CV to compare it against this role', 'senna-finance'),
                ];
            }

            $direct_match_score = max(0, min(100, (int) ($profile_comparison['match_score'] ?? 0)));
            if ($direct_match_score > 0) {
                return [
                    'score' => $direct_match_score,
                    'state' => 'ready',
                    'label' => __('Based on your CV and the role brief', 'senna-finance'),
                ];
            }

            $metrics = array_values(array_filter((array) ($profile_comparison['metrics'] ?? []), 'is_array'));
            if (empty($metrics)) {
                return [
                    'score' => 0,
                    'state' => 'upload',
                    'label' => __('Role score unavailable', 'senna-finance'),
                ];
            }

            $scores = [];
            foreach ($metrics as $metric) {
                $scores[] = max(0, min(100, (int) ($metric['score'] ?? 0)));
            }

            $average = !empty($scores) ? (int) round(array_sum($scores) / count($scores)) : 0;

            return [
                'score' => $average,
                'state' => 'ready',
                'label' => __('Based on the role brief', 'senna-finance'),
            ];
        }

