                                    aria-label="<?php esc_attr_e('Compare job with CV', 'senna-finance'); ?>">
                                    <span class="sffc-crm-reddit-single-analysis-score-lock-value">64</span>
                                    <svg viewBox="0 0 20 20">
                                        <path d="M6.5 8V6.8a3.5 3.5 0 1 1 7 0V8m-8 0h9a1 1 0 0 1 1 1v6.2a1 1 0 0 1-1 1h-9a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" />
                                    </svg>
                                </button>
                            <?php else : ?>
                                <a class="sffc-crm-reddit-single-analysis-score-lock" href="<?php echo esc_url($membership_url); ?>" target="_blank" rel="noopener noreferrer" aria-label="<?php esc_attr_e('Compare job with CV', 'senna-finance'); ?>">
                                    <span class="sffc-crm-reddit-single-analysis-score-lock-value">64</span>
                                    <svg viewBox="0 0 20 20">
                                        <path d="M6.5 8V6.8a3.5 3.5 0 1 1 7 0V8m-8 0h9a1 1 0 0 1 1 1v6.2a1 1 0 0 1-1 1h-9a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" />
                                    </svg>
                                </a>
                            <?php endif; ?>
                        <?php elseif ($state === 'upload') : ?>
                            <span class="sffc-crm-reddit-single-analysis-score-text is-small"><?php esc_html_e('Match Score', 'senna-finance'); ?></span>
                        <?php else : ?>
                            <span class="sffc-crm-reddit-single-analysis-score-text"><?php echo esc_html((string) $score); ?></span>
                        <?php endif; ?>
