        private function get_crm_reddit_single_job_title_badge(array $item)
        {
            $location = strtolower(trim((string) ($item['location'] ?? '')));
            $role_title = strtolower(trim((string) ($item['role_title'] ?? '')));
            $seniority = strtolower(trim((string) ($item['seniority'] ?? '')));

            $target_cities = ['dubai', 'doha', 'riyadh', 'manama', 'amman'];
            $location_match = false;

            foreach ($target_cities as $city) {
                if ($location !== '' && strpos($location, $city) !== false) {
                    $location_match = true;
                    break;
                }
            }

            if (!$location_match) {
                return '';
            }

            if (strpos($role_title, 'director') !== false || strpos($seniority, 'director') !== false) {
                $labels = [
                    __('Tax Free Income', 'senna-finance'),
                    __('Leadership Role', 'senna-finance'),
                ];
            } elseif (strpos($role_title, 'manager') !== false || strpos($seniority, 'manager') !== false) {
                $labels = [
                    __('Strong Currency', 'senna-finance'),
                    __('International Exposure', 'senna-finance'),
                ];
            } elseif (strpos($role_title, 'associate') !== false || strpos($seniority, 'associate') !== false) {
                $labels = [
                    __('Tax Free Salary', 'senna-finance'),
                    __('Strong Currency', 'senna-finance'),
                    __('International Exposure', 'senna-finance'),
                    __('Growing Financial Hub', 'senna-finance'),
                    __('Networking Opportunities', 'senna-finance'),
                    __('Strong Associate Salaries', 'senna-finance'),
                    __('Growing Opportunities', 'senna-finance'),
                ];
            } elseif (strpos($role_title, 'analyst') !== false || strpos($seniority, 'analyst') !== false) {
                $labels = [
                    __('High Career Growth', 'senna-finance'),
                    __('Growing Financial Hub', 'senna-finance'),
                    __('Networking Opportunities', 'senna-finance'),
                    __('Strong Manager Compensation', 'senna-finance'),
                ];
            } else {
                $labels = [
                    __('Growing Opportunities', 'senna-finance'),
                    __('International Exposure', 'senna-finance'),
                    __('Networking Opportunities', 'senna-finance'),
                ];
            }

            $seed = (string) ($item['role_title'] ?? '') . '|' . (string) ($item['location'] ?? '') . '|' . (string) ($item['company'] ?? '');
            $index = abs((int) crc32($seed)) % count($labels);

            return (string) $labels[$index];
        }

        private function render_crm_reddit_single_job_layout(array $item, $is_logged_in, $title, $include_recommendations = false)
        {
            $logged_out_cache_key = '';

            $company_name = trim((string) ($item['company'] ?? ''));
            $description_html = (string) ($item['description_html'] ?? '');
            $opportunity_notice = $this->get_crm_reddit_opportunity_notice($item);
            $recommendations = $include_recommendations ? $this->get_crm_reddit_single_job_recommendations($item, 8) : [];
            $membership_url = $this->get_crm_reddit_membership_url();
            $current_url = get_permalink(get_queried_object_id()) ?: home_url('/');
            $login_url = wp_login_url($current_url);
            $has_material_access = $this->current_user_has_crm_reddit_premium_access();
            $resume_payload = ($has_material_access && $is_logged_in)
                ? $this->get_crm_reddit_active_resume_text(get_current_user_id())
                : ['cv_text' => '', 'has_cv' => false];
            $topbar_account_user = $is_logged_in ? $this->get_crm_reddit_account_user(get_current_user_id()) : [];
            $search_suggestions = $include_recommendations
                ? $this->build_crm_reddit_search_suggestions($this->get_crm_reddit_single_job_search_items(72), '', 48)
                : [];
            $analysis = $this->build_crm_reddit_single_job_analysis_data($item);
            $ai_overview = $this->get_crm_reddit_single_job_ai_overview($item, $analysis);
            $profile_comparison = $this->get_crm_reddit_single_job_profile_comparison($item, $analysis, '');
            $salary_trajectory = $this->get_crm_reddit_single_job_salary_trajectory($item);
            $detail_points = [];
            $layout_classes = 'sffc-crm-reddit-single-layout sffc-crm-reddit-single-layout--analysis';
            if (empty($recommendations)) {
                $layout_classes .= ' sffc-crm-reddit-single-layout--no-rail';
            }

            $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
            $recruiter_display_name = $this->get_crm_reddit_public_recruiter_name($recruiter_name, $has_material_access);
            $recruiter_display_name = $recruiter_display_name !== '' ? $recruiter_display_name : __('Recruiter', 'senna-finance');
            $recruiter_title = trim((string) ($item['recruiter_title'] ?? __('Recruitment Team', 'senna-finance')));
            $recruiter_firm = trim((string) ($item['recruiter_firm'] ?? $company_name));
            $recruiter_public_firm_label = trim((string) ($item['recruiter_public_firm_label'] ?? ''));
            if ($this->is_crm_reddit_placeholder_recruiter_value($recruiter_firm)) {
                $recruiter_firm = '';
            }
            if ($this->is_crm_reddit_placeholder_recruiter_value($recruiter_public_firm_label)) {
                $recruiter_public_firm_label = '';
            }
            $recruiter_firm_profile_display = $recruiter_firm;
            if (!$has_material_access && $recruiter_firm !== '') {
                $first_char = function_exists('mb_substr') ? mb_substr($recruiter_firm, 0, 1) : substr($recruiter_firm, 0, 1);
                $recruiter_firm_profile_display = $first_char . '****';
            }
            $recruiter_phone_raw = trim((string) ($item['recruiter_phone'] ?? ''));
            $recruiter_phone_digits = preg_replace('/[^0-9+]/', '', $recruiter_phone_raw);
            $recruiter_phone_display = $recruiter_phone_raw !== '' ? $recruiter_phone_raw : __('Call recruiter', 'senna-finance');
            $recruiter_message_url = $has_material_access && !empty($item['recruiter_linkedin'])
                ? esc_url_raw((string) $item['recruiter_linkedin'])
                : $membership_url;
            $recruiter_message_disabled = $has_material_access && empty($item['recruiter_linkedin']);
            $recruiter_linkedin_url = $has_material_access && !empty($item['recruiter_linkedin'])
                ? esc_url_raw((string) $item['recruiter_linkedin'])
                : ($has_material_access ? '' : $membership_url);
            $recruiter_linkedin_disabled = $has_material_access && $recruiter_linkedin_url === '';
            $recruiter_email_url = $has_material_access && !empty($item['recruiter_email'])
                ? 'mailto:' . sanitize_email((string) $item['recruiter_email'])
                : $membership_url;
            $recruiter_email_disabled = $has_material_access && empty($item['recruiter_email']);
            $recruiter_call_url = $has_material_access && $recruiter_phone_digits !== ''
                ? 'tel:' . $recruiter_phone_digits
                : ($has_material_access ? '' : $membership_url);
            $recruiter_call_disabled = $has_material_access && $recruiter_phone_digits === '';
            $recruiter_view_jobs_url = $has_material_access
                ? (!empty($recommendations) ? '#single-job-best-matches' : $membership_url)
                : $membership_url;
            $recruiter_action_target = $has_material_access ? '_blank' : '_self';
            $recruiter_action_rel = $has_material_access ? 'noopener noreferrer' : '';
            $recruiter_access_score = (int) ($analysis['recruiter_access'] ?? 0);
            $interview_difficulty_score = (int) ($analysis['interview_difficulty'] ?? 0);
            $cv_change_score = (int) ($analysis['cv_change_intensity'] ?? 0);
            $role_specificity_score = (int) ($analysis['role_specificity'] ?? 0);
            $keyword_target = (int) ($analysis['keyword_target'] ?? 0);
            $keyword_covered = (int) ($analysis['keyword_covered'] ?? 0);
            $keyword_shortfall = max(0, $keyword_target - $keyword_covered);
            $best_backgrounds = array_slice((array) ($analysis['backgrounds'] ?? []), 0, 3);
            $best_skills = array_slice((array) ($analysis['top_skills'] ?? []), 0, 3);
            $best_qualifications = array_slice((array) ($analysis['qualifications'] ?? []), 0, 2);
            $title_badge = $this->get_crm_reddit_single_job_title_badge($item);
            $location_identifier_parts = array_values(array_filter(array_map('trim', explode(',', (string) ($item['location'] ?? '')))));
            $location_identifier = (string) ($location_identifier_parts[0] ?? trim((string) ($item['location'] ?? '')));
            $recruiter_label_text = $recruiter_public_firm_label !== ''
                ? $recruiter_public_firm_label
                : ($recruiter_firm !== '' ? $recruiter_firm : ($company_name !== '' ? $company_name : __('Search Firm', 'senna-finance')));
            $recruiter_contact_name = ($recruiter_name !== '' && !$this->is_crm_reddit_placeholder_recruiter_value($recruiter_name))
                ? $this->format_crm_reddit_recruiter_short_name($recruiter_name)
                : __('Hiring Team', 'senna-finance');
            $recruiter_contact_role_label = $this->get_crm_reddit_recruiter_role_short_label($recruiter_title);
            $recruiter_contact_cta = sprintf(
                /* translators: %s: recruiter short name */
                __('Contact %s', 'senna-finance'),
                $recruiter_contact_name
            );
            $recruiter_contact_initial = $recruiter_contact_name !== ''
                ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_contact_name, 0, 1) : substr($recruiter_contact_name, 0, 1))
                : 'R';
            $upgrade_capture_seed = [
                'role_title' => (string) ($item['role_title'] ?? ''),
                'company_name' => $company_name,
                'recruiter_name' => $recruiter_name !== '' ? $recruiter_name : $recruiter_contact_name,
                'recruiter_photo' => (string) ($item['recruiter_photo'] ?? ''),
                'recruiter_email_masked' => $this->mask_recruiter_email_for_display((string) ($item['recruiter_email'] ?? '')),
            ];
            $recruiter_upgrade_capture_attrs = $this->get_crm_reddit_upgrade_capture_attr_string(
                $this->get_crm_reddit_upgrade_capture_context('recruiter_contact', $upgrade_capture_seed + ['source' => 'single_job_recruiter_contact'])
            );
            $cv_report_upgrade_capture_attrs = $this->get_crm_reddit_upgrade_capture_attr_string(
                $this->get_crm_reddit_upgrade_capture_context('cv_report', $upgrade_capture_seed + ['source' => 'single_job_cv_report'])
            );

            $recruiter_access_label = $recruiter_access_score >= 78
                ? __('Open recruiter route', 'senna-finance')
                : ($recruiter_access_score >= 56 ? __('Some contact signal', 'senna-finance') : __('Limited contact signal', 'senna-finance'));
            $interview_difficulty_label = $interview_difficulty_score >= 78
                ? __('High competition', 'senna-finance')
                : ($interview_difficulty_score >= 58 ? __('Moderate competition', 'senna-finance') : __('More accessible', 'senna-finance'));
            $cv_change_label = $cv_change_score >= 78
                ? __('Significant CV changes', 'senna-finance')
                : ($cv_change_score >= 58 ? __('Targeted CV changes', 'senna-finance') : __('Light CV changes', 'senna-finance'));
            $role_specificity_label = $role_specificity_score >= 76
                ? __('Tight brief', 'senna-finance')
                : ($role_specificity_score >= 58 ? __('Defined brief', 'senna-finance') : __('Broad brief', 'senna-finance'));
            $contact_route_note = !empty($item['recruiter_email'])
                ? __('Email visible', 'senna-finance')
                : (!empty($item['recruiter_linkedin']) ? __('LinkedIn route visible', 'senna-finance') : __('Apply then follow up', 'senna-finance'));
            foreach ($recommendations as &$recommendation_item) {
                $recommendation_item['recruiter_name'] = $this->get_crm_reddit_public_recruiter_name((string) ($recommendation_item['recruiter_name'] ?? ''), $has_material_access);
                $recommendation_item['recruiter_short_name'] = $recommendation_item['recruiter_name'];
            }
            unset($recommendation_item);

            $item['recruiter_name'] = $recruiter_display_name;
            $item['recruiter_short_name'] = $recruiter_display_name;

            $recruiter_card_context = [
                'recruiter_photo' => (string) ($item['recruiter_photo'] ?? ''),
                'recruiter_display_name' => $recruiter_display_name,
                'recruiter_title' => $recruiter_title,
                'recruiter_firm_profile_display' => $recruiter_firm_profile_display,
                'recruiter_label_text' => $recruiter_label_text,
                'recruiter_view_jobs_url' => $recruiter_view_jobs_url,
                'recruiter_message_url' => $recruiter_message_url,
                'recruiter_message_disabled' => $recruiter_message_disabled,
                'recruiter_linkedin_url' => $recruiter_linkedin_url,
                'recruiter_linkedin_disabled' => $recruiter_linkedin_disabled,
