        private function render_crm_reddit_single_job_simple_layout(array $item, $title = '')
        {
            $company_name = trim((string) ($item['company'] ?? ''));
            $role_title = trim((string) ($item['role_title'] ?? __('Finance Role', 'senna-finance')));
            $description_html = (string) ($item['description_html'] ?? '');
            $opportunity_notice = $this->get_crm_reddit_opportunity_notice($item);
            $location = trim((string) ($item['location'] ?? ''));
            $seniority = trim((string) ($item['seniority'] ?? ''));
            $employment_type = trim((string) ($item['employment_type'] ?? ''));
            $summary_title_parts = array_values(array_filter([$company_name, $location]));
            $summary_heading = sprintf(
                /* translators: %s: job role and company/location */
                __('What to Expect - %s', 'senna-finance'),
                $role_title . (!empty($summary_title_parts) ? ' (' . implode(', ', $summary_title_parts) . ')' : '')
            );
            $eyebrow = trim((string) $title) !== '' ? (string) $title : __('Top Opportunity', 'senna-finance');
            $chip_values = array_values(array_filter([$location, $seniority, $employment_type]));

            if ($description_html === '' && !empty($item['excerpt'])) {
                $description_html = wpautop(esc_html((string) $item['excerpt']));
            }

            ob_start();
            ?>
            <article class="sffc-crm-reddit-simple-job">
                <header class="sffc-crm-reddit-simple-job__header">
                    <div class="sffc-crm-reddit-simple-job__brand-row">
                        <span class="sffc-crm-reddit-simple-job__brandmark" aria-label="<?php esc_attr_e('MENA Careers', 'senna-finance'); ?>">
                            <span class="sffc-crm-reddit-simple-job__branddot" aria-hidden="true"></span>
                            <span class="sffc-crm-reddit-simple-job__brandtext">MENA CAREERS</span>
                        </span>
                        <span class="sffc-crm-reddit-simple-job__eyebrow"><?php echo esc_html($eyebrow); ?></span>
