        private function get_crm_reddit_single_job_description_text(array $item)
        {
            $post_id = (int) ($item['post_id'] ?? 0);
            $job_description = $post_id > 0 ? trim((string) get_post_meta($post_id, 'jobDescription', true)) : '';
            if ($job_description === '' && $post_id > 0) {
                $job_description = trim((string) get_post_meta($post_id, 'sffc_job_description', true));
            }

            if ($job_description !== '') {
                return trim(wp_strip_all_tags($job_description));
            }

            return trim(wp_strip_all_tags((string) ($item['description_html'] ?? '')));
        }

        private function extract_crm_reddit_single_job_terms($text, array $catalog, $limit = 4)
        {
            $text = trim((string) $text);
            if ($text === '') {
                return [];
            }

            $haystack = function_exists('mb_strtolower') ? mb_strtolower($text) : strtolower($text);
            $matches = [];

            foreach ($catalog as $needle => $label) {
                $normalized_needle = function_exists('mb_strtolower') ? mb_strtolower((string) $needle) : strtolower((string) $needle);
                if ($normalized_needle !== '' && strpos($haystack, $normalized_needle) !== false) {
                    $matches[] = (string) $label;
                }

                if (count($matches) >= $limit) {
                    break;
                }
            }

            return array_values(array_unique($matches));
        }

        private function clamp_crm_reddit_single_job_metric($value, $min = 0, $max = 100)
        {
            return max((int) $min, min((int) $max, (int) round((float) $value)));
        }

        private function build_crm_reddit_single_job_bars($score)
        {
            $score = $this->clamp_crm_reddit_single_job_metric($score);
            $bars = [
                max(18, $score - 30),
                max(24, $score - 14),
                max(36, min(100, $score - 2)),
                max(46, min(100, $score + 8)),
            ];

            return array_map(function ($bar) {
                return $this->clamp_crm_reddit_single_job_metric($bar, 14, 100);
            }, $bars);
        }

        private function get_crm_reddit_single_job_years_requirement($text, $seniority)
        {
            $text = (string) $text;
            if (preg_match('/(\d+)\s*-\s*(\d+)\s+years?/i', $text, $matches)) {
                return $matches[1] . '-' . $matches[2] . ' ' . __('Years', 'senna-finance');
            }

            if (preg_match('/(\d+)\+?\s+years?/i', $text, $matches)) {
                return $matches[1] . '+ ' . __('Years', 'senna-finance');
            }

            $seniority = function_exists('mb_strtolower') ? mb_strtolower((string) $seniority) : strtolower((string) $seniority);
            if (strpos($seniority, 'intern') !== false || strpos($seniority, 'analyst') !== false || strpos($seniority, 'graduate') !== false) {
                return __('1-2 Years', 'senna-finance');
            }

            if (strpos($seniority, 'associate') !== false) {
                return __('3-5 Years', 'senna-finance');
            }

            return __('2-4 Years', 'senna-finance');
        }

