        private function get_crm_reddit_single_job_recommendations(array $item, $limit = 8)
        {
            $limit = max(1, min(12, (int) $limit));
            $exclude_ids = [];
            if (!empty($item['crm_post_id'])) {
                $exclude_ids[] = (int) $item['crm_post_id'];
            }

            $posts = (array) $this->get_crm_reddit_feed_posts_batch(36, get_current_user_id(), '', '', $exclude_ids);
            if (empty($posts)) {
                return [];
            }

            $recommendations = [];
            foreach ($posts as $post) {
                $candidate = $this->build_crm_reddit_crm_item($post);
                $raw_score = $this->calculate_crm_reddit_single_job_match_score($item, $candidate, $post);
                if ($raw_score <= 0) {
                    continue;
                }
                $candidate['raw_match_score'] = $raw_score;
                $recommendations[] = $candidate;
            }

            if (empty($recommendations)) {
                return [];
            }

            usort($recommendations, static function ($a, $b) {
                $score_compare = (float) ($b['raw_match_score'] ?? 0) <=> (float) ($a['raw_match_score'] ?? 0);
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return (int) ($b['posted_timestamp'] ?? 0) <=> (int) ($a['posted_timestamp'] ?? 0);
            });

            $top_score = max(1.0, (float) ($recommendations[0]['raw_match_score'] ?? 1));
            foreach ($recommendations as &$recommendation) {
                $normalized = (int) round(((float) ($recommendation['raw_match_score'] ?? 0) / $top_score) * 100);
                $normalized = max(42, min(100, $normalized));
                $recommendation['match_percent'] = $normalized;
                $recommendation['recruiter_short_name'] = $this->format_crm_reddit_recruiter_short_name((string) ($recommendation['recruiter_name'] ?? ''));
                $recommendation['match_label'] = $normalized >= 92
                    ? __('Strongest match', 'senna-finance')
                    : ($normalized >= 74 ? __('High match', 'senna-finance') : __('Relevant match', 'senna-finance'));
            }
            unset($recommendation);

            return array_slice($recommendations, 0, $limit);
        }

        private function calculate_crm_reddit_single_job_match_score(array $source_item, array $candidate_item, array $candidate_post = [])
        {
            $source_title_tokens = $this->tokenize_crm_reddit_match_text((string) ($source_item['role_title'] ?? ''));
            $candidate_title_tokens = $this->tokenize_crm_reddit_match_text((string) ($candidate_item['role_title'] ?? ''));
            $source_context_tokens = $this->tokenize_crm_reddit_match_text(
                trim(
                    (string) ($source_item['role_title'] ?? '') . ' ' .
                        (string) ($source_item['excerpt'] ?? '') . ' ' .
                        (string) ($source_item['group_name'] ?? '') . ' ' .
                        (string) ($source_item['seniority'] ?? '')
                )
            );
            $candidate_context_tokens = $this->tokenize_crm_reddit_match_text(
                trim(
                    (string) ($candidate_item['role_title'] ?? '') . ' ' .
                        (string) ($candidate_item['excerpt'] ?? '') . ' ' .
                        (string) ($candidate_item['group_name'] ?? '') . ' ' .
                        (string) ($candidate_item['seniority'] ?? '') . ' ' .
                        (string) ($candidate_post['keywords'] ?? '')
                )
            );

            $title_similarity = $this->calculate_crm_reddit_token_similarity($source_title_tokens, $candidate_title_tokens);
            $context_similarity = $this->calculate_crm_reddit_token_similarity($source_context_tokens, $candidate_context_tokens);

            $score = ($title_similarity * 72) + ($context_similarity * 18);

            $source_seniority = trim((string) ($source_item['seniority'] ?? ''));
            $candidate_seniority = trim((string) ($candidate_item['seniority'] ?? ''));
            if ($source_seniority !== '' && $candidate_seniority !== '') {
                if (strcasecmp($source_seniority, $candidate_seniority) === 0) {
                    $score += 8;
                } elseif (
                    stripos($candidate_seniority, $source_seniority) !== false ||
                    stripos($source_seniority, $candidate_seniority) !== false
                ) {
                    $score += 4;
                }
            }

            $source_group = sanitize_title((string) ($source_item['group_slug'] ?? ''));
            $candidate_group = sanitize_title((string) ($candidate_item['group_slug'] ?? ''));
            if ($source_group !== '' && $candidate_group !== '' && $source_group === $candidate_group) {
                $score += 5;
            }

            $source_location = function_exists('mb_strtolower') ? mb_strtolower((string) ($source_item['location'] ?? '')) : strtolower((string) ($source_item['location'] ?? ''));
            $candidate_location = function_exists('mb_strtolower') ? mb_strtolower((string) ($candidate_item['location'] ?? '')) : strtolower((string) ($candidate_item['location'] ?? ''));
            if ($source_location !== '' && $candidate_location !== '') {
                if ($source_location === $candidate_location) {
                    $score += 6;
                } elseif (strpos($source_location, $candidate_location) !== false || strpos($candidate_location, $source_location) !== false) {
                    $score += 3;
                }
            }

            $posted_timestamp = (int) ($candidate_item['posted_timestamp'] ?? 0);
            if ($posted_timestamp > 0) {
                $age = max(0, current_time('timestamp') - $posted_timestamp);
                if ($age <= DAY_IN_SECONDS) {
                    $score += 5;
                } elseif ($age <= (7 * DAY_IN_SECONDS)) {
                    $score += 3;
                } elseif ($age <= (21 * DAY_IN_SECONDS)) {
                    $score += 1;
                }
            }

            return round(max(0, min(100, $score)), 2);
        }

        private function tokenize_crm_reddit_match_text($text)
        {
            $text = trim((string) $text);
            if ($text === '') {
                return [];
            }

            $text = function_exists('mb_strtolower') ? mb_strtolower($text) : strtolower($text);
            $text = preg_replace('/[^a-z0-9\s]+/i', ' ', $text);
            $parts = preg_split('/\s+/', (string) $text) ?: [];
            $stop_words = [
                'and',
                'the',
                'for',
                'with',
                'role',
                'this',
                'that',
                'from',
                'into',
                'your',
                'will',
                'team',
                'jobs',
                'job',
                'our',
                'you',
                'have',
                'has',
                'their',
                'about',
                'within',
                'across',
                'more',
                'than',
                'into',
                'all',
                'are',
                'new',
                'top',
                'good',
                'great',
                'best',
                'real',
                'full'
            ];

            $tokens = [];
            foreach ($parts as $part) {
                $part = trim((string) $part);
                if ($part === '' || strlen($part) < 3 || in_array($part, $stop_words, true)) {
                    continue;
                }
                $tokens[] = $part;
            }

            return array_values(array_unique($tokens));
        }

        private function calculate_crm_reddit_token_similarity(array $source_tokens, array $candidate_tokens)
        {
            if (empty($source_tokens) || empty($candidate_tokens)) {
                return 0;
            }

            $overlap = array_intersect($source_tokens, $candidate_tokens);
            $union = array_unique(array_merge($source_tokens, $candidate_tokens));
            if (empty($union)) {
                return 0;
            }

            return count($overlap) / count($union);
        }

        private function format_crm_reddit_recruiter_short_name($name)
        {
            $name = trim((string) $name);
            if ($name === '') {
                return __('Recruiter', 'senna-finance');
            }

            $parts = preg_split('/\s+/', $name) ?: [];
            $first_name = trim((string) ($parts[0] ?? 'Recruiter'));
            $last_name = trim((string) ($parts[count($parts) - 1] ?? ''));
            if (count($parts) <= 1 || $last_name === '' || strcasecmp($first_name, $last_name) === 0) {
                return $first_name;
            }

            $initial = function_exists('mb_substr') ? mb_substr($last_name, 0, 1) : substr($last_name, 0, 1);
            $initial = function_exists('mb_strtoupper') ? mb_strtoupper((string) $initial) : strtoupper((string) $initial);

            return trim($first_name . ' ' . $initial . '.');
        }

        private function get_crm_reddit_public_recruiter_name($name, $has_full_access = false)
        {
            $name = trim((string) $name);
            if ($name === '') {
                return __('Recruiter', 'senna-finance');
            }

            if ($this->is_crm_reddit_placeholder_recruiter_value($name)) {
                return __('Hiring Team', 'senna-finance');
            }

            if (preg_match('/^(recruiter|recruiter contact|talent contact|hiring team|hiring manager|recruitment team|search firm)$/i', $name)) {
                return $name;
            }

            if ($has_full_access) {
                return $name;
            }

            return $this->format_crm_reddit_recruiter_short_name($name);
        }

        private function get_crm_reddit_recruiter_role_short_label($title)
        {
            return __('Recruiter', 'senna-finance');
        }

        private function is_crm_reddit_placeholder_recruiter_value($value)
        {
            $value = strtolower(trim((string) $value));
            if ($value === '') {
                return false;
            }

            return (bool) preg_match('/^(editorial|editorial desk|senna careers|senna editorial|content desk|content team)$/i', $value);
        }

