        private function enqueue_signup_form_assets($redirect_url = '')
        {
            wp_enqueue_style(
                'sffc-signup-form',
                SFFC_PLUGIN_URL . 'assets/css/crm/signup-form.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-signup-form-js',
                SFFC_PLUGIN_URL . 'assets/js/crm/signup-form.js',
                ['jquery'],
                SFFC_VERSION,
                true
            );

            wp_localize_script('sffc-signup-form-js', 'sffcSignupFormConfig', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
