        private function render_crm_reddit_single_networking_modal(array $item)
        {
            $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
            $recruiter_title = trim((string) ($item['recruiter_title'] ?? ''));
            $recruiter_firm = trim((string) ($item['recruiter_firm'] ?? ''));
            $company_name = trim((string) ($item['company'] ?? ''));
            $location = trim((string) ($item['location'] ?? ''));
            $seniority = trim((string) ($item['seniority'] ?? ''));
            $recruiter_linkedin = trim((string) ($item['recruiter_linkedin'] ?? ''));
            $recruiter_email = sanitize_email((string) ($item['recruiter_email'] ?? ''));
            $recruiter_phone = trim((string) ($item['recruiter_phone'] ?? ''));
            $recruiter_phone_digits = preg_replace('/[^0-9+]/', '', $recruiter_phone);
            $has_networking_access = $this->current_user_has_crm_reddit_premium_access();
            $membership_url = $this->get_canonical_membership_url();
            $locked_recruiter_label = __('Recruiter contact', 'senna-finance');
            $primary_channel_label = $recruiter_email !== ''
                ? __('Direct email first', 'senna-finance')
                : ($recruiter_linkedin !== '' ? __('LinkedIn message first', 'senna-finance') : __('Apply, then follow up', 'senna-finance'));
            $lead_signal_label = $company_name !== ''
                ? sprintf(__('Lead with why %s is a fit for your background', 'senna-finance'), $company_name)
                : __('Lead with your clearest role-fit signal', 'senna-finance');
            $follow_up_label = $location !== ''
                ? sprintf(__('Use a tight note tied to the %s market and this brief', 'senna-finance'), $location)
                : __('Use a short note tied directly to the live brief', 'senna-finance');
            $networking_upgrade_capture_attrs = $this->get_crm_reddit_upgrade_capture_attr_string(
                $this->get_crm_reddit_upgrade_capture_context('networking', [
                    'role_title' => (string) ($item['role_title'] ?? ''),
                    'company_name' => $company_name,
                    'recruiter_name' => $recruiter_name,
                    'recruiter_photo' => (string) ($item['recruiter_photo'] ?? ''),
                    'recruiter_email_masked' => $this->mask_recruiter_email_for_display($recruiter_email),
                    'source' => 'networking_modal',
                ])
            );
            ob_start();
        ?>
