        private function get_crm_reddit_application_pack_resources(array $item)
        {
            $company = trim((string) ($item['company'] ?? ''));
            $company_prefix = $company !== '' ? $company . ' ' : '';
            $resources = [
                [
                    'label' => $company_prefix . __('CV Template', 'senna-finance'),
                    'material_type' => 'cv_template',
                    'price' => __('Specific to Role', 'senna-finance'),
                    'meta' => __('Role-aligned CV rewrite built around the firm, team, and hiring brief.', 'senna-finance'),
                    'details' => __('Includes stronger finance positioning, sharper achievement bullets, recruiter-ready formatting, and keyword alignment for this opportunity.', 'senna-finance'),
                    'type' => 'DOCX',
                    'kind' => 'word',
                    'is_highlighted' => false,
                ],
                [
                    'label' => $company_prefix . __('Cover Letter', 'senna-finance'),
                    'material_type' => 'cover_letter',
                    'price' => __('Tailored to Skills', 'senna-finance'),
                    'meta' => __('A targeted letter framework shaped around your background and the mandate.', 'senna-finance'),
                    'details' => __('Includes motivation framing, relevant deal or transaction exposure, role fit messaging, and a polished structure you can adapt quickly.', 'senna-finance'),
                    'type' => 'DOCX',
                    'kind' => 'word',
                    'is_highlighted' => false,
                ],
                [
                    'label' => $company_prefix . __('Interview Questions', 'senna-finance'),
                    'material_type' => 'interview_questions',
                    'price' => __('Based on Past Questions', 'senna-finance'),
                    'meta' => __('Likely technical, market, and fit questions tailored to the role.', 'senna-finance'),
                    'details' => __('Includes likely interviewer prompts, answer angles, preparation themes, and role-specific talking points matched to the firm and level.', 'senna-finance'),
                    'type' => 'PDF',
                    'kind' => 'pdf',
                    'is_highlighted' => false,
                ],
                [
                    'label' => $company_prefix . __('Hiring Guide', 'senna-finance'),
                    'material_type' => 'hiring_guide',
                    'price' => __('What to Expect', 'senna-finance'),
                    'meta' => __('Practice materials for investment judgement, modelling, and case discussion.', 'senna-finance'),
                    'details' => __('Includes sample case prompts, what interviewers usually assess, and a clear response structure for more confident delivery.', 'senna-finance'),
                    'type' => 'PDF',
                    'kind' => 'pdf',
                    'is_highlighted' => true,
                ],
            ];

            return array_merge($resources, $this->get_crm_reddit_extra_material_resources($item));
        }

        private function get_crm_reddit_custom_application_pack_resources(array $context = [])
        {
            $material_types = ['cv_template', 'cover_letter', 'interview_questions', 'hiring_guide'];
            $resources = [];

            foreach ($material_types as $material_type) {
                $config = $this->get_crm_reddit_material_type_config($material_type, [
                    'company' => (string) ($context['company'] ?? ''),
                ]);
                if (empty($config)) {
                    continue;
                }

                $resources[] = [
                    'material_type' => $material_type,
                    'label' => (string) ($config['label'] ?? ''),
                    'meta' => (string) ($config['headline'] ?? ''),
                    'price' => __('Included', 'senna-finance'),
                    'type' => in_array($material_type, ['interview_questions', 'hiring_guide'], true) ? 'PDF' : 'DOCX',
                    'kind' => in_array($material_type, ['interview_questions', 'hiring_guide'], true) ? 'pdf' : 'word',
                    'is_highlighted' => $material_type === 'cv_template',
                ];
            }

            return $resources;
        }

        private function get_crm_reddit_requested_material_types($raw_value)
        {
            if (is_string($raw_value)) {
                $decoded = json_decode(wp_unslash($raw_value), true);
                $raw_value = is_array($decoded) ? $decoded : preg_split('/[\s,|]+/', (string) $raw_value);
            }

            if (!is_array($raw_value)) {
                return [];
            }

            return array_values(array_filter(array_map(static function ($value) {
                return sanitize_key((string) $value);
            }, $raw_value)));
        }

        private function get_crm_reddit_extra_material_resources(array $item)
        {
            $materials = $item['materials'] ?? [];
            if (is_string($materials)) {
                $decoded = json_decode($materials, true);
                $materials = is_array($decoded) ? $decoded : [];
            }

            if (!is_array($materials) || empty($materials)) {
                return [];
            }

            $resources = [];
            foreach (array_values($materials) as $index => $material) {
                if (!is_array($material)) {
                    continue;
                }

                $label = trim((string) ($material['label'] ?? ''));
                $url = esc_url_raw((string) ($material['url'] ?? ''));
                $description = trim((string) ($material['description'] ?? ''));
                $file_type = strtoupper(trim((string) ($material['file_type'] ?? '')));

                if ($label === '' || $url === '') {
                    continue;
                }

                if ($file_type === '') {
                    $path = wp_parse_url($url, PHP_URL_PATH);
                    $extension = $path ? strtolower(pathinfo((string) $path, PATHINFO_EXTENSION)) : '';
                    $file_type = $extension !== '' ? strtoupper($extension) : 'LINK';
                }

                $kind = in_array(strtolower($file_type), ['doc', 'docx'], true) ? 'word' : 'pdf';
                $resources[] = [
                    'label' => $label,
                    'material_type' => 'extra_document_' . ($index + 1),
                    'price' => __('Provided with role', 'senna-finance'),
                    'meta' => $description !== '' ? $description : __('Additional role document supplied with this opportunity.', 'senna-finance'),
                    'details' => $description !== '' ? $description : __('Additional role document supplied with this opportunity.', 'senna-finance'),
                    'type' => $file_type,
                    'kind' => $kind,
                    'direct_url' => $url,
                    'is_highlighted' => false,
                    'is_custom_document' => true,
                ];
            }

            return $resources;
        }

