        private function render_crm_reddit_story_role_item(array $item, $is_logged_in)
        {
            $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
            $recruiter_initial = $recruiter_name !== ''
                ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1))
                : 'R';
            $apply_url = !empty($item['apply_url']) ? (string) $item['apply_url'] : (string) ($item['view_url'] ?? '');
            $message_url = (string) ($item['message_url'] ?? '');
            $chips = [];

            foreach (['location', 'salary_text', 'seniority', 'employment_type'] as $chip_key) {
                $chip_value = trim((string) ($item[$chip_key] ?? ''));
                if ($chip_value !== '') {
                    $chips[] = $chip_value;
                }
            }

            $chips = array_slice(array_values(array_unique($chips)), 0, 3);

            ob_start();
        ?>
            <article class="sffc-crm-reddit-role-item">
                <div class="sffc-crm-reddit-role-item-main">
                    <div class="sffc-crm-reddit-role-item-avatar">
                        <?php if (!empty($item['recruiter_photo'])) : ?>
                            <img src="<?php echo esc_url((string) $item['recruiter_photo']); ?>" alt="<?php echo esc_attr($recruiter_name); ?>">
                        <?php else : ?>
                            <span><?php echo esc_html($recruiter_initial); ?></span>
                        <?php endif; ?>
                    </div>
                    <div class="sffc-crm-reddit-role-item-copy">
                        <h3><a href="<?php echo esc_url((string) ($item['view_url'] ?? '')); ?>"><?php echo esc_html((string) ($item['role_title'] ?? '')); ?></a></h3>
                        <p>
                            <strong><?php echo esc_html($recruiter_name !== '' ? $recruiter_name : __('Hiring Team', 'senna-finance')); ?></strong>
                            <?php if (!empty($item['recruiter_firm'])) : ?>
                                <span><?php echo esc_html((string) $item['recruiter_firm']); ?></span>
                            <?php endif; ?>
                        </p>
                        <?php if (!empty($chips)) : ?>
                            <div class="sffc-crm-reddit-role-item-chips">
                                <?php foreach ($chips as $chip) : ?>
                                    <span class="sffc-crm-reddit-role-item-chip"><?php echo esc_html($chip); ?></span>
                                <?php endforeach; ?>
                            </div>
                        <?php endif; ?>
                    </div>
                </div>

                <div class="sffc-crm-reddit-role-item-actions">
                    <a class="sffc-crm-reddit-role-link" href="<?php echo esc_url((string) ($item['view_url'] ?? '')); ?>"><?php esc_html_e('View', 'senna-finance'); ?></a>
                    <?php if ($message_url !== '') : ?>
                        <a class="sffc-crm-reddit-role-link" href="<?php echo esc_url($message_url); ?>" <?php echo strpos($message_url, 'mailto:') === 0 ? '' : ' target="_blank" rel="noopener noreferrer"'; ?>>
                            <?php echo esc_html($is_logged_in ? __('Message', 'senna-finance') : __('Contact', 'senna-finance')); ?>
                        </a>
                    <?php endif; ?>
                    <?php if ($apply_url !== '') : ?>
                        <a class="sffc-crm-reddit-role-link sffc-crm-reddit-role-link--primary" href="<?php echo esc_url($apply_url); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e('Apply', 'senna-finance'); ?></a>
                    <?php endif; ?>
                </div>
            </article>
        <?php
            return ob_get_clean();
        }

