                return $this->render_login_prompt();
            }

            $recruiter_model = new SFFC_CRM_Recruiter();
            $user_id = get_current_user_id();
            $recruiters = $recruiter_model->get_saved_recruiters($user_id);
            $stats = $recruiter_model->get_user_stats($user_id);
            $intro_requests = $this->get_intro_requests_for_user($user_id);

            ob_start();
        ?>
            <div class="sffc-crm-container">
                <div class="sffc-crm-recruiters-header">
                    <h2>My Recruiters</h2>
                    <div class="sffc-crm-stats-inline">
                        <span class="sffc-crm-stat"><strong><?php echo esc_html($stats['total']); ?></strong> Total</span>
                        <span class="sffc-crm-stat"><strong><?php echo esc_html($stats['replied']); ?></strong> Replied</span>
                        <span class="sffc-crm-stat"><strong><?php echo esc_html($stats['in_conversation']); ?></strong> In Conversation</span>
