                </div>

                <div class="sffc-crm-recruiters-list" id="crm-recruiters-list">
                    <?php if (empty($recruiters)): ?>
                        <div class="sffc-crm-empty">
                            <h3>No recruiters saved yet</h3>
                            <p>Save recruiters from the Recent Posts tab to track your relationships.</p>
                        </div>
                    <?php else: ?>
                        <?php foreach ($recruiters as $recruiter): ?>
                            <?php echo $this->render_recruiter_row($recruiter); ?>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </div>

                <div class="sffc-crm-intros" id="crm-intros-list">
                    <div class="sffc-crm-recruiters-header">
                        <h2><?php esc_html_e('Applied Roles', 'senna-finance'); ?></h2>
                        <div class="sffc-crm-stats-inline">
                            <span class="sffc-crm-stat"><strong><?php echo esc_html(count($intro_requests)); ?></strong> <?php esc_html_e('Queued', 'senna-finance'); ?></span>
                        </div>
                    </div>

                    <?php if (empty($intro_requests)): ?>
                        <div class="sffc-crm-empty">
                            <h3><?php esc_html_e('No applications yet', 'senna-finance'); ?></h3>
                            <p><?php esc_html_e('Express interest in roles from the CRM to track your applications here.', 'senna-finance'); ?></p>
                        </div>
                    <?php else: ?>
                        <div class="sffc-company-prep-grid">
                            <?php foreach ($intro_requests as $intro_request): ?>
                                <?php echo $this->render_intro_card($intro_request); ?>
                            <?php endforeach; ?>
