                <div class="sffc-crm-recruiter-avatar">
                    <?php if (!empty($recruiter['photo_url'])): ?>
                        <img src="<?php echo esc_url($recruiter['photo_url']); ?>" alt="">
                    <?php else: ?>
                        <div class="sffc-crm-avatar-placeholder">
                            <?php echo esc_html(substr($recruiter['name'], 0, 1)); ?>
                        </div>
                    <?php endif; ?>
                </div>
                <div class="sffc-crm-recruiter-details">
                    <span class="sffc-crm-recruiter-name"><?php echo esc_html($recruiter['name']); ?></span>
                    <span class="sffc-crm-recruiter-firm"><?php echo esc_html($recruiter['firm'] ?? ''); ?></span>
                </div>
                <div class="sffc-crm-recruiter-status">
                    <span class="sffc-crm-status-badge" style="background: <?php echo $status_color; ?>;">
                        <?php echo esc_html(ucwords(str_replace('_', ' ', $recruiter['status']))); ?>
                    </span>
                </div>
                <div class="sffc-crm-recruiter-last">
                    <?php if ($recruiter['last_contacted_at']): ?>
                        <span>Contacted <?php echo human_time_diff(strtotime($recruiter['last_contacted_at'])); ?> ago</span>
                    <?php else: ?>
                        <span>Saved <?php echo human_time_diff(strtotime($recruiter['saved_at'])); ?> ago</span>
                    <?php endif; ?>
                </div>
                <div class="sffc-crm-recruiter-actions">
