                </div>
            </div>
        <?php
            return ob_get_clean();
        }

        public function get_hr_contact_card_markup($contact)
        {
            if (empty($contact) || !is_array($contact)) {
                return '';
            }

            $existing_intro_request = null;
            if (is_user_logged_in()) {
                $user_intro_requests = $this->get_intro_requests_for_user(get_current_user_id());
                foreach ($user_intro_requests as $intro_request) {
                    if ((int) ($intro_request['recruiter_id'] ?? 0) === (int) ($contact['id'] ?? 0)) {
                        $existing_intro_request = $intro_request;
                        break;
                    }
                }
            }

