        /**
         * Render pipeline shortcode
         */
        public function render_pipeline($atts)
        {
            if (!is_user_logged_in()) {
                return $this->render_login_prompt();
            }

            $pipeline_model = new SFFC_CRM_Pipeline();
            $user_id = get_current_user_id();
            $kanban = $pipeline_model->get_pipeline_kanban($user_id);
            $stats = $pipeline_model->get_user_stats($user_id);

            ob_start();
        ?>
            <div class="sffc-crm-container">
                <div class="sffc-crm-pipeline-header">
                    <h2>My Pipeline</h2>
                    <div class="sffc-crm-stats-inline">
                        <span class="sffc-crm-stat"><strong><?php echo esc_html($stats['total']); ?></strong> Total</span>
                        <span class="sffc-crm-stat sffc-crm-stat-success"><strong><?php echo esc_html($stats['by_outcome']['won'] ?? 0); ?></strong> Won</span>
                    </div>
                </div>

                <div class="sffc-crm-pipeline-kanban" id="crm-pipeline-kanban">
                    <?php foreach ($kanban as $stage_key => $stage): ?>
                        <div class="sffc-crm-pipeline-column"
                            data-stage="<?php echo esc_attr($stage_key); ?>">
                            <div class="sffc-crm-pipeline-column-header" style="border-color: <?php echo esc_attr($stage['color']); ?>;">
                                <span class="sffc-crm-pipeline-stage-name"><?php echo esc_html($stage['label']); ?></span>
                                <span class="sffc-crm-pipeline-count"><?php echo esc_html(count($stage['items'])); ?></span>
                            </div>

                            <div class="sffc-crm-pipeline-items" data-stage="<?php echo esc_attr($stage_key); ?>">
                                <?php foreach ($stage['items'] as $item): ?>
                                    <?php echo $this->render_pipeline_card($item); ?>
                                <?php endforeach; ?>
                            </div>
                        </div>
                    <?php endforeach; ?>
                </div>
            </div>
        <?php
            return ob_get_clean();
        }

        /**
         * Render pipeline card
         */
        private function render_pipeline_card($item)
        {
            ob_start();
        ?>
            <div class="sffc-crm-pipeline-card" data-pipeline-id="<?php echo esc_attr($item['id']); ?>">
                <div class="sffc-crm-pipeline-card-title">
                    <?php echo esc_html($item['role_title'] ?: 'Opportunity'); ?>
                </div>
                <?php if (!empty($item['company'])): ?>
                    <div class="sffc-crm-pipeline-card-company">
                        <?php echo esc_html($item['company']); ?>
                    </div>
                <?php endif; ?>
                <div class="sffc-crm-pipeline-card-recruiter">
                    <?php echo esc_html($item['recruiter_name'] ?? 'Unknown'); ?>
                </div>
                <?php if (!empty($item['next_action_date'])): ?>
                    <div class="sffc-crm-pipeline-card-action">
                        <?php echo esc_html(date('M j', strtotime($item['next_action_date']))); ?>
                    </div>
                <?php endif; ?>
            </div>
        <?php
            return ob_get_clean();
        }

