        /**
         * Calculate match score for a post based on user preferences
         */
        private function calculate_match_score($post, $user_preferences)
        {
            $score = 0;
            $max_score = 0;

            // Sector match (30 points)
            $max_score += 30;
            if (
                !empty($user_preferences['target_sectors']) && !empty($post['sector']) &&
                in_array($post['sector'], $user_preferences['target_sectors'])
            ) {
                $score += 30;
            }

            // Seniority match (25 points)
            $max_score += 25;
            if (
                !empty($user_preferences['target_seniority']) && !empty($post['seniority']) &&
                in_array($post['seniority'], $user_preferences['target_seniority'])
            ) {
                $score += 25;
            }

            // Location match (20 points)
            $max_score += 20;
            if (!empty($user_preferences['target_locations']) && !empty($post['location'])) {
                foreach ($user_preferences['target_locations'] as $loc) {
                    if (stripos($post['location'], $loc) !== false) {
                        $score += 20;
                        break;
                    }
                }
            }

            // Work arrangement match (15 points)
            $max_score += 15;
            if (!empty($user_preferences['work_arrangement'])) {
                if ((in_array('remote', $user_preferences['work_arrangement']) && !empty($post['is_remote'])) ||
                    (in_array('hybrid', $user_preferences['work_arrangement']) && !empty($post['is_hybrid']))
                ) {
                    $score += 15;
                }
            }

            // Recency bonus (10 points)
            $max_score += 10;
            if (!empty($post['posted_at'])) {
                $posted_ts = strtotime($post['posted_at']);
                if ($posted_ts) {
                    $days_old = (time() - $posted_ts) / (24 * 60 * 60);
                    if ($days_old <= 7) {
                        $score += 10;
                    } elseif ($days_old <= 14) {
                        $score += 5;
                    }
                }
            }

            // Convert to percentage
            return $max_score > 0 ? round(($score / $max_score) * 100) : 0;
        }

        /**
         * Convert match score to likelihood badge data
         * Returns array with badge label and CSS class
         */
        private function get_match_likelihood($score)
        {
            $score = (int) $score;

            if ($score >= 90) {
                return [
                    'label' => __('Likely to Respond', 'senna-finance'),
                    'class' => 'highly-likely'
                ];
            } elseif ($score >= 85) {
                return [
                    'label' => __('Highly Recommended', 'senna-finance'),
                    'class' => 'highly-likely'
                ];
            } elseif ($score >= 80) {
                return [
                    'label' => __('Great Match', 'senna-finance'),
                    'class' => 'great-match'
                ];
            } elseif ($score >= 75) {
                return [
                    'label' => __('Fits Profile', 'senna-finance'),
                    'class' => 'good-chance'
                ];
            } elseif ($score >= 70) {
                return [
                    'label' => __('Recommended', 'senna-finance'),
                    'class' => 'good-chance'
                ];
            } elseif ($score >= 60) {
                return [
                    'label' => __('Review Match', 'senna-finance'),
                    'class' => 'worth-applying'
                ];
            } elseif ($score >= 50) {
                return [
                    'label' => __('Medium Match', 'senna-finance'),
                    'class' => 'worth-applying'
                ];
            } else {
                return [
                    'label' => __('Check Before', 'senna-finance'),
                    'class' => 'long-shot'
                ];
            }
        }

