        /**
         * Render CRM Post Article shortcode
         * Usage: [sffc_crm_post_article post_id="123"]
         *
         * Displays a CRM post with full gap analyzer functionality.
         * Works exactly like [sffc_recruiter_post_article] but pulls data from CRM database.
         */
        public function render_crm_post_article($atts)
        {
            $atts = shortcode_atts([
                'post_id' => '',
                'show_sidebar' => 'true',
            ], $atts);

            $post_id = $this->resolve_current_crm_post_id($atts['post_id'] ?? 0);

            if (!$post_id) {
                return '<!-- crm post article: no post id provided -->';
            }

            // Load the CRM post model
            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                } else {
                    return '<!-- crm post article: model not found -->';
                }
            }

            // Load template
            $template_file = plugin_dir_path(__FILE__) . '../../templates/crm-post-article.php';
            if (!file_exists($template_file)) {
                return '<!-- crm post article: template missing -->';
            }

            require_once $template_file;

            $show_sidebar = filter_var($atts['show_sidebar'], FILTER_VALIDATE_BOOLEAN);

            ob_start();
            sffc_render_crm_post_article([
                'post_id' => $post_id,
                'show_sidebar' => $show_sidebar,
                'user_has_access' => is_user_logged_in(),
            ]);
            return ob_get_clean();
        }

        public function render_crm_post_article_layout($atts = [])
        {
            return $this->render_crm_post_article_layout_variant($atts, false, 'default');
        }

        public function render_crm_linkedin_jobs_layout($atts = [])
        {
            $atts = shortcode_atts([
                'post_id' => '',
                'limit' => 25,
            ], $atts, 'sffc_crm_linkedin_jobs_layout');

            $post_id = $this->resolve_current_crm_post_id($atts['post_id'] ?? 0);

            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return '<!-- crm linkedin jobs layout: model not found -->';
            }

            $community_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                : SFFC_VERSION;
            $linkedin_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-linkedin-jobs-layout.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-linkedin-jobs-layout.css')
                : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-community-editorial',
                SFFC_PLUGIN_URL . 'assets/css/crm/community-editorial.css',
                [],
                $community_css_version
            );
            wp_enqueue_style(
                'sffc-crm-linkedin-jobs-layout',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-linkedin-jobs-layout.css',
                ['sffc-community-editorial'],
                $linkedin_css_version
            );

            $post_model = new SFFC_CRM_Post();
            $selected_post = $post_id > 0 ? $post_model->get_full_detail($post_id, get_current_user_id()) : null;
            if (empty($selected_post) || !is_array($selected_post)) {
                return '<!-- crm linkedin jobs layout: post not found -->';
            }
            if (!class_exists('SFFC_CRM_Post_Group')) {
                $group_model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post-group.php';
                if (file_exists($group_model_file)) {
                    require_once $group_model_file;
                }
            }

            $search = sanitize_text_field((string) ($_GET['sffc_job_search'] ?? ''));
            $location_filter = sanitize_text_field((string) ($_GET['sffc_job_location'] ?? ''));
            $date_filter = sanitize_key((string) ($_GET['sffc_job_date'] ?? ''));
            $experience_filter = sanitize_text_field((string) ($_GET['sffc_job_experience'] ?? ''));
            $company_filter = sanitize_text_field((string) ($_GET['sffc_job_company'] ?? ''));
            $work_filter = sanitize_key((string) ($_GET['sffc_job_work'] ?? ''));
            $sector_filter = sanitize_text_field((string) ($_GET['sffc_job_sector'] ?? ''));
            $tracker_filter = sanitize_text_field((string) ($_GET['sffc_job_tracker'] ?? ''));
            $match_filter = sanitize_key((string) ($_GET['sffc_job_match'] ?? ''));

            $feed_args = [
                'page' => 1,
                'per_page' => max(5, min(50, absint($atts['limit']))),
                'approved_only' => true,
                'post_status' => 'open',
                'orderby' => 'posted_at',
                'order' => 'DESC',
                'search' => $search !== '' ? $search : null,
                'location' => $location_filter !== '' ? $location_filter : null,
            ];
            if ($date_filter !== '') {
                $posted_after = $this->get_crm_linkedin_jobs_posted_after($date_filter);
                if ($posted_after !== '') {
                    $feed_args['posted_after'] = $posted_after;
                }
            }

            $feed_posts = $post_model->get_feed($feed_args);
            $tracker_context = [
                'id' => 0,
                'slug' => '',
                'name' => $search !== '' ? sprintf(__('%s roles', 'senna-finance'), $search) : __('Recommended roles', 'senna-finance'),
                'post_count' => 0,
            ];
            if (class_exists('SFFC_CRM_Post_Group')) {
                $group_model = new SFFC_CRM_Post_Group();
                $selected_groups = (array) $group_model->get_groups_for_post((int) $selected_post['id']);
                $selected_group = (array) ($selected_groups[0] ?? []);
                $selected_group_id = (int) ($selected_group['id'] ?? 0);
                if ($selected_group_id > 0) {
                    $tracker_context = [
                        'id' => $selected_group_id,
                        'slug' => sanitize_title((string) ($selected_group['slug'] ?? '')),
                        'name' => trim((string) ($selected_group['name'] ?? __('Recommended roles', 'senna-finance'))),
                        'post_count' => method_exists($group_model, 'count_posts_in_group')
                            ? (int) $group_model->count_posts_in_group($selected_group_id, ['is_active' => 1, 'admin_approved' => 1])
                            : (int) ($selected_group['post_count'] ?? 0),
                    ];
                    $group_posts = (array) $group_model->get_posts_by_group($selected_group_id, [
                        'limit' => max(5, min(50, absint($atts['limit']))),
                        'is_active' => 1,
                        'admin_approved' => 1,
                    ]);
                    if (!empty($group_posts)) {
                        $feed_posts = $group_posts;
                    }
                }
            }
            $posts_by_id = [];
            $posts_by_id[(int) $selected_post['id']] = $selected_post;
            foreach ((array) $feed_posts as $feed_post) {
                if (is_array($feed_post) && !empty($feed_post['id'])) {
                    $posts_by_id[(int) $feed_post['id']] = $feed_post;
                }
            }
            $feed_posts = array_values($posts_by_id);
            $tracker_context['post_count'] = max((int) ($tracker_context['post_count'] ?? 0), count($feed_posts));
            foreach ($feed_posts as $feed_index => $feed_post) {
                $feed_post_id = (int) ($feed_post['id'] ?? 0);
                if ($feed_post_id <= 0 || $feed_post_id === (int) $selected_post['id']) {
                    continue;
                }

                $full_feed_post = $post_model->get_full_detail($feed_post_id, get_current_user_id());
                if (is_array($full_feed_post) && !empty($full_feed_post['id'])) {
                    $feed_posts[$feed_index] = array_merge((array) $feed_post, $full_feed_post);
                }
            }
            $company_filter_options = [];
            $experience_filter_options = [
                '' => __('Role', 'senna-finance'),
            ];
            $sector_filter_options = [
                '' => __('Sector', 'senna-finance'),
            ];
            $work_filter_options = [
                '' => __('Remote', 'senna-finance'),
            ];
            $seen_experience_filter_values = [];
            $seen_sector_filter_values = [];
            $seen_work_filter_values = [];
            foreach ($feed_posts as $feed_post) {
                $feed_company_name = trim((string) ($feed_post['company'] ?? ''));
                if ($feed_company_name !== '') {
                    $company_filter_options[normalize_whitespace($feed_company_name)] = $feed_company_name;
                }

                $feed_experience = trim((string) ($feed_post['seniority'] ?? ''));
                if ($feed_experience !== '') {
                    $experience_key = $this->normalize_crm_linkedin_jobs_filter_token($feed_experience);
                    if ($experience_key !== '' && !isset($seen_experience_filter_values[$experience_key])) {
                        $seen_experience_filter_values[$experience_key] = true;
                        $experience_filter_options[$feed_experience] = $this->format_crm_linkedin_jobs_chip_label($feed_experience);
                    }
                }

                $feed_sector = trim((string) ($feed_post['sector'] ?? ''));
                if ($feed_sector !== '') {
                    $sector_key = $this->normalize_crm_linkedin_jobs_filter_token($feed_sector);
                    if ($sector_key !== '' && !isset($seen_sector_filter_values[$sector_key])) {
                        $seen_sector_filter_values[$sector_key] = true;
                        $sector_filter_options[$feed_sector] = $this->format_crm_linkedin_jobs_chip_label($feed_sector);
                    }
                }

                $feed_work_value = '';
                $feed_work_label = '';
                if (!empty($feed_post['is_remote'])) {
                    $feed_work_value = 'remote';
                    $feed_work_label = __('Remote', 'senna-finance');
                } elseif (!empty($feed_post['is_hybrid'])) {
                    $feed_work_value = 'hybrid';
                    $feed_work_label = __('Hybrid', 'senna-finance');
                } else {
                    $feed_work_value = 'onsite';
                    $feed_work_label = __('On-site', 'senna-finance');
                }
                if ($feed_work_value !== '' && !isset($seen_work_filter_values[$feed_work_value])) {
                    $seen_work_filter_values[$feed_work_value] = true;
                    $work_filter_options[$feed_work_value] = $feed_work_label;
                }
            }
            ksort($company_filter_options, SORT_NATURAL | SORT_FLAG_CASE);
            $all_experience_label = (string) ($experience_filter_options[''] ?? __('Role', 'senna-finance'));
            unset($experience_filter_options['']);
            uasort($experience_filter_options, static function ($left, $right) {
                return strcasecmp((string) $left, (string) $right);
            });
            $experience_filter_options = ['' => $all_experience_label] + $experience_filter_options;
            $all_sector_label = (string) ($sector_filter_options[''] ?? __('Sector', 'senna-finance'));
            unset($sector_filter_options['']);
            uasort($sector_filter_options, static function ($left, $right) {
                return strcasecmp((string) $left, (string) $right);
            });
            $sector_filter_options = ['' => $all_sector_label] + $sector_filter_options;
            $all_work_label = (string) ($work_filter_options[''] ?? __('Remote', 'senna-finance'));
            unset($work_filter_options['']);
            uasort($work_filter_options, static function ($left, $right) {
                return strcasecmp((string) $left, (string) $right);
            });
            $work_filter_options = ['' => $all_work_label] + $work_filter_options;

            $role_title = trim((string) ($selected_post['role_title'] ?? __('Untitled role', 'senna-finance')));
            $company_name = trim((string) ($selected_post['company'] ?? ''));
            $location = trim((string) ($selected_post['location'] ?? ''));
            $description_html = trim((string) ($selected_post['content'] ?? ''));
            if ($description_html === '') {
                $description_html = trim((string) ($selected_post['content_snippet'] ?? ''));
            }
            $application_url = trim((string) ($selected_post['application_url'] ?? ''));
            if ($application_url === '') {
                $application_url = trim((string) ($selected_post['source_url'] ?? ''));
            }
            $selected_url = $this->get_crm_post_article_layout_similar_post_url((array) $selected_post);
            $posted_label = $this->get_crm_linkedin_jobs_posted_label($selected_post);
            $meta_line = implode(' · ', array_filter([
                $location,
                $posted_label,
                trim((string) ($selected_post['source_platform'] ?? '')),
            ]));
            $company_logo = trim((string) ($selected_post['company_logo'] ?? ''));
            $company_initial = $company_name !== '' ? strtoupper(substr($company_name, 0, 1)) : 'S';
            $detail_chips = array_values(array_filter([
                !empty($selected_post['is_remote']) ? __('Remote', 'senna-finance') : (!empty($selected_post['is_hybrid']) ? __('Hybrid', 'senna-finance') : ''),
                trim((string) ($selected_post['duration'] ?? '')),
                trim((string) ($selected_post['seniority'] ?? '')),
                trim((string) ($selected_post['sector'] ?? '')),
            ]));
            $filter_base_args = [
                'crm_post_id' => (int) $selected_post['id'],
                'sffc_job_search' => $search,
                'sffc_job_location' => $location_filter,
                'sffc_job_date' => $date_filter,
                'sffc_job_experience' => $experience_filter,
                'sffc_job_company' => $company_filter,
                'sffc_job_work' => $work_filter,
                'sffc_job_sector' => $sector_filter,
                'sffc_job_tracker' => $tracker_filter,
                'sffc_job_match' => $match_filter,
            ];
            $tracker_filter_label = trim((string) ($tracker_context['name'] ?? ''));
            $tracker_filter_button_label = $tracker_filter_label !== ''
                ? sprintf(__('Tracker : %s', 'senna-finance'), $tracker_filter_label)
                : __('Trackers', 'senna-finance');
            $has_premium_access = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $current_user = wp_get_current_user();
            $join_prefill_name = $current_user instanceof WP_User && $current_user->exists() ? trim((string) $current_user->display_name) : '';
            $join_prefill_email = $current_user instanceof WP_User && $current_user->exists() ? sanitize_email((string) $current_user->user_email) : '';

