        private function get_crm_linkedin_jobs_posted_after($date_filter)
        {
            $seconds = 0;
            if ($date_filter === 'day') {
                $seconds = DAY_IN_SECONDS;
            } elseif ($date_filter === 'week') {
                $seconds = 7 * DAY_IN_SECONDS;
            } elseif ($date_filter === 'month') {
                $seconds = 30 * DAY_IN_SECONDS;
            }

            if ($seconds <= 0) {
                return '';
            }

            return wp_date('Y-m-d H:i:s', current_time('timestamp') - $seconds);
        }

        private function render_crm_linkedin_jobs_filter_select($name, $selected, array $options)
        {
            ob_start();
            ?>
            <select name="<?php echo esc_attr($name); ?>">
                <?php foreach ($options as $value => $label) : ?>
                    <option value="<?php echo esc_attr((string) $value); ?>" <?php selected((string) $selected, (string) $value); ?>><?php echo esc_html($label); ?></option>
                <?php endforeach; ?>
            </select>
            <?php
            return ob_get_clean();
        }

        private function render_crm_linkedin_jobs_filter_dropdown($name, $selected, $label, array $options, array $base_args, $show_search = false, $base_url = '')
        {
            $selected = (string) $selected;
            $button_label = (string) $label;
            if ($selected !== '') {
                $selected_token = $this->normalize_crm_linkedin_jobs_filter_token($selected);
                foreach ($options as $option_value => $option_label) {
                    if ((string) $option_value === $selected || $this->normalize_crm_linkedin_jobs_filter_token((string) $option_value) === $selected_token) {
                        $button_label = (string) $option_label;
                        break;
                    }
                }
            }
            $filter_key = str_replace('_', '-', sanitize_key($name));
            $base_url = (string) $base_url;
            if (!$base_url) {
                $base_url = get_permalink();
            }
