                    <span class="sffc-community-editorial__filter-plus" aria-hidden="true">+</span>
                    <span class="sffc-crm-linkedin-jobs__filter-current-label"><?php echo esc_html($button_label); ?></span>
                    <span class="sffc-community-editorial__filter-button-icon sffc-crm-linkedin-jobs__filter-button-icon" aria-hidden="true">
                        <svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
                    </span>
                </summary>
                <div class="sffc-community-editorial__filter-dropdown-panel sffc-crm-linkedin-jobs__filter-dropdown-panel">
                    <?php if ($show_search) : ?>
                        <label class="sffc-community-editorial__filter-search sffc-crm-linkedin-jobs__filter-search">
                            <span class="screen-reader-text"><?php echo esc_html(sprintf(__('Search %s options', 'senna-finance'), strtolower((string) $label))); ?></span>
                            <input type="search" placeholder="<?php echo esc_attr(sprintf(__('Search %s', 'senna-finance'), strtolower((string) $label))); ?>">
                        </label>
                    <?php endif; ?>
                    <?php foreach ($options as $value => $option_label) : ?>
                        <?php
                        $option_args = $base_args;
                        $option_args[$name] = (string) $value;
                        $option_args = array_filter($option_args, static function ($arg_value) {
                            return $arg_value !== '';
                        });
                        $is_active = $selected === (string) $value || (
                            $selected !== ''
                            && $this->normalize_crm_linkedin_jobs_filter_token($selected) === $this->normalize_crm_linkedin_jobs_filter_token((string) $value)
                        );
                        ?>
                        <a class="sffc-community-editorial__filter-option sffc-crm-linkedin-jobs__filter-option<?php echo $is_active ? ' is-active' : ''; ?>" href="<?php echo esc_url(add_query_arg($option_args, $base_url)); ?>" aria-current="<?php echo $is_active ? 'true' : 'false'; ?>" data-sffc-linkedin-jobs-filter-option data-sffc-linkedin-jobs-filter-name="<?php echo esc_attr((string) $name); ?>" data-sffc-linkedin-jobs-filter-value="<?php echo esc_attr((string) $value); ?>">
                            <?php echo esc_html((string) $option_label); ?>
                        </a>
                    <?php endforeach; ?>
                </div>
            </details>
            <?php
            return ob_get_clean();
        }

