                    </label>
                    <a class="sffc-community-editorial__filter-option sffc-crm-linkedin-jobs__filter-option<?php echo $selected === '' ? ' is-active' : ''; ?>" href="<?php echo esc_url(add_query_arg(array_filter(array_diff_key($base_args, ['sffc_job_company' => true]), static function ($arg_value) { return $arg_value !== ''; }), $base_url)); ?>" aria-current="<?php echo $selected === '' ? 'true' : 'false'; ?>" data-sffc-linkedin-jobs-filter-option data-sffc-linkedin-jobs-filter-name="sffc_job_company" data-sffc-linkedin-jobs-filter-value="">
                        <?php esc_html_e('All companies', 'senna-finance'); ?>
                    </a>
                    <?php foreach ($company_options as $company_name) : ?>
                        <?php
                        $option_args = $base_args;
                        $option_args['sffc_job_company'] = $company_name;
                        $option_args = array_filter($option_args, static function ($arg_value) {
                            return $arg_value !== '';
                        });
                        $is_active = strcasecmp((string) $selected, (string) $company_name) === 0;
                        ?>
                        <a class="sffc-community-editorial__filter-option sffc-crm-linkedin-jobs__filter-option<?php echo $is_active ? ' is-active' : ''; ?>" href="<?php echo esc_url(add_query_arg($option_args, $base_url)); ?>" aria-current="<?php echo $is_active ? 'true' : 'false'; ?>" data-sffc-linkedin-jobs-filter-option data-sffc-linkedin-jobs-filter-name="sffc_job_company" data-sffc-linkedin-jobs-filter-value="<?php echo esc_attr((string) $company_name); ?>">
                            <?php echo esc_html((string) $company_name); ?>
                        </a>
                    <?php endforeach; ?>
                    <?php if (empty($company_options)) : ?>
                        <span class="sffc-community-editorial__filter-option sffc-crm-linkedin-jobs__filter-option is-disabled"><?php esc_html_e('No companies found in this tracker', 'senna-finance'); ?></span>
                    <?php endif; ?>
                </div>
            </details>
            <?php
            return ob_get_clean();
        }

        private function format_crm_linkedin_jobs_chip_label($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return '';
            }

            $value = preg_replace('/[_-]+/', ' ', $value);
            $value = preg_replace('/\s+/', ' ', (string) $value);

            if (function_exists('mb_convert_case')) {
                return mb_convert_case($value, MB_CASE_TITLE, 'UTF-8');
            }

            return ucwords(strtolower($value));
        }

        private function normalize_crm_linkedin_jobs_filter_token($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return '';
            }

            $value = preg_replace('/[_-]+/', ' ', $value);
            $value = preg_replace('/\s+/', ' ', (string) $value);

            if (function_exists('mb_strtolower')) {
                return mb_strtolower($value, 'UTF-8');
            }

            return strtolower($value);
        }

