        private function render_crm_linkedin_jobs_detail_panel(array $post, $selected_post_id)
        {
            $post_id = (int) ($post['id'] ?? 0);
            $is_selected = $post_id > 0 && $post_id === (int) $selected_post_id;
            $role_title = trim((string) ($post['role_title'] ?? __('Untitled role', 'senna-finance')));
            $company_name = trim((string) ($post['company'] ?? ''));
            $location = trim((string) ($post['location'] ?? ''));
            $description_html = trim((string) ($post['content'] ?? ''));
            if ($description_html === '') {
                $description_html = trim((string) ($post['content_snippet'] ?? ''));
            }
            $application_url = trim((string) ($post['application_url'] ?? ''));
            if ($application_url === '') {
                $application_url = trim((string) ($post['source_url'] ?? ''));
            }
            $post_url = $this->get_crm_post_article_layout_similar_post_url($post);
            $posted_label = $this->get_crm_linkedin_jobs_posted_label($post);
            $source_platform = trim((string) ($post['source_platform'] ?? ''));
            $company_logo = trim((string) ($post['company_logo'] ?? ''));
            $company_initial = $company_name !== '' ? strtoupper(substr($company_name, 0, 1)) : 'S';
            $detail_chips = array_values(array_filter([
                !empty($post['is_remote']) ? __('Remote', 'senna-finance') : (!empty($post['is_hybrid']) ? __('Hybrid', 'senna-finance') : ''),
                trim((string) ($post['duration'] ?? '')),
                trim((string) ($post['seniority'] ?? '')),
                trim((string) ($post['sector'] ?? '')),
            ]));
            $match_item = $post;
            $match_item['crm_post_id'] = $post_id;
            $match_payload = $this->get_crm_editorial_community_item_match_payload($match_item, get_current_user_id());
            $has_guest_match_profile = is_array($this->crm_editorial_guest_match_profile) && !empty($this->crm_editorial_guest_match_profile['has_cv']);
            if (!is_user_logged_in() && !$has_guest_match_profile) {
                $match_payload = [
                    'rank' => 'unrated',
                    'label' => __('Review your profile first', 'senna-finance'),
                    'score' => null,
                    'reasons' => [],
                    'missing' => [],
                    'is_unrated' => true,
                ];
            }
            $match_rank = sanitize_key((string) ($match_payload['rank'] ?? 'consider'));
            $match_label = trim((string) ($match_payload['label'] ?? __('To Consider', 'senna-finance')));
            $match_score = (float) ($match_payload['score'] ?? 0);
            $is_match_unrated = $match_rank === 'unrated' || !empty($match_payload['is_unrated']);
            $match_rating = $is_match_unrated ? 0 : $this->get_crm_editorial_community_match_rating($match_score, $match_rank);
            $match_filled_stars = $is_match_unrated ? 0 : max(1, min(5, (int) floor($match_rating + 0.25)));
            $match_reasons = array_values(array_filter((array) ($match_payload['reasons'] ?? [])));
            $match_missing = array_values(array_filter((array) ($match_payload['missing'] ?? [])));
            $match_quick_checks = array_values(array_filter((array) ($match_payload['quick_checks'] ?? []), 'is_array'));
            $match_detected_groups = array_values(array_filter((array) ($match_payload['detected_groups'] ?? []), 'is_array'));
            $payload_fit_breakdown = array_values(array_filter((array) ($match_payload['fit_breakdown'] ?? []), 'is_array'));
            $match_heading = $is_match_unrated
                ? __('Find out if you\'re qualified', 'senna-finance')
                : ($match_rank === 'qualified'
                ? __('You\'re qualified for this job', 'senna-finance')
                : ($match_rank === 'mismatch' ? __('This role may be a stretch', 'senna-finance') : __('This role is worth considering', 'senna-finance')));
            $match_subheading = $is_match_unrated
                ? ''
                : ($match_rank === 'qualified'
                ? __('Your profile matches the required skills for this role', 'senna-finance')
                : ($match_rank === 'mismatch' ? __('Review the gaps before spending time on the application', 'senna-finance') : __('You have useful overlap, with a few areas to check first', 'senna-finance')));
            $fit_breakdown = $is_match_unrated
                ? [
                    ['label' => __('Role level', 'senna-finance'), 'value' => __('Seniority fit', 'senna-finance'), 'tone' => 'locked'],
                    ['label' => __('Sector fit', 'senna-finance'), 'value' => __('Industry match', 'senna-finance'), 'tone' => 'locked'],
                    ['label' => __('CV evidence', 'senna-finance'), 'value' => __('Proof in CV', 'senna-finance'), 'tone' => 'locked'],
                    ['label' => __('Apply route', 'senna-finance'), 'value' => __('Best next step', 'senna-finance'), 'tone' => 'locked'],
                ]
                : (!empty($payload_fit_breakdown) ? $payload_fit_breakdown : [
                    [
                        'label' => __('Role level', 'senna-finance'),
                        'value' => trim((string) ($post['seniority'] ?? '')) !== '' ? $this->format_crm_linkedin_jobs_chip_label($post['seniority']) : __('Check role brief', 'senna-finance'),
                        'tone' => $match_rank === 'mismatch' ? 'watch' : 'strong',
                    ],
                    [
                        'label' => __('Sector fit', 'senna-finance'),
                        'value' => trim((string) ($post['sector'] ?? '')) !== '' ? $this->format_crm_linkedin_jobs_chip_label($post['sector']) : __('Not specified', 'senna-finance'),
                        'tone' => $match_rank === 'qualified' ? 'strong' : 'watch',
                    ],
                    [
                        'label' => __('CV evidence', 'senna-finance'),
                        'value' => !empty($match_missing) ? __('Needs work', 'senna-finance') : __('Visible', 'senna-finance'),
                        'tone' => !empty($match_missing) ? 'watch' : 'strong',
                    ],
                    [
                        'label' => __('Apply route', 'senna-finance'),
                        'value' => $match_rank === 'qualified' ? __('Apply now', 'senna-finance') : ($match_rank === 'mismatch' ? __('Tailor first', 'senna-finance') : __('Review first', 'senna-finance')),
                        'tone' => $match_rank === 'qualified' ? 'strong' : 'watch',
                    ],
                ]);
            $has_match_premium_access = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $show_match_premium_cta = !$has_match_premium_access;
            $review_user = is_user_logged_in() ? wp_get_current_user() : null;
            $review_default_name = $review_user instanceof \WP_User
                ? trim((string) ($review_user->display_name ?: $review_user->user_login))
                : '';
            $review_default_email = $review_user instanceof \WP_User
                ? trim((string) $review_user->user_email)
                : '';
            $profile_review_score_percent = $is_match_unrated ? 0 : max(1, min(100, (int) round(($match_rating / 5) * 100)));
            $profile_review_score_display = $is_match_unrated ? __('Pending', 'senna-finance') : sprintf(__('%s%%', 'senna-finance'), number_format_i18n($profile_review_score_percent));
            $profile_review_shortlist_label = $is_match_unrated
                ? __('Expert score pending', 'senna-finance')
                : ($profile_review_score_percent >= 78
                    ? __('Very likely to be shortlisted', 'senna-finance')
                    : ($profile_review_score_percent >= 60
                        ? __('Competitive with tailoring', 'senna-finance')
                        : ($profile_review_score_percent >= 42
                            ? __('Possible, but needs clearer evidence', 'senna-finance')
                            : __('This may be a stretch', 'senna-finance'))));
            $profile_review_strengths = !empty($match_reasons)
                ? array_slice($match_reasons, 0, 4)
                : [
                    __('Role evidence will be checked against the job description.', 'senna-finance'),
                    __('Sector signal will be reviewed for relevance to the employer.', 'senna-finance'),
                    __('CV and LinkedIn consistency will be checked together.', 'senna-finance'),
                ];
            $profile_review_gaps = !empty($match_missing)
                ? array_slice($match_missing, 0, 4)
                : [
                    __('Missing keywords and weak proof points will be identified after the CV is reviewed.', 'senna-finance'),
                    __('The assessor will check whether seniority, location, and role evidence are clear enough.', 'senna-finance'),
                ];
            $profile_review_keyword_percent = $is_match_unrated ? 34 : max(30, min(92, $profile_review_score_percent + 7));
            $profile_review_seniority_percent = $is_match_unrated ? 28 : max(24, min(90, $profile_review_score_percent + ($match_rank === 'qualified' ? 8 : -4)));
            $profile_review_evidence_percent = $is_match_unrated ? 31 : max(26, min(88, $profile_review_score_percent + (empty($match_missing) ? 10 : -8)));
            $profile_review_market_percent = $is_match_unrated ? 40 : max(32, min(86, $profile_review_score_percent + 2));
            $profile_review_recommendations = [
                __('Add stronger evidence for the role requirements that matter most.', 'senna-finance'),
                __('Mirror the job description language where the experience is genuine.', 'senna-finance'),
                __('Make seniority and sector fit obvious in the first third of the CV.', 'senna-finance'),
                __('Use LinkedIn to reinforce the same role, market, and transaction signals.', 'senna-finance'),
            ];
            ob_start();
            ?>
            <article class="sffc-crm-linkedin-jobs__job<?php echo $is_selected ? ' is-active' : ''; ?>" data-sffc-linkedin-jobs-detail-panel="<?php echo esc_attr((string) $post_id); ?>"<?php echo $is_selected ? '' : ' hidden'; ?>>
