        private function render_crm_linkedin_jobs_result_card(array $post, $selected_post_id, array $tracker_context = [])
        {
            $post_id = (int) ($post['id'] ?? 0);
            $item = $post;
            $item['crm_post_id'] = $post_id;
            $role_title = trim((string) ($post['role_title'] ?? __('Untitled role', 'senna-finance')));
            $company_name = trim((string) ($post['company'] ?? ''));
            $location = trim((string) ($post['location'] ?? ''));
            $posted_label = $this->get_crm_linkedin_jobs_posted_label($post);
            $company_logo = trim((string) ($post['company_logo'] ?? ''));
            $company_initial = $company_name !== '' ? strtoupper(substr($company_name, 0, 1)) : 'S';
            $card_url = add_query_arg('crm_post_id', $post_id, $this->get_crm_post_article_layout_similar_post_url($post));
            $is_selected = $post_id > 0 && $post_id === (int) $selected_post_id;
            $meta_line = implode(' · ', array_filter([
                $company_name,
                $location,
                $this->format_crm_linkedin_jobs_chip_label((string) ($post['sector'] ?? '')),
            ]));
            $detail_line = implode(' · ', array_filter([
                !empty($post['is_remote']) ? __('Remote', 'senna-finance') : (!empty($post['is_hybrid']) ? __('Hybrid', 'senna-finance') : ''),
                trim((string) ($post['duration'] ?? '')),
                trim((string) ($post['seniority'] ?? '')),
            ]));
            $match_payload = $this->get_crm_editorial_community_item_match_payload($item, get_current_user_id());
            $has_guest_match_profile = is_array($this->crm_editorial_guest_match_profile) && !empty($this->crm_editorial_guest_match_profile['has_cv']);
            if (!is_user_logged_in() && !$has_guest_match_profile) {
                $match_payload = [
                    'rank' => 'unrated',
                    'label' => __('Upload CV to Match', 'senna-finance'),
                    'score' => null,
                    'reasons' => [__('Upload CV to Match', 'senna-finance')],
                    'missing' => [],
                    'is_unrated' => true,
                ];
            }
            $match_rank = sanitize_key((string) ($match_payload['rank'] ?? 'consider'));
            $match_label = trim((string) ($match_payload['label'] ?? __('To Consider', 'senna-finance')));
            $tracker_id = (int) ($tracker_context['id'] ?? 0);
            $match_reasons = array_values(array_filter((array) ($match_payload['reasons'] ?? [])));
            $match_missing = array_values(array_filter((array) ($match_payload['missing'] ?? [])));
            $qualification_values = array_values(array_filter($this->extract_crm_editorial_community_qualifications($item)));
            $chip_values = !empty($qualification_values)
                ? $qualification_values
                : array_values(array_filter([
                    trim((string) ($post['sector'] ?? '')),
                    trim((string) ($post['seniority'] ?? '')),
                    trim((string) ($post['duration'] ?? '')),
                ]));
            $posted_timestamp = $this->normalize_crm_linkedin_jobs_posted_timestamp($post['posted_at'] ?? '');
            $work_type_value = !empty($post['is_remote']) ? 'remote' : (!empty($post['is_hybrid']) ? 'hybrid' : 'onsite');
            $group_attr = implode(' ', array_map('sanitize_html_class', $this->get_cv_match_studio_mailbox_group_slugs($item)));
            $location_filter_value = $this->normalize_crm_editorial_community_location_label($location);
            $company_filter_value = sanitize_title($company_name);
            $sector_filter_value = $this->normalize_crm_editorial_community_sector_filter_value((string) ($post['sector'] ?? ''));
            $seniority_filter_value = $this->normalize_crm_editorial_community_seniority_filter_value((string) ($post['seniority'] ?? ''));
            $work_type_filter_values = $this->extract_crm_editorial_community_work_type_filters($item);
            $search_text = implode(' ', array_filter(array_merge([
                $role_title,
                $company_name,
                $location,
                trim((string) ($post['sector'] ?? '')),
                trim((string) ($post['seniority'] ?? '')),
                trim((string) ($post['duration'] ?? '')),
                trim((string) ($post['source_platform'] ?? '')),
            ], $chip_values, $match_reasons, $match_missing)));

            ob_start();
            ?>
            <a class="sffc-community-editorial__post-result<?php echo $is_selected ? ' is-active' : ''; ?>" href="<?php echo esc_url($card_url); ?>" data-sffc-linkedin-jobs-result-card data-sffc-linkedin-jobs-post-id="<?php echo esc_attr((string) $post_id); ?>" data-sffc-linkedin-jobs-card-url="<?php echo esc_url($card_url); ?>" data-sffc-linkedin-jobs-search="<?php echo esc_attr($search_text); ?>" data-sffc-linkedin-jobs-title="<?php echo esc_attr($role_title); ?>" data-sffc-linkedin-jobs-company="<?php echo esc_attr($company_name); ?>" data-sffc-linkedin-jobs-location="<?php echo esc_attr($location); ?>" data-sffc-linkedin-jobs-experience="<?php echo esc_attr(trim((string) ($post['seniority'] ?? ''))); ?>" data-sffc-linkedin-jobs-sector="<?php echo esc_attr(trim((string) ($post['sector'] ?? ''))); ?>" data-sffc-linkedin-jobs-tracker="<?php echo esc_attr($tracker_id > 0 ? (string) $tracker_id : ''); ?>" data-sffc-linkedin-jobs-match="<?php echo esc_attr($match_rank); ?>" data-sffc-linkedin-jobs-work="<?php echo esc_attr($work_type_value); ?>" data-sffc-linkedin-jobs-remote="<?php echo !empty($post['is_remote']) ? '1' : '0'; ?>" data-sffc-linkedin-jobs-posted-at="<?php echo esc_attr((string) $posted_timestamp); ?>" data-sffc-community-post-id="<?php echo esc_attr((string) $post_id); ?>" data-sffc-community-post-groups="<?php echo esc_attr($group_attr); ?>" data-sffc-community-post-location="<?php echo esc_attr($location_filter_value !== '' ? $location_filter_value : $location); ?>" data-sffc-community-post-company="<?php echo esc_attr($company_filter_value); ?>" data-sffc-community-post-sector="<?php echo esc_attr($sector_filter_value); ?>" data-sffc-community-post-work-types="<?php echo esc_attr(implode('|', $work_type_filter_values)); ?>" data-sffc-community-post-seniority="<?php echo esc_attr(trim((string) ($post['seniority'] ?? ''))); ?>" data-sffc-community-post-seniority-filter="<?php echo esc_attr($seniority_filter_value); ?>" data-sffc-community-post-qualifications="<?php echo esc_attr(implode('|', $qualification_values)); ?>" data-sffc-community-post-match-rank="<?php echo esc_attr($match_rank); ?>" data-sffc-community-post-search="<?php echo esc_attr($search_text); ?>" data-sffc-community-post-timestamp="<?php echo esc_attr((string) $posted_timestamp); ?>" data-sffc-community-post-recency="<?php echo !empty($post['exclude_from_early_bird']) ? 'standard' : 'early_bird'; ?>" aria-current="<?php echo $is_selected ? 'true' : 'false'; ?>">
                <span class="sffc-crm-linkedin-jobs__active-pin" aria-hidden="true">
                    <svg viewBox="0 0 24 24"><path d="M14.7 3.7 20.3 9.3 17.9 11.7 16.3 10.1 12.2 14.2 12.8 18.5 11.7 19.6 8.2 16.1 4.8 19.5 4.1 18.8 7.5 15.4 4 11.9 5.1 10.8 9.4 11.4 13.5 7.3 11.9 5.7 14.7 3.7Z" fill="currentColor"/></svg>
                </span>
                <div class="sffc-community-editorial__post-company-logo<?php echo $company_logo !== '' ? ' has-image' : ''; ?>" aria-hidden="true">
                    <?php if ($company_logo !== '') : ?>
                        <img src="<?php echo esc_url($company_logo); ?>" alt="">
                    <?php else : ?>
                        <span><?php echo esc_html($company_initial); ?></span>
                    <?php endif; ?>
                </div>
                <div class="sffc-community-editorial__post-result-main">
                    <div class="sffc-community-editorial__post-result-topline">
                        <?php if ($posted_label !== '') : ?>
                            <span class="sffc-community-editorial__post-age"><?php echo esc_html($posted_label); ?></span>
                        <?php endif; ?>
                        <?php if (!empty($match_reasons)) : ?>
                            <span class="sffc-community-editorial__post-match-reason"><?php echo esc_html((string) $match_reasons[0]); ?></span>
                        <?php endif; ?>
                        <?php if (!empty($match_missing)) : ?>
                            <span class="sffc-community-editorial__post-match-reason is-missing"><?php echo esc_html((string) $match_missing[0]); ?></span>
                        <?php endif; ?>
                    </div>
                    <h2 class="sffc-community-editorial__post-title-wrap">
                        <span class="sffc-community-editorial__post-title"><?php echo esc_html($role_title); ?></span>
                        <?php echo $this->render_crm_editorial_community_match_rating((float) ($match_payload['score'] ?? 0), $match_rank, $match_label); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                    </h2>
                    <?php if ($meta_line !== '') : ?>
                        <p class="sffc-community-editorial__post-meta-line"><?php echo esc_html($meta_line); ?></p>
                    <?php endif; ?>
                    <?php if ($detail_line !== '') : ?>
                        <div class="sffc-community-editorial__post-detail-row">
                            <span><?php echo esc_html($detail_line); ?></span>
                        </div>
                    <?php endif; ?>
                    <?php if (!empty($chip_values)) : ?>
                        <div class="sffc-community-editorial__chips" aria-label="<?php esc_attr_e('Matched skills and qualifications', 'senna-finance'); ?>">
                            <?php foreach (array_slice($chip_values, 0, 4) as $chip_value) : ?>
                                <span><?php echo esc_html($this->format_crm_linkedin_jobs_chip_label($chip_value)); ?></span>
                            <?php endforeach; ?>
                        </div>
                    <?php endif; ?>
                </div>
                <span class="sffc-crm-linkedin-jobs__card-cue" aria-hidden="true">
                    <svg viewBox="0 0 24 24"><path d="M8 5l7 7-7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
                </span>
            </a>
            <?php
            return ob_get_clean();
        }

        private function get_crm_linkedin_jobs_posted_label(array $post)
        {
            $timestamp = $this->normalize_crm_linkedin_jobs_posted_timestamp($post['posted_at'] ?? '');
            if (!$timestamp) {
                return '';
            }

            if ((current_time('timestamp') - $timestamp) >= MONTH_IN_SECONDS) {
                return '';
            }

            return sprintf(__('%s ago', 'senna-finance'), human_time_diff($timestamp, current_time('timestamp')));
        }

        private function normalize_crm_linkedin_jobs_posted_timestamp($posted_at)
        {
            $posted_at = is_scalar($posted_at) ? trim((string) $posted_at) : '';
            if ($posted_at === '' || preg_match('/^\d{4}$/', $posted_at) || preg_match('/^0{4}-0{2}-0{2}/', $posted_at)) {
                return 0;
            }

            $timestamp = strtotime($posted_at);
            if (!$timestamp || $timestamp <= 0) {
                return 0;
            }

            $now = current_time('timestamp');
            if ($timestamp > ($now + DAY_IN_SECONDS) || $timestamp < strtotime('2000-01-01 00:00:00')) {
                return 0;
            }

            return (int) $timestamp;
        }

