        public function render_crm_post_article_chat_layout($atts = [])
        {
            $atts = shortcode_atts([
                'post_id' => '',
                'similar_limit' => 3,
            ], $atts, 'sffc_crm_post_article_chat_layout');

            $post_id = $this->resolve_current_crm_post_id($atts['post_id'] ?? 0);
            if ($post_id <= 0) {
                return '<!-- crm post article chat layout: no post id provided -->';
            }

            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return '<!-- crm post article chat layout: model not found -->';
            }

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-apply-chat-article.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-apply-chat-article.css')
                : SFFC_VERSION;
            $community_editorial_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                : SFFC_VERSION;
            $linkedin_jobs_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-linkedin-jobs-layout.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-linkedin-jobs-layout.css')
                : SFFC_VERSION;
            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/crm-apply-chat-article.js')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/crm-apply-chat-article.js')
                : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-community-editorial',
