                true
            );

            wp_localize_script('sffc-crm-apply-chat-article', 'sffcCrmApplyChatArticle', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'nonce' => wp_create_nonce('sffc_crm_apply_chat_analyze_cv'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'resumeUploadNonce' => wp_create_nonce('sffc_cv_upload'),
                'accountLookupNonce' => wp_create_nonce('sffc_crm_apply_chat_check_account_email'),
                'requestHumanNonce' => wp_create_nonce('sffc_crm_apply_chat_request_human_followup'),
                'chatSessionNonce' => wp_create_nonce('sffc_crm_apply_chat_session'),
                'memoryNonce' => wp_create_nonce('sffc_crm_apply_chat_memory'),
                'matchesEmailNonce' => wp_create_nonce('sffc_crm_apply_chat_send_matches_email'),
                'autoApplyContactNonce' => wp_create_nonce('sffc_crm_apply_chat_capture_auto_apply_contact'),
                'autoSubmitSchemaNonce' => wp_create_nonce('sffc_crm_apply_chat_get_auto_submit_schema'),
                'applicationTaskNonce' => wp_create_nonce('sffc_crm_apply_chat_queue_application_task'),
                'catchUpInviteNonce' => wp_create_nonce('sffc_crm_apply_chat_send_catch_up_invite'),
                'jobsSearchNonce' => wp_create_nonce('sffc_crm_apply_chat_search_jobs'),
                'prefillNonce' => wp_create_nonce('sffc_sync_signup_prefill'),
                'currencyNonce' => wp_create_nonce('sffc_member_basic_signup_currency'),
                'membershipPanelNonce' => wp_create_nonce('sffc_apply_chat_membership_panel'),
                'signupUrl' => home_url('/get-started/'),
                'membershipsUrl' => home_url('/memberships/'),
                'applyChatPricingOptions' => $this->get_apply_chat_pricing_options(),
                'isLoggedIn' => is_user_logged_in(),
                'currentUserFirstName' => $this->get_crm_apply_chat_current_user_first_name(),
                'currentUserAvatarUrl' => is_user_logged_in() ? (string) get_avatar_url(get_current_user_id(), ['size' => 96]) : 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp',
                'pdfScriptUrl' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
                'pdfWorker' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
                'mammothScriptUrl' => 'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js',
            ]);

            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get_full_detail($post_id, get_current_user_id());
            if (empty($post) || !is_array($post)) {
                return '<!-- crm post article chat layout: post not found -->';
            }

            $role_title = trim((string) ($post['role_title'] ?? __('Untitled role', 'senna-finance')));
            $company_name = trim((string) ($post['company'] ?? ''));
            $location = trim((string) ($post['location'] ?? ''));
            $business_area = trim((string) ($post['sector'] ?? ''));
            $sector = $business_area;
            $seniority = trim((string) ($post['seniority'] ?? ''));
            $recruiter_name = trim((string) ($post['recruiter_name'] ?? __('Emily', 'senna-finance')));
            $recruiter_title = trim((string) ($post['recruiter_title'] ?? __('Candidate success advisor', 'senna-finance')));
            $recruiter_photo = trim((string) ($post['recruiter_photo'] ?? ''));
            $emily_photo = 'https://media.joinsenna.com/2026/07/1784056723762.png?1784414003';
            $advisor_photo = $recruiter_photo !== '' ? $recruiter_photo : $emily_photo;
            $description_html = trim((string) ($post['content'] ?? ''));
            if ($description_html === '') {
                $description_html = trim((string) ($post['content_snippet'] ?? ''));
            }

            $application_url = trim((string) ($post['application_url'] ?? ''));
            if ($application_url === '') {
                $application_url = trim((string) ($post['source_url'] ?? ''));
            }
            if ($application_url === '' && !empty($post['wp_post_id'])) {
                $application_url = (string) (get_permalink((int) $post['wp_post_id']) ?: '');
            }
            $public_opportunity_url = $this->get_crm_editorial_community_public_opportunity_url((array) $post, $role_title, $company_name);
            $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(
                (int) ($post['jobs_post_id'] ?? 0),
                (int) ($post['wp_post_id'] ?? 0),
                $post_id
            );
            $apply_chat_auto_submit = $this->get_crm_apply_chat_auto_submit_payload($jobs_post_id);
            $apply_chat_company_logo = trim((string) ($post['company_logo'] ?? ''));
            $apply_chat_posted_label = $this->get_crm_linkedin_jobs_posted_label((array) $post);

            $similar_limit = max(1, min(6, absint($atts['similar_limit'])));
            $similar_posts = $this->get_crm_post_article_layout_similar_posts((array) $post, $similar_limit);
            $role_context = $company_name !== '' ? sprintf('%s, %s', $role_title, $company_name) : $role_title;
            $matching_roles_seed = [];
            $matching_recruiters_seed = [];
            $matching_salary_guides_seed = [];
            $membership_workspace = $this->render_apply_chat_membership_workspace();
            $has_paid_editorial_access = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $membership_snapshot = is_user_logged_in() ? $this->get_crm_apply_chat_membership_snapshot(get_current_user_id()) : $this->get_crm_apply_chat_membership_snapshot(0);
            $member_onboarding_html = $this->render_crm_apply_chat_member_onboarding_dialog();
            $default_guest_avatar = 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp';
            $apply_chat_user_id = get_current_user_id();
            $apply_chat_account_user = $apply_chat_user_id > 0 ? $this->get_crm_reddit_account_user($apply_chat_user_id) : [];
            $apply_chat_avatar_url = $apply_chat_user_id > 0 ? $this->get_crm_reddit_profile_avatar_url($apply_chat_user_id, $apply_chat_account_user) : $default_guest_avatar;
            $apply_chat_avatar_name = trim((string) ($apply_chat_account_user['display_name'] ?? ''));
            if ($apply_chat_avatar_name === '') {
                $apply_chat_avatar_name = $this->get_crm_apply_chat_current_user_first_name();
            }
            if ($apply_chat_avatar_name === '') {
                $apply_chat_avatar_name = __('Guest user', 'senna-finance');
            }
            $apply_chat_resume_documents = $apply_chat_user_id > 0 ? $this->get_crm_editorial_resume_documents($apply_chat_user_id) : [];
            $apply_chat_intros_panel_html = $this->render_crm_apply_chat_activity_panel($apply_chat_user_id, 'intros');
            $apply_chat_sent_panel_html = $this->render_crm_apply_chat_activity_panel($apply_chat_user_id, 'sent');

            $matching_roles_seed = $this->get_apply_chat_matching_roles_seed([
                'location' => $location,
                'sector' => $sector,
                'keywords' => trim($role_title . ' ' . $company_name),
            ]);

            if (!class_exists('SFFC_CRM_HR_Outreach')) {
                $hr_model_file = plugin_dir_path(__FILE__) . 'models/class-crm-hr-outreach.php';
                if (file_exists($hr_model_file)) {
                    require_once $hr_model_file;
                }
            }

            if (class_exists('SFFC_CRM_HR_Outreach')) {
                $hr_outreach_model = new SFFC_CRM_HR_Outreach();
                $matching_recruiters_raw = (array) $hr_outreach_model->get_all([
                    'limit' => 36,
                ]);

                foreach ($matching_recruiters_raw as $recruiter_item) {
                    $recruiter_item = is_array($recruiter_item) ? $recruiter_item : [];
                    $contact_name = sanitize_text_field((string) ($recruiter_item['contact_name'] ?? ''));
                    if ($contact_name === '') {
                        continue;
                    }

                    $team_contacts = [];
                    if (!empty($recruiter_item['team_contacts']) && is_array($recruiter_item['team_contacts'])) {
                        foreach ($recruiter_item['team_contacts'] as $team_contact) {
                            if (!is_array($team_contact)) {
                                continue;
                            }
                            $team_contacts[] = [
                                'name' => sanitize_text_field((string) ($team_contact['name'] ?? '')),
                                'title' => sanitize_text_field((string) ($team_contact['title'] ?? '')),
                                'email' => sanitize_email((string) ($team_contact['email'] ?? '')),
                            ];
                        }
                    }

                    $matching_recruiters_seed[] = [
                        'id' => (int) ($recruiter_item['id'] ?? 0),
                        'name' => $contact_name,
                        'title' => sanitize_text_field((string) ($recruiter_item['contact_title'] ?? '')),
                        'company' => sanitize_text_field((string) ($recruiter_item['company_name'] ?? '')),
                        'location' => sanitize_text_field((string) ($recruiter_item['location'] ?? '')),
                        'regions' => implode(', ', array_filter(array_map('sanitize_text_field', (array) ($recruiter_item['regions'] ?? [])))),
                        'industry' => implode(', ', array_filter(array_map('sanitize_text_field', (array) ($recruiter_item['industry'] ?? [])))),
                        'skills' => implode(', ', array_filter(array_map('sanitize_text_field', (array) ($recruiter_item['skills'] ?? [])))),
                        'role_focus' => wp_strip_all_tags((string) ($recruiter_item['role_focus'] ?? '')),
                        'notes' => wp_strip_all_tags((string) ($recruiter_item['notes'] ?? '')),
                        'phone' => sanitize_text_field((string) ($recruiter_item['contact_phone'] ?? '')),
                        'email' => sanitize_email((string) ($recruiter_item['contact_email'] ?? '')),
                        'linkedin' => esc_url_raw((string) ($recruiter_item['contact_linkedin'] ?? '')),
                        'company_url' => esc_url_raw((string) ($recruiter_item['company_url'] ?? '')),
                        'avatar' => esc_url_raw((string) ($recruiter_item['contact_photo'] ?? '')),
                        'company_logo' => esc_url_raw((string) ($recruiter_item['company_logo'] ?? '')),
                        'team_contacts' => $team_contacts,
                    ];
                }
            }

            $salary_guide_posts = get_posts([
                'post_type' => 'sffc_salary_guide',
                'post_status' => 'publish',
                'posts_per_page' => 120,
                'orderby' => 'date',
                'order' => 'DESC',
                'no_found_rows' => true,
            ]);

            foreach ($salary_guide_posts as $salary_guide_post) {
                if (!$salary_guide_post instanceof WP_Post) {
                    continue;
                }

                $salary_region = sanitize_text_field((string) get_post_meta($salary_guide_post->ID, 'salary_region', true));
                $salary_role = sanitize_text_field((string) get_post_meta($salary_guide_post->ID, 'salary_role', true));
                $experience_level = sanitize_text_field((string) get_post_meta($salary_guide_post->ID, 'salary_experience_level', true));
                $salary_min = (int) get_post_meta($salary_guide_post->ID, 'salary_min', true);
                $salary_max = (int) get_post_meta($salary_guide_post->ID, 'salary_max', true);

                $region_haystack = strtolower($salary_region);
                $is_middle_east_region = strpos($region_haystack, 'dubai') !== false
                    || strpos($region_haystack, 'abu dhabi') !== false
                    || strpos($region_haystack, 'uae') !== false
                    || strpos($region_haystack, 'united arab emirates') !== false
                    || strpos($region_haystack, 'riyadh') !== false
                    || strpos($region_haystack, 'saudi') !== false
                    || strpos($region_haystack, 'ksa') !== false;

                if (!$is_middle_east_region) {
                    continue;
                }

                if ($salary_region === '' && $salary_role === '' && $salary_min <= 0 && $salary_max <= 0) {
                    continue;
                }

                $matching_salary_guides_seed[] = [
                    'id' => (int) $salary_guide_post->ID,
                    'title' => sanitize_text_field((string) $salary_guide_post->post_title),
                    'role' => $salary_role,
                    'region' => $salary_region,
                    'experience_level' => $experience_level,
                    'salary_min' => $salary_min,
                    'salary_max' => $salary_max,
                ];
            }

            $apply_chat_recruiter_name = trim((string) ($post['recruiter_name'] ?? ''));
            $apply_chat_recruiter_title = trim((string) ($post['recruiter_title'] ?? ''));
            $apply_chat_recruiter_email = sanitize_email((string) ($post['recruiter_email'] ?? ''));
            $apply_chat_recruiter_display_name = $this->get_recruiter_short_name_for_display(
                $apply_chat_recruiter_name !== '' ? $apply_chat_recruiter_name : $recruiter_name
