            $apply_chat_recruiter_first_name = trim((string) preg_replace('/\s+.*$/', '', $apply_chat_recruiter_name));
            if ($apply_chat_recruiter_first_name === '') {
                $apply_chat_recruiter_first_name = __('Recruiter', 'senna-finance');
            }
            $show_apply_via_recruiter = $apply_chat_recruiter_name !== '' || $apply_chat_recruiter_title !== '' || $apply_chat_recruiter_email !== '';
            $apply_chat_review_mode_raw = isset($_GET['sffc_review']) ? wp_unslash($_GET['sffc_review']) : '';
            $apply_chat_review_mode_key = !is_array($apply_chat_review_mode_raw) ? sanitize_key((string) $apply_chat_review_mode_raw) : '';
            $apply_chat_review_mode = in_array($apply_chat_review_mode_key, ['profile', 'recruiter_outreach'], true)
                ? $apply_chat_review_mode_key
                : 'role';

            ob_start();
            ?>
            <section
                class="sffc-crm-apply-chat"
                data-sffc-apply-chat
                data-post-id="<?php echo esc_attr((string) $post_id); ?>"
