                data-role-title="<?php echo esc_attr($role_title); ?>"
                data-role-company="<?php echo esc_attr($company_name); ?>"
                data-role-location="<?php echo esc_attr($location); ?>"
                data-role-sector="<?php echo esc_attr($business_area); ?>"
                data-role-seniority="<?php echo esc_attr($seniority); ?>"
                data-role-salary="<?php echo esc_attr((string) ($post['salary_text'] ?? '')); ?>"
                data-company-logo="<?php echo esc_url($apply_chat_company_logo); ?>"
                data-posted-label="<?php echo esc_attr($apply_chat_posted_label); ?>"
