                data-greenhouse-board-token="<?php echo esc_attr((string) ($apply_chat_auto_submit['greenhouse_board_token'] ?? '')); ?>"
                data-greenhouse-job-id="<?php echo esc_attr((string) ($apply_chat_auto_submit['greenhouse_job_id'] ?? '')); ?>"
                data-recruiter-email="<?php echo esc_attr((string) ($post['recruiter_email'] ?? '')); ?>"
                data-source-platform="<?php
                    $apply_chat_source_platform = trim((string) ($post['source_platform'] ?? ''));
                    $apply_chat_source_platform_custom = trim((string) ($post['source_platform_custom'] ?? ''));
                    if ($apply_chat_source_platform === 'Other' && $apply_chat_source_platform_custom !== '') {
                        $apply_chat_source_platform = $apply_chat_source_platform_custom;
