                    <a class="sffc-crm-apply-chat__brand" href="<?php echo esc_url(home_url('/')); ?>" aria-label="<?php esc_attr_e('MENA Careers home', 'senna-finance'); ?>">
                        <img src="<?php echo esc_url('https://media.joinsenna.com/2026/02/senna111-scaled.png'); ?>" alt="<?php esc_attr_e('MENA Careers', 'senna-finance'); ?>">
