        private function find_crm_apply_chat_crm_post_id_by_jobs_post_id($jobs_post_id)
        {
            global $wpdb;

            $jobs_post_id = absint($jobs_post_id);
            if ($jobs_post_id <= 0) {
                return 0;
            }

            return (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id
                 FROM {$wpdb->prefix}sffc_crm_posts
                 WHERE (jobs_post_id = %d OR wp_post_id = %d)
                   AND is_active = 1
                   AND admin_approved = 1
                   AND (post_status IS NULL OR post_status = 'open')
                 ORDER BY id DESC
                 LIMIT 1",
                $jobs_post_id,
                $jobs_post_id
            ));
        }

        private function normalize_crm_apply_chat_job_search_item(array $item)
        {
            $title = sanitize_text_field((string) ($item['title'] ?? $item['role_title'] ?? __('Opportunity', 'senna-finance')));
            $view_url = esc_url_raw((string) ($item['view_url'] ?? $item['url'] ?? ''));
            $apply_url = esc_url_raw((string) ($item['apply_url'] ?? $item['application_url'] ?? ''));
            if ($view_url === '' && !empty($item['wp_post_id'])) {
                $view_url = esc_url_raw((string) (get_permalink((int) $item['wp_post_id']) ?: ''));
            }

            return [
                'id' => (int) ($item['crm_post_id'] ?? $item['id'] ?? $item['post_id'] ?? 0),
                'post_id' => (int) ($item['crm_post_id'] ?? $item['id'] ?? 0),
                'jobs_post_id' => (int) ($item['jobs_post_id'] ?? ((string) ($item['source'] ?? '') === 'jobs' ? (int) ($item['post_id'] ?? 0) : 0)),
                'wp_post_id' => (int) ($item['wp_post_id'] ?? 0),
                'source' => sanitize_key((string) ($item['source'] ?? 'crm')),
                'source_platform' => sanitize_text_field((string) ($item['source_platform'] ?? '')),
                'title' => $title,
                'role_title' => $title,
                'company' => sanitize_text_field((string) ($item['company'] ?? '')),
                'location' => sanitize_text_field((string) ($item['location'] ?? '')),
                'salary_text' => sanitize_text_field((string) ($item['salary_text'] ?? '')),
                'seniority' => sanitize_text_field((string) ($item['seniority'] ?? '')),
                'sector' => sanitize_text_field((string) ($item['sector'] ?? '')),
                'excerpt' => sanitize_text_field((string) ($item['excerpt'] ?? $item['description_preview'] ?? '')),
                'recruiter_name' => sanitize_text_field((string) ($item['recruiter_name'] ?? $item['recruiter'] ?? '')),
                'recruiter_id' => (int) ($item['recruiter_id'] ?? 0),
                'view_url' => $view_url,
                'apply_url' => $apply_url,
                'application_workspace_url' => esc_url_raw((string) ($item['application_workspace_url'] ?? $item['application_embed_url'] ?? '')),
                'posted_label' => sanitize_text_field((string) ($item['posted_label'] ?? '')),
                'auto_submit_supported' => !empty($item['auto_submit_supported']),
                'auto_submit_provider' => sanitize_key((string) ($item['auto_submit_provider'] ?? '')),
                'auto_submit_schema_status' => sanitize_key((string) ($item['auto_submit_schema_status'] ?? '')),
                'auto_submit_field_count' => absint($item['auto_submit_field_count'] ?? 0),
                'auto_submit_required_question_count' => absint($item['auto_submit_required_question_count'] ?? 0),
                'greenhouse_board_token' => sanitize_text_field((string) ($item['greenhouse_board_token'] ?? '')),
                'greenhouse_job_id' => sanitize_text_field((string) ($item['greenhouse_job_id'] ?? '')),
            ];
        }

        private function search_crm_apply_chat_actual_jobs($query, $limit = 8)
        {
            $query = is_array($query) ? '' : trim(sanitize_text_field((string) $query));
            $limit = max(1, min(16, (int) $limit));
            if ($query === '') {
                return [];
            }

            $items = [];
            $seen = [];

            foreach ((array) $this->get_crm_reddit_jobs_search_items($limit, $query) as $item) {
                $normalized = $this->normalize_crm_apply_chat_job_search_item((array) $item);
                $key = $normalized['source'] . ':' . $normalized['jobs_post_id'] . ':' . $normalized['wp_post_id'] . ':' . $normalized['post_id'];
                if (!isset($seen[$key])) {
                    $seen[$key] = true;
                    $items[] = $normalized;
                }
            }

            foreach ((array) $this->get_crm_reddit_feed_posts_batch($limit, get_current_user_id(), '', $query) as $post) {
                $normalized = $this->normalize_crm_apply_chat_job_search_item($this->build_crm_reddit_dashboard_crm_item((array) $post));
                $key = $normalized['source'] . ':' . $normalized['jobs_post_id'] . ':' . $normalized['wp_post_id'] . ':' . $normalized['post_id'];
                if (!isset($seen[$key])) {
                    $seen[$key] = true;
                    $items[] = $normalized;
                }
                if (count($items) >= $limit) {
                    break;
                }
            }

            return array_slice($items, 0, $limit);
        }

        public function ajax_crm_apply_chat_search_jobs()
        {
            check_ajax_referer('sffc_crm_apply_chat_search_jobs', 'nonce');

            $raw_query = isset($_POST['query']) ? wp_unslash($_POST['query']) : '';
            $query = is_array($raw_query) ? '' : sanitize_text_field((string) $raw_query);
            if (trim($query) === '') {
                wp_send_json_error(['message' => __('Tell me what job to search for.', 'senna-finance')], 400);
            }
            $limit = isset($_POST['limit']) ? absint($_POST['limit']) : 10;
            if ($limit <= 0) {
                $limit = 10;
            }

            wp_send_json_success([
                'items' => $this->search_crm_apply_chat_actual_jobs($query, $limit),
                'query' => $query,
            ]);
        }

