                $launch_notes = is_array($launch_notes_raw) ? '' : sanitize_textarea_field((string) $launch_notes_raw);
            }
            $launch_public_opportunity_url = !empty($launch_post)
                ? $this->get_crm_editorial_community_public_opportunity_url((array) $launch_post, $launch_role_title, $launch_company_name)
                : (!empty($launch_jobs_item['view_url']) ? (string) $launch_jobs_item['view_url'] : '#');
            $launch_auto_submit = $this->get_crm_apply_chat_auto_submit_payload($launch_jobs_post_id);
            $matching_roles_seed = [];
            $matching_recruiters_seed = [];
            $matching_salary_guides_seed = [];
            $membership_workspace = $this->render_apply_chat_membership_workspace();
            $has_paid_editorial_access = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $membership_snapshot = is_user_logged_in() ? $this->get_crm_apply_chat_membership_snapshot(get_current_user_id()) : $this->get_crm_apply_chat_membership_snapshot(0);
            $member_onboarding_html = $this->render_crm_apply_chat_member_onboarding_dialog();
            $default_guest_avatar = 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp';
            $apply_chat_user_id = get_current_user_id();
            $apply_chat_account_user = $apply_chat_user_id > 0 ? $this->get_crm_reddit_account_user($apply_chat_user_id) : [];
            $apply_chat_avatar_url = $apply_chat_user_id > 0 ? $this->get_crm_reddit_profile_avatar_url($apply_chat_user_id, $apply_chat_account_user) : $default_guest_avatar;
            $apply_chat_avatar_name = trim((string) ($apply_chat_account_user['display_name'] ?? ''));
            if ($apply_chat_avatar_name === '') {
                $apply_chat_avatar_name = $this->get_crm_apply_chat_current_user_first_name();
            }
            if ($apply_chat_avatar_name === '') {
                $apply_chat_avatar_name = __('Guest user', 'senna-finance');
            }
            $apply_chat_resume_documents = $apply_chat_user_id > 0 ? $this->get_crm_editorial_resume_documents($apply_chat_user_id) : [];
