                <?php
                return (string) ob_get_clean();
            }

            if (!$this->current_user_has_crm_editorial_paid_membership_access()) {
                ob_start();
                ?>
                <section class="sffc-crm-apply-chat__member-gate">
                    <strong><?php esc_html_e('Upgrade to open your Emily desk', 'senna-finance'); ?></strong>
                    <p><?php esc_html_e('Emily updates, tailored applications, recruiter intros, and live search support are available on a paid MENA Careers membership.', 'senna-finance'); ?></p>
                    <div class="sffc-crm-apply-chat__member-gate-actions">
                        <a class="sffc-crm-apply-chat__member-gate-button" href="<?php echo esc_url(home_url('/memberships/')); ?>"><?php esc_html_e('View memberships', 'senna-finance'); ?></a>
                    </div>
                </section>
                <?php
                return (string) ob_get_clean();
            }

            $atts = shortcode_atts([
                'title' => __('Emily Desk', 'senna-finance'),
                'prompt' => __('Message Emily', 'senna-finance'),
                'mode' => 'search_apply',
                'surface' => 'member_desk',
            ], $atts, 'sffc_crm_member_emily_desk');
            $atts['surface'] = 'member_desk';

            return $this->render_crm_apply_chat_launcher($atts);
        }

        public function ajax_crm_apply_chat_analyze_cv()
        {
            check_ajax_referer('sffc_crm_apply_chat_analyze_cv', 'nonce');

            $send_json = static function ($success, array $data, $status_code = null) {
                while (ob_get_level() > 0) {
                    ob_end_clean();
                }

                if ($success) {
                    wp_send_json_success($data, $status_code);
                }

                wp_send_json_error($data, $status_code);
            };

            $post_id = absint($_POST['post_id'] ?? 0);
            $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
            $target_role = sanitize_text_field(wp_unslash((string) ($_POST['target_role'] ?? '')));
            $post = [];
            $jobs_item = [];

            if ($jobs_post_id <= 0) {
                $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(0, 0, $post_id);
            }

            if ($jobs_post_id > 0) {
                $jobs_item = (array) $this->get_crm_reddit_jobs_item($jobs_post_id);
                if ($post_id <= 0) {
                    $linked_crm_post_id = (int) ($jobs_item['crm_post_id'] ?? 0);
                    if ($linked_crm_post_id <= 0) {
                        $linked_crm_post_id = $this->find_crm_apply_chat_crm_post_id_by_jobs_post_id($jobs_post_id);
                    }
                    if ($linked_crm_post_id > 0) {
                        $post_id = $linked_crm_post_id;
                    }
                }
            }

            if ($post_id > 0) {
                if (!class_exists('SFFC_CRM_Post')) {
                    $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                    if (file_exists($model_file)) {
                        require_once $model_file;
                    }
                }

                if (!class_exists('SFFC_CRM_Post')) {
                    $send_json(false, ['message' => __('Role data is unavailable right now.', 'senna-finance')], 500);
                }

                $post_model = new SFFC_CRM_Post();
                $post = $post_model->get_full_detail($post_id, get_current_user_id());
                if (empty($post) || !is_array($post)) {
                    $send_json(false, ['message' => __('Unable to find that role.', 'senna-finance')], 404);
                }

                if ($jobs_post_id <= 0) {
                    $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(0, (int) ($post['wp_post_id'] ?? 0), $post_id);
                }
            }

            $cv_text = sanitize_textarea_field((string) wp_unslash($_POST['cv_text'] ?? ''));
            $analysis_mode = sanitize_key(wp_unslash((string) ($_POST['analysis_mode'] ?? 'full')));
            if ($analysis_mode !== 'fast') {
                $analysis_mode = 'full';
            }

            $file_name = '';
            if ($cv_text === '' && !empty($_FILES['cv_file'])) {
                $upload_result = $this->extract_crm_apply_chat_cv_text_from_upload($_FILES['cv_file'], $analysis_mode);
                if (empty($upload_result['success'])) {
                    $send_json(false, ['message' => (string) ($upload_result['message'] ?? __('Unable to read that CV file.', 'senna-finance'))], 422);
                }

                $cv_text = (string) ($upload_result['text'] ?? '');
                $file_name = (string) ($upload_result['file_name'] ?? '');
            }

            if (trim($cv_text) === '') {
                $send_json(false, ['message' => __('Upload a CV or paste CV text so Emily can compare it with the role.', 'senna-finance')], 422);
            }

            if ($post_id > 0) {
                if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                }

                $jd_text = function_exists('sffc_build_crm_jd_text_for_analysis')
                    ? (string) sffc_build_crm_jd_text_for_analysis($post)
                    : wp_strip_all_tags((string) ($post['content'] ?? $post['content_snippet'] ?? ''));
                $analysis = $this->build_crm_apply_chat_cv_analysis($cv_text, $jd_text, $post);
            } elseif ($jobs_post_id > 0 && !empty($jobs_item)) {
                $jobs_post = get_post($jobs_post_id);
                $jd_text = wp_strip_all_tags((string) ($jobs_item['description_html'] ?? $jobs_item['description'] ?? $jobs_item['excerpt'] ?? ''));
                if (trim($jd_text) === '' && $jobs_post instanceof WP_Post) {
                    $jd_text = wp_strip_all_tags((string) $jobs_post->post_content);
                }

                $post = [
                    'id' => 0,
                    'source' => 'jobs',
                    'wp_post_id' => $jobs_post_id,
                    'jobs_post_id' => $jobs_post_id,
                    'role_title' => sanitize_text_field((string) ($jobs_item['role_title'] ?? ($jobs_post instanceof WP_Post ? $jobs_post->post_title : ''))),
                    'company' => sanitize_text_field((string) ($jobs_item['company'] ?? '')),
                    'location' => sanitize_text_field((string) ($jobs_item['location'] ?? '')),
                    'sector' => sanitize_text_field((string) ($jobs_item['sector'] ?? '')),
                    'seniority' => sanitize_text_field((string) ($jobs_item['seniority'] ?? '')),
                    'salary_text' => sanitize_text_field((string) ($jobs_item['salary_text'] ?? '')),
                    'content' => $jd_text,
                    'content_snippet' => sanitize_text_field((string) ($jobs_item['excerpt'] ?? '')),
                ];
                if ($target_role === '' && !empty($post['role_title'])) {
                    $target_role = (string) $post['role_title'];
                }

                $analysis = $this->build_crm_apply_chat_cv_analysis($cv_text, $jd_text, $post);
                $analysis['standalone_context_role'] = [
                    'id' => $jobs_post_id,
                    'source' => 'jobs',
                    'role_title' => sanitize_text_field((string) ($post['role_title'] ?? '')),
                    'company' => sanitize_text_field((string) ($post['company'] ?? '')),
                    'location' => sanitize_text_field((string) ($post['location'] ?? '')),
                    'sector' => sanitize_text_field((string) ($post['sector'] ?? '')),
                    'target_role' => $target_role,
                ];
            } else {
                $post = $this->find_crm_apply_chat_standalone_context_role($cv_text, $target_role);
                if (!empty($post)) {
                    if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
                        require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
                    }

                    $jd_text = function_exists('sffc_build_crm_jd_text_for_analysis')
                        ? (string) sffc_build_crm_jd_text_for_analysis($post)
                        : wp_strip_all_tags((string) ($post['content'] ?? $post['content_snippet'] ?? ''));
                    if (trim($jd_text) === '') {
                        $jd_text = wp_strip_all_tags((string) ($post['content'] ?? $post['content_snippet'] ?? $post['description_preview'] ?? ''));
                    }

                    $analysis = $this->build_crm_apply_chat_cv_analysis($cv_text, $jd_text, $post);
                    $analysis['standalone_context_role'] = [
                        'id' => (int) ($post['id'] ?? 0),
                        'source' => sanitize_key((string) ($post['source'] ?? 'crm')),
                        'role_title' => sanitize_text_field((string) ($post['role_title'] ?? '')),
                        'company' => sanitize_text_field((string) ($post['company'] ?? '')),
                        'location' => sanitize_text_field((string) ($post['location'] ?? '')),
                        'sector' => sanitize_text_field((string) ($post['sector'] ?? '')),
                        'target_role' => $target_role,
                    ];
                } else {
                    $analysis = $this->build_crm_apply_chat_cv_only_analysis($cv_text);
                    if ($target_role !== '') {
                        $analysis['target_role'] = $target_role;
                    }
                }
            }

            $send_json(true, [
                'file_name' => $file_name,
                'role_title' => (string) ($post['role_title'] ?? ''),
                'company' => (string) ($post['company'] ?? ''),
                'jobs_post_id' => $jobs_post_id,
                'cv_text' => $cv_text,
                'analysis' => $analysis,
            ]);
        }

        public function ajax_crm_apply_chat_request_human_followup()
        {
            check_ajax_referer('sffc_crm_apply_chat_request_human_followup', 'nonce');

            $session_token = isset($_POST['session_token']) ? sanitize_text_field(wp_unslash((string) $_POST['session_token'])) : '';
            $post_id = absint($_POST['post_id'] ?? 0);
            $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
            $role_title = sanitize_text_field(wp_unslash((string) ($_POST['role_title'] ?? '')));
            $message = sanitize_textarea_field(wp_unslash((string) ($_POST['message'] ?? '')));
            $active_path = sanitize_text_field(wp_unslash((string) ($_POST['active_path'] ?? '')));
            $prompt_state = sanitize_text_field(wp_unslash((string) ($_POST['prompt_state'] ?? '')));
            $page_url = esc_url_raw(wp_unslash((string) ($_POST['page_url'] ?? '')));
            $conversation_focus = sanitize_text_field(wp_unslash((string) ($_POST['conversation_focus'] ?? '')));
            $cv_profile = sanitize_text_field(wp_unslash((string) ($_POST['cv_profile'] ?? '')));
            $context_summary = sanitize_textarea_field(wp_unslash((string) ($_POST['context_summary'] ?? '')));
            $preferred_email = sanitize_email(wp_unslash((string) ($_POST['preferred_email'] ?? '')));
            $full_name = sanitize_text_field(wp_unslash((string) ($_POST['full_name'] ?? '')));
            $request_kind = sanitize_key(wp_unslash((string) ($_POST['request_kind'] ?? 'general_handoff')));
            if ($request_kind === '') {
                $request_kind = 'general_handoff';
            }

            if ($role_title === '' && $post_id > 0 && class_exists('SFFC_CRM_Post')) {
                $post_model = new SFFC_CRM_Post();
                $post = $post_model->get_full_detail($post_id, get_current_user_id());
                if (!empty($post) && is_array($post)) {
                    $role_title = sanitize_text_field((string) ($post['role_title'] ?? ''));
                }
            }
            if ($jobs_post_id <= 0 && $post_id > 0 && get_post_type($post_id) === 'jobs') {
                $jobs_post_id = $post_id;
            }
            if ($role_title === '' && $jobs_post_id > 0) {
                $job_item = (array) $this->get_crm_reddit_jobs_item($jobs_post_id);
                $role_title = sanitize_text_field((string) ($job_item['role_title'] ?? get_the_title($jobs_post_id)));
            }

            $admin_email = (string) apply_filters(
                'sffc_crm_apply_chat_handoff_email',
                get_option('admin_email'),
                $post_id,
                $role_title
