            if ($admin_email === '' || !is_email($admin_email)) {
                wp_send_json_error(['message' => __('I could not find the right contact email for that just now.', 'senna-finance')], 500);
            }

            $current_user = wp_get_current_user();
            $user_email = '';
            $display_name = '';

            if ($current_user instanceof WP_User && $current_user->exists()) {
                $user_email = sanitize_email((string) $current_user->user_email);
                $display_name = sanitize_text_field((string) $current_user->display_name);
            }

            $subject_role = $role_title !== '' ? $role_title : __('role enquiry', 'senna-finance');
