                $subject_prefix = __('Priority: live join requested', 'senna-finance');
            } elseif ($request_kind === 'apply_for_me') {
                $subject_prefix = __('Get Hired request', 'senna-finance');
            } elseif ($request_kind === 'greenhouse_browser_submit') {
                $subject_prefix = __('Greenhouse application workspace', 'senna-finance');
            } elseif (strpos($request_kind, 'recruiter_outreach_discovery') === 0) {
                $subject_prefix = __('Recruiter outreach brief', 'senna-finance');
            } else {
                $subject_prefix = __('MENA Careers apply chat handoff', 'senna-finance');
            }
            $subject = sprintf('%s - %s', $subject_prefix, $subject_role);

            $meta_rows = [
                __('Role', 'senna-finance') => $role_title !== '' ? $role_title : __('Unknown', 'senna-finance'),
                __('Post ID', 'senna-finance') => $post_id > 0 ? (string) $post_id : __('Unknown', 'senna-finance'),
                __('Jobs post ID', 'senna-finance') => $jobs_post_id > 0 ? (string) $jobs_post_id : __('Unknown', 'senna-finance'),
                __('Active path', 'senna-finance') => $active_path !== '' ? $active_path : __('Unknown', 'senna-finance'),
                __('Prompt state', 'senna-finance') => $prompt_state !== '' ? $prompt_state : __('Unknown', 'senna-finance'),
                __('Conversation focus', 'senna-finance') => $conversation_focus !== '' ? $conversation_focus : __('Unknown', 'senna-finance'),
                __('CV profile', 'senna-finance') => $cv_profile !== '' ? $cv_profile : __('Unknown', 'senna-finance'),
                __('Preferred email', 'senna-finance') => $preferred_email !== '' ? $preferred_email : __('Not provided', 'senna-finance'),
                __('Full name', 'senna-finance') => $full_name !== '' ? $full_name : __('Not provided', 'senna-finance'),
                __('WordPress user', 'senna-finance') => $display_name !== '' ? $display_name : __('Guest', 'senna-finance'),
                __('User email', 'senna-finance') => $user_email !== '' ? $user_email : __('Not available', 'senna-finance'),
                __('Requested at', 'senna-finance') => current_time('mysql'),
