            $message_html = nl2br(esc_html($message !== '' ? $message : __('No message provided.', 'senna-finance')));
            $context_html = nl2br(esc_html($context_summary !== '' ? $context_summary : __('No additional context captured.', 'senna-finance')));
            if ($request_kind === 'real_person') {
