                    '<div style="max-width:760px;margin:0 auto;background:#ffffff;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden;">' .
                        '<div style="padding:20px 24px;background:#162d55;color:#ffffff;">' .
                            '<div style="font-size:12px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.85;">' . esc_html__('MENA Careers Apply Chat', 'senna-finance') . '</div>' .
                            '<div style="margin-top:6px;font-size:24px;font-weight:700;line-height:1.2;">' . esc_html($subject_prefix) . '</div>' .
                            '<div style="margin-top:10px;display:inline-block;padding:6px 10px;border-radius:999px;background:#ffef9f;color:#24303f;font-size:12px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;">' . esc_html__('Needs attention', 'senna-finance') . '</div>' .
