                            '<div style="margin:0 0 18px;padding:16px 18px;background:#f8fafc;border:1px solid #e7ebf0;border-radius:8px;">' .
                                '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#617085;margin-bottom:8px;">' . esc_html__('Page URL', 'senna-finance') . '</div>' .
                                '<div style="font-size:15px;line-height:1.5;">' . $page_url_html . '</div>' .
                            '</div>' .
                            '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 18px;border:1px solid #e7ebf0;border-radius:8px;overflow:hidden;">' .
                                $meta_html .
                            '</table>' .
                            '<div style="margin:0 0 18px;padding:16px 18px;background:#fff8de;border:1px solid #f0e1a0;border-radius:8px;">' .
                                '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#7a6517;margin-bottom:8px;">' . esc_html__('User message', 'senna-finance') . '</div>' .
                                '<div style="font-size:16px;line-height:1.6;color:#16202d;">' . $message_html . '</div>' .
                            '</div>' .
                            '<div style="padding:16px 18px;background:#f8fafc;border:1px solid #e7ebf0;border-radius:8px;">' .
                                '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#617085;margin-bottom:8px;">' . esc_html__('Context summary', 'senna-finance') . '</div>' .
                                '<div style="font-size:15px;line-height:1.7;color:#24303f;">' . $context_html . '</div>' .
                            '</div>' .
                        '</div>' .
                    '</div>' .
                '</div>';

            $headers = ['Content-Type: text/html; charset=UTF-8'];
            if ($user_email !== '' && is_email($user_email)) {
                $headers[] = 'Reply-To: ' . $user_email;
            } elseif ($preferred_email !== '' && is_email($preferred_email)) {
                $headers[] = 'Reply-To: ' . $preferred_email;
            }

            $sent = wp_mail($admin_email, $subject, $email_html, $headers);

            if (!$sent) {
                wp_send_json_error(['message' => __('I could not send that through automatically just now.', 'senna-finance')], 500);
            }

            $user_confirmation_sent = false;
            $confirmation_email = $preferred_email !== '' && is_email($preferred_email)
                ? $preferred_email
                : ($user_email !== '' && is_email($user_email) ? $user_email : '');
            if ($request_kind === 'apply_for_me' && $confirmation_email !== '') {
                $candidate_name = $full_name !== '' ? $full_name : ($display_name !== '' ? $display_name : __('there', 'senna-finance'));
                $candidate_subject = sprintf(
                    __('Your first Apply for Me request is submitted - %s', 'senna-finance'),
                    $subject_role
                );
                $candidate_html =
                    '<div style="margin:0;padding:24px;background:#f5f7fa;font-family:Arial,sans-serif;color:#16202d;">' .
                        '<div style="max-width:680px;margin:0 auto;background:#ffffff;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden;">' .
                            '<div style="padding:22px 26px;background:#162d55;color:#ffffff;">' .
                                '<div style="font-size:12px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.85;">' . esc_html__('MENA Careers', 'senna-finance') . '</div>' .
                                '<div style="margin-top:8px;font-size:24px;font-weight:700;line-height:1.2;">' . esc_html__('First application request submitted', 'senna-finance') . '</div>' .
                            '</div>' .
                            '<div style="padding:24px 26px;">' .
                                '<p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#24303f;">' .
                                    esc_html(sprintf(__('Hi %s, Emily has submitted your first Apply for Me request for %s.', 'senna-finance'), $candidate_name, $subject_role)) .
                                '</p>' .
                                '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 18px;border:1px solid #e7ebf0;border-radius:8px;overflow:hidden;">' .
                                    '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:160px;font-weight:600;color:#3a4759;">' . esc_html__('Role', 'senna-finance') . '</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">' . esc_html($subject_role) . '</td></tr>' .
                                    ($cv_profile !== '' ? '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:160px;font-weight:600;color:#3a4759;">' . esc_html__('CV', 'senna-finance') . '</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">' . esc_html($cv_profile) . '</td></tr>' : '') .
                                    ($page_url !== '' ? '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:160px;font-weight:600;color:#3a4759;">' . esc_html__('Chat link', 'senna-finance') . '</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;"><a href="' . esc_url($page_url) . '" style="color:#0f4c81;text-decoration:none;">' . esc_html__('Open chat', 'senna-finance') . '</a></td></tr>' : '') .
                                '</table>' .
                                '<p style="margin:0;font-size:15px;line-height:1.6;color:#4b5563;">' .
                                    esc_html__('Keep this email as your confirmation. If anything needs correcting, reply to this message and the team can pick it up from the same context.', 'senna-finance') .
                                '</p>' .
                            '</div>' .
                        '</div>' .
                    '</div>';
                $user_confirmation_sent = (bool) wp_mail(
                    $confirmation_email,
                    $candidate_subject,
                    $candidate_html,
                    [
                        'Content-Type: text/html; charset=UTF-8',
                        'Reply-To: MENA Careers Support <support.team@joinsenna.com>',
                    ]
                );
                if (!$user_confirmation_sent) {
                    wp_send_json_error(['message' => __('The application request was sent, but I could not send the confirmation email just now.', 'senna-finance')], 500);
                }
            }

            if ($session_token !== '') {
                $conversation = $this->get_crm_apply_chat_conversation_by_thread_id($this->get_crm_apply_chat_thread_id($session_token));
                if (!empty($conversation['id'])) {
                    $this->set_crm_apply_chat_conversation_label((int) $conversation['id'], 'priority_now', true);
                }
            }

            wp_send_json_success([
                'message' => $request_kind === 'real_person'
                    ? __('I have flagged this as priority and sent it to the team. If someone is online, they should join shortly.', 'senna-finance')
                    : ($request_kind === 'greenhouse_browser_submit'
                        ? __('I have opened the Greenhouse application workspace.', 'senna-finance')
                    : ($request_kind === 'apply_for_me'
                        ? __('I have submitted the first Apply for Me application request.', 'senna-finance')
                        : __('I have sent that across, so someone should pick it up shortly.', 'senna-finance'))),
                'user_confirmation_sent' => $user_confirmation_sent,
            ]);
        }

        private function normalize_crm_apply_chat_uploaded_files($files)
        {
            $normalized = [];
            if (!is_array($files) || empty($files['name'])) {
                return $normalized;
            }

            if (!is_array($files['name'])) {
                return [$files];
            }

            foreach ((array) $files['name'] as $index => $name) {
                if ($name === '') {
                    continue;
                }
                $normalized[] = [
                    'name' => $files['name'][$index] ?? '',
                    'type' => $files['type'][$index] ?? '',
                    'tmp_name' => $files['tmp_name'][$index] ?? '',
                    'error' => $files['error'][$index] ?? 0,
                    'size' => $files['size'][$index] ?? 0,
                ];
            }

            return $normalized;
        }

        private function upload_crm_apply_chat_attachments($files)
        {
            $attachments = [];
            $attachment_html = '';
            $normalized = $this->normalize_crm_apply_chat_uploaded_files($files);
            if (empty($normalized)) {
                return [
                    'attachments' => [],
                    'html' => '',
                ];
            }

            require_once ABSPATH . 'wp-admin/includes/file.php';
            foreach ($normalized as $file) {
                $upload = wp_handle_upload($file, ['test_form' => false]);
                if (!empty($upload['error'])) {
                    return new WP_Error('upload_failed', sanitize_text_field((string) $upload['error']));
                }
                $record = [
                    'name' => sanitize_file_name((string) ($file['name'] ?? basename((string) ($upload['file'] ?? '')))),
                    'url' => esc_url_raw((string) ($upload['url'] ?? '')),
                    'type' => sanitize_text_field((string) ($file['type'] ?? '')),
                ];
                $attachments[] = $record;
            }

            if (!empty($attachments)) {
                $links = array_map(static function ($item) {
                    return '<li><a href="' . esc_url((string) ($item['url'] ?? '')) . '" target="_blank" rel="noopener">' . esc_html((string) ($item['name'] ?? 'Attachment')) . '</a></li>';
                }, $attachments);
                $attachment_html = '<ul>' . implode('', $links) . '</ul>';
            }

            return [
                'attachments' => $attachments,
                'html' => $attachment_html,
            ];
        }

        private function get_crm_apply_chat_support_attachments(array $messages)
        {
            $items = [];
            foreach ($messages as $message) {
                $headers = (array) ($message['headers'] ?? []);
                if (empty($headers['support_attachment'])) {
                    continue;
                }
                $attachments = (array) ($message['attachments'] ?? []);
                foreach ($attachments as $attachment) {
                    $url = esc_url_raw((string) ($attachment['url'] ?? ''));
                    $name = sanitize_text_field((string) ($attachment['name'] ?? ''));
                    if ($url === '' || $name === '') {
                        continue;
                    }
                    $items[] = [
                        'name' => $name,
                        'url' => $url,
                        'type' => sanitize_text_field((string) ($attachment['type'] ?? '')),
                    ];
                }
            }

            return $items;
        }

        private function build_crm_apply_chat_matches_email(array $args = [])
        {
            $first_name = trim((string) ($args['first_name'] ?? ''));
            $role_title = trim((string) ($args['role_title'] ?? ''));
            $focus = trim((string) ($args['focus'] ?? ''));
            $cv_profile = trim((string) ($args['cv_profile'] ?? ''));
            $email_variant = trim((string) ($args['email_variant'] ?? 'job_search'));
            $support_mode = trim((string) ($args['support_mode'] ?? ''));
            $priority = trim((string) ($args['priority'] ?? ''));
            $route_summary = trim((string) ($args['route_summary'] ?? ''));
            $roles = array_values((array) ($args['roles'] ?? []));
            $language = strtolower(trim((string) ($args['language'] ?? 'en')));
            $job_description = trim((string) ($args['job_description'] ?? ''));
            $hero_role_url = trim((string) ($args['hero_role_url'] ?? ''));
            $applications_per_week = trim((string) ($args['applications_per_week'] ?? ''));
            $intros_per_week = trim((string) ($args['intros_per_week'] ?? ''));
            $lane_preference = trim((string) ($args['lane_preference'] ?? ''));
            $constraints_text = trim((string) ($args['constraints_text'] ?? ''));
            $highlight_text = trim((string) ($args['highlight_text'] ?? ''));
            $preferred_email = trim((string) ($args['preferred_email'] ?? ''));
            $is_arabic = $language === 'ar';
            $dir = $is_arabic ? 'rtl' : 'ltr';
            $align = $is_arabic ? 'right' : 'left';
            $date_label = wp_date('M d, Y');
            $briefing_number = strtoupper(substr(md5($first_name . '|' . $role_title . '|' . $focus), 0, 4));
            $terminal_url = esc_url(home_url('/terminal/'));
            $total_roles = count($roles);
            $remaining_roles = max(0, $total_roles - 1);

            // Get hero role (first role or the one matching hero_role_url)
            $hero_role = !empty($roles) ? $roles[0] : [];
            if ($hero_role_url !== '' && !empty($roles)) {
                foreach ($roles as $role) {
                    if (trim((string) ($role['url'] ?? '')) === $hero_role_url) {
                        $hero_role = $role;
                        break;
                    }
                }
            }

            $mask_email = static function ($email) {
                $email = sanitize_email((string) $email);
                if ($email === '' || strpos($email, '@') === false) {
                    return '';
                }
                [$local, $domain] = explode('@', $email, 2);
                $local = trim((string) $local);
                if ($local === '') {
                    return '***@' . $domain;
                }
                if (strlen($local) <= 2) {
                    return substr($local, 0, 1) . '***@' . $domain;
                }
                return substr($local, 0, 1) . '***' . substr($local, -1) . '@' . $domain;
            };

            // Format recruiter name as "First L."
            $format_recruiter_display_name = static function ($full_name) {
                $full_name = trim((string) $full_name);
                if ($full_name === '') {
                    return '';
                }
                $parts = preg_split('/\s+/', $full_name);
                $first_name = $parts[0] ?? '';
                $last_initial = '';
                if (isset($parts[1]) && strlen($parts[1]) > 0) {
                    $last_initial = strtoupper(substr($parts[1], 0, 1)) . '.';
                }
                return trim($first_name . ' ' . $last_initial);
            };

            // Extract hero role data
            $hero_title = trim((string) ($hero_role['title'] ?? $role_title));
            $hero_company = trim((string) ($hero_role['company'] ?? ''));
            $hero_location = trim((string) ($hero_role['location'] ?? ''));
            $hero_recruiter_name = trim((string) ($hero_role['recruiter_name'] ?? ''));
            $hero_recruiter_email = sanitize_email((string) ($hero_role['recruiter_email'] ?? ''));
            $hero_fit_summary = trim((string) ($hero_role['fit_summary'] ?? ''));
            $hero_url = esc_url((string) ($hero_role['url'] ?? $hero_role_url ?: $terminal_url));
            $hero_match_score = max(0, min(99, (int) ($hero_role['match_score'] ?? 0)));
            $hero_recruiter_display = $format_recruiter_display_name($hero_recruiter_name);
            $hero_masked_email = $mask_email($hero_recruiter_email);
            $is_apply_intro = in_array($email_variant, ['apply_intro', 'apply_intro_welcome'], true);
            $is_apply_intro_welcome = $email_variant === 'apply_intro_welcome';

            if ($is_apply_intro && $route_summary === '') {
                if ($is_arabic) {
                    $route_summary = 'إيميلي جاهزة لتبدأ العمل على هذا الدور من خلال هذا البريد.';
                } else {
                    $route_summary = 'Emily is ready to start working on this role from this inbox.';
                }
            }

            $next_steps = [];
            if ($is_apply_intro) {
                if ($support_mode === 'applications') {
                    $next_steps = $is_arabic
                        ? ['تجهيز التقديم لهذا الدور', 'إبراز أقوى النقاط من الـCV بشكل أوضح', 'إرسال التحديثات إلى هذا البريد']
                        : ['Shape the application around this role', 'Bring your strongest CV points through more clearly', 'Send updates to this inbox'];
                } elseif ($support_mode === 'intros') {
                    $next_steps = $is_arabic
                        ? ['تجهيز تعريف مباشر لهذا الدور', 'البدء بالنقطة التي اتفقنا عليها في الدردشة', 'إرسال التحديثات إلى هذا البريد']
                        : ['Prepare a direct intro for this role', 'Lead with the point we agreed on in chat', 'Send updates to this inbox'];
                } else {
                    $next_steps = $is_arabic
                        ? ['تجهيز التقديم لهذا الدور', 'تجهيز مسار التعريف في الوقت نفسه', 'إرسال التحديثات إلى هذا البريد']
                        : ['Prepare the application for this role', 'Keep the intro side ready at the same time', 'Send updates to this inbox'];
                }
                if ($priority === 'applications') {
