        public function ajax_crm_apply_chat_send_matches_email()
        {
            check_ajax_referer('sffc_crm_apply_chat_send_matches_email', 'nonce');

            $email = isset($_POST['email']) ? sanitize_email(wp_unslash((string) $_POST['email'])) : '';
            $full_name = sanitize_text_field(wp_unslash((string) ($_POST['full_name'] ?? '')));
            $role_title = sanitize_text_field(wp_unslash((string) ($_POST['role_title'] ?? '')));
            $focus = sanitize_text_field(wp_unslash((string) ($_POST['focus'] ?? '')));
            $cv_profile = sanitize_text_field(wp_unslash((string) ($_POST['cv_profile'] ?? '')));
            $language = strtolower(trim((string) wp_unslash($_POST['language'] ?? 'en')));
            $is_arabic = $language === 'ar';
            $email_variant = sanitize_key((string) wp_unslash($_POST['email_variant'] ?? 'job_search'));
            $support_mode = sanitize_key((string) wp_unslash($_POST['support_mode'] ?? ''));
            $priority = sanitize_key((string) wp_unslash($_POST['priority'] ?? ''));
            $route_summary = sanitize_text_field(wp_unslash((string) ($_POST['route_summary'] ?? '')));
            $applications_per_week = sanitize_text_field(wp_unslash((string) ($_POST['applications_per_week'] ?? '')));
            $intros_per_week = sanitize_text_field(wp_unslash((string) ($_POST['intros_per_week'] ?? '')));
            $lane_preference = sanitize_key((string) wp_unslash($_POST['lane_preference'] ?? ''));
            $constraints_text = sanitize_textarea_field(wp_unslash((string) ($_POST['constraints_text'] ?? '')));
            $highlight_text = sanitize_textarea_field(wp_unslash((string) ($_POST['highlight_text'] ?? '')));
            $preferred_email = sanitize_email(wp_unslash((string) ($_POST['preferred_email'] ?? '')));
            $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
            $hero_role_url = isset($_POST['hero_role_url']) ? esc_url_raw(wp_unslash((string) $_POST['hero_role_url'])) : '';
            $roles_raw = isset($_POST['roles']) ? json_decode(wp_unslash((string) $_POST['roles']), true) : [];
            $recruiters_raw = isset($_POST['recruiters']) ? json_decode(wp_unslash((string) $_POST['recruiters']), true) : [];

            // Fetch job description from post if available
            $job_description = '';
            if ($post_id > 0) {
                $post = get_post($post_id);
                if ($post && $post->post_content) {
                    $job_description = $post->post_content;
                    // Strip the MENA Careers description block
                    $job_description = preg_replace('/<h3[^>]*>\s*About MENA Careers\s*<\/h3>.*$/is', '', $job_description);
                    $job_description = trim($job_description);
                }
            }

            if ($email === '' || !is_email($email)) {
                wp_send_json_error(['message' => $is_arabic ? 'من فضلك أدخل بريدًا إلكترونيًا صحيحًا.' : __('Please enter a valid email address.', 'senna-finance')], 422);
            }

            $roles = [];
            foreach (array_slice((array) $roles_raw, 0, 6) as $role) {
                if (!is_array($role)) {
                    continue;
                }
                $title = sanitize_text_field((string) ($role['title'] ?? ''));
                $url = esc_url_raw((string) ($role['url'] ?? ''));
                if ($title === '' || $url === '') {
                    continue;
                }
                $roles[] = [
                    'title' => $title,
                    'company' => sanitize_text_field((string) ($role['company'] ?? '')),
                    'location' => sanitize_text_field((string) ($role['location'] ?? '')),
                    'seniority' => sanitize_text_field((string) ($role['seniority'] ?? '')),
                    'sector' => sanitize_text_field((string) ($role['sector'] ?? '')),
                    'salary' => sanitize_text_field((string) ($role['salary'] ?? '')),
                    'company_descriptor' => sanitize_text_field((string) ($role['company_descriptor'] ?? '')),
                    'fit_summary' => sanitize_text_field((string) ($role['fit_summary'] ?? '')),
                    'fit_label' => sanitize_text_field((string) ($role['fit_label'] ?? '')),
                    'match_score' => max(0, min(99, (int) ($role['match_score'] ?? 0))),
                    'recruiter_initials' => sanitize_text_field((string) ($role['recruiter_initials'] ?? '')),
                    'recent_role_title' => sanitize_text_field((string) ($role['recent_role_title'] ?? '')),
                    'recruiter_name' => sanitize_text_field((string) ($role['recruiter_name'] ?? '')),
                    'recruiter_title' => sanitize_text_field((string) ($role['recruiter_title'] ?? '')),
                    'recruiter_company' => sanitize_text_field((string) ($role['recruiter_company'] ?? '')),
                    'recruiter_location' => sanitize_text_field((string) ($role['recruiter_location'] ?? '')),
                    'recruiter_regions' => sanitize_text_field((string) ($role['recruiter_regions'] ?? '')),
                    'recruiter_email' => sanitize_email((string) ($role['recruiter_email'] ?? '')),
                    'recruiter_phone' => sanitize_text_field((string) ($role['recruiter_phone'] ?? '')),
                    'recruiter_linkedin' => esc_url_raw((string) ($role['recruiter_linkedin'] ?? '')),
                    'url' => $url,
                ];
            }

            if (empty($roles)) {
                wp_send_json_error(['message' => __('There are no matching roles ready to send yet.', 'senna-finance')], 422);
            }

            $recruiters = [];
            foreach (array_slice((array) $recruiters_raw, 0, 3) as $recruiter) {
                if (!is_array($recruiter)) {
                    continue;
                }
                $name = sanitize_text_field((string) ($recruiter['name'] ?? ''));
                if ($name === '') {
                    continue;
                }
                $recruiters[] = [
                    'name' => $name,
                    'title' => sanitize_text_field((string) ($recruiter['title'] ?? '')),
                    'company' => sanitize_text_field((string) ($recruiter['company'] ?? '')),
                    'location' => sanitize_text_field((string) ($recruiter['location'] ?? '')),
                    'regions' => sanitize_text_field((string) ($recruiter['regions'] ?? '')),
                ];
            }

            $first_name = '';
            if ($full_name !== '') {
                $parts = preg_split('/\s+/', $full_name);
                $first_name = sanitize_text_field((string) ($parts[0] ?? ''));
            }

            // Extract location from first role or recruiters for email subject
            $email_location = '';
            if (!empty($roles[0]['location'])) {
                $email_location = $roles[0]['location'];
            } elseif (!empty($recruiters[0]['location'])) {
                $email_location = $recruiters[0]['location'];
            }

            if ($email_variant === 'apply_intro_welcome') {
                if ($is_arabic) {
                    $subject = $role_title !== ''
                        ? sprintf('كل شيء جاهز الآن: %s', $role_title)
                        : 'كل شيء جاهز الآن';
                } else {
                    $subject = $role_title !== ''
                        ? sprintf(__('Everything is set now: %s', 'senna-finance'), $role_title)
                        : __('Everything is set now', 'senna-finance');
                }
            } elseif ($email_variant === 'apply_intro') {
                if ($is_arabic) {
                    $subject = $role_title !== ''
                        ? sprintf('إيميلي جاهزة لتبدأ: %s', $role_title)
                        : 'إيميلي جاهزة لتبدأ';
                } else {
                    $subject = $role_title !== ''
                        ? sprintf(__('Emily is ready to start: %s', 'senna-finance'), $role_title)
                        : __('Emily is ready to start', 'senna-finance');
                }
            } elseif ($is_arabic) {
                $subject = $role_title !== '' && $email_location !== ''
                    ? sprintf('جهات التوظيف توظّف لوظيفة %s في %s', $role_title, $email_location)
                    : ($role_title !== ''
                        ? sprintf('جهات التوظيف توظّف لوظيفة %s', $role_title)
                        : 'جهات التوظيف توظّف لملفك');
            } else {
                $subject = $role_title !== '' && $email_location !== ''
                    ? sprintf(__('Recruiters hiring for %s in %s', 'senna-finance'), $role_title, $email_location)
                    : ($role_title !== ''
                        ? sprintf(__('Recruiters hiring for %s', 'senna-finance'), $role_title)
                        : __('Recruiters hiring for your profile', 'senna-finance'));
            }

            $html = $this->build_crm_apply_chat_matches_email([
                'first_name' => $first_name,
                'role_title' => $role_title,
                'focus' => $focus,
                'cv_profile' => $cv_profile,
                'email_variant' => $email_variant,
                'support_mode' => $support_mode,
                'priority' => $priority,
                'route_summary' => $route_summary,
                'roles' => $roles,
                'recruiters' => $recruiters,
                'language' => $language,
                'job_description' => $job_description,
                'hero_role_url' => $hero_role_url,
                'post_id' => $post_id,
                'applications_per_week' => $applications_per_week,
                'intros_per_week' => $intros_per_week,
                'lane_preference' => $lane_preference,
                'constraints_text' => $constraints_text,
                'highlight_text' => $highlight_text,
                'preferred_email' => $preferred_email,
            ]);

            $headers = [
                'Content-Type: text/html; charset=UTF-8',
                'From: Emily at MENA Careers <support.team@joinsenna.com>',
                'Reply-To: Emily at MENA Careers <support.team@joinsenna.com>',
            ];

            $sent = wp_mail($email, $subject, $html, $headers);
            if (!$sent) {
                wp_send_json_error(['message' => $is_arabic ? 'ما قدرنا نرسل هذا البريد الآن.' : __('We could not send that email just now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => $is_arabic ? 'تم إرسال أول دفعة لك.' : __('The first batch has been sent.', 'senna-finance'),
            ]);
        }

        public function ajax_crm_apply_chat_get_auto_submit_schema()
        {
            check_ajax_referer('sffc_crm_apply_chat_get_auto_submit_schema', 'nonce');

            $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
            $crm_post_id = absint($_POST['post_id'] ?? ($_POST['crm_post_id'] ?? 0));
            if ($jobs_post_id <= 0 && $crm_post_id > 0) {
                $jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($crm_post_id);
            }
            if ($jobs_post_id <= 0 || get_post_type($jobs_post_id) !== 'jobs') {
                wp_send_json_error(['message' => __('I could not find the linked job post for this application.', 'senna-finance')], 404);
            }

            $auto_submit = $this->get_crm_apply_chat_auto_submit_payload($jobs_post_id);
            if (empty($auto_submit['supported'])) {
                wp_send_json_error(['message' => __('This role is not set up for the application workspace yet.', 'senna-finance')], 422);
            }

            $schema_raw = get_post_meta($jobs_post_id, '_sffc_auto_submit_schema', true);
            $schema = [];
            if (is_string($schema_raw) && trim($schema_raw) !== '') {
                $decoded = json_decode($schema_raw, true);
                $schema = is_array($decoded) ? $decoded : [];
            } elseif (is_array($schema_raw)) {
                $schema = $schema_raw;
            }

            if (empty($schema) && $auto_submit['provider'] === 'greenhouse') {
                $schema = $this->fetch_crm_apply_chat_greenhouse_schema_from_hosted_url($jobs_post_id);
            }
            if (empty($schema) && $auto_submit['provider'] === 'successfactors') {
                $schema = $this->fetch_crm_apply_chat_successfactors_schema_from_job_url($jobs_post_id);
            }

            if (empty($schema)) {
                wp_send_json_error(['message' => __('I can see this role has an application workspace, but the application question schema is missing.', 'senna-finance')], 404);
            }

            $questions = [];
            $schema_questions = array_merge(
                (array) ($schema['questions'] ?? []),
                (array) ($schema['location_questions'] ?? [])
            );
            foreach ($schema_questions as $question) {
                if (!is_array($question)) {
                    continue;
                }
                $fields = [];
                foreach ((array) ($question['fields'] ?? []) as $field) {
                    if (!is_array($field)) {
                        continue;
                    }
                    $values = [];
                    foreach ((array) ($field['values'] ?? []) as $value) {
                        if (!is_array($value)) {
                            continue;
                        }
                        $values[] = [
                            'value' => sanitize_text_field((string) ($value['value'] ?? '')),
                            'label' => sanitize_text_field((string) ($value['label'] ?? '')),
                        ];
                    }
                    $fields[] = [
                        'name' => sanitize_text_field((string) ($field['name'] ?? '')),
                        'type' => sanitize_key((string) ($field['type'] ?? '')),
                        'values' => $values,
                    ];
                }
                $questions[] = [
                    'label' => sanitize_text_field((string) ($question['label'] ?? '')),
                    'description' => sanitize_textarea_field((string) ($question['description'] ?? '')),
                    'required' => !empty($question['required']),
                    'fields' => $fields,
                ];
            }

            wp_send_json_success([
                'provider' => sanitize_key((string) ($schema['provider'] ?? $auto_submit['provider'] ?? '')),
                'jobs_post_id' => $jobs_post_id,
                'board_token' => sanitize_text_field((string) ($schema['board_token'] ?? $auto_submit['greenhouse_board_token'] ?? '')),
                'job_id' => sanitize_text_field((string) ($schema['job_id'] ?? $auto_submit['greenhouse_job_id'] ?? '')),
                'submit_url' => esc_url_raw((string) ($schema['submit_url'] ?? '')),
                'hosted_url' => esc_url_raw((string) ($schema['hosted_url'] ?? '')),
                'application_embed_url' => esc_url_raw((string) ($schema['application_embed_url'] ?? ($schema['hosted_url'] ?? ''))),
                'schema_url' => esc_url_raw((string) ($schema['schema_url'] ?? '')),
                'required_question_count' => count(array_filter($questions, static function ($question) {
                    return is_array($question) && !empty($question['required']);
                })),
                'field_count' => absint($schema['field_count'] ?? 0),
                'questions' => $questions,
            ]);
        }

        public function maybe_create_crm_application_tasks_table()
        {
            global $wpdb;

            $installed_version = (string) get_option('sffc_crm_application_tasks_schema_version', '');
            if ($installed_version === '1') {
                return;
            }
            if (!function_exists('dbDelta')) {
                require_once ABSPATH . 'wp-admin/includes/upgrade.php';
            }

            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $charset_collate = $wpdb->get_charset_collate();
            $sql = "CREATE TABLE $table (
                id bigint(20) NOT NULL AUTO_INCREMENT,
                task_uuid varchar(64) NOT NULL,
                status varchar(40) DEFAULT 'queued',
                provider varchar(80) DEFAULT NULL,
                session_token varchar(191) DEFAULT NULL,
                conversation_id bigint(20) DEFAULT NULL,
                user_id bigint(20) DEFAULT 0,
                wp_post_id bigint(20) DEFAULT 0,
                crm_post_id bigint(20) DEFAULT 0,
                role_title varchar(255) DEFAULT NULL,
                company_name varchar(255) DEFAULT NULL,
                application_url varchar(1000) DEFAULT NULL,
                application_workspace_url varchar(1000) DEFAULT NULL,
                candidate_name varchar(200) DEFAULT NULL,
                candidate_email varchar(200) DEFAULT NULL,
                candidate_phone varchar(80) DEFAULT NULL,
                cv_file_name varchar(255) DEFAULT NULL,
                cv_file_url varchar(1000) DEFAULT NULL,
                cv_text longtext,
                cover_letter_requested tinyint(1) DEFAULT 0,
                worker_id varchar(120) DEFAULT NULL,
                locked_at datetime DEFAULT NULL,
                submitted_at datetime DEFAULT NULL,
                last_error text,
                evidence_url varchar(1000) DEFAULT NULL,
                screenshot_url varchar(1000) DEFAULT NULL,
                payload longtext,
                result_payload longtext,
                created_at datetime DEFAULT CURRENT_TIMESTAMP,
                updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                UNIQUE KEY unique_task_uuid (task_uuid),
                KEY idx_status (status),
                KEY idx_provider (provider),
                KEY idx_user (user_id),
                KEY idx_conversation (conversation_id),
                KEY idx_post (wp_post_id),
                KEY idx_locked (locked_at),
                KEY idx_created (created_at),
                KEY idx_email (candidate_email)
            ) $charset_collate;";

            dbDelta($sql);
            update_option('sffc_crm_application_tasks_schema_version', '1', false);
        }

        private function get_crm_application_worker_token()
        {
            if (defined('SFFC_APPLICATION_WORKER_TOKEN') && SFFC_APPLICATION_WORKER_TOKEN) {
                return (string) SFFC_APPLICATION_WORKER_TOKEN;
            }

            $env_token = getenv('SFFC_APPLICATION_WORKER_TOKEN');
            if (is_string($env_token) && trim($env_token) !== '') {
                return trim($env_token);
            }

            $token = (string) get_option('sffc_application_worker_token', '');
            if ($token === '') {
                $token = wp_generate_password(48, false, false);
                update_option('sffc_application_worker_token', $token, false);
            }

            return $token;
        }

        private function verify_crm_application_worker_token()
        {
            $expected = $this->get_crm_application_worker_token();
            $provided = '';
            if (!empty($_SERVER['HTTP_X_SFFC_WORKER_TOKEN'])) {
                $provided = sanitize_text_field(wp_unslash((string) $_SERVER['HTTP_X_SFFC_WORKER_TOKEN']));
            } elseif (isset($_POST['worker_token'])) {
                $provided = sanitize_text_field(wp_unslash((string) $_POST['worker_token']));
            }

            return $expected !== '' && $provided !== '' && hash_equals($expected, $provided);
        }

        private function save_crm_application_task_cv_upload()
        {
            if (empty($_FILES['cv_file']) || !is_array($_FILES['cv_file'])) {
                return ['name' => '', 'url' => ''];
            }

            $file = $_FILES['cv_file'];
            $allowed_types = [
                'pdf' => 'application/pdf',
                'doc' => 'application/msword',
                'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            ];
            $check = wp_check_filetype_and_ext((string) ($file['tmp_name'] ?? ''), (string) ($file['name'] ?? ''), $allowed_types);
            if (empty($check['ext']) || empty($check['type'])) {
                return ['name' => '', 'url' => ''];
            }

            if (!function_exists('wp_handle_upload')) {
                require_once ABSPATH . 'wp-admin/includes/file.php';
            }

            add_filter('upload_dir', [$this, 'filter_crm_application_task_upload_dir']);
            $upload = wp_handle_upload($file, [
                'test_form' => false,
                'mimes' => $allowed_types,
            ]);
            remove_filter('upload_dir', [$this, 'filter_crm_application_task_upload_dir']);

            if (!is_array($upload) || !empty($upload['error']) || empty($upload['url'])) {
                return ['name' => '', 'url' => ''];
            }

            return [
                'name' => sanitize_file_name((string) ($file['name'] ?? basename((string) $upload['file']))),
                'url' => esc_url_raw((string) $upload['url']),
            ];
        }

        public function filter_crm_application_task_upload_dir($dirs)
        {
            $dirs = is_array($dirs) ? $dirs : [];
            $subdir = '/sffc-application-tasks';
            $dirs['path'] = rtrim((string) ($dirs['basedir'] ?? ''), '/') . $subdir;
            $dirs['url'] = rtrim((string) ($dirs['baseurl'] ?? ''), '/') . $subdir;
            $dirs['subdir'] = $subdir;
            return $dirs;
        }

        public function ajax_crm_apply_chat_queue_application_task()
        {
            check_ajax_referer('sffc_crm_apply_chat_queue_application_task', 'nonce');

            global $wpdb;

            $this->maybe_create_crm_application_tasks_table();
            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
            if (!$table_exists) {
                wp_send_json_error(['message' => __('The application task queue is not available yet.', 'senna-finance')], 500);
            }

            $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
            $crm_post_id = absint($_POST['crm_post_id'] ?? ($_POST['post_id'] ?? 0));
            if ($jobs_post_id <= 0 && $crm_post_id > 0) {
                $jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($crm_post_id);
            }

            $candidate_name = sanitize_text_field(wp_unslash((string) ($_POST['candidate_name'] ?? '')));
            $candidate_email = sanitize_email(wp_unslash((string) ($_POST['candidate_email'] ?? '')));
            $application_url = esc_url_raw(wp_unslash((string) ($_POST['application_url'] ?? '')));
            $application_workspace_url = esc_url_raw(wp_unslash((string) ($_POST['application_workspace_url'] ?? '')));
            $provider = sanitize_key((string) wp_unslash($_POST['provider'] ?? ''));

            if ($jobs_post_id > 0 && get_post_type($jobs_post_id) === 'jobs') {
                if ($application_url === '') {
                    $application_url = $this->get_crm_apply_chat_jobs_application_url($jobs_post_id);
                }
                $auto_submit = $this->get_crm_apply_chat_auto_submit_payload($jobs_post_id);
                if ($application_workspace_url === '' && !empty($auto_submit['application_embed_url'])) {
                    $application_workspace_url = esc_url_raw((string) $auto_submit['application_embed_url']);
                }
                if ($provider === '' && !empty($auto_submit['provider'])) {
                    $provider = sanitize_key((string) $auto_submit['provider']);
                }
            }

            if ($candidate_name === '' || $candidate_email === '' || !is_email($candidate_email)) {
                wp_send_json_error(['message' => __('I need the candidate name and a valid email before I can queue this application.', 'senna-finance')], 422);
            }
            if ($application_url === '' && $application_workspace_url === '') {
                wp_send_json_error(['message' => __('I need an employer application URL before I can queue this application.', 'senna-finance')], 422);
            }

            $session_token = sanitize_text_field(wp_unslash((string) ($_POST['session_token'] ?? '')));
            $role_title = sanitize_text_field(wp_unslash((string) ($_POST['role_title'] ?? '')));
            $company_name = sanitize_text_field(wp_unslash((string) ($_POST['company_name'] ?? '')));
            $candidate_phone = sanitize_text_field(wp_unslash((string) ($_POST['candidate_phone'] ?? '')));
            $cv_text = sanitize_textarea_field(wp_unslash((string) ($_POST['cv_text'] ?? '')));
            $cover_letter_requested = rest_sanitize_boolean(wp_unslash((string) ($_POST['cover_letter_requested'] ?? '0')));
            $page_url = esc_url_raw(wp_unslash((string) ($_POST['page_url'] ?? '')));
            $conversation_id = $this->find_or_create_crm_apply_chat_conversation($session_token, $crm_post_id ?: $jobs_post_id, $role_title, $page_url);
            $cv_upload = $this->save_crm_application_task_cv_upload();
            $task_uuid = wp_generate_uuid4();
            $payload = [
                'page_url' => $page_url,
                'role_url' => esc_url_raw(wp_unslash((string) ($_POST['role_url'] ?? ''))),
                'source' => 'apply_chat',
                'consent' => sanitize_text_field(wp_unslash((string) ($_POST['consent'] ?? 'candidate_clicked_apply_for_me'))),
                'application_schema' => [],
                'application_answers' => [],
                'verification_code' => sanitize_text_field(wp_unslash((string) ($_POST['verification_code'] ?? ''))),
            ];

            $application_answers_raw = wp_unslash((string) ($_POST['application_answers'] ?? '{}'));
            $application_answers_decoded = json_decode($application_answers_raw, true);
            if (is_array($application_answers_decoded)) {
                foreach ($application_answers_decoded as $answer_key => $answer_value) {
                    $clean_key = sanitize_text_field((string) $answer_key);
                    if ($clean_key === '') {
                        continue;
                    }
                    $payload['application_answers'][$clean_key] = is_array($answer_value)
                        ? array_map('sanitize_text_field', array_map('strval', $answer_value))
                        : sanitize_text_field((string) $answer_value);
                }
            }

            $schema_raw = $jobs_post_id > 0 ? get_post_meta($jobs_post_id, '_sffc_auto_submit_schema', true) : '';
            if (is_string($schema_raw) && trim($schema_raw) !== '') {
                $decoded = json_decode($schema_raw, true);
                if (is_array($decoded)) {
                    $payload['application_schema'] = $decoded;
                }
            } elseif (is_array($schema_raw)) {
                $payload['application_schema'] = $schema_raw;
            }
            if (empty($payload['application_schema']) && $jobs_post_id > 0 && $provider === 'greenhouse') {
                $schema = $this->fetch_crm_apply_chat_greenhouse_schema_from_hosted_url($jobs_post_id);
                if (!empty($schema)) {
                    $payload['application_schema'] = $schema;
                }
            }
            if (empty($payload['application_schema']) && $jobs_post_id > 0 && $provider === 'successfactors') {
                $schema = $this->fetch_crm_apply_chat_successfactors_schema_from_job_url($jobs_post_id);
                if (!empty($schema)) {
                    $payload['application_schema'] = $schema;
                }
            }

            $inserted = $wpdb->insert($table, [
                'task_uuid' => $task_uuid,
                'status' => 'queued',
                'provider' => $provider,
                'session_token' => $session_token,
                'conversation_id' => $conversation_id > 0 ? $conversation_id : null,
                'user_id' => get_current_user_id(),
                'wp_post_id' => $jobs_post_id,
                'crm_post_id' => $crm_post_id,
                'role_title' => $role_title,
                'company_name' => $company_name,
                'application_url' => $application_url,
                'application_workspace_url' => $application_workspace_url,
                'candidate_name' => $candidate_name,
                'candidate_email' => $candidate_email,
                'candidate_phone' => $candidate_phone,
                'cv_file_name' => $cv_upload['name'],
                'cv_file_url' => $cv_upload['url'],
                'cv_text' => $cv_text,
                'cover_letter_requested' => $cover_letter_requested ? 1 : 0,
                'payload' => wp_json_encode($payload),
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ]);

            if (!$inserted) {
                wp_send_json_error(['message' => __('I could not queue this application task just now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'task_uuid' => $task_uuid,
                'status' => 'queued',
                'message' => __('I have queued this for the application worker.', 'senna-finance'),
            ]);
        }

        public function ajax_crm_apply_chat_application_task_status()
        {
            check_ajax_referer('sffc_crm_apply_chat_queue_application_task', 'nonce');

            global $wpdb;

            $this->maybe_create_crm_application_tasks_table();
            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $task_uuid = sanitize_text_field(wp_unslash((string) ($_POST['task_uuid'] ?? '')));
            $session_token = sanitize_text_field(wp_unslash((string) ($_POST['session_token'] ?? '')));
            if ($task_uuid === '') {
                wp_send_json_error(['message' => __('Missing application task ID.', 'senna-finance')], 422);
            }

            $task = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT task_uuid, status, session_token, user_id, role_title, company_name, provider, last_error, submitted_at, result_payload, updated_at FROM {$table} WHERE task_uuid = %s LIMIT 1",
                    $task_uuid
                ),
                ARRAY_A
            );
            if (!is_array($task)) {
                wp_send_json_error(['message' => __('Application task not found.', 'senna-finance')], 404);
            }

            $current_user_id = get_current_user_id();
            $task_user_id = absint($task['user_id'] ?? 0);
            $task_session_token = sanitize_text_field((string) ($task['session_token'] ?? ''));
            $can_view = ($current_user_id > 0 && $task_user_id > 0 && $current_user_id === $task_user_id)
                || ($session_token !== '' && $task_session_token !== '' && hash_equals($task_session_token, $session_token));
            if (!$can_view) {
                wp_send_json_error(['message' => __('You do not have access to this application task.', 'senna-finance')], 403);
            }

            $result_payload = [];
            if (is_string($task['result_payload'] ?? '') && trim((string) $task['result_payload']) !== '') {
                $decoded = json_decode((string) $task['result_payload'], true);
                $result_payload = is_array($decoded) ? $decoded : [];
            }

            wp_send_json_success([
                'task_uuid' => sanitize_text_field((string) ($task['task_uuid'] ?? '')),
                'status' => sanitize_key((string) ($task['status'] ?? 'queued')),
                'role_title' => sanitize_text_field((string) ($task['role_title'] ?? '')),
                'company_name' => sanitize_text_field((string) ($task['company_name'] ?? '')),
                'provider' => sanitize_key((string) ($task['provider'] ?? '')),
                'last_error' => sanitize_textarea_field((string) ($task['last_error'] ?? '')),
                'submitted_at' => sanitize_text_field((string) ($task['submitted_at'] ?? '')),
                'final_url' => esc_url_raw((string) ($result_payload['final_url'] ?? '')),
                'uploaded_resume' => !empty($result_payload['uploaded_resume']),
                'submission_confirmed' => !empty($result_payload['submission_confirmed']),
                'verification_required' => !empty($result_payload['verification_required']),
                'application_answers_attempted' => absint($result_payload['application_answers_attempted'] ?? 0),
                'application_answers_filled' => absint($result_payload['application_answers_filled'] ?? 0),
                'application_choice_answers_attempted' => absint($result_payload['application_choice_answers_attempted'] ?? 0),
                'application_choice_answers_filled' => absint($result_payload['application_choice_answers_filled'] ?? 0),
                'validation_errors' => array_map('sanitize_text_field', array_slice((array) ($result_payload['validation_errors'] ?? []), 0, 10)),
                'missing_required_fields' => array_map('sanitize_text_field', array_slice((array) ($result_payload['missing_required_fields'] ?? []), 0, 10)),
                'updated_at' => sanitize_text_field((string) ($task['updated_at'] ?? '')),
            ]);
        }

        public function ajax_crm_apply_chat_application_task_verification_code()
        {
            check_ajax_referer('sffc_crm_apply_chat_queue_application_task', 'nonce');

            global $wpdb;

            $this->maybe_create_crm_application_tasks_table();
            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $task_uuid = sanitize_text_field(wp_unslash((string) ($_POST['task_uuid'] ?? '')));
            $session_token = sanitize_text_field(wp_unslash((string) ($_POST['session_token'] ?? '')));
            $verification_code = sanitize_text_field(wp_unslash((string) ($_POST['verification_code'] ?? '')));
            if ($task_uuid === '' || $verification_code === '') {
                wp_send_json_error(['message' => __('Missing application task or verification code.', 'senna-finance')], 422);
            }

            $task = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT task_uuid, status, session_token, user_id, payload FROM {$table} WHERE task_uuid = %s LIMIT 1",
                    $task_uuid
                ),
                ARRAY_A
            );
            if (!is_array($task)) {
                wp_send_json_error(['message' => __('Application task not found.', 'senna-finance')], 404);
            }

            $current_user_id = get_current_user_id();
            $task_user_id = absint($task['user_id'] ?? 0);
            $task_session_token = sanitize_text_field((string) ($task['session_token'] ?? ''));
            $can_update = ($current_user_id > 0 && $task_user_id > 0 && $current_user_id === $task_user_id)
                || ($session_token !== '' && $task_session_token !== '' && hash_equals($task_session_token, $session_token));
            if (!$can_update) {
                wp_send_json_error(['message' => __('You do not have access to this application task.', 'senna-finance')], 403);
            }

            $payload = [];
            if (is_string($task['payload'] ?? '') && trim((string) $task['payload']) !== '') {
                $decoded = json_decode((string) $task['payload'], true);
                $payload = is_array($decoded) ? $decoded : [];
            }
            $payload['verification_code'] = $verification_code;
            $payload['verification_code_received_at'] = current_time('mysql');

            $updated = $wpdb->update($table, [
                'status' => sanitize_key((string) ($task['status'] ?? '')) === 'verification_required' ? 'processing' : sanitize_key((string) ($task['status'] ?? 'processing')),
                'last_error' => '',
                'payload' => wp_json_encode($payload),
                'updated_at' => current_time('mysql'),
            ], [
                'task_uuid' => $task_uuid,
            ]);

            if ($updated === false) {
                wp_send_json_error(['message' => __('Could not save the Greenhouse verification code.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'task_uuid' => $task_uuid,
                'status' => sanitize_key((string) ($task['status'] ?? 'verification_required')),
                'message' => __('I have added the verification code to the active application task.', 'senna-finance'),
            ]);
        }

        public function ajax_crm_application_worker_claim()
        {
            if (!$this->verify_crm_application_worker_token()) {
                wp_send_json_error(['message' => __('Invalid worker token.', 'senna-finance')], 403);
            }

            global $wpdb;
            $this->maybe_create_crm_application_tasks_table();
            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $worker_id = sanitize_text_field(wp_unslash((string) ($_POST['worker_id'] ?? 'sffc-worker')));
            $stale_cutoff = date('Y-m-d H:i:s', current_time('timestamp') - 20 * MINUTE_IN_SECONDS);
            $task = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT * FROM {$table} WHERE status = %s OR (status = %s AND locked_at < %s) ORDER BY created_at ASC LIMIT 1",
                    'queued',
                    'processing',
                    $stale_cutoff
                ),
                ARRAY_A
            );

            if (!is_array($task) || empty($task['id'])) {
                wp_send_json_success(['task' => null]);
            }

            $updated = $wpdb->query(
                $wpdb->prepare(
                    "UPDATE {$table}
                     SET status = %s, worker_id = %s, locked_at = %s, updated_at = %s
                     WHERE id = %d AND (status = %s OR (status = %s AND locked_at < %s))",
                    'processing',
                    $worker_id,
                    current_time('mysql'),
                    current_time('mysql'),
                    (int) $task['id'],
                    'queued',
                    'processing',
                    $stale_cutoff
                )
            );

            if ($updated === false) {
                wp_send_json_error(['message' => __('Could not lock application task.', 'senna-finance')], 500);
            }
            if ((int) $updated === 0) {
                wp_send_json_success(['task' => null]);
            }

            $task['status'] = 'processing';
            $task['worker_id'] = $worker_id;
            $task['payload'] = is_string($task['payload'] ?? '') ? json_decode((string) $task['payload'], true) : [];
            $task['result_payload'] = is_string($task['result_payload'] ?? '') ? json_decode((string) $task['result_payload'], true) : [];

            wp_send_json_success(['task' => $task]);
        }

        public function ajax_crm_application_worker_get_task()
        {
            if (!$this->verify_crm_application_worker_token()) {
                wp_send_json_error(['message' => __('Invalid worker token.', 'senna-finance')], 403);
            }

            global $wpdb;
            $this->maybe_create_crm_application_tasks_table();
