            wp_send_json_success(['task' => $task]);
        }

        public function ajax_crm_application_worker_complete()
        {
            if (!$this->verify_crm_application_worker_token()) {
                wp_send_json_error(['message' => __('Invalid worker token.', 'senna-finance')], 403);
            }

            global $wpdb;
            $this->maybe_create_crm_application_tasks_table();
            $table = $wpdb->prefix . 'sffc_crm_application_tasks';
            $task_uuid = sanitize_text_field(wp_unslash((string) ($_POST['task_uuid'] ?? '')));
            $status = sanitize_key((string) wp_unslash($_POST['status'] ?? ''));
            if (!in_array($status, ['submitted', 'failed', 'review_required', 'verification_required', 'dry_run_ready'], true)) {
                wp_send_json_error(['message' => __('Invalid task status.', 'senna-finance')], 422);
            }
            if ($task_uuid === '') {
                wp_send_json_error(['message' => __('Missing task UUID.', 'senna-finance')], 422);
            }

            $result_payload_raw = wp_unslash((string) ($_POST['result_payload'] ?? '{}'));
            $decoded = json_decode($result_payload_raw, true);
            $result_payload = is_array($decoded) ? $decoded : [];
            $updated = $wpdb->update($table, [
                'status' => $status,
                'last_error' => sanitize_textarea_field(wp_unslash((string) ($_POST['last_error'] ?? ''))),
                'evidence_url' => esc_url_raw(wp_unslash((string) ($_POST['evidence_url'] ?? ''))),
                'screenshot_url' => esc_url_raw(wp_unslash((string) ($_POST['screenshot_url'] ?? ''))),
                'result_payload' => wp_json_encode($result_payload),
                'submitted_at' => $status === 'submitted' ? current_time('mysql') : null,
                'updated_at' => current_time('mysql'),
            ], [
                'task_uuid' => $task_uuid,
            ]);

            if ($updated === false) {
                wp_send_json_error(['message' => __('Could not update application task.', 'senna-finance')], 500);
            }

            wp_send_json_success(['status' => $status]);
        }

        public function ajax_crm_apply_chat_capture_auto_apply_contact()
        {
            check_ajax_referer('sffc_crm_apply_chat_capture_auto_apply_contact', 'nonce');

            global $wpdb;

            $table_name = $wpdb->prefix . 'sffc_crm_auto_apply_contacts';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name;
            if (!$table_exists) {
                wp_send_json_error(['message' => __('Auto Apply Contacts is not available yet. Run the CRM schema update first.', 'senna-finance')], 500);
            }

            $session_token = sanitize_text_field(wp_unslash((string) ($_POST['session_token'] ?? '')));
            $post_id = absint($_POST['post_id'] ?? 0);
            $crm_post_id = absint($_POST['crm_post_id'] ?? 0);
            $role_title = sanitize_text_field(wp_unslash((string) ($_POST['role_title'] ?? '')));
            $company_name = sanitize_text_field(wp_unslash((string) ($_POST['company_name'] ?? '')));
            $preferred_email = sanitize_email(wp_unslash((string) ($_POST['preferred_email'] ?? '')));
            $full_name = sanitize_text_field(wp_unslash((string) ($_POST['full_name'] ?? '')));
            $support_mode = sanitize_key((string) wp_unslash($_POST['support_mode'] ?? ''));
            $applications_per_week = sanitize_text_field(wp_unslash((string) ($_POST['applications_per_week'] ?? '')));
            $intros_per_week = sanitize_text_field(wp_unslash((string) ($_POST['intros_per_week'] ?? '')));
            $lane_preference = sanitize_key((string) wp_unslash($_POST['lane_preference'] ?? ''));
            $priority_preference = sanitize_key((string) wp_unslash($_POST['priority_preference'] ?? ''));
            $constraints_text = sanitize_textarea_field(wp_unslash((string) ($_POST['constraints_text'] ?? '')));
            $highlight_text = sanitize_textarea_field(wp_unslash((string) ($_POST['highlight_text'] ?? '')));
            $target_roles = sanitize_text_field(wp_unslash((string) ($_POST['target_roles'] ?? '')));
            $target_sectors = sanitize_text_field(wp_unslash((string) ($_POST['target_sectors'] ?? '')));
            $preferred_market = sanitize_text_field(wp_unslash((string) ($_POST['preferred_market'] ?? '')));
            $route_summary = sanitize_textarea_field(wp_unslash((string) ($_POST['route_summary'] ?? '')));
            $membership_account_type = sanitize_key((string) wp_unslash($_POST['membership_account_type'] ?? ''));
            $membership_url = esc_url_raw(wp_unslash((string) ($_POST['membership_url'] ?? '')));
            $page_url = esc_url_raw(wp_unslash((string) ($_POST['page_url'] ?? '')));
            $status = sanitize_key((string) wp_unslash($_POST['status'] ?? 'signup_clicked'));
            if (!in_array($status, ['signup_clicked', 'signup_confirmed'], true)) {
                $status = 'signup_clicked';
            }

            if ($session_token === '' && $preferred_email === '' && $post_id <= 0) {
                wp_send_json_error(['message' => __('The auto apply contact payload was incomplete.', 'senna-finance')], 422);
            }

            if ($crm_post_id <= 0 && $post_id > 0) {
                $crm_post_id = absint(get_post_meta($post_id, '_crm_post_id', true));
            }

            $conversation_id = $this->find_or_create_crm_apply_chat_conversation($session_token, $post_id, $role_title, $page_url);
            $user_id = is_user_logged_in() ? get_current_user_id() : 0;
            $now = current_time('mysql');
            $payload = [
                'page_url' => $page_url,
                'support_mode' => $support_mode,
                'applications_per_week' => $applications_per_week,
                'intros_per_week' => $intros_per_week,
                'lane_preference' => $lane_preference,
                'priority_preference' => $priority_preference,
                'constraints_text' => $constraints_text,
                'highlight_text' => $highlight_text,
                'target_roles' => $target_roles,
                'target_sectors' => $target_sectors,
                'preferred_market' => $preferred_market,
                'route_summary' => $route_summary,
                'membership_account_type' => $membership_account_type,
                'membership_url' => $membership_url,
            ];

            $existing_id = 0;
            $existing_status = '';
            if ($session_token !== '' && $post_id > 0) {
                $existing_row = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT id, status FROM {$table_name} WHERE session_token = %s AND wp_post_id = %d LIMIT 1",
                        $session_token,
                        $post_id
                    ),
                    ARRAY_A
                );
                if (is_array($existing_row)) {
                    $existing_id = (int) ($existing_row['id'] ?? 0);
                    $existing_status = sanitize_key((string) ($existing_row['status'] ?? ''));
                }
            }

            $row_data = [
                'session_token' => $session_token,
                'conversation_id' => $conversation_id > 0 ? $conversation_id : null,
                'user_id' => $user_id,
                'wp_post_id' => $post_id,
                'crm_post_id' => $crm_post_id,
                'role_title' => $role_title,
                'company_name' => $company_name,
                'preferred_email' => $preferred_email,
                'full_name' => $full_name,
                'support_mode' => $support_mode,
                'applications_per_week' => $applications_per_week,
                'intros_per_week' => $intros_per_week,
                'lane_preference' => $lane_preference,
                'priority_preference' => $priority_preference,
                'constraints_text' => $constraints_text,
                'highlight_text' => $highlight_text,
                'target_roles' => $target_roles,
                'target_sectors' => $target_sectors,
                'preferred_market' => $preferred_market,
                'route_summary' => $route_summary,
                'membership_account_type' => $membership_account_type,
                'membership_url' => $membership_url,
                'status' => $status,
                'source' => 'apply_chat_auto_apply',
                'payload' => wp_json_encode($payload),
                'updated_at' => $now,
            ];
            if ($status === 'signup_confirmed') {
                $row_data['signup_completed_at'] = $now;
            } else {
                $row_data['signup_link_clicked_at'] = $now;
            }

            if ($existing_id > 0) {
                $wpdb->update($table_name, $row_data, ['id' => $existing_id]);
                $record_id = $existing_id;
            } else {
                $row_data['created_at'] = $now;
                $wpdb->insert($table_name, $row_data);
                $record_id = (int) $wpdb->insert_id;
            }

            if ($record_id <= 0) {
                wp_send_json_error(['message' => __('Could not save the Auto Apply contact.', 'senna-finance')], 500);
            }

            $should_send_admin_email = !($status === 'signup_confirmed' && $existing_id > 0 && $existing_status === 'signup_confirmed');
            $sent = false;
            if ($should_send_admin_email) {
                $sent = $this->send_auto_apply_contact_admin_email([
                'record_id' => $record_id,
                'session_token' => $session_token,
                'conversation_id' => $conversation_id,
                'user_id' => $user_id,
                'wp_post_id' => $post_id,
                'crm_post_id' => $crm_post_id,
                'role_title' => $role_title,
                'company_name' => $company_name,
                'preferred_email' => $preferred_email,
                'full_name' => $full_name,
                'support_mode' => $support_mode,
                'applications_per_week' => $applications_per_week,
                'intros_per_week' => $intros_per_week,
                'lane_preference' => $lane_preference,
                'priority_preference' => $priority_preference,
                'constraints_text' => $constraints_text,
                'highlight_text' => $highlight_text,
                'target_roles' => $target_roles,
                'target_sectors' => $target_sectors,
                'preferred_market' => $preferred_market,
                'route_summary' => $route_summary,
                'membership_account_type' => $membership_account_type,
                'membership_url' => $membership_url,
                'page_url' => $page_url,
                'is_update' => $existing_id > 0,
                'status' => $status,
                ]);
            }

            if ($sent) {
                $wpdb->update($table_name, ['admin_notified_at' => $now], ['id' => $record_id]);
            }

            wp_send_json_success([
                'record_id' => $record_id,
                'admin_notified' => (bool) $sent,
            ]);
        }

        private function get_auto_apply_contact_admin_email()
        {
            $email = sanitize_email((string) get_option('sffc_crm_auto_apply_admin_email', ''));
            if ($email === '' || !is_email($email)) {
                $email = sanitize_email((string) get_option('admin_email'));
            }
            return $email;
        }

        private function send_auto_apply_contact_admin_email(array $payload)
        {
            $admin_email = $this->get_auto_apply_contact_admin_email();
            if ($admin_email === '' || !is_email($admin_email)) {
                return false;
            }

            $role_line = trim((string) ($payload['role_title'] ?? ''));
            $company_line = trim((string) ($payload['company_name'] ?? ''));
            $status = sanitize_key((string) ($payload['status'] ?? 'signup_clicked'));
            if ($status === 'signup_confirmed') {
                $subject_prefix = __('Auto Apply Signup Confirmed', 'senna-finance');
            } else {
                $subject_prefix = !empty($payload['is_update']) ? __('Updated Auto Apply Contact', 'senna-finance') : __('New Auto Apply Contact', 'senna-finance');
            }
            $subject = $role_line !== ''
                ? sprintf('%s: %s', $subject_prefix, $role_line)
                : $subject_prefix;

            $rows = [
                __('Record ID', 'senna-finance') => (string) ($payload['record_id'] ?? ''),
                __('Support mode', 'senna-finance') => (string) ($payload['support_mode'] ?? ''),
                __('Applications per week', 'senna-finance') => (string) ($payload['applications_per_week'] ?? ''),
                __('Intros per week', 'senna-finance') => (string) ($payload['intros_per_week'] ?? ''),
                __('Priority', 'senna-finance') => (string) ($payload['priority_preference'] ?? ''),
                __('Lane', 'senna-finance') => (string) ($payload['lane_preference'] ?? ''),
                __('Target roles', 'senna-finance') => (string) ($payload['target_roles'] ?? ''),
                __('Target sectors', 'senna-finance') => (string) ($payload['target_sectors'] ?? ''),
                __('Target private equity market', 'senna-finance') => (string) ($payload['preferred_market'] ?? ''),
                __('Preferred email', 'senna-finance') => (string) ($payload['preferred_email'] ?? ''),
                __('Full name', 'senna-finance') => (string) ($payload['full_name'] ?? ''),
                __('WordPress post ID', 'senna-finance') => (string) ($payload['wp_post_id'] ?? ''),
                __('CRM post ID', 'senna-finance') => (string) ($payload['crm_post_id'] ?? ''),
                __('User ID', 'senna-finance') => (string) ($payload['user_id'] ?? ''),
                __('Conversation ID', 'senna-finance') => (string) ($payload['conversation_id'] ?? ''),
                __('Membership type', 'senna-finance') => (string) ($payload['membership_account_type'] ?? ''),
                __('Membership URL', 'senna-finance') => (string) ($payload['membership_url'] ?? ''),
                __('Page URL', 'senna-finance') => (string) ($payload['page_url'] ?? ''),
                __('Status', 'senna-finance') => $status,
            ];

            $details_html = '';
            foreach ($rows as $label => $value) {
                if ((string) $value === '') {
                    continue;
                }
                $details_html .= sprintf(
                    '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:180px;font-weight:600;color:#3a4759;">%s</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">%s</td></tr>',
                    esc_html($label),
                    esc_html($value)
                );
            }

            $notes = [];
            if ($role_line !== '') {
                $notes[] = $company_line !== '' ? $role_line . ' · ' . $company_line : $role_line;
            }
            if (!empty($payload['constraints_text'])) {
                $notes[] = __('Constraints:', 'senna-finance') . ' ' . (string) $payload['constraints_text'];
            }
            if (!empty($payload['highlight_text'])) {
                $notes[] = __('Highlight:', 'senna-finance') . ' ' . (string) $payload['highlight_text'];
            }
            if (!empty($payload['route_summary'])) {
                $notes[] = __('Route summary:', 'senna-finance') . ' ' . (string) $payload['route_summary'];
            }

            $html =
                '<div style="margin:0;padding:24px;background:#f5f7fa;font-family:Arial,sans-serif;color:#16202d;">' .
                    '<div style="max-width:760px;margin:0 auto;background:#ffffff;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden;">' .
                        '<div style="padding:24px 28px;background:#162d55;color:#ffffff;">' .
                            '<div style="font-size:12px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.85;">' . esc_html__('MENA Careers CRM', 'senna-finance') . '</div>' .
                            '<div style="margin-top:8px;font-size:26px;font-weight:700;line-height:1.2;">' . esc_html($subject_prefix) . '</div>' .
                            '<div style="margin-top:8px;font-size:15px;opacity:0.92;">' . esc_html($role_line !== '' ? $role_line : __('Apply chat handoff', 'senna-finance')) . '</div>' .
                        '</div>' .
                        '<div style="padding:28px;">' .
                            '<p style="margin:0 0 18px;font-size:16px;line-height:1.7;color:#24303f;">' .
                                esc_html($status === 'signup_confirmed'
                                    ? __('The user has confirmed signup is complete and Emily can now start the work. Their current weekly preferences and handoff details are below.', 'senna-finance')
                                    : __('A user clicked the Get Hired sign-up link. Their current weekly preferences and handoff details are below.', 'senna-finance')) .
                            '</p>' .
                            '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 20px;border:1px solid #e7ebf0;border-radius:8px;overflow:hidden;">' .
                                $details_html .
                            '</table>';

            if (!empty($notes)) {
                $html .=
                    '<div style="padding:16px 18px;background:#f8fafc;border:1px solid #e7ebf0;border-radius:8px;">' .
                        '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#617085;margin-bottom:8px;">' . esc_html__('Notes', 'senna-finance') . '</div>' .
                        '<div style="font-size:15px;line-height:1.7;color:#24303f;">' . nl2br(esc_html(implode("\n\n", $notes))) . '</div>' .
                    '</div>';
            }

            $html .=
                        '</div>' .
                    '</div>' .
                '</div>';

            $headers = [
                'Content-Type: text/html; charset=UTF-8',
                'Reply-To: MENA Careers Support <support.team@joinsenna.com>',
            ];

            return wp_mail($admin_email, $subject, $html, $headers);
        }

        public function ajax_crm_apply_chat_send_catch_up_invite()
        {
            check_ajax_referer('sffc_crm_apply_chat_send_catch_up_invite', 'nonce');

            $email = isset($_POST['email']) ? sanitize_email(wp_unslash((string) $_POST['email'])) : '';
            $full_name = sanitize_text_field(wp_unslash((string) ($_POST['full_name'] ?? '')));
            $message = sanitize_textarea_field(wp_unslash((string) ($_POST['message'] ?? '')));
            $role_title = sanitize_text_field(wp_unslash((string) ($_POST['role_title'] ?? '')));
            $page_url = esc_url_raw(wp_unslash((string) ($_POST['page_url'] ?? home_url('/terminal/'))));
            $conversation_focus = sanitize_text_field(wp_unslash((string) ($_POST['conversation_focus'] ?? '')));
            $cv_profile = sanitize_text_field(wp_unslash((string) ($_POST['cv_profile'] ?? '')));
            $context_summary = sanitize_textarea_field(wp_unslash((string) ($_POST['context_summary'] ?? '')));
            $language = strtolower(trim((string) wp_unslash($_POST['language'] ?? 'en')));
            $is_arabic = $language === 'ar';

            if ($email === '' || !is_email($email)) {
                wp_send_json_error(['message' => $is_arabic ? 'أرسل لي بريدًا إلكترونيًا صحيحًا.' : __('Please send me a valid email address.', 'senna-finance')], 422);
            }
            if ($full_name === '') {
                wp_send_json_error(['message' => $is_arabic ? 'أرسل لي الاسم الكامل الذي تريدني أن أستخدمه في الدعوة.' : __('Please send me the full name to use for the invite.', 'senna-finance')], 422);
            }

            $first_name = sanitize_text_field((string) (preg_split('/\s+/', $full_name)[0] ?? ''));
            $terminal_url = $page_url !== '' ? $page_url : home_url('/terminal/');
            $subject = $is_arabic
                ? sprintf('%s / متابعة مع إيميلي', $first_name !== '' ? $first_name : 'مرشح')
                : sprintf(__('%s / Emily Catch Up', 'senna-finance'), $first_name !== '' ? $first_name : __('Candidate', 'senna-finance'));

            $details = array_filter([
                $is_arabic ? 'تركيز البحث' : __('Search focus', 'senna-finance') => $conversation_focus,
                $is_arabic ? 'ملف السيرة' : __('CV profile', 'senna-finance') => $cv_profile,
                $is_arabic ? 'الدور الذي كنت تشاهده' : __('Role in view', 'senna-finance') => $role_title,
            ]);

            $detail_html = '';
            foreach ($details as $label => $value) {
                $detail_html .= sprintf(
                    '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:170px;font-weight:600;color:#3a4759;">%s</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">%s</td></tr>',
                    esc_html($label),
                    esc_html($value)
                );
            }

            $request_copy = $message !== ''
                ? nl2br(esc_html($message))
                : esc_html($is_arabic ? 'لا توجد ملاحظة إضافية.' : __('No extra note was included.', 'senna-finance'));
            $context_copy = $context_summary !== ''
                ? nl2br(esc_html($context_summary))
                : esc_html($is_arabic ? 'لا يوجد سياق إضافي محفوظ.' : __('No extra context was captured.', 'senna-finance'));
            $dir = $is_arabic ? 'rtl' : 'ltr';
            $align = $is_arabic ? 'right' : 'left';

            $email_html =
                '<div dir="' . esc_attr($dir) . '" style="margin:0;padding:24px;background:#f5f7fa;font-family:Arial,sans-serif;color:#16202d;text-align:' . esc_attr($align) . ';">' .
                    '<div style="max-width:700px;margin:0 auto;background:#ffffff;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden;">' .
                        '<div style="padding:24px 28px;background:#162d55;color:#ffffff;">' .
                            '<div style="font-size:12px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.85;">' . esc_html__('MENA Careers', 'senna-finance') . '</div>' .
                            '<div style="margin-top:8px;font-size:26px;font-weight:700;line-height:1.2;">' . esc_html($is_arabic ? 'رابط المتابعة مع إيميلي' : __('Your Emily catch-up link', 'senna-finance')) . '</div>' .
                        '</div>' .
                        '<div style="padding:28px;">' .
                            '<p style="margin:0 0 14px;font-size:16px;line-height:1.7;color:#24303f;">' .
                                esc_html($is_arabic
                                    ? sprintf('مرحباً %s، جهزت لك إيميلي رابط متابعة. استخدم الزر أدناه عندما تكون جاهزاً وسيعيدك مباشرة إلى المنصة.', $first_name !== '' ? $first_name : $full_name)
                                    : sprintf(__('Hi %s, Emily has set aside a catch-up link for you. Use the button below when you are ready and it will take you straight back into the platform.', 'senna-finance'), $first_name !== '' ? $first_name : $full_name)
                                ) .
                            '</p>' .
                            '<p style="margin:0 0 20px;font-size:15px;line-height:1.7;color:#4b5563;">' . esc_html($is_arabic ? 'سيبقى كل شيء داخل نفس واجهة سنّا، حتى تكمّل من نفس النقطة التي توقفت عندها.' : __('Everything stays in the same MENA Careers interface, so you can pick up exactly where you left off.', 'senna-finance')) . '</p>' .
                            '<div style="margin:0 0 22px;"><a href="' . esc_url($terminal_url) . '" style="display:inline-block;padding:14px 22px;background:#467e6e;color:#ffffff;text-decoration:none;font-size:15px;font-weight:700;border-radius:8px;">' . esc_html($is_arabic ? 'افتح رابط المتابعة' : __('Open your catch-up link', 'senna-finance')) . '</a></div>' .
                            '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 20px;border:1px solid #e7ebf0;border-radius:8px;overflow:hidden;">' .
                                $detail_html .
                            '</table>' .
                            '<div style="margin:0 0 18px;padding:16px 18px;background:#fff8de;border:1px solid #f0e1a0;border-radius:8px;">' .
                                '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#7a6517;margin-bottom:8px;">' . esc_html($is_arabic ? 'ملاحظتك' : __('Your note', 'senna-finance')) . '</div>' .
                                '<div style="font-size:15px;line-height:1.7;color:#16202d;">' . $request_copy . '</div>' .
                            '</div>' .
                            '<div style="padding:16px 18px;background:#f8fafc;border:1px solid #e7ebf0;border-radius:8px;">' .
                                '<div style="font-size:13px;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;color:#617085;margin-bottom:8px;">' . esc_html($is_arabic ? 'السياق المحفوظ' : __('Context carried through', 'senna-finance')) . '</div>' .
                                '<div style="font-size:15px;line-height:1.7;color:#24303f;">' . $context_copy . '</div>' .
                            '</div>' .
                        '</div>' .
                    '</div>' .
                '</div>';

            $headers = [
                'Content-Type: text/html; charset=UTF-8',
                'Reply-To: MENA Careers Support <support.team@joinsenna.com>',
            ];

            $sent = wp_mail($email, $subject, $email_html, $headers);
            if (!$sent) {
                wp_send_json_error(['message' => $is_arabic ? 'ما قدرت أرسل دعوة المتابعة الآن.' : __('I could not send the catch-up invite just now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => $is_arabic
                    ? sprintf('تم. أرسلت رابط المتابعة إلى %s. وعندما تكون جاهزاً، افتحه وسيعيدك مباشرة إلى هنا.', $email)
                    : sprintf(
                        __('Done. I\'ve sent the catch-up link to %s. When you are ready, use that and it will bring you straight back here.', 'senna-finance'),
                        $email
                    ),
            ]);
        }

        public function ajax_crm_apply_chat_boot_session()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            $session_token = isset($_POST['session_token']) ? sanitize_text_field(wp_unslash((string) $_POST['session_token'])) : '';
            $post_id = absint($_POST['post_id'] ?? 0);
            $role_title = isset($_POST['role_title']) ? sanitize_text_field(wp_unslash((string) $_POST['role_title'])) : '';
            $page_url = isset($_POST['page_url']) ? esc_url_raw(wp_unslash((string) $_POST['page_url'])) : '';

            $conversation_id = $this->find_or_create_crm_apply_chat_conversation($session_token, $post_id, $role_title, $page_url);
            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Could not start the apply chat session.', 'senna-finance')], 500);
            }

            $this->touch_crm_apply_chat_presence($conversation_id, [
                'page_visible' => true,
                'page_url' => $page_url,
                'active_path' => 'boot',
                'prompt_state' => '',
            ]);

            $messages = $this->get_crm_apply_chat_conversation_messages($conversation_id);
            $last_message_id = !empty($messages) ? (int) end($messages)['id'] : 0;
            $memory_payload = [];
            $resume_context = [];
            $profile_preferences = [];
            $membership_snapshot = [];
            if (is_user_logged_in()) {
                $user_id = get_current_user_id();
                $memory_payload = $this->get_crm_apply_chat_user_memory($user_id);
                $resume_context = $this->build_crm_apply_chat_resume_context($user_id);
                $profile_preferences = $this->get_crm_apply_chat_profile_preferences($user_id);
                $membership_snapshot = $this->get_crm_apply_chat_membership_snapshot($user_id);
            }

            wp_send_json_success([
                'conversation_id' => $conversation_id,
                'last_message_id' => $last_message_id,
                'memory' => $memory_payload,
                'resume_context' => $resume_context,
                'profile_preferences' => $profile_preferences,
                'membership' => $membership_snapshot,
                'first_name' => $this->get_crm_apply_chat_current_user_first_name(),
            ]);
        }

        public function ajax_crm_apply_chat_update_memory()
        {
            check_ajax_referer('sffc_crm_apply_chat_memory', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_success([
                    'saved' => false,
                    'memory' => [],
                ]);
            }

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $memory_payload = isset($_POST['memory']) ? wp_unslash((string) $_POST['memory']) : '';
            $normalized = $this->normalize_crm_apply_chat_memory_payload($memory_payload);
            $user_id = get_current_user_id();
            $saved = $this->save_crm_apply_chat_user_memory($user_id, $normalized, $conversation_id);

            if ($saved && function_exists('sffc_crm_sync_premium_search_profile_from_apply_chat')) {
                sffc_crm_sync_premium_search_profile_from_apply_chat(
                    $user_id,
                    $normalized,
                    $this->build_crm_apply_chat_resume_context($user_id),
                    $this->get_crm_apply_chat_profile_preferences($user_id),
                    $this->get_crm_apply_chat_membership_snapshot($user_id)
                );
            }

            wp_send_json_success([
                'saved' => (bool) $saved,
                'memory' => $normalized,
            ]);
        }

        public function ajax_crm_apply_chat_heartbeat()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $session_token = isset($_POST['session_token']) ? sanitize_text_field(wp_unslash((string) $_POST['session_token'])) : '';
            $page_url = isset($_POST['page_url']) ? esc_url_raw(wp_unslash((string) $_POST['page_url'])) : '';
            $active_path = isset($_POST['active_path']) ? sanitize_key(wp_unslash((string) $_POST['active_path'])) : '';
            $prompt_state = isset($_POST['prompt_state']) ? sanitize_key(wp_unslash((string) $_POST['prompt_state'])) : '';
            $page_visible = !empty($_POST['page_visible']);

            $conversation = $conversation_id > 0
                ? $this->get_crm_apply_chat_conversation($conversation_id)
                : $this->get_crm_apply_chat_conversation_by_thread_id($this->get_crm_apply_chat_thread_id($session_token));
            if (empty($conversation['id'])) {
                wp_send_json_success([
                    'conversation_id' => 0,
                    'live' => false,
                ]);
            }

            $conversation_id = (int) $conversation['id'];
            $this->touch_crm_apply_chat_presence($conversation_id, [
                'page_visible' => $page_visible,
                'page_url' => $page_url,
                'active_path' => $active_path,
                'prompt_state' => $prompt_state,
            ]);

            wp_send_json_success([
                'conversation_id' => $conversation_id,
                'live' => true,
            ]);
        }

        public function ajax_crm_apply_chat_log_message()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $session_token = isset($_POST['session_token']) ? sanitize_text_field(wp_unslash((string) $_POST['session_token'])) : '';
            $post_id = absint($_POST['post_id'] ?? 0);
            $role_title = isset($_POST['role_title']) ? sanitize_text_field(wp_unslash((string) $_POST['role_title'])) : '';
            $page_url = isset($_POST['page_url']) ? esc_url_raw(wp_unslash((string) $_POST['page_url'])) : '';
            $speaker = isset($_POST['speaker']) ? sanitize_key((string) wp_unslash($_POST['speaker'])) : '';
            $content = isset($_POST['content']) ? sanitize_textarea_field(wp_unslash((string) $_POST['content'])) : '';
            $content_html = isset($_POST['content_html']) ? wp_kses_post(wp_unslash((string) $_POST['content_html'])) : '';
            $client_message_id = isset($_POST['client_message_id']) ? sanitize_text_field(wp_unslash((string) $_POST['client_message_id'])) : '';

            if ($speaker === '' || ($content === '' && trim(wp_strip_all_tags($content_html)) === '')) {
                wp_send_json_error(['message' => __('Message content required.', 'senna-finance')], 422);
            }

            if ($conversation_id > 0) {
                $conversation = $this->get_crm_apply_chat_conversation($conversation_id);
                if (empty($conversation['id'])) {
                    $conversation_id = 0;
                }
            }

            if ($conversation_id <= 0) {
                $conversation_id = $this->find_or_create_crm_apply_chat_conversation($session_token, $post_id, $role_title, $page_url);
            }
            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Could not attach that message to the session.', 'senna-finance')], 500);
            }

            $external_id = $client_message_id !== ''
                ? 'apply_chat:' . $this->normalize_crm_apply_chat_session_token($session_token) . ':' . $client_message_id
                : '';

            $message_id = $this->create_crm_apply_chat_message(
                $conversation_id,
                $speaker,
                $content,
                $content_html,
                $external_id,
                [
                    'client_message_id' => $client_message_id,
                    'page_url' => $page_url,
                ]
            );

            if (is_wp_error($message_id)) {
                wp_send_json_error(['message' => $message_id->get_error_message()], 500);
            }

            wp_send_json_success([
                'conversation_id' => $conversation_id,
                'message_id' => (int) $message_id,
            ]);
        }

        public function ajax_crm_apply_chat_fetch_replies()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $session_token = isset($_POST['session_token']) ? sanitize_text_field(wp_unslash((string) $_POST['session_token'])) : '';
            $last_message_id = absint($_POST['last_message_id'] ?? 0);
            $conversation = $conversation_id > 0
                ? $this->get_crm_apply_chat_conversation($conversation_id)
                : $this->get_crm_apply_chat_conversation_by_thread_id($this->get_crm_apply_chat_thread_id($session_token));

            if (empty($conversation['id'])) {
                wp_send_json_success([
                    'messages' => [],
                    'last_message_id' => $last_message_id,
                    'takeover_active' => false,
                    'status' => 'active',
                ]);
            }

            $messages = $this->get_crm_apply_chat_conversation_messages_after((int) $conversation['id'], $last_message_id);
            $reply_messages = [];
            $max_message_id = $last_message_id;

            foreach ($messages as $message) {
                $message_id = (int) ($message['id'] ?? 0);
                $headers = (array) ($message['headers'] ?? []);
                $speaker = sanitize_key((string) ($headers['speaker'] ?? ''));
                $max_message_id = max($max_message_id, $message_id);
                if ($speaker !== 'admin') {
                    continue;
                }
                if (!empty($headers['internal_note'])) {
                    continue;
                }

                $reply_messages[] = [
                    'id' => $message_id,
                    'speaker' => 'admin',
                    'content' => (string) ($message['content'] ?? ''),
                    'content_html' => (string) ($message['content_html'] ?? ''),
                    'from_name' => (string) ($message['from_name'] ?? __('MENA Careers team', 'senna-finance')),
                ];
            }

            wp_send_json_success([
                'messages' => $reply_messages,
                'last_message_id' => $max_message_id,
                'takeover_active' => (string) ($conversation['status'] ?? 'active') === 'human_takeover',
                'status' => (string) ($conversation['status'] ?? 'active'),
                'support_tab_enabled' => $this->crm_apply_chat_conversation_has_label((array) $conversation, 'support_attachments_enabled'),
                'support_attachments' => $this->get_crm_apply_chat_support_attachments($messages),
            ]);
        }

        public function ajax_crm_apply_chat_admin_threads()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            if (!$this->can_manage_crm_apply_chat_monitor()) {
                wp_send_json_error(['message' => __('Not allowed.', 'senna-finance')], 403);
            }

            $threads = array_map([$this, 'get_crm_apply_chat_monitor_thread_context'], $this->query_crm_apply_chat_admin_threads());
            wp_send_json_success(['threads' => $threads]);
        }

        public function ajax_crm_apply_chat_admin_open()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            if (!$this->can_manage_crm_apply_chat_monitor()) {
                wp_send_json_error(['message' => __('Not allowed.', 'senna-finance')], 403);
            }

            $threads = array_map([$this, 'get_crm_apply_chat_monitor_thread_context'], $this->query_crm_apply_chat_admin_threads());
            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            if ($conversation_id <= 0 && !empty($threads[0]['id'])) {
                $conversation_id = (int) $threads[0]['id'];
            }

            $messages = $conversation_id > 0 ? $this->get_crm_apply_chat_conversation_messages($conversation_id) : [];
            $formatted_messages = array_map(function ($message) {
                $headers = (array) ($message['headers'] ?? []);
                return [
                    'id' => (int) ($message['id'] ?? 0),
                    'speaker' => sanitize_key((string) ($headers['speaker'] ?? (($message['direction'] ?? '') === 'inbound' ? 'admin' : 'user'))),
                    'content' => (string) ($message['content'] ?? ''),
                    'content_html' => (string) ($message['content_html'] ?? ''),
                    'internal_note' => !empty($headers['internal_note']),
                ];
            }, $messages);

            $active = [];
            foreach ($threads as $thread) {
                if ((int) ($thread['id'] ?? 0) === $conversation_id) {
                    $active = $thread;
                    break;
                }
            }
            $conversation_row = [];
            foreach ($this->query_crm_apply_chat_admin_threads() as $row) {
                if ((int) ($row['id'] ?? 0) === $conversation_id) {
                    $conversation_row = $row;
                    break;
                }
            }
            $active_summary = !empty($conversation_row) ? $this->get_crm_apply_chat_summary($conversation_row, $messages) : [];

            $thread_payload = array_map(function ($thread) use ($conversation_id) {
                $thread['updated_label'] = date_i18n('j M, g:i A', strtotime((string) ($thread['updated_at'] ?? current_time('mysql'))));
                return $thread;
            }, $threads);

            wp_send_json_success([
                'threads' => $thread_payload,
                'messages' => $formatted_messages,
                'active_conversation_id' => $conversation_id,
                'active_subject' => (string) ($active['subject'] ?? __('Apply chat', 'senna-finance')),
                'active_meta' => trim((string) (($active['user_name'] ?? '') . (!empty($active['user_email']) ? ' · ' . $active['user_email'] : ''))),
                'active_status' => (string) ($active['status'] ?? 'active'),
                'active_summary' => $active_summary,
                'support_tab_enabled' => !empty($active_summary['support_tab_enabled']),
            ]);
        }

        public function ajax_crm_apply_chat_admin_reply()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            if (!$this->can_manage_crm_apply_chat_monitor()) {
                wp_send_json_error(['message' => __('Not allowed.', 'senna-finance')], 403);
            }

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            $body = wp_kses_post((string) wp_unslash($_POST['body'] ?? ''));
            $upload_payload = $_FILES['attachments'] ?? ($_FILES['attachment'] ?? []);
            $has_attachment = !empty($upload_payload['name']);
            $show_in_support_tab = !empty($_POST['show_in_support_tab']);
            if ($conversation_id <= 0 || (trim(wp_strip_all_tags($body)) === '' && !$has_attachment)) {
                wp_send_json_error(['message' => __('Reply content required.', 'senna-finance')], 422);
            }

            $attachments = [];
            $attachment_html = '';
            if ($has_attachment) {
                $upload_result = $this->upload_crm_apply_chat_attachments($upload_payload);
                if (is_wp_error($upload_result)) {
                    wp_send_json_error(['message' => $upload_result->get_error_message()], 422);
                }
                $attachments = (array) ($upload_result['attachments'] ?? []);
                $attachment_html = (string) ($upload_result['html'] ?? '');
            }

            $current_user = wp_get_current_user();
            $message_id = $this->create_crm_apply_chat_message(
                $conversation_id,
                'admin',
                wp_strip_all_tags($body),
                trim(wpautop($body) . $attachment_html),
                '',
                [
                    'admin_user_id' => (int) ($current_user->ID ?? 0),
                    'admin_name' => (string) ($current_user->display_name ?: $current_user->user_login ?: __('MENA Careers team', 'senna-finance')),
                    'support_attachment' => $show_in_support_tab ? 1 : 0,
                ],
                $attachments
            );

            if (is_wp_error($message_id)) {
                wp_send_json_error(['message' => $message_id->get_error_message()], 500);
            }

            $this->set_crm_apply_chat_conversation_status($conversation_id, 'human_takeover');
            if ($show_in_support_tab) {
                $this->set_crm_apply_chat_conversation_label($conversation_id, 'support_attachments_enabled', true);
            }
            $this->set_crm_apply_chat_conversation_label($conversation_id, 'priority_now', false);

            wp_send_json_success([
                'message_id' => (int) $message_id,
                'message' => [
                    'id' => (int) $message_id,
                    'speaker' => 'admin',
                    'content' => wp_strip_all_tags($body),
                    'content_html' => trim(wpautop($body) . $attachment_html),
                    'internal_note' => false,
                ],
            ]);
        }

