        public function ajax_crm_apply_chat_admin_delete()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            if (!$this->can_manage_crm_apply_chat_monitor()) {
                wp_send_json_error(['message' => __('Not allowed.', 'senna-finance')], 403);
            }

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Conversation not found.', 'senna-finance')], 422);
            }

            $this->ensure_crm_apply_chat_models();
            $conversation_model = new SFFC_CRM_Conversation();
            $conversation = $conversation_model->get($conversation_id);
            if (empty($conversation['id'])) {
                wp_send_json_error(['message' => __('Conversation not found.', 'senna-finance')], 404);
            }

            global $wpdb;
            $wpdb->delete($wpdb->prefix . 'sffc_crm_messages', ['conversation_id' => $conversation_id], ['%d']);
            $wpdb->delete($wpdb->prefix . 'sffc_crm_conversations', ['id' => $conversation_id], ['%d']);
            delete_transient($this->get_crm_apply_chat_presence_transient_key($conversation_id));

            wp_send_json_success(['deleted' => true]);
        }

        public function ajax_crm_apply_chat_admin_forward()
        {
            check_ajax_referer('sffc_crm_apply_chat_session', 'nonce');

            if (!$this->can_manage_crm_apply_chat_monitor()) {
                wp_send_json_error(['message' => __('Not allowed.', 'senna-finance')], 403);
            }

            $conversation_id = absint($_POST['conversation_id'] ?? 0);
            if ($conversation_id <= 0) {
                wp_send_json_error(['message' => __('Conversation not found.', 'senna-finance')], 422);
            }

            $conversation = $this->get_crm_apply_chat_conversation($conversation_id);
            if (empty($conversation['id'])) {
                wp_send_json_error(['message' => __('Conversation not found.', 'senna-finance')], 404);
            }

            $messages = $this->get_crm_apply_chat_conversation_messages($conversation_id);
            $destination = (string) apply_filters('sffc_crm_apply_chat_forward_email', 'support.team@joinsenna.com', $conversation_id, $conversation);
            if ($destination === '' || !is_email($destination)) {
                wp_send_json_error(['message' => __('Forward email is not configured.', 'senna-finance')], 500);
            }

            $summary = $this->get_crm_apply_chat_summary($conversation, $messages);
            $transcript_lines = [];
            foreach ($messages as $message) {
                $headers = (array) ($message['headers'] ?? []);
                $speaker = sanitize_key((string) ($headers['speaker'] ?? 'user'));
                $label = !empty($headers['internal_note']) ? 'Internal note' : ucfirst($speaker);
                $transcript_lines[] = $label . ': ' . trim((string) ($message['content'] ?? ''));
            }

            $subject = sprintf(__('Forwarded MENA Careers apply chat · %s', 'senna-finance'), trim((string) ($conversation['subject'] ?? __('Apply chat', 'senna-finance'))));
            $body = implode("\n", array_filter([
                'Forwarded from the apply chat monitor.',
                '',
                'Queue: ' . (string) ($summary['queue_label'] ?? ''),
                'Last seen: ' . (string) ($summary['last_seen_label'] ?? ''),
                'Source page: ' . (string) ($summary['page_url'] ?? ''),
                '',
                'Transcript:',
                implode("\n", $transcript_lines),
            ]));

            if (!wp_mail($destination, $subject, $body, ['Content-Type: text/plain; charset=UTF-8'])) {
                wp_send_json_error(['message' => __('Could not forward this session.', 'senna-finance')], 500);
            }

            wp_send_json_success(['forwarded' => true]);
        }

