        private function extract_crm_apply_chat_cv_text_from_upload($file, $analysis_mode = 'full')
        {
            if (empty($file['name']) || !empty($file['error'])) {
                return ['success' => false, 'message' => __('Select a valid CV file.', 'senna-finance')];
            }

            $extension = strtolower(pathinfo((string) $file['name'], PATHINFO_EXTENSION));
            if (!in_array($extension, ['pdf', 'doc', 'docx', 'txt'], true)) {
                return ['success' => false, 'message' => __('Upload a PDF, DOC, DOCX, or TXT CV.', 'senna-finance')];
            }

            if ((int) ($file['size'] ?? 0) > 10 * 1024 * 1024) {
                return ['success' => false, 'message' => __('CV file size must be under 10MB.', 'senna-finance')];
            }

            if (!function_exists('wp_handle_upload')) {
                require_once ABSPATH . 'wp-admin/includes/file.php';
            }

            $uploaded = wp_handle_upload($file, ['test_form' => false]);
            if (empty($uploaded['file']) || !empty($uploaded['error'])) {
                return ['success' => false, 'message' => (string) ($uploaded['error'] ?? __('Unable to upload that CV.', 'senna-finance'))];
            }

            $file_path = (string) $uploaded['file'];
            $text = '';
            try {
                if ($extension === 'txt') {
                    $text = (string) file_get_contents($file_path);
                } else {
                    if (!class_exists('SFFC_Document_Parser')) {
                        $parser_file = SFFC_PLUGIN_DIR . 'includes/class-document-parser.php';
                        if (file_exists($parser_file)) {
                            require_once $parser_file;
                        }
                    }

                    if (class_exists('SFFC_Document_Parser')) {
                        $parser = SFFC_Document_Parser::get_instance();
                        if ($extension === 'pdf') {
                            $text = (string) $parser->extract_pdf_text($file_path, $analysis_mode);
                        } elseif ($extension === 'docx') {
                            $text = (string) $parser->extract_docx_text($file_path);
                        } elseif ($extension === 'doc') {
                            $text = (string) $parser->extract_doc_text($file_path);
                        }

                        if ($text !== '' && method_exists($parser, 'clean_text')) {
                            $text = (string) $parser->clean_text($text);
                        }
                    }
                }
            } catch (\Throwable $e) {
                error_log('Apply chat CV upload extraction fatal: ' . $e->getMessage());
                return ['success' => false, 'message' => __('I could not read that CV file just now. Try again, or paste the CV text instead.', 'senna-finance')];
            }

            $text = str_replace(["\r\n", "\r"], "\n", (string) $text);
            $text = wp_strip_all_tags($text);
            $text = preg_replace("/[ \t]+/", ' ', (string) $text);
            $text = preg_replace("/\n{3,}/", "\n\n", (string) $text);
            $text = trim((string) $text);
            if ($text === '') {
                return ['success' => false, 'message' => __('I could not read text from that CV. Try a PDF/DOCX with selectable text, or paste the CV text instead.', 'senna-finance')];
            }

            return [
                'success' => true,
                'text' => $text,
                'file_name' => sanitize_file_name((string) $file['name']),
            ];
        }

        private function build_crm_apply_chat_cv_only_analysis($cv_text)
        {
            $cv_text = trim((string) $cv_text);
            if ($cv_text === '') {
                return [];
            }

            $profile = $this->build_crm_reddit_dashboard_discovery_cv_profile_fallback($cv_text);
            $experience_entries = $this->extract_crm_apply_chat_cv_experience_entries($cv_text);
            $primary_experience = !empty($experience_entries[0]) && is_array($experience_entries[0]) ? $experience_entries[0] : [];
            $location_signals = array_values(array_filter(array_map(static function ($item) {
                if (is_array($item)) {
                    return sanitize_text_field((string) ($item['label'] ?? ''));
                }
                return sanitize_text_field((string) $item);
            }, (array) ($profile['locations'] ?? []))));
            $role_signals = array_values(array_filter(array_map(static function ($item) {
                if (is_array($item)) {
                    return sanitize_text_field((string) ($item['label'] ?? ''));
                }
                return sanitize_text_field((string) $item);
            }, (array) ($profile['target_roles'] ?? []))));
            $keyword_signals = array_values(array_filter(array_map(static function ($item) {
                if (is_array($item)) {
                    return sanitize_text_field((string) ($item['label'] ?? ''));
                }
                return sanitize_text_field((string) $item);
            }, (array) ($profile['keywords'] ?? []))));
            $matched_keywords = array_slice(array_values(array_unique(array_merge($role_signals, $keyword_signals))), 0, 6);
            $location_signal = !empty($location_signals[0]) ? (string) $location_signals[0] : '';
            $company_signal = trim((string) ($primary_experience['company'] ?? ''));

            if ($company_signal === '') {
                $company_signal = $this->extract_crm_apply_chat_cv_company_signal($cv_text);
            }

            $analysis = [
                'issue_count' => 0,
                'company_signal' => $company_signal,
                'has_numbers' => (bool) preg_match('/\b(\d+(?:\.\d+)?%?|[£$€]\s?\d+|\d+\s?(?:m|mm|bn|k|million|billion))\b/i', $cv_text),
                'matched_keywords' => $matched_keywords,
                'missing_keywords' => [],
                'jd_signals' => [],
                'confirmed_signals' => [],
                'adjacent_signals' => [],
                'unconfirmed_signals' => [],
                'summary' => __('CV profile extracted for search.', 'senna-finance'),
                'specific_issue' => '',
                'before' => '',
                'after' => '',
                'experience_title' => trim((string) ($primary_experience['title'] ?? '')),
                'experience_company' => $company_signal,
                'experience_bullets' => array_slice((array) ($primary_experience['bullets'] ?? []), 0, 3),
                'experience_years' => $this->calculate_crm_apply_chat_cv_experience_years($experience_entries),
                'required_years' => '',
                'requirement_gaps' => [],
                'proof_note' => '',
                'location_signal' => $location_signal,
            ];

            $analysis['profile_review_ontology'] = $this->build_crm_apply_chat_profile_review_ontology($cv_text, '', [], $analysis);
            $analysis['cv_signal_profile'] = $this->build_crm_apply_chat_cv_signal_profile($cv_text, '', [], $analysis);
            $analysis['quick_role_insights'] = $this->build_crm_apply_chat_quick_role_insights($analysis);

            return $analysis;
        }

        private function build_crm_apply_chat_cv_analysis($cv_text, $jd_text, array $post = [])
        {
            $cv_text = trim((string) $cv_text);
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $normalized_cv = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $role_title = trim((string) ($post['role_title'] ?? __('this role', 'senna-finance')));
            $company = trim((string) ($post['company'] ?? ''));
            $jd_signals = $this->extract_crm_apply_chat_jd_signals($jd_text, $post);
            $confirmed_signals = [];
            $adjacent_signals = [];
            $unconfirmed_signals = [];

            foreach ($jd_signals as $signal) {
                $match_state = $this->match_crm_apply_chat_signal_against_cv($signal, $normalized_cv);
                $signal['match_state'] = $match_state;

                if ($match_state === 'confirmed') {
                    $confirmed_signals[] = $signal;
                } elseif ($match_state === 'adjacent') {
                    $adjacent_signals[] = $signal;
                } else {
                    $unconfirmed_signals[] = $signal;
                }
            }

            $matched = array_values(array_map(static function ($signal) {
                return (string) ($signal['label'] ?? '');
            }, array_slice($confirmed_signals, 0, 5)));
            $missing = array_values(array_map(static function ($signal) {
                return (string) ($signal['label'] ?? '');
            }, array_slice($unconfirmed_signals, 0, 5)));

            $matched = array_slice(array_values(array_unique($matched)), 0, 5);
            $missing = array_slice(array_values(array_unique($missing)), 0, 5);
            $has_numbers = (bool) preg_match('/\b(\d+(?:\.\d+)?%?|[£$€]\s?\d+|\d+\s?(?:m|mm|bn|k|million|billion))\b/i', $cv_text);
            $experience_entries = $this->extract_crm_apply_chat_cv_experience_entries($cv_text);
            $primary_experience = !empty($experience_entries[0]) && is_array($experience_entries[0]) ? $experience_entries[0] : [];
            $visible_experience_years = $this->calculate_crm_apply_chat_cv_experience_years($experience_entries);
            $required_years = $this->extract_crm_apply_chat_required_years($post, $jd_text);
            $requirement_gaps = $this->extract_crm_apply_chat_requirement_gaps($cv_text, $jd_text, $post, $visible_experience_years, $required_years, $jd_signals, $unconfirmed_signals);
            $company_signal = trim((string) ($primary_experience['company'] ?? ''));
            if ($company_signal === '') {
                $company_signal = $this->extract_crm_apply_chat_cv_company_signal($cv_text);
            }
            $issue_count = count($missing) + count($requirement_gaps);
            if (!$has_numbers) {
                $issue_count += 2;
            }
            if (empty($primary_experience)) {
                $issue_count += 2;
            }
            if (empty($primary_experience['bullets'])) {
                $issue_count += 1;
            }
            if ($visible_experience_years <= 0 && $required_years !== '') {
                $issue_count += 1;
            }
            $issue_count = max(1, min(18, $issue_count));
            $lead_skill = $adjacent_signals[0]['label'] ?? ($matched[0] ?? __('deal ownership', 'senna-finance'));
            $secondary_skill = $adjacent_signals[1]['label'] ?? ($missing[0] ?? ($matched[1] ?? __('investment judgement', 'senna-finance')));
            $role_signal = trim((string) ($primary_experience['title'] ?? ''));
            $before = trim((string) ($primary_experience['sample_bullet'] ?? ''));
            if ($before === '') {
                $before = __('Supported due diligence and prepared analysis for transactions.', 'senna-finance');
            }
            $after = sprintf(
                __('Reframe this %1$s work as a stronger achievement: show the action taken, the scale or result, and connect it more directly to %2$s, %3$s, and the role brief.', 'senna-finance'),
                $company_signal !== '' ? $company_signal : ($role_signal !== '' ? $role_signal : __('experience', 'senna-finance')),
                $lead_skill,
                $secondary_skill
            );

            $analysis = [
                'issue_count' => $issue_count,
                'company_signal' => $company_signal,
                'has_numbers' => $has_numbers,
                'matched_keywords' => $matched,
                'missing_keywords' => $missing,
                'jd_signals' => array_slice($jd_signals, 0, 12),
                'confirmed_signals' => array_slice($confirmed_signals, 0, 6),
                'adjacent_signals' => array_slice($adjacent_signals, 0, 4),
                'unconfirmed_signals' => array_slice($unconfirmed_signals, 0, 4),
                'summary' => sprintf(
                    __('You are close for %s, but the CV needs sharper proof before a recruiter reads it.', 'senna-finance'),
                    $role_title
                ),
                'specific_issue' => sprintf(
                    __('The %1$s section is not showing enough proof around %2$s, and %3$s is not visible enough for this brief.', 'senna-finance'),
                    $company_signal !== '' ? $company_signal : ($role_signal !== '' ? $role_signal : __('main experience', 'senna-finance')),
                    $has_numbers ? __('deal ownership', 'senna-finance') : __('measurable impact', 'senna-finance'),
                    $lead_skill
                ),
                'before' => $before,
                'after' => $after,
                'experience_title' => $role_signal,
                'experience_company' => $company_signal,
                'experience_bullets' => array_slice((array) ($primary_experience['bullets'] ?? []), 0, 3),
                'experience_years' => $visible_experience_years,
                'required_years' => $required_years,
                'requirement_gaps' => $requirement_gaps,
                'proof_note' => $has_numbers
                    ? __('You already have some numbers in the CV, but Emily needs to check which ones belong against the strongest bullets.', 'senna-finance')
                    : __('The CV is light on numbers, so Emily needs your real figures before finalising anything.', 'senna-finance'),
            ];

            $analysis['profile_review_ontology'] = $this->build_crm_apply_chat_profile_review_ontology($cv_text, $jd_text, $post, $analysis);
            $analysis['cv_signal_profile'] = $this->build_crm_apply_chat_cv_signal_profile($cv_text, $jd_text, $post, $analysis);
            $analysis['quick_role_insights'] = $this->build_crm_apply_chat_quick_role_insights($analysis);

            return $analysis;
        }

        private function build_crm_apply_chat_cv_signal_profile($cv_text, $jd_text = '', array $post = [], array $analysis = [])
        {
            $cv_norm = $this->normalize_crm_reddit_dashboard_cv_text((string) $cv_text);
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $jd_norm = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                (string) $jd_text,
                (string) ($post['role_title'] ?? ''),
                (string) ($post['sector'] ?? ''),
                (string) ($post['seniority'] ?? ''),
            ])));
            $score_terms = static function ($text, array $terms, $weight = 1) {
                $score = 0;
                $hits = [];
                foreach ($terms as $term) {
                    $term = trim((string) $term);
                    if ($term === '') {
                        continue;
                    }
                    $needle = preg_quote($term, '/');
                    $count = preg_match_all('/\b' . $needle . '\b/i', $text, $matches);
                    if ($count > 0) {
                        $score += min(4, (int) $count) * (int) $weight;
                        $hits[] = $term;
                    }
                }
                return ['score' => $score, 'hits' => array_slice(array_values(array_unique($hits)), 0, 8)];
            };

            $seniority_groups = [
                ['level' => 12, 'label' => 'C-suite', 'terms' => ['chief financial officer', 'chief operating officer', 'chief technology officer', 'chief investment officer', 'chief risk officer', 'chief executive officer', 'cfo', 'coo', 'cto', 'cio', 'cmo', 'cro', 'chro', 'ceo', 'founder ceo']],
                ['level' => 11, 'label' => 'Head / Executive', 'terms' => ['global head', 'regional head', 'country head', 'head of', 'general manager', 'president', 'senior vice president', 'executive vice president', 'svp', 'evp']],
                ['level' => 10, 'label' => 'Managing Director / Partner', 'terms' => ['senior managing director', 'managing director', 'managing partner', 'equity partner', 'operating partner', 'investment partner', 'associate partner', 'partner']],
                ['level' => 9, 'label' => 'Director', 'terms' => ['executive director', 'senior director', 'associate director', 'director', 'investment director', 'finance director']],
                ['level' => 8, 'label' => 'VP / Principal', 'terms' => ['assistant vice president', 'vice president', 'senior principal', 'principal', 'investment principal', 'vp', 'avp']],
                ['level' => 7, 'label' => 'Senior Manager', 'terms' => ['senior manager', 'lead manager', 'programme manager', 'program manager']],
                ['level' => 6, 'label' => 'Manager', 'terms' => ['assistant manager', 'team manager', 'finance manager', 'portfolio manager', 'relationship manager', 'project manager', 'product manager', 'manager']],
                ['level' => 5, 'label' => 'Senior Associate', 'terms' => ['senior associate', 'lead associate', 'experienced associate']],
                ['level' => 4, 'label' => 'Associate', 'terms' => ['junior associate', 'investment associate', 'research associate', 'associate']],
                ['level' => 3, 'label' => 'Senior Analyst', 'terms' => ['senior analyst', 'lead analyst', 'experienced analyst', 'senior accountant']],
                ['level' => 2, 'label' => 'Analyst', 'terms' => ['investment analyst', 'research analyst', 'business analyst', 'financial analyst', 'credit analyst', 'data analyst', 'quantitative analyst', 'junior analyst', 'analyst', 'analista', 'accountant', 'banker', 'accounting professional', 'finance professional']],
                ['level' => 1, 'label' => 'Entry / Graduate', 'terms' => ['graduate analyst', 'graduate trainee', 'graduate', 'junior', 'jr', 'assistant', 'coordinator', 'administrator', 'officer', 'student', 'estudiante', 'entry level', 'career objective', 'career objectives', 'objetivo atuar']],
                ['level' => 0, 'label' => 'Internship', 'terms' => ['apprentice', 'trainee', 'summer analyst', 'off-cycle analyst', 'intern', 'internship', 'placement', 'work experience', 'stagiaire', 'stage', 'alternance']],
            ];
            $action_groups = [
                ['band' => 'support', 'level' => 1, 'weight' => 1, 'terms' => ['assisted', 'supported', 'helped', 'shadowed', 'participated', 'contributed', 'worked alongside', 'under supervision', 'gained exposure', 'helped prepare', 'maintained', 'processed', 'updated', 'compiled']],
                ['band' => 'execute', 'level' => 3, 'weight' => 2, 'terms' => ['analysed', 'analyzed', 'built', 'prepared', 'modelled', 'modeled', 'researched', 'evaluated', 'calculated', 'forecasted', 'reviewed', 'monitored', 'identified', 'presented', 'drafted', 'screened', 'benchmarked', 'reconciled', 'implemented']],
                ['band' => 'own', 'level' => 5, 'weight' => 3, 'terms' => ['owned', 'executed', 'delivered', 'managed workstream', 'managed workstreams', 'coordinated', 'drove execution', 'led analysis', 'managed process', 'reviewed junior work', 'mentored', 'prepared recommendations', 'conducted due diligence', 'managed stakeholders']],
                ['band' => 'lead', 'level' => 8, 'weight' => 4, 'terms' => ['managed a team', 'led a team', 'supervised', 'coached', 'hired', 'developed team', 'allocated resources', 'managed performance', 'led transactions', 'originated', 'negotiated', 'approved', 'advised senior stakeholders', 'led workstreams', 'owned budget', 'influenced leadership']],
                ['band' => 'direct', 'level' => 10, 'weight' => 5, 'terms' => ['defined strategy', 'set direction', 'set strategic direction', 'established', 'transformed', 'restructured', 'launched', 'expanded', 'entered new markets', 'owned p and l', 'owned pnl', 'generated revenue', 'won mandates', 'advised board', 'chaired', 'accountable for', 'drove growth', 'set objectives']],
            ];
            $sector_groups = [
                ['label' => 'Private Equity', 'terms' => ['lbo', 'leveraged buyout', 'moic', 'investment committee', 'portfolio company', 'value creation', 'bolt-on', 'add-on acquisition', 'buyout', 'investment thesis', 'exit', 'management buyout', 'commercial due diligence'], 'weight' => 5],
                ['label' => 'Growth Equity', 'terms' => ['growth investment', 'minority investment', 'growth capital', 'unit economics', 'tam', 'cohort analysis', 'recurring revenue', 'arr', 'series c', 'series d', 'founder led'], 'weight' => 5],
                ['label' => 'Venture Capital', 'terms' => ['venture capital', 'seed', 'series a', 'series b', 'startup', 'startups', 'founders', 'cap table', 'term sheet', 'follow-on investment', 'product market fit', 'accelerator'], 'weight' => 5],
                ['label' => 'Investment Banking', 'terms' => ['investment banking', 'm&a', 'mergers and acquisitions', 'sell-side', 'buy-side', 'pitchbook', 'cim', 'information memorandum', 'fairness opinion', 'deal execution', 'buyer list', 'mandate'], 'weight' => 4],
                ['label' => 'Equity Capital Markets', 'terms' => ['equity capital markets', 'ecm', 'ipo', 'adx', 'dfm', 'tadawul', 'rights issue', 'follow-on offering', 'bookbuilding', 'prospectus', 'investor roadshow'], 'weight' => 5],
                ['label' => 'Debt Capital Markets', 'terms' => ['debt capital markets', 'dcm', 'bond issuance', 'debt issuance', 'fixed income issuance', 'refinancing', 'credit rating', 'sukuk issuance'], 'weight' => 5],
                ['label' => 'Private Credit', 'terms' => ['private credit', 'direct lending', 'unitranche', 'senior secured', 'credit underwriting', 'covenant', 'debt capacity', 'interest coverage', 'credit committee', 'leveraged loans', 'downside case'], 'weight' => 5],
                ['label' => 'Restructuring / Special Situations', 'terms' => ['distressed debt', 'restructuring', 'stressed credit', 'recovery analysis', 'liquidation value', 'special situations', 'turnaround', '13 week cash flow', 'covenant breach'], 'weight' => 5],
                ['label' => 'Transaction Services / FDD', 'terms' => ['financial due diligence', 'transaction services', 'fdd', 'qoe', 'quality of earnings', 'net debt', 'working capital', 'ebitda adjustments', 'deal advisory'], 'weight' => 5],
                ['label' => 'Valuations', 'terms' => ['dcf', 'discounted cash flow', 'comparable companies', 'precedent transactions', 'purchase price allocation', 'impairment testing', 'fair value', 'valuation modelling'], 'weight' => 4],
                ['label' => 'Asset Management', 'terms' => ['aum', 'portfolio management', 'fund performance', 'benchmark', 'alpha', 'asset allocation', 'investment mandate', 'institutional investors', 'stock selection', 'public equities'], 'weight' => 4],
                ['label' => 'Hedge Fund / Quant', 'terms' => ['hedge fund', 'long short', 'short thesis', 'gross exposure', 'net exposure', 'portfolio exposure', 'p and l', 'alpha generation', 'systematic', 'statistical arbitrage', 'backtesting', 'factor models'], 'weight' => 5],
                ['label' => 'Sovereign Investment', 'terms' => ['sovereign wealth fund', 'sovereign investments', 'national investment strategy', 'pif', 'mubadala', 'adia', 'adq', 'qia', 'gic', 'temasek', 'strategic investments', 'national champions'], 'weight' => 6],
                ['label' => 'Government / GRE', 'terms' => ['government related entity', 'gre', 'ministry', 'vision 2030', 'national transformation', 'economic development', 'strategic projects', 'giga project'], 'weight' => 5],
                ['label' => 'Family Office', 'terms' => ['family office', 'principal investments', 'family investments', 'family assets', 'strategic holdings', 'wealth preservation', 'single family office', 'multi family office'], 'weight' => 5],
                ['label' => 'Private Banking / Wealth', 'terms' => ['private banking', 'wealth management', 'hnw', 'uhnw', 'private clients', 'wealth planning', 'discretionary portfolio', 'client assets', 'investment advisory'], 'weight' => 5],
                ['label' => 'Islamic Finance', 'terms' => ['sharia', 'sharia compliant', 'sukuk', 'murabaha', 'ijara', 'musharaka', 'mudaraba', 'wakala', 'islamic banking'], 'weight' => 5],
                ['label' => 'Infrastructure Investment', 'terms' => ['infrastructure assets', 'ppp', 'concessions', 'regulated assets', 'utilities', 'transport', 'digital infrastructure', 'availability payments', 'project finance'], 'weight' => 5],
                ['label' => 'Real Estate Investment', 'terms' => ['real estate', 'real estate acquisitions', 'property portfolio', 'development appraisal', 'cap rate', 'yield', 'noi', 'occupancy', 'rent roll', 'nav', 'asset management'], 'weight' => 4],
                ['label' => 'Renewable Energy', 'terms' => ['solar', 'wind', 'bess', 'renewable energy', 'ppa', 'mw', 'gw', 'generation capacity', 'energy transition', 'clean energy', 'green hydrogen', 'renewable assets'], 'weight' => 5],
                ['label' => 'Energy', 'terms' => ['oil and gas', 'upstream', 'downstream', 'lng', 'hydrocarbons', 'reserves', 'production', 'exploration', 'energy markets', 'noc', 'adnoc', 'aramco'], 'weight' => 4],
                ['label' => 'Corporate Banking', 'terms' => ['corporate banking', 'commercial banking', 'corporate clients', 'credit facilities', 'working capital facility', 'revolving credit facility', 'loan book', 'relationship manager'], 'weight' => 4],
                ['label' => 'Corporate Finance', 'terms' => ['budgeting', 'forecasting', 'fp&a', 'management accounts', 'variance analysis', 'cash flow', 'business partnering'], 'weight' => 3],
                ['label' => 'Risk & Compliance', 'terms' => ['risk management', 'market risk', 'credit risk', 'operational risk', 'var', 'stress testing', 'aml', 'kyc', 'sanctions', 'regulatory compliance'], 'weight' => 4],
                ['label' => 'Treasury', 'terms' => ['treasury', 'liquidity', 'cash management', 'fx hedging', 'funding', 'interest rate risk', 'debt facilities', 'cash forecasting'], 'weight' => 4],
                ['label' => 'Fund Accounting / Operations', 'terms' => ['fund accounting', 'nav', 'capital calls', 'distributions', 'carried interest', 'waterfall', 'investor allocations', 'fund operations'], 'weight' => 4],
                ['label' => 'Insurance', 'terms' => ['insurance', 'underwriting', 'premiums', 'claims', 'loss ratio', 'combined ratio', 'actuarial', 'policyholders', 'reinsurance', 'solvency'], 'weight' => 4],
                ['label' => 'Management Consulting', 'terms' => ['consulting', 'strategy consulting', 'management consulting', 'operating model', 'transformation', 'market assessment', 'stakeholder interviews', 'client engagement', 'workstream'], 'weight' => 4],
                ['label' => 'Accounting / Audit', 'terms' => ['audit', 'ifrs', 'gaap', 'statutory accounts', 'financial statements', 'controls testing', 'substantive testing', 'audit procedures', 'month end', 'reconciliations'], 'weight' => 4],
                ['label' => 'Legal', 'terms' => ['legal', 'law degree', 'jurisprudence', 'litigation', 'contracts', 'legal advice', 'regulatory counsel', 'disputes', 'legal research', 'compliance policies'], 'weight' => 3],
                ['label' => 'Technology / Data', 'terms' => ['data analyst', 'data analytics', 'sql', 'python', 'tableau', 'power bi', 'machine learning', 'software', 'saas', 'cloud', 'api', 'digital transformation', 'erp'], 'weight' => 3],
                ['label' => 'Engineering / Industrials', 'terms' => ['mechanical engineer', 'engineering', 'cae', 'fea', 'cfd', 'matlab', 'ansys', 'manufacturing', 'production line', 'plant', 'factory', 'lean manufacturing'], 'weight' => 3],
                ['label' => 'Hospitality / Tourism', 'terms' => ['hospitality', 'restaurant', 'hotel', 'hotels', 'occupancy', 'revpar', 'adr', 'f&b', 'tourism', 'aviation', 'airports'], 'weight' => 3],
                ['label' => 'Sales / Business Development', 'terms' => ['sales', 'business development', 'customer service', 'account manager', 'pipeline', 'lead generation', 'client acquisition', 'relationship management', 'revenue targets'], 'weight' => 3],
                ['label' => 'Human Resources', 'terms' => ['human resources', 'hr', 'talent acquisition', 'recruitment', 'employee relations', 'payroll', 'people operations', 'learning and development'], 'weight' => 3],
                ['label' => 'Education', 'terms' => ['education', 'teaching', 'students', 'curriculum', 'schools', 'universities', 'academic', 'learning outcomes'], 'weight' => 3],
            ];

            $seniority_scores = [];
            foreach ($seniority_groups as $group) {
                $result = $score_terms($cv_norm, (array) $group['terms'], (int) ($group['level'] >= 8 ? 4 : 3));
                if ((int) $result['score'] > 0) {
                    $seniority_scores[] = [
                        'level' => (int) $group['level'],
                        'label' => sanitize_text_field((string) $group['label']),
                        'score' => (int) $result['score'],
                        'hits' => array_map('sanitize_text_field', (array) $result['hits']),
                    ];
                }
            }
            usort($seniority_scores, static function ($left, $right) {
                $score_compare = ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
                return $score_compare !== 0 ? $score_compare : (((int) ($right['level'] ?? 0)) <=> ((int) ($left['level'] ?? 0)));
            });

            $action_scores = [];
            foreach ($action_groups as $group) {
                $result = $score_terms($cv_norm, (array) $group['terms'], (int) $group['weight']);
                if ((int) $result['score'] > 0) {
                    $action_scores[] = [
                        'band' => sanitize_key((string) $group['band']),
                        'level' => (int) $group['level'],
                        'score' => (int) $result['score'],
                        'hits' => array_map('sanitize_text_field', (array) $result['hits']),
                    ];
                }
            }
            usort($action_scores, static function ($left, $right) {
                $score_compare = ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
                return $score_compare !== 0 ? $score_compare : (((int) ($right['level'] ?? 0)) <=> ((int) ($left['level'] ?? 0)));
            });

            $title_level = isset($seniority_scores[0]) ? (int) $seniority_scores[0]['level'] : null;
            $action_level = isset($action_scores[0]) ? (int) $action_scores[0]['level'] : 2;
            if (preg_match('/\b(managed|led|supervised|mentored|coached)\s+(?:a\s+)?team\s+(?:of\s+)?\d+/i', $cv_norm)) {
                $action_level = max($action_level, 7);
            }
            if (preg_match('/\b(board|investment committee|executive committee|c suite|senior stakeholders)\b/i', $cv_norm)) {
                $action_level = max($action_level, 7);
            }
            if (preg_match('/\b([£$€]\s?\d+|\d+(?:\.\d+)?\s?(?:m|mm|bn|million|billion))\b/i', $cv_norm) && preg_match('/\b(owned|delivered|generated|grew|secured|raised|won|reduced|increased|managed)\b/i', $cv_norm)) {
                $action_level = max($action_level, 8);
            }
            $demonstrated_level = $title_level === null ? $action_level : (int) round(($title_level * 0.65) + ($action_level * 0.35));

            $sector_scores = [];
            foreach ($sector_groups as $group) {
                $result = $score_terms($cv_norm, (array) $group['terms'], (int) $group['weight']);
                $role_result = $score_terms($jd_norm, (array) $group['terms'], (int) $group['weight']);
                if ((int) $result['score'] > 0 || (int) $role_result['score'] > 0) {
                    $sector_scores[] = [
                        'label' => sanitize_text_field((string) $group['label']),
                        'cv_score' => (int) $result['score'],
                        'role_score' => (int) $role_result['score'],
                        'hits' => array_map('sanitize_text_field', (array) $result['hits']),
                    ];
                }
            }
            usort($sector_scores, static function ($left, $right) {
                return ((int) ($right['cv_score'] ?? 0)) <=> ((int) ($left['cv_score'] ?? 0));
            });

            $level_label = 'Analyst';
            if ($demonstrated_level >= 10) {
                $level_label = 'Director+';
            } elseif ($demonstrated_level >= 8) {
                $level_label = 'VP / Principal';
            } elseif ($demonstrated_level >= 6) {
                $level_label = 'Manager';
            } elseif ($demonstrated_level >= 4) {
                $level_label = 'Associate';
            } elseif ($demonstrated_level <= 1) {
                $level_label = 'Entry / Graduate';
            }

            return [
                'seniority' => [
                    'title_level' => $title_level,
                    'title_label' => sanitize_text_field((string) ($seniority_scores[0]['label'] ?? '')),
                    'demonstrated_level' => $demonstrated_level,
                    'demonstrated_label' => $level_label,
                    'action_band' => sanitize_text_field((string) ($action_scores[0]['band'] ?? '')),
                    'title_signals' => array_slice($seniority_scores, 0, 4),
                    'action_signals' => array_slice($action_scores, 0, 4),
                ],
                'sectors' => array_slice($sector_scores, 0, 6),
                'summary' => sprintf(__('CV reads closest to %1$s level, with strongest detected sector evidence around %2$s.', 'senna-finance'), $level_label, !empty($sector_scores[0]['label']) ? (string) $sector_scores[0]['label'] : __('general finance', 'senna-finance')),
            ];
        }

        private function build_crm_apply_chat_quick_role_insights(array $analysis)
        {
            $insights = [];
            $add = static function ($title, $message, $tone = 'watch', $type = 'general', $label = '', $priority = 50) use (&$insights) {
                $title = trim(wp_strip_all_tags((string) $title));
                $message = trim(wp_strip_all_tags((string) $message));
                if ($message === '') {
                    return;
                }
                foreach ($insights as $existing) {
                    if (strcasecmp((string) ($existing['message'] ?? ''), $message) === 0) {
                        return;
                    }
                }
                $insights[] = [
                    'title' => sanitize_text_field($title !== '' ? $title : __('Worth noting', 'senna-finance')),
                    'message' => sanitize_text_field($message),
                    'tone' => sanitize_key($tone),
                    'type' => sanitize_key($type),
                    'label' => sanitize_text_field(trim(wp_strip_all_tags((string) $label))),
                    'priority' => (int) $priority,
                ];
            };

            foreach ((array) ($analysis['requirement_gaps'] ?? []) as $gap) {
                if (!is_array($gap)) {
                    continue;
                }
                $type = sanitize_key((string) ($gap['type'] ?? ''));
                $label = trim((string) ($gap['label'] ?? ''));
                if ($label === '') {
                    continue;
                }
                if ($type === 'language') {
                    $add(
                        sprintf(__('%s is not visible', 'senna-finance'), $label),
                        sprintf(__('I noticed this role appears to require %s, but I cannot see that language on the CV. If you use it professionally, it should be visible before you apply.', 'senna-finance'), $label),
                        'gap',
                        'language',
                        $label,
                        100
                    );
                    continue;
                }
                if ($type === 'work_authorization') {
                    $add(
                        __('Work authorisation may be screened', 'senna-finance'),
                        __('The application may screen for work authorisation or location readiness. I cannot confirm that from the CV, so it is worth checking before this goes out.', 'senna-finance'),
                        'gap',
                        'work_authorization',
                        $label,
                        95
                    );
                    continue;
                }
                if ($type === 'qualification') {
                    $add(
                        sprintf(__('%s is not on the CV', 'senna-finance'), $label),
                        sprintf(__('I noticed the job asks for %s, but your CV does not mention that qualification. If you do have it, I can help you improve the positioning before you apply.', 'senna-finance'), $label),
                        'gap',
                        'qualification',
                        $label,
                        98
                    );
                    continue;
                }
                if ($type === 'experience') {
                    $message = trim((string) ($gap['message'] ?? ''));
                    $add(
                        __('Experience level needs checking', 'senna-finance'),
                        $message !== ''
                            ? $message . ' ' . __('I can help make the relevant experience clearer before you apply.', 'senna-finance')
                            : sprintf(__('The role asks for %s, but the dated experience on the CV may not show that clearly. I can help position the relevant experience before you apply.', 'senna-finance'), $label),
                        'gap',
                        'experience',
                        $label,
                        92
                    );
                    continue;
                }
            }

            foreach ((array) ($analysis['unconfirmed_signals'] ?? []) as $signal) {
                if (!is_array($signal)) {
                    continue;
                }
                $category = sanitize_key((string) ($signal['category'] ?? ''));
                $label = trim((string) ($signal['label'] ?? ''));
                if ($label === '' || in_array($category, ['language', 'credential', 'soft_signal'], true)) {
                    continue;
                }
                $type = in_array($category, ['sector_exposure', 'industry'], true) ? 'sector_signal' : 'missing_signal';
                $priority = $type === 'sector_signal' ? 70 : 82;
                $add(
                    sprintf(__('%s is not obvious yet', 'senna-finance'), ucfirst($label)),
                    sprintf(__('I noticed the role asks for %s, but the CV does not make that evidence obvious yet. If it is part of your background, I can help bring it forward before you apply.', 'senna-finance'), $label),
                    'watch',
                    $type,
                    $label,
                    $priority
                );
            }

            $role_sector_scores = array_values(array_filter((array) ($analysis['cv_signal_profile']['sectors'] ?? []), static function ($sector) {
                return is_array($sector) && (int) ($sector['role_score'] ?? 0) > 0;
            }));
            usort($role_sector_scores, static function ($left, $right) {
                return ((int) ($right['role_score'] ?? 0)) <=> ((int) ($left['role_score'] ?? 0));
            });
            foreach ($role_sector_scores as $sector) {
                $label = trim((string) ($sector['label'] ?? ''));
                if ($label !== '' && (int) ($sector['cv_score'] ?? 0) <= 0) {
                    $add(
                        sprintf(__('%s exposure is not clear', 'senna-finance'), $label),
                        sprintf(__('This role leans toward %s, but the CV does not show that sector exposure clearly yet. I can help create a stronger bridge before you apply.', 'senna-finance'), $label),
                        'watch',
                        'sector_gap',
                        $label,
                        68
                    );
                    break;
                }
            }

            $matched = array_values(array_filter(array_map('strval', (array) ($analysis['matched_keywords'] ?? []))));
            if (!empty($matched)) {
                $matched_label = implode(', ', array_slice($matched, 0, 2));
                $add(
                    __('Strong match signal', 'senna-finance'),
                    sprintf(__('Good signal: your CV already shows %s for this role. That is worth keeping prominent in the application.', 'senna-finance'), $matched_label),
                    'strong',
                    'matched_signal',
                    $matched_label,
                    45
                );
            }

            if (empty($insights)) {
                $profile = (array) ($analysis['cv_signal_profile'] ?? []);
                $summary = trim((string) ($profile['summary'] ?? ''));
                if ($summary !== '') {
                    $add(__('CV direction is clear', 'senna-finance'), $summary, 'strong', 'profile_signal', '', 30);
                }
            }

            usort($insights, static function ($left, $right) {
                return ((int) ($right['priority'] ?? 0)) <=> ((int) ($left['priority'] ?? 0));
            });

            return array_slice($insights, 0, 5);
        }

        private function build_crm_apply_chat_profile_review_ontology($cv_text, $jd_text, array $post = [], array $analysis = [])
        {
            $cv_text = trim((string) $cv_text);
            $jd_text = trim((string) $jd_text);
            $normalized_cv = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $role_title = trim((string) ($post['role_title'] ?? ''));
            $company = trim((string) ($post['company'] ?? ''));
            $location = trim((string) ($post['location'] ?? $post['job_location'] ?? ''));
            $sector = trim((string) ($post['sector'] ?? $post['industry'] ?? ''));
            $seniority = trim((string) ($post['seniority'] ?? $post['role_seniority'] ?? ''));
            $required_years = trim((string) ($analysis['required_years'] ?? ''));
            $visible_years = (int) ($analysis['experience_years'] ?? 0);
            $experience_title = trim((string) ($analysis['experience_title'] ?? ''));
            $experience_company = trim((string) ($analysis['experience_company'] ?? ''));
            $experience_bullets = array_values(array_filter(array_map('strval', (array) ($analysis['experience_bullets'] ?? []))));
            $has_numbers = !empty($analysis['has_numbers']);
            $confirmed = array_values((array) ($analysis['confirmed_signals'] ?? []));
            $adjacent = array_values((array) ($analysis['adjacent_signals'] ?? []));
            $unconfirmed = array_values((array) ($analysis['unconfirmed_signals'] ?? []));
            $requirement_gaps = array_values((array) ($analysis['requirement_gaps'] ?? []));

            $clean_label = static function ($value) {
                $value = sanitize_text_field((string) $value);
                $value = str_replace('_', ' ', $value);
                $value = preg_replace('/\s+/', ' ', $value);
                return trim((string) $value);
            };

            $role_context_text = strtolower($clean_label(implode(' ', array_filter([
                $role_title,
                $company,
                $location,
                $sector,
                $seniority,
                $jd_text,
            ]))));
            $role_archetypes = $this->get_crm_apply_chat_profile_review_role_archetypes();
            $role_archetype = $this->infer_crm_apply_chat_profile_review_role_archetype($role_context_text, $role_archetypes);

            $signal_weight = static function ($signal) {
                $importance = strtolower((string) ($signal['importance'] ?? 'medium'));
                if ($importance === 'high') {
                    return 3;
                }
                if ($importance === 'low') {
                    return 1;
                }
                return 2;
            };

            $score_categories = static function (array $categories) use ($confirmed, $adjacent, $unconfirmed, $signal_weight) {
                $total = 0;
                $score = 0;
                $has_relevant = false;
                foreach (['confirmed' => $confirmed, 'adjacent' => $adjacent, 'unconfirmed' => $unconfirmed] as $state => $signals) {
                    foreach ($signals as $signal) {
                        $category = strtolower((string) ($signal['category'] ?? ''));
                        if (!in_array($category, $categories, true)) {
                            continue;
                        }
                        $has_relevant = true;
                        $weight = $signal_weight($signal);
                        $total += $weight;
                        if ($state === 'confirmed') {
                            $score += $weight;
                        } elseif ($state === 'adjacent') {
                            $score += $weight * 0.55;
                        }
                    }
                }

                if (!$has_relevant || $total <= 0) {
                    return null;
                }

                return (int) round(max(0, min(100, ($score / $total) * 100)));
            };

            $hard_skill_score = $score_categories(['hard_skill']);
            $sector_score = $score_categories(['experience_background', 'sector_exposure']);
            $credential_score = $score_categories(['qualification', 'credential', 'education']);
            $role_lane_score = $score_categories(['experience_background', 'sector_exposure', 'hard_skill']);

            $signal_labels = [
                'confirmed' => array_values(array_filter(array_map(static function ($signal) use ($clean_label) {
                    return is_array($signal) ? strtolower($clean_label($signal['label'] ?? '')) : '';
                }, $confirmed))),
                'adjacent' => array_values(array_filter(array_map(static function ($signal) use ($clean_label) {
                    return is_array($signal) ? strtolower($clean_label($signal['label'] ?? '')) : '';
                }, $adjacent))),
                'unconfirmed' => array_values(array_filter(array_map(static function ($signal) use ($clean_label) {
                    return is_array($signal) ? strtolower($clean_label($signal['label'] ?? '')) : '';
                }, $unconfirmed))),
            ];
            $matches_expectation = static function ($expectation, array $labels) {
                $expectation = strtolower(trim((string) $expectation));
                if ($expectation === '') {
                    return false;
                }
                foreach ($labels as $label) {
                    $label = strtolower(trim((string) $label));
                    if ($label === '') {
                        continue;
                    }
                    if (strpos($label, $expectation) !== false || strpos($expectation, $label) !== false) {
                        return true;
                    }
                }
                return false;
            };

            $year_min = null;
            if ($required_years !== '' && preg_match('/(\d+)(?:\s*[-–]\s*(\d+))?/', $required_years, $year_match)) {
                $year_min = (int) ($year_match[1] ?? 0);
            }
            $seniority_score = 62;
            if ($year_min !== null && $year_min > 0) {
                if ($visible_years >= $year_min) {
                    $seniority_score = 88;
                } elseif ($visible_years > 0 && ($visible_years + 1) >= $year_min) {
                    $seniority_score = 70;
                } elseif ($visible_years > 0) {
                    $seniority_score = 48;
                } else {
                    $seniority_score = 54;
                }
            } elseif ($visible_years > 0) {
                $seniority_score = min(90, 58 + ($visible_years * 6));
            }

            $evidence_score = 44;
            if ($has_numbers) {
                $evidence_score += 22;
            }
            if (!empty($experience_bullets)) {
                $evidence_score += min(20, count($experience_bullets) * 7);
            }
            if ($experience_title !== '') {
                $evidence_score += 8;
            }
            if ($experience_company !== '') {
                $evidence_score += 6;
            }
            $evidence_score = min(96, $evidence_score);

            $location_score = 68;
            if ($location !== '') {
                $location_norm = strtolower($clean_label($location));
                $location_score = $location_norm !== '' && strpos($normalized_cv, $location_norm) !== false ? 86 : 58;
                if (!empty($analysis['location_signal'])) {
                    $location_score = max($location_score, 74);
                }
            }

            $recruiter_score = 46;
            if ($experience_title !== '') {
                $recruiter_score += 14;
            }
            if ($experience_company !== '') {
                $recruiter_score += 10;
            }
            if (!empty($experience_bullets)) {
                $recruiter_score += 14;
            }
            if ($has_numbers) {
                $recruiter_score += 12;
            }
            $recruiter_score = min(96, $recruiter_score);

            $component_scores = [
                'role_lane' => $role_lane_score ?? 62,
                'hard_skills' => $hard_skill_score ?? 60,
                'sector_fit' => $sector_score ?? 60,
                'seniority' => $seniority_score,
                'evidence_quality' => $evidence_score,
                'location_readiness' => $location_score,
                'credentials' => $credential_score ?? 64,
                'recruiter_readability' => $recruiter_score,
            ];

            $expectation_items = [];
            $confirmed_expectations = 0;
            $transferable_expectations = 0;
            $missing_expectations = 0;
            foreach ((array) ($role_archetype['must_have'] ?? []) as $expectation) {
                $expectation_label = $clean_label($expectation);
                if ($expectation_label === '') {
                    continue;
                }
                $expectation_norm = strtolower($expectation_label);
                $is_confirmed = $matches_expectation($expectation_norm, $signal_labels['confirmed']) || strpos($normalized_cv, $expectation_norm) !== false;
                $is_transferable = !$is_confirmed && ($matches_expectation($expectation_norm, $signal_labels['adjacent']) || $matches_expectation($expectation_norm, $signal_labels['unconfirmed']));
                if ($is_confirmed) {
                    $status = 'confirmed';
                    $confirmed_expectations++;
                } elseif ($is_transferable) {
                    $status = 'transferable';
                    $transferable_expectations++;
                } else {
                    $status = 'missing';
                    $missing_expectations++;
                }
                $expectation_items[] = [
                    'label' => $expectation_label,
                    'status' => $status,
                    'importance' => 'high',
                    'why_it_matters' => sprintf(__('For %1$s roles, recruiters usually look for visible proof of %2$s.', 'senna-finance'), $clean_label($role_archetype['label'] ?? __('this role family', 'senna-finance')), $expectation_label),
                    'profile_move' => sprintf(__('Show %s in a summary line, skills row, or concrete experience bullet if it is true.', 'senna-finance'), $expectation_label),
                ];
            }
            if (!empty($expectation_items)) {
                $component_scores['archetype_fit'] = (int) round(
                    (($confirmed_expectations * 100) + ($transferable_expectations * 62) + ($missing_expectations * 28)) / count($expectation_items)
                );
            } else {
                $component_scores['archetype_fit'] = 62;
            }

            $overall = (int) round(
                ($component_scores['role_lane'] * 0.14) +
                ($component_scores['hard_skills'] * 0.15) +
                ($component_scores['sector_fit'] * 0.11) +
                ($component_scores['archetype_fit'] * 0.15) +
                ($component_scores['seniority'] * 0.11) +
                ($component_scores['evidence_quality'] * 0.15) +
                ($component_scores['location_readiness'] * 0.07) +
                ($component_scores['credentials'] * 0.05) +
                ($component_scores['recruiter_readability'] * 0.07)
            );
            $overall = max(0, min(100, $overall + min(8, $confirmed_expectations * 2) - min(16, $missing_expectations * 4)));

            $gap_items = [];
            foreach (array_slice($requirement_gaps, 0, 5) as $gap) {
                if (!is_array($gap)) {
                    continue;
                }
                $label = $clean_label($gap['label'] ?? '');
                if ($label === '') {
                    continue;
                }
                $gap_type = sanitize_key((string) ($gap['type'] ?? 'proof'));
                $severity = in_array($gap_type, ['qualification', 'work_authorization', 'language'], true) ? 'high' : 'medium';
                $gap_items[] = [
                    'type' => $gap_type,
                    'severity' => $severity,
                    'label' => $label,
                    'why_it_matters' => sprintf(__('Recruiters may look for clear proof of %s before shortlisting.', 'senna-finance'), $label),
                    'fix' => sprintf(__('Add one specific line or bullet that proves %s, or confirm it is not part of your background.', 'senna-finance'), $label),
                ];
            }

            foreach (array_slice($unconfirmed, 0, 4) as $signal) {
                if (!is_array($signal)) {
                    continue;
                }
                $label = $clean_label($signal['label'] ?? '');
                if ($label === '') {
                    continue;
                }
                $gap_items[] = [
                    'type' => 'missing_role_signal',
                    'severity' => !empty($signal['required']) ? 'high' : 'medium',
                    'label' => $label,
                    'why_it_matters' => sprintf(__('The role asks for %s, but it is not easy to find in the CV yet.', 'senna-finance'), $label),
                    'fix' => sprintf(__('Bring %s into the summary, skills, or strongest experience bullet if it is accurate.', 'senna-finance'), $label),
                ];
            }

            foreach ($expectation_items as $expectation) {
                if (($expectation['status'] ?? '') !== 'missing') {
                    continue;
                }
                $gap_items[] = [
                    'type' => 'role_family_expectation',
                    'severity' => 'high',
                    'label' => (string) ($expectation['label'] ?? ''),
                    'why_it_matters' => (string) ($expectation['why_it_matters'] ?? ''),
                    'fix' => (string) ($expectation['profile_move'] ?? ''),
                ];
            }

            if (!$has_numbers) {
                $gap_items[] = [
                    'type' => 'evidence_quality',
                    'severity' => 'medium',
                    'label' => __('measurable impact', 'senna-finance'),
                    'why_it_matters' => __('The CV has limited numbers, so the strength of the work may be harder to judge.', 'senna-finance'),
                    'fix' => __('Add scale, deal size, portfolio value, time saved, revenue, cost, or percentage impact where true.', 'senna-finance'),
                ];
            }

            if (empty($experience_bullets)) {
                $gap_items[] = [
                    'type' => 'recruiter_readability',
                    'severity' => 'medium',
                    'label' => __('experience proof', 'senna-finance'),
                    'why_it_matters' => __('The latest experience does not expose enough bullet-level proof for a quick screen.', 'senna-finance'),
                    'fix' => __('Add two or three concise bullets under the most relevant recent role.', 'senna-finance'),
                ];
            }

            $make_evidence = static function ($signals, $state) use ($clean_label) {
                $items = [];
                foreach ($signals as $signal) {
                    if (!is_array($signal)) {
                        continue;
                    }
                    $label = $clean_label($signal['label'] ?? '');
                    if ($label === '') {
                        continue;
                    }
                    $items[] = [
                        'label' => $label,
                        'category' => sanitize_key((string) ($signal['category'] ?? 'role_signal')),
                        'importance' => sanitize_key((string) ($signal['importance'] ?? 'medium')),
                        'state' => $state,
                        'why' => $state === 'confirmed'
                            ? sprintf(__('The CV gives visible evidence of %s.', 'senna-finance'), $label)
                            : sprintf(__('The CV has adjacent proof around %s, but it should be made more direct.', 'senna-finance'), $label),
                    ];
                }
                return $items;
            };

            $confirmed_evidence = array_slice($make_evidence($confirmed, 'confirmed'), 0, 6);
            $transferable_evidence = array_slice($make_evidence($adjacent, 'transferable'), 0, 4);
            $status_from_score = static function ($score) {
                $score = (int) $score;
                if ($score >= 76) {
                    return 'strong';
                }
                if ($score >= 60) {
                    return 'ok';
                }
                return 'needs_work';
            };

            $profile_sections = [
                [
                    'section' => __('Profile summary', 'senna-finance'),
                    'status' => $status_from_score($component_scores['role_lane']),
                    'finding' => $role_title !== ''
                        ? sprintf(__('The profile should make the move toward %s obvious in the first few lines.', 'senna-finance'), $role_title)
                        : __('The target role lane should be clearer in the first few lines.', 'senna-finance'),
                    'recommendation' => __('Lead with the role lane, sector, strongest transaction or analytical evidence, and location readiness.', 'senna-finance'),
                ],
                [
                    'section' => sprintf(__('%s positioning', 'senna-finance'), $clean_label($role_archetype['label'] ?? __('Role family', 'senna-finance'))),
                    'status' => $status_from_score($component_scores['archetype_fit']),
                    'finding' => sprintf(__('This role is being screened through a %s hiring lens.', 'senna-finance'), $clean_label($role_archetype['label'] ?? __('finance', 'senna-finance'))),
                    'recommendation' => $clean_label($role_archetype['positioning'] ?? __('Make the most relevant finance evidence visible before applying.', 'senna-finance')),
                ],
                [
                    'section' => __('Experience bullets', 'senna-finance'),
                    'status' => $status_from_score($component_scores['evidence_quality']),
                    'finding' => $has_numbers ? __('Some measurable proof is visible.', 'senna-finance') : __('The CV needs more measurable proof.', 'senna-finance'),
                    'recommendation' => __('Turn the strongest responsibilities into outcome-led bullets with scale and relevance.', 'senna-finance'),
                ],
                [
                    'section' => __('Skills and tools', 'senna-finance'),
                    'status' => $status_from_score($component_scores['hard_skills']),
                    'finding' => __('The hard-skill match is based on what is explicitly visible, not assumed.', 'senna-finance'),
                    'recommendation' => __('Surface the role-critical skills near the top and repeat them naturally inside experience bullets.', 'senna-finance'),
                ],
                [
                    'section' => __('Sector proof', 'senna-finance'),
                    'status' => $status_from_score($component_scores['sector_fit']),
                    'finding' => $sector !== '' ? sprintf(__('The role is positioned around %s.', 'senna-finance'), $clean_label($sector)) : __('Sector fit needs to be explicit enough for a quick screen.', 'senna-finance'),
                    'recommendation' => __('Name relevant sector exposure directly where it is true.', 'senna-finance'),
                ],
                [
                    'section' => __('Seniority and scope', 'senna-finance'),
                    'status' => $status_from_score($component_scores['seniority']),
                    'finding' => $required_years !== '' ? sprintf(__('The role appears to ask for %s.', 'senna-finance'), $required_years) : __('The seniority expectation is inferred from the role title and visible experience.', 'senna-finance'),
                    'recommendation' => __('Make years, responsibility level, and deal or portfolio scope easy to scan.', 'senna-finance'),
                ],
                [
                    'section' => __('Location readiness', 'senna-finance'),
                    'status' => $status_from_score($component_scores['location_readiness']),
                    'finding' => $location !== '' ? sprintf(__('The role location is %s.', 'senna-finance'), $clean_label($location)) : __('Location is not central in this role data.', 'senna-finance'),
                    'recommendation' => __('State relocation, work authorization, or current location clearly when it matters.', 'senna-finance'),
                ],
            ];

            $action_plan = [];
            foreach (array_slice($gap_items, 0, 4) as $index => $gap) {
                $action_plan[] = [
                    'priority' => $index + 1,
                    'label' => sprintf(__('Make %s clearer', 'senna-finance'), $gap['label']),
                    'action' => (string) ($gap['fix'] ?? ''),
                    'reason' => (string) ($gap['why_it_matters'] ?? ''),
                ];
            }
            if (empty($action_plan)) {
                $action_plan[] = [
                    'priority' => 1,
                    'label' => __('Tighten the opening profile', 'senna-finance'),
                    'action' => __('Make the target role, sector, strongest proof, and location readiness visible in the top third of the CV.', 'senna-finance'),
                    'reason' => __('Even good profiles convert better when the fit is immediate.', 'senna-finance'),
                ];
            }

            if ($overall >= 78 && empty(array_filter($gap_items, static function ($gap) {
                return is_array($gap) && (string) ($gap['severity'] ?? '') === 'high';
            }))) {
                $verdict_label = __('Strong fit', 'senna-finance');
                $decision = 'apply_now';
                $verdict_summary = __('The CV has enough visible evidence to support an application, with small positioning improvements still useful.', 'senna-finance');
            } elseif ($overall >= 64) {
                $verdict_label = __('Good fit, tighten first', 'senna-finance');
                $decision = 'tailor_first';
                $verdict_summary = __('The profile is credible for this role, but the strongest proof should be easier to find before applying.', 'senna-finance');
            } elseif ($overall >= 50) {
                $verdict_label = __('Possible fit, review first', 'senna-finance');
                $decision = 'review_first';
                $verdict_summary = __('There is usable overlap, but the CV needs clearer proof before it should be sent.', 'senna-finance');
            } else {
                $verdict_label = __('Needs clearer proof', 'senna-finance');
                $decision = 'review_first';
                $verdict_summary = __('The current CV does not yet make the role fit obvious enough for a quick recruiter screen.', 'senna-finance');
            }

            return [
                'version' => '2026-08-profile-review-v1',
                'role' => [
                    'title' => $role_title,
                    'company' => $company,
                    'location' => $location,
                    'sector' => $clean_label($sector),
                    'seniority' => $clean_label($seniority),
                    'required_years' => $required_years,
                    'archetype' => $clean_label($role_archetype['label'] ?? ''),
                    'archetype_confidence' => (int) ($role_archetype['confidence'] ?? 0),
                    'must_have_signals' => array_values(array_filter(array_map(static function ($signal) use ($clean_label) {
                        return !empty($signal['required']) ? $clean_label($signal['label'] ?? '') : '';
                    }, array_slice((array) ($analysis['jd_signals'] ?? []), 0, 12)))),
                    'supporting_signals' => array_values(array_filter(array_map(static function ($signal) use ($clean_label) {
                        return empty($signal['required']) ? $clean_label($signal['label'] ?? '') : '';
                    }, array_slice((array) ($analysis['jd_signals'] ?? []), 0, 12)))),
                ],
                'archetype' => [
                    'key' => sanitize_key((string) ($role_archetype['key'] ?? 'finance_general')),
                    'label' => $clean_label($role_archetype['label'] ?? ''),
                    'confidence' => (int) ($role_archetype['confidence'] ?? 0),
                    'positioning' => $clean_label($role_archetype['positioning'] ?? ''),
                    'expectations' => $expectation_items,
                    'screening_risks' => array_values(array_map($clean_label, (array) ($role_archetype['screening_risks'] ?? []))),
                    'section_priority' => array_values(array_map($clean_label, (array) ($role_archetype['section_priority'] ?? []))),
                ],
                'candidate' => [
                    'current_title' => $experience_title,
                    'current_company' => $experience_company,
                    'visible_experience_years' => $visible_years,
                    'has_measurable_evidence' => $has_numbers,
                    'evidence_density' => $evidence_score >= 76 ? 'strong' : ($evidence_score >= 60 ? 'moderate' : 'light'),
                    'location_signal' => trim((string) ($analysis['location_signal'] ?? '')),
                    'positioning_read' => $confirmed_expectations > 1
                        ? sprintf(__('Best positioned as a %1$s candidate with visible proof of %2$s.', 'senna-finance'), $clean_label($role_archetype['label'] ?? __('finance', 'senna-finance')), implode(', ', array_slice(array_map(static function ($item) {
                            return (string) ($item['label'] ?? '');
                        }, array_filter($expectation_items, static function ($item) {
                            return is_array($item) && (string) ($item['status'] ?? '') === 'confirmed';
                        })), 0, 3)))
                        : sprintf(__('The profile needs clearer %s positioning before applying.', 'senna-finance'), $clean_label($role_archetype['label'] ?? __('finance', 'senna-finance'))),
                ],
                'scores' => array_merge(['overall' => $overall], $component_scores),
                'verdict' => [
                    'label' => $verdict_label,
                    'decision' => $decision,
                    'summary' => $verdict_summary,
                ],
                'evidence' => [
                    'confirmed' => $confirmed_evidence,
                    'transferable' => $transferable_evidence,
                ],
                'gaps' => array_slice($gap_items, 0, 8),
                'profile_sections' => $profile_sections,
                'action_plan' => $action_plan,
                'application_strategy' => [
                    'route' => $decision,
                    'apply_readiness' => $verdict_label,
                    'tailoring_focus' => array_values(array_filter(array_map(static function ($gap) {
                        return is_array($gap) ? (string) ($gap['label'] ?? '') : '';
                    }, array_slice($gap_items, 0, 4)))),
                    'avoid_claiming' => array_values(array_filter(array_map(static function ($gap) {
                        return is_array($gap) && (string) ($gap['severity'] ?? '') === 'high' ? (string) ($gap['label'] ?? '') : '';
                    }, $gap_items))),
                ],
                'review_questions' => array_values(array_filter([
                    $required_years !== '' && $visible_years <= 0 ? __('How many years of directly relevant experience should we make visible?', 'senna-finance') : '',
                    $location !== '' && $component_scores['location_readiness'] < 70 ? sprintf(__('Are you currently based in, relocating to, or authorized for %s?', 'senna-finance'), $clean_label($location)) : '',
                    !$has_numbers ? __('Which achievements can we quantify with real numbers?', 'senna-finance') : '',
                ])),
            ];
        }

        private function get_crm_apply_chat_profile_review_role_archetypes()
        {
            return [
                'investment_banking' => [
                    'label' => __('Investment banking', 'senna-finance'),
                    'keywords' => ['investment banking', 'm&a', 'mergers', 'acquisitions', 'corporate finance', 'capital markets', 'transaction advisory', 'investment bank'],
                    'must_have' => [
                        __('financial modelling', 'senna-finance'),
                        __('valuation', 'senna-finance'),
                        __('transaction execution', 'senna-finance'),
                        __('presentation materials', 'senna-finance'),
                    ],
                    'strong_proof' => [
                        __('deal exposure', 'senna-finance'),
                        __('valuation output', 'senna-finance'),
                        __('pitch or IC materials', 'senna-finance'),
                        __('client or research output', 'senna-finance'),
                    ],
                    'screening_risks' => [
                        __('no transaction language', 'senna-finance'),
                        __('no modelling evidence', 'senna-finance'),
                        __('unclear deal role', 'senna-finance'),
                    ],
                    'positioning' => __('Position the profile as a transaction-focused private equity candidate with visible modelling, valuation, and execution proof.', 'senna-finance'),
                    'section_priority' => [
                        __('Experience bullets', 'senna-finance'),
                        __('Transaction proof', 'senna-finance'),
                        __('Technical skills', 'senna-finance'),
                        __('Profile summary', 'senna-finance'),
                    ],
                ],
                'private_equity' => [
