        private function infer_crm_apply_chat_profile_review_role_archetype($context, array $archetypes)
        {
            $context = strtolower((string) $context);
            $best_key = 'finance_general';
            $best_score = -1;

            foreach ($archetypes as $key => $archetype) {
                $score = 0;
                foreach ((array) ($archetype['keywords'] ?? []) as $keyword) {
                    $keyword = strtolower(trim((string) $keyword));
                    if ($keyword === '') {
                        continue;
                    }
                    if (strpos($context, $keyword) !== false) {
                        $score += strlen($keyword) > 12 ? 2 : 1;
                    }
                }
                if ($score > $best_score) {
                    $best_score = $score;
                    $best_key = (string) $key;
                }
            }

            if (!isset($archetypes[$best_key])) {
                $best_key = 'finance_general';
            }

            $archetype = (array) $archetypes[$best_key];
            $archetype['key'] = $best_key;
            $archetype['confidence'] = $best_score > 0 ? min(95, 45 + ($best_score * 12)) : 40;

            return $archetype;
        }

        private function clean_crm_apply_chat_jd_text_for_analysis($jd_text)
        {
            $text = trim(wp_strip_all_tags((string) $jd_text));
            if ($text === '') {
                return '';
            }

            $patterns = [
                '/\bAbout\s+MENA\s+Careers\b.*$/is',
                '/\bMENA\s+Careers\s+is\s+a\s+finance\s+community\b.*$/is',
                '/\bFor\s+more\s+information,\s+visit\s+joinsenna\.com\b.*$/is',
                '/\bAbout\s+Senna\b.*$/is',
            ];

            foreach ($patterns as $pattern) {
                $text = preg_replace($pattern, '', $text);
            }

            $text = preg_replace('/[ \t]+/', ' ', (string) $text);
            $text = preg_replace('/\R{3,}/', "\n\n", (string) $text);

            return trim((string) $text);
        }

