        private function extract_crm_apply_chat_jd_signals($jd_text, array $post)
        {
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $haystack = implode("\n", array_filter([
                (string) $jd_text,
                $this->clean_crm_apply_chat_jd_text_for_analysis((string) ($post['content'] ?? '')),
                $this->clean_crm_apply_chat_jd_text_for_analysis((string) ($post['content_snippet'] ?? '')),
                is_array($post['requirements'] ?? null) ? implode("\n", array_map('strval', (array) $post['requirements'])) : (string) ($post['requirements'] ?? ''),
                is_array($post['skills_mentioned'] ?? null) ? implode("\n", array_map('strval', (array) $post['skills_mentioned'])) : (string) ($post['skills_mentioned'] ?? ''),
                (string) ($post['role_title'] ?? ''),
            ]));
            $haystack_norm = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
            $signals = [];

            foreach ($this->get_crm_apply_chat_signal_dictionary() as $signal) {
                $matched = false;
                foreach ((array) ($signal['synonyms'] ?? []) as $synonym) {
                    $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $synonym);
                    if ($needle !== '' && preg_match('/\b' . preg_quote($needle, '/') . '\b/i', $haystack_norm)) {
                        $matched = true;
                        break;
                    }
                }

                if ($matched) {
                    $signals[] = $signal;
                }
            }

            usort($signals, static function ($left, $right) {
                $priority = [
                    'hard_skill' => 1,
                    'experience_background' => 2,
                    'sector_exposure' => 3,
                    'language' => 4,
                    'credential' => 5,
                    'soft_signal' => 6,
                    'seniority_signal' => 7,
                ];
                $importance_rank = ['high' => 1, 'medium' => 2, 'low' => 3];

                $left_priority = (int) ($priority[$left['category'] ?? 'soft_signal'] ?? 99);
                $right_priority = (int) ($priority[$right['category'] ?? 'soft_signal'] ?? 99);
                if ($left_priority !== $right_priority) {
                    return $left_priority <=> $right_priority;
                }

                $left_importance = (int) ($importance_rank[$left['importance'] ?? 'low'] ?? 99);
                $right_importance = (int) ($importance_rank[$right['importance'] ?? 'low'] ?? 99);
                if ($left_importance !== $right_importance) {
                    return $left_importance <=> $right_importance;
                }

                return strcmp((string) ($left['label'] ?? ''), (string) ($right['label'] ?? ''));
            });

            return array_slice(array_values($signals), 0, 16);
        }

        private function extract_crm_apply_chat_role_keywords($jd_text, array $post)
        {
            $signals = $this->extract_crm_apply_chat_jd_signals($jd_text, $post);
            return array_values(array_map(static function ($signal) {
                return (string) ($signal['label'] ?? '');
            }, $signals));
        }

        private function match_crm_apply_chat_signal_against_cv(array $signal, $cv_norm)
        {
            $cv_norm = trim((string) $cv_norm);
            if ($cv_norm === '') {
                return 'unconfirmed';
            }

            foreach ((array) ($signal['synonyms'] ?? []) as $synonym) {
                $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $synonym);
                if ($needle !== '' && preg_match('/\b' . preg_quote($needle, '/') . '\b/i', $cv_norm)) {
                    return 'confirmed';
                }
            }

            foreach ((array) ($signal['adjacent'] ?? []) as $adjacent) {
                $needle = $this->normalize_crm_reddit_dashboard_cv_text((string) $adjacent);
                if ($needle !== '' && preg_match('/\b' . preg_quote($needle, '/') . '\b/i', $cv_norm)) {
                    return 'adjacent';
                }
            }

            foreach ((array) ($signal['synonyms'] ?? []) as $synonym) {
                $tokens = array_values(array_filter(explode(' ', $this->normalize_crm_reddit_dashboard_cv_text((string) $synonym))));
                if (count($tokens) < 2) {
                    continue;
                }

                $match_count = 0;
                foreach ($tokens as $token) {
                    if ($token !== '' && preg_match('/\b' . preg_quote($token, '/') . '\b/i', $cv_norm)) {
                        $match_count++;
                    }
                }

                if ($match_count >= max(2, count($tokens) - 1)) {
                    return 'adjacent';
                }
            }

            return 'unconfirmed';
        }

        private function extract_crm_apply_chat_cv_company_signal($cv_text)
        {
            $lines = preg_split('/\R+/', wp_strip_all_tags((string) $cv_text)) ?: [];
            $lines = array_values(array_filter(array_map(static function ($line) {
                return trim(preg_replace('/\s+/', ' ', (string) $line));
            }, $lines), static function ($line) {
                return $line !== '';
            }));

            $date_pattern = $this->get_crm_apply_chat_cv_date_pattern();
            $candidates = [];

            foreach ($lines as $index => $line) {
                if (!preg_match('/' . $date_pattern . '/iu', $line, $date_match, PREG_OFFSET_CAPTURE)) {
                    continue;
                }

                $date_text = (string) ($date_match[0][0] ?? '');
                $date_offset = (int) ($date_match[0][1] ?? 0);
                $before_date = trim(substr($line, 0, $date_offset));
                $after_date = trim(substr($line, $date_offset + strlen($date_text)));
                $is_current = (bool) preg_match('/\b(Present|Current|Now)\b/i', $date_text);

                $add_candidate = function ($value, $score, $source = '') use (&$candidates, $is_current) {
                    $candidate = $this->clean_crm_apply_chat_cv_company_candidate($value);
                    if ($candidate === '' || !$this->is_valid_crm_apply_chat_cv_company_candidate($candidate)) {
                        return;
                    }
                    $key = function_exists('mb_strtolower') ? mb_strtolower($candidate) : strtolower($candidate);
                    $score = (int) $score + ($is_current ? 30 : 0) + $this->score_crm_apply_chat_cv_company_candidate($candidate);
                    if (!isset($candidates[$key]) || $score > (int) ($candidates[$key]['score'] ?? 0)) {
                        $candidates[$key] = [
                            'company' => $candidate,
                            'score' => $score,
                            'source' => $source,
                        ];
                    }
                };

                if ($before_date !== '') {
                    $add_candidate($before_date, 58, 'before-date');
                }

                if ($after_date !== '') {
                    $after_date = preg_replace('/^[\s:|,;-]+/', '', $after_date);
                    if (preg_match('/(?:^|\s)(?:-|–|—|\|)\s*([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})$/u', $after_date, $company_match)) {
                        $add_candidate((string) $company_match[1], 72, 'after-date-title-company');
                    } elseif (preg_match('/^([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})(?:\s*[:|-|–|—]\s*.+)?$/u', $after_date, $company_match)) {
                        $add_candidate((string) $company_match[1], 44, 'after-date');
                    }
                }

                foreach ([-2, -1, 1, 2] as $offset) {
                    $nearby_index = $index + $offset;
                    if (!isset($lines[$nearby_index])) {
                        continue;
                    }

                    $nearby_line = (string) $lines[$nearby_index];
                    $base_score = 66 - (abs($offset) * 8);

                    if (strpos($nearby_line, '|') !== false) {
                        $parts = array_values(array_filter(array_map('trim', explode('|', $nearby_line))));
                        if (count($parts) >= 2) {
                            $add_candidate((string) end($parts), $base_score + 24, 'pipe-near-date');
                        }
                    }

                    if (preg_match('/(?:-|–|—)\s*([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})$/u', $nearby_line, $company_match)) {
                        $add_candidate((string) $company_match[1], $base_score + 12, 'dash-near-date');
                    }

                    if ($offset < 0) {
                        $add_candidate($nearby_line, $base_score, 'previous-line');
                    }
                }
            }

            if (empty($candidates)) {
                return '';
            }

            usort($candidates, static function ($left, $right) {
                return ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
            });

            return (string) ($candidates[0]['company'] ?? '');
        }

        private function extract_crm_apply_chat_cv_experience_entries($cv_text)
        {
            $lines = preg_split('/\R+/', wp_strip_all_tags((string) $cv_text)) ?: [];
            $lines = array_values(array_map(static function ($line) {
                return trim(preg_replace('/\s+/', ' ', (string) $line));
            }, $lines));
            $date_pattern = $this->get_crm_apply_chat_cv_date_pattern();
            $entries = [];
            $inside_experience = false;

            foreach ($lines as $index => $line) {
                if ($this->is_crm_apply_chat_cv_experience_section_heading($line)) {
                    $inside_experience = true;
                    continue;
                }

                if ($inside_experience && $this->is_crm_apply_chat_cv_non_experience_section_heading($line)) {
                    break;
                }

                if (!$inside_experience) {
                    continue;
                }

                if ($line === '' || !preg_match('/' . $date_pattern . '/iu', $line, $date_match, PREG_OFFSET_CAPTURE)) {
                    continue;
                }

                $date_text = (string) ($date_match[0][0] ?? '');
                $date_offset = (int) ($date_match[0][1] ?? 0);
                $before_date = trim(substr($line, 0, $date_offset));
                $after_date = trim(substr($line, $date_offset + strlen($date_text)));
                $context = [
                    'previous' => $this->get_crm_apply_chat_cv_nearby_nonempty_line($lines, $index, -1),
                    'next' => $this->get_crm_apply_chat_cv_nearby_nonempty_line($lines, $index, 1),
                ];
                $heading = $this->parse_crm_apply_chat_cv_experience_heading($before_date, $after_date, $context);
                $company = trim((string) ($heading['company'] ?? ''));
                $title = trim((string) ($heading['title'] ?? ''));

                if ($company === '' && $title === '') {
                    continue;
                }

                $bullets = $this->collect_crm_apply_chat_cv_experience_bullets($lines, $index + 1, $date_pattern);
                $sample_bullet = $this->select_crm_apply_chat_cv_experience_sample_bullet($bullets);
                $score = ($sample_bullet !== '' ? 40 : 0) + (preg_match('/\b(Present|Current|Now)\b/i', $date_text) ? 35 : 0);
                $score += $company !== '' ? 18 : 0;
                $score += $title !== '' ? 12 : 0;

                $entries[] = [
                    'title' => $title,
                    'company' => $company,
                    'date' => $date_text,
                    'bullets' => $bullets,
                    'sample_bullet' => $sample_bullet,
                    'score' => $score,
                ];
            }

            usort($entries, static function ($left, $right) {
                return ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
            });

            return array_values($entries);
        }

        private function get_crm_apply_chat_cv_date_pattern()
        {
            $month = '(?:Jan|January|Feb|February|Mar|March|Apr|April|May|Jun|June|Jul|July|Aug|August|Sep|Sept|September|Oct|October|Nov|November|Dec|December)';
            $date = '(?:(?:' . $month . ')\.?\s*(?:19|20)\d{2}|\d{1,2}\s*[\/.]\s*(?:\d{2}|(?:19|20)\d{2})|(?:19|20)\d{2})';
            return $date . '\s*(?:-|–|—|to)\s*(?:Present|Current|Now|' . $date . ')';
        }

        private function calculate_crm_apply_chat_cv_experience_years(array $experience_entries)
        {
            $ranges = [];
            foreach ($experience_entries as $entry) {
                $date_range = (string) ($entry['date'] ?? '');
                $parsed = $this->parse_crm_apply_chat_cv_date_range($date_range);
                if (empty($parsed['start']) || empty($parsed['end'])) {
                    continue;
                }
                $ranges[] = [
                    'start' => (int) $parsed['start'],
                    'end' => (int) $parsed['end'],
                ];
            }

            if (empty($ranges)) {
                return 0;
            }

            usort($ranges, static function ($left, $right) {
                return ((int) $left['start']) <=> ((int) $right['start']);
            });

            $merged = [];
            foreach ($ranges as $range) {
                if (empty($merged)) {
                    $merged[] = $range;
                    continue;
                }

                $last_index = count($merged) - 1;
                if ((int) $range['start'] <= ((int) $merged[$last_index]['end'] + 31 * DAY_IN_SECONDS)) {
                    $merged[$last_index]['end'] = max((int) $merged[$last_index]['end'], (int) $range['end']);
                } else {
                    $merged[] = $range;
                }
            }

            $total_seconds = 0;
            foreach ($merged as $range) {
                $total_seconds += max(0, (int) $range['end'] - (int) $range['start']);
            }

            return (int) floor($total_seconds / YEAR_IN_SECONDS);
        }

        private function parse_crm_apply_chat_cv_date_range($date_range)
        {
            $parts = preg_split('/\s*(?:-|–|—|to)\s*/i', trim((string) $date_range));
            if (count((array) $parts) < 2) {
                return [];
            }

            $start = $this->parse_crm_apply_chat_cv_date_token((string) $parts[0], false);
            $end = $this->parse_crm_apply_chat_cv_date_token((string) $parts[1], true);
            if ($start <= 0 || $end <= 0 || $end < $start) {
                return [];
            }

            return [
                'start' => $start,
                'end' => $end,
            ];
        }

        private function parse_crm_apply_chat_cv_date_token($token, $allow_present = false)
        {
            $token = trim((string) $token);
            if ($allow_present && preg_match('/^(Present|Current|Now)/i', $token)) {
                return current_time('timestamp');
            }

            $month = 1;
            $month_map = [
                'jan' => 1, 'january' => 1, 'feb' => 2, 'february' => 2, 'mar' => 3, 'march' => 3,
                'apr' => 4, 'april' => 4, 'may' => 5, 'jun' => 6, 'june' => 6, 'jul' => 7, 'july' => 7,
                'aug' => 8, 'august' => 8, 'sep' => 9, 'sept' => 9, 'september' => 9, 'oct' => 10,
                'october' => 10, 'nov' => 11, 'november' => 11, 'dec' => 12, 'december' => 12,
            ];

            if (preg_match('/\b(' . implode('|', array_keys($month_map)) . ')\.?\b/i', $token, $month_match)) {
                $month_key = strtolower((string) $month_match[1]);
                $month = (int) ($month_map[$month_key] ?? 1);
            } elseif (preg_match('/\b(\d{1,2})\s*[\/.]\s*(\d{2,4})\b/', $token, $numeric_match)) {
                $month = max(1, min(12, (int) $numeric_match[1]));
            }

            if (!preg_match('/\b((?:19|20)\d{2}|\d{2})\b(?!.*\b(?:19|20)?\d{2}\b)/', $token, $year_match)) {
                return 0;
            }

            $year = (int) $year_match[1];
            if ($year < 100 && preg_match('/\d{1,2}\s*[\/.]\s*\d{2}\b/', $token)) {
                $year += $year >= 70 ? 1900 : 2000;
            } elseif ($year < 100) {
                return 0;
            }

            return strtotime(sprintf('%04d-%02d-01 00:00:00', $year, $month)) ?: 0;
        }

        private function is_crm_apply_chat_cv_experience_section_heading($line)
        {
            $line = trim((string) $line);
            return (bool) preg_match('/^(Professional\s+Experience|Work\s+Experience|Employment\s+History|Career\s+History|Relevant\s+Experience|Selected\s+Experience|Professional\s+History|Work\s+History|Experience(?:\s*&\s*(?:Projects|Leadership|Achievements))?|Career\s+Experience|Employment\s+Experience)$/i', $line);
        }

        private function is_crm_apply_chat_cv_non_experience_section_heading($line)
        {
            $line = trim((string) $line);
            return (bool) preg_match('/^(Education(?:\s*&\s*Qualifications)?|Education\s+and\s+Qualifications|Academic\s+Background|Qualifications|Skills|Core\s+Competencies|Technical\s+Skills|Languages|Certifications|References|Training|Courses|Professional\s+Development|Interests|Additional\s+Information|Awards|Publications)$/i', $line);
        }

        private function extract_crm_apply_chat_required_years(array $post, $jd_text)
        {
            foreach (['experience_years', 'years_experience', 'experience_required', 'required_years'] as $field) {
                $value = trim((string) ($post[$field] ?? ''));
                if ($value !== '') {
                    return $value;
                }
            }

            if (preg_match('/\b(\d{1,2}\s*(?:-|–|—)\s*\d{1,2}\s*\+?\s*(?:years?|yrs?)|\d{1,2}\s*\+?\s*(?:years?|yrs?))(?:\s+of)?\s+(?:relevant\s+)?experience\b/i', (string) $jd_text, $match)) {
                return trim((string) $match[1]);
            }

            return '';
        }

        private function extract_crm_apply_chat_requirement_gaps($cv_text, $jd_text, array $post, $visible_experience_years, $required_years, array $jd_signals = [], array $unconfirmed_signals = [])
        {
            $gaps = [];
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $cv_norm = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $required_range = $this->parse_crm_apply_chat_required_years_range($required_years);

            if (!empty($required_range) && (int) $visible_experience_years > 0 && (int) $visible_experience_years < (int) ($required_range['min'] ?? 0)) {
                $gaps[] = [
                    'type' => 'experience',
                    'label' => sprintf(__('%s experience', 'senna-finance'), $required_years),
                    'message' => sprintf(__('The role asks for %1$s, and the CV visibly shows about %2$d years from dated roles.', 'senna-finance'), $required_years, (int) $visible_experience_years),
                ];
            }

            foreach ($unconfirmed_signals as $signal) {
                $category = (string) ($signal['category'] ?? '');
                $label = (string) ($signal['label'] ?? '');
                if ($label === '') {
                    continue;
                }
                if ($category === 'language' && !empty($signal['needs_confirmation_if_unmatched'])) {
                    $gaps[] = [
                        'type' => 'language',
                        'label' => ucfirst($label),
                        'message' => sprintf(__('I cannot confirm %s from the CV yet, so Emily needs to check that with you rather than assume it.', 'senna-finance'), ucfirst($label)),
                    ];
                    continue;
                }
                if ($category === 'credential' && $label === 'regional work authorization' && !empty($signal['needs_confirmation_if_unmatched'])) {
                    $gaps[] = [
                        'type' => 'work_authorization',
                        'label' => __('regional work authorization', 'senna-finance'),
                        'message' => __('I cannot confirm your regional work authorization status from the CV yet, so Emily needs to check that with you rather than assume it.', 'senna-finance'),
                    ];
                }
            }

            foreach ($this->extract_crm_apply_chat_required_languages($jd_text, $post) as $language) {
                $language_needles = [
                    strtolower((string) $language),
                    'fluent ' . strtolower((string) $language),
                    'native ' . strtolower((string) $language),
                    strtolower((string) $language) . ' speaker',
                ];
                if (!$this->crm_apply_chat_cv_mentions_requirement($cv_norm, $language_needles)) {
                    $gaps[] = [
                        'type' => 'language',
                        'label' => (string) $language,
                        'message' => sprintf(__('The role appears to require %s, but I cannot see it clearly on the CV yet.', 'senna-finance'), (string) $language),
                    ];
                }
            }

            foreach ($this->extract_crm_apply_chat_required_qualifications($jd_text, $post) as $qualification) {
                if (!$this->crm_apply_chat_cv_mentions_requirement($cv_norm, (array) ($qualification['needles'] ?? []))) {
                    $gaps[] = [
                        'type' => 'qualification',
                        'label' => (string) ($qualification['label'] ?? ''),
                        'message' => sprintf(__('I cannot confirm %s from the CV yet, so Emily needs to check that with you rather than assume it.', 'senna-finance'), (string) ($qualification['label'] ?? __('a required qualification', 'senna-finance'))),
                    ];
                }
            }

            $deduped = [];
            $seen = [];
            foreach ($gaps as $gap) {
                if (!is_array($gap)) {
                    continue;
                }
                $key = sanitize_key(((string) ($gap['type'] ?? '')) . '_' . strtolower((string) ($gap['label'] ?? '')));
                if ($key !== '_' && isset($seen[$key])) {
                    continue;
                }
                if ($key !== '_') {
                    $seen[$key] = true;
                }
                $deduped[] = $gap;
            }

            return array_slice($deduped, 0, 4);
        }

        private function parse_crm_apply_chat_required_years_range($required_years)
        {
            $required_years = trim((string) $required_years);
            if ($required_years === '') {
                return [];
            }
            if (preg_match('/(\d{1,2})\s*(?:-|–|—)\s*(\d{1,2})/', $required_years, $match)) {
                return ['min' => (int) $match[1], 'max' => (int) $match[2]];
            }
            if (preg_match('/(\d{1,2})\s*\+/', $required_years, $match)) {
                return ['min' => (int) $match[1], 'max' => 99];
            }
            if (preg_match('/(\d{1,2})/', $required_years, $match)) {
                return ['min' => (int) $match[1], 'max' => (int) $match[1]];
            }

            return [];
        }

        private function extract_crm_apply_chat_required_languages($jd_text, array $post)
        {
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $haystack = implode(' ', array_filter([
                (string) $jd_text,
                implode(' ', array_map('strval', (array) ($post['languages'] ?? []))),
                implode(' ', array_map('strval', (array) ($post['language_requirements'] ?? []))),
                (string) ($post['language'] ?? ''),
            ]));
            $languages = [
                'Arabic' => ['arabic', 'fluent arabic', 'native arabic'],
                'English' => ['english', 'fluent english'],
                'French' => ['french'],
                'German' => ['german'],
                'Dutch' => ['dutch'],
                'Italian' => ['italian'],
                'Spanish' => ['spanish'],
                'Mandarin' => ['mandarin', 'chinese'],
                'Japanese' => ['japanese'],
                'Korean' => ['korean'],
                'Hindi' => ['hindi'],
                'Portuguese' => ['portuguese'],
                'Turkish' => ['turkish'],
            ];
            $required = [];
            $haystack_norm = $this->normalize_crm_reddit_dashboard_cv_text($haystack);

            foreach ($languages as $label => $needles) {
                foreach ($needles as $needle) {
                    $needle_norm = $this->normalize_crm_reddit_dashboard_cv_text($needle);
                    if ($needle_norm !== '' && preg_match('/\b(required|must|fluent|native|bilingual|proficient|excellent|written|spoken|language)[^.]{0,80}\b' . preg_quote($needle_norm, '/') . '\b|\b' . preg_quote($needle_norm, '/') . '\b[^.]{0,80}\b(required|must|fluent|native|bilingual|proficient|written|spoken|language)\b/i', $haystack_norm)) {
                        $required[] = $label;
                        break;
                    }
                }
            }

            return array_values(array_unique($required));
        }

        private function extract_crm_apply_chat_required_qualifications($jd_text, array $post)
        {
            $jd_text = $this->clean_crm_apply_chat_jd_text_for_analysis($jd_text);
            $haystack = implode(' ', array_filter([
                (string) $jd_text,
                implode(' ', array_map('strval', (array) ($post['qualifications'] ?? []))),
                implode(' ', array_map('strval', (array) ($post['requirements'] ?? []))),
            ]));
            $haystack_norm = $this->normalize_crm_reddit_dashboard_cv_text($haystack);
            $qualification_dictionary = method_exists($this, 'get_crm_editorial_community_qualification_dictionary')
                ? $this->get_crm_editorial_community_qualification_dictionary()
                : [];

            if (empty($qualification_dictionary)) {
                $qualification_dictionary = [
                    'CFA' => ['cfa', 'chartered financial analyst'],
                    'ACA' => ['aca', 'icaew', 'chartered accountant'],
                    'ACCA' => ['acca'],
                    'CPA' => ['cpa', 'certified public accountant'],
                    'MBA' => ['mba'],
                    'Master\'s degree' => ['masters degree', 'master\'s degree', 'msc', 'm.sc'],
                    'Bachelor\'s degree' => ['bachelor', 'bsc', 'ba degree'],
                ];
            }
            $actual_qualification_labels = [
                'ACCA',
                'ACA',
                'CIMA',
                'CFA',
                'CPA',
                'CAIA',
                'FRM',
                'CMA',
                'MBA',
                'IFRS',
                'Bachelor\'s degree',
                'Master\'s degree',
            ];
            $qualification_dictionary = array_intersect_key(
                $qualification_dictionary,
                array_fill_keys($actual_qualification_labels, true)
            );
            $qualification_dictionary['Master\'s degree'] = array_values(array_unique(array_merge(
                (array) ($qualification_dictionary['Master\'s degree'] ?? []),
                ['masters degree', 'master degree', 'master\'s degree', 'msc', 'm sc', 'advanced degree']
            )));
            $qualification_dictionary['Bachelor\'s degree'] = array_values(array_unique(array_merge(
                (array) ($qualification_dictionary['Bachelor\'s degree'] ?? []),
                ['bachelor', 'bachelors degree', 'bachelor\'s degree', 'ba', 'bsc', 'undergraduate degree']
            )));

            $required = [];
            foreach ($qualification_dictionary as $label => $needles) {
                foreach ((array) $needles as $needle) {
                    $needle_norm = trim($this->normalize_crm_reddit_dashboard_cv_text(str_replace(['.', '-'], [' ', ' '], (string) $needle)));
                    if ($needle_norm === '') {
                        continue;
                    }
                    if (preg_match('/\b(required|must|qualified|qualification|degree|certification|preferred|desirable|holder|chartered)[^.]{0,100}\b' . preg_quote($needle_norm, '/') . '\b|\b' . preg_quote($needle_norm, '/') . '\b[^.]{0,100}\b(required|must|qualified|qualification|degree|certification|preferred|desirable|holder|chartered)\b/i', $haystack_norm)) {
                        $required[] = [
                            'label' => (string) $label,
                            'needles' => (array) $needles,
                        ];
                        break;
                    }
                }
            }

            return array_slice($required, 0, 4);
        }

        private function crm_apply_chat_cv_mentions_requirement($cv_norm, array $needles)
        {
            $cv_norm = $this->normalize_crm_reddit_dashboard_cv_text(str_replace(['.', '-'], [' ', ' '], (string) $cv_norm));
            foreach ($needles as $needle) {
                $needle_norm = trim($this->normalize_crm_reddit_dashboard_cv_text(str_replace(['.', '-'], [' ', ' '], (string) $needle)));
                if ($needle_norm !== '' && preg_match('/\b' . preg_quote($needle_norm, '/') . '\b/i', $cv_norm)) {
                    return true;
                }
            }

            return false;
        }

        private function parse_crm_apply_chat_cv_experience_heading($before_date, $after_date, array $context = [])
        {
            $before_date = trim((string) $before_date);
            $after_date = trim(preg_replace('/^[\s:|,;-]+/', '', (string) $after_date));
            $previous = trim((string) ($context['previous'] ?? ''));
            $title = '';
            $company = '';

            if ($before_date !== '' && strpos($before_date, '|') !== false) {
                $parts = array_values(array_filter(array_map('trim', explode('|', $before_date))));
                $title = (string) ($parts[0] ?? '');
                $company = (string) end($parts);
            } elseif ($before_date === '' && $after_date === '' && $previous !== '') {
                if (strpos($previous, '|') !== false) {
                    $parts = array_values(array_filter(array_map('trim', explode('|', $previous))));
                    $title = (string) ($parts[0] ?? '');
                    $company = (string) end($parts);
                } elseif (preg_match('/^(.{3,80}?)\s*(?:-|–|—)\s*([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})$/u', $previous, $match)) {
                    $title = trim((string) $match[1]);
                    $company = trim((string) $match[2]);
                } else {
                    $company = $previous;
                }
            } elseif ($after_date !== '' && preg_match('/^(.{3,80}?)\s*(?:-|–|—|\|)\s*([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})/u', $after_date, $match)) {
                $title = trim((string) $match[1]);
                $company = trim((string) $match[2]);
            } elseif ($before_date !== '' && $after_date !== '') {
                $company = $before_date;
                $title = preg_replace('/^:\s*/', '', $after_date);
            } elseif ($before_date !== '' && $previous !== '') {
                $title = $before_date;
                $company = $previous;
            } elseif ($after_date !== '') {
                $title = $after_date;
                $company = $previous;
            } elseif ($before_date !== '') {
                $company = $before_date;
            }

            $company = $this->clean_crm_apply_chat_cv_company_candidate($company);
            if (!$this->is_valid_crm_apply_chat_cv_company_candidate($company)) {
                $company = '';
            }

            $title = $this->clean_crm_apply_chat_cv_role_title_candidate($title);

            return [
                'title' => $title,
                'company' => $company,
            ];
        }

        private function collect_crm_apply_chat_cv_experience_bullets(array $lines, $start_index, $date_pattern)
        {
            $bullets = [];
            $current = '';
            $pending_bullet_marker = false;
            $max_scan = min(count($lines), (int) $start_index + 24);

            for ($index = (int) $start_index; $index < $max_scan; $index++) {
                $line = trim((string) ($lines[$index] ?? ''));
                if ($line === '') {
                    continue;
                }
                if (preg_match('/' . $date_pattern . '/iu', $line)) {
                    break;
                }
                if (preg_match('/^(Education|Qualifications|Skills|Core Competencies|Languages|Certifications|References|Work Experience|Professional Experience)$/i', $line)) {
                    break;
                }
                if (preg_match('/^(Main Responsibilities|Key activities|Responsibilities|Achievements)\s*:?\s*$/i', $line)) {
                    continue;
                }
                if (preg_match('/^\d+\s*-\s*[^.]{2,80}:?$/u', $line)) {
                    continue;
                }

                if (preg_match('/^[▪•●\-–—*]$/u', $line)) {
                    if ($current !== '') {
                        $bullets[] = $current;
                        $current = '';
                    }
                    $pending_bullet_marker = true;
                    continue;
                }

                if (preg_match('/^(?:[▪•●\-–—*]|\d+[.)-])\s*(.+)$/u', $line, $match)) {
                    if ($current !== '') {
                        $bullets[] = $current;
                    }
                    $current = trim((string) $match[1]);
                    $pending_bullet_marker = false;
                    continue;
                }

                if ($pending_bullet_marker) {
                    $current = $line;
                    $pending_bullet_marker = false;
                } elseif ($current !== '' && !$this->looks_like_crm_apply_chat_cv_experience_heading($line, $date_pattern)) {
                    $current = trim($current . ' ' . $line);
                }
            }

            if ($current !== '') {
                $bullets[] = $current;
            }

            $bullets = array_values(array_filter(array_map(static function ($bullet) {
                $bullet = trim(preg_replace('/\s+/', ' ', (string) $bullet));
                return strlen($bullet) >= 20 ? $bullet : '';
            }, $bullets)));

            return array_slice($bullets, 0, 6);
        }

        private function select_crm_apply_chat_cv_experience_sample_bullet(array $bullets)
        {
            if (empty($bullets)) {
                return '';
            }

            usort($bullets, static function ($left, $right) {
                $left_has_number = preg_match('/\b\d/', (string) $left) ? 1 : 0;
                $right_has_number = preg_match('/\b\d/', (string) $right) ? 1 : 0;
                if ($left_has_number !== $right_has_number) {
                    return $left_has_number <=> $right_has_number;
                }

                return strlen((string) $right) <=> strlen((string) $left);
            });

            return (string) ($bullets[0] ?? '');
        }

        private function looks_like_crm_apply_chat_cv_experience_heading($line, $date_pattern)
        {
            $line = trim((string) $line);
            if ($line === '') {
                return false;
            }

            return (bool) (
                preg_match('/' . $date_pattern . '/iu', $line)
                || strpos($line, '|') !== false
                || preg_match('/\b(Analyst|Associate|Manager|Director|Consultant|Assistant|Lead|Head|Officer|Specialist|Advisor|Mentor|Intern|Executive|SVP|VP|Vice President)\b/i', $line)
            );
        }

        private function get_crm_apply_chat_cv_nearby_nonempty_line(array $lines, $index, $direction)
        {
            $direction = (int) $direction < 0 ? -1 : 1;
            for ($offset = 1; $offset <= 3; $offset++) {
                $candidate = trim((string) ($lines[(int) $index + ($offset * $direction)] ?? ''));
                if ($candidate !== '') {
                    return $candidate;
                }
            }

            return '';
        }

        private function clean_crm_apply_chat_cv_role_title_candidate($candidate)
        {
            $candidate = trim(wp_strip_all_tags((string) $candidate));
            $candidate = preg_replace('/\s+/', ' ', (string) $candidate);
            $candidate = preg_replace('/\s+\b(?:LONDON|MILAN|DUBAI|ABU DHABI|NEW YORK|PARIS|RIYADH|UAE|U\.A\.E|UK|ITALY|USA|KSA)\b(?:,\s*[A-Z .]+)?$/iu', '', (string) $candidate);
            $candidate = trim((string) $candidate, " \t\n\r\0\x0B-|:,;");
            if (strlen($candidate) > 90) {
                $candidate = '';
            }

            return $candidate;
        }

        private function clean_crm_apply_chat_cv_company_candidate($candidate)
        {
            $candidate = trim(wp_strip_all_tags((string) $candidate));
            $candidate = preg_replace('/\s+/', ' ', $candidate);
            $candidate = preg_replace('/^(?:at|with|for)\s+/i', '', (string) $candidate);
            $candidate = preg_replace('/\s+(?:Remote|Hybrid|On-site|Onsite)$/i', '', (string) $candidate);
            $candidate = preg_replace('/\s+\b(?:LONDON|MILAN|DUBAI|ABU DHABI|NEW YORK|PARIS|RIYADH|UAE|U\.A\.E|UK|ITALY|USA|KSA)\b(?:,\s*[A-Z .]+)?$/iu', '', (string) $candidate);
            $candidate = trim((string) $candidate, " \t\n\r\0\x0B-|:,;");

            if (strpos($candidate, '|') !== false) {
                $parts = array_values(array_filter(array_map('trim', explode('|', $candidate))));
                $candidate = (string) end($parts);
            }

            if (preg_match('/(?:^|\s)(?:-|–|—)\s*([A-Z][A-Za-z0-9&.,\'()\/ -]{2,100})$/u', $candidate, $match)) {
                $candidate = trim((string) $match[1]);
            }

            return trim($candidate);
        }

        private function is_valid_crm_apply_chat_cv_company_candidate($candidate)
        {
            $candidate = trim((string) $candidate);
            if ($candidate === '' || strlen($candidate) < 3 || strlen($candidate) > 90) {
                return false;
            }
            if (!preg_match('/[A-Za-z]/', $candidate)) {
                return false;
            }
            if (preg_match('/\b(Present|Current|Professional Experience|Experience|Employment|Education|Skills|Responsibilities|Achievements|Summary|Profile|Department|Division)\b/i', $candidate)) {
                return false;
            }
            if (preg_match('/\b(Analyst|Associate|Manager|Director|Consultant|Assistant|Lead|Head|Officer|Specialist|Advisor|Mentor|Intern|Executive|SVP|VP|Vice President)\b/i', $candidate) && !preg_match('/\b(Bank|Group|Capital|Partners|Society|AG|Ltd|Limited|LLC|LLP|Inc|Corp|Corporation|Company|Co\.|S\.p\.A\.|PLC|plc|GmbH|SAS|SA|Fund|Funds|Equity|Ventures|Accenture|Deloitte|PwC|KPMG|EY)\b/u', $candidate)) {
                return false;
            }
            if (str_word_count($candidate) > 8) {
                return false;
            }

            return true;
        }

        private function score_crm_apply_chat_cv_company_candidate($candidate)
        {
            $score = 0;
            if (preg_match('/\b(Bank|Group|Capital|Partners|Society|AG|Ltd|Limited|LLC|LLP|Inc|Corp|Corporation|Company|Co\.|S\.p\.A\.|PLC|plc|GmbH|SAS|SA|Fund|Funds|Equity|Ventures|Advisory|Consulting)\b/u', (string) $candidate)) {
                $score += 18;
            }
            if (preg_match('/\b(Self-Employed|Freelance|Independent)\b/i', (string) $candidate)) {
                $score -= 35;
            }
            if (preg_match('/^[A-Z][A-Za-z0-9&.,\'()\/ -]+$/u', (string) $candidate)) {
                $score += 8;
            }

            return $score;
        }

