        private function get_crm_post_article_layout_similar_posts(array $post, $limit = 3)
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $current_id = absint($post['id'] ?? 0);
            $role_title = trim((string) ($post['role_title'] ?? ''));
            $role_base = preg_replace('/\s*\([^)]*\)/', '', $role_title);
            $role_base = preg_replace('/,\s*.+$/', '', (string) $role_base);
            $role_base = trim((string) $role_base);
            $company = trim((string) ($post['company'] ?? ''));
            $sector = trim((string) ($post['sector'] ?? ''));

            $where = [
                'id <> %d',
                'is_active = 1',
                'admin_approved = 1',
                "(post_status IS NULL OR post_status = 'open')",
            ];
            $params = [$current_id];

            $matching = [];
            if ($company !== '') {
                $matching[] = 'company = %s';
                $params[] = $company;
            }
            if ($role_base !== '') {
                $matching[] = 'role_title LIKE %s';
                $params[] = '%' . $wpdb->esc_like($role_base) . '%';
            }
            if ($sector !== '') {
                $matching[] = 'sector = %s';
                $params[] = $sector;
            }

            if (!empty($matching)) {
                $where[] = '(' . implode(' OR ', $matching) . ')';
            }

            $sql = "
                SELECT p.id, p.role_title, p.location, p.company, p.content, p.content_snippet, p.posted_at, p.jobs_post_id, p.wp_post_id,
                       r.name as recruiter_name, r.firm as recruiter_firm,
                       r.photo_url as recruiter_photo, r.title as recruiter_title
                FROM {$table} p
                LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id
                WHERE " . implode(' AND ', array_map(static function ($clause) {
                    return str_replace(
                        ['id <> %d', 'is_active = 1', 'admin_approved = 1', "post_status IS NULL OR post_status = 'open'", 'company = %s', 'role_title LIKE %s', 'sector = %s'],
                        ['p.id <> %d', 'p.is_active = 1', 'p.admin_approved = 1', "p.post_status IS NULL OR p.post_status = 'open'", 'p.company = %s', 'p.role_title LIKE %s', 'p.sector = %s'],
                        $clause
                    );
                }, $where)) . "
                ORDER BY
                    CASE WHEN p.company = %s THEN 0 ELSE 1 END,
                    CASE WHEN p.role_title LIKE %s THEN 0 ELSE 1 END,
                    p.posted_at DESC
                LIMIT %d
            ";

            $params[] = $company;
            $params[] = '%' . $wpdb->esc_like($role_base !== '' ? $role_base : $role_title) . '%';
            $params[] = max(1, min(6, (int) $limit));

            return (array) $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);
        }

        private function get_crm_post_article_layout_similar_post_url(array $post)
        {
            foreach (['jobs_post_id', 'wp_post_id'] as $key) {
                $wp_post_id = absint($post[$key] ?? 0);
                if ($wp_post_id <= 0) {
                    continue;
                }

                $wp_post = get_post($wp_post_id);
                if (!$wp_post instanceof WP_Post || $wp_post->post_type !== 'jobs' || $wp_post->post_status === 'trash') {
                    continue;
                }

                $permalink = get_permalink($wp_post_id);
                if ($permalink) {
                    return (string) $permalink;
                }
            }

            return SFFC_CRM_Post_Type::get_post_url((int) ($post['id'] ?? 0));
        }

