        private function resolve_current_crm_post_id($raw_post_id = 0)
        {
            $post_id = absint($raw_post_id);
            if ($post_id > 0) {
                return $post_id;
            }

            $query_var_post_id = absint((int) get_query_var('sffc_crm_post_id'));
            if ($query_var_post_id > 0) {
                return $query_var_post_id;
            }

            $request_post_id = absint(isset($_GET['crm_post_id']) ? (int) $_GET['crm_post_id'] : 0);
            if ($request_post_id > 0) {
                return $request_post_id;
            }

            $prefill_post_id = absint(isset($_GET['sffc_prefill_post']) ? (int) $_GET['sffc_prefill_post'] : 0);
            if ($prefill_post_id > 0) {
                return $prefill_post_id;
            }

            if (!empty($GLOBALS['sffc_crm_current_post']) && is_array($GLOBALS['sffc_crm_current_post'])) {
                $global_post_id = absint((int) ($GLOBALS['sffc_crm_current_post']['id'] ?? 0));
                if ($global_post_id > 0) {
                    return $global_post_id;
                }
            }

            $queried_object = get_queried_object();
            if ($queried_object instanceof WP_Post) {
                if ($queried_object->post_type === 'sffc_recruiter_post' || $queried_object->post_type === 'sffc_crm_post') {
                    $linked_crm_post_id = absint((int) get_post_meta($queried_object->ID, '_crm_post_id', true));
                    if ($linked_crm_post_id > 0) {
                        return $linked_crm_post_id;
                    }
                    if ($queried_object->post_type === 'sffc_crm_post') {
                        return absint($queried_object->ID);
                    }
                }

                if ($queried_object->post_type === 'jobs') {
                    $linked_crm_post_id = absint((int) get_post_meta($queried_object->ID, '_crm_post_id', true));
                    if ($linked_crm_post_id > 0) {
                        return $linked_crm_post_id;
                    }
                }
            }

            return $this->get_random_live_crm_post_id();
        }

        private function resolve_current_crm_post_id_without_random_fallback($raw_post_id = 0)
        {
            $post_id = absint($raw_post_id);
            if ($post_id > 0) {
                return $post_id;
            }

            $query_var_post_id = absint((int) get_query_var('sffc_crm_post_id'));
            if ($query_var_post_id > 0) {
                return $query_var_post_id;
            }

            $request_post_id = absint(isset($_GET['crm_post_id']) ? (int) $_GET['crm_post_id'] : 0);
            if ($request_post_id > 0) {
                return $request_post_id;
            }

            $prefill_post_id = absint(isset($_GET['sffc_prefill_post']) ? (int) $_GET['sffc_prefill_post'] : 0);
            if ($prefill_post_id > 0) {
                return $prefill_post_id;
            }

            if (!empty($GLOBALS['sffc_crm_current_post']) && is_array($GLOBALS['sffc_crm_current_post'])) {
                $global_post_id = absint((int) ($GLOBALS['sffc_crm_current_post']['id'] ?? 0));
                if ($global_post_id > 0) {
                    return $global_post_id;
                }
            }

            $queried_object = get_queried_object();
            if ($queried_object instanceof WP_Post) {
                if ($queried_object->post_type === 'sffc_recruiter_post' || $queried_object->post_type === 'jobs' || $queried_object->post_type === 'sffc_crm_post') {
                    $linked_crm_post_id = absint((int) get_post_meta($queried_object->ID, '_crm_post_id', true));
                    if ($linked_crm_post_id > 0) {
                        return $linked_crm_post_id;
                    }
                    if ($queried_object->post_type === 'sffc_crm_post') {
                        return absint($queried_object->ID);
                    }
                }
            }

            return 0;
        }

        private function get_random_live_crm_post_id()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_posts';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
            if ($table_exists !== $table) {
                return 0;
            }

            $post_id = (int) $wpdb->get_var(
                "SELECT id
                 FROM {$table}
                 WHERE (is_active = 1 OR is_active IS NULL)
                   AND admin_approved = 1
                   AND (post_status IS NULL OR post_status = 'open')
                 ORDER BY RAND()
                 LIMIT 1"
            );

            return $post_id > 0 ? $post_id : 0;
        }

        /**
         * Render auto-sliding recruiter carousel for membership page
         * Usage: [sffc_recruiter_carousel posts_per_page="10" auto_slide_interval="5000"]
         */
        public function render_recruiter_carousel($atts)
        {
            $atts = shortcode_atts([
                'posts_per_page' => 10,
                'auto_slide_interval' => 5000, // 5 seconds
            ], $atts);

            $args = [
                'post_type' => 'sffc_recruiter_post',
                'posts_per_page' => intval($atts['posts_per_page']),
                'post_status' => 'publish',
                'orderby' => 'rand',
            ];

            $query = new WP_Query($args);

            if (!$query->have_posts()) {
                return '';
            }

            $carousel_recruiters = [];

            while ($query->have_posts()) : $query->the_post();
                $post_id = get_the_ID();
                $job_title = get_post_meta($post_id, '_job_title', true) ?: get_the_title();
                $company = get_post_meta($post_id, '_company_name', true);
                $location = get_post_meta($post_id, '_job_location', true);
                $salary_min = get_post_meta($post_id, '_salary_min', true);
                $salary_max = get_post_meta($post_id, '_salary_max', true);
                $salary_currency = get_post_meta($post_id, '_salary_currency', true) ?: 'AED';
                $recruiter_name = get_post_meta($post_id, '_recruiter_name', true);
                $recruiter_company = get_post_meta($post_id, '_recruiter_company', true);

                $recruiter_image_id = get_post_meta($post_id, '_recruiter_image_id', true);
                $recruiter_image_url = $recruiter_image_id ? wp_get_attachment_image_url($recruiter_image_id, 'thumbnail') : '';
                if (!$recruiter_image_url) {
                    $recruiter_image_url = get_post_meta($post_id, '_recruiter_image_url', true);
                }

                $salary_display = '';
                if ($salary_min && $salary_max) {
                    $salary_display = $salary_currency . ' ' . number_format($salary_min) . ' - ' . number_format($salary_max);
                } elseif ($salary_min) {
                    $salary_display = $salary_currency . ' ' . number_format($salary_min) . '+';
                }

                $initial = $recruiter_name ? (function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1)) : 'R';

                $carousel_recruiters[] = [
                    'post_id' => $post_id,
                    'job_title' => $job_title ?: __('Confidential Role', 'senna-finance'),
                    'company' => $company,
                    'location' => $location,
                    'salary_display' => $salary_display,
                    'recruiter_name' => $recruiter_name,
                    'recruiter_company' => $recruiter_company,
                    'avatar_url' => $recruiter_image_url,
                    'initial' => $initial ?: 'R',
                ];
            endwhile;
            wp_reset_postdata();

            $plan_entries = $this->get_subscription_plans();
            $membership_stats = $this->get_membership_social_proof_stats();
            $personalization = $this->get_recruiter_carousel_personalization();
            $prepared_plans = array();
            $monthly_plans = array();
            $annual_plans = array();

            foreach ($plan_entries as $plan) {
                $prepared_plan = $this->prepare_recruiter_pricing_plan($plan, $membership_stats);
                $prepared_plan = $this->personalize_recruiter_pricing_plan($prepared_plan, $personalization);
                $prepared_plans[] = $prepared_plan;

                if ('annual' === $prepared_plan['cycle']) {
                    $annual_plans[] = $prepared_plan;
                } else {
                    $monthly_plans[] = $prepared_plan;
                }
            }

            $primary_monthly_plan = $this->get_primary_cycle_plan($monthly_plans);
            $primary_annual_plan = $this->get_primary_cycle_plan($annual_plans);
            $default_selected_plan = $primary_monthly_plan ?: $primary_annual_plan ?: (!empty($prepared_plans) ? $prepared_plans[0] : null);
            $default_selected_slug = $default_selected_plan['slug'] ?? '';
            $default_cycle = $default_selected_plan['cycle'] ?? 'monthly';
            $other_plans = array_values(array_filter($prepared_plans, function ($plan) use ($primary_monthly_plan, $primary_annual_plan) {
                return $plan['slug'] !== ($primary_monthly_plan['slug'] ?? '') && $plan['slug'] !== ($primary_annual_plan['slug'] ?? '');
            }));

            $this->output_timezone_cookie_script();

            ob_start();
        ?>
            <div class="sffc-recruiter-carousel-wrapper" data-interval="<?php echo esc_attr($atts['auto_slide_interval']); ?>">
                <?php if (!empty($prepared_plans) && $default_selected_plan) : ?>
                    <div class="sffc-carousel-plans" id="sffcCarouselPlans" data-default-cycle="<?php echo esc_attr($default_cycle); ?>">
                        <?php if (!empty($monthly_plans) && !empty($annual_plans)) : ?>
                            <div class="sffc-carousel-cycle-toggle" role="tablist" aria-label="<?php esc_attr_e('Billing cycle', 'senna-finance'); ?>">
                                <button type="button" class="sffc-carousel-cycle-btn<?php echo 'monthly' === $default_cycle ? ' is-active' : ''; ?>" data-carousel-cycle-toggle="monthly" aria-pressed="<?php echo 'monthly' === $default_cycle ? 'true' : 'false'; ?>">
                                    <?php esc_html_e('Monthly', 'senna-finance'); ?>
