                            <div class="sffc-carousel-browser-badge" data-carousel-browser-badge><?php echo esc_html(!empty($default_selected_plan['featured_signup']) ? __('Most popular', 'senna-finance') : __('Recommended', 'senna-finance')); ?></div>
