        /**
         * Compact upgrade cards that reuse the same plan and MemberPress sources as the recruiter carousel.
         * Usage: [sffc_recruiter_upgrade_cards]
         */
        public function render_recruiter_upgrade_cards($atts = [])
        {
            $atts = shortcode_atts([
                'title' => __('Choose your recruiter outreach plan', 'senna-finance'),
                'subtitle' => __('Upgrade when you need more recruiter credits, saved lists, and introduction support.', 'senna-finance'),
                'default_cycle' => 'monthly',
            ], $atts, 'sffc_recruiter_upgrade_cards');

            wp_enqueue_style(
                'sffc-recruiter-carousel',
                SFFC_PLUGIN_URL . 'assets/css/crm/recruiter-carousel.css',
                [],
                defined('SFFC_VERSION') ? SFFC_VERSION : null
            );

            wp_enqueue_script(
                'sffc-recruiter-upgrade-cards',
                SFFC_PLUGIN_URL . 'assets/js/crm/recruiter-upgrade-cards.js',
                ['jquery'],
                defined('SFFC_VERSION') ? SFFC_VERSION : null,
                true
            );

            $plan_entries = $this->get_subscription_plans();
            if (empty($plan_entries)) {
                return '';
            }

            $membership_stats = $this->get_membership_social_proof_stats();
            $prepared_plans = [];
            $monthly_plans = [];
            $annual_plans = [];

            foreach ($plan_entries as $plan) {
                $prepared_plan = $this->prepare_recruiter_pricing_plan($plan, $membership_stats);
                $is_paid_plan = ((float) ($prepared_plan['price_amount'] ?? 0) > 0) || trim((string) ($prepared_plan['display_price'] ?? '')) !== '';
                if (!$is_paid_plan) {
                    continue;
                }

                $prepared_plans[] = $prepared_plan;
                if ('annual' === $prepared_plan['cycle']) {
                    $annual_plans[] = $prepared_plan;
                } else {
                    $monthly_plans[] = $prepared_plan;
                }
            }

            if (empty($prepared_plans)) {
                return '';
            }

            $default_cycle = sanitize_key($atts['default_cycle']);
            if (!in_array($default_cycle, ['monthly', 'annual'], true)) {
                $default_cycle = 'monthly';
            }
            if ('annual' === $default_cycle && empty($annual_plans)) {
                $default_cycle = 'monthly';
            }
            if ('monthly' === $default_cycle && empty($monthly_plans)) {
                $default_cycle = 'annual';
            }

            $default_plan = 'annual' === $default_cycle
                ? $this->get_primary_cycle_plan($annual_plans)
                : $this->get_primary_cycle_plan($monthly_plans);
            $default_plan = $default_plan ?: $prepared_plans[0];

            ob_start();
        ?>
            <section class="sffc-recruiter-upgrade" data-recruiter-upgrade-cards data-default-cycle="<?php echo esc_attr($default_cycle); ?>" data-selected-plan="<?php echo esc_attr($default_plan['slug']); ?>">
                <div class="sffc-recruiter-upgrade__header">
                    <p class="sffc-recruiter-upgrade__eyebrow"><?php esc_html_e('Upgrade MENA Careers', 'senna-finance'); ?></p>
                    <h2><?php echo esc_html($atts['title']); ?></h2>
                    <p><?php echo esc_html($atts['subtitle']); ?></p>
                </div>

                <?php if (!empty($monthly_plans) && !empty($annual_plans)) : ?>
                    <div class="sffc-recruiter-upgrade__toggle" role="tablist" aria-label="<?php esc_attr_e('Billing cycle', 'senna-finance'); ?>">
                        <button type="button" class="<?php echo 'monthly' === $default_cycle ? 'is-active' : ''; ?>" data-upgrade-cycle="monthly" aria-pressed="<?php echo 'monthly' === $default_cycle ? 'true' : 'false'; ?>">
                            <?php esc_html_e('Monthly', 'senna-finance'); ?>
                        </button>
                        <button type="button" class="<?php echo 'annual' === $default_cycle ? 'is-active' : ''; ?>" data-upgrade-cycle="annual" aria-pressed="<?php echo 'annual' === $default_cycle ? 'true' : 'false'; ?>">
                            <?php esc_html_e('Annual', 'senna-finance'); ?>
                        </button>
                    </div>
                <?php endif; ?>

                <div class="sffc-recruiter-upgrade__grid">
                    <?php foreach ($prepared_plans as $plan) :
                        $is_default_plan = $plan['slug'] === $default_plan['slug'];
                        $plan_features = array_values(array_filter((array) ($plan['features'] ?? [])));
                        $matches_per_week = max(0, (int) ($plan['matches_per_week'] ?? 0));
                    ?>
                        <article class="sffc-recruiter-upgrade-card<?php echo $is_default_plan ? ' is-selected' : ''; ?><?php echo !empty($plan['featured_signup']) ? ' is-featured' : ''; ?>" data-upgrade-plan-card data-plan-slug="<?php echo esc_attr($plan['slug']); ?>" data-plan-cycle="<?php echo esc_attr($plan['cycle']); ?>" <?php echo $plan['cycle'] === $default_cycle ? '' : 'hidden'; ?>>
                            <?php if (!empty($plan['featured_signup'])) : ?>
                                <span class="sffc-recruiter-upgrade-card__badge"><?php esc_html_e('Recommended', 'senna-finance'); ?></span>
                            <?php endif; ?>
                            <div class="sffc-recruiter-upgrade-card__mark" aria-hidden="true"><span></span></div>
                            <h3><?php echo esc_html($plan['name']); ?></h3>
                            <p class="sffc-recruiter-upgrade-card__tagline"><?php echo esc_html($plan['tagline'] ?: $plan['audience'] ?: __('More recruiter outreach capacity for active candidates.', 'senna-finance')); ?></p>
                            <p class="sffc-recruiter-upgrade-card__price">
                                <strong><?php echo esc_html($plan['display_price'] ?: ($plan['price'] ?? '')); ?></strong>
                                <?php if (!empty($plan['billing_cycle'])) : ?>
                                    <span><?php echo esc_html($plan['billing_cycle']); ?></span>
                                <?php endif; ?>
                            </p>
                            <ul class="sffc-recruiter-upgrade-card__features">
                                <li><?php echo esc_html($matches_per_week ? sprintf(__('%d recruiter email credits each week', 'senna-finance'), $matches_per_week) : __('More recruiter email credits', 'senna-finance')); ?></li>
                                <li><?php esc_html_e('Save recruiters and manage outreach lists', 'senna-finance'); ?></li>
                                <li><?php esc_html_e('Track roles, contacts, and follow-up in one place', 'senna-finance'); ?></li>
                                <?php foreach (array_slice($plan_features, 0, 3) as $feature) : ?>
                                    <li><?php echo esc_html($feature); ?></li>
                                <?php endforeach; ?>
                            </ul>
                            <button type="button" class="sffc-recruiter-upgrade-card__button" data-upgrade-select="<?php echo esc_attr($plan['slug']); ?>">
                                <?php printf(esc_html__('Get %s', 'senna-finance'), esc_html($plan['name'])); ?>
                            </button>
                        </article>
                    <?php endforeach; ?>
                </div>

                <div class="sffc-recruiter-upgrade__checkout" data-upgrade-checkout>
                    <div class="sffc-recruiter-upgrade__checkout-head">
                        <div>
                            <span><?php esc_html_e('Secure signup', 'senna-finance'); ?></span>
                            <h3 data-upgrade-checkout-title><?php echo esc_html($default_plan['name']); ?></h3>
                        </div>
                        <a href="mailto:support.team@joinsenna.com?subject=MENA Careers%20Membership%20Support"><?php esc_html_e('Need help?', 'senna-finance'); ?></a>
                    </div>

                    <?php foreach ($prepared_plans as $plan) :
                        $plan_has_shortcode = !empty($plan['shortcode']);
                        $plan_url = !empty($plan['mp_url']) ? $plan['mp_url'] : $this->get_canonical_membership_url();
                        $is_default_plan = $plan['slug'] === $default_plan['slug'];
                    ?>
                        <div class="sffc-recruiter-upgrade__form<?php echo $is_default_plan ? ' is-active' : ''; ?>" data-upgrade-form="<?php echo esc_attr($plan['slug']); ?>" <?php echo $is_default_plan ? '' : 'hidden'; ?>>
                            <?php if ($plan_has_shortcode) : ?>
                                <?php echo do_shortcode($plan['shortcode']); ?>
                            <?php else : ?>
                                <a href="<?php echo esc_url($plan_url); ?>" class="sffc-recruiter-upgrade__external" target="_blank" rel="noopener noreferrer">
                                    <?php esc_html_e('Open secure checkout', 'senna-finance'); ?>
                                </a>
                            <?php endif; ?>
                        </div>
                    <?php endforeach; ?>
                </div>
            </section>
        <?php
            return ob_get_clean();
        }

        public function render_recruiter_intro_onboarding_general($atts = [])
        {
            $atts = is_array($atts) ? $atts : [];
            $atts['mode'] = 'general';

            return $this->render_recruiter_intro_onboarding($atts);
        }

        public function render_recruiter_intro_onboarding($atts = [])
        {
            // CRITICAL: Prevent caching of this page to avoid exposing user data
            if (!headers_sent()) {
                header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
                header('Pragma: no-cache');
                header('Expires: 0');
            }

            $atts = shortcode_atts([
                'login_url' => wp_login_url(home_url('/onboarding/')),
                'mode' => 'role',
            ], $atts);

            $is_general_onboarding = in_array(sanitize_key((string) $atts['mode']), ['general', 'no_role', 'platform'], true);
            $post_id = (!$is_general_onboarding && isset($_GET['id'])) ? intval(wp_unslash($_GET['id'])) : 0;
            $post_context = $is_general_onboarding ? $this->get_recruiter_intro_onboarding_general_context() : $this->get_recruiter_intro_onboarding_post($post_id);

            if (empty($post_context)) {
                return '<div class="sffc-recruiter-intro-empty">' . esc_html__('We could not find that recruiter opportunity. Please return to the role and try again.', 'senna-finance') . '</div>';
            }

            wp_enqueue_style(
                'sffc-recruiter-intro-onboarding',
                SFFC_PLUGIN_URL . 'assets/css/crm/recruiter-intro-onboarding.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-recruiter-intro-onboarding',
                SFFC_PLUGIN_URL . 'assets/js/crm/recruiter-intro-onboarding.js',
                [],
                SFFC_VERSION,
                true
            );

            $this->output_timezone_cookie_script();

            $plan_entries = $this->get_subscription_plans();
            $membership_stats = $this->get_membership_social_proof_stats();
            $prepared_plans = [];
            $monthly_plans = [];
            $annual_plans = [];

            foreach ($plan_entries as $plan) {
                $prepared_plan = $this->prepare_recruiter_pricing_plan($plan, $membership_stats);
                $prepared_plans[] = $prepared_plan;

                if ('annual' === $prepared_plan['cycle']) {
                    $annual_plans[] = $prepared_plan;
                } else {
                    $monthly_plans[] = $prepared_plan;
                }
            }

            $featured_monthly_plan = $this->get_primary_cycle_plan($monthly_plans);
            $featured_annual_plan = $this->get_primary_cycle_plan($annual_plans);
            $selected_plan = $featured_monthly_plan ?: $featured_annual_plan;

            if (empty($selected_plan)) {
                return '<div class="sffc-recruiter-intro-empty">' . esc_html__('No membership plans are currently configured. Please add a featured plan first.', 'senna-finance') . '</div>';
            }

            $prefill = $this->get_recruiter_intro_onboarding_prefill();
            $display_first_name = trim((string) ($prefill['first_name'] ?? ''));
            if ($display_first_name !== '') {
                if (function_exists('mb_substr') && function_exists('mb_strtoupper')) {
                    $display_first_name = mb_strtoupper(mb_substr($display_first_name, 0, 1)) . mb_substr($display_first_name, 1);
                } else {
                    $display_first_name = strtoupper(substr($display_first_name, 0, 1)) . substr($display_first_name, 1);
                }
            } else {
                $display_first_name = __('John', 'senna-finance');
            }
            $match_data = $this->get_recruiter_intro_onboarding_matches($post_context, 6, !$is_general_onboarding);
            $matched_roles = $match_data['items'];

            // Deduplicate preview roles by recruiter name
            $preview_roles = [];
            $seen_recruiters = [];
            foreach ($matched_roles as $role) {
                $recruiter_name = $role['recruiter_name'] ?? '';
                if ($recruiter_name && !isset($seen_recruiters[$recruiter_name])) {
                    $preview_roles[] = $role;
                    $seen_recruiters[$recruiter_name] = true;
                }
                if (count($preview_roles) >= 3) break;
            }

            $best_roles = !empty($match_data['best_items']) ? $match_data['best_items'] : array_slice($matched_roles, 0, 3);
            $recent_roles = !empty($match_data['recent_items']) ? $match_data['recent_items'] : array_slice($matched_roles, 0, 3);
            $best_role_ids = array_values(array_filter(array_map(static function ($role) {
                return (int) ($role['id'] ?? 0);
            }, $best_roles)));
            $recent_roles = array_values(array_filter($recent_roles, static function ($role) use ($best_role_ids) {
                $role_id = (int) ($role['id'] ?? 0);
                return !$role_id || !in_array($role_id, $best_role_ids, true);
            }));
            if (count($recent_roles) < 3) {
                foreach ($matched_roles as $candidate_role) {
                    $candidate_id = (int) ($candidate_role['id'] ?? 0);
                    if (($candidate_id && in_array($candidate_id, $best_role_ids, true)) || ($candidate_id && in_array($candidate_id, array_map(static function ($role) {
                        return (int) ($role['id'] ?? 0);
                    }, $recent_roles), true))) {
                        continue;
                    }
                    $recent_roles[] = $candidate_role;
                    if (count($recent_roles) >= 3) {
                        break;
                    }
                }
            }
            $match_total = max((int) $match_data['total'], count($matched_roles));
            $recent_total = max((int) ($match_data['recent_total'] ?? 0), count($recent_roles));

            // Total jobs on MENA Careers for progress display
            global $wpdb;
            $total_jobs_on_senna = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sffc_crm_posts WHERE is_active = 1 AND admin_approved = 1");
            if ($total_jobs_on_senna < 100) {
                $total_jobs_on_senna = 850; // Fallback minimum for display (use realistic number)
            }
            $selected_queue_count = count($matched_roles);
            $apply_all_label = sprintf(__('Request All Intros (%s)', 'senna-finance'), number_format_i18n($match_total) . '+');
            $apply_single_label = __('Request Intro (1)', 'senna-finance');
            $best_matches_label = sprintf(__('Best Matches (%s)', 'senna-finance'), number_format_i18n($match_total) . '+');
            $recent_matches_label = sprintf(__('Recently Posted (%s)', 'senna-finance'), number_format_i18n(max(1, $recent_total)) . '+');
            $get_checkout_plan_benefit = static function (array $plan) use ($display_first_name) {
                // Show personalized plan name: {First Name}'s Plan - {Membership Type}
                $plan_name = $plan['name'] ?? __('Member', 'senna-finance');
                return sprintf(__("%s's Plan - %s", 'senna-finance'), $display_first_name, $plan_name);
            };
            $submitted_items = array_slice($best_roles, 0, 3);
            $submission_states = [
                __('submitted successfully', 'senna-finance'),
                __('submitted successfully', 'senna-finance'),
                __('moved to High Probability of Response', 'senna-finance'),
            ];
            $submission_times = [
                __('Confirmation sent 14 minutes ago', 'senna-finance'),
                __('Confirmation sent 31 minutes ago', 'senna-finance'),
                __('Confirmation sent 1 hour ago', 'senna-finance'),
            ];
            $decision_source_plans = $prepared_plans;
            usort($decision_source_plans, static function ($left, $right) {
                $left_amount = (float) ($left['price_amount'] ?? 0);
                $right_amount = (float) ($right['price_amount'] ?? 0);

                if ($left_amount > 0 && $right_amount > 0 && $left_amount !== $right_amount) {
                    return $left_amount <=> $right_amount;
                }

                return ((int) ($left['matches_per_week'] ?? 0)) <=> ((int) ($right['matches_per_week'] ?? 0));
            });
            $fallback_matches_per_week = [10, 15, 20];
            $decision_plans = [];
            $decision_plan_labels = [];
            $decision_source_plans = array_values(array_slice($decision_source_plans, 0, 3));
            $decision_plan_count = count($decision_source_plans);
            foreach ($decision_source_plans as $index => $plan) {
                $matches_per_week = max(1, (int) ($plan['matches_per_week'] ?? 0));
                if (!$matches_per_week) {
                    $matches_per_week = $fallback_matches_per_week[$index] ?? 15;
                }

                $tier_label = __('Pro', 'senna-finance');
                if (0 === $index) {
                    $tier_label = __('Starter', 'senna-finance');
                } elseif ($index === ($decision_plan_count - 1)) {
                    $tier_label = __('Max', 'senna-finance');
                }

                $features = [
                    sprintf(__('%d high-probability matches each week', 'senna-finance'), $matches_per_week),
                    __('Priority application queue for faster processing', 'senna-finance'),
                    __('Free tailored CV and cover letter for every application', 'senna-finance'),
                    __('Track every submission in one dashboard', 'senna-finance'),
                ];
                $descriptor = __('Apply faster with priority handling', 'senna-finance');
                $included_title = __('Everything in Starter, plus:', 'senna-finance');
                $billing_note = __('Cancel anytime', 'senna-finance');

                if (0 === $index) {
                    $features = [
                        sprintf(__('%d hand-picked matches sent each week', 'senna-finance'), $matches_per_week),
                        __('Free tailored CV and cover letter for every application', 'senna-finance'),
                        __('MENA Careers handles the application work for you', 'senna-finance'),
                        __('Track every submission in one dashboard', 'senna-finance'),
                    ];
                    $descriptor = __('Start applying smarter', 'senna-finance');
                    $included_title = __('Included:', 'senna-finance');
                    $billing_note = __('Low-commitment entry point', 'senna-finance');
                } elseif ($index === ($decision_plan_count - 1)) {
                    $features = [
                        sprintf(__('%d+ targeted matches handled each week', 'senna-finance'), $matches_per_week),
                        __('Priority queue across your application pipeline', 'senna-finance'),
                        __('Free tailored CV and cover letter for every application', 'senna-finance'),
                        __('Maximum exposure across relevant private equity roles', 'senna-finance'),
                    ];
                    $descriptor = __('Higher limits, priority access', 'senna-finance');
                    $included_title = __('Everything in Pro, plus:', 'senna-finance');
                    $billing_note = __('Highest weekly reach', 'senna-finance');
                }

                $decision_plans[] = [
                    'title' => sprintf(__('%d matches / week', 'senna-finance'), $matches_per_week),
                    'copy' => !empty($plan['tagline']) ? $plan['tagline'] : __('One setup, tracked applications, and application materials handled for you.', 'senna-finance'),
                    'meta' => [
                        sprintf(__('%d handled each week', 'senna-finance'), $matches_per_week),
                        __('CV + cover letter included', 'senna-finance'),
                    ],
                    'features' => $features,
                    'button' => sprintf(__('Choose %d / week', 'senna-finance'), $matches_per_week),
                    'featured' => $decision_plan_count > 1 ? ($index > 0 && $index < ($decision_plan_count - 1)) : true,
                    'price' => $plan['display_price'],
                    'price_meta' => $decision_plan_count > 1 && $index > 0 && $index < ($decision_plan_count - 1) ? __('most chosen plan', 'senna-finance') : __('membership plan', 'senna-finance'),
                    'tier_label' => $tier_label,
                    'descriptor' => $descriptor,
                    'included_title' => $included_title,
                    'billing_note' => $billing_note,
                    'slug' => $plan['slug'],
                    'cycle' => $plan['cycle'],
                ];
                $decision_plan_labels[$plan['slug']] = $tier_label;
            }
            $primary_manual_role = !empty($matched_roles[0]) ? $matched_roles[0] : [];
            $primary_manual_link = $primary_manual_role['apply_link'] ?? ($primary_manual_role['email_link'] ?? '');
            $email_mode = get_option('sffc_crm_email_mode', 'oauth');
            if (!in_array($email_mode, ['oauth', 'mailto'], true)) {
                $email_mode = 'oauth';
            }
            $support_mailto = 'mailto:support.team@joinsenna.com';

            wp_localize_script('sffc-recruiter-intro-onboarding', 'sffcRecruiterIntroOnboarding', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_recruiter_intro_onboarding'),
                'postId' => $is_general_onboarding ? '' : $post_context['id'],
                'isGeneral' => $is_general_onboarding,
                'defaultCycle' => $selected_plan['cycle'],
                'defaultPlanSlug' => $selected_plan['slug'],
                'monthlySlug' => $featured_monthly_plan['slug'] ?? '',
                'annualSlug' => $featured_annual_plan['slug'] ?? '',
                'emailMode' => $email_mode,
                'loginUrl' => esc_url_raw($atts['login_url']),
                'applyAllLabel' => $apply_all_label,
                'primaryManualLink' => $primary_manual_link,
                'supportEmail' => $support_mailto,
                'strings' => [
                    'nameRequired' => __('Please enter your full name.', 'senna-finance'),
                    'emailRequired' => __('Please enter a valid email address.', 'senna-finance'),
                    'saveError' => __('We could not save your details right now. Please try again.', 'senna-finance'),
                    'missingRecruiterEmail' => __('Recruiter email not available for this opportunity.', 'senna-finance'),
                ],
            ]);

            $recruiter_onboarding_locale = $this->get_member_pricing_signup_locale();
            $recruiter_onboarding_dir = $this->is_arabic_locale($recruiter_onboarding_locale) ? 'rtl' : 'ltr';

            ob_start();
        ?>
            <div class="sffc-recruiter-intro-onboarding<?php echo $is_general_onboarding ? ' sffc-recruiter-intro-onboarding--general' : ''; ?>" dir="<?php echo esc_attr($recruiter_onboarding_dir); ?>" data-locale="<?php echo esc_attr($this->is_arabic_locale($recruiter_onboarding_locale) ? 'ar' : 'en'); ?>" data-post-id="<?php echo esc_attr($is_general_onboarding ? '' : $post_context['id']); ?>" data-default-cycle="<?php echo esc_attr($selected_plan['cycle']); ?>" data-general-onboarding="<?php echo $is_general_onboarding ? '1' : '0'; ?>">
                <header class="topbar">
                    <button type="button" class="back" data-onboarding-back>← <?php esc_html_e('Back', 'senna-finance'); ?></button>
                    <div class="brand">
                        <img src="https://media.joinsenna.com/2026/02/senna111-scaled.png?1771880330" alt="<?php esc_attr_e('MENA Careers', 'senna-finance'); ?>">
                    </div>
                    <div class="topbar-spacer" aria-hidden="true"></div>
                </header>

                <main class="page">
                    <section class="page-head">
                        <div class="hero-role-badge"><?php echo esc_html($is_general_onboarding ? __('Finance matching', 'senna-finance') : $post_context['job_title']); ?></div>
                    </section>

                    <div class="sffc-onboarding-step is-active" data-step="1">
                        <div class="canvas canvas--wide">
                            <section class="hero hero--step">
                                <h1><?php echo esc_html($is_general_onboarding ? __('Get Recruiter Intros and Land the Role', 'senna-finance') : __('How would you like to apply?', 'senna-finance')); ?></h1>
                                <p><?php esc_html_e('Choose your preferred path to connect with recruiters. You can always switch later.', 'senna-finance'); ?></p>
                            </section>
                            <div class="card-grid">
                                <button type="button" class="option-card selected" data-choice-card="intro">
                                    <div class="popular-badge"><?php esc_html_e('Most popular', 'senna-finance'); ?></div>

                                    <!-- Visual Area -->
                                    <div class="card-visual">
                                        <div class="card-visual-bg"></div>

                                        <div class="card-visual-content">
                                            <!-- Recruiter Profile -->
                                            <div class="card-visual-profile">
                                                <div class="card-visual-avatar">
                                                    <?php if (!empty($post_context['avatar_url'])) : ?>
                                                        <img src="<?php echo esc_url($post_context['avatar_url']); ?>" alt="<?php echo esc_attr($post_context['recruiter_name']); ?>">
                                                    <?php else : ?>
                                                        <span class="card-visual-avatar-initial"><?php echo esc_html($post_context['avatar_initial']); ?></span>
                                                    <?php endif; ?>
                                                    <div class="card-visual-verified">
                                                        <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
                                                            <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                                        </svg>
                                                    </div>
                                                </div>
                                                <div class="card-visual-info">
