        public function ajax_save_recruiter_intro_onboarding()
        {
            check_ajax_referer('sffc_recruiter_intro_onboarding', 'nonce');

            $full_name = sanitize_text_field($_POST['full_name'] ?? '');
            $email = sanitize_email($_POST['email'] ?? '');
            $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
            $selected_path = sanitize_key($_POST['selected_path'] ?? 'intro');

            if ($full_name === '' || !is_email($email)) {
                wp_send_json_error(['message' => __('Please provide a valid name and email address.', 'senna-finance')]);
            }

            $name_parts = $this->parse_full_name($full_name);
            $cookie_data = [
                'full_name' => $full_name,
                'email' => $email,
                'first_name' => $name_parts['first_name'],
                'last_name' => $name_parts['last_name'],
                'post_id' => $post_id,
                'selected_path' => in_array($selected_path, ['intro', 'email'], true) ? $selected_path : 'intro',
            ];

            $expires = time() + (30 * DAY_IN_SECONDS);
            $this->set_signup_scoped_cookie('sffc_signup_email', $cookie_data['email'], $expires);
            $this->set_signup_scoped_cookie('sffc_signup_first_name', $cookie_data['first_name'], $expires);
            $this->set_signup_scoped_cookie('sffc_signup_last_name', $cookie_data['last_name'], $expires);
            $this->set_signup_scoped_cookie('sffc_contact_data', wp_json_encode($cookie_data), $expires);
            $this->set_signup_scoped_cookie('sffc_recruiter_intro_onboarding', wp_json_encode($cookie_data), $expires);

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name) {
                $wpdb->insert(
                    $table_name,
                    [
                        'full_name' => $full_name,
                        'email' => $email,
                        'created_at' => current_time('mysql'),
                    ],
                    ['%s', '%s', '%s']
                );
            }

            wp_send_json_success([
                'first_name' => $cookie_data['first_name'],
                'last_name' => $cookie_data['last_name'],
                'email' => $cookie_data['email'],
            ]);
        }

        public function ajax_schedule_recruiter_intro_top_match_email()
        {
            check_ajax_referer('sffc_recruiter_intro_onboarding', 'nonce');

            $email = sanitize_email($_POST['email'] ?? '');
            $first_name = sanitize_text_field($_POST['first_name'] ?? '');
            $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;

            if (!is_email($email) || !$post_id) {
                wp_send_json_error(['message' => __('Missing email or role context.', 'senna-finance')], 400);
            }

            if ((bool) get_option('sffc_crm_top_match_email_disabled', false)) {
                wp_send_json_success(['scheduled' => false, 'disabled' => true]);
            }

            $schedule_key = $this->get_recruiter_intro_top_match_schedule_key($email, $post_id);
            if (get_transient($schedule_key)) {
                wp_send_json_success(['scheduled' => true, 'duplicate' => true]);
            }

            set_transient($schedule_key, 1, 5 * MINUTE_IN_SECONDS);
            $post_context = $this->get_recruiter_intro_onboarding_post($post_id);
            if (empty($post_context)) {
                delete_transient($schedule_key);
                wp_send_json_error(['message' => __('Missing role context.', 'senna-finance')], 400);
            }

            $match_data = $this->get_recruiter_intro_onboarding_matches($post_context, 6);

            // For the email subject, use the ROLE THEY CLICKED ON (from post_context)
            // Use post_context recruiter and role for the subject line
            $subject_recruiter_name = $post_context['recruiter_name'] ?? 'Recruiter';
            $subject_role_title = $post_context['job_title'] ?? 'a role';

            // Format recruiter name for subject
            $name_parts = preg_split('/\s+/', trim($subject_recruiter_name));
            $recruiter_first = $name_parts[0] ?? 'Recruiter';
            $recruiter_last_initial = '';
            if (isset($name_parts[1])) {
                $recruiter_last_initial = function_exists('mb_substr') ? mb_strtoupper(mb_substr($name_parts[1], 0, 1)) : strtoupper(substr($name_parts[1], 0, 1));
            }
            $formatted_recruiter = $recruiter_first . ($recruiter_last_initial ? ' ' . $recruiter_last_initial . '.' : '');

            $locale = $this->get_email_recipient_locale($email);
            $recipient_name = trim($first_name) !== '' ? $first_name : $this->localize_interface_copy('there', 'هناك', $locale);
            $subject = $this->is_arabic_locale($locale)
                ? sprintf('%s، تواصلك مع %s بشأن %s جاهز', $recipient_name, $formatted_recruiter, $subject_role_title)
                : sprintf(__('%s, your intro to %s hiring for %s is waiting', 'senna-finance'), $recipient_name, $formatted_recruiter, $subject_role_title);

            // Find top match for email body content
            $top_match = [];
            foreach ((array) ($match_data['items'] ?? []) as $candidate) {
                if (empty($candidate['is_selected_role'])) {
                    $top_match = $candidate;
                    break;
                }
            }
            if (empty($top_match) && !empty($match_data['items'][0])) {
                $top_match = $match_data['items'][0];
            }
            if (empty($top_match)) {
                delete_transient($schedule_key);
                wp_send_json_error(['message' => __('No top match available.', 'senna-finance')], 400);
            }

            $match_total = max((int) ($match_data['total'] ?? 0), count($match_data['items'] ?? []));
            $html = $this->build_recruiter_intro_top_match_email_html($recipient_name, $post_context, $match_total, $locale);
            $send_at = time() + MINUTE_IN_SECONDS;

            $result = null;
            if (class_exists('SFFC_CRM_SendGrid_Service')) {
                $sendgrid = SFFC_CRM_SendGrid_Service::get_instance();
                if ($sendgrid && $sendgrid->is_configured()) {
                    $result = $sendgrid->send_email(
                        $subject,
                        $html,
                        $email,
                        $send_at,
                        [
                            'post_id' => $post_id,
                            'email_type' => 'top_match_exit',
                        ],
                        ['top_match_exit'],
                        'top_match_exit'
                    );
                }
            }

            if (is_wp_error($result)) {
                delete_transient($schedule_key);
                wp_send_json_error(['message' => $result->get_error_message()], 500);
            }

            if (!$result) {
                delete_transient($schedule_key);
                wp_send_json_success(['scheduled' => false, 'missing_sendgrid' => true]);
            }

            wp_send_json_success(['scheduled' => true, 'provider' => 'sendgrid']);
        }

        public function send_scheduled_recruiter_intro_top_match_email($email, $first_name, $post_id)
        {
            $email = sanitize_email((string) $email);
            $first_name = sanitize_text_field((string) $first_name);
            $post_id = (int) $post_id;

            if (!is_email($email) || !$post_id) {
                return;
            }

            delete_transient($this->get_recruiter_intro_top_match_schedule_key($email, $post_id));

            $post_context = $this->get_recruiter_intro_onboarding_post($post_id);
            if (empty($post_context)) {
                return;
            }

            $match_data = $this->get_recruiter_intro_onboarding_matches($post_context, 6);

            // For the email subject, use the ROLE THEY CLICKED ON (from post_context)
            // Use post_context recruiter and role for the subject line
            $subject_recruiter_name = $post_context['recruiter_name'] ?? 'Recruiter';
            $subject_role_title = $post_context['job_title'] ?? 'a role';

            // Format recruiter name for subject
            $name_parts = preg_split('/\s+/', trim($subject_recruiter_name));
            $recruiter_first = $name_parts[0] ?? 'Recruiter';
            $recruiter_last_initial = '';
            if (isset($name_parts[1])) {
                $recruiter_last_initial = function_exists('mb_substr') ? mb_strtoupper(mb_substr($name_parts[1], 0, 1)) : strtoupper(substr($name_parts[1], 0, 1));
            }
            $formatted_recruiter = $recruiter_first . ($recruiter_last_initial ? ' ' . $recruiter_last_initial . '.' : '');

            $locale = $this->get_email_recipient_locale($email);
            $recipient_name = trim($first_name) !== '' ? $first_name : $this->localize_interface_copy('there', 'هناك', $locale);
            $subject = $this->is_arabic_locale($locale)
                ? sprintf('%s، تواصلك مع %s بشأن %s جاهز', $recipient_name, $formatted_recruiter, $subject_role_title)
                : sprintf(__('%s, your intro to %s hiring for %s is waiting', 'senna-finance'), $recipient_name, $formatted_recruiter, $subject_role_title);

            // Find top match for email body content
            $top_match = [];
            foreach ((array) ($match_data['items'] ?? []) as $candidate) {
                if (empty($candidate['is_selected_role'])) {
                    $top_match = $candidate;
                    break;
                }
            }
            if (empty($top_match) && !empty($match_data['items'][0])) {
                $top_match = $match_data['items'][0];
            }

            if (empty($top_match)) {
                return;
            }

            $match_total = max((int) ($match_data['total'] ?? 0), count($match_data['items'] ?? []));
            $headers = function_exists('sffc_crm_build_email_headers')
                ? sffc_crm_build_email_headers('top_match_exit')
                : ['Content-Type: text/html; charset=UTF-8'];

            wp_mail(
                $email,
                $subject,
                $this->build_recruiter_intro_top_match_email_html($recipient_name, $post_context, $match_total, $locale),
                $headers
            );
        }

        private function get_recruiter_intro_onboarding_post($post_id)
        {
            if (!$post_id) {
                return [];
            }

            $post = get_post($post_id);
            if ($post && $post->post_type === 'sffc_recruiter_post') {
                $job_title = get_post_meta($post_id, '_job_title', true) ?: get_the_title($post_id);
                $company_name = get_post_meta($post_id, '_company_name', true) ?: get_post_meta($post_id, '_recruiter_company', true);
                $location = get_post_meta($post_id, '_job_location', true) ?: __('Global', 'senna-finance');
                $salary_min = get_post_meta($post_id, '_salary_min', true);
                $salary_max = get_post_meta($post_id, '_salary_max', true);
                $salary_currency = get_post_meta($post_id, '_salary_currency', true) ?: 'AED';
                $recruiter_name = __('Hiring Team', 'senna-finance');
                $recruiter_id_meta = get_post_meta($post_id, '_recruiter_id', true);

                // Get recruiter data from sffc_crm_recruiters table
                if (!empty($recruiter_id_meta)) {
                    global $wpdb;
                    $recruiter_data = $wpdb->get_row($wpdb->prepare(
                        "SELECT first_name, last_name FROM {$wpdb->prefix}sffc_crm_recruiters WHERE id = %d",
                        (int) $recruiter_id_meta
                    ), ARRAY_A);

                    if (!empty($recruiter_data['first_name'])) {
                        $first_name = trim($recruiter_data['first_name']);
                        $last_name = trim($recruiter_data['last_name'] ?? '');

                        if ($last_name) {
                            $last_initial = function_exists('mb_substr') ? mb_strtoupper(mb_substr($last_name, 0, 1)) : strtoupper(substr($last_name, 0, 1));
                            $recruiter_name = $first_name . ' ' . $last_initial . '.';
                        } else {
                            $recruiter_name = $first_name;
                        }
                    }
                } else {
                    // Fallback to old meta if no recruiter_id
                    $recruiter_name = get_post_meta($post_id, '_recruiter_name', true) ?: __('Hiring Team', 'senna-finance');
                }

                $recruiter_title = get_post_meta($post_id, '_recruiter_title', true) ?: __('Finance recruiter', 'senna-finance');
                $recruiter_company = get_post_meta($post_id, '_recruiter_company', true) ?: $company_name;
                $recruiter_email = get_post_meta($post_id, '_recruiter_email', true);
                $recruiter_image_id = get_post_meta($post_id, '_recruiter_image_id', true);
                $avatar_url = $recruiter_image_id ? wp_get_attachment_image_url($recruiter_image_id, 'thumbnail') : '';
                if (!$avatar_url) {
                    $avatar_url = get_post_meta($post_id, '_recruiter_image_url', true);
                }

                $salary_display = '';
                if ($salary_min && $salary_max) {
                    $salary_display = sprintf('%s %s - %s', $salary_currency, number_format_i18n((int) $salary_min), number_format_i18n((int) $salary_max));
                } elseif ($salary_min) {
                    $salary_display = sprintf('%s %s+', $salary_currency, number_format_i18n((int) $salary_min));
                }

                $requirements = get_post_meta($post_id, '_key_requirements', true);
                if (is_string($requirements)) {
                    $requirements = preg_split("/\r?\n|•/", $requirements);
                }
                $requirements = is_array($requirements) ? array_values(array_filter(array_map('trim', $requirements))) : [];
                $description = wp_trim_words(wp_strip_all_tags($post->post_content), 110, '...');

                return [
                    'id' => $post_id,
                    'job_title' => $job_title,
                    'company_name' => $company_name ?: __('Confidential company', 'senna-finance'),
                    'company_logo' => get_post_meta($post_id, '_company_logo', true) ?: '',
                    'location' => $location,
                    'location_short' => str_replace(', UAE', '', $location),
                    'location_city' => $location,
                    'location_country' => 'United Arab Emirates',
                    'salary_display' => $salary_display,
                    'sector' => get_post_meta($post_id, '_sector', true) ?: '',
                    'seniority' => get_post_meta($post_id, '_seniority', true) ?: '',
                    'recruiter_name' => $recruiter_name,
                    'recruiter_title' => $recruiter_title,
                    'recruiter_company' => $recruiter_company,
                    'recruiter_title_company' => trim($recruiter_title . ' at ' . $recruiter_company),
                    'recruiter_email' => $recruiter_email,
                    'avatar_url' => $avatar_url,
                    'avatar_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1)),
                    'description' => $description,
                    'requirements' => array_slice($requirements, 0, 6),
                    'posted_at' => get_post_time('mysql', true, $post_id),
                    'source_url' => get_permalink($post_id),
                    'application_url' => $application_url ?: get_permalink($post_id),
                    'keywords' => [],
                ];
            }

            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return [];
            }

            $crm_post_model = new SFFC_CRM_Post();
            $crm_post = $crm_post_model->get($post_id);
            if (empty($crm_post)) {
                return [];
            }

            $salary_display = '';
            if (!empty($crm_post['salary_text'])) {
                $salary_display = sanitize_text_field($crm_post['salary_text']);
            } elseif (!empty($crm_post['salary_min']) && !empty($crm_post['salary_max'])) {
                $salary_display = sprintf(
                    '%s %s - %s',
                    $crm_post['salary_currency'] ?: 'AED',
                    number_format_i18n((int) $crm_post['salary_min']),
                    number_format_i18n((int) $crm_post['salary_max'])
                );
            } elseif (!empty($crm_post['salary_min'])) {
                $salary_display = sprintf(
                    '%s %s+',
                    $crm_post['salary_currency'] ?: 'AED',
                    number_format_i18n((int) $crm_post['salary_min'])
                );
            }

            $requirements = [];
            if (!empty($crm_post['requirements']) && is_array($crm_post['requirements'])) {
                $requirements = $crm_post['requirements'];
            } elseif (!empty($crm_post['skills_mentioned']) && is_array($crm_post['skills_mentioned'])) {
                $requirements = $crm_post['skills_mentioned'];
            } elseif (!empty($crm_post['keywords'])) {
                $requirements = preg_split('/[\r\n,|]+/', (string) $crm_post['keywords']);
            }
            $requirements = array_values(array_filter(array_map(function ($item) {
                return is_scalar($item) ? trim(sanitize_text_field((string) $item)) : '';
            }, (array) $requirements)));

            $description_source = $crm_post['content_snippet'] ?? '';
            if ($description_source === '' && !empty($crm_post['content'])) {
                $description_source = wp_trim_words(wp_strip_all_tags((string) $crm_post['content']), 110, '...');
            }

            // Get recruiter data from sffc_crm_recruiters table
            $recruiter_name = __('Hiring Team', 'senna-finance');
            $recruiter_company = $crm_post['recruiter_display_company'] ?: ($crm_post['recruiter_firm'] ?: ($crm_post['company'] ?: __('Global Search Firm', 'senna-finance')));
            $recruiter_title = $crm_post['recruiter_title'] ?: __('Finance recruiter', 'senna-finance');

            if (!empty($crm_post['recruiter_id'])) {
                global $wpdb;
                $recruiter_data = $wpdb->get_row($wpdb->prepare(
                    "SELECT first_name, last_name FROM {$wpdb->prefix}sffc_crm_recruiters WHERE id = %d",
                    (int) $crm_post['recruiter_id']
                ), ARRAY_A);

                if (!empty($recruiter_data['first_name'])) {
                    $first_name = trim($recruiter_data['first_name']);
                    $last_name = trim($recruiter_data['last_name'] ?? '');

                    if ($last_name) {
                        $last_initial = function_exists('mb_substr') ? mb_strtoupper(mb_substr($last_name, 0, 1)) : strtoupper(substr($last_name, 0, 1));
                        $recruiter_name = $first_name . ' ' . $last_initial . '.';
                    } else {
                        $recruiter_name = $first_name;
                    }
                }
            }

            $location = $crm_post['location'] ?: ($crm_post['location_city'] ?? __('Global', 'senna-finance'));

            return [
                'id' => $post_id,
                'job_title' => $crm_post['role_title'] ?: __('Confidential Role', 'senna-finance'),
                'company_name' => $crm_post['company'] ?: __('Confidential company', 'senna-finance'),
                'company_logo' => $crm_post['company_logo'] ?? '',
                'location' => $location,
                'location_short' => str_replace(', UAE', '', $location),
                'location_city' => $crm_post['location_city'] ?? '',
                'location_country' => $crm_post['location_country'] ?? '',
                'salary_display' => $salary_display,
                'sector' => $crm_post['sector'] ?? '',
                'seniority' => $crm_post['seniority'] ?? '',
                'recruiter_name' => $recruiter_name,
                'recruiter_title' => $recruiter_title,
                'recruiter_company' => $recruiter_company,
                'recruiter_firm' => $recruiter_company,
                'recruiter_title_company' => trim($recruiter_title . ' at ' . $recruiter_company),
                'recruiter_email' => $crm_post['recruiter_email'] ?? '',
                'recruiter_photo' => $crm_post['recruiter_photo'] ?? '',
                'avatar_url' => $crm_post['recruiter_photo'] ?? '',
                'avatar_initial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1)),
                'description' => $description_source ?: __('Role details coming soon.', 'senna-finance'),
                'requirements' => array_slice($requirements, 0, 6),
                'posted_at' => $crm_post['posted_at'] ?? '',
                'source_url' => $crm_post['source_url'] ?? '',
                'application_url' => $crm_post['application_url'] ?? '',
                'keywords' => !empty($crm_post['keywords']) ? $this->normalize_recruiter_intro_keywords($crm_post['keywords']) : [],
            ];
        }

