        private function normalize_recruiter_intro_keywords($keywords)
        {
            if (is_string($keywords)) {
                $decoded = json_decode($keywords, true);
                if (is_array($decoded)) {
                    $keywords = $decoded;
                } else {
                    $keywords = preg_split('/[\r\n,|]+/', $keywords);
                }
            }

            $normalized = [];
            foreach ((array) $keywords as $keyword) {
                if (is_array($keyword)) {
                    $keyword = $keyword['keyword'] ?? $keyword['name'] ?? '';
                }
                $keyword = trim(sanitize_text_field((string) $keyword));
                if ($keyword !== '') {
                    $normalized[] = $keyword;
                }
            }

            return array_values(array_unique($normalized));
        }

        private function build_apply_chat_matching_role_seed_item(array $matching_role)
        {
            $matching_role_title = sanitize_text_field((string) ($matching_role['role_title'] ?? $matching_role['job_title'] ?? $matching_role['title'] ?? ''));
            if ($matching_role_title === '') {
                return null;
            }

            $matching_role_company = sanitize_text_field((string) ($matching_role['company'] ?? ''));
            $matching_role_location = sanitize_text_field((string) ($matching_role['location'] ?? ''));
            $matching_role_seniority = sanitize_text_field((string) ($matching_role['seniority'] ?? ''));
            $matching_role_sector = sanitize_text_field((string) ($matching_role['sector'] ?? ''));
            $matching_role_salary = sanitize_text_field((string) ($matching_role['salary_text'] ?? ''));
            $matching_role_recruiter_photo = esc_url_raw((string) (
                $matching_role['recruiter_photo']
                ?? $matching_role['recruiter_avatar']
                ?? $matching_role['avatar']
                ?? $matching_role['avatar_url']
                ?? $matching_role['recruiter_image_url']
                ?? $matching_role['_recruiter_image_url']
                ?? $matching_role['image.url']
                ?? ''
            ));
            $matching_role_recruiter_email = sanitize_email((string) (
                $matching_role['recruiter_email']
                ?? $matching_role['_recruiter_email']
                ?? ''
            ));
            $matching_role_recruiter_linkedin = esc_url_raw((string) (
                $matching_role['recruiter_linkedin']
                ?? $matching_role['_recruiter_linkedin']
                ?? ''
            ));
            $matching_role_url = $this->get_crm_editorial_community_public_opportunity_url(
                (array) $matching_role,
                $matching_role_title,
                $matching_role_company
            );

            $matching_role_keywords = $matching_role['keywords'] ?? '';
            if (is_array($matching_role_keywords)) {
                $matching_role_keywords = implode(', ', array_filter(array_map('sanitize_text_field', $matching_role_keywords)));
            }

            return [
                'id' => (int) ($matching_role['id'] ?? $matching_role['post_id'] ?? $matching_role['wp_post_id'] ?? 0),
                'source' => sanitize_key((string) ($matching_role['source'] ?? 'crm')),
                'wp_post_id' => (int) ($matching_role['wp_post_id'] ?? 0),
                'crm_post_id' => (int) ($matching_role['crm_post_id'] ?? 0),
                'title' => $matching_role_title,
                'company' => $matching_role_company,
                'location' => $matching_role_location,
                'seniority' => $matching_role_seniority,
                'sector' => $matching_role_sector,
                'salary' => $matching_role_salary,
                'salary_min' => isset($matching_role['salary_min']) ? (int) $matching_role['salary_min'] : 0,
                'salary_max' => isset($matching_role['salary_max']) ? (int) $matching_role['salary_max'] : 0,
                'salary_currency' => sanitize_text_field((string) ($matching_role['salary_currency'] ?? '')),
                'snippet' => sanitize_text_field((string) ($matching_role['content_snippet'] ?? $matching_role['excerpt'] ?? $matching_role['description_preview'] ?? '')),
                'keywords' => sanitize_text_field((string) $matching_role_keywords),
                'logo' => esc_url_raw((string) ($matching_role['company_logo'] ?? '')),
                'recruiter' => sanitize_text_field((string) ($matching_role['recruiter_name'] ?? '')),
                'recruiter_title' => sanitize_text_field((string) ($matching_role['recruiter_title'] ?? '')),
                'recruiter_photo' => $matching_role_recruiter_photo,
                'recruiter_avatar' => $matching_role_recruiter_photo,
                'avatar' => $matching_role_recruiter_photo,
                'avatar_url' => $matching_role_recruiter_photo,
                'recruiter_email' => $matching_role_recruiter_email,
                'recruiter_linkedin' => $matching_role_recruiter_linkedin,
                'url' => esc_url_raw($matching_role_url),
            ];
        }

        private function get_apply_chat_jobs_post_seed_candidates(array $context = [], $limit = 80)
        {
            $limit = max(12, min(120, absint($limit)));
            $query = new WP_Query([
                'post_type' => 'jobs',
                'post_status' => 'publish',
                'posts_per_page' => $limit,
                'orderby' => 'date',
                'order' => 'DESC',
                'no_found_rows' => true,
                'ignore_sticky_posts' => true,
                'update_post_meta_cache' => true,
                'update_post_term_cache' => false,
            ]);

            if (!$query->have_posts()) {
                return [];
            }

            $items = [];
            foreach ($query->posts as $jobs_post) {
                if (!$jobs_post instanceof WP_Post) {
                    continue;
                }

                $item = $this->get_crm_reddit_jobs_item((int) $jobs_post->ID);
                if (empty($item) || !is_array($item)) {
                    continue;
                }

                if (!$this->apply_chat_seed_candidate_matches_context($item, $context)) {
                    continue;
                }

                $items[] = $item;
            }

            wp_reset_postdata();

            return $items;
        }

        private function apply_chat_seed_candidate_matches_context(array $item, array $context)
        {
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($item['role_title'] ?? $item['job_title'] ?? $item['title'] ?? ''),
                (string) ($item['company'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                (string) ($item['excerpt'] ?? $item['content_snippet'] ?? $item['description_preview'] ?? ''),
                is_array($item['keywords'] ?? null) ? implode(' ', $item['keywords']) : (string) ($item['keywords'] ?? ''),
            ]))));

            foreach (['location', 'sector', 'keywords'] as $context_key) {
                $needle = strtolower(trim((string) ($context[$context_key] ?? '')));
                if ($needle !== '' && false === strpos($haystack, $needle)) {
                    return false;
                }
            }

            return true;
        }

        private function get_apply_chat_seed_key(array $seed_item)
        {
            $source = sanitize_key((string) ($seed_item['source'] ?? 'crm'));
            $id = (int) ($seed_item['id'] ?? 0);
            $wp_post_id = (int) ($seed_item['wp_post_id'] ?? 0);
            $crm_post_id = (int) ($seed_item['crm_post_id'] ?? 0);

            if ($source !== '' && ($id > 0 || $wp_post_id > 0 || $crm_post_id > 0)) {
                return $source . ':' . $id . ':' . $wp_post_id . ':' . $crm_post_id;
            }

            return md5(
                strtolower(trim((string) ($seed_item['title'] ?? ''))) . '|' .
                strtolower(trim((string) ($seed_item['company'] ?? ''))) . '|' .
                strtolower(trim((string) ($seed_item['location'] ?? '')))
            );
        }

        private function find_crm_apply_chat_standalone_context_role($cv_text, $target_role = '')
        {
            $normalized_cv = $this->normalize_crm_reddit_dashboard_cv_text((string) $cv_text);
            $target_role = sanitize_text_field((string) $target_role);
            if ($normalized_cv === '' && $target_role === '') {
                return [];
            }

            $seed_context = [];
            if ($target_role !== '') {
                $seed_context['keywords'] = $target_role;
            }
            $seed = $this->get_apply_chat_matching_roles_seed($seed_context, 120);
            if (empty($seed) && $target_role !== '') {
                $seed = $this->get_apply_chat_matching_roles_seed([], 120);
            }
            if (empty($seed)) {
                return [];
            }

            $best = null;
            $best_score = -1;
            foreach ($seed as $seed_item) {
                if (!is_array($seed_item)) {
                    continue;
                }

                $score = $this->score_apply_chat_standalone_seed_for_cv($seed_item, $normalized_cv, $target_role);
                if ($score > $best_score) {
                    $best = $seed_item;
                    $best_score = $score;
                }
            }

            if (empty($best) || $best_score < 2) {
                $best = $seed[0] ?? [];
            }

            if (empty($best) || !is_array($best)) {
                return [];
            }

            $content = trim(implode("\n", array_filter([
                (string) ($best['snippet'] ?? ''),
                (string) ($best['keywords'] ?? '') !== '' ? 'Role keywords: ' . (string) $best['keywords'] : '',
                (string) ($best['sector'] ?? '') !== '' ? 'Sector: ' . (string) $best['sector'] : '',
                (string) ($best['seniority'] ?? '') !== '' ? 'Seniority: ' . (string) $best['seniority'] : '',
            ])));

            return [
                'id' => (int) ($best['crm_post_id'] ?: ($best['id'] ?? 0)),
                'source' => sanitize_key((string) ($best['source'] ?? 'crm')),
                'wp_post_id' => (int) ($best['wp_post_id'] ?? 0),
                'crm_post_id' => (int) ($best['crm_post_id'] ?? 0),
                'role_title' => sanitize_text_field((string) ($best['title'] ?? $target_role)),
                'company' => sanitize_text_field((string) ($best['company'] ?? '')),
                'location' => sanitize_text_field((string) ($best['location'] ?? '')),
                'sector' => sanitize_text_field((string) ($best['sector'] ?? '')),
                'seniority' => sanitize_text_field((string) ($best['seniority'] ?? '')),
                'salary_text' => sanitize_text_field((string) ($best['salary'] ?? '')),
                'keywords' => sanitize_text_field((string) ($best['keywords'] ?? '')),
                'content' => $content,
                'content_snippet' => sanitize_text_field((string) ($best['snippet'] ?? '')),
            ];
        }

        private function score_apply_chat_standalone_seed_for_cv(array $seed_item, $normalized_cv, $target_role = '')
        {
            $score = 0;
            $normalized_cv = strtolower((string) $normalized_cv);
            $target_role = strtolower(trim(sanitize_text_field((string) $target_role)));
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($seed_item['title'] ?? ''),
                (string) ($seed_item['sector'] ?? ''),
                (string) ($seed_item['seniority'] ?? ''),
                (string) ($seed_item['keywords'] ?? ''),
                (string) ($seed_item['snippet'] ?? ''),
            ]))));

            if ($target_role !== '') {
                $target_terms = preg_split('/[\s,\/\-\|]+/', $target_role);
                $target_terms = array_slice(array_unique(array_filter(array_map(static function ($term) {
                    $term = trim((string) $term);
                    return strlen($term) >= 3 ? $term : '';
                }, (array) $target_terms))), 0, 8);
                foreach ($target_terms as $term) {
                    if (false !== strpos($haystack, $term)) {
                        $score += 8;
                    }
                }
                if (false !== strpos($haystack, $target_role)) {
                    $score += 18;
                }
            }

            $terms = preg_split('/[\s,\/\-\|]+/', $haystack);
            $terms = array_slice(array_unique(array_filter(array_map(static function ($term) {
                $term = trim((string) $term);
                return strlen($term) >= 4 ? $term : '';
            }, (array) $terms))), 0, 28);

            foreach ($terms as $term) {
                if (false !== strpos($normalized_cv, $term)) {
                    $score++;
                }
            }

            if (preg_match('/\b(?:private equity|investment|asset management|portfolio|fund|deal|transaction|valuation|m&a|credit|real estate)\b/i', $haystack)) {
                $score += 2;
            }

            return $score;
        }

        private function infer_apply_chat_matching_role_seed_family(array $seed_item)
        {
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($seed_item['title'] ?? ''),
                (string) ($seed_item['sector'] ?? ''),
                (string) ($seed_item['company'] ?? ''),
                (string) ($seed_item['keywords'] ?? ''),
                (string) ($seed_item['snippet'] ?? ''),
            ]))));

            if ($haystack === '') {
                return 'general';
            }

            $family_patterns = [
                'investment' => '/\b(?:investment banking|m&a|private equity|venture capital|valuation|equity research|asset management|portfolio management|due diligence|transaction|deal(?:s)?|fundraising|investor relations|fund|funds)\b/i',
                'credit' => '/\b(?:credit|lending|loan|underwriting|debt|special situations|distressed|collections)\b/i',
                'accounting' => '/\b(?:account(?:ing|ant)|audit|financial reporting|reconciliation|general ledger|accounts payable|accounts receivable|bookkeep|tax|fp&a|forecast|budget|treasury|financial controller)\b/i',
                'risk_compliance' => '/\b(?:risk|compliance|kyc|aml|governance|controls|internal audit|regulatory|data privacy|privacy|gdpr)\b/i',
                'operations' => '/\b(?:operations|customer service|call cent(?:re|er)|service delivery|back office|process improvement|support)\b/i',
                'commercial' => '/\b(?:sales|marketing|commercial|business development|customer relations|partnerships|alliances|wholesale)\b/i',
                'technology' => '/\b(?:cloud|data|analytics|python|sql|power bi|tableau|information security|cyber|digital|software|engineer|developer)\b/i',
                'supply_chain' => '/\b(?:supply chain|procurement|logistics|inventory|warehouse|planning)\b/i',
            ];

            foreach ($family_patterns as $family_key => $pattern) {
                if (preg_match($pattern, $haystack)) {
                    return $family_key;
                }
            }

            return 'general';
        }

        private function infer_apply_chat_matching_role_seed_seniority(array $seed_item)
        {
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($seed_item['seniority'] ?? ''),
                (string) ($seed_item['title'] ?? ''),
            ]))));

            if ($haystack === '') {
                return 'general';
            }

            if (preg_match('/\b(?:intern|graduate|junior|entry|assistant)\b/i', $haystack)) {
                return 'junior';
            }
            if (preg_match('/\b(?:head|director|vp|vice president|chief|partner)\b/i', $haystack)) {
                return 'leadership';
            }
            if (preg_match('/\b(?:manager|lead|principal|senior)\b/i', $haystack)) {
                return 'mid_senior';
            }

            return 'general';
        }

        private function diversify_apply_chat_matching_role_seed(array $seed, $limit)
        {
            $limit = max(1, (int) $limit);
            $family_buckets = [];
            $family_order = [];
            $seed = array_values(array_filter($seed, 'is_array'));

            foreach ($seed as $seed_item) {
                $family_key = $this->infer_apply_chat_matching_role_seed_family($seed_item);
                $seniority_key = $this->infer_apply_chat_matching_role_seed_seniority($seed_item);
                $bucket_key = $family_key . ':' . $seniority_key;
                if (!isset($family_buckets[$bucket_key])) {
                    $family_buckets[$bucket_key] = [];
                    $family_order[] = $bucket_key;
                }
                $family_buckets[$bucket_key][] = $seed_item;
            }

            $diversified = [];
            $seen = [];
            while (count($diversified) < $limit) {
                $added_this_round = false;
                foreach ($family_order as $bucket_key) {
                    while (!empty($family_buckets[$bucket_key])) {
                        $seed_item = array_shift($family_buckets[$bucket_key]);
                        $seed_key = $this->get_apply_chat_seed_key($seed_item);
                        if (isset($seen[$seed_key])) {
                            continue;
                        }
                        $diversified[] = $seed_item;
                        $seen[$seed_key] = true;
                        $added_this_round = true;
                        break;
                    }
                    if (count($diversified) >= $limit) {
                        break 2;
                    }
                }
                if (!$added_this_round) {
                    break;
                }
            }

            return array_values($diversified);
        }

        private function get_apply_chat_matching_roles_seed(array $context = [], $limit = 120)
        {
            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return [];
            }

            $post_model = new SFFC_CRM_Post();
            $user_id = get_current_user_id();
            $limit = max(48, min(180, absint($limit)));
            $context = array_merge([
                'location' => '',
                'sector' => '',
                'keywords' => '',
            ], $context);

            $candidate_sets = [];
            $base_args = [
                'page' => 1,
                'approved_only' => true,
                'user_id' => $user_id,
            ];

            if ($context['location'] !== '') {
                $candidate_sets[] = $post_model->get_feed(array_merge($base_args, [
                    'per_page' => 36,
                    'location' => $context['location'],
                ]));
                $candidate_sets[] = $this->get_apply_chat_jobs_post_seed_candidates($context, 36);
            }

            if ($context['sector'] !== '') {
                $candidate_sets[] = $post_model->get_feed(array_merge($base_args, [
                    'per_page' => 36,
                    'sector' => $context['sector'],
                ]));
                $candidate_sets[] = $this->get_apply_chat_jobs_post_seed_candidates($context, 36);
            }

            if ($context['keywords'] !== '') {
                $candidate_sets[] = $post_model->get_feed(array_merge($base_args, [
                    'per_page' => 36,
                    'keywords' => $context['keywords'],
                ]));
                $candidate_sets[] = $this->get_apply_chat_jobs_post_seed_candidates($context, 36);
            }

            $candidate_sets[] = $post_model->get_feed(array_merge($base_args, [
                'per_page' => $limit,
            ]));
            $candidate_sets[] = $this->get_apply_chat_jobs_post_seed_candidates($context, $limit);

            $seed = [];
            $seen = [];
            $normalized_sets = array_map(static function ($candidate_set) {
                return array_values((array) $candidate_set);
            }, $candidate_sets);

            while (count($seed) < $limit) {
                $added_this_round = false;

                foreach ($normalized_sets as &$candidate_set) {
                    while (!empty($candidate_set)) {
                        $matching_role = array_shift($candidate_set);
                        $seed_item = $this->build_apply_chat_matching_role_seed_item((array) $matching_role);
                        if (!is_array($seed_item)) {
                            continue;
                        }

                        $seed_key = $this->get_apply_chat_seed_key($seed_item);

                        if (isset($seen[$seed_key])) {
                            continue;
                        }

                        $seed[] = $seed_item;
                        $seen[$seed_key] = true;
                        $added_this_round = true;
                        break;
                    }

                    if (count($seed) >= $limit) {
                        break 2;
                    }
                }
                unset($candidate_set);

                if (!$added_this_round) {
                    break;
                }
            }

            return $this->diversify_apply_chat_matching_role_seed(array_values($seed), $limit);
        }

        private function get_recruiter_intro_onboarding_matches(array $post_context, $limit = 6, $include_selected = true)
        {
            if (!class_exists('SFFC_CRM_Post')) {
                $model_file = plugin_dir_path(__FILE__) . 'models/class-crm-post.php';
                if (file_exists($model_file)) {
                    require_once $model_file;
                }
            }

            if (!class_exists('SFFC_CRM_Post')) {
                return [
                    'total' => 0,
                    'items' => [],
                ];
            }

            $post_model = new SFFC_CRM_Post();
            $candidate_sets = [];

            $location_filter = $post_context['location_city'] ?: $post_context['location_short'];
            if ($location_filter !== '') {
                $candidate_sets[] = $post_model->get_feed([
                    'per_page' => 36,
                    'location' => $location_filter,
                ]);
            }

            if (!empty($post_context['sector'])) {
                $candidate_sets[] = $post_model->get_feed([
                    'per_page' => 36,
                    'sector' => $post_context['sector'],
                ]);
            }

            $keyword_seed = implode(' ', array_slice(array_filter([
                $post_context['job_title'] ?? '',
                $post_context['company_name'] ?? '',
            ]), 0, 2));
            if ($keyword_seed !== '') {
                $candidate_sets[] = $post_model->get_feed([
                    'per_page' => 36,
                    'keywords' => $keyword_seed,
                ]);
            }

            $candidate_sets[] = $post_model->get_feed([
                'per_page' => 60,
            ]);

            $scored = [];
            $seen = [];

            if ($include_selected) {
                $selected_item = $this->build_recruiter_intro_match_item($post_context, $post_context, true, 999, [
                    __('Selected role', 'senna-finance'),
                    $post_context['sector'] ? __('Sector match', 'senna-finance') : __('Finance role', 'senna-finance'),
                    __('One-click queue', 'senna-finance'),
                ]);
                $scored[] = $selected_item;
                $seen[$post_context['id']] = true;
            }

            foreach ($candidate_sets as $candidate_set) {
                foreach ((array) $candidate_set as $row) {
                    $candidate_id = (int) ($row['id'] ?? 0);
                    if (!$candidate_id || isset($seen[$candidate_id]) || $candidate_id === (int) $post_context['id']) {
                        continue;
                    }

                    $reasons = [];
                    $score = $this->score_recruiter_intro_match_row($row, $post_context, $reasons);
                    if ($score <= 0) {
                        continue;
                    }

                    $scored[] = $this->build_recruiter_intro_match_item($row, $post_context, false, $score, $reasons);
                    $seen[$candidate_id] = true;
                }
            }

            usort($scored, static function ($left, $right) {
                $left_score = $left['score'] ?? 0;
                $right_score = $right['score'] ?? 0;
                if ($left_score === $right_score) {
                    return strcmp($right['posted_sort'] ?? '', $left['posted_sort'] ?? '');
                }
                return $right_score <=> $left_score;
            });

            $total = count($scored);
            $items = array_slice($scored, 0, max(1, (int) $limit));

            // Authentic pre-submission statuses
            $statuses = [
                ['status' => __('Ready to apply', 'senna-finance'), 'key' => 'ready'],
                ['status' => __('Materials ready', 'senna-finance'), 'key' => 'ready'],
                ['status' => __('CV tailored', 'senna-finance'), 'key' => 'ready'],
            ];

            foreach ($items as $index => &$item) {
                $item['is_blurred'] = $index >= 3;
                $status_data = $statuses[$index % count($statuses)];
                $item['demo_status'] = $status_data['status'];
                $item['demo_status_key'] = $status_data['key'];
            }
            unset($item);

            $recent_items = [];
            $recent_total = 0;
            $recent_cutoff = strtotime('-3 days', current_time('timestamp'));
            foreach ($scored as $candidate) {
                $posted_timestamp = !empty($candidate['posted_sort']) ? strtotime((string) $candidate['posted_sort']) : 0;
                if ($posted_timestamp && $posted_timestamp >= $recent_cutoff) {
                    $recent_total++;
                    if (count($recent_items) < 3) {
                        $recent_items[] = $candidate;
                    }
                }
            }

            $best_items = array_slice($items, 0, 3);

            return [
                'total' => $total,
                'items' => $items,
                'best_items' => $best_items,
                'recent_items' => $recent_items,
                'recent_total' => $recent_total,
            ];
        }

        private function score_recruiter_intro_match_row(array $row, array $post_context, array &$reasons)
        {
            $score = 0;
            $reasons = [];

            $row_sector = sanitize_text_field((string) ($row['sector'] ?? ''));
            if ($row_sector !== '' && !empty($post_context['sector']) && strtolower($row_sector) === strtolower((string) $post_context['sector'])) {
                $score += 4;
                $reasons[] = __('Sector match', 'senna-finance');
            }

            $row_seniority = sanitize_text_field((string) ($row['seniority'] ?? ''));
            if ($row_seniority !== '' && !empty($post_context['seniority']) && strtolower($row_seniority) === strtolower((string) $post_context['seniority'])) {
                $score += 3;
                $reasons[] = __('Level match', 'senna-finance');
            }

            $row_location = strtolower(trim((string) (($row['location_city'] ?? '') ?: ($row['location'] ?? ''))));
            $target_location = strtolower(trim((string) ($post_context['location_city'] ?: $post_context['location_short'])));
            if ($row_location !== '' && $target_location !== '' && false !== strpos($row_location, $target_location)) {
                $score += 2;
                $reasons[] = __('Global', 'senna-finance');
            }

            $title_terms = preg_split('/[\s,\/\-]+/', strtolower((string) ($post_context['job_title'] ?? '')));
            $title_terms = array_values(array_filter(array_map(static function ($term) {
                $term = trim((string) $term);
                return strlen($term) >= 4 ? $term : '';
            }, (array) $title_terms)));
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($row['role_title'] ?? ''),
                (string) ($row['company'] ?? ''),
                (string) ($row['keywords'] ?? ''),
            ]))));

            $keyword_hits = 0;
            foreach (array_slice(array_unique($title_terms), 0, 5) as $term) {
                if ($term !== '' && false !== strpos($haystack, $term)) {
                    $keyword_hits++;
                }
            }
            if ($keyword_hits > 0) {
                $score += min(3, $keyword_hits);
                $reasons[] = __('Keyword fit', 'senna-finance');
            }

            if (!empty($row['is_featured'])) {
                $score += 1;
            }

            return $score;
        }

        private function build_recruiter_intro_match_item(array $row, array $post_context, $is_selected, $score, array $reasons)
        {
            $company = sanitize_text_field((string) ($row['company_name'] ?? $row['company'] ?? __('Confidential company', 'senna-finance')));
            $role_title = sanitize_text_field((string) ($row['job_title'] ?? $row['role_title'] ?? __('Confidential Role', 'senna-finance')));
            $location = sanitize_text_field((string) ($row['location_short'] ?? $row['location'] ?? __('Global', 'senna-finance')));
            $company_logo = esc_url_raw((string) ($row['company_logo'] ?? ''));
            $apply_link = '';
            if (!empty($row['application_url'])) {
                $apply_link = esc_url_raw((string) $row['application_url']);
            }

            $source_link = '';
            if (!empty($row['source_url'])) {
                $source_link = esc_url_raw((string) $row['source_url']);
            }

            $recruiter_email = sanitize_email((string) ($row['recruiter_email'] ?? ''));
            $email_link = '';
            if ($recruiter_email) {
                $email_subject = sprintf(__('Application for %s', 'senna-finance'), $role_title);
                $email_body = sprintf(
                    __("Hi,\n\nI am reaching out regarding the %s role in %s.\n\nI would be very interested in being considered and would welcome the chance to share more about my background.\n\nBest regards,", 'senna-finance'),
                    $role_title,
                    $location
                );
                $email_link = sprintf(
                    'mailto:%s?subject=%s&body=%s',
                    antispambot($recruiter_email),
                    rawurlencode($email_subject),
                    rawurlencode($email_body)
                );
            }
            if ($apply_link === '' && $email_link !== '') {
                $apply_link = $email_link;
            }

            $reasons = array_values(array_unique(array_filter(array_map('sanitize_text_field', $reasons))));
            $reasons = array_slice($reasons, 0, 3);

            // Get recruiter data
            $recruiter_name = sanitize_text_field((string) ($row['recruiter_name'] ?? ''));
            $recruiter_firm = sanitize_text_field((string) ($row['recruiter_firm'] ?? ''));
            $recruiter_photo = esc_url_raw((string) ($row['recruiter_photo'] ?? ''));
            $recruiter_title = sanitize_text_field((string) ($row['recruiter_title'] ?? ''));
            $recruiter_linkedin = esc_url_raw((string) ($row['recruiter_linkedin'] ?? ''));

            // Parse keywords
            $keywords = [];
            if (!empty($row['keywords'])) {
                $raw_keywords = $row['keywords'];
                if (is_string($raw_keywords)) {
                    $decoded = json_decode($raw_keywords, true);
                    if (is_array($decoded)) {
                        $keywords = array_slice($decoded, 0, 5);
                    } else {
                        $keywords = array_slice(array_filter(preg_split('/[\r\n,|]+/', $raw_keywords)), 0, 5);
                    }
                } elseif (is_array($raw_keywords)) {
                    $keywords = array_slice($raw_keywords, 0, 5);
                }
                $keywords = array_map('sanitize_text_field', $keywords);
            }

            return [
                'id' => (int) ($row['id'] ?? 0),
                'role_title' => $role_title,
                'company' => $company,
                'location' => $location,
                'company_logo' => $company_logo,
                'company_initials' => $this->get_recruiter_intro_company_initials($company),
                'posted_label' => $this->format_recruiter_intro_posted_label($row['posted_at'] ?? ''),
                'posted_sort' => (string) ($row['posted_at'] ?? ''),
                'reasons' => $reasons,
                'link' => $source_link ?: $apply_link,
                'apply_link' => $apply_link,
                'email' => $recruiter_email,
                'email_link' => $email_link,
                'score' => (int) $score,
                'match_percent' => max(72, min(99, (int) round(($score / 10) * 100))),
                'is_selected_role' => (bool) $is_selected,
                'recruiter_name' => $recruiter_name,
                'recruiter_firm' => $recruiter_firm,
                'recruiter_photo' => $recruiter_photo,
                'recruiter_title' => $recruiter_title,
                'recruiter_linkedin' => $recruiter_linkedin,
                'keywords' => $keywords,
            ];
        }

        private function get_recruiter_intro_company_initials($company)
        {
            $words = preg_split('/[\s&\-]+/', trim((string) $company));
            $words = array_values(array_filter($words));
            if (empty($words)) {
                return 'SC';
            }

            $initials = '';
            foreach (array_slice($words, 0, 2) as $word) {
                $initials .= strtoupper(function_exists('mb_substr') ? mb_substr($word, 0, 1) : substr($word, 0, 1));
            }

            return $initials ?: 'SC';
        }

