        private function current_user_has_recruiter_contact_credit_access($recruiter_email = '')
        {
            if (!is_user_logged_in()) {
                return false;
            }

            $user_id = get_current_user_id();
            if ($user_id <= 0) {
                return false;
            }

            if (user_can($user_id, 'manage_options')) {
                return true;
            }

            if ($this->has_existing_recruiter_contact_credit_event($user_id, $recruiter_email)) {
                return true;
            }

            $summary = $this->get_recruiter_contact_credit_summary($user_id);

            return !empty($summary['has_plan']) && (int) ($summary['remaining'] ?? 0) > 0;
        }

        private function render_apply_all_credit_meter(array $summary, $context = 'inline')
        {
            $context = sanitize_html_class($context ?: 'inline');
            $percent = max(0, min(100, (int) ($summary['percent'] ?? 0)));
            $used = max(0, (int) ($summary['used'] ?? 0));
            $limit = max(0, (int) ($summary['limit'] ?? 0));
            $label = sprintf(__('%d%% Used', 'senna-finance'), $percent);
            $meta = $limit > 0
                ? sprintf(__('%1$d of %2$d Recruiter Intro credits', 'senna-finance'), $used, $limit)
                : __('No active credits', 'senna-finance');

            ob_start();
        ?>
            <div class="sffc-apply-credit-meter sffc-apply-credit-meter--<?php echo esc_attr($context); ?>" data-apply-credit-meter data-credit-used="<?php echo esc_attr($used); ?>" data-credit-limit="<?php echo esc_attr($limit); ?>">
                <div class="sffc-apply-credit-meter__head">
                    <span><?php esc_html_e('Recruiter Intro Credits', 'senna-finance'); ?></span>
                    <strong data-credit-percent><?php echo esc_html($label); ?></strong>
                </div>
                <div class="sffc-apply-credit-meter__bar" aria-hidden="true">
                    <span data-credit-bar style="width: <?php echo esc_attr($percent); ?>%;"></span>
                </div>
                <div class="sffc-apply-credit-meter__meta" data-credit-meta><?php echo esc_html($meta); ?></div>
            </div>
        <?php
            return ob_get_clean();
        }

