        private function get_primary_cycle_plan(array $plans)
        {
            if (empty($plans)) {
                return null;
            }

            foreach ($plans as $plan) {
                if (!empty($plan['featured_signup'])) {
                    return $plan;
                }
            }

            return $plans[0];
        }

        private function get_recruiter_cycle_label($cycle)
        {
            return 'annual' === $cycle ? __('Annual', 'senna-finance') : __('Monthly', 'senna-finance');
        }

        private function render_review_stars($score)
        {
            $score = max(0, min(5, floatval($score)));
            $filled = (int) floor($score);
            $half = (($score - $filled) >= 0.5) ? 1 : 0;
            $empty = 5 - $filled - $half;
            $html = '';

            for ($i = 0; $i < $filled; $i++) {
                $html .= '<span class="sffc-carousel-star is-filled" aria-hidden="true">★</span>';
            }

            if ($half) {
                $html .= '<span class="sffc-carousel-star is-half" aria-hidden="true">★</span>';
            }

            for ($i = 0; $i < $empty; $i++) {
                $html .= '<span class="sffc-carousel-star" aria-hidden="true">★</span>';
            }

            return $html;
        }

        private function format_review_assessor_name($review)
        {
            $first = trim((string) ($review['first_name'] ?? ''));
            $last = trim((string) ($review['last_name'] ?? ''));
            $last_initial = $last !== '' ? strtoupper(substr($last, 0, 1)) . '.' : '';
            $name = trim($first . ' ' . $last_initial);

            return $name !== '' ? $name : __('Anonymous', 'senna-finance');
        }

        private function truncate_review_copy($text, $limit = 150)
        {
            $text = trim(wp_strip_all_tags((string) $text));
            if ($text === '') {
                return '';
            }

            if (function_exists('mb_strlen') && function_exists('mb_substr')) {
                if (mb_strlen($text) <= $limit) {
                    return $text;
                }

                return rtrim(mb_substr($text, 0, max(0, $limit - 3))) . '...';
            }

            if (strlen($text) <= $limit) {
                return $text;
            }

            return rtrim(substr($text, 0, max(0, $limit - 3))) . '...';
        }

        /**
         * Conversion-optimized carousel shortcode
         * Usage: [sffc_conversion_carousel posts_per_page="12"]
         */
        public function render_conversion_carousel($atts)
        {
            $atts = shortcode_atts([
                'posts_per_page' => 12,
            ], $atts);

            // Enqueue assets
            wp_enqueue_style(
                'sffc-conversion-carousel',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-conversion-carousel.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-conversion-carousel',
                SFFC_PLUGIN_URL . 'assets/js/crm-conversion-carousel.js',
                ['jquery'],
                SFFC_VERSION,
                true
            );

            wp_localize_script('sffc-conversion-carousel', 'sffcConversionData', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_conversion_nonce'),
            ]);

            // Query recruiter posts
            $args = [
                'post_type' => 'sffc_recruiter_post',
                'posts_per_page' => intval($atts['posts_per_page']),
                'post_status' => 'publish',
                'orderby' => 'rand',
            ];

            $query = new WP_Query($args);

            if (!$query->have_posts()) {
                return '';
            }

            $recruiters = [];
            while ($query->have_posts()) : $query->the_post();
                $post_id = get_the_ID();
                $recruiters[] = [
                    'id' => $post_id,
                    'job_title' => get_post_meta($post_id, '_job_title', true) ?: get_the_title(),
                    'company' => get_post_meta($post_id, '_company_name', true),
                    'location' => get_post_meta($post_id, '_job_location', true),
                    'recruiter_name' => get_post_meta($post_id, '_recruiter_name', true),
                    'recruiter_photo' => $this->get_recruiter_photo($post_id),
                    'recruiter_title' => get_post_meta($post_id, '_recruiter_title', true),
                    'salary_min' => get_post_meta($post_id, '_salary_min', true),
                    'salary_max' => get_post_meta($post_id, '_salary_max', true),
                ];
            endwhile;
            wp_reset_postdata();

            ob_start();
        ?>
