        private function get_recruiter_photo($post_id)
        {
            $image_id = get_post_meta($post_id, '_recruiter_image_id', true);
            if ($image_id) {
                return wp_get_attachment_image_url($image_id, 'thumbnail');
            }
            return get_post_meta($post_id, '_recruiter_image_url', true);
        }

