        private function get_mena_careers_paid_pricing_tier_plans()
        {
            $plans = [];

            foreach ((array) $this->get_subscription_plans() as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $shortcode = isset($plan['shortcode']) ? (string) $plan['shortcode'] : '';
                $product_id = !empty($plan['memberpress_product_id'])
                    ? absint($plan['memberpress_product_id'])
                    : $this->extract_memberpress_product_id_from_shortcode($shortcode);
                $price_amount = isset($plan['price_amount']) && $plan['price_amount'] !== ''
                    ? (float) $plan['price_amount']
                    : 0.0;
                if ($price_amount <= 0 && $product_id > 0) {
                    $price_amount = $this->get_memberpress_product_price_amount($product_id);
                }
                if ($price_amount <= 0 && !empty($plan['price']) && preg_match('/(\d+(?:[.,]\d+)?)/', (string) $plan['price'], $price_matches)) {
                    $price_amount = (float) str_replace(',', '.', $price_matches[1]);
                }
                if ($price_amount <= 0) {
                    continue;
                }

                $url = trim((string) ($plan['mp_url'] ?? ''));
                if ($url === '' && $product_id > 0) {
                    $url = (string) get_permalink($product_id);
                }
                if ($url === '') {
                    $url = $this->get_crm_reddit_membership_url();
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $display_price = $this->format_plan_price_amount((array) $plan) ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $tagline = trim((string) ($plan['tagline'] ?? ($plan['audience'] ?? '')));
                $signup_path = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim(implode(' ', array_filter([$name, $tagline, implode(' ', $features)])))
                );

                $plans[] = [
                    'name' => sanitize_text_field($name),
                    'slug' => sanitize_title((string) ($plan['slug'] ?? $name)),
                    'price' => sanitize_text_field($display_price),
                    'price_amount' => $price_amount,
                    'tagline' => sanitize_text_field($tagline),
                    'features' => $features,
                    'url' => esc_url_raw($url),
                    'shortcode' => wp_kses_post($shortcode),
                    'memberpress_product_id' => $product_id,
                    'is_annual' => !empty($plan['is_annual']),
                    'is_featured' => !empty($plan['featured_signup']),
                    'signup_path' => $signup_path['path'],
                ];
            }

            if (empty($plans) && class_exists('SFFC_MemberPress_Integration') && method_exists('SFFC_MemberPress_Integration', 'get_available_memberships')) {
                foreach ((array) SFFC_MemberPress_Integration::get_available_memberships() as $membership) {
                    $product_id = absint($membership['id'] ?? 0);
                    $name = trim((string) ($membership['name'] ?? ''));
                    $price_amount = isset($membership['price']) ? (float) $membership['price'] : 0.0;
                    if ($product_id <= 0 || $name === '' || $price_amount <= 0) {
                        continue;
                    }

                    $period = trim((string) ($membership['period_type'] ?? ''));
                    $period_label = $period !== '' ? sprintf('/ %s', $period) : '';
                    $plans[] = [
                        'name' => sanitize_text_field($name),
                        'slug' => sanitize_title($name),
                        'price' => sanitize_text_field(sprintf('%s%s', $this->get_currency_symbol(strtoupper(get_option('currency_detector_base_currency', 'USD'))), number_format($price_amount, 2)) . ($period_label ? ' ' . $period_label : '')),
                        'price_amount' => $price_amount,
                        'tagline' => sanitize_text_field((string) ($membership['description'] ?? __('Personalized tools and guidance to grow your career.', 'senna-finance'))),
                        'features' => [],
                        'url' => esc_url_raw((string) ($membership['register_url'] ?? get_permalink($product_id))),
                        'shortcode' => '',
                        'memberpress_product_id' => $product_id,
                        'is_annual' => strtolower($period) === 'years' || strtolower($period) === 'year',
                        'is_featured' => false,
                        'signup_path' => 'platform',
                    ];
                }
            }

            usort($plans, static function ($a, $b) {
                if ((bool) ($a['is_featured'] ?? false) !== (bool) ($b['is_featured'] ?? false)) {
                    return (bool) ($b['is_featured'] ?? false) <=> (bool) ($a['is_featured'] ?? false);
                }

                if ((bool) ($a['is_annual'] ?? false) !== (bool) ($b['is_annual'] ?? false)) {
                    return (bool) ($a['is_annual'] ?? false) <=> (bool) ($b['is_annual'] ?? false);
                }

                return (float) ($a['price_amount'] ?? 0) <=> (float) ($b['price_amount'] ?? 0);
            });

            return array_slice($plans, 0, 4);
        }

        public function render_members_pricing_landing($atts = [])
        {
            $atts = shortcode_atts([
                'headline' => __('Finance Career Guidance', 'senna-finance'),
                'subheadline' => __('Access live private equity roles, recruiter posts, instant alerts, salary benchmarks, and application support across the markets that matter most.', 'senna-finance'),
                'prompt' => __('Create your membership to unlock private equity roles, recruiter access, salary intelligence, instant alerts, and application tracking.', 'senna-finance'),
                'button_label' => __('Join MENA Careers', 'senna-finance'),
            ], $atts, 'sffc_members_pricing_landing');

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-landing.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-landing.css') : SFFC_VERSION;
            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-landing.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-landing.js') : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-member-pricing-landing',
                SFFC_PLUGIN_URL . 'assets/css/crm/member-pricing-landing.css',
                [],
                $css_version
            );

            wp_enqueue_script(
                'sffc-member-pricing-landing',
                SFFC_PLUGIN_URL . 'assets/js/crm/member-pricing-landing.js',
                [],
                $js_version,
                true
            );

            wp_localize_script('sffc-member-pricing-landing', 'sffcMemberPricingLanding', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'prefillNonce' => wp_create_nonce('sffc_sync_signup_prefill'),
            ]);

            $plans = array_values(array_filter((array) $this->get_subscription_plans(), static function ($plan) {
                return empty($plan['is_annual']);
            }));
            if (empty($plans)) {
                $plans = array_values((array) $this->get_subscription_plans());
            }

            $normalized_plans = [];
            $plan_cycles = [
                'monthly' => [],
                'annual' => [],
            ];

            foreach ($plans as $index => $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $display_price = $this->format_plan_price_amount($plan) ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $amount_label = $display_price;
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', (string) $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                }
                $price_currency = strtoupper(trim((string) ($plan['price_currency'] ?? 'GBP')));
                $currency_symbol = $price_currency === '' || $price_currency === 'GBP' ? '£' : $price_currency . ' ';
                $monthly_price_amount = isset($plan['price_amount']) ? (float) $plan['price_amount'] : 0.0;

                $normalized_plans[] = [
                    'slug' => (string) ($plan['slug'] ?? sanitize_title($name)),
                    'name' => $name,
                    'tagline' => trim((string) ($plan['tagline'] ?? '')),
                    'audience' => trim((string) ($plan['audience'] ?? '')),
                    'display_price' => $display_price,
                    'amount_label' => $amount_label,
                    'price_amount' => $monthly_price_amount,
                    'price_currency' => $price_currency,
                    'currency_symbol' => $currency_symbol,
                    'billing_cycle' => trim((string) ($plan['billing_cycle'] ?? __('per month', 'senna-finance'))),
                    'matches_per_week' => max(0, (int) ($plan['matches_per_week'] ?? 0)),
                    'features' => array_slice($features, 0, 5),
                    'url' => !empty($plan['mp_url']) ? esc_url_raw((string) $plan['mp_url']) : esc_url_raw($this->get_canonical_membership_url()),
                    'featured_signup' => !empty($plan['featured_signup']),
                    'theme' => ['indigo', 'violet', 'sunset'][$index % 3],
                ];

                $monthly_entry = $normalized_plans[count($normalized_plans) - 1];
                $monthly_entry['cycle'] = 'monthly';
                $monthly_entry['badge'] = 0 === $index ? __('Most popular', 'senna-finance') : (1 === $index ? __('Free Recruiter Job Alerts', 'senna-finance') : '');
                $monthly_entry['billing_label'] = __('Monthly', 'senna-finance');
                $monthly_entry['cta_label'] = __('Choose plan', 'senna-finance');
                $plan_cycles['monthly'][] = $monthly_entry;

                $annual_display_price = trim((string) ($plan['annual_price'] ?? ''));
                if ($annual_display_price === '' && $monthly_price_amount > 0) {
                    $annual_display_price = $currency_symbol . number_format($monthly_price_amount * 12 * 0.85, 2) . '/year';
                }

                if ($annual_display_price !== '' || !empty($plan['annual_mp_url']) || !empty($plan['annual_shortcode'])) {
                    $annual_display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $annual_display_price);
                    $annual_amount_label = $annual_display_price;
                    if (preg_match('/^(.*?)\s*\/\s*(.+)$/', (string) $annual_display_price, $annual_matches)) {
                        $annual_amount_label = trim((string) $annual_matches[1]);
                    }

                    $annual_entry = $monthly_entry;
                    $annual_entry['cycle'] = 'annual';
                    $annual_entry['slug'] = $monthly_entry['slug'] . '-annual';
                    $annual_entry['display_price'] = $annual_display_price;
                    $annual_entry['amount_label'] = $annual_amount_label;
                    $annual_entry['billing_cycle'] = trim((string) ($plan['annual_billing_cycle'] ?? __('per year', 'senna-finance'))) ?: __('per year', 'senna-finance');
                    $annual_entry['billing_label'] = __('Annual', 'senna-finance');
                    $annual_entry['url'] = !empty($plan['annual_mp_url']) ? esc_url_raw((string) $plan['annual_mp_url']) : $monthly_entry['url'];
                    $annual_entry['save_label'] = __('Save 15%', 'senna-finance');
                    $annual_entry['cta_label'] = __('Choose annual', 'senna-finance');
                    $plan_cycles['annual'][] = $annual_entry;
                }
            }

            if (empty($normalized_plans)) {
                return '';
            }

            if (empty($plan_cycles['annual'])) {
                $plan_cycles['annual'] = array_map(static function ($plan) {
                    $annual_amount = isset($plan['price_amount']) ? (float) $plan['price_amount'] * 12 * 0.85 : 0.0;
                    if ($annual_amount > 0) {
                        $annual_display_price = (string) ($plan['currency_symbol'] ?? '£') . number_format($annual_amount, 2) . '/year';
                        $plan['display_price'] = preg_replace('/([.,]00)(?=\s|$|\/)/', '', $annual_display_price);
                        $plan['amount_label'] = preg_replace('/\/.*$/', '', $plan['display_price']);
                    }
                    $plan['cycle'] = 'annual';
                    $plan['billing_label'] = __('Annual', 'senna-finance');
                    $plan['billing_cycle'] = __('per year', 'senna-finance');
                    $plan['save_label'] = __('Save 15%', 'senna-finance');
                    $plan['cta_label'] = __('Choose annual', 'senna-finance');
                    return $plan;
                }, $plan_cycles['monthly']);
            }

            $current_user = wp_get_current_user();
            $prefill_name = is_user_logged_in() && $current_user instanceof WP_User
                ? trim((string) ($current_user->display_name ?: $current_user->user_login))
                : '';
            $prefill_email = is_user_logged_in() && $current_user instanceof WP_User ? (string) $current_user->user_email : '';

            $career_stage_items = [
                [
                    'label' => __('Manager', 'senna-finance'),
                    'value' => 'student',
                    'image' => 'https://joinsenna.com/wp-content/uploads/2026/05/vecteezy_asia-businesspeople-stand-behind-transparent-glass-wall_3655953-scaled.jpg',
                ],
                [
                    'label' => __('Senior Manager', 'senna-finance'),
                    'value' => 'analyst',
                    'image' => 'https://joinsenna.com/wp-content/uploads/2023/12/094982036-business-people-standing-lapto.jpeg',
                ],
                [
                    'label' => __('Director', 'senna-finance'),
                    'value' => 'associate',
                    'image' => 'https://joinsenna.com/wp-content/uploads/2024/04/236910136-business-people-diversity-and-.jpeg',
                ],
                [
                    'label' => __('VP / Head of Finance', 'senna-finance'),
                    'value' => 'manager_vp',
                    'image' => 'https://joinsenna.com/wp-content/uploads/2024/02/vecteezy_team-meeting-of-caucasian-business-people-brainstorming-on_8585059_315-3072x2048-1-1024x683-1.jpg',
                ],
            ];

            $checklist_items = [
                __('Live recruiter matches, alerts, and application routes', 'senna-finance'),
                __('4 senior finance strategy calls every month', 'senna-finance'),
                __('Unlimited finance career lists and alerts', 'senna-finance'),
                __('50 weekly job to CV scan requests', 'senna-finance'),
                __('60 application pack requests', 'senna-finance'),
            ];

            ob_start();
            ?>
