                <div class="sffc-member-pricing__hero-step sffc-member-pricing__step is-active" data-member-pricing-step="1">
                    <div class="sffc-member-pricing__stage-shell">
                        <div class="sffc-member-pricing__stage-card">
                            <div class="sffc-member-pricing__stage-rule" aria-hidden="true"></div>
                            <p class="sffc-member-pricing__stage-kicker"><?php esc_html_e('Start Your Journey', 'senna-finance'); ?></p>
