        private function render_member_signup_brand($primary_label, $show_signin = true)
        {
            $user_id = get_current_user_id();
            $is_logged_in = $user_id > 0;
            $profile_url = home_url('/terminal/?community_tab=templates');
            $memberships_url = home_url('/memberships/');
            $support_mailto = 'mailto:support.team@joinsenna.com';
            $account_user = $is_logged_in ? $this->get_crm_reddit_account_user($user_id) : [];
            $default_guest_avatar_url = 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp';
            $avatar_url = $is_logged_in ? $this->get_crm_reddit_profile_avatar_url($user_id, $account_user) : $default_guest_avatar_url;
            $first_name = $this->get_crm_reddit_current_user_first_name($user_id);
            $display_name = '';

            if (!empty($account_user['display_name'])) {
                $display_name = trim((string) $account_user['display_name']);
            } elseif (!empty($account_user['first_name']) || !empty($account_user['last_name'])) {
                $display_name = trim(((string) ($account_user['first_name'] ?? '')) . ' ' . ((string) ($account_user['last_name'] ?? '')));
            } elseif ($first_name !== '') {
                $display_name = trim((string) $first_name);
            }

            if ($display_name === '') {
                $display_name = __('MENA Careers member', 'senna-finance');
            }

            $avatar_initial = strtoupper(function_exists('mb_substr') ? (string) mb_substr($display_name, 0, 1) : substr($display_name, 0, 1));

            ob_start();
            ?>
            <header class="sffc-member-signup__brand" aria-label="<?php esc_attr_e('MENA Careers', 'senna-finance'); ?>">
                <span class="sffc-member-signup__brand-mark" aria-hidden="true">
                    <span class="sffc-member-signup__brand-glyph">S</span>
                    <span class="sffc-member-signup__brand-dot"></span>
                </span>
                <span class="sffc-member-signup__brand-copy">
                    <strong><?php esc_html_e('MENA Careers', 'senna-finance'); ?></strong>
                </span>
                <?php if ($is_logged_in) : ?>
                    <div class="sffc-member-signup__brand-account" data-member-signup-brand-account>
                        <button
                            type="button"
                            class="sffc-member-signup__brand-avatar-toggle"
                            data-member-signup-brand-account-toggle
                            aria-haspopup="menu"
                            aria-expanded="false"
                            aria-label="<?php echo esc_attr(sprintf(__('Open account menu for %s', 'senna-finance'), $display_name)); ?>">
                            <span class="sffc-member-signup__brand-avatar<?php echo $avatar_url !== '' ? ' has-image' : ''; ?>" aria-hidden="true">
                                <?php if ($avatar_url !== '') : ?>
                                    <img src="<?php echo esc_url($avatar_url); ?>" alt="<?php echo esc_attr($display_name); ?>">
                                <?php else : ?>
                                    <span><?php echo esc_html($avatar_initial); ?></span>
                                <?php endif; ?>
                            </span>
                            <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
                                <path d="M4 6.5 8 10.3 12 6.5" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7"></path>
                            </svg>
                        </button>
                        <div class="sffc-member-signup__brand-account-menu" data-member-signup-brand-account-menu role="menu" hidden>
                            <a href="<?php echo esc_url($profile_url); ?>" class="sffc-member-signup__brand-account-item" role="menuitem">
                                <?php esc_html_e('Profile', 'senna-finance'); ?>
                            </a>
                            <a href="<?php echo esc_url($memberships_url); ?>" class="sffc-member-signup__brand-account-item" role="menuitem">
                                <?php esc_html_e('Upgrade', 'senna-finance'); ?>
                            </a>
                            <a href="<?php echo esc_url($support_mailto); ?>" class="sffc-member-signup__brand-account-item" role="menuitem">
                                <?php esc_html_e('Contact Support', 'senna-finance'); ?>
                            </a>
                            <a href="<?php echo esc_url(wp_logout_url(home_url('/'))); ?>" class="sffc-member-signup__brand-account-item is-logout" role="menuitem">
                                <?php esc_html_e('Log Out', 'senna-finance'); ?>
                            </a>
                        </div>
                    </div>
                <?php elseif ($show_signin) : ?>
                    <a class="sffc-member-signup__brand-signin" href="<?php echo esc_url(home_url('/login/')); ?>"><?php esc_html_e('Sign in', 'senna-finance'); ?></a>
                <?php endif; ?>
            </header>
            <?php

            return (string) ob_get_clean();
        }

        private function get_basic_member_signup_plans_data($target_currency = null)
        {
            $raw_plans = array_values((array) $this->get_subscription_plans());
            $plans = [];

            foreach ($raw_plans as $index => $plan) {
                $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                $name = trim((string) ($plan['name'] ?? ''));
                if ($shortcode === '' || $name === '') {
                    continue;
                }

                $is_annual = !empty($plan['is_annual']);
                $cycle_label = $is_annual ? __('Annual', 'senna-finance') : __('Monthly', 'senna-finance');
                $display_price = $target_currency
                    ? $this->format_plan_price_amount_for_currency((array) $plan, $target_currency)
                    : $this->format_plan_price_amount((array) $plan);
                $display_price = $display_price ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);

                $tagline = trim((string) ($plan['tagline'] ?? ($plan['audience'] ?? '')));
                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim((string) $feature);
                    }, $plan['features'])))
                    : [];

                $option_label = $name;
                $panel_id = 'sffc-basic-member-signup-plan-' . sanitize_html_class((string) ($plan['slug'] ?? ('plan-' . $index)));
                if ($is_annual) {
                    $panel_id .= '-annual';
                }
                $memberpress_product_id = $this->extract_memberpress_product_id_from_shortcode($shortcode);
                $signup_path = (string) ($plan['signup_path'] ?? 'platform');

                $plans[] = [
                    'id' => $panel_id,
                    'memberpress_product_id' => $memberpress_product_id,
                    'signup_path' => $signup_path,
                    'option_label' => $option_label,
                    'name' => $name,
                    'cycle_label' => $cycle_label,
                    'price' => $display_price,
                    'tagline' => $tagline,
                    'features' => array_slice($features, 0, 4),
                    'shortcode' => $shortcode,
                ];
            }

            return $plans;
        }

        public function render_members_pricing_signup($atts = [])
        {
            $atts = shortcode_atts([
                'flow' => 'default',
                'mode' => 'default',
                'presentation' => 'page',
            ], $atts, 'sffc_members_pricing_signup');
            $flow = sanitize_key((string) $atts['flow']);
            if ($flow !== 'recruiter_contact') {
                $flow = 'default';
            }
            $mode = sanitize_key((string) $atts['mode']);
            $is_simple_flow = $mode === 'simple' && $flow !== 'recruiter_contact';
            $presentation = sanitize_key((string) $atts['presentation']);
            if ($presentation !== 'overlay') {
                $presentation = 'page';
            }

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-signup.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-signup.css') : SFFC_VERSION;
            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-signup.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-signup.js') : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-member-pricing-signup',
                SFFC_PLUGIN_URL . 'assets/css/crm/member-pricing-signup.css',
                [],
                $css_version
            );

            wp_enqueue_script(
                'sffc-member-pricing-signup',
                SFFC_PLUGIN_URL . 'assets/js/crm/member-pricing-signup.js',
                [],
                $js_version,
                true
            );

            $member_signup_locale = $this->get_member_pricing_signup_locale();
            $member_signup_i18n = $this->get_member_signup_i18n($member_signup_locale);
            $member_signup_prefill_email = $this->get_signup_email_prefill_value();

            wp_localize_script('sffc-member-pricing-signup', 'sffcMemberPricingSignup', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_member_pricing_signup'),
                'prefillNonce' => wp_create_nonce('sffc_sync_signup_prefill'),
                'loginUrl' => home_url('/login/'),
                'locale' => $member_signup_locale,
                'messages' => [
                    'invalidIdentity' => $member_signup_i18n['invalid_identity'],
                    'missingStudy' => __('Choose what you would like help with first to continue.', 'senna-finance'),
                ],
            ]);

            if (is_user_logged_in()) {
                $terminal_url = home_url('/terminal/');

                return sprintf(
                    '<section class="sffc-member-signup"><div class="sffc-member-signup__shell"><div class="sffc-member-signup__card is-login"><div class="sffc-member-signup__login-state"><h2>%s</h2><p>%s</p><a href="%s">%s</a></div></div></div></section>',
                    esc_html__('You are already signed in.', 'senna-finance'),
                    esc_html__('Continue to your MENA Careers terminal.', 'senna-finance'),
                    esc_url($terminal_url),
                    esc_html__('Open terminal', 'senna-finance')
                );
            }

            $recruiter_contact_context_job_id = 0;
            $recruiter_contact_context_item = [];
            $recruiter_contact_name = __('Recruiter contact', 'senna-finance');
            $recruiter_contact_title = __('Relevant contact for this role', 'senna-finance');
            $recruiter_contact_company = __('Hiring team context', 'senna-finance');
            $recruiter_contact_photo = '';
            $recruiter_contact_fallback_photo = 'https://joinsenna.com/wp-content/uploads/2024/04/266217121-designer-woman-portrait-and-ha.jpeg';
            $recruiter_contact_company_logo = '';
            $recruiter_contact_company_logo_fallback = 'https://joinsenna.com/wp-content/uploads/jet-engine-forms/4553/2025/05/vecteezy_n-logo-mark-design_12186620-1.jpg';
            $recruiter_contact_linkedin_label = __('Recruiter profile', 'senna-finance');
            $recruiter_contact_initial = 'R';
            $recruiter_contact_masked_email_label = '';

            if ($flow === 'recruiter_contact') {
                $recruiter_contact_context_job_id = $this->resolve_crm_reddit_jobs_post_id((int) ($_GET['sffc_recruiter_contact_job_id'] ?? 0));
                if ($recruiter_contact_context_job_id > 0) {
                    $this->set_signup_scoped_cookie('sffc_signup_mepr_job_id', (string) $recruiter_contact_context_job_id, time() + (30 * DAY_IN_SECONDS));
                    $recruiter_contact_context_item = (array) $this->get_cached_cv_match_job_posts_item($recruiter_contact_context_job_id);
                }

                $recruiter_contact_name = trim((string) ($recruiter_contact_context_item['recruiter_name'] ?? $recruiter_contact_name));
                $recruiter_contact_title = trim((string) ($recruiter_contact_context_item['recruiter_title'] ?? $recruiter_contact_title));
                $recruiter_contact_company = trim((string) ($recruiter_contact_context_item['company'] ?? $recruiter_contact_company));
                $recruiter_contact_photo = trim((string) ($recruiter_contact_context_item['recruiter_photo'] ?? ''));
                $recruiter_contact_email = sanitize_email((string) ($recruiter_contact_context_item['recruiter_email'] ?? ''));
                $recruiter_contact_company_logo = !empty($recruiter_contact_context_item['company_logo'])
                    ? $this->normalize_company_logo_url((string) $recruiter_contact_context_item['company_logo'])
                    : '';
                if (!empty($recruiter_contact_context_item['recruiter_linkedin'])) {
                    $recruiter_contact_linkedin_label = __('View LinkedIn', 'senna-finance');
                }
                if ($recruiter_contact_email !== '' && strpos($recruiter_contact_email, '@') !== false) {
                    $recruiter_contact_email_parts = explode('@', $recruiter_contact_email, 2);
                    $recruiter_contact_email_domain = trim((string) ($recruiter_contact_email_parts[1] ?? ''));
                    if ($recruiter_contact_email_domain !== '') {
                        $recruiter_contact_masked_email_label = '••••••••@' . $recruiter_contact_email_domain;
                    }
                }

                $recruiter_contact_initial_source = $recruiter_contact_name !== ''
                    ? $recruiter_contact_name
                    : $recruiter_contact_company;
                if ($recruiter_contact_initial_source !== '') {
                    $recruiter_contact_initial = strtoupper(function_exists('mb_substr')
                        ? mb_substr($recruiter_contact_initial_source, 0, 1)
                        : substr($recruiter_contact_initial_source, 0, 1));
                }
            }

            $plans = array_values((array) $this->get_subscription_plans());
            $plans_by_cycle = [
                'monthly' => [],
                'annual' => [],
            ];
            $normalize_signup_price_label = static function ($display_price) {
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $amount_label = $display_price;
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', (string) $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                }

                return [$display_price, $amount_label];
            };
            $legacy_signup_fallback_index = 0;

            foreach ($plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                if (!empty($plan['is_annual'])) {
                    continue;
                }
                if ($name === '' || $shortcode === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];
                $features = array_map(function ($feature) use ($member_signup_locale) {
                    return $this->translate_member_signup_feature($feature, $member_signup_locale);
                }, $features);

                $display_price = $this->format_plan_price_amount($plan) ?: trim((string) ($plan['price'] ?? ''));
                [$display_price, $amount_label] = $normalize_signup_price_label($display_price);
                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim($name . ' ' . (string) ($plan['tagline'] ?? '') . ' ' . (string) ($plan['audience'] ?? ''))
                );
                $signup_path = $signup_path_meta['path'];
                if (empty($plan['signup_path_configured']) && !$signup_path_meta['configured']) {
                    $path_hint = strtolower($name . ' ' . (string) ($plan['tagline'] ?? '') . ' ' . (string) ($plan['audience'] ?? ''));
                    if (preg_match('/\b(cv|resume|review|mentorship|support)\b/', $path_hint)) {
                        $signup_path = 'mentorship';
                    } elseif (preg_match('/\b(platform|access only|basic)\b/', $path_hint)) {
                        $signup_path = 'platform';
                    } else {
                        $signup_path = $legacy_signup_fallback_index === 0 ? 'platform' : 'mentorship';
                    }
                }
                $legacy_signup_fallback_index++;
                $plan_slug = sanitize_key((string) ($plan['slug'] ?? sanitize_title($name)));
                $monthly_entry = [
                    'id' => sanitize_key($plan_slug . '-monthly'),
                    'name' => $this->translate_member_signup_plan_name($name, $member_signup_locale),
                    'tagline' => $this->translate_member_signup_feature(trim((string) ($plan['tagline'] ?? $plan['audience'] ?? '')), $member_signup_locale),
                    'price' => $display_price,
                    'price_amount' => (float) ($plan['price_amount'] ?? 0),
                    'amount_label' => $amount_label,
                    'billing_cycle' => $member_signup_i18n['billing_monthly'],
                    'features' => array_slice($features, 0, 5),
                    'shortcode' => $shortcode,
                    'cycle' => 'monthly',
                    'signup_path' => $signup_path,
                    'featured_signup' => !empty($plan['featured_signup']),
                    'recruiter_contact_pricing' => !empty($plan['recruiter_contact_pricing']),
                ];
                $plans_by_cycle['monthly'][] = $monthly_entry;

                $annual_shortcode = trim((string) ($plan['annual_shortcode'] ?? ''));
                if ($annual_shortcode !== '') {
                    $annual_plan = $plan;
                    $annual_display_price = '';
                    if (!empty($plan['annual_price_amount'])) {
                        $annual_plan['price_amount'] = (float) $plan['annual_price_amount'];
                        $annual_plan['billing_cycle'] = trim((string) ($plan['annual_billing_cycle'] ?? '')) ?: __('per year', 'senna-finance');
                        $annual_display_price = $this->format_plan_price_amount($annual_plan);
                    }
                    $annual_display_price = $annual_display_price ?: trim((string) ($plan['annual_price'] ?? ''));
                    if ($annual_display_price === '') {
                        $annual_display_price = $display_price;
                    }
                    [$annual_display_price, $annual_amount_label] = $normalize_signup_price_label($annual_display_price);

                    $annual_entry = $monthly_entry;
                    $annual_entry['id'] = sanitize_key($plan_slug . '-annual');
                    $annual_entry['price'] = $annual_display_price;
                    $annual_entry['price_amount'] = (float) ($annual_plan['price_amount'] ?? 0);
                    $annual_entry['amount_label'] = $annual_amount_label;
                    $annual_entry['billing_cycle'] = $member_signup_i18n['billing_annual'];
                    $annual_entry['shortcode'] = $annual_shortcode;
                    $annual_entry['cycle'] = 'annual';
                    $plans_by_cycle['annual'][] = $annual_entry;
                }
            }

            foreach (['monthly', 'annual'] as $cycle) {
                $has_all_access = false;
                foreach ($plans_by_cycle[$cycle] as $plan) {
                    if (($plan['signup_path'] ?? '') === 'all_access') {
                        $has_all_access = true;
                        break;
                    }
                }

                if ($has_all_access) {
                    continue;
                }

                if ($is_simple_flow) {
                    $alias_candidate = !empty($plans_by_cycle[$cycle])
                        ? $plans_by_cycle[$cycle][count($plans_by_cycle[$cycle]) - 1]
                        : null;
                } else {
                    $alias_candidate = null;
                    foreach ($plans_by_cycle[$cycle] as $plan) {
                        if (($plan['signup_path'] ?? '') === 'mentorship') {
                            if (
                                $alias_candidate === null
                                || (float) ($plan['price_amount'] ?? 0) > (float) ($alias_candidate['price_amount'] ?? 0)
                            ) {
                                $alias_candidate = $plan;
                            }
                        }
                    }

                    if ($alias_candidate === null) {
                        $highest_amount = -1;
                        foreach ($plans_by_cycle[$cycle] as $plan) {
                            $amount = (float) ($plan['price_amount'] ?? 0);
                            if ($amount > $highest_amount) {
                                $highest_amount = $amount;
                                $alias_candidate = $plan;
                            }
                        }
                    }
                }

                if ($alias_candidate !== null) {
                    $all_access_alias = $alias_candidate;
                    $all_access_alias['id'] = sanitize_key((string) ($alias_candidate['id'] ?? '') . '-all-access');
                    $all_access_alias['signup_path'] = 'all_access';
                    $all_access_alias['featured_signup'] = !empty($all_access_alias['featured_signup']);
                    $plans_by_cycle[$cycle][] = $all_access_alias;
                }
            }

            foreach (['monthly', 'annual'] as $cycle) {
                $unique_plans = [];
                foreach ($plans_by_cycle[$cycle] as $plan) {
                    $path = (string) ($plan['signup_path'] ?? 'platform');
                    if (
                        !isset($unique_plans[$path])
                        || (empty($unique_plans[$path]['featured_signup']) && !empty($plan['featured_signup']))
                    ) {
                        $unique_plans[$path] = $plan;
                    }
                }

                $plans_by_cycle[$cycle] = array_values($unique_plans);
            }

            $recruiter_contact_card_labels = [
                'one_contact' => __('Just one contact', 'senna-finance'),
                'extra_contacts' => __('Multiple contacts', 'senna-finance'),
                'ongoing_contacts' => __('Multiple contacts + Alerts', 'senna-finance'),
            ];

            $recruiter_contact_card_visuals = [
                'one_contact' => 'single-contact',
                'extra_contacts' => 'multiple-contacts',
                'ongoing_contacts' => 'ongoing-contacts',
            ];

            $build_recruiter_pricing_row = function (array $source, array $overrides = []) use (
                $recruiter_contact_title,
                $recruiter_contact_company,
                $recruiter_contact_fallback_photo,
                $recruiter_contact_company_logo_fallback
            ) {
                $title = trim((string) ($overrides['title'] ?? ($source['recruiter_title'] ?? '')));
                $company = trim((string) ($overrides['company'] ?? ($source['company'] ?? '')));
                $meta = trim((string) ($overrides['meta'] ?? ($source['role_title'] ?? '')));
                $avatar = trim((string) ($overrides['avatar'] ?? ($source['recruiter_photo'] ?? '')));
                $company_logo = trim((string) ($overrides['company_logo'] ?? ($source['company_logo'] ?? '')));

                if ($title === '') {
                    $title = $recruiter_contact_title;
                }

                if ($company === '') {
                    $company = $recruiter_contact_company;
                }

                if ($meta === '') {
                    $meta = __('Relevant hiring brief', 'senna-finance');
                }

                if ($avatar === '') {
                    $avatar = $recruiter_contact_fallback_photo;
                }

                if ($company_logo !== '') {
                    $company_logo = $this->normalize_company_logo_url($company_logo);
                }

                if ($company_logo === '') {
                    $company_logo = $recruiter_contact_company_logo_fallback;
                }

                return [
                    'title' => $title,
                    'company' => $company,
                    'meta' => $meta,
                    'avatar' => $avatar,
                    'company_logo' => $company_logo,
                    'badge' => trim((string) ($overrides['badge'] ?? '')),
                    'time' => trim((string) ($overrides['time'] ?? '')),
                    'badge_tone' => trim((string) ($overrides['badge_tone'] ?? '')),
                ];
            };

            $recruiter_contact_pricing_rows = [];
            if (!empty($recruiter_contact_context_item)) {
                $recruiter_contact_pricing_rows[] = $build_recruiter_pricing_row($recruiter_contact_context_item, [
                    'badge' => __('This role', 'senna-finance'),
                    'time' => __('Now', 'senna-finance'),
                    'badge_tone' => 'primary',
                ]);

                foreach ($this->get_crm_reddit_single_job_recommendations($recruiter_contact_context_item, 6) as $index => $recommendation_item) {
                    $unique_key = sanitize_title(
                        trim((string) ($recommendation_item['recruiter_title'] ?? '')) . '|' .
                        trim((string) ($recommendation_item['company'] ?? '')) . '|' .
                        trim((string) ($recommendation_item['role_title'] ?? ''))
                    );

                    if ($unique_key === '') {
                        continue;
                    }

                    $existing_keys = array_map(static function ($row) {
                        return sanitize_title($row['title'] . '|' . $row['company'] . '|' . $row['meta']);
                    }, $recruiter_contact_pricing_rows);

                    if (in_array($unique_key, $existing_keys, true)) {
                        continue;
                    }

                    $recruiter_contact_pricing_rows[] = $build_recruiter_pricing_row($recommendation_item, [
                        'badge' => $index === 0 ? __('Relevant', 'senna-finance') : __('Hiring now', 'senna-finance'),
                        'time' => $index === 0 ? __('Fresh', 'senna-finance') : __('Live', 'senna-finance'),
                        'badge_tone' => $index === 0 ? 'warm' : 'neutral',
                    ]);

                    if (count($recruiter_contact_pricing_rows) >= 3) {
                        break;
                    }
                }
            }

            if (empty($recruiter_contact_pricing_rows)) {
                $recruiter_contact_pricing_rows[] = $build_recruiter_pricing_row([], [
                    'badge' => __('This role', 'senna-finance'),
                    'time' => __('Now', 'senna-finance'),
                    'badge_tone' => 'primary',
                ]);
            }

            while (count($recruiter_contact_pricing_rows) < 3) {
                $fallback_index = count($recruiter_contact_pricing_rows);
                $fallback_badges = [
                    1 => [__('Relevant', 'senna-finance'), __('Fresh', 'senna-finance'), 'warm'],
                    2 => [__('Hiring now', 'senna-finance'), __('Live', 'senna-finance'), 'neutral'],
                ];
                $fallback = $recruiter_contact_pricing_rows[0];
                [$fallback['badge'], $fallback['time'], $fallback['badge_tone']] = $fallback_badges[$fallback_index] ?? [__('Relevant', 'senna-finance'), '', 'neutral'];
                $recruiter_contact_pricing_rows[] = $fallback;
            }

            $recruiter_contact_card_order = ['ongoing_contacts', 'extra_contacts', 'one_contact'];
            $recruiter_contact_pricing_cards = [];
            foreach ($recruiter_contact_card_order as $card_path) {
                foreach ($plans_by_cycle['monthly'] as $plan) {
                    if (($plan['signup_path'] ?? '') !== $card_path || empty($plan['recruiter_contact_pricing'])) {
                        continue;
                    }

                    $contact_limit = max(0, (int) ($plan['matches_per_week'] ?? 0));
                    if ($card_path === 'one_contact') {
                        $card_copy = '';
                        $card_recommendation = __('Best if you only want this recruiter', 'senna-finance');
                    } elseif ($card_path === 'extra_contacts') {
                        $card_copy = '';
                        $card_recommendation = __('Most popular for active job searches', 'senna-finance');
                    } else {
                        $card_copy = $contact_limit > 0
                            ? sprintf(__('Get up to %d contacts plus recruiter hiring alerts.', 'senna-finance'), $contact_limit)
                            : __('Get recruiter contacts plus recruiter hiring alerts.', 'senna-finance');
                        $card_recommendation = __('Best for ongoing recruiter visibility', 'senna-finance');
                    }

                    $recruiter_pricing_display_price = trim((string) ($plan['price'] ?? ''));
                    if ($card_path === 'one_contact') {
                        $recruiter_pricing_display_price = trim((string) ($plan['amount_label'] ?? $recruiter_pricing_display_price));
                        if ($recruiter_pricing_display_price !== '') {
                            $recruiter_pricing_display_price .= ' / ' . __('one time', 'senna-finance');
                        }
                    }

                    $recruiter_contact_pricing_cards[] = [
                        'path' => $card_path,
                        'label' => $recruiter_contact_card_labels[$card_path] ?? ($plan['name'] ?? ''),
                        'recommendation' => $this->translate_member_signup_feature($card_recommendation, $member_signup_locale),
                        'copy' => $this->translate_member_signup_feature($card_copy, $member_signup_locale),
                        'price' => $recruiter_pricing_display_price,
                        'amount_label' => trim((string) ($plan['amount_label'] ?? '')),
                        'visual' => $recruiter_contact_card_visuals[$card_path] ?? 'multiple-contacts',
                        'rows' => $recruiter_contact_pricing_rows,
                        'matches_per_week' => $contact_limit,
                    ];
                    break;
                }
            }

            $find_recruiter_pricing_card = static function (array $cards, array $preferred_paths) {
                foreach ($preferred_paths as $preferred_path) {
                    foreach ($cards as $card) {
                        if ((string) ($card['path'] ?? '') === $preferred_path) {
                            return $card;
                        }
                    }
                }

                return null;
            };

            $recruiter_contact_primary_card = $find_recruiter_pricing_card(
                $recruiter_contact_pricing_cards,
                ['ongoing_contacts', 'extra_contacts']
            );
            $recruiter_contact_secondary_card = $find_recruiter_pricing_card(
                $recruiter_contact_pricing_cards,
                ['one_contact']
            );

            $rendered_plans_by_cycle = $plans_by_cycle;
            if ($flow === 'recruiter_contact') {
                $rendered_plans_by_cycle = [
                    'monthly' => [],
                    'annual' => [],
                ];

                foreach (['monthly', 'annual'] as $cycle) {
                    foreach ($recruiter_contact_card_order as $card_path) {
                        foreach ((array) $plans_by_cycle[$cycle] as $plan) {
                            if (
                                (($plan['signup_path'] ?? '') === $card_path)
                                && !empty($plan['recruiter_contact_pricing'])
                            ) {
                                $rendered_plans_by_cycle[$cycle][] = $plan;
                                break;
                            }
                        }
                    }
                }
            }

            if (empty($plans_by_cycle['monthly']) && empty($plans_by_cycle['annual'])) {
                return '';
            }

            $has_annual_signup_plans = !empty($rendered_plans_by_cycle['annual']);

            $career_stages = [
                'daily_alerts' => __('Platform + Daily Finance Job Alerts', 'senna-finance'),
                'profile_guidance' => __('Career Assessment + Expert Guidance', 'senna-finance'),
            ];

            $account_types = [
                'platform' => $member_signup_i18n['account_platform'],
                'mentorship' => $member_signup_i18n['account_mentorship'],
                'all_access' => $member_signup_i18n['account_all_access'],
            ];

            ob_start();
            ?>
            <section class="sffc-member-signup<?php echo $flow === 'recruiter_contact' ? ' sffc-member-signup--recruiter-contact-flow' : ''; ?><?php echo $is_simple_flow ? ' sffc-member-signup--simple-flow' : ''; ?>" data-member-signup data-member-signup-variant="<?php echo esc_attr($flow === 'recruiter_contact' ? 'recruiter_contact' : ($is_simple_flow ? 'simple' : 'default')); ?>" lang="<?php echo esc_attr(str_replace('_', '-', $member_signup_locale)); ?>">
                <?php echo $this->render_member_signup_brand($is_simple_flow ? __('Finance Career Guidance', 'senna-finance') : __('Finance Career Guidance', 'senna-finance')); ?>

