                            <ol class="sffc-member-signup__steps" aria-label="<?php esc_attr_e('Signup progress', 'senna-finance'); ?>">
                                <li class="is-active"><?php esc_html_e('Create account', 'senna-finance'); ?></li>
                                <li><?php esc_html_e('Set preferences', 'senna-finance'); ?></li>
