                                    <?php echo do_shortcode((string) $plan['shortcode']); ?>
                                </div>
                            <?php endforeach; ?>
                        <?php endforeach; ?>
                    </div>
                </div>
            </section>
            <?php
            /*
             * MemberPress initialises pricing and checkout behaviour by scanning live
             * signup forms on page load. These checkout forms start in `[hidden]`
             * containers, so render one visually clipped form outside that tree.
             */
            $memberpress_init_shortcode = '';
            foreach (['monthly', 'annual'] as $cycle) {
                foreach ((array) $rendered_plans_by_cycle[$cycle] as $plan) {
                    $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                    if ($shortcode !== '') {
                        $memberpress_init_shortcode = $shortcode;
                        break 2;
                    }
                }
            }
            if ($presentation !== 'overlay' && $memberpress_init_shortcode !== '') : ?>
                <div class="sffc-mepr-init-decoy" aria-hidden="true" tabindex="-1">
                    <?php echo do_shortcode($memberpress_init_shortcode); ?>
                </div>
            <?php
            endif;
            return (string) ob_get_clean();
        }

        public function render_members_simple_pricing_signup($atts = [])
        {
            $atts = is_array($atts) ? $atts : [];
            $atts['mode'] = 'simple';

            return $this->render_members_pricing_signup($atts);
        }

        public function render_members_basic_signup($atts = [])
        {
            $atts = shortcode_atts([
                'headline' => __('Join Finance Career Guidance', 'senna-finance'),
                'subtitle' => '',
            ], $atts, 'sffc_members_basic_signup');

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/member-basic-signup.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/member-basic-signup.css') : SFFC_VERSION;
            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/member-basic-signup.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/member-basic-signup.js') : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-member-basic-signup',
                SFFC_PLUGIN_URL . 'assets/css/crm/member-basic-signup.css',
                [],
                $css_version
            );

            wp_enqueue_script(
                'sffc-member-basic-signup',
                SFFC_PLUGIN_URL . 'assets/js/crm/member-basic-signup.js',
                [],
                $js_version,
                true
            );

            $this->output_timezone_cookie_script();

            $plans = $this->get_basic_member_signup_plans_data();
            $memberpress_init_shortcode = '';
            foreach ($plans as $plan) {
                if (!empty($plan['shortcode'])) {
                    $memberpress_init_shortcode = (string) $plan['shortcode'];
                    break;
                }
            }

            if (empty($plans)) {
                return '';
            }

            $active_product_ids = [];
            $current_plan_id = '';
            if (is_user_logged_in()) {
                $active_product_ids = $this->get_active_memberpress_product_ids(get_current_user_id());
                foreach ($plans as $plan) {
                    $product_id = absint($plan['memberpress_product_id'] ?? 0);
                    if ($product_id && in_array($product_id, $active_product_ids, true)) {
                        $current_plan_id = (string) ($plan['id'] ?? '');
                        break;
                    }
                }
            }
            $last_plan = end($plans);
            reset($plans);
            $find_plan_id_by_path = static function (array $plans, array $paths, $fallback = '') {
                foreach ($plans as $plan) {
                    $signup_path = (string) ($plan['signup_path'] ?? '');
                    if (in_array($signup_path, $paths, true)) {
                        return (string) ($plan['id'] ?? $fallback);
                    }
                }

                return (string) $fallback;
            };
            $platform_plan_id = $find_plan_id_by_path($plans, ['platform'], (string) ($plans[0]['id'] ?? ''));
            $all_access_plan_id = $find_plan_id_by_path($plans, ['all_access'], (string) ($last_plan['id'] ?? $platform_plan_id));
            $default_plan_id = $current_plan_id !== '' ? $current_plan_id : (string) ($last_plan['id'] ?? '');
            $access_cards = [
                [
                    'title' => __('Hidden Roles + Daily Newsletter', 'senna-finance'),
                    'image' => 'https://media.joinsenna.com/2026/07/236053662-confident-what-i-do-attractive.jpeg',
                    'copy' => __('Hidden private equity and adjacent investing roles from recruiter networks, with daily job alerts in your inbox.', 'senna-finance'),
                    'plan_id' => $platform_plan_id,
                ],
                [
                    'title' => __('CV + LinkedIn Review', 'senna-finance'),
                    'image' => 'https://media.joinsenna.com/2026/07/204138220-smiling-young-indian-business-.jpeg',
                    'copy' => __('Expert feedback on your CV and LinkedIn profile so recruiters understand your value faster.', 'senna-finance'),
                    'plan_id' => $all_access_plan_id,
                ],
            ];

            wp_localize_script('sffc-member-basic-signup', 'sffcMemberBasicSignup', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'currencyNonce' => wp_create_nonce('sffc_member_basic_signup_currency'),
                'messages' => [
                    'selectPlan' => __('Please select an account type to continue.', 'senna-finance'),
                ],
            ]);

            ob_start();
            ?>
            <section class="sffc-basic-member-signup" data-sffc-basic-signup>
                <div class="sffc-basic-member-signup__masthead">
                    <?php echo $this->render_member_signup_brand(__('Join Finance Career Guidance', 'senna-finance'), false); ?>
                    <h1><?php esc_html_e('Finance Career Guidance', 'senna-finance'); ?></h1>
                </div>
                <div class="sffc-basic-member-signup__shell">
                    <div class="sffc-basic-member-signup__card">
                        <div class="sffc-basic-member-signup__field sffc-basic-member-signup__field--native-select">
                            <label for="sffc-basic-member-signup-plan"><?php esc_html_e('Choose your membership', 'senna-finance'); ?></label>
                            <p class="sffc-basic-member-signup__selector-copy"><?php esc_html_e('Connect with recruiters, find opportunities and get expert help', 'senna-finance'); ?></p>
                            <div class="sffc-basic-member-signup__select-wrap">
                                <select id="sffc-basic-member-signup-plan" class="sffc-basic-member-signup__select" data-sffc-basic-signup-select>
                                    <option value="" <?php selected('', $default_plan_id); ?>><?php esc_html_e('Please select account type', 'senna-finance'); ?></option>
                                    <?php foreach ($plans as $plan) : ?>
                                        <?php
                                        $plan_id = (string) $plan['id'];
                                        $is_current_plan = $current_plan_id !== '' && $plan_id === $current_plan_id;
                                        $is_default_plan = $default_plan_id !== '' && $plan_id === $default_plan_id;
                                        $option_label = (string) $plan['option_label'];
                                        if ($is_current_plan) {
                                            $option_label = sprintf(
                                                /* translators: %s: membership plan label. */
                                                __('%s (Current plan)', 'senna-finance'),
                                                $option_label
                                            );
                                        }
                                        ?>
                                        <option value="<?php echo esc_attr($plan_id); ?>" data-sffc-basic-signup-option="<?php echo esc_attr($plan_id); ?>" data-sffc-basic-signup-current="<?php echo $is_current_plan ? '1' : '0'; ?>" data-sffc-basic-signup-default="<?php echo $is_default_plan ? '1' : '0'; ?>" <?php selected($plan_id, $default_plan_id); ?>>
                                            <?php echo esc_html($option_label); ?>
                                        </option>
                                    <?php endforeach; ?>
                                </select>
                                <span class="sffc-basic-member-signup__select-chevron" aria-hidden="true">
                                    <svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
                                </span>
                            </div>
                        </div>

                        <div class="sffc-basic-member-signup__plan-details" data-sffc-basic-signup-details hidden>
                            <?php foreach ($plans as $plan) : ?>
                                <?php
                                $plan_id = (string) $plan['id'];
                                $is_current_plan = $current_plan_id !== '' && $plan_id === $current_plan_id;
                                $is_default_plan = $default_plan_id !== '' && $plan_id === $default_plan_id;
                                ?>
                                <article class="sffc-basic-member-signup__plan-detail<?php echo $is_current_plan ? ' is-current-plan' : ''; ?>" data-sffc-basic-signup-detail="<?php echo esc_attr($plan_id); ?>" <?php echo $is_default_plan ? '' : 'hidden'; ?>>
                                    <div class="sffc-basic-member-signup__plan-meta">
                                        <strong><?php echo esc_html((string) $plan['name']); ?></strong>
                                        <?php if ($is_current_plan) : ?>
                                            <em class="sffc-basic-member-signup__current-badge"><?php esc_html_e('Current plan', 'senna-finance'); ?></em>
                                        <?php endif; ?>
                                        <?php if ($plan['price'] !== '') : ?>
                                            <span data-sffc-basic-signup-price="<?php echo esc_attr($plan_id); ?>"><?php echo esc_html((string) $plan['price']); ?></span>
                                        <?php endif; ?>
                                    </div>
                                    <?php if ($plan['tagline'] !== '') : ?>
                                        <p><?php echo esc_html((string) $plan['tagline']); ?></p>
                                    <?php endif; ?>
                                    <?php if (!empty($plan['features'])) : ?>
                                        <ul>
                                            <?php foreach ($plan['features'] as $feature) : ?>
                                                <li><?php echo esc_html((string) $feature); ?></li>
                                            <?php endforeach; ?>
                                        </ul>
                                    <?php endif; ?>
                                </article>
                            <?php endforeach; ?>
                        </div>

                        <div class="sffc-basic-member-signup__forms" data-sffc-basic-signup-forms <?php echo $default_plan_id !== '' ? '' : 'hidden'; ?>>
                            <?php foreach ($plans as $plan) : ?>
                                <?php
                                $plan_id = (string) $plan['id'];
                                $is_current_plan = $current_plan_id !== '' && $plan_id === $current_plan_id;
                                $is_default_plan = $default_plan_id !== '' && $plan_id === $default_plan_id;
                                ?>
                                <div class="sffc-basic-member-signup__memberpress<?php echo $is_current_plan ? ' is-current-plan' : ''; ?>" data-sffc-basic-signup-panel="<?php echo esc_attr($plan_id); ?>" <?php echo $is_default_plan ? '' : 'hidden'; ?>>
                                    <?php echo do_shortcode((string) $plan['shortcode']); ?>
                                </div>
                            <?php endforeach; ?>
                        </div>
                    </div>
                </div>
            </section>
            <?php if ($memberpress_init_shortcode !== '') : ?>
                <div class="sffc-mepr-init-decoy" aria-hidden="true" tabindex="-1">
                    <?php echo do_shortcode($memberpress_init_shortcode); ?>
                </div>
            <?php endif; ?>
            <?php

            return (string) ob_get_clean();
        }

        public function render_crm_jobs_member_signup($atts = [])
        {
            [$member_signup_locale, $member_signup_i18n] = $this->enqueue_member_pricing_signup_assets();

            $atts = shortcode_atts([
                'jobs_post_id' => 0,
                'headline' => '',
                'subtitle' => '',
                'presentation' => 'page',
            ], $atts, 'sffc_crm_jobs_member_signup');
            $presentation = sanitize_key((string) $atts['presentation']);
            if ($presentation !== 'overlay') {
                $presentation = 'page';
            }

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            $job_item = $jobs_post_id > 0 ? $this->get_cached_cv_match_job_posts_item($jobs_post_id) : null;
            $job_title = '';

            if (!empty($job_item)) {
                $job_title = trim((string) ($job_item['role_title'] ?? ''));
            }
            if ($job_title === '' && $jobs_post_id > 0) {
                $job_title = trim((string) get_the_title($jobs_post_id));
            }
            if ($job_title === '' && !empty($atts['headline'])) {
                $job_title = sanitize_text_field((string) $atts['headline']);
            }
            if ($job_title === '') {
                $job_title = __('Finance Careers, Expert Support & More', 'senna-finance');
            }

            $subtitle = trim((string) $atts['subtitle']);
            if ($subtitle === '') {
                $subtitle = '';
            }

            $apply_url = '';
            if (!empty($job_item['apply_url'])) {
                $apply_url = esc_url_raw((string) $job_item['apply_url']);
            }
            if ($apply_url === '' && $jobs_post_id > 0) {
                foreach (['_application_url', 'newapplicationLink', 'applicationLink', 'sffc_application_url', '_sffc_job_application_url'] as $application_meta_key) {
                    $apply_url = trim((string) get_post_meta($jobs_post_id, $application_meta_key, true));
                    if ($apply_url !== '') {
                        $apply_url = esc_url_raw($apply_url);
                        break;
                    }
                }
            }
            $apply_via_email = $this->is_email_application_url($apply_url);
            $apply_email_value = '';
            if ($apply_via_email && $apply_url !== '') {
                $apply_email_value = preg_replace('/^mailto:/i', '', (string) $apply_url);
                $apply_email_value = strtok((string) $apply_email_value, '?');
                $apply_email_value = sanitize_email((string) $apply_email_value);
            }

            $help_url = home_url('/terminal/?tab=discover');
            $plans = array_values((array) $this->get_subscription_plans());
            $plans_by_cycle = [
                'monthly' => [],
                'annual' => [],
            ];
            $normalize_signup_price_label = static function ($display_price) {
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $amount_label = $display_price;
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', (string) $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                }

                return [$display_price, $amount_label];
            };
            $legacy_signup_fallback_index = 0;

            foreach ($plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                if (!empty($plan['is_annual'])) {
                    continue;
                }
                if ($name === '' || $shortcode === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];
                $features = array_map(function ($feature) use ($member_signup_locale) {
                    return $this->translate_member_signup_feature($feature, $member_signup_locale);
                }, $features);

                $display_price = $this->format_plan_price_amount($plan) ?: trim((string) ($plan['price'] ?? ''));
                [$display_price, $amount_label] = $normalize_signup_price_label($display_price);
                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim($name . ' ' . (string) ($plan['tagline'] ?? '') . ' ' . (string) ($plan['audience'] ?? ''))
                );
                $signup_path = $signup_path_meta['path'];
                if (empty($plan['signup_path_configured']) && !$signup_path_meta['configured']) {
                    $path_hint = strtolower($name . ' ' . (string) ($plan['tagline'] ?? '') . ' ' . (string) ($plan['audience'] ?? ''));
                    if (preg_match('/\b(cv|resume|review|mentorship|support)\b/', $path_hint)) {
                        $signup_path = 'mentorship';
                    } elseif (preg_match('/\b(platform|access only|basic)\b/', $path_hint)) {
                        $signup_path = 'platform';
                    } else {
                        $signup_path = $legacy_signup_fallback_index === 0 ? 'platform' : 'mentorship';
                    }
                }
                $legacy_signup_fallback_index++;
                $plan_slug = sanitize_key((string) ($plan['slug'] ?? sanitize_title($name)));
                $monthly_entry = [
                    'id' => sanitize_key($plan_slug . '-monthly'),
                    'name' => $this->translate_member_signup_plan_name($name, $member_signup_locale),
                    'tagline' => $this->translate_member_signup_feature(trim((string) ($plan['tagline'] ?? $plan['audience'] ?? '')), $member_signup_locale),
                    'price' => $display_price,
                    'amount_label' => $amount_label,
                    'billing_cycle' => $member_signup_i18n['billing_monthly'],
                    'features' => array_slice($features, 0, 5),
                    'shortcode' => $shortcode,
                    'cycle' => 'monthly',
                    'matches_per_week' => max(0, (int) ($plan['matches_per_week'] ?? 0)),
                    'signup_path' => $signup_path,
                    'featured_signup' => !empty($plan['featured_signup']),
                    'recruiter_contact_pricing' => !empty($plan['recruiter_contact_pricing']),
                ];
                $plans_by_cycle['monthly'][] = $monthly_entry;

                $annual_shortcode = trim((string) ($plan['annual_shortcode'] ?? ''));
                if ($annual_shortcode !== '') {
                    $annual_plan = $plan;
                    $annual_display_price = '';
                    if (!empty($plan['annual_price_amount'])) {
                        $annual_plan['price_amount'] = (float) $plan['annual_price_amount'];
                        $annual_plan['billing_cycle'] = trim((string) ($plan['annual_billing_cycle'] ?? '')) ?: __('per year', 'senna-finance');
                        $annual_display_price = $this->format_plan_price_amount($annual_plan);
                    }
                    $annual_display_price = $annual_display_price ?: trim((string) ($plan['annual_price'] ?? ''));
                    if ($annual_display_price === '') {
                        $annual_display_price = $display_price;
                    }
                    [$annual_display_price, $annual_amount_label] = $normalize_signup_price_label($annual_display_price);

                    $annual_entry = $monthly_entry;
                    $annual_entry['id'] = sanitize_key($plan_slug . '-annual');
                    $annual_entry['price'] = $annual_display_price;
                    $annual_entry['amount_label'] = $annual_amount_label;
                    $annual_entry['billing_cycle'] = $member_signup_i18n['billing_annual'];
                    $annual_entry['shortcode'] = $annual_shortcode;
                    $annual_entry['cycle'] = 'annual';
                    $plans_by_cycle['annual'][] = $annual_entry;
                }
            }

            foreach (['monthly', 'annual'] as $cycle) {
                $has_all_access = false;
                foreach ($plans_by_cycle[$cycle] as $plan) {
                    if (($plan['signup_path'] ?? '') === 'all_access') {
                        $has_all_access = true;
                        break;
                    }
                }

                if (!$has_all_access) {
                    $alias_candidate = null;
                    foreach ($plans_by_cycle[$cycle] as $plan) {
                        if (($plan['signup_path'] ?? '') === 'mentorship') {
                            if (
                                $alias_candidate === null
                                || (float) ($plan['price_amount'] ?? 0) > (float) ($alias_candidate['price_amount'] ?? 0)
                            ) {
                                $alias_candidate = $plan;
                            }
                        }
                    }

                    if ($alias_candidate === null) {
                        $highest_amount = -1;
                        foreach ($plans_by_cycle[$cycle] as $plan) {
                            $amount = (float) ($plan['price_amount'] ?? 0);
                            if ($amount > $highest_amount) {
                                $highest_amount = $amount;
                                $alias_candidate = $plan;
                            }
                        }
                    }

                    if ($alias_candidate !== null) {
                        $all_access_alias = $alias_candidate;
                        $all_access_alias['id'] = sanitize_key((string) ($alias_candidate['id'] ?? '') . '-all-access');
                        $all_access_alias['signup_path'] = 'all_access';
                        $all_access_alias['featured_signup'] = !empty($all_access_alias['featured_signup']);
                        $plans_by_cycle[$cycle][] = $all_access_alias;
                    }
                }

                $unique_plans = [];
                foreach ($plans_by_cycle[$cycle] as $plan) {
                    $path = (string) ($plan['signup_path'] ?? 'platform');
                    if (
                        !isset($unique_plans[$path])
                        || (empty($unique_plans[$path]['featured_signup']) && !empty($plan['featured_signup']))
                    ) {
                        $unique_plans[$path] = $plan;
                    }
                }

                $plans_by_cycle[$cycle] = array_values($unique_plans);
            }

            $has_annual_signup_plans = !empty($plans_by_cycle['annual']);
            $job_description_source = '';
            if ($jobs_post_id > 0) {
                $job_description_source = trim((string) get_post_meta($jobs_post_id, 'jobDescription', true));
                if ($job_description_source === '') {
                    $job_description_source = trim((string) get_post_meta($jobs_post_id, 'sffc_job_description', true));
                }
                if ($job_description_source === '') {
                    $job_post = get_post($jobs_post_id);
                    if ($job_post instanceof WP_Post && $job_post->post_type === 'jobs' && !empty($job_post->post_content)) {
                        $job_description_source = (string) $job_post->post_content;
                    }
                }
            }
            if ($job_description_source === '' && !empty($job_item)) {
                $job_description_source = trim((string) $this->build_cv_match_job_dashboard_jd_text((array) $job_item));
            }
            if ($job_description_source === '') {
                $queried_job_post = get_queried_object();
                if ($queried_job_post instanceof WP_Post && !empty($queried_job_post->post_content) && $queried_job_post->post_type !== 'page') {
                    $job_description_source = (string) $queried_job_post->post_content;
                }
            }
            $job_description_html = '';
            if ($job_description_source !== '') {
                $job_description_has_html = $job_description_source !== wp_strip_all_tags($job_description_source);
                $job_description_html = wp_kses_post(
                    $job_description_has_html ? $job_description_source : wpautop($job_description_source)
                );
            }
            $route_recruiter_name = trim((string) ($job_item['recruiter_name'] ?? __('Recruiter', 'senna-finance')));
            $route_recruiter_title = trim((string) ($job_item['recruiter_title'] ?? __('Recruiter', 'senna-finance')));
            $route_company_name = trim((string) ($job_item['company'] ?? __('Employer', 'senna-finance')));
            $route_recruiter_photo = trim((string) ($job_item['recruiter_photo'] ?? ''));
            $route_recruiter_email = sanitize_email((string) ($job_item['recruiter_email'] ?? ''));
            $route_recruiter_linkedin = esc_url_raw((string) ($job_item['recruiter_linkedin'] ?? ''));
            $route_masked_recruiter_email = $this->mask_recruiter_email_for_display($route_recruiter_email);
            $route_recruiter_initial_source = $route_recruiter_name !== ''
                ? $route_recruiter_name
                : trim((string) ($job_item['company'] ?? ''));
            $route_recruiter_initial = strtoupper(function_exists('mb_substr')
                ? mb_substr($route_recruiter_initial_source !== '' ? $route_recruiter_initial_source : 'R', 0, 1)
                : substr($route_recruiter_initial_source !== '' ? $route_recruiter_initial_source : 'R', 0, 1));
            $is_logged_in_member = is_user_logged_in();
            $has_direct_recruiter_contact_access = $is_logged_in_member
                && $route_recruiter_email !== ''
                && $this->current_user_has_recruiter_contact_credit_access($route_recruiter_email);
            $recruiter_contact_membership_url = home_url('/contacts/');
            if ($jobs_post_id > 0) {
                $recruiter_contact_membership_url = add_query_arg([
                    'sffc_recruiter_contact_job_id' => $jobs_post_id,
                ], $recruiter_contact_membership_url);
            }

            ob_start();
            ?>
            <section class="sffc-member-signup sffc-member-signup--job<?php echo $presentation === 'overlay' ? ' sffc-member-signup--overlay-panel' : ''; ?>" data-member-signup data-member-signup-variant="job" data-member-signup-help-url="<?php echo esc_url($help_url); ?>" data-member-signup-membership-url="<?php echo esc_url($recruiter_contact_membership_url); ?>" data-member-signup-job-id="<?php echo esc_attr((string) $jobs_post_id); ?>" data-member-signup-job-title="<?php echo esc_attr($job_title); ?>" lang="<?php echo esc_attr(str_replace('_', '-', $member_signup_locale)); ?>">
                <?php echo $this->render_member_signup_brand(__('Finance Career Guidance', 'senna-finance')); ?>

                <div class="sffc-member-signup__shell">
                    <h1><?php echo esc_html($job_title); ?></h1>
                    <p class="sffc-member-signup__subtitle"><?php echo esc_html($subtitle); ?></p>

                    <div class="sffc-member-signup__card" data-member-signup-card>
                        <div class="sffc-member-signup__login-state" data-member-signup-login hidden>
                            <h2><?php echo esc_html($member_signup_i18n['existing_account_title']); ?></h2>
                            <p><?php echo esc_html($member_signup_i18n['existing_account_copy']); ?></p>
                            <a href="<?php echo esc_url(home_url('/login/')); ?>"><?php echo esc_html($member_signup_i18n['log_in']); ?></a>
                        </div>

                        <form class="sffc-member-signup__form" data-member-signup-form novalidate<?php echo $is_logged_in_member ? ' hidden' : ''; ?>>
                            <div class="sffc-member-signup__field">
