        private function ensure_crm_apply_chat_models()
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-conversation.php';
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-message.php';
        }

        public function maybe_create_crm_apply_chat_memory_table()
        {
            global $wpdb;

            $installed_version = (string) get_option('sffc_crm_apply_chat_memory_schema_version', '');
            if ($installed_version === '1') {
                return;
            }

            require_once ABSPATH . 'wp-admin/includes/upgrade.php';

            $table = $wpdb->prefix . 'sffc_crm_apply_chat_memory';
            $charset_collate = $wpdb->get_charset_collate();

            $sql = "CREATE TABLE {$table} (
                id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
                user_id bigint(20) unsigned NOT NULL,
                memory_payload longtext DEFAULT NULL,
                last_conversation_id bigint(20) unsigned DEFAULT NULL,
                last_flow varchar(80) DEFAULT '',
                last_path varchar(120) DEFAULT '',
                created_at datetime DEFAULT CURRENT_TIMESTAMP,
                updated_at datetime DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY  (id),
                UNIQUE KEY user_id (user_id),
                KEY last_conversation_id (last_conversation_id)
            ) {$charset_collate};";

            dbDelta($sql);
            update_option('sffc_crm_apply_chat_memory_schema_version', '1', false);
        }

        private function get_crm_apply_chat_current_user_first_name()
        {
            if (!is_user_logged_in()) {
                return '';
            }

            $user = wp_get_current_user();
            if (!$user || empty($user->ID)) {
                return '';
            }

            $first_name = trim((string) get_user_meta((int) $user->ID, 'first_name', true));
            if ($first_name !== '') {
                return sanitize_text_field($first_name);
            }

            $display_name = trim((string) ($user->display_name ?? ''));
            if ($display_name === '') {
                return '';
            }

            $parts = preg_split('/\s+/', $display_name);
            return sanitize_text_field((string) ($parts[0] ?? ''));
        }

        private function sanitize_crm_apply_chat_memory_value($value)
        {
            if (is_bool($value) || is_int($value) || is_float($value) || $value === null) {
                return $value;
            }

            if (is_string($value)) {
                return sanitize_text_field($value);
            }

            if (!is_array($value)) {
                return '';
            }

            $clean = [];
            foreach ($value as $key => $item) {
                $clean_key = is_string($key) ? sanitize_key($key) : $key;
                $clean[$clean_key] = $this->sanitize_crm_apply_chat_memory_value($item);
            }

            return $clean;
        }

        private function normalize_crm_apply_chat_memory_payload($payload)
        {
            if (is_string($payload)) {
                $decoded = json_decode(wp_unslash($payload), true);
                $payload = is_array($decoded) ? $decoded : [];
            }

            if (!is_array($payload)) {
                $payload = [];
            }

            $defaults = [
                'version' => 1,
                'has_history' => false,
                'last_flow' => '',
                'last_path' => '',
                'last_prompt_state' => '',
                'last_role_title' => '',
                'preferred_ui_language' => '',
                'preferred_location' => '',
                'global_visa_status' => '',
                'cv_state' => '',
                'last_action' => '',
                'target_functions' => [],
                'target_sectors' => [],
                'target_locations' => [],
                'future_target_locations' => [],
                'excluded_target_locations' => [],
                'excluded_target_functions' => [],
                'excluded_target_sectors' => [],
                'target_skills' => [],
                'salary_priorities' => [],
                'family_constraints' => [],
                'work_style_preferences' => [],
                'timing_notes' => [],
                'saved_role_titles' => [],
                'rejected_role_titles' => [],
                'saved_company_names' => [],
                'rejected_company_names' => [],
                'recent_topics' => [],
                'answered_questions' => [],
                'location_visa_requirements' => [],
                'updated_at' => '',
            ];

            $payload = array_merge($defaults, $payload);
            $payload = $this->sanitize_crm_apply_chat_memory_value($payload);

            foreach ([
                'target_functions',
                'target_sectors',
                'target_locations',
                'future_target_locations',
                'excluded_target_locations',
                'excluded_target_functions',
                'excluded_target_sectors',
                'target_skills',
                'salary_priorities',
                'family_constraints',
                'work_style_preferences',
                'timing_notes',
                'saved_role_titles',
                'rejected_role_titles',
                'saved_company_names',
                'rejected_company_names',
                'recent_topics',
                'answered_questions',
            ] as $list_key) {
                $values = is_array($payload[$list_key]) ? $payload[$list_key] : [];
                $values = array_values(array_filter(array_map('sanitize_text_field', $values)));
                $payload[$list_key] = array_values(array_unique($values));
            }

            $visa_map = is_array($payload['location_visa_requirements']) ? $payload['location_visa_requirements'] : [];
            $clean_visa_map = [];
            foreach ($visa_map as $location_key => $status) {
                $clean_key = sanitize_key((string) $location_key);
                $clean_status = sanitize_text_field((string) $status);
                if ($clean_key === '' || $clean_status === '') {
                    continue;
                }
                $clean_visa_map[$clean_key] = $clean_status;
            }
            $payload['location_visa_requirements'] = $clean_visa_map;
            $payload['has_history'] = !empty($payload['has_history']);
            $payload['version'] = 1;

            return $payload;
        }

        private function get_crm_apply_chat_profile_preferences($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            return [
                'target_roles' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_target_roles', true) ?: []),
                'target_locations' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_target_locations', true) ?: []),
                'target_sectors' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_target_sectors', true) ?: []),
                'excluded_roles' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_roles', true) ?: []),
                'excluded_locations' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_locations', true) ?: []),
                'excluded_sectors' => $this->normalize_crm_reddit_profile_tag_values(get_user_meta($user_id, 'sffc_crm_excluded_sectors', true) ?: []),
                'access_choice' => sanitize_key((string) get_user_meta($user_id, 'sffc_crm_editorial_community_access_choice', true)),
                'ideal_role' => sanitize_text_field((string) get_user_meta($user_id, 'sffc_crm_editorial_community_ideal_role', true)),
                'role_interest' => sanitize_key((string) get_user_meta($user_id, 'sffc_signup_seniority_level', true)),
                'community_onboarding_seen' => get_user_meta($user_id, 'sffc_crm_editorial_community_onboarding_seen', true) === '1',
            ];
        }

        private function build_crm_apply_chat_resume_context($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            $documents = $this->get_crm_reddit_resume_uploads($user_id, 24);
            $active_upload_id = absint((string) get_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), true));
            $active_upload = $active_upload_id > 0 ? $this->get_crm_reddit_resume_upload($user_id, $active_upload_id) : null;
            $source_preference = sanitize_key((string) get_user_meta($user_id, $this->get_crm_reddit_resume_source_preference_meta_key(), true));
            $pasted_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) get_user_meta($user_id, $this->get_crm_reddit_pasted_cv_meta_key(), true));
            if ((empty($active_upload) || empty($active_upload['id'])) && !empty($documents[0]['id'])) {
                $active_upload_id = (int) $documents[0]['id'];
                $active_upload = $this->get_crm_reddit_resume_upload($user_id, $active_upload_id);
            }

            $context = [
                'has_cv' => !empty($resume_payload['has_cv']),
                'cv_text' => (string) ($resume_payload['cv_text'] ?? ''),
                'source' => (string) ($resume_payload['source'] ?? ''),
                'source_preference' => $source_preference,
                'saved_count' => count($documents),
                'cv_options' => $this->get_crm_reddit_dashboard_outreach_cv_options($user_id, $resume_payload),
                'active_upload_id' => $active_upload_id,
                'active_file_name' => '',
                'active_file_type' => '',
                'active_file_url' => '',
                'pasted_profile_available' => $pasted_cv_text !== '',
            ];

            if (!empty($active_upload['file_name'])) {
                $context['active_file_name'] = (string) $active_upload['file_name'];
                $context['active_file_type'] = strtolower((string) ($active_upload['file_type'] ?? ''));
                $context['active_file_url'] = $this->get_crm_reddit_resume_upload_public_url((string) ($active_upload['file_path'] ?? ''));
            }

            return $context;
        }

        private function get_crm_apply_chat_user_memory($user_id)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $table = $wpdb->prefix . 'sffc_crm_apply_chat_memory';
            $row = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT memory_payload FROM {$table} WHERE user_id = %d LIMIT 1",
                    $user_id
                ),
                ARRAY_A
            );

            if (empty($row['memory_payload'])) {
                return [];
            }

            return $this->normalize_crm_apply_chat_memory_payload((string) $row['memory_payload']);
        }

        private function save_crm_apply_chat_user_memory($user_id, array $payload, $conversation_id = 0)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return false;
            }

            $this->maybe_create_crm_apply_chat_memory_table();

            $table = $wpdb->prefix . 'sffc_crm_apply_chat_memory';
            $normalized = $this->normalize_crm_apply_chat_memory_payload($payload);
            $normalized['has_history'] = true;
            $normalized['updated_at'] = current_time('mysql');

            $data = [
                'user_id' => $user_id,
                'memory_payload' => wp_json_encode($normalized, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
                'last_conversation_id' => $conversation_id > 0 ? (int) $conversation_id : null,
                'last_flow' => sanitize_key((string) ($normalized['last_flow'] ?? '')),
                'last_path' => sanitize_key((string) ($normalized['last_path'] ?? '')),
                'updated_at' => current_time('mysql'),
            ];

            $existing_id = (int) $wpdb->get_var(
                $wpdb->prepare(
                    "SELECT id FROM {$table} WHERE user_id = %d LIMIT 1",
                    $user_id
                )
            );

            if ($existing_id > 0) {
                return false !== $wpdb->update(
                    $table,
                    $data,
                    ['id' => $existing_id],
                    ['%d', '%s', '%d', '%s', '%s', '%s'],
                    ['%d']
                );
            }

            $data['created_at'] = current_time('mysql');

            return false !== $wpdb->insert(
                $table,
                $data,
                ['%d', '%s', '%d', '%s', '%s', '%s', '%s']
            );
        }

        private function normalize_crm_apply_chat_session_token($token)
        {
            $token = strtolower(trim((string) $token));
            $token = preg_replace('/[^a-z0-9_-]+/', '', $token);
            if ($token === '') {
                return '';
            }

            return substr($token, 0, 80);
        }

        private function get_crm_apply_chat_thread_id($session_token)
        {
            return 'apply_chat:' . $this->normalize_crm_apply_chat_session_token($session_token);
        }

        private function get_crm_apply_chat_presence_transient_key($conversation_id)
        {
            return 'sffc_apply_chat_live_' . (int) $conversation_id;
        }

        private function get_crm_apply_chat_presence_state($conversation_id)
        {
            $conversation_id = (int) $conversation_id;
            if ($conversation_id <= 0) {
                return [
                    'is_live' => false,
                    'page_visible' => false,
                    'last_seen_at' => '',
                    'page_url' => '',
                    'active_path' => '',
                    'prompt_state' => '',
                ];
            }

            $state = get_transient($this->get_crm_apply_chat_presence_transient_key($conversation_id));
            if (!is_array($state)) {
                return [
                    'is_live' => false,
                    'page_visible' => false,
                    'last_seen_at' => '',
                    'page_url' => '',
                    'active_path' => '',
                    'prompt_state' => '',
                ];
            }

            $last_seen_at = sanitize_text_field((string) ($state['last_seen_at'] ?? ''));
            $last_seen_ts = $last_seen_at !== '' ? strtotime($last_seen_at) : 0;
            $is_live = $last_seen_ts > 0 && (time() - $last_seen_ts) <= 95;

            return [
                'is_live' => $is_live,
                'page_visible' => !empty($state['page_visible']),
                'last_seen_at' => $last_seen_at,
                'page_url' => esc_url_raw((string) ($state['page_url'] ?? '')),
                'active_path' => sanitize_key((string) ($state['active_path'] ?? '')),
                'prompt_state' => sanitize_key((string) ($state['prompt_state'] ?? '')),
            ];
        }

        private function touch_crm_apply_chat_presence($conversation_id, array $state = [])
        {
            $conversation_id = (int) $conversation_id;
            if ($conversation_id <= 0) {
                return;
            }

            $payload = [
                'last_seen_at' => current_time('mysql'),
                'page_visible' => !empty($state['page_visible']),
                'page_url' => esc_url_raw((string) ($state['page_url'] ?? '')),
                'active_path' => sanitize_key((string) ($state['active_path'] ?? '')),
                'prompt_state' => sanitize_key((string) ($state['prompt_state'] ?? '')),
            ];

            set_transient($this->get_crm_apply_chat_presence_transient_key($conversation_id), $payload, 10 * MINUTE_IN_SECONDS);

            $conversation = $this->get_crm_apply_chat_conversation($conversation_id);
            if (!empty($conversation['id']) && sanitize_key((string) ($conversation['status'] ?? 'active')) === 'archived' && !$this->crm_apply_chat_conversation_needs_attention($conversation)) {
                $this->set_crm_apply_chat_conversation_status($conversation_id, 'active');
            }
        }

        private function get_crm_apply_chat_labels(array $conversation)
        {
            $raw = trim((string) ($conversation['labels'] ?? ''));
            if ($raw === '') {
                return [];
            }

            $labels = array_map('trim', explode(',', $raw));
            $labels = array_map('sanitize_key', $labels);
            $labels = array_values(array_filter(array_unique($labels)));

            return $labels;
        }

        private function crm_apply_chat_conversation_has_label(array $conversation, $label)
        {
            $label = sanitize_key((string) $label);
            if ($label === '') {
                return false;
            }

            return in_array($label, $this->get_crm_apply_chat_labels($conversation), true);
        }

        private function crm_apply_chat_conversation_needs_attention(array $conversation)
        {
            $status = sanitize_key((string) ($conversation['status'] ?? 'active'));
            $has_unread = (int) ($conversation['unread_count'] ?? 0) > 0;
            $takeover = $status === 'human_takeover';
            $is_priority = $this->crm_apply_chat_conversation_has_label($conversation, 'priority_now');

            return $is_priority || $takeover || $has_unread;
        }

        private function update_crm_apply_chat_conversation_labels($conversation_id, array $labels)
        {
            global $wpdb;

            $conversation_id = (int) $conversation_id;
            if ($conversation_id <= 0) {
                return false;
            }

            $clean_labels = array_map('sanitize_key', $labels);
            $clean_labels = array_values(array_filter(array_unique($clean_labels)));
            if (!in_array('apply_chat', $clean_labels, true)) {
                $clean_labels[] = 'apply_chat';
            }

            return false !== $wpdb->update(
                $wpdb->prefix . 'sffc_crm_conversations',
                ['labels' => implode(',', $clean_labels)],
                ['id' => $conversation_id],
                ['%s'],
                ['%d']
            );
        }

        private function set_crm_apply_chat_conversation_label($conversation_id, $label, $enabled = true)
        {
            $conversation_id = (int) $conversation_id;
            $label = sanitize_key((string) $label);
            if ($conversation_id <= 0 || $label === '') {
                return false;
            }

            $conversation = $this->get_crm_apply_chat_conversation($conversation_id);
            if (empty($conversation['id'])) {
                return false;
            }

            $labels = $this->get_crm_apply_chat_labels($conversation);
            $labels = array_values(array_filter($labels, static function ($item) use ($label) {
                return $item !== $label;
            }));
            if ($enabled) {
                $labels[] = $label;
            }

            return $this->update_crm_apply_chat_conversation_labels($conversation_id, $labels);
        }

        private function get_crm_apply_chat_conversation($conversation_id)
        {
            global $wpdb;

            $conversation_id = (int) $conversation_id;
            if ($conversation_id <= 0) {
                return [];
            }

            return (array) $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT * FROM {$wpdb->prefix}sffc_crm_conversations WHERE id = %d LIMIT 1",
                    $conversation_id
                ),
                ARRAY_A
            );
        }

        private function maintain_crm_apply_chat_lifecycle()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $delete_before = gmdate('Y-m-d H:i:s', time() - (90 * DAY_IN_SECONDS));
            $conversations = (array) $wpdb->get_results(
                "SELECT *
                 FROM {$table}
                 WHERE FIND_IN_SET('apply_chat', labels)",
                ARRAY_A
            );

            foreach ($conversations as $conversation) {
                $conversation_id = (int) ($conversation['id'] ?? 0);
                if ($conversation_id <= 0) {
                    continue;
                }

                $status = sanitize_key((string) ($conversation['status'] ?? 'active'));
                $presence = $this->get_crm_apply_chat_presence_state($conversation_id);
                $is_live = !empty($presence['is_live']);
                $needs_attention = $this->crm_apply_chat_conversation_needs_attention($conversation);

                if ($status === 'archived') {
                    if ($is_live && !$needs_attention) {
                        $this->set_crm_apply_chat_conversation_status($conversation_id, 'active');
                    }
                    continue;
                }

                if (!$is_live && !$needs_attention) {
                    $this->set_crm_apply_chat_conversation_status($conversation_id, 'archived');
                }
            }

            $stale_ids = (array) $wpdb->get_col(
                $wpdb->prepare(
                    "SELECT id
                     FROM {$table}
                     WHERE FIND_IN_SET('apply_chat', labels)
                       AND status = 'archived'
                       AND COALESCE(updated_at, last_message_at, created_at) < %s",
                    $delete_before
                )
            );

            if (!empty($stale_ids)) {
                $message_table = $wpdb->prefix . 'sffc_crm_messages';
                foreach ($stale_ids as $conversation_id) {
                    $conversation_id = (int) $conversation_id;
                    if ($conversation_id <= 0) {
                        continue;
                    }
                    $wpdb->delete($message_table, ['conversation_id' => $conversation_id], ['%d']);
                    $wpdb->delete($table, ['id' => $conversation_id], ['%d']);
                    delete_transient($this->get_crm_apply_chat_presence_transient_key($conversation_id));
                }
            }
        }

        private function get_crm_apply_chat_queue_for_conversation(array $conversation, array $presence = [])
        {
            $status = sanitize_key((string) ($conversation['status'] ?? 'active'));
            $is_live = !empty($presence['is_live']);
            $has_unread = (int) ($conversation['unread_count'] ?? 0) > 0;
            $takeover = $status === 'human_takeover';
            $is_priority = $this->crm_apply_chat_conversation_has_label($conversation, 'priority_now');

            if ($status === 'archived') {
                return 'archived';
            }
            if ($is_priority) {
                return 'needs_attention';
            }
            if ($takeover || $has_unread) {
                return 'needs_attention';
            }
            if ($is_live) {
                return 'live_now';
            }

            return 'waiting';
        }

        private function get_crm_apply_chat_queue_label($queue)
        {
            switch ((string) $queue) {
                case 'needs_attention':
                    return __('Needs attention', 'senna-finance');
                case 'live_now':
                    return __('Live now', 'senna-finance');
                case 'archived':
                    return __('Archived', 'senna-finance');
                default:
                    return __('Waiting', 'senna-finance');
            }
        }

        private function format_crm_apply_chat_relative_time($mysql)
        {
            $mysql = trim((string) $mysql);
            if ($mysql === '') {
                return '';
            }

            $timestamp = strtotime($mysql);
            if (!$timestamp) {
                return '';
            }

            $delta = time() - $timestamp;
            if ($delta < MINUTE_IN_SECONDS) {
                return __('Just now', 'senna-finance');
            }
            if ($delta < HOUR_IN_SECONDS) {
                return sprintf(_n('%d min ago', '%d mins ago', (int) floor($delta / MINUTE_IN_SECONDS), 'senna-finance'), (int) floor($delta / MINUTE_IN_SECONDS));
            }
            if ($delta < DAY_IN_SECONDS) {
                return sprintf(_n('%d hr ago', '%d hrs ago', (int) floor($delta / HOUR_IN_SECONDS), 'senna-finance'), (int) floor($delta / HOUR_IN_SECONDS));
            }
            if ($delta < 7 * DAY_IN_SECONDS) {
                return sprintf(_n('%d day ago', '%d days ago', (int) floor($delta / DAY_IN_SECONDS), 'senna-finance'), (int) floor($delta / DAY_IN_SECONDS));
            }

            return date_i18n('j M', $timestamp);
        }

        private function get_crm_apply_chat_summary(array $conversation, array $messages = [])
        {
            $presence = $this->get_crm_apply_chat_presence_state((int) ($conversation['id'] ?? 0));
            $queue = $this->get_crm_apply_chat_queue_for_conversation($conversation, $presence);
            $page_url = $presence['page_url'];

            if ($page_url === '' && !empty($messages)) {
                for ($i = count($messages) - 1; $i >= 0; $i--) {
                    $headers = (array) ($messages[$i]['headers'] ?? []);
                    if (!empty($headers['page_url'])) {
                        $page_url = esc_url_raw((string) $headers['page_url']);
                        break;
                    }
                }
            }

            return [
                'queue' => $queue,
                'queue_label' => $this->get_crm_apply_chat_queue_label($queue),
                'is_live' => !empty($presence['is_live']),
                'is_priority' => $this->crm_apply_chat_conversation_has_label($conversation, 'priority_now'),
                'support_tab_enabled' => $this->crm_apply_chat_conversation_has_label($conversation, 'support_attachments_enabled'),
                'last_seen_label' => !empty($presence['last_seen_at']) ? $this->format_crm_apply_chat_relative_time($presence['last_seen_at']) : __('Offline', 'senna-finance'),
                'page_url' => $page_url,
                'post_id' => (int) ($conversation['post_id'] ?? 0),
                'message_count' => (int) ($conversation['message_count'] ?? 0),
                'unread_count' => (int) ($conversation['unread_count'] ?? 0),
                'status' => sanitize_key((string) ($conversation['status'] ?? 'active')),
                'updated_label' => $this->format_crm_apply_chat_relative_time((string) ($conversation['last_message_at'] ?? $conversation['created_at'] ?? '')),
            ];
        }

        private function get_crm_apply_chat_subject($role_title)
        {
            $role_title = trim((string) $role_title);
            if ($role_title === '') {
                $role_title = __('Unknown role', 'senna-finance');
            }

            return sprintf(__('Apply chat · %s', 'senna-finance'), $role_title);
        }

        private function get_crm_apply_chat_conversation_by_thread_id($thread_id)
        {
            global $wpdb;

            if ($thread_id === '') {
                return null;
            }

            $table = $wpdb->prefix . 'sffc_crm_conversations';

            return $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT * FROM {$table} WHERE thread_id = %s LIMIT 1",
                    $thread_id
                ),
                ARRAY_A
            );
        }

        private function sync_crm_apply_chat_conversation_user($conversation_id, $user_id)
        {
            global $wpdb;

            $conversation_id = (int) $conversation_id;
            $user_id = (int) $user_id;

            if ($conversation_id <= 0 || $user_id <= 0) {
                return;
            }

            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $wpdb->update(
                $table,
                ['user_id' => $user_id],
                ['id' => $conversation_id, 'user_id' => 0],
                ['%d'],
                ['%d', '%d']
            );
        }

        private function find_or_create_crm_apply_chat_conversation($session_token, $post_id, $role_title, $page_url = '')
        {
            $this->ensure_crm_apply_chat_models();

            $session_token = $this->normalize_crm_apply_chat_session_token($session_token);
            if ($session_token === '') {
                return 0;
            }

            $thread_id = $this->get_crm_apply_chat_thread_id($session_token);
            $conversation = $this->get_crm_apply_chat_conversation_by_thread_id($thread_id);
            $user_id = is_user_logged_in() ? get_current_user_id() : 0;

            if (!empty($conversation['id'])) {
                $this->sync_crm_apply_chat_conversation_user((int) $conversation['id'], $user_id);
                return (int) $conversation['id'];
            }

            $conversation_model = new SFFC_CRM_Conversation();
            $conversation_id = $conversation_model->create($user_id, [
                'post_id' => (int) $post_id,
                'subject' => $this->get_crm_apply_chat_subject($role_title),
                'channel' => 'manual',
                'thread_id' => $thread_id,
                'labels' => 'apply_chat',
                'is_read' => 1,
                'last_message_preview' => '',
                'direction' => 'outbound',
            ]);

            if (is_wp_error($conversation_id)) {
                return 0;
            }

            // The shared conversation model assumes creation happens alongside a first
            // message. Apply chat creates a blank shell first, so reset the seeded
            // counts/preview to truthful empty-state values.
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $wpdb->update(
                $table,
                [
                    'labels' => 'apply_chat',
                    'message_count' => 0,
                    'unread_count' => 0,
                    'last_message_preview' => '',
                ],
                ['id' => (int) $conversation_id],
                ['%s', '%d', '%d', '%s'],
                ['%d']
            );

            return (int) $conversation_id;
        }

        private function create_crm_apply_chat_message($conversation_id, $speaker, $content_text, $content_html = '', $external_id = '', array $extra_headers = [], array $attachments = [])
        {
            $this->ensure_crm_apply_chat_models();

            $speaker = sanitize_key((string) $speaker);
            $content_text = trim((string) $content_text);
            $content_html = trim((string) $content_html);
            if ($content_text === '' && $content_html === '') {
                return new WP_Error('empty_content', __('Message content required.', 'senna-finance'));
            }

            $message_model = new SFFC_CRM_Message();

            if ($external_id !== '') {
                $existing = $message_model->get_by_external_id($external_id);
                if (!empty($existing['id'])) {
                    return (int) $existing['id'];
                }
            }

            $direction = $speaker === 'admin' ? 'inbound' : 'outbound';
            $name_map = [
                'user' => __('Candidate', 'senna-finance'),
                'emily' => __('Emily', 'senna-finance'),
                'admin' => __('MENA Careers team', 'senna-finance'),
                'system' => __('System', 'senna-finance'),
            ];
            $from_name = $name_map[$speaker] ?? __('MENA Careers', 'senna-finance');

            return $message_model->create($conversation_id, [
                'direction' => $direction,
                'channel' => 'manual',
                'subject' => __('Apply chat', 'senna-finance'),
                'body_text' => $content_text,
                'body_html' => $content_html,
                'from_name' => $from_name,
                'attachments' => $attachments,
                'headers' => array_merge([
                    'speaker' => $speaker,
                    'source' => 'apply_chat',
                ], $extra_headers),
                'external_id' => $external_id !== '' ? $external_id : null,
            ]);
        }

        private function get_crm_apply_chat_conversation_messages($conversation_id)
        {
            $this->ensure_crm_apply_chat_models();
            $message_model = new SFFC_CRM_Message();
            return (array) $message_model->get_conversation_messages((int) $conversation_id, [
                'limit' => 250,
                'order' => 'ASC',
            ]);
        }

        private function get_crm_apply_chat_conversation_messages_after($conversation_id, $after_id)
        {
            $this->ensure_crm_apply_chat_models();
            $message_model = new SFFC_CRM_Message();
            return (array) $message_model->get_conversation_messages_after((int) $conversation_id, (int) $after_id, [
                'limit' => 100,
                'order' => 'ASC',
            ]);
        }

        private function can_manage_crm_apply_chat_monitor()
        {
            return current_user_can('manage_options');
        }

        private function get_crm_apply_chat_quick_reply_templates($user_id)
        {
            $user_id = (int) $user_id;
            $starter_templates = [
                [
                    'id' => 'starter_follow_up_team',
                    'label' => __('Team follow-up', 'senna-finance'),
                    'body' => __("Thanks for flagging that. I've passed it to the team and I'll keep an eye on it from here.", 'senna-finance'),
                    'starter' => true,
                ],
                [
                    'id' => 'starter_broken_link',
                    'label' => __('Broken link', 'senna-finance'),
                    'body' => __("Thanks, that sounds like a broken link. I've logged it and we’ll check the role path from our side.", 'senna-finance'),
                    'starter' => true,
                ],
                [
                    'id' => 'starter_verification_email',
                    'label' => __('Verification email', 'senna-finance'),
                    'body' => __("Got it. If the verification email has not come through, check spam first. If it still is not there, I’ll get support to look at the account.", 'senna-finance'),
                    'starter' => true,
                ],
                [
                    'id' => 'starter_refund_help',
                    'label' => __('Refund help', 'senna-finance'),
                    'body' => __("Understood. I’ve noted the refund request and will make sure the support team picks it up.", 'senna-finance'),
                    'starter' => true,
                ],
            ];

            $stored = get_user_meta($user_id, 'sffc_crm_apply_chat_quick_replies', true);
            $stored = is_array($stored) ? $stored : [];
            $custom = [];
            foreach ($stored as $item) {
                if (!is_array($item)) {
                    continue;
                }
                $label = sanitize_text_field((string) ($item['label'] ?? ''));
                $body = trim(wp_kses_post((string) ($item['body'] ?? '')));
                if ($label === '' || $body === '') {
                    continue;
                }
                $custom[] = [
                    'id' => sanitize_key((string) ($item['id'] ?? 'tmpl_' . wp_generate_password(10, false, false))),
                    'label' => $label,
                    'body' => $body,
                    'starter' => false,
                ];
            }

            return array_merge($starter_templates, $custom);
        }

        private function save_crm_apply_chat_quick_reply_templates($user_id, array $templates)
        {
            $user_id = (int) $user_id;
            $clean = [];
            foreach ($templates as $item) {
                if (!is_array($item)) {
                    continue;
                }
                $label = sanitize_text_field((string) ($item['label'] ?? ''));
                $body = trim(wp_kses_post((string) ($item['body'] ?? '')));
                if ($label === '' || $body === '') {
                    continue;
                }
                $clean[] = [
                    'id' => sanitize_key((string) ($item['id'] ?? 'tmpl_' . wp_generate_password(10, false, false))),
                    'label' => $label,
                    'body' => $body,
                ];
            }

            update_user_meta($user_id, 'sffc_crm_apply_chat_quick_replies', $clean);
        }

        private function query_crm_apply_chat_admin_threads()
        {
            global $wpdb;

            $this->maintain_crm_apply_chat_lifecycle();

            $table = $wpdb->prefix . 'sffc_crm_conversations';
            $users_table = $wpdb->users;

            return (array) $wpdb->get_results(
                "SELECT c.*,
                        u.display_name AS wp_user_name,
                        u.user_email AS wp_user_email
                 FROM {$table} c
                 LEFT JOIN {$users_table} u ON c.user_id = u.ID
                 WHERE FIND_IN_SET('apply_chat', c.labels)
                 ORDER BY COALESCE(c.last_message_at, c.created_at) DESC
                 LIMIT 250",
                ARRAY_A
            );
        }

        private function format_crm_apply_chat_admin_thread_preview(array $conversation)
        {
            $preview = trim((string) ($conversation['last_message_preview'] ?? ''));
            if ($preview === '') {
                $preview = __('No messages yet.', 'senna-finance');
            }

            return function_exists('mb_strimwidth')
                ? mb_strimwidth($preview, 0, 120, '…')
                : substr($preview, 0, 117) . (strlen($preview) > 117 ? '…' : '');
        }

        private function get_crm_apply_chat_monitor_thread_context(array $conversation)
        {
            $user_name = trim((string) ($conversation['wp_user_name'] ?? ''));
            $user_email = trim((string) ($conversation['wp_user_email'] ?? ''));
            $subject = trim((string) ($conversation['subject'] ?? __('Apply chat', 'senna-finance')));
            $status = trim((string) ($conversation['status'] ?? 'active'));
            $presence = $this->get_crm_apply_chat_presence_state((int) ($conversation['id'] ?? 0));
            $queue = $this->get_crm_apply_chat_queue_for_conversation($conversation, $presence);

            return [
                'id' => (int) ($conversation['id'] ?? 0),
                'subject' => $subject,
                'user_name' => $user_name !== '' ? $user_name : __('Guest user', 'senna-finance'),
                'user_email' => $user_email,
                'preview' => $this->format_crm_apply_chat_admin_thread_preview($conversation),
                'updated_at' => (string) ($conversation['last_message_at'] ?? $conversation['created_at'] ?? current_time('mysql')),
                'status' => $status,
                'takeover_active' => $status === 'human_takeover',
                'unread_count' => (int) ($conversation['unread_count'] ?? 0),
                'queue' => $queue,
                'queue_label' => $this->get_crm_apply_chat_queue_label($queue),
                'is_live' => !empty($presence['is_live']),
                'is_priority' => $this->crm_apply_chat_conversation_has_label($conversation, 'priority_now'),
                'last_seen_at' => (string) ($presence['last_seen_at'] ?? ''),
                'last_seen_label' => !empty($presence['last_seen_at']) ? $this->format_crm_apply_chat_relative_time((string) $presence['last_seen_at']) : __('Offline', 'senna-finance'),
            ];
        }

        private function set_crm_apply_chat_conversation_status($conversation_id, $status)
        {
            global $wpdb;

            $conversation_id = (int) $conversation_id;
            $status = sanitize_key((string) $status);
            if ($conversation_id <= 0 || $status === '') {
                return false;
            }

            $table = $wpdb->prefix . 'sffc_crm_conversations';

            return false !== $wpdb->update(
                $table,
                ['status' => $status],
                ['id' => $conversation_id],
                ['%s'],
                ['%d']
            );
        }

