        public function render_crm_apply_chat_monitor($atts = [])
        {
            if (!$this->can_manage_crm_apply_chat_monitor()) {
                return '';
            }

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-apply-chat-article.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/crm-apply-chat-article.css')
                : SFFC_VERSION;
            wp_enqueue_style(
                'sffc-crm-apply-chat-article',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-apply-chat-article.css',
                [],
                $css_version
            );

            $threads = array_map([$this, 'get_crm_apply_chat_monitor_thread_context'], $this->query_crm_apply_chat_admin_threads());
            $active_conversation_id = !empty($threads[0]['id']) ? (int) $threads[0]['id'] : 0;
            $messages = $active_conversation_id > 0 ? $this->get_crm_apply_chat_conversation_messages($active_conversation_id) : [];
            $quick_reply_templates = $this->get_crm_apply_chat_quick_reply_templates(get_current_user_id());

            ob_start();
            echo $this->render_crm_apply_chat_monitor_markup($threads, $messages, $active_conversation_id, $quick_reply_templates); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
            ?>
            <script>
            (function () {
              var root = document.querySelector("[data-sffc-apply-chat-monitor]");
              if (!root) return;
              var ajaxUrl = <?php echo wp_json_encode(admin_url('admin-ajax.php')); ?>;
              var nonce = <?php echo wp_json_encode(wp_create_nonce('sffc_crm_apply_chat_session')); ?>;
              var messages = root.querySelector("[data-apply-chat-monitor-messages]");
              var threads = root.querySelector("[data-apply-chat-monitor-threads]");
              var form = root.querySelector("[data-apply-chat-monitor-form]");
              var title = root.querySelector("[data-apply-chat-monitor-title]");
              var meta = root.querySelector("[data-apply-chat-monitor-meta]");
              var toggle = root.querySelector("[data-apply-chat-monitor-toggle]");
              var queues = root.querySelector("[data-apply-chat-monitor-queues]");
              var summary = root.querySelector("[data-apply-chat-monitor-summary]");
              var archiveButton = root.querySelector("[data-apply-chat-monitor-archive]");
              var deleteButton = root.querySelector("[data-apply-chat-monitor-delete]");
              var forwardButton = root.querySelector("[data-apply-chat-monitor-forward]");
              var supportToggleButton = root.querySelector("[data-apply-chat-monitor-support-toggle]");
              var noteForm = root.querySelector("[data-apply-chat-monitor-note-form]");
              var templateList = root.querySelector("[data-apply-chat-monitor-template-list]");
              var templateLabelInput = root.querySelector("[data-apply-chat-monitor-template-label]");
              var templateBodyInput = root.querySelector("[data-apply-chat-monitor-template-body]");
              var saveTemplateButton = root.querySelector("[data-apply-chat-monitor-save-template]");
              var currentQueue = root.getAttribute("data-initial-queue") || "needs_attention";
              var fullThreadList = [];
              var quickReplyTemplates = <?php echo wp_json_encode(array_values($quick_reply_templates)); ?>;

              function parseAjaxJson(response) {
                return response.json().catch(function () {
                  throw new Error("Invalid JSON response");
                });
              }

              function renderMessages(items) {
                if (!messages) return;
                if (!items.length) {
                  messages.innerHTML = '<div class="sffc-crm-apply-chat-monitor__empty">No transcript selected yet.</div>';
                  return;
                }
                messages.innerHTML = items.map(function (item) {
                  var speaker = String(item.speaker || "user");
                  var body = item.content_html || "<p>" + String(item.content || "").replace(/[&<>]/g, function (ch) { return {"&":"&amp;","<":"&lt;",">":"&gt;"}[ch]; }) + "</p>";
                  var noteClass = item.internal_note ? ' is-internal-note' : '';
                  var label = item.internal_note ? 'Internal note' : speaker.charAt(0).toUpperCase() + speaker.slice(1);
                  return '<article class="sffc-crm-apply-chat-monitor__message is-' + speaker + noteClass + '"><span class="sffc-crm-apply-chat-monitor__message-label">' + label + '</span><div class="sffc-crm-apply-chat-monitor__message-body">' + body + '</div></article>';
                }).join("");
                messages.scrollTop = messages.scrollHeight;
              }

              function appendMessage(item) {
                if (!messages || !item) return;
                if (messages.querySelector('.sffc-crm-apply-chat-monitor__empty')) {
                  messages.innerHTML = '';
                }
                var speaker = String(item.speaker || "user");
                var body = item.content_html || "<p>" + String(item.content || "").replace(/[&<>]/g, function (ch) { return {"&":"&amp;","<":"&lt;",">":"&gt;"}[ch]; }) + "</p>";
                var noteClass = item.internal_note ? ' is-internal-note' : '';
                var label = item.internal_note ? 'Internal note' : speaker.charAt(0).toUpperCase() + speaker.slice(1);
                messages.insertAdjacentHTML("beforeend", '<article class="sffc-crm-apply-chat-monitor__message is-' + speaker + noteClass + '"><span class="sffc-crm-apply-chat-monitor__message-label">' + label + '</span><div class="sffc-crm-apply-chat-monitor__message-body">' + body + '</div></article>');
                messages.scrollTop = messages.scrollHeight;
              }

              function escapeHtml(value) {
                return String(value || "").replace(/[&<>"]/g, function (ch) {
                  return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[ch];
                });
              }

              function renderTemplateList(items) {
                if (!templateList) return;
                var list = Array.isArray(items) ? items.slice() : [];
                quickReplyTemplates = list;
                if (!list.length) {
                  templateList.innerHTML = '<div class="sffc-crm-apply-chat-monitor__empty">No quick replies saved yet.</div>';
                  return;
                }
                templateList.innerHTML = list.map(function (item) {
                  var id = String(item.id || "");
                  var label = escapeHtml(item.label || "");
                  var body = escapeHtml(item.body || "");
                  var starter = !!item.starter;
                  return '<div class="sffc-crm-apply-chat-monitor__template-chip" data-template-id="' + escapeHtml(id) + '">' +
                    '<button type="button" class="sffc-crm-apply-chat-monitor__template-use" data-apply-chat-monitor-use-template="' + escapeHtml(id) + '" data-template-body="' + body + '">' + label + '</button>' +
                    (starter ? '' : '<button type="button" class="sffc-crm-apply-chat-monitor__template-delete" data-apply-chat-monitor-delete-template="' + escapeHtml(id) + '">Delete</button>') +
                    '</div>';
                }).join("");
              }

              function setReplyBody(value) {
                if (!form) return;
                var textarea = form.querySelector('textarea[name="body"]');
                if (!textarea) return;
                textarea.value = String(value || "");
                textarea.focus();
                textarea.setSelectionRange(textarea.value.length, textarea.value.length);
              }

              function updateTakeoverToggle(status) {
                if (!toggle) return;
                var normalized = status === "human_takeover" ? "human_takeover" : "active";
                toggle.setAttribute("data-state", normalized);
                toggle.textContent = normalized === "human_takeover" ? "Resume Emily" : "Pause Emily";
              }

              function renderSummaryCard(data) {
                if (!summary) return;
                if (!data) {
                  summary.innerHTML = "";
                  return;
                }
                var html = '<div class="sffc-crm-apply-chat-monitor__summary-grid">';
                html += '<div><span>Queue</span><strong>' + escapeHtml(data.queue_label || "") + '</strong></div>';
                html += '<div><span>Last seen</span><strong>' + escapeHtml(data.last_seen_label || "Offline") + '</strong></div>';
                html += '<div><span>Messages</span><strong>' + escapeHtml(data.message_count || 0) + '</strong></div>';
                html += '<div><span>Unread</span><strong>' + escapeHtml(data.unread_count || 0) + '</strong></div>';
                html += '<div><span>Support tab</span><strong>' + (data.support_tab_enabled ? 'Enabled' : 'Hidden') + '</strong></div>';
                if (data.page_url) {
                  html += '<div class="is-wide"><span>Source page</span><a href="' + escapeHtml(data.page_url) + '" target="_blank" rel="noopener">' + escapeHtml(data.page_url) + '</a></div>';
                }
                html += '</div>';
                summary.innerHTML = html;
              }

              function renderQueues(items) {
                if (!queues) return;
                var counts = {needs_attention: 0, live_now: 0, waiting: 0, archived: 0};
                (items || []).forEach(function (item) {
                  var queue = String(item.queue || "waiting");
                  if (counts.hasOwnProperty(queue)) counts[queue] += 1;
                });
                queues.querySelectorAll("[data-apply-chat-monitor-queue]").forEach(function (button) {
                  var queue = button.getAttribute("data-apply-chat-monitor-queue") || "waiting";
                  button.classList.toggle("is-active", queue === currentQueue);
                  var strong = button.querySelector("strong");
                  if (strong) strong.textContent = String(counts[queue] || 0);
                });
              }

              function renderThreads(items, activeId) {
                if (!threads) return;
                fullThreadList = Array.isArray(items) ? items.slice() : [];
                renderQueues(fullThreadList);
                var visibleItems = fullThreadList.filter(function (item) {
                  return String(item.queue || "waiting") === currentQueue;
                });
                if (!visibleItems.length) {
                  threads.innerHTML = '<div class="sffc-crm-apply-chat-monitor__empty">No sessions in this queue.</div>';
                  return;
                }
                threads.innerHTML = visibleItems.map(function (item) {
                  var active = Number(item.id || 0) === Number(activeId || 0) ? " is-active" : "";
                  var flags = '<div class="sffc-crm-apply-chat-monitor__thread-flags">' +
                    '<span class="sffc-crm-apply-chat-monitor__flag is-' + escapeHtml(item.queue || "waiting") + '">' + escapeHtml(item.queue_label || "") + '</span>' +
                    (item.is_live ? '<span class="sffc-crm-apply-chat-monitor__flag is-live">Live</span>' : '') +
                    (item.is_priority ? '<span class="sffc-crm-apply-chat-monitor__flag is-priority">Priority</span>' : '') +
                    (Number(item.unread_count || 0) > 0 ? '<span class="sffc-crm-apply-chat-monitor__flag is-unread">' + escapeHtml(item.unread_count) + ' unread</span>' : '') +
                    '</div>';
                  return '<div class="sffc-crm-apply-chat-monitor__thread' + active + '" data-thread-queue="' + escapeHtml(item.queue || "waiting") + '">' +
                    '<button type="button" class="sffc-crm-apply-chat-monitor__thread-main" data-apply-chat-monitor-open="' + item.id + '"><div class="sffc-crm-apply-chat-monitor__thread-row"><strong>' + escapeHtml(item.user_name || "") + '</strong><time>' + escapeHtml(item.updated_label || "") + '</time></div>' + flags + '<span class="sffc-crm-apply-chat-monitor__thread-subject">' + escapeHtml(item.subject || "") + '</span><small>' + escapeHtml(item.preview || "") + '</small></button>' +
                    '<div class="sffc-crm-apply-chat-monitor__thread-actions">' +
                    '<button type="button" class="sffc-crm-apply-chat-monitor__thread-action" data-apply-chat-monitor-thread-forward="' + item.id + '">Forward</button>' +
                    '<button type="button" class="sffc-crm-apply-chat-monitor__thread-action" data-apply-chat-monitor-thread-archive="' + item.id + '" data-restore="' + (item.status === "archived" ? '1' : '0') + '">' + (item.status === "archived" ? 'Restore' : 'Archive') + '</button>' +
                    '<button type="button" class="sffc-crm-apply-chat-monitor__thread-action is-danger" data-apply-chat-monitor-thread-delete="' + item.id + '">Delete</button>' +
                    '</div></div>';
                }).join("");
              }

              function openConversation(conversationId) {
                var body = new FormData();
                body.append("action", "sffc_crm_apply_chat_admin_open");
                body.append("nonce", nonce);
                body.append("conversation_id", conversationId || "");
                return fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                  .then(parseAjaxJson)
                  .then(function (payload) {
                    if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not load session.");
                    var data = payload.data || {};
                    renderThreads(data.threads || [], data.active_conversation_id || 0);
                    renderMessages(data.messages || []);
                    if (form) {
                      var hidden = form.querySelector('input[name="conversation_id"]');
                      if (hidden) hidden.value = data.active_conversation_id || "";
                    }
                    if (noteForm) {
                      var noteHidden = noteForm.querySelector('input[name="conversation_id"]');
                      if (noteHidden) noteHidden.value = data.active_conversation_id || "";
                    }
                    if (title) title.textContent = data.active_subject || "Apply chat";
                    if (meta) meta.textContent = data.active_meta || "";
                    updateTakeoverToggle(data.active_status || "active");
                    renderSummaryCard(data.active_summary || null);
                    if (archiveButton) {
                      archiveButton.textContent = data.active_status === "archived" ? "Restore" : "Archive";
                    }
                    if (supportToggleButton) {
                      supportToggleButton.textContent = data.support_tab_enabled ? "Hide support tab" : "Show support tab";
                      supportToggleButton.setAttribute("data-enabled", data.support_tab_enabled ? "1" : "0");
                    }
                  });
              }

              if (queues) {
                queues.addEventListener("click", function (event) {
                  var button = event.target.closest("[data-apply-chat-monitor-queue]");
                  if (!button) return;
                  currentQueue = button.getAttribute("data-apply-chat-monitor-queue") || "needs_attention";
                  renderThreads(fullThreadList, form && form.querySelector('input[name="conversation_id"]') ? form.querySelector('input[name="conversation_id"]').value : 0);
                });
              }

              if (threads) {
                threads.addEventListener("click", function (event) {
                  var button = event.target.closest("[data-apply-chat-monitor-open]");
                  if (button) {
                    openConversation(button.getAttribute("data-apply-chat-monitor-open"));
                    return;
                  }
                  var archiveAction = event.target.closest("[data-apply-chat-monitor-thread-archive]");
                  if (archiveAction) {
                    event.stopPropagation();
                    var archiveBody = new FormData();
                    archiveBody.append("action", "sffc_crm_apply_chat_admin_archive");
                    archiveBody.append("nonce", nonce);
                    archiveBody.append("conversation_id", archiveAction.getAttribute("data-apply-chat-monitor-thread-archive"));
                    archiveBody.append("restore", archiveAction.getAttribute("data-restore") === "1" ? "1" : "");
                    fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: archiveBody }).then(parseAjaxJson).then(function () {
                      openConversation(form && form.querySelector('input[name="conversation_id"]') ? form.querySelector('input[name="conversation_id"]').value : "");
                    }).catch(function (error) { window.alert(error.message || "Could not update the session."); });
                    return;
                  }
                  var deleteAction = event.target.closest("[data-apply-chat-monitor-thread-delete]");
                  if (deleteAction) {
                    event.stopPropagation();
                    if (!window.confirm("Delete this session and its transcript?")) return;
                    var deleteBody = new FormData();
                    deleteBody.append("action", "sffc_crm_apply_chat_admin_delete");
                    deleteBody.append("nonce", nonce);
                    deleteBody.append("conversation_id", deleteAction.getAttribute("data-apply-chat-monitor-thread-delete"));
                    fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: deleteBody }).then(parseAjaxJson).then(function () {
                      openConversation(form && form.querySelector('input[name="conversation_id"]') ? form.querySelector('input[name="conversation_id"]').value : "");
                    }).catch(function (error) { window.alert(error.message || "Could not delete the session."); });
                    return;
                  }
                  var forwardAction = event.target.closest("[data-apply-chat-monitor-thread-forward]");
                  if (forwardAction) {
                    event.stopPropagation();
                    var forwardBody = new FormData();
                    forwardBody.append("action", "sffc_crm_apply_chat_admin_forward");
                    forwardBody.append("nonce", nonce);
                    forwardBody.append("conversation_id", forwardAction.getAttribute("data-apply-chat-monitor-thread-forward"));
                    fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: forwardBody }).then(parseAjaxJson).then(function () {
                      window.alert("Session forwarded.");
                    }).catch(function (error) { window.alert(error.message || "Could not forward the session."); });
                  }
                });
              }

              if (form) {
                form.addEventListener("submit", function (event) {
                  event.preventDefault();
                  var textarea = form.querySelector('textarea[name="body"]');
                  var hidden = form.querySelector('input[name="conversation_id"]');
                  var value = textarea ? textarea.value.trim() : "";
                  if (!value || !hidden || !hidden.value) return;
                  var body = new FormData();
                  var fileInput = form.querySelector('input[name="attachments[]"]');
                  var supportCheckbox = form.querySelector('input[name="show_in_support_tab"]');
                  body.append("action", "sffc_crm_apply_chat_admin_reply");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  body.append("body", value);
                  if (supportCheckbox && supportCheckbox.checked) {
                    body.append("show_in_support_tab", "1");
                  }
                  if (fileInput && fileInput.files && fileInput.files.length) {
                    Array.prototype.forEach.call(fileInput.files, function (file) {
                      body.append("attachments[]", file);
                    });
                  }
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                    .then(parseAjaxJson)
                    .then(function (payload) {
                      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not send reply.");
                      if (payload.data && payload.data.message) {
                        appendMessage(payload.data.message);
                      }
                      textarea.value = "";
                      if (fileInput) fileInput.value = "";
                      if (supportCheckbox) supportCheckbox.checked = false;
                      openConversation(hidden.value);
                    })
                    .catch(function (error) {
                      window.alert(error.message || "Could not send reply.");
                    });
                });
              }

              if (templateList) {
                templateList.addEventListener("click", function (event) {
                  var useButton = event.target.closest("[data-apply-chat-monitor-use-template]");
                  if (useButton) {
                    setReplyBody(useButton.getAttribute("data-template-body") || "");
                    return;
                  }
                  var deleteTemplateButton = event.target.closest("[data-apply-chat-monitor-delete-template]");
                  if (deleteTemplateButton) {
                    var templateId = deleteTemplateButton.getAttribute("data-apply-chat-monitor-delete-template") || "";
                    if (!templateId) return;
                    var body = new FormData();
                    body.append("action", "sffc_crm_apply_chat_admin_delete_template");
                    body.append("nonce", nonce);
                    body.append("template_id", templateId);
                    fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                      .then(parseAjaxJson)
                      .then(function (payload) {
                        if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not delete template.");
                        renderTemplateList(payload.data && payload.data.templates ? payload.data.templates : []);
                      })
                      .catch(function (error) {
                        window.alert(error.message || "Could not delete template.");
                      });
                  }
                });
              }

              if (saveTemplateButton) {
                saveTemplateButton.addEventListener("click", function () {
                  var label = templateLabelInput ? templateLabelInput.value.trim() : "";
                  var bodyText = templateBodyInput ? templateBodyInput.value.trim() : "";
                  if (!label || !bodyText) {
                    window.alert("Add a template title and body first.");
                    return;
                  }
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_save_template");
                  body.append("nonce", nonce);
                  body.append("label", label);
                  body.append("body", bodyText);
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                    .then(parseAjaxJson)
                    .then(function (payload) {
                      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not save template.");
                      renderTemplateList(payload.data && payload.data.templates ? payload.data.templates : []);
                      if (templateLabelInput) templateLabelInput.value = "";
                      if (templateBodyInput) templateBodyInput.value = "";
                    })
                    .catch(function (error) {
                      window.alert(error.message || "Could not save template.");
                    });
                });
              }

              if (noteForm) {
                noteForm.addEventListener("submit", function (event) {
                  event.preventDefault();
                  var textarea = noteForm.querySelector('textarea[name="body"]');
                  var hidden = noteForm.querySelector('input[name="conversation_id"]');
                  var value = textarea ? textarea.value.trim() : "";
                  if (!value || !hidden || !hidden.value) return;
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_note");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  body.append("body", value);
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body }).then(parseAjaxJson).then(function (payload) {
                    if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not save note.");
                    if (payload.data && payload.data.message) {
                      appendMessage(payload.data.message);
                    }
                    textarea.value = "";
                    openConversation(hidden.value);
                  }).catch(function (error) {
                    window.alert(error.message || "Could not save note.");
                  });
                });
              }

              if (toggle) {
                toggle.addEventListener("click", function () {
                  var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                  if (!hidden || !hidden.value) return;
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_set_takeover");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  body.append("resume_emily", toggle.getAttribute("data-state") === "human_takeover" ? "1" : "");
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                    .then(parseAjaxJson)
                    .then(function (payload) {
                      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not update the chat state.");
                      updateTakeoverToggle(payload.data && payload.data.status || "active");
                    })
                    .catch(function (error) {
                      window.alert(error.message || "Could not update the chat state.");
                    });
                });
              }

              if (archiveButton) {
                archiveButton.addEventListener("click", function () {
                  var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                  if (!hidden || !hidden.value) return;
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_archive");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  body.append("restore", archiveButton.textContent === "Restore" ? "1" : "");
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                    .then(parseAjaxJson)
                    .then(function (payload) {
                      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not update the session.");
                      openConversation(hidden.value);
                    })
                    .catch(function (error) {
                      window.alert(error.message || "Could not update the session.");
                    });
                });
              }

              if (deleteButton) {
                deleteButton.addEventListener("click", function () {
                  var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                  if (!hidden || !hidden.value) return;
                  if (!window.confirm("Delete this session and its transcript?")) return;
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_delete");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body })
                    .then(parseAjaxJson)
                    .then(function (payload) {
                      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not delete the session.");
                      openConversation("");
                    })
                    .catch(function (error) {
                      window.alert(error.message || "Could not delete the session.");
                    });
                });
              }

              if (forwardButton) {
                forwardButton.addEventListener("click", function () {
                  var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                  if (!hidden || !hidden.value) return;
                  var body = new FormData();
                  body.append("action", "sffc_crm_apply_chat_admin_forward");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body }).then(parseAjaxJson).then(function (payload) {
                    if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not forward the session.");
                    window.alert("Session forwarded.");
                  }).catch(function (error) {
                    window.alert(error.message || "Could not forward the session.");
                  });
                });
              }

              if (supportToggleButton) {
                supportToggleButton.addEventListener("click", function () {
                  var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                  if (!hidden || !hidden.value) return;
                  var body = new FormData();
                  var nextEnabled = supportToggleButton.getAttribute("data-enabled") === "1" ? "" : "1";
                  body.append("action", "sffc_crm_apply_chat_admin_toggle_support_tab");
                  body.append("nonce", nonce);
                  body.append("conversation_id", hidden.value);
                  body.append("enabled", nextEnabled);
                  fetch(ajaxUrl, { method: "POST", credentials: "same-origin", body: body }).then(parseAjaxJson).then(function (payload) {
                    if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || "Could not update support tab visibility.");
                    openConversation(hidden.value);
                  }).catch(function (error) {
                    window.alert(error.message || "Could not update support tab visibility.");
                  });
                });
              }

              (function bootstrapMonitor() {
                renderTemplateList(quickReplyTemplates);
                var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                openConversation(hidden && hidden.value ? hidden.value : "");
              })();

              window.setInterval(function () {
                var hidden = form ? form.querySelector('input[name="conversation_id"]') : null;
                openConversation(hidden && hidden.value ? hidden.value : "");
              }, 12000);
            })();
            </script>
            <?php
            return (string) ob_get_clean();
        }

