        private function get_members_paid_signup_plan_cycles($member_signup_locale)
        {
            $plans = array_values((array) $this->get_subscription_plans());
            $catalog = $this->get_apply_chat_membership_plan_catalog();
            $plan_cycles = [
                'monthly' => [],
                'annual' => [],
            ];
            $normalize_signup_price_label = static function ($display_price) {
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $amount_label = $display_price;
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', (string) $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                }

                return [$display_price, $amount_label];
            };

            foreach ($plans as $plan) {
                if (!empty($plan['is_annual'])) {
                    continue;
                }

                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim($name . ' ' . (string) ($plan['tagline'] ?? '') . ' ' . (string) ($plan['audience'] ?? ''))
                );
                $signup_path = (string) ($signup_path_meta['path'] ?? 'platform');
                if (!in_array($signup_path, ['platform', 'mentorship', 'all_access'], true)) {
                    continue;
                }
                $catalog_entry = $catalog[$signup_path] ?? $catalog['platform'];

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];
                $features = array_map(function ($feature) use ($member_signup_locale) {
                    return $this->translate_member_signup_feature($feature, $member_signup_locale);
                }, $features);

                $display_price = $this->format_plan_price_amount($plan) ?: trim((string) ($plan['price'] ?? ''));
                [$display_price, $amount_label] = $normalize_signup_price_label($display_price);

                $monthly_entry = [
                    'slug' => sanitize_key((string) ($plan['slug'] ?? sanitize_title($name))),
                    'signup_path' => $signup_path,
                    'name' => sanitize_text_field((string) ($catalog_entry['title'] ?? $name)),
                    'switch_label' => sanitize_text_field((string) ($catalog_entry['switch_label'] ?? $name)),
                    'description' => sanitize_text_field((string) ($catalog_entry['description'] ?? trim((string) ($plan['tagline'] ?? $plan['audience'] ?? '')))),
                    'eyebrow' => sanitize_text_field((string) ($catalog_entry['eyebrow'] ?? '')),
                    'price' => $display_price,
                    'price_amount' => (float) ($plan['price_amount'] ?? 0),
                    'amount_label' => $amount_label,
                    'billing_cycle' => trim((string) ($plan['billing_cycle'] ?? __('per month', 'senna-finance'))) ?: __('per month', 'senna-finance'),
                    'matches_per_week' => max(0, (int) ($plan['matches_per_week'] ?? 0)),
                    'features' => !empty($catalog_entry['includes']) && is_array($catalog_entry['includes'])
                        ? array_values(array_filter(array_map('sanitize_text_field', (array) $catalog_entry['includes'])))
                        : array_slice($features, 0, 4),
                    'shortcode' => isset($plan['shortcode']) ? wp_kses_post((string) $plan['shortcode']) : '',
                    'url' => !empty($plan['mp_url']) ? esc_url_raw((string) $plan['mp_url']) : esc_url_raw($this->get_canonical_membership_url()),
                    'featured_signup' => !empty($plan['featured_signup']),
                ];
                $plan_cycles['monthly'][$signup_path] = $monthly_entry;

                $annual_display_price = trim((string) ($plan['annual_price'] ?? ''));
                $has_annual_variant = $annual_display_price !== ''
                    || !empty($plan['annual_mp_url'])
                    || !empty($plan['annual_shortcode'])
                    || !empty($plan['annual_price_amount']);
                if (!$has_annual_variant) {
                    continue;
                }

                if ($annual_display_price === '' && !empty($plan['annual_price_amount']) && !empty($plan['price_currency'])) {
                    $currency_symbol = strtoupper((string) $plan['price_currency']) === 'GBP' ? '£' : strtoupper((string) $plan['price_currency']) . ' ';
                    $annual_display_price = $currency_symbol . number_format((float) $plan['annual_price_amount'], 2) . '/year';
                }
                if ($annual_display_price === '') {
                    $annual_display_price = $display_price;
                }
                [$annual_display_price, $annual_amount_label] = $normalize_signup_price_label($annual_display_price);

                $annual_entry = $monthly_entry;
                $annual_entry['slug'] = $monthly_entry['slug'] . '-annual';
                $annual_entry['price'] = $annual_display_price;
                $annual_entry['price_amount'] = (float) ($plan['annual_price_amount'] ?? $monthly_entry['price_amount']);
                $annual_entry['amount_label'] = $annual_amount_label;
                $annual_entry['billing_cycle'] = trim((string) ($plan['annual_billing_cycle'] ?? __('per year', 'senna-finance'))) ?: __('per year', 'senna-finance');
                $annual_entry['shortcode'] = !empty($plan['annual_shortcode'])
                    ? wp_kses_post((string) $plan['annual_shortcode'])
                    : $monthly_entry['shortcode'];
                $annual_entry['url'] = !empty($plan['annual_mp_url']) ? esc_url_raw((string) $plan['annual_mp_url']) : $monthly_entry['url'];
                $plan_cycles['annual'][$signup_path] = $annual_entry;
            }

            foreach (['monthly', 'annual'] as $cycle) {
                $ordered = [];
                foreach (['mentorship', 'platform', 'all_access'] as $path) {
                    if (!empty($plan_cycles[$cycle][$path])) {
                        $ordered[] = $plan_cycles[$cycle][$path];
                    }
                }
                $plan_cycles[$cycle] = $ordered;
            }

            if (empty($plan_cycles['annual'])) {
                $plan_cycles['annual'] = [];
            }

            return $plan_cycles;
        }

