            endif;

            return (string) ob_get_clean();
        }

        private function get_apply_for_me_signup_context()
        {
            $account_type = isset($_GET['account_type']) ? sanitize_key(wp_unslash((string) $_GET['account_type'])) : '';
            if (!in_array($account_type, ['platform', 'mentorship', 'all_access'], true)) {
                $account_type = sanitize_key($this->get_valid_signup_cookie_value('sffc_signup_account_type'));
            }
            if (!in_array($account_type, ['platform', 'mentorship', 'all_access'], true)) {
                $account_type = 'all_access';
            }

            $support_mode = isset($_GET['support_mode']) ? sanitize_key(wp_unslash((string) $_GET['support_mode'])) : '';
            if (!in_array($support_mode, ['applications', 'intros', 'both'], true)) {
                $support_mode = $account_type === 'platform' ? 'intros' : 'both';
            }

            $normalize_volume = static function ($value) {
                $value = trim((string) $value);
                if ($value === '') {
                    return '';
                }
                if (preg_match('/(\d{1,3})/', $value, $matches)) {
                    return (string) absint($matches[1]);
                }
                return sanitize_text_field($value);
            };

            $email = $this->get_signup_email_prefill_value();
            $full_name = '';
            if (!empty($_GET['full_name'])) {
                $full_name = sanitize_text_field(wp_unslash((string) $_GET['full_name']));
            } else {
                $full_name = trim(
                    sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_first_name')) . ' ' .
                    sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_last_name'))
                );
            }

            return [
                'account_type' => $account_type,
                'support_mode' => $support_mode,
                'applications_per_week' => $normalize_volume($_GET['applications_per_week'] ?? ''),
                'intros_per_week' => $normalize_volume($_GET['intros_per_week'] ?? ''),
                'priority_preference' => sanitize_key(wp_unslash((string) ($_GET['priority_preference'] ?? ''))),
                'lane_preference' => sanitize_key(wp_unslash((string) ($_GET['lane_preference'] ?? ''))),
                'role' => sanitize_text_field(wp_unslash((string) ($_GET['role'] ?? ''))),
                'company' => sanitize_text_field(wp_unslash((string) ($_GET['company'] ?? ''))),
                'target_roles' => sanitize_text_field(wp_unslash((string) ($_GET['target_roles'] ?? ''))),
                'target_sectors' => sanitize_text_field(wp_unslash((string) ($_GET['target_sectors'] ?? ''))),
                'preferred_market' => sanitize_text_field(wp_unslash((string) ($_GET['preferred_market'] ?? ''))),
                'search_query' => sanitize_text_field(wp_unslash((string) ($_GET['search_query'] ?? ''))),
                'email' => $email,
                'full_name' => $full_name,
            ];
        }

        private function maybe_seed_apply_for_me_signup_identity(array $context)
        {
            $expires = time() + (30 * DAY_IN_SECONDS);
            if (!empty($context['email']) && is_email($context['email'])) {
                $this->set_signup_scoped_cookie('sffc_signup_email', (string) $context['email'], $expires);
            }
            if (!empty($context['full_name'])) {
                $parsed_name = $this->parse_full_name((string) $context['full_name']);
                if (!empty($parsed_name['first_name'])) {
                    $this->set_signup_scoped_cookie('sffc_signup_first_name', (string) $parsed_name['first_name'], $expires);
                }
                if (!empty($parsed_name['last_name'])) {
                    $this->set_signup_scoped_cookie('sffc_signup_last_name', (string) $parsed_name['last_name'], $expires);
                }
            }
            if (!empty($context['account_type'])) {
                $this->set_signup_scoped_cookie('sffc_signup_account_type', (string) $context['account_type'], $expires);
            }
        }

        private function get_apply_for_me_signup_plan($account_type)
        {
            $plans = (array) $this->get_apply_chat_membership_plans();
            foreach ($plans as $plan) {
                if (($plan['account_type'] ?? '') === $account_type) {
                    return (array) $plan;
                }
            }

            return !empty($plans[0]) ? (array) $plans[0] : [];
        }

        private function get_apply_for_me_signup_price_hint(array $context)
        {
            $recruiter_plans = array_values(array_filter(
                $this->get_dashboard_membership_plans_for_credits(),
                array($this, 'is_recruiter_contact_credit_plan')
            ));

            $recruiter_plans = array_values(array_filter($recruiter_plans, static function ($plan) {
                return empty($plan['is_annual']);
            }));

            usort($recruiter_plans, static function ($a, $b) {
                $a_amount = isset($a['price_amount']) ? (float) $a['price_amount'] : 0.0;
                $b_amount = isset($b['price_amount']) ? (float) $b['price_amount'] : 0.0;
                if ($a_amount !== $b_amount) {
                    return $a_amount <=> $b_amount;
                }
                return (int) ($a['matches_per_week'] ?? 0) <=> (int) ($b['matches_per_week'] ?? 0);
            });

            $chosen_plan = !empty($recruiter_plans[0]) ? (array) $recruiter_plans[0] : [];
            if (empty($chosen_plan)) {
                $chosen_plan = $this->get_apply_for_me_signup_plan((string) ($context['account_type'] ?? ''));
            }

            if (empty($chosen_plan)) {
                return [];
            }

            $display_price = $this->format_plan_price_amount($chosen_plan) ?: trim((string) ($chosen_plan['display_price'] ?? $chosen_plan['price'] ?? ''));
            $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
            $billing_cycle = trim((string) ($chosen_plan['billing_cycle'] ?? ''));

            if ($display_price === '') {
                return [];
            }

            return [
                'display_price' => sanitize_text_field($display_price),
                'billing_cycle' => sanitize_text_field($billing_cycle),
                'plan_name' => sanitize_text_field((string) ($chosen_plan['name'] ?? '')),
                'uses_recruiter_contact_source' => !empty($recruiter_plans[0]),
            ];
        }

        private function build_apply_for_me_signup_benefits(array $context)
        {
            $benefits = [];

            if (!empty($context['target_roles'])) {
                $benefits[] = sprintf(
                    __('Focused on %s', 'senna-finance'),
                    $context['target_roles']
                );
            }

            if (!empty($context['target_sectors'])) {
                $benefits[] = sprintf(
                    __('Sector focus: %s', 'senna-finance'),
                    $context['target_sectors']
                );
            }

            if (!empty($context['preferred_market'])) {
                $benefits[] = sprintf(
                    __('Main market: %s', 'senna-finance'),
                    $context['preferred_market']
                );
            }

            if (in_array($context['support_mode'], ['applications', 'both'], true) && $context['applications_per_week'] !== '') {
                $benefits[] = sprintf(
                    __('%s tailored applications handled each week', 'senna-finance'),
                    $context['applications_per_week']
                );
            }

            if (in_array($context['support_mode'], ['intros', 'both'], true) && $context['intros_per_week'] !== '') {
                $benefits[] = sprintf(
                    __('%s recruiter intros prepared each week', 'senna-finance'),
                    $context['intros_per_week']
                );
            }

            if ($context['priority_preference'] === 'speed') {
                $benefits[] = __('Built around faster interview momentum', 'senna-finance');
            } elseif ($context['priority_preference'] === 'fit') {
                $benefits[] = __('Built around better-fit roles and tighter targeting', 'senna-finance');
            }

            if ($context['lane_preference'] === 'close') {
                $benefits[] = __('Kept close to your recent background', 'senna-finance');
            } elseif ($context['lane_preference'] === 'widen') {
                $benefits[] = __('Leaves room for adjacent roles that still fit', 'senna-finance');
            }

            if (empty($benefits)) {
                $benefits[] = __('A personalised support plan based on what you asked Emily to handle in chat', 'senna-finance');
            }

            return array_slice($benefits, 0, 4);
        }

        private function build_apply_for_me_signup_features(array $context, array $plan)
        {
            $features = [];

            if (in_array($context['support_mode'], ['applications', 'both'], true)) {
                $features[] = __('Applications are prepared around the role direction you agreed with Emily', 'senna-finance');
            }
            if (in_array($context['support_mode'], ['intros', 'both'], true)) {
                $features[] = __('Recruiter outreach is included where there is a genuine contact route', 'senna-finance');
            }
            $features[] = __('Your signup stays linked to the chat context, so Emily can start from the right brief', 'senna-finance');

            foreach ((array) ($plan['features'] ?? []) as $feature) {
                $feature = sanitize_text_field((string) $feature);
                if ($feature !== '') {
                    $features[] = $feature;
                }
            }

            return array_values(array_slice(array_unique($features), 0, 6));
        }

