        public function capture_membership_signup_lead(array $payload)
        {
            $email = sanitize_email((string) ($payload['email'] ?? ''));
            if ($email === '' || !is_email($email)) {
                return false;
            }

            $now = time();
            $key = $this->get_membership_signup_reminder_option_key($email);
            $existing = get_option($key, []);
            $existing = is_array($existing) ? $existing : [];
            $created_at = !empty($existing['created_at']) ? (int) $existing['created_at'] : $now;

            $lead = [
                'email' => $email,
                'first_name' => sanitize_text_field((string) ($payload['first_name'] ?? ($existing['first_name'] ?? ''))),
                'last_name' => sanitize_text_field((string) ($payload['last_name'] ?? ($existing['last_name'] ?? ''))),
                'source' => sanitize_key((string) ($payload['source'] ?? ($existing['source'] ?? 'membership_capture'))),
                'study_level' => sanitize_key((string) ($payload['study_level'] ?? ($existing['study_level'] ?? ''))),
                'finance_interest' => array_values(array_filter(array_map('sanitize_key', (array) ($payload['finance_interest'] ?? ($existing['finance_interest'] ?? []))))),
                'seniority_level' => array_values(array_filter(array_map('sanitize_key', (array) ($payload['seniority_level'] ?? ($existing['seniority_level'] ?? []))))),
                'support_need' => array_values(array_filter(array_map('sanitize_key', (array) ($payload['support_need'] ?? ($existing['support_need'] ?? []))))),
                'jobs_post_id' => absint($payload['jobs_post_id'] ?? ($existing['jobs_post_id'] ?? 0)),
                'post_id' => absint($payload['post_id'] ?? ($existing['post_id'] ?? 0)),
                'application_url' => esc_url_raw((string) ($payload['application_url'] ?? ($existing['application_url'] ?? ''))),
                'role_title' => sanitize_text_field((string) ($payload['role_title'] ?? ($existing['role_title'] ?? ''))),
                'company_name' => sanitize_text_field((string) ($payload['company_name'] ?? ($existing['company_name'] ?? ''))),
                'created_at' => $created_at,
                'updated_at' => $now,
                'last_sent_at' => !empty($existing['last_sent_at']) ? (int) $existing['last_sent_at'] : 0,
                'send_count' => !empty($existing['send_count']) ? (int) $existing['send_count'] : 0,
                'status' => 'active',
            ];

            update_option($key, $lead, false);
            $this->persist_signup_prefill_state([
                'email' => $email,
                'first_name' => $lead['first_name'],
                'last_name' => $lead['last_name'],
                'finance_interest' => $lead['finance_interest'],
                'seniority_level' => $lead['seniority_level'],
                'support_need' => $lead['support_need'],
            ], 30 * DAY_IN_SECONDS);

            if (!$this->membership_signup_email_has_signed_up($email)) {
                $this->schedule_membership_signup_reminder($email, 4 * DAY_IN_SECONDS);
            }

            return true;
        }

        private function get_membership_signup_redirect_url($redirect_url = '', $email = '')
        {
            $base_url = esc_url_raw((string) $redirect_url);
            if ($base_url === '' || strpos($base_url, '/memberships') === false) {
                $base_url = home_url('/memberships/');
            }

            $email = sanitize_email((string) $email);
            if ($email !== '' && is_email($email)) {
                $base_url = add_query_arg([
                    'sffc_capture_signup_email' => '1',
                    'user_email' => $email,
                ], $base_url);
            }

            return $base_url;
        }

        private function get_membership_signup_reminder_option_key($email)
        {
            return 'sffc_membership_signup_reminder_' . md5(strtolower(trim((string) $email)));
        }

        private function membership_signup_email_has_signed_up($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return true;
            }

            $user_id = (int) email_exists($email);
            if ($user_id > 0) {
                return true;
            }

            return false;
        }

        public function stop_membership_signup_reminders($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return;
            }

            $key = $this->get_membership_signup_reminder_option_key($email);
            $lead = get_option($key, []);
            if (is_array($lead) && !empty($lead)) {
                $lead['status'] = 'stopped';
                $lead['stopped_at'] = time();
                update_option($key, $lead, false);
            }
            wp_clear_scheduled_hook('sffc_send_membership_signup_reminder_email', [$email]);
        }

        private function schedule_membership_signup_reminder($email, $delay)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return;
            }

            if (wp_next_scheduled('sffc_send_membership_signup_reminder_email', [$email])) {
                return;
            }

            wp_schedule_single_event(time() + max(HOUR_IN_SECONDS, (int) $delay), 'sffc_send_membership_signup_reminder_email', [$email]);
        }

        public function send_membership_signup_reminder_email($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return;
            }

            if ($this->membership_signup_email_has_signed_up($email)) {
                $this->stop_membership_signup_reminders($email);
                return;
            }

            $key = $this->get_membership_signup_reminder_option_key($email);
            $lead = get_option($key, []);
            if (!is_array($lead) || empty($lead) || ($lead['status'] ?? '') !== 'active') {
                return;
            }

            $created_at = !empty($lead['created_at']) ? (int) $lead['created_at'] : time();
            $send_count = !empty($lead['send_count']) ? (int) $lead['send_count'] : 0;
            if ($send_count >= 23 || (time() - $created_at) >= (90 * DAY_IN_SECONDS)) {
                $this->stop_membership_signup_reminders($email);
                return;
            }

            $variant = $this->get_membership_signup_reminder_variant($send_count, $lead);
            $html = $this->render_membership_signup_reminder_email_html($variant, $lead);
            $headers = [
                'Content-Type: text/html; charset=UTF-8',
                'From: MENA Careers <support.team@joinsenna.com>',
            ];

            $sent = wp_mail($email, (string) $variant['subject'], $html, $headers);
            if ($sent) {
                $lead['send_count'] = $send_count + 1;
                $lead['last_sent_at'] = time();
                update_option($key, $lead, false);
            }

            if (!$this->membership_signup_email_has_signed_up($email) && ($send_count + 1) < 23 && (time() - $created_at) < (90 * DAY_IN_SECONDS)) {
                $this->schedule_membership_signup_reminder($email, 4 * DAY_IN_SECONDS);
            }
        }

