        public function ajax_crm_editorial_cv_upload_membership_capture()
        {
            check_ajax_referer('sffc_crm_editorial_cv_upload_membership_capture', 'nonce');

            $email = sanitize_email(wp_unslash((string) ($_POST['email'] ?? '')));
            if ($email === '' || !is_email($email)) {
                wp_send_json_error([
                    'message' => __('Enter a valid email address.', 'senna-finance'),
                ], 400);
            }

            $redirect_url = $this->get_membership_signup_redirect_url(home_url('/memberships/'), $email);
            $this->capture_crm_editorial_cv_upload_membership_lead($email);

            wp_send_json_success([
                'redirect' => $redirect_url,
            ]);
        }

        private function get_crm_editorial_cv_upload_membership_option_key($email)
        {
            return 'sffc_crm_editorial_cv_upload_membership_' . md5(strtolower(trim((string) $email)));
        }

        private function capture_crm_editorial_cv_upload_membership_lead($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return false;
            }

            $now = time();
            $key = $this->get_crm_editorial_cv_upload_membership_option_key($email);
            $existing = get_option($key, []);
            $existing = is_array($existing) ? $existing : [];
            $lead = [
                'email' => $email,
                'source' => 'community_cv_upload_gate',
                'created_at' => !empty($existing['created_at']) ? (int) $existing['created_at'] : $now,
                'updated_at' => $now,
                'first_sent_at' => !empty($existing['first_sent_at']) ? (int) $existing['first_sent_at'] : 0,
                'second_sent_at' => !empty($existing['second_sent_at']) ? (int) $existing['second_sent_at'] : 0,
                'status' => 'active',
            ];

            update_option($key, $lead, false);
            $this->persist_signup_prefill_state([
                'email' => $email,
            ], 30 * DAY_IN_SECONDS);

            if (!$this->crm_editorial_email_has_paid_membership_access($email)) {
                $this->schedule_crm_editorial_cv_upload_membership_reminder($email, 1, 3 * HOUR_IN_SECONDS);
                $this->schedule_crm_editorial_cv_upload_membership_reminder($email, 2, DAY_IN_SECONDS);
            }

            return true;
        }

        private function schedule_crm_editorial_cv_upload_membership_reminder($email, $step, $delay)
        {
            $email = sanitize_email((string) $email);
            $step = absint($step);
            if ($email === '' || !is_email($email) || !in_array($step, [1, 2], true)) {
                return;
            }

            $args = [$email, $step];
            if (wp_next_scheduled('sffc_crm_editorial_send_cv_upload_membership_reminder', $args)) {
                return;
            }

            wp_schedule_single_event(time() + max(HOUR_IN_SECONDS, (int) $delay), 'sffc_crm_editorial_send_cv_upload_membership_reminder', $args);
        }

        public function send_crm_editorial_cv_upload_membership_reminder($email, $step)
        {
            $email = sanitize_email((string) $email);
            $step = absint($step);
            if ($email === '' || !is_email($email) || !in_array($step, [1, 2], true)) {
                return;
            }

            $key = $this->get_crm_editorial_cv_upload_membership_option_key($email);
            $lead = get_option($key, []);
            if (!is_array($lead) || empty($lead) || ($lead['status'] ?? '') !== 'active') {
                return;
            }

            if ($this->crm_editorial_email_has_paid_membership_access($email)) {
                $lead['status'] = 'stopped';
                $lead['stopped_at'] = time();
                update_option($key, $lead, false);
                wp_clear_scheduled_hook('sffc_crm_editorial_send_cv_upload_membership_reminder', [$email, 1]);
                wp_clear_scheduled_hook('sffc_crm_editorial_send_cv_upload_membership_reminder', [$email, 2]);
                return;
            }

            $variant = $this->get_crm_editorial_cv_upload_membership_reminder_variant($step);
            $html = $this->render_crm_editorial_cv_upload_membership_reminder_email_html($variant);
            $sent = false;

            $sendgrid = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
            if ($sendgrid && method_exists($sendgrid, 'is_configured') && $sendgrid->is_configured()) {
                $result = $sendgrid->send_email(
                    (string) ($variant['subject'] ?? __('Upload your CV to improve your MENA Careers results', 'senna-finance')),
                    $html,
                    $email,
                    null,
                    [
                        'category' => 'community_cv_upload_membership',
                        'step' => $step,
                    ],
                    ['community_cv_upload_membership'],
                    'default'
                );
                $sent = !is_wp_error($result);
            } else {
                $sent = wp_mail(
                    $email,
                    (string) ($variant['subject'] ?? __('Upload your CV to improve your MENA Careers results', 'senna-finance')),
                    $html,
                    [
                        'Content-Type: text/html; charset=UTF-8',
                        'From: MENA Careers <support.team@joinsenna.com>',
                    ]
                );
            }

            if ($sent) {
                $lead[$step === 1 ? 'first_sent_at' : 'second_sent_at'] = time();
                if ($step === 2) {
                    $lead['status'] = 'completed';
                    $lead['completed_at'] = time();
                }
                update_option($key, $lead, false);
            }
        }

        private function get_crm_editorial_cv_upload_membership_reminder_variant($step)
        {
            if ((int) $step === 2) {
                return [
                    'subject' => __('Your CV can make MENA Careers more relevant', 'senna-finance'),
                    'title' => __('Better roles start with better context', 'senna-finance'),
                    'lead' => __('Uploading your CV helps MENA Careers compare roles against your actual seniority, sector evidence, skills, and target market.', 'senna-finance'),
                    'facts' => [
                        __('Qualified Jobs can prioritise roles where your profile is strongest.', 'senna-finance'),
                        __('Match insights can show missing keywords, skills, and qualifications before you apply.', 'senna-finance'),
                        __('Tracker alerts become more useful when they are based on your CV context.', 'senna-finance'),
                    ],
                ];
            }

            return [
                'subject' => __('Upload your CV to see better-matched MENA roles', 'senna-finance'),
                'title' => __('Use your CV to reduce irrelevant roles', 'senna-finance'),
                'lead' => __('MENA Careers can use your CV to tailor private equity results across Dubai, Abu Dhabi, Riyadh, Doha, London, and Singapore.', 'senna-finance'),
                'facts' => [
                    __('Filter towards roles that match your seniority and experience.', 'senna-finance'),
                    __('See role-fit checks before spending time on applications.', 'senna-finance'),
                    __('Unlock deeper analysis for ATS keywords, sector signal, and CV evidence.', 'senna-finance'),
                ],
            ];
        }

