        private function crm_editorial_email_has_paid_membership_access($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return true;
            }

            $user_id = (int) email_exists($email);
            if ($user_id <= 0) {
                return false;
            }

            if (user_can($user_id, 'manage_options')) {
                return true;
            }

            try {
                if (method_exists($this, 'get_active_memberpress_product_ids') && method_exists($this, 'has_active_paid_memberpress_plan')) {
                    if ($this->has_active_paid_memberpress_plan($this->get_active_memberpress_product_ids($user_id))) {
                        return true;
                    }
                }
            } catch (\Throwable $throwable) {
                // Fall through to verified checkout metadata.
            }

            return $this->user_has_verified_memberpress_checkout_redirect($user_id);
        }

        public function handle_members_free_signup_submission()
        {
            if (empty($_POST['sffc_members_free_signup_submit'])) {
                return;
            }

            $redirect_url = isset($_POST['redirect_to'])
                ? wp_validate_redirect(esc_url_raw(wp_unslash((string) $_POST['redirect_to'])), home_url('/memberships/'))
                : home_url('/memberships/');
            $fallback_url = remove_query_arg('sffc_free_signup_error', wp_get_referer() ?: home_url('/'));

            if (
                empty($_POST['sffc_members_free_signup_nonce']) ||
                !wp_verify_nonce(sanitize_text_field(wp_unslash((string) $_POST['sffc_members_free_signup_nonce'])), 'sffc_members_free_signup')
            ) {
                wp_safe_redirect(add_query_arg('sffc_free_signup_error', 'failed', $fallback_url));
                exit;
            }

            $full_name = sanitize_text_field(wp_unslash((string) ($_POST['full_name'] ?? '')));
            $email = sanitize_email(wp_unslash((string) ($_POST['email'] ?? '')));
            $study_level = sanitize_key((string) ($_POST['study_level'] ?? ''));
            $name_parts = preg_split('/\s+/', trim($full_name));
            $first_name = trim((string) ($name_parts[0] ?? ''));
            $last_name = count((array) $name_parts) > 1 ? trim((string) end($name_parts)) : '';

            if ($first_name === '' || $email === '' || !is_email($email) || $study_level === '') {
                wp_safe_redirect(add_query_arg('sffc_free_signup_error', 'invalid', $fallback_url));
                exit;
            }

            $this->capture_membership_signup_lead([
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'study_level' => $study_level,
                'source' => 'members_free_signup',
            ]);

            wp_safe_redirect($this->get_membership_signup_redirect_url($redirect_url, $email));
            exit;
        }

        public function capture_job_post_join_email()
        {
            if (empty($_GET['sffc_capture_signup_email'])) {
                return;
            }

            $email = '';
            foreach (['user_email', 'email', 'mepr_user_email'] as $email_key) {
                if (empty($_GET[$email_key])) {
                    continue;
                }

                $email = sanitize_email(wp_unslash((string) $_GET[$email_key]));
                if ($email !== '') {
                    break;
                }
            }

            if ($email === '' || !is_email($email)) {
                return;
            }

            $expires = time() + (30 * DAY_IN_SECONDS);
            $this->set_signup_scoped_cookie('sffc_signup_email', $email, $expires);

            if (!empty($_GET['sffc_job_post_followup'])) {
                $this->schedule_job_post_join_followup_email($email);
            }
        }

