        private function schedule_job_post_join_followup_email($email)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return false;
            }

            $nonce = isset($_GET['sffc_job_post_join_nonce']) ? sanitize_text_field(wp_unslash((string) $_GET['sffc_job_post_join_nonce'])) : '';
            if ($nonce === '' || !wp_verify_nonce($nonce, 'sffc_job_post_followup')) {
                return false;
            }

            $role_title = isset($_GET['sffc_job_post_role_title']) ? sanitize_text_field(wp_unslash((string) $_GET['sffc_job_post_role_title'])) : '';
            $location = isset($_GET['sffc_job_post_location']) ? sanitize_text_field(wp_unslash((string) $_GET['sffc_job_post_location'])) : '';
            $company = isset($_GET['sffc_job_post_company']) ? sanitize_text_field(wp_unslash((string) $_GET['sffc_job_post_company'])) : '';
            $role_url = isset($_GET['sffc_job_post_url']) ? esc_url_raw(wp_unslash((string) $_GET['sffc_job_post_url'])) : '';

            if ($role_title === '') {
                $role_title = __('Finance', 'senna-finance');
            }

            $dedupe_key = 'sffc_job_post_followup_' . md5(strtolower($email) . '|' . strtolower($role_title) . '|' . strtolower($location));
            if (get_transient($dedupe_key)) {
                return true;
            }
            set_transient($dedupe_key, 1, DAY_IN_SECONDS);

            if (!class_exists('SFFC_CRM_SendGrid_Service')) {
                delete_transient($dedupe_key);
                return false;
            }

            $sendgrid = SFFC_CRM_SendGrid_Service::get_instance();
            if (!$sendgrid || !$sendgrid->is_configured()) {
                delete_transient($dedupe_key);
                return false;
            }

            $locale = $this->get_email_recipient_locale($email);
            $subject = $this->build_job_post_join_followup_subject($role_title, $location, $locale);
            $html = $this->build_job_post_join_followup_email_html($role_title, $location, $company, $locale);
            $send_at = time() + (5 * MINUTE_IN_SECONDS);

            $result = $sendgrid->send_email(
                $subject,
                $html,
                $email,
                $send_at,
                [
                    'email_type' => 'job_post_followup',
                    'role_title' => $role_title,
                    'location' => $location,
                    'company' => $company,
                    'role_url' => $role_url,
                ],
                ['job_post_followup'],
                'job_post_followup'
            );

            if (is_wp_error($result)) {
                delete_transient($dedupe_key);
                error_log('MENA Careers job post follow-up SendGrid error: ' . $result->get_error_message());
                return false;
            }

            return true;
        }

	        private function build_job_post_join_followup_subject($role_title, $location, $locale = '')
	        {
	            $location = trim(sanitize_text_field((string) $location));
	
	            if ($location !== '') {
	                return $this->is_arabic_locale($locale)
                        ? sprintf('فرص مالية مختارة في %s', $location)
                        : sprintf(__('Curated finance jobs in %s', 'senna-finance'), $location);
	            }
	
	            return $this->localize_interface_copy('Curated finance jobs', 'فرص مالية مختارة', $locale);
	        }

	        private function build_job_post_join_followup_email_html($role_title, $location, $company = '', $locale = '')
	        {
	            $role_title = trim(sanitize_text_field((string) $role_title));
	            $location = trim(sanitize_text_field((string) $location));
                $is_arabic = $this->is_arabic_locale($locale);
                $dir = $is_arabic ? 'rtl' : 'ltr';
                $align = $is_arabic ? 'right' : 'left';
	            $homepage_url = esc_url(home_url('/'));
	            $logo_url = esc_url('https://media.joinsenna.com/2026/02/senna111-1024x280.png');
	            $font = "font-family:'DM Sans',Arial,'Helvetica Neue',Helvetica,sans-serif;";
	            $green = '#047857';
	            $text = '#191919';
	            $muted = '#666666';
	            $border = '#e5e7eb';
	            $location_label = esc_html($location !== '' ? $location : $this->localize_interface_copy('your market', 'سوقك المستهدف', $locale));
		            $homepage_label = esc_html($this->localize_interface_copy('View curated finance jobs', 'اعرض الفرص المالية المختارة', $locale));
                $hello_label = esc_html($this->localize_interface_copy('Hi,', 'مرحباً،', $locale));
                $market_copy = $this->localize_interface_copy('MENA Careers helps private equity candidates skip job boards with curated role lists for ', 'يساعدك سنّا على تجاوز ضوضاء منصات الوظائف من خلال قوائم مختارة لفرص ', $locale);
