        private function get_signup_email_prefill_value()
        {
            foreach (['user_email', 'email', 'mepr_user_email'] as $email_key) {
                if (empty($_GET[$email_key])) {
                    continue;
                }

                $query_email = sanitize_email(wp_unslash((string) $_GET[$email_key]));
                if ($query_email !== '' && is_email($query_email)) {
                    return $query_email;
                }
            }

            if (is_user_logged_in()) {
                $current_user = wp_get_current_user();
                if ($current_user instanceof WP_User && !empty($current_user->user_email)) {
                    return sanitize_email((string) $current_user->user_email);
                }
            }

            $signup_email = $this->get_valid_signup_cookie_value('sffc_signup_email');
            if ($signup_email !== '') {
                return sanitize_email($signup_email);
            }

            return '';
        }

        public function ajax_sync_signup_prefill()
        {
            check_ajax_referer('sffc_sync_signup_prefill', 'nonce');

            $payload = [
                'email' => isset($_POST['email']) ? sanitize_email(wp_unslash((string) $_POST['email'])) : '',
                'first_name' => isset($_POST['first_name']) ? sanitize_text_field(wp_unslash((string) $_POST['first_name'])) : '',
                'last_name' => isset($_POST['last_name']) ? sanitize_text_field(wp_unslash((string) $_POST['last_name'])) : '',
                'mepr_job_id' => isset($_POST['mepr_job_id']) ? absint($this->parse_cv_match_context_job_id(wp_unslash((string) $_POST['mepr_job_id']))) : 0,
                'study_level' => isset($_POST['study_level']) ? sanitize_key(wp_unslash((string) $_POST['study_level'])) : '',
                'account_type' => isset($_POST['account_type']) ? sanitize_key(wp_unslash((string) $_POST['account_type'])) : '',
                'finance_interest' => isset($_POST['finance_interest']) ? array_values(array_filter(array_map('sanitize_text_field', (array) wp_unslash($_POST['finance_interest'])))) : [],
                'seniority_level' => isset($_POST['seniority_level']) ? array_values(array_filter(array_map('sanitize_text_field', (array) wp_unslash($_POST['seniority_level'])))) : [],
                'support_need' => isset($_POST['support_need']) ? array_values(array_filter(array_map('sanitize_text_field', (array) wp_unslash($_POST['support_need'])))) : [],
            ];

            if ($payload['email'] !== '' && !is_email($payload['email'])) {
                wp_send_json_error(['message' => __('Please enter a valid email address.', 'senna-finance')], 400);
            }

            $this->persist_signup_prefill_state($payload, 30 * DAY_IN_SECONDS);
            wp_send_json_success(['stored' => true]);
        }

        public function ajax_member_basic_signup_currency()
        {
            check_ajax_referer('sffc_member_basic_signup_currency', 'nonce');

            $timezone = isset($_POST['timezone']) ? sanitize_text_field(wp_unslash((string) $_POST['timezone'])) : '';
            $locale = isset($_POST['locale']) ? sanitize_text_field(wp_unslash((string) $_POST['locale'])) : '';

            $default_currency = strtoupper(get_option('currency_detector_base_currency', 'USD'));
            $supported = get_option('currency_detector_supported_currencies', array('USD', 'EUR', 'GBP'));
            $supported = array_map('strtoupper', (array) $supported);

            $detected_currency = $default_currency;
            $detector = $this->get_currency_location_detector();
            if ($detector && method_exists($detector, 'detect_currency_from_browser')) {
                $detected = strtoupper((string) $detector->detect_currency_from_browser($timezone, $locale));
                if ($detected !== '' && in_array($detected, $supported, true)) {
                    $detected_currency = $detected;
                }
            }

            $expires = time() + (30 * DAY_IN_SECONDS);
            setcookie('currency_detector_currency', $detected_currency, $expires, COOKIEPATH ?: '/', COOKIE_DOMAIN ?: '', is_ssl(), false);
            $_COOKIE['currency_detector_currency'] = $detected_currency;

            if ($timezone !== '') {
                setcookie('currency_detector_timezone', $timezone, $expires, COOKIEPATH ?: '/', COOKIE_DOMAIN ?: '', is_ssl(), false);
                $_COOKIE['currency_detector_timezone'] = $timezone;
            }

            $plans = $this->get_basic_member_signup_plans_data($detected_currency);
            $payload = [];
            foreach ($plans as $plan) {
                $payload[] = [
                    'id' => (string) ($plan['id'] ?? ''),
                    'option_label' => (string) ($plan['option_label'] ?? ''),
                    'price' => (string) ($plan['price'] ?? ''),
                    'signup_path' => (string) ($plan['signup_path'] ?? ''),
                ];
            }

            wp_send_json_success([
                'currency' => $detected_currency,
                'plans' => $payload,
            ]);
        }

        public function ajax_apply_chat_membership_panel()
        {
            check_ajax_referer('sffc_apply_chat_membership_panel', 'nonce');

            $selection = isset($_POST['account_type']) ? sanitize_key(wp_unslash((string) $_POST['account_type'])) : 'platform';
            $plans = $this->get_apply_chat_membership_plans();
            $selected_plan = null;

            foreach ($plans as $plan) {
                if (($plan['account_type'] ?? '') === $selection) {
                    $selected_plan = $plan;
                    break;
                }
            }

            if ($selected_plan === null && !empty($plans)) {
                $selected_plan = $plans[0];
            }

            if ($selected_plan === null) {
                wp_send_json_error([
                    'message' => __('Membership options are unavailable right now.', 'senna-finance'),
                ], 404);
            }

            wp_send_json_success([
                'account_type' => (string) ($selected_plan['account_type'] ?? 'platform'),
                'html' => $this->render_apply_chat_membership_panel((array) $selected_plan),
            ]);
        }

