        public function ajax_member_pricing_track_external_apply()
        {
            check_ajax_referer('sffc_member_pricing_signup', 'nonce');

            $route = isset($_POST['route']) ? sanitize_key(wp_unslash((string) $_POST['route'])) : '';
            $variant = isset($_POST['variant']) ? sanitize_key(wp_unslash((string) $_POST['variant'])) : '';
            $job_id = isset($_POST['job_id']) ? absint($_POST['job_id']) : 0;
            $job_title = isset($_POST['job_title']) ? sanitize_text_field(wp_unslash((string) $_POST['job_title'])) : '';
            $email = isset($_POST['email']) ? sanitize_email(wp_unslash((string) $_POST['email'])) : '';
            $apply_url = isset($_POST['apply_url']) ? esc_url_raw(wp_unslash((string) $_POST['apply_url'])) : '';

            if ($route === '') {
                $route = 'external_apply';
            }
            if ($variant === '') {
                $variant = 'job';
            }
            if ($email !== '' && !is_email($email)) {
                $email = '';
            }
            if ($apply_url !== '' && !wp_http_validate_url($apply_url)) {
                $apply_url = '';
            }

            $event = [
                'timestamp' => current_time('mysql'),
                'route' => $route,
                'variant' => $variant,
                'job_id' => $job_id,
                'job_title' => $job_title,
                'apply_url' => $apply_url,
                'email' => $email,
                'user_id' => get_current_user_id(),
            ];

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_crm_member_signup_events';
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name));

            if ($table_exists === $table_name) {
                $wpdb->insert(
                    $table_name,
                    [
                        'event_type' => $route,
                        'variant' => $variant,
                        'route' => $route,
                        'job_id' => $job_id,
                        'job_title' => $job_title,
                        'apply_url' => $apply_url,
                        'email' => $email,
                        'user_id' => (int) $event['user_id'],
                        'metadata' => wp_json_encode([
                            'source' => 'member_pricing_signup',
                        ]),
                        'created_at' => $event['timestamp'],
                    ],
                    [
                        '%s',
                        '%s',
                        '%s',
                        '%d',
                        '%s',
                        '%s',
                        '%s',
                        '%d',
                        '%s',
                        '%s',
                    ]
                );
            } else {
                $option_key = 'sffc_member_signup_external_apply_events';
                $events = get_option($option_key, []);
                if (!is_array($events)) {
                    $events = [];
                }
                $events[] = $event;
                if (count($events) > 100) {
                    $events = array_slice($events, -100);
                }
                update_option($option_key, $events, false);
            }

            if (!empty($event['user_id'])) {
                update_user_meta((int) $event['user_id'], 'sffc_member_signup_last_external_apply', $event);
            }

            wp_send_json_success([
                'logged' => true,
            ]);
        }

        public function ajax_load_job_member_signup_overlay()
        {
            check_ajax_referer('sffc_member_pricing_signup', 'nonce');

            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $wp_post_id = isset($_POST['wp_post_id']) ? absint($_POST['wp_post_id']) : 0;
            $crm_post_id = isset($_POST['crm_post_id']) ? absint($_POST['crm_post_id']) : 0;
            $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id($jobs_post_id, $wp_post_id, $crm_post_id);

            if ($jobs_post_id <= 0) {
                wp_send_json_error([
                    'message' => __('A valid job is required.', 'senna-finance'),
                ], 422);
            }

            $job_item = $this->get_crm_reddit_jobs_item($jobs_post_id);
            $job_post = get_post($jobs_post_id);
            if (empty($job_item) || !$job_post instanceof WP_Post || $job_post->post_type !== 'jobs') {
                wp_send_json_error([
                    'message' => __('That job is unavailable right now.', 'senna-finance'),
                ], 404);
            }

            $html = $this->render_crm_jobs_member_signup([
                'jobs_post_id' => $jobs_post_id,
                'presentation' => 'overlay',
            ]);

            if (trim((string) $html) === '') {
                wp_send_json_error([
                    'message' => __('We could not load this signup flow right now.', 'senna-finance'),
                ], 500);
            }

            wp_send_json_success([
                'html' => $html,
            ]);
        }

        public function ajax_member_pricing_join_job_community()
        {
            check_ajax_referer('sffc_member_pricing_signup', 'nonce');

            $email = isset($_POST['email']) ? sanitize_email(wp_unslash((string) $_POST['email'])) : '';
            $jobs_post_id = isset($_POST['jobs_post_id']) ? absint($_POST['jobs_post_id']) : 0;
            $finance_interest = isset($_POST['finance_interest']) && is_array($_POST['finance_interest'])
                ? array_values(array_filter(array_map('sanitize_key', wp_unslash((array) $_POST['finance_interest']))))
                : [];
            $seniority_level = isset($_POST['seniority_level']) && is_array($_POST['seniority_level'])
                ? array_values(array_filter(array_map('sanitize_key', wp_unslash((array) $_POST['seniority_level']))))
                : [];
            $support_need = isset($_POST['support_need']) && is_array($_POST['support_need'])
                ? array_values(array_filter(array_map('sanitize_key', wp_unslash((array) $_POST['support_need']))))
                : [];

            if ($email === '' || !is_email($email)) {
                wp_send_json_error([
                    'message' => __('Enter a valid email address to continue.', 'senna-finance'),
                ], 422);
            }

            if (is_user_logged_in()) {
                wp_send_json_success([
                    'status' => 'logged_in',
                    'redirect' => home_url('/memberships/'),
                ]);
            }

            if (email_exists($email)) {
                $this->stop_membership_signup_reminders($email);
                wp_send_json_success([
                    'status' => 'exists',
                    'redirect' => home_url('/memberships/'),
                ]);
            }

            $name_parts = $this->infer_name_parts_from_email($email);
            $this->capture_membership_signup_lead([
                'email' => $email,
                'first_name' => (string) ($name_parts['first_name'] ?? ''),
                'last_name' => (string) ($name_parts['last_name'] ?? ''),
                'finance_interest' => $finance_interest,
                'seniority_level' => $seniority_level,
                'support_need' => $support_need,
                'jobs_post_id' => $jobs_post_id,
                'source' => 'job_member_signup',
            ]);

            wp_send_json_success([
                'status' => 'lead_captured',
                'redirect' => home_url('/memberships/'),
            ]);
        }

