        private function get_member_pricing_signup_locale()
        {
            $country = $this->detect_member_pricing_country_code();
            if ($country === 'FR') {
                return 'fr_FR';
            }
            if ($country === 'ES') {
                return 'es_ES';
            }
            if ($country === 'IT') {
                return 'it_IT';
            }
            if ($country === 'DE') {
                return 'de_DE';
            }

            $language_header = isset($_SERVER['HTTP_ACCEPT_LANGUAGE'])
                ? sanitize_text_field(wp_unslash((string) $_SERVER['HTTP_ACCEPT_LANGUAGE']))
                : '';
            $primary_locale = $this->extract_primary_locale($language_header ?: get_locale());
            $primary_locale = strtolower(str_replace('_', '-', (string) $primary_locale));

            if ($primary_locale === 'fr-fr') {
                return 'fr_FR';
            }
            if ($primary_locale === 'es-es') {
                return 'es_ES';
            }
            if ($primary_locale === 'it-it') {
                return 'it_IT';
            }
            if ($primary_locale === 'de-de') {
                return 'de_DE';
            }

            return str_replace('-', '_', (string) get_locale());
        }

        private function detect_member_pricing_country_code()
        {
            $header_keys = [
                'HTTP_CF_IPCOUNTRY',
                'HTTP_CLOUDFRONT_VIEWER_COUNTRY',
                'HTTP_X_VERCEL_IP_COUNTRY',
                'HTTP_X_APPENGINE_COUNTRY',
                'HTTP_X_COUNTRY_CODE',
                'HTTP_X_GEOIP_COUNTRY_CODE',
                'HTTP_X_FORWARDED_COUNTRY',
                'HTTP_X_COUNTRY',
                'HTTP_GEOIP_COUNTRY_CODE',
                'GEOIP_COUNTRY_CODE',
                'MM_COUNTRY_CODE',
            ];

            foreach ($header_keys as $key) {
                if (empty($_SERVER[$key])) {
                    continue;
                }
                $country = strtoupper(substr(sanitize_text_field(wp_unslash((string) $_SERVER[$key])), 0, 2));
                if (preg_match('/^[A-Z]{2}$/', $country)) {
                    return $country;
                }
            }

            if (isset($_COOKIE['currency_detector_currency'])) {
                $currency = strtoupper(sanitize_text_field(wp_unslash((string) $_COOKIE['currency_detector_currency'])));
                $language_header = isset($_SERVER['HTTP_ACCEPT_LANGUAGE'])
                    ? strtolower(sanitize_text_field(wp_unslash((string) $_SERVER['HTTP_ACCEPT_LANGUAGE'])))
                    : '';
                if ($currency === 'EUR' && strpos($language_header, 'fr-fr') !== false) {
                    return 'FR';
                }
            }

            return '';
        }

        private function infer_name_parts_from_email($email)
        {
            $email = sanitize_email((string) $email);
            $local_part = strtolower((string) current(explode('@', $email)));
            $tokens = preg_split('/[._+\-\d]+/', $local_part);
            $tokens = array_values(array_filter(array_map('trim', (array) $tokens)));

            $first_name = '';
            $last_name = '';

            if (!empty($tokens[0])) {
                $first_name = ucfirst(sanitize_text_field((string) $tokens[0]));
            }

            if (count($tokens) > 1) {
                $last_name = ucfirst(sanitize_text_field((string) end($tokens)));
            }

            if ($first_name === '') {
                $first_name = __('MENA Careers', 'senna-finance');
            }

            return [
                'first_name' => $first_name,
                'last_name' => $last_name,
            ];
        }

