        private function translate_member_signup_plan_name($name, $locale = 'en_US')
        {
            $clean = trim((string) $name);
            $key = strtolower(preg_replace('/\s+/', ' ', $clean));
            $locale = strtolower(str_replace('-', '_', (string) $locale));
            $maps = [
                'fr_fr' => [
                    'platform access only' => 'Accès plateforme',
                    'platform + mentorship' => 'Plateforme + mentorat',
                    'platform and mentorship' => 'Plateforme + mentorat',
                    'mentorship' => 'Mentorat',
                    'basic' => 'Essentiel',
                    'starter' => 'Essentiel',
                    'pro' => 'Pro',
                    'premium' => 'Premium',
                    'elite' => 'Elite',
                ],
                'es_es' => [
                    'platform access only' => 'Acceso a la plataforma',
                    'platform + mentorship' => 'Plataforma + mentoría',
                    'platform and mentorship' => 'Plataforma + mentoría',
                    'mentorship' => 'Mentoría',
                    'basic' => 'Esencial',
                    'starter' => 'Esencial',
                ],
                'it_it' => [
                    'platform access only' => 'Accesso alla piattaforma',
                    'platform + mentorship' => 'Piattaforma + mentoring',
                    'platform and mentorship' => 'Piattaforma + mentoring',
                    'mentorship' => 'Mentoring',
                    'basic' => 'Essenziale',
                    'starter' => 'Essenziale',
                ],
                'de_de' => [
                    'platform access only' => 'Plattformzugang',
                    'platform + mentorship' => 'Plattform + Mentoring',
                    'platform and mentorship' => 'Plattform + Mentoring',
                    'mentorship' => 'Mentoring',
                    'basic' => 'Basis',
                    'starter' => 'Basis',
                ],
            ];
            $map = $maps[$locale] ?? [];

            return $map[$key] ?? $clean;
        }

        private function translate_member_signup_feature($text, $locale = 'en_US')
        {
            $original = trim((string) $text);
            if ($original === '') {
                return '';
            }

            $locale = strtolower(str_replace('-', '_', (string) $locale));
            if ($locale === 'en_us') {
                return $original;
            }

            $key = strtolower(preg_replace('/\s+/', ' ', $original));
            $maps = [
                'fr_fr' => [
                    'live instant daily recruiter matches + alerts + auto apply' => 'Matchs recruteurs en direct, alertes quotidiennes et candidatures facilitées',
                    '4 1 hour mentorship calls every month' => '4 sessions de mentorat d’une heure chaque mois',
                    'unlimited industry job newsletters' => 'Newsletters emploi illimitées par secteur',
                    '50 weekly job to cv scan requests' => '50 analyses hebdomadaires entre votre CV et les offres',
                    '60 application pack requests' => '60 demandes de dossiers de candidature',
                    'find top internships' => 'Trouvez les meilleurs stages',
                    'interview prep' => 'Préparation aux entretiens',
                    'get mentored' => 'Accès à des mentors',
                    'finance community' => 'Communauté finance',
                    'one-click matched applications, tailored materials, and tracked updates.' => 'Des candidatures mieux ciblées, des supports adaptés et un suivi clair.',
                    'monthly' => 'Mensuel',
                    'annual' => 'Annuel',
                    'per month' => 'par mois',
                    'per year' => 'par an',
                ],
                'es_es' => [
                    'monthly' => 'Mensual',
                    'annual' => 'Anual',
                    'per month' => 'por mes',
                    'per year' => 'por año',
                ],
                'it_it' => [
                    'monthly' => 'Mensile',
                    'annual' => 'Annuale',
                    'per month' => 'al mese',
                    'per year' => 'all’anno',
                ],
                'de_de' => [
                    'monthly' => 'Monatlich',
                    'annual' => 'Jährlich',
                    'per month' => 'pro Monat',
                    'per year' => 'pro Jahr',
                ],
            ];
            $map = $maps[$locale] ?? [];

            if (isset($map[$key])) {
                return $map[$key];
            }

            $replacements_by_locale = [
                'fr_fr' => [
                    '/\brecruiter matches\b/i' => 'matchs recruteurs',
                    '/\binterview prep\b/i' => 'préparation aux entretiens',
                    '/\bmentorship\b/i' => 'mentorat',
                    '/\bapplication packs?\b/i' => 'dossiers de candidature',
                    '/\bcover letters?\b/i' => 'lettres de motivation',
                    '/\bCV scans?\b/i' => 'analyses de CV',
                    '/\binternships?\b/i' => 'stages',
                    '/\balerts?\b/i' => 'alertes',
                    '/\bmonthly\b/i' => 'mensuel',
                    '/\bannual\b/i' => 'annuel',
                ],
                'es_es' => [
                    '/\bmentorship\b/i' => 'mentoría',
                    '/\balerts?\b/i' => 'alertas',
                    '/\bmonthly\b/i' => 'mensual',
                    '/\bannual\b/i' => 'anual',
                ],
                'it_it' => [
                    '/\bmentorship\b/i' => 'mentoring',
                    '/\balerts?\b/i' => 'alert',
                    '/\bmonthly\b/i' => 'mensile',
                    '/\bannual\b/i' => 'annuale',
                ],
                'de_de' => [
                    '/\bmentorship\b/i' => 'Mentoring',
                    '/\balerts?\b/i' => 'Benachrichtigungen',
                    '/\bmonthly\b/i' => 'monatlich',
                    '/\bannual\b/i' => 'jährlich',
                ],
            ];
            $replacements = $replacements_by_locale[$locale] ?? [];

            $translated = $original;
            foreach ($replacements as $pattern => $replacement) {
                $translated = preg_replace($pattern, $replacement, $translated);
            }

            return $translated ?: $original;
        }

        public function render_subscription_pricing($atts = [])
        {
            wp_enqueue_style(
                'sffc-subscription-pricing',
                SFFC_PLUGIN_URL . 'assets/css/crm/subscription-pricing.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-subscription-pricing',
                SFFC_PLUGIN_URL . 'assets/js/crm/subscription-pricing.js',
                ['jquery'],
                SFFC_VERSION,
                true
            );

            $plans = $this->get_subscription_plans();
            $membership_url = $this->get_canonical_membership_url();
            $login_target = is_user_logged_in() ? home_url('/my-account/') : wp_login_url(get_permalink());

            $normalized_plans = [];
            foreach ($plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $normalized_plan = [
                    'name' => $name,
                    'slug' => (string) ($plan['slug'] ?? sanitize_title($name)),
                    'price' => (string) ($plan['price'] ?? ''),
                    'price_amount' => isset($plan['price_amount']) ? (float) $plan['price_amount'] : 0.0,
                    'price_currency' => (string) ($plan['price_currency'] ?? ''),
                    'billing_cycle' => (string) ($plan['billing_cycle'] ?? ''),
                    'tagline' => (string) ($plan['tagline'] ?? ''),
                    'audience' => (string) ($plan['audience'] ?? ''),
                    'features' => $features,
                    'shortcode' => (string) ($plan['shortcode'] ?? ''),
                    'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : $membership_url,
                    'featured_signup' => !empty($plan['featured_signup']),
                    'is_annual' => !empty($plan['is_annual']),
                    'cycle' => !empty($plan['is_annual']) ? 'annual' : 'monthly',
                    'memberpress_product_id' => $this->extract_memberpress_product_id_from_shortcode((string) ($plan['shortcode'] ?? '')),
                ];

                $display_price = $this->format_plan_price_amount($normalized_plan) ?: (string) ($normalized_plan['price'] ?? '');
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', $display_price);
                $amount_label = $display_price;
                $cycle_label = '';
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                    $cycle_label = sprintf(
                        /* translators: %s billing cadence label */
                        __('per %s', 'senna-finance'),
                        trim((string) $matches[2])
                    );
                } elseif (!empty($normalized_plan['billing_cycle'])) {
                    $cycle_label = sprintf(
                        __('per %s', 'senna-finance'),
                        trim((string) $normalized_plan['billing_cycle'])
                    );
                }

                $normalized_plan['display_price'] = $display_price;
                $normalized_plan['amount_label'] = $amount_label;
                $normalized_plan['cycle_label'] = $cycle_label;
                $normalized_plans[] = $normalized_plan;
            }

            $plans_by_cycle = [
                'monthly' => [],
                'annual' => [],
            ];

            foreach ($normalized_plans as $plan) {
                $plans_by_cycle[$plan['cycle']][] = $plan;
            }

            $available_cycles = array_values(array_filter(['monthly', 'annual'], static function ($cycle) use ($plans_by_cycle) {
                return !empty($plans_by_cycle[$cycle]);
            }));

            if (empty($available_cycles)) {
                return '';
            }

            $default_cycle = in_array('monthly', $available_cycles, true) ? 'monthly' : $available_cycles[0];
            $default_plan_by_cycle = [];
            foreach ($available_cycles as $cycle) {
                $cycle_plans = $plans_by_cycle[$cycle];
                $default_plan = null;
                foreach ($cycle_plans as $candidate_plan) {
                    if (!empty($candidate_plan['featured_signup'])) {
                        $default_plan = $candidate_plan;
                        break;
                    }
                }
                if ($default_plan === null) {
                    $middle_index = (int) floor((count($cycle_plans) - 1) / 2);
                    $default_plan = $cycle_plans[$middle_index] ?? $cycle_plans[0];
                }
                $default_plan_by_cycle[$cycle] = $default_plan;
            }

            ob_start();
        ?>
            <section class="sffc-subscription-pricing" data-subscription-pricing data-default-cycle="<?php echo esc_attr($default_cycle); ?>">
                <div class="sffc-subscription-pricing__shell">
                    <div class="sffc-subscription-pricing__chrome">
                        <span class="sffc-subscription-pricing__mark" aria-hidden="true">
                            <span class="sffc-subscription-pricing__mark-s">S</span>
                            <span class="sffc-subscription-pricing__mark-dot"></span>
                        </span>
                        <a class="sffc-subscription-pricing__login" href="<?php echo esc_url($login_target); ?>">
                            <?php esc_html_e('Log in', 'senna-finance'); ?>
                        </a>
                    </div>

                    <header class="sffc-subscription-pricing__header">
                        <h1><?php esc_html_e('Choose the right plan for you', 'senna-finance'); ?></h1>
                        <?php if (count($available_cycles) > 1) : ?>
                            <div class="sffc-subscription-pricing__billing" role="tablist" aria-label="<?php esc_attr_e('Billing cycle', 'senna-finance'); ?>">
                                <?php foreach ($available_cycles as $cycle) : ?>
                                    <button
                                        type="button"
                                        class="sffc-subscription-pricing__billing-toggle<?php echo $cycle === $default_cycle ? ' is-active' : ''; ?>"
                                        data-pricing-cycle-toggle="<?php echo esc_attr($cycle); ?>"
                                        role="tab"
                                        aria-selected="<?php echo $cycle === $default_cycle ? 'true' : 'false'; ?>">
                                        <?php echo esc_html('annual' === $cycle ? __('Annual billing', 'senna-finance') : __('Monthly billing', 'senna-finance')); ?>
                                    </button>
                                <?php endforeach; ?>
                            </div>
                        <?php endif; ?>
                    </header>

                    <?php foreach ($available_cycles as $cycle) :
                        $cycle_plans = $plans_by_cycle[$cycle];
                        $cycle_default_plan = $default_plan_by_cycle[$cycle] ?? ($cycle_plans[0] ?? null);
                    ?>
                        <div class="sffc-subscription-pricing__grid<?php echo $cycle === $default_cycle ? ' is-active' : ''; ?>" data-pricing-grid="<?php echo esc_attr($cycle); ?>" <?php echo $cycle === $default_cycle ? '' : 'hidden'; ?>>
                            <?php foreach ($cycle_plans as $plan) :
                                $is_active = !empty($cycle_default_plan['slug']) && $cycle_default_plan['slug'] === $plan['slug'];
                                $badge_label = !empty($plan['featured_signup']) ? __('Most popular', 'senna-finance') : '';
                                $summary_copy = $plan['tagline'] ?: $plan['audience'];
                            ?>
                                <article class="sffc-subscription-pricing__card<?php echo $is_active ? ' is-active' : ''; ?><?php echo !empty($plan['featured_signup']) ? ' is-featured' : ''; ?>" data-pricing-card data-plan-slug="<?php echo esc_attr($plan['slug']); ?>" data-plan-cycle="<?php echo esc_attr($cycle); ?>" data-plan-name="<?php echo esc_attr($plan['name']); ?>" data-plan-price="<?php echo esc_attr($plan['display_price']); ?>" data-plan-billing="<?php echo esc_attr($plan['billing_cycle']); ?>" data-plan-copy="<?php echo esc_attr($summary_copy); ?>">
                                    <?php if ($badge_label) : ?>
                                        <span class="sffc-subscription-pricing__badge"><?php echo esc_html($badge_label); ?></span>
                                    <?php endif; ?>

                                    <div class="sffc-subscription-pricing__card-head">
                                        <h2><?php echo esc_html($plan['name']); ?></h2>
                                        <div class="sffc-subscription-pricing__price-row">
                                            <span class="sffc-subscription-pricing__price"><?php echo esc_html($plan['amount_label']); ?></span>
                                            <?php if (!empty($plan['cycle_label'])) : ?>
                                                <span class="sffc-subscription-pricing__cycle"><?php echo esc_html($plan['cycle_label']); ?></span>
                                            <?php endif; ?>
                                        </div>
                                    </div>

                                    <button type="button" class="sffc-subscription-pricing__cta" data-pricing-select>
                                        <?php esc_html_e('Get started', 'senna-finance'); ?>
                                    </button>

                                    <div class="sffc-subscription-pricing__divider"></div>

                                    <div class="sffc-subscription-pricing__features">
                                        <h3><?php esc_html_e('Features', 'senna-finance'); ?></h3>
                                        <?php if (!empty($summary_copy)) : ?>
                                            <p><?php echo esc_html($summary_copy); ?></p>
                                        <?php endif; ?>
                                        <?php if (!empty($plan['features'])) : ?>
                                            <ul>
                                                <?php foreach (array_slice($plan['features'], 0, 6) as $feature) : ?>
                                                    <li><?php echo esc_html($feature); ?></li>
                                                <?php endforeach; ?>
                                            </ul>
                                        <?php endif; ?>
                                    </div>
                                </article>
                            <?php endforeach; ?>
                        </div>
                    <?php endforeach; ?>

