                                <p data-pricing-summary-copy><?php esc_html_e('Choose a membership plan above to continue to checkout.', 'senna-finance'); ?></p>
                            </div>
                            <strong data-pricing-summary-price></strong>
                        </div>
                        <div class="sffc-subscription-pricing__checkout-body">
                            <?php foreach ($normalized_plans as $plan) : ?>
                                <div class="sffc-subscription-pricing__checkout-shell" data-pricing-shell="<?php echo esc_attr($plan['slug']); ?>" hidden>
                                    <?php if (!empty($plan['shortcode'])) : ?>
                                        <?php echo do_shortcode($plan['shortcode']); ?>
                                    <?php else : ?>
                                        <div class="sffc-subscription-pricing__fallback">
                                            <p><?php esc_html_e('This plan will continue through secure checkout.', 'senna-finance'); ?></p>
                                            <a href="<?php echo esc_url($plan['url']); ?>" class="sffc-subscription-pricing__fallback-link"><?php esc_html_e('Continue to checkout', 'senna-finance'); ?></a>
                                        </div>
                                    <?php endif; ?>
                                </div>
                            <?php endforeach; ?>
                        </div>
                    </div>
                </div>
            </section>
        <?php
            return ob_get_clean();
        }

        public function render_crm_cv_match_pricing($atts = [])
