            $subscription_pricing_js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/subscription-pricing.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/subscription-pricing.js') : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css',
                [],
                $reddit_feed_css_version
            );

            wp_enqueue_style(
                'sffc-crm-cv-match-studio',
                SFFC_PLUGIN_URL . 'assets/css/crm/cv-match-studio.css',
                ['sffc-crm-reddit-feed'],
                $cv_match_css_version
            );

            wp_enqueue_script(
                'pdfjs',
                'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
                [],
                '3.11.174',
                true
            );

            wp_enqueue_script(
                'mammoth',
                'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js',
                [],
                '1.6.0',
                true
            );

            wp_enqueue_script(
                'sffc-crm-reddit-feed',
                SFFC_PLUGIN_URL . 'assets/js/crm/reddit-feed.js',
                [],
                $reddit_feed_js_version,
                true
            );

            wp_enqueue_script(
                'sffc-crm-cv-match-studio',
                SFFC_PLUGIN_URL . 'assets/js/crm/cv-match-studio.js',
                ['pdfjs', 'mammoth', 'sffc-crm-reddit-feed'],
                $cv_match_js_version,
                true
            );

            wp_enqueue_script(
                'sffc-subscription-pricing',
                SFFC_PLUGIN_URL . 'assets/js/crm/subscription-pricing.js',
                ['jquery'],
                $subscription_pricing_js_version,
                true
            );

            wp_localize_script('sffc-crm-cv-match-studio', 'sffcCrmCvMatchStudio', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_nonce'),
                'accountNonce' => wp_create_nonce('sffc_crm_reddit_account'),
                'outreachNonce' => wp_create_nonce('sffc_crm_reddit_generate_outreach'),
                'materialNonce' => wp_create_nonce('sffc_crm_reddit_material_generate'),
                'cvGapUrl' => home_url('/cv-gap-analyser/'),
                'pdfWorker' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
                'membershipUrl' => $this->get_crm_reddit_membership_url(),
                'loggedIn' => is_user_logged_in(),
                'hasPremiumAccess' => is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access(),
                'pinnedMailboxKeys' => is_user_logged_in() ? $this->get_cv_match_studio_jobs_mailbox_pinned_keys_for_user(get_current_user_id()) : [],
                'defaultMailboxPinKey' => !is_user_logged_in() ? $this->get_cv_match_studio_jobs_mailbox_default_pin_key($this->get_cv_match_studio_jobs_mailbox_items(0, [], 9)) : '',
                'firstName' => '',
                'initialCvText' => '',
                'cvSourceOptions' => [],
                'initialCvSource' => '',
                'initialAtsState' => [],
                'currentUser' => [
                    'displayName' => is_user_logged_in() ? (string) wp_get_current_user()->display_name : '',
                    'email' => is_user_logged_in() ? (string) wp_get_current_user()->user_email : '',
                ],
                'scanPreviewItems' => $this->get_cv_match_studio_scan_preview_items(),
                'labels' => [
                    'scanButton' => __('Scan my CV', 'senna-finance'),
                ],
            ]);

            $membership_url = $this->get_canonical_membership_url();
            $plans = $this->get_subscription_plans();
            $landing_preview_data = $this->get_cv_match_studio_landing_preview_data();
            $landing_preview_roles = !empty($landing_preview_data['roles']) && is_array($landing_preview_data['roles'])
                ? $landing_preview_data['roles']
                : [];
            $landing_preview_recruiters = !empty($landing_preview_data['recruiters']) && is_array($landing_preview_data['recruiters'])
                ? $landing_preview_data['recruiters']
                : [];

            $normalized_plans = [];
            foreach ($plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $normalized_plan = [
                    'name' => $name,
                    'slug' => (string) ($plan['slug'] ?? sanitize_title($name)),
                    'price' => (string) ($plan['price'] ?? ''),
                    'price_amount' => isset($plan['price_amount']) ? (float) $plan['price_amount'] : 0.0,
                    'price_currency' => (string) ($plan['price_currency'] ?? ''),
                    'billing_cycle' => (string) ($plan['billing_cycle'] ?? ''),
                    'tagline' => (string) ($plan['tagline'] ?? ''),
                    'audience' => (string) ($plan['audience'] ?? ''),
                    'features' => $features,
                    'shortcode' => (string) ($plan['shortcode'] ?? ''),
                    'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : $membership_url,
                    'featured_signup' => !empty($plan['featured_signup']),
                    'is_annual' => !empty($plan['is_annual']),
                    'cycle' => !empty($plan['is_annual']) ? 'annual' : 'monthly',
                ];

                $display_price = $this->format_plan_price_amount($normalized_plan) ?: (string) ($normalized_plan['price'] ?? '');
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', $display_price);
                $amount_label = $display_price;
                $cycle_label = '';
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                    $cycle_label = sprintf(__('per %s', 'senna-finance'), trim((string) $matches[2]));
                } elseif (!empty($normalized_plan['billing_cycle'])) {
                    $cycle_label = sprintf(__('per %s', 'senna-finance'), trim((string) $normalized_plan['billing_cycle']));
                }

                $normalized_plan['display_price'] = $display_price;
                $normalized_plan['amount_label'] = $amount_label;
                $normalized_plan['cycle_label'] = $cycle_label;
                $normalized_plans[] = $normalized_plan;
            }

            $plans_by_cycle = ['monthly' => [], 'annual' => []];
            foreach ($normalized_plans as $plan) {
                $plans_by_cycle[$plan['cycle']][] = $plan;
            }

            $active_memberpress_product_ids = is_user_logged_in() ? $this->get_active_memberpress_product_ids(get_current_user_id()) : [];
            $has_existing_memberpress_plan = !empty($active_memberpress_product_ids);

            $available_cycles = array_values(array_filter(['monthly', 'annual'], static function ($cycle) use ($plans_by_cycle) {
                return !empty($plans_by_cycle[$cycle]);
            }));
            $default_cycle = in_array('monthly', $available_cycles, true) ? 'monthly' : (!empty($available_cycles[0]) ? $available_cycles[0] : 'monthly');
            $default_plan_by_cycle = [];
            foreach ($available_cycles as $cycle) {
                $cycle_plans = $plans_by_cycle[$cycle];
                $default_plan = null;
                foreach ($cycle_plans as $candidate_plan) {
                    if (!empty($candidate_plan['featured_signup'])) {
                        $default_plan = $candidate_plan;
                        break;
                    }
                }
                if ($default_plan === null && !empty($cycle_plans)) {
                    $middle_index = (int) floor((count($cycle_plans) - 1) / 2);
                    $default_plan = $cycle_plans[$middle_index] ?? $cycle_plans[0];
                }
                if ($default_plan !== null) {
                    $default_plan_by_cycle[$cycle] = $default_plan;
                }
            }

            $active_plan = $default_plan_by_cycle[$default_cycle] ?? (!empty($normalized_plans[0]) ? $normalized_plans[0] : null);
            $plan_highlights = [
                [
                    'title' => __('Live role matching', 'senna-finance'),
                    'copy' => __('Rank live private equity roles by fit, location, and recruiter context.', 'senna-finance'),
                ],
                [
                    'title' => __('Application packs', 'senna-finance'),
                    'copy' => __('Get CV templates, cover letters, interview questions, and hiring guides.', 'senna-finance'),
                ],
                [
                    'title' => __('Recruiter routes', 'senna-finance'),
                    'copy' => __('See the recruiter paths attached to live mandates before you reach out.', 'senna-finance'),
                ],
                [
                    'title' => __('Positioning review', 'senna-finance'),
                    'copy' => __('Spot blockers, ATS gaps, and what private equity hiring teams expect to see.', 'senna-finance'),
                ],
            ];

            ob_start();
            ?>
