        public function render_subscription_onboarding($atts = [])
        {
            wp_enqueue_style(
                'sffc-subscription-onboarding',
                SFFC_PLUGIN_URL . 'assets/css/crm/subscription-onboarding.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-subscription-onboarding',
                SFFC_PLUGIN_URL . 'assets/js/crm/subscription-onboarding.js',
                ['jquery'],
                SFFC_VERSION,
                true
            );

            $plans = $this->get_subscription_plans();
            $membership_url = $this->get_canonical_membership_url();
            $normalized_plans = array_map(function ($plan) use ($membership_url) {
                $features = isset($plan['features']) && is_array($plan['features']) ? array_values(array_filter(array_map('sanitize_text_field', $plan['features']))) : [];
                return [
                    'name' => (string) ($plan['name'] ?? ''),
                    'slug' => (string) ($plan['slug'] ?? sanitize_title($plan['name'] ?? 'plan')),
                    'price' => (string) ($plan['price'] ?? ''),
                    'price_amount' => isset($plan['price_amount']) ? (float) $plan['price_amount'] : 0.0,
                    'price_currency' => (string) ($plan['price_currency'] ?? ''),
                    'billing_cycle' => (string) ($plan['billing_cycle'] ?? ''),
                    'tagline' => (string) ($plan['tagline'] ?? ''),
                    'features' => $features,
                    'shortcode' => (string) ($plan['shortcode'] ?? ''),
                    'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : $membership_url,
                    'badge' => !empty($plan['is_annual']) ? __('Annual', 'senna-finance') : __('Monthly', 'senna-finance'),
                    'featured' => !empty($plan['featured_signup']),
                    'is_annual' => !empty($plan['is_annual']),
                ];
            }, $plans);

            foreach ($normalized_plans as &$normalized_plan) {
                $normalized_plan['display_price'] = $this->format_plan_price_amount($normalized_plan) ?: (string) ($normalized_plan['price'] ?? '');
            }
            unset($normalized_plan);

            $plan_cards = [];
            $blurred_avatars = [
                'https://joinsenna.com/wp-content/uploads/2025/01/340340_Lydia.jpeg',
                'https://joinsenna.com/wp-content/uploads/2024/05/275327873-portrait-happy-and-businessman.jpeg',
                'https://media.joinsenna.com/2026/04/242895182-she-emanates-happiness-studio-.jpeg?1775448289',
                'https://joinsenna.com/wp-content/uploads/2024/05/229397494-happy-portrait-or-business-wom.jpeg',
            ];
            foreach ($normalized_plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $headline = trim((string) ($plan['tagline'] ?? ''));
                if ($headline === '') {
                    $headline = trim((string) ($plan['audience'] ?? ''));
                }
                if ($headline === '') {
                    $headline = $name;
                }

                $copy = trim((string) ($plan['audience'] ?? ''));
                if ($copy === '') {
                    $copy = $headline;
                }

                $benefits = [];
                if (!empty($plan['features']) && is_array($plan['features'])) {
                    $benefits = array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])));
                }

                $text_blob = strtolower($name . ' ' . $headline . ' ' . $copy . ' ' . implode(' ', $benefits));
                $is_recruiter_plan = strpos($text_blob, 'recruiter') !== false || strpos($text_blob, 'network') !== false || strpos($text_blob, 'access') !== false;

                $badge = '';
                if (!empty($plan['is_annual'])) {
                    $badge = __('Annual', 'senna-finance');
                }

                $plan_cards[] = [
                    'label' => $name,
                    'headline' => $headline,
                    'copy' => $copy,
                    'badge' => $badge,
                    'value_badge' => !empty($plan['is_annual']) ? __('Good Value', 'senna-finance') : '',
                    'benefits' => $benefits,
                    'avatars' => $is_recruiter_plan ? $blurred_avatars : [],
                    'plan' => $plan,
                ];
            }

            if (!empty($plan_cards)) {
                $last_index = array_key_last($plan_cards);
                if ($last_index !== null) {
                    $plan_cards[$last_index]['badge'] = __('Most Selected', 'senna-finance');
                }
            }

            $initial_card = null;
            if (!empty($plan_cards[1])) {
                $initial_card = $plan_cards[1];
            } else {
                foreach ($plan_cards as $candidate_card) {
                    if (!empty($candidate_card['plan']['shortcode']) || !empty($candidate_card['plan']['url'])) {
                        $initial_card = $candidate_card;
                        break;
                    }
                }
                if ($initial_card === null) {
                    $initial_card = $plan_cards[0] ?? null;
                }
            }
            $initial_plan = $initial_card['plan'] ?? null;
            $login_target = is_user_logged_in() ? home_url('/my-account/') : wp_login_url(get_permalink());

            $subscription_locale = $this->get_member_pricing_signup_locale();
            $subscription_dir = $this->is_arabic_locale($subscription_locale) ? 'rtl' : 'ltr';

            ob_start();
        ?>
            <section class="sffc-subscription-onboarding" dir="<?php echo esc_attr($subscription_dir); ?>" data-locale="<?php echo esc_attr($this->is_arabic_locale($subscription_locale) ? 'ar' : 'en'); ?>" data-subscription-onboarding>
                <div class="sffc-subscription-onboarding__frame">
                    <aside class="sffc-subscription-onboarding__selector-pane">
                        <div class="sffc-subscription-onboarding__selector-mark">
                            <span class="sffc-subscription-onboarding__selector-mark-icon" aria-hidden="true">
                                <span class="sffc-subscription-onboarding__selector-mark-s">S</span>
                                <span class="sffc-subscription-onboarding__selector-mark-dot"></span>
                            </span>
                        </div>
                        <div class="sffc-subscription-onboarding__selector-head">
                            <span class="sffc-subscription-onboarding__eyebrow"><?php esc_html_e('The smart way to land interviews', 'senna-finance'); ?></span>
                            <h1><?php esc_html_e('Choose the right plan for you', 'senna-finance'); ?></h1>
                            <p><?php esc_html_e('Select the route that matches how much help you want across applications, recruiter access and ongoing search strategy.', 'senna-finance'); ?></p>
                        </div>

                        <div class="sffc-subscription-onboarding__plans-stack" data-plan-stack>
                            <?php if (empty($plan_cards)) : ?>
                                <div class="sffc-subscription-onboarding__plan-empty"><?php esc_html_e('Membership plans will appear here once configured.', 'senna-finance'); ?></div>
                            <?php else : ?>
                                <?php foreach ($plan_cards as $index => $card) :
                                    $plan = $card['plan'];
                                    $is_active = !empty($initial_plan['slug']) && !empty($plan['slug']) ? ($initial_plan['slug'] === $plan['slug']) : ($index === 0);
                                ?>
                                    <article
                                        class="sffc-subscription-onboarding__plan-card<?php echo $is_active ? ' is-active' : ''; ?>"
                                        data-plan-card
                                        data-plan-slug="<?php echo esc_attr($plan['slug']); ?>"
                                        data-plan-url="<?php echo esc_url($plan['url']); ?>"
                                        data-plan-name="<?php echo esc_attr($plan['name']); ?>"
                                        data-plan-copy="<?php echo esc_attr($card['headline']); ?>"
                                        data-plan-price="<?php echo esc_attr((string) ($plan['display_price'] ?? $plan['price'])); ?>"
                                        data-plan-billing="<?php echo esc_attr((string) $plan['billing_cycle']); ?>"
                                        data-plan-tagline="<?php echo esc_attr((string) $card['copy']); ?>">
                                        <button type="button" class="sffc-subscription-onboarding__plan-toggle" data-plan-toggle>
                                            <span class="sffc-subscription-onboarding__plan-radio" aria-hidden="true"></span>
                                            <span class="sffc-subscription-onboarding__plan-main">
                                                <span class="sffc-subscription-onboarding__plan-topline">
                                                    <strong><?php echo esc_html($card['label']); ?></strong>
                                                    <?php if (!empty($card['badge'])) : ?>
                                                        <span class="sffc-subscription-onboarding__plan-badge"><?php echo esc_html($card['badge']); ?></span>
                                                    <?php endif; ?>
                                                    <?php if (!empty($card['value_badge'])) : ?>
                                                        <span class="sffc-subscription-onboarding__plan-badge sffc-subscription-onboarding__plan-badge--value"><?php echo esc_html($card['value_badge']); ?></span>
                                                    <?php endif; ?>
                                                </span>
                                                <span class="sffc-subscription-onboarding__plan-headline"><?php echo esc_html($card['headline']); ?></span>
                                                <span class="sffc-subscription-onboarding__plan-meta"><?php echo esc_html($card['copy']); ?></span>
                                            </span>
                                            <span class="sffc-subscription-onboarding__plan-price">
                                                <?php if (!empty($plan['display_price']) || !empty($plan['price'])) : ?>
                                                    <span class="sffc-subscription-onboarding__plan-price-value"><?php echo esc_html($plan['display_price'] ?: $plan['price']); ?></span>
                                                <?php endif; ?>
                                                <span class="sffc-subscription-onboarding__plan-price-cycle"><?php echo esc_html(!empty($plan['is_annual']) ? __('Annual plan', 'senna-finance') : __('Monthly plan', 'senna-finance')); ?></span>
                                            </span>
                                        </button>

                                        <div class="sffc-subscription-onboarding__plan-panel" <?php echo $is_active ? '' : 'hidden'; ?>>
                                            <?php if ($index === 0) : ?>
                                                <div class="sffc-subscription-onboarding__plan-avatars sffc-subscription-onboarding__plan-avatars--materials" aria-hidden="true">
                                                    <span class="sffc-subscription-onboarding__plan-doc sffc-subscription-onboarding__plan-doc--word">
                                                        <span class="sffc-subscription-onboarding__plan-doc-icon">W</span>
                                                        <span class="sffc-subscription-onboarding__plan-doc-label">Word</span>
                                                    </span>
                                                    <span class="sffc-subscription-onboarding__plan-doc sffc-subscription-onboarding__plan-doc--pdf">
                                                        <span class="sffc-subscription-onboarding__plan-doc-icon">PDF</span>
                                                        <span class="sffc-subscription-onboarding__plan-doc-label">PDF</span>
                                                    </span>
                                                    <span class="sffc-subscription-onboarding__plan-doc sffc-subscription-onboarding__plan-doc--excel">
