                                                        <span class="sffc-subscription-onboarding__plan-doc-label">Excel</span>
                                                    </span>
                                                </div>
                                            <?php endif; ?>
                                            <?php if (!empty($card['avatars'])) : ?>
                                                <div class="sffc-subscription-onboarding__plan-avatars" aria-hidden="true">
                                                    <?php foreach ($card['avatars'] as $avatar_url) : ?>
                                                        <span class="sffc-subscription-onboarding__plan-avatar">
                                                            <img src="<?php echo esc_url($avatar_url); ?>" alt="">
                                                        </span>
                                                    <?php endforeach; ?>
                                                </div>
                                            <?php endif; ?>
                                            <ul class="sffc-subscription-onboarding__plan-benefits">
                                                <?php foreach ($card['benefits'] as $benefit) : ?>
                                                    <li><?php echo esc_html($benefit); ?></li>
                                                <?php endforeach; ?>
                                            </ul>
                                        </div>
                                    </article>
                                <?php endforeach; ?>
