                                <div class="sffc-subscription-onboarding__checkout-shell<?php echo $is_initial_shell ? ' is-active' : ''; ?>" data-plan-shell="<?php echo esc_attr($plan['slug']); ?>" <?php echo $is_initial_shell ? '' : 'hidden'; ?>>
