        public function render_members_recruiter_contact_signup($atts = [])
        {
            if (!is_array($atts)) {
                $atts = [];
            }

            $atts['flow'] = 'recruiter_contact';

            return $this->render_members_pricing_signup($atts);
        }

        public function render_signup_flow($atts = [])
        {
            wp_enqueue_style(
                'sffc-signup-flow',
                SFFC_PLUGIN_URL . 'assets/css/crm/signup-flow.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-signup-flow',
                SFFC_PLUGIN_URL . 'assets/js/crm/signup-flow.js',
                ['jquery'],
                SFFC_VERSION,
                true
            );

            $plans = $this->get_subscription_plans();
            $membership_url = $this->get_canonical_membership_url();

            $plan_payload = array_map(function ($plan) use ($membership_url) {
                return [
                    'name' => $plan['name'] ?? '',
                    'price' => $plan['price'] ?? '',
                    'price_amount' => $plan['price_amount'] ?? '',
                    'price_currency' => $plan['price_currency'] ?? '',
                    'billing' => $plan['billing_cycle'] ?? '',
                    'tagline' => $plan['tagline'] ?? '',
                    'features' => $plan['features'] ?? [],
                    'slug' => $plan['slug'] ?? '',
                    'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : $membership_url,
                    'featured' => !empty($plan['featured_signup'])
                ];
            }, $plans);

            $signup_flow_locale = $this->get_member_pricing_signup_locale();
            $signup_flow_dir = $this->is_arabic_locale($signup_flow_locale) ? 'rtl' : 'ltr';

            wp_localize_script('sffc-signup-flow', 'sffcSignupFlow', [
                'plans' => $plan_payload,
                'membershipUrl' => $membership_url,
            ]);

            $locations = ['Dubai', 'Abu Dhabi', 'Riyadh', 'Doha', 'Remote'];
            $sectors = ['Finance', 'Investment Banking', 'Asset Management', 'Corporate Finance', 'Investor Relations', 'Portfolio Operations', 'Fund Finance', 'All'];

            ob_start();
        ?>
