                    'description' => __('Pick the main problem you want to solve so we can set up your account in the right way', 'senna-finance'),
                    'options' => array_map(static function ($key, $item) {
                        $descriptions = [
                            'land_interviews' => __('You are applying already, but private equity interviews are not coming through.', 'senna-finance'),
                            'attract_more_roles' => __('You want stronger visibility so better private equity roles come to you more often.', 'senna-finance'),
                            'fix_cv_before_apply' => __('You want to fix your CV before sending another private equity application.', 'senna-finance'),
                            'get_recruiter_attention' => __('You want stronger outreach, referrals, and positioning so the right recruiters actually respond.', 'senna-finance'),
                        ];
                        $icons = [
                            'land_interviews' => 'signal',
                            'attract_more_roles' => 'globe',
                            'fix_cv_before_apply' => 'document',
                            'get_recruiter_attention' => 'network',
                        ];
                        return [
                            'key' => $key,
                            'label' => $item['label'],
                            'description' => $descriptions[$key] ?? '',
                            'icon' => $icons[$key] ?? 'document',
                        ];
                    }, array_keys($this->get_cv_match_guided_help_needs_catalog()), array_values($this->get_cv_match_guided_help_needs_catalog())),
                ],
                'commitment' => $this->get_cv_match_guided_commitment_step_catalog(),
                'constraint' => $this->get_cv_match_guided_constraint_step_catalog(),
                'deliverable' => $this->get_cv_match_guided_deliverable_step_catalog(),
            ];
        }

        private function enqueue_crm_cv_match_guided_pricing_assets()
        {
            $reddit_feed_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/reddit-feed.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/reddit-feed.css') : SFFC_VERSION;
            $cv_match_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') : SFFC_VERSION;
            $guided_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-guided-pricing.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-guided-pricing.css') : SFFC_VERSION;
            $subscription_pricing_js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/subscription-pricing.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/subscription-pricing.js') : SFFC_VERSION;
            $guided_js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/cv-match-guided-pricing.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/cv-match-guided-pricing.js') : SFFC_VERSION;

            wp_enqueue_style('sffc-crm-reddit-feed', SFFC_PLUGIN_URL . 'assets/css/crm/reddit-feed.css', [], $reddit_feed_css_version);
            wp_enqueue_style('sffc-crm-cv-match-studio', SFFC_PLUGIN_URL . 'assets/css/crm/cv-match-studio.css', ['sffc-crm-reddit-feed'], $cv_match_css_version);
            wp_enqueue_style('sffc-cv-match-guided-pricing', SFFC_PLUGIN_URL . 'assets/css/crm/cv-match-guided-pricing.css', ['sffc-crm-cv-match-studio'], $guided_css_version);
            wp_enqueue_script('sffc-subscription-pricing', SFFC_PLUGIN_URL . 'assets/js/crm/subscription-pricing.js', ['jquery'], $subscription_pricing_js_version, true);
            wp_enqueue_script('sffc-cv-match-guided-pricing', SFFC_PLUGIN_URL . 'assets/js/crm/cv-match-guided-pricing.js', ['sffc-subscription-pricing'], $guided_js_version, true);

            $help_needs_catalog = $this->get_cv_match_guided_help_needs_catalog();
            $wizard_catalog = $this->get_cv_match_guided_wizard_catalog();

            wp_localize_script('sffc-cv-match-guided-pricing', 'sffcCvMatchGuidedPricing', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'prefillNonce' => wp_create_nonce('sffc_sync_signup_prefill'),
                'entryContextKey' => 'sffcGuidedPricingEntryContext',
                'helpNeeds' => $help_needs_catalog,
                'wizard' => $wizard_catalog,
                'copy' => [
                    'fallbackFirstName' => __('there', 'senna-finance'),
                    'helpTitle' => __('Hi {first_name}, how can MENA Careers help your private equity search?', 'senna-finance'),
                    'constraintTitle' => __('{first_name}, Where is the biggest friction right now?', 'senna-finance'),
                    'dialogTitle' => __("Building {first_name}'s path into private equity", 'senna-finance'),
                    'dialogTitleFallback' => __('Building your path into private equity', 'senna-finance'),
                    'dialogCopy' => __('We are using your goals, application pressure, and support needs to recommend the best path for helping you land private equity roles.', 'senna-finance'),
                ],
            ]);
