        private function get_crm_cv_match_guided_pricing_prefill_identity()
        {
            $guided_user = wp_get_current_user();
            $guided_user_id = $guided_user instanceof WP_User ? (int) $guided_user->ID : 0;
            $guided_prefill_first_name = $this->get_crm_reddit_current_user_first_name($guided_user_id);
            $guided_prefill_full_name = $this->get_crm_reddit_current_user_full_name($guided_user_id);
            if ($guided_prefill_full_name === '' && $guided_prefill_first_name !== '') {
                $guided_prefill_full_name = $guided_prefill_first_name;
            }

            return [
                'first_name' => $guided_prefill_first_name,
                'full_name' => $guided_prefill_full_name,
                'email' => $guided_user_id > 0 ? (string) $guided_user->user_email : '',
            ];
        }

        private function get_crm_cv_match_guided_pricing_plan_context()
        {
            $membership_url = $this->get_canonical_membership_url();
            $plans = $this->get_subscription_plans();
            $normalized_plans = [];

            foreach ($plans as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $normalized_plan = [
                    'name' => $name,
                    'slug' => (string) ($plan['slug'] ?? sanitize_title($name)),
                    'price' => (string) ($plan['price'] ?? ''),
                    'price_amount' => isset($plan['price_amount']) ? (float) $plan['price_amount'] : 0.0,
                    'price_currency' => (string) ($plan['price_currency'] ?? ''),
                    'billing_cycle' => (string) ($plan['billing_cycle'] ?? ''),
                    'tagline' => (string) ($plan['tagline'] ?? ''),
                    'audience' => (string) ($plan['audience'] ?? ''),
                    'features' => $features,
                    'shortcode' => (string) ($plan['shortcode'] ?? ''),
                    'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : $membership_url,
                    'featured_signup' => !empty($plan['featured_signup']),
                    'is_annual' => !empty($plan['is_annual']),
                    'cycle' => !empty($plan['is_annual']) ? 'annual' : 'monthly',
                    'memberpress_product_id' => !empty($plan['memberpress_product_id'])
                        ? (int) $plan['memberpress_product_id']
                        : $this->extract_memberpress_product_id_from_shortcode((string) ($plan['shortcode'] ?? '')),
                    'onboarding_help_needs' => $this->resolve_guided_plan_help_needs($plan),
                    'onboarding_commitment_modes' => $this->resolve_guided_plan_commitment_modes($plan),
                    'onboarding_pitch' => (string) ($plan['onboarding_pitch'] ?? ($plan['tagline'] ?? ($plan['audience'] ?? ''))),
                ];

                $display_price = $this->format_plan_price_amount($normalized_plan) ?: (string) ($normalized_plan['price'] ?? '');
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', $display_price);
                $amount_label = $display_price;
                $cycle_label = '';
                if (preg_match('/^(.*?)\s*\/\s*(.+)$/', $display_price, $matches)) {
                    $amount_label = trim((string) $matches[1]);
                    $cycle_label = sprintf(__('per %s', 'senna-finance'), trim((string) $matches[2]));
                } elseif (!empty($normalized_plan['billing_cycle'])) {
                    $cycle_label = sprintf(__('per %s', 'senna-finance'), trim((string) $normalized_plan['billing_cycle']));
                }

                $normalized_plan['display_price'] = $display_price;
                $normalized_plan['amount_label'] = $amount_label;
                $normalized_plan['cycle_label'] = $cycle_label;
                $normalized_plans[] = $normalized_plan;
            }

            $plans_by_cycle = ['monthly' => [], 'annual' => []];
            foreach ($normalized_plans as $plan) {
                $plans_by_cycle[$plan['cycle']][] = $plan;
            }

            $available_cycles = array_values(array_filter(['monthly', 'annual'], static function ($cycle) use ($plans_by_cycle) {
                return !empty($plans_by_cycle[$cycle]);
            }));
            $default_cycle = in_array('monthly', $available_cycles, true) ? 'monthly' : (!empty($available_cycles[0]) ? $available_cycles[0] : 'monthly');
            $default_plan_by_cycle = [];
            foreach ($available_cycles as $cycle) {
                $cycle_plans = $plans_by_cycle[$cycle];
                $default_plan = null;
                foreach ($cycle_plans as $candidate_plan) {
                    if (!empty($candidate_plan['featured_signup'])) {
                        $default_plan = $candidate_plan;
                        break;
                    }
                }
                if ($default_plan === null && !empty($cycle_plans)) {
                    $default_plan = $cycle_plans[0];
                }
                if ($default_plan !== null) {
                    $default_plan_by_cycle[$cycle] = $default_plan;
                }
            }

            $active_memberpress_product_ids = is_user_logged_in() ? $this->get_active_memberpress_product_ids(get_current_user_id()) : [];
            $has_existing_memberpress_plan = !empty($active_memberpress_product_ids);
            $active_plan = $default_plan_by_cycle[$default_cycle] ?? (!empty($normalized_plans[0]) ? $normalized_plans[0] : null);

            return [
                'membership_url' => $membership_url,
                'normalized_plans' => $normalized_plans,
                'plans_by_cycle' => $plans_by_cycle,
                'available_cycles' => $available_cycles,
                'default_cycle' => $default_cycle,
                'default_plan_by_cycle' => $default_plan_by_cycle,
                'active_memberpress_product_ids' => $active_memberpress_product_ids,
                'has_existing_memberpress_plan' => $has_existing_memberpress_plan,
                'active_plan' => $active_plan,
            ];
        }

        private function resolve_guided_plan_help_needs(array $plan_entry)
        {
            $tags = $this->normalize_guided_plan_tag_list($plan_entry['onboarding_help_needs'] ?? []);
            if (!empty($tags)) {
                return $tags;
            }

            $text = strtolower(
                trim(
                    implode(
                        ' ',
                        array_filter([
                            (string) ($plan_entry['name'] ?? ''),
                            (string) ($plan_entry['tagline'] ?? ''),
                            (string) ($plan_entry['audience'] ?? ''),
                            implode(' ', isset($plan_entry['features']) && is_array($plan_entry['features']) ? $plan_entry['features'] : []),
                        ])
                    )
                )
            );

            $resolved = [];
            if (preg_match('/\b(cv|cover letter|interview|application pack|hiring guide|application materials|tailor)\b/i', $text)) {
                $resolved[] = 'fix_cv_before_apply';
                $resolved[] = 'land_interviews';
            }
            if (preg_match('/\b(role matching|live roles|role fit|search|opportunities|roles)\b/i', $text)) {
                $resolved[] = 'attract_more_roles';
            }
            if (preg_match('/\b(recruiter|outreach|network|referral|introductions?)\b/i', $text)) {
                $resolved[] = 'get_recruiter_attention';
                $resolved[] = 'attract_more_roles';
                $resolved[] = 'land_interviews';
            }
            if (preg_match('/\b(ats|cv review|scan|keyword)\b/i', $text)) {
                $resolved[] = 'fix_cv_before_apply';
            }

            if (empty($resolved)) {
                $resolved[] = 'land_interviews';
            }

            return array_values(array_unique($resolved));
        }

        private function resolve_guided_plan_commitment_modes(array $plan_entry)
        {
            $tags = $this->normalize_guided_plan_tag_list($plan_entry['onboarding_commitment_modes'] ?? []);
            if (!empty($tags)) {
                return $tags;
            }

            $text = strtolower(
                trim(
                    implode(
                        ' ',
                        array_filter([
                            (string) ($plan_entry['name'] ?? ''),
                            (string) ($plan_entry['tagline'] ?? ''),
                            (string) ($plan_entry['audience'] ?? ''),
                            implode(' ', isset($plan_entry['features']) && is_array($plan_entry['features']) ? $plan_entry['features'] : []),
                        ])
                    )
                )
            );

            $resolved = [];
            if (preg_match('/\b(monthly|annual|membership|live roles|outreach|search strategy|tracking|career report|ongoing)\b/i', $text)) {
                $resolved[] = 'ongoing';
            }
            if (preg_match('/\b(application pack|cv template|cover letter|interview questions|hiring guide|one time|one-off|single)\b/i', $text)) {
                $resolved[] = 'one_time';
            }

            if (empty($resolved)) {
                $resolved[] = !empty($plan_entry['matches_per_week']) || (!empty($plan_entry['price_amount']) && (float) $plan_entry['price_amount'] > 25)
                    ? 'ongoing'
                    : 'one_time';
            }

            return array_values(array_unique($resolved));
        }

        private function get_subscription_plans()
        {
            if ($this->subscription_plans !== null) {
                return $this->subscription_plans;
            }

            $plans = [];

            if (class_exists('SFFC_PE_News_Dashboard')) {
                $dashboard = SFFC_PE_News_Dashboard::get_instance();
                if (method_exists($dashboard, 'get_subscription_plans')) {
                    $plans = $dashboard->get_subscription_plans();
                }
            }

            if (empty($plans)) {
                $stored_plans = get_option('sffc_dashboard_plans', array());
                if (!empty($stored_plans) && is_array($stored_plans)) {
                    foreach ($stored_plans as $plan) {
                        if (empty($plan['name'])) {
                            continue;
                        }
                        $features = $plan['features'] ?? array();
                        if (is_string($features)) {
                            $features = preg_split("/\r?\n/", $features);
                        }
                        $features = is_array($features) ? array_filter(array_map('trim', $features)) : array();

                        $raw_signup_path = (string) ($plan['signup_path'] ?? '');
                        $signup_path_context = trim(
                            implode(
                                ' ',
                                array_filter([
                                    (string) ($plan['name'] ?? ''),
                                    (string) ($plan['tagline'] ?? ''),
                                    (string) ($plan['audience'] ?? ''),
                                    implode(' ', $features),
                                ])
                            )
                        );
                        $normalized_signup_path = $this->normalize_member_signup_path($raw_signup_path, $signup_path_context);

                        $plan_entry = array(
                            'name' => sanitize_text_field($plan['name']),
                            'slug' => sanitize_title($plan['slug'] ?? $plan['name']),
                            'price' => sanitize_text_field($plan['price'] ?? ''),
                            'price_amount' => isset($plan['price_amount']) ? floatval($plan['price_amount']) : '',
                            'annual_price' => sanitize_text_field($plan['annual_price'] ?? ''),
                            'annual_price_amount' => isset($plan['annual_price_amount']) ? floatval($plan['annual_price_amount']) : '',
                            'price_currency' => sanitize_text_field($plan['price_currency'] ?? ''),
                            'matches_per_week' => isset($plan['matches_per_week']) ? max(0, intval($plan['matches_per_week'])) : 0,
                            'billing_cycle' => sanitize_text_field($plan['billing_cycle'] ?? ''),
                            'annual_billing_cycle' => sanitize_text_field($plan['annual_billing_cycle'] ?? ''),
                            'tagline' => sanitize_text_field($plan['tagline'] ?? ''),
                            'audience' => sanitize_text_field($plan['audience'] ?? ''),
                            'features' => $features,
                            'mp_url' => esc_url_raw($plan['mp_url'] ?? ''),
                            'shortcode' => isset($plan['shortcode']) ? wp_kses_post($plan['shortcode']) : '',
                            'annual_mp_url' => esc_url_raw($plan['annual_mp_url'] ?? ''),
                            'annual_shortcode' => isset($plan['annual_shortcode']) ? wp_kses_post($plan['annual_shortcode']) : '',
                            'featured_signup' => !empty($plan['featured_signup']) ? 1 : 0,
                            'is_annual' => !empty($plan['is_annual']) ? 1 : 0,
                            'recruiter_contact_pricing' => !empty($plan['recruiter_contact_pricing']) ? 1 : 0,
                            'signup_path' => $normalized_signup_path['path'],
                            'signup_path_configured' => $normalized_signup_path['configured'] ? 1 : 0,
                            'hero_eyebrow' => sanitize_text_field($plan['hero_eyebrow'] ?? ''),
                            'hero_title' => sanitize_text_field($plan['hero_title'] ?? ''),
                            'hero_copy' => sanitize_textarea_field($plan['hero_copy'] ?? ''),
                            'hero_image_url' => esc_url_raw($plan['hero_image_url'] ?? ''),
                            'hero_image_alt' => sanitize_text_field($plan['hero_image_alt'] ?? ''),
                            'hero_cta_label' => sanitize_text_field($plan['hero_cta_label'] ?? ''),
                            'authority_title' => sanitize_text_field($plan['authority_title'] ?? ''),
                            'authority_copy' => sanitize_textarea_field($plan['authority_copy'] ?? ''),
                            'social_title' => sanitize_text_field($plan['social_title'] ?? ''),
                            'social_copy' => sanitize_textarea_field($plan['social_copy'] ?? ''),
                            'social_review_score' => isset($plan['social_review_score']) ? max(0, min(5, floatval($plan['social_review_score']))) : '',
                            'social_review_count' => isset($plan['social_review_count']) ? max(0, intval($plan['social_review_count'])) : '',
                            'social_reviews' => array(),
                            'free_title' => sanitize_text_field($plan['free_title'] ?? ''),
                            'free_copy' => sanitize_textarea_field($plan['free_copy'] ?? ''),
                            'category_title' => sanitize_text_field($plan['category_title'] ?? ''),
                            'category_copy' => sanitize_textarea_field($plan['category_copy'] ?? ''),
                            'scarcity_title' => sanitize_text_field($plan['scarcity_title'] ?? ''),
                            'scarcity_copy' => sanitize_textarea_field($plan['scarcity_copy'] ?? ''),
                            'now_title' => sanitize_text_field($plan['now_title'] ?? ''),
                            'now_copy' => sanitize_textarea_field($plan['now_copy'] ?? ''),
                            'other_plans_label' => sanitize_text_field($plan['other_plans_label'] ?? ''),
                            'back_label' => sanitize_text_field($plan['back_label'] ?? ''),
                            'onboarding_help_needs' => $this->normalize_guided_plan_tag_list($plan['onboarding_help_needs'] ?? []),
                            'onboarding_commitment_modes' => $this->normalize_guided_plan_tag_list($plan['onboarding_commitment_modes'] ?? []),
                            'onboarding_pitch' => sanitize_textarea_field($plan['onboarding_pitch'] ?? ''),
                        );
                        $plan_entry['onboarding_help_needs'] = $this->resolve_guided_plan_help_needs($plan_entry);
                        $plan_entry['onboarding_commitment_modes'] = $this->resolve_guided_plan_commitment_modes($plan_entry);
                        if ($plan_entry['onboarding_pitch'] === '') {
                            $plan_entry['onboarding_pitch'] = $plan_entry['tagline'] ?: $plan_entry['audience'];
                        }
                        $social_reviews = $plan['social_reviews'] ?? array();
                        if (is_string($social_reviews)) {
                            $social_reviews = preg_split("/\r?\n/", $social_reviews);
                        }
                        if (is_array($social_reviews)) {
                            foreach ($social_reviews as $review) {
                                if (is_array($review)) {
                                    $text = trim(wp_strip_all_tags($review['text'] ?? ''));
                                    if ($text === '') {
                                        continue;
                                    }

                                    $plan_entry['social_reviews'][] = array(
                                        'text' => $text,
                                        'first_name' => sanitize_text_field($review['first_name'] ?? ''),
                                        'last_name' => sanitize_text_field($review['last_name'] ?? ''),
                                        'rating' => isset($review['rating']) ? max(0, min(5, floatval($review['rating']))) : 5,
                                    );
                                    continue;
                                }

                                $review = trim(wp_strip_all_tags($review));
                                if ($review === '') {
                                    continue;
                                }

                                $parts = array_map('trim', explode('|', $review));
                                $plan_entry['social_reviews'][] = array(
                                    'text' => isset($parts[0]) ? $parts[0] : '',
                                    'first_name' => isset($parts[1]) ? sanitize_text_field($parts[1]) : '',
                                    'last_name' => isset($parts[2]) ? sanitize_text_field($parts[2]) : '',
                                    'rating' => isset($parts[3]) ? max(0, min(5, floatval($parts[3]))) : 5,
                                );
                            }
                        }

                        $legacy_annual_only = !empty($plan_entry['is_annual']);
                        $has_annual_variant = ((float) $plan_entry['annual_price_amount'] > 0)
                            || trim((string) $plan_entry['annual_price']) !== ''
                            || trim((string) $plan_entry['annual_shortcode']) !== ''
                            || trim((string) $plan_entry['annual_mp_url']) !== '';

                        if (!$legacy_annual_only || $has_annual_variant) {
                            $monthly_entry = $plan_entry;
                            $monthly_entry['is_annual'] = 0;
                            $plans[] = $monthly_entry;
                        }

                        if ($has_annual_variant || $legacy_annual_only) {
                            $annual_entry = $plan_entry;
                            $annual_entry['is_annual'] = 1;
                            $annual_entry['slug'] = sanitize_title(($plan['slug'] ?? $plan['name']) . '-annual');
                            $annual_entry['price'] = $has_annual_variant ? $plan_entry['annual_price'] : $plan_entry['price'];
                            $annual_entry['price_amount'] = $has_annual_variant && (float) $plan_entry['annual_price_amount'] > 0 ? (float) $plan_entry['annual_price_amount'] : (float) $plan_entry['price_amount'];
                            $annual_entry['billing_cycle'] = $has_annual_variant && trim((string) $plan_entry['annual_billing_cycle']) !== '' ? $plan_entry['annual_billing_cycle'] : ($plan_entry['billing_cycle'] ?: __('per year', 'senna-finance'));
                            $annual_entry['shortcode'] = $has_annual_variant && trim((string) $plan_entry['annual_shortcode']) !== '' ? $plan_entry['annual_shortcode'] : $plan_entry['shortcode'];
                            $annual_entry['mp_url'] = $has_annual_variant && trim((string) $plan_entry['annual_mp_url']) !== '' ? $plan_entry['annual_mp_url'] : $plan_entry['mp_url'];
                            $plans[] = $annual_entry;
                        }
                    }
                }
            }

            $this->subscription_plans = $plans;
            return $this->subscription_plans;
        }

        private function normalize_member_signup_path($raw_path, $context = '')
        {
            $raw_path = strtolower(trim((string) $raw_path));
            $context = strtolower(trim((string) $context));

            if ($raw_path !== '') {
                $raw_key = sanitize_key($raw_path);
                if (in_array($raw_key, ['platform', 'mentorship', 'all_access', 'one_contact', 'extra_contacts', 'ongoing_contacts'], true)) {
                    return [
                        'path' => $raw_key,
                        'configured' => true,
                    ];
                }

                $raw_tokens = $raw_path . ' ' . str_replace(['_', '-', '+', '/'], ' ', $raw_path);
                if (preg_match('/\b(one contact|single contact|one recruiter contact)\b/', $raw_tokens)) {
                    return [
                        'path' => 'one_contact',
                        'configured' => true,
                    ];
                }
                if (preg_match('/\b(extra contacts|multiple contacts|more contacts)\b/', $raw_tokens)) {
                    return [
                        'path' => 'extra_contacts',
                        'configured' => true,
                    ];
                }
                if (preg_match('/\b(ongoing contacts|ongoing recruiter contacts|recruiter alerts|ongoing access)\b/', $raw_tokens)) {
                    return [
                        'path' => 'ongoing_contacts',
                        'configured' => true,
                    ];
                }
                if (
                    preg_match('/\b(all access|all-access|premium|full access|everything)\b/', $raw_tokens)
                    || (
                        preg_match('/\b(recruiter|contact|intro|platform|access)\b/', $raw_tokens)
                        && preg_match('/\b(cv|resume|linkedin|profile|review|mentorship|support|transition)\b/', $raw_tokens)
                    )
                ) {
                    return [
                        'path' => 'all_access',
                        'configured' => true,
                    ];
                }
                if (preg_match('/\b(recruiter contacts?|recruiter|contacts?|intros?|platform|access only|basic|career)\b/', $raw_tokens)) {
                    return [
                        'path' => 'platform',
                        'configured' => true,
                    ];
                }
                if (preg_match('/\b(profile positioning|cv positioning|cv|resume|linkedin|profile|review|mentorship|support|transition)\b/', $raw_tokens)) {
                    return [
                        'path' => 'mentorship',
                        'configured' => true,
                    ];
                }
            }

            if ($context !== '') {
                if (preg_match('/\b(one contact|single contact|one recruiter contact)\b/', $context)) {
                    return [
                        'path' => 'one_contact',
                        'configured' => false,
                    ];
                }
                if (preg_match('/\b(extra contacts|multiple contacts|more contacts)\b/', $context)) {
                    return [
                        'path' => 'extra_contacts',
                        'configured' => false,
                    ];
                }
                if (preg_match('/\b(ongoing contacts|ongoing recruiter contacts|recruiter alerts|ongoing access)\b/', $context)) {
                    return [
                        'path' => 'ongoing_contacts',
                        'configured' => false,
                    ];
                }
                if (
                    preg_match('/\b(all access|all-access|premium|full access|everything)\b/', $context)
                    || (
                        preg_match('/\b(recruiter|contact|intro|platform|access)\b/', $context)
                        && preg_match('/\b(cv|resume|linkedin|profile|review|mentorship|support|transition)\b/', $context)
                    )
                ) {
                    return [
                        'path' => 'all_access',
                        'configured' => false,
                    ];
                }
                if (preg_match('/\b(recruiter contacts?|recruiter|contacts?|intros?|platform|access only|basic|career)\b/', $context)) {
                    return [
                        'path' => 'platform',
                        'configured' => false,
                    ];
                }
                if (preg_match('/\b(profile positioning|cv positioning|cv|resume|linkedin|profile|review|mentorship|support|transition)\b/', $context)) {
                    return [
                        'path' => 'mentorship',
                        'configured' => false,
                    ];
                }
            }

            return [
                'path' => 'platform',
                'configured' => false,
            ];
        }

        private function render_plan_modal(array $plan_entries)
        {
            if (empty($plan_entries)) {
                return;
            }

        ?>
