                <div class="sffc-plan-modal__overlay" data-plan-close></div>
                <div class="sffc-plan-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="sffc-plan-modal-title">
                    <div class="sffc-plan-modal__header">
                        <div>
                            <h3 id="sffc-plan-modal-title"><?php esc_html_e('Choose your membership', 'senna-finance'); ?></h3>
                            <p><?php esc_html_e('Unlock recruiter outreach, CRM automations, and analytics in minutes.', 'senna-finance'); ?></p>
                        </div>
                        <button type="button" class="sffc-plan-close" data-plan-close aria-label="<?php esc_attr_e('Close plans', 'senna-finance'); ?>">&times;</button>
                    </div>
                    <div class="sffc-plan-modal__body">
                        <div class="sffc-plan-grid">
                            <?php foreach ($plan_entries as $plan):
                                $plan_slug = sanitize_title($plan['slug'] ?? $plan['name']);
                                $features = isset($plan['features']) && is_array($plan['features']) ? $plan['features'] : array();
                                $plan_price = $this->format_plan_price_amount($plan) ?: ($plan['price'] ?? '');
                            ?>
                                <article class="sffc-plan-card" data-plan-card data-plan-slug="<?php echo esc_attr($plan_slug); ?>">
                                    <div class="sffc-plan-card__head">
                                        <h4><?php echo esc_html($plan['name']); ?></h4>
                                        <?php if (!empty($plan['tagline'])): ?>
                                            <p class="sffc-plan-card__tagline"><?php echo esc_html($plan['tagline']); ?></p>
                                        <?php endif; ?>
                                        <?php if (!empty($plan['audience'])): ?>
                                            <span class="sffc-plan-card__audience"><?php echo esc_html($plan['audience']); ?></span>
                                        <?php endif; ?>
                                    </div>
                                    <?php if (!empty($plan_price)): ?>
                                        <p class="sffc-plan-card__price">
                                            <?php echo esc_html($plan_price); ?>
                                            <?php if (!empty($plan['billing_cycle'])): ?>
                                                <span class="sffc-plan-card__cycle"><?php echo esc_html($plan['billing_cycle']); ?></span>
                                            <?php endif; ?>
                                        </p>
                                    <?php endif; ?>
                                    <?php if (!empty($features)): ?>
                                        <ul class="sffc-plan-card__list">
                                            <?php foreach ($features as $feature): ?>
                                                <li><?php echo esc_html($feature); ?></li>
                                            <?php endforeach; ?>
                                        </ul>
                                    <?php endif; ?>
                                    <button type="button"
                                        class="sffc-plan-select"
                                        data-plan-select
                                        data-plan-url="<?php echo esc_url($plan['mp_url'] ?? 'https://joinsenna.com/memberships/'); ?>"
                                        data-plan-slug="<?php echo esc_attr($plan_slug); ?>"
                                        data-plan-name="<?php echo esc_attr($plan['name']); ?>"
                                        data-plan-price="<?php echo esc_attr($plan_price); ?>"
                                        data-plan-cycle="<?php echo esc_attr($plan['billing_cycle'] ?? ''); ?>"
                                        data-plan-tagline="<?php echo esc_attr($plan['tagline'] ?? ''); ?>"
                                        data-plan-audience="<?php echo esc_attr($plan['audience'] ?? ''); ?>"
                                        data-plan-shortcode="<?php echo !empty($plan['shortcode']) ? 'true' : ''; ?>">
                                        <?php esc_html_e('Choose plan', 'senna-finance'); ?>
                                    </button>
                                </article>
                            <?php endforeach; ?>
                        </div>
                        <div class="sffc-plan-checkout" data-plan-checkout hidden>
                            <p data-plan-message><?php esc_html_e('Select a membership to view the secure checkout.', 'senna-finance'); ?></p>
                            <?php foreach ($plan_entries as $plan):
                                $plan_slug = sanitize_title($plan['slug'] ?? $plan['name']);
                                if (empty($plan['shortcode'])) {
                                    continue;
                                }
                            ?>
                                <div class="sffc-plan-form" data-plan-form="<?php echo esc_attr($plan_slug); ?>" hidden>
                                    <?php echo do_shortcode($plan['shortcode']); ?>
                                </div>
                            <?php endforeach; ?>
                            <div class="sffc-plan-external" data-plan-external hidden>
                                <a href="#" target="_blank" rel="noopener noreferrer" data-plan-external-link><?php esc_html_e('Open secure checkout in a new tab', 'senna-finance'); ?></a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        <?php
        }

