        private function format_plan_price_amount($plan)
        {
            $amount = isset($plan['price_amount']) ? floatval($plan['price_amount']) : 0;
            if ($amount <= 0) {
                return '';
            }

            $base_currency = !empty($plan['price_currency']) ? strtoupper($plan['price_currency']) : strtoupper(get_option('currency_detector_base_currency', 'USD'));
            $target_currency = $this->get_user_currency_preference();

            $converted_amount = $amount;
            if ($target_currency && $base_currency && $target_currency !== $base_currency) {
                $exchange = $this->get_currency_exchange_service();
                if ($exchange) {
                    $converted_amount = $exchange->convert_amount($amount, $base_currency, $target_currency);
                } else {
                    $target_currency = $base_currency;
                }
            } else {
                $target_currency = $target_currency ?: $base_currency;
            }

            $no_decimal_currencies = array('JPY', 'KRW', 'VND', 'IDR', 'CLP', 'PYG', 'UGX');
            $decimal_places = in_array($target_currency, $no_decimal_currencies, true) ? 0 : 2;

            $formatted_amount = sprintf(
                '%s%s',
                $this->get_currency_symbol($target_currency),
                number_format((float) $converted_amount, $decimal_places)
            );

            $cycle_short = $this->get_cycle_short_label($plan['billing_cycle'] ?? '');

            return $cycle_short ? sprintf('%s / %s', $formatted_amount, $cycle_short) : $formatted_amount;
        }

        private function format_plan_price_amount_for_currency($plan, $target_currency)
        {
            $target_currency = strtoupper(trim((string) $target_currency));
            if ($target_currency === '') {
                return $this->format_plan_price_amount($plan);
            }

            $amount = isset($plan['price_amount']) ? floatval($plan['price_amount']) : 0;
            if ($amount <= 0) {
                return '';
            }

            $base_currency = !empty($plan['price_currency']) ? strtoupper($plan['price_currency']) : strtoupper(get_option('currency_detector_base_currency', 'USD'));
            $converted_amount = $amount;

            if ($base_currency !== $target_currency) {
                $exchange = $this->get_currency_exchange_service();
                if ($exchange && method_exists($exchange, 'convert_amount')) {
                    $converted_amount = $exchange->convert_amount($amount, $base_currency, $target_currency);
                } else {
                    $target_currency = $base_currency;
                }
            }

            $no_decimal_currencies = array('JPY', 'KRW', 'VND', 'IDR', 'CLP', 'PYG', 'UGX');
            $decimal_places = in_array($target_currency, $no_decimal_currencies, true) ? 0 : 2;

            $formatted_amount = sprintf(
                '%s%s',
                $this->get_currency_symbol($target_currency),
                number_format((float) $converted_amount, $decimal_places)
            );

            $cycle_short = $this->get_cycle_short_label($plan['billing_cycle'] ?? '');

            return $cycle_short ? sprintf('%s / %s', $formatted_amount, $cycle_short) : $formatted_amount;
        }

        private function get_cycle_short_label($cycle)
        {
            $cycle = trim((string) $cycle);
            if ($cycle === '') {
                return '';
            }

            $lower = strtolower($cycle);
            if (strpos($lower, 'per ') === 0) {
                return trim(substr($cycle, 4));
            }

            return $cycle;
        }

        private function get_currency_symbol($currency)
        {
            $currency = strtoupper($currency);

            $detector = $this->get_currency_location_detector();
            if ($detector && method_exists($detector, 'get_currency_symbol')) {
                return $detector->get_currency_symbol($currency);
            }

            $map = array(
                'USD' => '$',
                'GBP' => '£',
                'EUR' => '€',
                'AED' => 'د.إ',
                'CAD' => 'C$',
                'AUD' => 'A$',
                'NZD' => 'NZ$',
                'JPY' => '¥',
                'CNY' => '¥',
                'INR' => '₹',
                'CHF' => 'CHF',
                'BRL' => 'R$',
                'ZAR' => 'R',
                'SAR' => 'ر.س'
            );

            return isset($map[$currency]) ? $map[$currency] : $currency . ' ';
        }

        private function get_user_currency_preference()
        {
            if ($this->user_currency_preference !== null) {
                return $this->user_currency_preference;
            }

            $default_currency = strtoupper(get_option('currency_detector_base_currency', 'USD'));
            $supported = get_option('currency_detector_supported_currencies', array('USD', 'EUR', 'GBP'));
            $supported = array_map('strtoupper', (array) $supported);

            if (isset($_COOKIE['currency_detector_currency'])) {
                $cookie_currency = strtoupper(sanitize_text_field($_COOKIE['currency_detector_currency']));
                if (in_array($cookie_currency, $supported, true)) {
                    return $this->user_currency_preference = $cookie_currency;
                }
            }

            $timezone = $this->get_user_timezone_from_cookie();
            $language_header = isset($_SERVER['HTTP_ACCEPT_LANGUAGE']) ? sanitize_text_field($_SERVER['HTTP_ACCEPT_LANGUAGE']) : get_locale();
            $primary_locale = $this->extract_primary_locale($language_header);

            $detector = $this->get_currency_location_detector();
            if ($detector && method_exists($detector, 'detect_currency_from_browser')) {
                $detected = $detector->detect_currency_from_browser($timezone, $primary_locale);
                if (!empty($detected)) {
                    $detected = strtoupper($detected);
                    if (in_array($detected, $supported, true)) {
                        return $this->user_currency_preference = $detected;
                    }
                }
            }

            return $this->user_currency_preference = in_array($default_currency, $supported, true) ? $default_currency : 'USD';
        }

        private function get_currency_exchange_service()
        {
            if ($this->currency_exchange === null) {
                if (class_exists('CurrencyDetector_ExchangeRates')) {
                    $this->currency_exchange = new CurrencyDetector_ExchangeRates();
                } else {
                    $this->currency_exchange = false;
                }
            }

            return $this->currency_exchange ?: null;
        }

        private function get_currency_location_detector()
        {
            if ($this->currency_location_detector === null) {
                if (class_exists('CurrencyDetector_LocationDetector')) {
                    $this->currency_location_detector = new CurrencyDetector_LocationDetector();
                } else {
                    $this->currency_location_detector = false;
                }
            }

            return $this->currency_location_detector ?: null;
        }

        private function get_user_timezone_from_cookie()
        {
            if (isset($_COOKIE['currency_detector_timezone'])) {
                return sanitize_text_field($_COOKIE['currency_detector_timezone']);
            }
            return '';
        }

        private function get_membership_social_proof_stats()
        {
            $timezone = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
            $today = new DateTimeImmutable('now', $timezone);

            return [
                'members' => $this->get_synthetic_member_total($today, $timezone),
                'linkedin' => '32k+',
            ];
        }

        private function get_synthetic_member_total(DateTimeImmutable $today, DateTimeZone $timezone)
        {
            $baseline_total = 812;
            $baseline_date = new DateTimeImmutable('2026-04-02 00:00:00', $timezone);
            $current_day = $today->setTime(0, 0);

            if ($current_day <= $baseline_date) {
                return $baseline_total;
            }

            $increments = [4, 6, 7, 9, 11];
            $total = $baseline_total;
            $cursor = $baseline_date->modify('+1 day');

            while ($cursor <= $current_day) {
                $day_of_week = (int) $cursor->format('N');
                if ($day_of_week >= 6) {
                    $total += 3;
                } else {
                    $index = $this->seeded_int('senna-member-growth-' . $cursor->format('Y-m-d'), 0, count($increments) - 1);
                    $total += $increments[$index];
                }
                $cursor = $cursor->modify('+1 day');
            }

            return $total;
        }

        private function seeded_int($seed, $min, $max)
        {
            $min = (int) $min;
            $max = (int) $max;

            if ($max <= $min) {
                return $min;
            }

            $hash = sprintf('%u', crc32((string) $seed));
            $value = (int) $hash;

            return $min + ($value % ($max - $min + 1));
        }

