                if (array_key_exists($raw_value, $options)) {
                    return $raw_value;
                }
                foreach ($options as $value => $label) {
                    if (strcasecmp($raw_value, (string) $value) === 0 || strcasecmp($raw_value, (string) $label) === 0) {
                        return (string) $value;
