                                <label class="sffc-crm-console-search__field">
                                    <span><?php esc_html_e('Location', 'senna-finance'); ?></span>
                                    <input type="text" name="location" list="<?php echo esc_attr($location_list_id); ?>" value="<?php echo esc_attr((string) $atts['location']); ?>" autocomplete="off">
                                </label>
                                <label class="sffc-crm-console-search__field">
                                    <span><?php esc_html_e('Specialisation', 'senna-finance'); ?></span>
                                    <select name="specialisation">
                                        <?php foreach ($sector_options as $value => $label) : ?>
                                            <option value="<?php echo esc_attr((string) $label); ?>" <?php selected($selected_specialisation, (string) $value); ?>><?php echo esc_html((string) $label); ?></option>
                                        <?php endforeach; ?>
                                    </select>
                                </label>
                                <button type="submit" class="sffc-crm-console-search__submit"><?php echo esc_html((string) $atts['button']); ?></button>
                            </div>
                        </div>
                        <datalist id="<?php echo esc_attr($role_list_id); ?>">
                            <?php foreach ($role_options as $role_option) : ?>
                                <option value="<?php echo esc_attr((string) $role_option); ?>"></option>
                            <?php endforeach; ?>
                        </datalist>
                        <datalist id="<?php echo esc_attr($location_list_id); ?>">
                            <?php foreach ($location_options as $location_option) : ?>
                                <option value="<?php echo esc_attr((string) $location_option); ?>"></option>
                            <?php endforeach; ?>
                        </datalist>
                    </form>

                    <div class="sffc-mena-search-landing__proof" aria-hidden="true">
                        <span><?php esc_html_e('Matched today', 'senna-finance'); ?></span>
                        <strong><?php esc_html_e('Investment Associate', 'senna-finance'); ?></strong>
                        <small><?php esc_html_e('Dubai - Private Equity - 4.2 / 5 fit', 'senna-finance'); ?></small>
                    </div>
                </div>
                <div class="sffc-mena-search-landing__chat">
                    <?php echo $chat_markup; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                </div>
            </section>
            <script>
                (function () {
                    var root = document.getElementById(<?php echo wp_json_encode($instance_id); ?>);
                    if (!root) {
                        return;
                    }
                    var form = root.querySelector('[data-sffc-mena-search-form]');
                    var chat = root.querySelector('[data-sffc-apply-chat]');
                    function fieldValue(name) {
                        var field = form ? form.querySelector('[name="' + name + '"]') : null;
                        return field ? String(field.value || '').trim() : '';
                    }
                    function buildQuery(context) {
                        var parts = [];
                        var seniority = context.seniority && !/^all\b/i.test(context.seniority) ? context.seniority : '';
                        if (seniority && context.role && seniority.toLowerCase() !== context.role.toLowerCase()) {
                            parts.push(context.seniority + ' ' + context.role);
                        } else if (context.role) {
                            parts.push(context.role);
                        }
                        if (context.specialisation) {
                            parts.push(context.specialisation);
                        }
                        var query = parts.join(' ');
                        if (context.location) {
                            query += (query ? ' jobs in ' : 'Jobs in ') + context.location;
                        }
                        return query || 'Finance jobs';
                    }
                    if (!form || !chat) {
                        return;
                    }
                    form.addEventListener('submit', function (event) {
                        var context;
                        event.preventDefault();
                        context = {
                            role: fieldValue('role'),
                            seniority: fieldValue('seniority'),
                            location: fieldValue('location'),
                            specialisation: fieldValue('specialisation')
                        };
                        context.query = buildQuery(context);
                        chat.dispatchEvent(new CustomEvent('sffc:apply-chat-launch-search', {
                            bubbles: true,
                            detail: context
                        }));
                    });
                })();
            </script>
            <?php
            return (string) ob_get_clean();
        }

        /**
         * Horizontal landing-page search form that redirects into the CRM console.
         */
        public function render_crm_console_search($atts)
        {
            $atts = shortcode_atts([
                'action' => home_url('/terminal/'),
                'role' => __('Investment Associate', 'senna-finance'),
                'location' => __('Global', 'senna-finance'),
                'specialisation' => '',
                'seniority' => '',
                'button' => __('Search', 'senna-finance'),
                'signup_url' => wp_login_url(home_url('/terminal/?tab=following')),
            ], $atts);

            wp_enqueue_style(
                'sffc-crm-linkedin',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-linkedin.css',
                [],
                defined('SFFC_VERSION') ? SFFC_VERSION : null
            );

            $style_options = [
                '--sffc-console-search-mode-bg' => get_option('sffc_crm_console_search_mode_bg', 'transparent'),
                '--sffc-console-search-mode-text' => get_option('sffc_crm_console_search_mode_text', '#ffffff'),
                '--sffc-console-search-mode-border' => get_option('sffc_crm_console_search_mode_border', 'rgba(255, 255, 255, 0.34)'),
                '--sffc-console-search-field-bg' => get_option('sffc_crm_console_search_field_bg', '#ffffff'),
                '--sffc-console-search-field-border' => get_option('sffc_crm_console_search_field_border', '#d8dee7'),
                '--sffc-console-search-field-radius' => get_option('sffc_crm_console_search_field_radius', '8px'),
                '--sffc-console-search-label-color' => get_option('sffc_crm_console_search_label_color', '#5f6671'),
                '--sffc-console-search-input-color' => get_option('sffc_crm_console_search_input_color', '#111827'),
                '--sffc-console-search-dropdown-bg' => get_option('sffc_crm_console_search_dropdown_bg', '#ffffff'),
                '--sffc-console-search-dropdown-text' => get_option('sffc_crm_console_search_dropdown_text', '#111827'),
                '--sffc-console-search-dropdown-hover-bg' => get_option('sffc_crm_console_search_dropdown_hover_bg', '#f3f6fb'),
                '--sffc-console-search-dropdown-border' => get_option('sffc_crm_console_search_dropdown_border', 'rgba(17, 24, 39, 0.12)'),
                '--sffc-console-search-dropdown-radius' => get_option('sffc_crm_console_search_dropdown_radius', '8px'),
                '--sffc-console-search-dropdown-shadow' => get_option('sffc_crm_console_search_dropdown_shadow', '0 18px 45px rgba(15, 23, 42, 0.18)'),
                '--sffc-console-search-button-bg' => get_option('sffc_crm_console_search_button_bg', '#9AF2BD'),
                '--sffc-console-search-button-hover-bg' => get_option('sffc_crm_console_search_button_hover_bg', '#7CE6A9'),
                '--sffc-console-search-button-text' => get_option('sffc_crm_console_search_button_text', '#0D353E'),
                '--sffc-console-search-secondary-bg' => get_option('sffc_crm_console_search_secondary_bg', '#ffffff'),
                '--sffc-console-search-secondary-text' => get_option('sffc_crm_console_search_secondary_text', '#111827'),
                '--sffc-console-landing-bg' => get_option('sffc_crm_console_landing_bg', '#0D353E'),
            ];
            $style_attr = '';
            foreach ($style_options as $property => $value) {
                $value = trim((string) $value);
                if ($value !== '') {
                    $style_attr .= $property . ':' . esc_attr($value) . ';';
                }
            }

            global $wpdb;

            $instance_id = function_exists('wp_unique_id') ? wp_unique_id('sffc-crm-console-search-') : 'sffc-crm-console-search-' . wp_rand();
            $role_list_id = $instance_id . 'roles';
            $location_list_id = $instance_id . 'locations';

            $role_options = [
                __('Investment Associate', 'senna-finance'),
                __('Senior Associate', 'senna-finance'),
                __('Vice President', 'senna-finance'),
                __('Principal', 'senna-finance'),
                __('Investment Director', 'senna-finance'),
                __('Portfolio Operations Manager', 'senna-finance'),
                __('Investor Relations Associate', 'senna-finance'),
                __('Fund Finance Manager', 'senna-finance'),
                __('Venture Capital Associate', 'senna-finance'),
                __('Asset Management Associate', 'senna-finance'),
                __('Growth Equity Associate', 'senna-finance'),
                __('Infrastructure Associate', 'senna-finance'),
                __('Portfolio Value Creation Manager', 'senna-finance'),
                __('Hedge Fund Associate', 'senna-finance'),
                __('Private Credit Associate', 'senna-finance'),
                __('Risk Manager', 'senna-finance'),
            ];
            $location_options = [];
            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $posts_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($posts_table))) === $posts_table;

            if ($posts_table_exists) {
                $post_role_options = $wpdb->get_col(
                    "SELECT role_title
                     FROM {$posts_table}
                     WHERE role_title IS NOT NULL AND role_title != '' AND is_active = 1 AND admin_approved = 1
                     GROUP BY role_title
                     ORDER BY COUNT(*) DESC, role_title ASC
                     LIMIT 60"
                );
                if (!empty($post_role_options)) {
                    $role_options = array_merge($role_options, $post_role_options);
                }

                $location_options = $wpdb->get_results(
                    "SELECT TRIM(COALESCE(NULLIF(location, ''), NULLIF(CONCAT_WS(', ', NULLIF(location_city, ''), NULLIF(location_country, '')), ''))) AS location_label,
                            COUNT(*) AS post_count
                     FROM {$posts_table}
                     WHERE is_active = 1 AND admin_approved = 1
                     GROUP BY location_label
                     HAVING location_label != ''
                     ORDER BY post_count DESC, location_label ASC
                     LIMIT 80",
                    ARRAY_A
                );
            }

            $role_options = array_values(array_unique(array_filter(array_map('trim', $role_options))));
            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [];
            $seniority_options = function_exists('sffc_crm_get_seniority_options') ? sffc_crm_get_seniority_options() : [];

            $get_prefill_param = static function ($keys) {
                foreach ((array) $keys as $key) {
                    if (isset($_GET[$key])) {
                        return sanitize_text_field(wp_unslash($_GET[$key]));
                    }
                }
                return null;
            };

            $normalize_choice = static function ($raw_value, array $options) {
                $raw_value = trim((string) $raw_value);
                if ($raw_value === '') {
                    return '';
                }

                if (array_key_exists($raw_value, $options)) {
                    return $raw_value;
                }

                $normalized_raw = strtolower(preg_replace('/[^a-z0-9]+/', '', $raw_value));
                foreach ($options as $value => $label) {
                    $value = (string) $value;
                    $label = (string) $label;
                    if (strcasecmp($raw_value, $label) === 0 || strcasecmp($raw_value, $value) === 0) {
                        return $value;
                    }

                    $normalized_value = strtolower(preg_replace('/[^a-z0-9]+/', '', $value));
                    $normalized_label = strtolower(preg_replace('/[^a-z0-9]+/', '', $label));
                    if ($normalized_raw === $normalized_value || $normalized_raw === $normalized_label) {
                        return $value;
                    }
                }

                return $raw_value;
            };

            $prefill_values = [
                'role' => (string) $atts['role'],
                'location' => (string) $atts['location'],
                'specialisation' => (string) $atts['specialisation'],
                'seniority' => (string) $atts['seniority'],
            ];

            $prefill_post_id = absint($get_prefill_param(['sffc_prefill_post', 'sffc_crm_post_id', 'crm_post_id']));
            if ($prefill_post_id && $posts_table_exists) {
                $prefill_post = $wpdb->get_row($wpdb->prepare(
                    "SELECT role_title, location, location_city, location_country, sector, seniority
                     FROM {$posts_table}
                     WHERE id = %d
                     LIMIT 1",
                    $prefill_post_id
                ), ARRAY_A);

                if (!empty($prefill_post)) {
                    $prefill_location = trim((string) ($prefill_post['location'] ?? ''));
                    if ($prefill_location === '') {
                        $prefill_location = trim(implode(', ', array_filter([
                            trim((string) ($prefill_post['location_city'] ?? '')),
                            trim((string) ($prefill_post['location_country'] ?? '')),
                        ])));
                    }

                    $prefill_values = array_merge($prefill_values, [
                        'role' => trim((string) ($prefill_post['role_title'] ?? '')) ?: $prefill_values['role'],
                        'location' => $prefill_location ?: $prefill_values['location'],
                        'specialisation' => trim((string) ($prefill_post['sector'] ?? '')) ?: $prefill_values['specialisation'],
                        'seniority' => trim((string) ($prefill_post['seniority'] ?? '')) ?: $prefill_values['seniority'],
                    ]);
                }
            }

            $url_role = $get_prefill_param('role');
            $url_location = $get_prefill_param('location');
            $url_specialisation = $get_prefill_param(['specialisation', 'specialization', 'sector']);
            $url_seniority = $get_prefill_param(['seniority', 'experience_level']);

            if ($url_role !== null) {
                $prefill_values['role'] = $url_role;
            }
            if ($url_location !== null) {
                $prefill_values['location'] = $url_location;
            }
            if ($url_specialisation !== null) {
                $prefill_values['specialisation'] = $url_specialisation;
            }
            if ($url_seniority !== null) {
                $prefill_values['seniority'] = $url_seniority;
            }

            $selected_role = trim((string) $prefill_values['role']);
            $selected_location = trim((string) $prefill_values['location']);
            $selected_specialisation = $normalize_choice($prefill_values['specialisation'], $sector_options);
            $selected_seniority = $normalize_choice($prefill_values['seniority'], $seniority_options);

            if ($selected_role !== '' && !in_array($selected_role, $role_options, true)) {
                array_unshift($role_options, $selected_role);
            }
            if ($selected_specialisation !== '' && !isset($sector_options[$selected_specialisation])) {
                $sector_options[$selected_specialisation] = ucwords(str_replace(['_', '-'], ' ', $selected_specialisation));
            }
            if ($selected_seniority !== '' && !isset($seniority_options[$selected_seniority])) {
                $seniority_options[$selected_seniority] = ucwords(str_replace(['_', '-'], ' ', $selected_seniority));
            }

            $selected_criteria_mode = strtolower((string) ($get_prefill_param('criteria_mode') ?? 'single'));
            if ($selected_criteria_mode !== 'multi' && (
                $get_prefill_param('role_2') !== null ||
                $get_prefill_param('location_2') !== null ||
                $get_prefill_param(['specialisation_2', 'specialization_2', 'sector_2']) !== null ||
                $get_prefill_param(['seniority_2', 'experience_level_2']) !== null
            )) {
                $selected_criteria_mode = 'multi';
            }
            if (!in_array($selected_criteria_mode, ['single', 'multi'], true)) {
                $selected_criteria_mode = 'single';
            }

            ob_start();
        ?>
            <form class="sffc-crm-console-search" action="<?php echo esc_url($atts['action']); ?>" method="get" style="<?php echo esc_attr($style_attr); ?>" data-console-search-form data-signup-url="<?php echo esc_url($atts['signup_url']); ?>">
                <input type="hidden" name="tab" value="console">
                <input type="hidden" name="sffc_console_search" value="1">
                <label class="sffc-crm-console-search__mode">
                    <span class="screen-reader-text"><?php esc_html_e('Criteria mode', 'senna-finance'); ?></span>
                    <select name="criteria_mode" data-console-search-mode>
                        <option value="single" <?php selected($selected_criteria_mode, 'single'); ?>><?php esc_html_e('Single Criteria', 'senna-finance'); ?></option>
                        <option value="multi" <?php selected($selected_criteria_mode, 'multi'); ?>><?php esc_html_e('Multi Criteria', 'senna-finance'); ?></option>
                    </select>
                </label>
                <div class="sffc-crm-console-search__bars" data-console-search-bars>
                    <div class="sffc-crm-console-search__bar" data-console-search-bar data-criteria-index="1">
                        <label class="sffc-crm-console-search__field">
                            <span><?php esc_html_e('Role', 'senna-finance'); ?></span>
                            <input type="text" name="role" value="<?php echo esc_attr($selected_role); ?>" list="<?php echo esc_attr($role_list_id); ?>" placeholder="<?php esc_attr_e('Investment Associate', 'senna-finance'); ?>">
                        </label>
                        <label class="sffc-crm-console-search__field">
                            <span><?php esc_html_e('Seniority', 'senna-finance'); ?></span>
                            <select name="seniority">
                                <option value=""><?php esc_html_e('All Seniority', 'senna-finance'); ?></option>
                                <?php foreach ($seniority_options as $value => $label): ?>
                                    <option value="<?php echo esc_attr($value); ?>" <?php selected($selected_seniority, $value); ?>><?php echo esc_html($label); ?></option>
                                <?php endforeach; ?>
                            </select>
                        </label>
                        <label class="sffc-crm-console-search__field">
                            <span><?php esc_html_e('Location', 'senna-finance'); ?></span>
                            <input type="text" name="location" value="<?php echo esc_attr($selected_location); ?>" list="<?php echo esc_attr($location_list_id); ?>" placeholder="<?php esc_attr_e('Global, Remote, or target city', 'senna-finance'); ?>">
                        </label>
                        <label class="sffc-crm-console-search__field">
                            <span><?php esc_html_e('Specialisation', 'senna-finance'); ?></span>
                            <select name="specialisation">
                                <option value=""><?php esc_html_e('All Specialisations', 'senna-finance'); ?></option>
                                <?php foreach ($sector_options as $value => $label): ?>
                                    <option value="<?php echo esc_attr($value); ?>" <?php selected($selected_specialisation, $value); ?>><?php echo esc_html($label); ?></option>
                                <?php endforeach; ?>
                            </select>
                        </label>
                        <button type="submit" class="sffc-crm-console-search__submit">
                            <?php echo esc_html($atts['button']); ?>
                        </button>
                    </div>
                </div>
                <datalist id="<?php echo esc_attr($role_list_id); ?>">
                    <?php foreach ($role_options as $role_option): ?>
                        <option value="<?php echo esc_attr($role_option); ?>"></option>
                    <?php endforeach; ?>
                </datalist>
                <datalist id="<?php echo esc_attr($location_list_id); ?>">
                    <?php foreach ($location_options as $location_option): ?>
                        <option value="<?php echo esc_attr($location_option['location_label']); ?>" label="<?php echo esc_attr(sprintf(_n('%d post', '%d posts', (int) $location_option['post_count'], 'senna-finance'), (int) $location_option['post_count'])); ?>"></option>
                    <?php endforeach; ?>
                </datalist>
                <div class="sffc-crm-console-search__multi-actions" data-console-search-multi-actions hidden>
                    <button type="button" class="sffc-crm-console-search__secondary" data-console-add-criteria><?php esc_html_e('Add Another Criteria', 'senna-finance'); ?></button>
                    <button type="button" class="sffc-crm-console-search__secondary" data-console-save-criteria><?php esc_html_e('Save Criteria', 'senna-finance'); ?></button>
                </div>
            </form>
            <script>
                (function() {
                    var form = document.currentScript.previousElementSibling;
                    if (!form || !form.matches('[data-console-search-form]')) {
                        return;
                    }

                    var mode = form.querySelector('[data-console-search-mode]');
                    var bars = form.querySelector('[data-console-search-bars]');
                    var actions = form.querySelector('[data-console-search-multi-actions]');
                    var addButton = form.querySelector('[data-console-add-criteria]');
                    var saveButton = form.querySelector('[data-console-save-criteria]');
                    var maxCriteria = 5;
                    var activeAutocomplete = null;

                    function escapeHtml(value) {
                        return String(value || '').replace(/[&<>"']/g, function(character) {
                            return {
                                '&': '&amp;',
                                '<': '&lt;',
                                '>': '&gt;',
                                '"': '&quot;',
                                "'": '&#039;'
                            } [character];
                        });
                    }

                    function initAutocompleteInputs(scope) {
                        Array.prototype.slice.call(scope.querySelectorAll('input[list]')).forEach(function(input) {
                            if (input.getAttribute('data-console-autocomplete-ready') === '1') {
                                return;
                            }

                            var sourceListId = input.getAttribute('list') || input.getAttribute('data-console-autocomplete-list');
                            var datalist = document.getElementById(sourceListId);
                            if (!datalist) {
                                return;
                            }

                            input.setAttribute('autocomplete', 'off');
                            input.setAttribute('data-console-autocomplete-list', sourceListId);
                            input.setAttribute('data-console-autocomplete-ready', '1');
                            input.removeAttribute('list');
                            input.setAttribute('role', 'combobox');
                            input.setAttribute('aria-autocomplete', 'list');

                            var field = input.closest('.sffc-crm-console-search__field');
                            var panel = document.createElement('div');
                            panel.className = 'sffc-crm-console-search__suggestions';
                            panel.setAttribute('role', 'listbox');
                            panel.hidden = true;
                            field.appendChild(panel);

                            function getOptions() {
                                return Array.prototype.slice.call(datalist.querySelectorAll('option')).map(function(option) {
                                    return {
                                        value: option.value || '',
                                        label: option.getAttribute('label') || ''
                                    };
                                }).filter(function(option) {
                                    return option.value;
                                });
                            }

                            function closePanel() {
                                panel.hidden = true;
                                input.removeAttribute('aria-activedescendant');
                            }

                            function choose(value) {
                                input.value = value;
                                closePanel();
                                input.dispatchEvent(new Event('change', {
                                    bubbles: true
                                }));
                            }

                            function render() {
                                var query = input.value.trim().toLowerCase();
                                var matches = getOptions().filter(function(option) {
                                    return !query || option.value.toLowerCase().indexOf(query) !== -1;
                                }).slice(0, 8);

                                if (!matches.length) {
                                    closePanel();
                                    return;
                                }

                                Array.prototype.slice.call(form.querySelectorAll('.sffc-crm-console-search__suggestions')).forEach(function(otherPanel) {
                                    if (otherPanel !== panel) {
                                        otherPanel.hidden = true;
                                    }
                                });
                                panel.innerHTML = matches.map(function(option, index) {
                                    var id = input.name + '-suggestion-' + index;
                                    return '<button type="button" id="' + escapeHtml(id) + '" role="option" data-value="' + escapeHtml(option.value) + '"' + (index === 0 ? ' class="is-active"' : '') + '>' +
                                        '<span>' + escapeHtml(option.value) + '</span>' +
                                        (option.label ? '<small>' + escapeHtml(option.label) + '</small>' : '') +
                                        '</button>';
                                }).join('');
                                panel.hidden = false;
                                activeAutocomplete = {
                                    input: input,
                                    panel: panel
                                };
                            }

                            input.addEventListener('focus', render);
                            input.addEventListener('input', render);
                            input.addEventListener('keydown', function(event) {
                                if (panel.hidden) {
                                    return;
                                }

                                var items = Array.prototype.slice.call(panel.querySelectorAll('button'));
                                var activeIndex = items.findIndex(function(item) {
                                    return item.classList.contains('is-active');
                                });

                                if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                                    event.preventDefault();
                                    if (!items.length) {
                                        return;
                                    }
                                    items.forEach(function(item) {
                                        item.classList.remove('is-active');
                                    });
                                    activeIndex = event.key === 'ArrowDown' ? activeIndex + 1 : activeIndex - 1;
                                    if (activeIndex < 0) {
                                        activeIndex = items.length - 1;
                                    }
                                    if (activeIndex >= items.length) {
                                        activeIndex = 0;
                                    }
                                    items[activeIndex].classList.add('is-active');
                                    input.setAttribute('aria-activedescendant', items[activeIndex].id);
                                } else if (event.key === 'Enter') {
                                    var activeItem = items[activeIndex] || items[0];
                                    if (activeItem) {
                                        event.preventDefault();
                                        choose(activeItem.getAttribute('data-value'));
                                    }
                                } else if (event.key === 'Escape') {
                                    closePanel();
                                }
                            });

                            panel.addEventListener('mousedown', function(event) {
                                var button = event.target.closest('button[data-value]');
                                if (!button) {
                                    return;
                                }
                                event.preventDefault();
                                choose(button.getAttribute('data-value'));
                            });
                        });
                    }

                    function closeActivePanel() {
                        if (!activeAutocomplete) {
                            return;
                        }
                        activeAutocomplete.panel.hidden = true;
                        if (activeAutocomplete.input) {
                            activeAutocomplete.input.removeAttribute('aria-activedescendant');
                        }
                        if (activeAutocomplete.trigger) {
                            activeAutocomplete.trigger.setAttribute('aria-expanded', 'false');
                        }
                        activeAutocomplete = null;
                    }

                    function initCustomSelects(scope) {
                        Array.prototype.slice.call(scope.querySelectorAll('.sffc-crm-console-search__field select')).forEach(function(select) {
                            if (select.getAttribute('data-console-select-ready') === '1') {
                                return;
                            }

                            var field = select.closest('.sffc-crm-console-search__field');
                            if (!field) {
                                return;
                            }

                            select.setAttribute('data-console-select-ready', '1');
                            select.classList.add('sffc-crm-console-search__native-select');
                            select.setAttribute('tabindex', '-1');

                            var trigger = document.createElement('button');
                            trigger.type = 'button';
                            trigger.className = 'sffc-crm-console-search__select-trigger';
                            trigger.setAttribute('aria-haspopup', 'listbox');
                            trigger.setAttribute('aria-expanded', 'false');

                            var panel = document.createElement('div');
                            panel.className = 'sffc-crm-console-search__suggestions sffc-crm-console-search__select-panel';
                            panel.setAttribute('role', 'listbox');
                            panel.hidden = true;

                            function selectedOption() {
                                return select.options[select.selectedIndex] || select.options[0];
                            }

                            function syncTrigger() {
                                var option = selectedOption();
                                trigger.innerHTML = '<span>' + escapeHtml(option ? option.text : '') + '</span>';
                            }

                            function renderOptions() {
                                panel.innerHTML = Array.prototype.slice.call(select.options).map(function(option, index) {
                                    var selected = option.selected ? ' is-active' : '';
                                    return '<button type="button" role="option" data-index="' + index + '" class="' + selected.trim() + '" aria-selected="' + (option.selected ? 'true' : 'false') + '">' +
                                        '<span>' + escapeHtml(option.text) + '</span>' +
                                        '</button>';
                                }).join('');
                            }

                            function choose(index) {
                                select.selectedIndex = index;
                                syncTrigger();
                                closeActivePanel();
                                select.dispatchEvent(new Event('change', {
                                    bubbles: true
                                }));
                            }

                            function openPanel() {
                                Array.prototype.slice.call(form.querySelectorAll('.sffc-crm-console-search__suggestions')).forEach(function(otherPanel) {
                                    if (otherPanel !== panel) {
                                        otherPanel.hidden = true;
                                    }
                                });
                                renderOptions();
                                panel.hidden = false;
                                trigger.setAttribute('aria-expanded', 'true');
                                activeAutocomplete = {
                                    trigger: trigger,
                                    panel: panel
                                };
                            }

                            syncTrigger();
                            select.insertAdjacentElement('afterend', trigger);
                            field.appendChild(panel);

                            trigger.addEventListener('click', function(event) {
                                event.preventDefault();
                                event.stopPropagation();
                                if (panel.hidden) {
                                    openPanel();
                                } else {
                                    closeActivePanel();
                                }
                            });

                            trigger.addEventListener('keydown', function(event) {
                                var items;
                                var activeIndex;
                                if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                                    event.preventDefault();
                                    if (panel.hidden) {
                                        openPanel();
                                    }
                                    items = Array.prototype.slice.call(panel.querySelectorAll('button'));
                                    activeIndex = items.findIndex(function(item) {
                                        return item.classList.contains('is-active');
                                    });
                                    items.forEach(function(item) {
                                        item.classList.remove('is-active');
                                    });
                                    activeIndex = event.key === 'ArrowDown' ? activeIndex + 1 : activeIndex - 1;
                                    if (activeIndex < 0) {
                                        activeIndex = items.length - 1;
                                    }
                                    if (activeIndex >= items.length) {
                                        activeIndex = 0;
                                    }
                                    if (items[activeIndex]) {
                                        items[activeIndex].classList.add('is-active');
                                    }
                                } else if (event.key === 'Enter' || event.key === ' ') {
                                    event.preventDefault();
                                    if (panel.hidden) {
                                        openPanel();
                                        return;
                                    }
                                    items = Array.prototype.slice.call(panel.querySelectorAll('button'));
                                    activeIndex = items.findIndex(function(item) {
                                        return item.classList.contains('is-active');
                                    });
                                    if (items[activeIndex]) {
                                        choose(parseInt(items[activeIndex].getAttribute('data-index'), 10));
                                    }
                                } else if (event.key === 'Escape') {
                                    closeActivePanel();
                                }
                            });

                            panel.addEventListener('mousedown', function(event) {
                                var button = event.target.closest('button[data-index]');
                                if (!button) {
                                    return;
                                }
                                event.preventDefault();
                                choose(parseInt(button.getAttribute('data-index'), 10));
                            });
                        });
                    }

                    function setBarNames(bar, index) {
                        var suffix = index === 1 ? '' : '_' + index;
                        bar.classList.toggle('is-additional', index > 1);
                        Array.prototype.slice.call(bar.querySelectorAll('.sffc-crm-console-search__suggestions')).forEach(function(panel) {
                            panel.remove();
                        });
                        Array.prototype.slice.call(bar.querySelectorAll('.sffc-crm-console-search__select-trigger')).forEach(function(trigger) {
                            trigger.remove();
                        });
                        ['role', 'seniority', 'location', 'specialisation'].forEach(function(name) {
                            var input = bar.querySelector('[name^="' + name + '"]');
                            if (input) {
                                input.name = name + suffix;
                                input.removeAttribute('data-console-autocomplete-ready');
                                input.removeAttribute('data-console-select-ready');
                                input.classList.remove('sffc-crm-console-search__native-select');
                                input.removeAttribute('tabindex');
                                if (index > 1) {
                                    input.value = '';
                                }
                            }
                        });
                        if (index > 1) {
                            var submitButton = bar.querySelector('.sffc-crm-console-search__submit');
                            if (submitButton) {
                                submitButton.remove();
                            }
                        }
                        bar.setAttribute('data-criteria-index', String(index));
                        initAutocompleteInputs(bar);
                        initCustomSelects(bar);
                    }

                    function syncMode() {
                        var isMulti = mode && mode.value === 'multi';
                        if (actions) {
                            actions.hidden = !isMulti;
                        }
                        if (isMulti && bars && bars.querySelectorAll('[data-console-search-bar]').length === 1) {
                            var secondBar = bars.querySelector('[data-console-search-bar]').cloneNode(true);
                            setBarNames(secondBar, 2);
                            bars.appendChild(secondBar);
                        }
                        if (!isMulti && bars) {
                            Array.prototype.slice.call(bars.querySelectorAll('[data-console-search-bar]'), 1).forEach(function(bar) {
                                bar.remove();
                            });
                        }
                    }

                    if (mode) {
                        mode.addEventListener('change', syncMode);
                    }

                    if (addButton && bars) {
                        addButton.addEventListener('click', function() {
                            var currentBars = bars.querySelectorAll('[data-console-search-bar]');
                            if (currentBars.length >= maxCriteria) {
                                return;
                            }
                            var clone = currentBars[0].cloneNode(true);
                            setBarNames(clone, currentBars.length + 1);
                            bars.appendChild(clone);
                        });
                    }

                    if (saveButton) {
                        saveButton.addEventListener('click', function() {
                            window.location.href = form.getAttribute('data-signup-url') || '/login/';
                        });
                    }

                    initAutocompleteInputs(form);
                    initCustomSelects(form);
                    document.addEventListener('mousedown', function(event) {
                        if (!activeAutocomplete) {
                            return;
                        }
                        if (
                            activeAutocomplete.input === event.target ||
                            activeAutocomplete.trigger === event.target ||
                            activeAutocomplete.panel.contains(event.target)
                        ) {
                            return;
                        }
                        closeActivePanel();
                    });
                })();
            </script>
            <?php
            return ob_get_clean();
        }

        /**
         * LinkedIn-style CRM experience
         */
        public function render_crm_linkedin_header_right_shortcode($atts)
        {
            $atts = shortcode_atts([
                'default_tab' => 'console',
            ], $atts);

            wp_enqueue_style(
                'sffc-crm-linkedin-header-embed',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-linkedin-header-embed.css',
                [],
                defined('SFFC_VERSION') ? SFFC_VERSION : null
            );

            $current_user = wp_get_current_user();
            $is_logged_in = is_user_logged_in();
            $display_name = $is_logged_in && !empty($current_user->display_name)
                ? $current_user->display_name
                : __('Guest', 'senna-finance');
            $profile_avatar_url = $is_logged_in ? $this->get_current_user_profile_avatar_url($current_user) : '';
            $avatar_initial = strtoupper(function_exists('mb_substr') ? mb_substr($display_name, 0, 1) : substr($display_name, 0, 1));
            if (!$avatar_initial) {
                $avatar_initial = 'G';
            }

            $standalone_tabs = $is_logged_in
                ? ['console', 'mentorship', 'application-packs', 'resource-library', 'intros', 'following', 'markets', 'profile', 'feed']
                : ['resource-library', 'console', 'mentorship', 'markets'];
            $default_tab = $is_logged_in ? $atts['default_tab'] : 'resource-library';

            return $this->get_crm_linkedin_header_right_html([
                'tabs' => $standalone_tabs,
                'default_tab' => $default_tab,
                'is_logged_in' => $is_logged_in,
                'current_user' => $current_user,
                'profile_avatar_url' => $profile_avatar_url,
                'avatar_initial' => $avatar_initial,
                'dashboard_url' => home_url('/terminal/?tab=console'),
                'standalone' => true,
            ]);
        }

        private function get_current_user_profile_avatar_url($current_user)
        {
            $default_guest_avatar = 'https://media.joinsenna.com/2025/05/bb-profile-avatar-buddyboss.webp';
            $user_id = ($current_user instanceof WP_User) ? (int) $current_user->ID : 0;
            if (!$user_id) {
                return $default_guest_avatar;
            }

            $custom_avatar_key = class_exists('SFFC_User_Preferences') ? SFFC_User_Preferences::META_PROFILE_AVATAR : 'sffc_profile_avatar';
            $custom_profile_avatar = get_user_meta($user_id, $custom_avatar_key, true);
            if (!empty($custom_profile_avatar)) {
                return (string) $custom_profile_avatar;
            }

            $gravatar_data = get_avatar_data($user_id, ['size' => 256, 'default' => '404']);
            if (!empty($gravatar_data['found_avatar']) && !empty($gravatar_data['url'])) {
                return (string) $gravatar_data['url'];
            }

            return $default_guest_avatar;
        }

