            ob_start();
            ?>
            <div class="sffc-crm-header-right<?php echo $standalone ? ' sffc-crm-header-right--standalone' : ''; ?>">
                <nav class="sffc-crm-tabs" role="tablist">
                    <?php foreach ($top_tabs as $tab_key):
                        $is_active = ($tab_key === $default_tab);
                        $is_criteria_locked_tab = false;
                        $external = '';
                        $tab_url = $standalone ? home_url('/terminal/?tab=' . $tab_key) : '';
                    ?>
                        <?php if ($standalone): ?>
                            <a href="<?php echo esc_url($tab_url); ?>"
                                class="sffc-crm-tab<?php echo $is_active ? ' active' : ''; ?><?php echo $is_criteria_locked_tab ? ' is-criteria-locked' : ''; ?>"
                                <?php echo $is_active ? 'aria-current="page"' : ''; ?>>
                                <span class="sffc-crm-tab-icon" aria-hidden="true"><?php echo $tab_icons[$tab_key]; ?></span>
                                <span class="sffc-crm-tab-label"><?php echo esc_html($tab_labels[$tab_key]); ?></span>
                            </a>
                        <?php else: ?>
                            <button type="button"
                                class="sffc-crm-tab<?php echo $is_active ? ' active' : ''; ?><?php echo $is_criteria_locked_tab ? ' is-criteria-locked' : ''; ?>"
                                data-tab="<?php echo esc_attr($tab_key); ?>"
                                <?php echo $is_criteria_locked_tab ? 'aria-disabled="true"' : ''; ?>
                                <?php if ($external): ?>data-external="<?php echo esc_url($external); ?>" <?php endif; ?>>
                                <span class="sffc-crm-tab-icon" aria-hidden="true"><?php echo $tab_icons[$tab_key]; ?></span>
                                <span class="sffc-crm-tab-label"><?php echo esc_html($tab_labels[$tab_key]); ?></span>
                            </button>
                        <?php endif; ?>
                    <?php endforeach; ?>
                </nav>
                <div class="sffc-crm-linkedin-profile">
                    <button type="button" class="sffc-crm-profile-toggle" aria-expanded="false" aria-label="<?php esc_attr_e('Profile menu', 'senna-finance'); ?>">
                        <div class="sffc-crm-linkedin-avatar">
                            <?php if ($profile_avatar_url): ?>
                                <img src="<?php echo esc_url($profile_avatar_url); ?>" alt="<?php echo esc_attr($current_user->display_name ?: __('MENA Careers member', 'senna-finance')); ?>">
                            <?php else: ?>
                                <span><?php echo esc_html($avatar_initial); ?></span>
                            <?php endif; ?>
                        </div>
                        <svg class="sffc-crm-profile-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <polyline points="6 9 12 15 18 9"></polyline>
                        </svg>
                    </button>
                    <div class="sffc-user-menu" role="menu" aria-label="<?php esc_attr_e('User menu', 'senna-finance'); ?>">
                        <?php if ($is_logged_in): ?>
                            <div class="sffc-user-menu-header">
                                <div class="sffc-crm-linkedin-avatar sffc-crm-linkedin-avatar-lg">
                                    <?php if ($profile_avatar_url): ?>
                                        <img src="<?php echo esc_url($profile_avatar_url); ?>" alt="<?php echo esc_attr($current_user->display_name); ?>">
                                    <?php else: ?>
                                        <span><?php echo esc_html($avatar_initial); ?></span>
                                    <?php endif; ?>
                                </div>
                                <div class="sffc-user-menu-info">
                                    <strong><?php echo esc_html($current_user->display_name); ?></strong>
                                    <span><?php echo esc_html($current_user->user_email); ?></span>
                                </div>
                            </div>
                            <nav class="sffc-user-menu-nav">
                                <a href="<?php echo esc_url(add_query_arg('tab', 'profile')); ?>" class="sffc-user-menu-item">
                                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                                        <circle cx="12" cy="7" r="4" />
                                    </svg>
                                    <?php esc_html_e('View Profile', 'senna-finance'); ?>
                                </a>
                                <a href="<?php echo esc_url($dashboard_url); ?>" class="sffc-user-menu-item">
                                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <rect x="3" y="3" width="7" height="7" />
                                        <rect x="14" y="3" width="7" height="7" />
                                        <rect x="14" y="14" width="7" height="7" />
                                        <rect x="3" y="14" width="7" height="7" />
                                    </svg>
	                                        <?php esc_html_e('Recruiter Matches', 'senna-finance'); ?>
                                </a>
                                <a href="<?php echo esc_url(home_url('/terminal/?tab=console')); ?>" class="sffc-user-menu-item">
                                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
                                        <circle cx="9" cy="7" r="4" />
                                        <path d="M22 21v-2a4 4 0 0 0-3-3.87" />
                                        <path d="M16 3.13a4 4 0 0 1 0 7.75" />
                                    </svg>
                                    <?php esc_html_e('Matches', 'senna-finance'); ?>
                                </a>
                                <a href="<?php echo esc_url(wp_logout_url(home_url())); ?>" class="sffc-user-menu-item sffc-user-menu-item-logout">
                                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
                                        <polyline points="16 17 21 12 16 7" />
                                        <line x1="21" y1="12" x2="9" y2="12" />
                                    </svg>
                                    <?php esc_html_e('Sign Out', 'senna-finance'); ?>
                                </a>
                            </nav>
                        <?php else: ?>
                            <div class="sffc-user-menu-guest">
                                <p><?php esc_html_e('Sign in to access your personalized career dashboard', 'senna-finance'); ?></p>
                                <a class="sffc-crm-btn sffc-crm-btn-primary" href="<?php echo esc_url(home_url('/join/')); ?>">
                                    <?php esc_html_e('Sign In', 'senna-finance'); ?>
                                </a>
                            </div>
                        <?php endif; ?>
                    </div>
                </div>
            </div>
        <?php

            return ob_get_clean();
        }

        public function render_crm_linkedin($atts)
        {
            $atts = shortcode_atts([
                'default_tab' => 'console',
            ], $atts);

            $tabs = ['console', 'mentorship', 'application-packs', 'resource-library', 'intros', 'following', 'markets', 'dashboard', 'profile', 'feed'];
            $requested_tab = '';
            if (!empty($_GET['tab'])) {
                $raw_requested_tab = sanitize_key(wp_unslash($_GET['tab']));
                if ($raw_requested_tab === 'prep') {
                    $raw_requested_tab = 'intros';
                } elseif ($raw_requested_tab === 'lists') {
                    $raw_requested_tab = 'application-packs';
                } elseif ($raw_requested_tab === 'matches') {
                    $raw_requested_tab = 'console';
                }
                if (in_array($raw_requested_tab, $tabs, true)) {
                    $requested_tab = $raw_requested_tab;
                    $atts['default_tab'] = $requested_tab;
                }
            }
            $is_console_search_request = !empty($_GET['sffc_console_search']);

            $current_user = wp_get_current_user();
            $user_id = get_current_user_id();
            $is_logged_in = $user_id > 0;
            if ($requested_tab === '') {
                $atts['default_tab'] = 'console';
            }
            $dashboard_first_name = __('Your', 'senna-finance');
            if ($is_logged_in) {
                $dashboard_first_name = trim((string) $current_user->first_name);
                if ($dashboard_first_name === '' && !empty($current_user->display_name)) {
                    $dashboard_name_parts = preg_split('/\s+/', trim((string) $current_user->display_name));
                    $dashboard_first_name = $dashboard_name_parts[0] ?? '';
                }
                if ($dashboard_first_name !== '') {
                    $dashboard_first_char = function_exists('mb_substr') ? mb_substr($dashboard_first_name, 0, 1) : substr($dashboard_first_name, 0, 1);
                    $dashboard_remaining_chars = function_exists('mb_substr') ? mb_substr($dashboard_first_name, 1) : substr($dashboard_first_name, 1);
                    $dashboard_first_name = (function_exists('mb_strtoupper') ? mb_strtoupper($dashboard_first_char) : strtoupper($dashboard_first_char)) . $dashboard_remaining_chars;
                } else {
                    $dashboard_first_name = __('Your', 'senna-finance');
                }
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
            $user_criteria_model = new SFFC_CRM_User_Criteria();

            if ($is_logged_in) {
                $this->maybe_sync_dubai_career_preferences($user_id);
            }

            // Load user job preferences
            $job_preferences = [];
            $user_criteria_groups = [];
            if ($is_logged_in) {
                $job_preferences = sffc_crm_get_job_preferences($user_id);

                // Create the two default criteria groups once; user edits should not be overwritten on refresh.
                $user_criteria_model->create_default_groups($user_id, $job_preferences);

                // Get user's criteria groups
                $user_criteria_groups = $user_criteria_model->get_user_criteria($user_id);
            }

            $primary_matches_criteria = null;
            $needs_matches_onboarding = $is_logged_in;
            foreach ($user_criteria_groups as $criteria_group) {
                $criteria_slug = strtolower((string) ($criteria_group['slug'] ?? ''));
                if (!empty($criteria_group['is_default']) && strpos($criteria_slug, 'best-matches') === 0) {
                    $primary_matches_criteria = $criteria_group;
                    break;
                }
            }
            if (!$primary_matches_criteria && !empty($user_criteria_groups)) {
                $primary_matches_criteria = $user_criteria_groups[0];
            }
            if ($primary_matches_criteria) {
                $normalized_primary_criteria = $user_criteria_model->normalize_criteria($primary_matches_criteria);
                $needs_matches_onboarding = empty($normalized_primary_criteria['job_title_list'])
                    || empty($normalized_primary_criteria['location_list'])
                    || trim((string) ($normalized_primary_criteria['years_experience'] ?? '')) === '';
            }
            $crm_membership_url = $this->get_canonical_membership_url();
            $show_console_landing = $atts['default_tab'] === 'console' && !$is_console_search_request;
            $has_membership_access = false;
            if ($is_logged_in) {
                if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                    $crm_memberpress = SFFC_CRM_MemberPress_Integration::get_instance();
                    $member_tier = $crm_memberpress->get_crm_tier($user_id);
                    $has_membership_access = in_array($member_tier, ['insider', 'pro'], true);
                } elseif (class_exists('SFFC_MemberPress_Integration')) {
                    $mepr = SFFC_MemberPress_Integration::get_instance();
                    $has_membership_access = $mepr->has_premium_access($user_id);
                } elseif (user_can($user_id, 'manage_options')) {
                    $has_membership_access = true;
                }
            }
            $mentorship_locked = !$has_membership_access;

            $post_model = new SFFC_CRM_Post();
            $feed_posts = $post_model->get_feed([
                'per_page' => 12,
                'user_id' => $user_id,
            ]);

            if (!empty($feed_posts)) {
                foreach ($feed_posts as &$feed_post) {
                    if (!empty($feed_post['company_logo'])) {
                        $feed_post['company_logo'] = $this->normalize_company_logo_url($feed_post['company_logo']);
                        continue;
                    }

                    if (!empty($feed_post['wp_post_id'])) {
                        $meta_logo = get_post_meta((int) $feed_post['wp_post_id'], '_company_logo', true);
                        if ($meta_logo) {
                            $feed_post['company_logo'] = $this->normalize_company_logo_url($meta_logo);
                        }
                    }
                }
                unset($feed_post);
            }

            $pipeline_model = new SFFC_CRM_Pipeline();
            $pipeline_items = $is_logged_in ? $pipeline_model->get_user_pipeline($user_id) : [];
            $pipeline_stats = $is_logged_in ? $pipeline_model->get_user_stats($user_id) : [
                'total' => 0,
                'by_stage' => [],
                'by_outcome' => [
                    'won' => 0,
                    'lost' => 0,
                    'withdrawn' => 0,
                ],
            ];

            $stage_meta = SFFC_CRM_Pipeline::get_stages();
            $stage_order_map = [];
            foreach ($stage_meta as $stage_key => $stage_data) {
                $stage_order_map[$stage_key] = $stage_data['order'] ?? 999;
            }

            $pipeline_lookup_by_post = [];
            if (!empty($pipeline_items)) {
                foreach ($pipeline_items as $pipeline_item) {
                    if (!empty($pipeline_item['post_id'])) {
                        $pipeline_lookup_by_post[(int) $pipeline_item['post_id']] = $pipeline_item;
                    }
                }
            }

            $following_items = [];
            foreach ($pipeline_items as $item) {
                $stage_key = isset($stage_meta[$item['stage']]) ? $item['stage'] : 'not_applied';
                $following_items[] = [
                    'id' => $item['id'],
                    'role' => $item['role_title'] ?: ($item['company'] ?: __('Opportunity', 'senna-finance')),
                    'company' => $item['company'] ?: '',
                    'location' => $item['location'] ?: '',
                    'stage' => $stage_key,
                    'recruiter' => $item['recruiter_name'] ?: '',
                    'notes' => $item['notes'] ?: '',
                    'updated_at' => $item['updated_at'] ?: $item['stage_entered_at'],
                    'post_id' => $item['post_id'],
                ];
            }

            usort($following_items, function ($a, $b) use ($stage_order_map) {
                $a_order = $stage_order_map[$a['stage']] ?? 999;
                $b_order = $stage_order_map[$b['stage']] ?? 999;
                if ($a_order === $b_order) {
                    return strcmp($a['role'], $b['role']);
                }
                return $a_order <=> $b_order;
            });

            $default_guest_avatar = 'https://media.joinsenna.com/2026/01/sennaLogoOfficial.png?1767629924';
            $custom_avatar_key = class_exists('SFFC_User_Preferences') ? SFFC_User_Preferences::META_PROFILE_AVATAR : 'sffc_profile_avatar';
            $custom_profile_avatar = $is_logged_in ? get_user_meta($user_id, $custom_avatar_key, true) : '';
            // Don't use Gravatar - only show custom uploaded avatars or placeholder initials
            $profile_avatar_url = $custom_profile_avatar;
            $has_custom_avatar = !empty($profile_avatar_url);

            $initial_source = $current_user->first_name ?: ($current_user->display_name ?: $current_user->user_login);
            $initial_source = $initial_source ?: get_bloginfo('name');
            $avatar_initial = strtoupper(function_exists('mb_substr') ? mb_substr($initial_source, 0, 1) : substr($initial_source, 0, 1));
            if (!$avatar_initial) {
                $avatar_initial = 'G';
            }

            $learning_url = home_url('/senna-ai/');
            $coaching_url = get_option('sffc_crm_coaching_url', home_url('/senna-coaching/'));
            $booking_url = get_option('sffc_crm_booking_url', home_url('/senna-booking/'));
            $dashboard_url = home_url('/terminal/?tab=console');

            $status_summary = [];
            foreach ($stage_meta as $stage_key => $stage_data) {
                $status_summary[] = [
                    'key' => $stage_key,
                    'label' => $stage_data['label'],
                    'color' => $stage_data['color'],
                    'count' => $pipeline_stats['by_stage'][$stage_key] ?? 0,
                ];
            }

            $interview_stage_keys = ['online_assessment', 'case_study', 'hirevue', 'telephone_interview', 'video_interview', 'face_to_face_interview', 'assessment_centre'];
            $interview_count = 0;
            foreach ($interview_stage_keys as $stage_key) {
                $interview_count += $pipeline_stats['by_stage'][$stage_key] ?? 0;
            }

            $offer_count = $pipeline_stats['by_stage']['offer_received'] ?? 0;

            global $wpdb;

            // Get total active jobs count for console progress display
            $total_jobs_on_senna = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sffc_crm_posts WHERE is_active = 1 AND admin_approved = 1");
            if ($total_jobs_on_senna < 100) {
                $total_jobs_on_senna = 850; // Fallback minimum for display (use realistic number)
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-company-prep.php';
            $company_prep_model = new SFFC_CRM_Company_Prep();
            $company_prep_records = $company_prep_model->get_all([
                'active_only' => true,
                'orderby' => 'company_name',
                'order' => 'ASC',
            ]);

            $company_prep_cards = [];
            $company_prep_total_materials = 0;

            if (!empty($company_prep_records)) {
                foreach ($company_prep_records as $prep_company) {
                    $regions_display = '';
                    if (!empty($prep_company['regions_covered'])) {
                        $decoded_regions = json_decode($prep_company['regions_covered'], true);
                        if (json_last_error() === JSON_ERROR_NONE && is_array($decoded_regions)) {
                            $clean_regions = array_filter(array_map('trim', $decoded_regions));
                            $regions_display = implode(', ', $clean_regions);
                        } else {
                            $regions_display = $prep_company['regions_covered'];
                        }
                    }

                    $materials_count = $company_prep_model->get_materials_count($prep_company['id']);
                    $company_prep_total_materials += $materials_count;

                    $company_prep_cards[] = [
                        'id' => (int) $prep_company['id'],
                        'name' => $prep_company['company_name'],
                        'logo' => $prep_company['logo_url'],
                        'banner' => $prep_company['banner_url'],
                        'location' => $prep_company['location'],
                        'regions' => $regions_display,
                        'website' => $prep_company['company_website'],
                        'materials_count' => $materials_count,
                    ];
                }
            }

            $company_prep_requests = [];
            if ($is_logged_in && !empty($company_prep_cards)) {
                $user_prep_requests = $company_prep_model->get_requests(['user_id' => $user_id]);
                foreach ($user_prep_requests as $prep_request) {
                    $company_prep_requests[(int) $prep_request['company_id']] = [
                        'status' => $prep_request['status'],
                        'materials_sent' => (int) $prep_request['materials_sent'],
                        'notes' => $prep_request['notes'],
                    ];
                }
            }

            $intro_requests = $is_logged_in ? $this->get_intro_requests_for_user($user_id) : [];
            $intro_lookup_by_post = [];
            foreach ($intro_requests as $intro_request) {
                if (!empty($intro_request['job_id'])) {
                    $intro_lookup_by_post[(int) $intro_request['job_id']] = $intro_request;
                }
            }
            $apply_all_credit_summary = $this->get_apply_all_credit_summary($user_id);
            $has_resume_document = $is_logged_in ? $this->user_has_resume_document($user_id) : false;

            $prep_status_templates = [
                'pending' => [
                    'label' => __('Pending approval', 'senna-finance'),
                    'help' => __('Our prep team is packaging your kit.', 'senna-finance'),
                    'class' => 'is-pending',
                ],
                'approved_sent' => [
                    'label' => __('Delivered', 'senna-finance'),
                    'help' => __('We emailed the download links to you.', 'senna-finance'),
                    'class' => 'is-approved',
                ],
                'approved_manual' => [
                    'label' => __('Approved', 'senna-finance'),
                    'help' => __('A MENA Careers coach will send a bespoke pack shortly.', 'senna-finance'),
                    'class' => 'is-approved',
                ],
                'rejected' => [
                    'label' => __('Request declined', 'senna-finance'),
                    'help' => __('Check your email for more details or reply to our team.', 'senna-finance'),
                    'class' => 'is-rejected',
                ],
            ];

            $spotlight_companies = [];
            $spotlight_archive_url = '';
            if (post_type_exists('sffc_recruiter_post')) {
                $spotlight_archive_url = get_post_type_archive_link('sffc_recruiter_post');
                $spotlight_posts = get_posts([
                    'post_type' => 'sffc_recruiter_post',
                    'post_status' => 'publish',
                    'posts_per_page' => 4,
                    'orderby' => 'date',
                    'order' => 'DESC',
                    'no_found_rows' => true,
                ]);

                foreach ($spotlight_posts as $spotlight_post) {
                    $post_id = $spotlight_post->ID;
                    $company_name = get_post_meta($post_id, '_company_name', true);
                    $recruiter_name = get_post_meta($post_id, '_recruiter_name', true);
                    $recruiter_firm = get_post_meta($post_id, '_recruiter_company', true);
                    $job_location = get_post_meta($post_id, '_job_location', true);
                    $recruiter_image_id = get_post_meta($post_id, '_recruiter_image_id', true);
                    $recruiter_image_url = '';
                    if ($recruiter_image_id) {
                        $recruiter_image_url = wp_get_attachment_image_url($recruiter_image_id, 'thumbnail') ?: '';
                    }
                    if (!$recruiter_image_url) {
                        $recruiter_image_url = get_post_meta($post_id, '_recruiter_image_url', true);
                    }

                    $post_type_terms = wp_get_post_terms($post_id, 'recruiter_post_type', ['fields' => 'names']);
                    $industry_terms = wp_get_post_terms($post_id, 'recruiter_post_industry', ['fields' => 'names']);
                    $location_terms = wp_get_post_terms($post_id, 'recruiter_post_location', ['fields' => 'names']);

                    $company_logo_meta = get_post_meta($post_id, '_company_logo', true);
                    $crm_post_id = (int) get_post_meta($post_id, '_crm_post_id', true);
                    $company_logo_crm = '';
                    if (!$company_logo_meta && $crm_post_id && isset($wpdb)) {
                        $company_logo_crm = $wpdb->get_var($wpdb->prepare(
                            "SELECT company_logo FROM {$wpdb->prefix}sffc_crm_posts WHERE id = %d",
                            $crm_post_id
                        ));
                    }
                    $company_logo = $this->normalize_company_logo_url($company_logo_meta ?: ($company_logo_crm ?: ''));

                    $industry_terms = is_wp_error($industry_terms) ? [] : $industry_terms;
                    $primary_industry = !empty($industry_terms) ? $industry_terms[0] : __('Financial Services', 'senna-finance');

                    $company_label = $company_name ?: get_the_title($spotlight_post);
                    $company_slug = $company_label ? sanitize_title($company_label) : sanitize_title($spotlight_post->ID);

                    $spotlight_companies[] = [
                        'title' => get_the_title($spotlight_post),
                        'permalink' => get_permalink($spotlight_post),
                        'company' => $company_name,
                        'company_display' => $company_label,
                        'company_logo' => $company_logo,
                        'slug' => $company_slug,
                        'recruiter' => $recruiter_name,
                        'recruiter_firm' => $recruiter_firm,
                        'recruiter_avatar' => $recruiter_image_url,
                        'recruiter_initial' => $recruiter_name ? strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name, 0, 1) : substr($recruiter_name, 0, 1)) : __('S', 'senna-finance'),
                        'location_meta' => $job_location,
                        'post_types' => $post_type_terms,
                        'industries' => $industry_terms,
                        'primary_industry' => $primary_industry,
                        'locations' => is_wp_error($location_terms) ? [] : $location_terms,
                        'date' => get_the_date(get_option('date_format'), $spotlight_post),
                    ];
                }
            }

            // Load groups from database
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $dashboard_groups = $group_model->get_all([
                'is_active' => 1,
                'include_post_count' => false
            ]);

            // Load posts for each group
            foreach ($dashboard_groups as &$group) {
                $group['items'] = $group_model->get_posts_by_group($group['id'], [
                    'limit' => 5,
                    'is_active' => 1,
                    'admin_approved' => 1
                ]);

                $group['total_posts'] = $group_model->count_posts_in_group($group['id'], [
                    'is_active' => 1,
                    'admin_approved' => 1,
                ]);

                // Normalize company logos
                if (!empty($group['items'])) {
                    foreach ($group['items'] as &$item) {
                        if (!empty($item['company_logo'])) {
                            $item['company_logo'] = $this->normalize_company_logo_url($item['company_logo']);
                            continue;
                        }

                        if (!empty($item['wp_post_id'])) {
                            $meta_logo = get_post_meta((int) $item['wp_post_id'], '_company_logo', true);
                            if ($meta_logo) {
                                $item['company_logo'] = $this->normalize_company_logo_url($meta_logo);
                            }
                        }
                    }
                    unset($item);
                }
            }
            unset($group);

            $hr_contacts = [];
            $hr_contacts_total = 0;
            $hr_contacts_per_page = 6;
            if (class_exists('SFFC_CRM_HR_Outreach')) {
                $hr_model = new SFFC_CRM_HR_Outreach();
                $hr_contacts_total = $hr_model->count_all();
                $hr_contacts = $hr_model->get_all([
                    'limit' => $hr_contacts_per_page,
                    'offset' => 0,
                ]);
                if (!empty($hr_contacts) && count($hr_contacts) > 1) {
                    $curated_contacts = array_values(array_filter($hr_contacts, static function ($contact) {
                        return ($contact['source_context'] ?? '') !== 'active_recruiter';
                    }));
                    $active_recruiter_contacts = array_values(array_filter($hr_contacts, static function ($contact) {
                        return ($contact['source_context'] ?? '') === 'active_recruiter';
                    }));
                    shuffle($curated_contacts);
                    shuffle($active_recruiter_contacts);
                    $hr_contacts = array_merge($curated_contacts, $active_recruiter_contacts);
                }
            }

            $console_lists = [];
            $console_list_items = [];
            $application_pack_items = [];
            if ($is_logged_in) {
                $console_lists_table = $wpdb->prefix . 'sffc_crm_console_lists';
                $console_items_table = $wpdb->prefix . 'sffc_crm_console_list_items';
                $console_lists_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($console_lists_table))) === $console_lists_table;
                $console_items_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($console_items_table))) === $console_items_table;

                if ($console_lists_exists && $console_items_exists) {
                    $console_lists = $wpdb->get_results($wpdb->prepare(
                        "SELECT id, list_name, description, item_count, updated_at
                         FROM {$console_lists_table}
                         WHERE user_id = %d
                         ORDER BY updated_at DESC, id DESC",
                        $user_id
                    ), ARRAY_A);

                    $console_list_items = $wpdb->get_results($wpdb->prepare(
                        "SELECT i.*, l.list_name
                         FROM {$console_items_table} i
                         INNER JOIN {$console_lists_table} l ON l.id = i.list_id
                         WHERE i.user_id = %d
                         ORDER BY i.created_at DESC, i.id DESC
                         LIMIT 100",
                        $user_id
                    ), ARRAY_A);
                }

                $application_packs_table = $wpdb->prefix . 'sffc_crm_application_packs';
                $application_packs_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($application_packs_table))) === $application_packs_table;
                if ($application_packs_exists) {
                    $application_pack_items = $wpdb->get_results($wpdb->prepare(
                        "SELECT *
                         FROM {$application_packs_table}
                         WHERE user_id = %d
                         ORDER BY created_at DESC, id DESC
                         LIMIT 100",
                        $user_id
                    ), ARRAY_A);
                }
            }

            $resource_library_items = [];
            $resource_featured_items = [];
            if (class_exists('SFFC_CRM_Resource_Library')) {
                $resource_table = $wpdb->prefix . 'sffc_crm_resource_library';
                $resource_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $resource_table)) === $resource_table;
                if ($resource_table_exists) {
                    $resource_model = new SFFC_CRM_Resource_Library();
                    $resource_library_items = $resource_model->get_all([
                        'is_active' => 1,
                        'limit' => 120,
                    ]);
                    foreach ($resource_library_items as $resource_item) {
                        if (!empty($resource_item['is_featured'])) {
                            $resource_featured_items[] = $resource_item;
                        }
                    }
                    $resource_featured_items = array_slice($resource_featured_items, 0, 3);
                }
            }

            // Fetch market articles for the Markets tab
            $market_feed = $this->get_market_articles_feed('all', 1, 12);
            $market_articles = $market_feed['articles'];
            $market_has_more = !empty($market_feed['has_more']);

