                                    <input type="text" data-email-modal-subject placeholder="<?php esc_attr_e('Subject line for your outreach', 'senna-finance'); ?>" />
                                </label>
                                <label class="sffc-crm-email-field">
                                    <span><?php esc_html_e('Email draft', 'senna-finance'); ?></span>
                                    <textarea rows="10" data-email-modal-body placeholder="<?php esc_attr_e('Introduce yourself, reference the role, and highlight the skills that match.', 'senna-finance'); ?>"></textarea>
                                </label>
                                <div class="sffc-crm-email-modal__actions">
                                    <button type="button" class="sffc-crm-btn sffc-crm-btn-secondary" data-email-modal-review>
                                        <?php esc_html_e('Review my Email', 'senna-finance'); ?>
                                    </button>
                                    <button type="button" class="sffc-crm-btn sffc-crm-btn-primary" data-email-modal-send>
                                        <?php esc_html_e('Send Email', 'senna-finance'); ?>
                                    </button>
                                </div>
                                <p class="sffc-crm-email-feedback" data-email-modal-feedback hidden></p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <?php
            // Render dashboard modal (includes email modal + prep materials modal)
            $this->render_dashboard_modal();
            ?>

            <?php if (!$is_logged_in): ?>
            <?php endif; ?>
            <?php
            return ob_get_clean();
        }

        /**
         * Render feed cards HTML (helper for AJAX loading)
         *
         * @param array $posts Array of post data
         * @param int $user_id User ID for pipeline lookups
         * @return void Outputs HTML directly
         */
        public function render_feed_cards_html($posts, $user_id = 0)
        {
            global $wpdb;

            if (empty($posts)) {
                return;
            }

            // Get pipeline lookup for logged-in users
            $pipeline_lookup_by_post = [];
            if ($user_id) {
                $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
                $pipeline_items = $wpdb->get_results($wpdb->prepare(
                    "SELECT id, post_id, stage FROM {$pipeline_table} WHERE user_id = %d",
                    $user_id
                ), ARRAY_A);

                foreach ($pipeline_items as $item) {
                    if (!empty($item['post_id'])) {
                        $pipeline_lookup_by_post[(int) $item['post_id']] = $item;
                    }
                }
            }

            // Get stage metadata
            $stage_meta = [
                'not_applied' => ['label' => __('Not Applied', 'senna-finance'), 'color' => '#c1c7cd'],
                'applied' => ['label' => __('Applied', 'senna-finance'), 'color' => '#5e6469'],
                'interviewing' => ['label' => __('Interviewing', 'senna-finance'), 'color' => '#1a73e8'],
                'offer' => ['label' => __('Offer', 'senna-finance'), 'color' => '#057642'],
                'rejected' => ['label' => __('Declined', 'senna-finance'), 'color' => '#dc2626'],
            ];

            $is_logged_in = is_user_logged_in();

            foreach ($posts as $post) {
                $company_slug = !empty($post['company']) ? sanitize_title($post['company']) : '';
                $company_logo = !empty($post['company_logo']) ? esc_url($post['company_logo']) : '';
                $company_initial = 'S';
                if (!$company_logo) {
                    $source = $post['company'] ?: $post['role_title'];
                    if ($source) {
                        $company_initial = strtoupper(function_exists('mb_substr') ? mb_substr($source, 0, 1) : substr($source, 0, 1));
                    }
                }
                $pipeline_item = isset($pipeline_lookup_by_post[(int) ($post['id'] ?? 0)]) ? $pipeline_lookup_by_post[(int) $post['id']] : null;
                $current_stage = $pipeline_item['stage'] ?? 'not_applied';
                if (!isset($stage_meta[$current_stage])) {
                    $current_stage = 'not_applied';
                }
                $pipeline_id = !empty($pipeline_item['id']) ? (int) $pipeline_item['id'] : 0;
                $location_label = $post['location'] ?: $post['location_country'];
                $posted_label = '';
                if (!empty($post['posted_at'])) {
                    $posted_label = sprintf(
                        esc_html__('Posted %s ago', 'senna-finance'),
                        human_time_diff(strtotime($post['posted_at']), current_time('timestamp'))
                    );
                }
                $recruiter_initial = $post['recruiter_name'] ? strtoupper(function_exists('mb_substr') ? mb_substr($post['recruiter_name'], 0, 1) : substr($post['recruiter_name'], 0, 1)) : 'R';

                // Get groups for this post
                $post_group_slugs = $wpdb->get_col($wpdb->prepare(
                    "SELECT g.slug
                 FROM {$wpdb->prefix}sffc_crm_post_groups g
                 INNER JOIN {$wpdb->prefix}sffc_crm_post_group_relationships pgr ON g.id = pgr.group_id
                 WHERE pgr.post_id = %d",
                    $post['id']
                ));
                $groups_attr = !empty($post_group_slugs) ? implode(',', $post_group_slugs) : '';
                // Prepare display variables
                $role_title = $post['role_title'];
                $company_name = $post['company'];
                $role_display = $company_name ? $role_title . ' @ ' . $company_name : $role_title;
                $recruiter_display = $post['recruiter_name'] ?: __('Recruiter contact', 'senna-finance');
                $contact_avatar = !empty($post['recruiter_photo']) ? esc_url($post['recruiter_photo']) : '';
                $contact_title = $post['recruiter_firm'] ?: '';
                $posted_diff = !empty($post['posted_at']) ? human_time_diff(strtotime($post['posted_at']), current_time('timestamp')) : '';
                $recruiter_first_name = trim($recruiter_display);
                if (strpos($recruiter_first_name, ' ') !== false) {
                    $recruiter_first_name = substr($recruiter_first_name, 0, strpos($recruiter_first_name, ' '));
                }
                $recruiter_email = $post['recruiter_email'] ?? '';
                $recruiter_linkedin = $post['recruiter_linkedin'] ?? '';
                $view_url = !empty($post['application_url']) ? $post['application_url'] : '';
                $is_internal_view = $view_url && strpos($view_url, home_url()) === 0;
                $detail_uid = !empty($post['id']) ? (int) $post['id'] : uniqid('post_');
                $detail_id = 'sffc-dashboard-detail-' . $detail_uid;
                $content_markup = '';
                if (!empty($post['content'])) {
                    $content_markup = wpautop(wp_kses_post($post['content']));
                }
                $is_logged_in = is_user_logged_in();
                $has_membership_access = false;
                if ($user_id) {
                    if (class_exists('SFFC_CRM_MemberPress_Integration')) {
                        $crm_memberpress = SFFC_CRM_MemberPress_Integration::get_instance();
                        $member_tier = $crm_memberpress->get_crm_tier($user_id);
                        $has_membership_access = in_array($member_tier, ['insider', 'pro'], true);
                    } elseif (class_exists('SFFC_MemberPress_Integration')) {
                        $mepr = SFFC_MemberPress_Integration::get_instance();
                        $has_membership_access = $mepr->has_premium_access($user_id);
                    } elseif (user_can($user_id, 'manage_options')) {
                        $has_membership_access = true;
                    }
                }
                $message_locked = !$is_logged_in || !$has_membership_access;
                $locked_action = !$is_logged_in ? 'login' : 'membership';
                $public_recruiter_display = $message_locked ? $this->mask_dashboard_contact_name($recruiter_display) : $recruiter_display;
            ?>
                <li class="sffc-crm-dashboard-list-item sffc-crm-linkedin-feed-card" <?php echo $company_slug ? ' data-company="' . esc_attr($company_slug) . '"' : ''; ?><?php echo $groups_attr ? ' data-groups="' . esc_attr($groups_attr) . '"' : ''; ?>>
                    <div class="sffc-crm-dashboard-identity">
                        <div class="sffc-crm-hr-avatar-wrapper sffc-crm-dashboard-avatar-wrapper">
                            <div class="sffc-crm-hr-avatar sffc-crm-dashboard-avatar">
                                <?php if ($contact_avatar): ?>
                                    <img src="<?php echo $contact_avatar; ?>" alt="<?php echo esc_attr($recruiter_display); ?>">
                                <?php else: ?>
                                    <span><?php echo esc_html($recruiter_initial); ?></span>
                                <?php endif; ?>
                            </div>
                            <div class="sffc-crm-hr-logo sffc-crm-dashboard-logo-badge">
                                <?php if ($company_logo): ?>
                                    <img src="<?php echo $company_logo; ?>" alt="<?php echo esc_attr($company_name ?: __('Company logo', 'senna-finance')); ?>">
                                <?php else: ?>
                                    <span><?php echo esc_html($company_initial); ?></span>
                                <?php endif; ?>
                            </div>
                        </div>
                        <div class="sffc-crm-dashboard-title">
                            <strong>
                                <?php echo esc_html($role_title); ?>
                                <?php if ($company_name): ?>
                                    <span> @ </span>
                                    <span class="sffc-crm-dashboard-company"><?php echo esc_html($company_name); ?></span>
                                <?php endif; ?>
                            </strong>
                            <span class="sffc-crm-dashboard-recruiter">
                                <?php if ($recruiter_display): ?>
                                    <span class="sffc-crm-dashboard-recruiter-name<?php echo $message_locked ? ' sffc-crm-dashboard-recruiter-name--masked' : ''; ?>"><?php echo esc_html($public_recruiter_display); ?></span>
                                <?php endif; ?>
                                <?php if ($contact_title): ?>
                                    <span class="sffc-crm-dashboard-recruiter-role"><?php echo esc_html($contact_title); ?></span>
                                <?php endif; ?>
                            </span>
                            <p class="sffc-crm-dashboard-meta">
                                <?php if ($location_label): ?>
                                    <span>
                                        <svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true">
                                            <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" fill="none" stroke="currentColor" stroke-width="2"></path>
                                            <circle cx="12" cy="10" r="3" fill="none" stroke="currentColor" stroke-width="2"></circle>
                                        </svg>
                                        <?php echo esc_html($location_label); ?>
                                    </span>
                                <?php endif; ?>
                                <?php if ($posted_diff && $is_logged_in): ?>
                                    <span>
                                        <svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true">
                                            <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2"></circle>
                                            <path d="M12 6v6l3 3" fill="none" stroke="currentColor" stroke-width="2"></path>
                                        </svg>
                                        <?php echo esc_html($posted_diff); ?>
                                    </span>
                                <?php endif; ?>
                                <?php echo $this->render_dashboard_fit_signal_badges($post); ?>
                            </p>
                        </div>
                    </div>
                    <div class="sffc-crm-dashboard-actions">
                        <?php echo $this->render_intro_request_button([
                            'post_id' => (int) $post['id'],
                            'recruiter_id' => (int) ($post['recruiter_id'] ?? 0),
                            'role_title' => $role_title,
                            'company_name' => $company_name,
                            'recruiter_name' => $recruiter_display,
                            'recruiter_email' => $recruiter_email,
                            'recruiter_linkedin' => $recruiter_linkedin,
                            'view_url' => $view_url,
                            'existing_request' => $intro_lookup_by_post[(int) $post['id']] ?? null,
                        ]); ?>
                        <?php echo $this->render_express_interest_button([
                            'post_id' => (int) $post['id'],
                            'recruiter_email' => $recruiter_email,
                            'recruiter_name' => $recruiter_display,
                            'role_title' => $role_title,
                            'company_name' => $company_name,
                            'view_url' => $view_url,
                        ]); ?>
                    </div>
                </li>
            <?php
            }
        }

        public function render_latest_posts($atts)
        {
            $atts = shortcode_atts([
                'count' => 3,
                'blur_last' => 0,
            ], $atts);

            $count = absint($atts['count']);
            $blur_last = absint($atts['blur_last']);

            // Enqueue required CSS for dashboard card design
            wp_enqueue_style(
                'sffc-crm-linkedin',
                SFFC_PLUGIN_URL . 'assets/css/crm/crm-linkedin.css',
                [],
                SFFC_VERSION
            );

            global $wpdb;

            // Use the same model that other parts use
            $post_model = new SFFC_CRM_Post();
            $posts = $post_model->get_feed([
                'per_page' => $count,
                'user_id' => 0, // Public view, no user filtering
            ]);

            if (empty($posts)) {
                // Debug: Check if table exists and has any data
                $table_exists = $wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}sffc_crm_posts'");
                $total_count = $table_exists ? $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sffc_crm_posts") : 0;

                if (WP_DEBUG) {
                    return '<p>' . sprintf(
                        esc_html__('No posts available yet. (Table exists: %s, Total posts in DB: %d)', 'senna-finance'),
                        $table_exists ? 'Yes' : 'No',
                        $total_count
                    ) . '</p>';
                }

                return '<p>' . esc_html__('No posts available yet.', 'senna-finance') . '</p>';
            }

            // Normalize company logos
            if (!empty($posts)) {
                foreach ($posts as &$post) {
                    if (!empty($post['company_logo'])) {
                        $post['company_logo'] = $this->normalize_company_logo_url($post['company_logo']);
                    }
                }
                unset($post);
            }

            ob_start();
            ?>
            <div class="sffc-crm-dashboard-grid">
                <article class="sffc-crm-dashboard-card">
                    <header class="sffc-crm-dashboard-card-header">
                        <div>
                            <p class="sffc-crm-dashboard-eyebrow"><?php echo count($posts); ?> <?php esc_html_e('Latest Opportunities', 'senna-finance'); ?></p>
                            <h3><?php esc_html_e('Recent Posts', 'senna-finance'); ?></h3>
                        </div>
                    </header>

                    <ul class="sffc-crm-dashboard-list sffc-crm-dashboard-list--teaser">
                        <?php
                        $total = count($posts);
                        $visible_posts = $blur_last > 0 ? array_slice($posts, 0, max(1, $total - $blur_last)) : array_slice($posts, 0, min(2, $total));
                        $locked_post_count = max(0, $total - count($visible_posts));
                        $crm_membership_url = $this->get_canonical_membership_url();

                        foreach ($visible_posts as $index => $post):
                            $role_title = $post['role_title'] ?: __('Opportunity', 'senna-finance');
                            $company_name = $post['company'] ?: '';
                            $recruiter_name = $post['recruiter_name'] ?: __('Hiring Team', 'senna-finance');
                            $public_recruiter_name = $this->mask_dashboard_contact_name($recruiter_name);
                            $recruiter_title = $post['recruiter_title'] ?: __('Talent Acquisition', 'senna-finance');
                            $company_logo = !empty($post['company_logo']) ? esc_url($post['company_logo']) : '';
                            $recruiter_avatar = !empty($post['recruiter_photo']) ? esc_url($post['recruiter_photo']) : '';

                            $contact_initial_source = $recruiter_name ?: $company_name ?: 'S';
                            $contact_initial = strtoupper(function_exists('mb_substr') ? mb_substr($contact_initial_source, 0, 1) : substr($contact_initial_source, 0, 1));

                            $company_initial = '';
                            if (empty($company_logo)) {
                                $source = $company_name ?: 'S';
                                $company_initial = strtoupper(function_exists('mb_substr') ? mb_substr($source, 0, 1) : substr($source, 0, 1));
                            }

                            $location_label = '';
                            if (!empty($post['location'])) {
                                $location_label = $post['location'];
                            } elseif (!empty($post['location_city']) || !empty($post['location_country'])) {
                                $location_parts = array_filter([$post['location_city'] ?? '', $post['location_country'] ?? '']);
                                $location_label = implode(', ', $location_parts);
                            }

                            $posted_diff = '';
                            if (!empty($post['posted_at'])) {
                                $posted_ts = strtotime($post['posted_at']);
                                if ($posted_ts) {
                                    $posted_diff = sprintf(__('Posted %s ago', 'senna-finance'), human_time_diff($posted_ts, current_time('timestamp')));
                                }
                            }

                            // Generate random match score and label
                            $match_score = rand(85, 98);
                            $match_labels = ['High Match', 'Skills Match', 'Salary Match'];
                            $match_label = $match_labels[$index % 3];
                        ?>
                            <li class="sffc-crm-dashboard-list-item">
                                <div class="sffc-crm-dashboard-identity">
                                    <div class="sffc-crm-hr-avatar-wrapper sffc-crm-dashboard-avatar-wrapper sffc-crm-match-avatar">
                                        <div class="sffc-crm-hr-avatar sffc-crm-dashboard-avatar">
                                            <?php if ($recruiter_avatar): ?>
                                                <img src="<?php echo $recruiter_avatar; ?>" alt="<?php echo esc_attr($recruiter_name); ?>">
                                            <?php else: ?>
                                                <span><?php echo esc_html($contact_initial); ?></span>
                                            <?php endif; ?>
                                        </div>
                                        <div class="sffc-crm-hr-logo sffc-crm-dashboard-logo-badge">
                                            <?php if ($company_logo): ?>
                                                <img src="<?php echo $company_logo; ?>" alt="<?php echo esc_attr($company_name); ?>">
                                            <?php else: ?>
                                                <span><?php echo esc_html($company_initial); ?></span>
                                            <?php endif; ?>
                                        </div>
                                        <div class="sffc-crm-match-score">
                                            <?php echo $match_score; ?>%
                                        </div>
                                    </div>
                                    <div class="sffc-crm-dashboard-title">
                                        <strong>
                                            <?php echo esc_html($role_title); ?>
                                            <?php if ($company_name): ?>
                                                <span> @ </span>
                                                <span class="sffc-crm-dashboard-company"><?php echo esc_html($company_name); ?></span>
                                            <?php endif; ?>
                                        </strong>
                                        <span class="sffc-crm-dashboard-recruiter">
                                            <?php if ($recruiter_name): ?>
                                                <span class="sffc-crm-dashboard-recruiter-name sffc-crm-dashboard-recruiter-name--masked"><?php echo esc_html($public_recruiter_name); ?></span>
                                            <?php endif; ?>
                                            <?php if ($recruiter_title): ?>
                                                <span class="sffc-crm-dashboard-recruiter-role"><?php echo esc_html($recruiter_title); ?></span>
                                            <?php endif; ?>
                                        </span>
                                        <p class="sffc-crm-dashboard-meta">
                                            <?php if ($location_label): ?>
                                                <span>
                                                    <svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true">
                                                        <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" fill="none" stroke="currentColor" stroke-width="2"></path>
                                                        <circle cx="12" cy="10" r="3" fill="none" stroke="currentColor" stroke-width="2"></circle>
                                                    </svg>
                                                    <?php echo esc_html($location_label); ?>
                                                </span>
                                            <?php endif; ?>
                                            <?php if ($posted_diff): ?>
                                                <span>
                                                    <svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true">
                                                        <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2"></circle>
                                                        <path d="M12 6v6l3 3" fill="none" stroke="currentColor" stroke-width="2"></path>
                                                    </svg>
                                                    <?php echo esc_html($posted_diff); ?>
                                                </span>
                                            <?php endif; ?>
                                            <span class="sffc-crm-match-label">
                                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
                                                    <polyline points="20 6 9 17 4 12"></polyline>
                                                </svg>
                                                <?php echo esc_html($match_label); ?>
                                            </span>
                                        </p>
                                    </div>
                                </div>
                                <div class="sffc-crm-dashboard-actions">
                                    <button type="button" class="sffc-crm-btn sffc-crm-btn-ghost sffc-crm-signup-prompt" data-action="add-to-queue">
                                        <?php esc_html_e('Add to Queue', 'senna-finance'); ?>
                                    </button>
                                    <button type="button" class="sffc-crm-btn sffc-crm-btn-ghost sffc-crm-signup-prompt" data-action="view-role">
                                        <?php esc_html_e('View Role', 'senna-finance'); ?>
                                    </button>
                                </div>
                            </li>
                        <?php endforeach; ?>
                        <?php if ($locked_post_count > 0): ?>
                            <li class="sffc-crm-dashboard-list-lock">
                                <div>
                                    <strong><?php echo esc_html(sprintf(_n('+%d more opportunity', '+%d more opportunities', $locked_post_count, 'senna-finance'), $locked_post_count)); ?></strong>
                                    <span><?php esc_html_e('Upgrade to unlock the full list and contact details.', 'senna-finance'); ?></span>
                                </div>
                                <a class="sffc-crm-btn sffc-crm-btn-primary" href="<?php echo esc_url(is_user_logged_in() ? $crm_membership_url : home_url('/join/')); ?>">
