                            <line x1="18" y1="6" x2="6" y2="18"></line>
                            <line x1="6" y1="6" x2="18" y2="18"></line>
                        </svg>
                    </button>
                    <div class="sffc-signup-content">
                        <div class="sffc-signup-icon">
                            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                                <circle cx="12" cy="7" r="4"></circle>
                            </svg>
                        </div>
                        <h3 class="sffc-signup-title" id="sffcSignupTitle">Join the Network</h3>
                        <p class="sffc-signup-subtitle" id="sffcSignupSubtitle">Unlock exclusive opportunities and career support</p>
                        <ul class="sffc-signup-benefits" id="sffcSignupBenefits">
                            <!-- Benefits will be inserted here -->
                        </ul>
                        <div class="sffc-signup-actions">
                            <button type="button" class="sffc-signup-btn sffc-signup-btn-secondary sffc-signup-cancel">Maybe Later</button>
                            <button type="button" class="sffc-signup-btn sffc-signup-btn-primary sffc-signup-confirm">Join Now</button>
                        </div>
                    </div>
                </div>
            </div>

            <script>
                (function() {
                    var modal = document.getElementById('sffcSignupModal');
                    var benefitsList = document.getElementById('sffcSignupBenefits');
                    var confirmBtn = modal.querySelector('.sffc-signup-confirm');
                    var cancelBtn = modal.querySelector('.sffc-signup-cancel');
                    var closeBtn = modal.querySelector('.sffc-signup-close');
                    var overlay = modal.querySelector('.sffc-signup-overlay');
                    var currentAction = null;

                    var benefits = {
                        'express-interest': [
                            'Express interest in this role',
                            'Get a tailored resume and cover letter',
                            'Track your applications',
                            'Access 100+ exclusive opportunities'
                        ],
                        'request-intro': [
                            'Get introduced directly to recruiters',
                            'Tailored CV for each role',
                            'Bypass the application black hole',
                            'Access our finance recruiter network'
                        ],
                        'add-to-queue': [
                            'Add this role to your application queue',
                            'Track applications in one place',
                            'Unlock tailored materials and updates',
                            'Access 100+ exclusive opportunities'
                        ],
                        'view-role': [
                            'View full role details',
                            'Review the company and requirements',
                            'See how the role fits your goals',
                            'Unlock your dashboard to track applications'
                        ]
                    };

                    function showModal(action) {
                        currentAction = action;
                        var actionBenefits = benefits[action] || [];

                        // Clear and populate benefits
                        benefitsList.innerHTML = '';
                        actionBenefits.forEach(function(benefit) {
                            var li = document.createElement('li');
                            li.className = 'sffc-signup-benefit';
                            li.innerHTML = '<div class="sffc-signup-benefit-icon">' +
                                '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3">' +
                                '<polyline points="20 6 9 17 4 12"></polyline>' +
                                '</svg>' +
                                '</div>' +
                                '<span class="sffc-signup-benefit-text">' + benefit + '</span>';
                            benefitsList.appendChild(li);
                        });

                        modal.classList.add('is-active');
                        document.body.classList.add('sffc-signup-modal-open');
                    }

                    function hideModal() {
                        modal.classList.remove('is-active');
                        document.body.classList.remove('sffc-signup-modal-open');
                        currentAction = null;
                    }

                    document.addEventListener('DOMContentLoaded', function() {
                        var signupButtons = document.querySelectorAll('.sffc-crm-signup-prompt');
                        signupButtons.forEach(function(button) {
                            button.addEventListener('click', function(e) {
                                e.preventDefault();
                                var action = this.getAttribute('data-action');
                                if (action) {
                                    showModal(action);
                                }
                            });
                        });
                    });

                    confirmBtn.addEventListener('click', function() {
                        var signupUrl = '<?php echo esc_url(home_url('/join/')); ?>';
                        window.location.href = signupUrl;
                    });

                    cancelBtn.addEventListener('click', hideModal);
                    closeBtn.addEventListener('click', hideModal);
                    overlay.addEventListener('click', hideModal);

                    document.addEventListener('keydown', function(e) {
                        if (e.key === 'Escape' && modal.classList.contains('is-active')) {
                            hideModal();
                        }
                    });
                })();
            </script>
        <?php
            return ob_get_clean();
        }

        /**
         * Render contact capture form shortcode
         */
        public function render_contact_capture($atts)
        {
            // Get admin settings
            $button_text = get_option('sffc_contact_capture_button_text', 'Get Started');
            $button_color = get_option('sffc_contact_capture_button_color', '#0d353e');
            $field_border_color = get_option('sffc_contact_capture_field_border_color', '#E5E7EB');
            $redirect_url = get_option('sffc_contact_capture_redirect_url', '/memberships/');

            $atts = shortcode_atts([
                'button_text' => $button_text,
                'placeholder_name' => 'Full Name',
                'placeholder_email' => 'Email Address',
            ], $atts);

            ob_start();
        ?>
            <div class="sffc-contact-capture">
                <form class="sffc-contact-capture-form" id="sffcContactCaptureForm">
                    <div class="sffc-contact-capture-fields">
                        <input
                            type="text"
                            name="full_name"
                            class="sffc-contact-capture-input"
                            placeholder="<?php echo esc_attr($atts['placeholder_name']); ?>"
                            required>
                        <input
                            type="email"
                            name="email"
                            class="sffc-contact-capture-input"
                            placeholder="<?php echo esc_attr($atts['placeholder_email']); ?>"
                            required>
                    </div>
                    <button type="submit" class="sffc-contact-capture-btn">
                        <?php echo esc_html($atts['button_text']); ?>
                    </button>
                    <div class="sffc-contact-capture-message"></div>
                </form>
            </div>

            <style>
                .sffc-contact-capture {
                    max-width: 500px;
                    margin: 0 auto;
                }

                .sffc-contact-capture-form {
                    display: flex;
                    flex-direction: column;
                    gap: 1rem;
                }

                .sffc-contact-capture-fields {
                    display: flex;
                    flex-direction: column;
                    gap: 0.75rem;
                }

                .sffc-contact-capture-input {
                    padding: 12px 16px;
                    border: 1px solid <?php echo esc_attr($field_border_color); ?>;
                    border-radius: 8px;
                    font-size: 1rem;
                    font-family: inherit;
                    transition: border-color 0.2s ease;
                }

                .sffc-contact-capture-input:focus {
                    outline: none;
                    border-color: <?php echo esc_attr($button_color); ?>;
                    box-shadow: 0 0 0 3px <?php echo esc_attr($button_color); ?>1a;
                }

                .sffc-contact-capture-btn {
                    padding: 12px 24px;
                    background: <?php echo esc_attr($button_color); ?>;
                    color: #ffffff;
                    border: none;
                    border-radius: 8px;
                    font-size: 1rem;
                    font-weight: 500;
                    cursor: pointer;
                    transition: all 0.2s ease;
                    font-family: inherit;
                }

                .sffc-contact-capture-btn:hover {
                    background: <?php echo esc_attr($button_color); ?>dd;
                    transform: translateY(-1px);
                    box-shadow: 0 4px 12px <?php echo esc_attr($button_color); ?>33;
                }

                .sffc-contact-capture-btn:disabled {
                    opacity: 0.6;
                    cursor: not-allowed;
                }

                .sffc-contact-capture-message {
                    font-size: 0.875rem;
                    text-align: center;
                    padding: 0.5rem;
                    border-radius: 6px;
                    display: none;
                }

                .sffc-contact-capture-message.success {
                    display: block;
                    background: #E8F5E9;
                    color: #2E7D32;
                }

                .sffc-contact-capture-message.error {
                    display: block;
                    background: #FFEBEE;
                    color: #C62828;
                }

                @media (max-width: 640px) {
                    .sffc-contact-capture {
                        max-width: 100%;
                        padding: 0 1rem;
                    }
                }
            </style>

            <script>
                (function() {
                    var form = document.getElementById('sffcContactCaptureForm');
                    if (!form) return;

                    form.addEventListener('submit', function(e) {
                        e.preventDefault();

                        var submitBtn = form.querySelector('.sffc-contact-capture-btn');
                        var messageEl = form.querySelector('.sffc-contact-capture-message');
                        var formData = new FormData(form);

                        submitBtn.disabled = true;
                        submitBtn.textContent = 'Saving...';
                        messageEl.className = 'sffc-contact-capture-message';
                        messageEl.style.display = 'none';

                        fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
                                method: 'POST',
                                body: new URLSearchParams({
                                    action: 'sffc_save_contact_data',
                                    full_name: formData.get('full_name'),
                                    email: formData.get('email'),
                                    nonce: '<?php echo wp_create_nonce('sffc_contact_capture'); ?>'
                                })
                            })
                            .then(function(response) {
                                return response.json();
                            })
                            .then(function(data) {
                                if (data.success) {
                                    messageEl.className = 'sffc-contact-capture-message success';
                                    messageEl.textContent = 'Saved successfully! Redirecting...';
                                    form.reset();
                                    setTimeout(function() {
                                        window.location.href = '<?php echo esc_js(home_url($redirect_url)); ?>';
                                    }, 1000);
                                } else {
                                    throw new Error(data.data || 'Failed to save');
                                }
                            })
                            .catch(function(error) {
                                messageEl.className = 'sffc-contact-capture-message error';
                                messageEl.textContent = error.message || 'Something went wrong';
                            })
                            .finally(function() {
                                submitBtn.disabled = false;
                                submitBtn.textContent = '<?php echo esc_js($atts['button_text']); ?>';
                            });
                    });
                })();
            </script>
        <?php
            return ob_get_clean();
        }

