        /**
         * Render contact flow with conditional questions (new extended version)
         * Supports two flows:
         * - Flow A: From job post (?id=322) - 2 questions only
         * - Flow B: Organic traffic - 4 questions
         */
        public function render_contact_flow($atts)
        {
            $atts = shortcode_atts([
                'redirect_url' => '/memberships/',
            ], $atts);

            // Detect if coming from job post
            $post_id = isset($_GET['id']) ? intval($_GET['id']) : 0;
            $from_job_post = false;
            $post_data = null;

            if ($post_id > 0) {
                global $wpdb;
                $table_name = $wpdb->prefix . 'sffc_crm_posts';
                $post_data = $wpdb->get_row($wpdb->prepare("SELECT * FROM $table_name WHERE id = %d", $post_id), ARRAY_A);

                if ($post_data) {
                    $from_job_post = true;
                }
            }

            // Check if user has already completed Step 1 (from homepage or elsewhere)
            $contact_data = $this->get_valid_signup_json_cookie('sffc_contact_data');
            if (empty($contact_data)) {
                $contact_data = null;
            }
            $skip_step_1 = !empty($contact_data['full_name']) && !empty($contact_data['email']);
            $initial_step = $skip_step_1 ? 2 : 1;

            ob_start();
        ?>
            <div class="sffc-contact-flow" id="sffcContactFlow" data-initial-step="<?php echo $initial_step; ?>" data-skip-step-1="<?php echo $skip_step_1 ? '1' : '0'; ?>">
                <!-- Step 1: Name + Email (Skip if already completed) -->
                <div class="sffc-flow-step <?php echo !$skip_step_1 ? 'sffc-step-active' : ''; ?>" data-step="1">
                    <div class="sffc-flow-progress">
                        <div class="sffc-progress-bar">
                            <div class="sffc-progress-fill" style="width: <?php echo $from_job_post ? '33%' : '25%'; ?>"></div>
                        </div>
                        <div class="sffc-progress-text">Step 1 of <?php echo $from_job_post ? '3' : '4'; ?></div>
                    </div>

                    <div class="sffc-flow-content">
                        <h2 class="sffc-flow-title">Get Started</h2>
                        <p class="sffc-flow-subtitle">Join candidates targeting private equity careers</p>

                        <form class="sffc-flow-form" id="sffcFlowForm1">
                            <input
                                type="text"
                                name="full_name"
                                class="sffc-flow-input"
                                placeholder="Full Name"
                                value="<?php echo $contact_data ? esc_attr($contact_data['full_name'] ?? '') : ''; ?>"
                                required>
                            <input
                                type="email"
                                name="email"
                                class="sffc-flow-input"
                                placeholder="Email Address"
                                value="<?php echo $contact_data ? esc_attr($contact_data['email'] ?? '') : ''; ?>"
                                required>
                            <button type="submit" class="sffc-flow-btn">
                                Continue
                            </button>
                        </form>
                    </div>
                </div>

                <?php if ($from_job_post && $post_data): ?>
                    <!-- Flow A: From Job Post -->

                    <!-- Step 2A: Visa Status / Location -->
                    <div class="sffc-flow-step <?php echo $skip_step_1 ? 'sffc-step-active' : ''; ?>" data-step="2">
                        <div class="sffc-flow-progress">
                            <div class="sffc-progress-bar">
                                <div class="sffc-progress-fill" style="width: <?php echo $skip_step_1 ? '50%' : '66%'; ?>"></div>
                            </div>
                            <div class="sffc-progress-text">Step <?php echo $skip_step_1 ? '1' : '2'; ?> of <?php echo $skip_step_1 ? '2' : '3'; ?></div>
                        </div>

                        <div class="sffc-flow-content">
                            <h2 class="sffc-flow-title">Quick Account Setup</h2>
                            <p class="sffc-flow-subtitle">You're applying for: <strong><?php echo esc_html($post_data['title']); ?></strong></p>

                            <form class="sffc-flow-form" id="sffcFlowForm2A">
                                <label class="sffc-flow-label">Right to work / Visa status?</label>
                                <select name="visa_status" class="sffc-flow-select" required>
                                    <option value="">Select your status</option>
                                    <option value="already_private_equity">Already have right to work in my target market</option>
                                    <option value="relocating_for_pe">Relocating for a finance role</option>
                                    <option value="relocating_us">Relocating internationally (need visa)</option>
                                    <option value="relocating_asia">Relocating from another market (need visa)</option>
                                    <option value="relocating_other">Relocating from elsewhere (need visa)</option>
                                </select>
                                <button type="submit" class="sffc-flow-btn">
                                    Continue
                                </button>
                                <button type="button" class="sffc-flow-btn-back">
                                    Back
                                </button>
                            </form>
                        </div>
                    </div>

                    <!-- Step 3A: Current Employer -->
                    <div class="sffc-flow-step" data-step="3">
                        <div class="sffc-flow-progress">
                            <div class="sffc-progress-bar">
                                <div class="sffc-progress-fill" style="width: 100%"></div>
                            </div>
                            <div class="sffc-progress-text">Step <?php echo $skip_step_1 ? '2' : '3'; ?> of <?php echo $skip_step_1 ? '2' : '3'; ?></div>
                        </div>

                        <div class="sffc-flow-content">
                            <h2 class="sffc-flow-title">Almost There</h2>
                            <p class="sffc-flow-subtitle">One last question to personalize your applications</p>

                            <form class="sffc-flow-form" id="sffcFlowForm3A">
                                <label class="sffc-flow-label">Where do you currently work (or most recently)?</label>
                                <select name="current_employer" class="sffc-flow-select" required>
                                    <option value="">Select employer type</option>
                                    <option value="big4">Big 4 Accounting (EY, PwC, Deloitte, KPMG)</option>
                                    <option value="tier2_accounting">Tier 2 Accounting (Grant Thornton, BDO, etc.)</option>
