        private function render_dubai_career_flow_scripts($skip_step_1, array $flow_data, $redirect_url)
        {
            $serialized_flow = wp_json_encode($flow_data);
        ?>
            <script>
                (function() {
                    var flowContainer = document.getElementById('sffcDubaiCareerFlow');
                    if (!flowContainer) {
                        return;
                    }

                    var initialStep = parseInt(flowContainer.getAttribute('data-initial-step'), 10) || 1;
                    var currentStep = initialStep;
                    var flowData = <?php echo $serialized_flow ?: '{}'; ?> || {};

                    if (!flowData.help_needs) {
                        flowData.help_needs = [];
                    }
                    if (!flowData.open_to_types) {
                        flowData.open_to_types = [];
                    }

                    if (<?php echo $skip_step_1 ? 'true' : 'false'; ?> && initialStep === 2) {
                        goToStep(2);
                    }

                    document.querySelectorAll('#sffcDubaiCareerFlow .sffc-flow-option-btn').forEach(function(btn) {
                        btn.addEventListener('click', function() {
                            var form = this.closest('form');
                            var hiddenInput = form.querySelector('input[type="hidden"]');

                            form.querySelectorAll('.sffc-flow-option-btn').forEach(function(button) {
                                button.classList.remove('selected');
                            });

                            this.classList.add('selected');
                            if (hiddenInput) {
                                hiddenInput.value = this.getAttribute('data-value');
                            }
                        });
                    });

                    var form1 = document.getElementById('sffcDubaiCareerForm1');
                    if (form1) {
                        form1.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form1);
                            flowData.full_name = formData.get('full_name') || '';
                            flowData.email = formData.get('email') || '';
                            goToStep(2);
                        });
                    }

                    var form2 = document.getElementById('sffcDubaiCareerForm2');
                    if (form2) {
                        form2.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form2);
                            var seniority = formData.get('target_seniority') || '';
                            if (!seniority) {
                                showMessage('error', 'Please select the level you are targeting.');
                                return;
                            }
                            flowData.target_seniority = seniority;
                            goToStep(3);
                        });
                    }

                    var form3 = document.getElementById('sffcDubaiCareerForm3');
                    if (form3) {
                        form3.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form3);
                            var openToTypes = formData.getAll('open_to_types[]');
                            if (!openToTypes.length) {
                                showMessage('error', 'Please choose at least one opportunity type.');
                                return;
                            }
                            flowData.open_to_types = openToTypes;
                            goToStep(4);
                        });
                    }

                    var form4 = document.getElementById('sffcDubaiCareerForm4');
                    if (form4) {
                        form4.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form4);
                            var targetSector = formData.get('target_sector') || '';
                            if (!targetSector) {
                                showMessage('error', 'Please choose your finance focus.');
                                return;
                            }
                            flowData.target_sectors = [targetSector];
                            goToStep(5);
                        });
                    }

                    var form5 = document.getElementById('sffcDubaiCareerForm5');
                    if (form5) {
                        form5.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form5);
                            var helpNeeds = formData.getAll('help_needs[]');
                            if (!helpNeeds.length) {
                                showMessage('error', 'Please choose at least one area where you want help.');
                                return;
                            }
                            flowData.help_needs = helpNeeds;
                            goToStep(6);
                        });
                    }

                    var form6 = document.getElementById('sffcDubaiCareerForm6');
                    if (form6) {
                        form6.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form6);

                            flowData.dubai_status = formData.get('dubai_status') || '';
                            flowData.recruiter_intro_intent = formData.get('recruiter_intro_intent') || '';
                            flowData.timeline = formData.get('timeline') || '';

                            if (!flowData.dubai_status || !flowData.recruiter_intro_intent || !flowData.timeline) {
                                showMessage('error', 'Please complete the final details.');
                                return;
                            }

                            saveDubaiCareerFlow(flowData, function() {
                                window.location.href = '<?php echo esc_js(home_url($redirect_url)); ?>';
                            });
                        });
                    }

                    document.querySelectorAll('#sffcDubaiCareerFlow .sffc-flow-btn-back').forEach(function(btn) {
                        btn.addEventListener('click', function() {
                            goToStep(currentStep - 1);
                        });
                    });

                    function goToStep(step) {
                        document.querySelectorAll('#sffcDubaiCareerFlow .sffc-flow-step').forEach(function(el) {
                            el.classList.remove('sffc-step-active');
                        });

                        var stepEl = document.querySelector('#sffcDubaiCareerFlow .sffc-flow-step[data-step="' + step + '"]');
                        if (stepEl) {
                            stepEl.classList.add('sffc-step-active');
                            currentStep = step;
                            window.scrollTo(0, 0);
                            showMessage('', '');
                        }
                    }

                    function saveDubaiCareerFlow(data, callback) {
                        fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/x-www-form-urlencoded'
                                },
                                body: new URLSearchParams({
                                    action: 'sffc_save_dubai_career_flow',
                                    flow_data: JSON.stringify(data),
                                    nonce: '<?php echo wp_create_nonce('sffc_dubai_career_flow'); ?>'
                                })
                            })
                            .then(function(response) {
                                return response.json();
                            })
                            .then(function(response) {
                                if (response.success) {
                                    if (callback) {
                                        callback();
                                    }
                                    return;
                                }
                                showMessage('error', response.data || 'Unable to save your answers right now.');
                            })
                            .catch(function() {
                                showMessage('error', 'Unable to save your answers right now.');
                            });
                    }

                    function showMessage(type, message) {
                        var messageEl = document.querySelector('#sffcDubaiCareerFlow .sffc-flow-message');
                        if (!messageEl) {
                            return;
                        }

                        if (!type || !message) {
                            messageEl.className = 'sffc-flow-message';
                            messageEl.textContent = '';
                            return;
                        }

                        messageEl.className = 'sffc-flow-message ' + type;
                        messageEl.textContent = message;
                    }
                })();
            </script>
        <?php
        }

        public function ajax_save_dubai_career_flow()
        {
            check_ajax_referer('sffc_dubai_career_flow', 'nonce');

            $flow_data_json = $_POST['flow_data'] ?? '';
            $flow_data = json_decode(stripslashes($flow_data_json), true);

            if (empty($flow_data) || empty($flow_data['full_name']) || empty($flow_data['email'])) {
                wp_send_json_error('Please complete your name and email address.');
                return;
            }

            $full_name = sanitize_text_field($flow_data['full_name']);
            $email = sanitize_email($flow_data['email']);

            if (!is_email($email)) {
                wp_send_json_error('Please provide a valid email address.');
                return;
            }

            $name_parts = $this->parse_full_name($full_name);
            $normalized_data = [
                'full_name' => $full_name,
                'email' => $email,
                'first_name' => $name_parts['first_name'],
                'last_name' => $name_parts['last_name'],
                'target_seniority' => sanitize_text_field($flow_data['target_seniority'] ?? ''),
                'open_to_types' => isset($flow_data['open_to_types']) && is_array($flow_data['open_to_types'])
                    ? array_values(array_filter(array_map('sanitize_text_field', $flow_data['open_to_types'])))
                    : [],
                'target_sectors' => isset($flow_data['target_sectors']) && is_array($flow_data['target_sectors'])
                    ? array_values(array_filter(array_map('sanitize_text_field', $flow_data['target_sectors'])))
                    : [],
                'help_needs' => isset($flow_data['help_needs']) && is_array($flow_data['help_needs'])
                    ? array_values(array_filter(array_map('sanitize_text_field', $flow_data['help_needs'])))
                    : [],
                'dubai_status' => sanitize_text_field($flow_data['dubai_status'] ?? ''),
                'recruiter_intro_intent' => sanitize_text_field($flow_data['recruiter_intro_intent'] ?? ''),
                'timeline' => sanitize_text_field($flow_data['timeline'] ?? ''),
            ];

            $this->persist_dubai_career_flow_cookies($normalized_data);
            $this->capture_dubai_career_lead($normalized_data);

            if (is_user_logged_in()) {
                $this->save_dubai_career_preferences(get_current_user_id(), $normalized_data);
            }

            wp_send_json_success([
                'message' => __('Career flow saved successfully.', 'senna-finance'),
            ]);
        }

        private function get_dubai_career_flow_data()
        {
            $cookie_data = [];
            $cookie_data = $this->get_valid_signup_json_cookie('sffc_dubai_career_flow');

            if (is_user_logged_in()) {
                $user_id = get_current_user_id();
                $name = trim((string) get_user_meta($user_id, 'first_name', true) . ' ' . (string) get_user_meta($user_id, 'last_name', true));
                $email = wp_get_current_user()->user_email;

                return [
                    'full_name' => $cookie_data['full_name'] ?? $name,
                    'email' => $cookie_data['email'] ?? $email,
                    'first_name' => $cookie_data['first_name'] ?? get_user_meta($user_id, 'first_name', true),
                    'last_name' => $cookie_data['last_name'] ?? get_user_meta($user_id, 'last_name', true),
                    'target_seniority' => $cookie_data['target_seniority'] ?? ((sffc_crm_get_job_preferences($user_id)['target_seniority'][0] ?? '')),
                    'open_to_types' => $cookie_data['open_to_types'] ?? (get_user_meta($user_id, 'sffc_crm_open_to_types', true) ?: []),
                    'target_sectors' => $cookie_data['target_sectors'] ?? (sffc_crm_get_job_preferences($user_id)['target_sectors'] ?? []),
                    'help_needs' => $cookie_data['help_needs'] ?? (get_user_meta($user_id, 'sffc_crm_help_needs', true) ?: []),
                    'dubai_status' => $cookie_data['dubai_status'] ?? get_user_meta($user_id, 'sffc_crm_dubai_status', true),
                    'recruiter_intro_intent' => $cookie_data['recruiter_intro_intent'] ?? get_user_meta($user_id, 'sffc_crm_recruiter_intro_intent', true),
                    'timeline' => $cookie_data['timeline'] ?? get_user_meta($user_id, 'sffc_crm_candidate_timeline', true),
                ];
            }

            return $cookie_data;
        }

        private function persist_dubai_career_flow_cookies(array $data)
        {
            $expires = time() + (30 * DAY_IN_SECONDS);

            $this->set_signup_scoped_cookie('sffc_dubai_career_flow', wp_json_encode($data), $expires);
            $this->set_signup_scoped_cookie('sffc_signup_email', $data['email'], $expires);
            $this->set_signup_scoped_cookie('sffc_signup_first_name', $data['first_name'], $expires);
            $this->set_signup_scoped_cookie('sffc_signup_last_name', $data['last_name'], $expires);
            $this->set_signup_scoped_cookie('sffc_contact_data', wp_json_encode($data), $expires);
        }

        private function capture_dubai_career_lead(array $data)
        {
            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) !== $table_name) {
                return;
            }

            $wpdb->insert(
                $table_name,
                [
                    'full_name' => $data['full_name'],
                    'email' => $data['email'],
                    'created_at' => current_time('mysql'),
                ],
                ['%s', '%s', '%s']
            );
        }

        private function maybe_sync_dubai_career_preferences($user_id)
        {
            if (!$user_id) {
                return;
            }

            if (get_user_meta($user_id, 'sffc_crm_dubai_flow_completed', true)) {
                return;
            }

            $flow_data = $this->get_dubai_career_flow_data();
            if (empty($flow_data['email'])) {
                return;
            }

            $this->save_dubai_career_preferences($user_id, $flow_data);
        }

        private function save_dubai_career_preferences($user_id, array $data)
        {
            $job_preferences = [
                'target_locations' => [],
                'target_seniority' => !empty($data['target_seniority']) ? [$data['target_seniority']] : [],
                'target_sectors' => !empty($data['target_sectors']) && is_array($data['target_sectors']) ? $data['target_sectors'] : [],
            ];

            sffc_crm_save_job_preferences($user_id, $job_preferences);

            update_user_meta($user_id, 'sffc_crm_open_to_types', !empty($data['open_to_types']) && is_array($data['open_to_types']) ? $data['open_to_types'] : []);
            update_user_meta($user_id, 'sffc_crm_help_needs', !empty($data['help_needs']) && is_array($data['help_needs']) ? $data['help_needs'] : []);
            update_user_meta($user_id, 'sffc_crm_dubai_status', sanitize_text_field($data['dubai_status'] ?? ''));
            update_user_meta($user_id, 'sffc_crm_recruiter_intro_intent', sanitize_text_field($data['recruiter_intro_intent'] ?? ''));
            update_user_meta($user_id, 'sffc_crm_candidate_timeline', sanitize_text_field($data['timeline'] ?? ''));
            update_user_meta($user_id, 'sffc_crm_dubai_flow_completed', current_time('mysql'));

            if (!empty($data['first_name'])) {
                update_user_meta($user_id, 'first_name', $data['first_name']);
            }
            if (!empty($data['last_name'])) {
                update_user_meta($user_id, 'last_name', $data['last_name']);
            }
        }

        private function parse_full_name($full_name)
        {
            $parts = preg_split('/\s+/', trim((string) $full_name));
            $parts = array_values(array_filter($parts));

            if (empty($parts)) {
                return [
                    'first_name' => '',
                    'last_name' => '',
                ];
            }

            $first_name = (string) ($parts[0] ?? '');
            $last_name = count($parts) > 1 ? (string) ($parts[count($parts) - 1] ?? '') : '';

            return [
                'first_name' => $first_name,
                'last_name' => $last_name,
            ];
        }

        private function get_recruiter_carousel_personalization()
        {
            $flow_data = $this->get_dubai_career_flow_data();
            $first_name = sanitize_text_field($flow_data['first_name'] ?? '');
            $help_needs = !empty($flow_data['help_needs']) && is_array($flow_data['help_needs']) ? $flow_data['help_needs'] : [];

            if (!$first_name && is_user_logged_in()) {
                $first_name = sanitize_text_field(get_user_meta(get_current_user_id(), 'first_name', true));
            }

            return [
                'first_name' => $first_name,
                'help_needs' => $help_needs,
            ];
        }

        private function personalize_recruiter_pricing_plan(array $plan, array $personalization)
        {
            $first_name = trim((string) ($personalization['first_name'] ?? ''));
            $help_needs = !empty($personalization['help_needs']) && is_array($personalization['help_needs']) ? $personalization['help_needs'] : [];

            if ($first_name !== '') {
                $plan['hero_title'] = $first_name . ', ' . $plan['hero_title'];
                $plan['free_title'] = sprintf(__('Free application materials for %s', 'senna-finance'), $first_name);
            }

            $plan['hero_copy_html'] = $this->build_help_needs_checklist_html($help_needs, $plan['hero_copy']);

            return $plan;
        }

        private function build_help_needs_checklist_html(array $help_needs, $fallback_text = '')
        {
            $labels = [
                'recruiter_intros' => __('Direct recruiter introductions', 'senna-finance'),
                'tailored_cv' => __('A tailored CV for private equity roles', 'senna-finance'),
                'cover_letter' => __('Tailored cover letters', 'senna-finance'),
                'interview_prep' => __('Interview prep', 'senna-finance'),
                'hidden_jobs' => __('Hidden finance opportunities', 'senna-finance'),
                'relocation_support' => __('Relocation support', 'senna-finance'),
            ];

            $items = [];
            foreach ($help_needs as $need) {
                if (!empty($labels[$need])) {
                    $items[] = $labels[$need];
                }
            }

            if (empty($items)) {
                return '<p>' . esc_html($fallback_text) . '</p>';
            }

            $html = '<ul class="sffc-carousel-help-checklist">';
            foreach ($items as $item) {
                $html .= '<li>' . esc_html($item) . '</li>';
            }
            $html .= '</ul>';

            return $html;
        }

