        /**
         * Render scripts for contact flow
         */
        private function render_contact_flow_scripts($from_job_post, $post_data, $redirect_url)
        {
        ?>
            <script>
                (function() {
                    var flowContainer = document.getElementById('sffcContactFlow');
                    var initialStep = parseInt(flowContainer.getAttribute('data-initial-step')) || 1;
                    var skipStep1 = flowContainer.getAttribute('data-skip-step-1') === '1';
                    var currentStep = initialStep;

                    var flowData = {
                        post_id: <?php echo $from_job_post ? intval($post_data['id']) : 0; ?>,
                        from_job_post: <?php echo $from_job_post ? 'true' : 'false'; ?>,
                        post_title: <?php echo $from_job_post ? json_encode($post_data['title']) : '""'; ?>
                    };

                    // Pre-populate from cookie if Step 1 was skipped
                    <?php if ($skip_step_1): ?>
                        var cookieData = <?php echo json_encode($contact_data); ?>;
                        if (cookieData) {
                            flowData.full_name = cookieData.full_name || '';
                            flowData.email = cookieData.email || '';
                        }
                    <?php endif; ?>

                    // Start at correct step if Step 1 was skipped
                    if (skipStep1 && initialStep === 2) {
                        goToStep(2);
                    }

                    // Handle option button selection (for years of experience)
                    document.querySelectorAll('.sffc-flow-option-btn').forEach(function(btn) {
                        btn.addEventListener('click', function() {
                            var form = this.closest('form');
                            var hiddenInput = form.querySelector('input[type="hidden"]');

                            // Remove selected class from siblings
                            form.querySelectorAll('.sffc-flow-option-btn').forEach(function(b) {
                                b.classList.remove('selected');
                            });

                            // Add selected class and set value
                            this.classList.add('selected');
                            hiddenInput.value = this.getAttribute('data-value');
                        });
                    });

                    // Handle Step 1 (Name + Email)
                    var form1 = document.getElementById('sffcFlowForm1');
                    if (form1) {
                        form1.addEventListener('submit', function(e) {
                            e.preventDefault();
                            var formData = new FormData(form1);
                            flowData.full_name = formData.get('full_name');
                            flowData.email = formData.get('email');

                            // Save to database via AJAX
                            saveContactData(flowData.full_name, flowData.email, function() {
                                goToStep(2);
                            });
                        });
                    }

                    // Handle subsequent forms
                    <?php if ($from_job_post): ?>
                        // Flow A: Job Post
                        var form2A = document.getElementById('sffcFlowForm2A');
                        if (form2A) {
                            form2A.addEventListener('submit', function(e) {
                                e.preventDefault();
                                var formData = new FormData(form2A);
                                flowData.visa_status = formData.get('visa_status');
                                goToStep(3);
                            });
                        }

                        var form3A = document.getElementById('sffcFlowForm3A');
                        if (form3A) {
                            form3A.addEventListener('submit', function(e) {
                                e.preventDefault();
                                var formData = new FormData(form3A);
                                flowData.current_employer = formData.get('current_employer');

                                // Save all data and redirect
                                saveFlowData(flowData, function() {
                                    window.location.href = '<?php echo esc_js(home_url($redirect_url)); ?>';
                                });
                            });
                        }
                    <?php else: ?>
                        // Flow B: Organic
                        var form2B = document.getElementById('sffcFlowForm2B');
                        if (form2B) {
                            form2B.addEventListener('submit', function(e) {
                                e.preventDefault();
                                var formData = new FormData(form2B);
                                flowData.target_role = formData.get('target_role');
                                goToStep(3);
                            });
                        }

                        var form3B = document.getElementById('sffcFlowForm3B');
                        if (form3B) {
                            form3B.addEventListener('submit', function(e) {
                                e.preventDefault();
                                var formData = new FormData(form3B);
                                flowData.years_experience = formData.get('years_experience');
                                goToStep(4);
                            });
                        }

                        var form4B = document.getElementById('sffcFlowForm4B');
                        if (form4B) {
                            form4B.addEventListener('submit', function(e) {
                                e.preventDefault();
                                var formData = new FormData(form4B);

                                // Get selected locations
                                var locations = [];
                                formData.getAll('target_location[]').forEach(function(loc) {
                                    locations.push(loc);
                                });

                                // Validate at least one location is selected
                                if (locations.length === 0) {
                                    showMessage('error', 'Please select at least one location');
                                    return;
                                }

                                flowData.target_location = locations;
                                flowData.current_employer = formData.get('current_employer');

                                // Save all data and redirect
                                saveFlowData(flowData, function() {
                                    window.location.href = '<?php echo esc_js(home_url($redirect_url)); ?>';
                                });
                            });
                        }
                    <?php endif; ?>

                    // Handle back buttons
                    document.querySelectorAll('.sffc-flow-btn-back').forEach(function(btn) {
                        btn.addEventListener('click', function() {
                            goToStep(currentStep - 1);
                        });
                    });

                    function goToStep(step) {
                        document.querySelectorAll('.sffc-flow-step').forEach(function(el) {
                            el.classList.remove('sffc-step-active');
                        });

                        var stepEl = document.querySelector('.sffc-flow-step[data-step="' + step + '"]');
                        if (stepEl) {
                            stepEl.classList.add('sffc-step-active');
                            currentStep = step;
                            window.scrollTo(0, 0);
                        }
                    }

                    function saveContactData(full_name, email, callback) {
                        fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/x-www-form-urlencoded'
                                },
                                body: new URLSearchParams({
                                    action: 'sffc_save_contact_data',
                                    full_name: full_name,
                                    email: email,
                                    nonce: '<?php echo wp_create_nonce('sffc_contact_capture'); ?>'
                                })
                            })
                            .then(function(response) {
                                return response.json();
                            })
                            .then(function(data) {
                                if (data.success) {
                                    if (callback) callback();
                                } else {
                                    showMessage('error', data.data || 'Failed to save contact data');
                                }
                            })
                            .catch(function(error) {
                                showMessage('error', 'An error occurred');
                            });
                    }

                    function saveFlowData(data, callback) {
                        fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/x-www-form-urlencoded'
                                },
                                body: new URLSearchParams({
                                    action: 'sffc_save_flow_data',
                                    flow_data: JSON.stringify(data),
                                    nonce: '<?php echo wp_create_nonce('sffc_contact_flow'); ?>'
                                })
                            })
                            .then(function(response) {
                                return response.json();
                            })
                            .then(function(data) {
                                if (data.success) {
                                    if (callback) callback();
                                } else {
                                    showMessage('error', data.data || 'Failed to save data');
                                }
                            })
                            .catch(function(error) {
                                showMessage('error', 'An error occurred');
                            });
                    }

                    function showMessage(type, message) {
                        var messageEl = document.querySelector('.sffc-flow-message');
                        if (messageEl) {
                            messageEl.className = 'sffc-flow-message ' + type;
                            messageEl.textContent = message;
                        }
                    }
                })();
            </script>
        <?php
        }

