            for ($i = 0; $i < $num_applications; $i++) {
                $applications[] = [
                    'image' => $recruiter_images[$i],
                    'recruiter' => $recruiter_first_names[$i] . ' ' . $recruiter_last_initials[$i] . '.',
                    'company' => $companies[$i],
                    'role' => $roles[$i],
                    'status' => $app_statuses[$i % count($app_statuses)],
                    'date' => date('M j', strtotime('-' . rand(1, 5) . ' days'))
                ];
            }

            // Generate randomized data for Window 3 (Recruiter Responses - 2-3 cards)
            $num_responses = rand(2, 3);
            $responses = [];

            // Reshuffle for different recruiters (arrays now have different elements at each index)
            shuffle($recruiter_images);
            shuffle($recruiter_first_names);
            shuffle($recruiter_last_initials);
            shuffle($recruiter_titles);
            shuffle($companies);
            shuffle($roles);
            shuffle($recruiter_messages);

            // Build employer-specific message snippets
            $employer_snippet = '';
            if (!empty($contact_data['current_employer'])) {
                $employer_snippets = [
                    'big4' => 'I saw your Big 4 background',
                    'tier2_accounting' => 'Your accounting experience',
                    'global_ib' => 'I noticed your global IB background',
                    'regional_ib' => 'Your regional banking experience',
                    'pe_vc' => 'I saw your PE/VC background',
                    'asset_mgmt' => 'Your asset management experience',
                    'corp_finance' => 'Your corporate finance background',
                    'government' => 'Your government/sovereign fund experience',
                    'between_roles' => '',
                    'other' => ''
                ];
                $employer_snippet = $employer_snippets[$contact_data['current_employer']] ?? '';
            }

            for ($i = 0; $i < $num_responses; $i++) {
                // Replace {first_name} placeholder in message template
                $message_template = $recruiter_messages[$i % count($recruiter_messages)];

                // If first_name is "Your" (fallback), remove the greeting salutation
                if ($first_name === 'Your') {
                    // Remove "Hi {first_name}, " or "Hello {first_name}, " or "{first_name}, "
                    $personalized_message = preg_replace('/^(Hi|Hello)?\s*\{first_name\},?\s*/i', '', $message_template);
                } else {
                    $personalized_message = str_replace('{first_name}', $first_name, $message_template);
                }

                // Inject employer snippet into first response for maximum impact
                if ($i === 0 && !empty($employer_snippet)) {
                    $personalized_message = preg_replace(
                        '/(I reviewed your profile|Your experience|Your profile)/',
                        '$1 - ' . $employer_snippet . ',',
                        $personalized_message,
                        1
                    );
                }

                $responses[] = [
                    'image' => $recruiter_images[$i],
                    'recruiter' => $recruiter_first_names[$i] . ' ' . $recruiter_last_initials[$i] . '.',
                    'recruiter_title' => $recruiter_titles[$i],
                    'company' => $companies[$i],
                    'role' => $roles[$i],
                    'message' => $personalized_message
                ];
            }

            ob_start();
        ?>
