        /**
         * AJAX handler to save contact data
         */
        public function ajax_save_contact_data()
        {
            check_ajax_referer('sffc_contact_capture', 'nonce');

            $full_name = sanitize_text_field($_POST['full_name'] ?? '');
            $email = sanitize_email($_POST['email'] ?? '');

            if (empty($full_name) || empty($email)) {
                wp_send_json_error('Please provide both name and email');
                return;
            }

            if (!is_email($email)) {
                wp_send_json_error('Please provide a valid email address');
                return;
            }

            // Save to database
            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';

            $inserted = $wpdb->insert(
                $table_name,
                [
                    'full_name' => $full_name,
                    'email' => $email,
                    'created_at' => current_time('mysql')
                ],
                ['%s', '%s', '%s']
            );

            if ($inserted === false) {
                wp_send_json_error('Failed to save contact data to database');
                return;
            }

            // Save to cookie (expires in 30 days) for app pack preview
            $data = json_encode([
                'full_name' => $full_name,
                'email' => $email,
            ]);

            $this->set_signup_scoped_cookie('sffc_contact_data', $data, time() + (30 * 24 * 60 * 60));

            wp_send_json_success('Contact data saved successfully');
        }

        public function ajax_crm_editorial_tracker_alert_subscribe()
        {
            check_ajax_referer('sffc_crm_editorial_tracker_alert_subscribe', 'nonce');

            $full_name = sanitize_text_field(wp_unslash($_POST['full_name'] ?? ''));
            $email = sanitize_email(wp_unslash($_POST['email'] ?? ''));
            $post_group_id = absint(wp_unslash($_POST['post_group_id'] ?? 0));
            $post_group_slug = sanitize_title(wp_unslash($_POST['post_group_slug'] ?? ''));
            $post_group_name = sanitize_text_field(wp_unslash($_POST['post_group_name'] ?? ''));
            $crm_post_id = absint(wp_unslash($_POST['crm_post_id'] ?? 0));

            if ($full_name === '' || $email === '') {
                wp_send_json_error(['message' => __('Please add your name and email.', 'senna-finance')]);
                return;
            }

            if (!is_email($email)) {
                wp_send_json_error(['message' => __('Please use a valid email address.', 'senna-finance')]);
                return;
            }

            $tracker = $this->get_crm_editorial_tracker_group_context($post_group_id, $post_group_slug, $post_group_name);
            if (!empty($tracker)) {
                $post_group_id = (int) ($tracker['id'] ?? $post_group_id);
                $post_group_slug = sanitize_title((string) ($tracker['slug'] ?? $post_group_slug));
                $post_group_name = trim((string) ($tracker['name'] ?? $post_group_name));
            }

            if ($post_group_name === '') {
                $post_group_name = __('Private equity roles', 'senna-finance');
            }

            $this->ensure_crm_contact_capture_tracker_subscription_columns();

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            $now = current_time('mysql');
            $inserted = $wpdb->insert(
                $table_name,
                [
                    'full_name' => $full_name,
                    'email' => $email,
                    'post_group_id' => $post_group_id,
                    'post_group_slug' => $post_group_slug,
                    'post_group_name' => $post_group_name,
                    'alert_source' => 'editorial_community_tracker_banner',
                    'alert_status' => 'subscribed',
                    'alert_frequency' => 'instant_single_role',
                    'last_alert_post_id' => $crm_post_id,
                    'created_at' => $now,
                    'updated_at' => $now,
                ],
                ['%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s']
            );

            if ($inserted === false) {
                wp_send_json_error(['message' => __('We could not save your alert yet. Please try again.', 'senna-finance')]);
                return;
            }

            $contact_data = wp_json_encode([
                'full_name' => $full_name,
                'email' => $email,
                'post_group_id' => $post_group_id,
                'post_group_slug' => $post_group_slug,
                'post_group_name' => $post_group_name,
            ]);
            $this->set_signup_scoped_cookie('sffc_contact_data', (string) $contact_data, time() + (30 * DAY_IN_SECONDS));
            $this->set_signup_scoped_cookie('sffc_signup_email', $email, time() + (30 * DAY_IN_SECONDS));

            $item = $crm_post_id > 0 ? $this->get_crm_editorial_community_feed_item_by_id($crm_post_id) : [];
            $email_sent = $this->send_crm_editorial_tracker_subscription_confirmation_email($email, $full_name, [
                'id' => $post_group_id,
                'slug' => $post_group_slug,
                'name' => $post_group_name,
            ], $item);

            $redirect_url = '';
            if (!is_user_logged_in()) {
                $login_url = home_url('/login/');
                if (!empty($item)) {
                    $role_url = $this->get_crm_editorial_community_public_opportunity_url(
                        $item,
                        (string) ($item['role_title'] ?? ''),
                        (string) ($item['company'] ?? '')
                    );
                    if ($role_url !== '' && $role_url !== '#') {
                        $login_url = add_query_arg('redirect_to', $role_url, $login_url);
                    }
                }
                $redirect_url = esc_url_raw($login_url);
            }

            wp_send_json_success([
                'message' => __('You are subscribed. We saved this tracker to your alerts and sent a confirmation email.', 'senna-finance'),
                'emailSent' => $email_sent,
                'redirectUrl' => $redirect_url,
            ]);
        }

        private function ensure_crm_contact_capture_tracker_subscription_columns()
        {
            global $wpdb;

            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            $charset_collate = $wpdb->get_charset_collate();
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name));

            if ($table_exists !== $table_name) {
                require_once ABSPATH . 'wp-admin/includes/upgrade.php';
                dbDelta("CREATE TABLE {$table_name} (
                    id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
                    full_name varchar(200) NOT NULL,
                    email varchar(200) NOT NULL,
                    post_group_id bigint(20) unsigned DEFAULT 0,
                    post_group_slug varchar(200) DEFAULT '',
                    post_group_name varchar(255) DEFAULT '',
                    alert_source varchar(120) DEFAULT '',
                    alert_status varchar(40) DEFAULT 'subscribed',
                    alert_frequency varchar(40) DEFAULT 'instant_single_role',
                    last_alert_post_id bigint(20) unsigned DEFAULT 0,
                    last_alert_sent_at datetime DEFAULT NULL,
                    direct_apply_source_post_id bigint(20) unsigned DEFAULT 0,
                    direct_apply_source_seniority varchar(40) DEFAULT '',
                    created_at datetime DEFAULT CURRENT_TIMESTAMP,
                    updated_at datetime DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY  (id),
                    KEY email (email),
                    KEY post_group_slug (post_group_slug),
                    KEY alert_status (alert_status)
                ) {$charset_collate};");
                return;
            }

            $columns = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table_name}", 0);
            $column_defs = [
                'post_group_id' => "ALTER TABLE {$table_name} ADD COLUMN post_group_id bigint(20) unsigned DEFAULT 0",
                'post_group_slug' => "ALTER TABLE {$table_name} ADD COLUMN post_group_slug varchar(200) DEFAULT ''",
                'post_group_name' => "ALTER TABLE {$table_name} ADD COLUMN post_group_name varchar(255) DEFAULT ''",
                'alert_source' => "ALTER TABLE {$table_name} ADD COLUMN alert_source varchar(120) DEFAULT ''",
                'alert_status' => "ALTER TABLE {$table_name} ADD COLUMN alert_status varchar(40) DEFAULT 'subscribed'",
                'alert_frequency' => "ALTER TABLE {$table_name} ADD COLUMN alert_frequency varchar(40) DEFAULT 'instant_single_role'",
                'last_alert_post_id' => "ALTER TABLE {$table_name} ADD COLUMN last_alert_post_id bigint(20) unsigned DEFAULT 0",
                'last_alert_sent_at' => "ALTER TABLE {$table_name} ADD COLUMN last_alert_sent_at datetime DEFAULT NULL",
                'direct_apply_source_post_id' => "ALTER TABLE {$table_name} ADD COLUMN direct_apply_source_post_id bigint(20) unsigned DEFAULT 0",
                'direct_apply_source_seniority' => "ALTER TABLE {$table_name} ADD COLUMN direct_apply_source_seniority varchar(40) DEFAULT ''",
                'updated_at' => "ALTER TABLE {$table_name} ADD COLUMN updated_at datetime DEFAULT CURRENT_TIMESTAMP",
            ];

            foreach ($column_defs as $column => $sql) {
                if (!in_array($column, $columns, true)) {
                    $wpdb->query($sql);
                }
            }
        }

        private function get_crm_editorial_tracker_group_context($post_group_id = 0, $post_group_slug = '', $post_group_name = '')
        {
            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }

            $group_model = new SFFC_CRM_Post_Group();
            $groups = (array) $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => true,
            ]);

            foreach ($groups as $group) {
                $group_id = (int) ($group['id'] ?? 0);
                $group_slug = sanitize_title((string) ($group['slug'] ?? ''));
                if (
                    ($post_group_id > 0 && $group_id === (int) $post_group_id)
                    || ($post_group_slug !== '' && $group_slug === sanitize_title((string) $post_group_slug))
                ) {
                    return [
                        'id' => $group_id,
                        'slug' => $group_slug,
                        'name' => trim((string) ($group['name'] ?? $post_group_name)),
                    ];
                }
            }

            return [
                'id' => (int) $post_group_id,
                'slug' => sanitize_title((string) $post_group_slug),
                'name' => trim((string) $post_group_name),
            ];
        }

        private function send_crm_editorial_tracker_single_role_alert_email($email, $full_name, array $tracker, array $item = [])
        {
            if (!is_email($email)) {
                return false;
            }

            $role_title = trim((string) ($item['role_title'] ?? __('New private equity role', 'senna-finance')));
            $company = trim((string) ($item['company'] ?? ''));
            $location = $this->get_crm_editorial_community_location_filter_label((string) ($item['location'] ?? ''));
            if ($location === '') {
                $location = __('the Middle East', 'senna-finance');
            }
            $salary_text = trim((string) ($item['salary_text'] ?? ''));
            $seniority = $this->get_crm_editorial_community_seniority_filter_label((string) ($item['seniority'] ?? ''));
            $sector = $this->get_crm_editorial_community_sector_filter_label((string) ($item['sector'] ?? ''));
            $tracker_name = trim((string) ($tracker['name'] ?? __('Private equity roles', 'senna-finance')));
            $role_url = !empty($item)
                ? $this->get_crm_editorial_community_public_opportunity_url($item, $role_title, $company)
                : home_url('/login/');
            $login_url = add_query_arg('redirect_to', $role_url, home_url('/login/'));
            $first_name = trim((string) strtok((string) $full_name, ' '));
            if ($first_name === '') {
                $first_name = __('there', 'senna-finance');
            }

            $subject = sprintf(__('New %1$s role in %2$s', 'senna-finance'), $sector !== '' ? $sector : $tracker_name, $location);
            $preheader = sprintf(__('A new role was added to %s.', 'senna-finance'), $tracker_name);
            $eyebrow = __('New tracker match', 'senna-finance');
            $headline = $role_title;
            $intro = sprintf(__('A new role was added to your %s tracker.', 'senna-finance'), $tracker_name);
            $meta = array_values(array_filter([$company, $location, $sector, $seniority]));
            $details = array_values(array_filter([
                $salary_text !== '' ? sprintf(__('Salary: %s', 'senna-finance'), $salary_text) : '',
                !empty($item['posted_label']) ? sprintf(__('Posted: %s', 'senna-finance'), trim((string) $item['posted_label'])) : '',
            ]));

            $html = $this->build_crm_editorial_tracker_email_html([
                'preheader' => $preheader,
                'eyebrow' => $eyebrow,
                'headline' => $headline,
                'greeting' => sprintf(__('Hi %s,', 'senna-finance'), $first_name),
                'intro' => $intro,
                'tracker_name' => $tracker_name,
                'role_title' => $role_title,
                'meta' => $meta,
                'details' => $details,
                'cta_url' => $login_url,
                'cta_label' => __('View role', 'senna-finance'),
                'footer' => __('You are receiving this because you subscribed to this MENA Careers tracker. Sign in to manage your alerts.', 'senna-finance'),
            ]);

            if (class_exists('SFFC_CRM_SendGrid_Service')) {
                $sendgrid = SFFC_CRM_SendGrid_Service::get_instance();
                if ($sendgrid && $sendgrid->is_configured()) {
                    $result = $sendgrid->send_email(
                        $subject,
                        $html,
                        $email,
                        null,
                        [
                            'email_type' => 'tracker_single_role_alert',
                            'post_group_slug' => sanitize_title((string) ($tracker['slug'] ?? '')),
                            'crm_post_id' => (string) (int) ($item['crm_post_id'] ?? $item['post_id'] ?? 0),
                        ],
                        ['tracker_alert', 'single_role_alert'],
                        'internship_alerts'
                    );

                    if (!is_wp_error($result)) {
                        return true;
                    }

                    error_log('MENA Careers tracker alert SendGrid error: ' . $result->get_error_message());
                }
            }

            return (bool) wp_mail($email, $subject, $html, $this->get_cv_match_newsletter_email_headers('internship_alerts'));
        }

