        public function send_crm_editorial_tracker_alerts_for_post($crm_post_id, $is_new = true)
        {
            $crm_post_id = absint($crm_post_id);
            if (!$is_new || $crm_post_id <= 0) {
                return;
            }

            $item = $this->get_crm_editorial_community_feed_item_by_id($crm_post_id);
            if (empty($item)) {
                return;
            }

            $matched_slugs = array_values(array_unique(array_filter(array_map('sanitize_title', $this->get_cv_match_studio_mailbox_group_slugs($item)))));
            if (empty($matched_slugs)) {
                $matched_slugs = array_values(array_unique(array_filter(array_map('sanitize_title', $this->get_crm_reddit_group_slugs_for_post($crm_post_id)))));
            }
            if (empty($matched_slugs)) {
                return;
            }

            $this->ensure_crm_contact_capture_tracker_subscription_columns();

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            $placeholders = implode(',', array_fill(0, count($matched_slugs), '%s'));
            $subscribers = $wpdb->get_results(
                $wpdb->prepare(
                    "SELECT id, full_name, email, post_group_id, post_group_slug, post_group_name
                     FROM {$table_name}
                     WHERE alert_status = 'subscribed'
                       AND post_group_slug IN ({$placeholders})
                       AND (last_alert_post_id IS NULL OR last_alert_post_id <> %d)
                       AND email <> ''
                     ORDER BY created_at ASC
                     LIMIT 200",
                    array_merge($matched_slugs, [$crm_post_id])
                ),
                ARRAY_A
            );

            if (empty($subscribers)) {
                return;
            }

            $sent_keys = [];
            foreach ($subscribers as $subscriber) {
                $email = sanitize_email((string) ($subscriber['email'] ?? ''));
                if (!is_email($email)) {
                    continue;
                }

                $tracker = [
                    'id' => (int) ($subscriber['post_group_id'] ?? 0),
                    'slug' => sanitize_title((string) ($subscriber['post_group_slug'] ?? '')),
                    'name' => trim((string) ($subscriber['post_group_name'] ?? __('Private equity roles', 'senna-finance'))),
                ];
                $sent_key = strtolower($email) . '|' . $tracker['slug'];
                if (isset($sent_keys[$sent_key])) {
                    continue;
                }
                $sent_keys[$sent_key] = true;

                $sent = $this->send_crm_editorial_tracker_single_role_alert_email(
                    $email,
                    trim((string) ($subscriber['full_name'] ?? __('there', 'senna-finance'))),
                    $tracker,
                    $item
                );

                if ($sent) {
                    $wpdb->update(
                        $table_name,
                        [
                            'last_alert_post_id' => $crm_post_id,
                            'updated_at' => current_time('mysql'),
                        ],
                        [
                            'email' => $email,
                            'post_group_slug' => $tracker['slug'],
                        ],
                        ['%d', '%s'],
                        ['%s', '%s']
                    );
                }
            }
        }

        private function generate_crm_editorial_tracker_alert_email_copy_with_claude(array $context)
        {
            if (!class_exists('SFFC_Claude_API_Manager')) {
                return [];
            }

            $prompt = sprintf(
                "Write concise, polished LinkedIn-style job alert copy for a single premium finance role. Return strict JSON only with keys subject, intro, role_summary, candidate_request. Do not invent facts. Use natural grammar and avoid spammy language.\n\nTracker: %s\nRole: %s\nCompany: %s\nLocation: %s\nSeniority: %s\nSalary: %s\nRecipient first name: %s",
                (string) ($context['tracker_name'] ?? ''),
                (string) ($context['role_title'] ?? ''),
                (string) ($context['company'] ?? ''),
                (string) ($context['location'] ?? ''),
                (string) ($context['seniority'] ?? ''),
                (string) ($context['salary_text'] ?? ''),
                (string) ($context['first_name'] ?? '')
            );

            $claude = SFFC_Claude_API_Manager::get_instance();
            $response = $claude->call_api($prompt, [
                'mode' => 'career',
                'max_tokens' => 500,
                'temperature' => 0.25,
                'system_prompt' => 'You write concise, high-quality private-market career alerts. Return valid JSON only.',
            ]);

            $text = trim((string) ($response['content'][0]['text'] ?? ''));
            if ($text === '') {
                return [];
            }

            $start = strpos($text, '{');
            $end = strrpos($text, '}');
            if ($start === false || $end === false || $end <= $start) {
                return [];
            }

            $json = substr($text, $start, ($end - $start) + 1);
            $decoded = json_decode($json, true);
            return is_array($decoded) ? $decoded : [];
        }

        /**
         * AJAX handler to save flow data (extended contact capture with questions)
         */
        public function ajax_save_flow_data()
        {
            check_ajax_referer('sffc_contact_flow', 'nonce');

            $flow_data_json = $_POST['flow_data'] ?? '';
            $flow_data = json_decode(stripslashes($flow_data_json), true);

            if (empty($flow_data) || empty($flow_data['full_name']) || empty($flow_data['email'])) {
                wp_send_json_error('Invalid flow data');
                return;
            }

            // Save extended data to cookie (expires in 30 days)
            $cookie_data = [
                'full_name' => sanitize_text_field($flow_data['full_name']),
                'email' => sanitize_email($flow_data['email']),
                'from_job_post' => !empty($flow_data['from_job_post']),
                'post_id' => !empty($flow_data['post_id']) ? intval($flow_data['post_id']) : 0,
                'post_title' => !empty($flow_data['post_title']) ? sanitize_text_field($flow_data['post_title']) : '',
                'target_role' => !empty($flow_data['target_role']) ? sanitize_text_field($flow_data['target_role']) : '',
                'years_experience' => !empty($flow_data['years_experience']) ? sanitize_text_field($flow_data['years_experience']) : '',
                'target_location' => !empty($flow_data['target_location']) ? array_map('sanitize_text_field', $flow_data['target_location']) : [],
                'visa_status' => !empty($flow_data['visa_status']) ? sanitize_text_field($flow_data['visa_status']) : '',
                'current_employer' => !empty($flow_data['current_employer']) ? sanitize_text_field($flow_data['current_employer']) : '',
            ];

            $this->set_signup_scoped_cookie('sffc_contact_data', json_encode($cookie_data), time() + (30 * 24 * 60 * 60));

            wp_send_json_success('Flow data saved successfully');
        }

        private function extract_primary_locale($header)
        {
            if (empty($header)) {
                return '';
            }

            $segments = explode(',', $header);
            if (!empty($segments)) {
                return trim($segments[0]);
            }

            return trim($header);
        }

        private function output_timezone_cookie_script()
        {
            if (self::$timezone_cookie_script_output) {
                return;
            }

            self::$timezone_cookie_script_output = true;
        ?>
            <script>
                (function() {
                    try {
                        var tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
                        if (tz) {
                            var expires = new Date();
                            expires.setTime(expires.getTime() + (30 * 24 * 60 * 60 * 1000));
                            document.cookie = 'currency_detector_timezone=' + encodeURIComponent(tz) + ';expires=' + expires.toUTCString() + ';path=/';
                        }
                    } catch (e) {}
                })();
            </script>
        <?php
        }

        private function normalize_company_logo_url($logo)
        {
            $logo = trim((string) $logo);
            if ($logo === '') {
                return '';
            }

            if (!preg_match('#^https?://#i', $logo)) {
                $logo = preg_replace('#^(https?:)?//#i', '', $logo);

                // Skip clearbit - just return empty or direct URL
                if (strpos($logo, '/') === false && strpos($logo, '.') !== false) {
                    // Domain only - return empty to use initials instead
                    return '';
                } else {
                    $logo = 'https://' . ltrim($logo, '/');
                }
            }

            return $logo;
        }

