        private function get_crm_cv_match_studio_url()
        {
            global $wpdb;

            $post_id = (int) $wpdb->get_var(
                $wpdb->prepare(
                    "SELECT ID
                    FROM {$wpdb->posts}
                    WHERE post_status = 'publish'
                      AND post_type IN ('page','post')
                      AND post_content LIKE %s
                    ORDER BY post_type = 'page' DESC, menu_order ASC, post_date DESC
                    LIMIT 1",
                    '%[sffc_crm_cv_match_studio%'
                )
            );

            if ($post_id > 0) {
                $url = get_permalink($post_id);
                if ($url) {
                    return (string) $url;
                }
            }

            return home_url('/community/');
        }

        private function mask_dashboard_contact_name($name)
        {
            $name = trim((string) $name);
            if ($name === '') {
                return __('Hiring contact available', 'senna-finance');
            }

            if (preg_match('/^(recruiter contact|talent contact|hiring team|hiring manager)$/i', $name)) {
                return __('Hiring contact available', 'senna-finance');
            }

            $parts = preg_split('/\s+/', $name);
            $masked_parts = [];

            foreach ((array) $parts as $index => $part) {
                $part = trim((string) $part);
                if ($part === '') {
                    continue;
                }

                $first = function_exists('mb_substr') ? mb_substr($part, 0, 1) : substr($part, 0, 1);
                if ($index === 0 && count($parts) > 1) {
                    $masked_parts[] = strtoupper($first) . '.';
                } else {
                    $masked_parts[] = strtoupper($first) . '****';
                }
            }

            return !empty($masked_parts) ? implode(' ', $masked_parts) : __('Hiring contact available', 'senna-finance');
        }

        private function mask_dashboard_matches_preview_label($value, $fallback = '')
        {
            $value = trim((string) $value);
            if ($value === '') {
                return (string) $fallback;
            }

            $parts = preg_split('/\s+/', $value);
            $masked_parts = [];

            foreach ((array) $parts as $index => $part) {
                $part = trim((string) $part);
                if ($part === '') {
                    continue;
                }

                $first = function_exists('mb_substr') ? mb_substr($part, 0, 1) : substr($part, 0, 1);
                $last = function_exists('mb_substr') ? mb_substr($part, -1) : substr($part, -1);

                if (count($parts) === 1 && strlen($part) >= 7) {
                    $masked_parts[] = strtoupper((string) $first) . '*****' . strtolower((string) $last);
                    continue;
                }

                $masked_parts[] = strtoupper((string) $first) . ($index === 0 ? '****' : '***');
            }

            return !empty($masked_parts) ? implode('', $masked_parts) : (string) $fallback;
        }

        private function render_dashboard_fit_signal_badges(array $post, $limit = 5)
        {
            $signals = $this->get_dashboard_fit_signals($post, $limit);
            if (empty($signals)) {
                return '';
            }

            ob_start();
        ?>
            <span class="sffc-crm-dashboard-fit-signals" aria-label="<?php esc_attr_e('Role fit signals', 'senna-finance'); ?>">
                <?php foreach ($signals as $signal) : ?>
                    <span class="sffc-crm-dashboard-fit-chip"><?php echo esc_html($signal); ?></span>
                <?php endforeach; ?>
            </span>
            <?php
            return ob_get_clean();
        }

        private function get_dashboard_fit_signals(array $post, $limit = 5)
        {
            $signals = [];
            $experience_signal = $this->format_dashboard_experience_signal($post['experience_years'] ?? ($post['years_experience'] ?? ''));
            if ($experience_signal !== '') {
                $signals[] = $experience_signal;
            }

            $skills = [];
            if (!empty($post['skills_mentioned'])) {
                if (is_array($post['skills_mentioned'])) {
                    $skills = $post['skills_mentioned'];
                } else {
                    $decoded_skills = json_decode((string) $post['skills_mentioned'], true);
                    $skills = is_array($decoded_skills) ? $decoded_skills : preg_split('/[\r\n,|]+/', (string) $post['skills_mentioned']);
                }
            }

            $keywords = !empty($post['keywords']) ? $this->normalize_recruiter_intro_keywords($post['keywords']) : [];
            $candidates = array_merge((array) $skills, (array) $keywords);

            $seen = [];
            foreach ($candidates as $candidate) {
                if (count($signals) >= $limit) {
                    break;
                }

                if (is_array($candidate)) {
                    $candidate = $candidate['keyword'] ?? $candidate['name'] ?? $candidate['label'] ?? '';
                }

                $label = $this->normalize_dashboard_fit_signal_label($candidate);
                if ($label === '') {
                    continue;
                }

                $key = strtolower($label);
                if (isset($seen[$key])) {
                    continue;
                }

                $seen[$key] = true;
                $signals[] = $label;
            }

            return array_slice($signals, 0, max(1, (int) $limit));
        }

        private function normalize_dashboard_fit_signal_label($label)
        {
            $label = trim(sanitize_text_field((string) $label));
            if ($label === '') {
                return '';
            }

            $generic_terms = [
                'finance',
                'financial services',
                'dubai',
                'uae',
                'role',
                'job',
            ];
            if (in_array(strtolower($label), $generic_terms, true)) {
                return '';
            }

            if (function_exists('mb_strlen') && mb_strlen($label) > 28) {
                $label = mb_substr($label, 0, 25) . '...';
            } elseif (strlen($label) > 28) {
                $label = substr($label, 0, 25) . '...';
            }

            return $label;
        }

        private function format_dashboard_experience_signal($value)
        {
            $value = trim(sanitize_text_field((string) $value));
            if ($value === '') {
                return '';
            }

            if (preg_match('/(\d+)\s*-\s*(\d+)/', $value, $matches)) {
                return sprintf(__('%d-%d yrs', 'senna-finance'), (int) $matches[1], (int) $matches[2]);
            }

            if (preg_match('/(\d+)/', $value, $matches)) {
                return sprintf(__('%d+ yrs', 'senna-finance'), (int) $matches[1]);
            }

            return $this->normalize_dashboard_fit_signal_label($value);
        }

