        public function render_matching_engine_landing($atts = [])
        {
            $atts = shortcode_atts([
                'title' => 'See the roles that actually match your background',
                'subtitle' => 'Paste your CV, upload your resume, or start from your experience. MENA Careers maps your profile against live recruiter-led opportunities using the same post skills and keywords already stored in CRM.',
                'cta_text' => 'Build My Matches',
                'secondary_text' => 'I already have an account',
                'secondary_url' => wp_login_url(home_url('/terminal/?tab=console')),
            ], $atts, 'sffc_crm_matching_engine');

            wp_enqueue_style(
                'sffc-institutional-article',
                SFFC_PLUGIN_URL . 'assets/css/institutional-article.css',
                [],
                SFFC_VERSION
            );

            wp_enqueue_style(
                'sffc-crm-matching-engine',
                SFFC_PLUGIN_URL . 'assets/css/crm/matching-engine-landing.css',
                ['sffc-institutional-article'],
                SFFC_VERSION
            );

            wp_enqueue_script(
                'sffc-crm-matching-engine',
                SFFC_PLUGIN_URL . 'assets/js/crm/matching-engine-landing.js',
                [],
                SFFC_VERSION,
                true
            );

            $skill_signals = $this->get_matching_engine_skill_signals();
            $match_posts = $this->get_matching_engine_posts();
            $logged_in = is_user_logged_in();
            $dashboard_url = home_url('/terminal/?tab=console');
            $current_user = wp_get_current_user();
            $user_name = $logged_in ? ($current_user->display_name ?: $current_user->user_login) : '';
            $user_email = $logged_in ? $current_user->user_email : '';

            wp_localize_script('sffc-crm-matching-engine', 'sffcCrmMatchingEngine', [
                'posts' => $match_posts,
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_crm_nonce'),
                'loginUrl' => wp_login_url($dashboard_url),
                'dashboardUrl' => $dashboard_url,
                'loggedIn' => $logged_in,
                'cvGapUrl' => home_url('/cv-gap-analyser/'),
                'currentUser' => [
                    'name' => $user_name,
                    'email' => $user_email,
                ],
            ]);

            ob_start();
        ?>
            <section class="sffc-crm-matching-engine inst-terminal" data-component="crm-matching-engine">
                <div class="sffc-crm-matching-shell">
                    <div class="sffc-crm-matching-main">
                        <section class="sffc-crm-matching-hub" data-matching-hub>
                            <div class="sffc-crm-matching-hub-copy">
