        public function render_crm_editorial_community_search($atts = [])
        {
            $atts = shortcode_atts([
                'placeholder' => __('Search jobs, recruiters, or resources', 'senna-finance'),
                'result_url' => home_url('/terminal/'),
            ], $atts, 'sffc_community_editorial_search');
            $is_logged_in = is_user_logged_in();

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/css/crm/community-editorial.css',
                [],
                $css_version
            );

            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                : SFFC_VERSION;

            wp_enqueue_script(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/js/crm/community-editorial.js',
                [],
                $js_version,
                true
            );

            wp_add_inline_script('sffc-crm-community-editorial', 'window.sffcCommunityEditorialConfig = Object.assign({}, window.sffcCommunityEditorialConfig || {}, ' . wp_json_encode([
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'crmNonce' => wp_create_nonce('sffc_crm_nonce'),
                'autocompleteNonce' => wp_create_nonce('sffc_crm_editorial_autocomplete_search'),
                'standaloneSearchNonce' => wp_create_nonce('sffc_crm_editorial_standalone_search'),
                'filterFeedNonce' => wp_create_nonce('sffc_crm_editorial_filter_feed'),
                'matchCvUploadNonce' => wp_create_nonce('sffc_crm_editorial_upload_match_cv'),
                'cvUploadMembershipNonce' => wp_create_nonce('sffc_crm_editorial_cv_upload_membership_capture'),
                'terminalUrl' => home_url('/terminal/'),
                'membershipsUrl' => home_url('/memberships/'),
                'isLoggedIn' => $is_logged_in,
                'currentUserEmail' => is_user_logged_in() ? sanitize_email((string) wp_get_current_user()->user_email) : '',
                'strings' => [
                    'autocompleteLoading' => __('Searching MENA Careers…', 'senna-finance'),
                    'autocompleteEmpty' => __('No matching results found yet.', 'senna-finance'),
                ],
            ]) . ');', 'before');

            $result_url = trim((string) ($atts['result_url'] ?? ''));
            if ($result_url === '') {
                $result_url = home_url('/terminal/');
            }

            ob_start();
            ?>
            <section
                class="sffc-community-editorial-search"
                data-sffc-community-editorial-search
                data-sffc-community-search-result-url="<?php echo esc_url($result_url); ?>"
                data-sffc-community-search-logged-in="<?php echo $is_logged_in ? '1' : '0'; ?>"
            >
                <div class="sffc-community-editorial-search__filters" aria-label="<?php esc_attr_e('Search type', 'senna-finance'); ?>">
                    <button type="button" class="is-active" data-sffc-community-standalone-category="jobs"><?php esc_html_e('Jobs', 'senna-finance'); ?></button>
                    <?php if ($is_logged_in) : ?>
                        <button type="button" data-sffc-community-standalone-category="resources"><?php esc_html_e('Resources', 'senna-finance'); ?></button>
                    <?php endif; ?>
                </div>
                <form class="sffc-community-editorial-search__form" data-sffc-community-standalone-form autocomplete="off">
                    <span class="sffc-community-editorial-search__icon" aria-hidden="true">
                        <svg viewBox="0 0 24 24" focusable="false"><path d="M10.8 18.1a7.3 7.3 0 1 1 0-14.6 7.3 7.3 0 0 1 0 14.6Zm0-1.8a5.5 5.5 0 1 0 0-11 5.5 5.5 0 0 0 0 11Zm5.1.9 1.3-1.3 4.1 4.1-1.3 1.3-4.1-4.1Z"/></svg>
                    </span>
                    <input
                        type="search"
                        data-sffc-community-standalone-input
                        placeholder="<?php echo esc_attr((string) $atts['placeholder']); ?>"
                        aria-label="<?php esc_attr_e('Search MENA Careers', 'senna-finance'); ?>"
                    >
                    <button type="submit" class="sffc-community-editorial-search__submit" aria-label="<?php esc_attr_e('Search', 'senna-finance'); ?>">→</button>
                </form>
                <div class="sffc-community-editorial-search__results" data-sffc-community-standalone-results hidden></div>
            </section>
            <?php

            return (string) ob_get_clean();
        }

        public function render_crm_editorial_community_launcher($atts = [])
        {
            $atts = shortcode_atts([
                'placeholder' => __('Search roles, companies, or locations', 'senna-finance'),
                'button_label' => __('Filter jobs', 'senna-finance'),
                'target' => '',
            ], $atts, 'sffc_crm_editorial_community_launcher');

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/css/crm/community-editorial.css',
                [],
                $css_version
            );

            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                : SFFC_VERSION;

            wp_enqueue_script(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/js/crm/community-editorial.js',
                [],
                $js_version,
                true
            );

            wp_add_inline_script('sffc-crm-community-editorial', 'window.sffcCommunityEditorialConfig = Object.assign({}, window.sffcCommunityEditorialConfig || {}, ' . wp_json_encode([
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'filterFeedNonce' => wp_create_nonce('sffc_crm_editorial_filter_feed'),
            ]) . ');', 'before');

            $target_selector = trim((string) ($atts['target'] ?? ''));

            ob_start();
            ?>
