        public function render_crm_editorial_jobs_carousel($atts = [])
        {
            $atts = shortcode_atts([
                'limit' => 6,
                'pool' => 48,
                'title' => '',
            ], $atts, 'sffc_crm_jobs_carousel');

            $limit = max(3, min(12, (int) ($atts['limit'] ?? 6)));
            $pool = max($limit, min(96, (int) ($atts['pool'] ?? 48)));
            $jobs = $this->get_crm_editorial_jobs_carousel_items($limit, $pool);

            if (empty($jobs)) {
                return '';
            }

            $is_logged_in = is_user_logged_in();

            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/community-editorial.css')
                : SFFC_VERSION;

            wp_enqueue_style(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/css/crm/community-editorial.css',
                [],
                $css_version
            );

            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/community-editorial.js')
                : SFFC_VERSION;

            wp_enqueue_script(
                'sffc-crm-community-editorial',
                SFFC_PLUGIN_URL . 'assets/js/crm/community-editorial.js',
                [],
                $js_version,
                true
            );

            ob_start();
            ?>
            <section class="sffc-jobs-carousel" data-sffc-jobs-carousel>
                <?php if (trim((string) ($atts['title'] ?? '')) !== '') : ?>
                    <h2 class="sffc-jobs-carousel__title"><?php echo esc_html((string) $atts['title']); ?></h2>
                <?php endif; ?>
                <div class="sffc-jobs-carousel__viewport" data-sffc-jobs-carousel-track>
                    <?php foreach ($jobs as $job) : ?>
                        <?php
                        $title = trim((string) ($job['role_title'] ?? __('Featured role', 'senna-finance')));
                        $company = $is_logged_in ? trim((string) ($job['company'] ?? '')) : '';
                        $location = $is_logged_in ? trim((string) ($job['location'] ?? '')) : '';
                        $posted = trim((string) ($job['posted_label'] ?? ''));
                        $recruiter = trim((string) ($job['recruiter_name'] ?? ''));
                        $display_recruiter = $is_logged_in ? $recruiter : $this->format_crm_reddit_recruiter_short_name($recruiter);
                        $recruiter_title = trim((string) ($job['recruiter_title'] ?? ''));
                        $avatar = trim((string) ($job['recruiter_photo'] ?? ''));
                        $logo = trim((string) ($job['company_logo'] ?? ''));
                        $image = $avatar !== '' ? $avatar : $logo;
                        $url = trim((string) ($job['view_url'] ?? ''));
                        $initial_source = $display_recruiter !== '' ? $display_recruiter : $title;
                        $initial = function_exists('mb_substr')
                            ? mb_strtoupper(mb_substr($initial_source, 0, 1))
                            : strtoupper(substr($initial_source, 0, 1));
                        ?>
                        <article class="sffc-jobs-carousel__card">
                            <a class="sffc-jobs-carousel__link" href="<?php echo esc_url($url !== '' ? $url : home_url('/terminal/')); ?>">
                                <span class="sffc-jobs-carousel__media<?php echo $image !== '' ? ' has-image' : ''; ?>" aria-hidden="true">
                                    <?php if ($image !== '') : ?>
                                        <img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr($recruiter !== '' ? $recruiter : $title); ?>" loading="lazy">
                                    <?php else : ?>
                                        <strong><?php echo esc_html($initial !== '' ? $initial : 'S'); ?></strong>
                                    <?php endif; ?>
                                </span>
                                <span class="sffc-jobs-carousel__copy">
                                    <?php if ($posted !== '') : ?>
                                        <time><?php echo esc_html($posted); ?></time>
                                    <?php endif; ?>
                                    <strong><?php echo esc_html($title); ?></strong>
                                    <?php if ($company !== '' || $location !== '') : ?>
                                        <span><?php echo esc_html(implode(' · ', array_filter([$company, $location]))); ?></span>
                                    <?php endif; ?>
                                    <?php if ($display_recruiter !== '' || $recruiter_title !== '') : ?>
                                        <em><?php echo esc_html(implode(' | ', array_filter([$display_recruiter, $recruiter_title]))); ?></em>
                                    <?php endif; ?>
                                </span>
                                <span class="sffc-jobs-carousel__cta"><?php esc_html_e('View role', 'senna-finance'); ?> <span aria-hidden="true">&rarr;</span></span>
                            </a>
                        </article>
                    <?php endforeach; ?>
                </div>
                <div class="sffc-jobs-carousel__controls" aria-label="<?php esc_attr_e('Job carousel controls', 'senna-finance'); ?>">
                    <button type="button" data-sffc-jobs-carousel-prev aria-label="<?php esc_attr_e('Previous roles', 'senna-finance'); ?>">&larr;</button>
                    <button type="button" data-sffc-jobs-carousel-next aria-label="<?php esc_attr_e('Next roles', 'senna-finance'); ?>">&rarr;</button>
                </div>
            </section>
            <?php

            return (string) ob_get_clean();
        }

        private function get_crm_editorial_jobs_carousel_items($limit = 6, $pool = 48)
        {
            global $wpdb;

            $limit = max(3, min(12, (int) $limit));
            $pool = max($limit, min(96, (int) $pool));
            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $early_bird_exclusion_select = $this->get_crm_posts_early_bird_exclusion_select('p');

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT p.id, p.role_title, p.company, p.location, p.location_country,
                        p.salary_text, p.seniority, p.sector, p.content_snippet, p.posted_at,
                        p.is_remote, p.is_hybrid, p.application_url, p.wp_post_id, p.company_logo, p.keywords,
                        p.experience_years, {$early_bird_exclusion_select},
                        COALESCE(NULLIF(p.company_logo, ''), r.default_company_logo) AS company_logo,
                        r.id as recruiter_id, r.name as recruiter_name, r.firm as recruiter_firm,
                        r.photo_url as recruiter_photo, r.title as recruiter_title,
                        r.email as recruiter_email, r.linkedin_url as recruiter_linkedin,
                        r.sectors as recruiter_specializations
                 FROM {$posts_table} p
                 LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id
                 WHERE p.is_active = 1
                   AND p.admin_approved = 1
                   AND (p.post_status IS NULL OR p.post_status = 'open')
                   AND p.role_title <> ''
                 ORDER BY p.posted_at DESC, p.id DESC
                 LIMIT %d",
                $pool
            ), ARRAY_A);

            if (empty($rows) || !is_array($rows)) {
                return [];
            }

            shuffle($rows);
            $rows = array_slice($rows, 0, $limit);

            return array_map(function ($row) {
                return $this->build_crm_reddit_dashboard_crm_item((array) $row);
            }, $rows);
        }

        private function get_crm_posts_early_bird_exclusion_select($alias = 'p')
        {
            global $wpdb;

            static $has_column = null;

            if ($has_column === null) {
                $table = $wpdb->prefix . 'sffc_crm_posts';
                $column = $wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s", 'exclude_from_early_bird'));

                if (empty($column)) {
                    $wpdb->query("ALTER TABLE {$table} ADD COLUMN exclude_from_early_bird tinyint(1) DEFAULT 0");
                    $column = $wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s", 'exclude_from_early_bird'));
                }

                $has_column = !empty($column);
            }

            if (!$has_column) {
                return '0 AS exclude_from_early_bird';
            }

            $alias = preg_replace('/[^A-Za-z0-9_]/', '', (string) $alias);
            return ($alias !== '' ? "{$alias}." : '') . 'exclude_from_early_bird';
        }

