                'savedListsUrl' => home_url('/terminal/?tab=saved-lists'),
                'pdfScriptUrl' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
                'pdfWorker' => 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js',
                'mammothScriptUrl' => 'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js',
                'locationLabels' => [
                    'dubai' => __('Dubai', 'senna-finance'),
                    'abu_dhabi' => __('Abu Dhabi', 'senna-finance'),
                    'riyadh' => __('Riyadh', 'senna-finance'),
                    'doha' => __('Doha', 'senna-finance'),
                ],
                'roleInterestMap' => [
                    'analyst_associate' => ['analyst', 'associate'],
                    'manager_director' => ['vp', 'director'],
                    'c_suite' => ['c_level'],
                ],
                'strings' => [
                    'saving' => __('Saving your preferences…', 'senna-finance'),
                    'saveError' => __('We could not save your onboarding right now.', 'senna-finance'),
                    'cvParseError' => __('We could not read that file yet. Please upload a PDF, DOCX, DOC, or TXT resume.', 'senna-finance'),
                    'cvSaving' => __('Saving your CV…', 'senna-finance'),
                    'cvSaved' => __('CV saved. MENA Careers will use it to tailor your feed.', 'senna-finance'),
                    'cvEmpty' => __('Choose a CV file first.', 'senna-finance'),
                    'autocompleteLoading' => __('Searching MENA Careers…', 'senna-finance'),
                    'autocompleteEmpty' => __('No matching jobs found yet.', 'senna-finance'),
                ],
            ]);

            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $has_premium_access = $is_logged_in && $this->current_user_has_crm_editorial_paid_membership_access();
            $saved_tracker_slugs = $this->get_crm_editorial_community_saved_tracker_slugs($user_id);
            $posts_limit = max(48, min(80, (int) $atts['posts_limit']));
            $groups_limit = max(6, min(8, (int) $atts['groups_limit']));
            $news_limit = max(1, min(10, (int) $atts['news_limit']));
            $events_limit = max(1, min(8, (int) $atts['events_limit']));
            $newsletters_limit = max(1, min(6, (int) $atts['newsletters_limit']));
            $requested_tab = sanitize_key((string) wp_unslash($_GET['community_tab'] ?? ''));
            $active_tab = $requested_tab !== '' ? $requested_tab : sanitize_key((string) $atts['active_tab']);
            if (!in_array($active_tab, ['posts', 'network', 'templates', 'early_bird', 'saved_trackers'], true)) {
                $active_tab = 'posts';
            }
            if ($active_tab === 'early_bird' || $active_tab === 'saved_trackers') {
                $posts_limit = 40;
            }

            $raw_context_post_id = absint((int) ($atts['post_id'] ?? 0));
            $context_jobs_post_id = $this->resolve_current_crm_editorial_community_jobs_post_id($raw_context_post_id);
            $context_crm_post_id = ($raw_context_post_id > 0 && get_post_type($raw_context_post_id) === 'jobs')
                ? 0
                : $this->resolve_current_crm_post_id_without_random_fallback($raw_context_post_id);
            if ($context_crm_post_id <= 0 && $context_jobs_post_id > 0) {
                $context_crm_post_id = absint((int) get_post_meta($context_jobs_post_id, '_crm_post_id', true));
            }
            if ($context_jobs_post_id <= 0 && $context_crm_post_id > 0) {
                $context_jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($context_crm_post_id);
            }
            $context_group_slug = '';
            if ($context_crm_post_id > 0) {
                $context_group_slugs = $this->get_crm_reddit_group_slugs_for_post($context_crm_post_id);
                $context_group_slug = sanitize_title((string) ($context_group_slugs[0] ?? ''));
            }
            $initial_selected_group = $context_group_slug;
            $initial_feed_filters = [];
            if ($active_tab === 'saved_trackers') {
                $initial_selected_group = '';
            }

            $initial_feed_payload = $this->get_crm_editorial_community_feed_items($posts_limit, $user_id, 0, $initial_selected_group, [], $initial_feed_filters);
            $feed_payload = $initial_feed_payload;
            $feed_items = (array) ($feed_payload['items'] ?? []);
            $feed_has_more = !empty($feed_payload['has_more']);
            $context_feed_item = $this->get_crm_editorial_community_context_feed_item($context_crm_post_id, $context_jobs_post_id);
            if (!empty($context_feed_item)) {
                $feed_items = $this->remove_crm_editorial_community_duplicate_feed_item($feed_items, $context_feed_item);
            }
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            $group_model = new SFFC_CRM_Post_Group();
            $post_groups = $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => true,
            ]);
            $post_groups = (array) $post_groups;
            $tracker_filter_groups = array_values(array_filter($post_groups, static function ($group) {
                return (int) ($group['post_count'] ?? 0) > 0;
            }));
            $brand_location_label = __('Middle East', 'senna-finance');
            $has_explicit_tracker_context = $context_crm_post_id > 0 || $context_group_slug !== '';
            if ($has_explicit_tracker_context) {
                $context_brand_location_label = $this->get_crm_editorial_community_brand_location_label($context_crm_post_id, $context_group_slug, $post_groups, $feed_items);
                if ($context_brand_location_label !== '' && $this->get_crm_editorial_community_middle_east_location_label($context_brand_location_label) !== '') {
                    $brand_location_label = $context_brand_location_label;
                    $location_scoped_post_groups = $this->filter_crm_editorial_community_post_groups_by_location($post_groups, $brand_location_label);
                    if (!empty($location_scoped_post_groups)) {
                        $post_groups = $location_scoped_post_groups;
                    }
                }
            }
            $post_groups = $this->filter_crm_editorial_community_post_groups_for_middle_east($post_groups);
            $post_groups = array_values(array_filter($post_groups, static function ($group) {
                return (int) ($group['post_count'] ?? 0) > 0;
            }));
            $premium_tracker_slugs = array_values(array_filter(array_map(
                static function ($group) {
                    return !empty($group['is_premium']) ? sanitize_title((string) ($group['slug'] ?? '')) : '';
                },
                $tracker_filter_groups
            )));
            if ($active_tab === 'saved_trackers' && $has_premium_access && !empty($premium_tracker_slugs)) {
                $initial_feed_filters['trackers'] = implode('|', $premium_tracker_slugs);
                $feed_payload = $this->get_crm_editorial_community_feed_items($posts_limit, $user_id, 0, '', [], $initial_feed_filters);
                $feed_items = (array) ($feed_payload['items'] ?? []);
                $feed_has_more = !empty($feed_payload['has_more']);
                if (!empty($context_feed_item)) {
                    $feed_items = $this->remove_crm_editorial_community_duplicate_feed_item($feed_items, $context_feed_item);
                }
            }
            if (!$has_premium_access && !empty($context_feed_item) && $this->is_crm_editorial_community_item_in_premium_tracker($context_feed_item)) {
                $context_feed_item = [];
            }
            $default_tracker_post_groups = $post_groups;
            $post_groups = array_slice($post_groups, 0, $groups_limit);
            $community_group_filters = array_values(array_filter(array_map(
                static function ($group) {
                    $name = trim((string) ($group['name'] ?? ''));
                    $slug = sanitize_title((string) ($group['slug'] ?? ''));
                    if ($name === '' || $slug === '') {
                        return null;
                    }

                    return [
                        'name' => $name,
                        'slug' => $slug,
                        'count' => (int) ($group['post_count'] ?? 0),
                    ];
                },
                $post_groups
            )));
            $job_preferences = ((int) $user_id > 0 && function_exists('sffc_crm_get_job_preferences'))
