                'London' => 'London',
                'Singapore' => 'Singapore',
            ];
            $seniority_filter_options = [];
            $qualification_filter_options = [];
            $company_filter_options = [];
            $sector_filter_options = [];
            $work_type_filter_options = [];
            foreach ($feed_items as $feed_item) {
                $feed_item = (array) $feed_item;
                $location_value = $this->get_crm_editorial_community_location_filter_label((string) ($feed_item['location'] ?? ''));
                $seniority_value = $this->normalize_crm_editorial_community_seniority_filter_value((string) ($feed_item['seniority'] ?? ''));
                $qualifications = $this->extract_crm_editorial_community_qualifications($feed_item);
                $company_value = trim((string) ($feed_item['company'] ?? ''));
                $sector_value = $this->normalize_crm_editorial_community_sector_filter_value((string) ($feed_item['sector'] ?? ''));
                $work_type_values = $this->extract_crm_editorial_community_work_type_filters($feed_item);
                if ($location_value !== '') {
                    $location_filter_options[$location_value] = $location_value;
                }
                if ($seniority_value !== '') {
                    $seniority_filter_options[$seniority_value] = $this->get_crm_editorial_community_seniority_filter_label($seniority_value);
                }
                if ($company_value !== '') {
                    $company_filter_options[sanitize_title($company_value)] = $company_value;
                }
                if ($sector_value !== '') {
                    $sector_filter_options[$sector_value] = $this->get_crm_editorial_community_sector_filter_label($sector_value);
                }
                foreach ($work_type_values as $work_type_value) {
                    $work_type_filter_options[$work_type_value] = $this->get_crm_editorial_community_work_type_filter_label($work_type_value);
