            ksort($qualification_filter_options, SORT_NATURAL | SORT_FLAG_CASE);
            asort($company_filter_options, SORT_NATURAL | SORT_FLAG_CASE);
            asort($sector_filter_options, SORT_NATURAL | SORT_FLAG_CASE);
            asort($work_type_filter_options, SORT_NATURAL | SORT_FLAG_CASE);

            $default_location_filter = 'all';
