            }
            if ($default_seniority_filter === 'all') {
                foreach ((array) ($job_preferences['target_seniority'] ?? []) as $saved_seniority) {
                    $normalized_default_seniority = $this->normalize_crm_editorial_community_seniority_filter_value((string) $saved_seniority);
                    if ($normalized_default_seniority !== '' && isset($seniority_filter_options[$normalized_default_seniority])) {
                        $default_seniority_filter = $normalized_default_seniority;
