                'posted_date' => 'all',
                'company' => 'all',
                'sector' => 'all',
                'work_type' => 'all',
                'match_rank' => $default_match_filter,
            ];
            $has_default_feed_filters = $default_location_filter !== 'all'
                || $default_seniority_filter !== 'all'
                || $default_qualification_filter !== 'all'
                || $default_match_filter !== 'all';

            if ($has_default_feed_filters) {
                $filtered_feed_payload = $this->get_crm_editorial_community_feed_items($posts_limit, $user_id, 0, $initial_selected_group, [], $default_feed_filters);
                $filtered_feed_items = (array) ($filtered_feed_payload['items'] ?? []);

                if (!empty($filtered_feed_items)) {
                    $feed_payload = $filtered_feed_payload;
                    $feed_items = $filtered_feed_items;
                    $feed_has_more = !empty($filtered_feed_payload['has_more']);
                } elseif ($default_match_filter !== 'all') {
                    $feed_payload = $filtered_feed_payload;
                    $feed_items = [];
                    $feed_has_more = false;
                } else {
