        private function should_show_crm_editorial_community_onboarding($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return false;
            }

            if ($this->current_user_has_crm_editorial_paid_membership_access($user_id)) {
                return false;
            }

            return get_user_meta($user_id, 'sffc_crm_editorial_community_onboarding_seen', true) !== '1';
        }

        private function normalize_crm_editorial_community_feed_filters(array $filters = [])
        {
            $search = sanitize_text_field((string) ($filters['search'] ?? ''));
            $location = (string) ($filters['location'] ?? 'all');
            $seniority = (string) ($filters['seniority'] ?? 'all');
            $qualification = (string) ($filters['qualification'] ?? 'all');
            $recency = sanitize_key((string) ($filters['recency'] ?? 'all'));
            $posted_date = sanitize_key((string) ($filters['posted_date'] ?? 'all'));
            $company = sanitize_title((string) ($filters['company'] ?? 'all'));
            $sector = sanitize_title((string) ($filters['sector'] ?? 'all'));
            $work_type = sanitize_key((string) ($filters['work_type'] ?? 'all'));
            $match_rank = sanitize_key((string) ($filters['match_rank'] ?? ($filters['match'] ?? 'all')));
            $trackers = $filters['trackers'] ?? [];

            $location = $location === 'all' ? 'all' : $this->normalize_crm_editorial_community_location_label($location);
            $seniority = $seniority === 'all' ? 'all' : $this->normalize_crm_editorial_community_seniority_filter_value($seniority);
            $qualification = $qualification === 'all' ? 'all' : $this->normalize_crm_editorial_community_qualification_label($qualification);
            $recency = 'all';
            if (!in_array($posted_date, ['all', 'past_24_hours', 'past_48_hours', 'past_7_days', 'past_14_days', 'past_30_days'], true)) {
                $posted_date = 'all';
            }
            if ($company === '') {
                $company = 'all';
            }
            if ($sector === '') {
                $sector = 'all';
            }
            if (!in_array($work_type, ['all', 'remote', 'hybrid', 'onsite', 'full_time', 'contract', 'internship', 'graduate'], true)) {
                $work_type = 'all';
            }
            if (!in_array($match_rank, ['all', 'qualified', 'consider', 'mismatch'], true)) {
                $match_rank = 'all';
            }

            if (!is_array($trackers)) {
                $trackers = preg_split('/[\s,|]+/', (string) $trackers) ?: [];
            }
            $trackers = array_values(array_unique(array_filter(array_map('sanitize_title', $trackers))));

            return [
                'search' => $search,
                'location' => $location !== '' ? $location : 'all',
                'seniority' => $seniority !== '' ? $seniority : 'all',
                'qualification' => $qualification !== '' ? $qualification : 'all',
                'recency' => $recency,
                'posted_date' => $posted_date,
                'company' => $company,
                'sector' => $sector,
                'work_type' => $work_type,
                'match_rank' => $match_rank,
                'trackers' => $trackers,
            ];
        }

        private function build_crm_editorial_community_search_index(array $item)
        {
            $location = $this->normalize_crm_editorial_community_location_label((string) ($item['location'] ?? ''));
            $qualifications = $this->extract_crm_editorial_community_qualifications($item);

            return strtolower(implode(' ', array_filter([
                (string) ($item['role_title'] ?? ''),
                (string) ($item['company'] ?? ''),
                (string) ($item['recruiter_name'] ?? ''),
                (string) ($item['recruiter_title'] ?? ''),
                $location,
                (string) ($item['sector'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                (string) ($item['salary_text'] ?? ''),
                (string) ($item['content'] ?? ''),
                (string) ($item['description_html'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
                implode(' ', $qualifications),
            ])));
        }

        private function does_crm_editorial_community_item_match_filters(array $item, array $filters = [])
        {
            $filters = $this->normalize_crm_editorial_community_feed_filters($filters);

            if (($filters['location'] ?? 'all') !== 'all') {
                $item_location = $this->normalize_crm_editorial_community_location_label((string) ($item['location'] ?? ''));
                if (
                    $item_location === ''
                    || (stripos($item_location, (string) $filters['location']) === false
                        && stripos((string) $filters['location'], $item_location) === false)
                ) {
                    return false;
                }
            }

            if (($filters['seniority'] ?? 'all') !== 'all') {
                $item_seniority = $this->normalize_crm_editorial_community_seniority_filter_value((string) ($item['seniority'] ?? ''));
                if ($item_seniority === '' || $item_seniority !== (string) $filters['seniority']) {
                    return false;
                }
            }

            if (($filters['qualification'] ?? 'all') !== 'all') {
                $item_qualifications = $this->extract_crm_editorial_community_qualifications($item);
                if (!in_array((string) $filters['qualification'], $item_qualifications, true)) {
                    return false;
                }
            }

            if (($filters['posted_date'] ?? 'all') !== 'all') {
                if (!$this->does_crm_editorial_community_item_match_posted_date_filter($item, (string) $filters['posted_date'])) {
                    return false;
                }
            }

            if (($filters['company'] ?? 'all') !== 'all') {
                if (sanitize_title((string) ($item['company'] ?? '')) !== (string) $filters['company']) {
                    return false;
                }
            }

            if (($filters['sector'] ?? 'all') !== 'all') {
                $item_sector = $this->normalize_crm_editorial_community_sector_filter_value((string) ($item['sector'] ?? ''));
                if ($item_sector === '' || $item_sector !== (string) $filters['sector']) {
                    return false;
                }
            }

            if (($filters['work_type'] ?? 'all') !== 'all') {
                $item_work_types = $this->extract_crm_editorial_community_work_type_filters($item);
                if (!in_array((string) $filters['work_type'], $item_work_types, true)) {
                    return false;
                }
            }

            if (($filters['match_rank'] ?? 'all') !== 'all') {
                $match_payload = $this->get_crm_editorial_community_item_match_payload($item, get_current_user_id());
                if ((string) ($match_payload['rank'] ?? 'consider') !== (string) $filters['match_rank']) {
                    return false;
                }
            }

            if (($filters['recency'] ?? 'all') === 'early_bird') {
                if (!$this->is_crm_editorial_community_item_early_bird_eligible($item)) {
                    return false;
                }
            }

            $selected_trackers = array_values(array_filter((array) ($filters['trackers'] ?? [])));
            if (!empty($selected_trackers)) {
                $matched_slugs = array_values(array_unique(array_filter(array_map('sanitize_title', $this->get_cv_match_studio_mailbox_group_slugs($item)))));
                if (empty(array_intersect($selected_trackers, $matched_slugs))) {
                    return false;
                }
            }

            $search = trim((string) ($filters['search'] ?? ''));
            if ($search !== '') {
                $normalized_index = strtolower($this->build_crm_editorial_community_search_index($item));
                $normalized_search = strtolower(preg_replace('/\s+/', ' ', $search));
                $tokens = array_values(array_filter(explode(' ', $normalized_search)));

                if (
                    strpos($normalized_index, $normalized_search) === false
                    && array_filter($tokens, static function ($token) use ($normalized_index) {
                        return strpos($normalized_index, $token) === false;
                    })
                ) {
                    return false;
                }
            }

            return true;
        }

        private function get_crm_editorial_community_tracker_source_groups(array $feed_items = [], $limit = 80)
        {
            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }

            $group_model = new SFFC_CRM_Post_Group();
            $post_groups = (array) $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => true,
            ]);
            $post_groups = array_values(array_filter($post_groups, static function ($group) {
                return (int) ($group['post_count'] ?? 0) > 0;
            }));

            return array_slice($post_groups, 0, max(1, (int) $limit));
        }

        private function get_crm_editorial_community_premium_tracker_slugs()
        {
            static $premium_tracker_slugs = null;

            if (is_array($premium_tracker_slugs)) {
                return $premium_tracker_slugs;
            }

            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }

            $group_model = new SFFC_CRM_Post_Group();
            $post_groups = (array) $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => false,
            ]);

            $premium_tracker_slugs = array_values(array_unique(array_filter(array_map(
                static function ($group) {
                    return !empty($group['is_premium']) ? sanitize_title((string) ($group['slug'] ?? '')) : '';
                },
                $post_groups
            ))));

            return $premium_tracker_slugs;
        }

        private function is_crm_editorial_community_item_in_premium_tracker(array $item, array $premium_tracker_slugs = [])
        {
            $premium_tracker_slugs = !empty($premium_tracker_slugs)
                ? $premium_tracker_slugs
                : $this->get_crm_editorial_community_premium_tracker_slugs();
            $premium_tracker_slugs = array_values(array_unique(array_filter(array_map('sanitize_title', $premium_tracker_slugs))));
            if (empty($premium_tracker_slugs)) {
                return false;
            }

            $item_tracker_slugs = array_values(array_unique(array_filter(array_map(
                'sanitize_title',
                $this->get_cv_match_studio_mailbox_group_slugs($item)
            ))));

            return !empty(array_intersect($premium_tracker_slugs, $item_tracker_slugs));
        }

        private function filter_crm_editorial_community_feed_items_for_membership_access(array $feed_items, $user_id = 0)
        {
            if (empty($feed_items)) {
                return [];
            }

            if ($this->current_user_has_crm_editorial_paid_membership_access($user_id)) {
                return array_values($feed_items);
            }

            $premium_tracker_slugs = $this->get_crm_editorial_community_premium_tracker_slugs();
            if (empty($premium_tracker_slugs)) {
                return array_values($feed_items);
            }

            return array_values(array_filter($feed_items, function ($item) use ($premium_tracker_slugs) {
                return !$this->is_crm_editorial_community_item_in_premium_tracker((array) $item, $premium_tracker_slugs);
            }));
        }

        private function build_crm_editorial_community_tracker_feed_sections(array $feed_items, array $post_groups = [], $selected_group = '', array $selected_trackers = [])
        {
            $selected_group = sanitize_title((string) $selected_group);
            $selected_trackers = array_values(array_unique(array_filter(array_map('sanitize_title', $selected_trackers))));
            $source_groups = [];

            foreach ($post_groups as $group) {
                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                $name = trim((string) ($group['name'] ?? ''));
                if ($slug === '' || $name === '') {
                    continue;
                }
                if ($selected_group !== '' && $selected_group !== $slug) {
                    continue;
                }
                if (!empty($selected_trackers) && !in_array($slug, $selected_trackers, true)) {
                    continue;
                }

                $source_groups[$slug] = [
                    'id' => (int) ($group['id'] ?? 0),
                    'slug' => $slug,
                    'name' => $name,
                    'description' => trim(wp_strip_all_tags((string) ($group['description'] ?? ''))),
                    'post_count' => (int) ($group['post_count'] ?? 0),
                    'items' => [],
                ];
            }

            $assigned_item_keys = [];
            foreach ($feed_items as $item) {
                $item = (array) $item;
                $item_id = (int) ($item['crm_post_id'] ?? $item['post_id'] ?? $item['wp_post_id'] ?? 0);
                $item_key = $item_id > 0
                    ? 'post-' . $item_id
                    : md5((string) wp_json_encode([
                        $item['role_title'] ?? '',
                        $item['company'] ?? '',
                        $item['location'] ?? '',
                    ]));
                $matched_slugs = array_values(array_unique(array_map('sanitize_title', $this->get_cv_match_studio_mailbox_group_slugs($item))));

                foreach ($matched_slugs as $matched_slug) {
                    if (!isset($source_groups[$matched_slug]) || isset($assigned_item_keys[$item_key])) {
                        continue;
                    }
                    $source_groups[$matched_slug]['items'][] = $item;
                    $assigned_item_keys[$item_key] = true;
                    break;
                }
            }

            $sections = array_values(array_filter($source_groups, static function ($group) {
                return !empty($group['items']);
            }));

            if (empty($sections) && !empty($feed_items) && empty($selected_trackers)) {
                $sections[] = [
                    'id' => 0,
                    'slug' => 'middle-east-live-roles',
                    'name' => __('Private Equity Jobs in the Middle East', 'senna-finance'),
                    'description' => __('Private equity opportunities across Dubai, Abu Dhabi, Riyadh, Doha, London, and Singapore from the live jobs feed.', 'senna-finance'),
                    'post_count' => count($feed_items),
                    'items' => array_values($feed_items),
                ];
            }

            return $sections;
        }

        private function build_crm_editorial_community_default_tracker_feed_sections(array $post_groups = [], $user_id = 0, $items_per_tracker = 8, $sections_limit = 6, array $filters = [])
        {
            $items_per_tracker = max(1, min(12, (int) $items_per_tracker));
            $sections_limit = max(1, min(8, (int) $sections_limit));
            $sections = [];
            $seen_slugs = [];

            foreach ($post_groups as $group) {
                if (count($sections) >= $sections_limit) {
                    break;
                }

                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                $name = trim((string) ($group['name'] ?? ''));
                if ($slug === '' || $name === '' || isset($seen_slugs[$slug])) {
                    continue;
                }

                $seen_slugs[$slug] = true;
                $payload = $this->get_crm_editorial_community_feed_items($items_per_tracker, (int) $user_id, 0, $slug, [], $filters);
                $items = array_values(array_filter((array) ($payload['items'] ?? [])));
                if (empty($items)) {
                    continue;
                }

                $sections[] = [
                    'id' => (int) ($group['id'] ?? 0),
                    'slug' => $slug,
                    'name' => $name,
                    'description' => trim(wp_strip_all_tags((string) ($group['description'] ?? ''))),
                    'post_count' => max((int) ($group['post_count'] ?? 0), count($items)),
                    'items' => $items,
                    'has_more' => !empty($payload['has_more']),
                ];
            }

            return $sections;
        }

        private function build_crm_editorial_community_qualified_tracker_section(array $feed_items)
        {
            $items = array_values($feed_items);

            return [
                'id' => 0,
                'slug' => 'your-qualified-jobs',
                'name' => __('Qualified Private Equity Jobs', 'senna-finance'),
                'description' => __('Private equity roles combined from every tracker based on your saved CV and role signals.', 'senna-finance'),
                'post_count' => count($items),
                'items' => $items,
            ];
        }

        private function build_crm_editorial_community_past_24_hours_tracker_section(array $feed_items)
        {
            $cutoff = current_time('timestamp') - DAY_IN_SECONDS;
            $items = array_values(array_filter($feed_items, function ($item) use ($cutoff) {
                $posted_timestamp = $this->get_crm_editorial_community_item_posted_timestamp((array) $item);
                return $posted_timestamp > 0 && $posted_timestamp >= $cutoff;
            }));

            if (empty($items)) {
                return [];
            }

            $items = $this->sort_crm_editorial_community_feed_items_by_recent($items);

            return [
                'id' => 0,
                'slug' => 'posted-in-the-past-24-hours',
                'name' => __('Private Equity Jobs Posted in the Past 24 Hours', 'senna-finance'),
                'description' => __('Fresh private equity roles from every tracker posted within the past 24 hours.', 'senna-finance'),
                'post_count' => count($items),
                'items' => $items,
            ];
        }

        private function format_crm_editorial_community_tracker_cta_count($count)
        {
            $count = max(0, (int) $count);

            if ($count >= 100) {
                return __('100+ Jobs', 'senna-finance');
            }

            return sprintf(_n('%d Job', '%d Jobs', max(1, $count), 'senna-finance'), max(1, $count));
        }

