        private function get_crm_editorial_community_tracker_locked_preview_items($tracker_slug, array $exclude_post_ids = [], $limit = 3, array $fallback_items = [])
        {
            $tracker_slug = sanitize_title((string) $tracker_slug);
            $limit = max(1, min(3, (int) $limit));
            if ($tracker_slug === '') {
                return array_slice(array_values($fallback_items), 0, $limit);
            }

            $exclude_post_ids = array_values(array_unique(array_filter(array_map('absint', $exclude_post_ids))));
            $preview_items = [];
            static $tracker_preview_cache = [];

            if (class_exists('SFFC_CRM_Post') || file_exists(SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php')) {
                if (!class_exists('SFFC_CRM_Post')) {
                    require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
                }

                if (!isset($tracker_preview_cache[$tracker_slug])) {
                    $post_model = new SFFC_CRM_Post();
                    $tracker_preview_cache[$tracker_slug] = (array) $post_model->get_feed_by_groups([$tracker_slug], [
                        'page' => 1,
                        'per_page' => 12,
                        'orderby' => 'posted_at',
                        'order' => 'DESC',
                        'user_id' => get_current_user_id(),
                    ]);
                }

                $candidate_items = (array) $tracker_preview_cache[$tracker_slug];

                foreach ($candidate_items as $candidate_item) {
                    $candidate_item = (array) $candidate_item;
                    $candidate_id = (int) ($candidate_item['crm_post_id'] ?? $candidate_item['id'] ?? $candidate_item['post_id'] ?? $candidate_item['wp_post_id'] ?? 0);
                    if ($candidate_id > 0 && in_array($candidate_id, $exclude_post_ids, true)) {
                        continue;
                    }

                    $candidate_item['crm_post_id'] = $candidate_id;
                    $candidate_item['company'] = trim((string) ($candidate_item['company'] ?? $candidate_item['company_name'] ?? ''));
                    $candidate_item['company_logo'] = !empty($candidate_item['company_logo']) ? $this->normalize_company_logo_url((string) $candidate_item['company_logo']) : '';
                    $preview_items[] = $candidate_item;

                    if (count($preview_items) >= $limit) {
                        break;
                    }
                }
            }

            if (count($preview_items) < $limit && !empty($fallback_items)) {
                foreach ($fallback_items as $fallback_item) {
                    $fallback_item = (array) $fallback_item;
                    $fallback_id = (int) ($fallback_item['crm_post_id'] ?? $fallback_item['id'] ?? $fallback_item['post_id'] ?? $fallback_item['wp_post_id'] ?? 0);
                    if ($fallback_id > 0 && in_array($fallback_id, $exclude_post_ids, true)) {
                        continue;
                    }
                    $preview_items[] = $fallback_item;
                    if (count($preview_items) >= $limit) {
                        break;
                    }
                }
            }

            return array_slice($preview_items, 0, $limit);
        }

        private function resolve_current_crm_editorial_community_jobs_post_id($raw_post_id = 0)
        {
            $raw_post_id = absint($raw_post_id);
            if ($raw_post_id > 0 && get_post_type($raw_post_id) === 'jobs') {
                return $raw_post_id;
            }

            $queried_object = get_queried_object();
            if ($queried_object instanceof WP_Post) {
                if ($queried_object->post_type === 'jobs') {
                    return (int) $queried_object->ID;
                }

                if ($queried_object->post_type === 'sffc_recruiter_post') {
                    $linked_crm_post_id = absint((int) get_post_meta($queried_object->ID, '_crm_post_id', true));
                    if ($linked_crm_post_id > 0) {
                        $linked_jobs_post_id = $this->find_jobs_post_id_by_crm_post_id($linked_crm_post_id);
                        if ($linked_jobs_post_id > 0) {
                            return $linked_jobs_post_id;
                        }
                    }
                }
            }

            $current_post_id = get_the_ID();
            if ($current_post_id > 0 && get_post_type($current_post_id) === 'jobs') {
                return (int) $current_post_id;
            }

            return 0;
        }

        private function get_crm_editorial_community_context_feed_item($context_crm_post_id = 0, $context_jobs_post_id = 0)
        {
            $context_crm_post_id = absint($context_crm_post_id);
            $context_jobs_post_id = absint($context_jobs_post_id);
            $item = [];

            if ($context_jobs_post_id > 0) {
                $item = (array) $this->get_cached_cv_match_job_posts_item($context_jobs_post_id);
            }

            if (empty($item) && $context_crm_post_id > 0) {
                $item = (array) $this->get_crm_editorial_community_feed_item_by_id($context_crm_post_id);
            }

            if (empty($item)) {
                return [];
            }

            if (empty($item['crm_post_id']) && $context_crm_post_id > 0) {
                $item['crm_post_id'] = $context_crm_post_id;
            }
            if (empty($item['wp_post_id']) && $context_jobs_post_id > 0) {
                $item['wp_post_id'] = $context_jobs_post_id;
            }
            if (empty($item['post_id']) && $context_jobs_post_id > 0) {
                $item['post_id'] = $context_jobs_post_id;
                $item['source'] = 'jobs';
            }

            return $item;
        }

        private function is_same_crm_editorial_community_feed_item(array $candidate, array $target)
        {
            $candidate_crm_id = (int) ($candidate['crm_post_id'] ?? 0);
            $target_crm_id = (int) ($target['crm_post_id'] ?? 0);
            if ($candidate_crm_id > 0 && $target_crm_id > 0 && $candidate_crm_id === $target_crm_id) {
                return true;
            }

            $candidate_wp_id = (int) ($candidate['wp_post_id'] ?? 0);
            $target_wp_id = (int) ($target['wp_post_id'] ?? 0);
            if ($candidate_wp_id > 0 && $target_wp_id > 0 && $candidate_wp_id === $target_wp_id) {
                return true;
            }

            $candidate_jobs_id = (string) ($candidate['source'] ?? '') === 'jobs' ? (int) ($candidate['post_id'] ?? 0) : 0;
            $target_jobs_id = (string) ($target['source'] ?? '') === 'jobs' ? (int) ($target['post_id'] ?? 0) : 0;
            return $candidate_jobs_id > 0 && $target_jobs_id > 0 && $candidate_jobs_id === $target_jobs_id;
        }

        private function remove_crm_editorial_community_duplicate_feed_item(array $feed_items, array $target_item)
        {
            if (empty($target_item)) {
                return $feed_items;
            }

            return array_values(array_filter($feed_items, function ($item) use ($target_item) {
                return !$this->is_same_crm_editorial_community_feed_item((array) $item, $target_item);
            }));
        }

        private function get_crm_editorial_community_item_tracker_context(array $item, array $post_groups = [])
        {
            $group_slug = sanitize_title((string) ($item['group_slug'] ?? ''));
            $group_name = trim((string) ($item['group_name'] ?? ''));
            $group_id = 0;

            if ($group_slug !== '') {
                foreach ($post_groups as $group) {
                    if (sanitize_title((string) ($group['slug'] ?? '')) === $group_slug) {
                        $group_id = (int) ($group['id'] ?? 0);
                        if ($group_name === '') {
                            $group_name = trim((string) ($group['name'] ?? ''));
                        }
                        $group_count = (int) ($group['post_count'] ?? 0);
                        break;
                    }
                }
            }

            if (($group_slug === '' || $group_name === '') && !empty($item['crm_post_id'])) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
                $group_model = new SFFC_CRM_Post_Group();
                $groups = (array) $group_model->get_groups_for_post((int) $item['crm_post_id']);
                $primary_group = (array) ($groups[0] ?? []);
                if (!empty($primary_group)) {
                    $group_id = (int) ($primary_group['id'] ?? $group_id);
                    $group_slug = sanitize_title((string) ($primary_group['slug'] ?? $group_slug));
                    $group_name = trim((string) ($primary_group['name'] ?? $group_name));
                    $group_count = (int) ($primary_group['post_count'] ?? $group_count ?? 0);
                }
            }

            return [
                'id' => $group_id,
                'slug' => $group_slug,
                'name' => $group_name !== '' ? $group_name : __('Private equity roles', 'senna-finance'),
                'description' => '',
                'post_count' => (int) ($group_count ?? 0),
            ];
        }

