        private function render_crm_editorial_community_linkedin_detail_markup(array $feed_items, array $context_feed_item = [], $select_first = true)
        {
            $detail_items = $this->get_crm_editorial_community_linkedin_detail_items($feed_items, $context_feed_item);
            if (empty($detail_items)) {
                return '<article class="sffc-crm-linkedin-jobs__empty-detail"><strong>' . esc_html__('Select a role', 'senna-finance') . '</strong><span>' . esc_html__('Choose a role from the results to review the full details.', 'senna-finance') . '</span></article>';
            }

            $selected_post_id = $select_first ? (int) ($detail_items[0]['id'] ?? 0) : 0;
            ob_start();
            foreach ($detail_items as $detail_item) {
                echo $this->render_crm_linkedin_jobs_detail_panel((array) $detail_item, $selected_post_id); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
            }

            return (string) ob_get_clean();
        }

        private function get_crm_editorial_community_linkedin_detail_items(array $feed_items, array $context_feed_item = [])
        {
            $items = [];
            $seen_ids = [];
            $source_items = $feed_items;
            if (!empty($context_feed_item)) {
                array_unshift($source_items, $context_feed_item);
            }

            foreach ($source_items as $source_item) {
                if (!is_array($source_item)) {
                    continue;
                }

                $detail_item = $this->normalize_crm_editorial_community_linkedin_detail_item($source_item);
                $detail_id = (int) ($detail_item['id'] ?? 0);
                if ($detail_id <= 0 || isset($seen_ids[$detail_id])) {
                    continue;
                }

                $seen_ids[$detail_id] = true;
                $items[] = $detail_item;
            }

            return $items;
        }

        private function normalize_crm_editorial_community_linkedin_detail_item(array $item)
        {
            $post_id = (int) ($item['id'] ?? $item['crm_post_id'] ?? $item['post_id'] ?? 0);
            $item['id'] = $post_id;
            $item['crm_post_id'] = $post_id;

            if (empty($item['content']) && !empty($item['content_snippet'])) {
                $item['content'] = '<p>' . esc_html(trim((string) $item['content_snippet'])) . '</p>';
            }

            if (empty($item['application_url'])) {
                foreach (['apply_url', 'source_url', 'view_url'] as $url_key) {
                    $fallback_url = trim((string) ($item[$url_key] ?? ''));
                    if ($fallback_url !== '') {
                        $item['application_url'] = $fallback_url;
                        break;
                    }
                }
            }

            if (empty($item['posted_at']) && !empty($item['posted_timestamp'])) {
                $item['posted_at'] = gmdate('Y-m-d H:i:s', (int) $item['posted_timestamp']);
            }

            return $item;
        }

        private function get_crm_editorial_community_feed_items($limit, $user_id, $offset = 0, $selected_group = '', array $exclude_crm_ids = [], array $filters = [])
        {
            $limit = max(1, min(120, (int) $limit));
            $offset = max(0, (int) $offset);
            $selected_group = sanitize_title((string) $selected_group);
            $filters = $this->normalize_crm_editorial_community_feed_filters($filters);
            $has_active_filters = $selected_group !== ''
                || ($filters['search'] ?? '') !== ''
                || ($filters['location'] ?? 'all') !== 'all'
                || ($filters['seniority'] ?? 'all') !== 'all'
                || ($filters['qualification'] ?? 'all') !== 'all'
                || ($filters['posted_date'] ?? 'all') !== 'all'
                || ($filters['company'] ?? 'all') !== 'all'
                || ($filters['sector'] ?? 'all') !== 'all'
                || ($filters['work_type'] ?? 'all') !== 'all'
                || ($filters['match_rank'] ?? 'all') !== 'all'
                || ($filters['recency'] ?? 'all') !== 'all'
                || !empty($filters['trackers'] ?? []);
            $window_size = $offset + $limit + 1;
            $fetch_limit = max($window_size * 3, 400);
            if ($has_active_filters) {
                $fetch_limit = 5000;
            }
            $fetch_limit = min($fetch_limit, 5000);
            $exclude_crm_ids = array_values(array_filter(array_map('absint', $exclude_crm_ids)));
            $feed_items = $this->get_crm_editorial_community_feed_source_items($fetch_limit, (int) $user_id, $selected_group, $exclude_crm_ids);

            if ((int) $user_id > 0 && function_exists('sffc_crm_get_job_preferences')) {
                $preferences = (array) sffc_crm_get_job_preferences((int) $user_id);
                $feed_items = $this->personalize_crm_editorial_community_feed_items($feed_items, $preferences);
            }

            if ($has_active_filters) {
                $feed_items = array_values(array_filter($feed_items, function ($item) use ($filters) {
                    return $this->does_crm_editorial_community_item_match_filters((array) $item, $filters);
                }));
            }

            $feed_items = $this->filter_crm_editorial_community_feed_items_for_membership_access($feed_items, $user_id);

            $feed_items = $this->sort_crm_editorial_community_feed_items_by_recent($feed_items);

            return [
                'items' => array_slice($feed_items, $offset, $limit),
                'has_more' => count($feed_items) > ($offset + $limit),
            ];
        }

        private function get_crm_editorial_community_feed_source_items($fetch_limit, $user_id, $selected_group = '', array $exclude_crm_ids = [])
        {
            $fetch_limit = max(1, min(5000, (int) $fetch_limit));
            $user_id = (int) $user_id;
            $selected_group = sanitize_title((string) $selected_group);
            $exclude_crm_ids = array_values(array_filter(array_map('absint', $exclude_crm_ids)));

            if (!empty($exclude_crm_ids)) {
                $raw_posts = (array) $this->get_crm_reddit_feed_posts_batch($fetch_limit, $user_id, $selected_group, '', $exclude_crm_ids);
                $raw_posts = $this->filter_crm_editorial_community_posts_for_middle_east($raw_posts);
                return array_map(function ($feed_post) {
                    return $this->build_crm_reddit_dashboard_crm_item((array) $feed_post);
                }, $raw_posts);
            }

            $cache_key = 'sffc_crm_editorial_feed_source_' . md5(implode('|', [
                'v5',
                (string) $fetch_limit,
                (string) $user_id,
                $selected_group,
            ]));
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            $raw_posts = (array) $this->get_crm_reddit_feed_posts_batch($fetch_limit, $user_id, $selected_group, '', []);
            $raw_posts = $this->filter_crm_editorial_community_posts_for_middle_east($raw_posts);
            $items = array_map(function ($feed_post) {
                return $this->build_crm_reddit_dashboard_crm_item((array) $feed_post);
            }, $raw_posts);

            set_transient($cache_key, $items, 5 * MINUTE_IN_SECONDS);

            return $items;
        }

        private function get_crm_editorial_community_feed_item_by_id($crm_post_id)
        {
            global $wpdb;

            $crm_post_id = absint($crm_post_id);
            if ($crm_post_id <= 0) {
                return [];
            }

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $early_bird_exclusion_select = $this->get_crm_posts_early_bird_exclusion_select('p');

            $sql = "SELECT p.id, p.role_title, p.company, p.location, p.location_country,
                           p.salary_text, p.seniority, p.sector, p.content, p.content_snippet, p.posted_at,
                           p.is_remote, p.is_hybrid, p.application_url, p.wp_post_id, p.company_logo, p.keywords,
                           p.experience_years, p.is_featured, {$early_bird_exclusion_select},
                           COALESCE(NULLIF(p.company_logo, ''), r.default_company_logo) AS company_logo,
                           r.id as recruiter_id, r.name as recruiter_name, r.firm as recruiter_firm,
                           r.photo_url as recruiter_photo, r.title as recruiter_title,
                           r.email as recruiter_email, r.linkedin_url as recruiter_linkedin,
                           r.sectors as recruiter_specializations
                    FROM {$posts_table} p
                    LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id
                    WHERE p.id = %d
                      AND p.is_active = 1
                      AND p.admin_approved = 1
                      AND (p.post_status IS NULL OR p.post_status = 'open')
                    LIMIT 1";

            $row = $wpdb->get_row($wpdb->prepare($sql, $crm_post_id), ARRAY_A);
            return !empty($row) ? $this->build_crm_reddit_dashboard_crm_item((array) $row) : [];
        }

        private function sort_crm_editorial_community_feed_items_by_recent(array $items)
        {
            if (count($items) <= 1) {
                return $items;
            }

            usort($items, function ($left, $right) {
                $left_timestamp = $this->get_crm_editorial_community_item_posted_timestamp((array) $left);
                $right_timestamp = $this->get_crm_editorial_community_item_posted_timestamp((array) $right);

                if ($left_timestamp === $right_timestamp) {
                    return ((int) ($right['crm_post_id'] ?? $right['post_id'] ?? 0)) <=> ((int) ($left['crm_post_id'] ?? $left['post_id'] ?? 0));
                }

                return $right_timestamp <=> $left_timestamp;
            });

            return array_values($items);
        }

        private function get_crm_editorial_community_item_posted_timestamp(array $item)
        {
            $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);

            if ($posted_timestamp <= 0 && !empty($item['posted_at'])) {
                $posted_timestamp = (int) strtotime((string) $item['posted_at']);
            }

            return max(0, $posted_timestamp);
        }

        private function format_crm_editorial_community_item_posted_age($posted_timestamp)
        {
            $posted_timestamp = (int) $posted_timestamp;

            if ($posted_timestamp <= 0) {
                return __('Recently posted', 'senna-finance');
            }

            $age = max(0, current_time('timestamp') - $posted_timestamp);

            if ($age < MINUTE_IN_SECONDS) {
                return __('Just now', 'senna-finance');
            }

            if ($age < HOUR_IN_SECONDS) {
                $minutes = max(1, (int) floor($age / MINUTE_IN_SECONDS));
                return sprintf(_n('%d min ago', '%d mins ago', $minutes, 'senna-finance'), $minutes);
            }

            if ($age < DAY_IN_SECONDS) {
                $hours = max(1, (int) floor($age / HOUR_IN_SECONDS));
                return sprintf(_n('%d hour ago', '%d hours ago', $hours, 'senna-finance'), $hours);
            }

            if ($age < WEEK_IN_SECONDS) {
                $days = max(1, (int) floor($age / DAY_IN_SECONDS));
                return sprintf(_n('%d day ago', '%d days ago', $days, 'senna-finance'), $days);
            }

            if ($age < MONTH_IN_SECONDS) {
                $weeks = max(1, (int) floor($age / WEEK_IN_SECONDS));
                return sprintf(_n('%d week ago', '%d weeks ago', $weeks, 'senna-finance'), $weeks);
            }

            return '';
        }

        private function is_crm_editorial_community_item_early_bird_eligible(array $item)
        {
            return false;
        }

        private function personalize_crm_editorial_community_feed_items(array $items, array $preferences)
        {
            $target_locations = array_values(array_filter(array_map('sanitize_text_field', (array) ($preferences['target_locations'] ?? []))));
            $target_seniority = array_values(array_filter(array_map('sanitize_key', (array) ($preferences['target_seniority'] ?? []))));

            if (empty($target_locations) && empty($target_seniority)) {
                return $this->sort_crm_editorial_community_feed_items_by_recent($items);
            }

            $matched = [];
            $partial = [];
            $fallback = [];

            foreach ($items as $item) {
                $location_match = $this->does_crm_editorial_community_item_match_locations((array) $item, $target_locations);
                $seniority_match = $this->does_crm_editorial_community_item_match_seniority((array) $item, $target_seniority);

                $requires_location = !empty($target_locations);
                $requires_seniority = !empty($target_seniority);
                $is_full_match = (!$requires_location || $location_match) && (!$requires_seniority || $seniority_match);
                $is_partial_match = !$is_full_match && ($location_match || $seniority_match);

                $item['_community_location_match'] = $location_match;
                $item['_community_seniority_match'] = $seniority_match;

                if ($is_full_match) {
                    $matched[] = $item;
                } elseif ($is_partial_match) {
                    $partial[] = $item;
                } else {
                    $fallback[] = $item;
                }
            }

            $matched = $this->sort_crm_editorial_community_feed_items_by_recent($matched);
            $partial = $this->sort_crm_editorial_community_feed_items_by_recent($partial);
            $fallback = $this->sort_crm_editorial_community_feed_items_by_recent($fallback);

            $ordered = array_merge($matched, $partial);
            if (empty($ordered)) {
                return $this->sort_crm_editorial_community_feed_items_by_recent($items);
            }

            if (count($ordered) < count($items)) {
                $ordered = array_merge($ordered, $fallback);
            }

            return $ordered;
        }

        private function does_crm_editorial_community_item_match_locations(array $item, array $target_locations)
        {
            if (empty($target_locations)) {
                return false;
            }

            $item_location = strtolower(trim((string) ($item['location'] ?? '')));
            if ($item_location === '') {
                return false;
            }

            foreach ($target_locations as $target_location) {
                $needle = strtolower(trim((string) $target_location));
                if ($needle === '') {
                    continue;
                }

                if (strpos($item_location, $needle) !== false || strpos($needle, $item_location) !== false) {
                    return true;
                }
            }

            return false;
        }

        private function does_crm_editorial_community_item_match_seniority(array $item, array $target_seniority)
        {
            if (empty($target_seniority)) {
                return false;
            }

            $item_seniority = sanitize_key((string) ($item['seniority'] ?? ''));
            if ($item_seniority === '') {
                return false;
            }

            return in_array($item_seniority, $target_seniority, true);
        }

        public function ajax_crm_editorial_load_more()
        {
            check_ajax_referer('sffc_crm_editorial_load_more', 'nonce');

            $user_id = get_current_user_id();
            $guest_cv_token = sanitize_text_field((string) wp_unslash($_POST['guest_cv_token'] ?? ''));
            $this->crm_editorial_guest_match_profile = $this->get_crm_editorial_community_guest_match_profile($guest_cv_token);
            $offset = max(0, (int) wp_unslash($_POST['offset'] ?? 0));
            $batch_size = max(1, min(80, (int) wp_unslash($_POST['batch_size'] ?? 10)));
            $selected_group = sanitize_title((string) wp_unslash($_POST['group'] ?? ''));
            $exclude_crm_ids = array_map('absint', (array) wp_unslash($_POST['exclude_ids'] ?? []));
            $filters = [
                'search' => (string) wp_unslash($_POST['search'] ?? ''),
                'location' => (string) wp_unslash($_POST['location'] ?? 'all'),
                'seniority' => (string) wp_unslash($_POST['seniority'] ?? 'all'),
                'qualification' => (string) wp_unslash($_POST['qualification'] ?? 'all'),
                'recency' => (string) wp_unslash($_POST['recency'] ?? 'all'),
                'posted_date' => (string) wp_unslash($_POST['posted_date'] ?? 'all'),
                'company' => (string) wp_unslash($_POST['company'] ?? 'all'),
                'sector' => (string) wp_unslash($_POST['sector'] ?? 'all'),
                'work_type' => (string) wp_unslash($_POST['work_type'] ?? 'all'),
                'match_rank' => (string) wp_unslash($_POST['match_rank'] ?? 'all'),
                'trackers' => (string) wp_unslash($_POST['trackers'] ?? ''),
            ];
            if ($selected_group === 'all') {
                $selected_group = '';
            }
            if (trim((string) $filters['trackers']) !== '') {
                $selected_group = '';
            }

            $payload = $this->get_crm_editorial_community_feed_items($batch_size, $user_id, $offset, $selected_group, $exclude_crm_ids, $filters);
            $items = (array) ($payload['items'] ?? []);
            $normalized_filters = $this->normalize_crm_editorial_community_feed_filters($filters);
            $tracker_groups = $this->get_crm_editorial_community_tracker_source_groups($items);
            $tracker_sections = $this->build_crm_editorial_community_tracker_feed_sections($items, $tracker_groups, $selected_group, (array) ($normalized_filters['trackers'] ?? []));

            ob_start();
            $position = $offset;
            foreach ($tracker_sections as $tracker_section) {
                echo $this->render_crm_editorial_community_tracker_section((array) $tracker_section, $position, [
                    'saved_tracker_slugs' => $this->get_crm_editorial_community_saved_tracker_slugs($user_id),
                    'linkedin_cards' => true,
                    'linkedin_selected_post_id' => -1,
                ]); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
            }
            $html = (string) ob_get_clean();

            wp_send_json_success([
                'html' => $html,
                'detailHtml' => !empty($items) ? $this->render_crm_editorial_community_linkedin_detail_markup($items, [], false) : '',
                'count' => count($items),
                'nextOffset' => $offset + count($items),
                'hasMore' => !empty($payload['has_more']),
            ]);
        }

