        public function ajax_crm_editorial_filter_feed()
        {
            check_ajax_referer('sffc_crm_editorial_filter_feed', 'nonce');

            $user_id = get_current_user_id();
            $guest_cv_token = sanitize_text_field((string) wp_unslash($_POST['guest_cv_token'] ?? ''));
            $this->crm_editorial_guest_match_profile = $this->get_crm_editorial_community_guest_match_profile($guest_cv_token);
            $batch_size = max(1, min(120, (int) wp_unslash($_POST['batch_size'] ?? 80)));
            $selected_group = sanitize_title((string) wp_unslash($_POST['group'] ?? ''));
            if ($selected_group === 'all') {
                $selected_group = '';
            }

            $filters = [
                'search' => (string) wp_unslash($_POST['search'] ?? ''),
                'location' => (string) wp_unslash($_POST['location'] ?? 'all'),
                'seniority' => (string) wp_unslash($_POST['seniority'] ?? 'all'),
                'qualification' => (string) wp_unslash($_POST['qualification'] ?? 'all'),
                'recency' => (string) wp_unslash($_POST['recency'] ?? 'all'),
                'posted_date' => (string) wp_unslash($_POST['posted_date'] ?? 'all'),
                'company' => (string) wp_unslash($_POST['company'] ?? 'all'),
                'sector' => (string) wp_unslash($_POST['sector'] ?? 'all'),
                'work_type' => (string) wp_unslash($_POST['work_type'] ?? 'all'),
                'match_rank' => (string) wp_unslash($_POST['match_rank'] ?? 'all'),
                'trackers' => (string) wp_unslash($_POST['trackers'] ?? ''),
            ];
            $render_mode = sanitize_key((string) wp_unslash($_POST['render_mode'] ?? 'trackers'));
            $combine_qualified_tracker = $render_mode === 'qualified_combined';
            $saved_trackers_only = $render_mode === 'saved_trackers';
            if (trim((string) $filters['trackers']) !== '') {
                $selected_group = '';
            }

            $payload = $this->get_crm_editorial_community_feed_items($batch_size, $user_id, 0, $selected_group, [], $filters);
            $items = (array) ($payload['items'] ?? []);
            $focus_post_id = absint(wp_unslash($_POST['focus_post_id'] ?? 0));
            if ($focus_post_id > 0) {
                $focus_item = $this->get_crm_editorial_community_feed_item_by_id($focus_post_id);
                if (
                    !empty($focus_item)
                    && $this->does_crm_editorial_community_item_match_filters((array) $focus_item, $this->normalize_crm_editorial_community_feed_filters($filters))
                    && (
                        $this->current_user_has_crm_editorial_paid_membership_access($user_id)
                        || !$this->is_crm_editorial_community_item_in_premium_tracker((array) $focus_item)
                    )
                ) {
                    $items = array_values(array_filter($items, static function ($item) use ($focus_post_id) {
                        $item_id = (int) ($item['crm_post_id'] ?? $item['post_id'] ?? 0);
                        return $item_id !== $focus_post_id;
                    }));
                    array_unshift($items, $focus_item);
                    $items = array_slice($items, 0, $batch_size);
                }
            }
            $normalized_filters = $this->normalize_crm_editorial_community_feed_filters($filters);
            $has_active_filters = $selected_group !== '';
            foreach (['search', 'location', 'seniority', 'qualification', 'recency', 'posted_date', 'company', 'sector', 'work_type', 'match_rank'] as $filter_key) {
                $filter_value = $normalized_filters[$filter_key] ?? 'all';
                if (($filter_key === 'search' && trim((string) $filter_value) !== '') || ($filter_key !== 'search' && (string) $filter_value !== 'all')) {
                    $has_active_filters = true;
                    break;
                }
            }
            if (!$has_active_filters && !empty($normalized_filters['trackers'])) {
                $has_active_filters = true;
            }

            $tracker_groups = $this->get_crm_editorial_community_tracker_source_groups($items);

            wp_send_json_success([
                'html' => $this->render_crm_editorial_community_posts_markup($items, !empty($payload['has_more']), 0, $selected_group, $tracker_groups, [], (array) ($normalized_filters['trackers'] ?? []), $combine_qualified_tracker, $saved_trackers_only, $this->get_crm_editorial_community_saved_tracker_slugs($user_id), $has_active_filters, !$saved_trackers_only),
                'detailHtml' => !$saved_trackers_only ? $this->render_crm_editorial_community_linkedin_detail_markup($items) : '',
                'count' => count($items),
                'hasMore' => !empty($payload['has_more']),
                'filters' => $normalized_filters,
            ]);
        }

        private function get_crm_editorial_community_saved_trackers_meta_key()
        {
            return 'sffc_crm_editorial_saved_trackers';
        }

        private function get_crm_editorial_community_saved_tracker_slugs($user_id = 0)
        {
            $user_id = absint($user_id);
            if ($user_id <= 0) {
                return [];
            }

            $saved = get_user_meta($user_id, $this->get_crm_editorial_community_saved_trackers_meta_key(), true);
            if (!is_array($saved)) {
                $saved = is_string($saved) && $saved !== '' ? explode('|', $saved) : [];
            }

            return array_values(array_unique(array_filter(array_map('sanitize_title', $saved))));
        }

        public function ajax_crm_editorial_toggle_saved_tracker()
        {
            check_ajax_referer('sffc_crm_editorial_saved_tracker', 'nonce');

            $tracker_slug = sanitize_title((string) wp_unslash($_POST['tracker_slug'] ?? ''));
            $should_save = (string) wp_unslash($_POST['saved'] ?? '1') === '1';

            if ($tracker_slug === '') {
                wp_send_json_error([
                    'message' => __('Tracker could not be saved.', 'senna-finance'),
                ], 400);
            }

            $user_id = get_current_user_id();
            if ($user_id <= 0) {
                wp_send_json_success([
                    'saved' => $should_save,
                    'tracker' => $tracker_slug,
                ]);
            }

            $saved_trackers = $this->get_crm_editorial_community_saved_tracker_slugs($user_id);
            if ($should_save) {
                $saved_trackers[] = $tracker_slug;
            } else {
                $saved_trackers = array_values(array_filter($saved_trackers, static function ($saved_slug) use ($tracker_slug) {
                    return $saved_slug !== $tracker_slug;
                }));
            }
            $saved_trackers = array_values(array_unique(array_filter(array_map('sanitize_title', $saved_trackers))));

            update_user_meta($user_id, $this->get_crm_editorial_community_saved_trackers_meta_key(), $saved_trackers);

            wp_send_json_success([
                'saved' => $should_save,
                'tracker' => $tracker_slug,
                'savedTrackers' => $saved_trackers,
            ]);
        }

        public function ajax_crm_editorial_upload_match_cv()
        {
            check_ajax_referer('sffc_crm_editorial_upload_match_cv', 'nonce');

            $posted_cv_text = $this->sanitize_crm_reddit_pasted_cv_text((string) wp_unslash($_POST['cv_text'] ?? ''));
            $posted_file_name = sanitize_file_name((string) wp_unslash($_POST['file_name'] ?? 'resume'));
            $upload_result = [
                'file_name' => $posted_file_name !== '' ? $posted_file_name : 'resume',
                'text' => $posted_cv_text,
                'success' => $posted_cv_text !== '',
            ];

            if ($posted_cv_text === '' && empty($_FILES['cv_file'])) {
                wp_send_json_error(['message' => __('Upload a PDF, DOC, DOCX, or TXT CV.', 'senna-finance')], 422);
            }

            if ($posted_cv_text === '') {
                $upload_result = $this->extract_crm_apply_chat_cv_text_from_upload($_FILES['cv_file'], 'fast');
            }

            if (empty($upload_result['success'])) {
                wp_send_json_error([
                    'message' => (string) ($upload_result['message'] ?? __('Unable to read that CV file.', 'senna-finance')),
                ], 422);
            }

            $cv_text = trim((string) ($upload_result['text'] ?? ''));
            if ($cv_text === '') {
                wp_send_json_error(['message' => __('I could not read text from that CV. Try a PDF/DOCX with selectable text.', 'senna-finance')], 422);
            }

            $text_length = function_exists('mb_strlen') ? mb_strlen($cv_text) : strlen($cv_text);
            if ($text_length < 120) {
                wp_send_json_error(['message' => __('I could not read enough CV text to score matches. Try a fuller PDF/DOCX or paste the CV text instead.', 'senna-finance')], 422);
            }

            $token = wp_generate_password(32, false, false);
            $profile = $this->build_crm_editorial_community_match_profile_from_cv_text($cv_text);
            set_transient('sffc_crm_editorial_guest_cv_' . $token, [
                'cv_text' => $cv_text,
                'profile' => $profile,
                'file_name' => sanitize_file_name((string) ($upload_result['file_name'] ?? 'resume')),
                'created_at' => time(),
            ], 12 * HOUR_IN_SECONDS);

            wp_send_json_success([
                'token' => $token,
                'file_name' => sanitize_file_name((string) ($upload_result['file_name'] ?? 'resume')),
                'message' => __('CV uploaded. Matching roles now.', 'senna-finance'),
            ]);
        }

        public function ajax_crm_editorial_autocomplete_search()
        {
            check_ajax_referer('sffc_crm_editorial_autocomplete_search', 'nonce');

            $term = sanitize_text_field((string) wp_unslash($_POST['term'] ?? ''));
            $mode = $this->get_crm_editorial_community_autocomplete_mode((string) wp_unslash($_POST['mode'] ?? 'contains'));
            if ((function_exists('mb_strlen') ? mb_strlen($term) : strlen($term)) < 2) {
                wp_send_json_success([
                    'html' => '',
                    'count' => 0,
                ]);
            }

            $payload = $this->get_crm_editorial_community_autocomplete_payload($term, get_current_user_id(), $mode);

            wp_send_json_success([
                'html' => $this->render_crm_editorial_community_autocomplete_markup($payload, $term),
                'count' => count((array) ($payload['posts'] ?? [])),
            ]);
        }

        public function ajax_crm_editorial_standalone_search()
        {
            check_ajax_referer('sffc_crm_editorial_standalone_search', 'nonce');

            $term = sanitize_text_field((string) wp_unslash($_POST['term'] ?? ''));
            $category = sanitize_key((string) wp_unslash($_POST['category'] ?? 'jobs'));
            $mode = $this->get_crm_editorial_community_autocomplete_mode((string) wp_unslash($_POST['mode'] ?? 'contains'));
            $is_logged_in = is_user_logged_in();

            if (!in_array($category, ['jobs', 'resources'], true)) {
                $category = 'jobs';
            }
            if (!$is_logged_in && $category === 'resources') {
                $category = 'jobs';
            }

            if ((function_exists('mb_strlen') ? mb_strlen($term) : strlen($term)) < 2) {
                wp_send_json_success([
                    'html' => '',
                    'count' => 0,
                    'items' => [],
                ]);
            }

            $items = [];

            if ($category === 'jobs') {
                $items = $this->get_crm_editorial_community_standalone_job_results($term, $mode, 6);
            } else {
                $items = $this->get_crm_editorial_community_search_resources($term, 8);
            }

            $has_premium_access = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $response_items = $has_premium_access ? $items : $this->mask_crm_editorial_community_search_items_for_public($items);

            wp_send_json_success([
                'html' => $this->render_crm_editorial_community_standalone_search_markup($items, $category, $term),
                'count' => count($items),
                'items' => $response_items,
                'category' => $category,
            ]);
        }

        private function mask_crm_editorial_community_search_items_for_public(array $items)
        {
            $masked_items = [];

            foreach ($items as $item) {
                $item = is_array($item) ? $item : [];
                $type = sanitize_key((string) ($item['type'] ?? ''));

                if ($type === 'job') {
                    $item['company'] = '';
                    $item['logo'] = '';
                    if (!empty($item['recruiter'])) {
                        $item['recruiter'] = $this->format_crm_reddit_recruiter_short_name((string) $item['recruiter']);
                    }
                } elseif ($type === 'recruiter') {
                    $item['company'] = '';
                    if (!empty($item['name'])) {
                        $item['name'] = $this->format_crm_reddit_recruiter_short_name((string) $item['name']);
                    }
                }

                unset(
                    $item['recruiter_email'],
                    $item['recruiter_linkedin'],
                    $item['email'],
                    $item['linkedin_url'],
                    $item['contact_email'],
                    $item['contact_linkedin']
                );

                $masked_items[] = $item;
            }

            return $masked_items;
        }

        private function get_crm_editorial_community_standalone_job_results($term, $mode = 'contains', $limit = 6)
        {
            global $wpdb;

            $term = sanitize_text_field((string) $term);
            $mode = $this->get_crm_editorial_community_autocomplete_mode($mode);
            $limit = max(1, min(10, (int) $limit));
            $normalized_term = $this->normalize_crm_reddit_dashboard_cv_text($term);
            if ($normalized_term === '') {
                return [];
            }

            $cache_key = 'sffc_crm_editorial_standalone_jobs_me_v2_' . md5($term . '|' . $mode . '|' . $limit);
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
            $early_bird_exclusion_select = $this->get_crm_posts_early_bird_exclusion_select('p');
            $like = '%' . $wpdb->esc_like($term) . '%';

            $where = [
                'p.is_active = 1',
                'p.admin_approved = 1',
                "(p.post_status IS NULL OR p.post_status = 'open')",
            ];
            $values = [];

            if ($mode === 'title') {
                $where[] = 'p.role_title LIKE %s';
                $values[] = $like;
            } else {
                $search_columns = [
                    'p.role_title',
                    'p.company',
                    'p.location',
                    'p.location_country',
                    'p.location_city',
                    'p.sector',
                    'p.seniority',
                    'p.content_snippet',
                    'p.keywords',
                ];
                $where[] = '(' . implode(' OR ', array_map(static function ($column) {
                    return "{$column} LIKE %s";
                }, $search_columns)) . ')';
                foreach ($search_columns as $_column) {
                    $values[] = $like;
                }
            }

            $query_limit = max($limit, 80);
            $values[] = $query_limit;

            $sql = "SELECT p.id, p.role_title, p.company, p.location, p.location_country,
                           p.salary_text, p.seniority, p.sector, p.content_snippet, p.posted_at,
                           p.is_remote, p.is_hybrid, p.application_url, p.wp_post_id, p.company_logo, p.keywords,
                           p.experience_years, {$early_bird_exclusion_select},
                           COALESCE(NULLIF(p.company_logo, ''), r.default_company_logo) AS company_logo,
                           r.id as recruiter_id, r.name as recruiter_name, r.firm as recruiter_firm,
                           r.photo_url as recruiter_photo, r.title as recruiter_title,
                           r.email as recruiter_email, r.linkedin_url as recruiter_linkedin,
                           r.sectors as recruiter_specializations
                    FROM {$posts_table} p
                    LEFT JOIN {$recruiters_table} r ON r.id = p.recruiter_id
                    WHERE " . implode(' AND ', $where) . "
                    ORDER BY p.posted_at DESC, p.id DESC
                    LIMIT %d";

            $rows = $wpdb->get_results($wpdb->prepare($sql, $values), ARRAY_A);
            if (empty($rows) || !is_array($rows)) {
                set_transient($cache_key, [], 2 * MINUTE_IN_SECONDS);
                return [];
            }
            $rows = $this->filter_crm_editorial_community_posts_for_middle_east($rows);

            $items = [];
            foreach ($rows as $row) {
                $post = $this->build_crm_reddit_dashboard_crm_item((array) $row);
                $title_haystack = $this->normalize_crm_reddit_dashboard_cv_text((string) ($post['role_title'] ?? ''));
                $title_match = $title_haystack !== '' && strpos($title_haystack, $normalized_term) !== false;

                $items[] = [
                    'type' => 'job',
                    'post_id' => (int) ($post['crm_post_id'] ?? $post['post_id'] ?? 0),
                    'group_slug' => '',
                    'url' => (string) ($post['view_url'] ?? ''),
                    'title' => trim((string) ($post['role_title'] ?? '')),
                    'company' => trim((string) ($post['company'] ?? '')),
                    'location' => trim((string) ($post['location'] ?? '')),
                    'posted' => trim((string) ($post['posted_label'] ?? '')),
                    'logo' => trim((string) ($row['company_logo'] ?? ($post['company_logo'] ?? ''))),
                    'avatar' => trim((string) ($post['recruiter_photo'] ?? '')),
                    'recruiter' => trim((string) ($post['recruiter_name'] ?? '')),
                    'recruiter_title' => trim((string) ($post['recruiter_title'] ?? '')),
                    'type_label' => __('Live role', 'senna-finance'),
                    'match_badges' => [
                        [
                            'tone' => $title_match ? 'title' : 'contains',
                            'prefix' => $title_match ? __('Title matches', 'senna-finance') : __('Contains keyword', 'senna-finance'),
                            'value' => $term,
                        ],
                    ],
                    'sort_score' => $title_match ? 34 : 20,
                ];

                if (count($items) >= $limit) {
                    break;
                }
            }

            set_transient($cache_key, $items, 2 * MINUTE_IN_SECONDS);

            return $items;
        }

        private function get_crm_editorial_community_standalone_recruiter_results($term, $limit = 8)
        {
            global $wpdb;

            $term = sanitize_text_field((string) $term);
            $limit = max(1, min(12, (int) $limit));
            $normalized_term = $this->normalize_crm_reddit_dashboard_cv_text($term);
            if ($normalized_term === '') {
                return [];
            }

            $cache_key = 'sffc_crm_editorial_standalone_recruiters_' . md5($term . '|' . $limit);
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            $table = $wpdb->prefix . 'sffc_crm_hr_outreach';
            $like = '%' . $wpdb->esc_like($term) . '%';
            $starts_like = $wpdb->esc_like($term) . '%';
            $columns = [
                'contact_name',
                'company_name',
                'contact_title',
                'contact_email',
                'location',
                'regions',
                'industry',
                'skills',
                'role_focus',
            ];

            $where_parts = array_map(static function ($column) {
                return "{$column} LIKE %s";
            }, $columns);
            $values = array_fill(0, count($columns), $like);
            $values[] = $starts_like;
            $values[] = $starts_like;
            $values[] = $limit;

            $sql = "SELECT id, company_name, company_logo, location, regions, industry, skills, role_focus,
                           contact_name, contact_title, contact_email, contact_phone, contact_linkedin, contact_photo,
                           source_context
                    FROM {$table}
                    WHERE (" . implode(' OR ', $where_parts) . ")
                      AND contact_name <> ''
                    ORDER BY
                        CASE
                            WHEN contact_name LIKE %s THEN 0
                            WHEN company_name LIKE %s THEN 1
                            ELSE 2
                        END ASC,
                        CASE WHEN source_context = 'active_recruiter' THEN 0 ELSE 1 END ASC,
                        company_name ASC,
                        contact_name ASC
                    LIMIT %d";

            $rows = $wpdb->get_results($wpdb->prepare($sql, $values), ARRAY_A);
            if (empty($rows) || !is_array($rows)) {
                set_transient($cache_key, [], 5 * MINUTE_IN_SECONDS);
                return [];
            }

            $items = [];
            foreach ($rows as $row) {
                $name = trim((string) ($row['contact_name'] ?? ''));
                $company = trim((string) ($row['company_name'] ?? ''));
                $title = trim((string) ($row['contact_title'] ?? ''));
                $location = $this->normalize_crm_editorial_discovery_location_label(
                    (string) ($row['location'] ?? ''),
                    (string) ($row['regions'] ?? '')
                );

                $items[] = [
                    'type' => 'recruiter',
                    'recruiter_id' => (int) ($row['id'] ?? 0),
                    'post_id' => 0,
                    'group_slug' => '',
                    'url' => home_url('/terminal/?community_tab=posts'),
                    'name' => $name !== '' ? $name : __('Hiring Contact', 'senna-finance'),
                    'company' => $company,
                    'title' => $title,
                    'location' => $location,
                    'avatar' => trim((string) ($row['contact_photo'] ?? '')),
                    'role_title' => trim((string) ($row['role_focus'] ?? '')),
                    'type_label' => __('Recruiter contact', 'senna-finance'),
                    'match_badges' => [
                        [
                            'tone' => 'contains',
                            'prefix' => __('Contains keyword', 'senna-finance'),
                            'value' => $term,
                        ],
                    ],
                    'sort_score' => 16,
                ];
            }

            set_transient($cache_key, $items, 5 * MINUTE_IN_SECONDS);

            return $items;
        }

        private function get_crm_editorial_community_autocomplete_payload($term, $user_id = 0, $mode = 'contains')
        {
            $term = sanitize_text_field((string) $term);
            $mode = $this->get_crm_editorial_community_autocomplete_mode($mode);
            $cache_key = 'sffc_crm_editorial_autocomplete_fast_' . md5($term . '|' . $mode);
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            $post_candidates = $this->get_crm_editorial_community_standalone_job_results($term, $mode, 6);

            $payload = [
                'mode' => $mode,
                'posts' => $post_candidates,
                'recruiters' => [],
            ];

            set_transient($cache_key, $payload, 2 * MINUTE_IN_SECONDS);

            return $payload;
        }

        private function get_crm_editorial_community_autocomplete_mode($mode)
        {
            $mode = sanitize_key((string) $mode);
            return in_array($mode, ['contains', 'title'], true) ? $mode : 'contains';
        }

        private function get_crm_editorial_community_autocomplete_post_match_context(array $post, $term, $mode = 'contains', $cv_text = '')
        {
            $mode = $this->get_crm_editorial_community_autocomplete_mode($mode);
            $term_label = trim((string) $term);
            $normalized_term = $this->normalize_crm_reddit_dashboard_cv_text($term_label);
            if ($normalized_term === '') {
                return ['matched' => false, 'badges' => [], 'score' => 0];
            }

            $title_haystack = $this->normalize_crm_reddit_dashboard_cv_text((string) ($post['role_title'] ?? ''));
            $contains_haystack = $this->build_cv_match_studio_item_signal_haystack($post) . ' ' . $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                (string) ($post['recruiter_name'] ?? ''),
                (string) ($post['recruiter_title'] ?? ''),
                (string) ($post['location'] ?? ''),
            ])));

            $title_match = $title_haystack !== '' && strpos($title_haystack, $normalized_term) !== false;
            $contains_match = $contains_haystack !== '' && strpos($contains_haystack, $normalized_term) !== false;

            if ($mode === 'title' && !$title_match) {
                return ['matched' => false, 'badges' => [], 'score' => 0];
            }

            if ($mode === 'contains' && !$contains_match) {
                return ['matched' => false, 'badges' => [], 'score' => 0];
            }

            $badges = [];
            $score = 0;

            if ($title_match) {
                $badges[] = [
                    'tone' => 'title',
                    'prefix' => __('Title matches', 'senna-finance'),
                    'value' => $term_label,
                ];
                $score += 34;
            } else {
                $badges[] = [
                    'tone' => 'contains',
                    'prefix' => __('Contains keyword', 'senna-finance'),
                    'value' => $term_label,
                ];
                $score += 20;
            }

            $cv_matches = array_values(array_filter((array) $this->get_cv_match_studio_jobs_mailbox_keyword_chips($post, $cv_text, 8), static function ($chip) {
                return is_array($chip) && (($chip['state'] ?? '') === 'match') && !empty($chip['label']);
            }));

            foreach (array_slice($cv_matches, 0, 2) as $chip) {
                $badges[] = [
                    'tone' => 'cv',
                    'prefix' => __('Appears on your CV', 'senna-finance'),
                    'value' => sanitize_text_field((string) ($chip['label'] ?? '')),
                ];
                $score += 8;
            }

            $posted_timestamp = (int) ($post['posted_timestamp'] ?? 0);
            if ($posted_timestamp > 0) {
                $days_old = max(0, (int) floor((current_time('timestamp') - $posted_timestamp) / DAY_IN_SECONDS));
                $score += max(0, 10 - min(10, $days_old));
            }

            return [
                'matched' => true,
                'badges' => $badges,
                'score' => $score,
            ];
        }

        private function get_crm_editorial_community_autocomplete_recruiter_match_context(array $record, $term)
        {
            $term_label = trim((string) $term);
            $normalized_term = $this->normalize_crm_reddit_dashboard_cv_text($term_label);
            if ($normalized_term === '') {
                return ['matched' => false, 'badges' => [], 'score' => 0];
            }

            $haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                (string) ($record['contact_name'] ?? ''),
                (string) ($record['company_name'] ?? ''),
                (string) ($record['contact_title'] ?? ''),
                (string) ($record['location'] ?? ''),
                (string) ($record['regions'] ?? ''),
                (string) ($record['industry'] ?? ''),
                (string) ($record['skills'] ?? ''),
                (string) ($record['notes'] ?? ''),
            ])));

            if ($haystack === '' || strpos($haystack, $normalized_term) === false) {
                return ['matched' => false, 'badges' => [], 'score' => 0];
            }

            return [
                'matched' => true,
                'badges' => [
                    [
                        'tone' => 'contains',
                        'prefix' => __('Contains keyword', 'senna-finance'),
                        'value' => $term_label,
                    ],
                ],
                'score' => 16,
            ];
        }

        private function match_crm_editorial_autocomplete_recruiter_to_post(array $record, array $posts, $user_id = 0)
        {
            $company = strtolower(trim((string) ($record['company_name'] ?? '')));
            $name = strtolower(trim((string) ($record['contact_name'] ?? '')));

            foreach ($posts as $post) {
                $post_company = strtolower(trim((string) ($post['company'] ?? '')));
                $post_recruiter = strtolower(trim((string) ($post['recruiter_name'] ?? '')));
                if (($company !== '' && $post_company === $company) || ($name !== '' && $post_recruiter === $name)) {
                    return $post;
                }
            }

            $fallback_search = trim((string) ($record['company_name'] ?? ''));
            if ($fallback_search === '') {
                $fallback_search = trim((string) ($record['contact_name'] ?? ''));
            }

            if ($fallback_search === '') {
                return [];
            }

            $fallback_posts = (array) $this->get_crm_reddit_feed_posts_batch(3, (int) $user_id, '', $fallback_search, []);
            if (empty($fallback_posts)) {
                return [];
            }

            return $this->build_crm_reddit_dashboard_crm_item((array) $fallback_posts[0]);
        }

        private function get_crm_editorial_community_search_resources($term, $limit = 8)
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-resource-library.php';

            $term = trim((string) $term);
            $normalized_term = $this->normalize_crm_reddit_dashboard_cv_text($term);
            if ($normalized_term === '') {
                return [];
            }

            $resource_model = new SFFC_CRM_Resource_Library();
            $resources = (array) $resource_model->get_all([
                'is_active' => 1,
                'limit' => 80,
            ]);

            $items = [];
            foreach ($resources as $resource) {
                $resource = is_array($resource) ? $resource : [];
                $title = trim((string) ($resource['title'] ?? ''));
                $url = trim((string) ($resource['resource_url'] ?? ''));
                if ($title === '' || $url === '') {
                    continue;
                }

                $category = trim((string) ($resource['category'] ?? ''));
                $description = trim((string) ($resource['description'] ?? ''));
                $type_label = strtoupper((string) ($resource['resource_type'] ?? 'link'));
                $haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                    $title,
                    $category,
                    $description,
                    $type_label,
                ])));

                if ($haystack === '' || strpos($haystack, $normalized_term) === false) {
                    continue;
                }

                $items[] = [
                    'type' => 'resource',
                    'resource_id' => (int) ($resource['id'] ?? 0),
                    'url' => esc_url_raw($url),
                    'title' => $title,
                    'category' => $category,
                    'description' => $description !== '' ? wp_trim_words($description, 24, '...') : __('MENA Careers resource library item', 'senna-finance'),
                    'thumbnail' => trim((string) ($resource['thumbnail_url'] ?? '')),
                    'type_label' => $type_label,
                    'match_badges' => [
                        [
                            'tone' => 'contains',
                            'prefix' => __('Contains keyword', 'senna-finance'),
                            'value' => $term,
                        ],
                    ],
                ];
            }

            return array_slice($items, 0, max(1, min(12, (int) $limit)));
        }

