                                trim((string) ($item['role_title'] ?? '')),
                            ]));
                            $image = trim((string) ($item['avatar'] ?? ''));
                        } else {
                            $subtitle_parts = array_values(array_filter([
                                trim((string) ($item['category'] ?? '')),
                                trim((string) ($item['type_label'] ?? '')),
                            ]));
                            $meta_parts = array_values(array_filter([
                                trim((string) ($item['description'] ?? '')),
