                            class="sffc-community-editorial-search__result"
                            href="<?php echo esc_url((string) ($item['url'] ?? '#')); ?>"
                            data-sffc-community-standalone-result
                            data-result-type="<?php echo esc_attr($type); ?>"
                            data-post-id="<?php echo esc_attr((string) ((int) ($item['post_id'] ?? 0))); ?>"
                            data-group-slug="<?php echo esc_attr(sanitize_title((string) ($item['group_slug'] ?? ''))); ?>"
                            data-recruiter-id="<?php echo esc_attr((string) ((int) ($item['recruiter_id'] ?? 0))); ?>"
                            data-result-url="<?php echo esc_url((string) ($item['url'] ?? '#')); ?>"
                        >
                            <span class="sffc-community-editorial-search__result-media<?php echo $image !== '' ? ' has-image' : ''; ?>" aria-hidden="true">
                                <?php if ($image !== '') : ?>
                                    <img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr($title); ?>">
                                <?php else : ?>
                                    <strong><?php echo esc_html($initial !== '' ? $initial : 'S'); ?></strong>
                                <?php endif; ?>
                            </span>
                            <span class="sffc-community-editorial-search__result-copy">
                                <strong><?php echo esc_html($title); ?></strong>
                                <?php if (!empty($subtitle_parts)) : ?>
                                    <span><?php echo esc_html(implode(' | ', $subtitle_parts)); ?></span>
                                <?php endif; ?>
                                <?php if (!empty($badges)) : ?>
                                    <span class="sffc-community-editorial-search__signals">
                                        <?php foreach (array_slice($badges, 0, 3) as $badge) : ?>
                                            <span><em><?php echo esc_html((string) ($badge['prefix'] ?? '')); ?></em> <mark><?php echo esc_html((string) ($badge['value'] ?? $term)); ?></mark></span>
