        public function ajax_crm_editorial_load_sidebars()
        {
            check_ajax_referer('sffc_crm_editorial_load_sidebars', 'nonce');

            $user_id = get_current_user_id();
            $context_crm_post_id = absint(wp_unslash($_POST['context_post_id'] ?? 0));
            $context_group_slug = sanitize_title((string) wp_unslash($_POST['context_group'] ?? ''));
            $newsletters = array_slice($this->get_cv_match_studio_newsletters($user_id), 0, 3);

            $market_news_preview = $this->get_crm_editorial_community_market_news_preview(5);
            $events = $this->get_crm_editorial_community_events(4);

            wp_send_json_success([
                'leftHtml' => $this->render_crm_editorial_community_left_sidebars($newsletters),
                'rightHtml' => $this->render_crm_editorial_community_right_sidebar([], $market_news_preview, $events),
            ]);
        }

        public function ajax_crm_editorial_load_tab_panel()
        {
            check_ajax_referer('sffc_crm_editorial_load_tab_panel', 'nonce');

            $tab = sanitize_key((string) wp_unslash($_POST['tab'] ?? ''));
            $user_id = get_current_user_id();

            if ($tab === 'templates') {
                $account_user_payload = $user_id > 0 ? $this->get_crm_reddit_account_user($user_id) : [];
                $membership_label = trim((string) ($account_user_payload['membership_label'] ?? ''));
                if ($membership_label === '') {
                    $membership_label = $user_id > 0
                        ? __('Community access', 'senna-finance')
                        : __('Professional careers and hiring network', 'senna-finance');
                }

                wp_send_json_success([
                    'html' => $this->render_crm_editorial_community_profile_panel($user_id, $account_user_payload, $membership_label),
                ]);
            }

            wp_send_json_error(['message' => __('Unsupported community panel.', 'senna-finance')], 422);
        }

        public function ajax_crm_editorial_save_apply_for_me_mandate()
        {
            check_ajax_referer('sffc_crm_editorial_apply_for_me_mandate', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Sign in to save your Get Hired brief.', 'senna-finance')], 403);
            }

            if (!$this->current_user_has_crm_editorial_paid_membership_access()) {
                wp_send_json_error([
                    'message' => __('A paid MENA Careers plan is required to save a Get Hired brief.', 'senna-finance'),
                    'redirect' => home_url('/memberships/'),
                ], 403);
            }

            $raw_mandate = isset($_POST['mandate']) ? wp_unslash((string) $_POST['mandate']) : '';
            $decoded = json_decode($raw_mandate, true);
            if (!is_array($decoded)) {
                wp_send_json_error(['message' => __('The Get Hired brief could not be read. Please review it and try again.', 'senna-finance')], 422);
            }

            $allowed_sections = [
                'goal',
                'targets',
                'location',
                'working',
                'level',
                'compensation',
                'mandate',
                'cv',
            ];
            $allowed_fields = [
                'target_titles',
                'adjacent_titles',
                'excluded_locations',
                'right_to_work',
                'notice_period',
                'level_flexibility',
                'target_compensation',
                'minimum_compensation',
                'bonus_equity_notes',
                'ask_first_rules',
                'hard_exclusions',
                'extra_notes',
                'stored_cv_url',
                'stored_cv_name',
                'cv_file',
            ];
            $sanitized = [];

            foreach ($allowed_sections as $section_key) {
                $section = isset($decoded[$section_key]) && is_array($decoded[$section_key]) ? $decoded[$section_key] : [];
                $options = [];
                foreach ((array) ($section['options'] ?? []) as $option) {
                    $option = sanitize_text_field((string) $option);
                    if ($option !== '') {
                        $options[] = $option;
                    }
                    if (count($options) >= 12) {
                        break;
                    }
                }

                $fields = [];
                foreach ((array) ($section['fields'] ?? []) as $field_key => $field_value) {
                    $field_key = sanitize_key((string) $field_key);
                    if (!in_array($field_key, $allowed_fields, true)) {
                        continue;
                    }

                    $field_value = sanitize_textarea_field((string) $field_value);
                    if ($field_value !== '') {
                        $fields[$field_key] = $field_value;
                    }
                }

                $sanitized[$section_key] = [
                    'options' => array_values(array_unique($options)),
                    'fields' => $fields,
                ];
            }

            $has_content = false;
            foreach ($sanitized as $section) {
                if (!empty($section['options']) || !empty($section['fields'])) {
                    $has_content = true;
                    break;
                }
            }

            if (!$has_content) {
                wp_send_json_error(['message' => __('Add at least one preference before saving your Get Hired brief.', 'senna-finance')], 422);
            }

            $user_id = get_current_user_id();
            $stored_document = [];
            if (!empty($_FILES['cv_file']) && !empty($_FILES['cv_file']['name'])) {
                $stored_document = $this->store_crm_editorial_onboarding_cv($user_id, $_FILES['cv_file']);
                if (is_wp_error($stored_document)) {
                    wp_send_json_error(['message' => $stored_document->get_error_message()], 422);
                }
            } else {
                $selected_cv_url = esc_url_raw((string) wp_unslash($_POST['stored_cv_url'] ?? ''));
                $selected_cv_name = sanitize_text_field((string) wp_unslash($_POST['stored_cv_name'] ?? ''));
                if ($selected_cv_url !== '') {
                    $stored_document = $this->get_crm_editorial_apply_for_me_selected_cv_document($user_id, $selected_cv_url, $selected_cv_name);
                    if (empty($stored_document)) {
                        wp_send_json_error(['message' => __('Select one of your saved CVs or upload a new CV before saving.', 'senna-finance')], 422);
                    }
                }
            }

            if (empty($stored_document) || empty($stored_document['url'])) {
                wp_send_json_error(['message' => __('Choose which CV Senna should use for applications.', 'senna-finance')], 422);
            }

            $sanitized['cv']['fields']['stored_cv_url'] = esc_url_raw((string) ($stored_document['url'] ?? ''));
            $sanitized['cv']['fields']['stored_cv_name'] = sanitize_text_field((string) ($stored_document['name'] ?? __('Stored CV', 'senna-finance')));
            $saved_at = current_time('mysql');
            update_user_meta($user_id, 'sffc_crm_editorial_apply_for_me_mandate', $sanitized);
            update_user_meta($user_id, 'sffc_crm_editorial_apply_for_me_mandate_saved_at', $saved_at);
            update_user_meta($user_id, 'sffc_crm_editorial_apply_for_me_cv', [
                'name' => sanitize_text_field((string) ($stored_document['name'] ?? '')),
                'url' => esc_url_raw((string) ($stored_document['url'] ?? '')),
                'uploaded' => sanitize_text_field((string) ($stored_document['uploaded'] ?? $saved_at)),
            ]);

            $target_roles = $this->split_crm_editorial_apply_for_me_text_values((string) ($sanitized['targets']['fields']['target_titles'] ?? ''));
            $target_locations = array_values(array_filter((array) ($sanitized['location']['options'] ?? [])));
            $target_sectors = array_values(array_filter((array) ($sanitized['targets']['options'] ?? [])));
            $excluded_locations = $this->split_crm_editorial_apply_for_me_text_values((string) ($sanitized['location']['fields']['excluded_locations'] ?? ''));

            if (!empty($target_roles) || !empty($target_locations) || !empty($target_sectors)) {
                if (function_exists('sffc_crm_save_job_preferences')) {
                    sffc_crm_save_job_preferences($user_id, array_filter([
                        'target_roles' => $target_roles,
                        'target_locations' => $target_locations,
                        'target_sectors' => $target_sectors,
                    ]));
                }

                if (!empty($target_roles)) {
                    update_user_meta($user_id, 'sffc_crm_target_roles', $target_roles);
                    update_user_meta($user_id, 'sffc_crm_editorial_community_target_roles', $target_roles);
                    update_user_meta($user_id, 'sffc_crm_editorial_community_ideal_role', (string) $target_roles[0]);
                }

                if (!empty($target_sectors)) {
                    update_user_meta($user_id, 'sffc_crm_target_sectors', $target_sectors);
                    update_user_meta($user_id, 'sffc_crm_editorial_community_target_sectors', $target_sectors);
                }
            }

            if (!empty($excluded_locations)) {
                update_user_meta($user_id, 'sffc_crm_excluded_locations', $excluded_locations);
            }

            $admin_email_sent = $this->send_crm_editorial_apply_for_me_admin_email($user_id, $sanitized, $stored_document, $saved_at);
            $user_email_sent = $this->send_crm_editorial_apply_for_me_user_confirmation_email($user_id, $sanitized, $stored_document, $saved_at);

            if (!$admin_email_sent || !$user_email_sent) {
                wp_send_json_error([
                    'message' => __('Your Get Hired brief was saved, but we could not send all confirmation emails right now.', 'senna-finance'),
                    'adminEmailSent' => $admin_email_sent,
                    'userEmailSent' => $user_email_sent,
                ], 500);
            }

            wp_send_json_success([
                'message' => __('Your Get Hired brief has been saved and sent to the MENA Careers team.', 'senna-finance'),
                'savedAt' => $saved_at,
            ]);
        }

        private function get_crm_editorial_apply_for_me_selected_cv_document($user_id, $selected_cv_url, $selected_cv_name = '')
        {
            $selected_cv_url = esc_url_raw((string) $selected_cv_url);
            if ($selected_cv_url === '') {
                return [];
            }

            foreach ($this->get_crm_editorial_resume_documents((int) $user_id) as $document) {
                $document_url = esc_url_raw((string) ($document['url'] ?? ''));
                if ($document_url === '' || $document_url !== $selected_cv_url) {
                    continue;
                }

                $name = sanitize_text_field((string) ($document['name'] ?? $selected_cv_name));
                if ($name === '') {
                    $name = __('Stored CV', 'senna-finance');
                }

                return [
                    'name' => $name,
                    'url' => $document_url,
                    'uploaded' => sanitize_text_field((string) ($document['uploaded'] ?? '')),
                    'document_type' => 'resume_cv',
                    '_file_path' => $this->get_crm_editorial_resume_document_file_path($document),
                ];
            }

            return [];
        }

        private function build_crm_editorial_apply_for_me_email_rows(array $mandate)
        {
            $labels = [
                'goal' => __('Goal', 'senna-finance'),
                'targets' => __('Target roles', 'senna-finance'),
                'location' => __('Private equity markets', 'senna-finance'),
                'working' => __('Working and visa rules', 'senna-finance'),
                'level' => __('Seniority', 'senna-finance'),
                'compensation' => __('Compensation', 'senna-finance'),
                'mandate' => __('Application criteria and representation rules', 'senna-finance'),
                'cv' => __('CV for applications', 'senna-finance'),
            ];
            $rows = '';

            foreach ($labels as $key => $label) {
                $section = isset($mandate[$key]) && is_array($mandate[$key]) ? $mandate[$key] : [];
                $parts = [];

                $options = array_values(array_filter(array_map('sanitize_text_field', (array) ($section['options'] ?? []))));
                if (!empty($options)) {
                    $parts[] = implode(', ', $options);
                }

                foreach ((array) ($section['fields'] ?? []) as $field_key => $field_value) {
                    $field_value = trim(sanitize_textarea_field((string) $field_value));
                    if ($field_value === '' || in_array($field_key, ['stored_cv_url', 'cv_file'], true)) {
                        continue;
                    }

                    $field_label = ucwords(str_replace('_', ' ', sanitize_key((string) $field_key)));
                    $parts[] = $field_label . ': ' . $field_value;
                }

                $value = !empty($parts) ? implode("\n", $parts) : __('Not specified', 'senna-finance');
                $rows .= '<tr>'
                    . '<td style="padding:12px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;line-height:1.45;vertical-align:top;width:190px;">' . esc_html($label) . '</td>'
                    . '<td style="padding:12px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;line-height:1.55;white-space:pre-line;vertical-align:top;">' . esc_html($value) . '</td>'
                    . '</tr>';
            }

            return $rows;
        }

        private function send_crm_editorial_apply_for_me_admin_email($user_id, array $mandate, array $stored_document, $saved_at)
        {
            $user = get_userdata((int) $user_id);
            $admin_email = (string) apply_filters('sffc_crm_editorial_apply_for_me_admin_email', get_option('admin_email'), $user_id, $mandate, $stored_document);
            if ($admin_email === '' || !is_email($admin_email)) {
                return false;
            }

            $display_name = $user instanceof WP_User && $user->display_name !== '' ? (string) $user->display_name : __('MENA Careers member', 'senna-finance');
            $user_email = $user instanceof WP_User ? sanitize_email((string) $user->user_email) : '';
            $cv_name = sanitize_text_field((string) ($stored_document['name'] ?? __('Stored CV', 'senna-finance')));
            $cv_url = esc_url_raw((string) ($stored_document['url'] ?? ''));
            $file_path = $this->get_crm_editorial_onboarding_cv_file_path($stored_document);
            if ($file_path === '') {
                $file_path = $this->get_crm_editorial_resume_document_file_path($stored_document);
            }
            $attachments = $file_path !== '' ? [$file_path] : [];
            $subject = sprintf(__('Get Hired brief - %s', 'senna-finance'), $display_name);

            $html = '<!doctype html><html><body style="margin:0;padding:0;background:#ffffff;color:#111827;font-family:Arial,Helvetica,sans-serif;">'
                . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;background:#ffffff;">'
                . '<tr><td align="center" style="padding:32px 20px;">'
                . '<table role="presentation" width="680" cellspacing="0" cellpadding="0" style="width:680px;max-width:100%;border-collapse:collapse;">'
                . '<tr><td style="padding:0 0 18px;border-bottom:3px solid #0a66c2;">'
                . '<div style="font-size:13px;line-height:1.4;font-weight:700;letter-spacing:0;text-transform:uppercase;color:#0a66c2;">MENA Careers</div>'
                . '<h1 style="margin:8px 0 0;font-size:28px;line-height:1.18;font-weight:700;color:#111827;">New Get Hired brief</h1>'
                . '</td></tr>'
                . '<tr><td style="padding:22px 0 4px;">'
                . '<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#374151;">A member submitted their Get Hired criteria. Review the rules below before outreach or applications start.</p>'
                . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">'
                . '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;width:190px;">Member</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;font-weight:700;">' . esc_html($display_name) . '</td></tr>'
                . ($user_email !== '' ? '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;">Email</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;"><a href="mailto:' . esc_attr($user_email) . '" style="color:#0a66c2;text-decoration:underline;">' . esc_html($user_email) . '</a></td></tr>' : '')
                . '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;">Submitted</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;">' . esc_html(mysql2date(get_option('date_format') . ' ' . get_option('time_format'), (string) $saved_at, false)) . '</td></tr>'
                . '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;">CV</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;">' . esc_html($cv_name) . ($cv_url !== '' ? ' - <a href="' . esc_url($cv_url) . '" style="color:#0a66c2;text-decoration:underline;">Open CV</a>' : '') . '</td></tr>'
                . $this->build_crm_editorial_apply_for_me_email_rows($mandate)
                . '</table>'
                . '</td></tr>'
                . '<tr><td style="padding:18px 0 0;color:#6b7280;font-size:12px;line-height:1.5;">This email was generated from the Get Hired tab in MENA Careers.</td></tr>'
                . '</table></td></tr></table></body></html>';

            $headers = ['Content-Type: text/html; charset=UTF-8'];
            if ($user_email !== '') {
                $headers[] = sprintf('Reply-To: %s <%s>', $display_name, $user_email);
            }

            return (bool) wp_mail($admin_email, $subject, $html, $headers, $attachments);
        }

        private function send_crm_editorial_apply_for_me_user_confirmation_email($user_id, array $mandate, array $stored_document, $saved_at)
        {
            $user = get_userdata((int) $user_id);
            if (!$user instanceof WP_User || !is_email((string) $user->user_email)) {
                return false;
            }

            $display_name = $user->display_name !== '' ? (string) $user->display_name : __('there', 'senna-finance');
            $cv_name = sanitize_text_field((string) ($stored_document['name'] ?? __('Stored CV', 'senna-finance')));
            $subject = __('We received your Get Hired brief', 'senna-finance');
            $html = '<!doctype html><html><body style="margin:0;padding:0;background:#ffffff;color:#111827;font-family:Arial,Helvetica,sans-serif;">'
                . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;background:#ffffff;">'
                . '<tr><td align="center" style="padding:32px 20px;">'
                . '<table role="presentation" width="680" cellspacing="0" cellpadding="0" style="width:680px;max-width:100%;border-collapse:collapse;">'
                . '<tr><td style="padding:0 0 18px;border-bottom:3px solid #0a66c2;">'
                . '<div style="font-size:13px;line-height:1.4;font-weight:700;letter-spacing:0;text-transform:uppercase;color:#0a66c2;">MENA Careers</div>'
                . '<h1 style="margin:8px 0 0;font-size:28px;line-height:1.18;font-weight:700;color:#111827;">Your Get Hired brief is with us</h1>'
                . '</td></tr>'
                . '<tr><td style="padding:22px 0 4px;">'
                . '<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#374151;">Hi ' . esc_html($display_name) . ',</p>'
                . '<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#374151;">We received your job-search criteria and the CV you want us to use. The MENA Careers team will use this to decide what to apply to, what to ask you about first, and what to avoid.</p>'
                . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">'
                . '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;width:190px;">Submitted</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;">' . esc_html(mysql2date(get_option('date_format') . ' ' . get_option('time_format'), (string) $saved_at, false)) . '</td></tr>'
                . '<tr><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:14px;">CV selected</td><td style="padding:10px 0;border-bottom:1px solid #e5e7eb;color:#111827;font-size:14px;">' . esc_html($cv_name) . '</td></tr>'
                . $this->build_crm_editorial_apply_for_me_email_rows($mandate)
                . '</table>'
                . '<p style="margin:18px 0 0;font-size:14px;line-height:1.6;color:#374151;">We will not invent credentials, achievements, compensation, right-to-work status, or personal information. Anything outside your criteria requires approval.</p>'
                . '</td></tr>'
                . '<tr><td style="padding:18px 0 0;color:#6b7280;font-size:12px;line-height:1.5;">MENA Careers</td></tr>'
                . '</table></td></tr></table></body></html>';

            return (bool) wp_mail((string) $user->user_email, $subject, $html, ['Content-Type: text/html; charset=UTF-8']);
        }

        private function split_crm_editorial_apply_for_me_text_values($value)
        {
            $value = trim((string) $value);
            if ($value === '') {
                return [];
            }

            $parts = preg_split('/[\r\n,;]+/', $value);
            $values = [];
            foreach ((array) $parts as $part) {
                $part = sanitize_text_field((string) $part);
                if ($part !== '') {
                    $values[] = $part;
                }
                if (count($values) >= 12) {
                    break;
                }
            }

            return array_values(array_unique($values));
        }

        public function ajax_crm_editorial_onboarding_submit()
        {
            check_ajax_referer('sffc_crm_editorial_onboarding', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Login required.', 'senna-finance')], 403);
            }

            $user_id = get_current_user_id();
            $skip = !empty($_POST['skip']);

            if ($skip) {
                update_user_meta($user_id, 'sffc_crm_editorial_community_onboarding_seen', '1');
                wp_send_json_success(['message' => __('Onboarding skipped.', 'senna-finance')]);
            }

            $access_choice = sanitize_key((string) wp_unslash($_POST['access_choice'] ?? ''));
            $location_choice = sanitize_key((string) wp_unslash($_POST['location_choice'] ?? ''));
            $location_other = sanitize_text_field((string) wp_unslash($_POST['location_other'] ?? ''));
            $role_interest = sanitize_key((string) wp_unslash($_POST['role_interest'] ?? 'analyst_associate'));
            $ideal_role = sanitize_text_field((string) wp_unslash($_POST['ideal_role'] ?? ''));
            $target_sector = sanitize_key((string) wp_unslash($_POST['target_sector'] ?? ''));
            $target_role_items_raw = isset($_POST['target_role_items']) ? wp_unslash((string) $_POST['target_role_items']) : '';
            $target_roles_raw = isset($_POST['target_roles']) ? wp_unslash((string) $_POST['target_roles']) : '';
            $target_sectors_raw = isset($_POST['target_sectors']) ? wp_unslash((string) $_POST['target_sectors']) : '';
            $allow_no_cv = !empty($_POST['allow_no_cv']);

            $access_labels = [
                'roles_only' => __('Finance Roles Only', 'senna-finance'),
                'roles_alerts' => __('Roles + Email Alerts', 'senna-finance'),
                'full_access' => __('CV + LinkedIn Review', 'senna-finance'),
            ];

            if ($access_choice === '') {
                $access_choice = 'full_access';
            }

            if (!isset($access_labels[$access_choice])) {
                wp_send_json_error(['message' => __('Choose what you want access to first.', 'senna-finance')], 422);
            }

            $location_labels = [
                'dubai' => __('Dubai', 'senna-finance'),
                'abu_dhabi' => __('Abu Dhabi', 'senna-finance'),
                'riyadh' => __('Riyadh', 'senna-finance'),
                'doha' => __('Doha', 'senna-finance'),
                'other' => __('Other', 'senna-finance'),
            ];

            if (!isset($location_labels[$location_choice])) {
                wp_send_json_error(['message' => __('Choose a preferred location first.', 'senna-finance')], 422);
            }

            $seniority_map = [
                'analyst_associate' => [
                    'crm' => ['analyst', 'associate'],
                    'signup' => ['analyst', 'associate'],
                ],
                'manager_director' => [
                    'crm' => ['vp', 'director'],
                    'signup' => ['manager', 'director'],
                ],
                'c_suite' => [
                    'crm' => ['c_level'],
                    'signup' => ['c_level'],
                ],
            ];

            if (!isset($seniority_map[$role_interest])) {
                $role_interest = 'analyst_associate';
            }

            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [];
            $target_role_items = [];
            $decoded_target_role_items = json_decode($target_role_items_raw, true);
            if (is_array($decoded_target_role_items)) {
                foreach ($decoded_target_role_items as $role_item) {
                    if (!is_array($role_item)) {
                        continue;
                    }

                    $role_value = sanitize_text_field((string) ($role_item['role'] ?? ''));
                    $sector_value = sanitize_key((string) ($role_item['sector'] ?? ''));
                    if ($role_value === '' || $sector_value === '' || !isset($sector_options[$sector_value])) {
                        continue;
                    }

                    $target_role_items[] = [
                        'role' => $role_value,
                        'sector' => $sector_value,
                    ];

                    if (count($target_role_items) >= 3) {
                        break;
                    }
                }
            }

            $decoded_target_roles = json_decode($target_roles_raw, true);
            $decoded_target_sectors = json_decode($target_sectors_raw, true);
            if (empty($target_role_items) && is_array($decoded_target_roles) && is_array($decoded_target_sectors)) {
                for ($target_index = 0; $target_index < 3; $target_index++) {
                    $role_value = sanitize_text_field((string) ($decoded_target_roles[$target_index] ?? ''));
                    $sector_value = sanitize_key((string) ($decoded_target_sectors[$target_index] ?? ''));
                    if ($role_value === '' || $sector_value === '' || !isset($sector_options[$sector_value])) {
                        continue;
                    }

                    $target_role_items[] = [
                        'role' => $role_value,
                        'sector' => $sector_value,
                    ];
                }
            }

            if (empty($target_role_items) && $ideal_role !== '' && $target_sector !== '' && isset($sector_options[$target_sector])) {
                $target_role_items[] = [
                    'role' => $ideal_role,
                    'sector' => $target_sector,
                ];
            }

            $target_roles = array_map(static function ($role_item) {
                return (string) ($role_item['role'] ?? '');
            }, $target_role_items);
            $target_roles = array_values(array_unique(array_filter($target_roles)));
            $ideal_role = (string) ($target_roles[0] ?? '');

            if ($ideal_role === '') {
                wp_send_json_error(['message' => __('Enter your ideal role before continuing.', 'senna-finance')], 422);
            }

            $target_sectors = array_map(static function ($role_item) {
                return (string) ($role_item['sector'] ?? '');
            }, $target_role_items);
            $target_sectors = array_values(array_unique(array_filter($target_sectors)));
            $target_sector = (string) ($target_sectors[0] ?? '');

            if ($target_sector === '' || !isset($sector_options[$target_sector])) {
                wp_send_json_error(['message' => __('Select the finance sector you want MENA Careers to prioritise.', 'senna-finance')], 422);
            }

            $target_locations = [];
            $campaign_location = '';
            if ($location_choice === 'other') {
                if ($location_other === '') {
                    wp_send_json_error(['message' => __('Enter your preferred location.', 'senna-finance')], 422);
                }
                $target_locations[] = $location_other;
                $campaign_location = $location_other;
            } else {
                $target_locations[] = (string) $location_labels[$location_choice];
                $campaign_location = (string) $location_labels[$location_choice];
            }

            if (function_exists('sffc_crm_save_job_preferences')) {
                sffc_crm_save_job_preferences($user_id, [
                    'target_locations' => $target_locations,
                    'target_seniority' => $seniority_map[$role_interest]['crm'],
                    'target_roles' => $target_roles,
                    'target_sectors' => $target_sectors,
                ]);
            }

            update_user_meta($user_id, $this->get_cv_match_studio_preferred_location_meta_key(), $location_choice);
            update_user_meta($user_id, 'sffc_signup_seniority_level', $seniority_map[$role_interest]['signup']);
            update_user_meta($user_id, 'sffc_crm_editorial_community_access_choice', $access_choice);
            update_user_meta($user_id, 'sffc_crm_editorial_community_ideal_role', $ideal_role);
            update_user_meta($user_id, 'sffc_crm_editorial_community_target_sector', $target_sector);
            update_user_meta($user_id, 'sffc_crm_editorial_community_target_role_items', $target_role_items);
            update_user_meta($user_id, 'sffc_crm_editorial_community_target_roles', $target_roles);
            update_user_meta($user_id, 'sffc_crm_editorial_community_target_sectors', $target_sectors);

            if ($location_choice === 'other' && $location_other !== '') {
                update_user_meta($user_id, 'sffc_crm_editorial_community_other_location', $location_other);
            } else {
                delete_user_meta($user_id, 'sffc_crm_editorial_community_other_location');
            }

            $cv_saved = isset($_POST['cv_saved']) ? sanitize_text_field(wp_unslash((string) $_POST['cv_saved'])) : '0';
            if ($cv_saved !== '1' && !$allow_no_cv) {
                wp_send_json_error(['message' => __('Upload your CV before completing onboarding.', 'senna-finance')], 422);
            }

            $stored_document = null;
            if (!empty($_FILES['cv_file']) && !empty($_FILES['cv_file']['name'])) {
                $stored_document = $this->store_crm_editorial_onboarding_cv($user_id, $_FILES['cv_file']);
                if (is_wp_error($stored_document)) {
                    wp_send_json_error(['message' => $stored_document->get_error_message()], 422);
                }

                $this->send_crm_editorial_onboarding_cv_admin_email($user_id, $stored_document, [
                    'access_choice' => $access_choice,
                    'location' => $campaign_location,
                    'role_interest' => $role_interest,
                    'ideal_role' => $ideal_role,
                    'target_role_items' => $target_role_items,
                    'target_roles' => $target_roles,
                    'target_sector' => $target_sector,
                    'target_sectors' => $target_sectors,
                ]);
            }

            $latest_resume_document = $this->get_crm_editorial_latest_resume_document($user_id);
            if ((empty($latest_resume_document) || empty($latest_resume_document['url'])) && !$allow_no_cv) {
                wp_send_json_error(['message' => __('Upload your CV before completing onboarding.', 'senna-finance')], 422);
            }

            $campaign_saved = $this->save_crm_editorial_onboarding_campaign_request($user_id, [
                'target_role' => $ideal_role,
                'target_location' => $campaign_location,
                'target_seniority' => $this->get_crm_editorial_onboarding_campaign_seniority_label($role_interest),
                'target_sector' => $target_sector,
                'intro_context' => $this->build_crm_editorial_onboarding_campaign_context([
                    'access_choice' => $access_choice,
                    'location' => $campaign_location,
                    'role_interest' => $role_interest,
                    'ideal_role' => $ideal_role,
                    'target_role_items' => $target_role_items,
                    'target_roles' => $target_roles,
                    'target_sector' => $target_sector,
                    'target_sectors' => $target_sectors,
                    'cv_saved' => !empty($latest_resume_document['url']) ? '1' : '0',
                ]),
                'stored_document' => is_array($stored_document) ? $stored_document : null,
            ]);

            if (is_wp_error($campaign_saved)) {
                wp_send_json_error(['message' => $campaign_saved->get_error_message()], 500);
            }

            update_user_meta($user_id, 'sffc_crm_editorial_community_onboarding_seen', '1');
            $this->sync_crm_editorial_onboarding_into_apply_chat($user_id);

            wp_send_json_success([
                'message' => __('Your preferences have been saved.', 'senna-finance'),
            ]);
        }

        private function sync_crm_editorial_onboarding_into_apply_chat($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0 || !function_exists('sffc_crm_sync_premium_search_profile_from_apply_chat')) {
                return;
            }

            $profile_preferences = $this->get_crm_apply_chat_profile_preferences($user_id);
            $resume_context = $this->build_crm_apply_chat_resume_context($user_id);
            $membership = $this->get_crm_apply_chat_membership_snapshot($user_id);
            $memory = [
                'has_history' => true,
                'premium_onboarding_completed' => true,
                'last_flow' => 'job_search',
                'last_path' => 'job_search',
                'cv_state' => !empty($resume_context['has_cv']) ? 'job_search' : '',
                'target_functions' => (array) ($profile_preferences['target_roles'] ?? []),
                'target_sectors' => (array) ($profile_preferences['target_sectors'] ?? []),
                'target_locations' => (array) ($profile_preferences['target_locations'] ?? []),
                'preferred_location' => (string) (($profile_preferences['target_locations'][0] ?? '')),
                'delivery_frequency' => sanitize_key((string) get_user_meta($user_id, 'sffc_crm_alert_frequency', true)),
                'last_role_title' => sanitize_text_field((string) get_user_meta($user_id, 'sffc_crm_editorial_community_ideal_role', true)),
                'updated_at' => current_time('mysql'),
            ];

            if ($memory['delivery_frequency'] === '') {
                $memory['delivery_frequency'] = 'daily';
            }

            sffc_crm_sync_premium_search_profile_from_apply_chat(
                $user_id,
                $memory,
                $resume_context,
                $profile_preferences,
                $membership
            );

            $existing_memory = $this->get_crm_apply_chat_user_memory($user_id);
            $merged_memory = array_merge(
                is_array($existing_memory) ? $existing_memory : [],
                $memory
            );
            $merged_memory['target_functions'] = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($merged_memory['target_functions'] ?? [])))));
            $merged_memory['target_sectors'] = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($merged_memory['target_sectors'] ?? [])))));
            $merged_memory['target_locations'] = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array) ($merged_memory['target_locations'] ?? [])))));
            $this->save_crm_apply_chat_user_memory($user_id, $merged_memory, 0);
        }

        private function get_crm_editorial_onboarding_campaign_seniority_label($role_interest)
        {
            $labels = [
                'analyst_associate' => __('Analyst to Associate', 'senna-finance'),
                'manager_director' => __('Manager to Director', 'senna-finance'),
                'c_suite' => __('C-Suite', 'senna-finance'),
            ];

            return isset($labels[$role_interest]) ? (string) $labels[$role_interest] : __('Other', 'senna-finance');
        }

        private function build_crm_editorial_onboarding_campaign_context(array $data)
        {
            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [];
            $sector_key = sanitize_key((string) ($data['target_sector'] ?? ''));
            $sector_label = isset($sector_options[$sector_key]) ? (string) $sector_options[$sector_key] : $sector_key;
            $access_labels = [
                'roles_only' => __('Finance Roles Only', 'senna-finance'),
                'roles_alerts' => __('Roles + Email Alerts', 'senna-finance'),
                'full_access' => __('CV + LinkedIn Review', 'senna-finance'),
            ];
            $access_key = sanitize_key((string) ($data['access_choice'] ?? ''));
            $access_label = isset($access_labels[$access_key]) ? (string) $access_labels[$access_key] : $access_key;
            $target_roles = !empty($data['target_roles']) && is_array($data['target_roles'])
                ? array_values(array_filter(array_map('sanitize_text_field', $data['target_roles'])))
                : [];
            $target_sectors = !empty($data['target_sectors']) && is_array($data['target_sectors'])
                ? array_values(array_filter(array_map('sanitize_key', $data['target_sectors'])))
                : [];
            $sector_labels = [];
            foreach ($target_sectors as $target_sector_key) {
                $sector_labels[] = isset($sector_options[$target_sector_key]) ? (string) $sector_options[$target_sector_key] : $target_sector_key;
            }

            $summary = [
                __('Created from community onboarding.', 'senna-finance'),
                sprintf(
                    /* translators: %s: access path */
                    __('Access path: %s', 'senna-finance'),
                    sanitize_text_field($access_label)
                ),
                sprintf(
                    /* translators: %s: location */
                    __('Preferred location: %s', 'senna-finance'),
                    sanitize_text_field((string) ($data['location'] ?? ''))
                ),
                sprintf(
                    /* translators: %s: role band */
                    __('Role band: %s', 'senna-finance'),
                    $this->get_crm_editorial_onboarding_campaign_seniority_label((string) ($data['role_interest'] ?? ''))
                ),
                sprintf(
                    /* translators: %s: ideal role */
                    __('Ideal role: %s', 'senna-finance'),
                    sanitize_text_field((string) ($data['ideal_role'] ?? ''))
                ),
            ];

            if (!empty($target_roles)) {
                $summary[] = sprintf(
                    /* translators: %s: target roles */
                    __('Target roles: %s', 'senna-finance'),
                    sanitize_text_field(implode(', ', $target_roles))
                );
            }

            if ($sector_label !== '') {
                $summary[] = sprintf(
                    /* translators: %s: sector */
                    __('Sector focus: %s', 'senna-finance'),
                    sanitize_text_field($sector_label)
                );
            }

            if (!empty($sector_labels)) {
                $summary[] = sprintf(
                    /* translators: %s: sectors */
                    __('Sector priorities: %s', 'senna-finance'),
                    sanitize_text_field(implode(', ', array_unique($sector_labels)))
                );
            }

            $summary[] = sprintf(
                /* translators: %s: CV status */
                __('CV status: %s', 'senna-finance'),
                !empty($data['cv_saved']) ? __('Uploaded', 'senna-finance') : __('Skipped', 'senna-finance')
            );

            return implode("\n", array_filter($summary));
        }

        private function save_crm_editorial_onboarding_campaign_request($user_id, array $data)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return new WP_Error('invalid_user', __('We could not save your onboarding campaign.', 'senna-finance'));
            }

            $table = $wpdb->prefix . 'sffc_crm_intro_requests';
            $prepared_table = $wpdb->prepare('SHOW TABLES LIKE %s', $table);
            $table_exists = $prepared_table ? (string) $wpdb->get_var($prepared_table) : '';
            if ($table_exists !== $table) {
                $this->ensure_crm_editorial_onboarding_campaign_table($table);
            } else {
                $this->ensure_crm_editorial_onboarding_campaign_columns($table);
            }

            $prepared_table = $wpdb->prepare('SHOW TABLES LIKE %s', $table);
            $table_exists = $prepared_table ? (string) $wpdb->get_var($prepared_table) : '';
            if ($table_exists !== $table) {
                return new WP_Error('campaign_table_missing', __('We could not initialise the campaigns queue right now.', 'senna-finance'));
            }

            $stored_document = !empty($data['stored_document']) && is_array($data['stored_document'])
                ? $data['stored_document']
                : $this->get_crm_editorial_latest_resume_document($user_id);

            $stored_cv_url = esc_url_raw((string) ($stored_document['url'] ?? ''));
            $stored_cv_name = sanitize_text_field((string) ($stored_document['name'] ?? ''));
            $target_role = sanitize_text_field((string) ($data['target_role'] ?? ''));
            $target_location = sanitize_text_field((string) ($data['target_location'] ?? ''));
            $target_seniority = sanitize_text_field((string) ($data['target_seniority'] ?? ''));
            $target_sector = sanitize_key((string) ($data['target_sector'] ?? ''));
            $intro_context = sanitize_textarea_field((string) ($data['intro_context'] ?? ''));

            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE user_id = %d AND request_type = %s ORDER BY id DESC LIMIT 1",
                $user_id,
                'campaign'
            ));

            $request_data = [
                'user_id' => $user_id,
                'recruiter_id' => 0,
                'recruiter_name' => '',
                'recruiter_email' => '',
                'recruiter_linkedin' => '',
                'company_name' => '',
                'role_title' => $target_role,
                'status' => 'pending_review',
                'request_type' => 'campaign',
                'target_role' => $target_role,
                'target_location' => $target_location,
                'target_seniority' => $target_seniority,
                'stored_cv_url' => $stored_cv_url,
                'stored_cv_name' => $stored_cv_name,
                'target_company' => '',
                'target_sector' => $target_sector,
                'intro_context' => $intro_context,
                'source_action' => 'community_onboarding',
                'updated_at' => current_time('mysql'),
            ];

            if ($existing_id > 0) {
                $updated = $wpdb->update($table, $request_data, ['id' => $existing_id], null, ['%d']);
                if ($updated === false) {
                    return new WP_Error('campaign_update_failed', __('We could not save your onboarding campaign right now.', 'senna-finance'));
                }

                return $existing_id;
            }

            $request_data['post_id'] = (int) floor(microtime(true) * 1000) + wp_rand(100, 999);
            $request_data['created_at'] = current_time('mysql');

            $inserted = $wpdb->insert($table, $request_data);
            if ($inserted === false) {
                return new WP_Error('campaign_insert_failed', __('We could not save your onboarding campaign right now.', 'senna-finance'));
            }

            return (int) $wpdb->insert_id;
        }

        private function get_crm_editorial_latest_resume_document($user_id)
        {
            $documents = get_user_meta((int) $user_id, 'sffc_crm_documents', true);
            if (!is_array($documents) || empty($documents)) {
                $documents = [];
            }

            $documents = array_reverse($documents);
            foreach ($documents as $document) {
                if (!is_array($document)) {
                    continue;
                }
                if (($document['document_type'] ?? '') === 'resume_cv' && !empty($document['url'])) {
                    return $document;
                }
            }

            $fallback_upload = $this->get_crm_editorial_latest_resume_upload_document($user_id);
            if (!empty($fallback_upload)) {
                return $fallback_upload;
            }

            return [];
        }

        private function get_crm_editorial_latest_resume_upload_document($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $active_upload_id = absint((string) get_user_meta($user_id, $this->get_crm_reddit_active_resume_meta_key(), true));
            $upload = $active_upload_id > 0 ? $this->get_crm_reddit_resume_upload($user_id, $active_upload_id) : null;

            if (empty($upload)) {
                $uploads = $this->get_crm_reddit_resume_uploads($user_id, 1);
                $upload = !empty($uploads[0]) && is_array($uploads[0]) ? $uploads[0] : null;
            }

            if (empty($upload) || !is_array($upload)) {
                return [];
            }

            $upload_url = $this->get_crm_reddit_resume_upload_public_url((string) ($upload['file_path'] ?? ''));
            if ($upload_url === '') {
                return [];
            }

            return [
                'name' => sanitize_file_name((string) ($upload['file_name'] ?? 'resume.txt')),
                'url' => $upload_url,
                'uploaded' => sanitize_text_field((string) ($upload['upload_date'] ?? current_time('mysql'))),
                'document_type' => 'resume_cv',
                '_file_path' => (string) ($upload['file_path'] ?? ''),
            ];
        }

        private function get_crm_editorial_resume_document_file_path(array $document)
        {
            $file_path = wp_normalize_path((string) ($document['_file_path'] ?? ''));
            if ($file_path !== '' && file_exists($file_path)) {
                return $file_path;
            }

            $url = esc_url_raw((string) ($document['url'] ?? ''));
            if ($url === '') {
                return '';
            }

            $upload_dir = wp_upload_dir();
            $base_url = (string) ($upload_dir['baseurl'] ?? '');
            $base_dir = wp_normalize_path((string) ($upload_dir['basedir'] ?? ''));
            if ($base_url === '' || $base_dir === '' || strpos($url, $base_url) !== 0) {
                return '';
            }

            $relative_path = ltrim(substr($url, strlen($base_url)), '/');
            if ($relative_path === '') {
                return '';
            }

            $resolved_path = wp_normalize_path(trailingslashit($base_dir) . str_replace('\\', '/', $relative_path));
            return file_exists($resolved_path) ? $resolved_path : '';
        }

        private function get_crm_reddit_resume_upload_public_url($file_path)
        {
            $file_path = wp_normalize_path((string) $file_path);
            if ($file_path === '') {
                return '';
            }

            $upload_dir = wp_upload_dir();
            $base_dir = wp_normalize_path((string) ($upload_dir['basedir'] ?? ''));
            $base_url = (string) ($upload_dir['baseurl'] ?? '');

            if ($base_dir === '' || $base_url === '' || strpos($file_path, $base_dir) !== 0) {
                return '';
            }

            $relative_path = ltrim(substr($file_path, strlen($base_dir)), '/');
            if ($relative_path === '') {
                return '';
            }

            return esc_url_raw(trailingslashit($base_url) . str_replace('\\', '/', $relative_path));
        }

        private function maybe_sync_crm_reddit_resume_upload_document($user_id, $upload_id)
        {
            $user_id = (int) $user_id;
            $upload_id = (int) $upload_id;

            if ($user_id <= 0 || $upload_id <= 0) {
                return;
            }

            $upload = $this->get_crm_reddit_resume_upload($user_id, $upload_id);
            if (empty($upload) || !is_array($upload)) {
                return;
            }

            $upload_url = $this->get_crm_reddit_resume_upload_public_url((string) ($upload['file_path'] ?? ''));
            if ($upload_url === '') {
                return;
            }

            $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
            if (!is_array($documents)) {
                $documents = [];
            }

            foreach ($documents as &$document) {
                if (($document['document_type'] ?? '') === 'resume_cv') {
                    $document['document_type'] = 'supporting';
                }
            }
            unset($document);

            $documents[] = [
                'name' => sanitize_file_name((string) ($upload['file_name'] ?? 'resume.txt')),
                'url' => $upload_url,
                'uploaded' => sanitize_text_field((string) ($upload['upload_date'] ?? current_time('mysql'))),
                'document_type' => 'resume_cv',
            ];

            update_user_meta($user_id, 'sffc_crm_documents', array_values($documents));
        }

        private function ensure_crm_editorial_onboarding_campaign_table($table)
        {
            global $wpdb;

            require_once ABSPATH . 'wp-admin/includes/upgrade.php';

            $charset_collate = $wpdb->get_charset_collate();
            $sql = "CREATE TABLE {$table} (
                id bigint(20) NOT NULL AUTO_INCREMENT,
                user_id bigint(20) NOT NULL,
                post_id bigint(20) NOT NULL,
                recruiter_id bigint(20) NOT NULL DEFAULT 0,
                recruiter_name varchar(255) DEFAULT NULL,
                recruiter_email varchar(255) DEFAULT NULL,
                recruiter_linkedin varchar(500) DEFAULT NULL,
                company_name varchar(255) DEFAULT NULL,
                role_title varchar(255) DEFAULT NULL,
                status varchar(50) DEFAULT 'pending_review',
                admin_message text DEFAULT NULL,
                recruiter_reply text DEFAULT NULL,
                tracking_status varchar(50) DEFAULT 'applied',
                materials_requested text DEFAULT NULL,
                materials_status varchar(50) DEFAULT 'not_requested',
                cover_letter_url text DEFAULT NULL,
                resume_url text DEFAULT NULL,
                email_template text DEFAULT NULL,
                criteria_id bigint(20) DEFAULT NULL,
                cv_file_id bigint(20) DEFAULT NULL,
                cover_letter_file_id bigint(20) DEFAULT NULL,
                application_url text DEFAULT NULL,
                source_action varchar(80) DEFAULT NULL,
                queue_status varchar(50) DEFAULT NULL,
                queue_position int(11) DEFAULT 0,
                submitted_at datetime DEFAULT NULL,
                user_queue_confirmation_sent_at datetime DEFAULT NULL,
                user_queue_digest_scheduled_at datetime DEFAULT NULL,
                user_queue_digest_sent_at datetime DEFAULT NULL,
                confirmation_sent_at datetime DEFAULT NULL,
                resume_sent_at datetime DEFAULT NULL,
                cover_letter_sent_at datetime DEFAULT NULL,
                request_type varchar(50) DEFAULT NULL,
                target_role varchar(255) DEFAULT NULL,
                target_location varchar(255) DEFAULT NULL,
                target_seniority varchar(255) DEFAULT NULL,
                stored_cv_url text DEFAULT NULL,
                stored_cv_name varchar(255) DEFAULT NULL,
                target_company varchar(255) DEFAULT NULL,
                target_sector varchar(255) DEFAULT NULL,
                intro_context text DEFAULT NULL,
                reached_recruiters longtext DEFAULT NULL,
                campaign_admin_notes longtext DEFAULT NULL,
                created_at datetime DEFAULT CURRENT_TIMESTAMP,
                updated_at datetime DEFAULT NULL,
                PRIMARY KEY  (id),
                UNIQUE KEY unique_user_post (user_id, post_id)
            ) {$charset_collate};";

            dbDelta($sql);
            $this->ensure_crm_editorial_onboarding_campaign_columns($table);
        }

        private function ensure_crm_editorial_onboarding_campaign_columns($table)
        {
            global $wpdb;

            $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
            if (!is_array($columns)) {
                return;
            }

            $required_columns = [
                'request_type' => "ALTER TABLE {$table} ADD COLUMN request_type varchar(50) DEFAULT NULL",
                'target_role' => "ALTER TABLE {$table} ADD COLUMN target_role varchar(255) DEFAULT NULL",
                'target_location' => "ALTER TABLE {$table} ADD COLUMN target_location varchar(255) DEFAULT NULL",
                'target_seniority' => "ALTER TABLE {$table} ADD COLUMN target_seniority varchar(255) DEFAULT NULL",
                'stored_cv_url' => "ALTER TABLE {$table} ADD COLUMN stored_cv_url text DEFAULT NULL",
                'stored_cv_name' => "ALTER TABLE {$table} ADD COLUMN stored_cv_name varchar(255) DEFAULT NULL",
                'target_company' => "ALTER TABLE {$table} ADD COLUMN target_company varchar(255) DEFAULT NULL",
                'target_sector' => "ALTER TABLE {$table} ADD COLUMN target_sector varchar(255) DEFAULT NULL",
                'intro_context' => "ALTER TABLE {$table} ADD COLUMN intro_context text DEFAULT NULL",
                'reached_recruiters' => "ALTER TABLE {$table} ADD COLUMN reached_recruiters longtext DEFAULT NULL",
                'campaign_admin_notes' => "ALTER TABLE {$table} ADD COLUMN campaign_admin_notes longtext DEFAULT NULL",
            ];

            foreach ($required_columns as $column => $sql) {
                if (!in_array($column, $columns, true)) {
                    $wpdb->query($sql);
                }
            }
        }

        private function store_crm_editorial_onboarding_cv($user_id, array $file)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return new WP_Error('invalid_user', __('We could not identify your account.', 'senna-finance'));
            }

            if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
                return new WP_Error('upload_error', __('The CV upload failed. Please try again.', 'senna-finance'));
            }

            $allowed_mimes = [
                'pdf' => 'application/pdf',
                'doc' => 'application/msword',
                'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                'txt' => 'text/plain',
            ];

            $extension = strtolower((string) pathinfo((string) ($file['name'] ?? ''), PATHINFO_EXTENSION));
            if (!isset($allowed_mimes[$extension])) {
                return new WP_Error('invalid_type', __('Please upload a PDF, DOC, DOCX, or TXT file.', 'senna-finance'));
            }

            require_once ABSPATH . 'wp-admin/includes/file.php';
            $uploaded = wp_handle_upload($file, [
                'test_form' => false,
                'mimes' => $allowed_mimes,
            ]);

            if (!empty($uploaded['error'])) {
                return new WP_Error('upload_failed', sanitize_text_field((string) $uploaded['error']));
            }

            $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
            if (!is_array($documents)) {
                $documents = [];
            }

            foreach ($documents as &$document) {
                if (($document['document_type'] ?? '') === 'resume_cv') {
                    $document['document_type'] = 'supporting';
                }
            }
            unset($document);

            $stored_document = [
                'name' => sanitize_file_name((string) ($file['name'] ?? basename((string) ($uploaded['file'] ?? 'resume')))),
                'url' => esc_url_raw((string) ($uploaded['url'] ?? '')),
                'uploaded' => current_time('mysql'),
                'document_type' => 'resume_cv',
                '_file_path' => !empty($uploaded['file']) ? (string) $uploaded['file'] : '',
            ];

            $documents[] = $stored_document;

            update_user_meta($user_id, 'sffc_crm_documents', array_values($documents));

            return $stored_document;
        }

        private function send_crm_editorial_onboarding_cv_admin_email($user_id, array $stored_document, array $data)
        {
            $user_id = (int) $user_id;
            $user = $user_id > 0 ? get_userdata($user_id) : false;
            $admin_email = (string) apply_filters('sffc_crm_editorial_onboarding_cv_admin_email', get_option('admin_email'), $user_id, $stored_document, $data);

            if ($admin_email === '' || !is_email($admin_email)) {
                return false;
            }

            $display_name = $user instanceof WP_User && $user->display_name !== ''
                ? $user->display_name
                : __('MENA Careers member', 'senna-finance');
            $user_email = $user instanceof WP_User ? (string) $user->user_email : '';
            $target_role = sanitize_text_field((string) ($data['ideal_role'] ?? ''));
            $location = sanitize_text_field((string) ($data['location'] ?? ''));
            $file_name = sanitize_file_name((string) ($stored_document['name'] ?? 'CV'));
            $file_url = esc_url_raw((string) ($stored_document['url'] ?? ''));
            $file_path = $this->get_crm_editorial_onboarding_cv_file_path($stored_document);
            $attachments = $file_path !== '' ? [$file_path] : [];

            $subject_parts = array_filter([
                __('New onboarding CV upload', 'senna-finance'),
                $target_role,
                $display_name,
            ]);
            $subject = implode(' - ', $subject_parts);

            $target_role_items = !empty($data['target_role_items']) && is_array($data['target_role_items'])
                ? $data['target_role_items']
                : [];
            $role_lines = [];
            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [];
            foreach ($target_role_items as $role_item) {
                if (!is_array($role_item)) {
                    continue;
                }

                $role_label = sanitize_text_field((string) ($role_item['role'] ?? ''));
                $sector_key = sanitize_key((string) ($role_item['sector'] ?? ''));
                $sector_label = isset($sector_options[$sector_key]) ? (string) $sector_options[$sector_key] : $sector_key;
                $role_lines[] = trim($role_label . ($sector_label !== '' ? ' - ' . sanitize_text_field($sector_label) : ''));
            }

            $message = '<div style="margin:0;padding:0;background:#f7f5ef;">'
                . '<div style="max-width:680px;margin:0 auto;padding:34px 22px;font-family:Arial,Helvetica,sans-serif;color:#111827;">'
                . '<div style="background:#ffffff;border:1px solid #e5e1d8;border-radius:18px;overflow:hidden;">'
                . '<div style="padding:28px 30px;background:#0d1d42;color:#ffffff;">'
                . '<div style="font-family:Georgia,serif;font-size:30px;line-height:1;color:#fffdf9;">MENA Careers</div>'
                . '<div style="margin-top:16px;font-size:13px;letter-spacing:0.16em;text-transform:uppercase;color:#d6bc7e;">Editorial onboarding</div>'
                . '<h1 style="margin:8px 0 0;font-size:28px;line-height:1.12;color:#ffffff;">New CV uploaded</h1>'
                . '</div>'
                . '<div style="padding:28px 30px;">'
                . '<p style="margin:0 0 18px;font-size:16px;line-height:1.65;color:#374151;">A user uploaded a CV during the editorial onboarding flow. The actual file is attached to this email where the upload is available locally.</p>'
                . '<table style="width:100%;border-collapse:collapse;font-size:15px;line-height:1.5;">'
                . '<tr><td style="padding:10px 0;color:#6b7280;width:160px;">User</td><td style="padding:10px 0;color:#111827;font-weight:700;">' . esc_html($display_name) . '</td></tr>'
                . ($user_email !== '' ? '<tr><td style="padding:10px 0;color:#6b7280;">Email</td><td style="padding:10px 0;"><a href="mailto:' . esc_attr($user_email) . '" style="color:#0d1d42;">' . esc_html($user_email) . '</a></td></tr>' : '')
                . ($target_role !== '' ? '<tr><td style="padding:10px 0;color:#6b7280;">Target role</td><td style="padding:10px 0;color:#111827;">' . esc_html($target_role) . '</td></tr>' : '')
                . ($location !== '' ? '<tr><td style="padding:10px 0;color:#6b7280;">Location</td><td style="padding:10px 0;color:#111827;">' . esc_html($location) . '</td></tr>' : '')
                . '<tr><td style="padding:10px 0;color:#6b7280;">CV file</td><td style="padding:10px 0;color:#111827;">' . esc_html($file_name) . '</td></tr>'
                . ($file_url !== '' ? '<tr><td style="padding:10px 0;color:#6b7280;">File URL</td><td style="padding:10px 0;"><a href="' . esc_url($file_url) . '" style="color:#0d1d42;">Open stored CV</a></td></tr>' : '')
                . '</table>';

            if (!empty($role_lines)) {
                $message .= '<div style="margin-top:22px;padding:18px;border-left:4px solid #0d1d42;background:#fbfaf7;">'
                    . '<div style="margin:0 0 8px;font-size:12px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:#6b7280;">Role priorities</div>'
                    . '<ul style="margin:0;padding-left:18px;color:#111827;">';
                foreach ($role_lines as $role_line) {
                    $message .= '<li style="margin:6px 0;">' . esc_html($role_line) . '</li>';
                }
                $message .= '</ul></div>';
            }

            if (empty($attachments)) {
                $message .= '<p style="margin:22px 0 0;font-size:14px;line-height:1.6;color:#92400e;">The file could not be attached from the local uploads path, so use the stored CV URL above.</p>';
            }

            $message .= '</div></div></div></div>';

            $headers = ['Content-Type: text/html; charset=UTF-8'];
            if ($user_email !== '' && is_email($user_email)) {
                $headers[] = sprintf('Reply-To: %s <%s>', $display_name, $user_email);
            }

            $sent = wp_mail($admin_email, $subject, $message, $headers, $attachments);
            if (!$sent && function_exists('error_log')) {
                error_log(sprintf('SFFC onboarding CV admin email failed for user %d.', $user_id));
            }

            return $sent;
        }

        private function get_crm_editorial_onboarding_cv_file_path(array $stored_document)
        {
            $file_path = wp_normalize_path((string) ($stored_document['_file_path'] ?? ''));
            if ($file_path !== '' && is_readable($file_path)) {
                return $file_path;
            }

            $url = (string) ($stored_document['url'] ?? '');
            if ($url === '') {
                return '';
            }

            $upload_dir = wp_upload_dir();
            $base_url = (string) ($upload_dir['baseurl'] ?? '');
            $base_dir = wp_normalize_path((string) ($upload_dir['basedir'] ?? ''));
            if ($base_url === '' || $base_dir === '' || strpos($url, $base_url) !== 0) {
                return '';
            }

            $relative_path = ltrim(substr($url, strlen($base_url)), '/');
            if ($relative_path === '') {
                return '';
            }

            $candidate = wp_normalize_path(trailingslashit($base_dir) . $relative_path);
            return is_readable($candidate) ? $candidate : '';
        }

