        private function get_crm_editorial_community_trending_companies(array $feed_items, $limit = 5)
        {
            $limit = max(1, min(8, (int) $limit));
            $store = $this->get_crm_editorial_company_click_store();
            $companies = [];

            foreach ($store as $key => $entry) {
                if (!is_array($entry)) {
                    continue;
                }

                $company_name = trim((string) ($entry['company_name'] ?? ''));
                if ($company_name === '') {
                    continue;
                }

                $companies[$key] = [
                    'company_name' => $company_name,
                    'logo' => esc_url_raw((string) ($entry['logo'] ?? '')),
                    'clicks' => max(0, (int) ($entry['clicks'] ?? 0)),
                    'last_clicked' => trim((string) ($entry['last_clicked'] ?? '')),
                ];
            }

            foreach ($feed_items as $item) {
                $item = (array) $item;
                $company_name = trim((string) ($item['company'] ?? ''));
                if ($company_name === '') {
                    continue;
                }

                $key = $this->get_crm_editorial_company_click_key($company_name);
                if ($key === '') {
                    continue;
                }

                if (!isset($companies[$key])) {
                    $companies[$key] = [
                        'company_name' => $company_name,
                        'logo' => esc_url_raw((string) ($item['company_logo'] ?? '')),
                        'clicks' => 0,
                        'last_clicked' => '',
                    ];
                } elseif ($companies[$key]['logo'] === '' && !empty($item['company_logo'])) {
                    $companies[$key]['logo'] = esc_url_raw((string) $item['company_logo']);
                }
            }

            uasort($companies, static function ($left, $right) {
                $leftClicks = (int) ($left['clicks'] ?? 0);
                $rightClicks = (int) ($right['clicks'] ?? 0);
                if ($leftClicks !== $rightClicks) {
                    return $rightClicks <=> $leftClicks;
                }

                $leftTime = strtotime((string) ($left['last_clicked'] ?? '')) ?: 0;
                $rightTime = strtotime((string) ($right['last_clicked'] ?? '')) ?: 0;
                if ($leftTime !== $rightTime) {
                    return $rightTime <=> $leftTime;
                }

                return strcasecmp((string) ($left['company_name'] ?? ''), (string) ($right['company_name'] ?? ''));
            });

            return array_slice(array_values($companies), 0, $limit);
        }

        private function get_crm_editorial_community_featured_resources($limit = 5, $is_logged_in = false)
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-resource-library.php';

            $resource_model = new SFFC_CRM_Resource_Library();
            $resources = $resource_model->get_all([
                'is_active' => 1,
                'is_featured' => 1,
                'limit' => max(1, min(8, (int) $limit)),
            ]);

            if (empty($resources)) {
                return [];
            }

            $items = [];
            foreach ((array) $resources as $resource) {
                $title = trim((string) ($resource['title'] ?? ''));
                if ($title === '') {
                    continue;
                }

                $access_level = sanitize_key((string) ($resource['access_level'] ?? 'free'));
                $is_locked = !$is_logged_in && $access_level !== 'free';
                $href = $is_locked
                    ? home_url('/join/')
                    : (trim((string) ($resource['resource_url'] ?? '')) !== '' ? (string) $resource['resource_url'] : '#');
                $description = trim((string) ($resource['description'] ?? ''));
                $category = trim((string) ($resource['category'] ?? ''));
                $type_label = strtoupper((string) ($resource['resource_type'] ?? 'link'));
                $author = $category !== '' ? $category : __('Resource Library', 'senna-finance');
                $author_initial = function_exists('mb_substr')
                    ? mb_strtoupper(mb_substr($author, 0, 1))
                    : strtoupper(substr($author, 0, 1));

                $items[] = [
                    'title' => $title,
                    'description' => $description !== '' ? $description : __('Featured private equity resource from the MENA Careers library.', 'senna-finance'),
                    'thumbnail_url' => trim((string) ($resource['thumbnail_url'] ?? '')),
                    'href' => $href,
                    'external' => !$is_locked && $href !== '#' && strpos($href, home_url('/')) !== 0,
                    'link_label' => $is_locked ? __('Unlock resource', 'senna-finance') : __('Open resource', 'senna-finance'),
                    'author' => $author,
                    'author_image' => '',
                    'author_initial' => $author_initial !== '' ? $author_initial : 'S',
                    'teaser_title' => wp_trim_words($title, 7, '...'),
                    'teaser_meta' => trim($author . ' • ' . $type_label),
                ];
            }

            return $items;
        }

        private function get_crm_editorial_community_showcase_roles(array $feed_items, $limit = 5, array $pinned_item = [])
        {
            $limit = max(1, min(8, (int) $limit));
            $feed_items = $this->sort_crm_editorial_community_feed_items_by_recent($feed_items);
            $items = [];
            $seen = [];

            $append_item = function (array $item, $is_pinned_current_role = false) use (&$items, &$seen, $limit) {
                if (count($items) >= $limit) {
                    return;
                }

                $role_title = trim((string) ($item['role_title'] ?? ''));
                if ($role_title === '') {
                    return;
                }

                $crm_post_id = (int) ($item['crm_post_id'] ?? $item['post_id'] ?? $item['id'] ?? 0);
                $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                $dedupe_key = $crm_post_id > 0
                    ? 'crm:' . $crm_post_id
                    : ($wp_post_id > 0 ? 'wp:' . $wp_post_id : 'role:' . md5(strtolower($role_title . '|' . (string) ($item['company'] ?? ''))));
                if (isset($seen[$dedupe_key])) {
                    return;
                }
                $seen[$dedupe_key] = true;

                $company = trim((string) ($item['company'] ?? ''));
                $location = trim((string) ($item['location'] ?? ''));
                $sector = trim((string) ($item['sector'] ?? ''));
                $meta_bits = array_values(array_filter([$company, $location, $sector]));
                $description = trim((string) ($item['excerpt'] ?? ''));
                if ($description === '') {
                    $description = trim((string) ($item['description_preview'] ?? ''));
                }

                $thumbnail_url = trim((string) ($item['company_logo'] ?? ''));
                if ($thumbnail_url === '') {
                    $thumbnail_url = trim((string) ($item['recruiter_photo'] ?? ''));
                }

                $teaser_meta = trim(implode(' • ', array_filter([
                    trim((string) ($item['posted_label'] ?? '')),
                    $company,
                ])));
                if ($teaser_meta === '') {
                    $teaser_meta = __('Recent role', 'senna-finance');
                }

                $author = trim((string) ($item['recruiter_name'] ?? $company));
                $author_initial = function_exists('mb_substr')
                    ? mb_strtoupper(mb_substr($author !== '' ? $author : 'S', 0, 1))
                    : strtoupper(substr($author !== '' ? $author : 'S', 0, 1));
                $href = $this->get_crm_editorial_community_public_opportunity_url($item, $role_title, $company);
                $is_internal_post = ($crm_post_id > 0 || $wp_post_id > 0) && $href !== '#';

                $items[] = [
                    'title' => $role_title,
                    'description' => $description !== '' ? $description : implode(' • ', $meta_bits),
                    'thumbnail_url' => $thumbnail_url,
                    'href' => $href,
                    'external' => false,
                    'open_new_tab' => !$is_internal_post,
                    'crm_post_id' => $crm_post_id,
                    'signup_overlay_detectable' => $is_internal_post,
                    'author' => $author,
                    'author_image' => $thumbnail_url,
                    'author_initial' => $author_initial !== '' ? $author_initial : 'S',
                    'company_name' => $company,
                    'company_logo' => trim((string) ($item['company_logo'] ?? '')),
                    'teaser_title' => wp_trim_words($role_title, 7, '...'),
                    'teaser_meta' => $teaser_meta,
                    'is_pinned_current_role' => (bool) $is_pinned_current_role,
                ];
            };

            if (!empty($pinned_item)) {
                $append_item($pinned_item, true);
            }

            foreach ($feed_items as $item) {
                $append_item((array) $item, false);
                if (count($items) >= $limit) {
                    break;
                }
            }

            return $items;
        }

        private function get_crm_editorial_community_public_opportunity_url(array $item, $role_title = '', $company = '')
        {
            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                $permalink = get_permalink($wp_post_id);
                if ($permalink) {
                    return esc_url_raw($permalink);
                }
            }

            $view_url = trim((string) ($item['view_url'] ?? ''));
            if ($view_url !== '' && strpos($view_url, '/crm-opportunity/') === false) {
                return esc_url_raw($view_url);
            }

            $slug_seed = sanitize_title(trim((string) $role_title . ' ' . (string) $company));
            if ($slug_seed === '') {
                $slug_seed = sanitize_title((string) ($item['role_title'] ?? __('opportunity', 'senna-finance')));
            }

            return $slug_seed !== ''
                ? esc_url_raw(home_url('/opportunity/' . $slug_seed . '/'))
                : '#';
        }

        private function get_crm_editorial_community_template_resources($limit = 10, $is_logged_in = false)
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-resource-library.php';

            $resource_model = new SFFC_CRM_Resource_Library();
            $resources = $resource_model->get_all([
                'is_active' => 1,
                'limit' => max(4, min(16, (int) $limit)),
            ]);

            if (empty($resources)) {
                return [];
            }

            $items = [];
            foreach ((array) $resources as $resource) {
                $title = trim((string) ($resource['title'] ?? ''));
                if ($title === '') {
                    continue;
                }

                $access_level = sanitize_key((string) ($resource['access_level'] ?? 'free'));
                $is_locked = !$is_logged_in && $access_level !== 'free';
                $resource_url = trim((string) ($resource['resource_url'] ?? ''));
                $href = $is_locked
                    ? home_url('/join/')
                    : ($resource_url !== '' ? $resource_url : '#');
                $description = trim((string) ($resource['description'] ?? ''));
                $resource_type = sanitize_key((string) ($resource['resource_type'] ?? 'link'));
                $category = trim((string) ($resource['category'] ?? ''));
                $type_label = strtoupper($resource_type !== '' ? $resource_type : 'LINK');
                $kicker = $category !== '' ? $category : $type_label;

                $items[] = [
                    'title' => $title,
                    'description' => $description !== '' ? wp_trim_words($description, 32, '...') : __('Career resource from the Senna library.', 'senna-finance'),
                    'thumbnail_url' => trim((string) ($resource['thumbnail_url'] ?? '')),
                    'href' => $href,
                    'external' => !$is_locked && $href !== '#' && strpos($href, home_url('/')) !== 0,
                    'kicker' => $kicker,
                    'type_label' => $type_label,
                    'related' => [],
                ];
            }

            if (count($items) > 1) {
                foreach ($items as $index => $item) {
                    if ($index > 1) {
                        break;
                    }

                    $related_items = [];
                    foreach ($items as $related_index => $related_item) {
                        if ($related_index === $index) {
                            continue;
                        }
                        $related_items[] = [
                            'title' => $related_item['title'],
                            'href' => $related_item['href'],
                            'external' => $related_item['external'],
                        ];
                        if (count($related_items) >= 2) {
                            break;
                        }
                    }
                    $items[$index]['related'] = $related_items;
                }
            }

            return $items;
        }

        private function get_crm_editorial_community_recruiters($user_id = 0, $limit = 5)
        {
            $payload = $this->get_crm_editorial_community_recruiters_result(250, 0, [], []);
            $items = (array) ($payload['items'] ?? []);
            if (empty($items)) {
                return [];
            }

            $items = $this->randomize_crm_editorial_community_recruiter_rail_items($items);
            return array_slice($items, 0, max(1, (int) $limit));
        }

        private function randomize_crm_editorial_community_recruiter_rail_items(array $items)
        {
            if (count($items) <= 1) {
                return $items;
            }

            $buckets = [
                0 => [],
                1 => [],
                2 => [],
                3 => [],
            ];

            foreach ($items as $item) {
                $priority = $this->get_crm_editorial_discovery_region_priority(
                    $this->build_crm_editorial_discovery_geo_haystack((array) $item)
                );
                if (!isset($buckets[$priority])) {
                    $buckets[$priority] = [];
                }
                $buckets[$priority][] = $item;
            }

            foreach ($buckets as $priority => $bucket_items) {
                if (count($bucket_items) > 1) {
                    shuffle($bucket_items);
                }
                $buckets[$priority] = $bucket_items;
            }

            return array_merge(
                $buckets[0] ?? [],
                $buckets[1] ?? [],
                $buckets[2] ?? [],
                $buckets[3] ?? []
            );
        }

        private function get_crm_editorial_community_recruiter_rail_items_for_location(array $items, $location_label = '', $limit = 5)
        {
            $limit = max(1, (int) $limit);
            if (empty($items)) {
                return [];
            }

            $location_label = $this->get_crm_editorial_community_known_location_label((string) $location_label);
            if ($location_label === '') {
                return array_slice($this->randomize_crm_editorial_community_recruiter_rail_items($items), 0, $limit);
            }

            $location_aliases = $this->get_crm_editorial_community_location_heading_aliases();
            $aliases = array_map('strtolower', (array) ($location_aliases[$location_label] ?? [$location_label]));
            $location_matches = [];
            $other_items = [];

            foreach ($items as $item) {
                $haystack = $this->build_crm_editorial_discovery_geo_haystack((array) $item);
                $is_match = false;

                foreach ($aliases as $alias) {
                    if ($alias !== '' && strpos($haystack, $alias) !== false) {
                        $is_match = true;
                        break;
                    }
                }

                if ($is_match) {
                    $location_matches[] = $item;
                } else {
                    $other_items[] = $item;
                }
            }

            $location_matches = $this->randomize_crm_editorial_community_recruiter_rail_items($location_matches);
            $other_items = $this->randomize_crm_editorial_community_recruiter_rail_items($other_items);

            return array_slice(array_merge($location_matches, $other_items), 0, $limit);
        }

        private function get_crm_editorial_community_recruiters_result($limit = 5, $offset = 0, array $filters = [], array $exclude_ids = [])
        {
            $requested_limit = max(1, min(24, (int) $limit));
            $offset = max(0, (int) $offset);
            $filters = [
                'search' => trim((string) ($filters['search'] ?? '')),
                'location' => trim((string) ($filters['location'] ?? 'all')),
                'industry' => trim((string) ($filters['industry'] ?? 'all')),
                'role' => trim((string) ($filters['role'] ?? 'all')),
            ];
            $exclude_ids = array_values(array_filter(array_map('absint', $exclude_ids)));
            $items = $this->get_crm_editorial_community_recruiter_source_items();

            if (!empty($items)) {
                $items = $this->randomize_crm_editorial_community_recruiter_rail_items($items);
            }

            if (!empty($exclude_ids)) {
                $items = array_values(array_filter($items, function ($item) use ($exclude_ids) {
                    return !in_array((int) ($item['id'] ?? 0), $exclude_ids, true);
                }));
            }

            $items = array_values(array_filter($items, function ($item) use ($filters) {
                return $this->does_crm_editorial_discovery_item_match_filters((array) $item, $filters);
            }));

            return [
                'items' => array_slice($items, $offset, $requested_limit),
                'has_more' => count($items) > ($offset + $requested_limit),
            ];
        }

        private function get_crm_editorial_community_recruiter_source_items()
        {
            $cache_key = 'sffc_crm_editorial_recruiter_source_v4';
            $cached = get_transient($cache_key);
            if (is_array($cached)) {
                return $cached;
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-outreach.php';

            $hr_model = new SFFC_CRM_HR_Outreach();
            $records = $hr_model->get_all([
                'limit' => 250,
                'offset' => 0,
            ]);

            if (empty($records)) {
                return [];
            }

            $items = [];
            foreach ((array) $records as $record) {
                $record = is_array($record) ? $record : [];

                $name = trim((string) ($record['contact_name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $company = trim((string) ($record['company_name'] ?? ''));
                $title = trim((string) ($record['contact_title'] ?? ''));
                $email = sanitize_email((string) ($record['contact_email'] ?? ''));
                $phone = sanitize_text_field((string) ($record['contact_phone'] ?? ''));
                $linkedin = esc_url_raw((string) ($record['contact_linkedin'] ?? ''));
                $photo = esc_url_raw((string) ($record['contact_photo'] ?? ''));
                $location = trim((string) ($record['location'] ?? ''));
                $regions = trim((string) ($record['regions'] ?? ''));
                $location_region = $this->normalize_crm_editorial_discovery_location_label($location, $regions);

                $program_types = $this->get_crm_editorial_discovery_role_values_from_record($record);
                $industry_values = $this->get_crm_editorial_discovery_industry_values_from_record($record);
                $process = array_filter(array_map('sanitize_key', (array) ($record['process'] ?? [])));
                $skills = array_filter(array_map('sanitize_key', (array) ($record['skills'] ?? [])));
                $last_hire_proof = trim(wp_strip_all_tags((string) ($record['last_hire_proof'] ?? '')));
                $notes = trim(wp_strip_all_tags((string) ($record['notes'] ?? '')));

                $items[] = [
                    'id' => (int) ($record['id'] ?? 0),
                    'name' => $name,
                    'firm' => $company,
                    'title' => $title,
                    'email' => $email,
                    'phone' => $phone,
                    'linkedin_url' => $linkedin,
                    'photo_url' => $photo,
                    'location' => $location_region,
                    'location_primary' => $location_region !== '' ? $location_region : ($location !== '' ? $location : $regions),
                    'regions' => $regions,
                    'industry' => $industry_values,
                    'industry_values' => implode('|', $industry_values),
                    'program_types' => $program_types,
                    'role_values' => implode('|', $program_types),
                    'process' => $process,
                    'skills' => $skills,
                    'sector' => implode('|', $industry_values),
                    'role_focus' => trim(wp_strip_all_tags((string) ($record['role_focus'] ?? ''))),
                    'last_hire_proof' => $last_hire_proof,
                    'notes' => $notes,
                    'source_context' => sanitize_key((string) ($record['source_context'] ?? '')),
                ];
            }

            if (count($items) > 1) {
                usort($items, function ($left, $right) {
                    $left_priority = $this->get_crm_editorial_discovery_region_priority(
                        $this->build_crm_editorial_discovery_geo_haystack((array) $left)
                    );
                    $right_priority = $this->get_crm_editorial_discovery_region_priority(
                        $this->build_crm_editorial_discovery_geo_haystack((array) $right)
                    );

                    if ($left_priority !== $right_priority) {
                        return $left_priority <=> $right_priority;
                    }

                    $left_company = strtolower(trim((string) ($left['firm'] ?? '')));
                    $right_company = strtolower(trim((string) ($right['firm'] ?? '')));
                    if ($left_company !== $right_company) {
                        return $left_company <=> $right_company;
                    }

                    return strcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
                });
            }

            set_transient($cache_key, $items, 5 * MINUTE_IN_SECONDS);

            return $items;
        }

        private function normalize_crm_editorial_discovery_location_label($location, $regions = '')
        {
            $location = trim((string) $location);
            $regions = trim((string) $regions);
            $haystack = strtolower(trim(implode(' ', array_filter([$location, $regions]))));

            $location_map = [
                'London, UK' => ['london, uk', 'london, united kingdom', 'london'],
                'Paris, France' => ['paris, france', 'paris'],
                'Milan, Italy' => ['milan, italy', 'milan'],
                'Amsterdam, Netherlands' => ['amsterdam, netherlands', 'amsterdam'],
                'Dubai, UAE' => ['dubai, uae', 'dubai, united arab emirates', 'dubai'],
                'Doha, Qatar' => ['doha, qatar', 'doha'],
                'United Kingdom' => ['united kingdom', 'uk', 'great britain', 'england'],
                'France' => ['france'],
                'Italy' => ['italy'],
                'Netherlands' => ['netherlands'],
                'UAE' => ['united arab emirates', 'u.a.e', 'uae'],
                'Qatar' => ['qatar'],
            ];

            foreach ($location_map as $label => $aliases) {
                foreach ($aliases as $alias) {
                    if ($alias !== '' && strpos($haystack, strtolower($alias)) !== false) {
                        return $label;
                    }
                }
            }

            if ($location !== '') {
                $normalized = str_replace(
                    ['United Arab Emirates', 'United Kingdom'],
                    ['UAE', 'UK'],
                    $location
                );
                return sanitize_text_field(trim((string) $normalized));
            }

            if ($regions !== '') {
                $normalized = str_replace(
                    ['United Arab Emirates', 'United Kingdom'],
                    ['UAE', 'UK'],
                    $regions
                );
                return sanitize_text_field(trim((string) $normalized));
            }

            return '';
        }

        private function normalize_crm_editorial_discovery_industry_value($value)
        {
            $normalized = sanitize_key((string) $value);
            if ($normalized === '') {
                return '';
            }

            $map = [
                'investment_banking' => ['investment_banking', 'investment banking', 'ib'],
                'private_equity' => ['private_equity', 'private equity', 'pe'],
                'family_office' => ['family_office', 'family office'],
                'venture_capital' => ['venture_capital', 'venture capital', 'vc'],
                'consulting' => ['consulting', 'consultancy'],
                'asset_management' => ['asset_management', 'asset management', 'asset mgmt'],
                'wealth_management' => ['wealth_management', 'wealth management'],
                'boutique' => ['boutique', 'boutiques'],
                'technology' => ['technology', 'tech'],
                'fintech' => ['fintech', 'fin_tech'],
                'investment_management' => ['investment_management', 'investment management'],
                'corporate_finance' => ['corporate_finance', 'corporate finance'],
                'accounting' => ['accounting', 'accountancy'],
                'other' => ['other'],
            ];

            foreach ($map as $canonical => $aliases) {
                foreach ($aliases as $alias) {
                    if ($normalized === sanitize_key((string) $alias)) {
                        return $canonical;
                    }
                }
            }

            return $normalized;
        }

        private function get_crm_editorial_discovery_industry_values_from_record(array $record)
        {
            $values = [];

            foreach ((array) ($record['industry'] ?? []) as $industry_value) {
                $normalized = $this->normalize_crm_editorial_discovery_industry_value($industry_value);
                if ($normalized !== '') {
                    $values[$normalized] = $normalized;
                }
            }

            return array_values($values);
        }

        private function get_crm_editorial_discovery_role_values_from_record(array $record)
        {
            $roles = [];

            foreach ((array) ($record['program_types'] ?? []) as $program_type) {
                $program_type = sanitize_key((string) $program_type);
                if (in_array($program_type, ['analyst', 'associate', 'senior', 'executive', 'other'], true)) {
                    $roles[$program_type] = $program_type;
                }
            }

            if (!empty($record['hire_interns']) || !empty($record['hire_graduates']) || !empty($record['hire_trainee']) || !empty($record['hire_placement']) || !empty($record['hire_analysts'])) {
                $roles['analyst'] = 'analyst';
            }
            if (!empty($record['hire_associates'])) {
                $roles['associate'] = 'associate';
            }
            if (!empty($record['hire_seniors'])) {
                $roles['senior'] = 'senior';
            }
            if (empty($roles) && !empty($record['hire_private_equity_candidates'])) {
                $roles['other'] = 'other';
            }

            return array_values($roles);
        }

        private function does_crm_editorial_discovery_item_match_filters(array $item, array $filters = [])
        {
            $search = strtolower(trim((string) ($filters['search'] ?? '')));
            $location = strtolower(trim((string) ($filters['location'] ?? 'all')));
            $industry = sanitize_key((string) ($filters['industry'] ?? 'all'));
            $role = strtolower(trim((string) ($filters['role'] ?? 'all')));

            $searchIndex = strtolower(trim(implode(' ', array_filter([
                (string) ($item['name'] ?? ''),
                (string) ($item['title'] ?? ''),
                (string) ($item['firm'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['role_focus'] ?? ''),
                implode(' ', (array) ($item['industry'] ?? [])),
                implode(' ', (array) ($item['program_types'] ?? [])),
            ]))));

            if ($search !== '') {
                $tokens = array_values(array_filter(explode(' ', preg_replace('/\s+/', ' ', $search))));
                if (strpos($searchIndex, $search) === false) {
                    foreach ($tokens as $token) {
                        if (strpos($searchIndex, $token) === false) {
                            return false;
                        }
                    }
                }
            }

            if ($location !== '' && $location !== 'all') {
                $itemLocation = strtolower(trim((string) ($item['location'] ?? '')));
                if ($itemLocation === '' || (strpos($itemLocation, $location) === false && strpos($location, $itemLocation) === false)) {
                    return false;
                }
            }

            if ($industry !== '' && $industry !== 'all') {
                $itemIndustries = array_filter(array_map('sanitize_key', (array) ($item['industry'] ?? [])));
                if (!in_array($industry, $itemIndustries, true)) {
                    return false;
                }
            }

            if ($role !== '' && $role !== 'all') {
                $itemRoles = array_filter(array_map('sanitize_key', (array) ($item['program_types'] ?? [])));
                if (empty($itemRoles) || !in_array(sanitize_key($role), $itemRoles, true)) {
                    return false;
                }
            }

            return true;
        }

        private function render_crm_editorial_discovery_card(array $recruiter_item)
        {
            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $has_premium_access = $is_logged_in && $this->current_user_has_crm_editorial_paid_membership_access();
            $recruiter_item = is_array($recruiter_item) ? $recruiter_item : [];
            $discovery_name = trim((string) ($recruiter_item['name'] ?? ''));
            $discovery_display_name = $has_premium_access ? $discovery_name : $this->format_crm_reddit_recruiter_short_name($discovery_name);
            $discovery_title = trim((string) ($recruiter_item['title'] ?? ''));
            $discovery_firm = trim((string) ($recruiter_item['firm'] ?? ''));
            $discovery_photo = esc_url_raw((string) ($recruiter_item['photo_url'] ?? ''));
            $discovery_linkedin = esc_url_raw((string) ($recruiter_item['linkedin_url'] ?? ''));
            $discovery_email = sanitize_email((string) ($recruiter_item['email'] ?? ''));
            $discovery_phone = trim((string) ($recruiter_item['phone'] ?? ''));
            $discovery_phone_href = preg_replace('/[^0-9\+]/', '', $discovery_phone);
            $discovery_location = trim((string) ($recruiter_item['location'] ?? ''));
            $discovery_flag = $this->get_crm_editorial_discovery_flag_data(
                $this->build_crm_editorial_discovery_geo_haystack($recruiter_item)
            );
            $discovery_industry_values = array_filter(array_map('sanitize_key', (array) ($recruiter_item['industry'] ?? [])));
            $discovery_program_types = array_filter(array_map('sanitize_key', (array) ($recruiter_item['program_types'] ?? [])));
            $discovery_role_focus = trim(wp_strip_all_tags((string) ($recruiter_item['role_focus'] ?? '')));
            $discovery_regions = $this->normalize_cv_match_recruiter_terms($recruiter_item['regions'] ?? []);
            $discovery_process = array_filter(array_map('sanitize_key', (array) ($recruiter_item['process'] ?? [])));
            $discovery_skills = array_filter(array_map('sanitize_key', (array) ($recruiter_item['skills'] ?? [])));
            $discovery_format_term = static function ($value) {
                $value = trim((string) $value);
                if ($value === '') {
                    return '';
                }

                return ucwords(str_replace(['_', '-'], ' ', $value));
            };
            $discovery_industry_labels = array_values(array_filter(array_map($discovery_format_term, $discovery_industry_values)));
            $discovery_role_labels = array_values(array_filter(array_map([$this, 'get_crm_editorial_discovery_program_type_label'], $discovery_program_types)));
            $discovery_process_labels = array_values(array_filter(array_map($discovery_format_term, $discovery_process)));
            $discovery_skill_labels = array_values(array_filter(array_map($discovery_format_term, $discovery_skills)));
            $discovery_focus_bits = array_values(array_filter(array_unique(array_merge(
                array_slice($discovery_industry_labels, 0, 3),
                array_slice($discovery_process_labels, 0, 2)
            ))));
            $discovery_recruiter_id = (int) ($recruiter_item['id'] ?? 0);
            if ($discovery_recruiter_id <= 0) {
                $fallback_recruiter_seed = strtolower(trim((string) ($discovery_email !== '' ? $discovery_email : ($discovery_name . '|' . $discovery_firm))));
                $discovery_recruiter_id = abs((int) sprintf('%u', crc32($fallback_recruiter_seed !== '' ? $fallback_recruiter_seed : wp_generate_uuid4())));
            }
            $discovery_intro_in_progress = $has_premium_access && $user_id > 0 && $this->has_crm_editorial_community_send_intro_in_progress($user_id, 0, $discovery_recruiter_id, 'recruiter_discovery');
            $discovery_name_initial = $discovery_name !== ''
                ? (function_exists('mb_strtoupper') ? mb_strtoupper(mb_substr($discovery_name, 0, 1)) : strtoupper(substr($discovery_name, 0, 1)))
                : 'R';
            $discovery_search_index = trim(implode(' ', array_filter([
                $discovery_display_name,
                $discovery_title,
                $has_premium_access ? $discovery_firm : '',
                $discovery_location,
                $discovery_role_focus,
                implode(' ', $discovery_industry_values),
                implode(' ', $discovery_program_types),
            ])));

            ob_start();
            ?>
            <article
                class="sffc-community-editorial__discovery-card"
                data-sffc-community-discovery-card
                data-sffc-community-discovery-id="<?php echo esc_attr((string) $discovery_recruiter_id); ?>"
                data-sffc-community-discovery-search="<?php echo esc_attr($discovery_search_index); ?>"
                data-sffc-community-discovery-location="<?php echo esc_attr($discovery_location); ?>"
                data-sffc-community-discovery-industries="<?php echo esc_attr(implode(' ', $discovery_industry_values)); ?>"
                data-sffc-community-discovery-roles="<?php echo esc_attr(implode(' ', $discovery_program_types)); ?>">
                <div class="sffc-community-editorial__discovery-card-top">
                    <div class="sffc-community-editorial__discovery-avatar">
                        <?php if ($discovery_photo !== '') : ?>
                            <img src="<?php echo esc_url($discovery_photo); ?>" alt="<?php echo esc_attr($discovery_display_name); ?>">
                        <?php else : ?>
                            <span><?php echo esc_html($discovery_name_initial); ?></span>
                        <?php endif; ?>
                    </div>
                    <?php if (!empty($discovery_flag['code'])) : ?>
