        private function get_crm_editorial_discovery_region_priority($location)
        {
            $location = strtolower(trim((string) $location));
            if ($location === '') {
                return 3;
            }

            $middle_east_aliases = [
                'saudi arabia', 'saudi', 'riyadh', 'jeddah', 'dammam', 'khobar', 'ksa', 'k.s.a', 'kingdom of saudi arabia', 'kafd', 'qiddiya', 'takamol', 'stc', 'pif', 'aramco',
                'united arab emirates', 'u.a.e', 'uae', 'dubai', 'abu dhabi', 'sharjah', 'ajman', 'ras al khaimah', 'al ain', 'adgm', 'difc', 'adnoc', 'mubadala',
                'qatar', 'doha',
                'kuwait', 'kuwait city',
                'bahrain', 'manama',
                'oman', 'muscat',
                'egypt', 'cairo',
                'singapore',
                'middle east', 'mena', 'gcc', 'gulf',
            ];

            foreach ($middle_east_aliases as $alias) {
                if ($alias !== '' && strpos($location, $alias) !== false) {
                    return 0;
                }
            }

            $international_aliases = [
                'united kingdom', 'uk', 'great britain', 'england', 'london', 'manchester', 'edinburgh', 'birmingham',
                'netherlands', 'amsterdam', 'rotterdam', 'the hague', 'utrecht', 'holland',
            ];

            foreach ($international_aliases as $alias) {
                if ($alias !== '' && strpos($location, $alias) !== false) {
                    return 1;
                }
            }

            return 2;
        }

        private function build_crm_editorial_discovery_geo_haystack(array $item)
        {
            return strtolower(trim(implode(' • ', array_filter([
                (string) ($item['location_primary'] ?? ''),
                (string) ($item['regions'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['firm'] ?? ''),
                (string) ($item['title'] ?? ''),
                (string) ($item['role_focus'] ?? ''),
                (string) ($item['last_hire_proof'] ?? ''),
                (string) ($item['notes'] ?? ''),
                implode(' ', (array) ($item['industry'] ?? [])),
                implode(' ', (array) ($item['program_types'] ?? [])),
                implode(' ', (array) ($item['process'] ?? [])),
                implode(' ', (array) ($item['skills'] ?? [])),
                (string) ($item['source_context'] ?? ''),
            ]))));
        }

        private function get_crm_editorial_discovery_flag_data($location)
        {
            $location = strtolower(trim((string) $location));
            if ($location === '') {
                return [];
            }

            $map = [
                'Saudi Arabia' => ['code' => 'sa', 'aliases' => ['saudi arabia', 'saudi', 'riyadh', 'jeddah', 'dammam', 'khobar', 'ksa', 'k.s.a', 'kingdom of saudi arabia', 'king abdullah economic city', 'kafd', 'qiddiya', 'takamol', 'stc', 'pif', 'aramco']],
                'United Arab Emirates' => ['code' => 'ae', 'aliases' => ['united arab emirates', 'u.a.e', 'uae', 'dubai', 'abu dhabi', 'sharjah', 'ajman', 'ras al khaimah', 'al ain', 'adgm', 'difc', 'adnoc', 'mubadala']],
                'Qatar' => ['code' => 'qa', 'aliases' => ['qatar', 'doha']],
                'Kuwait' => ['code' => 'kw', 'aliases' => ['kuwait', 'kuwait city']],
                'Bahrain' => ['code' => 'bh', 'aliases' => ['bahrain', 'manama']],
                'Oman' => ['code' => 'om', 'aliases' => ['oman', 'muscat']],
                'Egypt' => ['code' => 'eg', 'aliases' => ['egypt', 'cairo']],
                'United Kingdom' => ['code' => 'gb', 'aliases' => ['united kingdom', 'uk', 'great britain', 'england', 'london', 'manchester', 'edinburgh', 'birmingham']],
                'Netherlands' => ['code' => 'nl', 'aliases' => ['netherlands', 'amsterdam', 'rotterdam', 'the hague', 'utrecht', 'holland']],
                'United States' => ['code' => 'us', 'aliases' => ['united states', 'united states of america', 'usa', 'u.s.a', 'us', 'new york', 'san francisco', 'chicago', 'boston', 'miami', 'los angeles', 'washington']],
                'Singapore' => ['code' => 'sg', 'aliases' => ['singapore']],
            ];

            foreach ($map as $country => $data) {
                foreach ((array) ($data['aliases'] ?? []) as $alias) {
                    if ($alias !== '' && strpos($location, strtolower((string) $alias)) !== false) {
                        return [
                            'country' => $country,
                            'code' => (string) ($data['code'] ?? ''),
                        ];
                    }
                }
            }

            return [];
        }

        private function get_crm_editorial_discovery_program_type_label($program_type)
        {
            $program_type = sanitize_key((string) $program_type);
            $labels = [
                'analyst' => __('Analyst / Senior Analyst Roles', 'senna-finance'),
                'associate' => __('Associate Director / Director / Senior Director Roles', 'senna-finance'),
                'senior' => __('Executive Director / AVP / VP / SVP / EVP Roles', 'senna-finance'),
                'executive' => __('Managing Director / Head / Partner / C-Suite / Board Roles', 'senna-finance'),
                'other' => __('Other', 'senna-finance'),
            ];

            return (string) ($labels[$program_type] ?? '');
        }

        private function sort_crm_editorial_discovery_items_london_first(array $items)
        {
            if (count($items) <= 1) {
                return array_values($items);
            }

            usort($items, function ($left, $right) {
                $left_haystack = $this->build_crm_editorial_discovery_geo_haystack((array) $left);
                $right_haystack = $this->build_crm_editorial_discovery_geo_haystack((array) $right);
                $left_is_london = strpos($left_haystack, 'london') !== false;
                $right_is_london = strpos($right_haystack, 'london') !== false;

                if ($left_is_london !== $right_is_london) {
                    return $left_is_london ? -1 : 1;
                }

                $left_priority = $this->get_crm_editorial_discovery_region_priority($left_haystack);
                $right_priority = $this->get_crm_editorial_discovery_region_priority($right_haystack);
                if ($left_priority !== $right_priority) {
                    return $left_priority <=> $right_priority;
                }

                $left_company = strtolower(trim((string) ($left['firm'] ?? '')));
                $right_company = strtolower(trim((string) ($right['firm'] ?? '')));
                if ($left_company !== $right_company) {
                    return $left_company <=> $right_company;
                }

                return strcasecmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''));
            });

            return array_values($items);
        }

