        public function ajax_crm_editorial_track_company_click()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $company_name = sanitize_text_field((string) ($_POST['company_name'] ?? ''));
            $logo = esc_url_raw((string) ($_POST['logo'] ?? ''));

            if ($company_name === '') {
                wp_send_json_error(['message' => __('Missing company name.', 'senna-finance')], 400);
            }

            $key = $this->get_crm_editorial_company_click_key($company_name);
            if ($key === '') {
                wp_send_json_error(['message' => __('Invalid company key.', 'senna-finance')], 400);
            }

            $store = $this->get_crm_editorial_company_click_store();
            $entry = isset($store[$key]) && is_array($store[$key]) ? $store[$key] : [];
            $entry['company_name'] = $company_name;
            $entry['logo'] = $logo !== '' ? $logo : (string) ($entry['logo'] ?? '');
            $entry['clicks'] = max(0, (int) ($entry['clicks'] ?? 0)) + 1;
            $entry['last_clicked'] = current_time('mysql');
            $store[$key] = $entry;

            $this->save_crm_editorial_company_click_store($store);

            wp_send_json_success([
                'company' => $company_name,
                'clicks' => (int) $entry['clicks'],
            ]);
        }

        public function ajax_crm_editorial_schedule_direct_apply_followup()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $email = sanitize_email((string) ($_POST['email'] ?? ''));
            $crm_post_id = absint((int) ($_POST['crm_post_id'] ?? 0));
            $apply_url = esc_url_raw((string) ($_POST['apply_url'] ?? ''));

            if ($email === '' || !is_email($email)) {
                wp_send_json_error(['message' => __('Enter a valid email address.', 'senna-finance')], 422);
            }

            if ($crm_post_id <= 0) {
                wp_send_json_error(['message' => __('Missing role context.', 'senna-finance')], 400);
            }

            $role = $this->get_crm_editorial_community_feed_item_by_id($crm_post_id);
            if (empty($role)) {
                wp_send_json_error(['message' => __('We could not find that role.', 'senna-finance')], 404);
            }

            $subscription_id = $this->save_crm_editorial_daily_direct_apply_subscription($email, $role);
            if ($subscription_id <= 0) {
                wp_send_json_error(['message' => __('We could not save your role tracker updates right now.', 'senna-finance')], 500);
            }

            $this->schedule_crm_editorial_daily_direct_apply_followups();

            $transport = 'daily_tracker';
            $send_immediate_followup = (bool) apply_filters('sffc_crm_direct_apply_send_immediate_followup', false, $email, $crm_post_id);
            $dedupe_key = 'sffc_direct_apply_followup_' . md5(strtolower($email) . '|' . $crm_post_id);
            if ($send_immediate_followup && !get_transient($dedupe_key)) {
                $payload = [
                    'email' => $email,
                    'crm_post_id' => $crm_post_id,
                    'apply_url' => $apply_url,
                    'requested_at' => current_time('mysql'),
                ];
                $send_at = time() + (5 * MINUTE_IN_SECONDS);
                $transport = 'wp_cron';

                $sendgrid = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
                if ($sendgrid && $sendgrid->is_configured()) {
                    $result = $this->send_crm_editorial_direct_apply_followup_via_sendgrid($payload, $role, $send_at);
                    if (is_wp_error($result)) {
                        update_option('sffc_crm_last_direct_apply_followup_error', [
                            'message' => $result->get_error_message(),
                            'email' => $email,
                            'crm_post_id' => $crm_post_id,
                            'occurred_at' => current_time('mysql'),
                            'transport' => 'sendgrid_api',
                        ], false);
                        wp_send_json_error(['message' => $result->get_error_message()], 500);
                    }
                    $transport = 'sendgrid_api';
                    update_option('sffc_crm_last_direct_apply_followup_submission', [
                        'email' => $email,
                        'crm_post_id' => $crm_post_id,
                        'submitted_at' => current_time('mysql'),
                        'scheduled_for' => gmdate('Y-m-d H:i:s', $send_at),
                        'provider_reference' => (string) ($result['provider_reference'] ?? ''),
                        'transport' => $transport,
                    ], false);
                } else {
                    $scheduled = wp_schedule_single_event($send_at, 'sffc_crm_editorial_send_direct_apply_followup', [$payload]);
                    if ($scheduled === false || is_wp_error($scheduled)) {
                        wp_send_json_error(['message' => __('We could not schedule that follow-up right now.', 'senna-finance')], 500);
                    }
                }
                set_transient($dedupe_key, 1, 30 * MINUTE_IN_SECONDS);
            }

            wp_send_json_success([
                'scheduled' => true,
                'dailyTracker' => true,
                'nextRun' => gmdate('Y-m-d H:i:s', $this->get_next_crm_editorial_dubai_timestamp(6, 0)),
                'transport' => $transport ?? 'deduped',
            ]);
        }

        public function schedule_crm_editorial_daily_direct_apply_followups()
        {
            if (!wp_next_scheduled('sffc_crm_editorial_daily_direct_apply_followups')) {
                wp_schedule_event(
                    $this->get_next_crm_editorial_dubai_timestamp(6, 0),
                    'daily',
                    'sffc_crm_editorial_daily_direct_apply_followups'
                );
            }
        }

        private function get_next_crm_editorial_dubai_timestamp($hour = 6, $minute = 0)
        {
            try {
                $timezone = new DateTimeZone('Asia/Dubai');
                $now = new DateTimeImmutable('now', $timezone);
                $next = $now->setTime((int) $hour, (int) $minute, 0);
                if ($next <= $now) {
                    $next = $next->modify('+1 day');
                }

                return $next->getTimestamp();
            } catch (Exception $e) {
                $fallback = strtotime('tomorrow 02:00:00 UTC');
                return $fallback ?: (time() + DAY_IN_SECONDS);
            }
        }

        private function save_crm_editorial_daily_direct_apply_subscription($email, array $role)
        {
            $email = sanitize_email((string) $email);
            if ($email === '' || !is_email($email)) {
                return 0;
            }

            $this->ensure_crm_contact_capture_tracker_subscription_columns();

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            $crm_post_id = absint((int) ($role['crm_post_id'] ?? $role['post_id'] ?? 0));
            $group = $crm_post_id > 0 ? $this->get_crm_reddit_primary_group($crm_post_id) : [];
            $group_slug = sanitize_title((string) ($group['slug'] ?? ''));
            $group_name = trim((string) ($group['name'] ?? ''));
            if ($group_slug === '') {
                $group_slugs = $this->get_cv_match_studio_mailbox_group_slugs($role);
                $group_slug = sanitize_title((string) ($group_slugs[0] ?? ''));
            }
            if ($group_name === '') {
                $group_name = $this->get_crm_editorial_direct_apply_followup_role_type_label($role);
            }

            $source_level = $this->get_crm_editorial_direct_apply_role_level($role);
            $now = current_time('mysql');
            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table_name}
                 WHERE email = %s
                   AND alert_source = 'direct_apply_tracker_daily'
                   AND direct_apply_source_post_id = %d
                 LIMIT 1",
                $email,
                $crm_post_id
            ));

            $data = [
                'full_name' => $email,
                'email' => $email,
                'post_group_id' => (int) ($group['id'] ?? 0),
                'post_group_slug' => $group_slug,
                'post_group_name' => $group_name,
                'alert_source' => 'direct_apply_tracker_daily',
                'alert_status' => 'subscribed',
                'alert_frequency' => 'daily_6am_dubai',
                'direct_apply_source_post_id' => $crm_post_id,
                'direct_apply_source_seniority' => $source_level,
                'updated_at' => $now,
            ];

            if ($existing_id > 0) {
                $wpdb->update(
                    $table_name,
                    $data,
                    ['id' => $existing_id],
                    ['%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s'],
                    ['%d']
                );
                return $existing_id;
            }

            $data['created_at'] = $now;
            $data['last_alert_post_id'] = $crm_post_id;
            $data['last_alert_sent_at'] = $now;

            $inserted = $wpdb->insert(
                $table_name,
                $data,
                ['%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s', '%d', '%s']
            );

            return $inserted ? (int) $wpdb->insert_id : 0;
        }

        public function send_daily_crm_editorial_direct_apply_followups()
        {
            $this->ensure_crm_contact_capture_tracker_subscription_columns();

            global $wpdb;
            $table_name = $wpdb->prefix . 'sffc_contact_capture';
            $subscriptions = $wpdb->get_results(
                "SELECT id, email, post_group_slug, post_group_name, last_alert_post_id, last_alert_sent_at, created_at, direct_apply_source_post_id, direct_apply_source_seniority
                 FROM {$table_name}
                 WHERE alert_status = 'subscribed'
                   AND alert_source = 'direct_apply_tracker_daily'
                   AND alert_frequency = 'daily_6am_dubai'
                   AND email <> ''
                 ORDER BY updated_at ASC
                 LIMIT 300",
                ARRAY_A
            );

            if (empty($subscriptions)) {
                update_option('sffc_crm_direct_apply_daily_last_run', [
                    'ran_at' => current_time('mysql'),
                    'checked' => 0,
                    'sent' => 0,
                ], false);
                return;
            }

            $sent = 0;
            $checked = 0;

            foreach ($subscriptions as $subscription) {
                $checked++;
                $email = sanitize_email((string) ($subscription['email'] ?? ''));
                if (!is_email($email)) {
                    continue;
                }

                $source_post_id = absint((int) ($subscription['direct_apply_source_post_id'] ?? 0));
                $source_role = $source_post_id > 0 ? $this->get_crm_editorial_community_feed_item_by_id($source_post_id) : [];
                if (empty($source_role)) {
                    continue;
                }

                $last_sent_at = trim((string) ($subscription['last_alert_sent_at'] ?? ''));
                if ($last_sent_at === '') {
                    $last_sent_at = trim((string) ($subscription['created_at'] ?? ''));
                }
                $since_timestamp = $last_sent_at !== '' ? (int) strtotime($last_sent_at) : 0;
                $exclude_ids = array_values(array_filter([
                    $source_post_id,
                    absint((int) ($subscription['last_alert_post_id'] ?? 0)),
                ]));

                $related_roles = $this->get_crm_editorial_direct_apply_followup_related_roles($source_role, 5, [
                    'since_timestamp' => $since_timestamp,
                    'exclude_ids' => $exclude_ids,
                    'group_slug' => sanitize_title((string) ($subscription['post_group_slug'] ?? '')),
                    'strict_seniority' => true,
                ]);

                if (empty($related_roles)) {
                    continue;
                }

                $subject = $this->build_crm_editorial_direct_apply_followup_subject($source_role);
                $message = $this->build_crm_editorial_direct_apply_followup_email_html($source_role, $related_roles, [
                    'mode' => 'daily_tracker',
                    'lead' => sprintf(
                        __('New matching roles have been added since you applied for %s.', 'senna-finance'),
                        trim((string) ($source_role['role_title'] ?? __('your role', 'senna-finance')))
                    ),
                    'related_heading' => __('New matching roles in your tracker', 'senna-finance'),
                    'footer' => __('You are receiving this because you started an application from MENA Careers. We only send this tracker update when new matching roles are available.', 'senna-finance'),
                ]);
                $headers = function_exists('sffc_crm_build_email_headers')
                    ? sffc_crm_build_email_headers('job_alerts', 'text/html')
                    : ['Content-Type: text/html; charset=UTF-8'];

                if (!wp_mail($email, $subject, $message, $headers)) {
                    continue;
                }

                $latest_post_id = 0;
                $latest_timestamp = 0;
                foreach ($related_roles as $related_role) {
                    $related_post_id = absint((int) ($related_role['crm_post_id'] ?? $related_role['post_id'] ?? 0));
                    $related_timestamp = $this->get_crm_editorial_community_item_posted_timestamp((array) $related_role);
                    if ($related_timestamp >= $latest_timestamp) {
                        $latest_timestamp = $related_timestamp;
                        $latest_post_id = $related_post_id;
                    }
                }

                $wpdb->update(
                    $table_name,
                    [
                        'last_alert_post_id' => $latest_post_id,
                        'last_alert_sent_at' => current_time('mysql'),
                        'updated_at' => current_time('mysql'),
                    ],
                    ['id' => (int) ($subscription['id'] ?? 0)],
                    ['%d', '%s', '%s'],
                    ['%d']
                );
                $sent++;
            }

            update_option('sffc_crm_direct_apply_daily_last_run', [
                'ran_at' => current_time('mysql'),
                'checked' => $checked,
                'sent' => $sent,
            ], false);
        }

        private function send_crm_editorial_direct_apply_followup_via_sendgrid(array $payload, array $role, $send_at)
        {
            $email = sanitize_email((string) ($payload['email'] ?? ''));
            $crm_post_id = absint((int) ($payload['crm_post_id'] ?? 0));

            if ($email === '' || !is_email($email) || $crm_post_id <= 0) {
                return new WP_Error('sffc_direct_apply_invalid_payload', __('Missing follow-up email context.', 'senna-finance'));
            }

            $sendgrid = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
            if (!$sendgrid || !$sendgrid->is_configured()) {
                return new WP_Error('sffc_direct_apply_sendgrid_missing', __('SendGrid API is not configured.', 'senna-finance'));
            }

            $related_roles = $this->get_crm_editorial_direct_apply_followup_related_roles($role, 5);
            $subject = $this->build_crm_editorial_direct_apply_followup_subject($role);
            $message = $this->build_crm_editorial_direct_apply_followup_email_html($role, $related_roles);

            return $sendgrid->send_email(
                $subject,
                $message,
                $email,
                (int) $send_at,
                [
                    'crm_post_id' => (string) $crm_post_id,
                    'direct_apply_followup' => '1',
                ],
                ['direct_apply_followup'],
                'job_post_followup'
            );
        }

        public function send_scheduled_crm_editorial_direct_apply_followup($payload)
        {
            $payload = is_array($payload) ? $payload : [];
            $email = sanitize_email((string) ($payload['email'] ?? ''));
            $crm_post_id = absint((int) ($payload['crm_post_id'] ?? 0));

            if ($email === '' || !is_email($email) || $crm_post_id <= 0) {
                return false;
            }

            $role = $this->get_crm_editorial_community_feed_item_by_id($crm_post_id);
            if (empty($role)) {
                return false;
            }

            $related_roles = $this->get_crm_editorial_direct_apply_followup_related_roles($role, 5);
            $subject = $this->build_crm_editorial_direct_apply_followup_subject($role);
            $message = $this->build_crm_editorial_direct_apply_followup_email_html($role, $related_roles);
            $headers = function_exists('sffc_crm_build_email_headers')
                ? sffc_crm_build_email_headers('job_alerts', 'text/html')
                : ['Content-Type: text/html; charset=UTF-8'];

            return (bool) wp_mail($email, $subject, $message, $headers);
        }

        private function get_crm_editorial_direct_apply_followup_related_roles(array $role, $limit = 5, array $args = [])
        {
            $limit = max(1, min(8, (int) $limit));
            $crm_post_id = absint((int) ($role['crm_post_id'] ?? $role['post_id'] ?? 0));
            $seniority = $this->get_crm_editorial_direct_apply_role_level($role);
            $group = $crm_post_id > 0 ? $this->get_crm_reddit_primary_group($crm_post_id) : [];
            $group_slug = sanitize_title((string) ($args['group_slug'] ?? ($group['slug'] ?? '')));
            $exclude_ids = $crm_post_id > 0 ? [$crm_post_id] : [];
            $exclude_ids = array_values(array_unique(array_filter(array_merge(
                $exclude_ids,
                array_map('absint', (array) ($args['exclude_ids'] ?? []))
            ))));
            $since_timestamp = max(0, (int) ($args['since_timestamp'] ?? 0));

            $roles = [];
            if ($group_slug !== '' && $seniority !== '') {
                $payload = $this->get_crm_editorial_community_feed_items(max($limit * 3, 12), 0, 0, $group_slug, $exclude_ids, [
                    'seniority' => $seniority,
                ]);
                $roles = (array) ($payload['items'] ?? []);
            }

            if (count($roles) < $limit && $group_slug !== '') {
                $payload = $this->get_crm_editorial_community_feed_items(max($limit * 5, 24), 0, 0, $group_slug, array_merge($exclude_ids, array_map(static function ($item) {
                    return absint((int) ($item['crm_post_id'] ?? $item['post_id'] ?? 0));
                }, $roles)), []);
                $roles = array_merge($roles, (array) ($payload['items'] ?? []));
            }

            $roles = array_values(array_filter($roles, function ($candidate) use ($role, $since_timestamp, $exclude_ids) {
                $candidate = (array) $candidate;
                $candidate_id = absint((int) ($candidate['crm_post_id'] ?? $candidate['post_id'] ?? 0));
                if ($candidate_id <= 0 || in_array($candidate_id, $exclude_ids, true)) {
                    return false;
                }

                if ($since_timestamp > 0 && $this->get_crm_editorial_community_item_posted_timestamp($candidate) <= $since_timestamp) {
                    return false;
                }

                return $this->is_crm_editorial_direct_apply_related_role_level_match($role, $candidate);
            }));

            $deduped = [];
            foreach ($this->sort_crm_editorial_community_feed_items_by_recent($roles) as $candidate) {
                $candidate_id = absint((int) ($candidate['crm_post_id'] ?? $candidate['post_id'] ?? 0));
                if ($candidate_id <= 0 || isset($deduped[$candidate_id])) {
                    continue;
                }
                $deduped[$candidate_id] = (array) $candidate;
            }

            return array_slice(array_values($deduped), 0, $limit);
        }

        private function get_crm_editorial_direct_apply_role_level(array $role)
        {
            $normalized = $this->normalize_crm_editorial_community_seniority_filter_value((string) ($role['seniority'] ?? ''));
            if (in_array($normalized, ['analyst', 'associate', 'manager', 'director', 'c_suite'], true)) {
                return $normalized;
            }

            $title = strtolower(trim((string) ($role['role_title'] ?? $role['title'] ?? '')));
            if ($title === '') {
                return '';
            }

            if (preg_match('/\b(managing director|chief|cfo|ceo|coo|cio|partner|c[- ]?suite)\b/i', $title)) {
                return 'c_suite';
            }
            if (preg_match('/\b(executive director|director|head of|head,|head\b)\b/i', $title)) {
                return 'director';
            }
            if (preg_match('/\b(manager|senior manager|investment manager|portfolio manager|vice president|\\bvp\\b)\b/i', $title)) {
                return 'manager';
            }
            if (preg_match('/\b(associate|senior associate)\b/i', $title)) {
                return 'associate';
            }
            if (preg_match('/\b(analyst|senior analyst|intern|graduate|trainee)\b/i', $title)) {
                return 'analyst';
            }

            return '';
        }

        private function is_crm_editorial_direct_apply_related_role_level_match(array $source_role, array $candidate_role)
        {
            $source_level = $this->get_crm_editorial_direct_apply_role_level($source_role);
            $candidate_level = $this->get_crm_editorial_direct_apply_role_level($candidate_role);

            if ($source_level === '' || $candidate_level === '') {
                return false;
            }

            return $source_level === $candidate_level;
        }

        private function build_crm_editorial_direct_apply_followup_subject(array $role)
        {
            $role_type = $this->get_crm_editorial_direct_apply_followup_role_type_label($role);
            $location = $this->get_crm_editorial_community_location_filter_label((string) ($role['location'] ?? ''));

            if ($location === '') {
                $location = __('your target market', 'senna-finance');
            }

            return sprintf(__('More %1$s roles in %2$s', 'senna-finance'), $role_type, $location);
        }

        private function get_crm_editorial_direct_apply_followup_role_type_label(array $role)
        {
            $sector = trim((string) ($role['sector'] ?? ''));
            if ($sector !== '') {
                return $this->get_crm_editorial_community_sector_filter_label($sector);
            }

            $crm_post_id = absint((int) ($role['crm_post_id'] ?? $role['post_id'] ?? 0));
            $group = $crm_post_id > 0 ? $this->get_crm_reddit_primary_group($crm_post_id) : [];
            $group_name = trim((string) ($group['name'] ?? ''));
            if ($group_name !== '') {
                $group_name = preg_replace('/\s+jobs?\s+in\s+.+$/i', '', $group_name);
                $group_name = preg_replace('/\s+roles?$/i', '', (string) $group_name);
                $group_name = trim((string) $group_name);
            }

            return $group_name !== '' ? $group_name : __('Finance', 'senna-finance');
        }

