        private function get_crm_editorial_company_role_items($company_name, $limit = 8)
        {
            $company_name = trim((string) $company_name);
            if ($company_name === '') {
                return [];
            }

            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';

            $post_model = new SFFC_CRM_Post();
            $results = $post_model->get_feed([
                'page' => 1,
                'per_page' => max(8, min(40, (int) $limit * 4)),
                'approved_only' => true,
                'search' => $company_name,
                'orderby' => 'posted_at',
                'order' => 'DESC',
            ]);

            if (empty($results)) {
                return [];
            }

            $items = [];
            foreach ((array) $results as $item) {
                $item = (array) $item;
                $item_company = trim((string) ($item['company'] ?? ''));
                if ($item_company === '' || strcasecmp($item_company, $company_name) !== 0) {
                    continue;
                }

                $role_title = trim((string) ($item['role_title'] ?? ''));
                if ($role_title === '') {
                    continue;
                }

                $linked_wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                $slug_seed = sanitize_title($role_title . '-' . $item_company);
                $view_url = $linked_wp_post_id > 0 ? (get_permalink($linked_wp_post_id) ?: '') : '';
                if ($view_url === '') {
                    $view_url = SFFC_CRM_Post_Type::get_post_url((int) ($item['id'] ?? 0), $slug_seed);
                }

                $items[] = [
                    'title' => $role_title,
                    'url' => $view_url,
                    'posted_label' => trim((string) ($item['posted_label'] ?? '')),
                    'location' => $this->get_crm_editorial_community_location_filter_label((string) ($item['location'] ?? '')),
                ];

                if (count($items) >= $limit) {
                    break;
                }
            }

            return $items;
        }

        public function ajax_crm_editorial_company_roles()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            if (!is_user_logged_in() || !$this->current_user_has_crm_editorial_paid_membership_access()) {
                wp_send_json_error(['message' => __('Upgrade to view company role details.', 'senna-finance')], 403);
            }

            $company_name = sanitize_text_field((string) ($_POST['company_name'] ?? ''));
            if ($company_name === '') {
                wp_send_json_error(['message' => __('Missing company name.', 'senna-finance')], 400);
            }

            $roles = $this->get_crm_editorial_company_role_items($company_name, 8);

            wp_send_json_success([
                'company' => $company_name,
                'roles' => $roles,
            ]);
        }

        private function get_crm_editorial_community_recent_hiring_items($limit = 3)
        {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';

            $post_model = new SFFC_CRM_Post();
            $recent_posts = $post_model->get_feed([
                'page' => 1,
                'per_page' => 18,
                'approved_only' => true,
                'posted_after' => gmdate('Y-m-d H:i:s', current_time('timestamp') - (14 * DAY_IN_SECONDS)),
                'orderby' => 'posted_at',
                'order' => 'DESC',
            ]);

            if (empty($recent_posts)) {
                return [];
            }

            shuffle($recent_posts);
            $recent_posts = array_slice((array) $recent_posts, 0, max(1, min(4, (int) $limit)));

            $items = [];
            foreach ($recent_posts as $post) {
                $post = (array) $post;
                $recruiter_name = trim((string) ($post['recruiter_name'] ?? __('Recruiter', 'senna-finance')));
                $recruiter_title = trim((string) ($post['recruiter_title'] ?? __('Recruitment Consultant', 'senna-finance')));
                $recruiter_email = sanitize_email((string) ($post['recruiter_email'] ?? ''));
                $recruiter_linkedin = esc_url_raw((string) ($post['recruiter_linkedin'] ?? ''));
                $initial = function_exists('mb_substr')
                    ? mb_strtoupper(mb_substr($recruiter_name, 0, 1))
                    : strtoupper(substr($recruiter_name, 0, 1));
                $role_title = trim((string) ($post['role_title'] ?? __('a new role', 'senna-finance')));
                $slug_seed = sanitize_title($role_title . '-' . ($post['company'] ?? ''));
                $linked_wp_post_id = (int) ($post['wp_post_id'] ?? 0);
                $role_url = $linked_wp_post_id > 0 ? (get_permalink($linked_wp_post_id) ?: '') : '';
                if ($role_url === '') {
                    $role_url = SFFC_CRM_Post_Type::get_post_url((int) ($post['id'] ?? 0), $slug_seed);
                }
                $normalized_location = $this->normalize_crm_editorial_community_location_label((string) ($post['location'] ?? ''));
                $location_label = $this->get_crm_editorial_community_location_filter_label($normalized_location !== '' ? $normalized_location : (string) ($post['location'] ?? ''));
                $headline = $role_title;

                $byline_parts = array_values(array_filter([
                    sprintf(__('By %s', 'senna-finance'), $recruiter_name),
                    $location_label,
                ]));
                $company_name = trim((string) ($post['company'] ?? ''));
                $current_user = wp_get_current_user();
                $sender_name_parts = array_values(array_filter([
                    trim((string) ($current_user->first_name ?? '')),
                    trim((string) ($current_user->last_name ?? '')),
                ]));
                $sender_name = trim(implode(' ', $sender_name_parts));
                if ($sender_name === '') {
                    $sender_name = trim((string) ($current_user->display_name ?? ''));
                }
                if ($sender_name === '') {
                    $sender_name = __('MENA Careers Member', 'senna-finance');
                }
                $recruiter_first_name_tokens = preg_split('/\s+/', $recruiter_name);
                $recruiter_first_name = trim((string) ($recruiter_first_name_tokens[0] ?? ''));
                if ($recruiter_first_name === '') {
                    $recruiter_first_name = __('there', 'senna-finance');
                }
                $draft_subject = trim(sprintf(
                    __('Regarding %1$s at %2$s', 'senna-finance'),
                    $role_title !== '' ? $role_title : __('this role', 'senna-finance'),
                    $company_name !== '' ? $company_name : __('your team', 'senna-finance')
                ));
                $draft_body = trim(sprintf(
                    __("Hi %1\$s,\n\nI hope you're well. I came across the %3\$s opportunity at %4\$s and wanted to reach out directly.\n\nMy background looks relevant to the brief, and I would value the chance to share why I could be a strong fit for the role.\n\nIf useful, I can send over my CV and a concise summary of the most relevant experience.\n\nBest regards,\n%2\$s", 'senna-finance'),
                    $recruiter_first_name,
                    $sender_name,
                    $role_title !== '' ? $role_title : __('role', 'senna-finance'),
                    $company_name !== '' ? $company_name : __('your team', 'senna-finance')
                ));
                $draft_mailto = $recruiter_email !== ''
                    ? 'mailto:' . $recruiter_email . '?subject=' . rawurlencode($draft_subject) . '&body=' . rawurlencode($draft_body)
                    : '';

                $items[] = [
                    'recruiter_id' => (int) ($post['recruiter_id'] ?? 0),
                    'post_id' => (int) ($post['id'] ?? 0),
                    'headline' => $headline,
                    'byline' => implode(', ', $byline_parts),
                    'recruiter' => $recruiter_name,
                    'recruiter_title' => $recruiter_title,
                    'recruiter_email' => $recruiter_email,
                    'recruiter_linkedin' => $recruiter_linkedin,
                    'photo' => trim((string) ($post['recruiter_photo'] ?? '')),
                    'initial' => $initial !== '' ? $initial : 'R',
                    'url' => $role_url,
                    'company_name' => $company_name,
                    'company_url' => $role_url,
                    'draft_subject' => $draft_subject,
                    'draft_body' => $draft_body,
                    'draft_mailto' => $draft_mailto,
                ];
            }

            return $items;
        }

        private function get_crm_editorial_community_network_items(array $feed_items, array $post_groups, $limit = 6)
        {
            $cards = [];

            foreach ($feed_items as $item) {
                $item = (array) $item;
                $title = trim((string) ($item['role_title'] ?? ''));
                if ($title === '') {
                    continue;
                }

                $cards[] = [
                    'kicker' => __('Network signal', 'senna-finance'),
                    'title' => $title,
                    'summary' => $this->build_cv_match_studio_jobs_mailbox_preview($item),
                    'meta' => array_values(array_filter([
                        (string) ($item['company'] ?? ''),
                        (string) ($item['location'] ?? ''),
                        (string) ($item['sector'] ?? ''),
                    ])),
                ];

                if (count($cards) >= $limit) {
                    break;
                }
            }

            foreach ($post_groups as $group) {
                if (count($cards) >= $limit) {
                    break;
                }

                $cards[] = [
                    'kicker' => __('Community group', 'senna-finance'),
                    'title' => (string) ($group['name'] ?? ''),
                    'summary' => wp_trim_words(wp_strip_all_tags((string) ($group['description'] ?? '')), 18),
                    'meta' => array_values(array_filter([
                        !empty($group['location']) ? (string) $group['location'] : '',
                        sprintf(_n('%d role', '%d roles', (int) ($group['post_count'] ?? 0), 'senna-finance'), (int) ($group['post_count'] ?? 0)),
                    ])),
                ];
            }

            return array_slice($cards, 0, max(1, (int) $limit));
        }

        private function get_crm_editorial_community_events($limit = 4)
        {
            $limit = max(1, min(8, (int) $limit));
            $posts = get_posts([
                'post_type' => 'sffc_key_event',
                'post_status' => 'publish',
                'posts_per_page' => $limit,
                'meta_key' => 'event_date',
                'orderby' => 'meta_value',
                'order' => 'ASC',
                'meta_type' => 'DATETIME',
                'no_found_rows' => true,
            ]);

            if (empty($posts)) {
                $posts = get_posts([
                    'post_type' => 'sffc_key_event',
                    'post_status' => 'publish',
                    'posts_per_page' => $limit,
                    'orderby' => 'date',
                    'order' => 'DESC',
                    'no_found_rows' => true,
                ]);
            }

            $items = [];
            foreach ((array) $posts as $post) {
                $event_date = (string) get_post_meta($post->ID, 'event_date', true);
                $location = trim((string) get_post_meta($post->ID, 'event_location', true));
                $event_type = trim((string) get_post_meta($post->ID, 'event_type', true));
                $timestamp = $event_date !== '' ? strtotime($event_date) : false;

                $items[] = [
                    'title' => get_the_title($post),
                    'date_label' => $timestamp ? wp_date('j M', $timestamp) : get_the_date('j M', $post),
                    'meta' => implode(' • ', array_values(array_filter([$event_type, $location]))),
                ];
            }

            return $items;
        }

        private function get_crm_editorial_community_post_variant($index)
        {
            $index = max(0, (int) $index);
            $position = $index + 1;

            if ($position === 1) {
                return 'lead';
            }

            $cycle_position = (($position - 1) % 6) + 1;
            if ($cycle_position === 4) {
                return 'brief';
            }

            if ($cycle_position === 1) {
                return 'lead-lite';
            }

            return 'standard';
        }

        private function get_crm_editorial_community_post_preview_source(array $item)
        {
            $candidates = [
                (string) ($item['content'] ?? ''),
                (string) ($item['description_html'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
            ];

            foreach ($candidates as $candidate) {
                if (trim(wp_strip_all_tags($candidate)) !== '') {
                    return $candidate;
                }
            }

            return (string) $this->build_cv_match_studio_jobs_mailbox_preview($item);
        }

        private function normalize_crm_editorial_community_location_label($value)
        {
            $label = trim((string) $value);
            if ($label === '') {
                return '';
            }

            $normalized = strtolower($label);
            $normalized = preg_replace('/[[:space:]]+/', ' ', (string) $normalized);
            $normalized = str_replace(['–', '—'], '-', (string) $normalized);

            $aliases = [
                'dubai, uae' => 'Dubai, United Arab Emirates',
                'dubai, united arab emirates' => 'Dubai, United Arab Emirates',
                'dubai' => 'Dubai, United Arab Emirates',
                'abu dhabi' => 'Abu Dhabi, United Arab Emirates',
                'abu dhabi, uae' => 'Abu Dhabi, United Arab Emirates',
                'abu dhabi, united arab emirates' => 'Abu Dhabi, United Arab Emirates',
                'riyadh' => 'Riyadh, Saudi Arabia',
                'riyadh, saudi arabia' => 'Riyadh, Saudi Arabia',
                'riyadh, ksa' => 'Riyadh, Saudi Arabia',
                'doha' => 'Doha, Qatar',
                'doha, qatar' => 'Doha, Qatar',
                'qatar' => 'Doha, Qatar',
                'london, uk' => 'London, United Kingdom',
                'paris, france' => 'Paris, France',
                'milan, italy' => 'Milan, Italy',
                'amsterdam, netherlands' => 'Amsterdam, Netherlands',
                'mumbai, india' => 'Mumbai, India',
            ];

            if (isset($aliases[$normalized])) {
                return $aliases[$normalized];
            }

            return $label;
        }

        private function get_crm_editorial_community_location_filter_label($value)
        {
            $normalized = $this->normalize_crm_editorial_community_location_label($value);
            if ($normalized === '') {
                return '';
            }

            $parts = array_values(array_filter(array_map('trim', explode(',', $normalized))));
            if (empty($parts)) {
                return $normalized;
            }

            return (string) $parts[0];
        }

