        private function extract_crm_editorial_community_work_type_filters(array $item)
        {
            $haystack = strtolower(implode(' ', array_filter([
                (string) ($item['role_title'] ?? ''),
                (string) ($item['employment_type'] ?? ''),
                (string) ($item['job_type'] ?? ''),
                (string) ($item['work_type'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['content'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
            ])));

            $values = [];
            if (!empty($item['is_remote']) || preg_match('/\b(remote|work from home|wfh)\b/i', $haystack)) {
                $values[] = 'remote';
            }
            if (!empty($item['is_hybrid']) || preg_match('/\bhybrid\b/i', $haystack)) {
                $values[] = 'hybrid';
            }
            if (preg_match('/\b(on[- ]?site|office based|office-based)\b/i', $haystack)) {
                $values[] = 'onsite';
            }
            if (preg_match('/\b(full[- ]?time|permanent)\b/i', $haystack)) {
                $values[] = 'full_time';
            }
            if (preg_match('/\b(contract|temporary|fixed term|fixed-term|freelance)\b/i', $haystack)) {
                $values[] = 'contract';
            }
            if (preg_match('/\b(intern|internship|summer analyst|off-cycle|off cycle)\b/i', $haystack)) {
                $values[] = 'internship';
            }
            if (preg_match('/\b(graduate|graduate programme|graduate program|trainee|emiratisation|emiratization|national talent)\b/i', $haystack)) {
                $values[] = 'graduate';
            }

            return array_values(array_unique($values));
        }

        private function get_crm_editorial_community_work_type_filter_label($value)
        {
            $labels = [
                'remote' => __('Remote', 'senna-finance'),
                'hybrid' => __('Hybrid', 'senna-finance'),
                'onsite' => __('On-site', 'senna-finance'),
                'full_time' => __('Full-time', 'senna-finance'),
                'contract' => __('Contract', 'senna-finance'),
                'internship' => __('Internship', 'senna-finance'),
                'graduate' => __('Graduate programme', 'senna-finance'),
            ];

            $key = sanitize_key((string) $value);
            return (string) ($labels[$key] ?? ucwords(str_replace('_', ' ', $key)));
        }

        private function does_crm_editorial_community_item_match_posted_date_filter(array $item, $filter)
        {
            $filter = sanitize_key((string) $filter);
            if ($filter === '' || $filter === 'all') {
                return true;
            }

            $timestamp = $this->get_crm_editorial_community_item_posted_timestamp($item);
            if ($timestamp <= 0) {
                return false;
            }

            $now = current_time('timestamp');
            $age = max(0, $now - $timestamp);
            $day = DAY_IN_SECONDS;

            $windows = [
                'past_24_hours' => $day,
                'past_48_hours' => 2 * $day,
                'past_7_days' => 7 * $day,
                'past_14_days' => 14 * $day,
                'past_30_days' => 30 * $day,
            ];

            return isset($windows[$filter]) && $age <= $windows[$filter];
        }

