        private function get_crm_editorial_community_brand_location_label($context_crm_post_id = 0, $context_group_slug = '', array $post_groups = [], array $feed_items = [])
        {
            global $wpdb;

            $candidates = [];
            $context_crm_post_id = (int) $context_crm_post_id;

            if ($context_crm_post_id > 0) {
                $posts_table = $wpdb->prefix . 'sffc_crm_posts';
                $post_location = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT location, location_city, location_country FROM {$posts_table} WHERE id = %d LIMIT 1",
                        $context_crm_post_id
                    ),
                    ARRAY_A
                );

                if (is_array($post_location)) {
                    $candidates[] = trim((string) ($post_location['location_city'] ?? ''));
                    $candidates[] = trim((string) ($post_location['location'] ?? ''));
                    $candidates[] = trim((string) ($post_location['location_country'] ?? ''));
                }
            }

            $context_group_slug = sanitize_title((string) $context_group_slug);
            if ($context_group_slug !== '') {
                foreach ($post_groups as $group) {
                    if (sanitize_title((string) ($group['slug'] ?? '')) !== $context_group_slug) {
                        continue;
                    }

                    $candidates[] = trim((string) ($group['location'] ?? ''));
                    $candidates[] = $this->extract_crm_editorial_community_location_from_text((string) ($group['name'] ?? ''));
                    break;
                }
            }

            foreach ($feed_items as $item) {
                $candidates[] = trim((string) ((array) $item)['location'] ?? '');
            }

            foreach ($candidates as $candidate) {
                $candidate = trim((string) $candidate);
                if ($candidate === '') {
                    continue;
                }

                $label = $this->get_crm_editorial_community_known_location_label($candidate);
                if ($label !== '') {
                    return $label;
                }
            }

            return '';
        }

