        private function get_crm_editorial_community_known_location_label($location_label)
        {
            $location_label = trim((string) $location_label);
            if ($location_label === '') {
                return '';
            }

            $normalized = strtolower($location_label);
            $normalized = str_replace(['_', '-'], ' ', $normalized);
            $normalized = preg_replace('/[[:space:]]+/', ' ', (string) $normalized);

            foreach ($this->get_crm_editorial_community_location_heading_aliases() as $display_location => $aliases) {
                foreach ($aliases as $alias) {
                    if (strpos($normalized, $alias) !== false) {
                        return $display_location;
                    }
                }
            }

            return '';
        }

        private function filter_crm_editorial_community_post_groups_by_location(array $post_groups, $location_label)
        {
            global $wpdb;

            $location_label = $this->get_crm_editorial_community_location_filter_label((string) $location_label);
            if ($location_label === '' || empty($post_groups)) {
                return [];
            }

            $location_patterns = [$location_label];
            $location_aliases = [
                'Middle East' => ['Dubai', 'Abu Dhabi', 'Riyadh', 'Doha', 'UAE', 'United Arab Emirates', 'Saudi', 'Saudi Arabia', 'KSA', 'Qatar'],
                'Dubai' => ['Dubai'],
                'Abu Dhabi' => ['Abu Dhabi'],
                'Riyadh' => ['Riyadh', 'Saudi', 'Saudi Arabia', 'KSA'],
                'Doha' => ['Doha', 'Qatar'],
                'London' => ['London'],
                'Paris' => ['Paris'],
                'Milan' => ['Milan'],
                'Amsterdam' => ['Amsterdam'],
            ];
            if (isset($location_aliases[$location_label])) {
                $location_patterns = $location_aliases[$location_label];
            }

            $post_group_ids = array_values(array_filter(array_map(static function ($group) {
                return absint($group['id'] ?? 0);
            }, $post_groups)));

            if (empty($post_group_ids)) {
                return [];
            }

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $relationships_table = $wpdb->prefix . 'sffc_crm_post_group_relationships';
            $group_placeholders = implode(',', array_fill(0, count($post_group_ids), '%d'));
            $location_clauses = [];
            $values = $post_group_ids;

            foreach ($location_patterns as $pattern) {
                $pattern = trim((string) $pattern);
                if ($pattern === '') {
                    continue;
                }

                $like = '%' . $wpdb->esc_like($pattern) . '%';
                $location_clauses[] = '(p.location LIKE %s OR p.location_city LIKE %s)';
                $values[] = $like;
                $values[] = $like;
            }

            if (empty($location_clauses)) {
                return [];
            }

            $sql = "
                SELECT pgr.group_id, COUNT(DISTINCT p.id) AS location_post_count
                FROM {$posts_table} p
                INNER JOIN {$relationships_table} pgr ON p.id = pgr.post_id
                WHERE pgr.group_id IN ({$group_placeholders})
                  AND p.is_active = 1
                  AND p.admin_approved = 1
                  AND (p.post_status IS NULL OR p.post_status = '' OR p.post_status = 'open')
                  AND (" . implode(' OR ', $location_clauses) . ")
                GROUP BY pgr.group_id
            ";

            $rows = $wpdb->get_results($wpdb->prepare($sql, $values), ARRAY_A);
            if (empty($rows)) {
                return [];
            }

            $counts_by_group_id = [];
            foreach ($rows as $row) {
                $group_id = absint($row['group_id'] ?? 0);
                if ($group_id > 0) {
                    $counts_by_group_id[$group_id] = (int) ($row['location_post_count'] ?? 0);
                }
            }

            if (empty($counts_by_group_id)) {
                return [];
            }

            $filtered_groups = [];
            foreach ($post_groups as $group) {
                $group_id = absint($group['id'] ?? 0);
                if ($group_id <= 0 || !isset($counts_by_group_id[$group_id])) {
                    continue;
                }

                $group['post_count'] = $counts_by_group_id[$group_id];
                $filtered_groups[] = $group;
            }

            return $filtered_groups;
        }

        private function filter_crm_editorial_community_post_groups_for_middle_east(array $post_groups)
        {
            if (empty($post_groups)) {
                return [];
            }

            $filtered_groups = [];
            foreach ($post_groups as $group) {
                $haystack = implode(' ', array_filter([
                    (string) ($group['name'] ?? ''),
                    (string) ($group['description'] ?? ''),
                    (string) ($group['location'] ?? ''),
                    (string) ($group['slug'] ?? ''),
                ]));

                if ($this->get_crm_editorial_community_middle_east_location_label($haystack) !== '') {
                    $filtered_groups[] = $group;
                }
            }

            return $filtered_groups;
        }

        private function extract_crm_editorial_community_location_from_text($value)
        {
            $text = strtolower((string) $value);
            if ($text === '') {
                return '';
            }

            $locations = [
                'dubai' => __('Dubai', 'senna-finance'),
                'abu dhabi' => __('Abu Dhabi', 'senna-finance'),
                'riyadh' => __('Riyadh', 'senna-finance'),
                'doha' => __('Doha', 'senna-finance'),
            ];
            $matches = [];

            foreach ($locations as $needle => $label) {
                if (strpos($text, $needle) !== false) {
                    $matches[] = $label;
                }
            }

            if (empty($matches)) {
                return '';
            }

            return implode(' & ', array_values(array_unique($matches)));
        }

