                'Audit' => ['audit', 'auditing'],
                'Treasury' => ['treasury'],
                'Excel' => ['excel', 'advanced excel', 'microsoft excel', 'ms excel', 'spreadsheets', 'spreadsheet', 'spreadsheet modelling', 'spreadsheet modeling', 'vlookup', 'xlookup', 'pivot table', 'pivot tables'],
                'Power BI' => ['power bi'],
                'Tableau' => ['tableau'],
                'Bloomberg' => ['bloomberg', 'bloomberg terminal'],
                'SQL' => ['sql'],
                'SAP' => ['sap'],
            ];
        }

        private function normalize_crm_editorial_community_qualification_label($value)
        {
            $label = trim((string) $value);
            if ($label === '') {
                return '';
            }

            foreach ($this->get_crm_editorial_community_qualification_dictionary() as $canonical_label => $needles) {
                $needle_pool = array_merge([$canonical_label], (array) $needles);
                foreach ($needle_pool as $needle) {
                    if (stripos(' ' . strtolower($label) . ' ', ' ' . strtolower((string) $needle) . ' ') !== false || strtolower($label) === strtolower((string) $needle)) {
                        return $canonical_label;
                    }
                }
            }

            return $label;
        }

        private function extract_crm_editorial_community_qualifications(array $item)
        {
            $haystack = wp_strip_all_tags(implode(' ', array_filter([
                (string) ($item['role_title'] ?? ''),
                (string) ($item['content'] ?? ''),
                (string) ($item['description_html'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
                (string) ($item['sector'] ?? ''),
            ])));
            $haystack = strtolower($haystack);
            $haystack = ' ' . preg_replace('/\s+/', ' ', (string) $haystack) . ' ';

            $matches = [];
            foreach ($this->get_crm_editorial_community_qualification_dictionary() as $canonical_label => $needles) {
                foreach ((array) $needles as $needle) {
                    $normalized_needle = ' ' . strtolower((string) $needle) . ' ';
                    if (strpos($haystack, $normalized_needle) !== false) {
                        $matches[$canonical_label] = $canonical_label;
                        break;
                    }
                }
            }

            return array_values($matches);
        }

        private function get_crm_editorial_community_match_signal_dictionary()
        {
            return [
                'Private Equity' => ['private equity', 'pe fund', 'buyout', 'growth equity', 'portfolio company', 'private markets', 'alternatives advisory', 'alternative investments', 'capital deployment', 'investment committee', 'ic presentation', 'investment lifecycle'],
                'Investment Banking' => ['investment banking', 'global investment bank', 'top 10 global investment bank', 'm&a', 'mergers and acquisitions', 'corporate finance', 'deal advisory', 'deal origination', 'deal sourcing', 'transaction execution', 'structuring'],
                'Investor Relations' => ['investor relations', 'capital formation', 'fundraising', 'lp relations', 'limited partners', 'institutional investors', 'sovereign wealth funds', 'family offices', 'fund placement'],
                'Asset Management' => ['asset management', 'portfolio management', 'investment management', 'fund management', 'portfolio construction'],
                'Private Credit' => ['private credit', 'direct lending', 'credit investment', 'credit analyst', 'corporate credit'],
                'Real Estate' => ['real estate', 'real estate investment', 'property investment', 'property finance', 'real assets'],
                'Venture Capital' => ['venture capital', 'vc', 'startup investment', 'corporate venture capital', 'cvc', 'startup ecosystem'],
                'Strategy' => ['strategy', 'corporate development', 'special projects', 'go-to-market', 'gtm'],
                'Wealth Management' => ['wealth management', 'private banking', 'family office'],
                'Accounting' => ['accounting', 'accountant', 'audit', 'ifrs', 'financial control'],
                'Data' => ['data', 'analytics', 'sql', 'python', 'power bi', 'tableau'],
                'Treasury' => ['treasury', 'liquidity', 'cash management'],
                'Risk' => ['risk management', 'operational risk', 'credit risk', 'market risk', 'compliance', 'governance risk'],
            ];
        }

        private function normalize_crm_editorial_community_match_text($text)
        {
            return ' ' . strtolower(preg_replace('/\s+/', ' ', wp_strip_all_tags((string) $text))) . ' ';
        }

        private function extract_crm_editorial_community_text_signals($text, array $dictionary)
        {
            $haystack = $this->normalize_crm_editorial_community_match_text($text);
            $signals = [];

            foreach ($dictionary as $label => $needles) {
                foreach ((array) $needles as $needle) {
                    $needle = strtolower(trim((string) $needle));
                    if ($needle !== '' && preg_match('/(^|[^a-z0-9])' . preg_quote($needle, '/') . '([^a-z0-9]|$)/i', $haystack)) {
                        $signals[$label] = $label;
                        break;
                    }
                }
            }

            return array_values($signals);
        }

        private function extract_crm_editorial_community_seniority_signals($text)
        {
            $haystack = $this->normalize_crm_editorial_community_match_text($text);
            $signals = [];
            $patterns = [
                'internship' => '/\b(intern|internship|industrial placement|summer analyst|graduate programme|graduate program|trainee)\b/i',
                'graduate' => '/\b(graduate|entry level|junior analyst|analyst programme|analyst program)\b/i',
                'analyst' => '/\b(analyst|researcher)\b/i',
                'associate' => '/\b(associate|consultant)\b/i',
                'manager' => '/\b(manager|vp|vice president|lead|principal|senior associate|senior analyst)\b/i',
                'director' => '/\b(director|executive director|head of|head,|head -)\b/i',
                'c_suite' => '/\b(cfo|ceo|coo|chief|partner|managing director|founder|co-founder|svp|evp)\b/i',
            ];

            foreach ($patterns as $key => $pattern) {
                if (preg_match($pattern, $haystack)) {
                    $signals[] = $key;
                }
            }

            return array_values(array_unique($signals));
        }

        private function get_crm_editorial_community_highest_seniority_weight(array $signals)
        {
            $weights = [
                'internship' => 1,
                'graduate' => 2,
                'analyst' => 3,
                'associate' => 4,
                'manager' => 5,
                'director' => 6,
                'c_suite' => 7,
            ];
            $highest = 0;
            foreach ($signals as $signal) {
                $highest = max($highest, (int) ($weights[$signal] ?? 0));
            }

            return $highest;
        }

        private function get_crm_editorial_community_seniority_label_from_weight($weight)
        {
            $weight = (int) $weight;
            $labels = [
                1 => __('Intern', 'senna-finance'),
                2 => __('Graduate', 'senna-finance'),
                3 => __('Analyst', 'senna-finance'),
                4 => __('Associate', 'senna-finance'),
                5 => __('Manager', 'senna-finance'),
                6 => __('Director', 'senna-finance'),
                7 => __('C-suite', 'senna-finance'),
            ];

            return (string) ($labels[$weight] ?? __('Unclear', 'senna-finance'));
        }

        private function get_crm_editorial_community_signal_tone($score, $max_score)
        {
            $score = (float) $score;
            $max_score = max(1, (float) $max_score);
            $ratio = $score / $max_score;

            if ($ratio >= 0.75) {
                return 'strong';
            }

            if ($ratio >= 0.45) {
                return 'watch';
            }

            return 'gap';
        }

        private function build_crm_editorial_community_match_check_item($label, $present, $detail)
        {
            return [
                'label' => (string) $label,
                'present' => (bool) $present,
                'detail' => (string) $detail,
            ];
        }

        private function extract_crm_editorial_community_years_of_experience($text)
        {
            $years = 0;
            if (preg_match_all('/\b(\d{1,2})(?:\+|\s*(?:to|-|–)\s*\d{1,2})?\s*(?:years|yrs)\b/i', (string) $text, $matches)) {
                foreach ((array) ($matches[1] ?? []) as $match) {
                    $years = max($years, (int) $match);
                }
            }

            return $years;
        }

        private function extract_crm_editorial_community_required_year_range($text)
        {
            if (preg_match('/\b(?:minimum|min\.?|at least)?\s*(\d{1,2})(?:\s*(?:to|-|–)\s*(\d{1,2}))?\+?\s*(?:years|yrs)\b/i', (string) $text, $matches)) {
                return [
                    'min' => (int) ($matches[1] ?? 0),
                    'max' => (int) ($matches[2] ?? 0),
                ];
            }

            return ['min' => 0, 'max' => 0];
        }

        private function extract_crm_editorial_community_match_locations($text)
        {
            $haystack = $this->normalize_crm_editorial_community_match_text($text);
            return [
                'dubai' => (bool) preg_match('/\bdubai\b/i', $haystack),
                'abu_dhabi' => (bool) preg_match('/\babu dhabi\b/i', $haystack),
                'riyadh' => (bool) preg_match('/\briyadh\b/i', $haystack),
                'doha' => (bool) preg_match('/\bdoha\b/i', $haystack),
                'uae' => (bool) preg_match('/\b(uae|united arab emirates|dubai|abu dhabi)\b/i', $haystack),
                'saudi' => (bool) preg_match('/\b(saudi|ksa|riyadh|kingdom of saudi arabia)\b/i', $haystack),
                'qatar' => (bool) preg_match('/\b(qatar|doha)\b/i', $haystack),
                'gcc' => (bool) preg_match('/\b(gcc|gulf|mena|middle east)\b/i', $haystack),
            ];
        }

        private function build_crm_editorial_community_match_profile_from_cv_text($cv_text, array $cv_scan_payload = [])
        {
            $cv_text = trim((string) $cv_text);
            $cv_signal_text = trim($cv_text . ' ' . wp_json_encode($cv_scan_payload));
            $normalized_cv_text = $this->normalize_crm_editorial_community_match_text($cv_signal_text);
            $qualification_signals = $this->extract_crm_editorial_community_text_signals($cv_signal_text, $this->get_crm_editorial_community_qualification_dictionary());
            $domain_signals = $this->extract_crm_editorial_community_text_signals($cv_signal_text, $this->get_crm_editorial_community_match_signal_dictionary());
            $seniority_signals = $this->extract_crm_editorial_community_seniority_signals($cv_signal_text);
            $date_matches = [];
            if (preg_match_all('/\b(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s+\d{4}\b|\b(?:19|20)\d{2}\s*(?:-|–|—|to)\s*(?:present|current|now|(?:19|20)\d{2})\b|\b(?:19|20)\d{2}\b/i', $cv_signal_text, $matches)) {
                $date_matches = array_values(array_unique(array_map('trim', (array) ($matches[0] ?? []))));
            }
            $email_match = preg_match('/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i', $cv_signal_text);
            $linkedin_match = preg_match('/(?:https?:\/\/)?(?:[\w]+\.)?linkedin\.com\/in\/[A-Za-z0-9\-_%]+/i', $cv_signal_text);
            $phone_match = false;
            if (preg_match_all('/(?:\+?\d[\d\s().-]{7,}\d)/', $cv_signal_text, $phone_matches)) {
                foreach ((array) ($phone_matches[0] ?? []) as $phone_candidate) {
                    if (strlen(preg_replace('/\D+/', '', (string) $phone_candidate)) >= 8) {
                        $phone_match = true;
                        break;
                    }
                }
            }
            $language_signals = [];
            foreach (['English', 'Arabic', 'French', 'Italian', 'German', 'Spanish', 'Hindi', 'Urdu'] as $language) {
                if (preg_match('/\b' . preg_quote($language, '/') . '\b/i', $cv_signal_text)) {
                    $language_signals[] = $language;
                }
            }
            $tool_labels = array_values(array_intersect($qualification_signals, ['Excel', 'Power BI', 'Tableau', 'Bloomberg', 'SQL', 'SAP']));
            $certification_labels = array_values(array_intersect($qualification_signals, ['ACCA', 'ACA', 'CIMA', 'CFA', 'CPA', 'CAIA', 'FRM', 'CMA', 'MBA', 'Bloomberg']));

            return [
                'has_cv' => $cv_text !== '',
                'text' => $normalized_cv_text,
                'qualifications' => array_values(array_unique($qualification_signals)),
                'domains' => array_values(array_unique($domain_signals)),
                'seniority' => array_values(array_unique($seniority_signals)),
                'years' => $this->extract_crm_editorial_community_years_of_experience($cv_signal_text),
                'languages' => array_slice(array_values(array_unique($language_signals)), 0, 4),
                'tools' => array_slice($tool_labels, 0, 6),
                'certifications' => array_slice($certification_labels, 0, 6),
                'profile_signals' => [
                    'has_linkedin' => (bool) $linkedin_match,
                    'has_email' => (bool) $email_match,
                    'has_phone' => (bool) $phone_match,
                    'has_dates' => count($date_matches) >= 2,
                    'date_count' => count($date_matches),
                ],
                'nationality' => [
                    'uae' => (bool) preg_match('/\b(emirati|uae national|united arab emirates national)\b/i', $cv_signal_text),
                    'saudi' => (bool) preg_match('/\b(saudi national|saudi citizen|ksa national)\b/i', $cv_signal_text),
                    'qatari' => (bool) preg_match('/\b(qatari national|qatar national|qatari citizen)\b/i', $cv_signal_text),
                ],
                'locations' => $this->extract_crm_editorial_community_match_locations($cv_signal_text),
            ];
        }

        private function get_crm_editorial_community_guest_match_profile($token)
        {
            $token = preg_replace('/[^A-Za-z0-9]/', '', (string) $token);
            if ($token === '') {
                return null;
            }

            $payload = get_transient('sffc_crm_editorial_guest_cv_' . $token);
            if (!is_array($payload)) {
                return null;
            }

            $profile = isset($payload['profile']) && is_array($payload['profile'])
                ? (array) $payload['profile']
                : $this->build_crm_editorial_community_match_profile_from_cv_text((string) ($payload['cv_text'] ?? ''));

            return !empty($profile['has_cv']) ? $profile : null;
        }

        private function get_crm_editorial_community_user_match_profile($user_id)
        {
            static $profiles = [];

            if (is_array($this->crm_editorial_guest_match_profile) && !empty($this->crm_editorial_guest_match_profile['has_cv'])) {
                return $this->crm_editorial_guest_match_profile;
            }

            $user_id = (int) $user_id;
            if (isset($profiles[$user_id])) {
                return $profiles[$user_id];
            }

            $resume_payload = $user_id > 0 ? (array) $this->get_crm_reddit_active_resume_text($user_id) : [];
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $cv_scan_payload = ($user_id > 0 && $cv_text !== '') ? (array) $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, false) : [];
            $profiles[$user_id] = $this->build_crm_editorial_community_match_profile_from_cv_text($cv_text, $cv_scan_payload);

            return $profiles[$user_id];
        }

        private function get_crm_editorial_community_item_match_payload(array $item, $user_id = 0)
        {
            $profile = $this->get_crm_editorial_community_user_match_profile((int) $user_id);
            $role_text = implode(' ', array_filter([
                (string) ($item['role_title'] ?? ''),
                (string) ($item['company'] ?? ''),
                (string) ($item['location'] ?? ''),
                (string) ($item['sector'] ?? ''),
                (string) ($item['seniority'] ?? ''),
                (string) ($item['content'] ?? ''),
                (string) ($item['description_html'] ?? ''),
                (string) ($item['description_preview'] ?? ''),
                (string) ($item['excerpt'] ?? ''),
            ]));
            $role_domains = $this->extract_crm_editorial_community_text_signals($role_text, $this->get_crm_editorial_community_match_signal_dictionary());
            $role_qualifications = $this->extract_crm_editorial_community_qualifications($item);
            $role_seniority = $this->normalize_crm_editorial_community_seniority_filter_value((string) ($item['seniority'] ?? ''));
            $role_seniority_signals = $this->extract_crm_editorial_community_seniority_signals($role_text);
            if (($role_seniority === '' || $role_seniority === 'other') && !empty($role_seniority_signals)) {
                $role_seniority = (string) $role_seniority_signals[0];
            }
            $role_year_range = $this->extract_crm_editorial_community_required_year_range($role_text);
            $role_locations = $this->extract_crm_editorial_community_match_locations($role_text);
            $location = strtolower((string) ($item['location'] ?? ''));
            $role_title_text = strtolower((string) ($item['role_title'] ?? ''));
            $hard_missing = [];
            $reasons = [];
            $missing = [];
            $caps = [];
            $weights = [
                'role_relevance' => 20,
                'experience' => 20,
                'skills' => 20,
                'domain_depth' => 15,
                'seniority' => 10,
                'location' => 10,
                'application_strength' => 5,
            ];
            $category_scores = array_fill_keys(array_keys($weights), 0.0);
            $positive_categories = 0;

            if (preg_match('/\b(emirati|uae nationals?|emiratization|emiratisation)\b/i', $role_text) && empty($profile['nationality']['uae'])) {
                $hard_missing[] = __('Requires UAE national status', 'senna-finance');
                $caps[] = 56;
            }
            if (preg_match('/\b(saudi nationals?|ksa nationals?|saudization|saudisation)\b/i', $role_text) && empty($profile['nationality']['saudi'])) {
                $hard_missing[] = __('Requires Saudi national status', 'senna-finance');
                $caps[] = 56;
            }
            if (preg_match('/\b(qatari nationals?|qatar nationals?|qatarisation|qatarization)\b/i', $role_text) && empty($profile['nationality']['qatari'])) {
                $hard_missing[] = __('Requires Qatari national status', 'senna-finance');
                $caps[] = 56;
            }
            if (preg_match('/\barabic\b/i', $role_text) && !preg_match('/\barabic\b/i', (string) ($profile['text'] ?? ''))) {
                $caps[] = 64;
                $missing[] = __('Arabic is requested but not visible on CV', 'senna-finance');
            }
            if (
                preg_match('/\b(l&d|learning|human resources?|hr|recruitment|talent acquisition|marketing|communications?|legal|procurement|secretary|administrative|office manager)\b/i', $role_title_text)
                && !preg_match('/\b(finance|financial|investment|investor|equity|credit|m&a|mergers?|acquisitions?|portfolio|treasury|account|accounting|audit|tax|risk|valuation|fund)\b/i', $role_title_text)
            ) {
                $caps[] = 60;
                $missing[] = __('Role appears to be outside core finance or investing', 'senna-finance');
            }

            if (empty($profile['has_cv'])) {
                return [
                    'rank' => 'unrated',
                    'label' => __('Upload CV to Match', 'senna-finance'),
                    'score' => null,
                    'reasons' => [__('Upload CV to Match', 'senna-finance')],
                    'missing' => [],
                    'is_unrated' => true,
                ];
            }

            $domain_overlap = array_values(array_intersect($role_domains, (array) $profile['domains']));
            $role_domain_count = max(1, count($role_domains));
            if (!empty($domain_overlap)) {
                $domain_ratio = min(1.0, count($domain_overlap) / $role_domain_count);
                $category_scores['role_relevance'] = 8 + (12 * $domain_ratio);
                $category_scores['domain_depth'] = min(15, 6 + (count($domain_overlap) * 4.5));
                $positive_categories++;
                $reasons[] = sprintf(__('Domain fit: %s', 'senna-finance'), implode(', ', array_slice($domain_overlap, 0, 2)));
            } elseif (!empty($role_domains)) {
                $category_scores['role_relevance'] = 3;
                $category_scores['domain_depth'] = 2;
                $caps[] = 70;
                $missing[] = sprintf(__('No clear %s signal on CV', 'senna-finance'), (string) $role_domains[0]);
            } else {
                $category_scores['role_relevance'] = 10;
                $category_scores['domain_depth'] = 7;
            }

            $qualification_overlap = array_values(array_intersect($role_qualifications, (array) $profile['qualifications']));
            $has_high_value_qualification_fit = false;
            $mandatory_qualification_pattern = '/\b(required|must have|essential|qualified|certification|chartered|holder)[^.]{0,80}\b(' . implode('|', array_map(static function ($value) {
                return preg_quote((string) $value, '/');
            }, array_keys($this->get_crm_editorial_community_qualification_dictionary()))) . ')\b/i';
            if (!empty($qualification_overlap)) {
                $qualification_ratio = min(1.0, count($qualification_overlap) / max(1, count($role_qualifications)));
                $category_scores['skills'] = 8 + (12 * $qualification_ratio);
                $high_value_qualification_overlap = array_intersect($qualification_overlap, ['Financial Modelling', 'Due Diligence', 'Valuation', 'LBO Modeling', 'M&A', 'ACA', 'ACCA', 'CPA', 'CFA', 'Bloomberg', 'Portfolio Management', 'Risk Management', 'Private Equity']);
                if (empty($high_value_qualification_overlap)) {
                    $category_scores['skills'] = min($category_scores['skills'], 12);
                } else {
                    $has_high_value_qualification_fit = true;
                    $positive_categories++;
                }
                $reasons[] = sprintf(__('Skills fit: %s', 'senna-finance'), implode(', ', array_slice($qualification_overlap, 0, 3)));
            } elseif (!empty($role_qualifications)) {
                $category_scores['skills'] = 4;
                $missing[] = sprintf(__('Missing visible %s signal', 'senna-finance'), (string) $role_qualifications[0]);
                if (preg_match($mandatory_qualification_pattern, $role_text)) {
                    $caps[] = 72;
                }
            } else {
                $category_scores['skills'] = 10;
            }

            if (!empty($role_year_range['min']) && !empty($profile['years']) && (int) $profile['years'] >= (int) $role_year_range['min']) {
                if (!empty($role_year_range['max']) && (int) $profile['years'] > ((int) $role_year_range['max'] + 5)) {
                    $category_scores['experience'] = 13;
                    $missing[] = __('Experience may be above the target range', 'senna-finance');
                } else {
                    $category_scores['experience'] = 20;
                }
                $positive_categories++;
                $year_label = !empty($role_year_range['max'])
                    ? sprintf(__('%1$d-%2$d years', 'senna-finance'), (int) $role_year_range['min'], (int) $role_year_range['max'])
                    : sprintf(__('%d+ years', 'senna-finance'), (int) $role_year_range['min']);
                $reasons[] = sprintf(__('Experience covers %s', 'senna-finance'), $year_label);
            } elseif (!empty($role_year_range['min'])) {
                $profile_years = (int) ($profile['years'] ?? 0);
                if ($profile_years > 0) {
                    $gap = max(0, (int) $role_year_range['min'] - $profile_years);
                    $category_scores['experience'] = max(0, 16 - ($gap * 5));
                    if ($gap >= 3) {
                        $caps[] = 58;
                    } elseif ($gap >= 1) {
                        $caps[] = 68;
                    }
                } else {
                    $category_scores['experience'] = 6;
                    $caps[] = 68;
                }
                $missing[] = sprintf(__('Experience requirement: %d+ years', 'senna-finance'), (int) $role_year_range['min']);
            } else {
                $category_scores['experience'] = !empty($profile['years']) ? 13 : 8;
            }

            $profile_seniority_weight = $this->get_crm_editorial_community_highest_seniority_weight((array) ($profile['seniority'] ?? []));
            $role_seniority_weight = $this->get_crm_editorial_community_highest_seniority_weight($role_seniority !== '' ? [$role_seniority] : (array) $role_seniority_signals);
            $seniority_gap = null;
            if ($role_seniority !== '' && $role_seniority !== 'other') {
                $seniority_gap = ($profile_seniority_weight > 0 && $role_seniority_weight > 0) ? ($profile_seniority_weight - $role_seniority_weight) : null;
                if ($profile_seniority_weight > 0 && $role_seniority_weight > 0 && $profile_seniority_weight >= $role_seniority_weight) {
                    $category_scores['seniority'] = $profile_seniority_weight > ($role_seniority_weight + 2) ? 7 : 10;
                    $positive_categories++;
                    $reasons[] = __('Career level is credible for this role', 'senna-finance');
                } elseif ($profile_seniority_weight > 0 && $role_seniority_weight > 0 && ($role_seniority_weight - $profile_seniority_weight) >= 2) {
                    $category_scores['seniority'] = 1;
                    $caps[] = 66;
                    $missing[] = __('Seniority may be a stretch', 'senna-finance');
                } elseif ($profile_seniority_weight > 0 && $role_seniority_weight > 0) {
                    $category_scores['seniority'] = 6;
                }
            } else {
                $category_scores['seniority'] = 5;
            }

            if (
                (strpos($location, 'dubai') !== false && !empty($profile['locations']['dubai']))
                || (strpos($location, 'abu dhabi') !== false && !empty($profile['locations']['abu_dhabi']))
                || (strpos($location, 'riyadh') !== false && !empty($profile['locations']['riyadh']))
                || (strpos($location, 'doha') !== false && !empty($profile['locations']['doha']))
                || (!empty($role_locations['uae']) && (!empty($profile['locations']['uae']) || !empty($profile['locations']['gcc'])))
                || (!empty($role_locations['saudi']) && (!empty($profile['locations']['saudi']) || !empty($profile['locations']['gcc'])))
                || (!empty($role_locations['qatar']) && (!empty($profile['locations']['qatar']) || !empty($profile['locations']['gcc'])))
            ) {
                $category_scores['location'] = 10;
                $positive_categories++;
                $reasons[] = __('Regional experience aligns', 'senna-finance');
            } elseif (!empty(array_filter($role_locations))) {
                $category_scores['location'] = 4;
            } else {
                $category_scores['location'] = 6;
            }

            $cv_text = (string) ($profile['text'] ?? '');
            $application_strength_hits = 0;
            foreach (['transaction', 'deal', 'm&a', 'merger', 'acquisition', 'origination', 'execution', 'model', 'valuation', 'investment', 'portfolio', 'capital deployment', 'investment committee', 'pitchbook', 'presentation', 'committee', 'due diligence'] as $needle) {
                if (strpos($cv_text, $needle) !== false) {
                    $application_strength_hits++;
                }
            }
            $category_scores['application_strength'] = min(5, $application_strength_hits);

            $raw_score = array_sum($category_scores);
            $score = max(0, min(100, $raw_score));
            $profile_signals = (array) ($profile['profile_signals'] ?? []);
            if (!empty($caps)) {
                $score = min($score, min($caps));
            }
            if (!empty($hard_missing)) {
                $score = min($score, 56);
            }

            $confidence_signals = 0;
            foreach ([$role_domains, $role_qualifications, $role_seniority !== '' ? [$role_seniority] : [], !empty($role_year_range['min']) ? [$role_year_range['min']] : [], array_filter($role_locations)] as $signal_group) {
                if (!empty($signal_group)) {
                    $confidence_signals++;
                }
            }
            $confidence_score = min(100, 35 + ($confidence_signals * 10) + (!empty($profile['has_cv']) ? 15 : 0) + (count((array) $profile['domains']) * 3) + (count((array) $profile['qualifications']) * 2));
            $confidence = $confidence_score >= 78 ? __('High confidence', 'senna-finance') : ($confidence_score >= 58 ? __('Medium confidence', 'senna-finance') : __('Low confidence', 'senna-finance'));

            $has_strong_domain_fit = $category_scores['role_relevance'] >= 14 && $category_scores['domain_depth'] >= 10;
            $has_useful_skill_fit = $has_high_value_qualification_fit || $category_scores['application_strength'] >= 4;
            $has_credible_experience = $category_scores['experience'] >= 13 && $category_scores['seniority'] >= 7;
            $rank = ($score >= 78 && $positive_categories >= 3 && $has_strong_domain_fit && $has_useful_skill_fit && $has_credible_experience && empty($hard_missing)) ? 'qualified' : ($score >= 58 ? 'consider' : 'mismatch');
            $labels = [
                'qualified' => __('Qualified', 'senna-finance'),
                'consider' => __('To Consider', 'senna-finance'),
                'mismatch' => __('Weak Match', 'senna-finance'),
            ];

            $required_signal_count = count($role_domains) + count($role_qualifications) + (!empty($role_year_range['min']) ? 1 : 0) + ($role_seniority_weight > 0 ? 1 : 0);
            $matched_signal_count = count($domain_overlap) + count($qualification_overlap);
            if (!empty($role_year_range['min']) && !empty($profile['years']) && (int) $profile['years'] >= (int) $role_year_range['min']) {
                $matched_signal_count++;
            }
            if ($role_seniority_weight > 0 && $profile_seniority_weight > 0 && $profile_seniority_weight >= $role_seniority_weight) {
                $matched_signal_count++;
            }
            $required_signal_label = $required_signal_count > 0
                ? sprintf(__('%1$d of %2$d visible', 'senna-finance'), min($matched_signal_count, $required_signal_count), $required_signal_count)
                : __('No hard requirements detected', 'senna-finance');
            $seniority_label = __('Seniority unclear', 'senna-finance');
            $seniority_detail = __('We need clearer title and date signals to compare your level.', 'senna-finance');
            $seniority_tone = 'watch';
            if ($role_seniority_weight > 0 && $profile_seniority_weight > 0) {
                $cv_level_label = $this->get_crm_editorial_community_seniority_label_from_weight($profile_seniority_weight);
                $role_level_label = $this->get_crm_editorial_community_seniority_label_from_weight($role_seniority_weight);
                if ($seniority_gap >= 2) {
                    $seniority_label = __('Potentially overqualified', 'senna-finance');
                    $seniority_detail = sprintf(__('CV reads closer to %1$s level, while this role reads closer to %2$s.', 'senna-finance'), $cv_level_label, $role_level_label);
                    $seniority_tone = 'watch';
                } elseif ($seniority_gap <= -2) {
                    $seniority_label = __('Potentially underqualified', 'senna-finance');
                    $seniority_detail = sprintf(__('Role reads closer to %1$s level, while the CV currently reads closer to %2$s.', 'senna-finance'), $role_level_label, $cv_level_label);
                    $seniority_tone = 'gap';
                } elseif ($seniority_gap === -1) {
                    $seniority_label = __('Slightly junior', 'senna-finance');
                    $seniority_detail = sprintf(__('CV reads slightly earlier than the role level: %1$s vs %2$s.', 'senna-finance'), $cv_level_label, $role_level_label);
                    $seniority_tone = 'watch';
                } else {
                    $seniority_label = __('Seniority aligned', 'senna-finance');
                    $seniority_detail = sprintf(__('CV level and role level both read around %s.', 'senna-finance'), $role_level_label);
                    $seniority_tone = 'strong';
                }
            }
            $quick_checks = [
                $this->build_crm_editorial_community_match_check_item(__('LinkedIn profile', 'senna-finance'), !empty($profile_signals['has_linkedin']), !empty($profile_signals['has_linkedin']) ? __('Found linkedin.com/in/', 'senna-finance') : __('Missing linkedin.com/in/', 'senna-finance')),
                $this->build_crm_editorial_community_match_check_item(__('Email address', 'senna-finance'), !empty($profile_signals['has_email']), !empty($profile_signals['has_email']) ? __('Found email address', 'senna-finance') : __('Missing email address', 'senna-finance')),
                $this->build_crm_editorial_community_match_check_item(__('Phone number', 'senna-finance'), !empty($profile_signals['has_phone']), !empty($profile_signals['has_phone']) ? __('Found telephone number', 'senna-finance') : __('Missing telephone number', 'senna-finance')),
                $this->build_crm_editorial_community_match_check_item(__('Experience dates', 'senna-finance'), !empty($profile_signals['has_dates']), !empty($profile_signals['has_dates']) ? sprintf(__('Found %d date signals', 'senna-finance'), (int) ($profile_signals['date_count'] ?? 0)) : __('Missing clear duration signals', 'senna-finance')),
            ];
            $certifications_included = array_values(array_intersect($role_qualifications, (array) ($profile['qualifications'] ?? [])));
            $certifications_missing = array_values(array_diff($role_qualifications, (array) ($profile['qualifications'] ?? [])));
            $detected_groups = array_values(array_filter([
                ['label' => __('Languages detected', 'senna-finance'), 'values' => array_slice((array) ($profile['languages'] ?? []), 0, 4)],
                ['label' => __('Role signals spotted', 'senna-finance'), 'values' => array_slice((array) ($profile['domains'] ?? []), 0, 4)],
                ['label' => __('Tools and systems', 'senna-finance'), 'values' => array_slice((array) ($profile['tools'] ?? []), 0, 4)],
                ['label' => __('Qualifications found', 'senna-finance'), 'values' => array_slice((array) ($profile['certifications'] ?? []), 0, 4)],
            ], static function ($group) {
                return !empty($group['values']);
            }));
            $fit_breakdown = [
                [
                    'label' => __('Seniority match', 'senna-finance'),
                    'value' => $seniority_label,
                    'detail' => $seniority_detail,
                    'tone' => $seniority_tone,
                ],
                [
                    'label' => __('Experience requirement', 'senna-finance'),
                    'value' => !empty($role_year_range['min'])
                        ? (!empty($profile['years']) ? sprintf(__('%1$d yrs CV vs %2$d+ required', 'senna-finance'), (int) $profile['years'], (int) $role_year_range['min']) : sprintf(__('%d+ years requested', 'senna-finance'), (int) $role_year_range['min']))
                        : __('No exact year threshold', 'senna-finance'),
                    'detail' => !empty($role_year_range['min']) ? __('Derived from the role description and CV date signals.', 'senna-finance') : __('No explicit years requirement was found in the role text.', 'senna-finance'),
                    'tone' => $this->get_crm_editorial_community_signal_tone((float) $category_scores['experience'], 20),
                ],
                [
                    'label' => __('Sector evidence', 'senna-finance'),
                    'value' => !empty($domain_overlap) ? implode(', ', array_slice($domain_overlap, 0, 2)) : __('Missing clear signal', 'senna-finance'),
                    'detail' => !empty($role_domains) ? sprintf(__('Role expects: %s', 'senna-finance'), implode(', ', array_slice($role_domains, 0, 3))) : __('No specific sector was detected.', 'senna-finance'),
                    'tone' => $this->get_crm_editorial_community_signal_tone((float) $category_scores['domain_depth'], 15),
                ],
                [
                    'label' => __('Required signals', 'senna-finance'),
                    'value' => $required_signal_label,
                    'detail' => !empty($certifications_missing) ? sprintf(__('Missing: %s', 'senna-finance'), implode(', ', array_slice($certifications_missing, 0, 3))) : __('No obvious certification or keyword gap detected.', 'senna-finance'),
                    'tone' => empty($certifications_missing) ? 'strong' : 'watch',
                ],
            ];

            if (empty($reasons)) {
                $reasons[] = $rank === 'mismatch' ? __('Few CV signals match this role', 'senna-finance') : __('Some CV signals may fit this role', 'senna-finance');
            }

            return [
                'rank' => $rank,
                'label' => $labels[$rank],
                'score' => $score,
                'confidence' => $confidence,
                'confidence_score' => $confidence_score,
                'category_scores' => $category_scores,
                'fit_breakdown' => $fit_breakdown,
                'quick_checks' => $quick_checks,
                'detected_groups' => $detected_groups,
                'career_fit' => [
                    'seniority' => [
                        'label' => $seniority_label,
                        'detail' => $seniority_detail,
                        'tone' => $seniority_tone,
                        'cv_level' => $this->get_crm_editorial_community_seniority_label_from_weight($profile_seniority_weight),
                        'role_level' => $this->get_crm_editorial_community_seniority_label_from_weight($role_seniority_weight),
                        'estimated_years' => (int) ($profile['years'] ?? 0),
                    ],
                    'certifications' => [
                        'included' => array_slice($certifications_included, 0, 4),
                        'missing' => array_slice($certifications_missing, 0, 4),
                        'cv' => array_slice((array) ($profile['certifications'] ?? []), 0, 4),
                        'role' => array_slice($role_qualifications, 0, 6),
                    ],
                ],
                'reasons' => array_slice(array_values(array_unique($reasons)), 0, 3),
                'missing' => array_slice(array_values(array_unique(array_merge($hard_missing, $missing))), 0, 3),
            ];
        }

        private function render_crm_editorial_community_match_icon($rank)
        {
            $rank = sanitize_key((string) $rank);
            if ($rank === 'qualified') {
                return '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 10.4 3 3 7-7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
            }
            if ($rank === 'mismatch') {
                return '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 3 18 17H2L10 3Zm0 5v4m0 2.8v.2" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
            }

            return '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m10 2.8 2.1 4.3 4.7.7-3.4 3.3.8 4.7-4.2-2.2-4.2 2.2.8-4.7-3.4-3.3 4.7-.7L10 2.8Z" fill="currentColor"/></svg>';
        }

        private function get_crm_editorial_community_match_rating($score, $rank = '')
        {
            $score = max(0, min(100, (float) $score));
            $rank = sanitize_key((string) $rank);

            $rating = $score / 20;

            return max(1.0, min(5.0, round($rating, 1)));
        }

        private function render_crm_editorial_community_match_rating($score, $rank, $label)
        {
            $rank = sanitize_key((string) $rank);
            $label = trim((string) $label);
            if ($rank === 'unrated') {
                $label = __('Check fit', 'senna-finance');
                ob_start();
                ?>
                <span class="sffc-community-editorial__post-match-rating sffc-community-editorial__post-match-rating--unrated sffc-community-editorial__post-match-upload-trigger" role="link" tabindex="0" data-sffc-community-membership-link aria-label="<?php echo esc_attr($label); ?>">
                    <span class="sffc-community-editorial__post-match-stars" aria-hidden="true"><?php echo esc_html('☆☆☆☆☆'); ?></span>
                    <strong><?php echo esc_html($label); ?></strong>
                </span>
                <?php
                return trim((string) ob_get_clean());
            }

            $rating = $this->get_crm_editorial_community_match_rating($score, $rank);
            $filled_stars = max(1, min(5, (int) floor($rating + 0.25)));
            $empty_stars = 5 - $filled_stars;
            $label = $label !== '' ? $label : __('To Consider', 'senna-finance');
            $aria_label = sprintf(
                /* translators: 1: match rating, 2: match label */
                __('Match rating %1$s out of 5, %2$s', 'senna-finance'),
                number_format_i18n($rating, 1),
                $label
            );

            ob_start();
            ?>
            <span class="sffc-community-editorial__post-match-rating sffc-community-editorial__post-match-rating--<?php echo esc_attr($rank); ?>" aria-label="<?php echo esc_attr($aria_label); ?>">
                <span class="sffc-community-editorial__post-match-stars" aria-hidden="true">
                    <span class="sffc-community-editorial__post-match-stars-filled"><?php echo esc_html(str_repeat('★', $filled_stars)); ?></span><?php echo esc_html(str_repeat('☆', $empty_stars)); ?>
                </span>
                <strong><?php echo esc_html(number_format_i18n($rating, 1)); ?></strong>
                <span><?php echo esc_html($label); ?></span>
            </span>
            <?php
            return trim((string) ob_get_clean());
        }

        private function mask_crm_editorial_community_restricted_text($value, array $replacements = [])
        {
            $masked = (string) $value;
            if ($masked === '' || empty($replacements)) {
                return $masked;
            }

            foreach ($replacements as $needle => $replacement) {
                $needle = trim((string) $needle);
                if ($needle === '') {
                    continue;
                }

                $next_masked = preg_replace('/' . preg_quote($needle, '/') . '/iu', (string) $replacement, $masked);
                if (is_string($next_masked)) {
                    $masked = $next_masked;
                }
            }

            return (string) $masked;
        }

        private function render_crm_editorial_community_post_card(array $item, $variant = 'standard', $position = 0, $category_highlight_label = '', array $category_highlight_context = [])
        {
            $is_logged_in = is_user_logged_in();
            $has_premium_access = $is_logged_in && $this->current_user_has_crm_editorial_paid_membership_access();
            $user_id = get_current_user_id();
            $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(
                (int) ($item['post_id'] ?? 0),
                (int) ($item['wp_post_id'] ?? 0),
                (int) ($item['crm_post_id'] ?? 0)
            );
            $role_title = trim((string) ($item['role_title'] ?? __('Role brief', 'senna-finance')));
            $company_name = trim((string) ($item['company'] ?? ''));
            $company_logo = trim((string) ($item['company_logo'] ?? ''));
            $public_company_name = $has_premium_access ? $company_name : '';
            $preview_source = $this->get_crm_editorial_community_post_preview_source($item);
            $preview_full = trim(preg_replace('/\s+/', ' ', wp_strip_all_tags($preview_source)));
            if (!$has_premium_access) {
                $restricted_replacements = [
                    $company_name => __('the company', 'senna-finance'),
                ];
                $preview_full = $this->mask_crm_editorial_community_restricted_text($preview_full, $restricted_replacements);
            }
            $location = trim((string) ($item['location'] ?? ''));
            $location_filter_value = $this->normalize_crm_editorial_community_location_label($location);
            $sector = trim((string) ($item['sector'] ?? ''));
            $sector_filter_value = $this->normalize_crm_editorial_community_sector_filter_value($sector);
            $sector_label = $sector !== '' ? $this->get_crm_editorial_community_sector_filter_label($sector) : '';
            $seniority = trim((string) ($item['seniority'] ?? ''));
            $seniority_filter_value = $this->normalize_crm_editorial_community_seniority_filter_value($seniority);
            $salary_text = trim((string) ($item['salary_text'] ?? ''));
            $qualification_filter_values = $this->extract_crm_editorial_community_qualifications($item);
            $work_type_filter_values = $this->extract_crm_editorial_community_work_type_filters($item);
            $company_filter_value = sanitize_title($company_name);
            $match_payload = $this->get_crm_editorial_community_item_match_payload($item, $user_id);
            $match_rank = sanitize_key((string) ($match_payload['rank'] ?? 'consider'));
            $match_label = trim((string) ($match_payload['label'] ?? __('To Consider', 'senna-finance')));
            $match_reasons = array_values(array_filter((array) ($match_payload['reasons'] ?? [])));
            $match_missing = array_values(array_filter((array) ($match_payload['missing'] ?? [])));
            $view_url = (string) ($item['_jobs_mailbox_view_url'] ?? ($item['view_url'] ?? ''));
            $apply_url = trim((string) ($item['application_url'] ?? $item['apply_url'] ?? ''));
            if ($apply_url === '') {
                $apply_url = $view_url;
            }
            $public_opportunity_url = $this->get_crm_editorial_community_public_opportunity_url($item, $role_title, $company_name);
            $crm_post_id = (int) ($item['crm_post_id'] ?? $item['post_id'] ?? 0);
            $posted_timestamp = $this->get_crm_editorial_community_item_posted_timestamp($item);
            $current_timestamp = current_time('timestamp');
            $is_early_bird_post = $this->is_crm_editorial_community_item_early_bird_eligible($item);
            $posted_age_seconds = $posted_timestamp > 0 ? max(0, $current_timestamp - $posted_timestamp) : 0;
            $is_fresh_post = $posted_timestamp > 0 && $posted_age_seconds <= DAY_IN_SECONDS;
            $posted_label = $this->format_crm_editorial_community_item_posted_age($posted_timestamp);
            $company_initial_source = $company_name !== '' ? $company_name : $role_title;
            $company_initial = function_exists('mb_substr')
                ? mb_strtoupper(mb_substr($company_initial_source, 0, 1))
                : strtoupper(substr($company_initial_source, 0, 1));
            $meta_line_parts = $has_premium_access ? [$company_name, $location, $sector_label] : [$location, $sector_label];
            $meta_line = implode(' • ', array_values(array_filter($meta_line_parts)));
            $detail_items = array_values(array_filter([
                $salary_text,
            ]));
            $matched_slugs = $this->get_cv_match_studio_mailbox_group_slugs($item);
            $group_attr = implode(' ', array_map('sanitize_html_class', $matched_slugs));
            $search_index = implode(' ', array_filter([
                $role_title,
                $public_company_name,
                $location_filter_value !== '' ? $location_filter_value : $location,
                $sector,
                $sector_label,
                $seniority,
                $salary_text,
                $preview_full,
                implode(' ', $qualification_filter_values),
                $match_label,
                implode(' ', $match_reasons),
                implode(' ', $match_missing),
            ]));
            $is_recruiter_apply_url = stripos(trim((string) $apply_url), 'mailto:') === 0;
            $direct_apply_url = !$is_recruiter_apply_url ? $apply_url : ($view_url !== '' ? $view_url : '');
            $profile_review_url = add_query_arg(
                [
                    'sffc_review' => 'profile',
                    'sffc_apply_chat_open' => '1',
                    'sffc_apply_context' => 'community_editorial',
                    'post_id' => (string) $crm_post_id,
                    'crm_post_id' => (string) $crm_post_id,
                    'jobs_post_id' => (string) $jobs_post_id,
                    'role_title' => $role_title,
                    'company' => $company_name,
                    'location' => $location,
                    'sector' => $sector_label,
                    'seniority' => $seniority,
                ],
                home_url('/terminal/')
            );
            $render_mobile_post_action = function () use ($direct_apply_url, $public_opportunity_url) {
                ob_start();
                ?>
                <span class="sffc-community-editorial__post-mobile-action">
                    <?php if ($direct_apply_url !== '') : ?>
                        <button type="button" class="sffc-community-editorial__button is-primary sffc-community-editorial__post-apply-button" data-sffc-community-direct-open data-sffc-community-post-action-label="<?php esc_attr_e('Apply', 'senna-finance'); ?>">
                            <?php esc_html_e('Apply', 'senna-finance'); ?>
                            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h13M13 6l6 6-6 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
                        </button>
                    <?php else : ?>
                        <a class="sffc-community-editorial__button is-primary sffc-community-editorial__post-apply-button" href="<?php echo esc_url($public_opportunity_url); ?>" target="_blank" rel="noopener noreferrer" data-sffc-community-post-action-label="<?php esc_attr_e('View', 'senna-finance'); ?>">
                            <?php esc_html_e('View', 'senna-finance'); ?>
                            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h13M13 6l6 6-6 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
                        </a>
                    <?php endif; ?>
                </span>
                <?php
                return ob_get_clean();
            };
            $category_highlight_label = trim((string) $category_highlight_label);
            $current_user = $is_logged_in ? wp_get_current_user() : null;
            $alert_default_name = $current_user instanceof WP_User
                ? trim((string) ($current_user->display_name ?: $current_user->user_login))
                : '';
            $alert_default_email = $current_user instanceof WP_User ? trim((string) $current_user->user_email) : '';
