        private function get_crm_editorial_discovery_location_options(array $recruiters)
        {
            $options = [];

            foreach ($recruiters as $recruiter) {
                $location = trim((string) (($recruiter['location'] ?? '')));
                if ($location !== '') {
                    $options[$location] = $location;
                }
            }

            ksort($options, SORT_NATURAL | SORT_FLAG_CASE);

            return array_values($options);
        }

        private function get_crm_editorial_discovery_industry_options(array $recruiters)
        {
            $labels = [
                'investment_banking' => __('Investment Banking (PE feeder)', 'senna-finance'),
                'private_equity' => __('Private Equity', 'senna-finance'),
                'family_office' => __('Investor Relations / Family Office', 'senna-finance'),
                'venture_capital' => __('Growth Equity / Venture Capital', 'senna-finance'),
                'consulting' => __('Portfolio Operations', 'senna-finance'),
                'asset_management' => __('Real Assets / Infrastructure', 'senna-finance'),
                'wealth_management' => __('Wealth Management', 'senna-finance'),
                'boutique' => __('Boutique', 'senna-finance'),
                'technology' => __('Technology', 'senna-finance'),
                'fintech' => __('Fintech', 'senna-finance'),
                'investment_management' => __('Investment Management', 'senna-finance'),
                'corporate_finance' => __('Private Credit', 'senna-finance'),
                'accounting' => __('Fund Finance', 'senna-finance'),
                'other' => __('Other PE track', 'senna-finance'),
            ];
            $options = [];

            foreach ($recruiters as $recruiter) {
                $industries = array_filter(array_map('trim', explode('|', (string) ($recruiter['industry_values'] ?? ''))));
                foreach ($industries as $industry) {
