        private function get_crm_editorial_community_market_articles($limit = 6, $post_types = null)
        {
            $query_post_types = $post_types === null
                ? $this->get_crm_editorial_community_market_post_types()
                : array_values(array_filter(array_unique((array) $post_types), 'post_type_exists'));

            if (empty($query_post_types)) {
                return [];
            }

            $query = new WP_Query([
                'post_type' => $query_post_types,
                'posts_per_page' => max(1, absint($limit)),
                'post_status' => 'publish',
                'orderby' => 'date',
                'order' => 'DESC',
                'no_found_rows' => true,
                'update_post_meta_cache' => true,
                'update_post_term_cache' => false,
            ]);

            $articles = [];

            if ($query->have_posts()) {
                while ($query->have_posts()) {
                    $query->the_post();
                    $article = $this->build_crm_editorial_community_market_article_data(get_post());
                    if (!empty($article)) {
                        $articles[] = $article;
                    }
                }
                wp_reset_postdata();
            }

            return $articles;
        }

        private function get_crm_editorial_community_market_news_preview($limit = 5)
        {
            return $this->get_crm_editorial_community_market_articles(
                $limit,
                ['sffc_pe_news', 'sffc_pe_deal', 'sffc_pe_signal']
            );
        }

        private function get_crm_editorial_community_market_post_types()
        {
            $post_types = ['sffc_pe_news', 'sffc_pe_deal', 'sffc_pe_signal'];

            if (post_type_exists('sffc_pe_markets')) {
                $post_types[] = 'sffc_pe_markets';
            }

            return array_values(array_filter(array_unique($post_types), 'post_type_exists'));
        }

        private function get_crm_editorial_community_market_type_label($post_type)
        {
            if ($post_type === 'sffc_pe_news') {
                return __('News', 'senna-finance');
            }

            if ($post_type === 'sffc_pe_signal') {
                return __('Signal', 'senna-finance');
            }

            if ($post_type === 'sffc_pe_deal') {
                return __('Deal', 'senna-finance');
            }

            return __('Markets', 'senna-finance');
        }

        private function build_crm_editorial_community_market_article_data($post)
        {
            $post = get_post($post);
            if (!$post instanceof WP_Post || $post->post_status !== 'publish') {
                return null;
            }

            $allowed_post_types = $this->get_crm_editorial_community_market_post_types();
            if (!in_array($post->post_type, $allowed_post_types, true)) {
                return null;
            }

            $post_id = (int) $post->ID;
            $content = (string) $post->post_content;
            $title = $this->get_market_article_display_title($post);
            $excerpt = has_excerpt($post) ? $post->post_excerpt : wp_trim_words(wp_strip_all_tags($content), 28, '...');

            return [
                'id' => $post_id,
                'title' => $title,
                'excerpt' => wp_trim_words((string) $excerpt, 28, '...'),
                'url' => get_permalink($post),
                'featured_image' => get_the_post_thumbnail_url($post_id, 'large'),
                'post_type' => $post->post_type,
                'type_label' => $this->get_crm_editorial_community_market_type_label($post->post_type),
                'published_label' => sprintf(__('%s ago', 'senna-finance'), human_time_diff((int) get_post_time('U', true, $post), current_time('timestamp', true))),
            ];
        }

