                        <?php foreach ($articles as $article) : ?>
                            <?php
                            $article_title = (string) ($article['title'] ?? __('Market article', 'senna-finance'));
                            $article_type = (string) ($article['type_label'] ?? __('Markets', 'senna-finance'));
                            $article_initial = function_exists('mb_substr')
                                ? mb_strtoupper(mb_substr($article_type !== '' ? $article_type : $article_title, 0, 1))
                                : strtoupper(substr($article_type !== '' ? $article_type : $article_title, 0, 1));
                            ?>
                            <article class="sffc-community-editorial__market-story" data-market-story-type="<?php echo esc_attr((string) ($article['post_type'] ?? '')); ?>">
                                <div class="sffc-community-editorial__market-story-media" aria-hidden="true">
                                    <?php if (!empty($article['featured_image'])) : ?>
                                        <img src="<?php echo esc_url((string) $article['featured_image']); ?>" alt="">
                                    <?php else : ?>
                                        <span><?php echo esc_html($article_initial !== '' ? $article_initial : 'M'); ?></span>
                                    <?php endif; ?>
                                </div>
                                <div class="sffc-community-editorial__market-story-copy">
                                    <span class="sffc-community-editorial__market-story-type"><?php echo esc_html(implode(' • ', array_values(array_filter([$article_type, (string) ($article['published_label'] ?? '')])))); ?></span>
                                    <h3>
                                        <a href="<?php echo esc_url((string) ($article['url'] ?? '#')); ?>">
                                            <?php echo esc_html($article_title); ?>
                                        </a>
                                    </h3>
                                    <?php if (!empty($article['excerpt'])) : ?>
                                        <p><?php echo esc_html((string) $article['excerpt']); ?></p>
                                    <?php endif; ?>
                                    <div class="sffc-community-editorial__chips" aria-label="<?php esc_attr_e('Article labels', 'senna-finance'); ?>">
                                        <span><?php echo esc_html($article_type); ?></span>
                                    </div>
                                </div>
                                <a class="sffc-community-editorial__market-story-cta" href="<?php echo esc_url((string) ($article['url'] ?? '#')); ?>">
                                    <?php echo esc_html($this->localize_interface_copy('View Article', 'عرض المقال', $community_locale)); ?>
                                </a>
                            </article>
                        <?php endforeach; ?>
                    </div>
                <?php else : ?>
                    <article class="sffc-community-editorial__empty">
                        <h2><?php echo esc_html($this->localize_interface_copy('No market articles available yet', 'لا توجد مقالات سوق متاحة بعد', $community_locale)); ?></h2>
                        <p><?php echo esc_html($this->localize_interface_copy('As new private equity news, market notes, and signals are published, they will appear here.', 'عند نشر أخبار وأسواق وإشارات جديدة للأسهم الخاصة ستظهر هنا مباشرة.', $community_locale)); ?></p>
                    </article>
                <?php endif; ?>
            </section>
            <?php

            return (string) ob_get_clean();
        }

        private function enqueue_member_pricing_signup_assets()
        {
            $css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-signup.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/member-pricing-signup.css') : SFFC_VERSION;
            $js_version = file_exists(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-signup.js') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/js/crm/member-pricing-signup.js') : SFFC_VERSION;
            $member_signup_locale = $this->get_member_pricing_signup_locale();
            $member_signup_i18n = $this->get_member_signup_i18n($member_signup_locale);

            wp_enqueue_style(
                'sffc-member-pricing-signup',
                SFFC_PLUGIN_URL . 'assets/css/crm/member-pricing-signup.css',
                [],
                $css_version
            );

            wp_enqueue_script(
                'sffc-member-pricing-signup',
                SFFC_PLUGIN_URL . 'assets/js/crm/member-pricing-signup.js',
                [],
                $js_version,
                true
            );

            wp_localize_script('sffc-member-pricing-signup', 'sffcMemberPricingSignup', [
                'ajaxUrl' => admin_url('admin-ajax.php'),
                'nonce' => wp_create_nonce('sffc_member_pricing_signup'),
                'prefillNonce' => wp_create_nonce('sffc_sync_signup_prefill'),
                'loginUrl' => home_url('/login/'),
                'locale' => $member_signup_locale,
                'overlayAction' => 'sffc_load_job_member_signup_overlay',
                'messages' => [
                    'invalidIdentity' => $member_signup_i18n['invalid_identity'],
                    'missingStudy' => $member_signup_i18n['missing_study'],
                    'invalidEmailOnly' => __('Enter a valid email address to get started.', 'senna-finance'),
                    'overlayLoadFailed' => __('We could not load this signup flow right now. Please try again.', 'senna-finance'),
                    'joinFailed' => __('We could not continue to memberships right now. Please try again.', 'senna-finance'),
                ],
            ]);

            return [$member_signup_locale, $member_signup_i18n];
        }

        private function render_crm_cv_match_job_posts_variant($atts = [], $variant = 'default', $use_signup_overlay = false)
        {
            $atts = shortcode_atts([
                'jobs_post_id' => 0,
                'limit' => 24,
                'search' => '',
            ], $atts, $variant === 'finance_community' ? 'sffc_crm_finance_careers_community_job_posts' : 'sffc_crm_cv_match_job_posts');

            $cv_match_css_version = file_exists(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') ? (string) filemtime(SFFC_PLUGIN_DIR . 'assets/css/crm/cv-match-studio.css') : SFFC_VERSION;
            wp_enqueue_style(
                'sffc-crm-cv-match-studio',
                SFFC_PLUGIN_URL . 'assets/css/crm/cv-match-studio.css',
                [],
                $cv_match_css_version
            );

            if ($use_signup_overlay) {
                $this->enqueue_member_pricing_signup_assets();
            }

            $user_id = get_current_user_id();
            $is_logged_in = is_user_logged_in();
            $resume_payload = $is_logged_in
                ? $this->get_crm_reddit_active_resume_text($user_id)
                : ['cv_text' => '', 'has_cv' => false];
            $preferred_industry = $user_id > 0
                ? $this->get_cv_match_studio_user_preferred_industry($user_id)
                : '';
            if ($preferred_industry === '') {
                $preferred_industry = 'finance';
            }
            $resume_payload['preferred_industry'] = $preferred_industry;

            $jobs_post_id = $this->resolve_crm_reddit_jobs_post_id($atts['jobs_post_id']);
            $limit = max(1, min(48, absint($atts['limit'])));
            $search_term = sanitize_text_field((string) $atts['search']);
            if ($search_term === '') {
                $search_term = sanitize_text_field((string) wp_unslash($_GET['sffc_cv_match_posts_search'] ?? ''));
            }

            if ($jobs_post_id > 0) {
                $single_item = $this->get_cached_cv_match_job_posts_item($jobs_post_id);
                $items = !empty($single_item) ? [$single_item] : [];
            } else {
                $items = $this->get_cv_match_studio_jobs_mailbox_items($user_id, $resume_payload, $limit, $search_term, 0);
            }

            $is_finance_community = $variant === 'finance_community';
            $community_home_url = home_url('/');
            $community_login_url = home_url('/login/');
            $community_join_prefill_email = $this->get_signup_email_prefill_value();
            $community_people_hiring_url = add_query_arg('tab', 'discover', home_url('/terminal/'));
            $community_saved_lists_url = add_query_arg('tab', 'saved-lists', home_url('/terminal/'));
            $community_lists_url = add_query_arg('tab', 'newsletter-groups', home_url('/terminal/'));
            $community_support_mailto = 'mailto:support.team@joinsenna.com';
            $community_terminal_url = home_url('/terminal/?tab=dashboard');
            $community_profile_url = home_url('/terminal/?tab=profile');
            $community_memberships_url = home_url('/memberships/');
            $community_locale = $this->get_member_pricing_signup_locale();
            $community_account_user = $user_id > 0 ? $this->get_crm_reddit_account_user($user_id) : [];
            $community_avatar_url = $user_id > 0 ? $this->get_crm_reddit_profile_avatar_url($user_id, $community_account_user) : '';
            $community_first_name = $this->get_crm_reddit_current_user_first_name($user_id);
            $community_display_name = trim((string) ($community_account_user['display_name'] ?? ''));
            if ($community_display_name === '' && $community_first_name !== '') {
                $community_display_name = $community_first_name;
            }
            if ($community_display_name === '') {
                $community_display_name = $this->localize_interface_copy('MENA Careers member', 'عضو سنّا', $community_locale);
            }
            $community_avatar_initial = function_exists('mb_substr')
                ? mb_strtoupper(mb_substr($community_display_name, 0, 1))
                : strtoupper(substr($community_display_name, 0, 1));
