            ?>
            <section class="sffc-cv-match-job-posts<?php echo $is_finance_community ? ' sffc-cv-match-job-posts--finance-community' : ''; ?><?php echo $use_signup_overlay ? ' sffc-cv-match-job-posts--signup-overlay' : ''; ?>" dir="<?php echo esc_attr($this->is_arabic_locale($community_locale) ? 'rtl' : 'ltr'); ?>" data-locale="<?php echo esc_attr($this->is_arabic_locale($community_locale) ? 'ar' : 'en'); ?>" data-component="crm-cv-match-job-posts"<?php echo $use_signup_overlay ? ' data-sffc-job-signup-overlay-root' : ''; ?>>
                <div class="sffc-cv-match-studio__jobs-posts-shell">
                    <header class="sffc-cv-match-studio__community-headerbar">
                        <div class="sffc-cv-match-studio__community-headerbar-brand">
                            <span class="sffc-cv-match-studio__brand-mark" aria-hidden="true">
                                <span class="sffc-cv-match-studio__brand-glyph">S</span>
                                <span class="sffc-cv-match-studio__brand-dot"></span>
                            </span>
	                            <div class="sffc-cv-match-studio__brand-copy">
			                                <strong><?php echo esc_html($this->localize_interface_copy('Finance Career Guidance', 'مجتمع الأسهم الخاصة', $community_locale)); ?></strong>
	                                <span><?php echo esc_html($this->localize_interface_copy('MENA Careers', 'سنّا', $community_locale)); ?></span>
	                            </div>
