                                    <?php echo esc_html($this->localize_interface_copy('Open terminal', 'فتح المنصة', $community_locale)); ?>
                                </a>
                                <div class="sffc-cv-match-studio__community-account" data-cv-match-community-account>
                                    <button
                                        type="button"
                                        class="sffc-cv-match-studio__community-avatar-toggle"
                                        data-cv-match-community-account-toggle
                                        aria-expanded="false"
                                        aria-haspopup="menu"
                                        aria-label="<?php echo esc_attr($this->localize_interface_copy('Open account menu', 'فتح قائمة الحساب', $community_locale)); ?>">
