                    <?php if (empty($items)) : ?>
                        <article class="sffc-cv-match-studio__jobs-mailbox-empty">
                            <span class="sffc-cv-match-studio__jobs-mailbox-empty-kicker"><?php echo esc_html($this->localize_interface_copy('No roles found', 'لا توجد أدوار حالياً', $community_locale)); ?></span>
                            <h3><?php echo esc_html($this->localize_interface_copy('No job posts are available yet', 'لا توجد فرص منشورة بعد', $community_locale)); ?></h3>
                            <p><?php echo esc_html($this->localize_interface_copy('Try again once more roles have been added to the mailbox feed.', 'جرّب مرة أخرى بعد إضافة فرص جديدة إلى صندوق الوظائف.', $community_locale)); ?></p>
