                            $match_score = max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0)));
                            $sender_label = $this->build_cv_match_studio_jobs_mailbox_sender_label($item);
                            $raw_recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
