                                                <input type="hidden" name="sffc_job_post_location" value="<?php echo esc_attr($location); ?>">
                                                <input type="hidden" name="sffc_job_post_company" value="<?php echo esc_attr($public_company_name); ?>">
                                                <input type="hidden" name="sffc_job_post_url" value="<?php echo esc_url($view_url !== '' ? $view_url : ($apply_url !== '' ? $apply_url : $community_home_url)); ?>">
