                                                    <?php esc_html_e('Join MENA Careers', 'senna-finance'); ?>
                                                </button>
                                            </form>
                                        <?php endif; ?>
                                    </div>

                                    <div class="sffc-cv-match-studio__job-post-description">
                                        <?php echo $this->render_cv_match_studio_jobs_mailbox_body_sections($message_body, 'sffc-cv-match-studio__jobs-mailbox-messagebody', false); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
