        private function ensure_cv_match_newsletter_tables()
        {
            global $wpdb;

            $newsletters_table = $wpdb->prefix . 'sffc_crm_newsletters';
            $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';

            if (
                $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $newsletters_table)) !== $newsletters_table
                || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $subscriptions_table)) !== $subscriptions_table
            ) {
                if (class_exists('SFFC_CRM_Database_Schema')) {
                    SFFC_CRM_Database_Schema::get_instance()->create_newsletter_tables();
                }
            }

            return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $newsletters_table)) === $newsletters_table
                && $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $subscriptions_table)) === $subscriptions_table;
        }

        private function find_cv_match_studio_job_post_matched_group(array $item, array $groups)
        {
            if (empty($groups)) {
                return [null, 0];
            }

            $group_slug_map = [];
            foreach ($groups as $group) {
                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                if ($slug !== '') {
                    $group_slug_map[$slug] = $group;
                }
            }

            $matched_slugs = $this->get_cv_match_studio_mailbox_group_slugs($item);
            $matched_groups = [];
            foreach ($matched_slugs as $slug) {
                if ($slug !== '' && isset($group_slug_map[$slug])) {
                    $matched_groups[] = $group_slug_map[$slug];
                }
            }

            if (!empty($matched_groups)) {
                usort($matched_groups, static function ($left, $right) {
                    return ((int) ($right['total'] ?? 0)) <=> ((int) ($left['total'] ?? 0));
                });

                return [$matched_groups[0], max(0, count($matched_groups) - 1)];
            }

            $role_title = strtolower(trim((string) ($item['role_title'] ?? '')));
            $company_name = strtolower(trim((string) ($item['company'] ?? '')));
            $location = strtolower(trim((string) ($item['location'] ?? '')));
            $best_group = null;
            $best_score = 0;

            foreach ($groups as $group) {
                $score = 0;
                foreach ((array) ($group['roles'] ?? []) as $role) {
                    $candidate_title = strtolower(trim((string) ($role['title'] ?? '')));
                    $candidate_company = strtolower(trim((string) ($role['company'] ?? '')));
                    $candidate_location = strtolower(trim((string) ($role['location'] ?? '')));

                    if ($role_title !== '' && $candidate_title === $role_title) {
                        $score += 5;
                    }
                    if ($company_name !== '' && $candidate_company === $company_name) {
                        $score += 4;
                    }
                    if ($location !== '' && $candidate_location === $location) {
                        $score += 3;
                    }
                }

                if ($score > $best_score) {
                    $best_score = $score;
                    $best_group = $group;
                }
            }

            return [$best_score > 0 ? $best_group : null, 0];
        }

        private function get_cv_match_studio_newsletters($user_id = 0)
        {
            global $wpdb;

            if (!$this->ensure_cv_match_newsletter_tables()) {
                return [];
            }

            $newsletters_table = $wpdb->prefix . 'sffc_crm_newsletters';
            $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';
            $user_id = (int) $user_id;

            $rows = $wpdb->get_results(
                "SELECT id, slug, title, description, image_url, frequency, badge_label, display_order
                 FROM {$newsletters_table}
                 WHERE is_active = 1
                 ORDER BY display_order ASC, title ASC
                 LIMIT 24",
                ARRAY_A
            ) ?: [];

            if ($user_id <= 0 || empty($rows)) {
                return array_map(static function ($row) {
                    $row['is_subscribed'] = false;
                    return $row;
                }, $rows);
            }

            $newsletter_ids = array_map('intval', wp_list_pluck($rows, 'id'));
            $placeholders = implode(',', array_fill(0, count($newsletter_ids), '%d'));
            $subscribed_ids = $wpdb->get_col($wpdb->prepare(
                "SELECT newsletter_id
                 FROM {$subscriptions_table}
                 WHERE user_id = %d
                   AND status = 'subscribed'
                   AND newsletter_id IN ({$placeholders})",
                array_merge([$user_id], $newsletter_ids)
            )) ?: [];
            $subscribed_map = array_fill_keys(array_map('intval', $subscribed_ids), true);

            foreach ($rows as &$row) {
                $row['is_subscribed'] = !empty($subscribed_map[(int) $row['id']]);
            }
            unset($row);

            return $rows;
        }

        private function get_cv_match_studio_welcome_newsletter_choices(array $newsletters, $limit = 4)
        {
            $limit = max(1, (int) $limit);
            $choices = [];
            $seen_fingerprints = [];
            $seen_categories = [];

            foreach ($newsletters as $newsletter) {
                $fingerprint = $this->get_cv_match_studio_welcome_newsletter_fingerprint($newsletter);
                $category = $this->get_cv_match_studio_welcome_newsletter_category($newsletter);
                if ($fingerprint !== '' && isset($seen_fingerprints[$fingerprint])) {
                    continue;
                }
                if ($category !== '' && isset($seen_categories[$category])) {
                    continue;
                }

                $newsletter['welcome_meta'] = $this->get_cv_match_studio_welcome_newsletter_meta($newsletter);
                $choices[] = $newsletter;

                if ($fingerprint !== '') {
                    $seen_fingerprints[$fingerprint] = true;
                }
                if ($category !== '') {
                    $seen_categories[$category] = true;
                }

                if (count($choices) >= $limit) {
                    return $choices;
                }
            }

            foreach ($newsletters as $newsletter) {
                $fingerprint = $this->get_cv_match_studio_welcome_newsletter_fingerprint($newsletter);
                if ($fingerprint !== '' && isset($seen_fingerprints[$fingerprint])) {
                    continue;
                }

                $newsletter['welcome_meta'] = $this->get_cv_match_studio_welcome_newsletter_meta($newsletter);
                $choices[] = $newsletter;

                if ($fingerprint !== '') {
                    $seen_fingerprints[$fingerprint] = true;
                }

                if (count($choices) >= $limit) {
                    break;
                }
            }

            return array_slice($choices, 0, $limit);
        }

        private function get_cv_match_studio_welcome_newsletter_fingerprint(array $newsletter)
        {
            $value = strtolower(trim((string) ($newsletter['title'] ?? $newsletter['slug'] ?? '')));
            if ($value === '') {
                return '';
            }

            $value = str_replace(
                ['internships', 'internship', 'interns', 'roles', 'role', 'jobs', 'job', 'newsletter', 'newsletters', 'digest', 'digests', 'alerts', 'alert', 'weekly', 'daily', 'finance', '-', '_'],
                ' ',
                $value
            );
            $value = preg_replace('/\s+/', ' ', (string) $value);

            return trim((string) $value);
        }

        private function get_cv_match_studio_welcome_newsletter_category(array $newsletter)
        {
            $haystack = strtolower(trim(implode(' ', array_filter([
                (string) ($newsletter['slug'] ?? ''),
                (string) ($newsletter['title'] ?? ''),
                (string) ($newsletter['description'] ?? ''),
                (string) ($newsletter['badge_label'] ?? ''),
            ]))));

            if ($haystack === '') {
                return '';
            }

            $category_terms = [
                'private_equity' => ['finance', 'pe '],
                'investment_banking' => ['investment banking', 'ib '],
                'asset_management' => ['asset management'],
                'hedge_fund' => ['hedge fund'],
                'consulting' => ['consulting'],
                'internships' => ['internship', 'graduate', 'early career'],
                'riyadh' => ['riyadh', 'saudi'],
                'dubai' => ['dubai', 'uae', 'emirates'],
                'abu_dhabi' => ['abu dhabi'],
                'cairo' => ['cairo', 'egypt'],
                'recruiters' => ['recruiter', 'hiring team', 'talent'],
            ];

            foreach ($category_terms as $category => $terms) {
                foreach ($terms as $term) {
                    if (strpos($haystack, $term) !== false) {
                        return $category;
                    }
                }
            }

            return $this->get_cv_match_studio_welcome_newsletter_fingerprint($newsletter);
        }

        private function get_cv_match_studio_welcome_newsletter_meta(array $newsletter)
        {
            $meta = trim((string) ($newsletter['badge_label'] ?? ''));
            if ($meta !== '') {
                return $meta;
            }

            $frequency = trim((string) ($newsletter['frequency'] ?? ''));
            if ($frequency !== '') {
                return ucwords(str_replace(['_', '-'], ' ', strtolower($frequency)));
            }

            $description = trim(wp_strip_all_tags((string) ($newsletter['description'] ?? '')));
            if ($description !== '') {
                return wp_trim_words($description, 8, '');
            }

            return '';
        }

        private function subscribe_cv_match_user_to_newsletter($user_id, $newsletter_id)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $newsletter_id = (int) $newsletter_id;
            if ($user_id <= 0 || $newsletter_id <= 0 || !$this->ensure_cv_match_newsletter_tables()) {
                return false;
            }

            $newsletters_table = $wpdb->prefix . 'sffc_crm_newsletters';
            $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';
            $newsletter = $wpdb->get_row($wpdb->prepare(
                "SELECT id, slug, title, description, frequency, badge_label FROM {$newsletters_table} WHERE id = %d AND is_active = 1 LIMIT 1",
                $newsletter_id
            ), ARRAY_A);
            if (empty($newsletter)) {
                return false;
            }

            $existing = $wpdb->get_row($wpdb->prepare(
                "SELECT id FROM {$subscriptions_table} WHERE newsletter_id = %d AND user_id = %d LIMIT 1",
                $newsletter_id,
                $user_id
            ), ARRAY_A);
            $now = current_time('mysql');
            $user = get_user_by('id', $user_id);
            $user_email = $user instanceof WP_User ? (string) $user->user_email : '';

            if ($existing) {
                $wpdb->update(
                    $subscriptions_table,
                    [
                        'user_email' => $user_email,
                        'status' => 'subscribed',
                        'subscribed_at' => $now,
                        'unsubscribed_at' => null,
                        'updated_at' => $now,
                    ],
                    ['id' => (int) $existing['id']],
                    ['%s', '%s', '%s', '%s', '%s'],
                    ['%d']
                );
            } else {
                $wpdb->insert(
                    $subscriptions_table,
                    [
                        'newsletter_id' => $newsletter_id,
                        'user_id' => $user_id,
                        'user_email' => $user_email,
                        'status' => 'subscribed',
                        'subscribed_at' => $now,
                        'updated_at' => $now,
                    ],
                    ['%d', '%d', '%s', '%s', '%s', '%s']
                );
            }

            if (!empty($wpdb->last_error)) {
                return false;
            }

            $this->sync_cv_match_newsletter_alert_profile_for_user($user_id, $newsletter, true);

            return true;
        }

