        private function get_cv_match_studio_dashboard_role_samples(array $groups, $limit = 4)
        {
            $samples = [];
            foreach ($groups as $group) {
                $roles = array_values(array_filter((array) ($group['roles'] ?? []), 'is_array'));
                if (empty($roles)) {
                    continue;
                }

                $random_index = count($roles) > 1 ? wp_rand(0, count($roles) - 1) : 0;
                $samples[] = [
                    'group' => $group,
                    'role' => $roles[$random_index],
                ];
            }

            if (count($samples) > 1) {
                shuffle($samples);
            }

            return array_slice($samples, 0, max(1, (int) $limit));
        }

        private function get_cv_match_studio_dashboard_preference_role_samples(array $groups, $limit = 4, $user_id = 0, array $resume_payload = [], $preferred_location = '', $preferred_industry = '', $is_logged_in = false)
        {
            $limit = max(1, (int) $limit);
            if (empty($groups)) {
                return [];
            }

            $user_id = (int) $user_id;
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $cv_profile = ($is_logged_in && $user_id > 0 && $cv_text !== '')
                ? $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true)
                : [];
            $role_label = $is_logged_in ? $this->get_crm_reddit_dashboard_primary_cv_role_label($cv_profile) : '';
            $role_label_normalized = $this->normalize_crm_reddit_dashboard_cv_text((string) $role_label);
            $location_terms = $is_logged_in
                ? $this->get_cv_match_studio_dashboard_location_terms_for_preference($preferred_location)
                : $this->get_cv_match_studio_detected_location_terms();
            if (empty($location_terms)) {
                $location_terms = $this->get_cv_match_studio_detected_location_terms();
            }
            $ranked = [];

            if (count($groups) > 1) {
                shuffle($groups);
            }

            foreach ($groups as $group_index => $group) {
                $roles = array_values(array_filter((array) ($group['roles'] ?? []), 'is_array'));
                if (empty($roles)) {
                    continue;
                }

                $best_sample = null;
                $best_score = -1;
                foreach ($roles as $role_index => $role) {
                    $item = $this->build_cv_match_studio_dashboard_sample_score_item((array) $group, (array) $role);
                    $score = 0;
                    $location_score = $this->score_cv_match_studio_dashboard_sample_location_match($item, $location_terms);

                    if ($is_logged_in) {
                        if ($cv_text !== '' || !empty($cv_profile)) {
                            $score = $this->build_crm_reddit_dashboard_match_score($item, $cv_text, $cv_profile);
                        }

                        $preferred_industry_score = $this->score_cv_match_studio_preferred_industry_match($item, $preferred_industry, $cv_text);
                        if ($preferred_industry_score > 0) {
                            $score = ($cv_text !== '' || !empty($cv_profile))
                                ? $score + $preferred_industry_score
                                : max($score, 44 + $preferred_industry_score);
                        }

                        if ($role_label_normalized !== '') {
                            $title_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                                (string) ($item['role_title'] ?? ''),
                                (string) ($item['seniority'] ?? ''),
                                implode(' ', array_map('strval', (array) ($item['keywords'] ?? []))),
                            ])));
                            if ($title_haystack !== '' && strpos($title_haystack, $role_label_normalized) !== false) {
                                $score += 14;
                            }
                        }

                        $score += $location_score;
                        if ($score <= 0) {
                            $score = 30 + $location_score + ($role_index % 5);
                        }
                    } else {
                        $score = 40 + $location_score;
                        $score += !empty($item['recruiter_name']) ? 4 : 0;
                        $score += !empty($item['company_logo']) ? 3 : 0;
                        $score += !empty($item['keywords']) ? min(6, count((array) ($item['keywords'] ?? []))) : 0;
                        $score += (($group_index + $role_index) % 7);
                    }

                    if ($best_sample === null || $score > $best_score) {
                        $best_sample = [
                            'group' => $group,
                            'role' => $role,
                            '_score' => (int) $score,
                            '_location_score' => (int) $location_score,
                            '_group_order' => (int) $group_index,
                        ];
                        $best_score = $score;
                    }
                }

                if ($best_sample !== null) {
                    $ranked[] = $best_sample;
                }
            }

            usort($ranked, static function ($left, $right) {
                $score_compare = ((int) ($right['_score'] ?? 0)) <=> ((int) ($left['_score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                $location_compare = ((int) ($right['_location_score'] ?? 0)) <=> ((int) ($left['_location_score'] ?? 0));
                if ($location_compare !== 0) {
                    return $location_compare;
                }

                return ((int) ($left['_group_order'] ?? 0)) <=> ((int) ($right['_group_order'] ?? 0));
            });

            $ranked = array_values($ranked);
            if (!empty($location_terms)) {
                $location_matched = array_values(array_filter($ranked, static function ($sample) {
                    return (int) ($sample['_location_score'] ?? 0) > 0;
                }));

                if (!empty($location_matched) && count($location_matched) >= $limit) {
                    return array_slice($location_matched, 0, $limit);
                }

                if (!empty($location_matched)) {
                    $ranked = array_merge(
                        $location_matched,
                        array_values(array_filter($ranked, static function ($sample) {
                            return (int) ($sample['_location_score'] ?? 0) <= 0;
                        }))
                    );
                }
            }

            return $this->shuffle_cv_match_studio_dashboard_samples_within_window($ranked, $limit);
        }

        private function shuffle_cv_match_studio_dashboard_samples_within_window(array $samples, $limit = 4)
        {
            $limit = max(1, (int) $limit);
            $samples = array_values($samples);
            if (empty($samples)) {
                return [];
            }

            $top_window = array_slice($samples, 0, min(count($samples), max($limit * 2, $limit)));
            $remainder = array_slice($samples, count($top_window));

            $sample_buckets = [];
            foreach ($top_window as $sample) {
                $score_key = (string) ((int) ($sample['_score'] ?? 0));
                if (!isset($sample_buckets[$score_key])) {
                    $sample_buckets[$score_key] = [];
                }
                $sample_buckets[$score_key][] = $sample;
            }

            $score_keys = array_map('intval', array_keys($sample_buckets));
            rsort($score_keys, SORT_NUMERIC);

            $shuffled = [];
            foreach ($score_keys as $score_key) {
                $bucket = $sample_buckets[(string) $score_key] ?? [];
                if (count($bucket) > 1) {
                    shuffle($bucket);
                }
                foreach ($bucket as $entry) {
                    $shuffled[] = $entry;
                }
            }

            if (!empty($remainder)) {
                $shuffled = array_merge($shuffled, $remainder);
            }

            if (count($shuffled) > $limit) {
                $display_pool = array_slice($shuffled, 0, min(count($shuffled), max($limit + 2, $limit)));
                if (count($display_pool) > $limit) {
                    $fixed = array_slice($display_pool, 0, max(1, $limit - 1));
                    $tail_pool = array_slice($display_pool, max(1, $limit - 1));
                    if (count($tail_pool) > 1) {
                        shuffle($tail_pool);
                    }
                    $shuffled = array_merge($fixed, $tail_pool, array_slice($shuffled, count($display_pool)));
                }
            }

            return array_slice($shuffled, 0, $limit);
        }

        private function build_cv_match_studio_dashboard_sample_score_item(array $group, array $role)
        {
            $keywords = array_values(array_filter([
                sanitize_text_field((string) ($role['sector'] ?? '')),
                sanitize_text_field((string) ($role['seniority'] ?? '')),
                sanitize_text_field((string) ($group['name'] ?? '')),
                sanitize_text_field((string) ($group['location'] ?? '')),
                sanitize_text_field((string) ($group['description'] ?? '')),
            ]));

            return [
                'role_title' => sanitize_text_field((string) ($role['title'] ?? '')),
                'location' => sanitize_text_field((string) ($role['location'] ?? ($group['location'] ?? ''))),
                'seniority' => sanitize_text_field((string) ($role['seniority'] ?? '')),
                'keywords' => $keywords,
                'industry' => sanitize_text_field((string) ($role['sector'] ?? '')),
                'company_name' => sanitize_text_field((string) ($role['company'] ?? '')),
                'company_logo' => esc_url_raw((string) ($role['logo'] ?? '')),
                'recruiter_name' => sanitize_text_field((string) ($role['recruiter'] ?? '')),
                'group_name' => sanitize_text_field((string) ($group['name'] ?? '')),
                'group_description' => sanitize_text_field((string) ($group['description'] ?? '')),
            ];
        }

        private function score_cv_match_studio_dashboard_sample_location_match(array $item, array $terms)
        {
            if (empty($terms)) {
                return 0;
            }

            $location = strtolower(trim((string) ($item['location'] ?? '')));
            $keywords = array_map('strval', (array) ($item['keywords'] ?? []));
            $haystack = strtolower(trim(implode(' ', array_filter(array_merge(
                [$location],
                $keywords,
                [
                    (string) ($item['group_name'] ?? ''),
                    (string) ($item['group_description'] ?? ''),
                ]
            )))));
            $score = 0;

            foreach ($terms as $term) {
                $term = strtolower(trim((string) $term));
                if ($term === '') {
                    continue;
                }

                if ($location !== '' && strpos($location, $term) !== false) {
                    $score += 24;
                }

                if ($haystack !== '' && strpos($haystack, $term) !== false) {
                    $score += 8;
                }
            }

            return min(40, $score);
        }

        private function get_cv_match_studio_dashboard_location_terms_for_preference($preferred_location)
        {
