            $map = [
                'uk' => ['london', 'united kingdom', 'uk', 'england'],
                'united_kingdom' => ['london', 'united kingdom', 'uk', 'england'],
                'london' => ['london', 'united kingdom', 'uk', 'england'],
                'us' => ['new york', 'united states', 'usa'],
                'united_states' => ['new york', 'united states', 'usa'],
                'new_york' => ['new york', 'united states', 'usa'],
                'france' => ['paris', 'france'],
                'paris' => ['paris', 'france'],
                'germany' => ['frankfurt', 'munich', 'berlin', 'germany'],
                'frankfurt' => ['frankfurt', 'munich', 'berlin', 'germany'],
                'spain' => ['madrid', 'barcelona', 'spain'],
                'madrid' => ['madrid', 'barcelona', 'spain'],
                'italy' => ['milan', 'rome', 'italy'],
                'milan' => ['milan', 'rome', 'italy'],
                'switzerland' => ['zurich', 'geneva', 'switzerland'],
                'zurich' => ['zurich', 'geneva', 'switzerland'],
                'netherlands' => ['amsterdam', 'netherlands'],
                'amsterdam' => ['amsterdam', 'netherlands'],
                'singapore' => ['singapore'],
                'dubai' => ['dubai', 'uae', 'united arab emirates'],
                'abu_dhabi' => ['abu dhabi', 'uae', 'united arab emirates'],
                'riyadh' => ['riyadh', 'jeddah', 'saudi', 'saudi arabia', 'ksa'],
                'cairo' => ['cairo', 'egypt'],
                'doha' => ['doha', 'qatar'],
                'bahrain' => ['manama', 'bahrain'],
                'kuwait' => ['kuwait', 'kuwait city'],
            ];

            return array_values(array_filter(array_unique(array_map('strtolower', (array) ($map[$preferred_location] ?? [])))));
        }

