        private function get_cv_match_studio_membership_dropdown_plans()
        {
            $plans = [];
            $preferred_account_type = sanitize_key($this->get_valid_signup_cookie_value('sffc_signup_account_type'));
            if (!in_array($preferred_account_type, ['platform', 'mentorship', 'all_access'], true)) {
                $preferred_account_type = 'platform';
            }

            foreach ((array) $this->get_subscription_plans() as $plan) {
                $name = trim((string) ($plan['name'] ?? ''));
                if ($name === '') {
                    continue;
                }

                $url = trim((string) ($plan['mp_url'] ?? ''));
                if ($url === '' && !empty($plan['shortcode'])) {
                    $product_id = $this->extract_memberpress_product_id_from_shortcode((string) $plan['shortcode']);
                    if ($product_id > 0) {
                        $url = (string) get_permalink($product_id);
                    }
                }
                if ($url === '') {
                    $url = $this->get_crm_reddit_membership_url();
                }

                $display_price = $this->format_plan_price_amount((array) $plan) ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $billing_cycle = trim((string) ($plan['billing_cycle'] ?? ''));
                $tagline = trim((string) ($plan['tagline'] ?? ($plan['audience'] ?? '')));
                $features = isset($plan['features']) && is_array($plan['features']) ? array_values(array_filter(array_map('trim', $plan['features']))) : [];
                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim(
                        implode(
                            ' ',
                            array_filter([
                                $name,
                                $tagline,
                                (string) ($plan['audience'] ?? ''),
                                implode(' ', $features),
                            ])
                        )
                    )
                );

                $plans[] = [
                    'name' => sanitize_text_field($name),
                    'slug' => sanitize_title((string) ($plan['slug'] ?? $name)),
                    'price' => sanitize_text_field($display_price),
                    'billing_cycle' => sanitize_text_field($billing_cycle),
                    'tagline' => sanitize_text_field($tagline),
                    'url' => esc_url_raw($url),
                    'shortcode' => isset($plan['shortcode']) ? wp_kses_post($plan['shortcode']) : '',
                    'memberpress_product_id' => !empty($plan['memberpress_product_id'])
                        ? (int) $plan['memberpress_product_id']
                        : $this->extract_memberpress_product_id_from_shortcode((string) ($plan['shortcode'] ?? '')),
                    'is_annual' => !empty($plan['is_annual']),
                    'is_featured' => !empty($plan['featured_signup']),
                    'signup_path' => $signup_path_meta['path'],
                ];
            }

            if (empty($plans)) {
                $plans[] = [
                    'name' => __('MENA Careers Membership', 'senna-finance'),
                    'slug' => 'senna-membership',
                    'price' => '',
                    'billing_cycle' => '',
                    'tagline' => __('Unlock full private equity role lists, recruiter contacts, and application tracking.', 'senna-finance'),
                    'url' => $this->get_crm_reddit_membership_url(),
                    'shortcode' => '',
                    'memberpress_product_id' => 0,
                    'is_annual' => false,
                    'is_featured' => true,
                    'signup_path' => 'platform',
                ];
            }

            usort($plans, static function ($a, $b) use ($preferred_account_type) {
                $score = static function ($plan) use ($preferred_account_type) {
                    $score = 0;
                    $plan_path = (string) ($plan['signup_path'] ?? 'platform');
                    $is_annual = !empty($plan['is_annual']);
                    $is_featured = !empty($plan['is_featured']);

                    if ($preferred_account_type === 'mentorship') {
                        if ($plan_path === 'mentorship') {
                            $score += 100;
                        }
                        if (!$is_annual) {
                            $score += 30;
                        }
                        if (!$is_featured) {
                            $score += 20;
                        }
                    } elseif ($preferred_account_type === 'all_access') {
                        if ($plan_path === 'all_access') {
                            $score += 120;
                        }
                        if ($is_featured) {
                            $score += 25;
                        }
                        if (!$is_annual) {
                            $score += 15;
                        }
                    } else {
                        if ($plan_path === 'platform') {
                            $score += 100;
                        }
                        if ($is_featured) {
                            $score += 30;
                        }
                        if (!$is_annual) {
                            $score += 10;
                        }
                    }

                    return $score;
                };

                $a_score = $score($a);
                $b_score = $score($b);
                if ($a_score !== $b_score) {
                    return $b_score <=> $a_score;
                }

                if ((bool) $a['is_annual'] !== (bool) $b['is_annual']) {
                    return (bool) $a['is_annual'] <=> (bool) $b['is_annual'];
                }

                if ((bool) $a['is_featured'] !== (bool) $b['is_featured']) {
                    return (bool) $b['is_featured'] <=> (bool) $a['is_featured'];
                }

                return strcmp((string) $a['name'], (string) $b['name']);
            });

            return array_slice($plans, 0, 4);
        }

        private function get_apply_chat_pricing_options()
        {
            $options = [];
            $targets = [
                'platform' => [
                    'title' => __('Applications Submitted For You', 'senna-finance'),
                    'signup_option_label' => __('Applications', 'senna-finance'),
                    'description' => __('Application handling with Career Assessment included where it strengthens the submission.', 'senna-finance'),
                ],
                'mentorship' => [
                    'title' => __('Applications + Recruiter Outreach', 'senna-finance'),
                    'signup_option_label' => __('Applications + Outreach', 'senna-finance'),
                    'description' => __('Application handling, recruiter outreach, and Career Assessment including CV and LinkedIn positioning.', 'senna-finance'),
                ],
            ];

            foreach ((array) $this->get_subscription_plans() as $plan) {
                if (!empty($plan['is_annual'])) {
                    continue;
                }

                $name = trim((string) ($plan['name'] ?? ''));
                $tagline = trim((string) ($plan['tagline'] ?? ($plan['audience'] ?? '')));
                $features = isset($plan['features']) && is_array($plan['features']) ? array_values(array_filter(array_map('trim', $plan['features']))) : [];
                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim(implode(' ', array_filter([$name, $tagline, implode(' ', $features)])))
                );
                $path = (string) ($signup_path_meta['path'] ?? '');
                if (!isset($targets[$path])) {
                    continue;
                }

                $display_price = $this->format_plan_price_amount((array) $plan) ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $score = 0;
                if (!empty($plan['featured_signup'])) {
                    $score += 100;
                }
                if (!empty($signup_path_meta['configured'])) {
                    $score += 50;
                }
                if ($path === 'platform' && !empty($plan['recruiter_contact_pricing'])) {
                    $score += 25;
                }

                $entry = [
                    'account_type' => $path,
                    'title' => $targets[$path]['title'],
                    'signup_option_label' => $targets[$path]['signup_option_label'],
                    'description' => $targets[$path]['description'],
                    'display_price' => sanitize_text_field($display_price),
                    'billing_cycle' => sanitize_text_field((string) ($plan['billing_cycle'] ?? '')),
                    '_score' => $score,
                ];

                if (!isset($options[$path]) || $entry['_score'] > $options[$path]['_score']) {
                    $options[$path] = $entry;
                }
            }

            foreach ($targets as $path => $fallback) {
                if (!isset($options[$path])) {
                    $options[$path] = [
                        'account_type' => $path,
                        'title' => $fallback['title'],
                        'signup_option_label' => $fallback['signup_option_label'],
                        'description' => $fallback['description'],
                        'display_price' => '',
                        'billing_cycle' => '',
                        '_score' => 0,
                    ];
                }
            }

            foreach ($options as &$option) {
                unset($option['_score']);
            }
            unset($option);

            return array_values($options);
        }

