        private function get_apply_chat_membership_plans()
        {
            $plans_by_path = [];
            $catalog = $this->get_apply_chat_membership_plan_catalog();

            foreach ((array) $this->get_subscription_plans() as $plan) {
                if (!empty($plan['is_annual'])) {
                    continue;
                }

                $shortcode = trim((string) ($plan['shortcode'] ?? ''));
                $name = trim((string) ($plan['name'] ?? ''));
                if ($shortcode === '' || $name === '') {
                    continue;
                }

                $features = isset($plan['features']) && is_array($plan['features'])
                    ? array_values(array_filter(array_map(static function ($feature) {
                        return trim(sanitize_text_field((string) $feature));
                    }, $plan['features'])))
                    : [];

                $signup_path_meta = $this->normalize_member_signup_path(
                    (string) ($plan['signup_path'] ?? ''),
                    trim(implode(' ', array_filter([
                        $name,
                        (string) ($plan['tagline'] ?? ''),
                        (string) ($plan['audience'] ?? ''),
                        implode(' ', $features),
                    ])))
                );
                $path = (string) ($signup_path_meta['path'] ?? 'platform');
                if (!in_array($path, ['platform', 'mentorship', 'all_access'], true)) {
                    continue;
                }

                $display_price = $this->format_plan_price_amount((array) $plan) ?: trim((string) ($plan['price'] ?? ''));
                $display_price = preg_replace('/([.,]00)(?=\s|$|\/)/', '', (string) $display_price);
                $score = 0;
                if (!empty($plan['featured_signup'])) {
                    $score += 100;
                }
                if (!empty($signup_path_meta['configured'])) {
                    $score += 50;
                }
                if (!empty($plan['recruiter_contact_pricing']) && $path === 'platform') {
                    $score += 20;
                }
                $score += (float) ($plan['price_amount'] ?? 0);

                $catalog_entry = $catalog[$path] ?? $catalog['platform'];

                $entry = [
                    'account_type' => $path,
                    'signup_option_label' => sanitize_text_field((string) ($catalog_entry['switch_label'] ?? $name)),
                    'title' => sanitize_text_field((string) ($catalog_entry['title'] ?? $name)),
                    'eyebrow' => sanitize_text_field((string) ($catalog_entry['eyebrow'] ?? '')),
                    'description' => sanitize_text_field((string) ($catalog_entry['description'] ?? '')),
                    'display_price' => sanitize_text_field($display_price),
                    'billing_cycle' => sanitize_text_field((string) ($plan['billing_cycle'] ?? '')),
                    'shortcode' => $shortcode,
                    'features' => !empty($catalog_entry['includes']) && is_array($catalog_entry['includes'])
                        ? array_values(array_filter(array_map('sanitize_text_field', $catalog_entry['includes'])))
                        : array_slice($features, 0, 4),
                    '_score' => $score,
                ];

                if (!isset($plans_by_path[$path]) || $entry['_score'] > $plans_by_path[$path]['_score']) {
                    $plans_by_path[$path] = $entry;
                }
            }

            if (!isset($plans_by_path['all_access'])) {
                $alias = $plans_by_path['mentorship'] ?? null;
                if ($alias === null && !empty($plans_by_path)) {
                    $alias = reset($plans_by_path);
                }
                if ($alias !== null) {
                    $catalog_entry = $catalog['all_access'];
                    $plans_by_path['all_access'] = array_merge($alias, [
                        'account_type' => 'all_access',
                        'signup_option_label' => sanitize_text_field((string) ($catalog_entry['switch_label'] ?? __('All In One', 'senna-finance'))),
                        'title' => sanitize_text_field((string) ($catalog_entry['title'] ?? __('All In One', 'senna-finance'))),
                        'eyebrow' => sanitize_text_field((string) ($catalog_entry['eyebrow'] ?? '')),
                        'description' => sanitize_text_field((string) ($catalog_entry['description'] ?? '')),
                        'features' => array_values(array_filter(array_map('sanitize_text_field', (array) ($catalog_entry['includes'] ?? [])))),
                        '_score' => (float) ($alias['_score'] ?? 0),
                    ]);
                }
            }

            $ordered = [];
            foreach (['platform', 'mentorship', 'all_access'] as $path) {
                if (isset($plans_by_path[$path])) {
                    unset($plans_by_path[$path]['_score']);
                    $ordered[] = $plans_by_path[$path];
                }
            }

            return $ordered;
        }

