        private function get_cv_match_studio_saved_lists($user_id, array $job_groups = [], array $hr_contact_groups = [], array $daily_scan_group_ids = [])
        {
            global $wpdb;

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $table = $wpdb->prefix . 'sffc_crm_saved_lists';
            if (!$this->ensure_cv_match_saved_lists_table()) {
                return [];
            }

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$table} WHERE user_id = %d ORDER BY updated_at DESC, created_at DESC",
                $user_id
            ), ARRAY_A);

            if (empty($rows)) {
                return [];
            }

            $daily_scan_lookup = array_fill_keys(array_map('intval', $daily_scan_group_ids), true);
            $group_lookup = [];
            foreach (['jobs' => $job_groups, 'hr-contacts' => $hr_contact_groups] as $type => $groups) {
                foreach ((array) $groups as $group) {
                    $group_id = (int) ($group['id'] ?? 0);
                    if ($group_id > 0) {
                        $group_lookup[$type . ':' . $group_id] = $group;
                    }
                }
            }

            $items = [];
            foreach ($rows as $row) {
                $type = sanitize_key((string) ($row['group_type'] ?? 'jobs'));
                $type = $type === 'hr-contacts' ? 'hr-contacts' : 'jobs';
                $group_id = (int) ($row['group_id'] ?? 0);
                $group = $group_lookup[$type . ':' . $group_id] ?? [];

                $items[] = [
                    'id' => (int) ($row['id'] ?? 0),
                    'group_id' => $group_id,
                    'type' => $type,
                    'type_label' => $type === 'hr-contacts' ? __('HR Contacts', 'senna-finance') : __('Jobs', 'senna-finance'),
                    'name' => sanitize_text_field((string) ($group['name'] ?? ($row['group_name'] ?? __('Saved list', 'senna-finance')))),
                    'slug' => sanitize_title((string) ($group['slug'] ?? ($row['group_slug'] ?? ''))),
                    'description' => sanitize_text_field((string) ($group['description'] ?? '')),
                    'total' => max(0, (int) ($group['total'] ?? 0)),
                    'last_updated' => sanitize_text_field((string) ($group['last_updated'] ?? '')),
                    'url' => esc_url_raw((string) ($group['url'] ?? home_url('/terminal/'))),
                    'roles' => array_slice((array) ($group['roles'] ?? []), 0, 3),
                    'daily_scan' => $type === 'jobs' && $group_id > 0 && isset($daily_scan_lookup[$group_id]),
                    'saved_at' => !empty($row['created_at']) ? date_i18n('l jS M Y', strtotime((string) $row['created_at'])) : '',
                ];
            }

            return $items;
        }

        private function ensure_cv_match_saved_lists_table()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_saved_lists';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table) {
                return true;
            }

            if (!function_exists('dbDelta')) {
                require_once ABSPATH . 'wp-admin/includes/upgrade.php';
            }

            $charset_collate = $wpdb->get_charset_collate();
            dbDelta("CREATE TABLE $table (
                id bigint(20) NOT NULL AUTO_INCREMENT,
                user_id bigint(20) NOT NULL,
                group_type varchar(50) NOT NULL DEFAULT 'jobs',
                group_id bigint(20) NOT NULL,
                group_slug varchar(200) NOT NULL,
                group_name varchar(200) NOT NULL,
                created_at datetime DEFAULT CURRENT_TIMESTAMP,
                updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                UNIQUE KEY unique_user_group (user_id, group_type, group_id),
                KEY idx_user (user_id),
                KEY idx_group (group_type, group_id),
                KEY idx_created (created_at)
            ) $charset_collate;");

            return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
        }

