        private function get_cv_match_studio_newsletter_groups($user_id = 0)
        {
            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }

            if (!class_exists('SFFC_CRM_Post_Group')) {
                return [];
            }

            $group_model = new SFFC_CRM_Post_Group();
            $groups = $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => true,
            ]);

            if (empty($groups)) {
                return [];
            }

            $items = [];
            foreach ($groups as $group) {
                $group_id = (int) ($group['id'] ?? 0);
                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                if ($group_id <= 0 || $slug === '') {
                    continue;
                }

                $posts = $group_model->get_posts_by_group($group_id, [
                    'limit' => 4,
                    'is_active' => 1,
                    'admin_approved' => null,
                ]);
                if (empty($posts)) {
                    continue;
                }

                $latest_timestamp = $this->get_cv_match_studio_newsletter_group_latest_timestamp($group_id);
                $roles = [];
                foreach ($posts as $post) {
                    $item = $this->build_crm_reddit_crm_item((array) $post);
                    $roles[] = [
                        'title' => sanitize_text_field((string) ($item['role_title'] ?? __('Role brief', 'senna-finance'))),
                        'company' => sanitize_text_field((string) ($item['company'] ?? '')),
                        'recruiter' => sanitize_text_field((string) ($item['recruiter_name'] ?? __('Hiring Team', 'senna-finance'))),
                        'location' => sanitize_text_field((string) ($item['location'] ?? '')),
                        'sector' => sanitize_text_field((string) ($item['sector'] ?? '')),
                        'seniority' => sanitize_text_field((string) ($item['seniority'] ?? '')),
                        'posted_label' => sanitize_text_field((string) ($item['posted_label'] ?? '')),
                        'avatar' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'logo' => esc_url_raw((string) ($item['company_logo'] ?? '')),
                        'url' => esc_url_raw((string) ($item['view_url'] ?? '')),
                    ];
                }

                if (empty($roles)) {
                    continue;
                }

                $items[] = [
                    'id' => $group_id,
                    'name' => sanitize_text_field((string) ($group['name'] ?? __('Role group', 'senna-finance'))),
                    'slug' => $slug,
                    'description' => sanitize_text_field(wp_strip_all_tags((string) ($group['description'] ?? ''))),
                    'location' => sanitize_text_field((string) ($group['location'] ?? '')),
                    'icon' => esc_url_raw((string) ($group['icon'] ?? '')),
                    'total' => $group_model->count_posts_in_group($group_id, [
                        'is_active' => 1,
                        'admin_approved' => null,
                    ]),
                    'last_updated' => $latest_timestamp > 0 ? date_i18n('l jS M Y', $latest_timestamp) : '',
                    'url' => add_query_arg('reddit_group', $slug, home_url('/terminal/')),
                    'export_url' => $this->get_cv_match_studio_newsletter_group_export_url($slug),
                    'roles' => $roles,
                ];
            }

            return $this->sort_cv_match_studio_list_groups_by_detected_location($items);
        }

        private function get_cv_match_studio_hr_contact_groups($user_id = 0)
        {
            if (!class_exists('SFFC_CRM_HR_Contact_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-contact-group.php';
            }

            if (!class_exists('SFFC_CRM_HR_Contact_Group')) {
                return [];
            }

            $group_model = new SFFC_CRM_HR_Contact_Group();
            $groups = $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_contact_count' => true,
            ]);

            if (empty($groups)) {
                return [];
            }

            $items = [];
            foreach ($groups as $group) {
                $group_id = (int) ($group['id'] ?? 0);
                $slug = sanitize_title((string) ($group['slug'] ?? ''));
                if ($group_id <= 0 || $slug === '') {
                    continue;
                }

                $contacts = $group_model->get_contacts_by_group($group_id, [
                    'limit' => 4,
                ]);
                if (empty($contacts)) {
                    continue;
                }

                $roles = [];
                $latest_timestamp = 0;
                foreach ($contacts as $contact) {
                    $contact_name = sanitize_text_field((string) ($contact['contact_name'] ?? __('Hiring Team', 'senna-finance')));
                    $company = sanitize_text_field((string) ($contact['company_name'] ?? ''));
                    $title = sanitize_text_field((string) ($contact['contact_title'] ?? __('Recruiter contact', 'senna-finance')));
                    $location = sanitize_text_field((string) ($contact['location'] ?? ($contact['regions'] ?? '')));
                    $industry_values = array_filter(array_map('trim', explode(',', (string) ($contact['industry'] ?? ''))));
                    $sector = !empty($industry_values) ? sanitize_text_field(ucwords(str_replace('_', ' ', (string) reset($industry_values)))) : '';
                    $updated_at = !empty($contact['updated_at']) ? strtotime((string) $contact['updated_at']) : 0;
                    $latest_timestamp = max($latest_timestamp, (int) $updated_at);
                    $contact_url = trim((string) ($contact['contact_linkedin'] ?? ''));
                    if ($contact_url === '') {
                        $contact_url = trim((string) ($contact['company_url'] ?? ''));
                    }

                    $roles[] = [
                        'title' => $contact_name,
                        'company' => $company,
                        'recruiter' => $title,
                        'location' => $location,
                        'sector' => $sector,
                        'seniority' => sanitize_text_field((string) ($contact['regions'] ?? '')),
                        'posted_label' => '',
                        'avatar' => esc_url_raw((string) ($contact['contact_photo'] ?? '')),
                        'logo' => esc_url_raw((string) ($contact['contact_photo'] ?? ($contact['company_logo'] ?? ''))),
                        'url' => esc_url_raw($contact_url),
                    ];
                }

                if (empty($roles)) {
                    continue;
                }

                $items[] = [
                    'id' => $group_id,
                    'name' => sanitize_text_field((string) ($group['name'] ?? __('Recruiter contact group', 'senna-finance'))),
                    'slug' => $slug,
                    'description' => sanitize_text_field(wp_strip_all_tags((string) ($group['description'] ?? ''))),
                    'location' => sanitize_text_field((string) ($group['location'] ?? '')),
                    'icon' => esc_url_raw((string) ($group['icon'] ?? '')),
                    'total' => $group_model->count_contacts_in_group($group_id),
                    'last_updated' => $latest_timestamp > 0 ? date_i18n('l jS M Y', $latest_timestamp) : '',
                    'url' => add_query_arg(['tab' => 'discover', 'hr_group' => $slug], home_url('/terminal/')),
                    'export_url' => '#',
                    'type' => 'hr-contacts',
                    'roles' => $roles,
                ];
            }

            return $this->sort_cv_match_studio_list_groups_by_detected_location($items);
        }

        private function sort_cv_match_studio_list_groups_by_detected_location(array $items)
        {
            if (empty($items)) {
                return $items;
            }

            $terms = $this->get_cv_match_studio_detected_location_terms();
            if (empty($terms)) {
                return $items;
            }

            $ranked = [];
            foreach ($items as $index => $item) {
                $location = strtolower((string) ($item['location'] ?? ''));
                $fallback_text = strtolower(trim(
                    (string) ($item['name'] ?? '') . ' ' .
                    (string) ($item['description'] ?? '')
                ));
                $haystack = trim($location . ' ' . $fallback_text);
                $has_location = trim($location) !== '';
                $score = 0;

                foreach ($terms as $term) {
                    if ($term === '') {
                        continue;
                    }

                    if ($location !== '' && strpos($location, $term) !== false) {
                        $score += 20;
                    }

                    if ($haystack !== '' && strpos($haystack, $term) !== false) {
                        $score += 10;
                    }
                }

                $ranked[] = [
                    'item' => $item,
                    'bucket' => $score > 0 ? 0 : ($has_location ? 2 : 1),
                    'score' => $score,
                    'index' => $index,
                ];
            }

            usort($ranked, function ($a, $b) {
                if ($a['bucket'] !== $b['bucket']) {
                    return $a['bucket'] <=> $b['bucket'];
                }

                if ($a['score'] !== $b['score']) {
                    return $b['score'] <=> $a['score'];
                }

                return $a['index'] <=> $b['index'];
            });

            return array_map(function ($entry) {
                return $entry['item'];
            }, $ranked);
        }

        private function get_cv_match_studio_detected_location_terms()
        {
            $country = $this->detect_member_pricing_country_code();
            $timezone = strtolower((string) $this->get_user_timezone_from_cookie());
            $language_header = isset($_SERVER['HTTP_ACCEPT_LANGUAGE'])
                ? strtolower(sanitize_text_field(wp_unslash((string) $_SERVER['HTTP_ACCEPT_LANGUAGE'])))
                : strtolower((string) get_locale());
            $currency = isset($_COOKIE['currency_detector_currency'])
                ? strtoupper(sanitize_text_field(wp_unslash((string) $_COOKIE['currency_detector_currency'])))
                : '';
            $terms = [];

            $country_terms = [
                'GB' => ['london', 'united kingdom', 'uk', 'england'],
                'US' => ['new york', 'united states', 'usa'],
                'FR' => ['paris', 'france'],
                'DE' => ['frankfurt', 'munich', 'berlin', 'germany'],
                'ES' => ['madrid', 'barcelona', 'spain'],
                'IT' => ['milan', 'rome', 'italy'],
                'CH' => ['zurich', 'geneva', 'switzerland'],
                'NL' => ['amsterdam', 'netherlands'],
                'SG' => ['singapore'],
                'AE' => ['dubai', 'abu dhabi', 'uae', 'united arab emirates', 'private_equity', 'gcc'],
                'SA' => ['riyadh', 'saudi', 'saudi arabia', 'gcc'],
                'QA' => ['doha', 'qatar', 'gcc'],
                'KW' => ['kuwait', 'gcc'],
                'BH' => ['bahrain', 'gcc'],
                'OM' => ['oman', 'muscat', 'gcc'],
            ];

            if ($country !== '' && isset($country_terms[$country])) {
                $terms = array_merge($terms, $country_terms[$country]);
            }

            $timezone_terms = [
                'america/new_york' => ['new york', 'united states', 'usa'],
                'asia/singapore' => ['singapore'],
                'asia/dubai' => ['dubai', 'abu dhabi', 'uae', 'united arab emirates', 'private_equity', 'gcc'],
                'asia/riyadh' => ['riyadh', 'saudi arabia', 'gcc'],
                'asia/qatar' => ['doha', 'qatar', 'gcc'],
                'asia/bahrain' => ['bahrain', 'gcc'],
                'asia/kuwait' => ['kuwait', 'gcc'],
                'asia/muscat' => ['oman', 'muscat', 'gcc'],
            ];

            foreach ($timezone_terms as $needle => $matched_terms) {
                if ($timezone !== '' && strpos($timezone, $needle) !== false) {
                    $terms = array_merge($terms, $matched_terms);
                }
            }

            if (empty($terms) && $currency !== '') {
                $currency_terms = [
                    'GBP' => ['london', 'united kingdom', 'uk', 'england'],
                    'USD' => ['new york', 'united states', 'usa'],
                    'CHF' => ['zurich', 'geneva', 'switzerland'],
                    'SGD' => ['singapore'],
                    'AED' => ['dubai', 'abu dhabi', 'uae', 'united arab emirates', 'private_equity', 'gcc'],
                    'SAR' => ['riyadh', 'saudi arabia', 'gcc'],
                    'QAR' => ['doha', 'qatar', 'gcc'],
                    'BHD' => ['bahrain', 'gcc'],
                    'KWD' => ['kuwait', 'gcc'],
                    'OMR' => ['oman', 'muscat', 'gcc'],
                ];

                if (isset($currency_terms[$currency])) {
                    $terms = array_merge($terms, $currency_terms[$currency]);
                }
            }

            if (empty($terms)) {
                $language_terms = [
                    'fr' => ['paris', 'france'],
                    'de' => ['frankfurt', 'munich', 'berlin', 'germany'],
                    'es' => ['madrid', 'barcelona', 'spain'],
                    'it' => ['milan', 'rome', 'italy'],
                    'en-gb' => ['london', 'united kingdom', 'uk', 'england'],
                    'en-us' => ['new york', 'united states', 'usa'],
                ];

                foreach ($language_terms as $needle => $matched_terms) {
                    if ($language_header !== '' && strpos($language_header, $needle) !== false) {
                        $terms = array_merge($terms, $matched_terms);
                        break;
                    }
                }
            }

            $terms = array_map(function ($term) {
                return strtolower(sanitize_text_field((string) $term));
            }, $terms);

            return array_values(array_filter(array_unique($terms)));
        }

        private function get_cv_match_studio_newsletter_group_latest_timestamp($group_id)
        {
            global $wpdb;

            $group_id = (int) $group_id;
            if ($group_id <= 0) {
                return 0;
            }

            $posts_table = $wpdb->prefix . 'sffc_crm_posts';
            $relationships_table = $wpdb->prefix . 'sffc_crm_post_group_relationships';
            $latest = $wpdb->get_var($wpdb->prepare(
                "SELECT MAX(p.posted_at)
                 FROM {$posts_table} p
                 INNER JOIN {$relationships_table} pgr ON p.id = pgr.post_id
                 WHERE pgr.group_id = %d
                   AND p.is_active = 1",
                $group_id
            ));

            return !empty($latest) ? (int) strtotime((string) $latest) : 0;
        }

        private function get_cv_match_studio_newsletter_group_export_url($group_slug)
        {
            $group_slug = sanitize_title((string) $group_slug);
            if ($group_slug === '') {
                return '#';
            }

            return add_query_arg(
                [
                    'action' => 'sffc_cv_match_export_group_xls',
                    'group' => $group_slug,
                    'nonce' => wp_create_nonce('sffc_cv_match_export_group_xls_' . $group_slug),
                ],
                admin_url('admin-ajax.php')
            );
        }

        private function merge_cv_match_studio_newsletter_group_mailbox_items(array $mail_items, $posts_per_group = 16)
        {
            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }

            if (!class_exists('SFFC_CRM_Post_Group')) {
                return $mail_items;
            }

            $posts_per_group = max(4, min(40, (int) $posts_per_group));
            $seen_keys = [];
            foreach ($mail_items as $item) {
                $source = sanitize_key((string) ($item['source'] ?? ''));
                $post_id = (int) ($item['post_id'] ?? 0);
                $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                $crm_post_id = (int) ($item['crm_post_id'] ?? 0);

                if ($source !== '' || $post_id > 0 || $wp_post_id > 0) {
                    $seen_keys[$source . '-' . $post_id . '-' . $wp_post_id] = true;
                }
                if ($crm_post_id > 0) {
                    $seen_keys['crm-id-' . $crm_post_id] = true;
                }
            }

            $group_model = new SFFC_CRM_Post_Group();
            $groups = $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => false,
            ]);

            foreach ((array) $groups as $group) {
                $group_id = (int) ($group['id'] ?? 0);
                $group_slug = sanitize_title((string) ($group['slug'] ?? ''));
                if ($group_id <= 0 || $group_slug === '') {
                    continue;
                }

                $posts = $group_model->get_posts_by_group($group_id, [
                    'limit' => $posts_per_group,
                    'is_active' => 1,
                    'admin_approved' => null,
                ]);

                foreach ((array) $posts as $post) {
                    $item = $this->build_crm_reddit_crm_item((array) $post);
                    $item['group_slug'] = $group_slug;
                    $item['group_name'] = sanitize_text_field((string) ($group['name'] ?? ($item['group_name'] ?? '')));

                    $source = sanitize_key((string) ($item['source'] ?? ''));
                    $post_id = (int) ($item['post_id'] ?? 0);
                    $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                    $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
                    $key = $source . '-' . $post_id . '-' . $wp_post_id;
                    $crm_key = $crm_post_id > 0 ? 'crm-id-' . $crm_post_id : '';

                    if (($key !== '--' && isset($seen_keys[$key])) || ($crm_key !== '' && isset($seen_keys[$crm_key]))) {
                        continue;
                    }

                    $item['_jobs_mailbox_score'] = max(70, min(94, 78 + ($post_id % 13)));
                    $item['_jobs_mailbox_view_url'] = $this->resolve_crm_reddit_dashboard_item_view_url((array) $item);
                    $item['_jobs_mailbox_keyword_chips'] = $this->get_cv_match_studio_jobs_mailbox_keyword_chips((array) $item, '', 6);

                    $mail_items[] = $item;
                    if ($key !== '--') {
                        $seen_keys[$key] = true;
                    }
                    if ($crm_key !== '') {
                        $seen_keys[$crm_key] = true;
                    }
                }
            }

            $duration_lookup = $this->build_cv_match_studio_jobs_mailbox_duration_lookup($mail_items);
            foreach ($mail_items as &$item) {
                $item['duration'] = $this->resolve_cv_match_studio_jobs_mailbox_duration_label((array) $item, $duration_lookup);
            }
            unset($item);

            return array_values($mail_items);
        }

