                    foreach ((array) ($filter_group['roles'] ?? []) as $filter_role) {
                        $role_location = trim((string) ($filter_role['location'] ?? ''));
                        if ($role_location !== '') {
                            $location_candidates[] = $role_location;
                        }
                    }

                    foreach ($location_candidates as $location_candidate) {
                        [$location_key, $location_label] = $normalize_filter_location($location_candidate);
                        if ($location_key !== '' && !isset($filter_locations[$location_key])) {
                            $filter_locations[$location_key] = $location_label;
                        }
                    }
                }
            }
            natcasesort($filter_locations);
	        ?>
	            <div class="sffc-cv-match-studio__newsletter-groups-shell" data-cv-match-newsletter-groups-shell>
                    <div class="sffc-cv-match-studio__newsletter-group-filters" data-cv-match-newsletter-group-filters>
