        public function ajax_cv_match_toggle_newsletter_subscription()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Please sign in to manage email updates.', 'senna-finance')], 401);
            }

            global $wpdb;

            if (!$this->ensure_cv_match_newsletter_tables()) {
                wp_send_json_error(['message' => __('Email updates are not ready yet.', 'senna-finance')], 500);
            }

            $newsletter_id = isset($_POST['newsletter_id']) ? absint(wp_unslash($_POST['newsletter_id'])) : 0;
            $user_id = get_current_user_id();
            $user = wp_get_current_user();
            $newsletters_table = $wpdb->prefix . 'sffc_crm_newsletters';
            $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';

            $newsletter = $wpdb->get_row($wpdb->prepare(
                "SELECT id, slug, title FROM {$newsletters_table} WHERE id = %d AND is_active = 1 LIMIT 1",
                $newsletter_id
            ), ARRAY_A);
            if ($newsletter_id <= 0 || empty($newsletter)) {
                wp_send_json_error(['message' => __('Email update not found.', 'senna-finance')], 404);
            }

            $existing = $wpdb->get_row($wpdb->prepare(
                "SELECT id, status FROM {$subscriptions_table} WHERE newsletter_id = %d AND user_id = %d LIMIT 1",
                $newsletter_id,
                $user_id
            ), ARRAY_A);
            $now = current_time('mysql');
            $user_email = $user instanceof WP_User ? (string) $user->user_email : '';
            $subscribe = empty($existing) || (string) ($existing['status'] ?? '') !== 'subscribed';

            if ($existing) {
                $wpdb->update(
                    $subscriptions_table,
                    [
                        'user_email' => $user_email,
                        'status' => $subscribe ? 'subscribed' : 'unsubscribed',
                        'subscribed_at' => $subscribe ? $now : null,
                        'unsubscribed_at' => $subscribe ? null : $now,
                        'updated_at' => $now,
                    ],
                    ['id' => (int) $existing['id']],
                    ['%s', '%s', '%s', '%s', '%s'],
                    ['%d']
                );
            } else {
                $wpdb->insert(
                    $subscriptions_table,
                    [
                        'newsletter_id' => $newsletter_id,
                        'user_id' => $user_id,
                        'user_email' => $user_email,
                        'status' => 'subscribed',
                        'subscribed_at' => $now,
                        'updated_at' => $now,
                    ],
                    ['%d', '%d', '%s', '%s', '%s', '%s']
                );
            }

            if (!empty($wpdb->last_error)) {
                wp_send_json_error(['message' => __('We could not update that email update right now.', 'senna-finance')], 500);
            }

            $alert_profile_result = $this->sync_cv_match_newsletter_alert_profile_for_user($user_id, $newsletter, $subscribe);
            $message = $subscribe ? __('Alerts are on.', 'senna-finance') : __('Alerts are off.', 'senna-finance');
            if (!empty($alert_profile_result['message'])) {
                $message = (string) $alert_profile_result['message'];
            }

            $user_email_sent = false;
            $admin_email_sent = false;
            if ($subscribe) {
                $user_email_sent = $this->send_cv_match_newsletter_subscription_user_email($user, $newsletter);
                $admin_email_sent = $this->send_cv_match_newsletter_subscription_admin_email($user, $newsletter);
            }

            wp_send_json_success([
                'subscribed' => $subscribe,
                'label' => $subscribe ? __('On', 'senna-finance') : __('Turn on', 'senna-finance'),
                'message' => $message,
                'userEmailSent' => $user_email_sent,
                'adminEmailSent' => $admin_email_sent,
            ]);
        }

        public function ajax_cv_match_toggle_newsletter()
        {
            $this->ajax_cv_match_toggle_newsletter_subscription();
        }

        private function get_cv_match_newsletter_email_headers($context = 'user_confirmation', $content_type = 'text/html')
        {
            if (function_exists('sffc_crm_build_email_headers')) {
                return sffc_crm_build_email_headers($context, $content_type);
            }

            return ['Content-Type: ' . $content_type . '; charset=UTF-8'];
        }

        private function get_cv_match_newsletter_title(array $newsletter)
        {
            $title = trim((string) ($newsletter['title'] ?? ''));
            return $title !== '' ? $title : __('MENA Careers newsletter', 'senna-finance');
        }

        private function send_cv_match_newsletter_subscription_user_email($user, array $newsletter)
        {
            if (!$user instanceof WP_User || empty($user->user_email) || !is_email($user->user_email)) {
                return false;
            }

            $locale = function_exists('get_user_locale') ? (string) get_user_locale($user) : (string) get_locale();
            $is_arabic = $this->is_arabic_locale($locale);
            $newsletter_title = $this->get_cv_match_newsletter_title($newsletter);
            $frequency = trim((string) ($newsletter['frequency'] ?? ''));
            $badge = trim((string) ($newsletter['badge_label'] ?? ''));
            $description = trim(wp_strip_all_tags((string) ($newsletter['description'] ?? '')));
            $display_name = trim((string) ($user->display_name ?: $user->user_login));
            $first_name = trim((string) get_user_meta($user->ID, 'first_name', true));
            $greeting_name = $first_name !== '' ? $first_name : ($display_name !== '' ? $display_name : __('there', 'senna-finance'));
            $site_name = wp_specialchars_decode(get_bloginfo('name'), ENT_QUOTES);
            $subject = $is_arabic
                ? sprintf('تم الاشتراك في %s', $newsletter_title)
                : sprintf(__('You are subscribed to %s', 'senna-finance'), $newsletter_title);
            $details = [];

            if ($frequency !== '') {
                $details[] = $is_arabic ? sprintf('التكرار: %s', $frequency) : sprintf(__('Frequency: %s', 'senna-finance'), $frequency);
            }
            if ($badge !== '') {
                $details[] = $is_arabic ? sprintf('التركيز: %s', $badge) : sprintf(__('Focus: %s', 'senna-finance'), $badge);
            }

            $message = '<div dir="' . ($is_arabic ? 'rtl' : 'ltr') . '" style="margin:0;padding:28px;background:#f4f1ea;font-family:Arial,sans-serif;color:#101827;text-align:' . ($is_arabic ? 'right' : 'left') . ';">'
                . '<div style="max-width:640px;margin:0 auto;background:#fff;border:1px solid #ddd7cb;border-radius:18px;overflow:hidden;">'
                . '<div style="background:#0d1d42;color:#fff;padding:28px 32px;">'
                . '<p style="margin:0 0 8px;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#d8b56d;">' . esc_html($is_arabic ? 'نشرات سنّا' : 'MENA Careers newsletters') . '</p>'
                . '<h1 style="margin:0;font-size:28px;line-height:1.2;">' . esc_html($is_arabic ? 'تم تأكيد الاشتراك' : __('Subscription confirmed', 'senna-finance')) . '</h1>'
                . '</div>'
                . '<div style="padding:30px 32px;">'
                . '<p style="margin:0 0 18px;font-size:16px;line-height:1.6;">' . esc_html($is_arabic ? sprintf('مرحباً %s،', $greeting_name) : sprintf(__('Hi %s,', 'senna-finance'), $greeting_name)) . '</p>'
                . '<p style="margin:0 0 20px;font-size:16px;line-height:1.7;color:#364152;">' . esc_html($is_arabic ? sprintf('أصبحت الآن مشتركاً في %s. سنستخدم هذا التفضيل لنرسل لك تنبيهات أوضح عن الفرص وتحديثات السوق المرتبطة بهذه القائمة.', $newsletter_title) : sprintf(__('You are now subscribed to %s. We will use this preference to send you sharper role alerts and market updates that match this list.', 'senna-finance'), $newsletter_title)) . '</p>';

            if (!empty($details) || $description !== '') {
                $message .= '<div style="margin:22px 0;padding:18px 20px;background:#f8f6f0;border:1px solid #e4ded1;border-radius:14px;">'
                    . '<strong style="display:block;margin-bottom:10px;font-size:17px;color:#0d1d42;">' . esc_html($newsletter_title) . '</strong>';
                if ($description !== '') {
                    $message .= '<p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#4b5563;">' . esc_html($description) . '</p>';
                }
                foreach ($details as $detail) {
                    $message .= '<p style="margin:6px 0 0;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:#667085;">' . esc_html($detail) . '</p>';
                }
                $message .= '</div>';
            }

            $message .= '<p style="margin:22px 0 0;font-size:14px;line-height:1.6;color:#667085;">' . esc_html($is_arabic ? 'يمكنك تغيير تفضيلات النشرات من ملفك في سنّا في أي وقت.' : __('You can change newsletter preferences from your MENA Careers profile at any time.', 'senna-finance')) . '</p>'
                . '</div>'
                . '<div style="padding:18px 32px;background:#fbfaf7;border-top:1px solid #eee7dc;color:#667085;font-size:12px;">'
                . esc_html($site_name)
                . '</div>'
                . '</div>'
                . '</div>';

            return (bool) wp_mail($user->user_email, $subject, $message, $this->get_cv_match_newsletter_email_headers('user_confirmation'));
        }

        private function send_cv_match_newsletter_subscription_admin_email($user, array $newsletter)
        {
            $admin_email = get_option('admin_email');
            if (empty($admin_email) || !is_email($admin_email) || !$user instanceof WP_User) {
                return false;
            }

            $newsletter_title = $this->get_cv_match_newsletter_title($newsletter);
            $frequency = trim((string) ($newsletter['frequency'] ?? ''));
            $subject = sprintf(__('Newsletter subscription: %s', 'senna-finance'), $newsletter_title);
            $profile_url = admin_url('user-edit.php?user_id=' . (int) $user->ID);
            $message = '<div style="margin:0;padding:24px;background:#f4f1ea;font-family:Arial,sans-serif;color:#101827;">'
                . '<div style="max-width:640px;margin:0 auto;background:#fff;border:1px solid #ddd7cb;border-radius:16px;overflow:hidden;">'
                . '<div style="background:#0d1d42;color:#fff;padding:24px 28px;">'
                . '<p style="margin:0 0 8px;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#d8b56d;">Admin notification</p>'
                . '<h1 style="margin:0;font-size:24px;line-height:1.25;">' . esc_html__('New newsletter subscription', 'senna-finance') . '</h1>'
                . '</div>'
                . '<div style="padding:26px 28px;">'
                . '<p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#364152;">' . esc_html(sprintf(__('%s subscribed to %s.', 'senna-finance'), $user->display_name ?: $user->user_login, $newsletter_title)) . '</p>'
                . '<table style="width:100%;border-collapse:collapse;font-size:14px;">'
                . '<tr><td style="padding:8px 0;color:#667085;">User</td><td style="padding:8px 0;font-weight:700;">' . esc_html($user->display_name ?: $user->user_login) . '</td></tr>'
                . '<tr><td style="padding:8px 0;color:#667085;">Email</td><td style="padding:8px 0;font-weight:700;">' . esc_html($user->user_email) . '</td></tr>'
                . '<tr><td style="padding:8px 0;color:#667085;">Newsletter</td><td style="padding:8px 0;font-weight:700;">' . esc_html($newsletter_title) . '</td></tr>';

            if ($frequency !== '') {
                $message .= '<tr><td style="padding:8px 0;color:#667085;">Frequency</td><td style="padding:8px 0;font-weight:700;">' . esc_html($frequency) . '</td></tr>';
            }

            $message .= '</table>'
                . '<p style="margin:20px 0 0;"><a href="' . esc_url($profile_url) . '" style="display:inline-block;background:#0d1d42;color:#fff;text-decoration:none;padding:11px 16px;border-radius:999px;font-weight:700;">' . esc_html__('Open user profile', 'senna-finance') . '</a></p>'
                . '</div>'
                . '</div>'
                . '</div>';

            return (bool) wp_mail($admin_email, $subject, $message, $this->get_cv_match_newsletter_email_headers('admin_notifications'));
        }

        public function ajax_cv_match_save_list()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            if (!is_user_logged_in() || !$this->current_user_has_crm_reddit_premium_access()) {
                wp_send_json_error(['message' => __('Upgrade to save lists.', 'senna-finance')], 403);
            }

            global $wpdb;

            $user_id = get_current_user_id();
            $group_type = sanitize_key((string) wp_unslash($_POST['group_type'] ?? 'jobs'));
            $group_type = $group_type === 'hr-contacts' ? 'hr-contacts' : 'jobs';
            $group_id = absint($_POST['group_id'] ?? 0);
            $group_slug = sanitize_title((string) wp_unslash($_POST['group_slug'] ?? ''));
            $group_name = sanitize_text_field((string) wp_unslash($_POST['group_name'] ?? ''));

            if ($group_id <= 0 || $group_slug === '' || $group_name === '') {
                wp_send_json_error(['message' => __('We could not identify that list.', 'senna-finance')], 400);
            }

            $table = $wpdb->prefix . 'sffc_crm_saved_lists';
            if (!$this->ensure_cv_match_saved_lists_table()) {
                wp_send_json_error(['message' => __('Saved lists are not ready yet. Run the CRM schema update.', 'senna-finance')], 500);
            }

            $saved = $wpdb->replace(
                $table,
                [
                    'user_id' => $user_id,
                    'group_type' => $group_type,
                    'group_id' => $group_id,
                    'group_slug' => $group_slug,
                    'group_name' => $group_name,
                    'updated_at' => current_time('mysql'),
                ],
                ['%d', '%s', '%d', '%s', '%s', '%s']
            );

            if ($saved === false) {
                wp_send_json_error(['message' => __('We could not save this list right now.', 'senna-finance')], 500);
            }

            wp_send_json_success([
                'message' => __('List saved.', 'senna-finance'),
                'label' => __('Saved', 'senna-finance'),
            ]);
        }

        public function ajax_cv_match_save_daily_scan()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            if (!is_user_logged_in()) {
                wp_send_json_error(['message' => __('Sign in to request a daily scan.', 'senna-finance')], 401);
            }

            if (!$this->current_user_has_crm_reddit_premium_access()) {
                wp_send_json_error(['message' => __('Upgrade to request daily scans for saved job lists.', 'senna-finance')], 403);
            }

            if (!function_exists('sffc_crm_save_alert_preferences')) {
                $preferences_file = SFFC_PLUGIN_DIR . 'includes/crm/functions-job-preferences.php';
                if (file_exists($preferences_file)) {
                    require_once $preferences_file;
                }
            }

            if (!function_exists('sffc_crm_save_alert_preferences') || !function_exists('sffc_crm_get_alert_preferences')) {
                wp_send_json_error(['message' => __('Role alert settings are not available right now.', 'senna-finance')], 500);
            }

            $user_id = get_current_user_id();
            $group_ids = isset($_POST['group_ids']) && is_array($_POST['group_ids'])
                ? array_values(array_filter(array_map('absint', (array) wp_unslash($_POST['group_ids']))))
                : [];
            $group_ids = array_values(array_unique($group_ids));

            if (empty($group_ids)) {
                wp_send_json_error(['message' => __('Choose at least one list to scan daily.', 'senna-finance')], 400);
            }

            $valid_group_options = function_exists('sffc_crm_get_alert_group_options') ? sffc_crm_get_alert_group_options() : [];
            $valid_group_ids = array_map('intval', array_keys((array) $valid_group_options));
            $group_ids = array_values(array_intersect($group_ids, $valid_group_ids));

            if (empty($group_ids)) {
                wp_send_json_error(['message' => __('Those lists are no longer available.', 'senna-finance')], 400);
            }

            $existing_preferences = sffc_crm_get_alert_preferences($user_id);
            $saved_preferences = sffc_crm_save_alert_preferences($user_id, [
                'enabled' => true,
                'sectors' => (array) ($existing_preferences['sectors'] ?? []),
                'types' => (array) ($existing_preferences['types'] ?? []),
                'locations' => (array) ($existing_preferences['locations'] ?? []),
                'work_modes' => (array) ($existing_preferences['work_modes'] ?? []),
                'groups' => $group_ids,
            ]);

            if (empty($saved_preferences)) {
                wp_send_json_error(['message' => __('We could not save your daily scan right now.', 'senna-finance')], 500);
            }

            $profile_id = $this->get_or_create_cv_match_daily_scan_alert_profile($user_id, $group_ids, $valid_group_options);
            if ($profile_id > 0 && function_exists('sffc_crm_assign_alert_default_profile_to_users')) {
                sffc_crm_assign_alert_default_profile_to_users($profile_id, [$user_id], 0);
            }

            $selected_names = [];
            foreach ($group_ids as $group_id) {
                if (isset($valid_group_options[$group_id])) {
                    $selected_names[] = (string) $valid_group_options[$group_id];
                }
            }

            wp_send_json_success([
                'message' => __('Daily scan saved. New roles added to those lists will trigger your role alerts.', 'senna-finance'),
                'group_ids' => $group_ids,
                'group_names' => $selected_names,
            ]);
        }

        private function get_or_create_cv_match_daily_scan_alert_profile($user_id, array $group_ids, array $group_options = [])
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $group_ids = array_values(array_filter(array_map('intval', $group_ids)));
            if ($user_id <= 0 || empty($group_ids)) {
                return 0;
            }

            if (!class_exists('SFFC_CRM_Database_Schema')) {
                $schema_file = SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
                if (file_exists($schema_file)) {
                    require_once $schema_file;
                }
            }

            if (!class_exists('SFFC_CRM_Database_Schema') || !function_exists('sffc_crm_save_alert_default_profile')) {
                return 0;
            }

            SFFC_CRM_Database_Schema::get_instance()->create_alert_default_profile_tables();

            $table = $wpdb->prefix . 'sffc_crm_alert_default_profiles';
            $assignment_table = $wpdb->prefix . 'sffc_crm_alert_profile_users';
            if (
                $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table
                || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $assignment_table)) !== $assignment_table
            ) {
                return 0;
            }

            $user = get_user_by('id', $user_id);
            $display_name = $user ? ($user->display_name ?: $user->user_login) : sprintf(__('User %d', 'senna-finance'), $user_id);
            $profile_name = sprintf(__('Daily Scan: %s #%d', 'senna-finance'), $display_name, $user_id);
            $group_names = [];
            foreach ($group_ids as $group_id) {
                if (isset($group_options[$group_id])) {
                    $group_names[] = (string) $group_options[$group_id];
                }
            }

            $existing_profile_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE name = %s LIMIT 1",
                $profile_name
            ));

            $saved_id = sffc_crm_save_alert_default_profile($existing_profile_id, [
                'name' => $profile_name,
                'description' => sprintf(
                    __('Auto-created from CV Match Studio daily scan selections. Post groups: %s.', 'senna-finance'),
                    !empty($group_names) ? implode(', ', $group_names) : implode(', ', $group_ids)
                ),
                'enabled' => true,
                'sectors' => [],
                'types' => [],
                'locations' => [],
                'work_modes' => [],
                'groups' => $group_ids,
                'is_active' => true,
            ]);

            if (is_wp_error($saved_id)) {
                return $existing_profile_id > 0 ? $existing_profile_id : 0;
            }

            return (int) $saved_id;
        }

        public function ajax_cv_match_export_group_xls()
        {
            $group_slug = sanitize_title((string) ($_GET['group'] ?? ''));
            if ($group_slug === '') {
                wp_die(esc_html__('Missing group.', 'senna-finance'), '', ['response' => 400]);
            }

            check_ajax_referer('sffc_cv_match_export_group_xls_' . $group_slug, 'nonce');

            if (!is_user_logged_in() || !$this->current_user_has_crm_editorial_paid_membership_access()) {
                wp_die(esc_html__('A paid MENA Careers membership is required to export this list.', 'senna-finance'), '', ['response' => 403]);
            }

            if (!class_exists('SFFC_CRM_Post_Group')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
            }
            if (!class_exists('SFFC_CRM_Post_Group')) {
                wp_die(esc_html__('CRM groups are not available.', 'senna-finance'), '', ['response' => 500]);
            }

            $group_model = new SFFC_CRM_Post_Group();
            $groups = $group_model->get_all([
                'is_active' => 1,
                'order_by' => 'display_order',
                'order' => 'ASC',
                'include_post_count' => false,
            ]);

            $selected_group = null;
            foreach ((array) $groups as $group) {
                if (sanitize_title((string) ($group['slug'] ?? '')) === $group_slug) {
                    $selected_group = (array) $group;
                    break;
                }
            }

            if (empty($selected_group)) {
                wp_die(esc_html__('Group not found.', 'senna-finance'), '', ['response' => 404]);
            }

            $posts = $group_model->get_posts_by_group((int) ($selected_group['id'] ?? 0), [
                'limit' => null,
                'is_active' => 1,
                'admin_approved' => null,
            ]);

            $group_name = sanitize_text_field((string) ($selected_group['name'] ?? __('Role group', 'senna-finance')));
            $tracker_tags = $this->get_cv_match_studio_tracker_stage_export_labels();
            $headers = [
                'Application Status',
                'Priority',
                'Next Action',
                'Next Action Date',
                'Applied Date',
                'Interview Date',
                'Follow-up Date',
                'Role Title',
                'Company',
                'Location',
                'Sector',
                'Seniority',
                'Application URL',
                'MENA Careers Role URL',
                'Closing Date',
                'Posted Date',
                'Recruiter Name',
                'Recruiter Email',
                'Recruiter LinkedIn',
                'Recruiter Title',
                'Recruiter Firm',
                'Group',
                'Country',
                'City',
                'Starting Date',
                'Opening Date',
                'Source URL',
                'Role Summary',
                'Full Job Description',
                'Notes',
            ];

            $rows = [];
            $default_tracker_label = $this->get_cv_match_studio_default_tracker_export_label($tracker_tags);
            foreach ((array) $posts as $post) {
                $post = (array) $post;
                $rows[] = [
                    $default_tracker_label,
                    '',
                    '',
                    '',
                    '',
                    '',
                    '',
                    $post['role_title'] ?? '',
                    $post['company'] ?? '',
                    $post['location'] ?? '',
                    $post['sector'] ?? '',
                    $post['seniority'] ?? '',
                    $post['application_url'] ?? '',
                    $this->get_cv_match_studio_export_role_url($post),
                    $post['closing_date'] ?? '',
                    $post['posted_at'] ?? '',
                    $post['recruiter_name'] ?? '',
                    $post['recruiter_email'] ?? '',
                    $post['recruiter_linkedin'] ?? '',
                    $post['recruiter_title'] ?? '',
                    $post['recruiter_firm'] ?? '',
                    $group_name,
                    $post['location_country'] ?? '',
                    $post['location_city'] ?? '',
                    $post['starting_date'] ?? '',
                    $post['opening_date'] ?? '',
                    $post['source_url'] ?? '',
                    $this->get_cv_match_studio_export_role_summary($post),
                    wp_strip_all_tags((string) ($post['content'] ?? '')),
                    '',
                ];
            }

            $filename = sanitize_file_name('senna-' . $group_slug . '-roles-' . gmdate('Y-m-d') . '.xlsx');
            $xlsx_path = $this->create_cv_match_studio_group_xlsx_file($headers, $rows, $tracker_tags);
            if ($xlsx_path === '') {
                wp_die(esc_html__('Unable to create the Excel file.', 'senna-finance'), '', ['response' => 500]);
            }

            nocache_headers();
            header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
            header('Content-Disposition: attachment; filename="' . $filename . '"');
            header('Content-Length: ' . filesize($xlsx_path));
            header('Pragma: public');
            header('Expires: 0');
            readfile($xlsx_path);
            @unlink($xlsx_path);
            exit;
        }

        private function get_cv_match_studio_tracker_stage_export_labels()
        {
            if (!class_exists('SFFC_CRM_Pipeline')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-pipeline.php';
            }

            $labels = [];
            if (!class_exists('SFFC_CRM_Pipeline')) {
                $labels = [];
            } else {
                foreach ((array) SFFC_CRM_Pipeline::get_stages() as $stage) {
                    $label = sanitize_text_field((string) ($stage['label'] ?? ''));
                    if ($label !== '') {
                        $labels[] = $label;
                    }
                }
            }

            if (empty($labels)) {
                $labels = [
                    __('Not Applied', 'senna-finance'),
                    __('Interested', 'senna-finance'),
                    __('Applied', 'senna-finance'),
                    __('Interviewing', 'senna-finance'),
                    __('Offer', 'senna-finance'),
                    __('Rejected', 'senna-finance'),
                    __('Withdrawn', 'senna-finance'),
                ];
            }

            return array_values(array_unique($labels));
        }

        private function get_cv_match_studio_default_tracker_export_label(array $tracker_tags)
        {
            foreach ($tracker_tags as $label) {
                if (strcasecmp((string) $label, 'Not Applied') === 0) {
                    return (string) $label;
                }
            }

            return !empty($tracker_tags[0]) ? (string) $tracker_tags[0] : __('Not Applied', 'senna-finance');
        }

        private function get_cv_match_studio_export_role_url(array $post)
        {
            $wp_post_id = (int) ($post['wp_post_id'] ?? 0);
            if ($wp_post_id > 0) {
                $permalink = get_permalink($wp_post_id);
                if ($permalink) {
                    return esc_url_raw($permalink);
                }
            }

            $slug_seed = sanitize_title((string) ($post['role_title'] ?? '') . '-' . (string) ($post['company'] ?? ''));
            if (class_exists('SFFC_CRM_Post_Type')) {
                return esc_url_raw(SFFC_CRM_Post_Type::get_post_url((int) ($post['id'] ?? 0), $slug_seed));
            }

            return esc_url_raw(add_query_arg('crm_post_id', (int) ($post['id'] ?? 0), home_url('/')));
        }

        private function get_cv_match_studio_export_role_summary(array $post)
        {
            $summary = trim(wp_strip_all_tags((string) ($post['content_snippet'] ?? '')));
            if ($summary !== '') {
                return $summary;
            }

            return wp_trim_words(wp_strip_all_tags((string) ($post['content'] ?? '')), 45, '...');
        }

        private function create_cv_match_studio_group_xlsx_file(array $headers, array $rows, array $tracker_tags)
        {
            if (!class_exists('ZipArchive')) {
                return '';
            }

            $tmp = wp_tempnam('senna-role-export.xlsx');
            if (!$tmp) {
                return '';
            }

            $zip = new ZipArchive();
            if (true !== $zip->open($tmp, ZipArchive::OVERWRITE)) {
                @unlink($tmp);
                return '';
            }

            $zip->addFromString('[Content_Types].xml', $this->build_cv_match_studio_xlsx_content_types_xml());
            $zip->addFromString('_rels/.rels', $this->build_cv_match_studio_xlsx_root_rels_xml());
            $zip->addFromString('xl/workbook.xml', $this->build_cv_match_studio_xlsx_workbook_xml());
            $zip->addFromString('xl/_rels/workbook.xml.rels', $this->build_cv_match_studio_xlsx_workbook_rels_xml());
            $zip->addFromString('xl/styles.xml', $this->build_cv_match_studio_xlsx_styles_xml());
            $zip->addFromString('xl/worksheets/sheet1.xml', $this->build_cv_match_studio_xlsx_roles_sheet_xml($headers, $rows, count($tracker_tags)));
            $zip->addFromString('xl/worksheets/sheet2.xml', $this->build_cv_match_studio_xlsx_tracker_sheet_xml($tracker_tags));
            $zip->close();

            return $tmp;
        }

        private function build_cv_match_studio_xlsx_content_types_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8"?>'
                . '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                . '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                . '<Default Extension="xml" ContentType="application/xml"/>'
                . '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
                . '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                . '<Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                . '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
                . '</Types>';
        }

        private function build_cv_match_studio_xlsx_root_rels_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8"?>'
                . '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                . '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                . '</Relationships>';
        }

        private function build_cv_match_studio_xlsx_workbook_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8"?>'
                . '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                . '<sheets>'
                . '<sheet name="Roles" sheetId="1" r:id="rId1"/>'
                . '<sheet name="Tracker Options" sheetId="2" state="hidden" r:id="rId2"/>'
                . '</sheets>'
                . '</workbook>';
        }

        private function build_cv_match_studio_xlsx_workbook_rels_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8"?>'
                . '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                . '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
                . '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/>'
                . '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
                . '</Relationships>';
        }

        private function build_cv_match_studio_xlsx_styles_xml()
        {
            return '<?xml version="1.0" encoding="UTF-8"?>'
                . '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                . '<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts>'
                . '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>'
                . '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
                . '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
                . '<cellXfs count="2"><xf numFmtId="49" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="49" fontId="1" fillId="0" borderId="0" xfId="0"/></cellXfs>'
                . '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>'
                . '</styleSheet>';
        }

        private function build_cv_match_studio_xlsx_roles_sheet_xml(array $headers, array $rows, $tracker_option_count)
        {
            $xml = '<?xml version="1.0" encoding="UTF-8"?>'
                . '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac">'
                . '<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/><selection pane="bottomLeft"/></sheetView></sheetViews>'
                . '<sheetFormatPr defaultRowHeight="15"/>'
                . '<cols>';

            foreach ($headers as $index => $header) {
                if (in_array($header, ['Role Summary', 'Full Job Description', 'Notes'], true)) {
                    $width = 55;
                } elseif (in_array($header, ['Application URL', 'MENA Careers Role URL', 'Recruiter LinkedIn', 'Source URL'], true)) {
                    $width = 42;
                } elseif (in_array($header, ['Application Status', 'Next Action', 'Next Action Date', 'Applied Date', 'Interview Date', 'Follow-up Date'], true)) {
                    $width = 20;
                } else {
                    $width = 22;
                }
                $xml .= '<col min="' . (int) ($index + 1) . '" max="' . (int) ($index + 1) . '" width="' . (int) $width . '" customWidth="1"/>';
            }

            $xml .= '</cols><sheetData>';
            $xml .= $this->build_cv_match_studio_xlsx_row_xml(1, $headers, true);
            foreach ($rows as $index => $row) {
                $xml .= $this->build_cv_match_studio_xlsx_row_xml($index + 2, $row, false);
            }
            $xml .= '</sheetData>';
            $last_column = $this->get_cv_match_studio_xlsx_column_name(count($headers));
            $last_row = max(1, count($rows) + 1);
            $xml .= '<autoFilter ref="A1:' . esc_attr($last_column . (int) $last_row) . '"/>';

            if ((int) $tracker_option_count > 0) {
                $xml .= '<dataValidations count="1">'
                    . '<dataValidation type="list" allowBlank="1" showDropDown="0" showErrorMessage="1" sqref="A2:A1048576">'
                    . '<formula1>&apos;Tracker Options&apos;!$A$1:$A$' . (int) $tracker_option_count . '</formula1>'
                    . '</dataValidation>'
                    . '</dataValidations>';
            }

            return $xml . '</worksheet>';
        }

        private function build_cv_match_studio_xlsx_tracker_sheet_xml(array $tracker_tags)
        {
            $xml = '<?xml version="1.0" encoding="UTF-8"?>'
                . '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                . '<sheetData>';

            foreach (array_values($tracker_tags) as $index => $tag) {
                $xml .= $this->build_cv_match_studio_xlsx_row_xml($index + 1, [$tag], false);
            }

            return $xml . '</sheetData></worksheet>';
        }

        private function build_cv_match_studio_xlsx_row_xml($row_number, array $cells, $is_header = false)
        {
            $xml = '<row r="' . (int) $row_number . '">';
            foreach (array_values($cells) as $index => $cell) {
                $coordinate = $this->get_cv_match_studio_xlsx_column_name($index + 1) . (int) $row_number;
                $style = $is_header ? ' s="1"' : ' s="0"';
                $xml .= '<c r="' . esc_attr($coordinate) . '" t="inlineStr"' . $style . '><is><t xml:space="preserve">'
                    . $this->escape_cv_match_studio_xlsx_xml($this->sanitize_cv_match_studio_export_cell($cell))
                    . '</t></is></c>';
            }
            return $xml . '</row>';
        }

        private function get_cv_match_studio_xlsx_column_name($number)
        {
            $number = max(1, (int) $number);
            $name = '';
            while ($number > 0) {
                $number--;
                $name = chr(65 + ($number % 26)) . $name;
                $number = (int) floor($number / 26);
            }

            return $name;
        }

        private function escape_cv_match_studio_xlsx_xml($value)
        {
            return htmlspecialchars((string) $value, ENT_XML1 | ENT_COMPAT, 'UTF-8');
        }

        private function sanitize_cv_match_studio_export_cell($value)
        {
            $value = preg_replace('/\s+/', ' ', trim(wp_strip_all_tags((string) $value)));
            if (function_exists('mb_substr')) {
                $value = mb_substr($value, 0, 32767);
            } else {
                $value = substr($value, 0, 32767);
            }
            if ($value !== '' && preg_match('/^[=+\-@]/', $value)) {
                $value = "'" . $value;
            }

            return $value;
        }

        private function sync_cv_match_newsletter_alert_profile_for_user($user_id, $newsletter, $is_subscribe)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0 || !is_array($newsletter)) {
                return ['updated' => false, 'message' => ''];
            }

            if (!function_exists('sffc_crm_user_has_customized_alert_preferences')) {
                return ['updated' => false, 'message' => ''];
            }

            if (sffc_crm_user_has_customized_alert_preferences($user_id)) {
                return [
                    'updated' => false,
                    'message' => $is_subscribe
                        ? __('Alerts are on. Your existing role alert settings were left unchanged.', 'senna-finance')
                        : __('Alerts are off. Your existing role alert settings were left unchanged.', 'senna-finance'),
                ];
            }

            $profile_id = $this->get_or_create_cv_match_newsletter_alert_profile($newsletter);
            if ($profile_id <= 0) {
                return ['updated' => false, 'message' => ''];
            }

            if ($is_subscribe) {
                $assigned = function_exists('sffc_crm_assign_alert_default_profile_to_users')
                    ? sffc_crm_assign_alert_default_profile_to_users($profile_id, [$user_id], 0)
                    : 0;

                return [
                    'updated' => $assigned > 0,
                    'message' => $assigned > 0
                        ? __('Alerts are on and your default role alerts have been updated.', 'senna-finance')
                        : __('Alerts are on.', 'senna-finance'),
                ];
            }

            $this->reassign_cv_match_newsletter_alert_profile_after_unsubscribe($user_id, (int) ($newsletter['id'] ?? 0), $profile_id);

            return [
                'updated' => true,
                'message' => __('Alerts are off and your default role alerts have been updated.', 'senna-finance'),
            ];
        }

        private function get_or_create_cv_match_newsletter_alert_profile($newsletter)
        {
            global $wpdb;

            if (!class_exists('SFFC_CRM_Database_Schema') || !function_exists('sffc_crm_save_alert_default_profile')) {
                return 0;
            }

            SFFC_CRM_Database_Schema::get_instance()->create_alert_default_profile_tables();

            $table = $wpdb->prefix . 'sffc_crm_alert_default_profiles';
            $assignment_table = $wpdb->prefix . 'sffc_crm_alert_profile_users';
            if (
                $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table
                || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $assignment_table)) !== $assignment_table
            ) {
                return 0;
            }

            $profile_data = $this->get_cv_match_newsletter_alert_profile_data($newsletter);
            if (empty($profile_data['name'])) {
                return 0;
            }

            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE name = %s LIMIT 1",
                $profile_data['name']
            ));

            $saved_id = sffc_crm_save_alert_default_profile($existing_id, $profile_data);
            if (is_wp_error($saved_id)) {
                return $existing_id > 0 ? $existing_id : 0;
            }

            return (int) $saved_id;
        }

        private function get_cv_match_newsletter_alert_profile_data($newsletter)
        {
            $slug = sanitize_key((string) ($newsletter['slug'] ?? ''));
            $title = sanitize_text_field((string) ($newsletter['title'] ?? __('Newsletter', 'senna-finance')));
            $base_locations = [];
            $sectors = [];

            if ($slug === 'private-equity-analyst-roles') {
                $sectors = ['pe'];
            } elseif ($slug === 'private-equity-vc-careers') {
                $sectors = ['pe', 'vc', 'growth_equity'];
            } elseif ($slug === 'private-equity-interview-prep') {
                $sectors = ['pe'];
            } elseif ($slug === 'private-equity-recruiter-contacts') {
                $sectors = ['pe', 'private_credit', 'vc'];
            } else {
                $sectors = ['pe', 'private_credit', 'vc', 'growth_equity'];
            }

            return [
                'name' => sprintf(__('Newsletter: %s', 'senna-finance'), $title),
                'description' => sprintf(
                    __('Auto-created from the CV Match Studio newsletter subscription for %s. Assigned users inherit these role alert defaults until they customize their alert settings.', 'senna-finance'),
                    $title
                ),
                'enabled' => true,
                'sectors' => $sectors,
                'types' => [],
                'locations' => $base_locations,
                'work_modes' => [],
                'groups' => [],
                'is_active' => true,
            ];
        }

        private function reassign_cv_match_newsletter_alert_profile_after_unsubscribe($user_id, $unsubscribed_newsletter_id, $current_profile_id)
        {
            global $wpdb;

            $assignment_table = $wpdb->prefix . 'sffc_crm_alert_profile_users';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $assignment_table)) !== $assignment_table) {
                return;
            }

            $assigned_profile_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT profile_id FROM {$assignment_table} WHERE user_id = %d LIMIT 1",
                $user_id
            ));
            if ($assigned_profile_id !== (int) $current_profile_id) {
                return;
            }

            $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';
            $newsletters_table = $wpdb->prefix . 'sffc_crm_newsletters';
            if (
                $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $subscriptions_table)) !== $subscriptions_table
                || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $newsletters_table)) !== $newsletters_table
            ) {
                return;
            }

            $next_newsletter = $wpdb->get_row($wpdb->prepare(
                "SELECT n.id, n.slug, n.title
                 FROM {$subscriptions_table} s
                 INNER JOIN {$newsletters_table} n ON n.id = s.newsletter_id
                 WHERE s.user_id = %d
                   AND s.status = 'subscribed'
                   AND n.is_active = 1
                   AND n.id <> %d
                 ORDER BY n.display_order ASC, n.title ASC
                 LIMIT 1",
                $user_id,
                (int) $unsubscribed_newsletter_id
            ), ARRAY_A);

            if (!empty($next_newsletter)) {
                $next_profile_id = $this->get_or_create_cv_match_newsletter_alert_profile($next_newsletter);
                if ($next_profile_id > 0 && function_exists('sffc_crm_assign_alert_default_profile_to_users')) {
                    sffc_crm_assign_alert_default_profile_to_users($next_profile_id, [$user_id], 0);
                    return;
                }
            }

            if (function_exists('sffc_crm_clear_alert_default_profiles_for_users')) {
                sffc_crm_clear_alert_default_profiles_for_users([$user_id]);
            }
        }

        private function get_cv_match_studio_mentorship_quota($user_id)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $limit = (int) apply_filters('sffc_job_match_limit', 1, $user_id);
            $is_unlimited = $limit < 0;
            $used = 0;

            $table = $wpdb->prefix . 'sffc_crm_mentorship_sessions';
            if ($user_id > 0 && $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table) {
                $week_start = wp_date('Y-m-d H:i:s', strtotime('monday this week', current_time('timestamp')));
                $used = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM {$table} WHERE user_id = %d AND requested_at >= %s",
                    $user_id,
                    $week_start
                ));
            }

            $remaining = $is_unlimited ? -1 : max(0, $limit - $used);
            $label = $is_unlimited
                ? __('Unlimited mentorship sessions', 'senna-finance')
                : sprintf(
                    _n('%d mentorship session left this week', '%d mentorship sessions left this week', $remaining, 'senna-finance'),
                    $remaining
                );

            return [
                'limit' => $limit,
                'used' => $used,
                'remaining' => $remaining,
                'is_unlimited' => $is_unlimited,
                'label' => $label,
            ];
        }

        private function get_cv_match_studio_mentorship_requests($user_id, $limit = 5)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            $table = $wpdb->prefix . 'sffc_crm_mentorship_sessions';
            if ($user_id <= 0 || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return [];
            }

            return $wpdb->get_results($wpdb->prepare(
                "SELECT id, request_type, request_label, target_role, target_location, status, session_notes, requested_at, scheduled_at, completed_at
                 FROM {$table}
                 WHERE user_id = %d
                 ORDER BY requested_at DESC
                 LIMIT %d",
                $user_id,
                max(1, min(20, (int) $limit))
            ), ARRAY_A) ?: [];
        }

        private function get_matching_engine_skill_signals()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_posts';
            if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
                return [];
            }

            $rows = $wpdb->get_results(
                "SELECT skills_mentioned, keywords
             FROM {$table}
             WHERE is_active = 1
               AND admin_approved = 1
               AND (post_status IS NULL OR post_status = 'open')
             ORDER BY posted_at DESC, id DESC
             LIMIT 150",
                ARRAY_A
            );

            if (empty($rows)) {
                return [];
            }

            $signals = [];
            foreach ($rows as $row) {
                $skills = json_decode((string) ($row['skills_mentioned'] ?? '[]'), true);
                if (is_array($skills)) {
                    foreach ($skills as $skill) {
                        $skill = sanitize_text_field((string) $skill);
                        if ($skill !== '') {
                            $signals[$skill] = ($signals[$skill] ?? 0) + 2;
                        }
                    }
                }

                $keywords = preg_split('/[\r\n,|]+/', (string) ($row['keywords'] ?? ''));
                foreach ((array) $keywords as $keyword) {
                    $keyword = sanitize_text_field(trim((string) $keyword));
                    if ($keyword !== '') {
                        $signals[$keyword] = ($signals[$keyword] ?? 0) + 1;
                    }
                }
            }

            if (empty($signals)) {
                return [];
            }

            arsort($signals);
            return array_slice(array_keys($signals), 0, 12);
        }

        private function get_matching_engine_firm_signals()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_crm_posts';
            if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
                return [];
            }

            $rows = $wpdb->get_col(
                "SELECT DISTINCT company
             FROM {$table}
             WHERE is_active = 1
               AND admin_approved = 1
               AND (post_status IS NULL OR post_status = 'open')
               AND company IS NOT NULL
               AND company <> ''
             ORDER BY posted_at DESC, id DESC
             LIMIT 8"
            );

            if (empty($rows)) {
                return [];
            }

            return array_values(array_filter(array_map('sanitize_text_field', $rows)));
        }

        private function get_matching_engine_posts()
        {
            $post_model = new SFFC_CRM_Post();
            $posts = $post_model->get_feed([
                'per_page' => 24,
                'approved_only' => true,
            ]);

            if (empty($posts)) {
                return [];
            }

            $results = [];
            foreach ($posts as $post) {
                $skills = [];
                if (!empty($post['skills_mentioned'])) {
                    if (is_array($post['skills_mentioned'])) {
                        $skills = $post['skills_mentioned'];
                    } else {
                        $skills = json_decode((string) $post['skills_mentioned'], true) ?: [];
                    }
                }

                $keywords = preg_split('/[\r\n,|]+/', (string) ($post['keywords'] ?? ''));
                $keywords = array_values(array_filter(array_map(static function ($keyword) {
                    return sanitize_text_field(trim((string) $keyword));
                }, (array) $keywords)));

                $view_url = '';
                if (!empty($post['application_url'])) {
                    $view_url = esc_url_raw($post['application_url']);
                } elseif (!empty($post['wp_post_id'])) {
                    $view_url = esc_url_raw(get_permalink((int) $post['wp_post_id']));
                }

                $results[] = [
                    'id' => (int) ($post['id'] ?? 0),
                    'roleTitle' => sanitize_text_field($post['role_title'] ?? ''),
                    'company' => sanitize_text_field($post['company'] ?? ''),
                    'sector' => sanitize_text_field($post['sector'] ?? ''),
                    'location' => sanitize_text_field($post['location'] ?? ($post['location_city'] ?? $post['location_country'] ?? '')),
                    'postedAt' => sanitize_text_field($post['posted_at'] ?? ''),
                    'companyLogo' => esc_url_raw($post['company_logo'] ?? ''),
                    'viewUrl' => $view_url,
                    'skills' => array_values(array_filter(array_map('sanitize_text_field', (array) $skills))),
                    'keywords' => $keywords,
                ];
            }

            return array_values(array_filter($results, function ($item) {
                return $this->is_cv_match_studio_frontend_region_item([
                    'location' => (string) ($item['location'] ?? ''),
                ]);
            }));
        }

        private function get_cv_match_studio_scan_preview_items()
        {
            $post_model = new SFFC_CRM_Post();
            $posts = $post_model->get_feed([
                'per_page' => 6,
                'approved_only' => true,
            ]);

            if (empty($posts)) {
                return [];
            }

            $items = [];
            foreach ($posts as $post) {
                $role_title = sanitize_text_field((string) ($post['role_title'] ?? ''));
                $company = sanitize_text_field((string) ($post['company'] ?? ''));
                $location = sanitize_text_field((string) ($post['location'] ?? ($post['location_city'] ?? $post['location_country'] ?? '')));
                $seniority = sanitize_text_field((string) ($post['seniority'] ?? ''));
                $sector = sanitize_text_field((string) ($post['sector'] ?? ''));
                $company_logo = !empty($post['company_logo']) ? $this->normalize_company_logo_url((string) $post['company_logo']) : '';
                $recruiter_name = sanitize_text_field((string) ($post['recruiter_name'] ?? ''));
                $recruiter_photo = !empty($post['recruiter_photo']) ? esc_url_raw((string) $post['recruiter_photo']) : '';
                $recruiter_title = sanitize_text_field((string) ($post['recruiter_title'] ?? ''));

                $tags = array_values(array_filter([
                    $location,
                    $seniority,
                    $sector,
                ]));

                $items[] = [
                    'roleTitle' => $role_title,
                    'company' => $company,
                    'companyLogo' => esc_url_raw((string) $company_logo),
                    'companyInitial' => strtoupper(function_exists('mb_substr') ? mb_substr($company !== '' ? $company : ($role_title !== '' ? $role_title : 'S'), 0, 2) : substr($company !== '' ? $company : ($role_title !== '' ? $role_title : 'S'), 0, 2)),
                    'recruiterName' => $recruiter_name,
                    'recruiterPhoto' => $recruiter_photo,
                    'recruiterInitial' => strtoupper(function_exists('mb_substr') ? mb_substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 2) : substr($recruiter_name !== '' ? $recruiter_name : 'R', 0, 2)),
                    'recruiterTitle' => $recruiter_title,
                    'tags' => array_slice($tags, 0, 3),
                ];
            }

            $items = array_values(array_filter($items, function ($item) {
                return $this->is_cv_match_studio_frontend_region_item([
                    'location' => implode(' ', array_map('strval', (array) ($item['tags'] ?? []))),
                ]);
            }));

            return array_slice($items, 0, 3);
        }

        private function get_cv_match_studio_career_report_cache_ttl()
        {
            return 12 * HOUR_IN_SECONDS;
        }

        private function get_cv_match_studio_career_report_cache_version()
        {
            return 'v3';
        }

        private function normalize_cv_match_studio_career_report_text_value($value, $fallback = '')
        {
            if (is_array($value)) {
                $value = $value['role'] ?? $value['label'] ?? $value['name'] ?? implode(' ', array_filter(array_map('sanitize_text_field', array_values($value))));
            }

            $value = sanitize_text_field((string) $value);
            if ($value === '' || strtolower($value) === 'array') {
                return sanitize_text_field((string) $fallback);
            }

            return $value;
        }

        private function is_cv_match_studio_career_report_payload($payload)
        {
            return is_array($payload)
                && !empty($payload['source_hash'])
                && !empty($payload['report'])
                && is_array($payload['report'])
                && !empty($payload['report']['jobs'])
                && is_array($payload['report']['jobs'])
                && !empty($payload['report']['salary'])
                && is_array($payload['report']['salary']);
        }

        private function get_cv_match_studio_career_report_payload($user_id, array $resume_payload = [], $force = false)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [
                    'status' => 'missing_user',
                    'report' => [],
                ];
            }

            if (empty($resume_payload)) {
                $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            }

            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            if (empty($resume_payload['has_cv']) || $cv_text === '') {
                return [
                    'status' => 'missing_cv',
                    'report' => [],
                ];
            }

            $source_hash = md5($cv_text);
            $cache_key = 'sffc_cv_match_career_report_' . $this->get_cv_match_studio_career_report_cache_version() . '_' . md5($user_id . '|' . $source_hash);

            if (!$force) {
                $cached = get_transient($cache_key);
                if ($this->is_cv_match_studio_career_report_payload($cached)) {
                    return $cached;
                }
            }

            $prepared = $this->build_cv_match_studio_career_report_fallback($user_id, $resume_payload);
            $fallback_report = !empty($prepared['report']) && is_array($prepared['report']) ? $prepared['report'] : [];
            $context = !empty($prepared['context']) && is_array($prepared['context']) ? $prepared['context'] : [];
            $claude = $this->call_cv_match_studio_career_report_claude($context);
            $report = $this->merge_cv_match_studio_career_report_payload($fallback_report, is_array($claude) ? $claude : []);

            $payload = [
                'status' => 'ready',
                'source_hash' => $source_hash,
                'generated_at' => current_time('mysql'),
                'generated_with_claude' => !empty($claude),
                'report' => $report,
            ];

            set_transient($cache_key, $payload, $this->get_cv_match_studio_career_report_cache_ttl());

            return $payload;
        }

        private function build_cv_match_studio_career_report_fallback($user_id, array $resume_payload = [])
        {
            $user_id = (int) $user_id;
            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));

            if ($cv_text === '') {
                return [
                    'report' => [],
                    'context' => [],
                ];
            }

            if (!class_exists('SFFC_Planner_CV_Parser')) {
                $parser_file = SFFC_PLUGIN_DIR . 'includes/application-planner/class-cv-parser.php';
                if (file_exists($parser_file)) {
                    require_once $parser_file;
                }
            }

            $parsed = [];
            if (class_exists('SFFC_Planner_CV_Parser')) {
                $parser = new SFFC_Planner_CV_Parser();
                $parsed = (array) $parser->parse($cv_text);
            }

            $cv_profile = $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, false);
            if (empty($cv_profile)) {
                $cv_profile = $this->build_crm_reddit_cv_ats_fallback($cv_text);
            }

            $jobs = $this->get_cv_match_studio_jobs_mailbox_items($user_id, $resume_payload, 12);
            $jobs = array_values(array_filter((array) $jobs, 'is_array'));

            $experience_years = max(0, (int) round((float) ($parsed['total_years'] ?? 0)));
            $parsed_current_role = $parsed['current_role'] ?? '';
            if (is_array($parsed_current_role)) {
                if (!empty($parsed_current_role['role'])) {
                    $parsed_current_role = (string) $parsed_current_role['role'];
                } elseif (!empty($parsed_current_role['label'])) {
                    $parsed_current_role = (string) $parsed_current_role['label'];
                } else {
                    $parsed_current_role = implode(' ', array_filter(array_map('sanitize_text_field', array_values($parsed_current_role))));
                }
            }
            $current_role = sanitize_text_field((string) $parsed_current_role);
            if (strtolower($current_role) === 'array') {
                $current_role = '';
            }
            if ($current_role === '' && !empty($cv_profile['target_roles'][0]['label'])) {
                $current_role = sanitize_text_field((string) $cv_profile['target_roles'][0]['label']);
            }
            if ($current_role === '' && !empty($jobs[0]['role_title'])) {
                $current_role = sanitize_text_field((string) $jobs[0]['role_title']);
            }
            if ($current_role === '') {
                $current_role = __('Investment candidate', 'senna-finance');
            }

            $primary_market = sanitize_text_field((string) ($parsed['contact']['location'] ?? ''));
            if ($primary_market === '' && !empty($cv_profile['locations'][0]['label'])) {
                $primary_market = sanitize_text_field((string) $cv_profile['locations'][0]['label']);
            }
            if ($primary_market === '' && !empty($jobs[0]['location'])) {
                $primary_market = sanitize_text_field((string) $jobs[0]['location']);
            }
            if ($primary_market === '') {
                $primary_market = __('Your market', 'senna-finance');
            }

            $primary_sector = '';
            if (!empty($cv_profile['sectors'][0]['label'])) {
                $primary_sector = sanitize_text_field((string) $cv_profile['sectors'][0]['label']);
            } elseif (!empty($parsed['sectors'][0])) {
                $parsed_sector = $parsed['sectors'][0];
                if (is_array($parsed_sector)) {
                    $primary_sector = sanitize_text_field((string) ($parsed_sector['name'] ?? $parsed_sector['label'] ?? ''));
                } else {
                    $primary_sector = sanitize_text_field((string) $parsed_sector);
                }
            }

            $cv_keywords = [];
            foreach ((array) ($cv_profile['keywords'] ?? []) as $keyword_item) {
                $label = is_array($keyword_item)
                    ? sanitize_text_field((string) ($keyword_item['label'] ?? ''))
                    : sanitize_text_field((string) $keyword_item);
                if ($label !== '') {
                    $cv_keywords[] = $label;
                }
            }

            $role_contexts = [];
            $company_labels = [];
            foreach (array_slice($jobs, 0, 8) as $job) {
                $company = sanitize_text_field((string) ($job['company'] ?? ''));
                if ($company !== '') {
                    $company_labels[] = $company;
                }

                $context_id = (int) ($job['post_id'] ?? 0);
                if ($context_id <= 0) {
                    $context_id = (int) ($job['crm_post_id'] ?? 0);
                }
                if ($context_id <= 0) {
                    $context_id = (int) ($job['wp_post_id'] ?? 0);
                }

                $context = $context_id > 0 ? $this->get_recruiter_intro_onboarding_post($context_id) : [];
                if (empty($context)) {
                    $context = [
                        'job_title' => sanitize_text_field((string) ($job['role_title'] ?? '')),
                        'company_name' => $company,
                        'location' => sanitize_text_field((string) ($job['location'] ?? '')),
                        'salary_display' => sanitize_text_field((string) ($job['salary_text'] ?? '')),
                        'seniority' => sanitize_text_field((string) ($job['seniority'] ?? '')),
                        'description' => sanitize_text_field((string) ($job['description_preview'] ?? $job['excerpt'] ?? '')),
                        'requirements' => array_values(array_filter(array_map('sanitize_text_field', (array) ($job['keywords'] ?? [])))),
                        'keywords' => array_values(array_filter(array_map('sanitize_text_field', (array) ($job['keywords'] ?? [])))),
                    ];
                }

                $role_contexts[] = $context;
            }

            $job_rows = [];
            $seen_job_labels = [];
            foreach (array_slice($jobs, 0, 6) as $job) {
                $label = sanitize_text_field((string) ($job['role_title'] ?? ''));
                if ($label === '') {
                    continue;
                }

                $job_key = strtolower($label);
                if (isset($seen_job_labels[$job_key])) {
                    continue;
                }
                $seen_job_labels[$job_key] = true;

                $keywords = array_values(array_filter(array_map('sanitize_text_field', (array) ($job['keywords'] ?? []))));
                $reason_bits = [];
                if (!empty($job['company'])) {
                    $reason_bits[] = sprintf(
                        __('best live fit currently clusters around %s', 'senna-finance'),
                        sanitize_text_field((string) $job['company'])
                    );
                }
                if (!empty($keywords)) {
                    $reason_bits[] = sprintf(
                        __('repeated role signals include %s', 'senna-finance'),
                        implode(', ', array_slice($keywords, 0, 2))
                    );
                }
                if (!empty($job['location'])) {
                    $reason_bits[] = sprintf(
                        __('market relevance is strongest in %s', 'senna-finance'),
                        sanitize_text_field((string) $job['location'])
                    );
                }

                $job_rows[] = [
                    'label' => $label,
                    'fit_score' => max(40, min(98, (int) ($job['_jobs_mailbox_score'] ?? 0))),
                    'reason' => ucfirst(implode('. ', array_slice($reason_bits, 0, 2))) . '.',
                ];
            }

            $company_map = [];
            foreach ($jobs as $job) {
                $company = sanitize_text_field((string) ($job['company'] ?? ''));
                if ($company === '') {
                    continue;
                }

                $key = strtolower($company);
                if (!isset($company_map[$key])) {
                    $company_map[$key] = [
                        'label' => $company,
                        'fit_score' => max(0, min(100, (int) ($job['_jobs_mailbox_score'] ?? 0))),
                        'open_roles' => 0,
                        'best_role' => sanitize_text_field((string) ($job['role_title'] ?? '')),
                        'location' => sanitize_text_field((string) ($job['location'] ?? '')),
                    ];
                }

                $company_map[$key]['open_roles']++;
                if ((int) ($job['_jobs_mailbox_score'] ?? 0) >= (int) $company_map[$key]['fit_score']) {
                    $company_map[$key]['fit_score'] = max(0, min(100, (int) ($job['_jobs_mailbox_score'] ?? 0)));
                    $company_map[$key]['best_role'] = sanitize_text_field((string) ($job['role_title'] ?? ''));
                    $company_map[$key]['location'] = sanitize_text_field((string) ($job['location'] ?? ''));
                }
            }

            uasort($company_map, static function ($left, $right) {
                $score_compare = ((int) ($right['fit_score'] ?? 0)) <=> ((int) ($left['fit_score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return ((int) ($right['open_roles'] ?? 0)) <=> ((int) ($left['open_roles'] ?? 0));
            });

            $company_rows = [];
            foreach (array_slice(array_values($company_map), 0, 6) as $company_row) {
                $company_rows[] = [
                    'label' => sanitize_text_field((string) ($company_row['label'] ?? '')),
                    'fit_score' => max(40, min(98, (int) ($company_row['fit_score'] ?? 0))),
                    'open_roles' => max(1, (int) ($company_row['open_roles'] ?? 1)),
                    'reason' => sprintf(
                        __('Strongest fit currently comes through %1$s roles in %2$s.', 'senna-finance'),
                        sanitize_text_field((string) ($company_row['best_role'] ?? __('matched', 'senna-finance'))),
                        sanitize_text_field((string) ($company_row['location'] ?? $primary_market))
                    ),
                ];
            }

            $normalized_cv_text = $this->normalize_crm_reddit_dashboard_cv_text($cv_text);
            $skill_counts = [];
            foreach ($role_contexts as $context) {
                $terms = array_merge(
                    (array) ($context['requirements'] ?? []),
                    (array) ($context['keywords'] ?? [])
                );

                foreach ($terms as $term) {
                    if (is_array($term)) {
                        $term = $term['label'] ?? $term['keyword'] ?? $term['name'] ?? '';
                    }

                    $term = sanitize_text_field((string) $term);
                    if (!$this->is_cv_match_studio_career_report_useful_term($term, $company_labels)) {
                        continue;
                    }

                    $key = strtolower($term);
                    if (!isset($skill_counts[$key])) {
                        $skill_counts[$key] = [
                            'label' => $term,
                            'count' => 0,
                        ];
                    }
                    $skill_counts[$key]['count']++;
                }
            }

            uasort($skill_counts, static function ($left, $right) {
                $count_compare = ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
                if ($count_compare !== 0) {
                    return $count_compare;
                }

                return strlen((string) ($right['label'] ?? '')) <=> strlen((string) ($left['label'] ?? ''));
            });

            $skill_rows = [];
            foreach (array_slice(array_values($skill_counts), 0, 6) as $skill_row) {
                $label = sanitize_text_field((string) ($skill_row['label'] ?? ''));
                $count = max(1, (int) ($skill_row['count'] ?? 1));
                $current_score = strpos($normalized_cv_text, strtolower($label)) !== false ? 84 : 28;
                $demand_score = min(96, 50 + (($count - 1) * 14));

                $skill_rows[] = [
                    'label' => $label,
                    'current_score' => $current_score,
                    'demand_score' => $demand_score,
                    'advice' => $current_score >= 70
                        ? __('Already visible on your CV, but worth moving closer to the top third.', 'senna-finance')
                        : sprintf(__('Appears repeatedly across your stronger matches and should read more explicitly.', 'senna-finance')),
                ];
            }

            $qualification_library = [
                'CFA' => ['cfa'],
                'ACA' => ['aca'],
                'CAIA' => ['caia'],
                'ACCA' => ['acca'],
                'FRM' => ['frm'],
                'CPA' => ['cpa'],
                'MBA' => ['mba'],
                __('Master\'s degree', 'senna-finance') => ['master', 'msc', 'ma '],
                __('Bachelor\'s degree', 'senna-finance') => ['bachelor', 'bsc', 'ba '],
                __('Finance degree', 'senna-finance') => ['finance degree', 'finance'],
                __('Economics degree', 'senna-finance') => ['economics degree', 'economics'],
            ];

            $qualification_counts = [];
            foreach ($role_contexts as $context) {
                $haystack = strtolower(
                    implode(
                        ' ',
                        array_filter([
                            (string) ($context['description'] ?? ''),
                            implode(' ', (array) ($context['requirements'] ?? [])),
                            implode(' ', (array) ($context['keywords'] ?? [])),
                        ])
                    )
                );

                foreach ($qualification_library as $label => $needles) {
                    foreach ((array) $needles as $needle) {
                        if ($needle !== '' && strpos($haystack, strtolower($needle)) !== false) {
                            $qualification_counts[$label] = (int) ($qualification_counts[$label] ?? 0) + 1;
                            break;
                        }
                    }
                }
            }

            if (empty($qualification_counts) && $primary_sector !== '') {
                $qualification_counts['CFA'] = 2;
                $qualification_counts[__('Bachelor\'s degree', 'senna-finance')] = 1;
            }

            arsort($qualification_counts);
            $qualification_rows = [];
            foreach (array_slice(array_keys($qualification_counts), 0, 5) as $qualification_label) {
                $needles = (array) ($qualification_library[$qualification_label] ?? [$qualification_label]);
                $visible = false;
                foreach ($needles as $needle) {
                    if ($needle !== '' && strpos($normalized_cv_text, strtolower((string) $needle)) !== false) {
                        $visible = true;
                        break;
                    }
                }

                $count = max(1, (int) ($qualification_counts[$qualification_label] ?? 1));
                $qualification_rows[] = [
                    'label' => sanitize_text_field((string) $qualification_label),
                    'priority' => min(95, 58 + (($count - 1) * 12) + ($visible ? 0 : 10)),
                    'advice' => $visible
                        ? __('Already present. Keep it obvious in your summary, education, or certifications section.', 'senna-finance')
                        : __('Shows up often in your stronger target roles and is worth considering if it fits your route.', 'senna-finance'),
                ];
            }

            $lead_skill = !empty($skill_rows[0]['label']) ? (string) $skill_rows[0]['label'] : __('the strongest role signal', 'senna-finance');
            $secondary_skill = !empty($skill_rows[1]['label']) ? (string) $skill_rows[1]['label'] : __('the next strongest proof point', 'senna-finance');
            $top_job_label = !empty($job_rows[0]['label']) ? (string) $job_rows[0]['label'] : __('your strongest target role', 'senna-finance');

            $standout_rows = [
                [
                    'label' => __('Lead with fit', 'senna-finance'),
                    'score' => 89,
                    'detail' => sprintf(__('Open with %1$s and %2$s in the first third of your CV.', 'senna-finance'), $lead_skill, $secondary_skill),
                ],
                [
                    'label' => __('Bridge your story', 'senna-finance'),
                    'score' => 84,
                    'detail' => sprintf(__('Frame your background around %s instead of a broad finance profile.', 'senna-finance'), $top_job_label),
                ],
                [
                    'label' => __('Sound recruiter-ready', 'senna-finance'),
                    'score' => 87,
                    'detail' => __('Use sharper role language, deal proof, and quantified outcomes before softer narrative.', 'senna-finance'),
                ],
                [
                    'label' => __('Move faster on proof', 'senna-finance'),
                    'score' => 82,
                    'detail' => __('Bring the strongest technical evidence and any market tools above generic responsibilities.', 'senna-finance'),
                ],
            ];

            $positioning_rows = [
                [
                    'label' => __('Professional summary', 'senna-finance'),
                    'score' => 91,
                    'detail' => sprintf(__('State %1$s, %2$d years, and %3$s focus before softer motivation language.', 'senna-finance'), $current_role, max(1, $experience_years), $primary_sector !== '' ? $primary_sector : __('investment', 'senna-finance')),
                ],
                [
                    'label' => __('Experience bullets', 'senna-finance'),
                    'score' => 88,
                    'detail' => sprintf(__('Reword bullets so %s reads as delivered evidence, not implied exposure.', 'senna-finance'), $lead_skill),
                ],
                [
                    'label' => __('Skills and tools', 'senna-finance'),
                    'score' => 79,
                    'detail' => __('Separate tools, technical skills, and market platforms so recruiters can screen them quickly.', 'senna-finance'),
                ],
                [
                    'label' => __('Recruiter positioning', 'senna-finance'),
                    'score' => 85,
                    'detail' => __('Describe why your current profile is already useful to the target seat before discussing what you want next.', 'senna-finance'),
                ],
            ];

            $has_quantified = !empty($parsed['quantified_achievements']) && is_array($parsed['quantified_achievements']);
            $mistake_rows = [
                [
                    'label' => __('Applying with a generic opening summary', 'senna-finance'),
                    'risk_level' => 'high',
                    'detail' => sprintf(__('Open with %s rather than broad finance interest or personality-led wording.', 'senna-finance'), $current_role),
                ],
                [
                    'label' => __('Hiding the strongest role signals too low', 'senna-finance'),
                    'risk_level' => 'high',
                    'detail' => sprintf(__('Make %s visible before lower-value administrative detail.', 'senna-finance'), $lead_skill),
                ],
                [
                    'label' => __('Using generic bullets without quantified outcomes', 'senna-finance'),
                    'risk_level' => $has_quantified ? 'medium' : 'high',
                    'detail' => $has_quantified
                        ? __('Keep the quantified bullets, but move the strongest ones closer to the top of the experience section.', 'senna-finance')
                        : __('Add quantified outcomes, transaction detail, or measurable research impact so the CV reads as execution-ready.', 'senna-finance'),
                ],
                [
                    'label' => __('Underselling market tools or credentials', 'senna-finance'),
                    'risk_level' => 'medium',
                    'detail' => __('Recruiters screen tools, certifications, and technical shorthand quickly, so do not bury them.', 'senna-finance'),
                ],
                [
                    'label' => __('Letting the CV sound broader than the target role', 'senna-finance'),
                    'risk_level' => 'medium',
                    'detail' => sprintf(__('Mirror the language of %s so the fit reads intentionally targeted.', 'senna-finance'), $top_job_label),
                ],
            ];

            $salary_context = [
                'role_title' => $current_role,
                'location' => $primary_market,
                'seniority' => !empty($cv_profile['seniority'][0]['label']) ? (string) $cv_profile['seniority'][0]['label'] : '',
                'company' => '',
                'salary_text' => '',
                'employment_type' => '',
            ];
            $salary_data = $this->generate_crm_reddit_single_job_salary_trajectory($salary_context);
            $salary_stage_index = $this->map_cv_match_studio_career_report_stage_index($experience_years);
            $salary_stages = array_values((array) ($salary_data['stages'] ?? []));
            $salary_current = !empty($salary_stages[$salary_stage_index]) ? $salary_stages[$salary_stage_index] : (!empty($salary_stages[0]) ? $salary_stages[0] : []);
            $salary_data['current_stage_index'] = $salary_stage_index;
            $salary_data['current_stage_label'] = sanitize_text_field((string) ($salary_current['label'] ?? ''));
            $salary_data['current_salary'] = max(0, (int) ($salary_current['annual_salary'] ?? 0));

            $top_signals = array_values(array_filter(array_unique(array_filter([
                $current_role,
                $primary_sector,
                !empty($cv_profile['top_strength']) ? sanitize_text_field((string) $cv_profile['top_strength']) : '',
                !empty($cv_keywords[0]) ? $cv_keywords[0] : '',
                !empty($job_rows[0]['label']) ? (string) $job_rows[0]['label'] : '',
            ])), static function ($signal) {
                return trim(strtolower((string) $signal)) !== 'array';
            }));

            $headline = !empty($job_rows[0]['label'])
                ? sprintf(__('Your profile currently looks strongest for %s-style opportunities.', 'senna-finance'), (string) $job_rows[0]['label'])
                : __('Your profile already points toward a clearer finance route than your CV may currently show.', 'senna-finance');

            $summary = sprintf(
                __('MENA Careers sees %1$d years of experience, a current profile shaped around %2$s, and the strongest live demand clustering around %3$s in %4$s.', 'senna-finance'),
                max(1, $experience_years),
                $primary_sector !== '' ? $primary_sector : __('finance', 'senna-finance'),
                !empty($job_rows[0]['label']) ? (string) $job_rows[0]['label'] : __('matched private equity roles', 'senna-finance'),
                $primary_market
            );

            $report = [
                'headline' => $headline,
                'summary' => $summary,
                'current_role' => $current_role,
                'experience_years' => $experience_years,
                'primary_market' => $primary_market,
                'primary_sector' => $primary_sector,
                'analysis_source' => 'fallback',
                'jobs' => $job_rows,
                'companies' => $company_rows,
                'skills' => $skill_rows,
                'qualifications' => $qualification_rows,
                'standout' => $standout_rows,
                'positioning' => $positioning_rows,
                'mistakes' => $mistake_rows,
                'salary' => $salary_data,
                'top_signals' => array_slice($top_signals, 0, 6),
            ];

            $context = [
                'candidate' => [
                    'current_role' => $current_role,
                    'experience_years' => $experience_years,
                    'primary_market' => $primary_market,
                    'primary_sector' => $primary_sector,
                    'cv_strength' => sanitize_text_field((string) ($cv_profile['top_strength'] ?? '')),
                    'cv_gap' => sanitize_text_field((string) ($cv_profile['top_gap'] ?? '')),
                    'target_roles' => array_values(array_slice(array_map(static function ($entry) {
                        return sanitize_text_field((string) ($entry['label'] ?? ''));
                    }, (array) ($cv_profile['target_roles'] ?? [])), 0, 5)),
                    'credentials' => array_values(array_slice(array_map('sanitize_text_field', (array) ($parsed['credentials'] ?? [])), 0, 8)),
                    'skills' => array_values(array_slice(array_map('sanitize_text_field', (array) ($parsed['skills'] ?? [])), 0, 12)),
                ],
                'matched_roles' => array_slice($job_rows, 0, 6),
                'matched_companies' => array_slice($company_rows, 0, 6),
                'skill_candidates' => array_slice($skill_rows, 0, 8),
                'qualification_candidates' => array_slice($qualification_rows, 0, 6),
                'role_contexts' => array_slice(array_map(static function ($context) {
                    return [
                        'job_title' => sanitize_text_field((string) ($context['job_title'] ?? '')),
                        'company_name' => sanitize_text_field((string) ($context['company_name'] ?? '')),
                        'location' => sanitize_text_field((string) ($context['location'] ?? '')),
                        'requirements' => array_values(array_slice(array_map('sanitize_text_field', (array) ($context['requirements'] ?? [])), 0, 6)),
                        'keywords' => array_values(array_slice(array_map('sanitize_text_field', (array) ($context['keywords'] ?? [])), 0, 6)),
                    ];
                }, $role_contexts), 0, 6),
                'fallback_report' => [
                    'headline' => $headline,
                    'summary' => $summary,
                    'jobs' => $job_rows,
                    'companies' => $company_rows,
                    'skills' => $skill_rows,
                    'qualifications' => $qualification_rows,
                    'standout' => $standout_rows,
                    'positioning' => $positioning_rows,
                    'mistakes' => $mistake_rows,
                ],
            ];

            return [
                'report' => $report,
                'context' => $context,
            ];
        }

        private function is_cv_match_studio_career_report_useful_term($term, array $company_labels = [])
        {
            $term = trim(sanitize_text_field((string) $term));
            if ($term === '') {
                return false;
            }

            $term_lc = strtolower($term);
            $generic_terms = [
                'investment',
                'investments',
                'private',
                'equity',
                'credit',
                'finance',
                'financial',
                'market',
                'markets',
                'portfolio',
                'role',
                'candidate',
                'team',
                'teams',
                'support',
                'experience',
                'strong',
                'ability',
                'skills',
                'analysis',
                'analytical',
                'communication',
                'stakeholder management',
                'management',
                'leadership',
            ];

            if (in_array($term_lc, $generic_terms, true)) {
                return false;
            }

            foreach ($company_labels as $company_label) {
                $company_label = strtolower(trim((string) $company_label));
                if ($company_label !== '' && $term_lc === $company_label) {
                    return false;
                }
            }

            if (preg_match('/^[a-z]{1,3}$/', $term_lc)) {
                return false;
            }

            if (str_word_count($term_lc) === 1 && strlen($term_lc) < 5 && !preg_match('/^[A-Z]{2,5}$/', $term)) {
                return false;
            }

            return true;
        }

        private function map_cv_match_studio_career_report_stage_index($experience_years)
        {
            $experience_years = max(0, (int) $experience_years);

            if ($experience_years <= 2) {
                return 0;
            }
            if ($experience_years <= 5) {
                return 1;
            }
            if ($experience_years <= 10) {
                return 2;
            }
            if ($experience_years <= 15) {
                return 3;
            }
            if ($experience_years <= 20) {
                return 4;
            }

            return 5;
        }

        private function clean_cv_match_studio_career_report_copy($text, $max_sentences = 0, $max_chars = 0)
        {
            $text = wp_strip_all_tags((string) $text);
            $text = preg_replace('/\s+/', ' ', (string) $text);
            $text = trim((string) $text);
            $text = preg_replace('/(?:\s*(?:\.{3}|…))+$/u', '', (string) $text);
            $text = trim((string) $text);

            if ($text === '') {
                return '';
            }

            if ($max_sentences > 0) {
                preg_match_all('/[^.!?]+[.!?]?/u', $text, $matches);
                $sentences = [];
                foreach ((array) ($matches[0] ?? []) as $sentence) {
                    $sentence = trim((string) $sentence);
                    if ($sentence === '') {
                        continue;
                    }
                    $sentences[] = $sentence;
                    if (count($sentences) >= (int) $max_sentences) {
                        break;
                    }
                }

                if (!empty($sentences)) {
                    $text = trim(implode(' ', $sentences));
                }
            }

            if ($max_chars > 0 && strlen($text) > $max_chars) {
                $slice = function_exists('mb_substr') ? mb_substr($text, 0, $max_chars) : substr($text, 0, $max_chars);
                $punctuation_pos = max(
                    (int) strrpos((string) $slice, '.'),
                    (int) strrpos((string) $slice, '!'),
                    (int) strrpos((string) $slice, '?')
                );

                if ($punctuation_pos > 40) {
                    $text = trim(function_exists('mb_substr') ? mb_substr((string) $slice, 0, $punctuation_pos + 1) : substr((string) $slice, 0, $punctuation_pos + 1));
                } else {
                    $space_pos = (int) strrpos((string) $slice, ' ');
                    if ($space_pos > 40) {
                        $text = trim(function_exists('mb_substr') ? mb_substr((string) $slice, 0, $space_pos) : substr((string) $slice, 0, $space_pos));
                    } else {
                        $text = trim((string) $slice);
                    }

                    if ($text !== '' && !preg_match('/[.!?]$/', $text)) {
                        $text .= '.';
                    }
                }
            }

            return trim((string) $text);
        }

        private function get_cv_match_studio_career_report_tone_cycle($group = 'default')
        {
            $group = sanitize_key((string) $group);
            $map = [
                'jobs' => ['blue', 'green', 'purple', 'gold', 'slate'],
                'companies' => ['green', 'slate', 'blue', 'gold', 'purple'],
                'skills' => ['gold', 'purple', 'blue', 'green', 'slate'],
                'qualifications' => ['gold', 'slate', 'purple', 'blue'],
                'standout' => ['green', 'blue', 'gold', 'purple'],
                'positioning' => ['purple', 'blue', 'green', 'slate'],
                'mistakes' => ['gold', 'purple', 'slate', 'blue'],
                'snapshot' => ['blue', 'green', 'gold'],
                'default' => ['blue', 'green', 'gold', 'purple', 'slate'],
            ];

            return $map[$group] ?? $map['default'];
        }

        private function call_cv_match_studio_career_report_claude(array $context)
        {
            $api_key = $this->get_crm_reddit_claude_api_key();
            if ($api_key === '' || empty($context)) {
                return null;
            }

            $request_body = [
                'model' => 'claude-sonnet-4-6',
                'max_tokens' => 3200,
                'temperature' => 0.1,
                'system' => 'You are MENA Careers\'s private equity career report strategist.

CRITICAL INSTRUCTIONS:
1. Respond with ONLY valid JSON.
2. Start with { and end with }.
3. Ground every recommendation in the supplied CV signals, matched roles, and role contexts.
4. Do not invent employers, credentials, markets, languages, or experience the user does not have.
5. Keep the tone commercially sharp, recruiter-aware, and practical.
6. Prefer specific role names, company patterns, regional hiring workflows, and skills relevant to the broader private equity market, including investing, private credit, portfolio operations, investor relations, asset management, strategy, and operating leadership when supported by the supplied context.
7. Every text field must be complete and self-contained. Do not end any field with "..." or incomplete phrases.
7. Return this exact shape:
{
  "headline": "string",
  "summary": "string",
  "jobs": [{"label": "string", "fit_score": 0, "reason": "string"}],
  "companies": [{"label": "string", "fit_score": 0, "open_roles": 0, "reason": "string"}],
  "skills": [{"label": "string", "current_score": 0, "demand_score": 0, "advice": "string"}],
  "qualifications": [{"label": "string", "priority": 0, "advice": "string"}],
  "standout": [{"label": "string", "score": 0, "detail": "string"}],
  "positioning": [{"label": "string", "score": 0, "detail": "string"}],
  "mistakes": [{"label": "string", "risk_level": "high", "detail": "string"}]
}',
                'messages' => [
                    [
                        'role' => 'user',
                        'content' => wp_json_encode($context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                    ],
                ],
            ];

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 120,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => wp_json_encode($request_body),
            ]);

            if (is_wp_error($response)) {
                error_log('CV Match Career Report Claude Error: ' . $response->get_error_message());
                return null;
            }

            $status = wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);
            if ($status !== 200 || empty($body['content'][0]['text'])) {
                error_log('CV Match Career Report Claude Error: status ' . $status);
                return null;
            }

            $decoded = json_decode((string) $body['content'][0]['text'], true);
            if (!is_array($decoded)) {
                error_log('CV Match Career Report Claude Parse Error: ' . json_last_error_msg());
                return null;
            }

            return $decoded;
        }

        private function merge_cv_match_studio_career_report_payload(array $fallback, array $claude)
        {
            $report = $fallback;

            if (!empty($claude['headline'])) {
                $report['headline'] = sanitize_text_field((string) $claude['headline']);
            }
            if (!empty($claude['summary'])) {
                $report['summary'] = sanitize_text_field((string) $claude['summary']);
            }

            $list_map = [
                'jobs' => ['fit_score'],
                'companies' => ['fit_score', 'open_roles'],
                'skills' => ['current_score', 'demand_score'],
                'qualifications' => ['priority'],
                'standout' => ['score'],
                'positioning' => ['score'],
            ];

            foreach ($list_map as $list_key => $numeric_fields) {
                if (empty($claude[$list_key]) || !is_array($claude[$list_key])) {
                    continue;
                }

                $items = [];
                foreach ($claude[$list_key] as $item) {
                    if (!is_array($item)) {
                        continue;
                    }

                    $normalized = [];
                    foreach ($item as $item_key => $item_value) {
                        if (in_array($item_key, $numeric_fields, true)) {
                            $normalized[$item_key] = max(0, min(100, (int) round((float) $item_value)));
                        } else {
                            $normalized[$item_key] = sanitize_text_field((string) $item_value);
                        }
                    }

                    if (empty($normalized['label']) || strtolower((string) $normalized['label']) === 'array') {
                        continue;
                    }

                    $items[] = $normalized;
                }

                if (!empty($items)) {
                    $report[$list_key] = array_slice($items, 0, count((array) ($fallback[$list_key] ?? $items)));
                }
            }

            if (!empty($claude['mistakes']) && is_array($claude['mistakes'])) {
                $mistakes = [];
                foreach ($claude['mistakes'] as $mistake) {
                    if (!is_array($mistake) || empty($mistake['label'])) {
                        continue;
                    }

                    $risk_level = strtolower(trim((string) ($mistake['risk_level'] ?? 'medium')));
                    if (!in_array($risk_level, ['high', 'medium', 'low'], true)) {
                        $risk_level = 'medium';
                    }

                    $mistakes[] = [
                        'label' => sanitize_text_field((string) $mistake['label']),
                        'risk_level' => $risk_level,
                        'detail' => sanitize_text_field((string) ($mistake['detail'] ?? '')),
                    ];
                }

                if (!empty($mistakes)) {
                    $report['mistakes'] = array_slice($mistakes, 0, count((array) ($fallback['mistakes'] ?? $mistakes)));
                }
            }

            $report['analysis_source'] = !empty($claude) ? 'claude' : 'fallback';

            return $report;
        }

