        }

        private function render_cv_match_studio_career_report_view($user_id, array $resume_payload = [], array $payload = [])
        {
            $report = !empty($payload['report']) && is_array($payload['report']) ? $payload['report'] : [];
            if (($payload['status'] ?? '') === 'missing_cv' || empty($report)) {
                return $this->render_cv_match_studio_career_report_empty_state(
                    __('MENA Careers needs a saved CV before it can benchmark your target roles, company fit, salary range, and recruiter positioning.', 'senna-finance')
                );
            }

            $jobs = array_values(array_filter((array) ($report['jobs'] ?? []), 'is_array'));
            $companies = array_values(array_filter((array) ($report['companies'] ?? []), 'is_array'));
            $skills = array_values(array_filter((array) ($report['skills'] ?? []), 'is_array'));
            $qualifications = array_values(array_filter((array) ($report['qualifications'] ?? []), 'is_array'));
            $standout = array_values(array_filter((array) ($report['standout'] ?? []), 'is_array'));
            $positioning = array_values(array_filter((array) ($report['positioning'] ?? []), 'is_array'));
            $mistakes = array_values(array_filter((array) ($report['mistakes'] ?? []), 'is_array'));
            $salary = !empty($report['salary']) && is_array($report['salary']) ? $report['salary'] : [];
            $top_signals = array_values(array_filter(array_map('sanitize_text_field', (array) ($report['top_signals'] ?? [])), static function ($signal) {
                return trim(strtolower((string) $signal)) !== 'array';
            }));
            $headline = sanitize_text_field((string) ($report['headline'] ?? ''));
            $summary = sanitize_text_field((string) ($report['summary'] ?? ''));
            $current_role = $this->normalize_cv_match_studio_career_report_text_value(
                $report['current_role'] ?? '',
                __('Candidate profile', 'senna-finance')
            );
            $experience_years = max(0, (int) ($report['experience_years'] ?? 0));
            $primary_market = $this->normalize_cv_match_studio_career_report_text_value(
                $report['primary_market'] ?? '',
                __('Target market', 'senna-finance')
            );
            $primary_sector = $this->normalize_cv_match_studio_career_report_text_value(
                $report['primary_sector'] ?? '',
                __('Finance trajectory', 'senna-finance')
            );
            $report_score_parts = [];
            foreach (array_slice($jobs, 0, 3) as $job_row) {
                $report_score_parts[] = max(0, min(100, (int) ($job_row['fit_score'] ?? 0)));
            }
            foreach (array_slice($positioning, 0, 2) as $positioning_row) {
                $report_score_parts[] = max(0, min(100, (int) ($positioning_row['score'] ?? 0)));
            }
            $report_score = !empty($report_score_parts) ? (int) round(array_sum($report_score_parts) / count($report_score_parts)) : 72;
            $metric_source = array_slice(array_merge($standout, $positioning), 0, 4);
            $standout_tones = $this->get_cv_match_studio_career_report_tone_cycle('standout');
            $positioning_tones = $this->get_cv_match_studio_career_report_tone_cycle('positioning');
            $positioning_metrics = [];
            foreach ($metric_source as $index => $metric_item) {
                $score = max(0, min(100, (int) ($metric_item['score'] ?? 0)));
                $positioning_metrics[] = [
                    'label' => sanitize_text_field((string) ($metric_item['label'] ?? '')),
                    'detail' => $this->clean_cv_match_studio_career_report_copy((string) ($metric_item['detail'] ?? ''), 2, 180),
                    'score' => $score,
                    'tone' => $standout_tones[$index % count($standout_tones)],
                    'bars' => $this->build_crm_reddit_single_job_bars($score),
