        private function get_cv_match_studio_jobs_mailbox_items($user_id, array $resume_payload = [], $limit = 10, $search_term = '', $jobs_post_id = 0)
        {
            $user_id = (int) $user_id;
            $limit = max(1, (int) $limit);
            $search_term = trim((string) $search_term);
            $jobs_post_id = absint($jobs_post_id);

            if ($user_id > 0 && empty($resume_payload)) {
                $resume_payload = $this->get_crm_reddit_active_resume_text($user_id);
            }

            $cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $preferred_industry = $this->normalize_cv_match_studio_preferred_industry((string) ($resume_payload['preferred_industry'] ?? ''));
            $items_cache_key = 'sffc_jobs_mailbox_items_' . md5(wp_json_encode([
                'user_id' => $user_id,
                'limit' => $limit,
                'search_term' => $search_term,
                'jobs_post_id' => $jobs_post_id,
                'preferred_industry' => $preferred_industry,
                'cv_hash' => md5($cv_text),
                'has_cv' => !empty($resume_payload['has_cv']),
            ]));
            $cached_items = get_transient($items_cache_key);
            if (is_array($cached_items)) {
                return $cached_items;
            }
            $cv_profile = ($user_id > 0 && $cv_text !== '') ? $this->get_crm_reddit_cv_ats_scan_payload($user_id, $resume_payload, true) : [];
            $role_label = $this->get_crm_reddit_dashboard_primary_cv_role_label($cv_profile);
            $role_label_normalized = $this->normalize_crm_reddit_dashboard_cv_text((string) $role_label);
            $items = $this->get_crm_reddit_dashboard_metrics_source_items($jobs_post_id, $user_id, $search_term);

            if (empty($items)) {
                return [];
            }

            $guest_market_label = $user_id <= 0
                ? strtolower(trim((string) $this->get_cv_match_studio_jobs_mailbox_mobile_market_label(0, $items)))
                : '';
            $duration_lookup = $this->build_cv_match_studio_jobs_mailbox_duration_lookup($items);

            foreach ($items as &$item) {
                $score = 0;
                if ($cv_text !== '' || !empty($cv_profile)) {
                    $score = $this->build_crm_reddit_dashboard_match_score((array) $item, $cv_text, $cv_profile);
                }

                $preferred_industry_score = $this->score_cv_match_studio_preferred_industry_match((array) $item, $preferred_industry, $cv_text);
                if ($preferred_industry_score > 0) {
                    $score = ($cv_text !== '' || !empty($cv_profile))
                        ? $score + $preferred_industry_score
                        : max($score, 44 + $preferred_industry_score);
                }

                if ($role_label_normalized !== '') {
                    $title_haystack = $this->normalize_crm_reddit_dashboard_cv_text(implode(' ', array_filter([
                        (string) ($item['role_title'] ?? ''),
                        (string) ($item['seniority'] ?? ''),
                        implode(' ', array_map('strval', (array) ($item['keywords'] ?? []))),
                    ])));

                    if ($title_haystack !== '' && strpos($title_haystack, $role_label_normalized) !== false) {
                        $score += 14;
                    }
                }

                if ($user_id <= 0) {
                    $item_location = strtolower(trim((string) ($item['location'] ?? '')));
                    $location_relation = $this->get_cv_match_studio_jobs_mailbox_guest_location_relation($guest_market_label, $item_location);
                    $guest_score = 42;
                    $posted_timestamp = (int) ($item['posted_timestamp'] ?? 0);
                    $days_since_posted = $posted_timestamp > 0
                        ? max(0, (int) floor((current_time('timestamp') - $posted_timestamp) / DAY_IN_SECONDS))
                        : 30;
                    $freshness_bonus = 0;

                    if ('location' === $location_relation) {
                        $guest_score += 28;
                    } elseif ('nearby' === $location_relation) {
                        $guest_score += 17;
                    } else {
                        $guest_score += 8;
                    }

                    if ($days_since_posted <= 2) {
                        $freshness_bonus = 15;
                    } elseif ($days_since_posted <= 5) {
                        $freshness_bonus = 11;
                    } elseif ($days_since_posted <= 14) {
                        $freshness_bonus = 6;
                    } else {
                        $freshness_bonus = 3;
                    }

                    $guest_score += $freshness_bonus;
                    $guest_score += !empty($item['is_featured']) ? 7 : 0;
                    $guest_score += !empty($item['recruiter_name']) ? 4 : 0;
                    $guest_score += !empty($item['company_logo']) ? 3 : 0;
                    $guest_score += !empty($item['keywords']) ? min(5, count((array) ($item['keywords'] ?? []))) : 0;
                    $guest_score += !empty($item['application_url']) ? 2 : 0;
                    $guest_score += (((int) ($item['post_id'] ?? 0)) + ((int) ($item['wp_post_id'] ?? 0)) + ((int) ($item['crm_post_id'] ?? 0))) % 7;
                    $guest_score += $preferred_industry_score;

                    $score = max(50, min(95, $guest_score));
                }

                $item['_jobs_mailbox_score'] = max(0, (int) $score);
                $item['_jobs_mailbox_view_url'] = $this->resolve_crm_reddit_dashboard_item_view_url((array) $item);
                $item['_jobs_mailbox_keyword_chips'] = $this->get_cv_match_studio_jobs_mailbox_keyword_chips((array) $item, $cv_text, 6);
                $item['duration'] = $this->resolve_cv_match_studio_jobs_mailbox_duration_label((array) $item, $duration_lookup);
            }
            unset($item);

            usort($items, static function ($left, $right) {
                $score_compare = ((int) ($right['_jobs_mailbox_score'] ?? 0)) <=> ((int) ($left['_jobs_mailbox_score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
            });

            $items = array_values($items);
            $detected_item = [];
            $detected_key = $jobs_post_id > 0 ? 'jobs-' . $jobs_post_id . '-' . $jobs_post_id : '';
            if ($detected_key !== '') {
                foreach ($items as $item) {
                    $item_key = sanitize_key((string) ($item['source'] ?? '')) . '-' . (int) ($item['post_id'] ?? 0) . '-' . (int) ($item['wp_post_id'] ?? 0);
                    if ($item_key === $detected_key) {
                        $detected_item = $item;
                        break;
                    }
                }
            }

            if ($user_id <= 0 && $search_term === '' && count($items) > $limit) {
                $guest_pool = array_slice($items, 0, min(count($items), max($limit * 3, $limit)));
                shuffle($guest_pool);

                $items = array_slice($guest_pool, 0, $limit);
            } else {
                $items = array_slice($items, 0, $limit);
            }

            if (!empty($detected_item)) {
                $items = array_values(array_filter($items, static function ($item) use ($detected_key) {
                    $item_key = sanitize_key((string) ($item['source'] ?? '')) . '-' . (int) ($item['post_id'] ?? 0) . '-' . (int) ($item['wp_post_id'] ?? 0);
                    return $item_key !== $detected_key;
                }));
                array_unshift($items, $detected_item);
                $items = array_slice($items, 0, $limit);
            }

            $items = array_values($items);
            set_transient($items_cache_key, $items, 5 * MINUTE_IN_SECONDS);

            return $items;
        }

        private function build_cv_match_studio_jobs_mailbox_duration_lookup(array $items)
        {
            global $wpdb;

            $lookup = [
                'crm' => [],
                'linked' => [],
            ];
            $crm_post_ids = [];
            $linked_post_ids = [];

            foreach ($items as $item) {
                $duration = sanitize_text_field(trim((string) ($item['duration'] ?? '')));
                $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
                $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
                $jobs_post_id = (string) ($item['source'] ?? '') === 'jobs' ? (int) ($item['post_id'] ?? 0) : 0;
                $linked_post_id = $wp_post_id > 0 ? $wp_post_id : $jobs_post_id;

                if ($duration !== '') {
                    if ($crm_post_id > 0) {
                        $lookup['crm'][$crm_post_id] = $duration;
                    }
                    if ($linked_post_id > 0) {
                        $lookup['linked'][$linked_post_id] = $duration;
                    }
                    continue;
                }

                if ($crm_post_id > 0) {
                    $crm_post_ids[] = $crm_post_id;
                }
                if ($linked_post_id > 0) {
                    $linked_post_ids[] = $linked_post_id;
                }
            }

            $crm_post_ids = array_values(array_unique(array_filter(array_map('intval', $crm_post_ids))));
            $linked_post_ids = array_values(array_unique(array_filter(array_map('intval', $linked_post_ids))));

            if (!empty($linked_post_ids)) {
                update_meta_cache('post', $linked_post_ids);

                foreach ($linked_post_ids as $linked_post_id) {
                    foreach (['duration', 'internship_duration'] as $meta_key) {
                        $duration = sanitize_text_field(trim((string) get_post_meta($linked_post_id, $meta_key, true)));
                        if ($duration !== '') {
                            $lookup['linked'][$linked_post_id] = $duration;
                            break;
                        }
                    }
                }
            }

            if (!empty($crm_post_ids) || !empty($linked_post_ids)) {
                $where_clauses = [];
                $query_args = [];

                if (!empty($crm_post_ids)) {
                    $where_clauses[] = 'id IN (' . implode(',', array_fill(0, count($crm_post_ids), '%d')) . ')';
                    $query_args = array_merge($query_args, $crm_post_ids);
                }

                if (!empty($linked_post_ids)) {
                    $linked_placeholders = implode(',', array_fill(0, count($linked_post_ids), '%d'));
                    $where_clauses[] = 'wp_post_id IN (' . $linked_placeholders . ')';
                    $where_clauses[] = 'jobs_post_id IN (' . $linked_placeholders . ')';
                    $query_args = array_merge($query_args, $linked_post_ids, $linked_post_ids);
                }

                if (!empty($where_clauses)) {
                    $query = "SELECT id, wp_post_id, jobs_post_id, duration FROM {$wpdb->prefix}sffc_crm_posts WHERE " . implode(' OR ', $where_clauses);
                    $rows = $wpdb->get_results($wpdb->prepare($query, $query_args), ARRAY_A);

                    foreach ((array) $rows as $row) {
                        $duration = sanitize_text_field(trim((string) ($row['duration'] ?? '')));
                        if ($duration === '') {
                            continue;
                        }

                        $row_crm_id = (int) ($row['id'] ?? 0);
                        $row_wp_post_id = (int) ($row['wp_post_id'] ?? 0);
                        $row_jobs_post_id = (int) ($row['jobs_post_id'] ?? 0);

                        if ($row_crm_id > 0 && empty($lookup['crm'][$row_crm_id])) {
                            $lookup['crm'][$row_crm_id] = $duration;
                        }
                        foreach ([$row_wp_post_id, $row_jobs_post_id] as $linked_post_id) {
                            if ($linked_post_id > 0 && empty($lookup['linked'][$linked_post_id])) {
                                $lookup['linked'][$linked_post_id] = $duration;
                            }
                        }
                    }
                }
            }

            return $lookup;
        }

        private function resolve_cv_match_studio_jobs_mailbox_duration_label(array $item, array $lookup = [])
        {
            $duration = sanitize_text_field(trim((string) ($item['duration'] ?? '')));
            if ($duration !== '') {
                return $duration;
            }

            $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
            if ($crm_post_id > 0 && !empty($lookup['crm'][$crm_post_id])) {
                return sanitize_text_field(trim((string) $lookup['crm'][$crm_post_id]));
            }

            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            $jobs_post_id = (string) ($item['source'] ?? '') === 'jobs' ? (int) ($item['post_id'] ?? 0) : 0;
            $linked_post_id = $wp_post_id > 0 ? $wp_post_id : $jobs_post_id;
            if ($linked_post_id > 0 && !empty($lookup['linked'][$linked_post_id])) {
                return sanitize_text_field(trim((string) $lookup['linked'][$linked_post_id]));
            }

            return '';
        }

        private function get_cv_match_studio_jobs_mailbox_duration_label(array $item)
        {
            return $this->resolve_cv_match_studio_jobs_mailbox_duration_label(
                $item,
                $this->build_cv_match_studio_jobs_mailbox_duration_lookup([$item])
            );
        }

        private function build_cv_match_studio_jobs_mailbox_sender_label(array $item)
        {
            $show_full_recruiter_name = is_user_logged_in() && $this->current_user_has_crm_editorial_paid_membership_access();
            $recruiter_name = $this->get_crm_reddit_public_recruiter_name((string) ($item['recruiter_name'] ?? ''), $show_full_recruiter_name);
            $company = $show_full_recruiter_name ? trim((string) ($item['company'] ?? '')) : '';

            if ($recruiter_name !== '' && $company !== '') {
                return sprintf(__('%1$s @ %2$s', 'senna-finance'), $recruiter_name, $company);
            }

            if ($recruiter_name !== '') {
                return $recruiter_name;
            }

            if ($company !== '') {
                return sprintf(__('%s hiring team', 'senna-finance'), $company);
            }

            return __('MENA Careers brief', 'senna-finance');
        }

        private function build_cv_match_studio_jobs_mailbox_sender_address(array $item)
        {
            $email = sanitize_email((string) ($item['recruiter_email'] ?? ''));
            if ($email !== '') {
                return $email;
            }

            return 'support.team@joinsenna.com';
        }

        private function normalize_cv_match_studio_jobs_mailbox_preview_value($value)
        {
            if (is_array($value)) {
                $parts = [];
                foreach ($value as $entry) {
                    $normalized_entry = $this->normalize_cv_match_studio_jobs_mailbox_preview_value($entry);
                    if ($normalized_entry !== '') {
                        $parts[] = $normalized_entry;
                    }
                }

                return implode(' ', array_slice($parts, 0, 4));
            }

            if (is_object($value)) {
                return '';
            }

            return trim((string) $value);
        }

        private function build_cv_match_studio_jobs_mailbox_preview(array $item)
        {
            $preview = $this->normalize_cv_match_studio_jobs_mailbox_preview_value($item['excerpt'] ?? '');
            if ($preview === '') {
                $preview = $this->normalize_cv_match_studio_jobs_mailbox_preview_value($item['description_preview'] ?? '');
            }
            if ($preview === '') {
                $preview = __('Live role brief available inside MENA Careers.', 'senna-finance');
            }

            return sanitize_text_field(wp_trim_words($preview, 18, '...'));
        }

        private function cv_match_studio_jobs_mailbox_market_has_items($market_label, array $mail_items)
        {
            $market_label = trim((string) $market_label);
            if ($market_label === '' || empty($mail_items)) {
                return false;
            }

            foreach ($mail_items as $item) {
                $relation = $this->get_cv_match_studio_jobs_mailbox_guest_location_relation(
                    $market_label,
                    (string) ($item['location'] ?? '')
                );
                if ($relation === 'location' || $relation === 'nearby') {
                    return true;
                }
            }

            return false;
        }

        private function infer_cv_match_studio_jobs_mailbox_market_label_from_items(array $mail_items)
        {
            $locations = [];
            foreach ($mail_items as $item) {
                $location = trim((string) ($item['location'] ?? ''));
                if ($location !== '') {
                    $formatted_location = $this->get_crm_reddit_dashboard_app_location_label($location);
                    $locations[] = $formatted_location !== '' ? $formatted_location : $location;
                }
            }

            $locations = array_values(array_unique(array_filter($locations)));
            if (empty($locations)) {
                return __('your market', 'senna-finance');
            }

            $private_equity_terms = [
                'abu dhabi',
                'bahrain',
                'doha',
                'dubai',
                'gcc',
                'jeddah',
                'kuwait',
                'private_equity',
                'finance',
                'muscat',
                'oman',
                'qatar',
                'riyadh',
                'saudi',
                'saudi arabia',
                'uae',
                'united arab emirates',
            ];
            $private_equity_location_count = 0;
            foreach ($locations as $location) {
                $location_lc = strtolower((string) $location);
                foreach ($private_equity_terms as $term) {
                    if (strpos($location_lc, $term) !== false) {
                        $private_equity_location_count++;
                        break;
                    }
                }
            }

            if ($private_equity_location_count >= 2) {
                foreach ($locations as $location) {
                    $location_lc = strtolower((string) $location);
                    if (strpos($location_lc, 'dubai') !== false || strpos($location_lc, 'uae') !== false || strpos($location_lc, 'united arab emirates') !== false) {
                        return __('Finance market', 'senna-finance');
                    }
                }

                return __('Finance markets', 'senna-finance');
            }

            return $locations[0];
        }

        private function get_cv_match_studio_jobs_mailbox_mobile_market_label($user_id, array $mail_items = [])
        {
            $user_id = (int) $user_id;

            if ($user_id > 0) {
                $target_locations = get_user_meta($user_id, 'sffc_crm_target_locations', true);
                if (!empty($target_locations) && is_array($target_locations)) {
                    foreach ($target_locations as $target_location) {
                        $target_location = trim((string) $target_location);
                        if ($target_location !== '') {
                            $formatted_location = $this->get_crm_reddit_dashboard_app_location_label($target_location);
                            $candidate_location = $formatted_location !== '' ? $formatted_location : $target_location;
                            if ($this->cv_match_studio_jobs_mailbox_market_has_items($candidate_location, $mail_items)) {
                                return $candidate_location;
                            }
                        }
                    }
                }
            }

            if (!empty($mail_items)) {
                return $this->infer_cv_match_studio_jobs_mailbox_market_label_from_items($mail_items);
            }

            $timezone = trim((string) wp_timezone_string());
            $timezone_map = [
                'Asia/Dubai' => 'Dubai',
                'Asia/Riyadh' => 'Riyadh',
                'Asia/Qatar' => 'Doha',
                'Asia/Bahrain' => 'Bahrain',
                'Asia/Kuwait' => 'Kuwait',
                'Asia/Muscat' => 'Muscat',
            ];

            if ($timezone !== '' && isset($timezone_map[$timezone])) {
                return $timezone_map[$timezone];
            }

            return $this->infer_cv_match_studio_jobs_mailbox_market_label_from_items($mail_items);
        }

        private function get_cv_match_studio_jobs_mailbox_guest_location_relation($market_label, $item_location)
        {
            $market_label = strtolower(trim((string) $market_label));
            $item_location = strtolower(trim((string) $item_location));

            if ($market_label === '' || $market_label === 'your market' || $item_location === '') {
                return 'trending';
            }

            if (strpos($item_location, $market_label) !== false) {
                return 'location';
            }

            $region_groups = [
                ['dubai', 'abu dhabi', 'uae', 'united arab emirates', 'doha', 'qatar', 'riyadh', 'saudi', 'ksa', 'manama', 'bahrain', 'amman', 'jordan'],
                ['sao paulo', 'brazil'],
                ['johannesburg', 'south africa'],
            ];

            foreach ($region_groups as $terms) {
                $market_in_group = false;
                $item_in_group = false;
                foreach ($terms as $term) {
                    if (!$market_in_group && strpos($market_label, $term) !== false) {
                        $market_in_group = true;
                    }
                    if (!$item_in_group && strpos($item_location, $term) !== false) {
                        $item_in_group = true;
                    }
                }

                if ($market_in_group && $item_in_group) {
                    return 'nearby';
                }
            }

            return 'trending';
        }

        private function get_cv_match_studio_jobs_mailbox_guest_badge_label(array $item, $market_label = '')
        {
            $relation = $this->get_cv_match_studio_jobs_mailbox_guest_location_relation(
                $market_label,
                (string) ($item['location'] ?? '')
            );

            if ('location' === $relation) {
                return __('Location Match', 'senna-finance');
            }

            if ('nearby' === $relation) {
                return __('Nearby Location', 'senna-finance');
            }

            return __('Trending Role', 'senna-finance');
        }

        private function sort_cv_match_studio_jobs_mailbox_mobile_items(array $items, $market_label = '')
        {
            $market_label = strtolower(trim((string) $market_label));
            if ($market_label === '' || empty($items)) {
                return array_values($items);
            }

            usort($items, static function ($left, $right) use ($market_label) {
                $left_location = strtolower(trim((string) ($left['location'] ?? '')));
                $right_location = strtolower(trim((string) ($right['location'] ?? '')));
                $left_market_match = $left_location !== '' && strpos($left_location, $market_label) !== false ? 1 : 0;
                $right_market_match = $right_location !== '' && strpos($right_location, $market_label) !== false ? 1 : 0;

                if ($left_market_match !== $right_market_match) {
                    return $right_market_match <=> $left_market_match;
                }

                $left_score = (int) ($left['_jobs_mailbox_score'] ?? 0);
                $right_score = (int) ($right['_jobs_mailbox_score'] ?? 0);
                if ($left_score !== $right_score) {
                    return $right_score <=> $left_score;
                }

                return ((int) ($right['posted_timestamp'] ?? 0)) <=> ((int) ($left['posted_timestamp'] ?? 0));
            });

            return array_values($items);
        }

        private function build_cv_match_studio_jobs_mailbox_mobile_recruiters(array $items, $shuffle = false)
        {
            $recruiters = [];

            foreach ($items as $index => $item) {
                $recruiter_name = trim((string) ($item['recruiter_name'] ?? ''));
                $company = trim((string) ($item['company'] ?? ($item['recruiter_firm'] ?? '')));
                $item_key = sanitize_key((string) ($item['source'] ?? '')) . '-' . (int) ($item['post_id'] ?? 0) . '-' . (int) ($item['wp_post_id'] ?? 0);

                if ($recruiter_name === '' && $company === '') {
                    continue;
                }

                $display_name = $recruiter_name !== '' ? $recruiter_name : __('Hiring Team', 'senna-finance');
                $display_company = $company !== '' ? $company : __('MENA Careers', 'senna-finance');
                $key = sanitize_title($display_name . '-' . $display_company);
                if ($key === '') {
                    $key = 'mailbox-recruiter-' . ($index + 1);
                }

                if (!isset($recruiters[$key])) {
                    $recruiters[$key] = [
                        'name' => sanitize_text_field($display_name),
                        'company' => sanitize_text_field($display_company),
                        'title' => sanitize_text_field((string) ($item['recruiter_title'] ?? __('Recruiter', 'senna-finance'))),
                        'photo' => esc_url_raw((string) ($item['recruiter_photo'] ?? '')),
                        'location' => sanitize_text_field((string) ($item['location'] ?? '')),
                        'role_count' => 0,
                        'best_role' => sanitize_text_field((string) ($item['role_title'] ?? __('Role brief', 'senna-finance'))),
                        'best_score' => max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0))),
                        'best_key' => $item_key,
                        'initial' => strtoupper(function_exists('mb_substr') ? mb_substr($display_name, 0, 1) : substr($display_name, 0, 1)),
                    ];
                }

                if ($recruiters[$key]['photo'] === '' && !empty($item['recruiter_photo'])) {
                    $recruiters[$key]['photo'] = esc_url_raw((string) $item['recruiter_photo']);
                }

                $score = max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0)));
                if ($score >= (int) $recruiters[$key]['best_score']) {
                    $recruiters[$key]['best_score'] = $score;
                    $recruiters[$key]['best_role'] = sanitize_text_field((string) ($item['role_title'] ?? __('Role brief', 'senna-finance')));
                    $recruiters[$key]['best_key'] = $item_key;
                    if ($recruiters[$key]['location'] === '' && !empty($item['location'])) {
                        $recruiters[$key]['location'] = sanitize_text_field((string) $item['location']);
                    }
                }

                $recruiters[$key]['role_count']++;
            }

            uasort($recruiters, static function ($left, $right) {
                $left_count = (int) ($left['role_count'] ?? 0);
                $right_count = (int) ($right['role_count'] ?? 0);

                if ($left_count === $right_count) {
                    return ((int) ($right['best_score'] ?? 0)) <=> ((int) ($left['best_score'] ?? 0));
                }

                return $right_count <=> $left_count;
            });

            $recruiters = array_slice(array_values($recruiters), 0, 8);
            if ($shuffle && count($recruiters) > 1) {
                shuffle($recruiters);
            }

            return $recruiters;
        }

        private function get_cv_match_studio_jobs_mailbox_fit_grade($score)
        {
            $score = max(0, min(100, (int) $score));

            if ($score >= 75) {
                return 'perfect';
            }

            if ($score >= 60) {
                return 'strong';
            }

            if ($score >= 50) {
                return 'ok';
            }

            return 'weak';
        }

        private function get_cv_match_studio_jobs_mailbox_fit_filter_group($score)
        {
            $grade = $this->get_cv_match_studio_jobs_mailbox_fit_grade($score);

            if ('perfect' === $grade || 'strong' === $grade) {
                return 'strong';
            }

            if ('ok' === $grade) {
                return 'ok';
            }

            return 'weak';
        }

        private function get_cv_match_studio_jobs_mailbox_fit_label($score)
        {
            $grade = $this->get_cv_match_studio_jobs_mailbox_fit_grade($score);

            if ('perfect' === $grade) {
                return __('Perfect Match', 'senna-finance');
            }

            if ('strong' === $grade) {
                return __('Strong Match', 'senna-finance');
            }

            if ('ok' === $grade) {
                return __('OK Match', 'senna-finance');
            }

            return __('Weak Match', 'senna-finance');
        }

        private function build_cv_match_studio_jobs_mailbox_desktop_companies(array $items, $shuffle = false)
        {
            $companies = [];

            foreach ($items as $index => $item) {
                $company = trim((string) ($item['company'] ?? ''));
                $item_key = sanitize_key((string) ($item['source'] ?? '')) . '-' . (int) ($item['post_id'] ?? 0) . '-' . (int) ($item['wp_post_id'] ?? 0);

                if ($company === '') {
                    continue;
                }

                $key = sanitize_title($company);
                if ($key === '') {
                    $key = 'mailbox-company-' . ($index + 1);
                }

                if (!isset($companies[$key])) {
                    $companies[$key] = [
                        'company' => sanitize_text_field($company),
                        'logo' => esc_url_raw((string) ($item['company_logo'] ?? '')),
                        'role_count' => 0,
                        'best_score' => max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0))),
                        'best_key' => $item_key,
                        'initial' => strtoupper(function_exists('mb_substr') ? mb_substr($company, 0, 1) : substr($company, 0, 1)),
                    ];
                }

                if ($companies[$key]['logo'] === '' && !empty($item['company_logo'])) {
                    $companies[$key]['logo'] = esc_url_raw((string) $item['company_logo']);
                }

                $score = max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0)));
                if ($score >= (int) $companies[$key]['best_score']) {
                    $companies[$key]['best_score'] = $score;
                    $companies[$key]['best_key'] = $item_key;
                }

                $companies[$key]['role_count']++;
            }

            uasort($companies, static function ($left, $right) {
                $left_count = (int) ($left['role_count'] ?? 0);
                $right_count = (int) ($right['role_count'] ?? 0);

                if ($left_count === $right_count) {
                    return ((int) ($right['best_score'] ?? 0)) <=> ((int) ($left['best_score'] ?? 0));
                }

                return $right_count <=> $left_count;
            });

            $companies = array_slice(array_values($companies), 0, 8);
            if ($shuffle && count($companies) > 1) {
                shuffle($companies);
            }

            return $companies;
        }

        private function shuffle_cv_match_studio_jobs_mailbox_items_by_fit(array $items)
        {
            $perfect = [];
            $strong = [];
            $ok = [];
            $weak = [];

            foreach ($items as $item) {
                $grade = $this->get_cv_match_studio_jobs_mailbox_fit_grade((int) ($item['_jobs_mailbox_score'] ?? 0));
                if ('perfect' === $grade) {
                    $perfect[] = $item;
                } elseif ('strong' === $grade) {
                    $strong[] = $item;
                } elseif ('ok' === $grade) {
                    $ok[] = $item;
                } else {
                    $weak[] = $item;
                }
            }

            if (count($perfect) > 1) {
                shuffle($perfect);
            }
            if (count($strong) > 1) {
                shuffle($strong);
            }
            if (count($ok) > 1) {
                shuffle($ok);
            }
            if (count($weak) > 1) {
                shuffle($weak);
            }

            return array_merge($perfect, $strong, $ok, $weak);
        }

