        private function get_cv_match_studio_jobs_mailbox_pins_table_name()
        {
            global $wpdb;

            return $wpdb->prefix . 'sffc_crm_mailbox_pins';
        }

        private function get_cv_match_studio_jobs_mailbox_pinned_keys_for_user($user_id)
        {
            global $wpdb;

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $table = $this->get_cv_match_studio_jobs_mailbox_pins_table_name();
            $table_exists = (string) $wpdb->get_var(
                $wpdb->prepare('SHOW TABLES LIKE %s', $table)
            );
            if ($table_exists !== $table) {
                return [];
            }

            $keys = $wpdb->get_col(
                $wpdb->prepare(
                    "SELECT mailbox_key FROM {$table} WHERE user_id = %d ORDER BY created_at DESC, id DESC",
                    $user_id
                )
            );

            if (empty($keys) || !is_array($keys)) {
                return [];
            }

            return array_values(
                array_filter(
                    array_map(
                        static function ($key) {
                            return sanitize_key((string) $key);
                        },
                        $keys
                    )
                )
            );
        }

        private function get_cv_match_studio_jobs_mailbox_default_pin_key(array $mail_items)
        {
            if (empty($mail_items)) {
                return '';
            }

            $market_label = strtolower(trim((string) $this->get_cv_match_studio_jobs_mailbox_mobile_market_label(0, $mail_items)));
            $location_matches = [];
            $nearby_matches = [];
            $trending_matches = [];

            foreach ($mail_items as $item) {
                if (!is_array($item)) {
                    continue;
                }

                $mailbox_key = sanitize_key((string) ($item['source'] ?? '')) . '-' . (int) ($item['post_id'] ?? 0) . '-' . (int) ($item['wp_post_id'] ?? 0);
                if ($mailbox_key === '') {
                    continue;
                }

                $score = max(0, min(100, (int) ($item['_jobs_mailbox_score'] ?? 0)));
                $timestamp = (int) ($item['posted_timestamp'] ?? 0);
                $candidate = [
                    'key' => $mailbox_key,
                    'score' => $score,
                    'timestamp' => $timestamp,
                ];

                $relation = $this->get_cv_match_studio_jobs_mailbox_guest_location_relation(
                    $market_label,
                    (string) ($item['location'] ?? '')
                );

                if ('location' === $relation) {
                    $location_matches[] = $candidate;
                } elseif ('nearby' === $relation) {
                    $nearby_matches[] = $candidate;
                } else {
                    $trending_matches[] = $candidate;
                }
            }

            $pool = !empty($location_matches)
                ? $location_matches
                : (!empty($nearby_matches) ? $nearby_matches : $trending_matches);

            if (empty($pool)) {
                return '';
            }

            usort($pool, static function ($left, $right) {
                $score_compare = ((int) ($right['score'] ?? 0)) <=> ((int) ($left['score'] ?? 0));
                if ($score_compare !== 0) {
                    return $score_compare;
                }

                return ((int) ($right['timestamp'] ?? 0)) <=> ((int) ($left['timestamp'] ?? 0));
            });

            $pool = array_slice($pool, 0, min(8, count($pool)));
            if (count($pool) > 1) {
                shuffle($pool);
            }

            return (string) ($pool[0]['key'] ?? '');
        }

        private function render_cv_match_studio_jobs_mailbox_attachment_strip(array $item, $has_material_access, $membership_url)
        {
            $resources = array_slice($this->get_crm_reddit_application_pack_resources($item), 0, 4);
            if (empty($resources)) {
                return '';
            }

            $company_name = trim((string) ($item['company'] ?? ''));
            $role_title = trim((string) ($item['role_title'] ?? ''));
            $jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(
                (string) ($item['source'] ?? '') === 'jobs' ? (int) ($item['post_id'] ?? 0) : 0,
                (int) ($item['wp_post_id'] ?? 0),
                (int) ($item['crm_post_id'] ?? 0)
            );
            $wp_post_id = (int) ($item['wp_post_id'] ?? 0);
            $crm_post_id = (int) ($item['crm_post_id'] ?? 0);
            $fallback_view_url = esc_url_raw((string) ($item['view_url'] ?? ''));

            ob_start();
        ?>
            <div class="sffc-cv-match-studio__jobs-mailbox-attachments" aria-label="<?php esc_attr_e('Tailored attachments', 'senna-finance'); ?>">
                <?php foreach ($resources as $resource) : ?>
                    <?php
                    $kind = trim((string) ($resource['kind'] ?? 'doc'));
                    $file_type = trim((string) ($resource['type'] ?? 'DOC'));
                    $material_type = trim((string) ($resource['material_type'] ?? ''));
                    $direct_url = esc_url_raw((string) ($resource['direct_url'] ?? ''));
                    $classes = 'sffc-crm-reddit-inline-pack-card sffc-crm-reddit-inline-pack-card--' . esc_attr($kind) . ' sffc-cv-match-studio__jobs-mailbox-attachment';
                    ?>
                    <?php if ($has_material_access && $direct_url !== '') : ?>
                        <a class="<?php echo esc_attr($classes); ?>" href="<?php echo esc_url($direct_url); ?>" target="_blank" rel="noopener noreferrer">
                    <?php elseif ($has_material_access && $jobs_post_id > 0) : ?>
                        <button
                            type="button"
                            class="<?php echo esc_attr($classes); ?>"
                            data-cv-match-mailbox-materials-open="1"
                            data-cv-match-mailbox-material-type="<?php echo esc_attr($material_type); ?>"
                            data-cv-match-mailbox-jobs-post-id="<?php echo esc_attr((string) $jobs_post_id); ?>"
                            data-cv-match-mailbox-wp-post-id="<?php echo esc_attr((string) $wp_post_id); ?>"
                            data-cv-match-mailbox-crm-post-id="<?php echo esc_attr((string) $crm_post_id); ?>"
                            data-cv-match-mailbox-role-title="<?php echo esc_attr($role_title); ?>"
                            data-cv-match-mailbox-company="<?php echo esc_attr($company_name); ?>">
                    <?php else : ?>
                        <a class="<?php echo esc_attr($classes); ?>" href="<?php echo esc_url($has_material_access && $fallback_view_url !== '' ? $fallback_view_url : $membership_url); ?>" target="_blank" rel="noopener noreferrer">
                    <?php endif; ?>
                        <span class="sffc-crm-reddit-inline-pack-card-icon" aria-hidden="true"></span>
                        <span class="sffc-crm-reddit-inline-pack-card-copy">
                            <strong class="sffc-crm-reddit-inline-pack-card-label"><?php echo esc_html((string) ($resource['label'] ?? __('Attachment', 'senna-finance'))); ?></strong>
                            <span class="sffc-crm-reddit-inline-pack-card-meta">
                                <?php echo esc_html((string) ($resource['meta'] ?? __('Generated in MENA Careers', 'senna-finance'))); ?>
                                <?php if ($file_type !== '') : ?>
                                    &bull; <?php echo esc_html($file_type); ?>
                                <?php endif; ?>
                            </span>
                        </span>
                        <span class="sffc-crm-reddit-inline-pack-card-action" aria-hidden="true">
                            <svg viewBox="0 0 16 16">
                                <path d="M5 3.5h5.4v5.4M4 12 10.4 5.6" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" />
                            </svg>
                        </span>
                    <?php if ($has_material_access && $direct_url !== '') : ?>
                        </a>
                    <?php elseif ($has_material_access && $jobs_post_id > 0) : ?>
                        </button>
                    <?php else : ?>
                        </a>
                    <?php endif; ?>
                <?php endforeach; ?>
            </div>
        <?php
            return (string) ob_get_clean();
        }

