        private function render_cv_match_studio_jobs_mailbox_view($user_id, array $resume_payload = [], $first_name = '', array $workspace = [], $search_term = '', $preferred_active_key = '')
        {
            $search_term = trim((string) $search_term);
            $preferred_active_key = sanitize_key((string) $preferred_active_key);
            $workspace_jobs_post_id = absint($workspace['jobs_post_id'] ?? 0);
            $workspace_jobs_mailbox_key = $workspace_jobs_post_id > 0 ? 'jobs-' . $workspace_jobs_post_id . '-' . $workspace_jobs_post_id : '';
            $mailbox_limit = $search_term !== '' ? 18 : 24;
            $mailbox_cache_key = 'sffc_jobs_mailbox_view_' . md5(wp_json_encode([
                'user_id' => (int) $user_id,
                'search_term' => $search_term,
                'preferred_active_key' => $preferred_active_key,
                'workspace_jobs_post_id' => $workspace_jobs_post_id,
                'mailbox_limit' => $mailbox_limit,
                'preferred_industry' => (string) ($resume_payload['preferred_industry'] ?? ''),
                'has_cv' => !empty($resume_payload['has_cv']),
                'cv_hash' => md5((string) ($resume_payload['cv_text'] ?? '')),
            ]));
            $mail_items = get_transient($mailbox_cache_key);
            if (!is_array($mail_items)) {
                $mail_items = $this->get_cv_match_studio_jobs_mailbox_items($user_id, $resume_payload, $mailbox_limit, $search_term, $workspace_jobs_post_id);
                if ($search_term === '') {
                    $mail_items = $this->merge_cv_match_studio_newsletter_group_mailbox_items($mail_items, 24);
                }
                set_transient($mailbox_cache_key, $mail_items, 5 * MINUTE_IN_SECONDS);
            }
            $is_logged_in = is_user_logged_in();
            $mailbox_cv_text = trim((string) ($resume_payload['cv_text'] ?? ''));
            $has_cv = !empty($resume_payload['has_cv']) && $mailbox_cv_text !== '';
            $has_material_access = $this->current_user_has_crm_reddit_premium_access();
            $membership_url = $this->get_crm_reddit_membership_url();
            $mailbox_membership_dropdown_plans = $this->get_cv_match_studio_membership_dropdown_plans();
            $mobile_mailbox_locked = !$is_logged_in || !$has_material_access;
            $login_url = $is_logged_in
                ? $membership_url
                : wp_login_url((string) (get_permalink(get_queried_object_id()) ?: home_url('/')));
            $mobile_plan_cta_label = $has_material_access
                ? __('Manage Plan', 'senna-finance')
                : ($is_logged_in ? __('Upgrade', 'senna-finance') : __('Join', 'senna-finance'));
            $mobile_title_cta_label = $has_material_access
                ? __('Manage Plan', 'senna-finance')
                : ($is_logged_in ? __('Upgrade', 'senna-finance') : __('Join MENA Careers', 'senna-finance'));
            $workspace_account_user = !empty($workspace['account_user']) && is_array($workspace['account_user']) ? $workspace['account_user'] : [];
            $workspace_avatar_url = trim((string) ($workspace['avatar_url'] ?? ''));
            $workspace_topbar_counts = !empty($workspace['topbar_counts']) && is_array($workspace['topbar_counts']) ? $workspace['topbar_counts'] : ['notifications' => 0, 'messages' => 0];
            $workspace_notification_items = !empty($workspace['notification_items']) && is_array($workspace['notification_items']) ? $workspace['notification_items'] : [];
            $workspace_message_items = !empty($workspace['message_items']) && is_array($workspace['message_items']) ? $workspace['message_items'] : [];
            $first_name = trim((string) $first_name);
            $stored_pinned_keys = is_user_logged_in() ? $this->get_cv_match_studio_jobs_mailbox_pinned_keys_for_user(get_current_user_id()) : [];
            if ($workspace_jobs_mailbox_key !== '' && !in_array($workspace_jobs_mailbox_key, $stored_pinned_keys, true)) {
                array_unshift($stored_pinned_keys, $workspace_jobs_mailbox_key);
            }
            if (!is_user_logged_in() && empty($stored_pinned_keys)) {
                $guest_default_pinned_key = $this->get_cv_match_studio_jobs_mailbox_default_pin_key($mail_items);
                if ($guest_default_pinned_key !== '') {
                    $stored_pinned_keys = [$guest_default_pinned_key];
                }
            }
            $stored_pinned_lookup = array_fill_keys($stored_pinned_keys, true);
            $pinned_items = [];
            $primary_items = [];
            $score_values = [];
            $priority_count = 0;
            $ready_pack_count = 0;
            $market_labels = [];
            $active_key = '';

            foreach ($mail_items as $mail_item) {
                $mailbox_item_key = sanitize_key((string) ($mail_item['source'] ?? '')) . '-' . (int) ($mail_item['post_id'] ?? 0) . '-' . (int) ($mail_item['wp_post_id'] ?? 0);
                if ($active_key === '' && $preferred_active_key !== '' && $mailbox_item_key === $preferred_active_key) {
                    $active_key = $mailbox_item_key;
                }
                if (isset($stored_pinned_lookup[$mailbox_item_key])) {
                    $pinned_items[] = $mail_item;
                } else {
                    $primary_items[] = $mail_item;
                }

                $mail_score = max(0, min(100, (int) ($mail_item['_jobs_mailbox_score'] ?? 0)));
                if ($mail_score > 0) {
                    $score_values[] = $mail_score;
                }
                if ($mail_score >= 75) {
                    $priority_count++;
                }
                $mail_location = trim((string) ($mail_item['location'] ?? ''));
                if ($mail_location !== '') {
                    $market_labels[] = $mail_location;
                }
                $resolved_mail_jobs_post_id = $this->resolve_cv_match_job_view_jobs_post_id(
                    (string) ($mail_item['source'] ?? '') === 'jobs' ? (int) ($mail_item['post_id'] ?? 0) : 0,
                    (int) ($mail_item['wp_post_id'] ?? 0),
                    (int) ($mail_item['crm_post_id'] ?? 0)
                );
                if ($has_material_access && $has_cv && $resolved_mail_jobs_post_id > 0) {
                    $ready_pack_count++;
                }
            }

            if ($active_key === '' && !empty($mail_items[0]['source'])) {
                $active_key = sanitize_key((string) ($mail_items[0]['source'] ?? '')) . '-' . (int) ($mail_items[0]['post_id'] ?? 0) . '-' . (int) ($mail_items[0]['wp_post_id'] ?? 0);
            }

            $avg_match_score = !empty($score_values) ? (int) round(array_sum($score_values) / count($score_values)) : 0;
            $market_count = count(array_unique($market_labels));
            $mobile_market_label = $this->get_cv_match_studio_jobs_mailbox_mobile_market_label($user_id, $mail_items);
            $mobile_items = $this->sort_cv_match_studio_jobs_mailbox_mobile_items($mail_items, $mobile_market_label);
            $mobile_pinned_item = !empty($mobile_items[0]) ? (array) $mobile_items[0] : [];
            $mobile_recommended_items = count($mobile_items) > 1 ? array_values(array_slice($mobile_items, 1)) : [];
            $desktop_company_cards = $this->build_cv_match_studio_jobs_mailbox_desktop_companies($mail_items, true);
