        <?php
            return (string) ob_get_clean();
        }

        /**
         * Pre-fill MemberPress form with captured signup data
         * Hook: mepr-signup-form-vars
         */
        public function prefill_memberpress_form($vars)
        {
            $email = sanitize_email($this->get_signup_email_prefill_value());
            if ($email === '' && !empty($_GET['email'])) {
                $url_email = sanitize_email(wp_unslash((string) $_GET['email']));
                if ($url_email !== '' && is_email($url_email)) {
                    $email = $url_email;
                }
            }
            if ($email !== '') {
                $vars['user_email'] = $email;
                $vars['mepr_user_email'] = $email;
            }

            $first_name = sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_first_name'));
            $last_name = sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_last_name'));
            if (($first_name === '' || $last_name === '') && !empty($_GET['full_name'])) {
                $parsed_name = $this->parse_full_name(sanitize_text_field(wp_unslash((string) $_GET['full_name'])));
                if ($first_name === '') {
                    $first_name = sanitize_text_field((string) ($parsed_name['first_name'] ?? ''));
                }
                if ($last_name === '') {
                    $last_name = sanitize_text_field((string) ($parsed_name['last_name'] ?? ''));
                }
            }

            if ($first_name !== '') {
                $vars['user_first_name'] = $first_name;
                $vars['mepr_first_name'] = $first_name;
            }

            if ($last_name !== '') {
                $vars['user_last_name'] = $last_name;
                $vars['mepr_last_name'] = $last_name;
            }

            $mepr_job_id = absint($this->parse_cv_match_context_job_id($this->get_valid_signup_cookie_value('sffc_signup_mepr_job_id')));
            if ($mepr_job_id > 0) {
                $vars['mepr_job_id'] = (string) $mepr_job_id;
            }

            return $vars;
        }

        /**
         * Pre-fill MemberPress registration fields using JavaScript
         * This runs early to inject script that will populate fields
         */
        public function prefill_memberpress_registration_fields()
        {
            // Only run on MemberPress registration pages
            if (!function_exists('mepr_is_registration_page') || !mepr_is_registration_page()) {
                return;
            }

            $email = sanitize_email($this->get_signup_email_prefill_value());
            $first_name = sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_first_name'));
            $last_name = sanitize_text_field($this->get_valid_signup_cookie_value('sffc_signup_last_name'));
            $mepr_job_id = absint($this->parse_cv_match_context_job_id($this->get_valid_signup_cookie_value('sffc_signup_mepr_job_id')));

            if ($email === '' && !empty($_GET['email'])) {
                $url_email = sanitize_email(wp_unslash((string) $_GET['email']));
                if ($url_email !== '' && is_email($url_email)) {
                    $email = $url_email;
                }
            }

            if (($first_name === '' || $last_name === '') && !empty($_GET['full_name'])) {
                $parsed_name = $this->parse_full_name(sanitize_text_field(wp_unslash((string) $_GET['full_name'])));
                if ($first_name === '') {
                    $first_name = sanitize_text_field((string) ($parsed_name['first_name'] ?? ''));
                }
                if ($last_name === '') {
                    $last_name = sanitize_text_field((string) ($parsed_name['last_name'] ?? ''));
                }
            }

            if (!$email && !$first_name && !$last_name && !$mepr_job_id) {
                return;
            }

        ?>
            <script type="text/javascript">
                jQuery(document).ready(function($) {
                    // Pre-fill MemberPress registration form fields
                    <?php if ($email): ?>
                        $('input[name="user_email"], input[name="mepr_user_email"], input[name="email"], #user_email, #user_email1, #mepr_email, #mepr_user_email').val('<?php echo esc_js($email); ?>');
                    <?php endif; ?>

                    <?php if ($first_name): ?>
                        $('input[name="user_first_name"], input[name="mepr_first_name"], input[name="first_name"], #user_first_name, #user_first_name1, #mepr_first_name').val('<?php echo esc_js($first_name); ?>');
                    <?php endif; ?>

                    <?php if ($last_name): ?>
                        $('input[name="user_last_name"], input[name="mepr_last_name"], input[name="last_name"], #user_last_name, #user_last_name1, #mepr_last_name').val('<?php echo esc_js($last_name); ?>');
                    <?php endif; ?>

                    <?php if ($mepr_job_id > 0): ?>
                        $('input[name="mepr_job_id"], #mepr_job_id, #mepr_job_id1').val('<?php echo esc_js((string) $mepr_job_id); ?>');
                    <?php endif; ?>

                    // Generate username from email if needed
                    <?php if ($email):
                        $email_parts = explode('@', $email);
                        $username = $email_parts[0];
                    ?>
                        var username = '<?php echo esc_js($username); ?>';
                        $('input[name="user_login"], input[name="mepr_user_login"], #user_login, #mepr_user_login').val(username);
                    <?php endif; ?>
                });
            </script>
        <?php
        }

        private function get_intro_requests_for_user($user_id)
        {
            if (!$user_id) {
                return [];
            }

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_intro_requests';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return [];
            }

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$table} WHERE user_id = %d AND (status IS NULL OR status != 'cancelled') ORDER BY created_at DESC",
                $user_id
            ), ARRAY_A);

            if (empty($rows)) {
                return [];
            }

            $status_labels = [
                'pending_review' => __('Queued', 'senna-finance'),
                'approved' => __('Approved', 'senna-finance'),
                'sent' => __('Sent to recruiter', 'senna-finance'),
                'awaiting_response' => __('Awaiting response', 'senna-finance'),
                'accepted' => __('Accepted', 'senna-finance'),
                'rejected' => __('Declined', 'senna-finance'),
                'expired' => __('Expired', 'senna-finance'),
            ];

            $post_model = new SFFC_CRM_Post();
            foreach ($rows as &$row) {
                $post = !empty($row['post_id']) ? $post_model->get((int) $row['post_id']) : null;
                $row['job_title'] = $row['role_title'] ?? ($post['role_title'] ?? __('Role', 'senna-finance'));
                $row['job_company'] = $row['company_name'] ?? ($post['company'] ?? __('Company', 'senna-finance'));
                $row['job_location'] = $post['location'] ?? '';
                $row['recruiter_name'] = $row['recruiter_name'] ?? ($post['recruiter_name'] ?? __('Hiring Team', 'senna-finance'));
                $row['recruiter_email'] = $row['recruiter_email'] ?? ($post['recruiter_email'] ?? '');
                $row['recruiter_linkedin'] = $row['recruiter_linkedin'] ?? ($post['recruiter_linkedin'] ?? '');
                $row['status_label'] = $status_labels[$row['status']] ?? ucfirst(str_replace('_', ' ', (string) $row['status']));
                $row['created_at_formatted'] = !empty($row['created_at'])
                    ? wp_date(get_option('date_format'), strtotime($row['created_at']))
                    : '';
                $row['confirmation_sent_label'] = !empty($row['confirmation_sent_at'])
                    ? sprintf(__('Confirmation sent %s ago', 'senna-finance'), human_time_diff(strtotime($row['confirmation_sent_at']), current_time('timestamp')))
                    : '';
                $row['resume_sent'] = !empty($row['resume_sent_at']);
                $row['cover_letter_sent'] = !empty($row['cover_letter_sent_at']);
            }
            unset($row);

            return $rows;
        }

        private function get_community_send_intro_applications_for_user($user_id)
        {
            if (!$user_id) {
                return [];
            }

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_job_applications';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return [];
            }

            $this->ensure_job_applications_intro_columns_for_community();

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$table} WHERE user_id = %d AND workflow_type = %s ORDER BY applied_date DESC, id DESC",
                $user_id,
                'send_intro'
            ), ARRAY_A);

            if (empty($rows)) {
                return [];
            }

            $items = [];
            foreach ($rows as $row) {
                $row = is_array($row) ? $row : [];
                $recruiter_snapshot = json_decode((string) ($row['recruiter_snapshot'] ?? ''), true);
                $post_snapshot = json_decode((string) ($row['post_snapshot'] ?? ''), true);
                $name = trim((string) ($row['recruiter_name'] ?? ($recruiter_snapshot['name'] ?? '')));
                $company = trim((string) ($row['company_name'] ?? ($recruiter_snapshot['company_name'] ?? '')));
                if ($name === '' && $company === '') {
                    continue;
                }

                $avatar_initial = $name !== ''
                    ? (function_exists('mb_strtoupper') ? mb_strtoupper(mb_substr($name, 0, 1)) : strtoupper(substr($name, 0, 1)))
                    : 'R';
                $stage = sanitize_key((string) ($row['stage'] ?? 'queued'));
                $sent_at = !empty($row['applied_date'])
                    ? wp_date(get_option('date_format'), strtotime((string) $row['applied_date']))
                    : __('Queued', 'senna-finance');

                $items[] = [
                    'application_id' => (int) ($row['id'] ?? 0),
                    'source_post_id' => (int) ($row['source_post_id'] ?? 0),
                    'campaign_status' => $this->format_community_send_intro_stage_label($stage),
                    'name' => $name !== '' ? $name : __('Recruiter contact', 'senna-finance'),
                    'title' => trim((string) ($row['recruiter_title'] ?? ($recruiter_snapshot['title'] ?? ''))),
                    'company' => $company !== '' ? $company : __('Company', 'senna-finance'),
                    'company_info' => trim((string) ($row['job_title'] ?? ($post_snapshot['role_title'] ?? ''))),
                    'email' => sanitize_email((string) ($row['recruiter_email'] ?? ($recruiter_snapshot['email'] ?? ''))),
                    'linkedin' => esc_url_raw((string) ($row['recruiter_linkedin'] ?? ($recruiter_snapshot['linkedin'] ?? ''))),
                    'avatar_url' => esc_url_raw((string) ($row['recruiter_avatar_url'] ?? ($recruiter_snapshot['avatar_url'] ?? ''))),
                    'avatar_initial' => $avatar_initial,
                    'message_subject' => trim((string) ($row['message_subject'] ?? '')),
                    'message_body' => trim((string) ($row['message_body'] ?? '')),
                    'attachment_urls' => trim((string) ($row['stored_cv_name'] ?? ($row['attachment_urls'] ?? ''))),
                    'sent_at' => $sent_at,
                    'location' => trim((string) ($row['recruiter_location'] ?? ($row['location'] ?? ''))),
                    'location_primary' => trim((string) ($row['recruiter_location'] ?? ($row['location'] ?? ''))),
                    'regions' => trim((string) ($row['recruiter_regions'] ?? '')),
                ];
            }

            return $items;
        }

        private function get_community_managed_applications_for_user($user_id)
        {
            if (!$user_id) {
                return [];
            }

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_job_applications';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return [];
            }

            $this->ensure_job_applications_intro_columns_for_community();

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$table} WHERE user_id = %d AND workflow_type = %s ORDER BY applied_date DESC, id DESC",
                $user_id,
                'application'
            ), ARRAY_A);

            if (empty($rows)) {
                return [];
            }

            $items = [];
            foreach ($rows as $row) {
                $row = is_array($row) ? $row : [];
                $post_snapshot = json_decode((string) ($row['post_snapshot'] ?? ''), true);
                $recruiter_snapshot = json_decode((string) ($row['recruiter_snapshot'] ?? ''), true);
                $role_title = trim((string) ($row['job_title'] ?? ($post_snapshot['role_title'] ?? '')));
                $company_name = trim((string) ($row['company_name'] ?? ($post_snapshot['company_name'] ?? '')));
                if ($role_title === '' && $company_name === '') {
                    continue;
                }

                $avatar_initial = $company_name !== ''
                    ? (function_exists('mb_strtoupper') ? mb_strtoupper(mb_substr($company_name, 0, 1)) : strtoupper(substr($company_name, 0, 1)))
                    : 'A';
                $stage = sanitize_key((string) ($row['stage'] ?? 'queued'));
                $sent_at = !empty($row['submitted_at'])
                    ? wp_date(get_option('date_format'), strtotime((string) $row['submitted_at']))
                    : (!empty($row['applied_date']) ? wp_date(get_option('date_format'), strtotime((string) $row['applied_date'])) : __('Queued', 'senna-finance'));
                $attachments_label = trim((string) ($row['stored_cv_name'] ?? ''));
                if ($attachments_label === '') {
                    $attachments_label = !empty($row['cover_letter_url'])
                        ? __('CV + Cover Letter', 'senna-finance')
                        : __('Stored CV', 'senna-finance');
                }

                $message_body = trim((string) ($row['admin_message'] ?? ''));
                if ($message_body === '') {
                    $message_body = trim((string) ($row['notes'] ?? ''));
                }

                $items[] = [
                    'application_id' => (int) ($row['id'] ?? 0),
                    'campaign_status' => $this->format_application_stage_label($stage),
                    'name' => $role_title !== '' ? $role_title : __('Managed application', 'senna-finance'),
                    'title' => trim((string) ($row['location'] ?? ($post_snapshot['location'] ?? ''))),
                    'company' => $company_name !== '' ? $company_name : __('Company', 'senna-finance'),
                    'company_info' => trim((string) ($row['recruiter_name'] ?? ($recruiter_snapshot['name'] ?? __('MENA Careers managed application', 'senna-finance')))),
                    'email' => '',
                    'linkedin' => esc_url_raw((string) ($row['application_url'] ?? ($post_snapshot['application_url'] ?? ''))),
                    'avatar_url' => '',
                    'avatar_initial' => $avatar_initial,
                    'message_subject' => trim((string) ($row['message_subject'] ?? __('Application details', 'senna-finance'))),
                    'message_body' => $message_body !== '' ? $message_body : __('MENA Careers is managing this application on your behalf. Progress updates and materials will appear here as the workflow moves forward.', 'senna-finance'),
                    'attachment_urls' => $attachments_label,
                    'sent_at' => $sent_at,
                ];
            }

            return $items;
        }

        private function get_crm_editorial_community_default_resume_document($user_id)
        {
            static $cache = [];

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            if (array_key_exists($user_id, $cache)) {
                return $cache[$user_id];
            }

            $cache[$user_id] = $this->get_crm_editorial_latest_resume_document($user_id);

            return $cache[$user_id];
        }

        private function get_crm_editorial_resume_documents($user_id)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            $resume_documents = [];
            $user_documents = get_user_meta($user_id, 'sffc_crm_documents', true);
            if (is_array($user_documents)) {
                foreach ($user_documents as $document) {
                    $document = is_array($document) ? $document : [];
                    if (($document['document_type'] ?? '') !== 'resume_cv') {
                        continue;
                    }

                    $resume_name = trim((string) ($document['name'] ?? ''));
                    $resume_url = esc_url_raw((string) ($document['url'] ?? ''));
                    if ($resume_url === '') {
                        continue;
                    }

                    $resume_documents[] = [
                        'name' => $resume_name !== '' ? $resume_name : __('Stored CV', 'senna-finance'),
                        'url' => $resume_url,
                        'uploaded' => trim((string) ($document['uploaded'] ?? '')),
                    ];
                }
            }

            if (empty($resume_documents)) {
                $latest_resume_document = $this->get_crm_editorial_latest_resume_upload_document($user_id);
                if (!empty($latest_resume_document['url'])) {
                    $resume_documents[] = [
                        'name' => trim((string) ($latest_resume_document['name'] ?? __('Stored CV', 'senna-finance'))),
                        'url' => trim((string) ($latest_resume_document['url'] ?? '')),
                        'uploaded' => trim((string) ($latest_resume_document['uploaded'] ?? '')),
                    ];
                }
            }

            return $resume_documents;
        }

        private function get_crm_editorial_community_in_progress_send_intro_keys($user_id)
        {
            static $cache = [];

            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return [];
            }

            if (array_key_exists($user_id, $cache)) {
                return $cache[$user_id];
            }

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_job_applications';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                $cache[$user_id] = [];
                return $cache[$user_id];
            }

            $this->ensure_job_applications_intro_columns_for_community();

            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT source_post_id, recruiter_id, source_action FROM {$table} WHERE user_id = %d AND workflow_type = %s",
                $user_id,
                'send_intro'
            ), ARRAY_A);

            $cache[$user_id] = [];
            foreach ((array) $rows as $row) {
                $source_post_id = (int) ($row['source_post_id'] ?? 0);
                $recruiter_id = (int) ($row['recruiter_id'] ?? 0);
                $source_action = sanitize_key((string) ($row['source_action'] ?? 'recruiter_discovery'));
                $cache[$user_id][$this->get_crm_editorial_community_send_intro_key($source_post_id, $recruiter_id, $source_action)] = true;
            }

            return $cache[$user_id];
        }

        private function get_crm_editorial_community_send_intro_key($source_post_id, $recruiter_id, $source_action)
        {
            return implode('|', [
                (int) $source_post_id,
                (int) $recruiter_id,
                sanitize_key((string) $source_action),
            ]);
        }

        private function has_crm_editorial_community_send_intro_in_progress($user_id, $source_post_id, $recruiter_id, $source_action)
        {
            $user_id = (int) $user_id;
            if ($user_id <= 0) {
                return false;
            }

            $keys = $this->get_crm_editorial_community_in_progress_send_intro_keys($user_id);

            return isset($keys[$this->get_crm_editorial_community_send_intro_key($source_post_id, $recruiter_id, $source_action)]);
        }

        private function ensure_job_applications_intro_columns_for_community()
        {
            global $wpdb;

            $table = $wpdb->prefix . 'sffc_job_applications';
            if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
                return;
            }

            $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");
            $columns_to_add = [
                'source_post_id' => "ALTER TABLE `{$table}` ADD COLUMN `source_post_id` bigint(20) DEFAULT 0 AFTER `job_id`",
                'workflow_type' => "ALTER TABLE `{$table}` ADD COLUMN `workflow_type` varchar(50) DEFAULT 'application' AFTER `source_post_id`",
                'created_at' => "ALTER TABLE `{$table}` ADD COLUMN `created_at` datetime DEFAULT CURRENT_TIMESTAMP AFTER `stage_updated`",
                'updated_at' => "ALTER TABLE `{$table}` ADD COLUMN `updated_at` datetime DEFAULT CURRENT_TIMESTAMP AFTER `created_at`",
                'source_action' => "ALTER TABLE `{$table}` ADD COLUMN `source_action` varchar(100) DEFAULT NULL AFTER `source`",
                'recruiter_id' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_id` bigint(20) DEFAULT 0 AFTER `location`",
                'recruiter_name' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_name` varchar(255) DEFAULT NULL AFTER `recruiter_id`",
                'recruiter_title' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_title` varchar(255) DEFAULT NULL AFTER `recruiter_name`",
                'recruiter_email' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_email` varchar(255) DEFAULT NULL AFTER `recruiter_title`",
                'recruiter_linkedin' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_linkedin` text DEFAULT NULL AFTER `recruiter_email`",
                'recruiter_avatar_url' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_avatar_url` text DEFAULT NULL AFTER `recruiter_linkedin`",
                'recruiter_location' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_location` varchar(255) DEFAULT NULL AFTER `recruiter_avatar_url`",
                'recruiter_regions' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_regions` text DEFAULT NULL AFTER `recruiter_location`",
                'stored_cv_url' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_url` text DEFAULT NULL AFTER `recruiter_regions`",
                'stored_cv_name' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_name` varchar(255) DEFAULT NULL AFTER `stored_cv_url`",
                'message_subject' => "ALTER TABLE `{$table}` ADD COLUMN `message_subject` text DEFAULT NULL AFTER `stored_cv_name`",
                'message_body' => "ALTER TABLE `{$table}` ADD COLUMN `message_body` longtext DEFAULT NULL AFTER `message_subject`",
                'attachment_urls' => "ALTER TABLE `{$table}` ADD COLUMN `attachment_urls` longtext DEFAULT NULL AFTER `message_body`",
                'application_url' => "ALTER TABLE `{$table}` ADD COLUMN `application_url` text DEFAULT NULL AFTER `attachment_urls`",
                'submitted_at' => "ALTER TABLE `{$table}` ADD COLUMN `submitted_at` datetime DEFAULT NULL AFTER `application_url`",
                'confirmation_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `confirmation_sent_at` datetime DEFAULT NULL AFTER `submitted_at`",
                'resume_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `resume_sent_at` datetime DEFAULT NULL AFTER `confirmation_sent_at`",
                'cover_letter_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_sent_at` datetime DEFAULT NULL AFTER `resume_sent_at`",
                'resume_url' => "ALTER TABLE `{$table}` ADD COLUMN `resume_url` text DEFAULT NULL AFTER `cover_letter_sent_at`",
                'cover_letter_url' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_url` text DEFAULT NULL AFTER `resume_url`",
                'admin_message' => "ALTER TABLE `{$table}` ADD COLUMN `admin_message` longtext DEFAULT NULL AFTER `cover_letter_url`",
                'post_snapshot' => "ALTER TABLE `{$table}` ADD COLUMN `post_snapshot` longtext DEFAULT NULL AFTER `admin_message`",
                'recruiter_snapshot' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_snapshot` longtext DEFAULT NULL AFTER `post_snapshot`",
            ];

            foreach ($columns_to_add as $column_name => $sql) {
                if (in_array($column_name, $existing_columns, true)) {
                    continue;
                }
                $wpdb->query($sql);
                $existing_columns[] = $column_name;
            }
        }

        private function format_community_send_intro_stage_label($stage)
        {
            $labels = [
                'queued' => __('Queued', 'senna-finance'),
                'pending_review' => __('Queued', 'senna-finance'),
                'preparing' => __('Preparing', 'senna-finance'),
                'approved' => __('Approved', 'senna-finance'),
                'submitted' => __('Submitted', 'senna-finance'),
                'sent' => __('Sent to recruiter', 'senna-finance'),
                'confirmation_sent' => __('Confirmation sent', 'senna-finance'),
                'assessment_pending' => __('Assessment pending', 'senna-finance'),
                'awaiting_response' => __('Awaiting response', 'senna-finance'),
                'interview' => __('Interview stage', 'senna-finance'),
                'offer' => __('Offer stage', 'senna-finance'),
                'accepted' => __('Accepted', 'senna-finance'),
                'rejected' => __('Declined', 'senna-finance'),
                'expired' => __('Expired', 'senna-finance'),
                'cancelled' => __('Cancelled', 'senna-finance'),
            ];

            return $labels[$stage] ?? ucwords(str_replace(['-', '_'], ' ', (string) $stage));
        }

        private function parse_intro_campaign_reached_recruiters($value)
        {
            if (!is_string($value) || trim($value) === '') {
                return [];
            }

            $decoded = json_decode($value, true);
            return is_array($decoded) ? $decoded : [];
        }

        private function get_intro_campaign_requests_for_user($user_id)
        {
            $requests = $this->get_intro_requests_for_user($user_id);
            if (empty($requests)) {
                return [];
            }

            $campaigns = [];
            foreach ($requests as $request) {
                if (($request['request_type'] ?? '') !== 'campaign') {
                    continue;
                }
                if (in_array((string) ($request['source_action'] ?? ''), ['recruiter_discovery', 'hiring_strip'], true)) {
                    continue;
                }

                $request = is_array($request) ? $request : [];
                $request['reached_recruiters_items'] = $this->parse_intro_campaign_reached_recruiters((string) ($request['reached_recruiters'] ?? ''));
                $request['reached_recruiters_count'] = count($request['reached_recruiters_items']);
                $campaigns[] = $request;
            }

            return $campaigns;
        }

        private function get_intro_campaign_requested_contacts(array $campaign_requests)
        {
            if (empty($campaign_requests)) {
                return [];
            }

            $items = [];
            foreach ($campaign_requests as $campaign_request) {
                $campaign_request = is_array($campaign_request) ? $campaign_request : [];

                $reached_contacts = isset($campaign_request['reached_recruiters_items']) && is_array($campaign_request['reached_recruiters_items'])
                    ? $campaign_request['reached_recruiters_items']
                    : $this->parse_intro_campaign_reached_recruiters((string) ($campaign_request['reached_recruiters'] ?? ''));

                if (!empty($reached_contacts)) {
                    foreach ($reached_contacts as $contact) {
                        $contact = is_array($contact) ? $contact : [];
                        $name = trim((string) ($contact['name'] ?? ''));
                        $company = trim((string) ($contact['company'] ?? ($campaign_request['target_company'] ?? '')));
                        if ($name === '' && $company === '') {
                            continue;
                        }

                        $avatar_initial = $name !== ''
                            ? (function_exists('mb_strtoupper') ? mb_strtoupper(mb_substr($name, 0, 1)) : strtoupper(substr($name, 0, 1)))
                            : 'R';

                        $items[] = [
                            'campaign_id' => (int) ($campaign_request['id'] ?? 0),
                            'campaign_title' => (string) ($campaign_request['target_role'] ?? ''),
                            'campaign_location' => (string) ($campaign_request['target_location'] ?? ''),
                            'campaign_status' => (string) ($campaign_request['status_label'] ?? ''),
                            'name' => $name,
                            'title' => trim((string) ($contact['title'] ?? '')),
                            'company' => $company,
                            'company_info' => trim((string) ($contact['company_info'] ?? '')),
                            'email' => sanitize_email((string) ($contact['email'] ?? '')),
                            'linkedin' => esc_url_raw((string) ($contact['linkedin'] ?? '')),
                            'avatar_url' => esc_url_raw((string) ($contact['avatar_url'] ?? '')),
                            'avatar_initial' => $avatar_initial,
                            'message_subject' => trim((string) ($contact['message_subject'] ?? '')),
                            'message_body' => trim((string) ($contact['message_body'] ?? '')),
                            'attachment_urls' => trim((string) ($contact['attachment_urls'] ?? '')),
                            'sent_at' => trim((string) ($contact['sent_at'] ?? '')),
                            'location' => trim((string) ($contact['location'] ?? ($campaign_request['target_location'] ?? ''))),
                            'location_primary' => trim((string) ($contact['location'] ?? ($campaign_request['target_location'] ?? ''))),
                            'regions' => trim((string) ($contact['regions'] ?? '')),
                        ];
                    }
                    continue;
                }

                $name = trim((string) ($campaign_request['recruiter_name'] ?? ''));
                $company = trim((string) ($campaign_request['company_name'] ?? ($campaign_request['target_company'] ?? '')));
                if ($name === '' && $company === '') {
                    continue;
                }

                $avatar_initial = $name !== ''
                    ? (function_exists('mb_strtoupper') ? mb_strtoupper(mb_substr($name, 0, 1)) : strtoupper(substr($name, 0, 1)))
                    : 'R';

                $items[] = [
                    'campaign_id' => (int) ($campaign_request['id'] ?? 0),
                    'campaign_title' => (string) ($campaign_request['target_role'] ?? ''),
                    'campaign_location' => (string) ($campaign_request['target_location'] ?? ''),
                    'campaign_status' => (string) ($campaign_request['status_label'] ?? ''),
                    'name' => $name !== '' ? $name : __('Recruiter contact', 'senna-finance'),
                    'title' => trim((string) ($campaign_request['recruiter_title'] ?? '')),
                    'company' => $company,
                    'company_info' => (string) ($campaign_request['job_title'] ?? ''),
                    'email' => sanitize_email((string) ($campaign_request['recruiter_email'] ?? '')),
                    'linkedin' => esc_url_raw((string) ($campaign_request['recruiter_linkedin'] ?? '')),
                    'avatar_url' => '',
                    'avatar_initial' => $avatar_initial,
                    'message_subject' => '',
                    'message_body' => trim((string) ($campaign_request['intro_context'] ?? '')),
                    'attachment_urls' => trim((string) ($campaign_request['stored_cv_name'] ?? '')),
                    'sent_at' => trim((string) ($campaign_request['created_at_formatted'] ?? '')),
                    'location' => trim((string) ($campaign_request['target_location'] ?? '')),
                    'location_primary' => trim((string) ($campaign_request['target_location'] ?? '')),
                    'regions' => '',
                ];
            }

            return $items;
        }

