        private function user_has_resume_document($user_id)
        {
            $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
            if (!is_array($documents)) {
                return false;
            }

            foreach ($documents as $document) {
                if (($document['document_type'] ?? '') === 'resume_cv') {
                    return true;
                }
            }

            return false;
        }

        private function get_document_type_label($document_type)
        {
            if ($document_type === 'resume_cv') {
                return __('Resume/CV', 'senna-finance');
            }

            return __('Supporting Document', 'senna-finance');
        }

