        private function get_linkedin_search_criteria_groups($user_id)
        {
            if (!$user_id || !function_exists('sffc_crm_get_job_preferences')) {
                return [];
            }

            $preferences = sffc_crm_get_job_preferences($user_id);
            $sector_options = function_exists('sffc_crm_get_sector_options') ? sffc_crm_get_sector_options() : [];
            $seniority_options = function_exists('sffc_crm_get_seniority_options') ? sffc_crm_get_seniority_options() : [];
            $work_options = function_exists('sffc_crm_get_work_arrangement_options') ? sffc_crm_get_work_arrangement_options() : [];
            $salary_display = function_exists('sffc_crm_format_salary_range') ? sffc_crm_format_salary_range($user_id) : '';

            $groups = [];

            $this->append_search_criteria_group($groups, __('Target Roles', 'senna-finance'), $preferences['target_roles'] ?? []);
            $this->append_search_criteria_group($groups, __('Locations', 'senna-finance'), $preferences['target_locations'] ?? []);
            $this->append_search_criteria_group($groups, __('Sectors', 'senna-finance'), $this->map_criteria_values($preferences['target_sectors'] ?? [], $sector_options));
            $this->append_search_criteria_group($groups, __('Seniority', 'senna-finance'), $this->map_criteria_values($preferences['target_seniority'] ?? [], $seniority_options));
            $this->append_search_criteria_group($groups, __('Work Style', 'senna-finance'), $this->map_criteria_values($preferences['work_arrangement'] ?? [], $work_options));

            if ($salary_display !== '') {
                $groups[] = [
                    'label' => __('Salary', 'senna-finance'),
                    'values' => [$salary_display],
                ];
            }

            return $groups;
        }

        private function append_search_criteria_group(&$groups, $label, $values)
        {
            $values = array_values(array_filter(array_map('sanitize_text_field', (array) $values)));
            if (empty($values)) {
                return;
            }

            $groups[] = [
                'label' => $label,
                'values' => array_slice($values, 0, 4),
            ];
        }

        private function map_criteria_values($values, $options)
        {
            $mapped = [];
            foreach ((array) $values as $value) {
                $mapped[] = $options[$value] ?? $value;
            }

            return $mapped;
        }

