        private function get_recent_submitted_applications($user_id, $limit = 8)
        {
            if (!$user_id) {
                return [];
            }

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_job_applications';

            return $wpdb->get_results($wpdb->prepare(
                "SELECT id, job_id, stage, applied_date, company_name, job_title, location
             FROM {$table}
             WHERE user_id = %d
             ORDER BY applied_date DESC, id DESC
             LIMIT %d",
                $user_id,
                $limit
            ), ARRAY_A) ?: [];
        }

        private function format_application_stage_label($stage)
        {
            $labels = [
                'queued' => __('Queued', 'senna-finance'),
                'pending_review' => __('Pending review', 'senna-finance'),
                'preparing' => __('Preparing materials', 'senna-finance'),
                'applied' => __('Submitted', 'senna-finance'),
                'waiting' => __('Waiting for Response', 'senna-finance'),
                'submitted' => __('Submitted', 'senna-finance'),
                'sent' => __('Sent to recruiter', 'senna-finance'),
                'confirmation_sent' => __('Confirmation sent', 'senna-finance'),
                'assessment_pending' => __('Assessment pending', 'senna-finance'),
                'awaiting_response' => __('Awaiting response', 'senna-finance'),
                'first-interview' => __('1st Stage Interview', 'senna-finance'),
                'interview' => __('Interview stage', 'senna-finance'),
                'further-interview' => __('Further Interview', 'senna-finance'),
                'offer' => __('Offer stage', 'senna-finance'),
                'secured' => __('Secured', 'senna-finance'),
                'accepted' => __('Accepted', 'senna-finance'),
                'rejected' => __('Declined', 'senna-finance'),
                'expired' => __('Expired', 'senna-finance'),
                'cancelled' => __('Cancelled', 'senna-finance'),
                'moved-on' => __('Moved On', 'senna-finance'),
            ];

            return $labels[$stage] ?? ucwords(str_replace(['-', '_'], ' ', (string) $stage));
        }

        /**
         * AJAX handler for capturing conversion carousel leads
         */
        public function ajax_capture_conversion_lead()
        {
            check_ajax_referer('sffc_conversion_nonce', 'nonce');

            $email = isset($_POST['email']) ? sanitize_email($_POST['email']) : '';
            $first_name = isset($_POST['first_name']) ? sanitize_text_field($_POST['first_name']) : '';
            $current_level = isset($_POST['current_level']) ? sanitize_text_field($_POST['current_level']) : '';
            $target_role = isset($_POST['target_role']) ? sanitize_text_field($_POST['target_role']) : '';
            $location = isset($_POST['location']) ? sanitize_text_field($_POST['location']) : '';
            $recruiter_post_id = isset($_POST['recruiter_post_id']) ? intval($_POST['recruiter_post_id']) : 0;

            if (empty($email) || !is_email($email)) {
                wp_send_json_error(['message' => __('Please provide a valid email address.', 'senna-finance')]);
            }

            // Prepare applicant data
            $applicant_model = new SFFC_CRM_Applicant();

            $job_title = $target_role ?: 'Guest';
            $company = '';
            $recruiter_id = 0;

            // Get post details if recruiter_post_id is provided
            if ($recruiter_post_id) {
                $post = get_post($recruiter_post_id);
                if ($post) {
                    $job_title = get_post_meta($recruiter_post_id, '_job_title', true) ?: $job_title;
                    $company = get_post_meta($recruiter_post_id, '_company_name', true);
                    $recruiter_id = get_post_meta($recruiter_post_id, '_recruiter_id', true);
                }
            }

            // Build form data from quiz answers
            $form_data = [
                'current_level' => $current_level,
                'target_role' => $target_role,
                'location' => $location,
                'source_flow' => 'conversion_carousel',
            ];

            $applicant_data = [
                'user_id' => get_current_user_id() ?: 0,
                'recruiter_post_id' => $recruiter_post_id,
                'recruiter_id' => $recruiter_id,
                'job_title' => $job_title,
                'company' => $company,
                'first_name' => $first_name,
                'last_name' => '',
                'email' => $email,
                'materials' => [],
                'source' => 'conversion_carousel',
                'form_data' => $form_data,
            ];

            $result = $applicant_model->log_applicant($applicant_data);

            if (is_wp_error($result)) {
                wp_send_json_error(['message' => $result->get_error_message()]);
            }

            // Store lead data in session for personalization
            if (!session_id()) {
                session_start();
            }

            $_SESSION['sffc_conversion_lead'] = [
                'email' => $email,
                'first_name' => $first_name,
                'current_level' => $current_level,
                'target_role' => $target_role,
                'location' => $location,
                'applicant_id' => $result,
            ];

            wp_send_json_success([
                'message' => __('Email captured successfully!', 'senna-finance'),
                'applicant_id' => $result,
            ]);
        }

