        /**
         * Render scripts for guest search
         */
        private function render_guest_search_scripts()
        {
        ?>
            <script>
                (function() {
                    'use strict';

                    var form = document.getElementById('sffcGuestSearchForm');
                    if (!form) return;

                    form.addEventListener('submit', function(e) {
                        e.preventDefault();

                        var formData = new FormData(form);
                        var roleTitle = formData.get('role_title');
                        var location = formData.get('location');
                        var yearsExperience = formData.get('years_experience');

                        // Build the criteria object
                        var criteria = {
                            job_title: roleTitle,
                            location: location ? [location] : [],
                            years_experience: yearsExperience
                        };

                        // Encode criteria as URL parameter
                        var params = new URLSearchParams({
                            guest_criteria: JSON.stringify(criteria),
                            tab: 'console'
                        });

                        // Redirect to /terminal with criteria
                        window.location.href = '/terminal?' + params.toString();
                    });
                })();
            </script>
    <?php
        }

        /**
         * AJAX handler: Generate market article report
         */
        public function ajax_markets_generate_report()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $article_id = isset($_POST['article_id']) ? absint($_POST['article_id']) : 0;
            if (!$article_id) {
                wp_send_json_error(['message' => __('Invalid article ID', 'senna-finance')]);
            }

            $post = get_post($article_id);
            if (!$post || !$this->is_market_post($post)) {
                wp_send_json_error(['message' => __('Article not found', 'senna-finance')]);
            }

            // Generate report data
            $report_data = [
                'title' => get_the_title($post),
                'date' => get_the_date('Y-m-d', $post),
                'excerpt' => get_the_excerpt($post),
                'content' => wp_strip_all_tags((string) $post->post_content),
                'type' => get_post_type($post),
                'company' => get_post_meta($article_id, '_company_name', true),
                'deal_value' => get_post_meta($article_id, '_deal_value', true),
                'region' => get_post_meta($article_id, '_region', true),
                'url' => get_permalink($post),
            ];

            // For now, redirect to the article with a report view parameter
            // In production, this could generate a PDF or open a report modal
            $report_url = add_query_arg('view', 'report', get_permalink($post));

            wp_send_json_success([
                'report_url' => $report_url,
                'report_data' => $report_data,
            ]);
        }

        /**
         * AJAX handler: Export market article data
         */
        public function ajax_markets_export_data()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $article_id = isset($_POST['article_id']) ? absint($_POST['article_id']) : 0;
            if (!$article_id) {
                wp_send_json_error(['message' => __('Invalid article ID', 'senna-finance')]);
            }

            $post = get_post($article_id);
            if (!$post || !$this->is_market_post($post)) {
                wp_send_json_error(['message' => __('Article not found', 'senna-finance')]);
            }

            // Build export data
            $export_data = [
                'id' => $article_id,
                'title' => get_the_title($post),
                'date' => get_the_date('c', $post),
                'type' => get_post_type($post),
                'url' => get_permalink($post),
                'excerpt' => get_the_excerpt($post),
                'company' => get_post_meta($article_id, '_company_name', true),
                'deal_value' => get_post_meta($article_id, '_deal_value', true),
                'region' => get_post_meta($article_id, '_region', true),
                'signal_type' => get_post_meta($article_id, '_signal_type', true),
                'exported_at' => current_time('c'),
            ];

            // Create a temporary file with the JSON data
            $upload_dir = wp_upload_dir();
            if (!empty($upload_dir['error'])) {
                wp_send_json_error(['message' => __('Unable to access uploads directory', 'senna-finance')]);
            }

            if (!wp_mkdir_p($upload_dir['path'])) {
                wp_send_json_error(['message' => __('Unable to prepare export directory', 'senna-finance')]);
            }

            $filename = 'senna-market-data-' . $article_id . '-' . time() . '.json';
            $filepath = $upload_dir['path'] . '/' . $filename;
            $fileurl = $upload_dir['url'] . '/' . $filename;
            $json_data = wp_json_encode($export_data, JSON_PRETTY_PRINT);

            if (false === $json_data) {
                wp_send_json_error(['message' => __('Unable to encode export data', 'senna-finance')]);
            }

            if (false === file_put_contents($filepath, $json_data)) {
                wp_send_json_error(['message' => __('Unable to create export file', 'senna-finance')]);
            }

            // Schedule deletion of the file after 1 hour
            wp_schedule_single_event(time() + 3600, 'sffc_delete_temp_export', [$filepath]);

            wp_send_json_success([
                'download_url' => $fileurl,
                'filename' => $filename,
            ]);
        }

        /**
         * AJAX handler: Load more market articles
         */
        public function ajax_markets_load_more()
        {
            check_ajax_referer('sffc_crm_nonce', 'nonce');

            $page = isset($_POST['page']) ? absint($_POST['page']) : 1;
            $filter = isset($_POST['filter']) ? sanitize_key($_POST['filter']) : 'all';
            $feed = $this->get_market_articles_feed($filter, $page, 12);
            $html = $this->render_market_cards_html($feed['articles'], 1 === $page);

            wp_send_json_success([
                'html' => $html,
                'has_more' => !empty($feed['has_more']),
                'count' => count($feed['articles']),
                'page' => (int) $feed['current_page'],
            ]);
        }
    }

